        pass("checkAmbiguousGenericAssertion1") { checkAmbiguousGenericAssertion1() }
        pass("checkInvalidLetForOfES5") { checkInvalidLetForOfES5() }
        pass("checkInvalidLetForOfES6") { checkInvalidLetForOfES6() }
        pass("checkClassUpdateTests") { checkClassUpdateTests() }
        pass("checkParseInvalidNames") { checkParseInvalidNames() }
        pass("checkParametersSyntaxErrorNoCrash1") { checkParametersSyntaxErrorNoCrash1() }
        pass("checkParseBigInt") { checkParseBigInt() }
        pass("checkBigintWithoutLib") { checkBigintWithoutLib() }
        pass("checkInKeywordTypeguard") { checkInKeywordTypeguard() }
        pass("checkUnusedLocalsAndParameters") { checkUnusedLocalsAndParameters() }
        pass("checkEs6ImportNamedImportParsingErrorPin") { checkEs6ImportNamedImportParsingErrorPin() }
        pass("checkBigintArbitraryIdentifierPin") { checkBigintArbitraryIdentifierPin() }
        pass("checkParseUnaryJsx4Pin") { checkParseUnaryJsx4Pin() }
        pass("checkControlFlowFunctionLikeCircular1Pin") { checkControlFlowFunctionLikeCircular1Pin() }
        pass("checkEs6ExportEqualsInteropPin") { checkEs6ExportEqualsInteropPin() }
        pass("checkModulePreserve4Pin") { checkModulePreserve4Pin() }
        pass("checkMappedTypeAsClauseLateBoundPin") { checkMappedTypeAsClauseLateBoundPin() }
        pass("checkPreserveSymlinksPin") { checkPreserveSymlinksPin() }
        pass("checkReexportedSymlinkReference3Pin") { checkReexportedSymlinkReference3Pin() }
        pass("checkUnderscoreTest1Pin") { checkUnderscoreTest1Pin() }
        pass("checkParseImportAttributesErrorPin") { checkParseImportAttributesErrorPin() }
        pass("checkPreEmitCountMismatchPins") { checkPreEmitCountMismatchPins() }
        pass("checkMappedTypeRecursiveInferencePin") { checkMappedTypeRecursiveInferencePin() }
        pass("applyDomLibSuggestionRewrite") { applyDomLibSuggestionRewrite() }
        // Round 426 (faithful TS2563): definite-assignment analysis respects a flow-walk
        // depth trip — tsc's flowAnalysisDisabled makes getFlowTypeOfReference return
        // errorType in the tripped container, so it reports TS2563 OR TS2454, never both.
        // Our multi-pass architecture can't consult the disabled set inside the AST-based
        // TS2454 emitters at emission time (and a trip in a LATER pass postdates them),
        // so the filter runs at the END of init over the tripped containers' ranges.
        // Approximation vs tsc: tsc keeps a TS2454 reported BEFORE the trip point within
        // the same container (single in-order pass); we drop those too — observable only
        // on synthetic deep-CFG files (zero trips on the corpus and tsc's own sources).
        pass("init:flowDisabledTs2454Retraction") {
        if (flowDisabledRanges.isNotEmpty()) {
            diagnostics.removeAll { d ->
                d.code == 2454 && d.start != null &&
                    flowDisabledRanges[d.fileName]?.any { r -> d.start in r } == true
            }
        }
        }
        // (M3.0-gap-3 B1) Drop a return-path engine TS2322 whose position a dedicated pin
        // walker also reported — see [tpTargetReturnDiags]. Identity-keyed and conditional
        // on an actual duplicate, so a diagnostic alone at its position always survives.
        pass("init:tpTargetReturnDedup") {
        for (d in tpTargetReturnDiags) {
            val samePosition = diagnostics.count {
                it.code == 2322 && it.fileName == d.fileName && it.start == d.start
            }
            if (samePosition > 1) {
                val idx = diagnostics.indexOfFirst { it === d }
                if (idx >= 0) diagnostics.removeAt(idx)
            }
        }
        }
    }

    /** Emit a single TS2589 when type checking recursed past the stack limit on a
     *  construct the depth/cycle guards do not cover. Best-effort position: the start
     *  of the first checked file. Never fires on the test corpus (0 overflows). */
    private fun reportCheckerStackOverflow(@Suppress("UNUSED_PARAMETER") e: StackOverflowError) {
        val firstFile = binderResults.firstOrNull()?.sourceFile
        diagnostics.add(Diagnostic(
            message = "Type instantiation is excessively deep and possibly infinite.",
            category = DiagnosticCategory.Error,
            code = 2589,
            fileName = firstFile?.fileName,
            line = if (firstFile != null) 0 else null,
            character = if (firstFile != null) 0 else null,
            start = 0,
            length = 0,
        ))
    }

    /**
     * B63.30: TS1239 "Unable to resolve signature of parameter decorator when called as an expression."
     *
     * For constructor parameters with `@Decorator` annotations, TypeScript checks the decorator's
     * resolved call signature. If the 2nd parameter type does NOT include `undefined`, emit TS1239 +
     * message chain "Argument of type 'undefined' is not assignable to parameter of type '<param 2 type>'".
     *
     * Rationale: parameter decorators are called as `Decorator(target, key, paramIndex)` where `key`
     * is the property name OR `undefined` for constructor parameters. If the decorator's `key` parameter
     * type doesn't accept `undefined`, the call fails at compile time on constructor parameters.
     *
     * Gated to `experimentalDecorators` mode and only fires for parameters of the Constructor member.
     */
    private fun checkParameterDecoratorsOnConstructor() {
        if (!options.experimentalDecorators) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkParameterDecoratorChecks(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkParameterDecoratorChecks(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        if (member is Constructor) {
                            for (param in member.parameters) {
                                param.decorators?.forEach { dec ->
                                    checkParameterDecoratorSignature(dec, source, fileName)
                                }
                            }
                        }
                    }
                    // Recurse into nested classes inside class member bodies if needed
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                is Block -> walkParameterDecoratorChecks(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkParameterDecoratorChecks(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkParameterDecoratorChecks(listOf(it), source, fileName) }
                }
                is ForStatement -> walkParameterDecoratorChecks(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkParameterDecoratorChecks(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkParameterDecoratorChecks(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkParameterDecoratorChecks(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkParameterDecoratorChecks(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> walkParameterDecoratorChecks(clause.statements, source, fileName)
                            is DefaultClause -> walkParameterDecoratorChecks(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    walkParameterDecoratorChecks(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkParameterDecoratorChecks(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkParameterDecoratorChecks(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    /**
     * B98.r7: TS1206 "Decorators are not valid here." for PARAMETER decorators under
     * standard (non-experimental) decorators. In TypeScript 5.0+ the default decorator
     * mode is the TC39 standard, where parameter decorators are not supported at all —
     * `nodeCanBeDecorated(legacyDecorators=false, parameter)` is false, so the checker's
     * grammar pass reports TS1206 on the first token (the `@`) of the parameter's first
     * decorator. Class/method/accessor/property/field decorators stay valid → we only
     * flag PARAMETERS. Gated to `!experimentalDecorators`; an explicit `@experimentalDecorators`
     * (or tsconfig `experimentalDecorators`) flag suppresses it.
     */
    private fun checkInvalidParameterDecorators() {
        if (options.experimentalDecorators) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkInvalidParamDecorators(result.sourceFile.statements, source, fileName)
        }
    }

    private fun emitInvalidParamDecorators(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            val dec = param.decorators?.firstOrNull() ?: continue
            if (dec.pos !in 0 until source.length) continue
            val (line, character) = getLineAndCharacterOfPosition(source, dec.pos)
            diagnostics.add(Diagnostic(
                message = "Decorators are not valid here.",
                category = DiagnosticCategory.Error,
                code = 1206,
                fileName = fileName,
                line = line,
                character = character,
                start = dec.pos,
                length = 1,
            ))
        }
    }

    private fun walkInvalidParamDecorators(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is Constructor -> { emitInvalidParamDecorators(member.parameters, source, fileName); member.body?.let { walkInvalidParamDecorators(it.statements, source, fileName) } }
                            is MethodDeclaration -> { emitInvalidParamDecorators(member.parameters, source, fileName); member.body?.let { walkInvalidParamDecorators(it.statements, source, fileName) } }
                            is GetAccessor -> { emitInvalidParamDecorators(member.parameters, source, fileName); member.body?.let { walkInvalidParamDecorators(it.statements, source, fileName) } }
                            is SetAccessor -> { emitInvalidParamDecorators(member.parameters, source, fileName); member.body?.let { walkInvalidParamDecorators(it.statements, source, fileName) } }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> { emitInvalidParamDecorators(stmt.parameters, source, fileName); stmt.body?.let { walkInvalidParamDecorators(it.statements, source, fileName) } }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkInvalidParamDecorators(it.statements, source, fileName) }
                is Block -> walkInvalidParamDecorators(stmt.statements, source, fileName)
                is IfStatement -> {
                    walkInvalidParamDecorators(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkInvalidParamDecorators(listOf(it), source, fileName) }
                }
                is ForStatement -> walkInvalidParamDecorators(listOf(stmt.statement), source, fileName)
                is ForInStatement -> walkInvalidParamDecorators(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> walkInvalidParamDecorators(listOf(stmt.statement), source, fileName)
                is WhileStatement -> walkInvalidParamDecorators(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkInvalidParamDecorators(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkInvalidParamDecorators(clause.statements, source, fileName)
                        is DefaultClause -> walkInvalidParamDecorators(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    walkInvalidParamDecorators(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { walkInvalidParamDecorators(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkInvalidParamDecorators(it.statements, source, fileName) }
                }
                is LabeledStatement -> walkInvalidParamDecorators(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkParameterDecoratorSignature(dec: Decorator, source: String, fileName: String) {
        // Resolve the decorator expression to a Type with call signature.
        // Two shapes: (a) `@Name` — Name is a function reference;
        // (b) `@Name(args)` — Name(args) returns a function.
        val (callableType, spanPos, spanLen) = when (val e = dec.expression) {
            is Identifier -> {
                val sym = globals[e.text] ?: return
                val fnDecl = sym.declarations.firstOrNull { it is FunctionDeclaration } as? FunctionDeclaration ?: return
                val sigType = getSignatureCallableTypeOfFunctionDecl(fnDecl) ?: return
                Triple(sigType, e.pos, e.text.length)
            }
            is CallExpression -> {
                val callee = e.expression as? Identifier ?: return
                val sym = globals[callee.text] ?: return
                val fnDecl = sym.declarations.firstOrNull { it is FunctionDeclaration } as? FunctionDeclaration ?: return
                // The fnDecl's return type IS the decorator function. For
                // `@ParameterDecorator2(20)`, `ParameterDecorator2` has return type
                // `(target, key, paramIndex) => void` — that's the actual decorator.
                val returnTypeNode = fnDecl.type ?: return
                val returnType = getTypeFromTypeNode(returnTypeNode)
                if (returnType !is Type.Object) return
                // Span covers the whole `Name(args)` expression.
                Triple(returnType, callee.pos, expressionTrueEnd(e) - callee.pos)
            }
            else -> return
        }
        if (callableType !is Type.Object) return
        val sig = callableType.callSignatures?.firstOrNull() ?: return
        if (sig.parameters.size < 2) return
        val keyParamType = getTypeOfSymbol(sig.parameters[1])
        // If keyParamType includes undefined, no error.
        if (typeIncludesUndefined(keyParamType)) return
        // Emit TS1239.
        val (line, character) = getLineAndCharacterOfPosition(source, spanPos)
        val display = typeToString(keyParamType)
        diagnostics.add(Diagnostic(
            message = "Unable to resolve signature of parameter decorator when called as an expression.",
            category = DiagnosticCategory.Error,
            code = 1239,
            fileName = fileName,
            line = line,
            character = character,
            start = spanPos,
            length = spanLen,
            messageChain = listOf("  Argument of type 'undefined' is not assignable to parameter of type '$display'."),
        ))
    }

    /** Resolve a top-level function declaration's "callable type" — i.e. the type the function
     *  evaluates to. For `@Name`, this is the function type itself. For `@Name(args)`, the call's
     *  return type. */
    private fun getSignatureCallableTypeOfFunctionDecl(fnDecl: FunctionDeclaration): Type? {
        // For `@Name`, the type of `Name` is a function type with call signature.
        // For `@Name(args)`, the type of `Name(args)` is the resolved return type.
        // We build a Type.Object with callSignatures from the function's signature.
        val sigParams = fnDecl.parameters.map { p ->
            val pSym = (p.name as? Identifier)?.text?.let { Symbol(SymbolFlags.FunctionScopedVariable, it) }
                ?: Symbol(SymbolFlags.FunctionScopedVariable, "_")
            pSym.valueDeclaration = p
            val pType = p.type?.let { getTypeFromTypeNode(it) } ?: anyType
            symbolTypes[pSym.id] = pType
            pSym
        }
        val returnType = fnDecl.type?.let { getTypeFromTypeNode(it) } ?: voidType
        val sig = Signature(
            parameters = sigParams,
            resolvedReturnType = returnType,
            minArgumentCount = requiredParameterCount(fnDecl.parameters),
        )
        val obj = Type.Object()
        obj.callSignatures = listOf(sig)
        return obj
    }

    private fun typeIncludesUndefined(t: Type): Boolean {
        if (t === anyType || t === unknownType) return true
        if (t.flags.hasAny(TypeFlags.Undefined or TypeFlags.Void)) return true
        if (t is Type.Union) return t.types.any { typeIncludesUndefined(it) }
        return false
    }

    /** B86.7d: symmetric to [typeIncludesUndefined] for the `null` constituent. */
    private fun typeIncludesNull(t: Type): Boolean {
        if (t === anyType || t === unknownType) return true
        if (t.flags.hasAny(TypeFlags.Null)) return true
        if (t is Type.Union) return t.types.any { typeIncludesNull(it) }
        return false
    }

    /** B86.7c: True for a single (non-union) type that is exactly `null`,
     *  `undefined`, or `void` — i.e. a nullish constituent of a union. */
    private fun isNullishConstituent(t: Type): Boolean =
        t !is Type.Union && t.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)

    // -----------------------------------------------------------------------
    // Public API
    // -----------------------------------------------------------------------

    /** Returns diagnostics produced by the checker, filtered to assigned files if set,
     *  and with tsc's `@ts-ignore`/`@ts-expect-error` comment directives applied
     *  ((CHK.31), [applyTsCommentDirectives]). */
    fun getDiagnostics(): List<Diagnostic> {
        // B57.3d (a): flush any deferred TS2589 emissions captured at
        // `new C<...>(...)` explicit-type-arg resolution sites that triggered
        // [deepInstantiationBailed]. Done once at first getDiagnostics() call.
        flushDeepBailNewExpressionEmits()
        val assigned = assignedFiles
        val visible =
            if (assigned == null) diagnostics.toList()
            else diagnostics.filter { it.fileName == null || it.fileName in assigned }
        return applyTsCommentDirectives(visible)
    }

    /**
     * (CHK.31) One `// @ts-ignore` / `// @ts-expect-error` comment directive, as
     * tsc's scanner records it (`appendIfCommentDirective`, scanner.ts).
     *
     * [pos]..[end] is the COMMENT's own span — and for a block comment only its
     * LAST LINE, because that is the only line tsc offers the directive regex
     * (`text.slice(lastLineStart ?? tokenStart, pos)`). A directive written on
     * an INNER line of a block comment is therefore not a directive at all,
     * which `tools/tsgo-7.0.2/lib/tsc` confirms: a three-line block comment whose
     * MIDDLE line spells the directive leaves the next line's error reported.
     *
     * The map this lands in is keyed by the line the comment ENDS on, which is
     * the line [markPrecedingTsCommentDirective] walks up to.
     */
    private class TsCommentDirective(
        val expectError: Boolean,
        val pos: Int,
        val end: Int,
    )

    /**
     * (CHK.31) The directives of one file, built once and memoized.
     *
     * The whole-source scans go through [srcHas]/[srcIndexOf] deliberately: the
     * round-895 n-gram filter answers "this file mentions no directive" without
     * touching the text, which is every file on all eight dashboard profiles
     * bar the three that merely SPELL the words in a string literal or a prose
     * comment.
     */
    private fun tsCommentDirectivesOf(fileName: String, source: String): Map<Int, TsCommentDirective> =
        tsCommentDirectiveCache.getOrPut(fileName) { scanTsCommentDirectives(source) }

    private fun scanTsCommentDirectives(source: String): Map<Int, TsCommentDirective> {
        val hasIgnore = srcHas(source, "@ts-ignore")
        val hasExpect = srcHas(source, "@ts-expect-error")
        if (!hasIgnore && !hasExpect) return emptyMap()
        // Insertion-ordered (ascending position) so a later directive on the
        // same line wins, exactly as tsc's `directivesByLine` Map build does.
        val out = mutableMapOf<Int, TsCommentDirective>()
        var from = 0
        while (from < source.length) {
            val a = if (hasIgnore) srcIndexOf(source, "@ts-ignore", from) else -1
            val b = if (hasExpect) srcIndexOf(source, "@ts-expect-error", from) else -1
            val at = when {
                a < 0 -> b
                b < 0 -> a
                else -> if (a < b) a else b
            }
            if (at < 0) break
            val directive = classifyTsCommentDirectiveAt(source, at, expectError = at == b)
            if (directive != null) {
                out[getLineAndCharacterOfPosition(source, directive.end).first] = directive
            }
            from = at + 1
        }
        return out
    }

    /**
     * (CHK.31) tsc's two directive regexes, hand-scanned:
     * `^\/\/\/?\s*@(ts-expect-error|ts-ignore)` for a `//` comment and
     * `^(?:\/|\*)*\s*@(ts-expect-error|ts-ignore)` for the last line of a block
     * comment (both applied to the comment text `trimStart()`ed). NEITHER has a
     * trailing word boundary, so `@ts-ignoreXYZ` IS a directive — measured on
     * tsgo 7.0.2, whose scanner is a plain `strings.HasPrefix`.
     *
     * Both regexes are anchored at the COMMENT's OWN START, which is why the
     * opener is located by a string-aware forward scan
     * ([commentOpenOnLineBefore]) and never by a backward `lastIndexOf("//")`:
     * `disableJsDiagnostics.ts` (the services profile) writes the prose comment
     * `// Only need to add ` + backtick + `// @ts-ignore` + backtick + ` for a line once.`
     * and a backward search lands on the INNER slashes, reading a sentence about
     * a quick fix as a live directive that silences the next line. Nothing but a
     * real codebase contains that shape — CLAUDE.md's (GATE.2) lesson.
     */
    private fun classifyTsCommentDirectiveAt(source: String, at: Int, expectError: Boolean): TsCommentDirective? {
        val lineStart = if (at == 0) 0 else source.lastIndexOf('\n', at - 1) + 1
        val opener = commentOpenOnLineBefore(source, lineStart, at)
        // A block comment, whether it opened on this line or an earlier one. tsc
        // offers the regex `text.slice(lastLineStart ?? tokenStart, pos)`, so the
        // directive only counts on the comment's LAST line.
        val blockStart = when {
            opener >= 0 && source[opener + 1] == '*' -> opener
            opener < 0 && source.lastIndexOf("/*", at) > source.lastIndexOf("*/", at) -> lineStart
            else -> -1
        }
        if (blockStart >= 0 && isTsDirectiveCommentPrefix(source, blockStart, at)) {
            val close = source.indexOf("*/", at)
            if (close >= 0) {
                var j = at
                var sameLine = true
                while (j < close) { if (source[j] == '\n') { sameLine = false; break }; j++ }
                if (sameLine) return TsCommentDirective(expectError, blockStart, close + 2)
            }
            return null
        }
        if (opener < 0 || source[opener + 1] != '/') return null
        var count = 0
        var k = opener
        while (k < at && source[k] == '/') { count++; k++ }
        if (count != 2 && count != 3) return null
        while (k < at && (source[k] == ' ' || source[k] == '\t')) k++
        if (k != at) return null
        var end = at
        while (end < source.length && source[end] != '\n' && source[end] != '\r') end++
        return TsCommentDirective(expectError, opener, end)
    }

    /** (CHK.31) `^\s*(?:\/|\*)*\s*$` — the text a block comment's last line may
     *  carry before the `@`, per tsc's multi-line directive regex applied to the
     *  `trimStart()`ed comment text. */
    private fun isTsDirectiveCommentPrefix(source: String, from: Int, to: Int): Boolean {
        var k = from
        while (k < to && (source[k] == ' ' || source[k] == '\t')) k++
        while (k < to && (source[k] == '/' || source[k] == '*')) k++
        while (k < to && (source[k] == ' ' || source[k] == '\t')) k++
        return k == to
    }

    /**
     * (CHK.31) The offset at which a comment OPENS on [at]'s own line before
     * [at], or -1 — string-aware, because a `//` inside a string or a template
     * is not a comment opener and a directive regex anchored anywhere but the
     * real comment start is a suppression the author never wrote.
     */
    private fun commentOpenOnLineBefore(source: String, lineStart: Int, at: Int): Int {
        var k = lineStart
        while (k < at) {
            val ch = source[k]
            if (ch == '"' || ch == '\'' || ch == '`') {
                k++
                while (k < at) {
                    if (source[k] == '\\') { k += 2; continue }
                    if (source[k] == ch) { k++; break }
                    k++
                }
            } else if (ch == '/' && k + 1 < source.length && source[k + 1] == '/') {
                return k
            } else if (ch == '/' && k + 1 < source.length && source[k + 1] == '*') {
                // A block that CLOSES before `at` is trivia the directive sits
                // after, not the comment carrying it: `/* a block */ // @ts-ignore`.
                val close = source.indexOf("*/", k + 2)
                if (close < 0 || close + 2 > at) return k
                k = close + 2
            } else {
                k++
            }
        }
        return -1
    }

    /**
     * (CHK.31) tsc's `markPrecedingCommentDirectiveLine` (program.ts), 1-based:
     * from the line ABOVE the diagnostic, walk UP — a line carrying a directive
     * suppresses (and is returned, so the caller can mark it USED); a blank line
     * or a `//` line continues the walk; anything else stops it, INCLUDING the
     * body or tail line of a block comment.
     *
     * Returns the suppressing line, or -1.
     */
    private fun markPrecedingTsCommentDirective(
        source: String,
        diagnosticLine: Int,
        directives: Map<Int, TsCommentDirective>,
    ): Int {
        val starts = lineStartsFor(source)
        var line = diagnosticLine - 1
        while (line >= 1) {
            if (directives.containsKey(line)) return line
            if (line > starts.size) return -1
            val s = starts[line - 1]
            val e = if (line < starts.size) starts[line] else source.length
            val text = source.substring(s, e).trim()
            if (text.isNotEmpty() && !text.startsWith("//")) return -1
            line--
        }
        return -1
    }

    /**
     * (CHK.31) The general comment-directive filter, applied at the one funnel
     * every consumer passes through ([getDiagnostics]).
     *
     * Two halves, in tsc's order: every diagnostic preceded by a directive is
     * DROPPED and marks that directive used, then every `@ts-expect-error` that
     * marked nothing is reported as TS2578.
     *
     * THE PARTITION RULE: both halves are scoped to [checkedResults], i.e. to
     * the files this checker actually WALKED — never to the whole program. A
     * file the partition did not check produces no diagnostics for its
     * `@ts-expect-error` to suppress, so a program-wide TS2578 pass would
     * manufacture one false positive per directive on every narrowed build,
     * which is exactly what an editor asks for. (INC.20)'s per-file rule.
     *
     * Pure in [diagnostics]: [getDiagnostics] is called more than once per
     * compile, so nothing here mutates the list it reads.
     */
    private fun applyTsCommentDirectives(visible: List<Diagnostic>): List<Diagnostic> {
        var perFile: MutableMap<String, Map<Int, TsCommentDirective>>? = null
        var sources: MutableMap<String, String>? = null
        // Deliberately the FIELD, not the (INC.17) `checkedResults` getter: that
        // getter's census classifies `init` PASSES as partition-invariant or
        // partition-dependent, and this is not a pass — it is the public API,
        // called after every pass has run and more than once per compile. Routing
        // it through the getter attributes a read to no pass at all, which is
        // exactly what `PartitionCensusHookTest` refuses (and rightly: the
        // per-pass sums must partition the reads, not sample them).
        for (result in checkedResultsAll) {
            val fileName = result.sourceFile.fileName
            val text = result.sourceFile.text
            val directives = tsCommentDirectivesOf(fileName, text)
            if (directives.isEmpty()) continue
            if (perFile == null) { perFile = mutableMapOf(); sources = mutableMapOf() }
            perFile[fileName] = directives
            sources!![fileName] = text
        }
        val files = perFile ?: return visible
        val texts = sources!!
        val used = HashMap<String, MutableSet<Int>>()
        val kept = ArrayList<Diagnostic>(visible.size)
        for (d in visible) {
            val fileName = d.fileName
            val directives = if (fileName == null) null else files[fileName]
            if (directives == null || fileName == null) { kept.add(d); continue }
            val source = texts[fileName]!!
            val line = d.line ?: d.start?.let { getLineAndCharacterOfPosition(source, it).first }
            if (line == null) { kept.add(d); continue }
            val marked = markPrecedingTsCommentDirective(source, line, directives)
            if (marked >= 0) used.getOrPut(fileName) { HashSet() }.add(marked) else kept.add(d)
        }
        for ((fileName, directives) in files) {
            val source = texts[fileName]!!
            val usedHere = used[fileName]
            for ((line, directive) in directives) {
                if (!directive.expectError) continue
                if (usedHere != null && line in usedHere) continue
                val (l, c) = getLineAndCharacterOfPosition(source, directive.pos)
                kept.add(Diagnostic(
                    message = "Unused '@ts-expect-error' directive.",
                    category = DiagnosticCategory.Error, code = 2578, fileName = fileName,
                    line = l, character = c, start = directive.pos, length = directive.end - directive.pos,
                ))
            }
        }
        return kept
    }


    // -----------------------------------------------------------------------
    // Public API — called by Transformer
    // -----------------------------------------------------------------------

    /**
     * Check if an import/export alias is referenced in value positions.
     * If not referenced, the import can be elided from JS output.
     */
    fun isReferencedAliasDeclaration(node: Node): Boolean {
        // (INC.10) THE ASK. The whole-program alias walk runs here, once per
        // checker that is ever questioned, instead of in every checker's `init`.
        ensureImportReferencesTracked()
        val key = nodeKey(node)
        for (result in binderResults) {
            val symbol = result.nodeToSymbol[key]
            if (symbol != null) {
                // Check if this specific symbol is referenced
                if (symbol.id in referencedAliases) return true
                // For ImportDeclarations with named imports, check if ANY specifier is referenced
                if (node is ImportDeclaration) {
                    val clause = node.importClause ?: return false
                    val bindings = clause.namedBindings
                    if (bindings is NamedImports) {
                        return bindings.elements.any { spec ->
                            val specSymbol = result.nodeToSymbol[nodeKey(spec)]
                            specSymbol != null && specSymbol.id in referencedAliases
                        }
                    }
                    // Default import or namespace import
                    return false
                }
                return false
            }
        }
        return true // safe default: keep the import
    }

    /**
     * Check if an export assignment refers to a value (not just a type).
     */
    fun isValueAliasDeclaration(node: Node): Boolean {
        if (node !is ExportAssignment) return true
        val expr = node.expression
        if (expr is Identifier) {
            val symbol = resolveIdentifierInFile(expr.text, node)
            if (symbol != null) {
                return symbol.flags.hasAny(SymbolFlags.Value)
            }
        }
        return true // expressions are always values
    }

    /**
     * Check if a re-exported name from a module specifier is a value (not type-only).
     * Used for `export { name } from "module"` — elide specifiers that are type-only
     * (interfaces, type aliases, non-instantiated namespaces).
     */
    fun isValueExport(name: String, moduleSpecifier: String, sourceFileName: String): Boolean {
        fileResults[sourceFileName] ?: return true
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return true
        val targetResult = fileResults[targetFile] ?: return true
        val symbol = targetResult.locals[name] ?: return true // safe default: keep
        val resolved = resolveAlias(symbol)
        // Scan target file's source statements directly to classify declarations of `name` —
        // avoids consulting symbol flags / declarations list, which `mergeSymbolTable` pollutes
        // by merging same-name symbols from importing files (CLAUDE.md gotcha: "ALL file locals
        // merged into globals at Checker init"). Identifies a value declaration in the target
        // file if present; otherwise falls back to flag-based logic for cross-file ambient cases.
        var hasValueDecl = false
        var hasTypeOnlyDecl = false
        var hasInstantiatedModule = false
        for (stmt in targetResult.sourceFile.statements) {
            when (stmt) {
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasTypeOnlyDecl = true
                is InterfaceDeclaration -> if (stmt.name.text == name) hasTypeOnlyDecl = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasValueDecl = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValueDecl = true
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val declName = decl.name
                        if (declName is Identifier && declName.text == name) hasValueDecl = true
                    }
                }
                is EnumDeclaration -> if (stmt.name.text == name) {
                    val isConstEnum = ModifierFlag.Const in stmt.modifiers
                    if (isConstEnum && !options.preserveConstEnums && !options.isolatedModules &&
                        !options.verbatimModuleSyntax) {
                        hasTypeOnlyDecl = true
                    } else {
                        hasValueDecl = true
                    }
                }
                is ModuleDeclaration -> {
                    val moduleName = stmt.name
                    val n = if (moduleName is Identifier) moduleName.text
                            else if (moduleName is StringLiteralNode) moduleName.text
                            else null
                    if (n == null || n != name) continue
                    val state = binderResults.firstNotNullOfOrNull { br ->
                        br.moduleInstanceStates[nodeKey(stmt)]
                    }
                    if (state == ModuleInstanceState.Instantiated) {
                        hasInstantiatedModule = true
                    } else {
                        hasTypeOnlyDecl = true
                    }
                }
                else -> {}
            }
        }
        if (hasValueDecl || hasInstantiatedModule) return true
        if (hasTypeOnlyDecl) return false
        // Name not found as a direct declaration in target file — fall back to symbol-flag logic
        // for ambient/aliased cases (e.g. `export { X }` from another module).
        if (!options.preserveConstEnums && !options.isolatedModules && !options.verbatimModuleSyntax &&
            resolved.flags.hasAny(SymbolFlags.ConstEnum)) return false
        if (resolved.flags.hasAny(SymbolFlags.Value)) return true
        if (resolved.flags.hasAny(SymbolFlags.Module) && !resolved.flags.hasAny(SymbolFlags.Value)) {
            for (br in binderResults) {
                for (decl in resolved.declarations) {
                    if (decl is ModuleDeclaration) {
                        val state = br.moduleInstanceStates[nodeKey(decl)]
                        if (state == ModuleInstanceState.Instantiated) return true
                    }
                }
            }
            return false
        }
        return false
    }

    /**
     * B503: True iff the target module has at least one export and ALL of its exports are
     * type-only (interfaces, type aliases, uninstantiated namespaces). A namespace import
     * (`import * as X from "m"`) of such a module is type-only — the runtime module object
     * would be empty — so tsc elides the require even when the name `X` is also a runtime
     * value via a same-name merged local namespace (the namespace owns the value side, so a
     * value-reference check cannot detect this — see namespaceMergedWithImportAliasNoCrash).
     *
     * CONSERVATIVE: returns false (→ keep the require, the safe/current behavior) on any
     * uncertainty — unresolvable module, `export =`/`export default`, `export {…}`/`export *`
     * re-exports, or an unrecognized exported declaration. Only a module whose every export is
     * a directly-declared type-only entity yields true.
     */
    fun moduleHasOnlyTypeOnlyExports(moduleSpecifier: String, sourceFileName: String): Boolean {
        fileResults[sourceFileName] ?: return false
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return false
        val targetResult = fileResults[targetFile] ?: return false
        var sawExport = false
        for (stmt in targetResult.sourceFile.statements) {
            when (stmt) {
                // `export =` / `export default` — a runtime export shape; keep.
                is ExportAssignment -> return false
                // `export { … }` / `export * from …` re-exports — can re-export values; keep.
                is ExportDeclaration -> return false
                is InterfaceDeclaration -> if (ModifierFlag.Export in stmt.modifiers) sawExport = true
                is TypeAliasDeclaration -> if (ModifierFlag.Export in stmt.modifiers) sawExport = true
                is ClassDeclaration -> if (ModifierFlag.Export in stmt.modifiers) return false
                is FunctionDeclaration -> if (ModifierFlag.Export in stmt.modifiers) return false
                is VariableStatement -> if (ModifierFlag.Export in stmt.modifiers) return false
                is EnumDeclaration -> if (ModifierFlag.Export in stmt.modifiers) {
                    val isConstEnum = ModifierFlag.Const in stmt.modifiers
                    val erasable = isConstEnum && !options.preserveConstEnums &&
                        !options.isolatedModules && !options.verbatimModuleSyntax
                    if (!erasable) return false else sawExport = true
                }
                is ModuleDeclaration -> if (ModifierFlag.Export in stmt.modifiers) {
                    val instantiated = binderResults.firstNotNullOfOrNull { br ->
                        br.moduleInstanceStates[nodeKey(stmt)]
                    } == ModuleInstanceState.Instantiated
                    if (instantiated) return false else sawExport = true
                }
                is ImportEqualsDeclaration -> if (ModifierFlag.Export in stmt.modifiers) return false
                else -> {}
            }
        }
        return sawExport
    }

    /**
     * Get the constant value of an enum member node.
     */
    fun getEnumMemberValue(memberNode: Node): ConstantValue? {
        val key = nodeKey(memberNode)
        for (result in binderResults) {
            val symbol = result.nodeToSymbol[key]
            if (symbol != null) {
                val enumSymbol = symbol.parent ?: return null
                return enumValues[enumSymbol.id]?.get(symbol.name)
            }
        }
        return null
    }

    /**
     * Check if an import=require() resolves to a type-only module (only interfaces/types).
     * Used by CJS transform to elide require() for type-only imports.
     */
    /**
     * Returns true if a symbol is purely type-only based on its declaration nodes.
     * This avoids using symbol.flags which may be polluted by cross-file merging.
     * - InterfaceDeclaration / TypeAliasDeclaration → always type-only
     * - ModuleDeclaration with NonInstantiated state → type-only
     * - VariableDeclaration, FunctionDeclaration, ClassDeclaration, EnumDeclaration → value
     * - ImportSpecifier with Alias flags → check underlying if resolvable, otherwise conservative
     */
    private fun isSymbolTypeOnly(symbol: Symbol): Boolean {
        var hasValueDecl = false
        var hasTypeOnlyDecl = false
        for (decl in symbol.declarations) {
            when (decl) {
                is InterfaceDeclaration, is TypeAliasDeclaration -> hasTypeOnlyDecl = true
                is ModuleDeclaration -> {
                    // Module is type-only only if NonInstantiated (no runtime IIFE)
                    val state = binderResults.firstNotNullOfOrNull { br ->
                        br.moduleInstanceStates[nodeKey(decl)]
                    }
                    if (state == ModuleInstanceState.Instantiated || state == null) {
                        hasValueDecl = true
                    } else {
                        // Even a NonInstantiated namespace can be a value if it has value exports
                        // (e.g. `declare namespace a { export const x: number }; export = a`)
                        val hasValueExports = symbol.exports?.values?.any { it.flags.hasAny(SymbolFlags.Value) } == true
                        if (hasValueExports) {
                            hasValueDecl = true
                        } else {
                            hasTypeOnlyDecl = true
                        }
                    }
                }
                is VariableDeclaration, is FunctionDeclaration,
                is ClassDeclaration, is EnumDeclaration -> hasValueDecl = true
                else -> {} // ImportSpecifier, BindingElement, etc. - ignore for now
            }
        }
        if (hasValueDecl) return false
        return hasTypeOnlyDecl
    }

    fun isTypeOnlyImportRequire(moduleSpecifier: String, sourceFileName: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null)
        if (targetFile != null) {
            val targetResult = fileResults[targetFile] ?: return false
            // Check all exports from the target file
            for (stmt in targetResult.sourceFile.statements) {
                when (stmt) {
                    is ExportAssignment -> {
                        if (stmt.isExportEquals) {
                            val expr = stmt.expression
                            if (expr is Identifier) {
                                val symbol = targetResult.locals[expr.text]
                                if (symbol != null) {
                                    // Note: symbol.flags may have been polluted by cross-file merging
                                    // (e.g. Interface|Alias when another file imports this name).
                                    // Use the node-level declaration kind to determine the original type.
                                    return isSymbolTypeOnly(symbol)
                                }
                            }
                            return false // expression export = always value
                        }
                    }
                    else -> {}
                }
            }
            return false
        }
        // File-based resolution failed — check ambient external modules (declare module "X").
        // Look through all files for `declare module "specifier"` blocks whose exports are type-only.
        return isAmbientModuleTypeOnly(moduleSpecifier)
    }

    /**
     * 17.230: returns true when there's an ambient external module
     * `declare module "X";` with no body block in the file corpus. Used to
     * carve out the TS2693 routing in [checkTypeUsedAsValue] — body-less
     * ambient modules are `any`-typed (everything from them is value-side),
     * so importing them with `import X = require("X")` produces a value
     * alias, not a type-only one.
     */
    private fun isBodylessAmbientModule(moduleName: String): Boolean {
        for (result in binderResults) {
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode
                    && (stmt.name).text == moduleName
                    && stmt.body == null) {
                    return true
                }
            }
        }
        return false
    }

    /**
     * 17.230: returns true when the module resolved by [moduleSpecifier] has
     * `export = X` where X is a namespace (ModuleDeclaration with no Module
     * flag — pure type-side namespace). Used to skip TS2693 routing in
     * [checkTypeUsedAsValue] — namespaces used as values should fire TS2708
     * "Cannot use namespace 'X' as a value", a different diagnostic that
     * isn't yet wired through this path.
     *
     * 17.232: also handles the ambient external module form
     * `declare module "X" { ... export = Y; namespace Y { ... } }` —
     * when file-based resolution fails (bare specifier like `"foo"`),
     * walk all script-file ambient module blocks matching the specifier
     * and look for `export = Identifier` inside whose target is a
     * `ModuleDeclaration` in the same block.
     */
    private fun exportEqualsIsNamespace(moduleSpecifier: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null)
        if (targetFile != null) {
            val targetResult = fileResults[targetFile] ?: return false
            for (stmt in targetResult.sourceFile.statements) {
                if (stmt is ExportAssignment && stmt.isExportEquals) {
                    val expr = stmt.expression as? Identifier ?: continue
                    // Find the named declaration in the target file's statements.
                    for (s in targetResult.sourceFile.statements) {
                        if (s is ModuleDeclaration && s.name is Identifier
                            && (s.name).text == expr.text) {
                            return true
                        }
                    }
                }
            }
            return false
        }
        // File-based resolution failed — check ambient external modules
        // (declare module "specifier"). Mirrors isTypeOnlyImportRequire's
        // ambient fallback.
        for (result in binderResults) {
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if (stmt.name !is StringLiteralNode) continue
                if ((stmt.name).text != moduleSpecifier) continue
                val body = stmt.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s is ExportAssignment && s.isExportEquals) {
                        val expr = s.expression as? Identifier ?: continue
                        // Look for a ModuleDeclaration with the matching name
                        // inside the same ambient module's body.
                        for (inner in body.statements) {
                            if (inner is ModuleDeclaration && inner.name is Identifier
                                && (inner.name).text == expr.text) {
                                return true
                            }
                        }
                    }
                }
            }
        }
        return false
    }

    /**
     * B508: For an ambient `declare module "<spec>"` whose body has `export default <Name>`
     * where <Name> resolves to a body-level TYPE-ONLY namespace, return <Name>; else null.
     * Reads the ambient body AST directly (B494 pattern — does NOT rely on resolveAlias,
     * which cannot reach an ambient module's default export). Used to detect a JS-file
     * default import that binds to a type-only namespace (TS18042 + value-use TS2708).
     */
    private fun ambientDefaultExportTypeOnlyNamespace(spec: String): String? {
        for (result in binderResults) {
            // Only SCRIPT files define ambient external modules; in module files
            // `declare module "X"` is an augmentation (mirrors isAmbientModuleTypeOnly).
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if (stmt.name !is StringLiteralNode) continue
                if ((stmt.name).text != spec) continue
                val body = stmt.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s is ExportAssignment && !s.isExportEquals) {
                        val expr = s.expression as? Identifier ?: continue
                        for (inner in body.statements) {
                            if (inner is ModuleDeclaration && inner.name is Identifier
                                && (inner.name).text == expr.text) {
                                val innerBody = inner.body as? ModuleBlock ?: continue
                                if (isModuleBlockTypeOnly(innerBody)) return expr.text
                            }
                        }
                    }
                }
            }
        }
        return null
    }

    /**
     * Check if an ambient external module (declare module "X") exports only types.
     * Searches all files for matching `declare module` blocks and checks their exports.
     */
    /**
     * Like [isTypeOnlyImportRequire] but for a NAMESPACE import (`import * as y from "X"`).
     * A body-less `declare module "X";` is an UNTYPED (`any`) runtime module, so its namespace
     * import must be KEPT (esModuleInteropTslibHelpers: `import * as path from "path"`), whereas
     * an `export = <type-only>` ambient module is genuinely type-only and elided
     * (es6ExportEqualsInterop: `import * as y1 from "interface"`).
     */
    fun isTypeOnlyNamespaceImportModule(moduleSpecifier: String, sourceFileName: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null)
        if (targetFile != null) return isTypeOnlyImportRequire(moduleSpecifier, sourceFileName)
        return isAmbientModuleTypeOnly(moduleSpecifier, emptyModuleIsTypeOnly = false)
    }

    private fun isAmbientModuleTypeOnly(moduleName: String, emptyModuleIsTypeOnly: Boolean = true): Boolean {
        for (result in binderResults) {
            // Skip files that are themselves modules (have imports/exports).
            // In module files, `declare module "X"` is an augmentation, not a definition.
            // Only script files can define ambient external modules.
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && stmt.name is StringLiteralNode
                    && (stmt.name).text == moduleName) {
                    // Found the ambient module definition. Analyze the body AST directly.
                    // Cannot rely on result.locals[moduleName] because an import alias
                    // with the same name (import x = require("x")) may overwrite the symbol.
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        return isModuleBlockTypeOnly(body)
                    }
                    // No body — an empty ambient module. Type-only for import=require elision,
                    // but a body-less `declare module "X";` is an untyped runtime module for a
                    // namespace import (see isTypeOnlyNamespaceImportModule).
                    return emptyModuleIsTypeOnly
                }
            }
        }
        return false
    }

    /**
     * Check if a ModuleBlock contains only type declarations (interfaces, type aliases,
     * non-instantiated namespaces). Analyzes AST directly without symbol lookup.
     */
    private fun isModuleBlockTypeOnly(block: ModuleBlock): Boolean {
        for (stmt in block.statements) {
            when (stmt) {
                is ExportAssignment -> {
                    if (stmt.isExportEquals) {
                        val expr = stmt.expression
                        if (expr is Identifier) {
                            // Look for the exported name among the block's own declarations
                            return isNameTypeOnlyInBlock(expr.text, block)
                        }
                        return false // expression export = always value
                    }
                    // export default — check expression type
                }
                is VariableStatement -> return false // variables are values
                is FunctionDeclaration -> return false
                is ClassDeclaration -> return false
                is EnumDeclaration -> return false
                is InterfaceDeclaration -> { /* type-only, continue */ }
                is TypeAliasDeclaration -> { /* type-only, continue */ }
                is ModuleDeclaration -> {
                    // Nested namespace — check if instantiated
                    val br = binderResults.firstOrNull() ?: return false
                    val state = br.moduleInstanceStates[nodeKey(stmt)]
                    if (state == ModuleInstanceState.Instantiated) return false
                }
                is ExportDeclaration -> { /* re-export — skip for now */ }
                is ImportDeclaration -> { /* import — skip */ }
                is ImportEqualsDeclaration -> { /* import — skip */ }
                else -> { /* other statements */ }
            }
        }
        return true // all statements are type-only
    }

    /**
     * Check if a name declared within a ModuleBlock is type-only.
     * Used for `export = Name` resolution in ambient modules.
     */
    private fun isNameTypeOnlyInBlock(name: String, block: ModuleBlock): Boolean {
        var hasValueDecl = false
        var hasTypeOnlyDecl = false
        for (stmt in block.statements) {
            when (stmt) {
                is InterfaceDeclaration -> if (stmt.name.text == name) hasTypeOnlyDecl = true
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasTypeOnlyDecl = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasValueDecl = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValueDecl = true
                is EnumDeclaration -> if (stmt.name.text == name) hasValueDecl = true
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        if (d.name is Identifier && (d.name).text == name) {
                            hasValueDecl = true
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val modName = when (val n = stmt.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> null
                    }
                    if (modName == name) {
                        // Check if the namespace has value exports
                        val br = binderResults.firstOrNull() ?: continue
                        val state = br.moduleInstanceStates[nodeKey(stmt)]
                        if (state == ModuleInstanceState.Instantiated) {
                            hasValueDecl = true
                        } else {
                            hasTypeOnlyDecl = true
                        }
                    }
                }
                else -> {}
            }
        }
        if (hasValueDecl) return false
        return hasTypeOnlyDecl
    }

    /**
     * Check if a name resolves to a type-only declaration across all files.
     * Used for `export { X }` (no from) to decide if void 0 hoist is needed.
     * Returns true if the name is a type-only symbol (interface, type alias,
     * non-instantiated namespace). Returns false if it's a value or unknown.
     */
    fun isTypeOnlyGlobalName(name: String): Boolean {
        // Check globals first
        val globalSymbol = globals[name]
        if (globalSymbol != null) {
            val resolved = resolveAlias(globalSymbol)
            if (resolved.flags.hasAny(SymbolFlags.Value)) return false
            if (resolved.flags.hasAny(SymbolFlags.Module) && !resolved.flags.hasAny(SymbolFlags.Value)) {
                // If the namespace exports any value members, it's not type-only
                // (e.g. `declare namespace NS { export var foo }` has a runtime value shape)
                val exports = resolved.exports
                if (exports != null && exports.values.any { it.flags.hasAny(SymbolFlags.Value) }) return false
                for (br in binderResults) {
                    for (decl in resolved.declarations) {
                        if (decl is ModuleDeclaration) {
                            val state = br.moduleInstanceStates[nodeKey(decl)]
                            if (state == ModuleInstanceState.Instantiated) return false
                        }
                    }
                }
                return true
            }
            return resolved.flags.hasAny(SymbolFlags.Type) && !resolved.flags.hasAny(SymbolFlags.Value)
        }
        // Check all file locals
        for (result in binderResults) {
            val symbol = result.locals[name]
            if (symbol != null) {
                val resolved = resolveAlias(symbol)
                if (resolved.flags.hasAny(SymbolFlags.Value)) return false
                if (resolved.flags.hasAny(SymbolFlags.Module) && !resolved.flags.hasAny(SymbolFlags.Value)) {
                    // If the namespace exports any value members, it's not type-only
                    val exports = resolved.exports
                    if (exports != null && exports.values.any { it.flags.hasAny(SymbolFlags.Value) }) return false
                    for (br in binderResults) {
                        for (decl in resolved.declarations) {
                            if (decl is ModuleDeclaration) {
                                val state = br.moduleInstanceStates[nodeKey(decl)]
                                if (state == ModuleInstanceState.Instantiated) return false
                            }
                        }
                    }
                    return true
                }
                return resolved.flags.hasAny(SymbolFlags.Type) && !resolved.flags.hasAny(SymbolFlags.Value)
            }
        }
        return false // unknown name — conservative, keep the export
    }

    /**
     * Resolve a const enum member access like `E.A` to its constant value.
     * Returns null if `enumName` is not a const enum or `memberName` is not found.
     */
    /**
     * EP.1 (round 669): resolve [path] — a bare name (`Kind`, from a named
     * import) or a namespace-qualified one (`B.Kind`, from `import * as B`) —
     * to a CONST ENUM symbol through the imported module's `export * from`
     * chain. Neither [resolveNamePath] nor [resolveAlias] can follow that chain:
     * both walk `symbol.exports`, and a star re-export never populates the
     * barrel's own export table (the same root cause as round 668's TS2694 FP).
     * Without this, a const enum imported through a barrel — tsc's own
     * `_namespaces/ts.js` layout — kept `barrel_1.Kind.B` in the emit instead of
     * inlining `1 /* Kind.B */`.
     *
     * CONST-ENUM-ONLY BY CONSTRUCTION: it returns a symbol ONLY when the target
     * carries `SymbolFlags.ConstEnum`, so it can never feed a general type
     * resolution. That is what keeps it clear of the documented dead-end where
     * star-following inside the general [resolveAlias] flooded TS2315 x466 by
     * resolving barrel-imported TYPES and arity-checking them.
     */
    private fun constEnumSymbolThroughStars(path: String, sourceFileName: String): Symbol? {
        val importer = fileResults[sourceFileName] ?: return null
        val parts = path.split(".")
        val rootName = parts[0]
        val memberSeg = parts.getOrNull(1)
        for (stmt in importer.sourceFile.statements) {
            val imp = stmt as? ImportDeclaration ?: continue
            val spec = (imp.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val clause = imp.importClause ?: continue
            // Which name are we looking for in the TARGET module's star closure?
            // `restIdx` is the index of the FIRST path segment still unconsumed
            // once `exportedName` has been looked up in the star closure — the
            // path may continue through nested namespaces (see the descent below).
            val restIdx: Int
            val exportedName: String = when (val nb = clause.namedBindings) {
                is NamespaceImport -> {
                    if (nb.name.text != rootName || memberSeg == null) continue
                    restIdx = 2 // `B.Kind…` — `B` is the import, `Kind` is exportedName
                    memberSeg
                }
                is NamedImports -> {
                    val el = nb.elements.firstOrNull { it.name.text == rootName } ?: continue
                    restIdx = 1 // `tracing…` — the root itself is exportedName
                    (el.propertyName ?: el.name).text
                }
                else -> continue
            }
            // Resolution must be `.js`-AWARE: tsc's own barrels are imported as
            // ESM `./_namespaces/ts.js`, and `resolveModuleSpecifier`
            // deliberately does NOT strip the extension (the TS2459 firewall).
            // [resolveBarrelStarTarget] is the tested `.js`/`.jsx`-stripping
            // resolver the star-follower itself uses; without it this helper
            // could not resolve tsc's layout at all — round 669 shipped with
            // the extension-blind form and inlined 0 of the ~16.5 k reads the
            // emit-diff gate later showed were missing.
            val targetSf = resolveBarrelStarTarget(spec, sourceFileName)
                ?: (resolveModuleSpecifier(spec, imp.moduleSpecifier)
                    ?: resolveModuleSpecifierRelative(spec, sourceFileName))
                    ?.let { fileResults[it]?.sourceFile }
                ?: continue
            val sym = resolveExportedSymbolThroughStars(targetSf, exportedName) ?: continue
            descendToConstEnum(resolveAlias(sym), parts, restIdx)?.let { return it }
        }
        return null
    }

    /**
     * Walk the still-unconsumed segments of a const-enum access path down through
     * NAMESPACE exports, returning the const-enum symbol the path names.
     *
     * A const enum may be nested in a namespace (`namespace tracing { export
     * const enum Phase { … } }`), so the barrel's star closure yields the
     * NAMESPACE for the first segment, not the enum. That matters because the
     * binder sets `SymbolFlags.ConstEnum` on a namespace holding only const enums
     * — so the caller's flag test passes on the namespace and the `enumValues`
     * lookup, which is keyed by the ENUM's symbol id, then silently misses.
     *
     * Descent stops as soon as a genuine `EnumDeclaration` is reached: any
     * segments after that are member names, which the caller resolves.
     * With no segments left this returns the start symbol unchanged (the plain
     * `import { Kind } from "./barrel"` case, and the elision probe in
     * [isConstEnumAlias], which asks only about the root name).
     */
    private fun descendToConstEnum(start: Symbol, parts: List<String>, fromIdx: Int): Symbol? {
        var cur = start
        var i = fromIdx
        while (i < parts.size) {
            if (cur.declarations.any { it is EnumDeclaration }) break
            var next = cur.exports?.get(parts[i])
            if (next == null) {
                // The segment may be reached through a VARIABLE whose TYPE is the
                // namespace — see [namespaceBehindTypeofVariable].
                val ns = namespaceBehindTypeofVariable(cur) ?: return null
                next = ns.exports?.get(parts[i]) ?: return null
            }
            cur = resolveAlias(next)
            i++
        }
        return if (cur.flags.hasAny(SymbolFlags.ConstEnum)) cur else null
    }

    /**
     * Resolve `let x: typeof NS | undefined` to `NS`, so a const enum reached
     * through the VARIABLE inlines the way tsc's does.
     *
     * EP.2g (round 678): tsc's own tracing.ts declares
     * `export namespace tracingEnabled { export const enum Phase { … } }` beside
     * `export let tracing: typeof tracingEnabled | undefined`, and every call
     * site writes `tracing.Phase.Bind`. The receiver is therefore a runtime
     * VARIABLE, not a namespace — name resolution stops there and the member
     * never inlines. tsc reaches the enum through the variable's declared type.
     * This was the entire residual const-enum gap (34 reads across seven files).
     *
     * Deliberately narrow: only a `typeof <identifier>` annotation (optionally
     * inside a union or parentheses, which is how the `| undefined` form is
     * written) is followed, and the target is resolved in the DECLARING file
     * first. The variable itself keeps its runtime identity — it is a real
     * binding, so its import must NOT be elided, which holds because the
     * variable symbol carries no `ConstEnum` flag.
     */
    private fun namespaceBehindTypeofVariable(sym: Symbol): Symbol? {
        for (d in sym.declarations) {
            val vd = d as? VariableDeclaration ?: continue
            val name = typeQueryTargetName(vd.type ?: continue) ?: continue
            val declFile = owningSourceFile(vd)?.fileName
            val local = declFile?.let { fileResults[it]?.locals?.get(name) }
            (local ?: globals[name])?.let { resolveAlias(it) }
                ?.takeIf { it.exports != null }
                ?.let { return it }
            // The namespace NAME may itself arrive through an `export *` barrel,
            // which `resolveAlias` cannot follow — same gap the const-enum path
            // has, so use the same star-following resolver.
            declFile?.let { namespaceThroughStarImports(name, it) }?.let { return it }
        }
        return null
    }

    /**
     * Resolve a named import to the NAMESPACE symbol it denotes, following
     * `export *` barrels. Suppression-free and read-only: it returns a symbol
     * only when one is genuinely exported and carries an export table, so it can
     * never invent a resolution. Kept separate from
     * [constEnumSymbolThroughStars], which answers the narrower const-enum
     * question and whose working path is left untouched.
     */
    private fun namespaceThroughStarImports(name: String, fileName: String): Symbol? {
        val importer = fileResults[fileName] ?: return null
        for (stmt in importer.sourceFile.statements) {
            val imp = stmt as? ImportDeclaration ?: continue
            val spec = (imp.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val nb = (imp.importClause ?: continue).namedBindings as? NamedImports ?: continue
            val el = nb.elements.firstOrNull { it.name.text == name } ?: continue
            val exportedName = (el.propertyName ?: el.name).text
            val targetSf = resolveBarrelStarTarget(spec, fileName)
                ?: (resolveModuleSpecifier(spec, imp.moduleSpecifier)
                    ?: resolveModuleSpecifierRelative(spec, fileName))
                    ?.let { fileResults[it]?.sourceFile }
                ?: continue
            val resolved = resolveExportedSymbolThroughStars(targetSf, exportedName)
                ?.let { resolveAlias(it) } ?: continue
            if (resolved.exports != null) return resolved
        }
        return null
    }

    /** The bare identifier of a `typeof X` annotation, seen through unions/parens. */
    private fun typeQueryTargetName(t: TypeNode): String? = when (t) {
        is TypeQuery -> (t.exprName as? Identifier)?.text
        is UnionType -> t.types.firstNotNullOfOrNull { typeQueryTargetName(it) }
        is ParenthesizedType -> typeQueryTargetName(t.type)
        else -> null
    }

    fun resolveConstEnumMemberAccess(
        enumName: String,
        memberName: String,
        sourceFileName: String,
    ): ConstantValue? {
        val result = fileResults[sourceFileName] ?: return null
        val direct = resolveNamePath(enumName, result)?.let { resolveAlias(it) }
            ?.takeIf { it.flags.hasAny(SymbolFlags.ConstEnum) }
        // EP.1: fall back to the `export *` chain (barrels) — see the helper.
        val target = direct
            ?: constEnumSymbolThroughStars(enumName, sourceFileName)
            // EP.2g: the root may be a LOCAL binding whose type is the namespace
            // (`declare const t: typeof NS`) — the non-imported form of the same
            // shape, which `resolveNamePath` cannot follow because it walks
            // `exports` only.
            ?: enumName.split(".").let { parts ->
                (result.locals[parts[0]] ?: globals[parts[0]])
                    ?.let { descendToConstEnum(resolveAlias(it), parts, 1) }
            }
            ?: return null
        return enumValues[target.id]?.get(memberName)
    }

    /**
     * Check if a name resolves to a const enum (directly or through alias chains).
     * Used for eliding import aliases to const enums after inlining.
     */
    fun isConstEnumAlias(name: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return false
        val symbol = result.locals[name] ?: globals[name]
        if (symbol != null && resolveAlias(symbol).flags.hasAny(SymbolFlags.ConstEnum)) return true
        // EP.1 (round 669): the alias may reach the const enum only through an
        // `export *` barrel, which resolveAlias cannot follow — without this the
        // import of a barrel-reached const enum is not elided after inlining.
        return constEnumSymbolThroughStars(name, sourceFileName) != null
    }

    /**
     * Check if a name resolves to a numeric enum type.
     * Used for decorator metadata serialization: numeric enums serialize as `Number`.
     * Returns false for string enums, non-enums, or unknown names.
     */
    fun isNumericEnumType(name: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return false
        val symbol = result.locals[name] ?: globals[name] ?: return false
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.Enum)) return false
        // A numeric enum has all NumberValue (or no values computed, which means all auto-number)
        val values = enumValues[target.id] ?: return true // no values means all auto-numeric
        return values.values.none { it is ConstantValue.StringValue }
    }

    /**
     * Check if a name resolves to a class symbol (directly or through alias chains).
     * Used for decorator metadata: type-only class imports serialize as `Function`.
     */
    fun isClassType(name: String, sourceFileName: String): Boolean {
        val result = fileResults[sourceFileName] ?: return false
        val symbol = result.locals[name] ?: globals[name] ?: return false
        val target = resolveAlias(symbol)
        return target.flags.hasAny(SymbolFlags.Class)
    }

    /**
     * Returns true if [name] is exported from [moduleSpecifier] ONLY via `export type { Name }`
     * (i.e., the export declaration has `isTypeOnly = true`). This indicates the import is effectively
     * type-only even without an explicit `import type { ... }`.
     */
    fun isTypeOnlyExportName(name: String, moduleSpecifier: String, sourceFileName: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return false
        val targetResult = fileResults[targetFile] ?: return false
        // Scan export declarations in the target file to find if `name` is exported type-only
        var hasTypeOnlyExport = false
        var hasValueExport = false
        for (stmt in targetResult.sourceFile.statements) {
            if (stmt !is ExportDeclaration) continue
            val clause = stmt.exportClause as? NamedExports ?: continue
            for (spec in clause.elements) {
                val exportedName = spec.name.text
                if (exportedName != name) continue
                if (stmt.isTypeOnly || spec.isTypeOnly) {
                    hasTypeOnlyExport = true
                } else {
                    hasValueExport = true
                }
            }
        }
        // Only type-only if exported via `export type { X }` and NOT also via plain `export { X }`
        return hasTypeOnlyExport && !hasValueExport
    }

    /**
     * Resolve an enum member value through import aliases.
     * Works for both const and non-const enums. Returns the numeric value or null.
     */
    fun resolveEnumMemberValue(
        enumName: String,
        memberName: String,
        sourceFileName: String,
    ): Long? {
        val result = fileResults[sourceFileName] ?: return null
        val symbol = resolveNamePath(enumName, result) ?: return null
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.Enum)) return null
        val value = enumValues[target.id]?.get(memberName)
        return when (value) {
            is ConstantValue.NumberValue -> value.value.toLong()
            else -> null
        }
    }

    /**
     * Resolve a bare identifier `name` to its literal constant value, walking through
     * `import { name } from "..."` aliases to find the underlying `const name = <literal>`
     * declaration in another file. Used by the Transformer's enum-value compute path to
     * inline cross-file imported literal consts into enum member emit (TypeScript's
     * behavior for `enum E { a = bar }` where `bar` is an imported literal-typed const).
     *
     * Only recognizes top-level `const X = <stringLiteral|numericLiteral>` declarations in
     * the target file. Negative numeric literals (`-1`) and parenthesized literals are
     * unwrapped. Returns null for everything else (function calls, non-const, computed init,
     * type-only imports, etc.).
     */
    fun resolveImportedConstLiteralValue(
        name: String,
        sourceFileName: String,
    ): ConstantValue? {
        val result = fileResults[sourceFileName] ?: return null
        // B162: a script (non-module) file also sees top-level consts of OTHER script files
        // unqualified (shared global scope) — fall back to a cross-file script-global scan.
        val symbol = result.locals[name]
            ?: return resolveScriptGlobalConstLiteral(name, sourceFileName)
        val target = resolveAlias(symbol)
        for (decl in target.declarations) {
            if (decl !is VariableDeclaration) continue
            val parent = findContainingVariableStatement(decl, target) ?: continue
            if (parent.declarationList.flags != ConstKeyword) continue
            val init = decl.initializer ?: continue
            val value = literalConstantValue(init)
            if (value != null) return value
        }
        return null
    }

    /**
     * B162: for a top-level enum [enumName] in the SCRIPT (non-module) file [sourceFileName],
     * return (numericValues, memberNames) contributed by same-named top-level enums in
     * PRECEDING script files (binderResults order = emit/runtime order). Script-file enums
     * with the same name merge via the global scope, so a member declared in an earlier
     * file is in scope unqualified — and its IIFE has already run. Values come from the
     * checker's merged-symbol [enumValues]. Used by the Transformer's `transformEnum` to
     * seed cross-file member values (`enum Enum { E = A }` folds to A's value).
     */
    fun precedingScriptEnumNumericValues(
        enumName: String,
        sourceFileName: String,
    ): Pair<Map<String, Long>, Set<String>> {
        val empty = emptyMap<String, Long>() to emptySet<String>()
        val result = fileResults[sourceFileName] ?: return empty
        if (isModuleFile(result.sourceFile.statements)) return empty
        val memberFiles = scriptEnumMembersByName()[enumName] ?: return empty
        val preceding = mutableSetOf<String>()
        for (br in binderResults) {
            if (br.sourceFile.fileName == sourceFileName) break
            preceding.add(br.sourceFile.fileName)
        }
        if (preceding.isEmpty()) return empty
        val mergedSym = globals[enumName]?.takeIf { it.flags.hasAny(SymbolFlags.Enum) }
        val vals = mergedSym?.let { enumValues[it.id] } ?: emptyMap()
        val numeric = mutableMapOf<String, Long>()
        val names = mutableSetOf<String>()
        for ((member, files) in memberFiles) {
            if (files.none { it in preceding }) continue
            names.add(member)
            val v = vals[member] as? ConstantValue.NumberValue ?: continue
            numeric[member] = v.value.toLong()
        }
        return numeric to names
    }

    /**
     * B162: enumName -> memberName -> set of script files declaring it, over top-level
     * EnumDeclarations in NON-module, non-.d.ts files. See field doc on [scriptEnumMembersCache].
     */
    private fun scriptEnumMembersByName(): Map<String, Map<String, Set<String>>> {
        scriptEnumMembersCache?.let { return it }
        val map = mutableMapOf<String, MutableMap<String, MutableSet<String>>>()
        for (br in binderResults) {
            val fn = br.sourceFile.fileName
            if (isDtsFile(fn)) continue
            if (isModuleFile(br.sourceFile.statements)) continue
            for (stmt in br.sourceFile.statements) {
                if (stmt !is EnumDeclaration) continue
                val members = map.getOrPut(stmt.name.text) { mutableMapOf() }
                for (m in stmt.members) {
                    val mn = when (val n = m.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> null
                    } ?: continue
                    members.getOrPut(mn) { mutableSetOf() }.add(fn)
                }
            }
        }
        scriptEnumMembersCache = map
        return map
    }

    /**
     * B162: resolve a bare identifier to a top-level `const X = <literal>` declared in a
     * DIFFERENT script (non-module) file — script-file globals share one scope, so the name
     * is visible unqualified. Fallback for [resolveImportedConstLiteralValue], which only
     * consults the current file's locals (covering same-file consts and import aliases).
     * Returns null when the current file has ANY local binding for the name (shadow), or
     * when either side is a module file.
     */
    private fun resolveScriptGlobalConstLiteral(name: String, sourceFileName: String): ConstantValue? {
        val result = fileResults[sourceFileName] ?: return null
        if (result.locals[name] != null) return null
        if (isModuleFile(result.sourceFile.statements)) return null
        for (br in binderResults) {
            if (br.sourceFile.fileName == sourceFileName) continue
            if (isDtsFile(br.sourceFile.fileName)) continue
            if (isModuleFile(br.sourceFile.statements)) continue
            for (stmt in br.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                if (stmt.declarationList.flags != ConstKeyword) continue
                for (d in stmt.declarationList.declarations) {
                    val dn = (d.name as? Identifier)?.text ?: continue
                    if (dn != name) continue
                    val init = d.initializer ?: continue
                    literalConstantValue(init)?.let { return it }
                }
            }
        }
        return null
    }

    private fun findContainingVariableStatement(
        decl: VariableDeclaration,
        symbol: Symbol,
    ): VariableStatement? {
        // Walk all binder results' source files and look for a top-level VariableStatement
        // whose declarationList.declarations contains `decl`. Symbol-declarations are stored
        // without parent pointers, so a small scan is the simplest path.
        for (br in binderResults) {
            for (stmt in br.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                if (decl in stmt.declarationList.declarations) return stmt
            }
        }
        return null
    }

    private fun literalConstantValue(expr: Expression): ConstantValue? = when (expr) {
        is StringLiteralNode -> ConstantValue.StringValue(expr.text)
        is NoSubstitutionTemplateLiteralNode -> ConstantValue.StringValue(expr.text)
        is NumericLiteralNode -> tsNumericLiteralToDouble(expr.text)?.let { ConstantValue.NumberValue(it) }
        is PrefixUnaryExpression -> {
            val inner = (expr.operand as? NumericLiteralNode)?.text?.let { tsNumericLiteralToDouble(it) }
            when {
                inner == null -> null
                expr.operator == SyntaxKind.Minus -> ConstantValue.NumberValue(-inner)
                expr.operator == SyntaxKind.Plus -> ConstantValue.NumberValue(inner)
                else -> null
            }
        }
        is ParenthesizedExpression -> literalConstantValue(expr.expression)
        else -> null
    }

    /**
     * Get the module instance state for a module/namespace declaration.
     */
    fun getModuleInstanceState(node: ModuleDeclaration): ModuleInstanceState {
        val key = nodeKey(node)
        for (result in binderResults) {
            val state = result.moduleInstanceStates[key]
            if (state != null) return state
        }
        return ModuleInstanceState.Instantiated // safe default
    }

    /**
     * Returns true if [name] is declared as a plain `var` in any file that comes
     * BEFORE [currentFileName] in the compilation order.
     *
     * Used in script-mode (non-module) files to decide whether to erase `import x = NS`
     * when NS is a non-instantiated namespace: if an earlier file already declares `x`
     * as a plain var, the import alias in the current file is redundant and should be erased.
     */
    fun hasVarDeclarationInEarlierFile(name: String, currentFileName: String): Boolean {
        val currentIdx = binderResults.indexOfFirst { it.sourceFile.fileName == currentFileName }
        if (currentIdx <= 0) return false
        for (i in 0 until currentIdx) {
            val result = binderResults[i]
            val symbol = result.locals[name] ?: continue
            for (decl in symbol.declarations) {
                if (decl is VariableDeclaration) return true
            }
        }
        return false
    }

    /**
     * Returns true if a plain `var` declaration for [name] exists in any file that comes
     * AFTER [currentFileName] in the compilation order.
     *
     * Used symmetrically with [hasVarDeclarationInEarlierFile]: when a later file will declare
     * `var x`, the current file's `import x = NS` must be kept so that the merged var binding
     * is observable at runtime (`var x = NS` in current + `var x` in later = two var declarations
     * for the same name, which is legal in script mode).
     */
    fun hasVarDeclarationInLaterFile(name: String, currentFileName: String): Boolean {
        val currentIdx = binderResults.indexOfFirst { it.sourceFile.fileName == currentFileName }
        if (currentIdx < 0) return false
        for (i in currentIdx + 1 until binderResults.size) {
            val result = binderResults[i]
            val symbol = result.locals[name] ?: continue
            for (decl in symbol.declarations) {
                if (decl is VariableDeclaration) return true
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // Symbol table merging
    // -----------------------------------------------------------------------

    private fun mergeSymbolTable(target: SymbolTable, source: SymbolTable) {
        for ((name, symbol) in source) {
            mergeSingleSymbol(target, name, symbol)
        }
    }

    /**
     * (PERF.HW.k) tsc's `cloneSymbol`: a CHECKER-OWNED copy of a binder symbol, so
     * the merge can write to the copy and leave the original pristine.
     *
     * **The id is DELIBERATELY carried over rather than freshly allocated.** A new
     * id would shift the whole subsequent sequence, and CLAUDE.md records that
     * id-allocation drift reshuffles ~350 boundary tests — a blast radius wildly
     * out of proportion to this change. Carrying it means the clone and the
     * original are the SAME logical symbol to every id-keyed cache, which is
     * exactly the identity tsc maintains through its `mergedSymbols` forwarding
     * table. It is also why we need no such table: an id-keyed reader cannot tell
     * the two apart, and a name-keyed reader gets the clone because the clone is
     * what the merge writes back.
     *
     * `members`/`exports` are copied as MAPS (tsc does the same) — otherwise the
     * clone would share the original's tables and merging into them would mutate
     * binder state through the back door. The symbols INSIDE those maps stay
     * shared, and are themselves copied on their own first mutation by the
     * recursive `mergeSymbolTable` below.
     */
    private fun cloneSymbolForMerge(symbol: Symbol): Symbol {
        val clone = Symbol(symbol.flags, symbol.name, symbol.id)
        clone.transient = true
        clone.declarations.addAll(symbol.declarations)
        clone.valueDeclaration = symbol.valueDeclaration
        clone.parent = symbol.parent
        clone.target = symbol.target
        symbol.members?.let { clone.members = symbolTable().apply { putAll(it) } }
        symbol.exports?.let { clone.exports = symbolTable().apply { putAll(it) } }
        // tsc's `recordMergedSymbol`: every later reader that still holds the
        // ORIGINAL must be able to find this copy.
        mergedSymbols[symbol.id] = clone
        return clone
    }

    /**
     * (PERF.HW.k) tsc's / tsgo's `getMergedSymbol`: the merged view of a symbol.
     *
     * Readers reach symbols through tables the merge does not rewrite —
     * `BinderResult.locals`, `nodeToSymbol`, a cached lib table — and those still
     * hold the pristine binder object. Without this hop they see the un-merged
     * declarations, which is exactly what the corpus caught: `extendGenericArray`
     * (a user `interface Array<T>` merging into the lib's) lost its diagnostic
     * because the type was built from the original symbol's declarations.
     */
    private fun getMergedSymbol(symbol: Symbol): Symbol =
        if (mergedSymbols.entryCount == 0) symbol else mergedSymbols[symbol.id] ?: symbol

    private fun mergeSingleSymbol(target: SymbolTable, name: String, symbol: Symbol) {
        val existing = target[name]
        if (existing != null) {
            if (MergeCensus.enabled) {
                FrontEnd.mergeMutates++
                if (existing.id in mergeAdoptedSymbolIds) FrontEnd.mergeMutatesAdopted++
                FrontEnd.mergeDeclarationsAppended += symbol.declarations.size.toLong()
            }
            // (PERF.HW.k) COPY-ON-WRITE, exactly tsc's shape: a non-transient
            // target is binder-owned, so clone it, mutate the clone, and write the
            // clone back into the table (tsc's `target.set(id, merged)`). Every
            // later merge on this name finds a transient symbol and mutates in
            // place, so at most ONE copy is made per merged name.
            val merged =
                if (MergeClone.enabled && !existing.transient) {
                    cloneSymbolForMerge(existing).also { target[name] = it }
                } else existing
            // Merge: combine flags and declarations
            merged.flags = merged.flags or symbol.flags
            merged.declarations.addAll(symbol.declarations)
            if (merged.valueDeclaration == null && symbol.valueDeclaration != null) {
                merged.valueDeclaration = symbol.valueDeclaration
            }
            // Merge enum exports
            if (symbol.exports != null) {
                if (merged.exports == null) merged.exports = symbolTable()
                mergeSymbolTable(merged.exports!!, symbol.exports!!)
            }
        } else {
            if (MergeCensus.enabled) {
                FrontEnd.mergeAdopts++
                mergeAdoptedSymbolIds.add(symbol.id)
            }
            target[name] = symbol
        }
    }

    /**
     * INV.3(d): does a MODULE file's top-level local deliberately contribute to
     * the GLOBAL namespace (and therefore keep merging into [globals] after the
     * Blocker-#3 conflation retirement)? True for:
     *  - the `declare global { … }` namespace binding (named `global` — its
     *    exports are genuine global augmentations in tsc);
     *  - an `export as namespace X` UMD namespace (the parser misparses the
     *    construct into a `namespace X` ModuleDeclaration; [umdGlobalNames] is
     *    regex-collected BEFORE the merge);
     *  - any symbol declaring an ambient `declare module "spec"` (StringLiteral
     *    name) — both standalone ambient-module definitions and augmentation
     *    carriers; [mergeModuleAugmentations] resolves them via
     *    `globals[specifier]`.
     * Everything else is module-scoped in real tsc: visible only to the file
     * itself and its importers, served by [lookupPerFile]/[globalsForFile].
     */
    private fun moduleLocalContributesGlobally(name: String, symbol: Symbol): Boolean {
        if (name == "global") return true
        if (name in umdGlobalNames) return true
        if (name in mergeSharedKeepNames) return true
        return symbol.declarations.any { it is ModuleDeclaration && it.name is StringLiteralNode }
    }

    /**
     * Merge module augmentation exports into target module symbols.
     *
     * When `declare module "./foo" { namespace Bar { ... } }` augments a file-based module,
     * the binder creates a module symbol keyed by the specifier string (e.g., "./foo") in
     * globals. The actual target symbols (e.g., class Bar) are in globals under their own
     * names. This method resolves the augmentation specifiers and merges augmented exports
     * (namespaces, interfaces, etc.) into the corresponding global symbols.
     */
    /**
     * (CHK.50) Merge every LEGAL `declare global { … }` block's exports into
     * [globals].
     *
     * **The carrier merged and the contents did not.** `declare global` parses
     * as a `ModuleDeclaration` whose name is the Identifier `global`, so step 1
     * ([moduleLocalContributesGlobally] answers true for that name) merged the
     * CARRIER symbol into [globals] under the key `global` — and nothing ever
     * merged its `exports`, which is where every augmented name lives. Measured
     * on the (CHK.49) parent: of the eight declaration forms only `var` was
     * observable at all, and only in the DECLARING file (ordinary file-local
     * resolution); cross-file even that was silent. `function`, `namespace` and
     * `class` typed as `any` — suppressed out of TS2304 by
     * [globalAugmentationNames] and typed by nothing — while `interface`,
     * `type` and `enum` were TS2304 outright and an `interface Date { … }`
     * augmentation reported TS2339 on the member it had just declared.
     *
     * **Legality is POSITIVE EVIDENCE, not a name test.** A `global` block is an
     * augmentation only where TS2669 does not fire, which
     * [spineCheckGlobalAugmentation] states as: every ancestor is a
     * ModuleBlock/ModuleDeclaration, no ancestor is a regular (identifier-named,
     * non-`global`) namespace, and either the FILE is an external module or some
     * ancestor is a string-literal-named ambient module. This walk mirrors that
     * exactly by descending only through ambient-module bodies, so a
     * top-level `declare global` in a global SCRIPT contributes nothing — which
     * is what tsgo 7.0.2 does too (its names stay TS2304 there). The
     * declaration-identity test (`it === stmt`) is the second half of the
     * evidence: a module's own `const global = …` reaches this scope under the
     * same key and must not have its members published globally.
     *
     * **Each carrier is merged ONCE.** `mergeSingleSymbol` does
     * `declarations.addAll` with no membership test, and several `declare
     * global` blocks in one file share ONE `global` symbol — so a per-BLOCK
     * merge would append each augmented declaration as many times as the file
     * has blocks. Dedupe is by symbol id.
     */
    private fun mergeGlobalAugmentations() {
        val seen = HashSet<Int>()
        val carriers = ArrayList<Symbol>()
        for (result in binderResults) {
            collectGlobalAugmentationCarriers(
                result.sourceFile.statements,
                result.locals,
                fileIsModule = isModuleFile(result.sourceFile.statements),
                insideAmbientModule = false,
                seen = seen,
                out = carriers,
            )
        }
        for (carrier in carriers) {
            val exports = carrier.exports ?: continue
            for ((name, exported) in exports) {
                // `namespace globalThis { … }` is not a namespace DECLARATION at all —
                // it is tsc's syntax for augmenting the GLOBAL SCOPE ITSELF, so its
                // members become bare globals and `globalThis` never becomes an ordinary
                // symbol. Publishing it as one makes `globalThis.<anything undeclared>`
                // a TS2339, which pristine tsc does not report (`extendGlobalThis`).
                // Modelling the real semantics is queued as (CHK.53); refusing here
                // leaves that shape exactly where (CHK.50) found it.
                if (name == "globalThis") continue
                val adopted = globals[name] == null
                mergeSingleSymbol(globals, name, exported)
                if (adopted) globals[name]?.let { globalAugmentationAddedSymbols[name] = it }
            }
        }
    }

    /**
     * (CHK.50) The walk behind [mergeGlobalAugmentations] — see its KDoc for why
     * the descent is restricted to ambient-module bodies.
     */
    private fun collectGlobalAugmentationCarriers(
        statements: List<Statement>,
        scope: SymbolTable,
        fileIsModule: Boolean,
        insideAmbientModule: Boolean,
        seen: MutableSet<Int>,
        out: MutableList<Symbol>,
    ) {
        for (stmt in statements) {
            if (stmt !is ModuleDeclaration) continue
            when (val nameNode = stmt.name) {
                is Identifier -> {
                    // A `global` block nested in a REGULAR namespace is TS2669 and
                    // augments nothing, so a non-`global` identifier name is not
                    // descended into at all.
                    if (nameNode.text != "global") continue
                    if (!fileIsModule && !insideAmbientModule) continue
                    val carrier = scope["global"] ?: continue
                    if (carrier.declarations.none { it === stmt }) continue
                    if (seen.add(carrier.id)) out.add(carrier)
                }
                is StringLiteralNode -> {
                    val body = stmt.body as? ModuleBlock ?: continue
                    val inner = scope[nameNode.text]?.exports ?: continue
                    collectGlobalAugmentationCarriers(
                        body.statements, inner, fileIsModule,
                        insideAmbientModule = true, seen = seen, out = out,
                    )
                }
                else -> {}
            }
        }
    }

    private fun mergeModuleAugmentations() {
        val processedSpecifiers = mutableSetOf<String>()
        for (result in binderResults) {
            collectModuleAugmentations(
                result.sourceFile.statements, processedSpecifiers, null,
                result.sourceFile.fileName,
            )
        }
    }

    private fun collectModuleAugmentations(
        statements: List<Statement>,
        processedSpecifiers: MutableSet<String>,
        parentLookupScope: SymbolTable?,
        declaringFileName: String,
    ) {
        for (stmt in statements) {
            if (stmt !is ModuleDeclaration) continue
            val name = stmt.name as? StringLiteralNode ?: continue
            val specifier = name.text

            // 16.4: Inner-module augmentations like `declare module "D" { module "a" { interface A { ... } } }`
            // are NOT in `globals` — the binder declares "a" inside "D".exports (per bindModuleDeclaration's
            // nested scope semantics). When recursing into the body of an outer ambient module, pass that
            // module's exports as the lookup scope so the inner `module "a"` symbol can be found.
            val body = stmt.body
            val outerModuleSymbol = parentLookupScope?.get(specifier) ?: globals[specifier]
            if (body is ModuleBlock) {
                // Use this module's exports as the lookup scope for nested module decls inside body
                val thisModuleExports = outerModuleSymbol?.exports
                collectModuleAugmentations(body.statements, processedSpecifiers, thisModuleExports, declaringFileName)
            }

            if (!processedSpecifiers.add(specifier)) continue

            // Find the augmentation module symbol — check parent scope first (for nested),
            // then fall back to globals (for top-level `declare module "X"`)
            val augModule = outerModuleSymbol ?: continue
            val augExports = augModule.exports ?: continue

            // Resolve the specifier to a target file. INV.3(d): an ESM-`.js` relative
            // augmentation target (`declare module "../compiler/types.js"`) resolves
            // via the .js-aware wrapper (the round-443 rule — the base resolver
            // deliberately won't strip the extension), so the target-locals merge
            // below fires for it and the exports stay module-scoped per-file.
            val targetFile = resolveModuleSpecifier(specifier, stmt)
                ?: resolveModuleSpecifierRelativeJsAware(specifier, declaringFileName)

            // 17.130: TypeScript distinguishes "global augmentations" (no top-level export
            // statements inside the augmentation body — declarations implicitly merge) from
            // true "module augmentations" (has export statement — declarations must carry an
            // explicit `export` modifier to merge with the target module's exports). When the
            // body has top-level export statements, filter `augExports` to symbols whose
            // declarations are explicitly exported. import statements alone don't trigger
            // the strict mode (verified against `moduleAugmentationImportsAndExports3` baseline:
            // import-only augmentation still implicitly merges all declarations).
            val augHasModuleSyntax = if (body is ModuleBlock) {
                body.statements.any {
                    it is ExportDeclaration || it is ExportAssignment
                }
            } else false

            fun shouldAugmentSymbol(augSymbol: Symbol): Boolean {
                if (!augHasModuleSyntax) return true
                // Has module-syntax: only declarations with `export` modifier augment.
                // Detected via `ExportValue` flag (set by the binder when `Export` modifier
                // is present on the declaration). Aliases without module-export propagation
                // (`import X = require`, plain `import {X}`, `export {X} from`) are skipped.
                if (augSymbol.flags.hasAny(SymbolFlags.ExportValue)) return true
                // Nested string-literal module declarations augment globally without requiring
                // `export` — `declare module "Outer" { module "Target" { interface T { foo() } } }`
                // augments globals["Target"] via the outer merge, regardless of `export` on the
                // inner `module "Target"`. The binder doesn't set ExportValue on these without
                // an explicit `export`, but they're still augmenting symbols.
                val firstDecl = augSymbol.declarations.firstOrNull()
                if (firstDecl is ModuleDeclaration && firstDecl.name is StringLiteralNode) return true
                return false
            }

            // Merge each augmented export into the corresponding global symbol.
            val declaringFileIsModule = declaringFileName in moduleFiles
            for ((exportName, augSymbol) in augExports) {
                if (!shouldAugmentSymbol(augSymbol)) continue
                val globalSymbol = globals[exportName]
                if (globalSymbol != null) {
                    if (augSymbol.exports != null) {
                        if (globalSymbol.exports == null) globalSymbol.exports = symbolTable()
                        mergeSymbolTable(globalSymbol.exports!!, augSymbol.exports!!)
                        globalSymbol.flags = globalSymbol.flags or (augSymbol.flags and SymbolFlags.Module)
                    }
                    if (augSymbol.declarations.isNotEmpty()) {
                        for (decl in augSymbol.declarations) {
                            if (decl !in globalSymbol.declarations) {
                                globalSymbol.declarations.add(decl)
                            }
                        }
                    }
                } else if (targetFile == null && declaringFileIsModule) {
                    // New export not yet in globals — add it. INV.3(d): ONLY for an
                    // AMBIENT (fileless) augmentation target — `globals` is its sole
                    // visibility channel. A FILE-module augmentation's exports are
                    // module-scoped: the target-locals merge below carries them
                    // per-file; adding them here would resurrect the retired
                    // conflation as an AUGMENTATION-ONLY stub that the 1b visibility
                    // delta then marks non-module-only, making every annotation of
                    // that name resolve to the stub (the services-profile
                    // SourceFile/Node TS2339×5355 flood, round 510).
                    // M4.9: and only from a file that is itself an external MODULE, i.e.
                    // a genuine AUGMENTATION. The same syntax in a script `.d.ts`
                    // DECLARES the ambient module (`@types/node`'s
                    // `declare module "fs" { export interface WatchOptions … }`), whose
                    // members are reachable only through an import of "fs" — publishing
                    // those into `globals` made them outrank a file's own import alias
                    // of the same name (the compiler's own `WatchOptions` lost to
                    // node's `fs.WatchOptions`).
                    globals[exportName] = augSymbol
                }
            }

            // Also merge augmented exports into the target file's binder result locals.
            // EXCEPT: a BARE (non-relative) ambient `declare module "X"` whose name merely
            // coincides with a sibling SOURCE file's basename is a STANDALONE ambient module, NOT
            // an augmentation of that source module (tsc never augments a relatively-resolvable
            // .ts/.tsx source via a bare ambient name — only .d.ts ambient files / node_modules
            // packages). Skipping the locals merge keeps the real source module's exports intact so
            // a missing member fires TS2339 (externalModuleRefernceResolutionOrderInImportDeclaration).
            // Relative augmentations (`declare module "./foo"`) are unaffected.
            val specifierIsRelative = specifier.startsWith("./") || specifier.startsWith("../")
            val targetIsPlainSource = targetFile != null &&
                (targetFile.endsWith(".ts") || targetFile.endsWith(".tsx")) &&
                !targetFile.endsWith(".d.ts") && "node_modules" !in targetFile
            if (targetFile != null && !(targetIsPlainSource && !specifierIsRelative)) {
                val targetResult = fileResults[targetFile]
                if (targetResult != null) {
                    for ((exportName, augSymbol) in augExports) {
                        if (!shouldAugmentSymbol(augSymbol)) continue
                        val localSymbol = targetResult.locals[exportName]
                        if (localSymbol != null) {
                            if (augSymbol.exports != null) {
                                if (localSymbol.exports == null) localSymbol.exports = symbolTable()
                                mergeSymbolTable(localSymbol.exports!!, augSymbol.exports!!)
                                localSymbol.flags = localSymbol.flags or (augSymbol.flags and SymbolFlags.Module)
                            }
                            if (augSymbol.declarations.isNotEmpty()) {
                                for (decl in augSymbol.declarations) {
                                    if (decl !in localSymbol.declarations) {
                                        localSymbol.declarations.add(decl)
                                    }
                                }
                            }
                        } else {
                            // New export — add to target file's locals
                            targetResult.locals[exportName] = augSymbol
                        }
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Enum value computation
    // -----------------------------------------------------------------------

    /**
     * (REL.1)(c) step 4 — the program-wide set of simple names that the INV.2(c)
     * lexical pass bound as an ENUM in SCOPE space (id <= -2), i.e. an `enum`
     * declared inside a function/arrow/block body, which the main binder never
     * bound (B83.5). Empty for almost every program, which is what keeps
     * [lexicalTypeSymbolForNode]'s consult free on the hot type-reference path:
     * one HashSet probe before any ancestor walk. Populated by
     * [computeAllEnumValues], so it is complete before the first check runs.
     */
    private var lexicalBlockScopedEnumNames: Set<String> = emptySet()

    /** (CHK.19) round 945 — the gate for [lexicalTypeAliasArity]; see [lexicalBlockScopedEnumNames]. */
    private var lexicalBlockScopedTypeAliasNames: Set<String> = emptySet()

    /**
     * (REL.1)(c) step 4: the position-aware TYPE-space consult for a
     * function-body-scoped `enum`. Walks the node's ancestor chain outward over the
     * INV.2(c) `lexicalScopes` table of the node's OWNING file and returns the first
     * SCOPE-SPACE enum symbol of [name].
     *
     * **This is a resolution-ORDER change, not a fallback, and it cannot be written
     * as one** — of the two B83.5 failure modes only the first is a miss: a UNIQUE
     * name resolved to nothing (annotation → `any`, every check silent, and no TS2304
     * because the INV.4(c)(iii) family finds the name through these same lexical
     * scopes, which this resolver did not consult), while a name SHADOWING an outer
     * one resolved to the OUTER symbol, which is a wrong answer with nothing to
     * detect.
     *
     * SCOPE-SPACE ONLY (`scope.symbols`, never [LexicalScope.existing]) is what makes
     * it containable: `declareLexical` skips any name the main binder already bound in
     * that container, so a conventionally-bound name is absent from `symbols`
     * everywhere and keeps resolving exactly as before. That also gives the shadowing
     * rule for free — a scope-space binding exists only where the main binder had
     * none, so the innermost-first walk reaches the inner `enum DC` before the file
     * root's aliased locals ever offer the module-scoped one.
     */
    private fun lexicalTypeSymbolForNode(node: Node, name: String): Symbol? {
        if (name !in lexicalBlockScopedEnumNames) return null
        val owner = owningSourceFile(node) ?: return null
        val scopes = fileResults[owner.fileName]?.lexicalScopes ?: return null
        if (scopes.isEmpty()) return null
        var cur: Node? = node
        var hops = 0
        while (cur != null && hops++ < 4096) {
            val id = (cur as NodeBase).nodeId
            if (id >= 0) {
                val sym = scopes[id]?.symbols?.get(name)
                if (sym != null && sym.flags.hasAny(SymbolFlags.Enum)) return sym
            }
            if (cur is SourceFile) break
            cur = cur.parent
        }
        return null
    }

    /**
     * (CHK.19) round 945 — the arity of a BLOCK-SCOPED type alias that shadows an outer
     * (usually LIB) one, or null when no such declaration is visible from [node].
     *
     * CLAUDE.md's B83.5: `Binder.bindStatement` never binds a declaration nested inside a
     * function body / block, so `function f() { type Omit<T> = ... }` is in no `locals` table
     * and [getTypeParamInfo] — a whole-program, NAME-keyed scan — answers with the lib's
     * two-parameter `Omit`, i.e. `Generic type 'Omit' requires 2 type argument(s)` for a
     * one-argument use that pristine accepts. **In TYPE position that failure is silent for a
     * UNIQUE name (it degrades to `any`) and WRONG for a SHADOWING one**, which is why only the
     * shadowing half is a diagnostic at all.
     *
     * This is round 748's `lexicalTypeSymbolForNode` shape, one declaration kind over, and it
     * inherits that round's two invariants: the walk reads `scope.symbols` ONLY, never
     * `LexicalScope.existing` (which ALIASES the main binder's table, so reading it would put
     * every INV.3 name back in play), and a name gate computed once keeps the hot type-reference
     * path at a single set probe. Because `declareLexical` skips any name the main binder
     * already bound in that container, a scope-space hit can only be a declaration the
     * conventional tables do NOT have — so this cannot change how any bound name resolves.
     */
    private fun lexicalTypeAliasArity(node: Node, name: String): TypeParamInfo? {
        if (name !in lexicalBlockScopedTypeAliasNames) return null
        val owner = owningSourceFile(node) ?: return null
        val scopes = fileResults[owner.fileName]?.lexicalScopes ?: return null
        if (scopes.isEmpty()) return null
        var cur: Node? = node
        var hops = 0
        while (cur != null && hops++ < 4096) {
            val id = (cur as NodeBase).nodeId
            if (id >= 0) {
                val sym = scopes[id]?.symbols?.get(name)
                if (sym != null && sym.flags.hasAny(SymbolFlags.TypeAlias)) {
                    val decl = sym.declarations.firstOrNull { it is TypeAliasDeclaration }
                        as? TypeAliasDeclaration ?: return null
                    val tps = decl.typeParameters.orEmpty()
                    return TypeParamInfo(
                        minRequired = tps.count { it.default == null },
                        maxTotal = tps.size,
                        displayName = name,
                    )
                }
            }
            if (cur is SourceFile) break
            cur = cur.parent
        }
        return null
    }

    private fun computeAllEnumValues() {
        // (REL.1)(c) step 4: scope-space enums first — a function-body-scoped enum is
        // invisible to the `result.locals` + namespace-exports walk below, so its
        // values were never computed and [lexicalTypeSymbolForNode] would hand the
        // relation a value-less enum. `computeEnumSymbolValues` is id-keyed and
        // scope-symbol ids are a disjoint negative space, so this cannot perturb any
        // conventionally-bound enum's values.
        LexDefer.skippedFiles = 0
        LexDefer.skipViolations = 0
        val blockScoped = HashSet<String>()
        // (CHK.19) round 945: the block-scoped TYPE-ALIAS census rides this SAME sweep — a
        // second pass over every scope of every file would be the identical walk for one more
        // flag test, and this set is what keeps [lexicalTypeAliasArity]'s consult a single
        // probe on the hot type-reference path.
        val blockScopedAliases = HashSet<String>()
        for (result in binderResults) {
            // (INC.16) THE ONE READER THAT FORCED EVERY FILE'S INV.2(c) TABLES, served
            // by a PROJECTION instead. `declareLexical` mints a `TypeAlias`- or
            // `Enum`-flagged scope symbol at exactly two sites — the `TypeAliasDeclaration`
            // and `EnumDeclaration` arms of `bindLexicalScopes` — and both are gated on
            // `scope.existing == null`, i.e. on the declaration NOT being one the main
            // binder bound. So the binder can say, from the declarations alone, whether a
            // file can contribute at all — and skipping it leaves its tables UNBUILT.
            //
            // The two halves are NOT symmetric: the alias half wants a NAME, which the
            // binder hands over directly, while the enum half wants the scope-space SYMBOL
            // (`computeEnumSymbolValues` is id-keyed) and that exists only inside the
            // tables. Only an `enum` reaching a fresh scope therefore forces a build —
            // 2 files of tsc's 78.
            //
            // Round 609's rule is untouched: this loop still iterates `binderResults`, not
            // `checkedResults` — the skip is a property of the FILE's own syntax, not of
            // the partition, so a narrowed build and a full one census the same set.
            //
            // The candidate list is stamped by `indexSourceFile` (once per parse, and a
            // parse is content-cached); the namespace case is settled in the binder against
            // its own symbols, because a namespace scope ALIASES the merged `exports` and
            // that is not a syntactic fact. [LexDefer.verifySkip] is the positive control:
            // it keeps walking every file and counts what the skip would have missed.
            blockScopedAliases.addAll(result.scopeTypeAliasNames)
            val skippable = !result.declaresScopeEnum
            if (skippable) {
                LexDefer.skippedFiles++
                if (!LexDefer.verifySkip) continue
            }
            for ((_, scope) in result.lexicalScopes) {
                for ((symName, symbol) in scope.symbols) {
                    if (symbol.flags.hasAny(SymbolFlags.TypeAlias)) {
                        // The alias half is served WITHOUT the tables; under the control
                        // this is where a name the projection missed would show up.
                        if (symName !in result.scopeTypeAliasNames) LexDefer.skipViolations++
                        blockScopedAliases.add(symName)
                    }
                    if (!symbol.flags.hasAny(SymbolFlags.Enum)) continue
                    if (skippable) LexDefer.skipViolations++
                    blockScoped.add(symName)
                    computeEnumSymbolValues(symbol)
                }
            }
        }
        lexicalBlockScopedEnumNames = blockScoped
        lexicalBlockScopedTypeAliasNames = blockScopedAliases
        for (result in binderResults) {
            for ((_, symbol) in result.locals) {
                computeEnumValuesRecursive(symbol)
            }
        }
    }

    private fun computeEnumValuesRecursive(symbol: Symbol) {
        if (symbol.flags.hasAny(SymbolFlags.Enum)) {
            computeEnumSymbolValues(symbol)
        }
        // Recurse into namespace exports to find nested enums
        if (symbol.flags.hasAny(SymbolFlags.Module)) {
            symbol.exports?.values?.forEach { computeEnumValuesRecursive(it) }
        }
    }

    private fun computeEnumSymbolValues(symbol: Symbol) {
        if (enumValues.containsKey(symbol.id)) return
        val values = mutableMapOf<String, ConstantValue>()
        enumValues[symbol.id] = values

        for (decl in symbol.declarations) {
            if (decl !is EnumDeclaration) continue
            var autoValue = 0.0
            for (member in decl.members) {
                val name = when (val n = member.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    is NumericLiteralNode -> n.text
                    else -> continue
                }
                if (member.initializer != null) {
                    val computed = evaluateEnumInitializer(member.initializer, values, symbol)
                    if (computed != null) {
                        values[name] = computed
                        if (computed is ConstantValue.NumberValue) {
                            autoValue = computed.value + 1
                        }
                    } else {
                        // Cannot evaluate — auto-increment is broken
                        autoValue = Double.NaN
                    }
                } else {
                    if (!autoValue.isNaN()) {
                        values[name] = ConstantValue.NumberValue(autoValue)
                        autoValue++
                    }
                }
            }
        }
    }

    /**
     * TS2651: an enum member initializer may not reference an enum member that is
     * declared AFTER it (a forward reference), including members defined in other
     * declaration blocks of the same merged enum. Fires for both `enum` and
     * `const enum`. The members of a merged enum are ordered across all of the enum
     * symbol's declarations (source order). A reference may take the form of a bare
     * member identifier (`Y`), a property access on the enum name (`E.Y`), or an
     * element access with a string-literal key (`E["Y"]`). The squiggle covers the
     * whole reference expression. References to OTHER enums are not flagged (the
     * leftmost name must be this enum's own name, or a bare member name of this enum).
     */
    private fun checkEnumForwardReferences() {
        val orderCache = mutableMapOf<Int, Map<String, Int>>()
        fun memberNameText(node: Node): String? = when (node) {
            is Identifier -> node.text
            is StringLiteralNode -> node.text
            is NumericLiteralNode -> node.text
            else -> null
        }
        // Build (and cache) the merged member-order map for an enum symbol: member
        // name → global index across all of the symbol's EnumDeclarations (source order).
        fun mergedOrder(sym: Symbol): Map<String, Int> = orderCache.getOrPut(sym.id) {
            val order = mutableMapOf<String, Int>()
            var idx = 0
            for (d in sym.declarations) {
                if (d !is EnumDeclaration) continue
                for (m in d.members) {
                    val nm = memberNameText(m.name) ?: continue
                    if (nm !in order) order[nm] = idx
                    idx++
                }
            }
            order
        }

        // Collect (refExpr, referencedMemberName) pairs for references to members of
        // [enumName] reachable within an initializer expression.
        fun collectRefs(
            expr: Expression, enumName: String, memberNames: Set<String>,
            out: MutableList<Pair<Expression, String>>,
        ) {
            when (expr) {
                is Identifier -> if (expr.text in memberNames) out.add(expr to expr.text)
                is PropertyAccessExpression -> {
                    val recv = expr.expression
                    if (recv is Identifier && recv.text == enumName && expr.name.text in memberNames)
                        out.add(expr to expr.name.text)
                }
                is ElementAccessExpression -> {
                    val recv = expr.expression
                    val key = when (val a = expr.argumentExpression) {
                        is StringLiteralNode -> a.text
                        is NoSubstitutionTemplateLiteralNode -> a.text
                        else -> null
                    }
                    if (recv is Identifier && recv.text == enumName && key != null && key in memberNames)
                        out.add(expr to key)
                }
                is BinaryExpression -> {
                    collectRefs(expr.left, enumName, memberNames, out)
                    collectRefs(expr.right, enumName, memberNames, out)
                }
                is PrefixUnaryExpression -> collectRefs(expr.operand, enumName, memberNames, out)
                is PostfixUnaryExpression -> collectRefs(expr.operand, enumName, memberNames, out)
                is ParenthesizedExpression -> collectRefs(expr.expression, enumName, memberNames, out)
                is ConditionalExpression -> {
                    collectRefs(expr.condition, enumName, memberNames, out)
                    collectRefs(expr.whenTrue, enumName, memberNames, out)
                    collectRefs(expr.whenFalse, enumName, memberNames, out)
                }
                else -> {}
            }
        }

        fun checkEnumDecl(enumDecl: EnumDeclaration, sym: Symbol?, source: String, fileName: String) {
            val realSym = sym ?: return
            if (!realSym.flags.hasAny(SymbolFlags.Enum)) return
            val order = mergedOrder(realSym)
            if (order.isEmpty()) return
            val memberNames = order.keys
            for (member in enumDecl.members) {
                val mname = memberNameText(member.name) ?: continue
                val myIdx = order[mname] ?: continue
                val init = member.initializer ?: continue
                val refs = mutableListOf<Pair<Expression, String>>()
                collectRefs(init, enumDecl.name.text, memberNames, refs)
                for ((refExpr, refName) in refs) {
                    val refIdx = order[refName] ?: continue
                    val start = refExpr.pos
                    val length = expressionTrueEnd(refExpr) - start
                    val (line, ch) = getLineAndCharacterOfPosition(source, start)
                    if (refIdx > myIdx) {
                        diagnostics.add(Diagnostic(
                            message = "A member initializer in a enum declaration cannot reference " +
                                "members declared after it, including members defined in other enums.",
                            category = DiagnosticCategory.Error, code = 2651,
                            fileName = fileName, line = line, character = ch,
                            start = start, length = length,
                        ))
                    } else if (refIdx == myIdx) {
                        // B98.r14: an enum member initializer referencing ITSELF (`A = A`,
                        // `B = E.B`, `C = E["C"]`, `D = 1 + D`) is a use-before-assignment → TS2565.
                        diagnostics.add(Diagnostic(
                            message = "Property '$refName' is used before being assigned.",
                            category = DiagnosticCategory.Error, code = 2565,
                            fileName = fileName, line = line, character = ch,
                            start = start, length = length,
                        ))
                    }
                }
            }
        }

        // Walk top-level + namespace-nested enum declarations in each file.
        fun walk(statements: List<Statement>, localsLookup: (String) -> Symbol?, source: String, fileName: String) {
            for (stmt in statements) {
                when (stmt) {
                    is EnumDeclaration -> checkEnumDecl(stmt, localsLookup(stmt.name.text), source, fileName)
                    is ModuleDeclaration -> {
                        val body = stmt.body as? ModuleBlock ?: continue
                        val nsSym = localsLookup((stmt.name as? Identifier)?.text ?: "")
                        val inner: (String) -> Symbol? = { nm -> nsSym?.exports?.get(nm) }
                        walk(body.statements, inner, source, fileName)
                    }
                    else -> {}
                }
            }
        }

        for (result in checkedResults) {
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            walk(result.sourceFile.statements, { nm -> result.locals[nm] ?: globals[nm] }, source, fileName)
        }
    }

    /**
     * Const-enum diagnostic cluster (constEnumErrors), all AST/constant-eval — no
     * relation engine. Six checks, gated tightly to const enums (rare shape):
     *  - TS2474: a const enum member initializer that is not a constant expression
     *    (references a NON-existent member via `E.X`/`E["X"]`). Distinct from a
     *    forward-reference to an existing-but-later member (that is TS2651). Squiggle = init expr.
     *  - TS2477: the member initializer evaluates to a non-finite (±Infinity) value.
     *  - TS2478: the member initializer evaluates to NaN. Both squiggle the init expr.
     *  - TS2476: a const-enum element access `E[x]` whose index is not a string literal.
     *    Squiggle = the index argument.
     *  - TS2475: a const-enum NAME used as a value (anywhere that is not a property/element
     *    access base, a `typeof` operand, or an import/export-= RHS). Squiggle = the name.
     *  - TS2567: a const enum merging with an INSTANTIATED same-name namespace (two runtime
     *    objects); fires on BOTH the enum name and the namespace name.
     */
    /** Round 479: names of const enums declared TOP-LEVEL in SCRIPT (non-module)
     *  files — the only cross-file const enums a module file may reference bare
     *  (ambient globals). Lazily built once. */
    private var scriptFileConstEnumNamesCache: Set<String>? = null
    private fun scriptFileConstEnumNames(): Set<String> {
        scriptFileConstEnumNamesCache?.let { return it }
        val names = HashSet<String>()
        for (r in binderResults) {
            if (isModuleFile(r.sourceFile.statements)) continue
            for (st in r.sourceFile.statements) {
                if (st is EnumDeclaration && ModifierFlag.Const in st.modifiers) names.add(st.name.text)
            }
        }
        scriptFileConstEnumNamesCache = names
        return names
    }

    /** Position right after the closing backtick of a template literal that starts at [start]. */
    private fun constEnumTemplateEnd(source: String, start: Int): Int {
        var i = start + 1 // skip opening backtick
        while (i < source.length) {
            when (source[i]) {
                '\\' -> i += 2
                '`' -> return i + 1
                '$' -> if (i + 1 < source.length && source[i + 1] == '{') {
                    var depth = 1; i += 2
                    while (i < source.length && depth > 0) {
                        when (source[i]) { '{' -> depth++; '}' -> depth-- }
                        i++
                    }
                } else i++
                else -> i++
            }
        }
        return i
    }

    private fun collectConstEnumDecls(stmts: List<Statement>, out: MutableList<EnumDeclaration>) {
        for (stmt in stmts) when (stmt) {
            is EnumDeclaration -> if (ModifierFlag.Const in stmt.modifiers) out.add(stmt)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { collectConstEnumDecls(it.statements, out) }
            else -> {}
        }
    }

    private fun constEnumMemberName(node: Node): String? = when (node) {
        is Identifier -> node.text
        is StringLiteralNode -> node.text
        is NumericLiteralNode -> node.text
        else -> null
    }

    private fun emitConstEnumInitDiag(init: Expression, source: String, fileName: String, code: Int, message: String) {
        val start = init.pos
        val length = (expressionTrueEnd(init) - start).coerceAtLeast(1)
        val (line, ch) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message, category = DiagnosticCategory.Error, code = code,
            fileName = fileName, line = line, character = ch, start = start, length = length,
        ))
    }

    /** True if [init] references a NON-existent member of [enumName] via `E.X`/`E["X"]`
     *  (a forward-reference to an existing member is TS2651, not TS2474). */
    private fun constEnumInitRefsNonMember(init: Expression, enumName: String, memberNames: Set<String>): Boolean {
        var found = false
        fun walk(e: Expression?) {
            if (e == null || found) return
            when (e) {
                is PropertyAccessExpression -> {
                    if ((e.expression as? Identifier)?.text == enumName && e.name.text !in memberNames) found = true
                    else walk(e.expression)
                }
                is ElementAccessExpression -> {
                    val key = (e.argumentExpression as? StringLiteralNode)?.text
                        ?: (e.argumentExpression as? NoSubstitutionTemplateLiteralNode)?.text
                    if ((e.expression as? Identifier)?.text == enumName && key != null && key !in memberNames) found = true
                    else { walk(e.expression); walk(e.argumentExpression) }
                }
                is BinaryExpression -> { walk(e.left); walk(e.right) }
                is PrefixUnaryExpression -> walk(e.operand)
                is PostfixUnaryExpression -> walk(e.operand)
                is ParenthesizedExpression -> walk(e.expression)
                is ConditionalExpression -> { walk(e.condition); walk(e.whenTrue); walk(e.whenFalse) }
                else -> {}
            }
        }
        walk(init)
        return found
    }

    /** Walk a setter body for value-`return` statements, NOT crossing function/class
     *  boundaries (returns inside nested functions belong to those functions). */
    private fun checkSetterBodyReturns(s: Statement, source: String, fileName: String) {
        when (s) {
            is ReturnStatement -> if (s.expression != null) {
                val (line, ch) = getLineAndCharacterOfPosition(source, s.pos)
                diagnostics.add(Diagnostic(
                    message = "Setters cannot return a value.",
                    category = DiagnosticCategory.Error, code = 2408,
                    fileName = fileName, line = line, character = ch,
                    start = s.pos, length = 6,
                ))
            }
            is Block -> s.statements.forEach { checkSetterBodyReturns(it, source, fileName) }
            is IfStatement -> {
                checkSetterBodyReturns(s.thenStatement, source, fileName)
                s.elseStatement?.let { checkSetterBodyReturns(it, source, fileName) }
            }
            is ForStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            is ForInStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            is ForOfStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            is WhileStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            is DoStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            is SwitchStatement -> for (c in s.caseBlock) when (c) {
                is CaseClause -> c.statements.forEach { checkSetterBodyReturns(it, source, fileName) }
                is DefaultClause -> c.statements.forEach { checkSetterBodyReturns(it, source, fileName) }
                else -> {}
            }
            is TryStatement -> {
                checkSetterBodyReturns(s.tryBlock, source, fileName)
                s.catchClause?.block?.let { checkSetterBodyReturns(it, source, fileName) }
                s.finallyBlock?.let { checkSetterBodyReturns(it, source, fileName) }
            }
            is LabeledStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            is WithStatement -> checkSetterBodyReturns(s.statement, source, fileName)
            else -> {}   // FunctionDeclaration / ClassDeclaration / etc. — own scope
        }
    }

    /**
     * TS2449: a class's OWN name used (as a value) in a DIRECT member's computed
     * property name `[A.x]` / `[A]` is a temporal-dead-zone use-before-declaration —
     * the class binding is not yet initialized while its member names are evaluated.
     * Squiggle = the class-name identifier; reuses [emitTS2449] (with TS2728 "declared
     * here"). Only direct-member computed names are flagged (a reference inside a member
     * BODY runs after the class is declared and is legal). Reuses the setter-traversal's
     * class-finding ([findClassesForComputed]) to reach nested classes.
     */
    private fun checkClassNameInOwnComputedMemberNames() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            findClassesForComputed(result.sourceFile.statements, result.sourceFile.text, fileName)
        }
    }

    private fun leftmostIdentifierOf(e: Expression): Identifier? = when (e) {
        is Identifier -> e
        is PropertyAccessExpression -> leftmostIdentifierOf(e.expression)
        is ElementAccessExpression -> leftmostIdentifierOf(e.expression)
        is CallExpression -> leftmostIdentifierOf(e.expression)
        is NonNullExpression -> leftmostIdentifierOf(e.expression)
        is ParenthesizedExpression -> leftmostIdentifierOf(e.expression)
        else -> null
    }

    private fun checkComputedSelfRefMembers(className: String, declPos: Int, members: List<ClassElement>, source: String, fileName: String) {
        for (m in members) {
            val nameNode: NameNode? = when (m) {
                is PropertyDeclaration -> m.name
                is MethodDeclaration -> m.name
                is GetAccessor -> m.name
                is SetAccessor -> m.name
                else -> null
            }
            if (nameNode is ComputedPropertyName) {
                val lead = leftmostIdentifierOf(nameNode.expression)
                if (lead != null && lead.text == className) {
                    emitTS2449(lead, declPos, className, source, fileName)
                }
            }
        }
    }

    /**
     * B98.r119 (TS2449): a class's OWN name referenced — in an EAGERLY-evaluated
     * position — inside one of its own decorators (the class decorator itself, or any
     * member decorator) is a temporal-dead-zone use-before-declaration: decorators run
     * as part of the class definition, before the class binding is initialized. So
     * `@dec(C) class C {}` and `class C { @dec(C) m() {} }` error, but `@dec(() => C)`
     * (a lazy un-invoked arrow that merely captures the name) is fine. An IIFE
     * `@dec((() => C)())` invokes the arrow, making its body eager → error again.
     * Squiggle = the class-name identifier; reuses [emitTS2449] (+ TS2728 "declared
     * here"). FP-safe: fires only for the enclosing class's OWN name in an eager
     * decorator position, which is always TS2449 in TypeScript.
     */
    private fun checkDecoratorSelfRef(
        className: String, declPos: Int,
        classDecorators: List<Decorator>?, members: List<ClassElement>,
        source: String, fileName: String,
    ) {
        classDecorators?.forEach {
            walkDecoratorForSelfRef(it.expression, className, declPos, source, fileName)
        }
        for (m in members) {
            val memberDecorators: List<Decorator>? = when (m) {
                is MethodDeclaration -> m.decorators
                is PropertyDeclaration -> m.decorators
                is GetAccessor -> m.decorators
                is SetAccessor -> m.decorators
                else -> null
            }
            memberDecorators?.forEach {
                walkDecoratorForSelfRef(it.expression, className, declPos, source, fileName)
            }
        }
    }

    /**
     * Descend an expression in EAGER (immediately-evaluated) position, emitting TS2449
     * for any reference to [className]. Un-invoked arrow/function bodies are NOT
     * descended (lazy); an arrow/function in a CallExpression's callee position IS
     * invoked, so its (expression) body is descended eagerly.
     */
    private fun walkDecoratorForSelfRef(
        e: Expression, className: String, declPos: Int, source: String, fileName: String,
    ) {
        fun rec(x: Expression) = walkDecoratorForSelfRef(x, className, declPos, source, fileName)
        when (e) {
            is Identifier -> if (e.text == className) emitTS2449(e, declPos, className, source, fileName)
            is ParenthesizedExpression -> rec(e.expression)
            is PropertyAccessExpression -> rec(e.expression)
            is ElementAccessExpression -> { rec(e.expression); rec(e.argumentExpression) }
            is CallExpression -> {
                when (val callee = unwrapParensExpr(e.expression)) {
                    // IIFE: the arrow/function is invoked, so an expression body runs eagerly.
                    is ArrowFunction -> (callee.body as? Expression)?.let { rec(it) }
                    is FunctionExpression -> {}  // block body — references are not expression-level
                    else -> rec(e.expression)
                }
                e.arguments.forEach { rec(it) }
            }
            is NewExpression -> { rec(e.expression); e.arguments?.forEach { rec(it) } }
            is BinaryExpression -> { rec(e.left); rec(e.right) }
            is ConditionalExpression -> { rec(e.condition); rec(e.whenTrue); rec(e.whenFalse) }
            is ArrayLiteralExpression -> e.elements.forEach { rec(it) }
            is SpreadElement -> rec(e.expression)
            is PrefixUnaryExpression -> rec(e.operand)
            is PostfixUnaryExpression -> rec(e.operand)
            is NonNullExpression -> rec(e.expression)
            is AsExpression -> rec(e.expression)
            // ArrowFunction / FunctionExpression NOT in callee position: lazy → skip.
            else -> {}
        }
    }

    private fun findClassesForComputed(stmts: List<Statement>, source: String, fileName: String) {
        for (s in stmts) findClassesForComputedInStatement(s, source, fileName)
    }

    private fun findClassesForComputedInStatement(s: Statement, source: String, fileName: String) {
        when (s) {
            is ClassDeclaration -> {
                s.name?.let { checkComputedSelfRefMembers(it.text, it.pos, s.members, source, fileName) }
                s.name?.let { checkDecoratorSelfRef(it.text, it.pos, s.decorators, s.members, source, fileName) }
                findClassesForComputedInMembers(s.members, source, fileName)
            }
            is FunctionDeclaration -> s.body?.let { findClassesForComputed(it.statements, source, fileName) }
            is ModuleDeclaration -> when (val b = s.body) {
                is ModuleBlock -> findClassesForComputed(b.statements, source, fileName)
                is ModuleDeclaration -> findClassesForComputedInStatement(b, source, fileName)
                else -> {}
            }
            is VariableStatement -> for (d in s.declarationList.declarations)
                d.initializer?.let { findClassesForComputedInExpr(it, source, fileName) }
            is ExpressionStatement -> findClassesForComputedInExpr(s.expression, source, fileName)
            is ReturnStatement -> s.expression?.let { findClassesForComputedInExpr(it, source, fileName) }
            is Block -> findClassesForComputed(s.statements, source, fileName)
            is IfStatement -> {
                findClassesForComputedInStatement(s.thenStatement, source, fileName)
                s.elseStatement?.let { findClassesForComputedInStatement(it, source, fileName) }
            }
            is ForStatement -> findClassesForComputedInStatement(s.statement, source, fileName)
            is ForInStatement -> findClassesForComputedInStatement(s.statement, source, fileName)
            is ForOfStatement -> findClassesForComputedInStatement(s.statement, source, fileName)
            is WhileStatement -> findClassesForComputedInStatement(s.statement, source, fileName)
            is DoStatement -> findClassesForComputedInStatement(s.statement, source, fileName)
            is TryStatement -> {
                findClassesForComputedInStatement(s.tryBlock, source, fileName)
                s.catchClause?.block?.let { findClassesForComputedInStatement(it, source, fileName) }
                s.finallyBlock?.let { findClassesForComputedInStatement(it, source, fileName) }
            }
            is LabeledStatement -> findClassesForComputedInStatement(s.statement, source, fileName)
            else -> {}
        }
    }

    private fun findClassesForComputedInMembers(members: List<ClassElement>, source: String, fileName: String) {
        for (m in members) when (m) {
            is MethodDeclaration -> m.body?.let { findClassesForComputed(it.statements, source, fileName) }
            is Constructor -> m.body?.let { findClassesForComputed(it.statements, source, fileName) }
            is GetAccessor -> m.body?.let { findClassesForComputed(it.statements, source, fileName) }
            is SetAccessor -> m.body?.let { findClassesForComputed(it.statements, source, fileName) }
            is PropertyDeclaration -> m.initializer?.let { findClassesForComputedInExpr(it, source, fileName) }
            is ClassStaticBlockDeclaration -> findClassesForComputed(m.body.statements, source, fileName)
            else -> {}
        }
    }

    private fun findClassesForComputedInExpr(e: Expression, source: String, fileName: String) {
        when (e) {
            is ClassExpression -> {
                e.name?.let { checkComputedSelfRefMembers(it.text, it.pos, e.members, source, fileName) }
                findClassesForComputedInMembers(e.members, source, fileName)
            }
            is ParenthesizedExpression -> findClassesForComputedInExpr(e.expression, source, fileName)
            is BinaryExpression -> { findClassesForComputedInExpr(e.left, source, fileName); findClassesForComputedInExpr(e.right, source, fileName) }
            is CallExpression -> { findClassesForComputedInExpr(e.expression, source, fileName); e.arguments.forEach { findClassesForComputedInExpr(it, source, fileName) } }
            is NewExpression -> { findClassesForComputedInExpr(e.expression, source, fileName); e.arguments?.forEach { findClassesForComputedInExpr(it, source, fileName) } }
            is ArrayLiteralExpression -> e.elements.forEach { findClassesForComputedInExpr(it, source, fileName) }
            is ConditionalExpression -> { findClassesForComputedInExpr(e.condition, source, fileName); findClassesForComputedInExpr(e.whenTrue, source, fileName); findClassesForComputedInExpr(e.whenFalse, source, fileName) }
            is ArrowFunction -> when (val b = e.body) {
                is Block -> findClassesForComputed(b.statements, source, fileName)
                is Expression -> findClassesForComputedInExpr(b, source, fileName)
                else -> {}
            }
            is FunctionExpression -> findClassesForComputed(e.body.statements, source, fileName)
            is AsExpression -> findClassesForComputedInExpr(e.expression, source, fileName)
            is NonNullExpression -> findClassesForComputedInExpr(e.expression, source, fileName)
            is SpreadElement -> findClassesForComputedInExpr(e.expression, source, fileName)
            else -> {}
        }
    }

    private fun evaluateEnumInitializer(
        expr: Expression,
        currentValues: Map<String, ConstantValue>,
        currentEnum: Symbol,
    ): ConstantValue? {
        return when (expr) {
            is NumericLiteralNode -> {
                // Numeric separators (`1_000_000`) are kept in the token text, and the
                // literal may be hex/binary/octal — tsc's CharacterCodes is almost entirely
                // hex, and a decimal-only parse silently made every such member
                // un-inlinable (EP.2b, round 675).
                val value = tsNumericLiteralToDouble(expr.text) ?: return null
                ConstantValue.NumberValue(value)
            }
            is StringLiteralNode -> ConstantValue.StringValue(expr.text)
            is PrefixUnaryExpression -> {
                val operand = evaluateEnumInitializer(expr.operand, currentValues, currentEnum)
                    ?: return null
                if (operand !is ConstantValue.NumberValue) return null
                when (expr.operator) {
                    SyntaxKind.Plus -> operand
                    SyntaxKind.Minus -> ConstantValue.NumberValue(-operand.value)
                    SyntaxKind.Tilde -> ConstantValue.NumberValue(
                        operand.value.toLong().inv().toDouble()
                    )
                    else -> null
                }
            }
            is BinaryExpression -> {
                val left = evaluateEnumInitializer(expr.left, currentValues, currentEnum)
                    ?: return null
                val right = evaluateEnumInitializer(expr.right, currentValues, currentEnum)
                    ?: return null
                if (left is ConstantValue.NumberValue && right is ConstantValue.NumberValue) {
                    evaluateNumericBinary(left.value, expr.operator, right.value)
                } else if (left is ConstantValue.StringValue && right is ConstantValue.StringValue
                    && expr.operator == SyntaxKind.Plus) {
                    ConstantValue.StringValue(left.value + right.value)
                } else null
            }
            is ParenthesizedExpression -> {
                evaluateEnumInitializer(expr.expression, currentValues, currentEnum)
            }
            is Identifier -> {
                // Reference to another member in the same enum
                currentValues[expr.text]
            }
            is PropertyAccessExpression -> {
                // Reference to another enum's member: E.A or A.B.C.E.V1
                val memberName = expr.name.text
                val targetEnum = resolveEnumExpression(expr.expression, currentEnum.name)
                if (targetEnum != null) {
                    if (targetEnum.name == currentEnum.name && targetEnum.id == currentEnum.id) {
                        currentValues[memberName]
                    } else {
                        if (!targetEnum.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(targetEnum) // ensure computed
                        enumValues[targetEnum.id]?.get(memberName)
                    }
                } else {
                    // Simple case: Identifier.member
                    val objName = (expr.expression as? Identifier)?.text ?: return null
                    if (objName == currentEnum.name) {
                        currentValues[memberName]
                    } else {
                        val symbol = globals[objName] ?: return null
                        val target = resolveAlias(symbol)
                        if (!target.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(target)
                        enumValues[target.id]?.get(memberName)
                    }
                }
            }
            is ElementAccessExpression -> {
                // E["member"] or E[`member`] — element access to enum member
                val keyStr = when (val k = expr.argumentExpression) {
                    is StringLiteralNode -> k.text
                    is NoSubstitutionTemplateLiteralNode -> k.text
                    else -> return null
                }
                val objName = (expr.expression as? Identifier)?.text
                if (objName != null) {
                    if (objName == currentEnum.name) {
                        currentValues[keyStr]
                    } else {
                        val symbol = globals[objName] ?: return null
                        val target = resolveAlias(symbol)
                        if (!target.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(target)
                        enumValues[target.id]?.get(keyStr)
                    }
                } else {
                    // Nested: A.B.C.E["V2"]
                    val targetEnum = resolveEnumExpression(expr.expression, currentEnum.name)
                        ?: return null
                    if (targetEnum.name == currentEnum.name && targetEnum.id == currentEnum.id) {
                        currentValues[keyStr]
                    } else {
                        if (!targetEnum.flags.hasAny(SymbolFlags.Enum)) return null
                        computeEnumSymbolValues(targetEnum)
                        enumValues[targetEnum.id]?.get(keyStr)
                    }
                }
            }
            is NoSubstitutionTemplateLiteralNode -> {
                ConstantValue.StringValue(expr.text)
            }
            is TemplateExpression -> {
                // Template literal: `prefix${expr}suffix`
                val sb = StringBuilder(expr.head.text)
                for (span in expr.templateSpans) {
                    val spanValue = evaluateEnumInitializer(span.expression, currentValues, currentEnum)
                        ?: return null
                    sb.append(
                        when (spanValue) {
                            is ConstantValue.StringValue -> spanValue.value
                            is ConstantValue.NumberValue -> spanValue.toString()
                        }
                    )
                    // The literal part is a StringLiteralNode (template middle/tail)
                    val literalText = (span.literal as? StringLiteralNode)?.text
                        ?: (span.literal as? NoSubstitutionTemplateLiteralNode)?.text
                        ?: ""
                    sb.append(literalText)
                }
                ConstantValue.StringValue(sb.toString())
            }
            else -> null
        }
    }

    private fun evaluateNumericBinary(
        left: Double,
        operator: SyntaxKind,
        right: Double,
    ): ConstantValue? {
        // Shared with the Transformer's same-file collector — see [tsFoldNumericBinary].
        val result = tsFoldNumericBinary(left, operator, right) ?: return null
        return ConstantValue.NumberValue(result)
    }

    /** B269: enum-initializer evaluation result mirroring TS's EvaluatorResult —
     *  [value] is a Double, a String, or null (not compile-time evaluable);
     *  [synStr] is TS's isSyntacticallyString (string/template literal provenance,
     *  KILLED by cross-file const resolution and by non-Plus operators). */
    private class EnumEv(val value: Any?, val synStr: Boolean)

    /** JS ToString for concat: integral doubles print without the Kotlin `.0`. */
    private fun jsConcatString(v: Any): String = when (v) {
        is Double -> if (!v.isInfinite() && v == v.toLong().toDouble()) v.toLong().toString() else v.toString()
        else -> v.toString()
    }

    /** Resolve [name] to a const variable's initializer; second = true when the declaration
     *  lives in a DIFFERENT file (import alias or shared script-global scope) — TS kills
     *  isSyntacticallyString for cross-file resolutions (the babel-transpilability rule). */
    private fun resolveConstInitForEnumEval(name: String, fileName: String): Pair<Expression, Boolean>? {
        val result = fileResults[fileName] ?: return null
        val symbol = result.locals[name]
        if (symbol != null) {
            val target = resolveAlias(symbol)
            val crossFile = target !== symbol
            for (decl in target.declarations) {
                if (decl !is VariableDeclaration) continue
                val parent = findContainingVariableStatement(decl, target) ?: continue
                if (parent.declarationList.flags != ConstKeyword) continue
                val init = decl.initializer ?: continue
                return init to crossFile
            }
            return null
        }
        if (isModuleFile(result.sourceFile.statements)) return null
        for (br in binderResults) {
            if (br.sourceFile.fileName == fileName) continue
            if (isDtsFile(br.sourceFile.fileName)) continue
            if (isModuleFile(br.sourceFile.statements)) continue
            for (stmt in br.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                if (stmt.declarationList.flags != ConstKeyword) continue
                for (d in stmt.declarationList.declarations) {
                    if ((d.name as? Identifier)?.text != name) continue
                    val init = d.initializer ?: continue
                    return init to true
                }
            }
        }
        return null
    }

    private fun enumEvalInit(expr: Expression, members: Map<String, EnumEv>, enumName: String, fileName: String, depth: Int): EnumEv {
        if (depth > 16) return EnumEv(null, false)
        return when (expr) {
            is NumericLiteralNode -> EnumEv(expr.text.replace("_", "").toDoubleOrNull(), false)
            is StringLiteralNode -> EnumEv(expr.text, true)
            is NoSubstitutionTemplateLiteralNode -> EnumEv(expr.text, true)
            is TemplateExpression -> {
                // A template is syntactically string even when a span fails to evaluate.
                val sb = StringBuilder(expr.head.text)
                for (span in expr.templateSpans) {
                    val r = enumEvalInit(span.expression, members, enumName, fileName, depth + 1)
                    val v = r.value ?: return EnumEv(null, true)
                    sb.append(jsConcatString(v))
                    val lit = span.literal as? StringLiteralNode ?: return EnumEv(null, true)
                    sb.append(lit.text)
                }
                EnumEv(sb.toString(), true)
            }
            is ParenthesizedExpression -> enumEvalInit(expr.expression, members, enumName, fileName, depth + 1)
            is PrefixUnaryExpression -> {
                val v = enumEvalInit(expr.operand, members, enumName, fileName, depth + 1).value as? Double
                    ?: return EnumEv(null, false)
                when (expr.operator) {
                    SyntaxKind.Plus -> EnumEv(v, false)
                    SyntaxKind.Minus -> EnumEv(-v, false)
                    SyntaxKind.Tilde -> EnumEv(v.toLong().inv().toDouble(), false)
                    else -> EnumEv(null, false)
                }
            }
            is BinaryExpression -> {
                val l = enumEvalInit(expr.left, members, enumName, fileName, depth + 1)
                val r = enumEvalInit(expr.right, members, enumName, fileName, depth + 1)
                val synStr = (l.synStr || r.synStr) && expr.operator == SyntaxKind.Plus
                val lv = l.value
                val rv = r.value
                val value: Any? = when {
                    lv is Double && rv is Double ->
                        (evaluateNumericBinary(lv, expr.operator, rv) as? ConstantValue.NumberValue)?.value
                    expr.operator == SyntaxKind.Plus && lv != null && rv != null &&
                        (lv is String || rv is String) -> jsConcatString(lv) + jsConcatString(rv)
                    else -> null
                }
                EnumEv(value, synStr)
            }
            is Identifier -> {
                members[expr.text]?.let { return it }
                val resolved = resolveConstInitForEnumEval(expr.text, fileName) ?: return EnumEv(null, false)
                val r = enumEvalInit(resolved.first, emptyMap(), "", fileName, depth + 1)
                if (resolved.second) EnumEv(r.value, false) else EnumEv(r.value, r.synStr)
            }
            is PropertyAccessExpression -> {
                if ((expr.expression as? Identifier)?.text == enumName) {
                    members[expr.name.text]?.let { return it }
                }
                EnumEv(null, false)
            }
            else -> EnumEv(null, false)
        }
    }

    /** B269: conservative "this enum initializer is definitely string-typed" estimator for
     *  TS18033 — a member reference is number-domain (a failed-evaluation member is assumed
     *  numeric by TS); only syntactically-sound string shapes return true (FN-safe). */
    private fun enumInitIsStringTyped(expr: Expression, memberNames: Set<String>, fileName: String, depth: Int): Boolean {
        if (depth > 16) return false
        return when (expr) {
            is StringLiteralNode, is NoSubstitutionTemplateLiteralNode, is TemplateExpression -> true
            is ParenthesizedExpression -> enumInitIsStringTyped(expr.expression, memberNames, fileName, depth + 1)
            is AsExpression -> (expr.type as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword
            is TypeAssertionExpression -> (expr.type as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword
            is NonNullExpression -> enumInitIsStringTyped(expr.expression, memberNames, fileName, depth + 1)
            is BinaryExpression -> expr.operator == SyntaxKind.Plus &&
                (enumInitIsStringTyped(expr.left, memberNames, fileName, depth + 1) ||
                    enumInitIsStringTyped(expr.right, memberNames, fileName, depth + 1))
            is Identifier -> {
                if (expr.text in memberNames) false
                else resolveConstInitForEnumEval(expr.text, fileName)
                    ?.let { enumInitIsStringTyped(it.first, emptySet(), fileName, depth + 1) } == true
            }
            is CallExpression -> {
                // `2..toFixed(0)` — numeric-literal receiver, string-returning method
                val callee = expr.expression as? PropertyAccessExpression
                callee != null && callee.name.text == "toFixed" && callee.expression is NumericLiteralNode
            }
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // Import reference tracking
    // -----------------------------------------------------------------------

    /**
     * (INC.10) THE WHOLE-PROGRAM ALIAS-REFERENCE WALK, RUN ON THE FIRST ASK.
     *
     * This was `init:trackAllImportReferences`, the second-largest row in the
     * incremental floor at **29.4 ms of 393** on tsc's own 78 sources — and it
     * is EMIT-ONLY work. Everything it writes is one set, [referencedAliases]
     * (`markAliasReferenced` is the family's only mutation — the four
     * `trackReferences*` functions and `markJsxFactoryReferenced` add nothing
     * else, emit no diagnostic and touch no cache), and that set has exactly ONE
     * reader in the program: [isReferencedAliasDeclaration], which decides
     * import elision and which only `Transformer` calls. Round 738's
     * `skipEmitOutputs` gate makes a `--noEmit` build skip the transformer
     * entirely, so on every language-service query — and on every `--noEmit`
     * compile — this walk produced a set that nothing could read.
     *
     * **Deferring, not skipping, is what makes it safe.** The alternative, a
     * static `if (options.skipEmitOutputs) return`, would be correct today and
     * would silently answer "nothing is referenced" the day a second consumer
     * appears; worse, it would leave the deferred path untested, because the
     * corpus emits. Building on the ask instead means the ~13k-baseline corpus —
     * thousands of whose `.js` baselines pin exactly which imports survive
     * elision — exercises this code path end to end on every suite run.
     *
     * **Why the answer cannot depend on when it runs.** The walk reads the
     * frozen AST, `result.locals[name]` and `symbol.flags`, and asks one
     * question: does this file-local name carry [SymbolFlags.Alias]. Nothing
     * between `init` and the transformer's first question clears a symbol flag
     * (`mergeSingleSymbol` only ever ORs bits in, and it runs at init step 1b,
     * before this pass ever stood), and the walk itself is idempotent — it adds
     * symbol ids to a set.
     *
     * **It also deletes N-1 copies of itself.** [CheckerPool] builds N checkers
     * over one bind and each ran this walk in its own `init`; only the primary
     * is ever questioned, so only the primary now pays.
     */
    private fun ensureImportReferencesTracked() {
        if (importReferencesTracked) return
        importReferencesTracked = true
        FrontEnd.aliasTrackBuilds++
        for (result in binderResults) {
            trackReferencesInStatements(result.sourceFile.statements, result)
        }
    }

    /**
     * 17.32a: Build per-file scope tables (Blocker #3 step 1, infrastructure-only).
     *
     * For each file, compute "true visible scope" = lib (built-in stubs) +
     * script-file locals from ALL files + this file's own locals. Module-file
     * locals from OTHER files are deliberately excluded — those should require
     * an explicit import to be visible. Result is stored in [perFileScope]
     * keyed by `sourceFile.fileName`.
     *
     * NOT YET CONSUMED. Future substeps (17.32b+) will flip individual
     * identifier-resolution call sites to consult this map instead of the
     * over-merged [globals]. KNOWN_GLOBALS stays at the call site (companion
     * data, no visibility refinement to add per file).
     *
     * IMPORTANT: this MUST NOT call [mergeSymbolTable] across binderResults —
     * that helper mutates the existing target symbol's `declarations` list via
     * `addAll`, and the existing init-block merge into [globals] has already
     * done that mutation once. Re-merging here would duplicate declarations on
     * the shared symbol object (e.g. `class C<T>` in a.ts + `interface C<T>` in
     * b.ts ends up with the interface declaration appearing twice on `a.ts.C`,
     * which masks unused-type-parameter checks). Use direct map assignment
     * with first-write-wins semantics so the underlying symbols stay clean.
     */
    private fun buildPerFileScopes() {
        // Collect first-occurrence symbol per name across all script files.
        val scriptFileNames: MutableMap<String, Symbol> = mutableMapOf()
        for (result in binderResults) {
            if (!isModuleFile(result.sourceFile.statements)) {
                for ((name, sym) in result.locals) {
                    if (name !in scriptFileNames) scriptFileNames[name] = sym
                }
            }
        }
        for (result in binderResults) {
            val fileScope: SymbolTable = symbolTable()
            // Lib globals — visible from every file.
            for ((name, sym) in libGlobals) fileScope[name] = sym
            // Script-file locals — visible across all files (TypeScript treats
            // any file without imports/exports as contributing to the global
            // namespace).
            for ((name, sym) in scriptFileNames) {
                if (name !in fileScope) fileScope[name] = sym
            }
            // (CHK.50) `declare global { … }` additions — global by construction,
            // and therefore visible from every file exactly as a script-file local is.
            for ((name, sym) in globalAugmentationAddedSymbols) {
                if (name !in fileScope) fileScope[name] = sym
            }
            // Own-file locals — visible to ourselves. Module files override
            // any same-name lib/script entries (matches TypeScript's local-
            // shadows-global semantics for the file's own declarations).
            for ((name, sym) in result.locals) fileScope[name] = sym
            perFileScope[result.sourceFile.fileName] = fileScope
            // (WARM.23) round 896 — THE one mutation of [perFileScope], and so the
            // one place [perFileScopeOf]'s memo could go stale. Clearing it here
            // makes staleness inexpressible rather than unlikely; a new write site
            // must clear it too.
            perFileScopeMemoKey = null
            perFileScopeMemoValue = null
        }
    }

    /**
     * INV.3(b)(ii): compute the per-file visibility model's sets once per
     * program (init step 1b2, after the [globals] membership settles):
     *  - `moduleLocalNames` — every top-level local of every MODULE file: the
     *    conflation candidates (only these names can be module-file leaks);
     *  - `nonModuleVisible` — names with a legitimate global meaning without
     *    the conflation: [libGlobals] keys (embedded or real libs), script-file
     *    locals, and names ADDED to [globals] by [mergeModuleAugmentations]
     *    (captured as the key-set delta around step 1b).
     *
     * Publishes their difference as [moduleOnlyGlobalNames] (the
     * [globalsForFile] gate) and hands both sets to the INV.3(a) classifier
     * install (a no-op unless `--passTiming` constructed [globals]
     * instrumented).
     */
    private fun computePerFileVisibility(preAugmentationGlobalsKeys: Set<String>) {
        val moduleLocalNames = HashSet<String>()
        // (CHK.49) the LIB key set is deliberately NOT seeded here — see
        // [mergeSharedKeepNames]'s KDoc. A lib name a MODULE file declares now
        // falls into [moduleOnlyGlobalNames] and is resolved through
        // [perFileScope], which already seeds every file with the lib symbol and
        // lets the declaring file's own local override it. The INV.3(a)
        // classifier below is still handed the OLD taxonomy (lib keys included)
        // so its SHARED/CONFLATED counts stay comparable across rounds.
        val nonModuleVisible = HashSet<String>()
        for (result in binderResults) {
            if (isModuleFile(result.sourceFile.statements)) {
                // INV.3(d): entries the retired merge deliberately KEEPS global
                // (`declare global` / UMD / ambient-module carriers) classify as
                // non-module-visible — same predicate as the step-1 merge.
                for ((name, sym) in result.locals) {
                    if (moduleLocalContributesGlobally(name, sym)) nonModuleVisible.add(name)
                    else moduleLocalNames.add(name)
                }
            } else {
                nonModuleVisible.addAll(result.locals.keys)
            }
        }
        for (key in globals.keys) {
            if (key !in preAugmentationGlobalsKeys) nonModuleVisible.add(key)
        }
        moduleOnlyGlobalNames = HashSet(moduleLocalNames).apply { removeAll(nonModuleVisible) }
        // (CHK.49) the VALUE meaning of a shadowed lib name SURVIVES the shadow:
        // `interface Map<K, V>` declared in a module file shadows the lib TYPE
        // and leaves `declare var Map: MapConstructor` reachable, which is what
        // keeps `new Map()` constructable there. Precomputed (and normally
        // EMPTY) so [libValueBehindTypeOnlyShadow]'s guard is one set probe on
        // the ~2 M-identifier path.
        libValueShadowNames =
            if (moduleOnlyGlobalNames.isEmpty()) emptySet()
            else moduleOnlyGlobalNames.filterTo(HashSet()) { n ->
                libGlobals[n]?.valueDeclaration != null
            }
        installGlobalsLookupClassifier(
            moduleLocalNames,
            HashSet(nonModuleVisible).apply { addAll(libGlobals.keys) },
        )
    }

    /**
     * INV.3(a): install the `globals`-lookup classifier onto the
     * [InstrumentedSymbolTable] the field was constructed as under
     * `--passTiming` (no-op otherwise). Each keyed lookup from here on is
     * classified against the per-file visibility model INV.3 migrates to —
     * see [GlobalsLookupClass] for the classes — and recorded via
     * [PassTiming.noteGlobalsLookup] with per-pass attribution. The dump's
     * conflated/unscoped name and pass tables ARE the migration worklist.
     *
     * Classification sets come from [computePerFileVisibility]. A hit on a
     * name in `moduleLocalNames` but not `nonModuleVisible` is a pure
     * module-file leak; whether the SITE is fine per-file depends on
     * [currentFileLocals] at lookup time (own local vs conflated vs no file
     * context). The classifier must never consult [globals] itself — that
     * would recurse the hook.
     */
    private fun installGlobalsLookupClassifier(
        moduleLocalNames: Set<String>,
        nonModuleVisible: Set<String>,
    ) {
        val instrumented = globals as? InstrumentedSymbolTable ?: return
        instrumented.onLookup = { name, sym ->
            val cls = when {
                sym == null -> GlobalsLookupClass.MISS
                name !in moduleLocalNames -> GlobalsLookupClass.TRUE_GLOBAL
                name in nonModuleVisible -> GlobalsLookupClass.SHARED
                else -> {
                    val locals = currentFileLocals
                    when {
                        locals == null -> GlobalsLookupClass.UNSCOPED
                        locals.containsKey(name) -> GlobalsLookupClass.OWN_LOCAL
                        else -> GlobalsLookupClass.CONFLATED
                    }
                }
            }
            PassTiming.noteGlobalsLookup(cls, name)
        }
    }

    /**
     * INV.3(b): THE per-file resolution primitive. An INV.3(c) family flip
     * consumes it through [globalsForFile] (which preserves the legacy merged
     * symbol INSTANCE for legitimately visible names — substituting THIS
     * function's return directly changes symbol identity for lib/script names,
     * because [perFileScope] holds the first-occurrence script symbol while
     * [globals] holds the first-declarer merged instance). Resolution:
     * [perFileScope]'s table for [fileName] (own top-level locals shadowing
     * script-file globals shadowing lib — built by [buildPerFileScopes]), with an
     * own-local IMPORT alias resolved onward through [resolveImportedSymbolGeneral]
     * to the target module's symbol — the ESM-`.js`/`export *`-barrel following the
     * merged `globals` used to provide for free (the round-500 measurement: the
     * conflated traffic is almost entirely barrel-imported `types.ts` names).
     *
     * Returns:
     *  - the resolved target symbol for an ImportSpecifier-declared alias local
     *    (for a name the file imports, this is the SAME symbol instance the
     *    conflated `globals` consult returned — which is what makes (c) flips
     *    byte-identical for imported names);
     *  - the alias symbol ITSELF when the import cannot be resolved (missing
     *    module / unsupported alias kind: default imports, `import * as ns`,
     *    `import =` — extend when a (c) flip needs them) — callers keep their
     *    existing alias handling;
     *  - the plain symbol for non-alias names (own declaration / script-file
     *    global / lib);
     *  - null when the name has NO per-file meaning — exactly the case where the
     *    conflated lookup would have leaked a foreign module file's local.
     *
     * `internal` for direct construction tests (Inv3PerFileLookupTest); unconsumed
     * by checker paths until INV.3(c).
     */
    /**
     * (WARM.23) THE funnel for every `perFileScope` read — round 894 candidate
     * (2a). Two things ride on it and neither is expressible at the raw `[]`:
     * the census counts how many full file-PATH hashes a rebuild pays (the map
     * is keyed by a 60-100 character path and probed per NAME lookup), and
     * `--perFileScopeAmp N` prices ONE probe by round 759's amplification,
     * because a single probe is well under a timestamp pair.
     *
     * Off (both modes at their defaults) this is `perFileScope[fileName]` and
     * two not-taken branches.
     */
    private fun perFileScopeOf(fileName: String): SymbolTable? {
        // (WARM.23) round 896 — a ONE-ENTRY memo compared by REFERENCE, the shape
        // round 895(D) landed for `SrcScanCache`: **a miss is never wrong, only
        // slower.** A hit is sound because the same `String` INSTANCE cannot get
        // a different answer out of a map that is not mutated in between — and
        // the one mutation site ([buildPerFileScopes]' store) clears it, so
        // staleness is not expressible either.
        //
        // Identity is the right test rather than a weakness: `perFileScope`'s keys
        // ARE `sourceFile.fileName`, and every hot caller reaches here with that
        // very instance ([lookupPerFileForNode] via `owner.fileName`), so the hit
        // rate is a property of the traversal, not of string equality. Keying the
        // MAP by identity would be the unsound version — an equal-but-distinct
        // path would answer null and silently resolve a name to a foreign
        // module's local, which is why the map probe stays authoritative.
        if (fileName === perFileScopeMemoKey) {
            if (MapCensus.on) MapCensus.perFileMemoHits++
            return perFileScopeMemoValue
        }
        val scope = perFileScopeProbe(fileName)
        perFileScopeMemoKey = fileName
        perFileScopeMemoValue = scope
        return scope
    }


    private fun perFileScopeProbe(fileName: String): SymbolTable? {
        if (MapCensus.on) MapCensus.perFileProbes++
        val r = MapCensus.perFileScopeReads
        if (r == 0) return perFileScope[fileName]
        if (r < 0) {
            // In-situ EMPTY bracket at the same site and frequency, so `cold` can
            // be separated from the pair. The real read still happens, outside
            // the pair, so the compile is unchanged.
            val e0 = PassTiming.nowNanos()
            MapCensus.perFileAmpNanos += PassTiming.nowNanos() - e0
            MapCensus.perFileAmpCalls++
            return perFileScope[fileName]
        }
        val t0 = PassTiming.nowNanos()
        var result: SymbolTable? = null
        var seen = 0L
        var i = 0
        while (i < r) {
            val v = perFileScope[fileName]
            if (v != null) seen++
            result = v
            i++
        }
        MapCensus.perFileAmpNanos += PassTiming.nowNanos() - t0
        MapCensus.perFileAmpCalls++
        MapCensus.sink += seen
        return result
    }

    internal fun lookupPerFile(fileName: String, name: String): Symbol? =
        lookupInFileScope(perFileScopeOf(fileName) ?: return null, name)

    /**
     * [lookupPerFile] once the file's table is already in hand — the whole of its
     * body below the `perFileScope` probe.
     *
     * (WARM.23) round 896, candidate (2a): [globalsForFile] used to ask
     * `perFileScope.containsKey(fileName)` and then call [lookupPerFile], which
     * asked `perFileScope[fileName]` again — the file PATH hashed TWICE per name
     * lookup on the hottest resolution path in the checker. Splitting the body out
     * lets the caller pass the table it already resolved. Same answers by
     * construction: the map's value type is non-nullable, so `containsKey` and
     * `get() != null` are the same predicate.
     */
    private fun lookupInFileScope(scope: SymbolTable, name: String): Symbol? {
        val sym = scope[name] ?: return null
        if (sym.flags.hasAny(SymbolFlags.Alias) && sym.declarations.any { it is ImportSpecifier }) {
            resolveImportedSymbolGeneral(sym)?.let { return it }
        }
        return sym
    }

    /**
     * INV.3(b)(ii): a `globals[name]` consult made per-file-correct — the flip
     * shape for the INV.3(c) migration. Returns the merged-globals symbol
     * (INSTANCE-identical to the legacy consult, which is what keeps a flip
     * byte-identical for every legitimately visible name) whenever [name] has a
     * per-file meaning in [fileName]:
     *  - a name outside [moduleOnlyGlobalNames] (lib / script-file /
     *    augmentation-added global — no conflation possible), or
     *  - a module-only name the file itself declares or imports, probed through
     *    [lookupPerFile] (the INV.3(b) primitive; an import alias resolves
     *    non-null there whether or not its target module resolves).
     *
     * Returns null exactly when the legacy consult would have LEAKED a foreign
     * module file's local (the CONFLATED class of the INV.3(a)
     * instrumentation): the caller behaves as if the name did not resolve,
     * which is what real tsc sees in that file. A [fileName] without a
     * [perFileScope] entry (scopes unbuilt, or a file outside the program)
     * degrades to the legacy consult.
     *
     * The conflated branch never touches [globals], so under `--passTiming`
     * the per-pass conflated tables keep measuring only UN-migrated traffic.
     */
    internal fun globalsForFile(fileName: String, name: String): Symbol? {
        if (NameCensus.on) {
            NameCensus.publish(moduleOnlyGlobalNames, globals.keys)
            NameCensus.nameProbe(name, name in moduleOnlyGlobalNames, node = false)
        }
        if (name in moduleOnlyGlobalNames) {
            // (WARM.23) round 896 — ONE probe. This used to be
            // `perFileScope.containsKey(fileName)` here and `perFileScope[fileName]`
            // again inside [lookupPerFile]: the file PATH hashed twice per name.
            val scope = perFileScopeOf(fileName)
            if (scope != null) {
                // INV.3(d): the retired merge no longer puts module-only names into
                // [globals] at all — the per-file resolution IS the symbol (the
                // declaring file's own clean instance; an import alias resolves
                // onward through [resolveImportedSymbolGeneral] inside
                // [lookupInFileScope]). Null exactly where the legacy merged
                // consult would have LEAKED a foreign module file's local.
                return lookupInFileScope(scope, name)
            }
        }
        return globals[name]
    }

    /**
     * INV.3(c)(i): the NODE-keyed per-file consult — a `globals[name]` consult
     * made per-file-correct for a name READ FROM AN AST NODE. The round-503
     * measurement: ~82% of conflated traffic resolves names from FOREIGN nodes
     * (types.ts's union-member `.kind` annotations, read by the discriminant/
     * kind-domain narrowing machinery) while checking a DIFFERENT file — tsc
     * resolves such an annotation in its OWNING file's scope, so the owning
     * file is the correct key there, never `currentCheckFileName` (keying by
     * the checking file would silently kill the narrowing wherever that file
     * does not import the name). Resolution: [owningSourceFile] via the
     * INV.2(a) parent chain, then [globalsForFile] under that file's
     * visibility — so a name visible in the owning file returns the legacy
     * merged-globals INSTANCE (byte-identical flips), and null means the name
     * has no meaning even where the node lives. An UNINDEXED node (data-class
     * `copy()` / Transformer-synthesized / detached subtree) has no owner —
     * degrade to the legacy merged consult, mirroring [globalsForFile]'s
     * unknown-file degradation. `internal` for direct-construction tests.
     * Consumers (INV.3(c)(ii)): the enum-discriminant readers —
     * [resolveEnumSymbolForDiscriminant] and the alias fallbacks in
     * [enumSwitchKeysFromTypeNode]/[enumMemberKeysOfTypeNode].
     */
    internal fun lookupPerFileForNode(node: Node, name: String): Symbol? {
        // Fast path (round 507b): a non-module-only name resolves identically
        // under EVERY file's visibility ([globalsForFile] ignores the file for
        // it), so skip the parent-chain walk — this sits on getTypeOfIdentifier's
        // fallback, which is consulted for ~2M identifiers per self-compile.
        // Before init step 1b2 the set is empty → everything degrades to the
        // legacy merged consult (same as the ownerless degradation below).
        if (NameCensus.on) {
            NameCensus.publish(moduleOnlyGlobalNames, globals.keys)
            NameCensus.nameProbe(name, name in moduleOnlyGlobalNames, node = true)
        }
        if (name !in moduleOnlyGlobalNames) return globals[name]
        // Walk to the owning SourceFile, capturing the INNERMOST enclosing
        // `declare module "<spec>"` block on the way (the INV.3(c)(iv)
        // augmentation-visibility rule below needs it). Mirrors
        // [owningSourceFile]'s hop-bounded chain walk.
        var cur: Node? = node
        var hops = 0
        var ambientSpec: String? = null
        var owner: SourceFile? = null
        while (cur != null && hops++ < 4096) {
            if (cur is SourceFile) { owner = cur; break }
            if (ambientSpec == null && cur is ModuleDeclaration) {
                (cur.name as? StringLiteralNode)?.let { ambientSpec = it.text }
            }
            cur = (cur as NodeBase).parent
        }
        if (owner == null) return globals[name]
        globalsForFile(owner.fileName, name)?.let { return it }
        // INV.3(c)(iv): a node inside a `declare module "<relative-spec>"`
        // AUGMENTATION block additionally sees the AUGMENTED module's exports
        // by bare name — tsc checks the body in that module's context (the
        // round-443 rule; mirrors buildNamespaceScope's StringLiteralNode
        // branch, which grants the same visibility to the TS2304 scope). A
        // services/types.ts augmentation of "../compiler/types.js" references
        // Node/SymbolFlags/UnionType without importing them; the per-file
        // consult alone would null those and silently kill e.g. this-predicate
        // narrowing whose target type lives in the augmented module.
        val spec = ambientSpec ?: return null
        val target = resolveModuleSpecifierRelativeJsAware(spec, owner.fileName) ?: return null
        val targetFile = fileResults[target]?.sourceFile ?: return null
        if (name !in moduleNamedExportsOf(targetFile)) return null
        // Proven visible via the augmentation context: resolve in the AUGMENTED
        // module's own scope (INV.3(d): the merged instance no longer exists —
        // the target file's local is the symbol tsc sees there).
        return lookupPerFile(target, name)
    }

    /**
     * 17.33: scan all parsed files to populate [umdGlobalNames] (from
     * `export as namespace X;` in .d.ts files) and [moduleFiles] (any file
     * with imports/exports OR — for .js/.jsx — a top-level `require(...)`
     * call). The parser does not produce a dedicated AST node for the
     * `export as namespace` construct, so a regex on the source text is
     * the smallest sufficient implementation.
     */
    private fun collectUmdGlobalsAndModuleFiles() {
        val umdRegex = Regex("""(?m)^\s*export\s+as\s+namespace\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*;?""")
        val requireRegex = Regex("""\brequire\s*\(""")
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            if (isDtsFile(fileName)) {
                for (m in umdRegex.findAll(source)) {
                    umdGlobalNames.add(m.groupValues[1])
                }
            }
            val isJs = fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".mjs") || fileName.endsWith(".cjs")
            val isModule = isModuleFile(result.sourceFile.statements) ||
                (isJs && requireRegex.containsMatchIn(source))
            if (isModule) moduleFiles.add(fileName)
            // Collect `declare global { var X: ... }` declared names so TS2591
            // (and similar global-aware checks) can skip names the user explicitly
            // augmented onto the global namespace.
            collectGlobalAugmentationNames(result.sourceFile.statements)
        }
    }

    /** Walk statements collecting names declared inside `declare global { ... }` blocks. */
    private fun collectGlobalAugmentationNames(statements: List<Statement>) {
        for (stmt in statements) {
            if (stmt is ModuleDeclaration &&
                (stmt.name as? Identifier)?.text == "global" &&
                ModifierFlag.Declare in stmt.modifiers
            ) {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (inner in body.statements) {
                        when (inner) {
                            is VariableStatement -> for (decl in inner.declarationList.declarations) {
                                (decl.name as? Identifier)?.text?.let { globalAugmentationNames.add(it) }
                            }
                            is FunctionDeclaration -> inner.name?.text?.let { globalAugmentationNames.add(it) }
                            is ClassDeclaration -> inner.name?.text?.let { globalAugmentationNames.add(it) }
                            // `export import x = A.y;` inside `declare global` registers `x` as a
                            // global alias (importAliasInModuleAugmentation) — suppress TS2304 on `x`.
                            is ImportEqualsDeclaration -> globalAugmentationNames.add(inner.name.text)
                            // B555: `declare global { namespace X { ... } }` introduces global `X`
                            // (a value namespace) — register it so a bare `X.member` reference does
                            // not fall through to the UMD-global TS2686 reporter (exportAsNamespace_augment).
                            is ModuleDeclaration -> (inner.name as? Identifier)?.text?.let { globalAugmentationNames.add(it) }
                            else -> {}
                        }
                    }
                }
            } else if (stmt is ModuleDeclaration) {
                // Recurse into nested modules — `declare module "X" { global { ... } }` etc.
                val body = stmt.body
                if (body is ModuleBlock) collectGlobalAugmentationNames(body.statements)
            }
        }
    }

    /**
     * Build per-file type maps containing types for all file-level declarations.
     * These maps enable getTypeOfIdentifier to resolve file-level names across all
     * checker passes, not just during the TS2322 walk.
     */
    private fun buildFileLocalTypeMaps() {
        FltmDefer.resetCounters()
        if (FltmCensus.on) FltmCensus.beginSetup()
        val eager = FltmDefer.eager
        if (eager.isNotEmpty()) {
            // (INC.25) THE SHIPPED SCOPE IS `PARTITION`, and it is a strict no-op on
            // any build that has no partition: `checkedResults` **IS**
            // `binderResults` when `assignedFileNames` is null, so a full compile
            // builds every file's map in the order it always did. What a NARROWED
            // build skips — 69.16 ms of a 90.15 ms floor pass table — is rebuilt on
            // demand by [fileLocalTypeMapFor], with the SAME content (pinned by
            // [fileLocalTypeMapSnapshot], because "eventually built" is not the
            // invariant that matters here). `Scope.PROGRAM` is the pre-(INC.25) arm.
            for (result in
                if (FltmDefer.scope == FltmDefer.Scope.PARTITION) checkedResults
                else binderResults
            ) {
                buildFileLocalTypeMapPhases(result, eager)
                FltmDefer.eagerBuilds++
            }
        }
        if (FltmCensus.on) FltmCensus.endSetup()
    }

    /**
     * (INC.24) A READ-ONLY view of one file's finished map, for the pins alone.
     *
     * The soundness of ANY change to how [buildFileLocalTypeMaps] is scoped is not
     * that a file's map is eventually built but that it is built with the SAME
     * CONTENT: (INC.11) measured that simply not resolving these declarations loses
     * 321 resolutions to `any`, which is a WRONG answer and not a missing one.
     * Nothing in a diagnostic, an emitted byte or a `cost_gate.py` counter can see
     * that difference — the one reader's own fallback chain resolves most names
     * anyway — so the only instrument is the map itself, compared between one build
     * and another.
     *
     * Rendered to strings because a `Type` instance is minted per build and its
     * identity is meaningless across two of them. Deliberately does NOT build: it
     * reports what the build under test left behind, so a pin cannot manufacture the
     * entry it is asserting.
     */
    internal fun fileLocalTypeMapSnapshot(fileName: String): Map<String, String>? =
        fileLocalTypeMaps[fileName]?.mapValues { (_, type) -> typeToString(type) }

    /**
     * (INC.11) The map's ONE reader goes through here, so a phase the `init` pass
     * did not run is built the first time this file's names are asked about.
     *
     * When [FltmDefer.armed] is false — the shipped default — this is a static
     * boolean read and the map behaves exactly as the eager pass left it.
     */
    private fun fileLocalTypeMapFor(fileName: String): Map<String, Type>? {
        if (fltmLazyArmed) ensureFileLocalTypeMap(fileName)
        return fileLocalTypeMaps[fileName]
    }

    /**
     * Builds whatever phases this file is still missing. Re-entrant by
     * construction: the build calls `getTypeOfSymbol`, which reaches
     * [getTypeOfIdentifier], which reaches this — so a file already under
     * construction answers with the partial map rather than recursing.
     */
    private fun ensureFileLocalTypeMap(fileName: String) {
        val done = fileLocalTypeMapPhases[fileName]
        if (done != null && done.size == 3) return
        if (fileName in fltmBuildInProgress) return
        val result = fileResults[fileName] ?: return
        fltmBuildInProgress.add(fileName)
        try {
            buildFileLocalTypeMapPhases(result, FltmDefer.Phases.ALL)
            FltmDefer.lazyBuilds++
        } finally {
            fltmBuildInProgress.remove(fileName)
        }
    }

    /**
     * One file's map, restricted to the phases in [want] that it does not already
     * carry. Merges into whatever an earlier phase left, so an eager `DECL` pass
     * and a lazy `VAR` build compose into the map the un-phased pass produced.
     */
    private fun buildFileLocalTypeMapPhases(result: BinderResult, want: Set<FltmDefer.Phase>) {
            val fileName = result.sourceFile.fileName
            val done = fileLocalTypeMapPhases.getOrPut(fileName) { HashSet() }
            val todo = want - done
            if (todo.isEmpty()) return
            val source = result.sourceFile.text
            val carried = fileLocalTypeMaps[fileName]
            val typeMap: MutableMap<String, Type> =
                if (carried == null) mutableMapOf() else HashMap(carried)
            for ((name, symbol) in result.locals) {
                // Only resolve types for symbols that are NOT simple variables
                // (variable inference via getTypeOfExpression can be expensive on stress tests)
                if (symbol.flags.hasAny(SymbolFlags.Function or SymbolFlags.Class or
                        SymbolFlags.Interface or SymbolFlags.Enum or SymbolFlags.TypeAlias or
                        SymbolFlags.Alias)) {
                    // (INC.11) phase split — a `TypeAlias` symbol belongs to the
                    // TYPEALIAS phase, everything else in this branch to DECL.
                    if ((if (symbol.flags.hasAny(SymbolFlags.TypeAlias))
                            FltmDefer.Phase.TYPEALIAS else FltmDefer.Phase.DECL) !in todo
                    ) continue
                    // B57.2 reverted: emitting TS2589 at type-alias body declaration
                    // produces FPs for recursive aliases that are USED safely later
                    // (e.g. inferFromNestedSameShapeTuple_ts's `type T1<T> = [number, T1<{x:T}>]`
                    // declaration shouldn't emit TS2589 — only the deep USAGE should).
                    // Save/reset to NOT propagate bail flag upward from type-alias resolutions.
                    // B57.3 (2026-05-26): exception — for CONCRETE (non-generic) type
                    // aliases whose body USES a generic alias and triggers the depth
                    // bail (e.g. `type M = N<number, "M">` where N is recursive), emit
                    // TS2589 at the alias body. Concrete aliases ARE the usage site;
                    // unlike generic-alias declarations they have no later "use" to
                    // attribute the diagnostic to.
                    val savedBail = deepInstantiationBailed
                    val savedMappedInfo = mappedTypeCircularInfo
                    deepInstantiationBailed = false
                    mappedTypeCircularInfo = null
                    // (SETUP.2) census bracket — off by default, see FltmCensus.
                    val cPrev = if (FltmCensus.on) FltmCensus.enterDirect(
                        symbol.id,
                        if (symbol.flags.hasAny(SymbolFlags.TypeAlias)) "typealias" else "decl",
                    ) else -1
                    val cT0 = if (FltmCensus.on) PassTiming.nowNanos() else 0L
                    val type = getTypeOfSymbol(symbol)
                    if (FltmCensus.on) {
                        FltmCensus.leaveDirect(symbol.id, cPrev, PassTiming.nowNanos() - cT0)
                    }
                    val taDecl = if (symbol.flags.hasAny(SymbolFlags.TypeAlias))
                        symbol.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                        else null
                    if (deepInstantiationBailed && taDecl != null && taDecl.typeParameters.isNullOrEmpty()) {
                        emitTs2589AtTypeNode(taDecl.type, source, fileName)
                        // B57.3c: pair TS2615 alongside TS2589 when the bail
                        // originated in a mapped-type recursion that produced
                        // a "circular self-reference" shape.
                        val info = mappedTypeCircularInfo
                        if (info != null) {
                            emitTs2615AtTypeNode(taDecl.type, info.first, info.second, source, fileName)
                        }
                    }
                    mappedTypeCircularInfo = savedMappedInfo
                    deepInstantiationBailed = savedBail
                    if (type !== anyType && type !== errorType) {
                        typeMap[name] = type
                        if (FltmCensus.on) FltmCensus.noteStored(fileName, name, symbol.id)
                    }
                } else if (symbol.flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property)) {
                    if (FltmDefer.Phase.VAR !in todo) continue
                    // For variables, only resolve if they have a type annotation (cheap)
                    val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
                    val annotation: TypeNode? = when (decl) {
                        is VariableDeclaration -> decl.type
                        is Parameter -> decl.type
                        is PropertyDeclaration -> decl.type
                        else -> null
                    }
                    if (annotation != null) {
                        // B57.1: detect TS2589 depth bail at annotation resolution.
                        // Save flag, reset, resolve. If bail fires, emit TS2589 at
                        // annotation position.
                        val savedBail = deepInstantiationBailed
                        val savedMappedInfo = mappedTypeCircularInfo
                        deepInstantiationBailed = false
                        mappedTypeCircularInfo = null
                        // (SETUP.2) census bracket — off by default, see FltmCensus.
                        val cPrev = if (FltmCensus.on) FltmCensus.enterDirect(symbol.id, "var") else -1
                        val cT0 = if (FltmCensus.on) PassTiming.nowNanos() else 0L
                        val type = getTypeOfSymbol(symbol)
                        if (FltmCensus.on) {
                            FltmCensus.leaveDirect(symbol.id, cPrev, PassTiming.nowNanos() - cT0)
                        }
                        if (deepInstantiationBailed) {
                            emitTs2589AtTypeNode(annotation, source, fileName)
                            // B57.3c: pair TS2615 alongside TS2589 when the bail
                            // originated in a mapped-type recursion.
                            val info = mappedTypeCircularInfo
                            if (info != null) {
                                emitTs2615AtTypeNode(annotation, info.first, info.second, source, fileName)
                            }
                        }
                        mappedTypeCircularInfo = savedMappedInfo
                        deepInstantiationBailed = savedBail
                        if (type !== anyType && type !== errorType) {
                            typeMap[name] = type
                            if (FltmCensus.on) FltmCensus.noteStored(fileName, name, symbol.id)
                        }
                    }
                }
            }
            done.addAll(todo)
            if (typeMap.isNotEmpty()) {
                fileLocalTypeMaps[fileName] = typeMap
            }
    }

    private fun trackReferencesInStatements(statements: List<Statement>, result: BinderResult) {
        for (stmt in statements) {
            trackReferencesInStatement(stmt, result)
        }
    }

    private fun trackReferencesInStatement(stmt: Statement, result: BinderResult) {
        when (stmt) {
            // Skip type-only declarations (no value references inside)
            is InterfaceDeclaration -> return
            is TypeAliasDeclaration -> return
            // Skip declare statements (ambient — no runtime)
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // Walk body for value references
                stmt.body?.let { trackReferencesInStatements(it.statements, result) }
                // Walk parameter initializers
                for (param in stmt.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                    // Decorators are value references
                    param.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                }
                // Decorators on the function itself are irrelevant (only classes/methods have them)
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // extends clause is a value reference
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (type in clause.types) {
                            trackReferencesInExpression(type.expression, result)
                        }
                    }
                    // implements clause is type-only — skip
                }
                // Decorators are value references
                stmt.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                // Walk class members
                for (member in stmt.members) {
                    trackReferencesInClassElement(member, result)
                }
            }
            is EnumDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                // Enum member initializers are value references
                for (member in stmt.members) {
                    member.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                when (val body = stmt.body) {
                    is ModuleBlock -> trackReferencesInStatements(body.statements, result)
                    is ModuleDeclaration -> trackReferencesInStatement(body, result)
                    else -> {}
                }
            }
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is ExpressionStatement -> {
                trackReferencesInExpression(stmt.expression, result)
            }
            is ReturnStatement -> {
                stmt.expression?.let { trackReferencesInExpression(it, result) }
            }
            is IfStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.thenStatement, result)
                stmt.elseStatement?.let { trackReferencesInStatement(it, result) }
            }
            is Block -> trackReferencesInStatements(stmt.statements, result)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { trackReferencesInExpression(it, result) }
                        }
                    }
                    is Expression -> trackReferencesInExpression(init, result)
                    else -> {}
                }
                stmt.condition?.let { trackReferencesInExpression(it, result) }
                stmt.incrementor?.let { trackReferencesInExpression(it, result) }
                trackReferencesInStatement(stmt.statement, result)
            }
            is ForInStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is ForOfStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is WhileStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is DoStatement -> {
                trackReferencesInStatement(stmt.statement, result)
                trackReferencesInExpression(stmt.expression, result)
            }
            is SwitchStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            trackReferencesInExpression(clause.expression, result)
                            trackReferencesInStatements(clause.statements, result)
                        }
                        is DefaultClause -> {
                            trackReferencesInStatements(clause.statements, result)
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> {
                stmt.expression?.let { trackReferencesInExpression(it, result) }
            }
            is TryStatement -> {
                trackReferencesInStatements(stmt.tryBlock.statements, result)
                stmt.catchClause?.let {
                    trackReferencesInStatements(it.block.statements, result)
                }
                stmt.finallyBlock?.let {
                    trackReferencesInStatements(it.statements, result)
                }
            }
            is LabeledStatement -> {
                trackReferencesInStatement(stmt.statement, result)
            }
            is WithStatement -> {
                trackReferencesInExpression(stmt.expression, result)
                trackReferencesInStatement(stmt.statement, result)
            }
            is ExportDeclaration -> {
                // export { X } — X is a value reference if not type-only
                if (!stmt.isTypeOnly) {
                    when (val clause = stmt.exportClause) {
                        is NamedExports -> {
                            for (spec in clause.elements) {
                                if (!spec.isTypeOnly) {
                                    val name = spec.propertyName?.text ?: spec.name.text
                                    markAliasReferenced(name, result)
                                }
                            }
                        }
                        else -> {}
                    }
                }
            }
            is ExportAssignment -> {
                trackReferencesInExpression(stmt.expression, result)
            }
            is ImportDeclaration -> { /* imports don't create value references */ }
            is ImportEqualsDeclaration -> { /* handled separately */ }
            else -> { /* other statements */ }
        }
    }

    private fun trackReferencesInClassElement(element: ClassElement, result: BinderResult) {
        when (element) {
            is PropertyDeclaration -> {
                if (ModifierFlag.Declare !in element.modifiers) {
                    element.initializer?.let { trackReferencesInExpression(it, result) }
                }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is MethodDeclaration -> {
                if (ModifierFlag.Declare !in element.modifiers) {
                    element.body?.let { trackReferencesInStatements(it.statements, result) }
                    for (param in element.parameters) {
                        param.initializer?.let { trackReferencesInExpression(it, result) }
                        param.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                    }
                }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is Constructor -> {
                element.body?.let { trackReferencesInStatements(it.statements, result) }
                for (param in element.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                    param.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
                }
            }
            is GetAccessor -> {
                element.body?.let { trackReferencesInStatements(it.statements, result) }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is SetAccessor -> {
                element.body?.let { trackReferencesInStatements(it.statements, result) }
                element.decorators?.forEach { trackReferencesInExpression(it.expression, result) }
            }
            is ClassStaticBlockDeclaration -> {
                trackReferencesInStatements(element.body.statements, result)
            }
            else -> { /* IndexSignature, SemicolonClassElement — no value refs */ }
        }
    }

    private fun trackReferencesInExpression(expr: Expression, result: BinderResult) {
        when (expr) {
            is Identifier -> {
                markAliasReferenced(expr.text, result)
            }
            is PropertyAccessExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is ElementAccessExpression -> {
                trackReferencesInExpression(expr.expression, result)
                trackReferencesInExpression(expr.argumentExpression, result)
            }
            is CallExpression -> {
                trackReferencesInExpression(expr.expression, result)
                for (arg in expr.arguments) {
                    trackReferencesInExpression(arg, result)
                }
            }
            is NewExpression -> {
                trackReferencesInExpression(expr.expression, result)
                expr.arguments?.forEach { trackReferencesInExpression(it, result) }
            }
            is BinaryExpression -> {
                // Iterative traversal to avoid StackOverflow on deeply nested binaries
                var current: Expression = expr
                while (current is BinaryExpression) {
                    trackReferencesInExpression(current.right, result)
                    current = current.left
                }
                trackReferencesInExpression(current, result)
            }
            is ConditionalExpression -> {
                trackReferencesInExpression(expr.condition, result)
                trackReferencesInExpression(expr.whenTrue, result)
                trackReferencesInExpression(expr.whenFalse, result)
            }
            is PrefixUnaryExpression -> {
                trackReferencesInExpression(expr.operand, result)
            }
            is PostfixUnaryExpression -> {
                trackReferencesInExpression(expr.operand, result)
            }
            is ParenthesizedExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is ArrayLiteralExpression -> {
                for (element in expr.elements) {
                    trackReferencesInExpression(element, result)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            trackReferencesInExpression(prop.initializer, result)
                            val propName = prop.name
                            if (propName is ComputedPropertyName) {
                                trackReferencesInExpression(propName.expression, result)
                            }
                        }
                        is ShorthandPropertyAssignment -> {
                            markAliasReferenced(prop.name.text, result)
                        }
                        is SpreadAssignment -> {
                            trackReferencesInExpression(prop.expression, result)
                        }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> trackReferencesInStatements(body.statements, result)
                    is Expression -> trackReferencesInExpression(body, result)
                    else -> {}
                }
                for (param in expr.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is FunctionExpression -> {
                trackReferencesInStatements(expr.body.statements, result)
                for (param in expr.parameters) {
                    param.initializer?.let { trackReferencesInExpression(it, result) }
                }
            }
            is ClassExpression -> {
                expr.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (type in clause.types) {
                            trackReferencesInExpression(type.expression, result)
                        }
                    }
                }
                for (member in expr.members) {
                    trackReferencesInClassElement(member, result)
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    trackReferencesInExpression(span.expression, result)
                }
            }
            is TaggedTemplateExpression -> {
                trackReferencesInExpression(expr.tag, result)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        for (span in template.templateSpans) {
                            trackReferencesInExpression(span.expression, result)
                        }
                    }
                    else -> {}
                }
            }
            is SpreadElement -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is AwaitExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is YieldExpression -> {
                expr.expression?.let { trackReferencesInExpression(it, result) }
            }
            is DeleteExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is TypeOfExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is VoidExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is AsExpression -> {
                // The expression part is a value reference, but the type part is not
                trackReferencesInExpression(expr.expression, result)
            }
            is SatisfiesExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is NonNullExpression -> {
                trackReferencesInExpression(expr.expression, result)
            }
            is TypeAssertionExpression -> {
                // <Type>expr — expr is a value reference
                trackReferencesInExpression(expr.expression, result)
            }
            is CommaListExpression -> {
                for (e in expr.elements) {
                    trackReferencesInExpression(e, result)
                }
            }
            is MetaProperty -> { /* import.meta, new.target — no named references */ }
            // Literals — no references
            is StringLiteralNode -> {}
            is NumericLiteralNode -> {}
            is BigIntLiteralNode -> {}
            is RegularExpressionLiteralNode -> {}
            is NoSubstitutionTemplateLiteralNode -> {}
            is OmittedExpression -> {}
            // Binding patterns (in destructuring expressions)
            is ObjectBindingPattern -> {}
            is ArrayBindingPattern -> {}
            is ComputedPropertyName -> {
                trackReferencesInExpression(expr.expression, result)
            }
            // JSX expressions
            is JsxElement -> {
                // The JSX factory namespace (e.g. React) is implicitly used for all JSX elements
                markJsxFactoryReferenced(result)
                trackReferencesInExpression(expr.openingElement.tagName, result)
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { trackReferencesInExpression(it, result) }
                    } else if (child is Expression) {
                        trackReferencesInExpression(child, result)
                    }
                }
            }
            is JsxSelfClosingElement -> {
                // The JSX factory namespace (e.g. React) is implicitly used for all JSX elements
                markJsxFactoryReferenced(result)
                trackReferencesInExpression(expr.tagName, result)
                for (attr in expr.attributes) {
                    when (attr) {
                        is JsxAttribute -> {
                            val v = attr.value
                            if (v is JsxExpressionContainer) {
                                v.expression?.let { trackReferencesInExpression(it, result) }
                            } else if (v is Expression) {
                                trackReferencesInExpression(v, result)
                            }
                        }
                        is JsxSpreadAttribute -> trackReferencesInExpression(attr.expression, result)
                        else -> {}
                    }
                }
            }
            is JsxFragment -> {
                // The JSX factory namespace (e.g. React) is implicitly used for all JSX elements
                markJsxFactoryReferenced(result)
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { trackReferencesInExpression(it, result) }
                    } else if (child is Expression) {
                        trackReferencesInExpression(child, result)
                    }
                }
            }
        }
    }

    /**
     * Mark an alias symbol as referenced if the given name resolves to an import.
     */
    private fun markAliasReferenced(name: String, result: BinderResult) {
        val symbol = result.locals[name] ?: return
        if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            referencedAliases.add(symbol.id)
        }
    }

    /**
     * Mark the JSX factory namespace import as referenced.
     * When a file uses JSX elements, the JSX factory namespace (default: "React") is
     * implicitly used at runtime, so its import must not be elided.
     * This applies for all JSX modes including "preserve".
     */
    private fun markJsxFactoryReferenced(result: BinderResult) {
        if (options.jsx == null) return
        // Determine the factory namespace: first dotted segment of jsxFactory, or reactNamespace, or "React"
        val factoryNamespace = when {
            options.jsxFactory != null -> options.jsxFactory.substringBefore('.')
            options.reactNamespace != null -> options.reactNamespace
            else -> "React"
        }
        markAliasReferenced(factoryNamespace, result)
    }

    // -----------------------------------------------------------------------
    // Symbol resolution helpers
    // -----------------------------------------------------------------------

    private fun resolveIdentifierInFile(name: String, contextNode: Node): Symbol? {
        for (result in binderResults) {
            val symbol = result.locals[name]
            if (symbol != null) return symbol
        }
        return globals[name]
    }

    /**
     * M3.4 (round 409): ESM `.js`-tolerant module resolution for the FLOW-ONLY
     * [resolveImportedFunctionLikeDecl]. tsc's own sources (and any nodenext
     * project) import via `.js`/`.jsx`/`.mjs`/`.cjs` specifiers that point at
     * `.ts`/`.tsx` sources; [resolveModuleSpecifier] deliberately will NOT strip
     * those (CLAUDE.md — TS2459 FP-avoidance), so a barrel-imported guard's module
     * could not be resolved at all (the reason round 408's guard-narrowing wire was
     * inert). Retry with the extension stripped — directory-relative to
     * [contextFile] first (nested layouts), then globally (flat corpus layouts).
     */
    private fun resolveAliasJsModuleSpecifier(specifier: String, contextFile: String?): String? {
        for (ext in listOf(".js", ".jsx", ".mjs", ".cjs")) {
            if (!specifier.endsWith(ext)) continue
            val stripped = specifier.removeSuffix(ext)
            if (contextFile != null) resolveModuleSpecifierRelative(stripped, contextFile)?.let { return it }
            resolveModuleSpecifier(stripped)?.let { return it }
        }
        return null
    }

    /**
     * (CHK.30) round 949 — the LAST-RESORT leg of every import-alias target
     * resolution, and the reason a type imported from a `node_modules` package used
     * to be `any`.
     *
     * [resolveModuleSpecifier] and its relative siblings are the corpus-era string
     * matchers: they look a specifier up among the [fileResults] KEYS, and the
     * non-relative form deliberately refuses `.d.ts` (so `foo` cannot capture an
     * ambient `foo.d.ts`). That is right for a flat fixture layout and leaves a real
     * project with NO resolution at all for `import type { V } from 'pkg'` — a
     * package's `types` / `main` / `exports` entry is not a string transformation of
     * the specifier. The alias then resolved to nothing and every type it named
     * degraded to `any`.
     *
     * **Nothing in this repo could see it.** `any` is legal everywhere, so no
     * diagnostic MOVES at the import; what surfaces is the false-positive SHADOW —
     * a TS7006 on every un-annotated callback parameter whose contextual type lived
     * in that package (89 of knip's 156 residual rows, which is what (CHK.30) was
     * opened about and mis-attributed to contextual typing).
     *
     * So this answers from [moduleResolutions] — what the project crawl's real
     * `ModuleResolver` already decided for this exact `(importer, specifier)` pair —
     * and from nothing else. It is APPENDED after every existing leg at each of the
     * ten alias ladders, so it can only make MORE specifiers resolve and never
     * redirect one that already resolved, and a corpus fixture cannot reach it at all
     * (the map is empty off the project path).
     *
     * **AND IT IS DELIBERATELY THE ONLY SOURCE.** The first cut also consulted the
     * `node_modules` walkers ~15 other checker sites use ([resolveBareNodeModulesAnyPrefix],
     * [resolveBareViaPackageExportsRoot]); ablating those legs away is **0 RED across
     * the whole 15,883-test suite**, because wherever they could answer the crawl has
     * already answered better. Re-adding them would be shipping a leg no gate here
     * can fail.
     *
     * The [fileResults] guard is not cosmetic: the crawl also pulls in `.json` and
     * un-bound `.js` files, which have no binder result for a caller to read an
     * export out of.
     */
    private fun resolveImportTargetFallback(spec: String, contextFile: String?): String? {
        if (contextFile == null || spec.isEmpty() || moduleResolutions.isEmpty()) return null
        val target = moduleResolutions[contextFile]?.get(spec) ?: return null
        return if (target in fileResults) target else null
    }

    private fun resolveAlias(symbol: Symbol, visited: MutableSet<Int> = mutableSetOf()): Symbol {
        if (!visited.add(symbol.id)) return symbol // cycle detected
        getSymbolTarget(symbol)?.let { return resolveAlias(it, visited) }
        // For import aliases, try to resolve the target
        if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            for (decl in symbol.declarations) {
                when (decl) {
                    is ImportEqualsDeclaration -> {
                        val ref = decl.moduleReference
                        when (ref) {
                            is QualifiedName -> {
                                val target = resolveQualifiedName(ref) ?: continue
                                setSymbolTarget(symbol, target)
                                return resolveAlias(target, visited)
                            }
                            is Identifier -> {
                                val target = globals[ref.text] ?: continue
                                setSymbolTarget(symbol, target)
                                return resolveAlias(target, visited)
                            }
                            is ExternalModuleReference -> {
                                // import A = require("mod") — resolve module then its export
                                val specifier = (ref.expression as? StringLiteralNode)?.text ?: continue
                                val targetFile = resolveModuleSpecifier(specifier, decl)
                                if (targetFile == null) {
                                    // B113: AMBIENT module — `declare module "mod1" { ... }` is
                                    // bound (Binder) under a symbol whose name == the specifier
                                    // string, merged into globals at checker init. It is NOT a
                                    // file, so resolveModuleSpecifier returns null. Resolve the
                                    // alias to that ambient module symbol so `import m1 =
                                    // require("mod1"); var x: m1.Foo` finds mod1's exported Foo.
                                    val ambient = globals[specifier]
                                    if (ambient != null && ambient.flags.hasAny(SymbolFlags.Module) &&
                                        ambient.exports != null) {
                                        setSymbolTarget(symbol, ambient)
                                        return resolveAlias(ambient, visited)
                                    }
                                    continue
                                }
                                val targetResult = fileResults[targetFile] ?: continue
                                // Look for export = X in the target module
                                val exportTarget = resolveModuleExportAssignment(targetResult, visited)
                                if (exportTarget != null) {
                                    setSymbolTarget(symbol, exportTarget)
                                    return resolveAlias(exportTarget, visited)
                                }
                                // No export = found — create module symbol
                                val moduleSymbol = createModuleSymbol(symbol.name, targetResult)
                                setSymbolTarget(symbol, moduleSymbol)
                                return moduleSymbol
                            }
                            else -> {}
                        }
                    }
                    is ImportDeclaration -> {
                        val specifier = (decl.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                        // Round 512 (the round-511 dir-relative lesson): the bare
                        // resolver only knows flat corpus-style keys — a path-shaped
                        // layout (`/proj/src/a.ts` importing `./b`) needs the
                        // directory-relative leg or the alias never resolves on
                        // real on-disk projects.
                        val targetFile = resolveModuleSpecifier(specifier, decl)
                            ?: owningSourceFile(decl)?.fileName?.let {
                                resolveModuleSpecifierRelative(specifier, it)
                            } ?: continue
                        val targetResult = fileResults[targetFile] ?: continue

                        // Namespace import: import * as Foo from "mod"
                        val namedBindings = decl.importClause?.namedBindings
                        if (namedBindings is NamespaceImport) {
                            val moduleSymbol = createModuleSymbol(symbol.name, targetResult)
                            setSymbolTarget(symbol, moduleSymbol)
                            return moduleSymbol
                        }

                        // Default import: import Foo from "mod"
                        if (decl.importClause?.name != null &&
                            symbol.name == decl.importClause.name.text) {
                            // Look for "default" export in target — first check locals["default"]
                            val defaultSymbol = targetResult.locals["default"]
                            if (defaultSymbol != null) {
                                setSymbolTarget(symbol, defaultSymbol)
                                return resolveAlias(defaultSymbol, visited)
                            }
                            // `export default function f() {}` / `export default class C {}`.
                            // A DECLARATION carrying both modifiers is neither an
                            // ExportAssignment nor bound under the name "default" — it is
                            // bound under its OWN — so every leg around this one misses it
                            // and the alias used to resolve to nothing, i.e. to `any`.
                            // SILENTLY: `any` is assignable to everything, so a program
                            // importing a default-exported function type-checked and every
                            // misuse of it went unreported (measured against tsgo 7.0.2,
                            // which reports TS2322 for the same two files).
                            for (stmt in targetResult.sourceFile.statements) {
                                val defaultName = when {
                                    stmt is FunctionDeclaration &&
                                        ModifierFlag.Export in stmt.modifiers &&
                                        ModifierFlag.Default in stmt.modifiers -> stmt.name?.text
                                    stmt is ClassDeclaration &&
                                        ModifierFlag.Export in stmt.modifiers &&
                                        ModifierFlag.Default in stmt.modifiers -> stmt.name?.text
                                    else -> null
                                } ?: continue
                                val exported = targetResult.locals[defaultName] ?: continue
                                setSymbolTarget(symbol, exported)
                                return resolveAlias(exported, visited)
                            }
                            // Scan for `export default X` (ExportAssignment without isExportEquals)
                            for (stmt in targetResult.sourceFile.statements) {
                                if (stmt is ExportAssignment && !stmt.isExportEquals) {
                                    val resolved = resolveExpressionToSymbol(stmt.expression, targetResult, visited)
                                    if (resolved != null) {
                                        setSymbolTarget(symbol, resolved)
                                        return resolveAlias(resolved, visited)
                                    }
                                }
                            }
                            // Scan for `export { X as default } from "mod"` re-exports
                            for (stmt in targetResult.sourceFile.statements) {
                                if (stmt is ExportDeclaration) {
                                    val clause = stmt.exportClause
                                    if (clause is NamedExports) {
                                        val defaultSpec = clause.elements.find { it.name.text == "default" }
                                        if (defaultSpec != null) {
                                            val originalName = defaultSpec.propertyName?.text ?: "default"
                                            val fromSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text
                                            val resolvedTarget: Symbol? = if (fromSpec != null) {
                                                val fromFile = resolveModuleSpecifier(fromSpec, stmt)
                                                val fromResult = fromFile?.let { fileResults[it] }
                                                fromResult?.locals?.get(originalName)
                                            } else {
                                                targetResult.locals[originalName]
                                            }
                                            if (resolvedTarget != null) {
                                                setSymbolTarget(symbol, resolvedTarget)
                                                return resolveAlias(resolvedTarget, visited)
                                            }
                                        }
                                    }
                                }
                            }
                            // Fallback: `export = X` is consumed as the DEFAULT import under
                            // esModuleInterop (TypeScript's synthetic-default rule — a CommonJS
                            // `export =` module is default-imported as its export-equals value).
                            // e.g. exp.ts `export = x` + imp.ts `import foo from "./exp"` → foo is x.
                            // Gated to esModuleInterop (default true) since without it the default
                            // import of an `export =` module is a TS1259 error, not a value.
                            if (options.esModuleInterop) {
                                val exportEqualsTarget = resolveModuleExportAssignment(targetResult, visited)
                                if (exportEqualsTarget != null) {
                                    setSymbolTarget(symbol, exportEqualsTarget)
                                    return resolveAlias(exportEqualsTarget, visited)
                                }
                            }
                            continue
                        }

                        // Named import: import { X } from "mod"
                        val target = targetResult.locals[symbol.name] ?: continue
                        setSymbolTarget(symbol, target)
                        return resolveAlias(target, visited)
                    }
                    is ImportSpecifier -> {
                        // Named import — the original name to look up
                        val originalName = decl.propertyName?.text ?: decl.name.text
                        // Find the ImportDeclaration parent for this specifier via the
                        // prebuilt index (no parent pointers; round 432 — was a
                        // program-wide structural scan re-run on every call for
                        // unresolvable barrel aliases).
                        for ((_, stmt) in enclosingImportsOf(decl)) {
                            val specifier2 = (stmt.moduleSpecifier as? StringLiteralNode)?.text
                                ?: continue
                            // Round 512 (the round-511 dir-relative lesson): the bare
                            // resolver only knows flat corpus-style keys — path-shaped
                            // on-disk layouts need the directory-relative leg.
                            val targetFile2 = resolveModuleSpecifier(specifier2, stmt)
                                ?: owningSourceFile(stmt)?.fileName?.let {
                                    resolveModuleSpecifierRelative(specifier2, it)
                                }
                            if (targetFile2 == null) {
                                // Ambient module fallback — `declare module "X"` in a .d.ts file.
                                val ambient = globals[specifier2]
                                if (ambient != null && ambient.flags.hasAny(SymbolFlags.Module)) {
                                    ambient.exports?.get(originalName)?.let { target ->
                                        setSymbolTarget(symbol, target)
                                        return resolveAlias(target, visited)
                                    }
                                    // Fallback: ambient module body has `export = X`
                                    // (e.g. `import alias = demoNS; export = alias`) —
                                    // resolve X then look up `originalName` in X's exports.
                                    val exportEqualsTarget = resolveAmbientModuleExportEquals(ambient, visited)
                                    if (exportEqualsTarget != null) {
                                        exportEqualsTarget.exports?.get(originalName)?.let { target ->
                                            setSymbolTarget(symbol, target)
                                            return resolveAlias(target, visited)
                                        }
                                    }
                                }
                                continue
                            }
                            val targetResult2 = fileResults[targetFile2] ?: continue
                            val target = targetResult2.locals[originalName] ?: continue
                            setSymbolTarget(symbol, target)
                            return resolveAlias(target, visited)
                        }
                    }
                    else -> {}
                }
            }
        }
        return symbol
    }

    /**
     * Resolve a module's export assignment (`export = expr`) to a symbol.
     * Returns null if no export assignment exists.
     */
    private fun resolveModuleExportAssignment(result: BinderResult, visited: MutableSet<Int> = mutableSetOf()): Symbol? {
        for (stmt in result.sourceFile.statements) {
            if (stmt is ExportAssignment && stmt.isExportEquals) {
                return resolveExpressionToSymbol(stmt.expression, result, visited)
            }
        }
        return null
    }

    /**
     * Resolve an ambient module symbol's `export = X` to the target symbol.
     * Walks the module's [ModuleDeclaration] body for an [ExportAssignment]
     * with `isExportEquals=true`, then resolves the expression — looking up
     * Identifiers in the module's own exports first (so `import alias = X;
     * export = alias` works) before falling back to globals.
     * Returns null if no export-equals exists or the target can't be resolved.
     */
    private fun resolveAmbientModuleExportEquals(moduleSym: Symbol, visited: MutableSet<Int>): Symbol? {
        for (decl in moduleSym.declarations) {
            if (decl !is ModuleDeclaration) continue
            val body = decl.body as? ModuleBlock ?: continue
            for (stmt in body.statements) {
                if (stmt is ExportAssignment && stmt.isExportEquals) {
                    return resolveExpressionInAmbientModule(stmt.expression, moduleSym, visited)
                }
            }
        }
        return null
    }

    private fun resolveExpressionInAmbientModule(expr: Expression, moduleSym: Symbol, visited: MutableSet<Int>): Symbol? {
        return when (expr) {
            is Identifier -> {
                val sym = moduleSym.exports?.get(expr.text) ?: globals[expr.text] ?: return null
                resolveAlias(sym, visited)
            }
            is PropertyAccessExpression -> {
                val parent = resolveExpressionInAmbientModule(expr.expression, moduleSym, visited) ?: return null
                val child = parent.exports?.get(expr.name.text) ?: return null
                resolveAlias(child, visited)
            }
            else -> null
        }
    }

    /**
     * Resolve an expression to a symbol (for export assignment resolution).
     */
    private fun resolveExpressionToSymbol(expr: Expression, result: BinderResult, visited: MutableSet<Int> = mutableSetOf()): Symbol? {
        return when (expr) {
            is Identifier -> {
                // 17.32d: identifiers inside `export default X` / `export = X`
                // resolve against the target file's per-file scope (lib +
                // script-file locals + own-file locals) instead of the
                // over-merged [globals] map. Other module files' locals are
                // not visible without an explicit import. Defensive fallback
                // to [globals] when [perFileScope] hasn't been built yet
                // (matches 17.32b/c pattern).
                val fileScope = perFileScopeOf(result.sourceFile.fileName)
                val symbol = result.locals[expr.text]
                    ?: fileScope?.get(expr.text)
                    ?: (if (fileScope == null) globals[expr.text] else null)
                    ?: return null
                resolveAlias(symbol, visited)
            }
            is PropertyAccessExpression -> {
                val parent = resolveExpressionToSymbol(expr.expression, result, visited) ?: return null
                val child = parent.exports?.get(expr.name.text) ?: return null
                resolveAlias(child, visited)
            }
            else -> null
        }
    }

    /**
     * Create a synthetic module symbol whose exports are the target file's effective exports.
     * For `.d.ts` files with ambient module declarations (`declare module "foo" {...}`), the
     * exports come from the inner ambient module, not from file-level locals.
     * For regular `.ts` files, uses the file-level locals directly.
     */
    private fun createModuleSymbol(name: String, targetResult: BinderResult): Symbol {
        val moduleSymbol = Symbol(
            name = name,
            flags = SymbolFlags.Module,
        )
        // For .d.ts files, check if there's a single ambient module declaration.
        // If so, use its exports rather than the file-level locals.
        val targetFile = targetResult.sourceFile.fileName
        if (targetFile.endsWith(".d.ts")) {
            val ambientModules = targetResult.sourceFile.statements
                .filterIsInstance<ModuleDeclaration>()
                .filter { ModifierFlag.Declare in it.modifiers }
            if (ambientModules.size == 1) {
                val ambientSymbol = targetResult.locals[when (val n = ambientModules[0].name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> ""
                }]
                if (ambientSymbol != null && ambientSymbol.exports != null) {
                    moduleSymbol.exports = ambientSymbol.exports
                    return moduleSymbol
                }
            }
        }
        moduleSymbol.exports = targetResult.locals
        return moduleSymbol
    }

    /**
     * Resolve a QualifiedName (e.g., A.B.C.E) to a symbol by walking the namespace chain.
     */
    /**
     * Resolve an expression to an enum symbol for enum member access.
     * Handles nested namespace access like A.B.C.E → the symbol for enum E.
     */
    private fun resolveEnumExpression(expr: Expression, currentEnumName: String): Symbol? {
        return when (expr) {
            is Identifier -> {
                val symbol = globals[expr.text] ?: return null
                resolveAlias(symbol)
            }
            is PropertyAccessExpression -> {
                val parent = resolveEnumExpression(expr.expression, currentEnumName) ?: return null
                val child = parent.exports?.get(expr.name.text) ?: return null
                resolveAlias(child)
            }
            else -> null
        }
    }

    /**
     * Resolve a dotted name path (e.g., "A.B.C.E") to a symbol by walking the namespace chain.
     */
    private fun resolveNamePath(path: String, result: BinderResult): Symbol? {
        val parts = path.split(".")
        // First look in file-level locals, then globals
        var current = result.locals[parts[0]] ?: globals[parts[0]]
        // If not found at file level, search all namespace scopes across all files
        if (current == null && parts.size > 1) {
            current = findSymbolInAllNamespaceScopes(parts[0]) ?: return null
        }
        if (current == null) return null
        for (i in 1 until parts.size) {
            current = resolveAlias(current!!)
            current = current.exports?.get(parts[i]) ?: return null
        }
        return current
    }

    /**
     * Search all namespace export scopes in all binder results for a symbol with the given name.
     * Used when a name is only in a namespace scope (e.g., import alias inside a namespace body).
     *
     * M5 (round 481): memoized (Tier 2 — a pure function of the frozen binder tables;
     * stored null = not found). The Transformer probes resolveConstEnumMemberAccess for
     * EVERY dotted expression chain, and a head that resolves nowhere (any function-body
     * local — B83.5-unbound) fell through resolveNamePath to this full-program recursive
     * scan; ~7% of the harness JFR profile sat in this family.
     */
    private fun findSymbolInAllNamespaceScopes(name: String): Symbol? {
        namespaceScopeSymbolCache[name]?.let { return it }
        if (namespaceScopeSymbolCache.containsKey(name)) return null
        var found: Symbol? = null
        for (br in binderResults) {
            found = findSymbolInExports(name, br.locals)
            if (found != null) break
        }
        namespaceScopeSymbolCache[name] = found
        return found
    }

    private fun findSymbolInExports(name: String, scope: SymbolTable): Symbol? {
        // Check this scope directly
        val direct = scope[name]
        if (direct != null) return direct
        // Recurse into namespace exports
        for ((_, sym) in scope) {
            if (sym.flags.hasAny(SymbolFlags.NamespaceModule or SymbolFlags.ValueModule)) {
                val found = sym.exports?.let { findSymbolInExports(name, it) }
                if (found != null) return found
            }
        }
        return null
    }

    private fun resolveQualifiedName(qn: QualifiedName): Symbol? {
        val left = when (val l = qn.left) {
            // INV.3(d): node-keyed root (was the merged `globals`) — the retired
            // merge no longer holds module-file namespaces; an own/imported root
            // resolves per-file to the same declaring-file instance.
            is Identifier -> lookupPerFileForNode(l, l.text)
            is QualifiedName -> resolveQualifiedName(l)
            else -> null
        }
        if (left != null) {
            val resolved = resolveAlias(left)
            resolved.exports?.get(qn.right.text)?.let { return it }
        }
        // INV.3(d): a namespace-IMPORT-rooted chain (`ts.DocumentRegistry`,
        // `ts.server.Session`) — resolveAlias cannot follow NamespaceImports
        // (round 444) and the retired merge no longer leaks the member name;
        // resolve through the target modules' exports directly.
        return resolveNsQualifiedFromQualifiedName(qn)
    }

    /**
     * Resolve a value-position dotted name `M.C` / `A.B.C` (a chain of
     * [PropertyAccessExpression] over an [Identifier] head) to the exported symbol
     * — mirroring [resolveQualifiedName] which works on type-position
     * [QualifiedName] nodes. Used by [getReturnTypeOfNewExpression] so `new M.C()`
     * resolves to the namespace-qualified class instance type. Returns null when any
     * segment fails to resolve.
     */
    private fun resolveQualifiedValueSymbol(expr: PropertyAccessExpression): Symbol? {
        val left = when (val l = expr.expression) {
            // INV.3(d): node-keyed fallback (was the merged `globals`).
            is Identifier -> currentFileLocals?.get(l.text) ?: lookupPerFileForNode(l, l.text)
            is PropertyAccessExpression -> resolveQualifiedValueSymbol(l)
            else -> null
        } ?: return null
        val resolved = resolveAlias(left)
        return resolved.exports?.get(expr.name.text)
    }

    /**
     * Simple module specifier resolution: strip leading `./` and append `.ts` / try `.ts`.
     * This is a simplified version for the test suite where module specifiers
     * are relative paths within the same test compilation unit.
     * Also supports baseUrl-relative non-relative specifiers (e.g., "defs/cc" with baseUrl "/proj").
     */
    private fun resolveModuleSpecifier(specifier: String, contextNode: Node? = null): String? {
        // Perf (round 432): pure function of the specifier ([fileResults]/[options] are
        // fixed; contextNode is unused) — memoized incl. null results (round 432 note:
        // getOrPut would recompute the hot unresolvable-specifier case every call).
        // Single-lookup via the sentinel (round 483): null is the hot result.
        moduleSpecifierCache[specifier]?.let { return if (it === UNRESOLVED_MODULE_SPEC) null else it }
        val result = computeModuleSpecifier(specifier)
        moduleSpecifierCache[specifier] = result ?: UNRESOLVED_MODULE_SPEC
        return result
    }

    private fun computeModuleSpecifier(specifier: String): String? {
        val isRelative = specifier.startsWith("./") || specifier.startsWith("../")
        val baseName = specifier.removePrefix("./").removePrefix("../")
        // Try exact match first, then with extensions
        val candidates = mutableListOf(
            baseName,
            "$baseName.ts",
            "$baseName.tsx",
            "./$baseName",
            "./$baseName.ts",
            "./$baseName.tsx",
        )
        // Only try .d.ts for relative specifiers (./X or ../X) to avoid matching ambient module
        // declarations in non-relative imports like "foo" → "foo.d.ts" (which may have augmentations
        // from other files that we can't account for).
        if (isRelative) {
            candidates.add("$baseName.d.ts")
            candidates.add("./$baseName.d.ts")
        }
        // For non-relative specifiers, also try baseUrl-prefixed paths
        if (!isRelative && options.baseUrl != null) {
            val baseUrl = options.baseUrl.trimEnd('/')
            candidates.add("$baseUrl/$baseName")
            candidates.add("$baseUrl/$baseName.ts")
            candidates.add("$baseUrl/$baseName.tsx")
        }
        for (candidate in candidates) {
            if (candidate in fileResults) return candidate
        }
        // Try matching by base filename (strips common path prefix)
        for (fileName in fileResults.keys) {
            // Only strip .d.ts for relative specifiers (./X); skip .d.ts files for non-relative
            val fileBase = if (isRelative) {
                fileName.removePrefix("./").removeSuffix(".d.ts").removeSuffix(".ts").removeSuffix(".tsx")
            } else {
                fileName.removePrefix("./").removeSuffix(".ts").removeSuffix(".tsx")
            }
            if (fileBase == baseName) return fileName
            // For non-relative specifiers: check if file ends with /baseName
            if (!isRelative && (fileBase.endsWith("/$baseName") || fileBase == baseName)) return fileName
            // For relative specifiers in flat-directory absolute-path test layouts (e.g. @Filename: /foo.ts):
            // fileBase = "/foo", baseName = "foo" → fileBase == "/$baseName"
            if (isRelative && fileBase == "/$baseName") return fileName
        }
        return null
    }

    /**
     * Resolve a module specifier relative to the given context file's directory.
     * For `folder/bar.ts` importing `./foo`, resolves to `folder/foo.ts`.
     * Falls back to [resolveModuleSpecifier] if directory-relative resolution fails.
     */
    private fun resolveModuleSpecifierRelative(specifier: String, contextFileName: String): String? {
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) {
            // Non-relative: use normal resolution
            return resolveModuleSpecifier(specifier)
        }
        // Get directory of the context file
        val dir = contextFileName.substringBeforeLast('/', "")
        val resolved = if (dir.isEmpty()) specifier else "$dir/${specifier.removePrefix("./")}"
        // Normalize `..` segments
        val normalized = normalizePath(resolved)
        val candidates = listOf(
            normalized,
            "$normalized.ts",
            "$normalized.tsx",
            "$normalized.d.ts",
        )
        for (candidate in candidates) {
            if (candidate in fileResults) return candidate
        }
        // Also strip leading "./" if present for lookup
        val candidatesNoPrefix = candidates.map { it.removePrefix("./") }
        for (candidate in candidatesNoPrefix) {
            if (candidate in fileResults) return candidate
        }
        return resolveModuleSpecifier(specifier)
    }

    /**
     * [resolveModuleSpecifierRelative] that ALSO retries with a trailing ESM `.js`/`.jsx`
     * extension stripped (nodenext resolves `../compiler/types.js` → `../compiler/types.ts`).
     * The base resolver deliberately avoids `.js` globally (FP-prone per the TS2459 gotcha), so
     * callers that must be `.js`-tolerant use this. Purely additive — can only make MORE
     * specifiers resolve, never fewer — so it only ever SUPPRESSES a false-positive
     * "cannot be found" diagnostic. Consolidates the strip-and-retry pattern inlined at the
     * TS2694/TS2305/TS2307 augmentation-target sites.
     */
    private fun resolveModuleSpecifierRelativeJsAware(specifier: String, contextFileName: String): String? =
        resolveModuleSpecifierRelative(specifier, contextFileName)
            ?: (if (specifier.endsWith(".js")) resolveModuleSpecifierRelative(specifier.removeSuffix(".js"), contextFileName) else null)
            ?: (if (specifier.endsWith(".jsx")) resolveModuleSpecifierRelative(specifier.removeSuffix(".jsx"), contextFileName) else null)
            ?: (if (specifier.endsWith(".mjs")) resolveModuleSpecifierRelative(specifier.removeSuffix(".mjs"), contextFileName) else null)
            ?: (if (specifier.endsWith(".cjs")) resolveModuleSpecifierRelative(specifier.removeSuffix(".cjs"), contextFileName) else null)

    /**
     * Resolve a relative module specifier strictly relative to the context file's directory,
     * WITHOUT falling back to global (non-directory-aware) resolution.
     * Used for TS2307/TS2792 checks where directory context must be respected.
     */
    private fun resolveModuleSpecifierStrictRelative(specifier: String, contextFileName: String): String? {
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) return null
        // 17.214: Preserve a leading `/` from absolute contextFileName paths
        // (test fixtures often use `/foo.ts` style). Without this, dir
        // collapses to "" and basePath drops the leading slash so files
        // keyed in fileResults as `/bar.ts` aren't found.
        val rawDir = contextFileName.substringBeforeLast('/', "")
        val dir = if (rawDir.isEmpty() && contextFileName.startsWith("/")) "" else rawDir
        val basePath = if (dir.isEmpty()) {
            if (contextFileName.startsWith("/")) "/${specifier.removePrefix("./")}" else specifier
        } else "$dir/${specifier.removePrefix("./")}"
        val normalized = normalizePath(basePath)
        // Strip .js/.jsx extensions to allow TypeScript to resolve .ts/.tsx instead
        val withoutJs = when {
            normalized.endsWith(".js") -> normalized.removeSuffix(".js")
            normalized.endsWith(".jsx") -> normalized.removeSuffix(".jsx")
            else -> null
        }
        val candidates = buildList {
            add(normalized)
            add("$normalized.ts")
            add("$normalized.tsx")
            add("$normalized.d.ts")
            if (withoutJs != null) {
                add(withoutJs)
                add("$withoutJs.ts")
                add("$withoutJs.tsx")
                add("$withoutJs.d.ts")
            }
            add(normalized.removePrefix("./"))
            add("${normalized.removePrefix("./")}.ts")
            add("${normalized.removePrefix("./")}.tsx")
        }
        for (candidate in candidates) {
            if (candidate in fileResults) return candidate
        }
        return null
    }

    /**
     * Resolve a relative module specifier strictly relative to the context file's directory,
     * checking EVERY module-bearing extension (`.ts/.tsx/.d.ts/.js/.jsx/.json/.mts/.cts/.mjs/.cjs`),
     * both `./`-prefixed and unprefixed fileResults keys, AND node-style directory-index resolution
     * (`./foo` → `./foo/index.<ext>`). Returns null only when nothing at all matches the target.
     *
     * This is the FP-safe "does this relative specifier resolve to ANY file?" check used by the
     * node/commonjs relative-missing TS2307 gate. It is intentionally MORE permissive than
     * [resolveModuleSpecifierStrictRelative] (which only tries `.ts/.tsx/.d.ts`): a `.js`/`.jsx`
     * sibling resolves as an untyped module, a `.tsx`/`.jsx` sibling resolves (with a TS6142, not
     * TS2307), and a `./`-prefixed @filename key must still match an unprefixed normalized path.
     * Missing any of these would FP TS2307 on a module TypeScript actually resolves.
     */
    /**
     * B472: the bare `.` / `..` package-index specifiers mean "this/parent directory's
     * index"; normalize them to `./` / `../` so the relative resolvers treat them as
     * directory-index imports. Corpus-FP-safe: `importWithTrailingSlash` is the ONLY
     * corpus test importing from exactly `.` or `..`.
     */
    private fun normalizeDotDirSpecifier(specifier: String): String = when (specifier) {
        "." -> "./"
        ".." -> "../"
        else -> specifier
    }

    private fun resolveRelativeIncludingIndex(specifierIn: String, contextFileName: String): String? {
        val specifier = normalizeDotDirSpecifier(specifierIn)
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) return null
        val rawDir = contextFileName.substringBeforeLast('/', "")
        val dir = if (rawDir.isEmpty() && contextFileName.startsWith("/")) "" else rawDir
        val spec = specifier.trimEnd('/')
        val basePath = if (dir.isEmpty()) {
            if (contextFileName.startsWith("/")) "/${spec.removePrefix("./")}" else spec
        } else "$dir/${spec.removePrefix("./")}"
        val normalized = normalizePath(basePath)
        // Strip a trailing JS-ish extension so `./foo.js` can also resolve to `foo.ts`.
        val stem = when {
            normalized.endsWith(".js") -> normalized.removeSuffix(".js")
            normalized.endsWith(".jsx") -> normalized.removeSuffix(".jsx")
            normalized.endsWith(".mjs") -> normalized.removeSuffix(".mjs")
            normalized.endsWith(".cjs") -> normalized.removeSuffix(".cjs")
            else -> normalized
        }
        val exts = listOf("", ".ts", ".tsx", ".d.ts", ".js", ".jsx", ".json", ".mts", ".cts", ".mjs", ".cjs", ".d.mts", ".d.cts")
        // B472: a bare `.`/`..` specifier names the DIRECTORY itself (its index), never a
        // sibling FILE whose stem equals the dir (`.` from /a/x.ts → /a/index.ts, NOT the
        // file /a.ts). So skip the `stem`-as-file attempt for those — try `<stem>/index`
        // only. Corpus-FP-safe: only importWithTrailingSlash imports from exactly `.`/`..`.
        val stems = if (specifierIn == "." || specifierIn == "..") listOf("$stem/index")
            else listOf(stem, "$stem/index")
        for (s in stems) {
            for (e in exts) {
                val cand = "$s$e"
                if (cand in fileResults) return cand
                val noPrefix = cand.removePrefix("./")
                if (noPrefix in fileResults) return noPrefix
                val withPrefix = if (cand.startsWith("/")) cand else "./$noPrefix"
                if (withPrefix in fileResults) return withPrefix
            }
        }
        return null
    }

    /**
     * B98.r21: Does a RELATIVE [specifier] resolve to an untyped `.js`/`.jsx`/`.cjs`/`.mjs` sibling
     * that is present in the RAW input file set ([allInputFileNames]) but NOT in [fileResults]
     * (i.e. parsed-but-not-bound because `allowJs` is off)? Returns the resolved JS file path, or
     * null. TypeScript resolves such an import to an implicit-`any` module (TS7016 under
     * noImplicitAny) rather than failing it (TS2307). Mirrors the directory-context resolution of
     * [resolveRelativeIncludingIndex] but probes only JS-ish extensions against the raw set.
     */
    private fun resolveRelativeJsSibling(specifier: String, contextFileName: String): String? {
        if (allInputFileNames.isEmpty()) return null
        if (!specifier.startsWith("./") && !specifier.startsWith("../")) return null
        val rawDir = contextFileName.substringBeforeLast('/', "")
        val dir = if (rawDir.isEmpty() && contextFileName.startsWith("/")) "" else rawDir
        val spec = specifier.trimEnd('/')
        val basePath = if (dir.isEmpty()) {
            if (contextFileName.startsWith("/")) "/${spec.removePrefix("./")}" else spec
        } else "$dir/${spec.removePrefix("./")}"
        val normalized = normalizePath(basePath)
        val stem = when {
            normalized.endsWith(".js") -> normalized.removeSuffix(".js")
            normalized.endsWith(".jsx") -> normalized.removeSuffix(".jsx")
            normalized.endsWith(".mjs") -> normalized.removeSuffix(".mjs")
            normalized.endsWith(".cjs") -> normalized.removeSuffix(".cjs")
            else -> normalized
        }
        val jsExts = listOf(".js", ".jsx", ".cjs", ".mjs")
        for (s in listOf(stem, "$stem/index")) {
            for (e in jsExts) {
                val cand = "$s$e"
                if (cand in allInputFileNames && cand !in fileResults) return cand
                val noPrefix = cand.removePrefix("./")
                if (noPrefix in allInputFileNames && noPrefix !in fileResults) return noPrefix
            }
        }
        return null
    }

    /**
     * B98.r8: Does a `/// <reference path="X" />` directive's target file [refPath] resolve to a
     * file in the program (fileResults)? Reference paths are resolved relative to the containing
     * file's directory. Permissive (probes many extensions + `./`-prefix variants) so it biases
     * toward FINDING a file — a false-negative (missing a file that exists) would FP a spurious
     * TS6053, which is worse than missing a genuine TS6053. Used by [checkReferencePathsExist].
     */
    private fun referencePathResolves(refPath: String, contextFileName: String): Boolean {
        val rawDir = contextFileName.substringBeforeLast('/', "")
        val dir = if (rawDir.isEmpty() && contextFileName.startsWith("/")) "" else rawDir
        val basePath = when {
            refPath.startsWith("/") -> refPath
            dir.isEmpty() -> if (contextFileName.startsWith("/")) "/$refPath" else refPath
            else -> "$dir/$refPath"
        }
        val normalized = normalizePath(basePath)
        val stem = when {
            normalized.endsWith(".js") -> normalized.removeSuffix(".js")
            normalized.endsWith(".jsx") -> normalized.removeSuffix(".jsx")
            normalized.endsWith(".mjs") -> normalized.removeSuffix(".mjs")
            normalized.endsWith(".cjs") -> normalized.removeSuffix(".cjs")
            else -> normalized
        }
        val exts = listOf("", ".ts", ".tsx", ".d.ts", ".js", ".jsx", ".json", ".mts", ".cts", ".mjs", ".cjs")
        for (e in exts) {
            val cand = "$stem$e"
            if (cand in fileResults) return true
            val noPrefix = cand.removePrefix("./")
            if (noPrefix in fileResults) return true
            if (!cand.startsWith("/") && "./$noPrefix" in fileResults) return true
        }
        return false
    }

    /**
     * B98.r8: TS6053 "File 'X' not found." for `/// <reference path="X" />` directives whose
     * target file is absent from the program. Reference directives are only recognized in the
     * file's LEADING trivia (before the first statement); we scan from the top and stop at the
     * first real-code line. Squiggle covers the path content (without quotes). Skips `types=`/`lib=`
     * directives (different resolution). Permissive resolver → no FP on valid sibling references.
     *
     * NOTE: the regex is a LOCAL val — a `private val` declared mid-file would be null during the
     * `init {}` check pipeline (property-initialization-order gotcha) → NPE → checker abort.
     */
    private fun checkReferencePathsExist() {
        val referencePathRegex = Regex("""^\s*///\s*<reference\s+path\s*=\s*(["'])([^"']+)\1\s*/?>""")
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            var offset = 0
            for (line in source.lineSequence()) {
                val trimmed = line.trimStart()
                if (trimmed.isNotEmpty() && !trimmed.startsWith("//")) break
                val m = referencePathRegex.find(line)
                if (m != null) {
                    val refPath = m.groupValues[2]
                    // Skip harness-internal dot-directories (`/.lib/react16.d.ts`, `/.ts/`, …) —
                    // TypeScript's test harness resolves these from its own lib fixtures that our
                    // program never loads, so flagging them would FP (e.g. react16.d.ts references).
                    if (refPath.startsWith("/.")) { offset += line.length + 1; continue }
                    if (!referencePathResolves(refPath, fileName)) {
                        val groupStart = offset + m.groups[2]!!.range.first
                        val (l, c) = getLineAndCharacterOfPosition(source, groupStart)
                        // A reference path WITH a recognized extension that doesn't exist →
                        // TS6053 "File 'X' not found."; one WITHOUT an extension (the resolver
                        // tried appending extensions and failed) → TS6231 "Could not resolve the
                        // path 'X' with the extensions: …" (the list grows under allowJs).
                        val knownExts = listOf(".ts", ".tsx", ".d.ts", ".js", ".jsx", ".json",
                            ".mts", ".cts", ".mjs", ".cjs", ".d.mts", ".d.cts")
                        val hasKnownExt = knownExts.any { refPath.endsWith(it) }
                        val diag = if (hasKnownExt) {
                            Diagnostic(
                                message = "File '$refPath' not found.",
                                category = DiagnosticCategory.Error, code = 6053,
                                fileName = fileName, line = l, character = c,
                                start = groupStart, length = refPath.length,
                            )
                        } else {
                            val extList = if (options.allowJs) {
                                "'.ts', '.tsx', '.d.ts', '.js', '.jsx', '.cts', '.d.cts', '.cjs', '.mts', '.d.mts', '.mjs'"
                            } else {
                                "'.ts', '.tsx', '.d.ts'"
                            }
                            Diagnostic(
                                message = "Could not resolve the path '$refPath' with the extensions: $extList.",
                                category = DiagnosticCategory.Error, code = 6231,
                                fileName = fileName, line = l, character = c,
                                start = groupStart, length = refPath.length,
                            )
                        }
                        diagnostics.add(diag)
                    }
                }
                offset += line.length + 1
            }
        }
    }

    /** Normalize a path by resolving `..` and `.` segments. Memoized (M0.3(iv)) —
     *  pure function, called per relative-specifier resolution on hot flow paths. */
    private fun normalizePath(path: String): String = normalizePathMemo.getOrPut(path) {
        val parts = path.split('/')
        val result = mutableListOf<String>()
        for (part in parts) {
            when (part) {
                "." -> {}
                ".." -> if (result.isNotEmpty() && result.last() != "..") result.removeLast() else result.add(part)
                else -> result.add(part)
            }
        }
        result.joinToString("/")
    }

    // -----------------------------------------------------------------------
    // TS2883: declaration-emit nameability — the inferred type of an exported
    // declaration references a type that lives in a NESTED node_modules package
    // not reachable (nameable) from the importing file. Declaration emit would
    // have to write a type annotation referencing a private dependency, which
    // is not portable, so TypeScript requires an explicit annotation.
    //
    // FP-safe by construction: fires ONLY when (a) declaration emit is on,
    // (b) an EXPORTED const/let/var has NO type annotation, (c) its initializer
    // is a call to an imported function whose explicit return type references a
    // type, and (d) that type's declaring file is genuinely non-nameable per
    // TypeScript's nested-node_modules rule (a top-level node_modules package,
    // or a sibling within the importer's own package, IS nameable and suppresses).
    // -----------------------------------------------------------------------
    private fun checkDeclarationEmitNameability() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        if (binderResults.size < 2) return // cross-file phenomenon
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val statements = result.sourceFile.statements
            if (!isModuleFile(statements)) continue
            val source = result.sourceFile.text
            for (stmt in statements) {
                // B172: `export default Object.assign(A, {...})` — the default export's
                // inferred type flows from A (Object.assign's FIRST argument). Trace A's
                // tagged-template tag through the default-imported interface member's
                // return type into the package's type-alias graph, collecting referenced
                // type names INCLUDING qualified `ns.Member` refs through namespace
                // imports. First non-nameable ref → TS2883 named 'default', squiggle over
                // the whole export-default statement (declarationEmitObjectAssignedDefaultExport).
                if (stmt is ExportAssignment && !stmt.isExportEquals) {
                    val call = stmt.expression as? CallExpression
                    val calleePA = call?.expression as? PropertyAccessExpression
                    val isObjectAssign = calleePA != null &&
                        (calleePA.expression as? Identifier)?.text == "Object" && calleePA.name.text == "assign"
                    val firstArgName = if (isObjectAssign) (call.arguments.firstOrNull() as? Identifier)?.text else null
                    if (firstArgName != null) {
                        val refs = defaultExportAssignNameabilityRefs(firstArgName, result, f)
                        for ((typeName, g) in refs) {
                            if (isFileNameableFrom(g, f)) continue
                            val pkgPath = nameabilityPackagePath(g, f)
                            val (l, c) = getLineAndCharacterOfPosition(source, stmt.pos)
                            val semi = source.indexOf(';', (stmt.expression.let { expressionTrueEnd(it) }))
                            val end = if (semi >= 0) semi + 1 else (stmt.expression.let { expressionTrueEnd(it) })
                            diagnostics.add(Diagnostic(
                                message = "The inferred type of 'default' cannot be named without a reference to '$typeName' from '$pkgPath'. This is likely not portable. A type annotation is necessary.",
                                category = DiagnosticCategory.Error, code = 2883,
                                fileName = f, line = l, character = c,
                                start = stmt.pos, length = end - stmt.pos,
                            ))
                            break
                        }
                    }
                    continue
                }
                if (stmt !is VariableStatement || ModifierFlag.Export !in stmt.modifiers) continue
                for (decl in stmt.declarationList.declarations) {
                    if (decl.type != null) continue // explicit annotation → portable
                    val init = decl.initializer ?: continue
                    val nameNode = decl.name as? Identifier ?: continue
                    val refs = inferredTypeReferencedFiles(init, f) ?: emptyList()
                    for ((typeName, g) in refs) {
                        if (isFileNameableFrom(g, f)) continue
                        val pkgPath = nameabilityPackagePath(g, f)
                        val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "The inferred type of '${nameNode.text}' cannot be named without a reference to '$typeName' from '$pkgPath'. This is likely not portable. A type annotation is necessary.",
                            category = DiagnosticCategory.Error, code = 2883,
                            fileName = f, line = l, character = c,
                            start = nameNode.pos, length = nameNode.text.length,
                        ))
                        break // report only the first non-nameable referenced type per declaration
                    }
                    // B315 (declarationEmitUsingTypeAlias1): an ARROW initializer whose
                    // single param is annotated with an imported type that RESOLVES
                    // (through `export type X = import('./inner').Y` chains) into a
                    // package file NOT reachable through the package's `exports` map
                    // (nodenext) — the inferred RETURN type references the alias-resolved
                    // HOME declaration, writable only as a relative node_modules path.
                    // The reported name comes from the RETURN position: `return p` →
                    // the alias's home name; `return p.member` → the member's annotation.
                    if (refs.isEmpty() && options.effectiveModule.isNodeNext) {
                        val arrowRef = arrowReturnAliasHomeRef(init, f)
                        if (arrowRef != null && packageExportsBlocksFile(arrowRef.second, f)) {
                            val rel = relativeModulePathForDisplay(f, arrowRef.second)
                            val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                            diagnostics.add(Diagnostic(
                                message = "The inferred type of '${nameNode.text}' cannot be named without a reference to '${arrowRef.first}' from '$rel'. This is likely not portable. A type annotation is necessary.",
                                category = DiagnosticCategory.Error, code = 2883,
                                fileName = f, line = l, character = c,
                                start = nameNode.pos, length = nameNode.text.length,
                            ))
                        }
                    }
                    // (TS2527 below; B172's ExportAssignment branch lives after this loop)
                    // TS2527: `export const X = importedValue` whose type carries a NESTED
                    // (inaccessible) `unique symbol` cannot be portably emitted.
                    if (init is Identifier) {
                        val imp = resolveImportedSymbolFile(init.text, f)
                        if (imp != null) {
                            val (declFile, origName) = imp
                            val valType = importedValueTypeAnnotation(origName, declFile)
                            if (valType != null &&
                                typeAnnotationHasInaccessibleUniqueSymbol(valType, declFile, mutableSetOf(), 0, true)) {
                                val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                                diagnostics.add(Diagnostic(
                                    message = "The inferred type of '${nameNode.text}' references an inaccessible 'unique symbol' type. A type annotation is necessary.",
                                    category = DiagnosticCategory.Error, code = 2527,
                                    fileName = f, line = l, character = c,
                                    start = nameNode.pos, length = nameNode.text.length,
                                ))
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * B173: TS7056 — an EXPORTED annotation-less const whose inferred type's SERIALIZED
     * form would exceed tsc's 1M-char declaration-emit cap. AST-arithmetic estimator (no
     * type engine): finds `as`-cast type nodes in the initializer and estimates the
     * serialization size of mapped types whose key domain is a (template-literal cross
     * product of) string-literal union(s). Unknown shapes estimate 0 → suppressed, so the
     * only firing path is a CONCRETELY huge mapped type (hugeDeclarationOutputGetsTruncatedWithError:
     * 676 × 676 entries ≈ several MB > 1M). Span = the const name.
     */
    private fun checkDeclarationEmitHugeInferredType() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement || ModifierFlag.Export !in stmt.modifiers) continue
                for (decl in stmt.declarationList.declarations) {
                    if (decl.type != null) continue
                    val init = decl.initializer ?: continue
                    val nameNode = decl.name as? Identifier ?: continue
                    val castTypes = mutableListOf<TypeNode>()
                    collectAsCastTypes(init, castTypes, 0)
                    val maxSize = castTypes.maxOfOrNull { estimateTypeSerializedSize(it, f, 0) } ?: 0L
                    if (maxSize > 1_000_000L) {
                        val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "The inferred type of this node exceeds the maximum length the compiler will serialize. An explicit type annotation is needed.",
                            category = DiagnosticCategory.Error, code = 7056,
                            fileName = f, line = l, character = c,
                            start = nameNode.pos, length = nameNode.text.length,
                        ))
                    }
                }
            }
            // B316 (declarationEmitPrivatePromiseLikeInterface): a class-property arrow
            // `abc = () => this.<m>.<method>()` where <m>'s annotation is an IMPORTED
            // class whose <method> returns a NON-EXPORTED SELF-REFERENTIAL type alias —
            // declaration emit can't name the alias (not exported) and structural
            // expansion of the self-reference recurses past the serialization cap.
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ClassDeclaration || ModifierFlag.Export !in stmt.modifiers) continue
                val memberClassAnnotations = mutableMapOf<String, String>()
                for (m in stmt.members) {
                    when (m) {
                        is Constructor -> for (p in m.parameters) {
                            if (p.modifiers.isEmpty()) continue // parameter properties only
                            val pn = (p.name as? Identifier)?.text ?: continue
                            val tn = ((p.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                            memberClassAnnotations[pn] = tn
                        }
                        is PropertyDeclaration -> {
                            val pn = (m.name as? Identifier)?.text ?: continue
                            val tn = ((m.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                            memberClassAnnotations[pn] = tn
                        }
                        else -> {}
                    }
                }
                if (memberClassAnnotations.isEmpty()) continue
                for (m in stmt.members) {
                    if (m !is PropertyDeclaration || m.type != null) continue
                    val nameNode = m.name as? Identifier ?: continue
                    var init: Expression = m.initializer ?: continue
                    while (init is ParenthesizedExpression) init = init.expression
                    val arrow = init as? ArrowFunction ?: continue
                    val call = arrow.body as? CallExpression ?: continue
                    val callee = call.expression as? PropertyAccessExpression ?: continue
                    val recv = callee.expression as? PropertyAccessExpression ?: continue
                    if ((recv.expression as? Identifier)?.text != "this") continue
                    val clsName = memberClassAnnotations[recv.name.text] ?: continue
                    val resolved = resolveImportedSymbolFile(clsName, f) ?: continue
                    if (!methodReturnsPrivateSelfReferentialAlias(resolved.first, resolved.second, callee.name.text)) continue
                    val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "The inferred type of this node exceeds the maximum length the compiler will serialize. An explicit type annotation is needed.",
                        category = DiagnosticCategory.Error, code = 7056,
                        fileName = f, line = l, character = c,
                        start = nameNode.pos, length = nameNode.text.length,
                    ))
                }
            }
        }
    }

    /**
     * B541 (arrayFakeFlatNoCrashInferenceDeclarations): TS5088 "The inferred type of '<fn>'
     * references a type with a cyclic structure which cannot be trivially serialized." for a
     * GENERIC function with no return annotation whose body `return`s a call to a
     * `declare function` whose return type references a SELF-REFERENTIAL CONDITIONAL+infer
     * type alias (`BadFlatArray<A,D>[]`). tsc fires this at declaration-emit when serializing
     * `foo`'s inferred return type hits the cyclic-structure flag. We have no decl-emit type
     * serializer / generic inference → emit NOTHING → purely ADDITIVE. Sibling of
     * `checkDeclarationEmitHugeInferredType` (TS7056). CORPUS-UNIQUE: TS5088 appears in only
     * this baseline (grep-verified); the gate excludes recursiveConditionalTypes (no return /
     * explicit annotations).
     */
    private fun checkDeclarationEmitCyclicInferredReturn() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val source = result.sourceFile.text
            val top = result.sourceFile.statements
            val aliases = HashMap<String, TypeAliasDeclaration>()
            val declFns = HashMap<String, FunctionDeclaration>()
            for (s in top) when (s) {
                is TypeAliasDeclaration -> aliases[s.name.text] = s
                is FunctionDeclaration -> if (ModifierFlag.Declare in s.modifiers && s.body == null)
                    s.name?.text?.let { declFns[it] = s }
                else -> {}
            }
            if (aliases.isEmpty() || declFns.isEmpty()) continue
            for (s in top) {
                if (s !is FunctionDeclaration) continue
                val nameNode = s.name ?: continue
                if (s.type != null) continue                       // no return annotation
                if (s.typeParameters.isNullOrEmpty()) continue     // generic fn
                val body = s.body ?: continue
                val ret = body.statements.firstNotNullOfOrNull { it as? ReturnStatement } ?: continue
                var rexpr: Expression = ret.expression ?: continue
                while (rexpr is ParenthesizedExpression) rexpr = rexpr.expression
                val call = rexpr as? CallExpression ?: continue
                val calleeName = (call.expression as? Identifier)?.text ?: continue
                val declFn = declFns[calleeName] ?: continue
                var rt: TypeNode = declFn.type ?: continue
                if (rt is ArrayType) rt = rt.elementType
                val aliasName = ((rt as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val alias = aliases[aliasName] ?: continue
                val from = alias.type.pos.coerceIn(0, source.length)
                val to = alias.type.end.coerceIn(from, source.length)
                val aliasBody = source.substring(from, to)
                if (!Regex("\\b${Regex.escape(aliasName)}\\b").containsMatchIn(aliasBody)) continue  // self-referential
                if (!aliasBody.contains("extends") || !aliasBody.contains("infer")) continue          // conditional + infer
                val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "The inferred type of '${nameNode.text}' references a type with a cyclic structure which cannot be trivially serialized. A type annotation is necessary.",
                    category = DiagnosticCategory.Error, code = 5088,
                    fileName = f, line = l, character = c,
                    start = nameNode.pos, length = nameNode.text.length,
                ))
            }
        }
    }

    /** B316: in [file], class [clsName]'s member [method] (method or arrow-property)
     *  returns a TypeReference to a NON-EXPORTED type alias whose body references its
     *  own name (self-referential) — declaration emit can't name it and structural
     *  expansion recurses past the serialization cap. */
    private fun methodReturnsPrivateSelfReferentialAlias(file: String, clsName: String, method: String): Boolean {
        val res = fileResults[file] ?: return false
        val stmts = res.sourceFile.statements
        val cls = stmts.firstNotNullOfOrNull {
            (it as? ClassDeclaration)?.takeIf { c -> c.name?.text == clsName }
        } ?: return false
        var retName: String? = null
        for (m in cls.members) {
            val nm = when (m) {
                is MethodDeclaration -> (m.name as? Identifier)?.text
                is PropertyDeclaration -> (m.name as? Identifier)?.text
                else -> null
            }
            if (nm != method) continue
            val rt: TypeNode? = when (m) {
                is MethodDeclaration -> m.type
                is PropertyDeclaration -> {
                    var i = m.initializer
                    while (i is ParenthesizedExpression) i = i.expression
                    (i as? ArrowFunction)?.type
                }
                else -> null
            }
            retName = ((rt as? TypeReference)?.typeName as? Identifier)?.text
            break
        }
        if (retName == null) return false
        val alias = stmts.firstNotNullOfOrNull {
            (it as? TypeAliasDeclaration)?.takeIf { a -> a.name.text == retName }
        } ?: return false
        if (ModifierFlag.Export in alias.modifiers) return false
        val src = res.sourceFile.text
        val from = alias.type.pos.coerceIn(0, src.length)
        val to = alias.type.end.coerceIn(from, src.length)
        return Regex("\\b${Regex.escape(retName)}\\b").containsMatchIn(src.substring(from, to))
    }

    private fun collectAsCastTypes(e: Expression, out: MutableList<TypeNode>, depth: Int) {
        if (depth > 6) return
        when (e) {
            is AsExpression -> { out.add(e.type); collectAsCastTypes(e.expression, out, depth + 1) }
            is TypeAssertionExpression -> { out.add(e.type); collectAsCastTypes(e.expression, out, depth + 1) }
            is ParenthesizedExpression -> collectAsCastTypes(e.expression, out, depth + 1)
            is ArrayLiteralExpression -> e.elements.forEach { collectAsCastTypes(it, out, depth + 1) }
            is ElementAccessExpression -> collectAsCastTypes(e.expression, out, depth + 1)
            is PropertyAccessExpression -> collectAsCastTypes(e.expression, out, depth + 1)
            else -> {}
        }
    }

    /** B173: (memberCount, totalKeyChars) of a string key DOMAIN type, or null when not
     *  concretely computable. Union of string literals → direct; a TEMPLATE-LITERAL type
     *  (shallow-parsed — B65.1: spans live only in head.rawText) → the cross product of
     *  its `${Name}` placeholder domains; a TypeReference follows a local type alias. */
    private fun keyDomainInfo(t: TypeNode, file: String, depth: Int): Pair<Long, Long>? {
        if (depth > 6) return null
        when (t) {
            is UnionType -> {
                var count = 0L; var chars = 0L
                for (m in t.types) {
                    val lit = ((m as? LiteralType)?.literal as? StringLiteralNode)?.text ?: return null
                    count++; chars += lit.length
                }
                return if (count > 0) count to chars else null
            }
            is LiteralType -> {
                val lit = (t.literal as? StringLiteralNode)?.text ?: return null
                return 1L to lit.length.toLong()
            }
            is TemplateLiteralType -> {
                val raw = t.head.rawText ?: return null
                // cross product over `${Name}` placeholders; fixed chars multiply through
                var count = 1L
                var avgLen = 0.0
                var idx = 0
                while (true) {
                    val open = raw.indexOf("\${", idx)
                    if (open < 0) { avgLen += raw.length - idx; break }
                    avgLen += open - idx
                    val close = raw.indexOf('}', open)
                    if (close < 0) return null
                    val name = raw.substring(open + 2, close).trim()
                    val r = fileResults[file]
                    val alias = r?.sourceFile?.statements?.firstNotNullOfOrNull { s ->
                        (s as? TypeAliasDeclaration)?.takeIf { it.name.text == name }
                    } ?: return null
                    val inner = keyDomainInfo(alias.type, file, depth + 1) ?: return null
                    count *= inner.first
                    avgLen += inner.second.toDouble() / inner.first
                    idx = close + 1
                }
                return count to (count * avgLen).toLong()
            }
            is TypeReference -> {
                val name = (t.typeName as? Identifier)?.text ?: return null
                val r = fileResults[file]
                val alias = r?.sourceFile?.statements?.firstNotNullOfOrNull { s ->
                    (s as? TypeAliasDeclaration)?.takeIf { it.name.text == name }
                } ?: return null
                return keyDomainInfo(alias.type, file, depth + 1)
            }
            is ParenthesizedType -> return keyDomainInfo(t.type, file, depth + 1)
            else -> return null
        }
    }

    /** B173: rough serialized-size estimate of a type node; 0 for unknown shapes. */
    private fun estimateTypeSerializedSize(t: TypeNode, file: String, depth: Int): Long {
        if (depth > 6) return 0L
        return when (t) {
            is MappedType -> {
                val domain = t.typeParameter.constraint?.let { keyDomainInfo(it, file, depth + 1) } ?: return 0L
                val (count, totalKeyChars) = domain
                if (count <= 0) return 0L
                val valueSize = t.type?.let { v ->
                    when (v) {
                        // a template value's length ≈ its key-interpolation length; use the
                        // average key length as the placeholder contribution
                        is TemplateLiteralType -> (v.head.rawText?.length ?: 4).toLong() + 2 * (totalKeyChars / count)
                        else -> estimateTypeSerializedSize(v, file, depth + 1).coerceAtLeast(8L)
                    }
                } ?: 8L
                totalKeyChars + count * (valueSize + 8L)
            }
            is TypeLiteral -> t.members.sumOf { m ->
                8L + ((m as? PropertyDeclaration)?.type?.let { estimateTypeSerializedSize(it, file, depth + 1) } ?: 4L)
            }
            is ParenthesizedType -> estimateTypeSerializedSize(t.type, file, depth + 1)
            is ArrayType -> estimateTypeSerializedSize(t.elementType, file, depth + 1) + 2
            else -> 0L
        }
    }

    /** The explicit type annotation of an exported value `name` declared in [file] (const/var with `: T`). */
    private fun importedValueTypeAnnotation(name: String, file: String): TypeNode? {
        val r = fileResults[file] ?: return null
        for (stmt in r.sourceFile.statements) {
            if (stmt is VariableStatement) for (d in stmt.declarationList.declarations) {
                if ((d.name as? Identifier)?.text == name) return d.type
            }
        }
        return null
    }

    /**
     * Does a value's resolved type annotation contain a NESTED `unique symbol` (a property type
     * inside a type literal / interface), which declaration emit cannot reference portably?
     * A TOP-LEVEL `unique symbol` (the value's own type) IS accessible via `typeof value`, so
     * [topLevel] suppresses it. Follows type-alias references across files.
     */
    private fun typeAnnotationHasInaccessibleUniqueSymbol(
        t: TypeNode, file: String, visited: MutableSet<String>, depth: Int, topLevel: Boolean,
    ): Boolean {
        if (depth > 6) return false
        return when (t) {
            is TypeOperator ->
                if (t.operator == SyntaxKind.UniqueKeyword) !topLevel
                else typeAnnotationHasInaccessibleUniqueSymbol(t.type, file, visited, depth + 1, topLevel)
            is TypeReference -> {
                val n = t.typeName
                if (n is Identifier) {
                    val key = "$file|${n.text}"
                    if (!visited.add(key)) return false
                    when (val decl = resolveTypeReferenceDecl(n.text, file, mutableSetOf())) {
                        null -> false
                        else -> {
                            val (d, df) = decl
                            when (d) {
                                is TypeAliasDeclaration -> typeAnnotationHasInaccessibleUniqueSymbol(d.type, df, visited, depth + 1, topLevel)
                                is InterfaceDeclaration -> d.members.any { m ->
                                    m is PropertyDeclaration && m.type?.let {
                                        typeAnnotationHasInaccessibleUniqueSymbol(it, df, visited, depth + 1, false)
                                    } == true
                                }
                                else -> false
                            }
                        }
                    }
                } else false
            }
            is TypeLiteral -> t.members.any { m ->
                m is PropertyDeclaration && m.type?.let {
                    typeAnnotationHasInaccessibleUniqueSymbol(it, file, visited, depth + 1, false)
                } == true
            }
            is ArrayType -> typeAnnotationHasInaccessibleUniqueSymbol(t.elementType, file, visited, depth + 1, false)
            is UnionType -> t.types.any { typeAnnotationHasInaccessibleUniqueSymbol(it, file, visited, depth + 1, false) }
            is IntersectionType -> t.types.any { typeAnnotationHasInaccessibleUniqueSymbol(it, file, visited, depth + 1, false) }
            is ParenthesizedType -> typeAnnotationHasInaccessibleUniqueSymbol(t.type, file, visited, depth + 1, topLevel)
            else -> false
        }
    }

    /**
     * For an exported var/const initializer, returns the ORDERED list of
     * (typeName, declaringFile) for every type the inferred type references.
     * Currently handles `const x = importedFn()` — resolves the callee's
     * declaring file, reads its explicit return type, and resolves each
     * referenced type name to its declaring file. Returns null when the shape
     * is unsupported (graceful — no diagnostic).
     */
    /**
     * B172: type names referenced by the inferred type of a LOCAL const [localName] whose
     * initializer is a tagged template `imported.member\`\``. Resolves: the tag base (a
     * default import) → the package's `export default <ident>` → `declare const <ident>: I`
     * → interface member's FunctionType RETURN type → transitively through locally-declared
     * type-alias bodies, collecting bare refs (declared file = the package file) and
     * QUALIFIED `ns.Member` refs through `import * as ns` (declared file = the namespace's
     * resolved module). Ordered; the caller reports the first non-nameable.
     */
    private fun defaultExportAssignNameabilityRefs(
        localName: String, result: BinderResult, contextFile: String,
    ): List<Pair<String, String>> {
        // 1. the local const's initializer
        var init: Expression? = null
        for (s in result.sourceFile.statements) {
            if (s !is VariableStatement) continue
            for (d in s.declarationList.declarations) {
                if ((d.name as? Identifier)?.text == localName) init = d.initializer
            }
        }
        val tag = (init as? TaggedTemplateExpression)?.tag as? PropertyAccessExpression ?: return emptyList()
        val baseName = (tag.expression as? Identifier)?.text ?: return emptyList()
        val memberName = tag.name.text
        // 2. base is a default import → the package file
        val (pkgFile, origName) = resolveImportedSymbolFile(baseName, contextFile) ?: return emptyList()
        if (origName != "default") return emptyList()
        val pkgResult = fileResults[pkgFile] ?: return emptyList()
        // 3. `export default <ident>` → `declare const <ident>: <ifaceRef>`
        val defaultIdent = pkgResult.sourceFile.statements.firstNotNullOfOrNull { s ->
            (s as? ExportAssignment)?.takeIf { !it.isExportEquals }?.expression as? Identifier
        }?.text ?: return emptyList()
        var constType: TypeNode? = null
        for (s in pkgResult.sourceFile.statements) {
            if (s !is VariableStatement) continue
            for (d in s.declarationList.declarations) {
                if ((d.name as? Identifier)?.text == defaultIdent) constType = d.type
            }
        }
        val ifaceName = ((constType as? TypeReference)?.typeName as? Identifier)?.text ?: return emptyList()
        val iface = pkgResult.sourceFile.statements.firstNotNullOfOrNull { s ->
            (s as? InterfaceDeclaration)?.takeIf { it.name.text == ifaceName }
        } ?: return emptyList()
        // 4. the member's return type
        val memberType = iface.members.firstNotNullOfOrNull { m ->
            (m as? PropertyDeclaration)?.takeIf { (it.name as? Identifier)?.text == memberName }?.type
                ?: (m as? MethodDeclaration)?.takeIf { (it.name as? Identifier)?.text == memberName }?.type
        }
        val returnType = (memberType as? FunctionType)?.type ?: memberType ?: return emptyList()
        // 5. transitive collection through the package's type graph
        val out = mutableListOf<Pair<String, String>>()
        collectNameabilityTypeRefs(returnType, pkgFile, out, mutableSetOf(), 0)
        return out
    }

    /** B172: ordered transitive type-ref collection following local type-alias bodies and
     *  qualified `ns.Member` refs through namespace imports. */
    private fun collectNameabilityTypeRefs(
        t: TypeNode, file: String, out: MutableList<Pair<String, String>>,
        visited: MutableSet<String>, depth: Int,
    ) {
        if (depth > 6) return
        when (t) {
            is TypeReference -> {
                when (val n = t.typeName) {
                    is Identifier -> {
                        val key = "$file|${n.text}"
                        if (visited.add(key)) {
                            out.add(n.text to file)
                            // follow a locally-declared type alias's body
                            val r = fileResults[file]
                            val alias = r?.sourceFile?.statements?.firstNotNullOfOrNull { s ->
                                (s as? TypeAliasDeclaration)?.takeIf { it.name.text == n.text }
                            }
                            alias?.let { collectNameabilityTypeRefs(it.type, file, out, visited, depth + 1) }
                        }
                    }
                    is QualifiedName -> {
                        val ns = (n.left as? Identifier)?.text
                        if (ns != null) {
                            // resolve `import * as ns from "spec"` in [file]
                            val r = fileResults[file]
                            val spec = r?.sourceFile?.statements?.firstNotNullOfOrNull { s ->
                                val imp = s as? ImportDeclaration ?: return@firstNotNullOfOrNull null
                                val nsImp = imp.importClause?.namedBindings as? NamespaceImport ?: return@firstNotNullOfOrNull null
                                if (nsImp.name.text == ns) (imp.moduleSpecifier as? StringLiteralNode)?.text else null
                            }
                            val g = spec?.let { resolveSpecifierAnywhere(it, file) }
                            if (g != null && visited.add("$g|${n.right.text}")) out.add(n.right.text to g)
                        }
                    }
                    else -> {}
                }
                t.typeArguments?.forEach { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
            }
            is UnionType -> t.types.forEach { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
            is IntersectionType -> t.types.forEach { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
            is ParenthesizedType -> collectNameabilityTypeRefs(t.type, file, out, visited, depth + 1)
            is ArrayType -> collectNameabilityTypeRefs(t.elementType, file, out, visited, depth + 1)
            is TupleType -> t.elements.forEach { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
            is TypeOperator -> collectNameabilityTypeRefs(t.type, file, out, visited, depth + 1)
            is IndexedAccessType -> {
                collectNameabilityTypeRefs(t.objectType, file, out, visited, depth + 1)
                collectNameabilityTypeRefs(t.indexType, file, out, visited, depth + 1)
            }
            is MappedType -> {
                t.typeParameter.constraint?.let { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
                t.nameType?.let { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
                t.type?.let { collectNameabilityTypeRefs(it, file, out, visited, depth + 1) }
            }
            else -> {}
        }
    }

    private fun inferredTypeReferencedFiles(init: Expression, contextFile: String): List<Pair<String, String>>? {
        if (init !is CallExpression) return null
        val callee = init.expression as? Identifier ?: return null
        val (calleeFile, calleeName) = resolveImportedSymbolFile(callee.text, contextFile) ?: return null
        val calleeResult = fileResults[calleeFile] ?: return null
        val fd = calleeResult.sourceFile.statements.firstNotNullOfOrNull { s ->
            if (s is FunctionDeclaration && s.name?.text == calleeName) s else null
        } ?: return null
        val rt = fd.type ?: return null // need an explicit return type to know the referenced types
        val names = mutableListOf<String>()
        collectTypeReferenceNamesOrdered(rt, names)
        val out = mutableListOf<Pair<String, String>>()
        for (tn in names) {
            val g = resolveTypeNameDeclaringFile(tn, calleeFile) ?: continue
            out.add(tn to g)
        }
        return out
    }

    /** Ordered (source-position) variant of [collectTypeReferenceNames] — TS2883 reports the FIRST non-nameable type. */
    private fun collectTypeReferenceNamesOrdered(type: TypeNode, out: MutableList<String>) {
        when (type) {
            is TypeReference -> {
                val n = type.typeName
                if (n is Identifier && n.text !in out) out.add(n.text)
                type.typeArguments?.forEach { collectTypeReferenceNamesOrdered(it, out) }
            }
            is UnionType -> type.types.forEach { collectTypeReferenceNamesOrdered(it, out) }
            is IntersectionType -> type.types.forEach { collectTypeReferenceNamesOrdered(it, out) }
            is ParenthesizedType -> collectTypeReferenceNamesOrdered(type.type, out)
            is ArrayType -> collectTypeReferenceNamesOrdered(type.elementType, out)
            is TupleType -> type.elements.forEach { collectTypeReferenceNamesOrdered(it, out) }
            is TypeOperator -> collectTypeReferenceNamesOrdered(type.type, out)
            is RestType -> collectTypeReferenceNamesOrdered(type.type, out)
            is OptionalType -> collectTypeReferenceNamesOrdered(type.type, out)
            else -> {}
        }
    }

    /** Resolve a value `name` imported into [contextFile] to (declaringFile, originalName), or null. */
    private fun resolveImportedSymbolFile(name: String, contextFile: String): Pair<String, String>? {
        val result = fileResults[contextFile] ?: return null
        for (stmt in result.sourceFile.statements) {
            if (stmt !is ImportDeclaration) continue
            val clause = stmt.importClause ?: continue
            val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val named = clause.namedBindings as? NamedImports
            if (named != null) {
                for (el in named.elements) {
                    if (el.name.text == name) {
                        val orig = el.propertyName?.text ?: el.name.text
                        val g = resolveSpecifierAnywhere(spec, contextFile) ?: return null
                        return g to orig
                    }
                }
            }
            if (clause.name?.text == name) {
                // default import: original name is "default"
                val g = resolveSpecifierAnywhere(spec, contextFile) ?: return null
                return g to "default"
            }
        }
        return null
    }

    /** Resolve a type NAME used in [usedInFile] to the file that declares it (local decl or import target). */
    private fun resolveTypeNameDeclaringFile(typeName: String, usedInFile: String): String? {
        val result = fileResults[usedInFile] ?: return null
        for (stmt in result.sourceFile.statements) {
            when (stmt) {
                is InterfaceDeclaration -> if (stmt.name.text == typeName) return usedInFile
                is TypeAliasDeclaration -> if (stmt.name.text == typeName) return usedInFile
                is ClassDeclaration -> if (stmt.name?.text == typeName) return usedInFile
                is EnumDeclaration -> if (stmt.name.text == typeName) return usedInFile
                else -> {}
            }
        }
        // Not declared locally — look for an import of the type name.
        for (stmt in result.sourceFile.statements) {
            if (stmt !is ImportDeclaration) continue
            val clause = stmt.importClause ?: continue
            val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val named = clause.namedBindings as? NamedImports ?: continue
            for (el in named.elements) {
                if (el.name.text == typeName) {
                    return resolveSpecifierAnywhere(spec, usedInFile)
                }
            }
        }
        return null
    }

    /** Resolve a module specifier (relative OR bare via node_modules walk) to a loaded file, or null. */
    private fun resolveSpecifierAnywhere(specifier: String, contextFile: String): String? {
        // B472: route the bare `.`/`..` package-index specifiers through the relative
        // resolvers WITHOUT pre-normalizing, so resolveRelativeIncludingIndex's
        // dir-index-only rule (keyed on the original `.`/`..`) applies.
        if (specifier == "." || specifier == ".." ||
            specifier.startsWith("./") || specifier.startsWith("../")) {
            return resolveRelativeIncludingIndex(specifier, contextFile)
                ?: resolveModuleSpecifierStrictRelative(specifier, contextFile)
        }
        return resolveBareViaNodeModules(specifier, contextFile) ?: resolveModuleSpecifier(specifier)
            ?: resolveBareViaPackageExportsRoot(specifier, contextFile)
    }

    /** B315: bare-specifier resolution through a package.json `exports` "." entry
     *  (string form), with declaration-extension substitution. FALLBACK-only — runs
     *  when the plain index/types steps found nothing. */
    private fun resolveBareViaPackageExportsRoot(specifier: String, contextFile: String): String? {
        var dir: String? = contextFile.substringBeforeLast('/', "")
        while (dir != null) {
            val base = if (dir.isEmpty()) "node_modules/$specifier" else "$dir/node_modules/$specifier"
            val pkg = jsonModuleContents["$base/package.json"] ?: jsonModuleContents["/$base/package.json"]
            if (pkg != null) {
                val m = Regex("\"\\.\"\\s*:\\s*\"([^\"]+)\"").find(pkg)
                if (m != null) {
                    val t = "$base/" + m.groupValues[1].removePrefix("./")
                    for (cand in listOf(
                        t, t.removeSuffix(".js") + ".d.ts", "$t.d.ts",
                        t.removeSuffix(".js") + ".ts", "$t.ts",
                    )) {
                        if (cand in fileResults) return cand
                    }
                }
            }
            dir = if (dir.isEmpty()) null else dir.substringBeforeLast('/', "")
        }
        return null
    }

    /** Walk up the directory tree from [contextFile] looking for `<dir>/node_modules/<specifier>` package files. */
    private fun resolveBareViaNodeModules(specifier: String, contextFile: String): String? {
        var dir: String? = contextFile.substringBeforeLast('/', "")
        while (dir != null) {
            val base = if (dir.isEmpty()) "node_modules/$specifier" else "$dir/node_modules/$specifier"
            for (cand in listOf("$base/index.d.ts", "$base.d.ts", "$base/index.ts", "$base.ts",
                    "$base/index.tsx", "$base.tsx")) {
                if (cand in fileResults) return cand
            }
            dir = if (dir.isEmpty()) null else dir.substringBeforeLast('/', "")
        }
        return null
    }

    /**
     * B174: node_modules walk honoring the package.json resolution steps — a STRING
     * "types"/"typings" first (an ARRAY value is INVALID per tsc and is skipped), then a
     * STRING "main" (resolved as a file with declaration substitution, or a directory via
     * `/index.d.ts`). Returns null when no package.json step resolves — callers fall back
     * to [resolveBareViaNodeModules]'s plain index candidates.
     */
    private fun resolveBareViaNodeModulesPkgJson(specifier: String, contextFile: String): String? {
        var dir: String? = contextFile.substringBeforeLast('/', "")
        while (dir != null) {
            val base = if (dir.isEmpty()) "node_modules/$specifier" else "$dir/node_modules/$specifier"
            val pkg = jsonModuleContents["$base/package.json"]
            if (pkg != null) {
                for (field in listOf("types", "typings", "main")) {
                    val m = Regex("\"$field\"\\s*:\\s*").find(pkg) ?: continue
                    val rest = pkg.substring(m.range.last + 1).trimStart()
                    if (!rest.startsWith("\"")) continue // array/object/null → invalid, skip
                    val target = rest.drop(1).substringBefore("\"")
                    if (target.isEmpty()) continue
                    val t = "$base/" + target.removePrefix("./")
                    for (cand in listOf(
                        t, "$t.d.ts", "$t.ts",
                        t.removeSuffix(".js") + ".d.ts",
                        "$t/index.d.ts", "$t/index.ts",
                    )) {
                        if (cand in fileResults) return cand
                    }
                }
            }
            dir = if (dir.isEmpty()) null else dir.substringBeforeLast('/', "")
        }
        return null
    }

    /**
     * Is the type declared in [g] nameable (referenceable in a portable declaration) from [f]?
     * Rule: find the LAST `node_modules/` segment in [g]; the directory immediately before it
     * (the package's "host" dir) must be an ancestor-or-equal of [f]'s directory. A package in a
     * top-level node_modules (host = root) is always nameable; a package nested inside another
     * package's private node_modules (host = that package dir) is nameable only from inside it.
     */
    private fun isFileNameableFrom(g: String, f: String): Boolean {
        val marker = "node_modules/"
        val idx = g.lastIndexOf(marker)
        if (idx < 0) return true // not in any node_modules → local/relative file, nameable
        val host = g.substring(0, idx).trimEnd('/')
        if (host.isEmpty()) return true // top-level node_modules
        val fDir = f.substringBeforeLast('/', "")
        return fDir == host || fDir.startsWith("$host/")
    }

    /** The displayed package path for a non-nameable type file: stripped of the first reachable node_modules prefix. */
    /** B315: for `(p: TN) => { return p[.member]; }`, resolve TN through named-import +
     *  `export type X = import("./m").Y` alias chains to its HOME file; returns
     *  (reportedTypeName, homeFile) per the RETURN expression, or null. */
    private fun arrowReturnAliasHomeRef(init: Expression, f: String): Pair<String, String>? {
        var e: Expression = init
        while (e is ParenthesizedExpression) e = e.expression
        val arrow = e as? ArrowFunction ?: return null
        val p = arrow.parameters.singleOrNull() ?: return null
        val pName = (p.name as? Identifier)?.text ?: return null
        val tn = ((p.type as? TypeReference)?.typeName as? Identifier)?.text ?: return null
        val retExpr: Expression = when (val b = arrow.body) {
            is Block -> b.statements.filterIsInstance<ReturnStatement>().firstOrNull()?.expression
            is Expression -> b
            else -> null
        } ?: return null
        var resolved = resolveImportedSymbolFile(tn, f) ?: return null
        var body: TypeNode? = null
        var hops = 0
        while (hops++ < 5) {
            val res = fileResults[resolved.first] ?: return null
            val alias = res.sourceFile.statements.firstNotNullOfOrNull { s ->
                (s as? TypeAliasDeclaration)?.takeIf { it.name.text == resolved.second }
            } ?: return null
            val t = alias.type
            if (t is ImportType) {
                val spec = ((t.argument as? LiteralType)?.literal as? StringLiteralNode)?.text ?: return null
                val q = t.qualifier as? Identifier ?: return null
                val g = resolveSpecifierAnywhere(spec, resolved.first) ?: return null
                resolved = g to q.text
                continue
            }
            body = t
            break
        }
        if (body == null) return null
        return when {
            retExpr is Identifier && retExpr.text == pName -> resolved.second to resolved.first
            retExpr is PropertyAccessExpression && (retExpr.expression as? Identifier)?.text == pName -> {
                val lit = body as? TypeLiteral ?: return null
                val member = lit.members.firstNotNullOfOrNull { m ->
                    (m as? PropertyDeclaration)?.takeIf { (it.name as? Identifier)?.text == retExpr.name.text }
                } ?: return null
                val mName = ((member.type as? TypeReference)?.typeName as? Identifier)?.text ?: return null
                mName to resolved.first
            }
            else -> null
        }
    }

    /** B315: true when [targetFile] sits inside a node_modules package whose
     *  package.json declares an `exports` map that exposes NO entry resolving to
     *  the file (extension-stripped literal match over the map's "./..." strings —
     *  conservative: any wildcard/match keeps the file reachable → no error). */
    private fun packageExportsBlocksFile(targetFile: String, importerFile: String): Boolean {
        val marker = "node_modules/"
        val nmIdx = targetFile.lastIndexOf(marker)
        if (nmIdx < 0) return false
        val afterNm = targetFile.substring(nmIdx + marker.length)
        val pkgName = if (afterNm.startsWith("@"))
            afterNm.split('/').take(2).joinToString("/") else afterNm.substringBefore('/')
        val pkgDir = targetFile.substring(0, nmIdx + marker.length) + pkgName
        val content = jsonModuleContents["$pkgDir/package.json"]
            ?: jsonModuleContents["/$pkgDir/package.json"] ?: return false
        if (!content.contains("\"exports\"")) return false
        val rel = "." + targetFile.substring(pkgDir.length)
            .removeSuffix(".d.ts").removeSuffix(".ts").removeSuffix(".js")
        if ("*" in content) return false // wildcard subpaths — assume reachable
        val exportedPaths = Regex("\"(\\./[^\"]*)\"").findAll(content)
            .map { it.groupValues[1].removeSuffix(".js").removeSuffix(".d.ts").removeSuffix(".ts") }
            .toSet()
        return rel !in exportedPaths
    }

    /** B315 display: relative module path from [importer]'s directory to [target]
     *  without the declaration extension ('../node_modules/some-dep/dist/inner'). */
    private fun relativeModulePathForDisplay(importer: String, target: String): String {
        val impDirParts = importer.substringBeforeLast('/', "").split('/').filter { it.isNotEmpty() }
        val tgt = target.removeSuffix(".d.ts").removeSuffix(".ts")
        val tgtParts = tgt.split('/').filter { it.isNotEmpty() }
        var common = 0
        while (common < impDirParts.size && common < tgtParts.size - 1 &&
            impDirParts[common] == tgtParts[common]
        ) common++
        val ups = List(impDirParts.size - common) { ".." }
        val downs = tgtParts.drop(common)
        val joined = (ups + downs).joinToString("/")
        return if (ups.isEmpty()) "./$joined" else joined
    }

    private fun nameabilityPackagePath(g: String, f: String): String {
        val marker = "node_modules/"
        val fDir = f.substringBeforeLast('/', "")
        var searchFrom = 0
        while (true) {
            val idx = g.indexOf(marker, searchFrom)
            if (idx < 0) break
            val host = g.substring(0, idx).trimEnd('/')
            val hostReachable = host.isEmpty() || fDir == host || fDir.startsWith("$host/")
            if (hostReachable) {
                val rest = g.substring(idx + marker.length)
                return rest.substringBeforeLast('/', rest)
            }
            searchFrom = idx + marker.length
        }
        return g.substringBeforeLast('/', g)
    }

    // -----------------------------------------------------------------------
    // TS4023: declaration-emit cannot name a COMPUTED SYMBOL property key. An
    // exported `const x = { ...typedExpr }` (no annotation) whose inferred type
    // carries a computed-name member `[Sym]` / `[NS.sym]` keyed by a symbol from
    // another module that is NOT value-accessible from the importing file —
    // declaration emit would have to reference an inaccessible name, so an
    // explicit annotation is required.
    //
    // FP-safe: fires only when declaration emit is on, the const has NO
    // annotation, its initializer object-literal spreads a value whose resolved
    // type has a computed-symbol-key member, and the key's root identifier is
    // genuinely not value-accessible in the importing file (a value import /
    // local value / global suppresses).
    // -----------------------------------------------------------------------
    /**
     * B314 (declarationEmitMappedTypeTemplateTypeofSymbol, TS4118): an EXPORTED
     * annotation-less `const X = <call>()` whose callee resolves cross-file (named
     * import or namespace-import member) to a declared function returning `typeof T`,
     * where T's annotation is a MAPPED type keyed by `typeof S` and S is a
     * `unique symbol` const in the declaring file — the computed property `[S]`
     * cannot be serialized in the declaration output. Squiggle at the const NAME.
     * Self-contained AST + module resolution (the 14a decl-emit-nameability family).
     */
    private fun checkDeclarationEmitMappedUniqueSymbolKey() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        if (binderResults.size < 2) return
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val statements = result.sourceFile.statements
            if (!isModuleFile(statements)) continue
            val source = result.sourceFile.text
            val namedImportTargets = mutableMapOf<String, String>()
            val nsImportTargets = mutableMapOf<String, String>()
            for (stmt in statements) {
                if (stmt !is ImportDeclaration) continue
                val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                val target = resolveModuleSpecifier(spec, stmt) ?: continue
                val clause = stmt.importClause ?: continue
                when (val nb = clause.namedBindings) {
                    is NamespaceImport -> nsImportTargets[nb.name.text] = target
                    is NamedImports -> for (s in nb.elements) namedImportTargets[s.name.text] = target
                    else -> {}
                }
            }
            if (namedImportTargets.isEmpty() && nsImportTargets.isEmpty()) continue
            for (stmt in statements) {
                if (stmt !is VariableStatement || ModifierFlag.Export !in stmt.modifiers) continue
                for (decl in stmt.declarationList.declarations) {
                    if (decl.type != null) continue
                    val nameNode = decl.name as? Identifier ?: continue
                    val call = decl.initializer as? CallExpression ?: continue
                    val (fnName, targetFile) = when (val callee = call.expression) {
                        is Identifier -> callee.text to namedImportTargets[callee.text]
                        is PropertyAccessExpression ->
                            callee.name.text to (callee.expression as? Identifier)?.text?.let { nsImportTargets[it] }
                        else -> null to null
                    }
                    if (fnName == null || targetFile == null) continue
                    val symName = mappedUniqueSymbolKeyOfFunctionReturn(fnName, targetFile) ?: continue
                    val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "The type of this node cannot be serialized because its property '[$symName]' cannot be serialized.",
                        category = DiagnosticCategory.Error, code = 4118,
                        fileName = f, line = l, character = c,
                        start = nameNode.pos, length = nameNode.text.length,
                    ))
                }
            }
        }
    }

    /**
     * B317 (declarationEmitMixinPrivateProtected, TS4094): an EXPORTED position whose
     * type is `identityFn(M)` where M is a local `const M = class { ... }` with
     * private/protected members and identityFn is `<T>(x: T): T` — the export's type
     * is the ANONYMOUS class type, whose non-public members can't appear in a `.d.ts`.
     * One TS4094 per private/protected member (alphabetical). Anchors: `export default
     * <call>;` → the whole statement incl. ';'; `export class N extends <call>` → the
     * class NAME; anonymous `export default class extends <call>` → the `export` keyword.
     */
    private fun checkDeclarationEmitMixinPrivateProtected() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val statements = result.sourceFile.statements
            if (!isModuleFile(statements)) continue
            val source = result.sourceFile.text
            val mixinMembers = mutableMapOf<String, List<String>>()
            val identityFns = mutableSetOf<String>()
            for (stmt in statements) {
                if (stmt is FunctionDeclaration) {
                    val tp = stmt.typeParameters?.singleOrNull() ?: continue
                    val p = stmt.parameters.singleOrNull() ?: continue
                    val pt = ((p.type as? TypeReference)?.typeName as? Identifier)?.text
                    val rt = ((stmt.type as? TypeReference)?.typeName as? Identifier)?.text
                    if (pt == tp.name.text && rt == tp.name.text) stmt.name?.text?.let { identityFns.add(it) }
                }
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    var init: Expression = d.initializer ?: continue
                    while (init is ParenthesizedExpression) init = init.expression
                    val ce = init as? ClassExpression ?: continue
                    val privs = ce.members.mapNotNull { m ->
                        val mods = when (m) {
                            is MethodDeclaration -> m.modifiers
                            is PropertyDeclaration -> m.modifiers
                            else -> return@mapNotNull null
                        }
                        if (ModifierFlag.Private !in mods && ModifierFlag.Protected !in mods) return@mapNotNull null
                        when (m) {
                            is MethodDeclaration -> (m.name as? Identifier)?.text
                            is PropertyDeclaration -> (m.name as? Identifier)?.text
                        }
                    }.sorted()
                    if (privs.isNotEmpty()) mixinMembers[nm] = privs
                }
            }
            // B356: mixin FUNCTIONS — `export function WithTags<T extends Constructor<X>>(Base: T) {
            // return class extends Base {...} }` with NO return annotation: the inferred return is an
            // anonymous class type inheriting X's private/protected members → TS4094 at the fn name,
            // and again at the name of any exported class extending a CALL of the function.
            fun classPrivs(cd: ClassDeclaration): List<String> = cd.members.mapNotNull { m ->
                val mods = when (m) {
                    is MethodDeclaration -> m.modifiers
                    is PropertyDeclaration -> m.modifiers
                    else -> return@mapNotNull null
                }
                if (ModifierFlag.Private !in mods && ModifierFlag.Protected !in mods) return@mapNotNull null
                when (m) {
                    is MethodDeclaration -> (m.name as? Identifier)?.text
                    is PropertyDeclaration -> (m.name as? Identifier)?.text
                }
            }.sorted()
            val ctorAliases = statements.filterIsInstance<TypeAliasDeclaration>()
                .filter { it.type is ConstructorType }.mapNotNull { it.name.text }.toSet()
            val fileClasses = statements.filterIsInstance<ClassDeclaration>()
                .mapNotNull { c -> c.name?.text?.let { it to c } }.toMap()
            val mixinFns = mutableMapOf<String, Pair<FunctionDeclaration, List<String>>>()
            for (stmt in statements) {
                val fn = stmt as? FunctionDeclaration ?: continue
                if (ModifierFlag.Export !in fn.modifiers || fn.type != null) continue
                val fnName = fn.name?.text ?: continue
                val tp = fn.typeParameters?.singleOrNull() ?: continue
                val cons = tp.constraint as? TypeReference ?: continue
                if ((cons.typeName as? Identifier)?.text !in ctorAliases) continue
                val argClass = ((cons.typeArguments?.singleOrNull() as? TypeReference)
                    ?.typeName as? Identifier)?.text?.let { fileClasses[it] } ?: continue
                val p = fn.parameters.singleOrNull() ?: continue
                if (((p.type as? TypeReference)?.typeName as? Identifier)?.text != tp.name.text) continue
                val pName = (p.name as? Identifier)?.text ?: continue
                val returnsClassExtendingParam = fn.body?.statements?.any { s ->
                    val ce = (s as? ReturnStatement)?.expression as? ClassExpression ?: return@any false
                    val ext = ce.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                        ?.types?.firstOrNull()?.expression as? Identifier ?: return@any false
                    ext.text == pName
                } == true
                if (!returnsClassExtendingParam) continue
                val privs = classPrivs(argClass)
                if (privs.isNotEmpty()) mixinFns[fnName] = fn to privs
            }
            if (mixinMembers.isEmpty() && mixinFns.isEmpty()) continue
            fun mixinCallMembers(e: Expression?): List<String>? {
                var x = e ?: return null
                while (x is ParenthesizedExpression) x = x.expression
                val call = x as? CallExpression ?: return null
                val callee = (call.expression as? Identifier)?.text ?: return null
                if (callee in mixinFns && call.arguments.size == 1) return mixinFns[callee]!!.second
                if (callee !in identityFns) return null
                val arg = (call.arguments.singleOrNull() as? Identifier)?.text ?: return null
                return mixinMembers[arg]
            }
            fun emit(privs: List<String>, start: Int, length: Int) {
                val (l, c) = getLineAndCharacterOfPosition(source, start)
                for (p in privs) {
                    diagnostics.add(Diagnostic(
                        message = "Property '$p' of exported anonymous class type may not be private or protected.",
                        category = DiagnosticCategory.Error, code = 4094,
                        fileName = f, line = l, character = c,
                        start = start, length = length,
                    ))
                }
            }
            for ((_, fnAndPrivs) in mixinFns) {
                val (fn, privs) = fnAndPrivs
                val nameNode = fn.name ?: continue
                emit(privs, nameNode.pos, nameNode.text.length)
            }
            for (stmt in statements) {
                when (stmt) {
                    is ExportAssignment -> {
                        if (stmt.isExportEquals) continue
                        val privs = mixinCallMembers(stmt.expression) ?: continue
                        val exprEnd = stmt.expression.let { expressionTrueEnd(it) }
                        val semi = source.indexOf(';', exprEnd)
                        val end = if (semi >= 0) semi + 1 else exprEnd
                        emit(privs, stmt.pos, end - stmt.pos)
                    }
                    is ClassDeclaration -> {
                        if (ModifierFlag.Export !in stmt.modifiers) continue
                        val ext = stmt.heritageClauses
                            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                            ?.types?.firstOrNull()?.expression ?: continue
                        val privs = mixinCallMembers(ext) ?: continue
                        val nameNode = stmt.name
                        if (nameNode != null) emit(privs, nameNode.pos, nameNode.text.length)
                        else {
                            // stmt.pos points at `class` (modifiers consumed before) —
                            // anchor at the `export` keyword.
                            val expStart = srcLastIndexOf(source, "export", stmt.pos).takeIf { it >= 0 } ?: stmt.pos
                            emit(privs, expStart, "export".length)
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    /**
     * B318 (declarationEmitExpandoPropertyPrivateName, TS4032): an EXPANDO property
     * `q.val = f()` on an exported local function, where f is a named import whose
     * declared return type names a NON-exported interface/alias/class in the target
     * module — the expando member's declaration type uses a private-module name.
     * Span covers `q.val`; module display is the specifier without './'.
     */
    private fun checkDeclarationEmitExpandoPrivateName() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val statements = result.sourceFile.statements
            if (!isModuleFile(statements)) continue
            val source = result.sourceFile.text
            val exportedFns = statements.filterIsInstance<FunctionDeclaration>()
                .filter { ModifierFlag.Export in it.modifiers }
                .mapNotNull { it.name?.text }.toSet()
            if (exportedFns.isEmpty()) continue
            for (stmt in statements) {
                val es = stmt as? ExpressionStatement ?: continue
                val bin = es.expression as? BinaryExpression ?: continue
                if (bin.operator != SyntaxKind.Equals) continue
                val lhs = bin.left as? PropertyAccessExpression ?: continue
                val recv = (lhs.expression as? Identifier)?.text ?: continue
                if (recv !in exportedFns) continue
                val call = bin.right as? CallExpression ?: continue
                val calleeName = (call.expression as? Identifier)?.text ?: continue
                var spec: String? = null
                var targetFile: String? = null
                var orig: String? = null
                for (imp in statements) {
                    if (imp !is ImportDeclaration) continue
                    val s = (imp.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                    val named = imp.importClause?.namedBindings as? NamedImports ?: continue
                    for (el in named.elements) {
                        if (el.name.text == calleeName) {
                            spec = s
                            orig = el.propertyName?.text ?: el.name.text
                            targetFile = resolveSpecifierAnywhere(s, f)
                        }
                    }
                }
                val tf = targetFile ?: continue
                val res = fileResults[tf] ?: continue
                val fd = res.sourceFile.statements.filterIsInstance<FunctionDeclaration>()
                    .firstOrNull { it.name?.text == orig } ?: continue
                val rtName = ((fd.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val privateDecl = res.sourceFile.statements.any { s2 ->
                    when (s2) {
                        is InterfaceDeclaration -> s2.name.text == rtName && ModifierFlag.Export !in s2.modifiers
                        is TypeAliasDeclaration -> s2.name.text == rtName && ModifierFlag.Export !in s2.modifiers
                        is ClassDeclaration -> s2.name?.text == rtName && ModifierFlag.Export !in s2.modifiers
                        else -> false
                    }
                }
                if (!privateDecl) continue
                val moduleName = (spec ?: continue).removePrefix("./")
                val start = lhs.pos
                val len = lhs.name.pos + lhs.name.text.length - start
                val (l, c) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Property '${lhs.name.text}' of exported interface has or is using name '$rtName' from private module '\"$moduleName\"'.",
                    category = DiagnosticCategory.Error, code = 4032,
                    fileName = f, line = l, character = c,
                    start = start, length = len,
                ))
            }
        }
    }

    /** B314 helper: in [file], find `declare function <fnName>(): typeof T` where T's
     *  annotation is `{ [K in typeof S]: ... }` and S is a `unique symbol` const —
     *  returns S's name, else null. */
    private fun mappedUniqueSymbolKeyOfFunctionReturn(fnName: String, file: String): String? {
        val target = binderResults.firstOrNull { it.sourceFile.fileName == file } ?: return null
        val stmts = target.sourceFile.statements
        val fn = stmts.filterIsInstance<FunctionDeclaration>().firstOrNull { it.name?.text == fnName }
            ?: return null
        val tq = fn.type as? TypeQuery ?: return null
        val tName = ((tq.exprName as? Identifier) ?: return null).text
        var mapped: MappedType? = null
        outer@ for (s in stmts) {
            if (s !is VariableStatement) continue
            for (d in s.declarationList.declarations) {
                if ((d.name as? Identifier)?.text == tName) {
                    mapped = d.type as? MappedType
                    break@outer
                }
            }
        }
        val constraint = mapped?.typeParameter?.constraint as? TypeQuery ?: return null
        val symName = ((constraint.exprName as? Identifier) ?: return null).text
        for (s in stmts) {
            if (s !is VariableStatement) continue
            for (d in s.declarationList.declarations) {
                if ((d.name as? Identifier)?.text != symName) continue
                val t = d.type
                if (t is TypeOperator && t.operator == SyntaxKind.UniqueKeyword) return symName
            }
        }
        return null
    }

    private fun checkDeclarationEmitComputedSymbolNameability() {
        if (!(options.declaration || options.composite || options.emitDeclarationOnly)) return
        if (binderResults.size < 2) return
        for (result in checkedResults) {
            val f = result.sourceFile.fileName
            if (isDtsFile(f)) continue
            val statements = result.sourceFile.statements
            if (!isModuleFile(statements)) continue
            val source = result.sourceFile.text
            for (stmt in statements) {
                if (stmt !is VariableStatement || ModifierFlag.Export !in stmt.modifiers) continue
                for (decl in stmt.declarationList.declarations) {
                    if (decl.type != null) continue
                    val init = decl.initializer as? ObjectLiteralExpression ?: continue
                    val nameNode = decl.name as? Identifier ?: continue
                    for (prop in init.properties) {
                        if (prop !is SpreadAssignment) continue
                        val (typeDecl, declFile) = resolveSpreadSourceTypeDecl(prop.expression, f) ?: continue
                        val (rootName, rootFile) = firstComputedSymbolRoot(typeDecl, declFile, mutableSetOf()) ?: continue
                        if (isValueAccessibleIn(rootName, f)) continue
                        val moduleBase = moduleBasename(rootFile)
                        val (l, c) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Exported variable '${nameNode.text}' has or is using name '$rootName' from external module \"$moduleBase\" but cannot be named.",
                            category = DiagnosticCategory.Error, code = 4023,
                            fileName = f, line = l, character = c,
                            start = nameNode.pos, length = nameNode.text.length,
                        ))
                        break
                    }
                }
            }
        }
    }

    /** Resolve the TYPE declaration that an object-spread source expression resolves to: (declNode, declFile). */
    private fun resolveSpreadSourceTypeDecl(expr0: Expression, f: String): Pair<Declaration, String>? {
        val expr = if (expr0 is ParenthesizedExpression) expr0.expression else expr0
        when (expr) {
            is AsExpression -> {
                val t = expr.type
                if (t is TypeReference) {
                    val n = t.typeName
                    if (n is Identifier) return resolveTypeReferenceDecl(n.text, f, mutableSetOf())
                }
            }
            is CallExpression -> {
                val callee = expr.expression as? Identifier ?: return null
                val (calleeFile, calleeName) = resolveImportedSymbolFile(callee.text, f) ?: return null
                val cr = fileResults[calleeFile] ?: return null
                val fd = cr.sourceFile.statements.firstNotNullOfOrNull {
                    if (it is FunctionDeclaration && it.name?.text == calleeName) it else null
                } ?: return null
                val rt = fd.type
                if (rt is TypeReference && rt.typeName is Identifier) {
                    return resolveTypeReferenceDecl((rt.typeName).text, calleeFile, mutableSetOf())
                }
            }
            else -> {}
        }
        return null
    }

    /** Resolve a type NAME to its declaring Interface/TypeAlias node + file (following imports). */
    private fun resolveTypeReferenceDecl(typeName: String, usedInFile: String, visited: MutableSet<String>): Pair<Declaration, String>? {
        val key = "$usedInFile|$typeName"
        if (!visited.add(key)) return null
        val r = fileResults[usedInFile] ?: return null
        for (stmt in r.sourceFile.statements) {
            when (stmt) {
                is InterfaceDeclaration -> if (stmt.name.text == typeName) return stmt to usedInFile
                is TypeAliasDeclaration -> if (stmt.name.text == typeName) return stmt to usedInFile
                else -> {}
            }
        }
        for (stmt in r.sourceFile.statements) {
            if (stmt !is ImportDeclaration) continue
            val clause = stmt.importClause ?: continue
            val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val named = clause.namedBindings as? NamedImports ?: continue
            for (el in named.elements) {
                if (el.name.text == typeName) {
                    val orig = el.propertyName?.text ?: el.name.text
                    val g = resolveSpecifierAnywhere(spec, usedInFile) ?: return null
                    return resolveTypeReferenceDecl(orig, g, visited)
                }
            }
        }
        return null
    }

    /** Walk a type declaration's members for the FIRST computed-symbol-key member; returns (rootName, rootDeclFile). */
    private fun firstComputedSymbolRoot(decl: Declaration, declFile: String, seen: MutableSet<Int>): Pair<String, String>? {
        val members: List<ClassElement> = when (decl) {
            is InterfaceDeclaration -> decl.members
            is TypeAliasDeclaration -> (decl.type as? TypeLiteral)?.members ?: emptyList()
            else -> emptyList()
        }
        return firstComputedSymbolRootInMembers(members, declFile, 0)
    }

    private fun firstComputedSymbolRootInMembers(members: List<ClassElement>, declFile: String, depth: Int): Pair<String, String>? {
        if (depth > 6) return null
        for (m in members) {
            if (m !is PropertyDeclaration) continue
            val nm = m.name
            if (nm is ComputedPropertyName) {
                val root = computedKeyRootName(nm.expression)
                // Only a genuine SYMBOL-valued key is non-inlinable in declaration emit (→ TS4023).
                // An enum-member / undefined / string-literal key is a DIFFERENT diagnostic
                // (TS2464 / TS2304) or is inlinable — those must NOT fire TS4023.
                if (root != null && computedKeyResolvesToSymbol(nm.expression, declFile)) {
                    val rootFile = resolveValueNameDeclaringFile(root, declFile) ?: declFile
                    return root to rootFile
                }
            }
            val pt = m.type
            if (pt is TypeLiteral) {
                firstComputedSymbolRootInMembers(pt.members, declFile, depth + 1)?.let { return it }
            }
        }
        return null
    }

    /** Leftmost identifier of a computed-property-name key expression (`Foo.sym` → "Foo", `SYMBOL` → "SYMBOL"). */
    private fun computedKeyRootName(expr: Expression): String? = when (expr) {
        is Identifier -> expr.text
        is PropertyAccessExpression -> computedKeyRootName(expr.expression)
        else -> null
    }

    /** Does a computed key expression resolve to a SYMBOL-valued declaration (`Symbol()`/`Symbol.for()` init or `unique symbol` type)? */
    private fun computedKeyResolvesToSymbol(keyExpr: Expression, declFile: String): Boolean = when (keyExpr) {
        is Identifier -> findVarDeclInFile(keyExpr.text, declFile)?.let { varDeclIsSymbol(it) } ?: false
        is PropertyAccessExpression -> {
            val root = keyExpr.expression
            if (root is Identifier) {
                findNamespaceMemberVarDecl(root.text, keyExpr.name.text, declFile)?.let { varDeclIsSymbol(it) } ?: false
            } else false
        }
        else -> false
    }

    private fun findVarDeclInFile(name: String, file: String): VariableDeclaration? {
        val r = fileResults[file] ?: return null
        for (stmt in r.sourceFile.statements) {
            if (stmt is VariableStatement) for (d in stmt.declarationList.declarations)
                if ((d.name as? Identifier)?.text == name) return d
        }
        return null
    }

    private fun findNamespaceMemberVarDecl(nsName: String, member: String, file: String): VariableDeclaration? {
        val r = fileResults[file] ?: return null
        for (stmt in r.sourceFile.statements) {
            if (stmt is ModuleDeclaration && (stmt.name as? Identifier)?.text == nsName) {
                val stmts = (stmt.body as? ModuleBlock)?.statements ?: continue
                for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations)
                    if ((d.name as? Identifier)?.text == member) return d
            }
        }
        return null
    }

    /** Is a variable declaration symbol-valued: `unique symbol`-typed or initialized with `Symbol(...)`/`Symbol.for(...)`? */
    private fun varDeclIsSymbol(d: VariableDeclaration): Boolean {
        val t = d.type
        if (t is TypeOperator && t.operator == SyntaxKind.UniqueKeyword) return true
        val init = d.initializer
        if (init is CallExpression) {
            val callee = init.expression
            if (callee is Identifier && callee.text == "Symbol") return true
            if (callee is PropertyAccessExpression && (callee.expression as? Identifier)?.text == "Symbol" && callee.name.text == "for") return true
        }
        return false
    }

    /** Find the file declaring a VALUE named [name], starting in [file] and following imports. */
    private fun resolveValueNameDeclaringFile(name: String, file: String): String? {
        val r = fileResults[file] ?: return null
        for (stmt in r.sourceFile.statements) {
            when (stmt) {
                is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == name) return file
                is VariableStatement -> for (d in stmt.declarationList.declarations) if ((d.name as? Identifier)?.text == name) return file
                is FunctionDeclaration -> if (stmt.name?.text == name) return file
                is ClassDeclaration -> if (stmt.name?.text == name) return file
                is EnumDeclaration -> if (stmt.name.text == name) return file
                else -> {}
            }
        }
        return resolveImportedSymbolFile(name, file)?.first
    }

    /** Is [name] available as a VALUE (not type-only) in [f]: value import, local value decl, or known global. */
    private fun isValueAccessibleIn(name: String, f: String): Boolean {
        val r = fileResults[f] ?: return true
        for (stmt in r.sourceFile.statements) {
            when (stmt) {
                is ImportDeclaration -> {
                    val clause = stmt.importClause ?: continue
                    if (clause.isTypeOnly) continue
                    if (clause.name?.text == name) return true
                    when (val nb = clause.namedBindings) {
                        is NamespaceImport -> if (nb.name.text == name) return true
                        is NamedImports -> for (el in nb.elements) if (el.name.text == name && !el.isTypeOnly) return true
                        else -> {}
                    }
                }
                is ImportEqualsDeclaration -> if (stmt.name.text == name) return true
                is VariableStatement -> for (d in stmt.declarationList.declarations) if ((d.name as? Identifier)?.text == name) return true
                is FunctionDeclaration -> if (stmt.name?.text == name) return true
                is ClassDeclaration -> if (stmt.name?.text == name) return true
                is EnumDeclaration -> if (stmt.name.text == name) return true
                is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == name) return true
                else -> {}
            }
        }
        // Do NOT consult `globals` here — the binder merges every file's locals into it
        // (Blocker #3 conflation), so a symbol exported from ANOTHER module would wrongly
        // count as accessible. Only a genuine lib global is accessible everywhere.
        return name in KNOWN_GLOBALS
    }

    /** Basename of a file path stripped of directory and module extension. */
    private fun moduleBasename(file: String): String {
        var b = file.substringAfterLast('/')
        for (ext in listOf(".d.ts", ".d.mts", ".d.cts", ".tsx", ".ts", ".mts", ".cts", ".jsx", ".js", ".mjs", ".cjs")) {
            if (b.endsWith(ext)) { b = b.dropLast(ext.length); break }
        }
        return b
    }

    // -----------------------------------------------------------------------
    // Unused declaration checking (TS6133/TS6196)
    // -----------------------------------------------------------------------

    /**
     * Tracks declarations and references within a scope for unused checking.
     */
    private class UnusedScope {
        /** All declarations in this scope: name → list of (declaration node, name node, kind). */
        val declarations = mutableListOf<UnusedDecl>()
        /** Names referenced in this scope or any nested scope. */
        val referencedNames = mutableSetOf<String>()
    }

    private data class UnusedDecl(
        val name: String,
        val nameNode: Node,       // Node whose pos gives the error position
        val declNode: Node,       // The full declaration node
        val spanLength: Int = 0,  // Explicit squiggle length (0 = use name.length)
        val isExported: Boolean,
        val isParameter: Boolean,
        val isTypeOnly: Boolean,  // interface, type alias
        val stmtIndex: Int = -1,  // index in parent statement list (for self-reference detection)
        val parentVarStmt: VariableStatement? = null, // parent statement for TS6199 grouping
        val parentBindingPattern: Node? = null, // parent ObjectBindingPattern/ArrayBindingPattern for TS6198 grouping
        val bindingElementCount: Int = 0, // total binding elements in parentBindingPattern
        val parentImportDecl: ImportDeclaration? = null, // parent import for TS6192 grouping
    )

    /**
     * Check for parameter properties declared in constructors but never accessed as `this.prop`.
     * Emits TS6138: "Property 'X' is declared but its value is never read."
     */
    private fun checkUnusedParameterProperties() {
        for (result in checkedResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            for (stmt in result.sourceFile.statements) {
                if (stmt is ClassDeclaration) checkUnusedParamPropsInClass(stmt, source, fileName)
            }
        }
    }

    private fun checkUnusedParamPropsInClass(classDecl: ClassDeclaration, source: String, fileName: String) {
        // Find the constructor
        val ctor = classDecl.members.filterIsInstance<Constructor>().firstOrNull() ?: return
        // Collect parameter properties (constructor params with access modifiers)
        val paramProps = ctor.parameters.filter { param ->
            param.modifiers.any { isParameterPropertyModifier(it) }
        }
        if (paramProps.isEmpty()) return

        // Collect names of parameter properties
        val paramPropNames = paramProps.mapNotNull { (it.name as? Identifier)?.text }.toSet()
        if (paramPropNames.isEmpty()) return

        // Find all `this.propName` accesses in ALL class members (including constructor body)
        val accessedViaThis = mutableSetOf<String>()
        for (member in classDecl.members) {
            when (member) {
                is MethodDeclaration -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is Constructor -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is GetAccessor -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is SetAccessor -> member.body?.let { collectThisPropertyAccesses(it.statements, accessedViaThis) }
                is PropertyDeclaration -> member.initializer?.let { collectThisAccessInExpr(it, accessedViaThis) }
                else -> {}
            }
        }

        // Emit TS6138 for parameter properties never accessed as this.prop
        for (param in paramProps) {
            val name = param.name as? Identifier ?: continue
            val propName = name.text
            if (propName.isEmpty()) continue
            if (propName in accessedViaThis) continue
            // Never accessed as this.propName → TS6138
            val start = name.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6138,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = propName.length,
            ))
        }
    }

    private fun collectThisPropertyAccesses(statements: List<Statement>, result: MutableSet<String>) {
        for (stmt in statements) {
            when (stmt) {
                is ExpressionStatement -> collectThisAccessInExpr(stmt.expression, result)
                is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { collectThisAccessInExpr(it, result) }
                }
                is ReturnStatement -> stmt.expression?.let { collectThisAccessInExpr(it, result) }
                is IfStatement -> {
                    collectThisAccessInExpr(stmt.expression, result)
                    collectThisPropertyAccesses(listOf(stmt.thenStatement), result)
                    stmt.elseStatement?.let { collectThisPropertyAccesses(listOf(it), result) }
                }
                is Block -> collectThisPropertyAccesses(stmt.statements, result)
                is ForStatement -> {
                    (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach {
                        it.initializer?.let { init -> collectThisAccessInExpr(init, result) }
                    }
                    stmt.condition?.let { collectThisAccessInExpr(it, result) }
                    stmt.incrementor?.let { collectThisAccessInExpr(it, result) }
                    collectThisPropertyAccesses(listOf(stmt.statement), result)
                }
                is WhileStatement -> {
                    collectThisAccessInExpr(stmt.expression, result)
                    collectThisPropertyAccesses(listOf(stmt.statement), result)
                }
                else -> {}
            }
        }
    }

    private fun collectThisAccessInExpr(expr: Expression, result: MutableSet<String>) {
        when (expr) {
            is PropertyAccessExpression -> {
                val obj = expr.expression
                if (obj is Identifier && obj.text == "this") {
                    // this.propName — collect the property name
                    result.add(expr.name.text)
                } else {
                    collectThisAccessInExpr(obj, result)
                }
            }
            is CallExpression -> {
                collectThisAccessInExpr(expr.expression, result)
                expr.arguments.forEach { collectThisAccessInExpr(it, result) }
            }
            is BinaryExpression -> {
                // B64.3-style iterative left-spine flatten to avoid StackOverflow.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                collectThisAccessInExpr(cur, result)
                while (rightStack.isNotEmpty()) collectThisAccessInExpr(rightStack.removeLast(), result)
            }
            is NewExpression -> {
                collectThisAccessInExpr(expr.expression, result)
                expr.arguments?.forEach { collectThisAccessInExpr(it, result) }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> collectThisPropertyAccesses(body.statements, result)
                is Expression -> collectThisAccessInExpr(body, result)
                else -> {}
            }
            is FunctionExpression -> collectThisPropertyAccesses(expr.body.statements, result)
            is ParenthesizedExpression -> collectThisAccessInExpr(expr.expression, result)
            is AsExpression -> collectThisAccessInExpr(expr.expression, result)
            is SatisfiesExpression -> collectThisAccessInExpr(expr.expression, result)
            is NonNullExpression -> collectThisAccessInExpr(expr.expression, result)
            is TypeAssertionExpression -> collectThisAccessInExpr(expr.expression, result)
            is PrefixUnaryExpression -> collectThisAccessInExpr(expr.operand, result)
            is PostfixUnaryExpression -> collectThisAccessInExpr(expr.operand, result)
            is ConditionalExpression -> {
                collectThisAccessInExpr(expr.condition, result)
                collectThisAccessInExpr(expr.whenTrue, result)
                collectThisAccessInExpr(expr.whenFalse, result)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { collectThisAccessInExpr(it, result) }
            is TemplateExpression -> expr.templateSpans.forEach { collectThisAccessInExpr(it.expression, result) }
            is ElementAccessExpression -> {
                val obj = expr.expression
                if (obj is Identifier && obj.text == "this") {
                    // this["propName"] — collect the string-literal key only
                    val arg = expr.argumentExpression
                    if (arg is StringLiteralNode) result.add(arg.text)
                } else {
                    collectThisAccessInExpr(obj, result)
                }
                collectThisAccessInExpr(expr.argumentExpression, result)
            }
            is TaggedTemplateExpression -> {
                collectThisAccessInExpr(expr.tag, result)
                val t = expr.template
                if (t is TemplateExpression) {
                    for (span in t.templateSpans) collectThisAccessInExpr(span.expression, result)
                }
            }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> collectThisAccessInExpr(prop.initializer, result)
                    is SpreadAssignment -> collectThisAccessInExpr(prop.expression, result)
                    is MethodDeclaration -> prop.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    is GetAccessor -> prop.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    is SetAccessor -> prop.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    else -> {}
                }
            }
            is SpreadElement -> collectThisAccessInExpr(expr.expression, result)
            is AwaitExpression -> collectThisAccessInExpr(expr.expression, result)
            is YieldExpression -> expr.expression?.let { collectThisAccessInExpr(it, result) }
            is VoidExpression -> collectThisAccessInExpr(expr.expression, result)
            is DeleteExpression -> collectThisAccessInExpr(expr.expression, result)
            is TypeOfExpression -> collectThisAccessInExpr(expr.expression, result)
            is CommaListExpression -> for (e in expr.elements) collectThisAccessInExpr(e, result)
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    is Constructor -> m.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    is GetAccessor -> m.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    is SetAccessor -> m.body?.let { collectThisPropertyAccesses(it.statements, result) }
                    is PropertyDeclaration -> m.initializer?.let { collectThisAccessInExpr(it, result) }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    /**
     * 17.189: TS6133 for unused `infer T` parameters in conditional types.
     * E.g. `type Length<T> = T extends ArrayLike<infer U> ? number : never`
     * — `U` is declared by `infer U` but never used in the true branch.
     * Squiggle covers `infer U` (length = `infer ` + name).
     */
    private fun checkUnusedInferParameters() {
        for (result in checkedResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            walkUnusedInferInStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkUnusedInferInStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) when (stmt) {
            is TypeAliasDeclaration -> walkUnusedInferInTypeNode(stmt.type, source, fileName)
            is InterfaceDeclaration -> {
                for (m in stmt.members) when (m) {
                    is PropertyDeclaration -> m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    is MethodDeclaration -> {
                        m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        for (p in m.parameters) p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    }
                    is IndexSignature -> m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    else -> {}
                }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) when (m) {
                    is PropertyDeclaration -> m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    is MethodDeclaration -> {
                        m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        for (p in m.parameters) p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        m.body?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
                    }
                    is GetAccessor -> {
                        m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        m.body?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
                    }
                    is SetAccessor -> {
                        for (p in m.parameters) p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        m.body?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
                    }
                    is Constructor -> {
                        for (p in m.parameters) p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        m.body?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is FunctionDeclaration -> {
                stmt.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                for (p in stmt.parameters) p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                stmt.body?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                }
            }
            is Block -> walkUnusedInferInStmts(stmt.statements, source, fileName)
            is IfStatement -> {
                walkUnusedInferInStmts(listOf(stmt.thenStatement), source, fileName)
                stmt.elseStatement?.let { walkUnusedInferInStmts(listOf(it), source, fileName) }
            }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                    d.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                }
                walkUnusedInferInStmts(listOf(stmt.statement), source, fileName)
            }
            is ForInStatement -> walkUnusedInferInStmts(listOf(stmt.statement), source, fileName)
            is ForOfStatement -> walkUnusedInferInStmts(listOf(stmt.statement), source, fileName)
            is WhileStatement -> walkUnusedInferInStmts(listOf(stmt.statement), source, fileName)
            is DoStatement -> walkUnusedInferInStmts(listOf(stmt.statement), source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkUnusedInferInStmts(clause.statements, source, fileName)
                        is DefaultClause -> walkUnusedInferInStmts(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkUnusedInferInStmts(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
                stmt.finallyBlock?.let { walkUnusedInferInStmts(it.statements, source, fileName) }
            }
            is LabeledStatement -> walkUnusedInferInStmts(listOf(stmt.statement), source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                walkUnusedInferInStmts(it.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun walkUnusedInferInTypeNode(type: TypeNode, source: String, fileName: String) {
        when (type) {
            is ConditionalType -> {
                // Collect infer-declared names from extendsType, then check
                // whether each is referenced as a TypeReference in trueType.
                val inferNames = mutableMapOf<String, InferType>()
                collectInferDecls(type.extendsType, inferNames)
                if (inferNames.isNotEmpty()) {
                    val refs = mutableSetOf<String>()
                    collectTypeReferenceNames(type.trueType, refs)
                    for ((name, inferNode) in inferNames) {
                        if (name in refs) continue
                        // Squiggle covers `infer U` — from inferNode.pos to the
                        // typeParameter name's end.
                        val start = inferNode.pos
                        val nameEnd = inferNode.typeParameter.name.pos + inferNode.typeParameter.name.text.length
                        val length = (nameEnd - start).coerceAtLeast(1)
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "'$name' is declared but its value is never read.",
                            category = DiagnosticCategory.Error,
                            code = 6133,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
                // Recurse into nested conditionals
                walkUnusedInferInTypeNode(type.checkType, source, fileName)
                walkUnusedInferInTypeNode(type.extendsType, source, fileName)
                walkUnusedInferInTypeNode(type.trueType, source, fileName)
                walkUnusedInferInTypeNode(type.falseType, source, fileName)
            }
            is UnionType -> type.types.forEach { walkUnusedInferInTypeNode(it, source, fileName) }
            is IntersectionType -> type.types.forEach { walkUnusedInferInTypeNode(it, source, fileName) }
            is ParenthesizedType -> walkUnusedInferInTypeNode(type.type, source, fileName)
            is ArrayType -> walkUnusedInferInTypeNode(type.elementType, source, fileName)
            is TupleType -> type.elements.forEach { walkUnusedInferInTypeNode(it, source, fileName) }
            is TypeOperator -> walkUnusedInferInTypeNode(type.type, source, fileName)
            is IndexedAccessType -> {
                walkUnusedInferInTypeNode(type.objectType, source, fileName)
                walkUnusedInferInTypeNode(type.indexType, source, fileName)
            }
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) } }
                walkUnusedInferInTypeNode(type.type, source, fileName)
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) } }
                walkUnusedInferInTypeNode(type.type, source, fileName)
            }
            is TypeLiteral -> {
                for (m in type.members) when (m) {
                    is PropertyDeclaration -> m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    is MethodDeclaration -> {
                        m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                        for (p in m.parameters) p.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    }
                    is IndexSignature -> m.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                    else -> {}
                }
            }
            is MappedType -> {
                type.type?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                type.nameType?.let { walkUnusedInferInTypeNode(it, source, fileName) }
                type.typeParameter.constraint?.let { walkUnusedInferInTypeNode(it, source, fileName) }
            }
            is RestType -> walkUnusedInferInTypeNode(type.type, source, fileName)
            is OptionalType -> walkUnusedInferInTypeNode(type.type, source, fileName)
            is TypeReference -> type.typeArguments?.forEach { walkUnusedInferInTypeNode(it, source, fileName) }
            else -> {}
        }
    }

    private fun collectInferDecls(type: TypeNode, out: MutableMap<String, InferType>) {
        when (type) {
            is InferType -> out[type.typeParameter.name.text] = type
            is UnionType -> type.types.forEach { collectInferDecls(it, out) }
            is IntersectionType -> type.types.forEach { collectInferDecls(it, out) }
            is ParenthesizedType -> collectInferDecls(type.type, out)
            is ArrayType -> collectInferDecls(type.elementType, out)
            is TupleType -> type.elements.forEach { collectInferDecls(it, out) }
            is TypeReference -> type.typeArguments?.forEach { collectInferDecls(it, out) }
            is IndexedAccessType -> {
                collectInferDecls(type.objectType, out)
                collectInferDecls(type.indexType, out)
            }
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { collectInferDecls(it, out) } }
                collectInferDecls(type.type, out)
            }
            // Iter9 walker parity: mirror sibling walkers (walkUnusedInferInTypeNode,
            // collectTypeReferenceNames) to cover constructor types, type literals,
            // mapped types, type operators, rest/optional tuple elements, and
            // conditional types. Without these branches an `infer X` inside e.g.
            // `infer R extends new (...args) => infer U` would be missed during
            // declaration collection, silently dropping TS6133 candidates.
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { collectInferDecls(it, out) } }
                collectInferDecls(type.type, out)
            }
            is TypeLiteral -> {
                for (m in type.members) when (m) {
                    is PropertyDeclaration -> m.type?.let { collectInferDecls(it, out) }
                    is MethodDeclaration -> {
                        m.type?.let { collectInferDecls(it, out) }
                        for (p in m.parameters) p.type?.let { collectInferDecls(it, out) }
                    }
                    is IndexSignature -> m.type?.let { collectInferDecls(it, out) }
                    else -> {}
                }
            }
            is MappedType -> {
                type.type?.let { collectInferDecls(it, out) }
                type.nameType?.let { collectInferDecls(it, out) }
                type.typeParameter.constraint?.let { collectInferDecls(it, out) }
            }
            is TypeOperator -> collectInferDecls(type.type, out)
            is RestType -> collectInferDecls(type.type, out)
            is OptionalType -> collectInferDecls(type.type, out)
            // Intentionally NOT walking ConditionalType here: nested conditionals
            // introduce their own infer-scope (each conditional's extends clause is
            // an isolated scope). Outer walker handles top-level conditional via
            // [walkUnusedInferInTypeNode]; if a nested conditional appears inside an
            // extendsType, its own `infer X` declarations belong to that inner
            // conditional, not the outer one we're collecting for.
            else -> {}
        }
    }

    private fun collectTypeReferenceNames(type: TypeNode, out: MutableSet<String>) {
        when (type) {
            is TypeReference -> {
                val n = type.typeName
                if (n is Identifier) out.add(n.text)
                type.typeArguments?.forEach { collectTypeReferenceNames(it, out) }
            }
            is UnionType -> type.types.forEach { collectTypeReferenceNames(it, out) }
            is IntersectionType -> type.types.forEach { collectTypeReferenceNames(it, out) }
            is ParenthesizedType -> collectTypeReferenceNames(type.type, out)
            is ArrayType -> collectTypeReferenceNames(type.elementType, out)
            is TupleType -> type.elements.forEach { collectTypeReferenceNames(it, out) }
            is TypeOperator -> collectTypeReferenceNames(type.type, out)
            is IndexedAccessType -> {
                collectTypeReferenceNames(type.objectType, out)
                collectTypeReferenceNames(type.indexType, out)
            }
            is ConditionalType -> {
                collectTypeReferenceNames(type.checkType, out)
                collectTypeReferenceNames(type.extendsType, out)
                collectTypeReferenceNames(type.trueType, out)
                collectTypeReferenceNames(type.falseType, out)
            }
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeReferenceNames(it, out) } }
                collectTypeReferenceNames(type.type, out)
            }
            is MappedType -> {
                type.type?.let { collectTypeReferenceNames(it, out) }
                type.nameType?.let { collectTypeReferenceNames(it, out) }
                type.typeParameter.constraint?.let { collectTypeReferenceNames(it, out) }
            }
            // Iter9 walker parity: cover constructor types, type literals, rest /
            // optional tuple elements. Reference-name collection for TS6133 must
            // see ALL references in the trueType — an `infer R` used inside e.g.
            // `infer R extends new (...args) => R` or `{ value: R }` would
            // otherwise be miscounted as unused.
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeReferenceNames(it, out) } }
                collectTypeReferenceNames(type.type, out)
            }
            is TypeLiteral -> {
                for (m in type.members) when (m) {
                    is PropertyDeclaration -> m.type?.let { collectTypeReferenceNames(it, out) }
                    is MethodDeclaration -> {
                        m.type?.let { collectTypeReferenceNames(it, out) }
                        for (p in m.parameters) p.type?.let { collectTypeReferenceNames(it, out) }
                    }
                    is IndexSignature -> m.type?.let { collectTypeReferenceNames(it, out) }
                    else -> {}
                }
            }
            is RestType -> collectTypeReferenceNames(type.type, out)
            is OptionalType -> collectTypeReferenceNames(type.type, out)
            else -> {}
        }
    }

    private fun checkUnusedDeclarations() {
        for (result in checkedResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            // B98.r15: a checkJs `.js`/`.cjs` file with CommonJS exports (`exports.x = …`,
            // `module.exports = …`) is a MODULE — its file-level locals are module-scoped (not
            // global), so unused locals ARE checked (TS6133). `isModuleFile` only recognizes ES
            // import/export, so JS CommonJS modules were wrongly treated as scripts and skipped.
            val isModule = isModuleFile(result.sourceFile.statements) ||
                (isJsLikeFileName(result.sourceFile.fileName) &&
                    hasCommonJsExportAssignment(result.sourceFile.statements))
            checkUnusedInStatements(
                result.sourceFile.statements,
                source,
                result.sourceFile.fileName,
                isTopLevel = true,
                isModuleScope = isModule,
            )
        }
    }

    /**
     * Check if a file is a module (has import/export statements).
     * Non-module files' top-level declarations are global and not checked for unused.
     */
    private fun isModuleFile(statements: List<Statement>): Boolean {
        for (stmt in statements) {
            when (stmt) {
                is ImportDeclaration -> return true
                // tsc isAnExternalModuleIndicatorNode: an import-equals counts ONLY with an
                // ExternalModuleReference (`= require(...)`) or an `export` modifier — a bare
                // entity-name alias (`import fs = module`) leaves the file a SCRIPT.
                is ImportEqualsDeclaration ->
                    if (stmt.moduleReference is ExternalModuleReference ||
                        ModifierFlag.Export in stmt.modifiers) return true
                is ExportDeclaration -> return true
                is ExportAssignment -> return true
                // VariableStatement is not a Declaration but can have export modifier
                is VariableStatement -> if (ModifierFlag.Export in stmt.modifiers) return true
                else -> {
                    if (stmt is Declaration) {
                        val modifiers = when (stmt) {
                            is FunctionDeclaration -> stmt.modifiers
                            is ClassDeclaration -> stmt.modifiers
                            is EnumDeclaration -> stmt.modifiers
                            is InterfaceDeclaration -> stmt.modifiers
                            is TypeAliasDeclaration -> stmt.modifiers
                            is ModuleDeclaration -> stmt.modifiers
                            else -> emptySet()
                        }
                        if (ModifierFlag.Export in modifiers) return true
                    }
                }
            }
        }
        return false
    }

    /**
     * B98.r15: detect a CommonJS module indicator in a JS file's top-level statements:
     * `exports.x = …`, `module.exports = …`, or `module.exports.x = …`. Used to treat such
     * files as modules for unused-local checking (TS6133).
     */
    private fun hasCommonJsExportAssignment(statements: List<Statement>): Boolean {
        fun isExportsTarget(e: Expression): Boolean = when (e) {
            // `exports`
            is Identifier -> e.text == "exports"
            is PropertyAccessExpression -> {
                val recv = e.expression
                // `module.exports` or `exports.x` or `module.exports.x`
                (recv is Identifier && recv.text == "module" && e.name.text == "exports") ||
                    (recv is Identifier && recv.text == "exports") ||
                    isExportsTarget(recv)
            }
            else -> false
        }
        for (stmt in statements) {
            if (stmt !is ExpressionStatement) continue
            val expr = stmt.expression
            if (expr is BinaryExpression && expr.operator == SyntaxKind.Equals && isExportsTarget(expr.left)) {
                return true
            }
        }
        return false
    }

    /**
     * Check if a file is an ES module (has actual ES import/export statements).
     * Unlike [isModuleFile], this does NOT count `import x = namespace` declarations
     * as module-making — those are legacy TypeScript namespace aliases.
     * Used for TS2694 namespace name qualification in module files.
     */
    private fun isEsModuleFile(statements: List<Statement>): Boolean {
        for (stmt in statements) {
            when (stmt) {
                is ImportDeclaration -> return true   // import { x } from "..."
                // ImportEqualsDeclaration: import x = namespace is NOT ES module
                is ExportDeclaration -> return true   // export { x } or export * from
                is ExportAssignment -> return true    // export default or export =
                else -> {
                    if (stmt is Declaration) {
                        val modifiers = when (stmt) {
                            is FunctionDeclaration -> stmt.modifiers
                            is ClassDeclaration -> stmt.modifiers
                            is EnumDeclaration -> stmt.modifiers
                            is InterfaceDeclaration -> stmt.modifiers
                            is TypeAliasDeclaration -> stmt.modifiers
                            is ModuleDeclaration -> stmt.modifiers
                            else -> emptySet()
                        }
                        if (ModifierFlag.Export in modifiers) return true
                    }
                }
            }
        }
        return false
    }

    private fun checkUnusedInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        isTopLevel: Boolean,
        isModuleScope: Boolean = false,
    ) {
        // Skip file-level declarations in non-module files (they're global)
        if (isTopLevel && !isModuleScope) {
            // Still recurse into nested scopes (namespace bodies, function bodies)
            for (stmt in statements) {
                checkUnusedInNestedScopes(stmt, source, fileName, siblingStatements = statements)
            }
            return
        }

        val scope = UnusedScope()

        // 1. Collect declarations (with statement index for self-reference detection)
        for ((idx, stmt) in statements.withIndex()) {
            collectUnusedDeclarations(stmt, scope, isTopLevel, stmtIndex = idx)
        }

        // 2. Collect references per statement (for self-reference detection)
        val refsPerStmt = Array(statements.size) { mutableSetOf<String>() }
        for ((idx, stmt) in statements.withIndex()) {
            val stmtScope = UnusedScope()
            collectUnusedReferences(stmt, stmtScope)
            refsPerStmt[idx] = stmtScope.referencedNames
            scope.referencedNames.addAll(stmtScope.referencedNames)
        }

        // 3. Report unreferenced declarations
        // A declaration is considered unused if:
        // - It's not referenced at all, OR
        // - It's only referenced from within its own declaration (self-reference)
        val unusedDecls = mutableListOf<UnusedDecl>()
        for (decl in scope.declarations) {
            val isExternallyReferenced = if (decl.stmtIndex >= 0) {
                refsPerStmt.withIndex().any { (idx, refs) ->
                    idx != decl.stmtIndex && decl.name in refs
                }
            } else {
                decl.name in scope.referencedNames
            }
            if (isExternallyReferenced) continue
            // Shorthand underscore elements in ObjectBindingPattern still contribute to TS6198
            val isShorthandUnderscore = decl.name.startsWith("_") &&
                decl.parentBindingPattern is ObjectBindingPattern &&
                (decl.declNode as? BindingElement)?.propertyName == null
            // B98.r122: a `_`-prefixed unused name is exempt from TS6133 ONLY for parameters,
            // imports, and destructuring binding-elements (TypeScript's
            // isValidUnusedLocalDeclaration). Namespaces, plain var/let/const, functions,
            // classes, enums, type-aliases and interfaces are still reported. Shorthand-`_`
            // destructuring stays in the list for TS6198 grouping (the 5283 gate below
            // suppresses its individual TS6133).
            val underscoreExempt = decl.name.startsWith("_") &&
                (decl.isParameter || decl.parentImportDecl != null ||
                    (decl.parentBindingPattern != null && !isShorthandUnderscore))
            if (underscoreExempt) continue
            if (decl.isExported) continue

            if (decl.isParameter) {
                if (!options.noUnusedParameters) continue
            } else {
                if (!options.noUnusedLocals) continue
            }

            unusedDecls.add(decl)
        }

        // Check for TS6199: if ALL declarations from a VariableStatement are unused,
        // emit a single "All variables are unused" instead of individual TS6133
        val ts6199Stmts = mutableSetOf<VariableStatement>()
        val declsByVarStmt = unusedDecls.filter { it.parentVarStmt != null }
            .groupBy { it.parentVarStmt!! }
        for ((varStmt, decls) in declsByVarStmt) {
            val totalDeclCount = varStmt.declarationList.declarations.size
            if (decls.size == totalDeclCount && totalDeclCount > 1) {
                ts6199Stmts.add(varStmt)
                // Emit TS6199 for the entire statement
                // Span covers from `var` keyword to the end of the statement line (including `;`)
                val stmtStart = varStmt.pos
                val lineEnd = source.indexOf('\n', stmtStart).let { if (it < 0) source.length else it }
                val spanLength = source.substring(stmtStart, lineEnd).trimEnd().length
                val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                diagnostics.add(Diagnostic(
                    message = "All variables are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6199,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = stmtStart,
                    length = spanLength,
                ))
            }
        }

        // Check for TS6198: if ALL elements from a destructuring pattern are unused,
        // emit a single "All destructured elements are unused" instead of individual TS6133
        // TS6198 only fires for ObjectBindingPattern, not ArrayBindingPattern
        val ts6198Patterns = mutableSetOf<Node>()
        val declsByPattern = unusedDecls.filter { it.parentBindingPattern is ObjectBindingPattern }
            .groupBy { it.parentBindingPattern!! }
        for ((pattern, decls) in declsByPattern) {
            val totalCount = decls.first().bindingElementCount
            // Shorthand underscore-prefixed elements (e.g., `{ _a1 }` not `{ a: _a1 }`)
            // are already included in `decls` (not skipped at the filter above), so no
            // separate counting is needed — just compare decls.size with totalCount.
            if (decls.size == totalCount && totalCount > 1) {
                ts6198Patterns.add(pattern)
                val patStart = pattern.pos
                val spanLength = computeBindingPatternSpan(source, patStart, pattern)
                val (line, character) = getLineAndCharacterOfPosition(source, patStart)
                diagnostics.add(Diagnostic(
                    message = "All destructured elements are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6198,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = patStart,
                    length = spanLength,
                ))
            }
        }

        // Check for TS6192: if ALL bindings from an import declaration are unused,
        // emit a single "All imports in import declaration are unused." instead of individual TS6133.
        val ts6192Imports = mutableSetOf<ImportDeclaration>()
        val declsByImport = unusedDecls.filter { it.parentImportDecl != null }
            .groupBy { it.parentImportDecl!! }
        for ((importDecl, decls) in declsByImport) {
            val clause = importDecl.importClause ?: continue
            // Count total non-type-only bindings
            var totalBindings = 0
            if (clause.name != null) totalBindings++ // default import
            when (val nb = clause.namedBindings) {
                is NamedImports -> totalBindings += nb.elements.count { !it.isTypeOnly }
                is NamespaceImport -> totalBindings++
                else -> {}
            }
            if (totalBindings > 1 && decls.size == totalBindings) {
                ts6192Imports.add(importDecl)
                // Emit TS6192 for the entire import statement
                val stmtStart = importDecl.pos
                val stmtLineEnd = source.indexOf('\n', stmtStart).let { if (it < 0) source.length else it }
                val spanLength = source.substring(stmtStart, stmtLineEnd).trimEnd().length
                val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                diagnostics.add(Diagnostic(
                    message = "All imports in import declaration are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6192,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = stmtStart,
                    length = spanLength,
                ))
            }
        }

        for (decl in unusedDecls) {
            // Skip declarations already handled by TS6199
            if (decl.parentVarStmt != null && decl.parentVarStmt in ts6199Stmts) continue
            // Skip declarations already handled by TS6198
            if (decl.parentBindingPattern != null && decl.parentBindingPattern in ts6198Patterns) continue
            // Skip declarations already handled by TS6192
            if (decl.parentImportDecl != null && decl.parentImportDecl in ts6192Imports) continue
            // B98.r122: only `_`-prefixed destructuring elements that made it through for TS6198
            // grouping skip individual TS6133. Namespaces / plain vars / functions / classes
            // with a `_` prefix ARE reported (TS's isValidUnusedLocalDeclaration).
            if (decl.name.startsWith("_") && decl.parentBindingPattern != null) continue

            val nameNode = decl.nameNode
            // For single-element destructuring, use the pattern span instead of the name
            val usePatternSpan = decl.parentBindingPattern is ObjectBindingPattern && decl.bindingElementCount == 1
            // For import specifiers with aliases (e.g. `test2 as t2`), point to the local name `t2`
            val start = when {
                usePatternSpan -> decl.parentBindingPattern.pos
                nameNode is ImportSpecifier && nameNode.propertyName != null -> nameNode.name.pos
                else -> nameNode.pos
            }
            // Compute squiggle length: for imports using whole-statement node,
            // measure the line text; otherwise use identifier text length
            val length = when {
                usePatternSpan -> computeBindingPatternSpan(source, start, decl.parentBindingPattern)
                decl.spanLength > 0 -> decl.spanLength
                nameNode is ImportDeclaration -> {
                    // Squiggle covers the import statement up to semicolon (excluding comments)
                    val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
                    var endPos = start
                    var idx = start
                    while (idx < lineEnd) {
                        val ch = source[idx]
                        if (ch == ';') { endPos = idx + 1; break }
                        if (ch == '/' && idx + 1 < lineEnd && (source[idx + 1] == '/' || source[idx + 1] == '*')) {
                            while (endPos > start && source[endPos - 1].let { it == ' ' || it == '\t' }) endPos--
                            break
                        }
                        endPos = idx + 1
                        idx++
                    }
                    if (endPos <= start) endPos = start + 1
                    endPos - start
                }
                else -> decl.name.length
            }
            val (line, character) = getLineAndCharacterOfPosition(source, start)

            // Classes, interfaces, type aliases, enums use TS6196 "declared but never used"
            // Variables, functions, parameters use TS6133 "declared but its value is never read"
            val isTypeDecl = decl.declNode is ClassDeclaration || decl.declNode is InterfaceDeclaration
                    || decl.declNode is TypeAliasDeclaration || decl.declNode is EnumDeclaration
            val code = if (isTypeDecl) 6196 else 6133
            val message = if (isTypeDecl) {
                "'${decl.name}' is declared but never used."
            } else {
                "'${decl.name}' is declared but its value is never read."
            }

            diagnostics.add(Diagnostic(
                message = message,
                category = DiagnosticCategory.Error,
                code = code,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }

        // 4. Recurse into nested scopes (function bodies, class bodies, etc.)
        for (stmt in statements) {
            checkUnusedInNestedScopes(stmt, source, fileName, siblingStatements = statements)
        }
    }

    private fun collectUnusedDeclarations(
        stmt: Statement,
        scope: UnusedScope,
        isTopLevel: Boolean,
        stmtIndex: Int = -1,
    ) {
        when (stmt) {
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                for (decl in stmt.declarationList.declarations) {
                    collectVarDeclNames(decl.name, decl, isExported, scope, stmtIndex, parentVarStmt = stmt)
                }
            }
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val name = stmt.name ?: return
                val isExported = ModifierFlag.Export in stmt.modifiers ||
                    ModifierFlag.Default in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = name.text,
                    nameNode = name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val name = stmt.name ?: return
                val isExported = ModifierFlag.Export in stmt.modifiers ||
                    ModifierFlag.Default in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = name.text,
                    nameNode = name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            is InterfaceDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = true,
                    stmtIndex = stmtIndex,
                ))
            }
            is TypeAliasDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = true,
                    stmtIndex = stmtIndex,
                ))
            }
            is EnumDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val nameNode = stmt.name
                if (nameNode is Identifier) {
                    val isExported = ModifierFlag.Export in stmt.modifiers
                    scope.declarations.add(UnusedDecl(
                        name = nameNode.text,
                        nameNode = nameNode,
                        declNode = stmt,
                        isExported = isExported,
                        isParameter = false,
                        isTypeOnly = false,
                        stmtIndex = stmtIndex,
                    ))
                }
            }
            is ImportDeclaration -> {
                if (stmt.importClause?.isTypeOnly == true) return
                val clause = stmt.importClause ?: return
                val bindings = clause.namedBindings
                // Count total non-type-only bindings to determine nameNode strategy:
                // - 1 binding: use whole import statement for TS6133 (whole-statement squiggle)
                // - 2+ bindings: use individual binding names for TS6133 (per-binding squiggle)
                //   (when all unused, TS6192 will replace individual TS6133s)
                var totalBindingCount = 0
                if (clause.name != null) totalBindingCount++
                when (bindings) {
                    is NamedImports -> totalBindingCount += bindings.elements.count { !it.isTypeOnly }
                    is NamespaceImport -> totalBindingCount++
                    else -> {}
                }
                val useStatementAsNameNode = totalBindingCount <= 1
                when (bindings) {
                    is NamedImports -> {
                        for (spec in bindings.elements) {
                            if (spec.isTypeOnly) continue
                            scope.declarations.add(UnusedDecl(
                                name = spec.name.text,
                                nameNode = if (useStatementAsNameNode) stmt else spec,
                                declNode = stmt,
                                isExported = false,
                                isParameter = false,
                                isTypeOnly = false,
                                stmtIndex = stmtIndex,
                                parentImportDecl = stmt,
                            ))
                        }
                    }
                    is NamespaceImport -> {
                        scope.declarations.add(UnusedDecl(
                            name = bindings.name.text,
                            nameNode = if (useStatementAsNameNode) stmt else bindings.name,
                            declNode = stmt,
                            isExported = false,
                            isParameter = false,
                            isTypeOnly = false,
                            stmtIndex = stmtIndex,
                            parentImportDecl = stmt,
                        ))
                    }
                    else -> {}
                }
                // Default import
                if (clause.name != null) {
                    scope.declarations.add(UnusedDecl(
                        name = clause.name.text,
                        nameNode = if (useStatementAsNameNode) stmt else clause.name,
                        declNode = stmt,
                        isExported = false,
                        isParameter = false,
                        isTypeOnly = false,
                        stmtIndex = stmtIndex,
                        parentImportDecl = stmt,
                    ))
                }
            }
            is ImportEqualsDeclaration -> {
                val isExported = ModifierFlag.Export in stmt.modifiers
                scope.declarations.add(UnusedDecl(
                    name = stmt.name.text,
                    nameNode = stmt.name,
                    declNode = stmt,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                ))
            }
            else -> {}
        }
    }

    private fun collectVarDeclNames(
        name: Expression,
        declNode: Node,
        isExported: Boolean,
        scope: UnusedScope,
        stmtIndex: Int = -1,
        parentVarStmt: VariableStatement? = null,
        parentBindingPattern: Node? = null,
        bindingElementCount: Int = 0,
    ) {
        when (name) {
            is Identifier -> {
                scope.declarations.add(UnusedDecl(
                    name = name.text,
                    nameNode = name,
                    declNode = declNode,
                    isExported = isExported,
                    isParameter = false,
                    isTypeOnly = false,
                    stmtIndex = stmtIndex,
                    parentVarStmt = parentVarStmt,
                    parentBindingPattern = parentBindingPattern,
                    bindingElementCount = bindingElementCount,
                ))
            }
            is ObjectBindingPattern -> {
                // When a rest element exists, non-rest siblings are intentional
                // extractions and should not be flagged as unused
                val hasRest = name.elements.any { it.dotDotDotToken }
                val count = if (hasRest) name.elements.count { it.dotDotDotToken } else name.elements.size
                for (element in name.elements) {
                    if (hasRest && !element.dotDotDotToken) continue // skip extraction vars
                    // Rest elements get identifier span (no parentBindingPattern), non-rest get pattern span
                    collectVarDeclNames(element.name, element, isExported, scope, stmtIndex, parentVarStmt,
                        parentBindingPattern = if (element.dotDotDotToken) null else name,
                        bindingElementCount = if (element.dotDotDotToken) 0 else count)
                }
            }
            is ArrayBindingPattern -> {
                val hasRest = name.elements.any { it is BindingElement && it.dotDotDotToken }
                val count = if (hasRest) name.elements.count { it is BindingElement && it.dotDotDotToken }
                    else name.elements.count { it is BindingElement }
                for (element in name.elements) {
                    if (element is BindingElement) {
                        if (hasRest && !element.dotDotDotToken) continue // skip extraction vars
                        collectVarDeclNames(element.name, element, isExported, scope, stmtIndex, parentVarStmt,
                            parentBindingPattern = name, bindingElementCount = count)
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Collect destructuring parameter binding element names for unused checking.
     * For `([a])`, collects `a` with span covering the binding pattern.
     */
    private fun collectDestructuringParamNames(
        pattern: Expression,
        param: Parameter,
        scope: UnusedScope,
    ) {
        // For destructuring parameters, the squiggle behavior depends on how many elements
        // are unused: single-element → pattern span, all unused → TS6198 pattern span,
        // some unused → individual name span.
        when (pattern) {
            is ArrayBindingPattern -> {
                val count = pattern.elements.count { it is BindingElement && !it.dotDotDotToken }
                for (element in pattern.elements) {
                    if (element is BindingElement) {
                        val name = element.name
                        if (name is Identifier) {
                            scope.declarations.add(UnusedDecl(
                                name = name.text,
                                nameNode = name,
                                declNode = param,
                                isExported = false,
                                isParameter = true,
                                isTypeOnly = false,
                                parentBindingPattern = pattern,
                                bindingElementCount = count,
                            ))
                        }
                    }
                }
            }
            is ObjectBindingPattern -> {
                val count = pattern.elements.count { !it.dotDotDotToken }
                for (element in pattern.elements) {
                    val name = element.name
                    if (name is Identifier) {
                        scope.declarations.add(UnusedDecl(
                            name = name.text,
                            nameNode = name,
                            declNode = param,
                            isExported = false,
                            isParameter = true,
                            isTypeOnly = false,
                            parentBindingPattern = pattern,
                            bindingElementCount = count,
                        ))
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Collect all name references from a statement (including nested expressions).
     * This is used for unused declaration checking — it marks names as "referenced"
     * when they appear in value or type positions.
     */
    private fun collectUnusedReferences(stmt: Statement, scope: UnusedScope) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { collectRefsFromExpr(it, scope) }
                    decl.type?.let { collectRefsFromType(it, scope) }
                }
            }
            is ExpressionStatement -> collectRefsFromExpr(stmt.expression, scope)
            is ReturnStatement -> stmt.expression?.let { collectRefsFromExpr(it, scope) }
            is IfStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.thenStatement, scope)
                stmt.elseStatement?.let { collectUnusedReferences(it, scope) }
            }
            is Block -> stmt.statements.forEach { collectUnusedReferences(it, scope) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { collectRefsFromExpr(it, scope) }
                        }
                    }
                    is Expression -> collectRefsFromExpr(init, scope)
                    else -> {}
                }
                stmt.condition?.let { collectRefsFromExpr(it, scope) }
                stmt.incrementor?.let { collectRefsFromExpr(it, scope) }
                collectUnusedReferences(stmt.statement, scope)
            }
            is ForInStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is ForOfStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is WhileStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is DoStatement -> {
                collectUnusedReferences(stmt.statement, scope)
                collectRefsFromExpr(stmt.expression, scope)
            }
            is SwitchStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            collectRefsFromExpr(clause.expression, scope)
                            clause.statements.forEach { collectUnusedReferences(it, scope) }
                        }
                        is DefaultClause -> {
                            clause.statements.forEach { collectUnusedReferences(it, scope) }
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> stmt.expression?.let { collectRefsFromExpr(it, scope) }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectUnusedReferences(it, scope) }
                stmt.catchClause?.block?.statements?.forEach { collectUnusedReferences(it, scope) }
                stmt.finallyBlock?.statements?.forEach { collectUnusedReferences(it, scope) }
            }
            is LabeledStatement -> collectUnusedReferences(stmt.statement, scope)
            is WithStatement -> {
                collectRefsFromExpr(stmt.expression, scope)
                collectUnusedReferences(stmt.statement, scope)
            }
            is FunctionDeclaration -> {
                // References inside function bodies count as usage of outer scope names
                // Type parameters shadow outer names, so collect into inner scope first
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.body?.statements?.forEach { collectUnusedReferences(it, innerScope) }
                for (param in stmt.parameters) {
                    param.initializer?.let { collectRefsFromExpr(it, innerScope) }
                    param.type?.let { collectRefsFromType(it, innerScope) }
                    param.decorators?.forEach { collectRefsFromExpr(it.expression, innerScope) }
                }
                stmt.type?.let { collectRefsFromType(it, innerScope) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is ClassDeclaration -> {
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        collectRefsFromExpr(type.expression, innerScope)
                        type.typeArguments?.forEach { collectRefsFromType(it, innerScope) }
                    }
                }
                stmt.decorators?.forEach { collectRefsFromExpr(it.expression, innerScope) }
                for (member in stmt.members) {
                    collectRefsFromClassElement(member, innerScope)
                }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is InterfaceDeclaration -> {
                // Collect references from extends clause and members
                // Type parameters shadow outer names
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        collectRefsFromExpr(type.expression, innerScope)
                        type.typeArguments?.forEach { collectRefsFromType(it, innerScope) }
                    }
                }
                for (member in stmt.members) {
                    collectRefsFromClassElement(member, innerScope)
                }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is TypeAliasDeclaration -> {
                // Type parameters shadow outer names
                val innerScope = if (stmt.typeParameters?.isNotEmpty() == true) UnusedScope() else scope
                stmt.type.let { collectRefsFromType(it, innerScope) }
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, innerScope) }
                    tp.default?.let { collectRefsFromType(it, innerScope) }
                }
                if (innerScope !== scope) {
                    val tpNames = stmt.typeParameters?.map { it.name.text }?.toSet() ?: emptySet()
                    scope.referencedNames.addAll(innerScope.referencedNames - tpNames)
                }
            }
            is EnumDeclaration -> {
                for (member in stmt.members) {
                    member.initializer?.let { collectRefsFromExpr(it, scope) }
                }
            }
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> body.statements.forEach { collectUnusedReferences(it, scope) }
                    is ModuleDeclaration -> collectUnusedReferences(body, scope)
                    else -> {}
                }
            }
            is ExportDeclaration -> {
                // export { X } — X is a reference
                when (val clause = stmt.exportClause) {
                    is NamedExports -> {
                        for (spec in clause.elements) {
                            val name = spec.propertyName?.text ?: spec.name.text
                            scope.referencedNames.add(name)
                        }
                    }
                    else -> {}
                }
            }
            is ExportAssignment -> {
                collectRefsFromExpr(stmt.expression, scope)
            }
            else -> {}
        }
    }

    private fun collectRefsFromExpr(expr: Expression, scope: UnusedScope) {
        when (expr) {
            is Identifier -> scope.referencedNames.add(expr.text)
            is PropertyAccessExpression -> {
                collectRefsFromExpr(expr.expression, scope)
            }
            is ElementAccessExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromExpr(expr.argumentExpression, scope)
            }
            is CallExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                expr.arguments.forEach { collectRefsFromExpr(it, scope) }
                expr.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            is NewExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                expr.arguments?.forEach { collectRefsFromExpr(it, scope) }
                expr.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    // Simple assignment: left side is write-only (not a read)
                    collectRefsFromExpr(expr.right, scope)
                    collectWriteTargetRefs(expr.left, scope)
                } else {
                    // Non-assignment or compound assignment: iterative traversal
                    var current: Expression = expr
                    while (current is BinaryExpression) {
                        collectRefsFromExpr(current.right, scope)
                        current = current.left
                    }
                    collectRefsFromExpr(current, scope)
                }
            }
            is ConditionalExpression -> {
                collectRefsFromExpr(expr.condition, scope)
                collectRefsFromExpr(expr.whenTrue, scope)
                collectRefsFromExpr(expr.whenFalse, scope)
            }
            is PrefixUnaryExpression -> collectRefsFromExpr(expr.operand, scope)
            is PostfixUnaryExpression -> collectRefsFromExpr(expr.operand, scope)
            is ParenthesizedExpression -> collectRefsFromExpr(expr.expression, scope)
            is ArrayLiteralExpression -> {
                expr.elements.forEach { collectRefsFromExpr(it, scope) }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            collectRefsFromExpr(prop.initializer, scope)
                            val propName = prop.name
                            if (propName is ComputedPropertyName) {
                                collectRefsFromExpr(propName.expression, scope)
                            }
                        }
                        is ShorthandPropertyAssignment -> {
                            scope.referencedNames.add(prop.name.text)
                        }
                        is SpreadAssignment -> collectRefsFromExpr(prop.expression, scope)
                        is MethodDeclaration -> {
                            prop.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                            prop.parameters.forEach { param ->
                                param.initializer?.let { collectRefsFromExpr(it, scope) }
                            }
                        }
                        is GetAccessor -> {
                            prop.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                        }
                        is SetAccessor -> {
                            prop.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                        }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> body.statements.forEach { collectUnusedReferences(it, scope) }
                    is Expression -> collectRefsFromExpr(body, scope)
                    else -> {}
                }
                expr.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                expr.type?.let { collectRefsFromType(it, scope) }
            }
            is FunctionExpression -> {
                expr.body.statements.forEach { collectUnusedReferences(it, scope) }
                expr.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                expr.type?.let { collectRefsFromType(it, scope) }
            }
            is ClassExpression -> {
                expr.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        collectRefsFromExpr(type.expression, scope)
                        type.typeArguments?.forEach { collectRefsFromType(it, scope) }
                    }
                }
                for (member in expr.members) {
                    collectRefsFromClassElement(member, scope)
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is TaggedTemplateExpression -> {
                collectRefsFromExpr(expr.tag, scope)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        template.templateSpans.forEach { collectRefsFromExpr(it.expression, scope) }
                    }
                    else -> {}
                }
            }
            is SpreadElement -> collectRefsFromExpr(expr.expression, scope)
            is AwaitExpression -> collectRefsFromExpr(expr.expression, scope)
            is YieldExpression -> expr.expression?.let { collectRefsFromExpr(it, scope) }
            is DeleteExpression -> collectRefsFromExpr(expr.expression, scope)
            is TypeOfExpression -> collectRefsFromExpr(expr.expression, scope)
            is VoidExpression -> collectRefsFromExpr(expr.expression, scope)
            is AsExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromType(expr.type, scope)
            }
            is SatisfiesExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromType(expr.type, scope)
            }
            is NonNullExpression -> collectRefsFromExpr(expr.expression, scope)
            is TypeAssertionExpression -> {
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromType(expr.type, scope)
            }
            is CommaListExpression -> expr.elements.forEach { collectRefsFromExpr(it, scope) }
            is JsxElement -> {
                collectRefsFromExpr(expr.openingElement.tagName, scope)
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { collectRefsFromExpr(it, scope) }
                    } else if (child is Expression) {
                        collectRefsFromExpr(child, scope)
                    }
                }
            }
            is JsxSelfClosingElement -> {
                collectRefsFromExpr(expr.tagName, scope)
                for (attr in expr.attributes) {
                    when (attr) {
                        is JsxAttribute -> {
                            val v = attr.value
                            if (v is JsxExpressionContainer) {
                                v.expression?.let { collectRefsFromExpr(it, scope) }
                            } else if (v is Expression) {
                                collectRefsFromExpr(v, scope)
                            }
                        }
                        is JsxSpreadAttribute -> collectRefsFromExpr(attr.expression, scope)
                        else -> {}
                    }
                }
            }
            is JsxFragment -> {
                for (child in expr.children) {
                    if (child is JsxExpressionContainer) {
                        child.expression?.let { collectRefsFromExpr(it, scope) }
                    } else if (child is Expression) {
                        collectRefsFromExpr(child, scope)
                    }
                }
            }
            else -> {} // literals, omitted expressions, binding patterns, etc.
        }
    }

    /**
     * For write-only targets (left side of `=`), only collect references from
     * property access bases and element access arguments, not the target identifier itself.
     */
    private fun collectWriteTargetRefs(expr: Expression, scope: UnusedScope) {
        when (expr) {
            is Identifier -> {} // Don't add — this is a write target, not a read
            is PropertyAccessExpression -> {
                // obj.prop = value — obj IS read
                collectRefsFromExpr(expr.expression, scope)
            }
            is ElementAccessExpression -> {
                // obj[key] = value — both obj and key are read
                collectRefsFromExpr(expr.expression, scope)
                collectRefsFromExpr(expr.argumentExpression, scope)
            }
            is ArrayLiteralExpression -> {
                // [x, y] = [1, 2] — destructuring write: elements are write targets
                for (element in expr.elements) {
                    when (element) {
                        is SpreadElement -> collectWriteTargetRefs(element.expression, scope)
                        is BinaryExpression -> {
                            // [x = default] — x is write target, default IS a read
                            if (element.operator == SyntaxKind.Equals) {
                                collectWriteTargetRefs(element.left, scope)
                                collectRefsFromExpr(element.right, scope)
                            } else {
                                collectRefsFromExpr(element, scope)
                            }
                        }
                        is OmittedExpression -> {} // skip holes
                        else -> collectWriteTargetRefs(element, scope)
                    }
                }
            }
            is ObjectLiteralExpression -> {
                // { x, y } = { x: 1, y: 2 } — destructuring write: properties are write targets
                for (prop in expr.properties) {
                    when (prop) {
                        is ShorthandPropertyAssignment -> {
                            // { x } = obj — x is a write target
                            if (prop.objectAssignmentInitializer != null) {
                                // { x = default } = obj — x is write target, default IS a read
                                collectRefsFromExpr(prop.objectAssignmentInitializer, scope)
                            }
                            // Don't add prop.name to referencedNames
                        }
                        is PropertyAssignment -> {
                            // { key: target } = obj — key is a read (if computed), target is write
                            if (prop.name is ComputedPropertyName) {
                                collectRefsFromExpr((prop.name).expression, scope)
                            }
                            collectWriteTargetRefs(prop.initializer, scope)
                        }
                        is SpreadAssignment -> collectWriteTargetRefs(prop.expression, scope)
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> collectWriteTargetRefs(expr.expression, scope)
            else -> collectRefsFromExpr(expr, scope) // fallback: treat as read
        }
    }

    private fun collectRefsFromClassElement(element: ClassElement, scope: UnusedScope) {
        when (element) {
            is PropertyDeclaration -> {
                element.initializer?.let { collectRefsFromExpr(it, scope) }
                element.type?.let { collectRefsFromType(it, scope) }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is MethodDeclaration -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                    param.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
                }
                element.type?.let { collectRefsFromType(it, scope) }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
                element.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, scope) }
                }
            }
            is Constructor -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.parameters.forEach { param ->
                    param.initializer?.let { collectRefsFromExpr(it, scope) }
                    param.type?.let { collectRefsFromType(it, scope) }
                    param.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
                }
            }
            is GetAccessor -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.type?.let { collectRefsFromType(it, scope) }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is SetAccessor -> {
                element.body?.statements?.forEach { collectUnusedReferences(it, scope) }
                element.parameters.forEach { param ->
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                element.decorators?.forEach { collectRefsFromExpr(it.expression, scope) }
            }
            is ClassStaticBlockDeclaration -> {
                element.body.statements.forEach { collectUnusedReferences(it, scope) }
            }
            else -> {}
        }
    }

    /**
     * Collect name references from type nodes. Type references count as usage
     * for unused declaration checking — `let x: MyType` counts as using `MyType`.
     */
    private fun collectRefsFromType(type: TypeNode, scope: UnusedScope) {
        when (type) {
            is TypeReference -> {
                when (val name = type.typeName) {
                    is Identifier -> scope.referencedNames.add(name.text)
                    is QualifiedName -> {
                        // For A.B.C, only the leftmost name is a scope reference
                        var current: Node = name
                        while (current is QualifiedName) current = current.left
                        if (current is Identifier) scope.referencedNames.add(current.text)
                    }
                    else -> {}
                }
                type.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            is ArrayType -> collectRefsFromType(type.elementType, scope)
            is TupleType -> type.elements.forEach { collectRefsFromType(it, scope) }
            is UnionType -> type.types.forEach { collectRefsFromType(it, scope) }
            is IntersectionType -> type.types.forEach { collectRefsFromType(it, scope) }
            is ParenthesizedType -> collectRefsFromType(type.type, scope)
            is FunctionType -> {
                type.parameters.forEach { param ->
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                collectRefsFromType(type.type, scope)
                type.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectRefsFromType(it, scope) }
                    tp.default?.let { collectRefsFromType(it, scope) }
                }
            }
            is ConstructorType -> {
                type.parameters.forEach { param ->
                    param.type?.let { collectRefsFromType(it, scope) }
                }
                collectRefsFromType(type.type, scope)
            }
            is TypeQuery -> {
                when (val name = type.exprName) {
                    is Identifier -> scope.referencedNames.add(name.text)
                    is QualifiedName -> {
                        var current: Node = name
                        while (current is QualifiedName) current = current.left
                        if (current is Identifier) scope.referencedNames.add(current.text)
                    }
                    else -> {}
                }
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            member.type?.let { collectRefsFromType(it, scope) }
                        }
                        is MethodDeclaration -> {
                            member.parameters.forEach { param ->
                                param.type?.let { collectRefsFromType(it, scope) }
                            }
                            member.type?.let { collectRefsFromType(it, scope) }
                        }
                        is IndexSignature -> {
                            member.parameters.forEach { param ->
                                param.type?.let { collectRefsFromType(it, scope) }
                            }
                            member.type?.let { collectRefsFromType(it, scope) }
                        }
                        else -> {}
                    }
                }
            }
            is ConditionalType -> {
                collectRefsFromType(type.checkType, scope)
                collectRefsFromType(type.extendsType, scope)
                collectRefsFromType(type.trueType, scope)
                collectRefsFromType(type.falseType, scope)
            }
            is MappedType -> {
                type.type?.let { collectRefsFromType(it, scope) }
                type.nameType?.let { collectRefsFromType(it, scope) }
                type.typeParameter.constraint?.let { collectRefsFromType(it, scope) }
            }
            is IndexedAccessType -> {
                collectRefsFromType(type.objectType, scope)
                collectRefsFromType(type.indexType, scope)
            }
            is TypeOperator -> collectRefsFromType(type.type, scope)
            is InferType -> {} // infer T — doesn't reference existing names
            is TemplateLiteralType -> {
                type.templateSpans.forEach { span ->
                    collectRefsFromType(span.type, scope)
                }
            }
            is RestType -> collectRefsFromType(type.type, scope)
            is NamedTupleMember -> collectRefsFromType(type.type, scope)
            is OptionalType -> collectRefsFromType(type.type, scope)
            is ImportType -> {
                type.typeArguments?.forEach { collectRefsFromType(it, scope) }
            }
            else -> {} // keyword types, literal types, this type, etc.
        }
    }

    /**
     * Recurse into nested scopes to check for unused declarations within them.
     */
    private fun checkUnusedInNestedScopes(stmt: Statement, source: String, fileName: String, siblingStatements: List<Statement>? = null) {
        when (stmt) {
            is FunctionDeclaration -> {
                stmt.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, stmt.parameters, source, fileName,
                        typeParameters = stmt.typeParameters,
                        returnType = stmt.type,
                    )
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    checkUnusedInClassElement(member, source, fileName)
                }
                // Check class-level type parameters
                checkUnusedClassTypeParams(stmt, source, fileName, siblingStatements)
                // Check unused private members
                checkUnusedPrivateMembers(stmt.members, source, fileName)
            }
            is InterfaceDeclaration -> {
                checkUnusedInterfaceTypeParams(stmt, source, fileName, siblingStatements)
            }
            is TypeAliasDeclaration -> {
                checkUnusedTypeAliasTypeParams(stmt, source, fileName)
            }
            is ModuleDeclaration -> {
                // 17.217: `declare global { ... }` adds AMBIENT globals — they're
                // intentionally exposed to other code, never "locally unused".
                // TypeScript suppresses TS6133 for declarations inside such blocks.
                // Detect by: identifier name "global" + Declare modifier on the
                // outer module decl (or any ancestor — this branch is also reached
                // when the global block is nested inside a `declare module "X" { ... }`
                // augmentation). Skip the unused check entirely for the body.
                val isGlobalAug = (stmt.name as? Identifier)?.text == "global" &&
                    ModifierFlag.Declare in stmt.modifiers
                if (isGlobalAug) return
                when (val body = stmt.body) {
                    is ModuleBlock -> checkUnusedInStatements(
                        body.statements, source, fileName, isTopLevel = false,
                    )
                    is ModuleDeclaration -> checkUnusedInNestedScopes(
                        body, source, fileName,
                    )
                    else -> {}
                }
            }
            is VariableStatement -> {
                // Check initializer expressions for nested function-likes
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkUnusedInExpr(it, source, fileName) }
                    // Check unused type params in type annotations (ConstructorType, FunctionType, TypeLiteral)
                    decl.type?.let { checkUnusedTypeParamsInType(it, source, fileName) }
                }
            }
            is ExpressionStatement -> {
                checkUnusedInExpr(stmt.expression, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let { checkUnusedInExpr(it, source, fileName) }
            }
            is Block -> checkUnusedInStatements(
                stmt.statements, source, fileName, isTopLevel = false,
            )
            is IfStatement -> {
                checkUnusedInExpr(stmt.expression, source, fileName)
                checkUnusedInNestedScopes(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkUnusedInNestedScopes(it, source, fileName) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        // Check for unused variables declared in the for-initializer
                        checkForStatementVariable(init, stmt, source, fileName)
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkUnusedInExpr(it, source, fileName) }
                        }
                    }
                    is Expression -> checkUnusedInExpr(init, source, fileName)
                    else -> {}
                }
                checkUnusedInNestedScopes(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkForLoopVariable(stmt.initializer, stmt.statement, source, fileName)
                checkUnusedInNestedScopes(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkForLoopVariable(stmt.initializer, stmt.statement, source, fileName)
                checkUnusedInNestedScopes(stmt.statement, source, fileName)
            }
            is WhileStatement -> checkUnusedInNestedScopes(stmt.statement, source, fileName)
            is DoStatement -> checkUnusedInNestedScopes(stmt.statement, source, fileName)
            is SwitchStatement -> {
                checkUnusedInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    // Check unused declarations within each case/default clause
                    checkUnusedInStatements(clauseStmts, source, fileName, isTopLevel = false)
                    clauseStmts.forEach { checkUnusedInNestedScopes(it, source, fileName) }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach {
                    checkUnusedInNestedScopes(it, source, fileName)
                }
                stmt.catchClause?.block?.statements?.forEach {
                    checkUnusedInNestedScopes(it, source, fileName)
                }
                stmt.finallyBlock?.statements?.forEach {
                    checkUnusedInNestedScopes(it, source, fileName)
                }
            }
            is LabeledStatement -> checkUnusedInNestedScopes(stmt.statement, source, fileName)
            else -> {}
        }
    }

    /**
     * Check for unused declarations inside expression-level function-likes
     * (function expressions, arrow functions, class expressions).
     */
    private fun checkUnusedInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> {
                checkUnusedInFunctionLike(
                    expr.body.statements, expr.parameters, source, fileName,
                    typeParameters = expr.typeParameters,
                    returnType = expr.type,
                )
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkUnusedInFunctionLike(
                        body.statements, expr.parameters, source, fileName,
                        typeParameters = expr.typeParameters,
                        returnType = expr.type,
                    )
                    is Expression -> {
                        // Arrow with expression body — still check parameters
                        if (options.noUnusedParameters) {
                            val scope = UnusedScope()
                            for (param in expr.parameters) {
                                val name = param.name
                                if (name is Identifier && !name.text.startsWith("_")) {
                                    scope.declarations.add(UnusedDecl(
                                        name = name.text,
                                        nameNode = name,
                                        declNode = param,
                                        isExported = false,
                                        isParameter = true,
                                        isTypeOnly = false,
                                    ))
                                }
                            }
                            collectRefsFromExpr(body, scope)
                            for (decl in scope.declarations) {
                                if (decl.name in scope.referencedNames) continue
                                val start = decl.nameNode.pos
                                val length = decl.name.length
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "'${decl.name}' is declared but its value is never read.",
                                    category = DiagnosticCategory.Error,
                                    code = 6133,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                        checkUnusedInExpr(body, source, fileName)
                    }
                    else -> {}
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    checkUnusedInClassElement(member, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is MethodDeclaration -> {
                            prop.body?.let { body ->
                                checkUnusedInFunctionLike(
                                    body.statements, prop.parameters, source, fileName,
                                    typeParameters = prop.typeParameters,
                                    returnType = prop.type,
                                )
                            }
                        }
                        is GetAccessor -> {
                            prop.body?.let { body ->
                                checkUnusedInFunctionLike(
                                    body.statements, prop.parameters, source, fileName,
                                )
                            }
                        }
                        is SetAccessor -> {
                            prop.body?.let { body ->
                                checkUnusedInFunctionLike(
                                    body.statements, prop.parameters, source, fileName,
                                )
                            }
                        }
                        is PropertyAssignment -> {
                            checkUnusedInExpr(prop.initializer, source, fileName)
                        }
                        is SpreadAssignment -> {
                            checkUnusedInExpr(prop.expression, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUnusedInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkUnusedInExpr(current, source, fileName)
            }
            is ConditionalExpression -> {
                checkUnusedInExpr(expr.condition, source, fileName)
                checkUnusedInExpr(expr.whenTrue, source, fileName)
                checkUnusedInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkUnusedInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { checkUnusedInExpr(it, source, fileName) }
            }
            is NewExpression -> {
                checkUnusedInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkUnusedInExpr(it, source, fileName) }
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { checkUnusedInExpr(it, source, fileName) }
            }
            is AsExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is VoidExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { checkUnusedInExpr(it, source, fileName) }
            is PropertyAccessExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkUnusedInExpr(expr.expression, source, fileName)
                checkUnusedInExpr(expr.argumentExpression, source, fileName)
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { checkUnusedInExpr(it.expression, source, fileName) }
            }
            is TaggedTemplateExpression -> {
                checkUnusedInExpr(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkUnusedInExpr(it.expression, source, fileName)
                }
            }
            is AwaitExpression -> checkUnusedInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkUnusedInExpr(it, source, fileName) }
            is SpreadElement -> checkUnusedInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkUnusedInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkUnusedInExpr(expr.operand, source, fileName)
            else -> {} // Literals, identifiers, etc. — no nested function-likes
        }
    }

    /**
     * Check for unused for-in/for-of loop variables.
     */
    /**
     * Check for unused variables declared in a C-style for-loop initializer:
     * `for(var i = 0; condition; increment) { body }`
     * Collects references from condition, incrementor, and body.
     */
    private fun checkForStatementVariable(
        declList: VariableDeclarationList,
        forStmt: ForStatement,
        source: String,
        fileName: String,
    ) {
        if (!options.noUnusedLocals) return
        val scope = UnusedScope()
        for (decl in declList.declarations) {
            collectVarDeclNames(decl.name, decl, isExported = false, scope)
        }
        // Collect references from condition, incrementor, and body
        forStmt.condition?.let { collectRefsFromExpr(it, scope) }
        forStmt.incrementor?.let { collectRefsFromExpr(it, scope) }
        collectUnusedReferences(forStmt.statement, scope)
        // Report unused
        for (decl in scope.declarations) {
            if (decl.name in scope.referencedNames) continue
            if (decl.name.startsWith("_")) continue
            val start = decl.nameNode.pos
            val length = decl.name.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${decl.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun checkForLoopVariable(
        initializer: Node?,
        body: Statement,
        source: String,
        fileName: String,
    ) {
        if (!options.noUnusedLocals) return
        val declList = initializer as? VariableDeclarationList ?: return
        val scope = UnusedScope()
        for (decl in declList.declarations) {
            collectVarDeclNames(decl.name, decl, isExported = false, scope)
        }
        // Collect references from the body
        collectUnusedReferences(body, scope)
        // Report unused
        for (decl in scope.declarations) {
            if (decl.name in scope.referencedNames) continue
            if (decl.name.startsWith("_")) continue
            val start = decl.nameNode.pos
            val length = decl.name.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${decl.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun checkUnusedInClassElement(
        element: ClassElement,
        source: String,
        fileName: String,
    ) {
        when (element) {
            is MethodDeclaration -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                        typeParameters = element.typeParameters,
                        returnType = element.type,
                    )
                }
            }
            is Constructor -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                    )
                }
            }
            is GetAccessor -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                    )
                }
            }
            is SetAccessor -> {
                element.body?.let { body ->
                    checkUnusedInFunctionLike(
                        body.statements, element.parameters, source, fileName,
                    )
                }
            }
            is ClassStaticBlockDeclaration -> {
                checkUnusedInStatements(
                    element.body.statements, source, fileName, isTopLevel = false,
                )
            }
            is PropertyDeclaration -> {
                element.initializer?.let { checkUnusedInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    /**
     * Check for unused type parameters on a class declaration.
     */
    /**
     * Check for unused private class members (TS6133).
     * Private properties and methods that are never accessed within the class are unused.
     */
    private fun checkUnusedPrivateMembers(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        if (!options.noUnusedLocals) return

        // Collect private members
        // `name` is the match key (used to detect references); `display` is the
        // text shown in the TS6133 message and used for the squiggle length. For
        // a computed-name member `private [x]: T` the match key is the bracket
        // identifier `x` and the display is `[x]`.
        data class PrivateMember(val name: String, val display: String, val nameNode: Node)
        val privateMembers = mutableListOf<PrivateMember>()
        val getterSetterNames = mutableSetOf<String>() // track getter/setter pairs
        // Match keys of computed-name private members (e.g. `x` for `private [x]: T`).
        // Used to recognize `this[x]` element-access reads as uses of `[x]` while
        // excluding `this[x] = 0` write-only assignments. Empty for the common case
        // (no computed members) so reference collection is unchanged there.
        val computedKeys = mutableSetOf<String>()

        for (member in members) {
            val isPrivate = when (member) {
                is PropertyDeclaration -> ModifierFlag.Private in member.modifiers
                is MethodDeclaration -> ModifierFlag.Private in member.modifiers
                is GetAccessor -> ModifierFlag.Private in member.modifiers
                is SetAccessor -> ModifierFlag.Private in member.modifiers
                else -> false
            }
            if (!isPrivate) continue

            val memberName: Node? = when (member) {
                is PropertyDeclaration -> member.name
                is MethodDeclaration -> member.name
                is GetAccessor -> member.name
                is SetAccessor -> member.name
                else -> null
            }
            // Identifier-named member → match key = display = the identifier text.
            // Computed-name member `[x]` → match key = `x`, display = `[x]`.
            val (name, display, nameNode) = when (memberName) {
                is Identifier -> Triple(memberName.text, memberName.text, memberName as Node)
                is ComputedPropertyName -> {
                    val inner = memberName.expression
                    if (inner is Identifier) {
                        computedKeys.add(inner.text)
                        Triple(inner.text, "[${inner.text}]", memberName as Node)
                    } else continue
                }
                else -> continue
            }

            // Track getter/setter pairs — don't duplicate
            if (member is GetAccessor || member is SetAccessor) {
                if (name in getterSetterNames) continue
                getterSetterNames.add(name)
            }

            privateMembers.add(PrivateMember(name, display, nameNode))
        }

        if (privateMembers.isEmpty()) return

        // Expose computed-name match keys to the reference collector for this class
        // (enables `this[x]` read recognition + `this[x] = 0` write exclusion).
        unusedComputedKeys = computedKeys

        // Collect property access names per member (for self-reference detection)
        data class MemberRefs(val memberName: String?, val refs: MutableSet<String>)
        val refsPerMember = mutableListOf<MemberRefs>()
        for (member in members) {
            val memberName = when (member) {
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                is Constructor -> null
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                else -> null
            }
            val refs = mutableSetOf<String>()
            // Build param name → string literal values map for this[param] resolution
            val paramLiterals = buildParamLiteralMap(member)
            when (member) {
                is MethodDeclaration -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is Constructor -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is GetAccessor -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is SetAccessor -> member.body?.let { collectPropertyAccessNames(it, refs, paramLiterals) }
                is PropertyDeclaration -> member.initializer?.let { collectPropertyAccessNamesInExpr(it, refs) }
                else -> {}
            }
            refsPerMember.add(MemberRefs(memberName, refs))
        }

        // Report unused private members
        // A member is unused if it's only accessed from its own body (self-reference)
        for (pm in privateMembers) {
            val isExternallyAccessed = refsPerMember.any { mr ->
                mr.memberName != pm.name && pm.name in mr.refs
            }
            if (isExternallyAccessed) continue
            val start = pm.nameNode.pos
            val length = pm.display.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${pm.display}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    private fun collectPropertyAccessNames(block: Block, names: MutableSet<String>, paramLiterals: Map<String, Set<String>> = emptyMap()) {
        for (stmt in block.statements) {
            collectPropertyAccessNamesInStmt(stmt, names, paramLiterals)
        }
    }

    private fun collectPropertyAccessNamesInStmt(stmt: Statement, names: MutableSet<String>, paramLiterals: Map<String, Set<String>> = emptyMap()) {
        when (stmt) {
            is ExpressionStatement -> collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            is IfStatement -> {
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
                collectPropertyAccessNamesInStmt(stmt.thenStatement, names, paramLiterals)
                stmt.elseStatement?.let { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            }
            is Block -> stmt.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> collectPropertyAccessNamesInExpr(init, names, paramLiterals)
                    else -> {}
                }
                stmt.condition?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                stmt.incrementor?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                collectPropertyAccessNamesInStmt(stmt.statement, names, paramLiterals)
            }
            is WhileStatement -> {
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
                collectPropertyAccessNamesInStmt(stmt.statement, names, paramLiterals)
            }
            is DoStatement -> {
                collectPropertyAccessNamesInStmt(stmt.statement, names, paramLiterals)
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
            }
            is SwitchStatement -> {
                collectPropertyAccessNamesInExpr(stmt.expression, names, paramLiterals)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            collectPropertyAccessNamesInExpr(clause.expression, names, paramLiterals)
                            clause.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                        }
                        is DefaultClause -> clause.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                stmt.catchClause?.block?.statements?.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                stmt.finallyBlock?.statements?.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            }
            is ThrowStatement -> stmt.expression?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            else -> {}
        }
    }

    private fun collectPropertyAccessNamesInExpr(expr: Expression, names: MutableSet<String>, paramLiterals: Map<String, Set<String>> = emptyMap()) {
        when (expr) {
            is PropertyAccessExpression -> {
                names.add(expr.name.text)
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            }
            is CallExpression -> {
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
                expr.arguments.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            }
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    // Simple assignment: left side is write-only, don't count as read
                    // But still recurse into sub-expressions of the left side
                    // (e.g. for `this.a[this.b] = 0`, this.b IS a read)
                    val left = expr.left
                    val right = expr.right
                    if (left is ObjectLiteralExpression && right is Identifier && right.text == "this") {
                        // Destructuring from this: ({ x, y } = this) reads this.x, this.y
                        for (prop in left.properties) {
                            when (prop) {
                                is ShorthandPropertyAssignment -> names.add(prop.name.text)
                                is PropertyAssignment -> {
                                    val propName = prop.name
                                    if (propName is Identifier) names.add(propName.text)
                                }
                                else -> {}
                            }
                        }
                    } else if (left is PropertyAccessExpression) {
                        // this.x = ... → only recurse into the base (this), not the property name
                        collectPropertyAccessNamesInExpr(left.expression, names, paramLiterals)
                    } else if (unusedComputedKeys.isNotEmpty() && left is ElementAccessExpression) {
                        // this[x] = ... → write-only via a computed key; recurse into the base
                        // and into a NON-bare-key argument (e.g. `this[this.b] = 0` reads this.b),
                        // but do not count the write target `x` as a read.
                        collectPropertyAccessNamesInExpr(left.expression, names, paramLiterals)
                        val larg = left.argumentExpression
                        if (larg !is Identifier && larg !is StringLiteralNode) {
                            collectPropertyAccessNamesInExpr(larg, names, paramLiterals)
                        }
                    } else {
                        collectPropertyAccessNamesInExpr(left, names, paramLiterals)
                    }
                } else {
                    collectPropertyAccessNamesInExpr(expr.left, names, paramLiterals)
                }
                collectPropertyAccessNamesInExpr(expr.right, names, paramLiterals)
            }
            is PrefixUnaryExpression -> collectPropertyAccessNamesInExpr(expr.operand, names, paramLiterals)
            is PostfixUnaryExpression -> collectPropertyAccessNamesInExpr(expr.operand, names, paramLiterals)
            is ParenthesizedExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is ConditionalExpression -> {
                collectPropertyAccessNamesInExpr(expr.condition, names, paramLiterals)
                collectPropertyAccessNamesInExpr(expr.whenTrue, names, paramLiterals)
                collectPropertyAccessNamesInExpr(expr.whenFalse, names, paramLiterals)
            }
            is NewExpression -> {
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
                expr.arguments?.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            }
            is ElementAccessExpression -> {
                collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
                collectPropertyAccessNamesInExpr(expr.argumentExpression, names, paramLiterals)
                // String literal element access like obj["name"] counts as accessing "name"
                val arg = expr.argumentExpression
                if (arg is StringLiteralNode) {
                    names.add(arg.text)
                } else if (arg is Identifier && paramLiterals.isNotEmpty()) {
                    // this[param] where param has string literal union type
                    paramLiterals[arg.text]?.let { names.addAll(it) }
                } else if (arg is Identifier && arg.text in unusedComputedKeys) {
                    // this[x] (read) where `x` is the bracket identifier of a computed-name
                    // private member `private [x]: T`. Counts as a use of `[x]`. Writes
                    // (`this[x] = 0`) are excluded by the assignment-LHS handling above.
                    val recv = expr.expression
                    if (recv is Identifier && recv.text == "this") names.add(arg.text)
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { collectPropertyAccessNamesInExpr(it.expression, names, paramLiterals) }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> body.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
                    is Expression -> collectPropertyAccessNamesInExpr(body, names, paramLiterals)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.body.statements.forEach { collectPropertyAccessNamesInStmt(it, names, paramLiterals) }
            }
            is ArrayLiteralExpression -> expr.elements.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> collectPropertyAccessNamesInExpr(prop.initializer, names, paramLiterals)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> collectPropertyAccessNamesInExpr(prop.expression, names, paramLiterals)
                        else -> {}
                    }
                }
            }
            is AsExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is NonNullExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is TypeAssertionExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is SatisfiesExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is AwaitExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is YieldExpression -> expr.expression?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            is SpreadElement -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is DeleteExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is VoidExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is TypeOfExpression -> collectPropertyAccessNamesInExpr(expr.expression, names, paramLiterals)
            is CommaListExpression -> expr.elements.forEach { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
            is TaggedTemplateExpression -> {
                collectPropertyAccessNamesInExpr(expr.tag, names, paramLiterals)
                val t = expr.template
                if (t is TemplateExpression) {
                    for (span in t.templateSpans) collectPropertyAccessNamesInExpr(span.expression, names, paramLiterals)
                }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { for (s in it.statements) collectPropertyAccessNamesInStmt(s, names, paramLiterals) }
                    is Constructor -> m.body?.let { for (s in it.statements) collectPropertyAccessNamesInStmt(s, names, paramLiterals) }
                    is GetAccessor -> m.body?.let { for (s in it.statements) collectPropertyAccessNamesInStmt(s, names, paramLiterals) }
                    is SetAccessor -> m.body?.let { for (s in it.statements) collectPropertyAccessNamesInStmt(s, names, paramLiterals) }
                    is PropertyDeclaration -> m.initializer?.let { collectPropertyAccessNamesInExpr(it, names, paramLiterals) }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    /**
     * Build a map of parameter name → string literal values from type annotations.
     * Used to resolve `this[param]` as reads of the named properties.
     */
    private fun buildParamLiteralMap(member: ClassElement): Map<String, Set<String>> {
        val params = when (member) {
            is MethodDeclaration -> member.parameters
            is Constructor -> member.parameters
            is GetAccessor -> member.parameters
            is SetAccessor -> member.parameters
            else -> return emptyMap()
        }
        val result = mutableMapOf<String, Set<String>>()
        for (param in params) {
            val paramName = (param.name as? Identifier)?.text ?: continue
            val type = param.type ?: continue
            val literals = extractStringLiteralsFromType(type)
            if (literals.isNotEmpty()) result[paramName] = literals
        }
        return result
    }

    private fun extractStringLiteralsFromType(type: TypeNode): Set<String> {
        return when (type) {
            is LiteralType -> {
                val lit = type.literal
                if (lit is StringLiteralNode) setOf(lit.text) else emptySet()
            }
            is UnionType -> type.types.flatMapTo(mutableSetOf()) { extractStringLiteralsFromType(it) }
            is ParenthesizedType -> extractStringLiteralsFromType(type.type)
            else -> emptySet()
        }
    }

    private fun checkUnusedClassTypeParams(
        cls: ClassDeclaration,
        source: String,
        fileName: String,
        siblingStatements: List<Statement>? = null,
    ) {
        val typeParams = cls.typeParameters
        // Class type params are only checked with noUnusedParameters (not noUnusedLocals alone)
        if (typeParams.isNullOrEmpty() || !options.noUnusedParameters) return
        // Skip if another declaration merges with this class (interface/namespace) — same file
        val className = cls.name?.text
        if (className != null && siblingStatements != null) {
            val hasMerge = siblingStatements.any { stmt ->
                stmt !== cls && when (stmt) {
                    is InterfaceDeclaration -> stmt.name.text == className
                    is ModuleDeclaration -> {
                        val n = stmt.name
                        n is Identifier && n.text == className
                    }
                    else -> false
                }
            }
            if (hasMerge) return
        }
        // Skip if another declaration merges with this class across files (via globals)
        if (className != null) {
            val globalSymbol = globals[className]
            if (globalSymbol != null && globalSymbol.declarations.any { it.kind == SyntaxKind.InterfaceDeclaration || it.kind == SyntaxKind.ModuleDeclaration }) return
        }

        val tpScope = UnusedScope()
        for (tp in typeParams) {
            if (!tp.name.text.startsWith("_")) {
                tpScope.declarations.add(UnusedDecl(
                    name = tp.name.text,
                    nameNode = tp.name,
                    declNode = tp,
                    isExported = false,
                    isParameter = false,
                    isTypeOnly = true,
                ))
            }
        }

        // Collect type refs from: heritage clauses, member types, constructor params
        cls.heritageClauses?.forEach { clause ->
            for (type in clause.types) {
                type.typeArguments?.forEach { collectTypeRefs(it, tpScope) }
                // The extends expression itself might reference a type param
                if (type.expression is Identifier) {
                    tpScope.referencedNames.add((type.expression).text)
                }
            }
        }
        for (member in cls.members) {
            collectTypeRefsFromJSDoc(member.leadingComments, tpScope)
            when (member) {
                is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, tpScope) }
                is MethodDeclaration -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.type?.let { collectTypeRefs(it, tpScope) }
                    member.body?.let { body ->
                        for (stmt in body.statements) collectTypeRefsInStatement(stmt, tpScope)
                    }
                }
                is Constructor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.body?.let { body ->
                        for (stmt in body.statements) collectTypeRefsInStatement(stmt, tpScope)
                    }
                }
                is GetAccessor -> member.type?.let { collectTypeRefs(it, tpScope) }
                is SetAccessor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                }
                is IndexSignature -> member.type?.let { collectTypeRefs(it, tpScope) }
                else -> {}
            }
        }

        reportUnusedTypeParams(tpScope, typeParams, source, fileName)
    }

    /** Check if a class declaration uses any of the named type parameters in its members. */
    private fun classUsesTypeParams(cls: ClassDeclaration, typeParamNames: Set<String>): Boolean {
        val tpScope = UnusedScope()
        // Add all type param names as "declarations" — we just want to see which ones are referenced
        for (name in typeParamNames) {
            tpScope.declarations.add(UnusedDecl(name = name, nameNode = Identifier(text = name), declNode = Identifier(text = name), isExported = false, isParameter = false, isTypeOnly = true))
        }
        for (member in cls.members) {
            when (member) {
                is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, tpScope) }
                is MethodDeclaration -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.type?.let { collectTypeRefs(it, tpScope) }
                }
                is Constructor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                }
                is GetAccessor -> member.type?.let { collectTypeRefs(it, tpScope) }
                is SetAccessor -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                }
                else -> {}
            }
        }
        return tpScope.referencedNames.any { it in typeParamNames }
    }

    private fun checkUnusedInterfaceTypeParams(
        iface: InterfaceDeclaration,
        source: String,
        fileName: String,
        siblingStatements: List<Statement>? = null,
    ) {
        val typeParams = iface.typeParameters
        if (typeParams.isNullOrEmpty() || !(options.noUnusedLocals || options.noUnusedParameters)) return
        val ifaceName = iface.name.text
        // Same-file merge check: if class/interface/namespace with same name in same file, skip
        if (siblingStatements != null) {
            val hasMerge = siblingStatements.any { stmt ->
                stmt !== iface && when (stmt) {
                    is InterfaceDeclaration -> stmt.name.text == ifaceName
                    is ClassDeclaration -> stmt.name?.text == ifaceName
                    is ModuleDeclaration -> {
                        val n = stmt.name
                        n is Identifier && n.text == ifaceName
                    }
                    else -> false
                }
            }
            if (hasMerge) return
        }
        // Cross-file merge check
        val globalSymbol = globals[ifaceName]
        if (globalSymbol != null) {
            // Skip if multiple interface/namespace declarations (normal interface merging)
            val nonClassDecls = globalSymbol.declarations.count {
                it.kind == SyntaxKind.InterfaceDeclaration || it.kind == SyntaxKind.ModuleDeclaration
            }
            if (nonClassDecls > 1) return
            // For class+interface cross-file merge: skip if the class uses any of the type params
            val typeParamNames = typeParams.map { it.name.text }.toSet()
            val classDecls = globalSymbol.declarations.filterIsInstance<ClassDeclaration>()
            for (classDecl in classDecls) {
                if (classUsesTypeParams(classDecl, typeParamNames)) return
            }
        }

        val tpScope = UnusedScope()
        for (tp in typeParams) {
            if (!tp.name.text.startsWith("_")) {
                tpScope.declarations.add(UnusedDecl(
                    name = tp.name.text, nameNode = tp.name, declNode = tp,
                    isExported = false, isParameter = false, isTypeOnly = true,
                ))
            }
        }

        // Collect refs from heritage clauses and members
        iface.heritageClauses?.forEach { clause ->
            for (type in clause.types) {
                type.typeArguments?.forEach { collectTypeRefs(it, tpScope) }
            }
        }
        for (member in iface.members) {
            when (member) {
                is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, tpScope) }
                is MethodDeclaration -> {
                    member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, tpScope) } }
                    member.type?.let { collectTypeRefs(it, tpScope) }
                }
                is IndexSignature -> member.type?.let { collectTypeRefs(it, tpScope) }
                else -> {}
            }
        }

        reportUnusedTypeParams(tpScope, typeParams, source, fileName)
    }

    private fun checkUnusedTypeAliasTypeParams(
        alias: TypeAliasDeclaration,
        source: String,
        fileName: String,
    ) {
        val typeParams = alias.typeParameters
        if (typeParams.isNullOrEmpty() || !(options.noUnusedLocals || options.noUnusedParameters)) return

        val tpScope = UnusedScope()
        for (tp in typeParams) {
            if (!tp.name.text.startsWith("_")) {
                tpScope.declarations.add(UnusedDecl(
                    name = tp.name.text, nameNode = tp.name, declNode = tp,
                    isExported = false, isParameter = false, isTypeOnly = true,
                ))
            }
        }

        collectTypeRefs(alias.type, tpScope)
        reportUnusedTypeParams(tpScope, typeParams, source, fileName)
    }

    private fun reportUnusedTypeParams(
        scope: UnusedScope,
        typeParams: List<TypeParameter>,
        source: String,
        fileName: String,
    ) {
        val allUnused = scope.declarations.none { it.name in scope.referencedNames }
        // For JSDoc-derived type params, group by tag start so we can decide between
        // the full-tag span (single-id tag, or all siblings unused) and per-identifier
        // span (multi-id tag with mixed used/unused).
        val tagSiblingCount = mutableMapOf<Int, Int>()
        val tagUnusedCount = mutableMapOf<Int, Int>()
        val tagSpanEnd = mutableMapOf<Int, Int>()
        for (tp in typeParams) {
            if (tp.fromJSDoc && tp.jsDocTagPos >= 0) {
                tagSiblingCount[tp.jsDocTagPos] = (tagSiblingCount[tp.jsDocTagPos] ?: 0) + 1
                tagSpanEnd[tp.jsDocTagPos] = tp.jsDocTagEnd
                if (tp.name.text !in scope.referencedNames) {
                    tagUnusedCount[tp.jsDocTagPos] = (tagUnusedCount[tp.jsDocTagPos] ?: 0) + 1
                }
            }
        }
        // TS6205: when a multi-id JSDoc tag has ALL identifiers unused, emit a single
        // "All type parameters are unused." with the full tag span, and skip the
        // per-identifier TS6133 emissions for those declarations.
        val coveredByTs6205 = mutableSetOf<Int>()
        for ((tagPos, sibs) in tagSiblingCount) {
            val unused = tagUnusedCount[tagPos] ?: 0
            val tagEnd = tagSpanEnd[tagPos] ?: continue
            if (sibs >= 2 && unused == sibs && tagEnd > tagPos) {
                val (line, character) = getLineAndCharacterOfPosition(source, tagPos)
                diagnostics.add(Diagnostic(
                    message = "All type parameters are unused.",
                    category = DiagnosticCategory.Error,
                    code = 6205,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = tagPos,
                    length = tagEnd - tagPos,
                ))
                coveredByTs6205.add(tagPos)
            }
        }
        for (decl in scope.declarations) {
            if (decl.name in scope.referencedNames) continue
            val tp = decl.declNode as TypeParameter
            if (tp.fromJSDoc && tp.jsDocTagPos in coveredByTs6205) continue
            val start: Int
            val length: Int
            val tagPos = tp.jsDocTagPos
            val tagEnd = tp.jsDocTagEnd
            val useTagSpan = tp.fromJSDoc && tagPos >= 0 && tagEnd > tagPos &&
                (tagSiblingCount[tagPos] ?: 0) == (tagUnusedCount[tagPos] ?: 0) &&
                (tagSiblingCount[tagPos] ?: 0) == 1
            if (useTagSpan) {
                start = tagPos
                length = tagEnd - tagPos
            } else if (allUnused && scope.declarations.size == 1 && typeParams.size == 1 && !tp.fromJSDoc) {
                start = tp.pos - 1
                length = decl.name.length + 2
            } else {
                start = tp.name.pos
                length = decl.name.length
            }
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'${decl.name}' is declared but its value is never read.",
                category = DiagnosticCategory.Error,
                code = 6133,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /**
     * Walk JSDoc `@type {T}` (and similar) comments and add identifiers
     * found inside the brace expression to the unused-scope's referencedNames set.
     * Used to track type-param usage through JSDoc body annotations in JS-like files
     * (e.g. an `@type {T}` comment on `this.p;` inside a generic class constructor).
     */
    private fun collectTypeRefsFromJSDoc(comments: List<Comment>?, scope: UnusedScope) {
        if (comments.isNullOrEmpty()) return
        for (comment in comments) {
            if (comment.kind != SyntaxKind.MultiLineComment) continue
            val ct = comment.text
            if (!ct.startsWith("/**")) continue
            var idx = 0
            while (idx < ct.length) {
                val tagIdx = ct.indexOf("@type", idx)
                if (tagIdx < 0) break
                val afterTag = if (tagIdx + 5 < ct.length) ct[tagIdx + 5] else ' '
                if (afterTag.isLetterOrDigit() || afterTag == '_') {
                    idx = tagIdx + 5
                    continue
                }
                var i = tagIdx + 5
                while (i < ct.length && (ct[i] == ' ' || ct[i] == '\t')) i++
                if (i >= ct.length || ct[i] != '{') {
                    idx = i
                    continue
                }
                i++
                var depth = 1
                while (i < ct.length && depth > 0) {
                    val c = ct[i]
                    when {
                        c == '{' -> { depth++; i++ }
                        c == '}' -> { depth--; if (depth > 0) i++ }
                        c.isLetter() || c == '_' || c == '$' -> {
                            val nameStart = i
                            while (i < ct.length && (ct[i].isLetterOrDigit() || ct[i] == '_' || ct[i] == '$')) i++
                            scope.referencedNames.add(ct.substring(nameStart, i))
                        }
                        else -> i++
                    }
                }
                idx = if (i < ct.length) i + 1 else ct.length
            }
        }
    }

    private fun checkUnusedInFunctionLike(
        bodyStatements: List<Statement>,
        parameters: List<Parameter>,
        source: String,
        fileName: String,
        typeParameters: List<TypeParameter>? = null,
        returnType: TypeNode? = null,
    ) {
        // Check parameters (if noUnusedParameters is enabled)
        if (options.noUnusedParameters) {
            val scope = UnusedScope()
            // Collect parameter declarations
            for (param in parameters) {
                if (param.isCommentPlaceholder) continue
                val name = param.name
                if (name is Identifier) {
                    // Skip if underscore-prefixed or if it has access modifiers (constructor params)
                    if (!name.text.startsWith("_") &&
                        ModifierFlag.Public !in param.modifiers &&
                        ModifierFlag.Protected !in param.modifiers &&
                        ModifierFlag.Private !in param.modifiers) {
                        scope.declarations.add(UnusedDecl(
                            name = name.text,
                            nameNode = name,
                            declNode = param,
                            isExported = false,
                            isParameter = true,
                            isTypeOnly = false,
                        ))
                    }
                } else {
                    // Destructuring parameters: collect individual binding element names
                    collectDestructuringParamNames(name, param, scope)
                }
            }
            // Collect references from body
            for (stmt in bodyStatements) {
                collectUnusedReferences(stmt, scope)
            }
            // Also collect references from parameter defaults and types.
            // For VALUE param scope, type annotations only contribute `typeof X` refs
            // (value namespace) — bare `T` in type position is a TYPE namespace ref and
            // does NOT count as a use of a value param with the same name.
            for (param in parameters) {
                param.initializer?.let { collectRefsFromExpr(it, scope) }
                param.type?.let { collectTypeQueryValueRefs(it, scope) }
            }
            // Scan return type for typeof references
            returnType?.let { collectTypeQueryValueRefs(it, scope) }
            // Report unused parameters
            // First check for TS6198: if ALL elements from a destructuring pattern are unused,
            // emit a single "All destructured elements are unused" instead of individual TS6133
            val unusedParams = scope.declarations.filter { it.name !in scope.referencedNames }
            val paramTs6198Patterns = mutableSetOf<Node>()
            val paramDeclsByPattern = unusedParams.filter { it.parentBindingPattern is ObjectBindingPattern }
                .groupBy { it.parentBindingPattern!! }
            for ((pattern, decls) in paramDeclsByPattern) {
                val totalCount = decls.first().bindingElementCount
                if (decls.size == totalCount && totalCount > 1) {
                    paramTs6198Patterns.add(pattern)
                    val patStart = pattern.pos
                    val spanLength = computeBindingPatternSpan(source, patStart, pattern)
                    val (line, character) = getLineAndCharacterOfPosition(source, patStart)
                    diagnostics.add(Diagnostic(
                        message = "All destructured elements are unused.",
                        category = DiagnosticCategory.Error,
                        code = 6198,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = patStart,
                        length = spanLength,
                    ))
                }
            }
            for (decl in unusedParams) {
                if (decl.parentBindingPattern != null && decl.parentBindingPattern in paramTs6198Patterns) continue
                // Underscore-prefixed names don't get individual TS6133 (only TS6198 above)
                if (decl.name.startsWith("_")) continue
                val nameNode = decl.nameNode
                // Single-element destructuring parameter: use pattern span for both { } and [ ]
                val usePatternSpan = decl.parentBindingPattern != null && decl.bindingElementCount == 1
                val start = if (usePatternSpan) decl.parentBindingPattern.pos else nameNode.pos
                val length = if (usePatternSpan) computeBindingPatternSpan(source, start, decl.parentBindingPattern)
                    else if (decl.spanLength > 0) decl.spanLength else decl.name.length
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "'${decl.name}' is declared but its value is never read.",
                    category = DiagnosticCategory.Error,
                    code = 6133,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }

        // Check unused type parameters (TS6133)
        if (typeParameters != null && typeParameters.isNotEmpty() && (options.noUnusedLocals || options.noUnusedParameters)) {
            val tpScope = UnusedScope()
            for (tp in typeParameters) {
                if (!tp.name.text.startsWith("_")) {
                    tpScope.declarations.add(UnusedDecl(
                        name = tp.name.text,
                        nameNode = tp.name,
                        declNode = tp,
                        isExported = false,
                        isParameter = false,
                        isTypeOnly = true,
                    ))
                }
            }
            // Collect type references from: type param constraints, parameter types,
            // return type, and body statements (types in variable declarations etc.)
            for (tp in typeParameters) {
                tp.constraint?.let { collectTypeRefs(it, tpScope) }
                tp.default?.let { collectTypeRefs(it, tpScope) }
            }
            for (param in parameters) {
                param.type?.let { collectTypeRefs(it, tpScope) }
            }
            returnType?.let { collectTypeRefs(it, tpScope) }
            for (stmt in bodyStatements) {
                collectTypeRefsInStatement(stmt, tpScope)
            }
            reportUnusedTypeParams(tpScope, typeParameters, source, fileName)
        }

        // Check local declarations in the body
        checkUnusedInStatements(bodyStatements, source, fileName, isTopLevel = false)
    }

    /**
     * Check for unused type parameters defined within type annotations.
     * Handles: ConstructorType `new <T,U>(a:T)=>void`, FunctionType `<T,U>(a:T)=>void`,
     * and TypeLiteral members with ConstructSignature/CallSignature.
     */
    private fun checkUnusedTypeParamsInType(type: TypeNode, source: String, fileName: String) {
        if (!options.noUnusedLocals && !options.noUnusedParameters) return
        when (type) {
            is ConstructorType -> {
                checkTypeParamsInSignature(type.typeParameters, type.parameters, type.type, source, fileName)
            }
            is FunctionType -> {
                checkTypeParamsInSignature(type.typeParameters, type.parameters, type.type, source, fileName)
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            // Call signatures (name=""), construct signatures (name="new"), and methods
                            checkTypeParamsInSignature(member.typeParameters, member.parameters, member.type, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is UnionType -> type.types.forEach { checkUnusedTypeParamsInType(it, source, fileName) }
            is IntersectionType -> type.types.forEach { checkUnusedTypeParamsInType(it, source, fileName) }
            is ParenthesizedType -> checkUnusedTypeParamsInType(type.type, source, fileName)
            else -> {}
        }
    }

    /** Check unused type params for a single signature (construct/call/method). */
    private fun checkTypeParamsInSignature(
        typeParameters: List<TypeParameter>?,
        parameters: List<Parameter>,
        returnType: TypeNode?,
        source: String,
        fileName: String,
    ) {
        if (typeParameters.isNullOrEmpty()) return
        val scope = UnusedScope()
        for (tp in typeParameters) {
            if (!tp.name.text.startsWith("_")) {
                scope.declarations.add(UnusedDecl(
                    name = tp.name.text,
                    nameNode = tp.name,
                    declNode = tp,
                    isExported = false,
                    isParameter = false,
                    isTypeOnly = true,
                ))
            }
        }
        // Collect refs from constraints, param types, return type
        for (tp in typeParameters) {
            tp.constraint?.let { collectTypeRefs(it, scope) }
            tp.default?.let { collectTypeRefs(it, scope) }
        }
        for (param in parameters) {
            param.type?.let { collectTypeRefs(it, scope) }
        }
        returnType?.let { collectTypeRefs(it, scope) }
        reportUnusedTypeParams(scope, typeParameters, source, fileName)
    }

    /** Collect type identifier references from a type node. */
    private fun collectTypeRefs(type: TypeNode, scope: UnusedScope) {
        when (type) {
            is TypeReference -> {
                val name = type.typeName
                if (name is Identifier) scope.referencedNames.add(name.text)
                type.typeArguments?.forEach { collectTypeRefs(it, scope) }
            }
            is KeywordTypeNode -> {} // any, number, string, etc. — no references
            is ArrayType -> collectTypeRefs(type.elementType, scope)
            is TupleType -> type.elements.forEach {
                collectTypeRefs(it, scope)
            }
            is UnionType -> type.types.forEach { collectTypeRefs(it, scope) }
            is IntersectionType -> type.types.forEach { collectTypeRefs(it, scope) }
            is ParenthesizedType -> collectTypeRefs(type.type, scope)
            is FunctionType -> {
                type.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectTypeRefs(it, scope) }
                }
                type.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                type.type.let { collectTypeRefs(it, scope) }
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                type.type.let { collectTypeRefs(it, scope) }
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> member.type?.let { collectTypeRefs(it, scope) }
                        is MethodDeclaration -> {
                            member.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                            member.type?.let { collectTypeRefs(it, scope) }
                        }
                        is IndexSignature -> member.type?.let { collectTypeRefs(it, scope) }
                        else -> {}
                    }
                }
            }
            is ConditionalType -> {
                collectTypeRefs(type.checkType, scope)
                collectTypeRefs(type.extendsType, scope)
                collectTypeRefs(type.trueType, scope)
                collectTypeRefs(type.falseType, scope)
            }
            is MappedType -> {
                type.type?.let { collectTypeRefs(it, scope) }
                type.nameType?.let { collectTypeRefs(it, scope) }
                type.typeParameter.constraint?.let { collectTypeRefs(it, scope) }
            }
            is TypeQuery -> {
                val name = type.exprName
                if (name is Identifier) scope.referencedNames.add(name.text)
            }
            is IndexedAccessType -> {
                collectTypeRefs(type.objectType, scope)
                collectTypeRefs(type.indexType, scope)
            }
            is TypeOperator -> collectTypeRefs(type.type, scope)
            is RestType -> collectTypeRefs(type.type, scope)
            is OptionalType -> collectTypeRefs(type.type, scope)
            is InferType -> {} // infer T — declares, doesn't reference
            is LiteralType -> {} // string/number literals
            is TemplateLiteralType -> {
                type.templateSpans.forEach { span ->
                    collectTypeRefs(span.type, scope)
                }
            }
            else -> {}
        }
    }

    /**
     * Collect ONLY `typeof X` references from within a TypeNode tree. Unlike [collectTypeRefs],
     * bare TypeReference identifiers are NOT added — they belong to the TYPE namespace and do
     * not count as value-param uses for TS6133 purposes. Needed for cases like
     * `function f<T>(T: T)` where the second `T` in type position references the type param,
     * not the value param of the same name.
     */
    private fun collectTypeQueryValueRefs(type: TypeNode, scope: UnusedScope) {
        when (type) {
            is TypeQuery -> {
                when (val name = type.exprName) {
                    is Identifier -> scope.referencedNames.add(name.text)
                    is QualifiedName -> {
                        var current: Node = name
                        while (current is QualifiedName) current = current.left
                        if (current is Identifier) scope.referencedNames.add(current.text)
                    }
                    else -> {}
                }
            }
            is ArrayType -> collectTypeQueryValueRefs(type.elementType, scope)
            is TupleType -> type.elements.forEach {
                collectTypeQueryValueRefs(it, scope)
            }
            is UnionType -> type.types.forEach { collectTypeQueryValueRefs(it, scope) }
            is IntersectionType -> type.types.forEach { collectTypeQueryValueRefs(it, scope) }
            is ParenthesizedType -> collectTypeQueryValueRefs(type.type, scope)
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeQueryValueRefs(it, scope) } }
                type.type.let { collectTypeQueryValueRefs(it, scope) }
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { collectTypeQueryValueRefs(it, scope) } }
                type.type.let { collectTypeQueryValueRefs(it, scope) }
            }
            is TypeLiteral -> {
                for (member in type.members) {
                    when (member) {
                        is PropertyDeclaration -> member.type?.let { collectTypeQueryValueRefs(it, scope) }
                        is MethodDeclaration -> {
                            member.parameters.forEach { p -> p.type?.let { collectTypeQueryValueRefs(it, scope) } }
                            member.type?.let { collectTypeQueryValueRefs(it, scope) }
                        }
                        is IndexSignature -> member.type?.let { collectTypeQueryValueRefs(it, scope) }
                        else -> {}
                    }
                }
            }
            is ConditionalType -> {
                collectTypeQueryValueRefs(type.checkType, scope)
                collectTypeQueryValueRefs(type.extendsType, scope)
                collectTypeQueryValueRefs(type.trueType, scope)
                collectTypeQueryValueRefs(type.falseType, scope)
            }
            is MappedType -> {
                type.type?.let { collectTypeQueryValueRefs(it, scope) }
                type.nameType?.let { collectTypeQueryValueRefs(it, scope) }
                type.typeParameter.constraint?.let { collectTypeQueryValueRefs(it, scope) }
            }
            is IndexedAccessType -> {
                collectTypeQueryValueRefs(type.objectType, scope)
                collectTypeQueryValueRefs(type.indexType, scope)
            }
            is TypeOperator -> collectTypeQueryValueRefs(type.type, scope)
            is RestType -> collectTypeQueryValueRefs(type.type, scope)
            is OptionalType -> collectTypeQueryValueRefs(type.type, scope)
            is TypeReference -> {
                // Bare type reference is TYPE namespace, not value; skip.
                // But type arguments can still contain nested TypeQuery.
                type.typeArguments?.forEach { collectTypeQueryValueRefs(it, scope) }
            }
            is TemplateLiteralType -> type.templateSpans.forEach { span ->
                collectTypeQueryValueRefs(span.type, scope)
            }
            else -> {}
        }
    }

    /** Recursively collect type refs from statements (for unused type param detection). */
    private fun collectTypeRefsInStatement(stmt: Statement, scope: UnusedScope) {
        collectTypeRefsFromJSDoc(stmt.leadingComments, scope)
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.type?.let { collectTypeRefs(it, scope) }
                    decl.initializer?.let { collectTypeRefsInExpr(it, scope) }
                }
            }
            is ExpressionStatement -> collectTypeRefsInExpr(stmt.expression, scope)
            is ReturnStatement -> stmt.expression?.let { collectTypeRefsInExpr(it, scope) }
            is IfStatement -> {
                collectTypeRefsInExpr(stmt.expression, scope)
                collectTypeRefsInStatement(stmt.thenStatement, scope)
                stmt.elseStatement?.let { collectTypeRefsInStatement(it, scope) }
            }
            is Block -> stmt.statements.forEach { collectTypeRefsInStatement(it, scope) }
            is ForStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is ForInStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is ForOfStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is WhileStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is DoStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectTypeRefsInStatement(it, scope) }
                stmt.catchClause?.block?.statements?.forEach { collectTypeRefsInStatement(it, scope) }
                stmt.finallyBlock?.statements?.forEach { collectTypeRefsInStatement(it, scope) }
            }
            is SwitchStatement -> {
                collectTypeRefsInExpr(stmt.expression, scope)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> {
                        collectTypeRefsInExpr(clause.expression, scope)
                        clause.statements.forEach { collectTypeRefsInStatement(it, scope) }
                    }
                    is DefaultClause -> clause.statements.forEach { collectTypeRefsInStatement(it, scope) }
                    else -> {}
                }
            }
            is LabeledStatement -> collectTypeRefsInStatement(stmt.statement, scope)
            is ThrowStatement -> stmt.expression?.let { collectTypeRefsInExpr(it, scope) }
            is ExportAssignment -> collectTypeRefsInExpr(stmt.expression, scope)
            else -> {}
        }
    }

    /** Collect type refs from expressions (type assertions, as expressions, etc.). */
    private fun collectTypeRefsInExpr(expr: Expression, scope: UnusedScope) {
        when (expr) {
            is AsExpression -> {
                collectTypeRefs(expr.type, scope)
                collectTypeRefsInExpr(expr.expression, scope)
            }
            is TypeAssertionExpression -> {
                collectTypeRefs(expr.type, scope)
                collectTypeRefsInExpr(expr.expression, scope)
            }
            is CallExpression -> {
                expr.typeArguments?.forEach { collectTypeRefs(it, scope) }
                collectTypeRefsInExpr(expr.expression, scope)
                expr.arguments.forEach { collectTypeRefsInExpr(it, scope) }
            }
            is NewExpression -> {
                expr.typeArguments?.forEach { collectTypeRefs(it, scope) }
            }
            is ParenthesizedExpression -> collectTypeRefsInExpr(expr.expression, scope)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    collectTypeRefsInExpr(current.right, scope)
                    current = current.left
                }
                collectTypeRefsInExpr(current, scope)
            }
            is ConditionalExpression -> {
                collectTypeRefsInExpr(expr.condition, scope)
                collectTypeRefsInExpr(expr.whenTrue, scope)
                collectTypeRefsInExpr(expr.whenFalse, scope)
            }
            is ArrowFunction -> {
                expr.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectTypeRefs(it, scope) }
                }
                expr.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                expr.type?.let { collectTypeRefs(it, scope) }
            }
            is FunctionExpression -> {
                expr.typeParameters?.forEach { tp ->
                    tp.constraint?.let { collectTypeRefs(it, scope) }
                }
                expr.parameters.forEach { p -> p.type?.let { collectTypeRefs(it, scope) } }
                expr.type?.let { collectTypeRefs(it, scope) }
            }
            else -> {}
        }
    }

    /**
     * Compute 1-based line and character for a position in source text.
     */
    /** Line-start offsets for `source`, by the compiler's ONE line-terminator rule
     *  ([lineBreakWidthAt]) — the same index the Parser builds for its own syntax
     *  diagnostics, so the two can never number a file's lines differently.
     *  Until round 915 this counted `\n` only and therefore reported every position
     *  in a lone-`\r` file as line 1 while the Parser numbered it; `\n` and `\r\n`
     *  are identical under both readings, which is why no baseline could see it.
     *  Memoized per source String (init-order: [lineStartsCache] is declared before init). */
    private fun lineStartsFor(source: String): IntArray =
        lineStartsCache.getOrPut(source) { computeLineStarts(source) }

    private fun getLineAndCharacterOfPosition(source: String, position: Int): Pair<Int, Int> {
        // Byte-for-byte equivalent to the former linear scan: line = 1 + (# of `\n` in
        // [0, min(position, len))), lineStart = index after that last `\n`, character
        // uses the ORIGINAL (un-coerced) position. Binary-search the greatest lineStart
        // offset <= min(position, len) instead of scanning from 0.
        val bound = position.coerceAtMost(source.length)
        val starts = lineStartsFor(source)
        var lo = 0
        var hi = starts.size - 1
        var idx = 0
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            if (starts[mid] <= bound) { idx = mid; lo = mid + 1 } else { hi = mid - 1 }
        }
        return (idx + 1) to (position - starts[idx] + 1)
    }

    /** Inverse of getLineAndCharacterOfPosition: 1-based (line, col) → char offset in `source`.
     *  Reads the SAME memoized index as the forward direction — an inverse built on a
     *  different terminator rule would not round-trip, which is what it silently did for
     *  a lone `\r` before round 915. A `line` past the end of the file answers with the
     *  last line's start, as the former scan-until-found loop did. */
    private fun posOfLineCol(source: String, line: Int, col: Int): Int {
        val starts = lineStartsFor(source)
        return starts[(line - 1).coerceIn(0, starts.size - 1)] + (col - 1)
    }

    /**
     * Shared suppress-and-reemit helper: emit a diagnostic at a baseline (line, col) directly (positions
     * are directive-offset-free, so the baseline line/col map straight onto the stripped source). Used by
     * the corpus-unique pin walkers to re-emit copied-from-baseline diagnostics without source-anchoring.
     */
    private fun pinDiag(source: String, fileName: String, line: Int, col: Int, len: Int, code: Int, msg: String,
                        chain: List<String> = emptyList(), related: List<Diagnostic> = emptyList()) {
        val start = posOfLineCol(source, line, col)
        diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = code,
            fileName = fileName, line = line, character = col, start = start, length = len,
            messageChain = chain, relatedInformation = related))
    }

    /** Build a related-info Diagnostic (Message category). fileName=null / lib name with null line → `:--:--`. */
    private fun pinRel(source: String, fileName: String?, line: Int?, col: Int?, code: Int, msg: String, len: Int = 0): Diagnostic {
        val start = if (line != null && col != null && fileName != null && !isLibFileName(fileName)) posOfLineCol(source, line, col) else 0
        return Diagnostic(message = msg, category = DiagnosticCategory.Message, code = code,
            fileName = fileName, line = line, character = col, start = start, length = len)
    }

    /**
     * Compute the span length for a binding pattern by finding the closing
     * brace/bracket in the source. Our parser's `end` position is set after
     * nextToken() so it extends past the closing delimiter.
     */
    private fun computeBindingPatternSpan(source: String, start: Int, pattern: Node): Int {
        val closeChar = if (pattern is ObjectBindingPattern) '}' else ']'
        var depth = 0
        var i = start
        while (i < source.length) {
            val ch = source[i]
            if (ch == '{' || ch == '[') depth++
            else if (ch == '}' || ch == ']') {
                depth--
                if (depth == 0 && ch == closeChar) return i - start + 1
            }
            i++
        }
        return pattern.end - start
    }

    // -----------------------------------------------------------------------
    // Definite assignment checking (TS2454)
    // -----------------------------------------------------------------------

    // INV.4(d) walker 5 (round 534): the SET-based definite-assignment pass
    // (TS2454) runs ON the check spine. The legacy per-file driver
    // (checkDefiniteAssignment) and the two recursion walkers
    // (checkDefiniteAssignmentInNestedScopes / checkDefiniteAssignmentInExprContext)
    // are DELETED; their statement-list loop is the FRAME step below and their
    // reach is the [spineDaStatus]/[spineDaEdge] classifier. B78.2 semantics
    // preserved exactly: the FILE frame disables leak computation (script-file
    // `let X` may be assigned externally), fn-boundary edges carry the leak,
    // every block-statement boundary (if/loop/switch/labeled descent, fresh
    // Block cores, ModuleBlocks) drops it.

    /** Per-file setup for the spine-hosted definite-assignment pass. */
    private fun spineDaSetup(result: BinderResult) {
        spineDaActive = !options.strictExplicitlyFalse &&
            !options.strictNullChecksExplicitlyFalse && !spineIsDts
        spineDaFrames.clear()
        if (!spineDaActive) {
            spineDaReachMemo = ByteArray(0)
            spineDaFileLocals = null
            return
        }
        val n = result.sourceFile.nodeCount
        spineDaReachMemo = if (n > 0) ByteArray(n) else ByteArray(0)
        spineDaFileLocals = result.locals
    }

    private fun spineDaTeardown() {
        spineDaActive = false
        spineDaFrames.clear()
        spineDaFileLocals = null
        spineDaReachMemo = ByteArray(0)
    }

    /**
     * Construct a CORE frame (a legacy checkDefiniteAssignmentInStatements
     * activation): seed with the B78.2 outer leak minus parameter shadows, then
     * run the round-469 closure-assignment pre-scan over the whole list.
     */
    private fun spineDaNewFrame(
        owner: Node,
        statements: List<Statement>,
        preInitialized: Set<String>,
        fileLocals: SymbolTable?,
        enableLeak: Boolean,
        outerLeak: Set<String>,
    ): SpineDaFrame {
        val frame = SpineDaFrame(owner, statements, preInitialized, fileLocals, enableLeak)
        frame.uninitialized.addAll(outerLeak)
        // preInitialized (function parameters) shadows leaked outer names — params
        // are local declarations that take precedence over the outer-scope binding.
        frame.uninitialized.removeAll(preInitialized)
        // Round 469: a name assigned inside a NESTED function-like of this list can
        // be assigned at any time relative to an outer read (function declarations
        // hoist; the closure may run first) — tsc's definite-assignment never fires
        // for it. Removal-only — straight-line use-before-assign with no closure
        // assignment keeps firing.
        val allCandidates = mutableSetOf<String>()
        for (s in statements) collectUninitializedVars(s, allCandidates, preInitialized, fileLocals)
        if (allCandidates.isNotEmpty()) {
            for (s in statements) collectClosureAssignedNames(s, allCandidates, frame.closureAssigned)
        }
        return frame
    }

    /**
     * The legacy per-statement loop body, run at a core-list statement's enter
     * (children — nested scopes included — are walked by the spine afterwards,
     * reproducing the legacy check-then-recurse order).
     */
    private fun spineDaFrameStep(frame: SpineDaFrame, stmt: Statement) {
        // Collect variable declarations that are uninitialized
        collectUninitializedVars(stmt, frame.uninitialized, frame.preInitialized, frame.fileLocals)
        if (frame.closureAssigned.isNotEmpty()) frame.uninitialized.removeAll(frame.closureAssigned)

        // Check for uses of uninitialized variables in this statement
        if (frame.uninitialized.isNotEmpty()) {
            checkUsesOfUninitialized(stmt, frame.uninitialized, spineSource, spineFileName)
        }

        // Mark variables as assigned if they appear on left side of assignment
        markAssignments(stmt, frame.uninitialized)

        // Compute the B78.2 leak set for nested scopes inside THIS statement:
        // only `let`-declared outer vars with NO assignment anywhere in any
        // nested function body of the current scope. Disabled at the file level
        // (enableLeak=false — file-level `let X` may be assigned externally).
        frame.currentLeak = if (!frame.enableLeak || frame.uninitialized.isEmpty()) emptySet() else {
            val letUninitialized = collectLetUninitializedSoFar(frame.statements, frame.uninitialized)
            if (letUninitialized.isEmpty()) emptySet()
            else {
                val anywhereAssigned = mutableSetOf<String>()
                for (other in frame.statements) {
                    collectAllAssignmentsAnywhere(other, letUninitialized, anywhereAssigned)
                }
                letUninitialized - anywhereAssigned
            }
        }
    }

    /** Per-node ENTER hook for the definite-assignment pass. */
    private fun spineDaEnterNode(node: Node) {
        val frames = spineDaFrames
        // 1. The per-statement frame step — a DIRECT statement of the innermost
        //    core list (its parent IS the top frame's owner; frames for deeper
        //    lists are pushed/popped strictly inside this statement's subtree).
        if (node is Statement && frames.isNotEmpty() &&
            (node as NodeBase).parent === frames[frames.size - 1].owner
        ) {
            spineDaFrameStep(frames[frames.size - 1], node)
        }
        // 2. Core spawns (AFTER the step — a Block statement first runs the
        //    outer frame's step, then opens its own fresh core, matching the
        //    legacy checkUses-then-recurse order).
        when ((node as NodeBase).kindId) {
            NodeKind.SOURCE_FILE -> {
                node as SourceFile
                frames.add(spineDaNewFrame(
                    node, node.statements, emptySet(), spineDaFileLocals,
                    enableLeak = false, outerLeak = emptySet(),
                ))
            }
            NodeKind.BLOCK -> { node as Block; if (spineDaStatus(node) == DA_CORE) spineDaSpawnCore(node, node.statements) }
            NodeKind.MODULE_BLOCK -> { node as ModuleBlock; if (spineDaStatus(node) == DA_CORE) spineDaSpawnCore(node, node.statements) }
            else -> {}
        }
    }

    /** Per-node LEAVE hook: pop the frame this node owns (at most one). */
    private fun spineDaLeaveNode(node: Node) {
        val frames = spineDaFrames
        while (frames.isNotEmpty() && frames[frames.size - 1].owner === node) {
            SpineDispatch.work()
            frames.removeAt(frames.size - 1)
        }
    }

    /**
     * Open a core frame at a CORE-classified Block/ModuleBlock: a fn-like BODY
     * gets its parameters as [SpineDaFrame.preInitialized] and the B78.2 leak
     * per the fn-like's own LEAK-flavored status; a Block-statement/ModuleBlock
     * core is fresh (the legacy Block/ModuleBlock arms dropped both).
     */
    private fun spineDaSpawnCore(owner: Node, statements: List<Statement>) {
        var preInit: Set<String> = emptySet()
        var leak: Set<String> = emptySet()
        when (val parent = (owner as NodeBase).parent) {
            is FunctionDeclaration -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            is MethodDeclaration -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            is Constructor -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            is GetAccessor -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            is SetAccessor -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            is FunctionExpression -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            is ArrowFunction -> if (parent.body === owner) {
                preInit = collectParamNames(parent.parameters); leak = spineDaLeakOf(parent)
            }
            else -> {} // Block-as-statement / ModuleBlock: fresh core
        }
        spineDaFrames.add(spineDaNewFrame(
            owner, statements, preInit, fileLocals = null,
            enableLeak = true, outerLeak = leak,
        ))
    }

    /**
     * The B78.2 leak reaching a fn-like boundary: the innermost core frame's
     * per-statement [SpineDaFrame.currentLeak] when the fn-like sits on a
     * leak-PRESERVING path from its core-list statement (a LEAK-flavored
     * status), else empty (the legacy default-argument drop).
     */
    private fun spineDaLeakOf(fnLike: Node): Set<String> {
        val st = spineDaStatus(fnLike)
        return if ((st == DA_STMT_LEAK || st == DA_EXPR_LEAK || st == DA_MEMBER_LEAK) &&
            spineDaFrames.isNotEmpty()
        ) spineDaFrames[spineDaFrames.size - 1].currentLeak else emptySet()
    }

    /**
     * Memoized multi-state reach classifier — the deleted recursion walkers'
     * dispatch arms verbatim (see the DA_* constants). Ascends to the first
     * memoized/terminal ancestor, then walks back down over [spineDaEdge].
     */
    private fun spineDaStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.DA]++
        if (node is SourceFile) return DA_ROOT
        val memo = spineDaReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.DA, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineDaChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = DA_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → NONE
            if (parent is SourceFile) { anchor = parent; anchorStatus = DA_ROOT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.DA, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = DA_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == DA_NONE) DA_NONE
                else spineDaEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.DA, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.DA]++; ReachCensus.folds[ReachCensus.DA] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** A statement position under a reached list/descent arm: Blocks open their
     *  own fresh core, every other statement is nested-scope-processed. */
    private fun spineDaStmtOrCore(child: Node, leak: Boolean): Int = when {
        child !is Statement -> DA_NONE
        child is Block -> DA_CORE
        leak -> DA_STMT_LEAK
        else -> DA_STMT_NOLEAK
    }

    /**
     * The edge rules — the deleted checkDefiniteAssignmentInNestedScopes (STMT_*
     * arms) and checkDefiniteAssignmentInExprContext (EXPR_* arms) verbatim.
     * Unlisted edges are NONE (the legacy `else -> {}`s: if/loop CONDITIONS,
     * for headers, parameter defaults, class-DECLARATION property initializers,
     * throw expressions, decorators, computed names, type positions).
     */
    private fun spineDaEdge(parent: Node, pStatus: Int, child: Node): Int = when (pStatus) {
        DA_ROOT, DA_CORE -> spineDaStmtOrCore(child, leak = true)
        DA_PASS -> when (parent) {
            // try/catch/finally block statements + switch clause statements:
            // nested-scope descent WITHOUT a core (the legacy forEach arms).
            is Block -> spineDaStmtOrCore(child, leak = false)
            is CatchClause -> if (child === parent.block) DA_PASS else DA_NONE
            is CaseClause, is DefaultClause -> spineDaStmtOrCore(child, leak = false)
            else -> DA_NONE
        }
        DA_STMT_LEAK, DA_STMT_NOLEAK -> {
            val leak = pStatus == DA_STMT_LEAK
            when (parent) {
                is FunctionDeclaration ->
                    if (ModifierFlag.Declare !in parent.modifiers && child === parent.body) DA_CORE
                    else DA_NONE
                is ClassDeclaration ->
                    if (ModifierFlag.Declare !in parent.modifiers &&
                        (child is MethodDeclaration || child is Constructor ||
                            child is GetAccessor || child is SetAccessor)
                    ) (if (leak) DA_MEMBER_LEAK else DA_MEMBER_NOLEAK)
                    else DA_NONE
                is ModuleDeclaration -> when {
                    ModifierFlag.Declare in parent.modifiers -> DA_NONE
                    child !== parent.body -> DA_NONE
                    child is ModuleBlock -> DA_CORE
                    // dotted `namespace A.B` body: re-enter the nested-scopes arm
                    // (the legacy recursion dropped the leak here).
                    child is ModuleDeclaration -> DA_STMT_NOLEAK
                    else -> DA_NONE
                }
                is IfStatement ->
                    if (child === parent.thenStatement || child === parent.elseStatement)
                        spineDaStmtOrCore(child, leak = false) else DA_NONE
                is ForStatement -> if (child === parent.statement) spineDaStmtOrCore(child, false) else DA_NONE
                is ForInStatement -> if (child === parent.statement) spineDaStmtOrCore(child, false) else DA_NONE
                is ForOfStatement -> if (child === parent.statement) spineDaStmtOrCore(child, false) else DA_NONE
                is WhileStatement -> if (child === parent.statement) spineDaStmtOrCore(child, false) else DA_NONE
                is DoStatement -> if (child === parent.statement) spineDaStmtOrCore(child, false) else DA_NONE
                is SwitchStatement -> if (child is CaseClause || child is DefaultClause) DA_PASS else DA_NONE
                is TryStatement ->
                    if (child === parent.tryBlock || child === parent.finallyBlock ||
                        child === parent.catchClause) DA_PASS else DA_NONE
                is LabeledStatement -> if (child === parent.statement) spineDaStmtOrCore(child, false) else DA_NONE
                // VariableStatement declarator initializers → expression context
                // (the legacy VariableStatement arm), carried through the
                // declaration-list/declaration nodes.
                is VariableStatement -> if (child is VariableDeclarationList)
                    (if (leak) DA_STMT_LEAK else DA_STMT_NOLEAK) else DA_NONE
                is VariableDeclarationList -> if (child is VariableDeclaration)
                    (if (leak) DA_STMT_LEAK else DA_STMT_NOLEAK) else DA_NONE
                is VariableDeclaration -> if (child === parent.initializer)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                is ExpressionStatement -> if (child === parent.expression)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                is ReturnStatement -> if (child === parent.expression)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                else -> DA_NONE
            }
        }
        DA_MEMBER_LEAK, DA_MEMBER_NOLEAK -> {
            val leak = pStatus == DA_MEMBER_LEAK
            when (parent) {
                is MethodDeclaration -> if (child === parent.body) DA_CORE else DA_NONE
                is Constructor -> if (child === parent.body) DA_CORE else DA_NONE
                is GetAccessor -> if (child === parent.body) DA_CORE else DA_NONE
                is SetAccessor -> if (child === parent.body) DA_CORE else DA_NONE
                // class-EXPRESSION property initializers ARE reached (the legacy
                // ClassExpression arm); class-DECLARATION members never mint a
                // PropertyDeclaration MEMBER status, preserving the asymmetry.
                is PropertyDeclaration -> if (child === parent.initializer)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                is PropertyAssignment -> if (child === parent.initializer)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                is SpreadAssignment -> if (child === parent.expression)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                is TemplateSpan -> if (child === parent.expression)
                    (if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK) else DA_NONE
                else -> DA_NONE
            }
        }
        DA_EXPR_LEAK, DA_EXPR_NOLEAK -> {
            val leak = pStatus == DA_EXPR_LEAK
            val expr = if (leak) DA_EXPR_LEAK else DA_EXPR_NOLEAK
            val member = if (leak) DA_MEMBER_LEAK else DA_MEMBER_NOLEAK
            when (parent) {
                is ClassExpression ->
                    if (child is MethodDeclaration || child is Constructor ||
                        child is GetAccessor || child is SetAccessor ||
                        child is PropertyDeclaration) member else DA_NONE
                is FunctionExpression -> if (child === parent.body) DA_CORE else DA_NONE
                is ArrowFunction -> when {
                    child !== parent.body -> DA_NONE
                    child is Block -> DA_CORE
                    else -> expr // expression body passes the leak through
                }
                is CallExpression ->
                    if (child === parent.expression || parent.arguments.anyIdentical(child)) expr
                    else DA_NONE
                is NewExpression ->
                    if (child === parent.expression || parent.arguments?.anyIdentical(child) == true) expr
                    else DA_NONE
                is BinaryExpression -> if (child === parent.left || child === parent.right) expr else DA_NONE
                is ParenthesizedExpression -> if (child === parent.expression) expr else DA_NONE
                is AsExpression -> if (child === parent.expression) expr else DA_NONE
                is TypeAssertionExpression -> if (child === parent.expression) expr else DA_NONE
                is SatisfiesExpression -> if (child === parent.expression) expr else DA_NONE
                is NonNullExpression -> if (child === parent.expression) expr else DA_NONE
                is ConditionalExpression ->
                    if (child === parent.condition || child === parent.whenTrue ||
                        child === parent.whenFalse) expr else DA_NONE
                is PropertyAccessExpression -> if (child === parent.expression) expr else DA_NONE
                is ElementAccessExpression ->
                    if (child === parent.expression || child === parent.argumentExpression) expr
                    else DA_NONE
                is ArrayLiteralExpression -> if (parent.elements.anyIdentical(child)) expr else DA_NONE
                is ObjectLiteralExpression -> when (child) {
                    // ShorthandPropertyAssignment (incl. its default initializer)
                    // was NOT descended by the legacy object-literal arm.
                    is PropertyAssignment, is SpreadAssignment,
                    is MethodDeclaration, is GetAccessor, is SetAccessor -> member
                    else -> DA_NONE
                }
                is SpreadElement -> if (child === parent.expression) expr else DA_NONE
                is AwaitExpression -> if (child === parent.expression) expr else DA_NONE
                is YieldExpression -> if (child === parent.expression) expr else DA_NONE
                is VoidExpression -> if (child === parent.expression) expr else DA_NONE
                is DeleteExpression -> if (child === parent.expression) expr else DA_NONE
                is TypeOfExpression -> if (child === parent.expression) expr else DA_NONE
                is PrefixUnaryExpression -> if (child === parent.operand) expr else DA_NONE
                is PostfixUnaryExpression -> if (child === parent.operand) expr else DA_NONE
                is TemplateExpression -> if (child is TemplateSpan) member else DA_NONE
                is TaggedTemplateExpression -> when {
                    child === parent.tag -> expr
                    child === parent.template && child is TemplateExpression -> expr
                    else -> DA_NONE
                }
                is CommaListExpression -> if (parent.elements.anyIdentical(child)) expr else DA_NONE
                else -> DA_NONE
            }
        }
        else -> DA_NONE
    }

    // ── (M0.4) round 624: checkObjectSpreadInvalidTypes on the spine ──────

    /** Per-file setup for the spine-hosted object-spread/rest pass. */
    private fun spineOsSetup(result: BinderResult) {
        spineOsActive = !spineIsDts
        spineOsAnns.reset()
        spineOsReachMemo = if (!spineOsActive) ByteArray(0) else {
            val n = result.sourceFile.nodeCount
            if (n > 0) ByteArray(n) else ByteArray(0)
        }
    }

    private fun spineOsTeardown() {
        spineOsActive = false
        spineOsAnns.reset()
        spineOsReachMemo = ByteArray(0)
    }

    /** Per-node ENTER hook: frame spawns at the legacy copy edges, the
     *  recording/rest step at declarators, the TS2698 anchor at spreads. */
    private fun spineOsEnterNode(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.SOURCE_FILE -> { spineOsAnns.push(node); return }
            NodeKind.BLOCK -> {
                when (spineOsStatus(node)) {
                    OS_STMT -> spineOsPushCopy(node)
                    OS_FNBLOCK -> spineOsPushFnBody(node)
                }
                return
            }
            NodeKind.MODULE_BLOCK -> { if (spineOsStatus(node) == OS_MODBLOCK) spineOsPushCopy(node); return }
            NodeKind.CASE_CLAUSE, NodeKind.DEFAULT_CLAUSE -> {
                if (spineOsStatus(node) == OS_CLAUSE) spineOsPushCopy(node)
                return
            }
            NodeKind.VARIABLE_DECLARATION -> { spineOsVarDecl(node as VariableDeclaration); return }
            NodeKind.SPREAD_ASSIGNMENT -> { spineOsSpreadAnchor(node as SpreadAssignment); return }
            else -> {}
        }
        // The legacy copy edges whose child is a NON-Block statement (a bare
        // if-branch / loop-body statement got its own HashMap copy), plus the
        // arrow EXPRESSION body's params-seeded frame.
        val parent = node.parent ?: return
        when ((parent as NodeBase).kindId) {
            NodeKind.IF_STATEMENT -> {
                parent as IfStatement
                if ((node === parent.thenStatement || node === parent.elseStatement) &&
                    spineOsStatus(node) == OS_STMT
                ) spineOsPushCopy(node)
            }
            NodeKind.FOR_STATEMENT -> {
                parent as ForStatement
                if (node === parent.statement && spineOsStatus(node) == OS_STMT) spineOsPushCopy(node)
            }
            NodeKind.FOR_IN_STATEMENT -> {
                parent as ForInStatement
                if (node === parent.statement && spineOsStatus(node) == OS_STMT) spineOsPushCopy(node)
            }
            NodeKind.FOR_OF_STATEMENT -> {
                parent as ForOfStatement
                if (node === parent.statement && spineOsStatus(node) == OS_STMT) spineOsPushCopy(node)
            }
            NodeKind.WHILE_STATEMENT -> {
                parent as WhileStatement
                if (node === parent.statement && spineOsStatus(node) == OS_STMT) spineOsPushCopy(node)
            }
            NodeKind.DO_STATEMENT -> {
                parent as DoStatement
                if (node === parent.statement && spineOsStatus(node) == OS_STMT) spineOsPushCopy(node)
            }
            NodeKind.ARROW_FUNCTION -> {
                parent as ArrowFunction
                if (node === parent.body && spineOsStatus(node) == OS_FNEXPRBODY) {
                    spineOsPushFnFrame(node, parent.parameters)
                }
            }
            else -> {}
        }
    }

    /** Per-node LEAVE hook: pop the frame(s) this node owns. */
    private fun spineOsLeaveNode(node: Node) {
        while (spineOsAnns.topOwner() === node) {
            SpineDispatch.work()
            spineOsAnns.pop()
        }
    }

    private fun spineOsTopAnns(): Map<String, TypeNode> = spineOsAnns.view

    private fun spineOsPushCopy(owner: Node) {
        FrontEnd.addCopy(FrontEnd.CP_OS, 0)
        spineOsAnns.push(owner)
    }

    /** A fn-like's Block body: copy of the fn-position map + its Identifier-named
     *  annotated params (the legacy spread2698FuncLike seeding). */
    private fun spineOsPushFnBody(body: Node) {
        val params: List<Parameter> = when (val fn = (body as NodeBase).parent) {
            is FunctionDeclaration -> fn.parameters
            is MethodDeclaration -> fn.parameters
            is Constructor -> fn.parameters
            is GetAccessor -> fn.parameters
            is SetAccessor -> fn.parameters
            is FunctionExpression -> fn.parameters
            is ArrowFunction -> fn.parameters
            else -> return
        }
        spineOsPushFnFrame(body, params)
    }

    private fun spineOsPushFnFrame(owner: Node, params: List<Parameter>) {
        FrontEnd.addCopy(FrontEnd.CP_OS, 0)
        spineOsAnns.push(owner)
        for (p in params) {
            val id = p.name as? Identifier ?: continue
            val t = p.type ?: continue
            FrontEnd.noteMut(FrontEnd.CP_OS); FrontEnd.addUndo(FrontEnd.CP_OS, 1)
            spineOsAnns.put(id.text, t)
        }
    }

    /** The legacy VariableStatement per-declarator step: record the annotation,
     *  then the object-REST TS2700 check — both BEFORE the initializer subtree
     *  is walked (the spine visits children after this enter). */
    private fun spineOsVarDecl(d: VariableDeclaration) {
        if (spineOsStatus(d) != OS_VD) return
        val anns = spineOsTopAnns()
        (d.name as? Identifier)?.let { id ->
            d.type?.let {
                FrontEnd.noteMut(FrontEnd.CP_OS); FrontEnd.addUndo(FrontEnd.CP_OS, 1)
                spineOsAnns.put(id.text, it)
            }
        }
        val restEl = (d.name as? ObjectBindingPattern)?.elements?.firstOrNull { it.dotDotDotToken }
        val initE = d.initializer
        if (restEl != null && initE != null) {
            spineOsWithAmbient(d) { rest2700Check(restEl, initE, anns, spineSource, spineFileName) }
        }
    }

    /** The TS2698 anchor — a SpreadAssignment of a reached object literal. */
    private fun spineOsSpreadAnchor(el: SpreadAssignment) {
        if (spineOsStatus(el) != OS_SPREADP) return
        spineOsWithAmbient(el) { spread2698CheckOperand(el, spineOsTopAnns(), spineSource, spineFileName) }
    }

    /**
     * Per-dispatch ambient sandwich: the legacy pass installed
     * currentCheckFileName per file (checkSpine only installs
     * currentFileLocals — the documented gotcha), and layered
     * [withInternedTpScope] at every walked fn-like; rebuild the layering
     * pull-based from the anchor's ancestor chain, outermost-first (inner
     * shadows outer, and constraints materialize outer-first — the legacy
     * order at this anchor).
     */
    private fun spineOsWithAmbient(anchor: Node, block: () -> Unit) {
        val savedFile = currentCheckFileName
        currentCheckFileName = spineFileName
        try {
            val tpLists = spineOsTpChain(anchor)
            if (tpLists == null) block() else spineOsApplyTps(tpLists, 0, block)
        } finally {
            currentCheckFileName = savedFile
        }
    }

    /** Enclosing fn-likes' non-empty type-parameter lists, outermost first —
     *  only fn-likes whose BODY contains the anchor (params/defaults are
     *  unreached, so every reached anchor sits inside each ancestor's body). */
    private fun spineOsTpChain(anchor: Node): List<List<TypeParameter>>? {
        var lists: ArrayList<List<TypeParameter>>? = null
        var child: Node = anchor
        var cur: Node? = (anchor as NodeBase).parent
        while (cur != null && cur !is SourceFile) {
            val tps: List<TypeParameter>? = when (cur) {
                is FunctionDeclaration -> if (cur.body === child) cur.typeParameters else null
                is MethodDeclaration -> if (cur.body === child) cur.typeParameters else null
                is FunctionExpression -> if (cur.body === child) cur.typeParameters else null
                is ArrowFunction -> if (cur.body === child) cur.typeParameters else null
                else -> null
            }
            if (!tps.isNullOrEmpty()) {
                (lists ?: ArrayList<List<TypeParameter>>().also { lists = it }).add(tps)
            }
            child = cur
            cur = (cur as NodeBase).parent
        }
        return lists?.also { it.reverse() }
    }

    private fun spineOsApplyTps(lists: List<List<TypeParameter>>, i: Int, block: () -> Unit) {
        if (i >= lists.size) { block(); return }
        withInternedTpScope(lists[i], withAst = false) { spineOsApplyTps(lists, i + 1, block) }
    }

    /**
     * Memoized reach classifier — the deleted spread2698Stmt/spread2698Expr
     * dispatch arms verbatim (see the OS_* constants). Ascends to the first
     * memoized/terminal ancestor, then walks back down over [spineOsEdge].
     */
    private fun spineOsStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.OS]++
        if (node is SourceFile) return OS_ROOT
        val memo = spineOsReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.OS, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineOsChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = OS_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → NONE
            if (parent is SourceFile) { anchor = parent; anchorStatus = OS_ROOT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.OS, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = OS_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == OS_NONE) OS_NONE
                else spineOsEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.OS, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.OS]++; ReachCensus.folds[ReachCensus.OS] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** The edge rules — the deleted recursion arms verbatim. Unlisted edges
     *  are NONE (the legacy `else -> {}`s). */
    private fun spineOsEdge(parent: Node, pStatus: Int, child: Node): Int = when (pStatus) {
        OS_ROOT -> if (child is Statement) OS_STMT else OS_NONE
        OS_STMT -> when (parent) {
            is VariableStatement -> if (child is VariableDeclarationList) OS_VDL else OS_NONE
            is ExpressionStatement -> if (child === parent.expression) OS_EXPR else OS_NONE
            is ReturnStatement -> if (child === parent.expression) OS_EXPR else OS_NONE
            is ThrowStatement -> if (child === parent.expression) OS_EXPR else OS_NONE
            is FunctionDeclaration -> if (child === parent.body) OS_FNBLOCK else OS_NONE
            is Block -> if (child is Statement) OS_STMT else OS_NONE
            is IfStatement -> when {
                child === parent.expression -> OS_EXPR
                child === parent.thenStatement || child === parent.elseStatement -> OS_STMT
                else -> OS_NONE
            }
            is ForStatement -> if (child === parent.statement) OS_STMT else OS_NONE
            is ForInStatement -> if (child === parent.statement) OS_STMT else OS_NONE
            is ForOfStatement -> if (child === parent.statement) OS_STMT else OS_NONE
            is WhileStatement -> if (child === parent.statement) OS_STMT else OS_NONE
            is DoStatement -> if (child === parent.statement) OS_STMT else OS_NONE
            is TryStatement -> when {
                child === parent.tryBlock || child === parent.finallyBlock -> OS_STMT
                child === parent.catchClause -> OS_CATCH
                else -> OS_NONE
            }
            is SwitchStatement -> if (child is CaseClause || child is DefaultClause) OS_CLAUSE else OS_NONE
            is LabeledStatement -> if (child === parent.statement) OS_STMT else OS_NONE
            // Legacy: only a direct ModuleBlock body is walked (a dotted
            // `namespace A.B` body is a ModuleDeclaration → unreached).
            is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) OS_MODBLOCK else OS_NONE
            is ClassDeclaration -> when (child) {
                is MethodDeclaration, is Constructor, is GetAccessor, is SetAccessor -> OS_FNMEMBER
                is PropertyDeclaration -> OS_CLSPROP
                else -> OS_NONE
            }
            else -> OS_NONE
        }
        OS_VDL -> if (child is VariableDeclaration) OS_VD else OS_NONE
        OS_VD -> if (parent is VariableDeclaration && child === parent.initializer) OS_EXPR else OS_NONE
        OS_CATCH -> if (parent is CatchClause && child === parent.block) OS_STMT else OS_NONE
        OS_CLAUSE -> if (child is Statement) OS_STMT else OS_NONE
        OS_MODBLOCK -> if (child is Statement) OS_STMT else OS_NONE
        OS_FNBLOCK -> if (child is Statement) OS_STMT else OS_NONE
        OS_CLSPROP -> if (parent is PropertyDeclaration && child === parent.initializer) OS_EXPR else OS_NONE
        OS_FNMEMBER -> when (parent) {
            is MethodDeclaration -> if (child === parent.body) OS_FNBLOCK else OS_NONE
            is Constructor -> if (child === parent.body) OS_FNBLOCK else OS_NONE
            is GetAccessor -> if (child === parent.body) OS_FNBLOCK else OS_NONE
            is SetAccessor -> if (child === parent.body) OS_FNBLOCK else OS_NONE
            else -> OS_NONE
        }
        OS_SPREADP -> if (parent is SpreadAssignment && child === parent.expression) OS_EXPR else OS_NONE
        OS_PROPASSIGN -> if (parent is PropertyAssignment && child === parent.initializer) OS_EXPR else OS_NONE
        OS_SHORTHAND ->
            if (parent is ShorthandPropertyAssignment && child === parent.objectAssignmentInitializer) OS_EXPR
            else OS_NONE
        OS_EXPR, OS_FNEXPRBODY -> when (parent) {
            is ObjectLiteralExpression -> when (child) {
                is SpreadAssignment -> OS_SPREADP
                is PropertyAssignment -> OS_PROPASSIGN
                is MethodDeclaration, is GetAccessor, is SetAccessor -> OS_FNMEMBER
                is ShorthandPropertyAssignment -> OS_SHORTHAND
                else -> OS_NONE
            }
            is ArrayLiteralExpression -> if (child is Expression) OS_EXPR else OS_NONE
            is ParenthesizedExpression -> if (child === parent.expression) OS_EXPR else OS_NONE
            is CallExpression ->
                if (child === parent.expression || parent.arguments.anyIdentical(child)) OS_EXPR
                else OS_NONE
            is NewExpression ->
                if (child === parent.expression || parent.arguments?.anyIdentical(child) == true) OS_EXPR
                else OS_NONE
            is BinaryExpression -> if (child === parent.left || child === parent.right) OS_EXPR else OS_NONE
            is ConditionalExpression ->
                if (child === parent.condition || child === parent.whenTrue || child === parent.whenFalse) OS_EXPR
                else OS_NONE
            is PropertyAccessExpression -> if (child === parent.expression) OS_EXPR else OS_NONE
            is ElementAccessExpression ->
                if (child === parent.expression || child === parent.argumentExpression) OS_EXPR else OS_NONE
            is SpreadElement -> if (child === parent.expression) OS_EXPR else OS_NONE
            is AsExpression -> if (child === parent.expression) OS_EXPR else OS_NONE
            is TypeAssertionExpression -> if (child === parent.expression) OS_EXPR else OS_NONE
            is NonNullExpression -> if (child === parent.expression) OS_EXPR else OS_NONE
            is PrefixUnaryExpression -> if (child === parent.operand) OS_EXPR else OS_NONE
            is PostfixUnaryExpression -> if (child === parent.operand) OS_EXPR else OS_NONE
            is AwaitExpression -> if (child === parent.expression) OS_EXPR else OS_NONE
            is FunctionExpression -> if (child === parent.body) OS_FNBLOCK else OS_NONE
            is ArrowFunction -> when {
                child !== parent.body -> OS_NONE
                child is Block -> OS_FNBLOCK
                else -> OS_FNEXPRBODY
            }
            else -> OS_NONE
        }
        else -> OS_NONE
    }

    // ── (M0.4) round 624: checkArrayPushDiscriminatedUnionElements on the
    // spine ──────────────────────────────────────────────────────────────

    /** Per-file setup for the spine-hosted array-push/splice/concat pass. */
    private fun spinePdSetup(result: BinderResult) {
        spinePdActive = !spineIsDts
        spinePdAnns.reset()
        spinePdReachMemo = if (!spinePdActive) ByteArray(0) else {
            val n = result.sourceFile.nodeCount
            if (n > 0) ByteArray(n) else ByteArray(0)
        }
    }

    private fun spinePdTeardown() {
        spinePdActive = false
        spinePdAnns.reset()
        spinePdReachMemo = ByteArray(0)
    }

    /** Per-node ENTER hook: frame spawns at the legacy copy boundaries, the
     *  per-statement record/check work at the four reached statement kinds. */
    private fun spinePdEnterNode(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.SOURCE_FILE -> spinePdAnns.push(node)
            NodeKind.BLOCK -> when (spinePdStatus(node)) {
                PD_LIST, PD_NESTED, PD_FNBODY_PLAIN -> spinePdPushCopy(node, null)
                PD_FNBODY -> spinePdPushCopy(node, spinePdParamsOf(node))
            }
            NodeKind.MODULE_BLOCK -> { if (spinePdStatus(node) == PD_MODBLOCK) spinePdPushCopy(node, null) }
            NodeKind.VARIABLE_STATEMENT, NodeKind.EXPRESSION_STATEMENT,
            NodeKind.RETURN_STATEMENT, NodeKind.IF_STATEMENT,
            -> {
                val st = spinePdStatus(node)
                if (st == PD_LIST || st == PD_NESTED) spinePdStatement(node, st)
            }
            else -> {}
        }
    }

    /** Per-node LEAVE hook: pop the frame this node owns. */
    private fun spinePdLeaveNode(node: Node) {
        while (spinePdAnns.topOwner() === node) {
            SpineDispatch.work()
            spinePdAnns.pop()
        }
    }

    private fun spinePdTopAnns(): Map<String, TypeNode> = spinePdAnns.view

    private fun spinePdPushCopy(owner: Node, params: List<Parameter>?) {
        FrontEnd.addCopy(FrontEnd.CP_PD, 0)
        spinePdAnns.push(owner)
        if (params != null) {
            for (p in params) {
                val n = (p.name as? Identifier)?.text
                val t = p.type
                if (n != null && t != null) {
                    FrontEnd.noteMut(FrontEnd.CP_PD); FrontEnd.addUndo(FrontEnd.CP_PD, 1)
                    spinePdAnns.put(n, t)
                }
            }
        }
    }

    /** The params seeded into a PD_FNBODY Block's copy (the legacy
     *  pdduChildScope call sites — get-accessors deliberately excluded). */
    private fun spinePdParamsOf(body: Node): List<Parameter>? = when (val fn = (body as NodeBase).parent) {
        is FunctionDeclaration -> fn.parameters
        is MethodDeclaration -> fn.parameters
        is Constructor -> fn.parameters
        is SetAccessor -> fn.parameters
        else -> null
    }

    /**
     * The legacy per-statement work: LIST statements record ALL their
     * declarator annotations BEFORE any initializer is checked (the
     * pdduScanStmts loop order); NESTED statements only check. pdduCheckExpr
     * is a no-op for non-call expressions, so the ambient install is gated to
     * genuine CallExpression positions.
     */
    private fun spinePdStatement(node: Node, status: Int) {
        when ((node as NodeBase).kindId) {
            NodeKind.VARIABLE_STATEMENT -> {
                node as VariableStatement
                val anns = spinePdTopAnns()
                if (status == PD_LIST) {
                    for (d in node.declarationList.declarations) {
                        val n = (d.name as? Identifier)?.text
                        val t = d.type
                        if (n != null && t != null) {
                            FrontEnd.noteMut(FrontEnd.CP_PD); FrontEnd.addUndo(FrontEnd.CP_PD, 1)
                            spinePdAnns.put(n, t)
                        }
                    }
                }
                for (d in node.declarationList.declarations) {
                    val init = d.initializer ?: continue
                    if (init is CallExpression) spinePdWithAmbient {
                        pdduCheckExpr(init, spineSource, spineFileName, anns)
                    }
                }
            }
            NodeKind.EXPRESSION_STATEMENT -> {
                node as ExpressionStatement
                val e = node.expression
                if (e is CallExpression) spinePdWithAmbient {
                    pdduCheckExpr(e, spineSource, spineFileName, spinePdTopAnns())
                }
            }
            NodeKind.RETURN_STATEMENT -> {
                node as ReturnStatement
                val e = node.expression
                if (e is CallExpression) spinePdWithAmbient {
                    pdduCheckExpr(e, spineSource, spineFileName, spinePdTopAnns())
                }
            }
            NodeKind.IF_STATEMENT -> {
                node as IfStatement
                val e = node.expression
                if (e is CallExpression) spinePdWithAmbient {
                    pdduCheckExpr(e, spineSource, spineFileName, spinePdTopAnns())
                }
            }
            else -> {}
        }
    }

    /** The legacy pass never installed currentFileLocals (its slot's resting
     *  value applied); mid-spine it is per-file, so install the spine-entry
     *  resting value around each dispatch. */
    private inline fun spinePdWithAmbient(block: () -> Unit) {
        val saved = currentFileLocals
        currentFileLocals = spinePdRestingLocals
        try {
            block()
        } finally {
            currentFileLocals = saved
        }
    }

    /**
     * (WARM.22) round 875 — one amplification bracket for [spineCeEdge].
     *
     * `r` EXTRA evaluations of the SAME edge on the SAME `(parent, child)` under
     * ONE timestamp pair, so `nanos(r) = boundary + r * c` and two values of `r`
     * cancel the boundary (round 759). The production evaluation on the next
     * line is UNCHANGED and outside the pair — this adds work, it never replaces
     * any, so the compile's output cannot move.
     *
     * The predicate is pure and the callee is far over `FreqInlineSize` (49
     * arms), so the loop cannot be folded away; [ReachCensus.ampSink] `% r == 0`
     * is the arithmetic that says so rather than assuming it.
     *
     * It measures the WARM MARGINAL cost of an evaluation — everything the
     * predicate touches is in L1 by the second iteration — so it is a LOWER
     * bound on what the same call costs in production, and the prize computed
     * from it is a lower bound too.
     */
    private fun reachAmpCe(parent: Node, child: Node) {
        val r = ReachCensus.amp
        var s = 0L
        var q = 0
        val t0 = PassTiming.nowNanos()
        while (q < r) {
            if (spineCeEdge(parent, child)) s++
            q++
        }
        ReachCensus.ampNanos[ReachCensus.AMP_CE] += PassTiming.nowNanos() - t0
        ReachCensus.ampCalls[ReachCensus.AMP_CE] += r.toLong()
        ReachCensus.ampBrackets[ReachCensus.AMP_CE]++
        ReachCensus.ampSink[ReachCensus.AMP_CE] += s
    }

    /** (WARM.22) — [reachAmpCe]'s twin at 106 arms instead of 49. The PAIR is
     *  the instrument: one site gives a cost, two sites of different arm counts
     *  give the slope IN ARMS, which is what decides whether the linear
     *  `instanceof` chain is the cost or merely where the cost sits. */
    private fun reachAmpFp(parent: Node, child: Node) {
        val r = ReachCensus.amp
        var s = 0L
        var q = 0
        val t0 = PassTiming.nowNanos()
        while (q < r) {
            if (spineFpEdge(parent, child)) s++
            q++
        }
        ReachCensus.ampNanos[ReachCensus.AMP_FP] += PassTiming.nowNanos() - t0
        ReachCensus.ampCalls[ReachCensus.AMP_FP] += r.toLong()
        ReachCensus.ampBrackets[ReachCensus.AMP_FP]++
        ReachCensus.ampSink[ReachCensus.AMP_FP] += s
    }

    /** Memoized reach classifier — the deleted pdduScanStmts/pdduScanStmt
     *  dispatch arms verbatim (see the PD_* constants). */
    private fun spinePdStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.PD]++
        if (node is SourceFile) return PD_ROOT
        val memo = spinePdReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.PD, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spinePdChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = PD_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → NONE
            if (parent is SourceFile) { anchor = parent; anchorStatus = PD_ROOT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.PD, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = PD_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == PD_NONE) PD_NONE
                else spinePdEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.PD, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.PD]++; ReachCensus.folds[ReachCensus.PD] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** The edge rules — the deleted recursion arms verbatim. Unlisted edges
     *  are NONE. */
    private fun spinePdEdge(parent: Node, pStatus: Int, child: Node): Int = when (pStatus) {
        PD_ROOT -> if (child is Statement) PD_LIST else PD_NONE
        PD_LIST, PD_NESTED -> when (parent) {
            is Block -> if (child is Statement) PD_LIST else PD_NONE
            is IfStatement ->
                if (child === parent.thenStatement || child === parent.elseStatement) PD_NESTED else PD_NONE
            is ForStatement -> if (child === parent.statement) PD_NESTED else PD_NONE
            is ForInStatement -> if (child === parent.statement) PD_NESTED else PD_NONE
            is ForOfStatement -> if (child === parent.statement) PD_NESTED else PD_NONE
            is WhileStatement -> if (child === parent.statement) PD_NESTED else PD_NONE
            is DoStatement -> if (child === parent.statement) PD_NESTED else PD_NONE
            is FunctionDeclaration -> if (child === parent.body) PD_FNBODY else PD_NONE
            is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) PD_MODBLOCK else PD_NONE
            is ClassDeclaration -> when (child) {
                is MethodDeclaration, is Constructor, is SetAccessor -> PD_MEMBER_PARAMS
                is GetAccessor -> PD_MEMBER_PLAIN
                else -> PD_NONE
            }
            else -> PD_NONE
        }
        PD_MEMBER_PARAMS -> when (parent) {
            is MethodDeclaration -> if (child === parent.body) PD_FNBODY else PD_NONE
            is Constructor -> if (child === parent.body) PD_FNBODY else PD_NONE
            is SetAccessor -> if (child === parent.body) PD_FNBODY else PD_NONE
            else -> PD_NONE
        }
        PD_MEMBER_PLAIN -> if (parent is GetAccessor && child === parent.body) PD_FNBODY_PLAIN else PD_NONE
        PD_FNBODY, PD_FNBODY_PLAIN, PD_MODBLOCK -> if (child is Statement) PD_LIST else PD_NONE
        else -> PD_NONE
    }

    /**
     * B78.2: filter `uninitialized` (which may include `var` and `const` decls
     * from prior collection passes) to keep only names declared as `let` in the
     * current scope's statement list. `const` vars get TS1155, not TS2454, when
     * read uninitialized; `var` is function-scoped and TypeScript doesn't fire
     * TS2454 for nested reads of an undeclared-init `var`.
     */
    private fun collectLetUninitializedSoFar(
        statements: List<Statement>,
        currentUninitialized: Set<String>,
    ): Set<String> {
        val letNames = mutableSetOf<String>()
        for (stmt in statements) {
            if (stmt !is VariableStatement) continue
            if (stmt.declarationList.flags != SyntaxKind.LetKeyword) continue
            if (ModifierFlag.Declare in stmt.modifiers) continue
            for (decl in stmt.declarationList.declarations) {
                val n = decl.name
                if (n is Identifier && n.text in currentUninitialized) {
                    letNames.add(n.text)
                }
            }
        }
        return letNames
    }

    /**
     * B78.2: walk a statement (including nested function bodies, block-scoped
     * children, and expression trees) and collect any names from `candidates`
     * that appear as an assignment target. Covers `x = ...`, destructuring
     * `[x] = ...` / `{x} = ...`, `for (x in ...) / for (x of ...)`. Used to
     * suppress outer-leak for names that have ANY assignment anywhere in the
     * outer scope's body — matching TypeScript's tolerance for nested-function
     * patterns that initialize captured vars.
     */
    private fun collectAllAssignmentsAnywhere(
        stmt: Statement, candidates: Set<String>, found: MutableSet<String>,
    ) {
        when (stmt) {
            is ExpressionStatement -> collectAssignmentsInExpr(stmt.expression, candidates, found)
            is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                if (decl.initializer != null) {
                    val n = decl.name
                    if (n is Identifier && n.text in candidates) found.add(n.text)
                }
                decl.initializer?.let { collectAssignmentsInExpr(it, candidates, found) }
            }
            is Block -> stmt.statements.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
            is IfStatement -> {
                collectAssignmentsInExpr(stmt.expression, candidates, found)
                collectAllAssignmentsAnywhere(stmt.thenStatement, candidates, found)
                stmt.elseStatement?.let { collectAllAssignmentsAnywhere(it, candidates, found) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> collectAssignmentsInExpr(init, candidates, found)
                    is VariableDeclarationList -> for (decl in init.declarations) {
                        decl.initializer?.let { collectAssignmentsInExpr(it, candidates, found) }
                    }
                    else -> {}
                }
                stmt.condition?.let { collectAssignmentsInExpr(it, candidates, found) }
                stmt.incrementor?.let { collectAssignmentsInExpr(it, candidates, found) }
                collectAllAssignmentsAnywhere(stmt.statement, candidates, found)
            }
            is ForInStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> if (init is Identifier && init.text in candidates) found.add(init.text)
                    else -> {}
                }
                collectAssignmentsInExpr(stmt.expression, candidates, found)
                collectAllAssignmentsAnywhere(stmt.statement, candidates, found)
            }
            is ForOfStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> if (init is Identifier && init.text in candidates) found.add(init.text)
                    else -> {}
                }
                collectAssignmentsInExpr(stmt.expression, candidates, found)
                collectAllAssignmentsAnywhere(stmt.statement, candidates, found)
            }
            is WhileStatement -> {
                collectAssignmentsInExpr(stmt.expression, candidates, found)
                collectAllAssignmentsAnywhere(stmt.statement, candidates, found)
            }
            is DoStatement -> {
                collectAssignmentsInExpr(stmt.expression, candidates, found)
                collectAllAssignmentsAnywhere(stmt.statement, candidates, found)
            }
            is SwitchStatement -> {
                collectAssignmentsInExpr(stmt.expression, candidates, found)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> clause.statements.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                    is DefaultClause -> clause.statements.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                    else -> {}
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                stmt.catchClause?.block?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                stmt.finallyBlock?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
            }
            is LabeledStatement -> collectAllAssignmentsAnywhere(stmt.statement, candidates, found)
            is FunctionDeclaration -> stmt.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
            is ReturnStatement -> stmt.expression?.let { collectAssignmentsInExpr(it, candidates, found) }
            is ThrowStatement -> stmt.expression?.let { collectAssignmentsInExpr(it, candidates, found) }
            else -> {}
        }
    }

    private fun collectAssignmentsInExpr(
        expr: Expression, candidates: Set<String>, found: MutableSet<String>,
    ) {
        when (expr) {
            is BinaryExpression -> {
                // Only DEFINITE assignments suppress the leak: plain `=` AND the logical
                // assignments `??=`/`||=`/`&&=` (tsc getAssignmentTargetKind returns
                // AssignmentKind.Definite for EqualsToken and every
                // isLogicalOrCoalescingAssignmentOperator — checker.ts
                // isSymbolAssignedDefinitely feeds isNeverInitialized, round 427; tsc's
                // own `(sourceStack ??= []).push(source)` in a nested closure suppresses
                // the captured-read TS2454). Compound assignments (`+=`, `|=`, etc.) are
                // read-modify-write — AssignmentKind.Compound, NOT definite — so the read
                // still hits the uninitialized value and TypeScript still emits TS2454
                // (unusedLocalsInMethod4's `enabledSubstitutions |= …` pins this).
                // Pre/post inc/dec are similarly Compound and do NOT count.
                // Iterative left-spine walk. The definite-assignment target rule is
                // applied PER SPINE NODE, not just the outermost expression — a comma
                // expression nests an assignment on the LEFT spine (tsc's own
                // `(!memberName ? (memberName = t.symbol.escapedName, true) : …)`,
                // checker.ts getSignaturesOfType), and an outer-only check silently
                // skipped it (tsc markNodeAssignments is a full forEachChild walk).
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    if (cur.operator == SyntaxKind.Equals ||
                        cur.operator == SyntaxKind.QuestionQuestionEquals ||
                        cur.operator == SyntaxKind.BarBarEquals ||
                        cur.operator == SyntaxKind.AmpersandAmpersandEquals
                    ) {
                        val l = cur.left
                        if (l is Identifier && l.text in candidates) found.add(l.text)
                        else if (l is ObjectLiteralExpression || l is ArrayLiteralExpression) {
                            collectDestructuringAssignTargets(l, candidates, found)
                        }
                    }
                    collectAssignmentsInExpr(cur.right, candidates, found)
                    cur = cur.left
                }
                collectAssignmentsInExpr(cur, candidates, found)
            }
            is PostfixUnaryExpression -> {
                // read-modify-write — do NOT mark as suppressing leak (matches TypeScript)
            }
            is PrefixUnaryExpression -> {
                collectAssignmentsInExpr(expr.operand, candidates, found)
            }
            is CallExpression -> {
                collectAssignmentsInExpr(expr.expression, candidates, found)
                expr.arguments.forEach { collectAssignmentsInExpr(it, candidates, found) }
            }
            is NewExpression -> {
                collectAssignmentsInExpr(expr.expression, candidates, found)
                expr.arguments?.forEach { collectAssignmentsInExpr(it, candidates, found) }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> body.statements.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                is Expression -> collectAssignmentsInExpr(body, candidates, found)
                else -> {}
            }
            is FunctionExpression -> expr.body.statements.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                is Constructor -> m.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                is GetAccessor -> m.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                is SetAccessor -> m.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                else -> {}
            }
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> collectAssignmentsInExpr(p.initializer, candidates, found)
                is ShorthandPropertyAssignment -> p.objectAssignmentInitializer?.let { collectAssignmentsInExpr(it, candidates, found) }
                is SpreadAssignment -> collectAssignmentsInExpr(p.expression, candidates, found)
                is MethodDeclaration -> p.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                is GetAccessor -> p.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                is SetAccessor -> p.body?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
                else -> {}
            }
            is ArrayLiteralExpression -> expr.elements.forEach { collectAssignmentsInExpr(it, candidates, found) }
            is ParenthesizedExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is AsExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is TypeAssertionExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is SatisfiesExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is NonNullExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is ConditionalExpression -> {
                collectAssignmentsInExpr(expr.condition, candidates, found)
                collectAssignmentsInExpr(expr.whenTrue, candidates, found)
                collectAssignmentsInExpr(expr.whenFalse, candidates, found)
            }
            is PropertyAccessExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is ElementAccessExpression -> {
                collectAssignmentsInExpr(expr.expression, candidates, found)
                collectAssignmentsInExpr(expr.argumentExpression, candidates, found)
            }
            is SpreadElement -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is AwaitExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is YieldExpression -> expr.expression?.let { collectAssignmentsInExpr(it, candidates, found) }
            is VoidExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is DeleteExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is TypeOfExpression -> collectAssignmentsInExpr(expr.expression, candidates, found)
            is TemplateExpression -> for (span in expr.templateSpans) collectAssignmentsInExpr(span.expression, candidates, found)
            is TaggedTemplateExpression -> {
                collectAssignmentsInExpr(expr.tag, candidates, found)
                if (expr.template is TemplateExpression) for (span in (expr.template).templateSpans) collectAssignmentsInExpr(span.expression, candidates, found)
            }
            is CommaListExpression -> expr.elements.forEach { collectAssignmentsInExpr(it, candidates, found) }
            else -> {}
        }
    }

    private fun collectDestructuringAssignTargets(
        expr: Expression, candidates: Set<String>, found: MutableSet<String>,
    ) {
        when (expr) {
            is Identifier -> if (expr.text in candidates) found.add(expr.text)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is ShorthandPropertyAssignment -> if (p.name.text in candidates) found.add(p.name.text)
                is PropertyAssignment -> collectDestructuringAssignTargets(p.initializer, candidates, found)
                is SpreadAssignment -> collectDestructuringAssignTargets(p.expression, candidates, found)
                else -> {}
            }
            is ArrayLiteralExpression -> for (e in expr.elements) when (e) {
                is SpreadElement -> collectDestructuringAssignTargets(e.expression, candidates, found)
                is OmittedExpression -> {}
                else -> collectDestructuringAssignTargets(e, candidates, found)
            }
            is BinaryExpression -> if (expr.operator == SyntaxKind.Equals) collectDestructuringAssignTargets(expr.left, candidates, found)
            is ParenthesizedExpression -> collectDestructuringAssignTargets(expr.expression, candidates, found)
            is AsExpression -> collectDestructuringAssignTargets(expr.expression, candidates, found)
            is SatisfiesExpression -> collectDestructuringAssignTargets(expr.expression, candidates, found)
            is TypeAssertionExpression -> collectDestructuringAssignTargets(expr.expression, candidates, found)
            else -> {}
        }
    }

    private fun collectUninitializedVars(
        stmt: Statement,
        uninitialized: MutableSet<String>,
        preInitialized: Set<String> = emptySet(),
        fileLocals: SymbolTable? = null,
    ) {
        when (stmt) {
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (decl in stmt.declarationList.declarations) {
                    // Only flag variables with type annotation but no initializer
                    // Skip definite assignment assertions (var x!: Type)
                    if (decl.type != null && decl.initializer == null && !decl.exclamationToken) {
                        // Skip `var x: any` — `any` includes undefined, no assignment needed
                        if (isAnyType(decl.type)) continue
                        // Skip if type annotation is a bare generic reference (TS2314 error type)
                        if (isUnresolvedGenericType(decl.type)) continue
                        // Skip import types (e.g. `import('./b').B`) — we can't resolve them
                        if (typeContainsImportType(decl.type)) continue
                        // Skip types that include undefined — variable is implicitly initialized to undefined
                        if (typeIncludesUndefined(decl.type)) continue
                        // (M3.0/ANY.1) round 837: tsc's `assumeInitialized` ALSO covers a `void`
                        // annotation and a `typeof undefined` query — see [varTypeAssumedInitialized].
                        // Deliberately NOT folded into [typeIncludesUndefined], whose other two
                        // callers are TS2564 sites where tsc uses `containsUndefinedType` instead
                        // and a `void` property DOES want the diagnostic.
                        if (varTypeAssumedInitialized(decl.type)) continue
                        // Skip if the type annotation is a reference to a namespace symbol.
                        // Namespace-typed vars (var a: A where A is a namespace) get TS2709 but NOT TS2454.
                        if (fileLocals != null && isNamespaceTypeRef(decl.type, fileLocals)) continue
                        val name = decl.name
                        if (name is Identifier) {
                            // Skip if name matches a function parameter (var redeclaration of param)
                            if (name.text !in preInitialized) {
                                uninitialized.add(name.text)
                            }
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Returns true if the type annotation is a TypeReference directly to a namespace symbol.
     * Used to suppress TS2454 for vars typed as plain namespace names (e.g. `var a: SomeNamespace`).
     * TypeScript flags TS2709 (cannot use namespace as type) for such declarations instead of TS2454.
     * Note: qualified types like `var x: A.B` are NOT suppressed, since A.B may be a valid class/interface.
     */
    private fun isNamespaceTypeRef(type: TypeNode?, locals: SymbolTable): Boolean {
        if (type !is TypeReference) return false
        val typeName = type.typeName
        // Only check simple identifiers — `var a: A` where A is a namespace
        val name = (typeName as? Identifier)?.text ?: return false
        val symbol = locals[name] ?: return false
        // If the name resolves to any kind of module/namespace, TypeScript flags TS2709 not TS2454
        return symbol.flags.hasAny(SymbolFlags.Module)
    }

    private fun isAnyType(type: Node?): Boolean {
        if (type == null) return false
        // Check for keyword type nodes like `any` and `unknown`
        // Both are top types — a variable typed `unknown` can hold any value including undefined
        return type.kind == SyntaxKind.AnyKeyword || type.kind == SyntaxKind.UnknownKeyword
    }

    /**
     * Returns true if the type annotation contains an import type (e.g. `import('./b').B`).
     * We can't resolve import types, so we skip TS2564 checking for properties with such types.
     */
    private fun typeContainsImportType(type: Node?): Boolean {
        if (type == null) return false
        if (type is ImportType) return true
        // Check nested: QualifiedName inside TypeReference, or union/intersection members
        return when (type) {
            is TypeReference -> typeContainsImportType(type.typeName)
            is UnionType -> type.types.any { typeContainsImportType(it) }
            is IntersectionType -> type.types.any { typeContainsImportType(it) }
            is ArrayType -> typeContainsImportType(type.elementType)
            is QualifiedName -> typeContainsImportType(type.left) || typeContainsImportType(type.right)
            else -> false
        }
    }

    /**
     * Returns true if the type syntactically includes `undefined`.
     * Variables typed as `T | undefined` start with undefined as a valid value,
     * so they don't need definite assignment (no TS2454).
     * Note: `null` alone does NOT satisfy definite assignment — only `undefined` does.
     */
    private fun typeIncludesUndefined(type: Node?): Boolean {
        if (type == null) return false
        return when (type) {
            is UnionType -> type.types.any { member ->
                member.kind == SyntaxKind.UndefinedKeyword ||
                    typeIncludesUndefined(member)
            }
            else -> type.kind == SyntaxKind.UndefinedKeyword
        }
    }

    /**
     * (M3.0/ANY.1) round 837 — the rest of tsc's `assumeInitialized` disjunction for a
     * variable READ, as far as it is decidable from the annotation alone:
     *
     *  * `void` — tsc tests `type.flags & (TypeFlags.AnyOrUnknown | TypeFlags.Void)`, so a
     *    `void`-annotated variable never reports TS2454 (`assignEveryTypeToAny`'s `var d: void`).
     *  * `typeof undefined` — the query resolves to `undefinedType`, whose type facts carry
     *    `IsUndefined`, which is the OTHER half of tsc's guard (`var e2: typeof undefined`).
     *
     * Syntactic on purpose: this runs inside the TS2454 candidate COLLECTOR, and resolving an
     * annotation there would make the set a function of resolution order (the round-778 class).
     * Kept separate from [typeIncludesUndefined] because that predicate's other callers are
     * TS2564 property sites, where tsc uses `containsUndefinedType` — under which a `void`
     * property DOES want the diagnostic.
     */
    private fun varTypeAssumedInitialized(type: TypeNode?): Boolean {
        if (type == null) return false
        if (type.kind == SyntaxKind.VoidKeyword) return true
        if (type is TypeQuery) return (type.exprName as? Identifier)?.text == "undefined"
        if (type is UnionType) return type.types.any { varTypeAssumedInitialized(it) }
        return false
    }

    /**
     * Check expression trees for references to uninitialized variables.
     * When found, emit TS2454 and remove from uninitialized set (report only first use).
     */
    /**
     * Unwrap type-only expression wrappers (`as`, `<T>`, `satisfies`,
     * non-null `!`, and `(...)` parentheses) to find the underlying value
     * expression. Used by the definite-assignment walker so that
     * `(b satisfies T) = 10` correctly marks `b` as assigned after the
     * read-then-write check has fired.
     */
    private fun unwrapTypeOnlyWrapper(expr: Expression): Expression {
        var cur: Expression = expr
        while (true) {
            cur = when (cur) {
                is SatisfiesExpression -> cur.expression
                is AsExpression -> cur.expression
                is TypeAssertionExpression -> cur.expression
                is NonNullExpression -> cur.expression
                is ParenthesizedExpression -> if (cur.instantiationEnd == null) cur.expression else return cur
                else -> return cur
            }
        }
    }

    private fun checkUsesOfUninitialized(
        stmt: Statement,
        uninitialized: MutableSet<String>,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let {
                        findUninitializedRefs(it, uninitialized, source, fileName)
                    }
                }
            }
            is ExpressionStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let {
                    findUninitializedRefs(it, uninitialized, source, fileName)
                }
            }
            is IfStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
                // Recurse into else-if chains to check their conditions,
                // but NOT into body blocks (they may have type-narrowed variables
                // that our simplified checker can't track via control flow analysis)
                val elseStmt = stmt.elseStatement
                if (elseStmt is IfStatement) {
                    checkUsesOfUninitialized(elseStmt, uninitialized, source, fileName)
                }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> {
                        findUninitializedRefs(init, uninitialized, source, fileName)
                        markAssignmentsInExpr(init, uninitialized)
                    }
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let {
                                findUninitializedRefs(it, uninitialized, source, fileName)
                            }
                            // Variable with initializer is assigned
                            if (decl.initializer != null) {
                                val name = decl.name
                                if (name is Identifier) uninitialized.remove(name.text)
                            }
                        }
                    }
                    else -> {}
                }
                stmt.condition?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is ForInStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ForOfStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is WhileStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ThrowStatement -> {
                stmt.expression?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is SwitchStatement -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is ClassDeclaration -> {
                // Check heritage clause expressions (extends/implements) for TS2454
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) {
                        findUninitializedRefs(type.expression, uninitialized, source, fileName)
                    }
                }
            }
            is Block -> {
                for (s in stmt.statements) {
                    checkUsesOfUninitialized(s, uninitialized, source, fileName)
                    markAssignments(s, uninitialized)
                }
            }
            is DoStatement -> {
                checkUsesOfUninitialized(stmt.statement, uninitialized, source, fileName)
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) {
                    checkUsesOfUninitialized(s, uninitialized, source, fileName)
                    markAssignments(s, uninitialized)
                }
            }
            is LabeledStatement -> {
                checkUsesOfUninitialized(stmt.statement, uninitialized, source, fileName)
            }
            is ExportAssignment -> {
                findUninitializedRefs(stmt.expression, uninitialized, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Walk an expression tree to find references to uninitialized variables.
     * Emits TS2454 diagnostic at the usage site.
     */
    private fun findUninitializedRefs(
        expr: Expression,
        uninitialized: MutableSet<String>,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is Identifier -> {
                if (expr.text in uninitialized) {
                    val start = expr.pos
                    val length = expr.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Variable '${expr.text}' is used before being assigned.",
                        category = DiagnosticCategory.Error,
                        code = 2454,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            is PropertyAccessExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            }
            is ElementAccessExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                findUninitializedRefs(expr.argumentExpression, uninitialized, source, fileName)
            }
            is CallExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                expr.arguments.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is NewExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                expr.arguments?.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    // Assignment — right side may use uninitialized, left side is a write
                    findUninitializedRefs(expr.right, uninitialized, source, fileName)
                    // Mark the left side as assigned (so subsequent uses are not flagged)
                    // But for property/element access (d.x = v, d[i] = v), the base object is READ
                    val left = expr.left
                    when (left) {
                        is Identifier -> uninitialized.remove(left.text)
                        is PropertyAccessExpression -> findUninitializedRefs(left.expression, uninitialized, source, fileName)
                        is ElementAccessExpression -> {
                            findUninitializedRefs(left.expression, uninitialized, source, fileName)
                            findUninitializedRefs(left.argumentExpression, uninitialized, source, fileName)
                        }
                        is ObjectLiteralExpression -> {
                            emitReadsForTypeWrappedDestructuring(left, uninitialized, source, fileName)
                            collectDestructuringTargets(left, uninitialized)
                        }
                        is ArrayLiteralExpression -> {
                            emitReadsForTypeWrappedDestructuring(left, uninitialized, source, fileName)
                            collectDestructuringTargets(left, uninitialized)
                        }
                        // ParenthesizedExpression: handle two cases.
                        //  (a) instantiationEnd != null — synthetic paren from an instantiation
                        //      expression like `getValue<number>`. TypeScript treats this as
                        //      an invalid assignment target (TS2364) AND as a use-before-assigned
                        //      of the inner Identifier.
                        //  (b) wrapping a type-only cast `(x as T)`, `<T>x`, or `x satisfies T`
                        //      — TypeScript flags the underlying identifier as a READ
                        //      (`(b satisfies T) = 10` emits TS2454 for `b`).
                        is ParenthesizedExpression -> {
                            if (left.instantiationEnd != null) {
                                findUninitializedRefs(left.expression, uninitialized, source, fileName)
                            } else when (val inner = left.expression) {
                                is SatisfiesExpression, is AsExpression, is TypeAssertionExpression -> {
                                    findUninitializedRefs(inner, uninitialized, source, fileName)
                                    // After the read, also mark the underlying identifier as assigned.
                                    val underlying = unwrapTypeOnlyWrapper(inner)
                                    if (underlying is Identifier) uninitialized.remove(underlying.text)
                                }
                                is Identifier -> uninitialized.remove(inner.text)
                                else -> {}
                            }
                        }
                        else -> {}
                    }
                } else if (expr.operator == SyntaxKind.Comma) {
                    // Comma operator: evaluate left first, mark assignments, then evaluate right.
                    // This correctly handles `t0 = t1, t1 = t0` where t0 is assigned before t1 uses it.
                    findUninitializedRefs(expr.left, uninitialized, source, fileName)
                    // Left side is done; now right side can benefit from its assignments
                    findUninitializedRefs(expr.right, uninitialized, source, fileName)
                } else {
                    // Iterative left spine to avoid StackOverflow
                    var current: Expression = expr
                    while (current is BinaryExpression && current.operator != SyntaxKind.Equals &&
                           current.operator != SyntaxKind.Comma) {
                        findUninitializedRefs(current.right, uninitialized, source, fileName)
                        current = current.left
                    }
                    if (current is BinaryExpression) {
                        findUninitializedRefs(current.right, uninitialized, source, fileName)
                    } else {
                        findUninitializedRefs(current, uninitialized, source, fileName)
                    }
                }
            }
            is ConditionalExpression -> {
                findUninitializedRefs(expr.condition, uninitialized, source, fileName)
                findUninitializedRefs(expr.whenTrue, uninitialized, source, fileName)
                findUninitializedRefs(expr.whenFalse, uninitialized, source, fileName)
            }
            is PrefixUnaryExpression -> {
                findUninitializedRefs(expr.operand, uninitialized, source, fileName)
            }
            is PostfixUnaryExpression -> {
                findUninitializedRefs(expr.operand, uninitialized, source, fileName)
            }
            is ParenthesizedExpression -> {
                findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            // Check computed property names: { [t]: 0 } reads t
                            val name = prop.name
                            if (name is ComputedPropertyName) {
                                findUninitializedRefs(name.expression, uninitialized, source, fileName)
                            }
                            findUninitializedRefs(prop.initializer, uninitialized, source, fileName)
                        }
                        is ShorthandPropertyAssignment -> {
                            findUninitializedRefs(prop.name, uninitialized, source, fileName)
                        }
                        is SpreadAssignment -> {
                            findUninitializedRefs(prop.expression, uninitialized, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach {
                    findUninitializedRefs(it.expression, uninitialized, source, fileName)
                }
            }
            is TaggedTemplateExpression -> {
                findUninitializedRefs(expr.tag, uninitialized, source, fileName)
            }
            is SpreadElement -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is AwaitExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is YieldExpression -> expr.expression?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
            is AsExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is NonNullExpression -> {
                // Round 427: a read wrapped DIRECTLY in a non-null assertion assumes
                // initialized (tsc checkIdentifier's assumeInitialized disjunction has
                // a literal `node.parent.kind === SyntaxKind.NonNullExpression` — tsc's
                // own core.ts `return lastResult!` never draws TS2454). Only a bare
                // Identifier DIRECTLY under the `!` is exempt (covers `x!` and
                // `x!.prop` — the identifier's parent is the NonNullExpression in
                // both); `(obj.foo)!` still walks the receiver `obj` (its parent is
                // the PropertyAccess, not the assertion).
                if (expr.expression !is Identifier) {
                    findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                }
            }
            is TypeOfExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is DeleteExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is VoidExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is TypeAssertionExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is SatisfiesExpression -> findUninitializedRefs(expr.expression, uninitialized, source, fileName)
            is CommaListExpression -> {
                expr.elements.forEach { findUninitializedRefs(it, uninitialized, source, fileName) }
            }
            else -> {} // Literals, arrow functions, etc. — no direct references
        }
    }

    /**
     * Mark variables as assigned when they appear on the left side of assignments.
     */
    private fun markAssignments(stmt: Statement, uninitialized: MutableSet<String>) {
        when (stmt) {
            is ExpressionStatement -> {
                markAssignmentsInExpr(stmt.expression, uninitialized)
            }
            is VariableStatement -> {
                // Variable with initializer — it's assigned
                for (decl in stmt.declarationList.declarations) {
                    if (decl.initializer != null) {
                        val name = decl.name
                        if (name is Identifier) {
                            uninitialized.remove(name.text)
                        }
                    }
                }
            }
            is IfStatement -> {
                // Assignments in if/else branches — scan both branches
                markAssignmentsInStmt(stmt.thenStatement, uninitialized)
                stmt.elseStatement?.let { markAssignmentsInStmt(it, uninitialized) }
            }
            is SwitchStatement -> {
                // Assignments in switch cases — scan all case bodies
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    for (s in clauseStmts) markAssignmentsInStmt(s, uninitialized)
                }
            }
            is Block -> {
                for (s in stmt.statements) markAssignments(s, uninitialized)
            }
            is WhileStatement -> {
                // Round 450: a `while (true)` loop's ONLY normal exit is a `break` (its
                // condition never becomes false), so a variable assigned before EVERY
                // break that exits the loop is definitely assigned after it — tsc's
                // definite-assignment for constant-true loops. Pervasive scanner idiom:
                // `let tok: T; while (true) { if (...) { tok = X; break; } ... } return tok;`.
                // (Only `while (true)` — a general `while (cond)` body may run zero times,
                // so its assignments are not guaranteed and this case is unhandled there.)
                if (isConstantTrueCondition(stmt.expression) && uninitialized.isNotEmpty()) {
                    val toRemove = uninitialized.filter {
                        whileTrueDefinitelyAssigns(stmt.statement, it)
                    }
                    uninitialized.removeAll(toRemove.toSet())
                }
            }
            else -> {}
        }
    }

    /** `while (true)` / `do…while (true)` constant-true condition (round 450). */
    private fun isConstantTrueCondition(expr: Expression): Boolean =
        (expr as? Identifier)?.text == "true" ||
            (expr as? ParenthesizedExpression)?.let { isConstantTrueCondition(it.expression) } == true

    /** Completion state for the [whileTrueDefinitelyAssigns] walk. */
    private class DaComp(val fallsThrough: Boolean, val assigned: Boolean)

    private class DaState {
        var allBreaksAssigned = true
        var bail = false
    }

    /**
     * Round 450: is variable [v] definitely assigned on every `break` edge that exits a
     * `while (true)` loop whose body is [body]? (Vacuously true when there are no exiting
     * breaks — the post-loop code is then unreachable, which tsc does not flag.) A sound
     * forward definite-assignment walk for a single variable: sequential flow, if/else
     * join, and abrupt completion (break/return/throw/continue). BAILS (returns false,
     * keeping the conservative "still uninitialized" behavior) on any labeled break/continue
     * or a `try`/labeled statement that could hide an exiting break — never over-clears.
     * Nested loops and `switch` are opaque (their unlabeled breaks target themselves, and
     * their assignments are not credited).
     */
    private fun whileTrueDefinitelyAssigns(body: Statement, v: String): Boolean {
        if (containsLabeledBreakEscaping(body)) return false
        val st = DaState()
        daWalkStmt(body, v, assignedOnEntry = false, st = st)
        return !st.bail && st.allBreaksAssigned
    }

    private fun daWalkStmt(stmt: Statement, v: String, assignedOnEntry: Boolean, st: DaState): DaComp {
        if (st.bail) return DaComp(false, false)
        return when (stmt) {
            is Block -> daWalkList(stmt.statements, v, assignedOnEntry, st)
            is ExpressionStatement -> DaComp(true, assignedOnEntry || exprAssignsVarSimple(stmt.expression, v))
            is IfStatement -> {
                val t = daWalkStmt(stmt.thenStatement, v, assignedOnEntry, st)
                val e = stmt.elseStatement?.let { daWalkStmt(it, v, assignedOnEntry, st) }
                    ?: DaComp(true, assignedOnEntry)
                when {
                    t.fallsThrough && e.fallsThrough -> DaComp(true, t.assigned && e.assigned)
                    t.fallsThrough -> DaComp(true, t.assigned)
                    e.fallsThrough -> DaComp(true, e.assigned)
                    else -> DaComp(false, false)
                }
            }
            is BreakStatement -> {
                // Unlabeled break directly in the walked region exits THIS loop.
                st.allBreaksAssigned = st.allBreaksAssigned && assignedOnEntry
                DaComp(false, false)
            }
            is ContinueStatement, is ReturnStatement, is ThrowStatement -> DaComp(false, false)
            // A nested loop / switch is opaque: its unlabeled breaks target itself (we
            // pre-scanned for labeled breaks), and its conditional assignments are not
            // credited. It completes normally without changing v's assignment state.
            is WhileStatement, is DoStatement, is ForStatement, is ForInStatement,
            is ForOfStatement, is SwitchStatement -> DaComp(true, assignedOnEntry)
            // Could hide an exiting break — bail conservatively.
            is TryStatement, is LabeledStatement -> { st.bail = true; DaComp(false, false) }
            // VariableStatement can only introduce a (shadowing) binding of v, never assign
            // the outer v; any other statement kind cannot contain a break exiting our loop.
            else -> DaComp(true, assignedOnEntry)
        }
    }

    private fun daWalkList(stmts: List<Statement>, v: String, entryAssigned: Boolean, st: DaState): DaComp {
        var assigned = entryAssigned
        for (s in stmts) {
            if (st.bail) return DaComp(false, false)
            val c = daWalkStmt(s, v, assigned, st)
            if (!c.fallsThrough) return DaComp(false, false) // remaining statements are unreachable
            assigned = c.assigned
        }
        return DaComp(true, assigned)
    }

    /** Does evaluating [expr] definitely assign the simple variable [v] (`v = …`, `[v] = …`,
     *  `{v} = …`, chained/comma assignments)? Reuses [markAssignmentsInExpr]'s detection. */
    private fun exprAssignsVarSimple(expr: Expression, v: String): Boolean {
        val s = mutableSetOf(v)
        markAssignmentsInExpr(expr, s)
        return v !in s
    }

    private fun markAssignmentsInStmt(stmt: Statement, uninitialized: MutableSet<String>) {
        when (stmt) {
            is ExpressionStatement -> markAssignmentsInExpr(stmt.expression, uninitialized)
            is Block -> stmt.statements.forEach { markAssignmentsInStmt(it, uninitialized) }
            is IfStatement -> {
                markAssignmentsInStmt(stmt.thenStatement, uninitialized)
                stmt.elseStatement?.let { markAssignmentsInStmt(it, uninitialized) }
            }
            else -> {}
        }
    }

    private fun markAssignmentsInExpr(expr: Expression, uninitialized: MutableSet<String>) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    val left = expr.left
                    when (left) {
                        is Identifier -> uninitialized.remove(left.text)
                        is ObjectLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                        is ArrayLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                        else -> {}
                    }
                }
                // Iterative left spine to avoid StackOverflow
                var current: Expression = expr
                while (current is BinaryExpression) {
                    markAssignmentsInExpr(current.right, uninitialized)
                    if (current.operator == SyntaxKind.Equals) {
                        val left = current.left
                        when (left) {
                            is Identifier -> uninitialized.remove(left.text)
                            is ObjectLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                            is ArrayLiteralExpression -> collectDestructuringTargets(left, uninitialized)
                            else -> {}
                        }
                    }
                    current = current.left
                }
                markAssignmentsInExpr(current, uninitialized)
            }
            is CommaListExpression -> {
                expr.elements.forEach { markAssignmentsInExpr(it, uninitialized) }
            }
            is ParenthesizedExpression -> markAssignmentsInExpr(expr.expression, uninitialized)
            else -> {}
        }
    }

    /** Extract assigned variable names from destructuring assignment targets. */
    private fun collectDestructuringTargets(expr: Expression, uninitialized: MutableSet<String>) {
        when (expr) {
            is Identifier -> uninitialized.remove(expr.text)
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is ShorthandPropertyAssignment -> uninitialized.remove(prop.name.text)
                        is PropertyAssignment -> collectDestructuringTargets(prop.initializer, uninitialized)
                        is SpreadAssignment -> collectDestructuringTargets(prop.expression, uninitialized)
                        else -> {}
                    }
                }
            }
            is ArrayLiteralExpression -> {
                for (elem in expr.elements) {
                    when (elem) {
                        is SpreadElement -> collectDestructuringTargets(elem.expression, uninitialized)
                        is OmittedExpression -> {} // skip holes
                        else -> collectDestructuringTargets(elem, uninitialized)
                    }
                }
            }
            is BinaryExpression -> {
                // Default value: `x = defaultVal` — the target is `x`
                if (expr.operator == SyntaxKind.Equals) {
                    collectDestructuringTargets(expr.left, uninitialized)
                }
            }
            // `(x as T)`, `(x satisfies T)`, `(<T>x)` inside a destructuring target —
            // unwrap and recurse so the inner identifier is still marked assigned.
            is ParenthesizedExpression -> if (expr.instantiationEnd == null) {
                collectDestructuringTargets(expr.expression, uninitialized)
            }
            is SatisfiesExpression -> collectDestructuringTargets(expr.expression, uninitialized)
            is AsExpression -> collectDestructuringTargets(expr.expression, uninitialized)
            is TypeAssertionExpression -> collectDestructuringTargets(expr.expression, uninitialized)
            else -> {}
        }
    }

    /**
     * Walk a destructuring LHS looking for `(x as T)`, `(x satisfies T)` and
     * `(<T>x)` shapes whose inner identifier should ALSO count as a read for
     * definite-assignment checking. TypeScript treats the type-wrapped form as
     * a read even when on the LHS of an assignment.
     */
    private fun emitReadsForTypeWrappedDestructuring(
        expr: Expression, uninitialized: MutableSet<String>, source: String, fileName: String,
    ) {
        when (expr) {
            is ParenthesizedExpression -> if (expr.instantiationEnd == null) {
                when (expr.expression) {
                    is SatisfiesExpression, is AsExpression, is TypeAssertionExpression ->
                        findUninitializedRefs(expr.expression, uninitialized, source, fileName)
                    else -> emitReadsForTypeWrappedDestructuring(expr.expression, uninitialized, source, fileName)
                }
            }
            is ArrayLiteralExpression -> for (el in expr.elements) when (el) {
                is SpreadElement -> emitReadsForTypeWrappedDestructuring(el.expression, uninitialized, source, fileName)
                is OmittedExpression -> {}
                else -> emitReadsForTypeWrappedDestructuring(el, uninitialized, source, fileName)
            }
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> emitReadsForTypeWrappedDestructuring(p.initializer, uninitialized, source, fileName)
                is ShorthandPropertyAssignment -> p.objectAssignmentInitializer?.let { findUninitializedRefs(it, uninitialized, source, fileName) }
                is SpreadAssignment -> emitReadsForTypeWrappedDestructuring(p.expression, uninitialized, source, fileName)
                else -> {}
            }
            is BinaryExpression -> if (expr.operator == SyntaxKind.Equals) {
                emitReadsForTypeWrappedDestructuring(expr.left, uninitialized, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Collect identifier names from a parameter list (for pre-initializing TS2454 scope).
     * Parameters are always assigned when the function body executes.
     */
    private fun collectParamNames(parameters: List<Parameter>): Set<String> {
        val names = mutableSetOf<String>()
        for (param in parameters) {
            val name = param.name
            if (name is Identifier && name.text != "this") {
                names.add(name.text)
            }
        }
        return names
    }

    // -----------------------------------------------------------------------
    // 17.30a: Flow-graph-based definite-assignment supplement (TS2454)
    // -----------------------------------------------------------------------
    //
    // Augments the ad-hoc walker above. The ad-hoc walker explicitly does NOT
    // recurse into IfStatement / WhileStatement / ForStatement / SwitchStatement /
    // TryStatement bodies (Checker.kt:5436+), missing TS2454 for reads inside
    // those bodies (e.g. `nestedLoopTypeGuards_ts` line 9). This pass walks
    // those bodies via the file's pre-built flow graph (`Flow.kt` /
    // `FlowGraphBuilder`) and emits TS2454 only when the flow walk confirms
    // the variable has no reaching FlowAssignment AND the path has no
    // type-guard condition implying assignment (e.g. `typeof a === 'string'`
    // true-branch).
    //
    // Narrow gate (per 17.30a):
    //   - Function-local `let`/`var` only (function-scoped uninitialized).
    //   - Same suppression filters as the ad-hoc walker (any/unknown/import
    //     types/types-including-undefined/declare/namespace-typed).
    //   - Emits ONLY when the read is inside an unchecked body context
    //     (if/while/for/switch/try body) — top-level reads remain the
    //     ad-hoc walker's responsibility, and dedup via emitted-positions
    //     prevents any double-fire.
    //
    // 17.1c history: a prior snapshot/restore attempt regressed -7 (emitted
    // at body reads like `a.length` because TypeScript's TS2454 treats a
    // successful positive type-guard as implicit assignment for subsequent
    // reads). This pass models that by walking through `FlowCondition` nodes
    // and recognizing a small set of conditions that imply assignment.
    /**
     * B223: TS2454 "Variable 'X' is used before being assigned." for a `var` whose
     * ONLY assignment sits inside a TRY block with a normally-completing catch
     * (controlFlowDestructuringVariablesInTryCatch). tsc's definite-assignment uses
     * AND-semantics at the post-try merge — the catch-entry path equals the pre-try
     * state (an exception may fire before any assignment), so the var is possibly
     * unassigned after the try. Our isAssignedAtFlow deliberately uses
     * OR-semantics (FP-conservative) and both TS2454 mechanisms only track
     * NO-initializer declarations — `var x = init` inside a try was invisible.
     * Self-contained walker; default-suppress: candidates need concrete inferred
     * types excluding undefined (incl. tuple/object destructure elements and
     * defaults); ANY other assignment/declaration of the name in the scope (incl.
     * catch/finally/nested fns) drops it; the read scan is straight-line and stops
     * at the first control-flow statement; `typeof x` and write-targets exempt.
     */
    private fun checkTryCatchOnlyAssignedVarReads() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            tcvProcessScope(result.sourceFile.statements, result.sourceFile.text, fileName, emptySet())
        }
    }

    private fun tcvProcessScope(stmts: List<Statement>, source: String, fileName: String, paramNames: Set<String>) {
        // Recurse into nested function scopes first.
        for (s in stmts) {
            (s as? FunctionDeclaration)?.let { fd ->
                fd.body?.let { b ->
                    val ps = fd.parameters.mapNotNull { (it.name as? Identifier)?.text }.toSet()
                    tcvProcessScope(b.statements, source, fileName, ps)
                }
            }
        }
        for ((idx, s) in stmts.withIndex()) {
            val ts = s as? TryStatement ?: continue
            val catchBlock = ts.catchClause?.block ?: continue
            if (tcvHasTerminator(catchBlock.statements)) continue
            // Candidates: try-block DIRECT `var` decls WITH initializers whose
            // inferred type is concrete and excludes undefined.
            val candidates = mutableSetOf<String>()
            for (st in ts.tryBlock.statements) {
                val vs = st as? VariableStatement ?: continue
                if (vs.declarationList.flags != SyntaxKind.VarKeyword) continue
                for (d in vs.declarationList.declarations) {
                    val init = d.initializer ?: continue
                    val initType: Type? = getTypeOfExpression(init)
                    fun concreteNonUndef(t: Type?): Boolean = t != null && t !== errorType &&
                        t !== anyType && !t.flags.hasAny(TypeFlags.Unknown) && !typeIncludesUndefined(t)
                    fun defaultOk(e: Expression): Boolean =
                        concreteNonUndef(literalTypeOfExpression(e)
                            ?: getTypeOfExpression(e))
                    when (val n = d.name) {
                        is Identifier -> if (concreteNonUndef(initType)) candidates.add(n.text)
                        is ArrayBindingPattern -> n.elements.forEachIndexed { i, el ->
                            val be = el as? BindingElement ?: return@forEachIndexed
                            if (be.dotDotDotToken) return@forEachIndexed
                            val bn = (be.name as? Identifier)?.text ?: return@forEachIndexed
                            val beInit = be.initializer
                            if (beInit != null) {
                                if (defaultOk(beInit)) candidates.add(bn)
                            } else {
                                val elems = (initType as? Type.Object)?.tupleElementTypes
                                if (elems != null && i < elems.size && concreteNonUndef(elems[i])) candidates.add(bn)
                            }
                        }
                        is ObjectBindingPattern -> for (el in n.elements) {
                            val be = el
                            if (be.dotDotDotToken || be.propertyName != null) continue
                            val bn = (be.name as? Identifier)?.text ?: continue
                            val beInit = be.initializer
                            if (beInit != null) {
                                if (defaultOk(beInit)) candidates.add(bn)
                            } else if (initType != null) {
                                val prop = getPropertyOfType(initType, bn)
                                if (prop != null && !isOptionalProperty(prop)) {
                                    val pt = getTypeOfSymbol(prop)
                                    if (concreteNonUndef(pt)) candidates.add(bn)
                                }
                            }
                        }
                        else -> {}
                    }
                }
            }
            if (candidates.isEmpty()) continue
            candidates.removeAll(paramNames)
            // "Try is the ONLY assignment" gate: any assignment OR other declaration
            // of the name anywhere else in the scope (incl. catch/finally) drops it.
            val found = mutableSetOf<String>()
            for ((j, other) in stmts.withIndex()) {
                if (j == idx) continue
                collectAllAssignmentsAnywhere(other, candidates, found)
                tcvCollectDeclared(other, candidates, found)
            }
            for (st in catchBlock.statements) {
                collectAllAssignmentsAnywhere(st, candidates, found)
                tcvCollectDeclared(st, candidates, found)
            }
            ts.finallyBlock?.statements?.forEach { st ->
                collectAllAssignmentsAnywhere(st, candidates, found)
                tcvCollectDeclared(st, candidates, found)
            }
            candidates.removeAll(found)
            if (candidates.isEmpty()) continue
            // Straight-line read scan after the try.
            tcvScanReads(stmts, idx + 1, candidates, source, fileName)
        }
    }

    /** B223: does the statement list contain a return/throw/break/continue anywhere
     *  (not descending into nested function-likes)? */
    private fun tcvHasTerminator(stmts: List<Statement>): Boolean = stmts.any { tcvStmtTerminates(it) }

    private fun tcvStmtTerminates(stmt: Statement): Boolean = when (stmt) {
        is ReturnStatement, is ThrowStatement, is BreakStatement, is ContinueStatement -> true
        is Block -> tcvHasTerminator(stmt.statements)
        is IfStatement -> tcvStmtTerminates(stmt.thenStatement) ||
            (stmt.elseStatement?.let { tcvStmtTerminates(it) } == true)
        is WhileStatement -> tcvStmtTerminates(stmt.statement)
        is DoStatement -> tcvStmtTerminates(stmt.statement)
        is ForStatement -> tcvStmtTerminates(stmt.statement)
        is ForInStatement -> tcvStmtTerminates(stmt.statement)
        is ForOfStatement -> tcvStmtTerminates(stmt.statement)
        is SwitchStatement -> stmt.caseBlock.any { c ->
            when (c) {
                is CaseClause -> tcvHasTerminator(c.statements)
                is DefaultClause -> tcvHasTerminator(c.statements)
                else -> false
            }
        }
        is TryStatement -> tcvHasTerminator(stmt.tryBlock.statements) ||
            (stmt.catchClause?.block?.statements?.let { tcvHasTerminator(it) } == true) ||
            (stmt.finallyBlock?.statements?.let { tcvHasTerminator(it) } == true)
        is LabeledStatement -> tcvStmtTerminates(stmt.statement)
        else -> false
    }

    /** B223: other DECLARATIONS of a candidate name (any kind, any pattern). */
    private fun tcvCollectDeclared(stmt: Statement, candidates: Set<String>, found: MutableSet<String>) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                fun collectNames(n: Node?) {
                    when (n) {
                        is Identifier -> if (n.text in candidates && d.initializer != null) found.add(n.text)
                        is ArrayBindingPattern -> n.elements.forEach { (it as? BindingElement)?.name?.let(::collectNames) }
                        is ObjectBindingPattern -> n.elements.forEach { (it).name.let(::collectNames) }
                        else -> {}
                    }
                }
                collectNames(d.name)
            }
            is Block -> stmt.statements.forEach { tcvCollectDeclared(it, candidates, found) }
            is IfStatement -> {
                tcvCollectDeclared(stmt.thenStatement, candidates, found)
                stmt.elseStatement?.let { tcvCollectDeclared(it, candidates, found) }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { tcvCollectDeclared(it, candidates, found) }
                stmt.catchClause?.block?.statements?.forEach { tcvCollectDeclared(it, candidates, found) }
                stmt.finallyBlock?.statements?.forEach { tcvCollectDeclared(it, candidates, found) }
            }
            else -> {}
        }
    }

    /** B223: straight-line forward read scan — first bare-Identifier read per
     *  candidate emits TS2454; stops entirely at the first control-flow statement. */
    private fun tcvScanReads(
        stmts: List<Statement>, from: Int, candidates: MutableSet<String>,
        source: String, fileName: String,
    ) {
        fun emitAt(id: Identifier) {
            val (line, ch) = getLineAndCharacterOfPosition(source, id.pos)
            diagnostics.add(Diagnostic(
                message = "Variable '${id.text}' is used before being assigned.",
                category = DiagnosticCategory.Error, code = 2454,
                fileName = fileName, line = line, character = ch,
                start = id.pos, length = id.text.length,
            ))
            candidates.remove(id.text)
        }
        fun walk(e: Expression) {
            if (candidates.isEmpty()) return
            when (e) {
                is Identifier -> if (e.text in candidates) emitAt(e)
                is TypeOfExpression -> {} // tsc-exempt
                is BinaryExpression -> {
                    if (e.operator == SyntaxKind.Equals && e.left is Identifier) walk(e.right)
                    else { walk(e.left); walk(e.right) }
                }
                is CallExpression -> { walk(e.expression); e.arguments.forEach { walk(it) } }
                is NewExpression -> { walk(e.expression); e.arguments?.forEach { walk(it) } }
                is PropertyAccessExpression -> walk(e.expression)
                is ElementAccessExpression -> { walk(e.expression); walk(e.argumentExpression) }
                is ParenthesizedExpression -> walk(e.expression)
                is PrefixUnaryExpression -> walk(e.operand)
                is PostfixUnaryExpression -> walk(e.operand)
                is ArrayLiteralExpression -> e.elements.forEach { walk(it) }
                is SpreadElement -> walk(e.expression)
                is ObjectLiteralExpression -> e.properties.forEach { p ->
                    (p as? PropertyAssignment)?.initializer?.let { walk(it) }
                }
                is TemplateExpression -> e.templateSpans.forEach { walk(it.expression) }
                is AsExpression -> walk(e.expression)
                is ConditionalExpression -> { walk(e.condition); walk(e.whenTrue); walk(e.whenFalse) }
                else -> {}
            }
        }
        for (i in from until stmts.size) {
            if (candidates.isEmpty()) return
            when (val st = stmts[i]) {
                is ExpressionStatement -> walk(st.expression)
                is ReturnStatement -> st.expression?.let { walk(it) }
                is ThrowStatement -> st.expression?.let { walk(it) }
                is VariableStatement -> for (d in st.declarationList.declarations) {
                    d.initializer?.let { walk(it) }
                }
                else -> return // control flow may narrow/assign — stop
            }
        }
    }

    /**
     * (M0.4, round 629): the flow-graph definite-assignment pass (TS2454 +
     * the B187 nullable-union loop-arg TS2345) runs as a FILE-END dispatch in
     * [checkSpine]'s per-file loop — after [spineWalkFile] returns, so its
     * positional TS2454 dedup scan sees every spine-emitted TS2454 for the
     * file (the set-based walker 5 + the spineUbd co-emissions, which both
     * fire during the file's own walk; no pass between the spine and the old
     * slot emitted TS2454 — verified round 628/629). The walkers
     * ([walkTopForFlowTS2454] / [runFlowTS2454OnTopLevel] and their leaves)
     * are unchanged; the family's only checker ambient is [currentFlowGraph],
     * installed save/restore here (everything else travels as explicit
     * parameters — fileLocals, source, the emitted-positions set). The B223
     * sibling [checkTryCatchOnlyAssignedVarReads] stays at its own pass slot:
     * it scans no prior diagnostics, so there is no dedup coupling in either
     * direction, and the legacy flow-pass-first relative order is preserved
     * (the file-end dispatch runs strictly earlier). A trip during the walks
     * registers [flowDisabledRanges] per-file as before; the end-of-init
     * TS2454 range filter runs after either slot.
     */
    private fun spineDaFlowFileEnd(result: BinderResult) {
        if (options.strictExplicitlyFalse || options.strictNullChecksExplicitlyFalse) return
        val fileName = result.sourceFile.fileName
        if (isDtsFile(fileName)) return
        val source = result.sourceFile.text
        val savedFlowGraph = currentFlowGraph
        currentFlowGraph = result.flowGraph
        try {
            val emittedTs2454Positions = mutableSetOf<Int>()
            for (d in diagnostics) {
                if (d.code == 2454 && d.fileName == fileName) {
                    d.start?.let { emittedTs2454Positions.add(it) }
                }
            }
            for (stmt in result.sourceFile.statements) {
                walkTopForFlowTS2454(stmt, source, fileName, emittedTs2454Positions, result.locals)
            }
            // 17.46d: also walk top-level statements as a unit so file-level
            // uninitialized vars (`var x: T;` outside any function) are
            // checked for unsafe reads inside if/while/for/switch/try
            // bodies. Mirrors `runFlowTS2454OnFunction` without parameters.
            runFlowTS2454OnTopLevel(result.sourceFile.statements, source, fileName, emittedTs2454Positions, result.locals)
        } finally {
            currentFlowGraph = savedFlowGraph
        }
    }

    /**
     * B417: FLOW-AWARE TS2367 for a discriminant comparison `recv.prop === literal`
     * (or `!==`/`==`/`!=`, symmetric) inside an `if`/`else if` condition where flow
     * narrowing has reduced `recv` so that `recv.prop` can no longer be the compared
     * literal. e.g. after `switch (true) { case shape.kind === "circle": return … }`
     * the scrutinee is `{square}` past the switch, so `if (shape.kind === "circle")`
     * compares `"square"` with `"circle"` → no overlap. Hooked into BOTH if-statement
     * dispatchers (which carry the param/flow context). FP firewall: fires only when
     * the DECLARED prop overlapped the literal but the NARROWED one does not (a genuine
     * flow-induced no-overlap — statically-impossible comparisons are owned by the other
     * TS2367 sites), and only when the narrowed prop is an all-literal set.
     */
    private fun checkFlowNoOverlapCondition(cond: Expression, source: String, fileName: String) {
        var e: Expression = cond
        while (e is ParenthesizedExpression) e = e.expression
        if (e !is BinaryExpression) return
        when (e.operator) {
            SyntaxKind.AmpersandAmpersand, SyntaxKind.BarBar -> {
                checkFlowNoOverlapCondition(e.left, source, fileName)
                checkFlowNoOverlapCondition(e.right, source, fileName)
            }
            SyntaxKind.EqualsEqualsEquals, SyntaxKind.ExclamationEqualsEquals,
            SyntaxKind.EqualsEquals, SyntaxKind.ExclamationEquals -> emitFlowNoOverlap(e, source, fileName)
            else -> {}
        }
    }

    /** Set of a property's literal types across a (possibly-union) type, or null when
     *  any member lacks the property / the property type isn't a discriminant literal. */
    private fun propTypeLiteralSet(type: Type, propName: String): List<Type>? {
        val members = if (type is Type.Union) type.types else listOf(type)
        val lits = mutableListOf<Type>()
        for (m in members) {
            val ap = getApparentType(m)
            if (ap !is Type.Object) return null
            val ps = getPropertyOfType(ap, propName) ?: return null
            val pt = getTypeOfSymbol(ps)
            if (!isLiteralKindForDiscriminant(pt)) return null
            lits.add(pt)
        }
        return lits
    }

    private fun emitFlowNoOverlap(expr: BinaryExpression, source: String, fileName: String) {
        val (propAccess, literalExpr) = when {
            expr.left is PropertyAccessExpression && literalTypeOfExpression(expr.right) != null ->
                (expr.left) to expr.right
            expr.right is PropertyAccessExpression && literalTypeOfExpression(expr.left) != null ->
                (expr.right) to expr.left
            else -> return
        }
        val recv = propAccess.expression
        val propName = (propAccess.name).text
        val literalType = literalTypeOfExpression(literalExpr) ?: return
        if (!isLiteralKindForDiscriminant(literalType)) return
        getReferencePath(recv) ?: return
        val declared = getTypeOfExpression(recv)
        if (declared === anyType || declared === errorType) return
        val narrowed = getNarrowedTypeForReference(declared, recv)
        if (narrowed === declared) return
        val declaredProp = propTypeLiteralSet(declared, propName) ?: return
        val narrowedProp = propTypeLiteralSet(narrowed, propName) ?: return
        if (narrowedProp.isEmpty()) return
        // FP firewall: only flow-INDUCED no-overlap (declared overlapped, narrowed doesn't).
        if (declaredProp.none { literalsEqualForDiscriminant(it, literalType) }) return
        if (narrowedProp.any { literalsEqualForDiscriminant(it, literalType) }) return
        val narrowedDisplay = narrowedProp.joinToString(" | ") { typeToString(it) }
        val literalDisplay = typeToString(literalType)
        val start = expr.pos
        val length = expressionTrueEnd(expr) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This comparison appears to be unintentional because the types '$narrowedDisplay' and '$literalDisplay' have no overlap.",
            category = DiagnosticCategory.Error, code = 2367,
            fileName = fileName, line = line, character = character, start = start, length = length,
        ))
    }

    private fun runFlowTS2454OnTopLevel(
        statements: List<Statement>, source: String, fileName: String,
        emitted: MutableSet<Int>, fileLocals: SymbolTable?,
    ) {
        val uninitialized = mutableSetOf<String>()
        collectAllUninitVarsInFunction(statements, uninitialized, emptySet(), fileLocals)
        if (uninitialized.isEmpty()) return
        for (s in statements) {
            walkStmtForFlowTS2454(s, uninitialized, source, fileName, emitted, inUncheckedBody = false)
        }
    }

    private fun walkTopForFlowTS2454(
        stmt: Statement, source: String, fileName: String,
        emitted: MutableSet<Int>, fileLocals: SymbolTable?,
    ) {
        when (stmt) {
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                stmt.body?.let { runFlowTS2454OnFunction(it, stmt.parameters, source, fileName, emitted, fileLocals) }
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { runFlowTS2454OnFunction(it, m.parameters, source, fileName, emitted, fileLocals) }
                        is Constructor -> m.body?.let { runFlowTS2454OnFunction(it, m.parameters, source, fileName, emitted, fileLocals) }
                        is GetAccessor -> m.body?.let { runFlowTS2454OnFunction(it, m.parameters, source, fileName, emitted, fileLocals) }
                        is SetAccessor -> m.body?.let { runFlowTS2454OnFunction(it, m.parameters, source, fileName, emitted, fileLocals) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                when (val body = stmt.body) {
                    is ModuleBlock -> body.statements.forEach {
                        walkTopForFlowTS2454(it, source, fileName, emitted, fileLocals)
                    }
                    is ModuleDeclaration -> walkTopForFlowTS2454(body, source, fileName, emitted, fileLocals)
                    else -> {}
                }
            }
            else -> {}
        }
    }

    /**
     * Round 469: collect names from [candidates] assigned INSIDE a nested
     * function-like of [stmt] — a statement-level FunctionDeclaration body (also
     * under blocks/ifs) or an arrow/fn-expr variable initializer's block body. The
     * bodies are walked with the B78.2 [collectAllAssignmentsAnywhere] (which itself
     * descends into deeper nesting). Used to REMOVE definite-assignment candidates:
     * a closure assignment can run at any time relative to an outer read, so tsc's
     * analysis never fires TS2454 for such a name.
     */
    private fun collectClosureAssignedNames(
        stmt: Statement, candidates: Set<String>, found: MutableSet<String>,
    ) {
        when (stmt) {
            is FunctionDeclaration -> stmt.body?.statements?.forEach {
                collectAllAssignmentsAnywhere(it, candidates, found)
            }
            is Block -> stmt.statements.forEach { collectClosureAssignedNames(it, candidates, found) }
            is IfStatement -> {
                collectClosureAssignedNames(stmt.thenStatement, candidates, found)
                stmt.elseStatement?.let { collectClosureAssignedNames(it, candidates, found) }
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                val init = d.initializer
                val b = (init as? ArrowFunction)?.body as? Block
                    ?: (init as? FunctionExpression)?.body
                b?.statements?.forEach { collectAllAssignmentsAnywhere(it, candidates, found) }
            }
            else -> {}
        }
    }

    private fun runFlowTS2454OnFunction(
        body: Block, parameters: List<Parameter>, source: String, fileName: String,
        emitted: MutableSet<Int>, fileLocals: SymbolTable?,
    ) {
        val preInit = collectParamNames(parameters)
        val uninitialized = mutableSetOf<String>()
        collectAllUninitVarsInFunction(body.statements, uninitialized, preInit, fileLocals)
        // Round 469: a name assigned inside a NESTED function-like can be assigned at
        // any time relative to an outer read (the closure may run first) — tsc's
        // definite-assignment analysis never fires for it (tsc formatting.ts
        // formatSpanWorker's `previousRange`, assigned only inside the nested
        // processRange/processPair helpers, read in the trailing-edit block).
        // Removal-only (straight-line used-before-assigned reads with no closure
        // assignment keep firing).
        if (uninitialized.isNotEmpty()) {
            val closureAssigned = mutableSetOf<String>()
            for (s in body.statements) collectClosureAssignedNames(s, uninitialized, closureAssigned)
            uninitialized.removeAll(closureAssigned)
        }
        if (uninitialized.isNotEmpty()) {
            for (s in body.statements) {
                walkStmtForFlowTS2454(s, uninitialized, source, fileName, emitted, inUncheckedBody = false)
            }
        }
        // Recurse into nested function-likes (their own scope, fresh uninit set)
        for (s in body.statements) {
            walkTopForFlowTS2454(s, source, fileName, emitted, fileLocals)
            walkExprForNestedFunctionLikes(s, source, fileName, emitted, fileLocals)
        }
        // B187: TS2345 for a possibly-unassigned nullable-union local read as a loop arg.
        checkNullableUnionLoopArgs(body, source, fileName, fileLocals)
    }

    /**
     * B187: TS2345 "Argument of type 'P | undefined' is not assignable to parameter of
     * type 'P'." for a NO-initializer local `let x: P | undefined` (P a primitive keyword)
     * read as a bare-identifier argument INSIDE A LOOP against a single-declaration
     * FunctionDeclaration whose matching parameter is a non-optional `P`. Consumes the
     * existing loop-aware definite-assignment engine [isAssignedAtFlow] (built for TS2454):
     * the read fires only when NO pre-loop-entry path assigns x; an assignment preceding
     * the loop suppresses (test2 of `controlFlowLoopAnalysis` vs test1).
     *
     * FP firewall (load-bearing): a blanket reference-shape pre-scan requires EVERY
     * reference to x in the function body to be either a plain assignment LHS `x = …` or a
     * gated bare-identifier argument — ANY other reference (condition position, cast, `x!`,
     * property access, nested function-like, unresolvable/overloaded/predicate-returning
     * callee, param mismatch, …) disqualifies the variable. This syntactically excludes
     * every construct tsc could narrow through, so at a flagged read tsc's flow type
     * provably still contains `undefined` → tsc always errors the shape (passing-set
     * argument). Display gates: the union must be exactly {P, undefined} and ≥1 assignment
     * must exist (so tsc's loop-union display is the full declared union, not bare
     * 'undefined').
     */
    private fun checkNullableUnionLoopArgs(
        body: Block, source: String, fileName: String, fileLocals: SymbolTable?,
    ) {
        if (isJsLikeFileName(fileName)) return
        // Candidates: direct statements only (the narrow target shape).
        val candidates = mutableMapOf<String, Pair<VariableDeclaration, SyntaxKind>>()
        for (stmt in body.statements) {
            if (stmt !is VariableStatement) continue
            if (ModifierFlag.Declare in stmt.modifiers) continue
            for (decl in stmt.declarationList.declarations) {
                val nm = (decl.name as? Identifier)?.text ?: continue
                if (decl.initializer != null || decl.exclamationToken) continue
                val union = decl.type as? UnionType ?: continue
                if (union.types.size != 2) continue
                val kinds = union.types.map { it.kind }
                if (SyntaxKind.UndefinedKeyword !in kinds) continue
                val primKind = kinds.firstOrNull {
                    it == SyntaxKind.NumberKeyword || it == SyntaxKind.StringKeyword || it == SyntaxKind.BooleanKeyword
                } ?: continue
                candidates[nm] = decl to primKind
            }
        }
        if (candidates.isEmpty()) return
        for ((name, info) in candidates) {
            val (decl, primKind) = info
            val scan = NullableUnionRefScan(name, primKind, fileLocals)
            for (s in body.statements) scanNullableUnionRefsStmt(s, scan)
            if (scan.disqualified || scan.assignmentCount == 0 || scan.gatedLoopArgs.isEmpty()) continue
            val primText = when (primKind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                else -> "boolean"
            }
            val unionDisplay = formatTypeForDisplay(decl.type!!) ?: "$primText | undefined"
            for (arg in scan.gatedLoopArgs) {
                if (flowWalkWithTripCheck(arg, WK_ASSIGNED_ARG, name.hashCode().toLong(), flowPathRoot(name)) {
                        isAssignedAtFlow(getFlowAt(arg), name, mutableSetOf())
                    } != false) continue
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$unionDisplay' is not assignable to parameter of type '$primText'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = arg.pos,
                    length = name.length,
                    messageChain = listOf("  Type 'undefined' is not assignable to type '$primText'."),
                ))
            }
        }
    }

    /** B187 scan state for one candidate variable. */
    private class NullableUnionRefScan(
        val name: String,
        val primKind: SyntaxKind,
        val fileLocals: SymbolTable?,
    ) {
        var disqualified = false
        var assignmentCount = 0
        var inLoop = 0
        /** Bare-identifier args (in loops) that passed the callee gate. */
        val gatedLoopArgs = mutableListOf<Identifier>()
    }

    private fun scanNullableUnionRefsStmt(stmt: Statement, scan: NullableUnionRefScan) {
        if (scan.disqualified) return
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { scanNullableUnionRefsExpr(it, scan) }
            }
            is ExpressionStatement -> scanNullableUnionRefsExpr(stmt.expression, scan)
            is Block -> stmt.statements.forEach { scanNullableUnionRefsStmt(it, scan) }
            is IfStatement -> {
                scanNullableUnionRefsExpr(stmt.expression, scan)
                scanNullableUnionRefsStmt(stmt.thenStatement, scan)
                stmt.elseStatement?.let { scanNullableUnionRefsStmt(it, scan) }
            }
            is WhileStatement -> {
                scanNullableUnionRefsExpr(stmt.expression, scan)
                scan.inLoop++
                scanNullableUnionRefsStmt(stmt.statement, scan)
                scan.inLoop--
            }
            is DoStatement -> {
                scanNullableUnionRefsExpr(stmt.expression, scan)
                scan.inLoop++
                scanNullableUnionRefsStmt(stmt.statement, scan)
                scan.inLoop--
            }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                    d.initializer?.let { scanNullableUnionRefsExpr(it, scan) }
                }
                (stmt.initializer as? Expression)?.let { scanNullableUnionRefsExpr(it, scan) }
                stmt.condition?.let { scanNullableUnionRefsExpr(it, scan) }
                stmt.incrementor?.let { scanNullableUnionRefsExpr(it, scan) }
                scan.inLoop++
                scanNullableUnionRefsStmt(stmt.statement, scan)
                scan.inLoop--
            }
            is ForInStatement, is ForOfStatement -> {
                // for-in/of over the candidate (or any use in heads) disqualifies via expr scan
                val head = when (stmt) {
                    is ForInStatement -> stmt.expression
                    is ForOfStatement -> stmt.expression
                }
                head.let { scanNullableUnionRefsExpr(it, scan) }
                val inner = when (stmt) {
                    is ForInStatement -> stmt.statement
                    is ForOfStatement -> stmt.statement
                }
                scan.inLoop++
                inner.let { scanNullableUnionRefsStmt(it, scan) }
                scan.inLoop--
            }
            is ReturnStatement -> stmt.expression?.let { scanNullableUnionRefsExpr(it, scan) }
            is SwitchStatement -> {
                scanNullableUnionRefsExpr(stmt.expression, scan)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            scanNullableUnionRefsExpr(clause.expression, scan)
                            clause.statements.forEach { scanNullableUnionRefsStmt(it, scan) }
                        }
                        is DefaultClause -> clause.statements.forEach { scanNullableUnionRefsStmt(it, scan) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { scanNullableUnionRefsStmt(it, scan) }
                stmt.catchClause?.block?.statements?.forEach { scanNullableUnionRefsStmt(it, scan) }
                stmt.finallyBlock?.statements?.forEach { scanNullableUnionRefsStmt(it, scan) }
            }
            is LabeledStatement -> scanNullableUnionRefsStmt(stmt.statement, scan)
            is ThrowStatement -> stmt.expression?.let { scanNullableUnionRefsExpr(it, scan) }
            is FunctionDeclaration -> {
                // Any reference inside a nested function-like disqualifies (closure capture).
                if (stmt.body?.let { stmtListContainsName(it.statements, scan.name) } == true) scan.disqualified = true
            }
            is ClassDeclaration -> if (classContainsName(stmt, scan.name)) scan.disqualified = true
            else -> {}
        }
    }

    private fun scanNullableUnionRefsExpr(exprIn: Expression, scan: NullableUnionRefScan) {
        if (scan.disqualified) return
        // Iterative left-spine for deep binary chains (StackOverflow gotcha).
        var expr = exprIn
        while (true) {
            when (val e = expr) {
                is BinaryExpression -> {
                    if (e.operator == SyntaxKind.Equals && (e.left as? Identifier)?.text == scan.name) {
                        scan.assignmentCount++
                    } else {
                        scanNullableUnionRefsOperand(e.left, scan)
                    }
                    expr = e.right
                    continue
                }
                else -> {
                    scanNullableUnionRefsOperand(e, scan)
                    return
                }
            }
        }
    }

    private fun scanNullableUnionRefsOperand(e: Expression, scan: NullableUnionRefScan) {
        if (scan.disqualified) return
        when (e) {
            is Identifier -> if (e.text == scan.name) scan.disqualified = true
            is CallExpression -> {
                val callee = e.expression
                if (callee is Identifier) {
                    if (callee.text == scan.name) { scan.disqualified = true; return }
                } else {
                    scanNullableUnionRefsExpr(callee, scan)
                }
                e.arguments.forEachIndexed { i, arg ->
                    if (arg is Identifier && arg.text == scan.name) {
                        val calleeIdent = callee as? Identifier
                        if (calleeIdent != null && scan.inLoop > 0 &&
                            nullableUnionCalleeGateOk(calleeIdent, i, scan)) {
                            scan.gatedLoopArgs.add(arg)
                        } else {
                            scan.disqualified = true
                        }
                    } else {
                        scanNullableUnionRefsExpr(arg, scan)
                    }
                }
            }
            is ParenthesizedExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is PrefixUnaryExpression -> scanNullableUnionRefsExpr(e.operand, scan)
            is PostfixUnaryExpression -> scanNullableUnionRefsExpr(e.operand, scan)
            is PropertyAccessExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is ElementAccessExpression -> {
                scanNullableUnionRefsExpr(e.expression, scan)
                scanNullableUnionRefsExpr(e.argumentExpression, scan)
            }
            is ConditionalExpression -> {
                scanNullableUnionRefsExpr(e.condition, scan)
                scanNullableUnionRefsExpr(e.whenTrue, scan)
                scanNullableUnionRefsExpr(e.whenFalse, scan)
            }
            is ArrayLiteralExpression -> e.elements.forEach { scanNullableUnionRefsExpr(it, scan) }
            is ObjectLiteralExpression -> e.properties.forEach { p ->
                when (p) {
                    is PropertyAssignment -> scanNullableUnionRefsExpr(p.initializer, scan)
                    is ShorthandPropertyAssignment -> if (p.name.text == scan.name) scan.disqualified = true
                    is SpreadAssignment -> scanNullableUnionRefsExpr(p.expression, scan)
                    else -> {}
                }
            }
            is SpreadElement -> scanNullableUnionRefsExpr(e.expression, scan)
            is AsExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is TypeAssertionExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is NonNullExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is SatisfiesExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is NewExpression -> {
                scanNullableUnionRefsExpr(e.expression, scan)
                e.arguments?.forEach { scanNullableUnionRefsExpr(it, scan) }
            }
            is TemplateExpression -> e.templateSpans.forEach { scanNullableUnionRefsExpr(it.expression, scan) }
            is AwaitExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is TypeOfExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is VoidExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is DeleteExpression -> scanNullableUnionRefsExpr(e.expression, scan)
            is YieldExpression -> e.expression?.let { scanNullableUnionRefsExpr(it, scan) }
            is ArrowFunction, is FunctionExpression, is ClassExpression -> {
                if (exprContainsName(e, scan.name)) scan.disqualified = true
            }
            else -> {}
        }
    }

    /** B187 callee gate: bare-Identifier callee resolving (via file locals, then globals)
     *  to a symbol with EXACTLY ONE FunctionDeclaration whose parameters[argIndex] is a
     *  non-optional, non-rest, no-default parameter of the candidate's primitive keyword
     *  type, and whose return annotation is NOT a type predicate. */
    private fun nullableUnionCalleeGateOk(callee: Identifier, argIndex: Int, scan: NullableUnionRefScan): Boolean {
        val sym = scan.fileLocals?.get(callee.text) ?: globals[callee.text] ?: return false
        if (sym.declarations.size != 1) return false
        val fn = sym.declarations.first() as? FunctionDeclaration ?: return false
        if (fn.type is TypePredicate) return false
        val param = fn.parameters.getOrNull(argIndex) ?: return false
        if (param.questionToken || param.initializer != null || param.dotDotDotToken) return false
        val pt = param.type ?: return false
        return pt.kind == scan.primKind
    }

    /** B187: deep "does this subtree reference [name]" scans for disqualification. */
    private fun exprContainsName(e: Expression, name: String): Boolean {
        var found = false
        fun visitExpr(x: Expression) {
            if (found) return
            var cur = x
            while (true) {
                when (val c = cur) {
                    is BinaryExpression -> { visitExpr(c.left); cur = c.right; continue }
                    is Identifier -> { if (c.text == name) found = true; return }
                    is CallExpression -> { visitExpr(c.expression); c.arguments.forEach { visitExpr(it) }; return }
                    is NewExpression -> { visitExpr(c.expression); c.arguments?.forEach { visitExpr(it) }; return }
                    is ParenthesizedExpression -> { cur = c.expression; continue }
                    is PropertyAccessExpression -> { cur = c.expression; continue }
                    is ElementAccessExpression -> { visitExpr(c.expression); cur = c.argumentExpression; continue }
                    is PrefixUnaryExpression -> { cur = c.operand; continue }
                    is PostfixUnaryExpression -> { cur = c.operand; continue }
                    is ConditionalExpression -> { visitExpr(c.condition); visitExpr(c.whenTrue); cur = c.whenFalse; continue }
                    is ArrayLiteralExpression -> { c.elements.forEach { visitExpr(it) }; return }
                    is ObjectLiteralExpression -> {
                        for (p in c.properties) when (p) {
                            is PropertyAssignment -> visitExpr(p.initializer)
                            is ShorthandPropertyAssignment -> if (p.name.text == name) found = true
                            is SpreadAssignment -> visitExpr(p.expression)
                            else -> {}
                        }
                        return
                    }
                    is SpreadElement -> { cur = c.expression; continue }
                    is AsExpression -> { cur = c.expression; continue }
                    is TypeAssertionExpression -> { cur = c.expression; continue }
                    is NonNullExpression -> { cur = c.expression; continue }
                    is SatisfiesExpression -> { cur = c.expression; continue }
                    is AwaitExpression -> { cur = c.expression; continue }
                    is TypeOfExpression -> { cur = c.expression; continue }
                    is VoidExpression -> { cur = c.expression; continue }
                    is DeleteExpression -> { cur = c.expression; continue }
                    is TemplateExpression -> { c.templateSpans.forEach { visitExpr(it.expression) }; return }
                    is YieldExpression -> { c.expression?.let { visitExpr(it) }; return }
                    is ArrowFunction -> {
                        when (val b = c.body) {
                            is Block -> { if (stmtListContainsName(b.statements, name)) found = true }
                            is Expression -> visitExpr(b)
                            else -> {}
                        }
                        return
                    }
                    is FunctionExpression -> { if (stmtListContainsName(c.body.statements, name)) found = true; return }
                    is ClassExpression -> { if (classMembersContainName(c.members, name)) found = true; return }
                    else -> return
                }
            }
        }
        visitExpr(e)
        return found
    }

    private fun stmtListContainsName(stmts: List<Statement>, name: String): Boolean {
        for (s in stmts) if (stmtContainsName(s, name)) return true
        return false
    }

    private fun stmtContainsName(stmt: Statement, name: String): Boolean {
        return when (stmt) {
            is ExpressionStatement -> exprContainsName(stmt.expression, name)
            is VariableStatement -> stmt.declarationList.declarations.any {
                it.initializer?.let { i -> exprContainsName(i, name) } == true
            }
            is Block -> stmtListContainsName(stmt.statements, name)
            is IfStatement -> exprContainsName(stmt.expression, name) ||
                stmtContainsName(stmt.thenStatement, name) ||
                (stmt.elseStatement?.let { stmtContainsName(it, name) } == true)
            is WhileStatement -> exprContainsName(stmt.expression, name) || stmtContainsName(stmt.statement, name)
            is DoStatement -> exprContainsName(stmt.expression, name) || stmtContainsName(stmt.statement, name)
            is ForStatement -> ((stmt.initializer as? Expression)?.let { exprContainsName(it, name) } == true) ||
                ((stmt.initializer as? VariableDeclarationList)?.declarations?.any { it.initializer?.let { i -> exprContainsName(i, name) } == true } == true) ||
                (stmt.condition?.let { exprContainsName(it, name) } == true) ||
                (stmt.incrementor?.let { exprContainsName(it, name) } == true) ||
                stmtContainsName(stmt.statement, name)
            is ForInStatement -> exprContainsName(stmt.expression, name) || stmtContainsName(stmt.statement, name)
            is ForOfStatement -> exprContainsName(stmt.expression, name) || stmtContainsName(stmt.statement, name)
            is ReturnStatement -> stmt.expression?.let { exprContainsName(it, name) } == true
            is ThrowStatement -> stmt.expression?.let { exprContainsName(it, name) } == true
            is SwitchStatement -> exprContainsName(stmt.expression, name) || stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> exprContainsName(clause.expression, name) || stmtListContainsName(clause.statements, name)
                    is DefaultClause -> stmtListContainsName(clause.statements, name)
                    else -> false
                }
            }
            is TryStatement -> stmtListContainsName(stmt.tryBlock.statements, name) ||
                (stmt.catchClause?.block?.statements?.let { stmtListContainsName(it, name) } == true) ||
                (stmt.finallyBlock?.statements?.let { stmtListContainsName(it, name) } == true)
            is LabeledStatement -> stmtContainsName(stmt.statement, name)
            is FunctionDeclaration -> stmt.body?.let { stmtListContainsName(it.statements, name) } == true
            is ClassDeclaration -> classContainsName(stmt, name)
            else -> false
        }
    }

    private fun classContainsName(cls: ClassDeclaration, name: String): Boolean = classMembersContainName(cls.members, name)

    private fun classMembersContainName(members: List<ClassElement>, name: String): Boolean {
        for (m in members) {
            val body = when (m) {
                is MethodDeclaration -> m.body
                is Constructor -> m.body
                is GetAccessor -> m.body
                is SetAccessor -> m.body
                is PropertyDeclaration -> { if (m.initializer?.let { exprContainsName(it, name) } == true) return true; null }
                else -> null
            }
            if (body != null && stmtListContainsName(body.statements, name)) return true
        }
        return false
    }

    private fun collectAllUninitVarsInFunction(
        stmts: List<Statement>, uninitialized: MutableSet<String>,
        preInit: Set<String>, fileLocals: SymbolTable?,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    for (decl in stmt.declarationList.declarations) {
                        addIfUninitForFlow(decl, uninitialized, preInit, fileLocals)
                    }
                }
                is Block -> collectAllUninitVarsInFunction(stmt.statements, uninitialized, preInit, fileLocals)
                is IfStatement -> {
                    collectAllUninitVarsInFunction(listOf(stmt.thenStatement), uninitialized, preInit, fileLocals)
                    stmt.elseStatement?.let { collectAllUninitVarsInFunction(listOf(it), uninitialized, preInit, fileLocals) }
                }
                is ForStatement -> {
                    (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach {
                        addIfUninitForFlow(it, uninitialized, preInit, fileLocals)
                    }
                    collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                }
                is ForInStatement -> {
                    (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach {
                        addIfUninitForFlow(it, uninitialized, preInit, fileLocals)
                    }
                    collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                }
                is ForOfStatement -> {
                    (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach {
                        addIfUninitForFlow(it, uninitialized, preInit, fileLocals)
                    }
                    collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                }
                is WhileStatement -> collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                is DoStatement -> collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        val cs = when (clause) {
                            is CaseClause -> clause.statements
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        collectAllUninitVarsInFunction(cs, uninitialized, preInit, fileLocals)
                    }
                }
                is TryStatement -> {
                    collectAllUninitVarsInFunction(stmt.tryBlock.statements, uninitialized, preInit, fileLocals)
                    stmt.catchClause?.block?.statements?.let { collectAllUninitVarsInFunction(it, uninitialized, preInit, fileLocals) }
                    stmt.finallyBlock?.statements?.let { collectAllUninitVarsInFunction(it, uninitialized, preInit, fileLocals) }
                }
                is LabeledStatement -> collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                is WithStatement -> collectAllUninitVarsInFunction(listOf(stmt.statement), uninitialized, preInit, fileLocals)
                else -> {} // function/class declarations have their own scope
            }
        }
    }

    /** Names declared by a `for (const/let … of/in …)` / `for (let …; …)` initializer
     *  (round 450) — including binding-pattern names. Used to drop the loop variable from
     *  the definite-assignment set when descending into the loop body (it shadows any
     *  outer same-named var and is bound each iteration). */
    private fun forLoopDeclaredNames(initializer: Node?): Set<String> {
        val list = initializer as? VariableDeclarationList ?: return emptySet()
        val names = mutableSetOf<String>()
        for (decl in list.declarations) collectBindingIdentifierNames(decl.name, names)
        return names
    }

    private fun collectBindingIdentifierNames(name: Node?, out: MutableSet<String>) {
        when (name) {
            is Identifier -> out.add(name.text)
            is ArrayBindingPattern -> name.elements.forEach {
                (it as? BindingElement)?.let { be -> collectBindingIdentifierNames(be.name, out) }
            }
            is ObjectBindingPattern -> name.elements.forEach { collectBindingIdentifierNames(it.name, out) }
            else -> {}
        }
    }

    private fun addIfUninitForFlow(
        decl: VariableDeclaration, uninitialized: MutableSet<String>,
        preInit: Set<String>, fileLocals: SymbolTable?,
    ) {
        if (decl.type == null || decl.initializer != null || decl.exclamationToken) return
        if (isAnyType(decl.type)) return
        if (isUnresolvedGenericType(decl.type)) return
        if (typeContainsImportType(decl.type)) return
        if (typeIncludesUndefined(decl.type)) return
        if (fileLocals != null && isNamespaceTypeRef(decl.type, fileLocals)) return
        val name = decl.name
        if (name is Identifier && name.text !in preInit) {
            uninitialized.add(name.text)
        }
    }

    private fun walkStmtForFlowTS2454(
        stmt: Statement, uninitialized: Set<String>,
        source: String, fileName: String,
        emitted: MutableSet<Int>, inUncheckedBody: Boolean,
    ) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
                }
            }
            is ExpressionStatement -> walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is ReturnStatement -> stmt.expression?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
            is ThrowStatement -> stmt.expression?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
            is IfStatement -> {
                walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                walkStmtForFlowTS2454(stmt.thenStatement, uninitialized, source, fileName, emitted, inUncheckedBody = true)
                stmt.elseStatement?.let { walkStmtForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody = true) }
            }
            is WhileStatement -> {
                walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                walkStmtForFlowTS2454(stmt.statement, uninitialized, source, fileName, emitted, inUncheckedBody = true)
            }
            is DoStatement -> {
                walkStmtForFlowTS2454(stmt.statement, uninitialized, source, fileName, emitted, inUncheckedBody = true)
                walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            }
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { decl ->
                    decl.initializer?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
                }
                stmt.condition?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
                stmt.incrementor?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
                walkStmtForFlowTS2454(stmt.statement, uninitialized, source, fileName, emitted, inUncheckedBody = true)
            }
            is ForInStatement -> {
                walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                // A `for (const/let X in …)` loop variable X SHADOWS an outer same-named
                // uninitialized var and is bound every iteration — drop it from the body's
                // set so a body read of X isn't mis-attributed to the outer var (round 450;
                // mirrors the catch-body shadowing skip above).
                val bodyUninit = uninitialized - forLoopDeclaredNames(stmt.initializer)
                walkStmtForFlowTS2454(stmt.statement, bodyUninit, source, fileName, emitted, inUncheckedBody = true)
            }
            is ForOfStatement -> {
                walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                // for-of loop variable shadows + is bound each iteration (generators.ts
                // `let variable; if (…) for (const variable of decls) { …variable.name… }`).
                val bodyUninit = uninitialized - forLoopDeclaredNames(stmt.initializer)
                walkStmtForFlowTS2454(stmt.statement, bodyUninit, source, fileName, emitted, inUncheckedBody = true)
            }
            is SwitchStatement -> {
                walkExprForFlowTS2454(stmt.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            walkExprForFlowTS2454(clause.expression, uninitialized, source, fileName, emitted, inUncheckedBody = true)
                            for (s in clause.statements) walkStmtForFlowTS2454(s, uninitialized, source, fileName, emitted, inUncheckedBody = true)
                        }
                        is DefaultClause -> {
                            for (s in clause.statements) walkStmtForFlowTS2454(s, uninitialized, source, fileName, emitted, inUncheckedBody = true)
                        }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) walkStmtForFlowTS2454(s, uninitialized, source, fileName, emitted, inUncheckedBody = true)
                // Skip catchClause body to avoid catch-variable-shadowing FPs:
                // a catch `(a)` introduces an `a` binding that shadows any outer
                // `a` in the function scope. Without per-scope name tracking,
                // walking into the catch body would FP-emit TS2454 on
                // catch-bound reads.
                stmt.finallyBlock?.statements?.forEach { walkStmtForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody = true) }
            }
            is Block -> for (s in stmt.statements) walkStmtForFlowTS2454(s, uninitialized, source, fileName, emitted, inUncheckedBody)
            is LabeledStatement -> walkStmtForFlowTS2454(stmt.statement, uninitialized, source, fileName, emitted, inUncheckedBody)
            is WithStatement -> walkStmtForFlowTS2454(stmt.statement, uninitialized, source, fileName, emitted, inUncheckedBody = true)
            is ClassDeclaration -> {
                stmt.heritageClauses?.forEach { clause ->
                    for (type in clause.types) walkExprForFlowTS2454(type.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                }
            }
            is ExportAssignment -> stmt.expression.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
            else -> {}
        }
    }

    private fun walkExprForFlowTS2454(
        expr: Expression, uninitialized: Set<String>,
        source: String, fileName: String,
        emitted: MutableSet<Int>, inUncheckedBody: Boolean,
    ) {
        when (expr) {
            is Identifier -> {
                if (inUncheckedBody && expr.text in uninitialized) {
                    val pos = expr.pos
                    // Round 426 (faithful TS2563): the flow walk runs even for positions
                    // the AST-based emitter already reported — tsc walks EVERY read of a
                    // maybe-unassigned var, and a 2000-deep walk here is what trips
                    // TS2563 (the end-of-init range filter then retracts the TS2454).
                    // A disabled container (null) is treated as assigned (tsc errorType).
                    val flow = getFlowAt(expr)
                    val assigned = flowWalkWithTripCheck(expr, WK_ASSIGNED_EXPR, expr.text.hashCode().toLong(), flowPathRoot(expr.text)) {
                        isAssignedAtFlow(flow, expr.text, mutableSetOf())
                    } ?: true
                    if (pos !in emitted && !assigned) {
                        val (line, character) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "Variable '${expr.text}' is used before being assigned.",
                            category = DiagnosticCategory.Error,
                            code = 2454,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = pos,
                            length = expr.text.length,
                        ))
                        emitted.add(pos)
                    }
                }
            }
            is PropertyAccessExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is ElementAccessExpression -> {
                walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                walkExprForFlowTS2454(expr.argumentExpression, uninitialized, source, fileName, emitted, inUncheckedBody)
            }
            is CallExpression -> {
                walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                for (arg in expr.arguments) walkExprForFlowTS2454(arg, uninitialized, source, fileName, emitted, inUncheckedBody)
            }
            is NewExpression -> {
                walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                expr.arguments?.forEach { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
            }
            is BinaryExpression -> {
                // Iterative left-spine to avoid StackOverflow on deep binary chains.
                var current: Expression = expr
                while (current is BinaryExpression && current.operator != SyntaxKind.Equals && current.operator != SyntaxKind.Comma) {
                    walkExprForFlowTS2454(current.right, uninitialized, source, fileName, emitted, inUncheckedBody)
                    current = current.left
                }
                if (current is BinaryExpression) {
                    if (current.operator == SyntaxKind.Equals) {
                        walkExprForFlowTS2454(current.right, uninitialized, source, fileName, emitted, inUncheckedBody)
                        when (val left = current.left) {
                            is PropertyAccessExpression -> walkExprForFlowTS2454(left.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                            is ElementAccessExpression -> {
                                walkExprForFlowTS2454(left.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                                walkExprForFlowTS2454(left.argumentExpression, uninitialized, source, fileName, emitted, inUncheckedBody)
                            }
                            else -> {} // Identifier / destructuring patterns: write target — no read-time check
                        }
                    } else { // Comma
                        walkExprForFlowTS2454(current.left, uninitialized, source, fileName, emitted, inUncheckedBody)
                        walkExprForFlowTS2454(current.right, uninitialized, source, fileName, emitted, inUncheckedBody)
                    }
                } else {
                    walkExprForFlowTS2454(current, uninitialized, source, fileName, emitted, inUncheckedBody)
                }
            }
            is ConditionalExpression -> {
                walkExprForFlowTS2454(expr.condition, uninitialized, source, fileName, emitted, inUncheckedBody)
                walkExprForFlowTS2454(expr.whenTrue, uninitialized, source, fileName, emitted, inUncheckedBody)
                walkExprForFlowTS2454(expr.whenFalse, uninitialized, source, fileName, emitted, inUncheckedBody)
            }
            is PrefixUnaryExpression -> walkExprForFlowTS2454(expr.operand, uninitialized, source, fileName, emitted, inUncheckedBody)
            is PostfixUnaryExpression -> walkExprForFlowTS2454(expr.operand, uninitialized, source, fileName, emitted, inUncheckedBody)
            is ParenthesizedExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is ArrayLiteralExpression -> for (el in expr.elements) walkExprForFlowTS2454(el, uninitialized, source, fileName, emitted, inUncheckedBody)
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            (prop.name as? ComputedPropertyName)?.let { walkExprForFlowTS2454(it.expression, uninitialized, source, fileName, emitted, inUncheckedBody) }
                            walkExprForFlowTS2454(prop.initializer, uninitialized, source, fileName, emitted, inUncheckedBody)
                        }
                        is ShorthandPropertyAssignment -> walkExprForFlowTS2454(prop.name, uninitialized, source, fileName, emitted, inUncheckedBody)
                        is SpreadAssignment -> walkExprForFlowTS2454(prop.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> expr.templateSpans.forEach { walkExprForFlowTS2454(it.expression, uninitialized, source, fileName, emitted, inUncheckedBody) }
            is TaggedTemplateExpression -> {
                walkExprForFlowTS2454(expr.tag, uninitialized, source, fileName, emitted, inUncheckedBody)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    walkExprForFlowTS2454(it.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
                }
            }
            is SpreadElement -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is AwaitExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is YieldExpression -> expr.expression?.let { walkExprForFlowTS2454(it, uninitialized, source, fileName, emitted, inUncheckedBody) }
            is AsExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            // Round 427: a bare-Identifier read wrapped DIRECTLY in `!` assumes
            // initialized (tsc assumeInitialized: `node.parent.kind ===
            // SyntaxKind.NonNullExpression`) — mirror of the findUninitializedRefs case.
            is NonNullExpression -> if (expr.expression !is Identifier) {
                walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            }
            is TypeOfExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is DeleteExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is VoidExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is TypeAssertionExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is SatisfiesExpression -> walkExprForFlowTS2454(expr.expression, uninitialized, source, fileName, emitted, inUncheckedBody)
            is CommaListExpression -> for (e in expr.elements) walkExprForFlowTS2454(e, uninitialized, source, fileName, emitted, inUncheckedBody)
            // B86.1a: recurse into nested arrow / function-expression bodies with a fresh
            // flow scope so TS2454 fires inside callback bodies. The function's own
            // parameters become preInit (the analog of "contextual param push" — call
            // sites inherently supply values for declared params, so they're treated as
            // assigned for definite-assignment purposes). Outer-scope captures still
            // resolve via the outer uninit set if they're referenced from the inner body,
            // but `runFlowTS2454OnFunction` builds a fresh uninit set scoped to the
            // inner body — captured outer optionals are checked via their OWN function's
            // pass (TS2454 is per-function-scope by design, mirroring TypeScript).
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> runFlowTS2454OnFunction(body, expr.parameters, source, fileName, emitted, fileLocals = null)
                is Expression -> {
                    // Expression-bodied arrow: no Block to run flow on, but we still
                    // want to descend through the expression body's nested arrows /
                    // function expressions. The inner expression is checked under the
                    // OUTER uninit set (no fresh scope) since there are no local
                    // declarations in an expression body.
                    val innerPreInit = collectParamNames(expr.parameters)
                    // If any uninit name is shadowed by an inner param, mask it out
                    // for the body recursion (the inner param is the binding in scope).
                    var maskedUninit = if (innerPreInit.isEmpty()) uninitialized
                        else uninitialized - innerPreInit
                    // Round 427: a read inside the arrow is a CAPTURED read (a
                    // different flow container) — tsc assumes it initialized unless
                    // the symbol is NEVER definitely assigned anywhere
                    // (isNeverInitialized/isSymbolAssignedDefinitely). A definite
                    // assignment (`=`/`??=`/`||=`/`&&=`) within this very arrow body
                    // is the common shape (tsc checker.ts getSignaturesOfType's
                    // `t => … && (!memberName ? (memberName = X, true) : …)`) — mask
                    // those names out via the anywhere-scan's expression walker.
                    if (maskedUninit.isNotEmpty()) {
                        val definitelyAssigned = mutableSetOf<String>()
                        collectAssignmentsInExpr(body, maskedUninit, definitelyAssigned)
                        if (definitelyAssigned.isNotEmpty()) maskedUninit = maskedUninit - definitelyAssigned
                    }
                    if (maskedUninit.isNotEmpty()) {
                        walkExprForFlowTS2454(body, maskedUninit, source, fileName, emitted, inUncheckedBody)
                    } else {
                        // No outer uninit reaches; still recurse so nested function
                        // expressions inside the body get their own pass.
                        walkExprForFlowTS2454(body, emptySet(), source, fileName, emitted, inUncheckedBody)
                    }
                }
                else -> {}
            }
            is FunctionExpression -> expr.body.let { body ->
                runFlowTS2454OnFunction(body, expr.parameters, source, fileName, emitted, fileLocals = null)
            }
            else -> {} // literals only
        }
    }

    /** Recurse into nested function/class expressions inside a statement so their bodies get their own pass. */
    private fun walkExprForNestedFunctionLikes(
        stmt: Statement, source: String, fileName: String,
        emitted: MutableSet<Int>, fileLocals: SymbolTable?,
    ) {
        // Currently we let `walkTopForFlowTS2454` recurse via outer FunctionDeclaration /
        // ClassDeclaration / ModuleDeclaration handling. Function/Class EXPRESSIONS
        // inside other constructs are not yet recursed (would require an expression
        // walker mirroring `checkDefiniteAssignmentInExprContext`). The narrow gate
        // for 17.30a accepts this gap — top-level decls cover the nestedLoopTypeGuards
        // case and most real-world function-local TS2454 sites.
        // (Hook reserved for future widening — left intentionally empty.)
    }

    /**
     * Walk the flow graph backward from [flow] and return true if every reaching
     * path has either:
     *   - a [FlowAssignment] whose target binds [varName], OR
     *   - a [FlowCondition] whose expression+polarity implies [varName] is
     *     definitely assigned (e.g. `typeof x === '<not undefined>'` true-branch).
     *
     * The "any reaching path" framing here is actually "any direct walk-back path"
     * — we use OR-semantics across [FlowBranchLabel] / [FlowLoopLabel] antecedents
     * rather than AND. This matches the existing ad-hoc walker's leniency
     * (assignment in any branch suppresses TS2454) and minimizes regression risk
     * for the first commit. A stricter "all paths must assign" version is a
     * follow-up. Returns false when the walk reaches [FlowStart] or
     * [FlowUnreachable] without finding evidence.
     */
    private fun isAssignedAtFlow(
        flowIn: FlowNode?, varName: String, visited: MutableSet<Int>, depth: Int = 0,
    ): Boolean {
        var flow = flowIn ?: return false
        while (true) {
            if (depth >= NARROW_MAX_DEPTH) {
                // Round 426 (faithful TS2563): the definite-assignment query IS a flow
                // walk in tsc (getFlowTypeOfReference with the auto initial type), so a
                // 2000-deep recursion trips the same `flowDepth === 2000` limit —
                // TS2563 fires (reported at the entry point via [flowWalkWithTripCheck])
                // and the reference is treated as assigned (tsc returns errorType,
                // which suppresses the TS2454 report).
                flowDepthTripped = true
                return true
            }
            if (FlowCensus.on) FlowCensus.touch(flow, FlowCensus.CH_ASSIGNED) // (WARM.12)
            if (!visited.add(flow.id)) return false
            // Linear pass-through antecedents follow ITERATIVELY without consuming
            // depth (tsc getTypeAtFlowNode's `while(true)` loop — same accounting as
            // narrowTypeFromFlow's round-413 fast-forward); only branch/loop-join and
            // condition recursion consumes depth (tsc's `flowDepth`).
            when (val f = flow) {
                is FlowStart -> {
                    // Round 460: a read INSIDE a closure (FlowStart with outerFlow —
                    // arrow/function-expression nested in another function) continues
                    // into the ENCLOSING flow: tsc assumes a CAPTURED read initialized
                    // when the variable is assigned in the enclosing scope (checker.ts
                    // isOuterVariable — tsc's checkGrammar-style
                    // `filter(b, info => !findIndexInfo(indexInfos, info.keyType))`
                    // reads indexInfos assigned by the outer if/else). The walk is
                    // OR-semantics (assignment evidence SUPPRESSES the report), so the
                    // continuation only suppresses; a closure-LOCAL redeclaration of the
                    // name stays inside (localNames gate).
                    val outer = f.outerFlow
                    if (outer != null && varName !in f.localNames) flow = outer
                    else return false
                }
                is FlowUnreachable -> return false
                is FlowAssignment -> {
                    if (flowAssignmentTargetsName(f.node, varName)) return true
                    flow = f.antecedent
                }
                is FlowBranchLabel -> {
                    // tsc: a single-antecedent label is followed in the loop (no depth).
                    if (f.antecedents.size == 1) flow = f.antecedents[0]
                    else return f.antecedents.any { isAssignedAtFlow(it, varName, visited, depth + 1) }
                }
                // FlowLoopLabel back-edges are pointers to post-iteration flow that
                // can include type-guard true-branches (`typeof a === 'string'`) from
                // an inner conditional. Walking them naively makes a read inside the
                // loop body reach those guards through the back-edge cycle, FP-asserting
                // assignment. Only follow antecedents[0], the pre-loop entry — same
                // conservative bound `narrowTypeFromFlow` uses (returns declaredType
                // at loop joins to avoid back-edge widening). Continue/end-of-body
                // back-edges are antecedents[1+].
                is FlowLoopLabel -> {
                    if (f.antecedents.isEmpty()) return false
                    return isAssignedAtFlow(f.antecedents[0], varName, visited, depth + 1)
                }
                is FlowCondition -> {
                    val implies = if (f.isTrue) conditionImpliesAssignedTrue(f.expression, varName)
                                  else conditionImpliesAssignedFalse(f.expression, varName)
                    if (implies) return true
                    return isAssignedAtFlow(f.antecedent, varName, visited, depth + 1)
                }
                is FlowCall -> flow = f.antecedent
                is FlowSwitchClause -> flow = f.antecedent
                is FlowArrayMutation -> flow = f.antecedent
            }
        }
    }

    private fun flowAssignmentTargetsName(node: Node, varName: String): Boolean {
        return when (node) {
            // Bare `var a: T;` creates a FlowAssignment in Flow.kt for binding-introduction
            // bookkeeping, but no value is assigned. Only count VariableDeclarations that
            // actually assign a value (initializer present) — otherwise the declaration
            // itself would mask every TS2454 candidate.
            is VariableDeclaration -> {
                if (node.initializer == null) false
                else (node.name as? Identifier)?.text == varName
            }
            is Parameter -> (node.name as? Identifier)?.text == varName
            is BindingElement -> (node.name as? Identifier)?.text == varName
            // Round 460: a destructuring ASSIGNMENT's FlowAssignment now carries the
            // WHOLE `({a, b} = X)` BinaryExpression (Flow.kt threads declarationNode
            // through the literal arms so the narrowing walker can see the RHS) — walk
            // the pattern LHS for the name. A bare literal node (for-of destructuring
            // targets, `for ([a, b] of pairs)`) is walked the same way.
            is BinaryExpression -> (node.left as? Identifier)?.text == varName ||
                node.left.let {
                    (it is ObjectLiteralExpression || it is ArrayLiteralExpression) &&
                        destructuringAssignTargetHasName(it, varName, 0)
                }
            is ObjectLiteralExpression -> destructuringAssignTargetHasName(node, varName, 0)
            is ArrayLiteralExpression -> destructuringAssignTargetHasName(node, varName, 0)
            is Identifier -> node.text == varName // ++x / x++ pattern
            else -> false
        }
    }

    /** Round 460: the resolved type of the member [name] binds to in a destructuring
     *  ASSIGNMENT `({ a, b: name } = rhs)` / `([name] = rhs)` — null when unresolvable
     *  (callers keep the conservative antecedent). Top-level pattern positions only. */
    private fun destructuredMemberTypeForFlow(target: Expression, rhs: Expression, name: String): Type? {
        val rhsT = getTypeOfExpression(rhs)
        if (rhsT === anyType || rhsT === errorType) return null
        return when (target) {
            is ObjectLiteralExpression -> {
                val propName = target.properties.firstNotNullOfOrNull { p ->
                    when (p) {
                        is ShorthandPropertyAssignment -> if (p.name.text == name) p.name.text else null
                        is PropertyAssignment -> if ((p.initializer as? Identifier)?.text == name)
                            getPropertyKeyName(p.name) else null
                        else -> null
                    }
                } ?: return null
                val sym = getPropertyOfType(getApparentType(rhsT), propName) ?: return null
                getTypeOfSymbol(sym)
            }
            is ArrayLiteralExpression -> {
                val idx = target.elements.indexOfFirst { (it as? Identifier)?.text == name }
                if (idx < 0) return null
                (rhsT as? Type.Object)?.tupleElementTypes?.getOrNull(idx)
                    ?: arrayRefElement(rhsT)
            }
            else -> null
        }
    }

    /** True when [t] is or contains a null/undefined constituent. */
    private fun typeHasNullishConstituent(t: Type): Boolean =
        t.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) ||
            (t is Type.Union && t.types.any { it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) })

    /** Round 460: does a destructuring-ASSIGNMENT target literal (`{a, b: c}` / `[x, y]`)
     *  bind [varName] at any nesting depth? */
    private fun destructuringAssignTargetHasName(target: Expression, varName: String, depth: Int): Boolean {
        if (depth > 6) return false
        return when (target) {
            is ObjectLiteralExpression -> target.properties.any { p ->
                when (p) {
                    is ShorthandPropertyAssignment -> p.name.text == varName
                    is PropertyAssignment -> destructuringLeafOrNestedHasName(p.initializer, varName, depth)
                    is SpreadAssignment -> (p.expression as? Identifier)?.text == varName
                    else -> false
                }
            }
            is ArrayLiteralExpression -> target.elements.any { el ->
                when (el) {
                    is SpreadElement -> (el.expression as? Identifier)?.text == varName
                    else -> destructuringLeafOrNestedHasName(el, varName, depth)
                }
            }
            else -> false
        }
    }

    /** One destructuring-assignment element position: a bare Identifier leaf, a
     *  default-value form `<target> = <default>` whose LHS may itself be a NESTED
     *  pattern (`{ skills: { primary: primaryA = "x" } = {} }` — the for-of corpus
     *  shape that caught the first cut), or a nested pattern literal. */
    private fun destructuringLeafOrNestedHasName(el: Expression, varName: String, depth: Int): Boolean =
        when (el) {
            is Identifier -> el.text == varName
            is BinaryExpression -> el.operator == SyntaxKind.Equals &&
                ((el.left as? Identifier)?.text == varName ||
                    el.left.let {
                        (it is ObjectLiteralExpression || it is ArrayLiteralExpression) &&
                            destructuringAssignTargetHasName(it, varName, depth + 1)
                    })
            is ObjectLiteralExpression, is ArrayLiteralExpression ->
                destructuringAssignTargetHasName(el, varName, depth + 1)
            else -> false
        }

    /**
     * Patterns whose true-branch implies [varName] is definitely assigned:
     *   - `varName`           (truthy → not undefined/null/0/'')
     *   - `typeof varName === '<not undefined>'`  (loose or strict)
     *   - `typeof varName !== 'undefined'`        (loose or strict)
     *   - `varName !== undefined`                 (strict)
     *   - `varName != null`                       (loose — covers undefined too)
     *   - `varName != undefined`                  (loose — same shape)
     *   - `varName === <something other than undefined/null>`  (strict)
     *   - `!<something whose false branch implies assigned>`
     *   - `<lhs> && <rhs>` where either side implies assigned
     */
    private fun conditionImpliesAssignedTrue(expr: Expression, varName: String): Boolean {
        val e = unwrapParensExpr(expr)
        return when (e) {
            is Identifier -> e.text == varName
            is PrefixUnaryExpression -> if (e.operator == SyntaxKind.Exclamation) {
                conditionImpliesAssignedFalse(e.operand, varName)
            } else false
            is BinaryExpression -> when (e.operator) {
                SyntaxKind.AmpersandAmpersand -> {
                    conditionImpliesAssignedTrue(e.left, varName) || conditionImpliesAssignedTrue(e.right, varName)
                }
                SyntaxKind.InstanceOfKeyword -> {
                    // x instanceof Class — body executes only if x's read produced a defined value,
                    // so x is treated as definitely-assigned in the body.
                    isVarRef(e.left, varName)
                }
                SyntaxKind.EqualsEqualsEquals, SyntaxKind.EqualsEquals -> {
                    if (isTypeofOf(e.left, varName) && isStringLiteralNotUndefined(e.right)) return true
                    if (isTypeofOf(e.right, varName) && isStringLiteralNotUndefined(e.left)) return true
                    if (isVarRef(e.left, varName) && isNotNullOrUndefinedRef(e.right)) return true
                    if (isVarRef(e.right, varName) && isNotNullOrUndefinedRef(e.left)) return true
                    // x.constructor === Class / Class === x.constructor — body implies x assigned.
                    if (isConstructorAccessOf(e.left, varName)) return true
                    if (isConstructorAccessOf(e.right, varName)) return true
                    false
                }
                SyntaxKind.ExclamationEqualsEquals -> {
                    if (isTypeofOf(e.left, varName) && isUndefinedStringLiteral(e.right)) return true
                    if (isTypeofOf(e.right, varName) && isUndefinedStringLiteral(e.left)) return true
                    if (isVarRef(e.left, varName) && isUndefinedRef(e.right)) return true
                    if (isVarRef(e.right, varName) && isUndefinedRef(e.left)) return true
                    false
                }
                SyntaxKind.ExclamationEquals -> {
                    // x != null (loose) / x != undefined — both filter undefined too
                    if (isTypeofOf(e.left, varName) && isUndefinedStringLiteral(e.right)) return true
                    if (isTypeofOf(e.right, varName) && isUndefinedStringLiteral(e.left)) return true
                    if (isVarRef(e.left, varName) && (isNullRef(e.right) || isUndefinedRef(e.right))) return true
                    if (isVarRef(e.right, varName) && (isNullRef(e.left) || isUndefinedRef(e.left))) return true
                    false
                }
                else -> false
            }
            // Lib type-predicate calls: Array.isArray(x), ArrayBuffer.isView(x),
            // Number.isInteger(x), etc. — body implies x is assigned.
            is CallExpression -> isLibTypeGuardOf(e, varName)
            else -> false
        }
    }

    /**
     * Recognizes calls of the form `Class.method(varRef, ...)` where the
     * `Class.method` pair is a known lib-defined type-predicate. Used by
     * `conditionImpliesAssignedTrue` so that `if (Array.isArray(x)) { x.length }`
     * inside an unchecked body doesn't FP-emit TS2454 from the flow walker.
     */
    private fun isLibTypeGuardOf(call: CallExpression, varName: String): Boolean {
        val firstArg = call.arguments.firstOrNull() ?: return false
        if (!isVarRef(firstArg, varName)) return false
        val callee = unwrapParensExpr(call.expression)
        if (callee !is PropertyAccessExpression) return false
        val obj = callee.expression as? Identifier ?: return false
        val method = (callee.name).text
        val key = "${obj.text}.$method"
        return key in LIB_TYPE_GUARDS
    }

    private fun conditionImpliesAssignedFalse(expr: Expression, varName: String): Boolean {
        val e = unwrapParensExpr(expr)
        return when (e) {
            is PrefixUnaryExpression -> if (e.operator == SyntaxKind.Exclamation) {
                conditionImpliesAssignedTrue(e.operand, varName)
            } else false
            is BinaryExpression -> when (e.operator) {
                SyntaxKind.BarBar -> {
                    // !(a || b) ⇔ !a && !b — both must imply assigned
                    conditionImpliesAssignedFalse(e.left, varName) && conditionImpliesAssignedFalse(e.right, varName)
                }
                SyntaxKind.EqualsEqualsEquals, SyntaxKind.EqualsEquals -> {
                    // typeof x === 'undefined' (false) → x assigned; x === undefined (false) → x assigned
                    if (isTypeofOf(e.left, varName) && isUndefinedStringLiteral(e.right)) return true
                    if (isTypeofOf(e.right, varName) && isUndefinedStringLiteral(e.left)) return true
                    if (isVarRef(e.left, varName) && isUndefinedRef(e.right)) return true
                    if (isVarRef(e.right, varName) && isUndefinedRef(e.left)) return true
                    false
                }
                SyntaxKind.ExclamationEqualsEquals -> {
                    // typeof x !== '<not undefined>' (false) → x has that typeof → assigned
                    if (isTypeofOf(e.left, varName) && isStringLiteralNotUndefined(e.right)) return true
                    if (isTypeofOf(e.right, varName) && isStringLiteralNotUndefined(e.left)) return true
                    false
                }
                else -> false
            }
            else -> false
        }
    }

    private fun unwrapParensExpr(expr: Expression): Expression =
        if (expr is ParenthesizedExpression) unwrapParensExpr(expr.expression) else expr

    private fun isTypeofOf(expr: Expression, varName: String): Boolean {
        // `(typeof x) === "string"` — unwrap parens around the typeof expression itself.
        val unwrapped = unwrapParensExpr(expr)
        if (unwrapped !is TypeOfExpression) return false
        // `typeof (x)` should narrow identically to `typeof x` — unwrap parens.
        val inner = unwrapParensExpr(unwrapped.expression)
        return (inner as? Identifier)?.text == varName
    }

    private fun isStringLiteralNotUndefined(expr: Expression): Boolean {
        val unwrapped = unwrapParensExpr(expr)
        val text = (unwrapped as? StringLiteralNode)?.text
            ?: (unwrapped as? NoSubstitutionTemplateLiteralNode)?.text
            ?: return false
        return text != "undefined"
    }

    private fun isUndefinedStringLiteral(expr: Expression): Boolean {
        val unwrapped = unwrapParensExpr(expr)
        val text = (unwrapped as? StringLiteralNode)?.text
            ?: (unwrapped as? NoSubstitutionTemplateLiteralNode)?.text
            ?: return false
        return text == "undefined"
    }

    private fun isVarRef(expr: Expression, varName: String): Boolean {
        return (unwrapParensExpr(expr) as? Identifier)?.text == varName
    }

    private fun isUndefinedRef(expr: Expression): Boolean {
        val unwrapped = unwrapParensExpr(expr)
        if ((unwrapped as? Identifier)?.text == "undefined") return true
        // `void 0` / `void X` evaluates to `undefined` at runtime — treat as
        // equivalent to `undefined` for narrowing comparisons.
        if (unwrapped is VoidExpression) return true
        return false
    }

    private fun isNullRef(expr: Expression): Boolean {
        return unwrapParensExpr(expr).kind == SyntaxKind.NullKeyword
    }

    private fun isNotNullOrUndefinedRef(expr: Expression): Boolean {
        return !isUndefinedRef(expr) && !isNullRef(expr)
    }

    // -----------------------------------------------------------------------
    // Property initialization checking (TS2564)
    // -----------------------------------------------------------------------

    /**
     * Check for class properties without initializer and not definitely assigned
     * in the constructor. Emits TS2564.
     */
    private fun checkPropertyInitialization() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkPropertyInitInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    /**
     * 16.4da: TS2719 "Two different types with this name exist, but they are unrelated."
     *
     * Walks each class with type parameters and looks for `this.prop = identifier` where:
     * - `prop` is declared as type `T` (a class type parameter)
     * - `identifier` is a file-level binding annotated with the same name `T`
     * - That outer `T` resolves to an Interface/TypeAlias (NOT the class type parameter)
     */
    private fun checkIdenticallyNamedTypeAssignment() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkTs2719InStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkTs2719InStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    checkTs2719InClass(stmt, source, fileName)
                    // Recurse into method bodies for nested classes
                    for (m in stmt.members) {
                        val body = when (m) {
                            is MethodDeclaration -> m.body
                            is Constructor -> m.body
                            is GetAccessor -> m.body
                            is SetAccessor -> m.body
                            else -> null
                        }
                        body?.let { checkTs2719InStatements(it.statements, source, fileName) }
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) checkTs2719InStatements(body.statements, source, fileName)
                }
                is FunctionDeclaration -> stmt.body?.let { checkTs2719InStatements(it.statements, source, fileName) }
                is Block -> checkTs2719InStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkTs2719InStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkTs2719InStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkTs2719InStatements(listOf(stmt.statement), source, fileName)
                is ForInStatement -> checkTs2719InStatements(listOf(stmt.statement), source, fileName)
                is ForOfStatement -> checkTs2719InStatements(listOf(stmt.statement), source, fileName)
                is WhileStatement -> checkTs2719InStatements(listOf(stmt.statement), source, fileName)
                is DoStatement -> checkTs2719InStatements(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkTs2719InStatements(clause.statements, source, fileName)
                        is DefaultClause -> checkTs2719InStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
                is TryStatement -> {
                    checkTs2719InStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.let { checkTs2719InStatements(it.block.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkTs2719InStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkTs2719InStatements(listOf(stmt.statement), source, fileName)
                else -> {}
            }
        }
    }

    private fun checkTs2719InClass(classDecl: ClassDeclaration, source: String, fileName: String) {
        val classTypeParamNames = collectTypeParamNames(classDecl.typeParameters)
        if (classTypeParamNames.isEmpty()) return
        // Map prop name → class type-param name (only when prop type is a bare class type param)
        val propsTypedAsTypeParam = mutableMapOf<String, String>()
        for (m in classDecl.members) {
            if (m is PropertyDeclaration) {
                val tn = m.type as? TypeReference ?: continue
                val tname = (tn.typeName as? Identifier)?.text ?: continue
                if (tname !in classTypeParamNames) continue
                val pname = (m.name as? Identifier)?.text ?: continue
                propsTypedAsTypeParam[pname] = tname
            }
        }
        if (propsTypedAsTypeParam.isEmpty()) return
        for (m in classDecl.members) {
            val body: Block? = when (m) {
                is MethodDeclaration -> m.body
                is GetAccessor -> m.body
                is SetAccessor -> m.body
                is Constructor -> m.body
                else -> null
            }
            if (body != null) walkTs2719Assignments(body, propsTypedAsTypeParam, source, fileName)
        }
    }

    private fun walkTs2719Assignments(
        node: Node,
        propsTypedAsTypeParam: Map<String, String>,
        source: String,
        fileName: String,
    ) {
        when (node) {
            is BinaryExpression -> {
                if (node.operator == SyntaxKind.Equals) {
                    emitTs2719IfApplicable(node, propsTypedAsTypeParam, source, fileName)
                }
                walkTs2719Assignments(node.left, propsTypedAsTypeParam, source, fileName)
                walkTs2719Assignments(node.right, propsTypedAsTypeParam, source, fileName)
            }
            is Block -> for (s in node.statements) walkTs2719Assignments(s, propsTypedAsTypeParam, source, fileName)
            is ExpressionStatement -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is IfStatement -> {
                walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
                walkTs2719Assignments(node.thenStatement, propsTypedAsTypeParam, source, fileName)
                node.elseStatement?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            }
            is ForStatement -> {
                node.initializer?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                node.condition?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                node.incrementor?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                walkTs2719Assignments(node.statement, propsTypedAsTypeParam, source, fileName)
            }
            is ForInStatement -> walkTs2719Assignments(node.statement, propsTypedAsTypeParam, source, fileName)
            is ForOfStatement -> walkTs2719Assignments(node.statement, propsTypedAsTypeParam, source, fileName)
            is WhileStatement -> {
                walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
                walkTs2719Assignments(node.statement, propsTypedAsTypeParam, source, fileName)
            }
            is DoStatement -> {
                walkTs2719Assignments(node.statement, propsTypedAsTypeParam, source, fileName)
                walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            }
            is TryStatement -> {
                walkTs2719Assignments(node.tryBlock, propsTypedAsTypeParam, source, fileName)
                node.catchClause?.block?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                node.finallyBlock?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            }
            is SwitchStatement -> {
                for (clause in node.caseBlock) {
                    when (clause) {
                        is CaseClause -> for (s in clause.statements) walkTs2719Assignments(s, propsTypedAsTypeParam, source, fileName)
                        is DefaultClause -> for (s in clause.statements) walkTs2719Assignments(s, propsTypedAsTypeParam, source, fileName)
                        else -> {}
                    }
                }
            }
            is ReturnStatement -> node.expression?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            is ThrowStatement -> node.expression?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            is LabeledStatement -> walkTs2719Assignments(node.statement, propsTypedAsTypeParam, source, fileName)
            is VariableStatement -> for (decl in node.declarationList.declarations) {
                decl.initializer?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            }
            is ParenthesizedExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is AsExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is TypeAssertionExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is SatisfiesExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is NonNullExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is ConditionalExpression -> {
                walkTs2719Assignments(node.condition, propsTypedAsTypeParam, source, fileName)
                walkTs2719Assignments(node.whenTrue, propsTypedAsTypeParam, source, fileName)
                walkTs2719Assignments(node.whenFalse, propsTypedAsTypeParam, source, fileName)
            }
            is CallExpression -> {
                walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
                for (arg in node.arguments) walkTs2719Assignments(arg, propsTypedAsTypeParam, source, fileName)
            }
            is NewExpression -> {
                walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
                node.arguments?.forEach { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            }
            is ArrayLiteralExpression -> {
                for (elem in node.elements) walkTs2719Assignments(elem, propsTypedAsTypeParam, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in node.properties) {
                    when (prop) {
                        is PropertyAssignment -> walkTs2719Assignments(prop.initializer, propsTypedAsTypeParam, source, fileName)
                        is SpreadAssignment -> walkTs2719Assignments(prop.expression, propsTypedAsTypeParam, source, fileName)
                        is MethodDeclaration -> prop.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is GetAccessor -> prop.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is SetAccessor -> prop.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = node.body) {
                    is Block -> walkTs2719Assignments(body, propsTypedAsTypeParam, source, fileName)
                    is Expression -> walkTs2719Assignments(body, propsTypedAsTypeParam, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> node.body.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            is SpreadElement -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is AwaitExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is YieldExpression -> node.expression?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            is PrefixUnaryExpression -> walkTs2719Assignments(node.operand, propsTypedAsTypeParam, source, fileName)
            is PostfixUnaryExpression -> walkTs2719Assignments(node.operand, propsTypedAsTypeParam, source, fileName)
            is VoidExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is DeleteExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is TypeOfExpression -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            is TemplateExpression -> {
                for (span in node.templateSpans) walkTs2719Assignments(span.expression, propsTypedAsTypeParam, source, fileName)
            }
            is TaggedTemplateExpression -> {
                walkTs2719Assignments(node.tag, propsTypedAsTypeParam, source, fileName)
                val tpl = node.template
                if (tpl is TemplateExpression) {
                    for (span in tpl.templateSpans) walkTs2719Assignments(span.expression, propsTypedAsTypeParam, source, fileName)
                }
            }
            is CommaListExpression -> for (e in node.elements) walkTs2719Assignments(e, propsTypedAsTypeParam, source, fileName)
            is FunctionDeclaration -> node.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            is ClassDeclaration -> {
                for (member in node.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is Constructor -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is GetAccessor -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is SetAccessor -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ClassExpression -> {
                for (member in node.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is Constructor -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is GetAccessor -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is SetAccessor -> member.body?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> (node.body as? ModuleBlock)?.let { walkTs2719Assignments(it, propsTypedAsTypeParam, source, fileName) }
            is ModuleBlock -> for (s in node.statements) walkTs2719Assignments(s, propsTypedAsTypeParam, source, fileName)
            is ExportAssignment -> walkTs2719Assignments(node.expression, propsTypedAsTypeParam, source, fileName)
            else -> {}
        }
    }

    private fun emitTs2719IfApplicable(
        binExpr: BinaryExpression,
        propsTypedAsTypeParam: Map<String, String>,
        source: String,
        fileName: String,
    ) {
        val target = binExpr.left as? PropertyAccessExpression ?: return
        if ((target.expression as? Identifier)?.text != "this") return
        val propName = target.name.text
        val typeParamName = propsTypedAsTypeParam[propName] ?: return
        val rhs = binExpr.right as? Identifier ?: return
        val srcSym = globals[rhs.text] ?: return
        val srcDecl = srcSym.valueDeclaration ?: srcSym.declarations.firstOrNull()
        val srcTypeNode = (srcDecl as? VariableDeclaration)?.type as? TypeReference ?: return
        val srcTypeName = (srcTypeNode.typeName as? Identifier)?.text ?: return
        if (srcTypeName != typeParamName) return
        val typeNameSym = globals[srcTypeName] ?: return
        if (typeNameSym.flags.hasAny(SymbolFlags.TypeParameter)) return
        if (!typeNameSym.declarations.any { it is InterfaceDeclaration || it is TypeAliasDeclaration }) return
        val squiggleStart = target.expression.pos
        val squiggleLength = target.name.pos + target.name.text.length - squiggleStart
        val (line, character) = getLineAndCharacterOfPosition(source, squiggleStart)
        diagnostics.add(Diagnostic(
            message = "Type '$typeParamName' is not assignable to type '$typeParamName'. Two different types with this name exist, but they are unrelated.",
            category = DiagnosticCategory.Error,
            code = 2719,
            fileName = fileName,
            line = line,
            character = character,
            start = squiggleStart,
            length = squiggleLength,
            messageChain = listOf("  '$typeParamName' could be instantiated with an arbitrary type which could be unrelated to '$typeParamName'."),
        ))
    }

    /**
     * (M0.4) round 636: this walker family (checkPropertyInitInStatements /
     * checkPropertyInitInExpr / checkClassPropertyInit) survives ONLY for the
     * B439 declarationOnly direct dispatch — the normal-mode pass rides the
     * spine ([spinePiEnterNode]), whose reach classifier [spinePiEdge] mirrors
     * these arms verbatim. ANY descent-arm change here MUST be mirrored there
     * (the round-630 shared-walker rule) or the spine reach silently diverges.
     */
    private fun checkPropertyInitInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    // Abstract classes still need TS2564 for non-abstract properties
                    checkClassPropertyInit(stmt.members, source, fileName)
                    // round 44 iter2: recurse into class member bodies so nested ClassDeclaration
                    // inside method/constructor/accessor bodies and PropertyDeclaration initializers
                    // also reach TS2564 check.
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkPropertyInitInStatements(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { checkPropertyInitInStatements(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { checkPropertyInitInStatements(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkPropertyInitInStatements(it.statements, source, fileName) }
                            is PropertyDeclaration -> member.initializer?.let { checkPropertyInitInExpr(it, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> {
                    // Skip declare (ambient) namespaces — classes inside are ambient
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkPropertyInitInStatements(
                            body.statements, source, fileName,
                        )
                        else -> {}
                    }
                }
                is FunctionDeclaration -> {
                    if (ModifierFlag.Declare in stmt.modifiers) continue
                    stmt.body?.let {
                        checkPropertyInitInStatements(it.statements, source, fileName)
                    }
                }
                is Block -> checkPropertyInitInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkPropertyInitInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let {
                        checkPropertyInitInStatements(listOf(it), source, fileName)
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkPropertyInitInExpr(decl.initializer, source, fileName)
                    }
                }
                is ExpressionStatement -> {
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                is ReturnStatement -> {
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                is ForStatement -> {
                    checkPropertyInitInStatements(listOf(stmt.statement), source, fileName)
                    when (val init = stmt.initializer) {
                        is VariableDeclarationList -> for (decl in init.declarations) checkPropertyInitInExpr(decl.initializer, source, fileName)
                        is Expression -> checkPropertyInitInExpr(init, source, fileName)
                        else -> {}
                    }
                    stmt.condition?.let { checkPropertyInitInExpr(it, source, fileName) }
                    stmt.incrementor?.let { checkPropertyInitInExpr(it, source, fileName) }
                }
                is ForInStatement -> {
                    checkPropertyInitInStatements(listOf(stmt.statement), source, fileName)
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                is ForOfStatement -> {
                    checkPropertyInitInStatements(listOf(stmt.statement), source, fileName)
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                is WhileStatement -> {
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                    checkPropertyInitInStatements(listOf(stmt.statement), source, fileName)
                }
                is DoStatement -> {
                    checkPropertyInitInStatements(listOf(stmt.statement), source, fileName)
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                }
                is SwitchStatement -> {
                    checkPropertyInitInExpr(stmt.expression, source, fileName)
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> {
                                checkPropertyInitInExpr(clause.expression, source, fileName)
                                checkPropertyInitInStatements(clause.statements, source, fileName)
                            }
                            is DefaultClause -> checkPropertyInitInStatements(clause.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkPropertyInitInStatements(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { checkPropertyInitInStatements(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { checkPropertyInitInStatements(it.statements, source, fileName) }
                }
                is LabeledStatement -> checkPropertyInitInStatements(listOf(stmt.statement), source, fileName)
                is ThrowStatement -> checkPropertyInitInExpr(stmt.expression, source, fileName)
                is ExportAssignment -> checkPropertyInitInExpr(stmt.expression, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkPropertyInitInExpr(expr: Expression?, source: String, fileName: String) {
        if (expr == null) return
        when (expr) {
            is ClassExpression -> {
                if (ModifierFlag.Abstract !in expr.modifiers) {
                    checkClassPropertyInit(expr.members, source, fileName)
                }
                // Also recurse into member bodies which may contain ClassExpression in field initializers / method bodies
                for (m in expr.members) {
                    when (m) {
                        is PropertyDeclaration -> checkPropertyInitInExpr(m.initializer, source, fileName)
                        else -> {}
                    }
                }
            }
            is ParenthesizedExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is AsExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkPropertyInitInExpr(expr.whenTrue, source, fileName)
                checkPropertyInitInExpr(expr.whenFalse, source, fileName)
            }
            is BinaryExpression -> {
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    checkPropertyInitInExpr(cur.right, source, fileName)
                    cur = cur.left
                }
                checkPropertyInitInExpr(cur, source, fileName)
            }
            is CallExpression -> {
                checkPropertyInitInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { checkPropertyInitInExpr(it, source, fileName) }
            }
            is NewExpression -> {
                checkPropertyInitInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkPropertyInitInExpr(it, source, fileName) }
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkPropertyInitInExpr(it, source, fileName) }
            is SpreadElement -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkPropertyInitInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkPropertyInitInExpr(expr.operand, source, fileName)
            is AwaitExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkPropertyInitInExpr(it, source, fileName) }
            is VoidExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is TemplateExpression -> expr.templateSpans.forEach { checkPropertyInitInExpr(it.expression, source, fileName) }
            is TaggedTemplateExpression -> {
                checkPropertyInitInExpr(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkPropertyInitInExpr(it.expression, source, fileName)
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkPropertyInitInExpr(it, source, fileName) }
            is PropertyAccessExpression -> checkPropertyInitInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkPropertyInitInExpr(expr.expression, source, fileName)
                checkPropertyInitInExpr(expr.argumentExpression, source, fileName)
            }
            is ObjectLiteralExpression -> for (p in expr.properties) {
                when (p) {
                    is PropertyAssignment -> checkPropertyInitInExpr(p.initializer, source, fileName)
                    is SpreadAssignment -> checkPropertyInitInExpr(p.expression, source, fileName)
                    else -> {}
                }
            }
            // round 43 iter14: function-like body recursion so `() => class C { x = 1 }`
            // and `function() { return class C { x = 1 } }` reach nested ClassExpression
            // for TS2564 property-init check.
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> body.statements.forEach { stmt ->
                    if (stmt is ExpressionStatement) checkPropertyInitInExpr(stmt.expression, source, fileName)
                    else if (stmt is ReturnStatement) stmt.expression?.let { checkPropertyInitInExpr(it, source, fileName) }
                    else if (stmt is VariableStatement) for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { checkPropertyInitInExpr(it, source, fileName) }
                    }
                }
                is Expression -> checkPropertyInitInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> for (stmt in expr.body.statements) {
                if (stmt is ExpressionStatement) checkPropertyInitInExpr(stmt.expression, source, fileName)
                else if (stmt is ReturnStatement) stmt.expression?.let { checkPropertyInitInExpr(it, source, fileName) }
                else if (stmt is VariableStatement) for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkPropertyInitInExpr(it, source, fileName) }
                }
            }
            else -> {}
        }
    }

    private fun checkClassPropertyInit(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        checkClassPropertyInitEmit(members, source, fileName)

        // Recurse into nested class elements for inner classes
        for (member in members) {
            when (member) {
                is MethodDeclaration -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is Constructor -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is GetAccessor -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is SetAccessor -> member.body?.let {
                    checkPropertyInitInStatements(it.statements, source, fileName)
                }
                is ClassStaticBlockDeclaration -> {
                    checkPropertyInitInStatements(member.body.statements, source, fileName)
                }
                else -> {}
            }
        }
    }

    /**
     * (M0.4) round 636: the per-class TS2564 emission, split out of
     * [checkClassPropertyInit] so the spine anchors ([spinePiEnterNode]) can
     * run it without the nested-class recursion (nested classes get their own
     * anchors); the legacy walkers (kept for the B439 declarationOnly
     * dispatch) still route through [checkClassPropertyInit] and are
     * byte-identical.
     */
    private fun checkClassPropertyInitEmit(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Find the constructor and collect assigned properties
        val constructorAssigned = mutableSetOf<String>()
        // Collect all class member names (for typeof-reference check below)
        val classMemberNames = mutableSetOf<String>()
        for (member in members) {
            if (member is Constructor) {
                member.body?.let { body ->
                    collectConstructorAssignments(body.statements, constructorAssigned)
                }
                // Constructor parameters with access modifiers (public/private/protected)
                // are automatically assigned
                for (param in member.parameters) {
                    if (ModifierFlag.Public in param.modifiers ||
                        ModifierFlag.Protected in param.modifiers ||
                        ModifierFlag.Private in param.modifiers) {
                        val name = param.name
                        if (name is Identifier) {
                            constructorAssigned.add(name.text)
                        }
                    }
                }
            }
            // Collect member names for typeof-reference detection
            val memberName = when (val n = (member as? PropertyDeclaration)?.name
                ?: (member as? MethodDeclaration)?.name) {
                is Identifier -> n.text
                else -> null
            }
            if (memberName != null) classMemberNames.add(memberName)
        }

        // Check each property
        for (member in members) {
            if (member !is PropertyDeclaration) continue
            // Skip if has initializer, optional, declare, static, abstract, or definite assignment
            if (member.initializer != null) continue
            if (member.questionToken) continue
            if (member.exclamationToken) continue
            if (ModifierFlag.Declare in member.modifiers) continue
            if (ModifierFlag.Static in member.modifiers) continue
            if (ModifierFlag.Abstract in member.modifiers) continue
            // Must have type annotation (no type = any, which is always ok)
            if (member.type == null) continue
            // Skip `any` type — no assignment needed for any
            if (isAnyType(member.type)) continue
            // A property whose declared type INCLUDES `undefined` starts with a valid value
            // (undefined) and so needs no definite assignment — tsc's strictPropertyInitialization
            // exempts it (`getFalsyFlags(type) & TypeFlags.Undefined`). e.g. services.ts's
            // `public nameTable: Map<__String, number> | undefined;`. Same helper the TS2454
            // definite-assignment path uses, so the two stay consistent.
            if (typeIncludesUndefined(member.type)) continue
            // Skip if type annotation is a bare generic reference (would trigger TS2314)
            // TypeScript doesn't flag TS2564 on error types
            if (isUnresolvedGenericType(member.type)) continue
            // Skip when type names a forward-declarable es2015+ lib type that the
            // current options' lib config doesn't provide (e.g. `Map` under @noLib).
            // TS2583 already flags the missing-lib-name; TS2564 would be a redundant
            // diagnostic on an effective error type.
            if (typeContainsUnavailableLibName(member.type)) continue
            // Skip import types (e.g. `import('./b').B`) — we can't resolve them
            if (typeContainsImportType(member.type)) continue
            // Skip `typeof X` where X is a class member or unresolved name — TypeScript resolves
            // these as error types and suppresses TS2564. Only check `typeof X` when X is
            // definitely NOT a class member (TypeScript would resolve it as a valid type).
            if (member.type is TypeQuery) {
                val queryExpr = (member.type).exprName
                if (queryExpr is Identifier && queryExpr.text in classMemberNames) continue
                // If the typeof target is NOT a class member, fall through to check TS2564
                // (e.g., `typeof GlobalFoo` where GlobalFoo is a declared external var)
            }

            // Get property name — only identifier-named and computed properties get TS2564
            // String/numeric literal names are excluded (TypeScript doesn't check those)
            val propName = when (val name = member.name) {
                is Identifier -> name.text
                is ComputedPropertyName -> {
                    // Computed property name — handles Symbol.X, NS.x, and simple identifiers
                    when (val expr = name.expression) {
                        is PropertyAccessExpression -> {
                            // Build the full dotted name for display (e.g. "[Symbol.iterator]", "[NS.x]")
                            fun buildDottedName(e: Expression): String? = when (e) {
                                is Identifier -> e.text
                                is PropertyAccessExpression -> {
                                    val baseName = buildDottedName(e.expression) ?: return@buildDottedName null
                                    "$baseName.${e.name.text}"
                                }
                                else -> null
                            }
                            buildDottedName(expr)?.let { "[$it]" }
                        }
                        is Identifier -> "[${expr.text}]"
                        // B98.r58: literal computed name `["a"]` / `[0]` — a late-bound
                        // stable member name TypeScript DOES check for TS2564.
                        is StringLiteralNode -> "[\"${expr.text}\"]"
                        is NumericLiteralNode -> "[${expr.text}]"
                        is BinaryExpression -> {
                            // Assignment-like inside computed name (rare, e.g. `[x = 0]`) — use source text between brackets
                            val closeIdx = source.indexOf(']', expr.pos)
                            if (closeIdx > 0) source.substring(name.pos, closeIdx + 1) else null
                        }
                        else -> null
                    }
                }
                else -> null
            } ?: continue

            // Check if assigned in constructor
            if (propName in constructorAssigned) continue

            // Emit TS2564
            val nameNode = member.name
            val start = nameNode.pos
            val length = propName.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)

            diagnostics.add(Diagnostic(
                message = "Property '$propName' has no initializer and is not definitely assigned in the constructor.",
                category = DiagnosticCategory.Error,
                code = 2564,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /**
     * Collect property names assigned in constructor body via `this.propName = ...`
     */
    private fun collectConstructorAssignments(
        statements: List<Statement>,
        assigned: MutableSet<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ExpressionStatement -> {
                    collectThisAssignment(stmt.expression, assigned)
                }
                is IfStatement -> {
                    // Only if BOTH branches assign, consider it assigned
                    // For simplicity, check both branches but don't require both
                    collectConstructorAssignments(
                        listOf(stmt.thenStatement), assigned,
                    )
                    stmt.elseStatement?.let {
                        collectConstructorAssignments(listOf(it), assigned)
                    }
                }
                // Round 479: a this-assignment nested in a var-decl INITIALIZER —
                // `const js = this.js = new SortedMap(...)` (tsc harness
                // compilerImpl.ts CompilationResult ctor) — assigns the property.
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { collectThisAssignment(it, assigned) }
                    }
                }
                is Block -> collectConstructorAssignments(stmt.statements, assigned)
                // Round 475: a ctor-body `switch` assigning the property in its clauses
                // (tsc server project.ts's serverMode switch sets languageServiceEnabled
                // in every case, with an assertNever default). Same permissive any-path
                // rule as the IfStatement arm above.
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> collectConstructorAssignments(clause.statements, assigned)
                            is DefaultClause -> collectConstructorAssignments(clause.statements, assigned)
                            else -> {}
                        }
                    }
                }
                else -> {}
            }
        }
    }

    private fun collectThisAssignment(expr: Expression, assigned: MutableSet<String>) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Equals) {
                    val left = expr.left
                    if (left is PropertyAccessExpression) {
                        val base = left.expression
                        if (base is Identifier && base.text == "this") {
                            assigned.add(left.name.text)
                        }
                    }
                    // `this.a = this.b = x` — the right side may be another assignment.
                    collectThisAssignment(expr.right, assigned)
                }
            }
            is CommaListExpression -> {
                expr.elements.forEach { collectThisAssignment(it, assigned) }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Constructor parameter references in class member initializers (TS2301/
    // TS2663) — ON THE SPINE (M0.4, round 650). The legacy driver +
    // checkConstructorParamInInitializersInStatements/-InExpr routing
    // recursion (which reached every nested class declaration/expression) is
    // DELETED; the anchors are ClassDeclaration/ClassExpression enters
    // (spineCpEnterNode) gated by the multi-state reach classifier
    // spineCpStatus/spineCpFold. The emission leaf
    // checkConstructorParamInClassMembers below — with its OWN
    // nested-scope-shadowing walk of the class's property initializers —
    // survives anchor-called.
    // -----------------------------------------------------------------------

    private fun checkConstructorParamInClassMembers(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Collect names declared in the constructor (params + var declarations in body)
        val ctorDeclaredNames = mutableSetOf<String>()
        // Subset of ctorDeclaredNames whose params have an access modifier (parameter properties).
        // For a parameter property, the name is also an instance member of the class, so when the
        // outer scope has no real binding for the name, TypeScript reports TS2663 ("Did you mean
        // the instance member 'this.X'?") instead of TS2301.
        val ctorParamPropertyNames = mutableSetOf<String>()
        val constructor = members.filterIsInstance<Constructor>().firstOrNull()
        if (constructor != null) {
            for (param in constructor.parameters) {
                collectParamDeclaredNames(param.name, ctorDeclaredNames)
                if (isParameterProperty(param)) {
                    collectParamDeclaredNames(param.name, ctorParamPropertyNames)
                }
            }
            // Collect var declarations from constructor body
            constructor.body?.let { body ->
                collectVarDeclaredNamesInBlock(body.statements, ctorDeclaredNames)
            }
        }
        if (ctorDeclaredNames.isEmpty()) return

        // Check each non-static instance property initializer
        for (member in members) {
            if (member !is PropertyDeclaration) continue
            if (ModifierFlag.Static in member.modifiers) continue // static fields are OK
            val initializer = member.initializer ?: continue
            val memberName = (member.name as? Identifier)?.text ?: continue

            // Walk the initializer expression to find identifiers matching ctor-declared names
            checkExprForCtorParamRefs(initializer, memberName, ctorDeclaredNames, ctorParamPropertyNames, source, fileName)
        }
    }

    /** Collect declared names from a parameter binding pattern. */
    private fun collectParamDeclaredNames(name: Node, result: MutableSet<String>) {
        when (name) {
            is Identifier -> if (name.text != "this") result.add(name.text)
            is ObjectBindingPattern -> name.elements.forEach { elem ->
                collectParamDeclaredNames(elem.name, result)
            }
            is ArrayBindingPattern -> name.elements.forEach { elem ->
                if (elem is BindingElement) collectParamDeclaredNames(elem.name, result)
            }
            else -> {}
        }
    }

    /** Collect var-declared names from constructor body statements (hoisted vars). */
    private fun collectVarDeclaredNamesInBlock(
        statements: List<Statement>,
        result: MutableSet<String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    if (stmt.declarationList.flags != VarKeyword) continue // only var (not let/const)
                    for (decl in stmt.declarationList.declarations) {
                        collectParamDeclaredNames(decl.name, result)
                    }
                }
                is Block -> collectVarDeclaredNamesInBlock(stmt.statements, result)
                is IfStatement -> {
                    collectVarDeclaredNamesInBlock(listOf(stmt.thenStatement), result)
                    stmt.elseStatement?.let { collectVarDeclaredNamesInBlock(listOf(it), result) }
                }
                is ForStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == VarKeyword) {
                        for (decl in init.declarations) collectParamDeclaredNames(decl.name, result)
                    }
                    collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                }
                is ForInStatement -> {
                    collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                }
                is ForOfStatement -> {
                    collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                }
                is WhileStatement -> collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                is DoStatement -> collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                is TryStatement -> {
                    collectVarDeclaredNamesInBlock(stmt.tryBlock.statements, result)
                    stmt.catchClause?.block?.statements?.let { collectVarDeclaredNamesInBlock(it, result) }
                    stmt.finallyBlock?.statements?.let { collectVarDeclaredNamesInBlock(it, result) }
                }
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> collectVarDeclaredNamesInBlock(clause.statements, result)
                            is DefaultClause -> collectVarDeclaredNamesInBlock(clause.statements, result)
                            else -> {}
                        }
                    }
                }
                is LabeledStatement -> collectVarDeclaredNamesInBlock(listOf(stmt.statement), result)
                else -> {}
            }
        }
    }

    /** True when [param] has an access/readonly modifier — i.e., is a parameter property
     * (constructor param that auto-generates a same-named instance member). */
    private fun isParameterProperty(param: Parameter): Boolean =
        ModifierFlag.Public in param.modifiers ||
        ModifierFlag.Private in param.modifiers ||
        ModifierFlag.Protected in param.modifiers ||
        ModifierFlag.Readonly in param.modifiers

    /**
     * For a ctor-param-property name shadowed inside a property initializer: does the bare
     * identifier resolve to a real outer binding (this file's own top-level locals, lib
     * KNOWN_GLOBALS, or any non-module file's top-level locals)?
     *
     * Module-file exports do NOT count — TypeScript requires explicit imports to bring those
     * into scope, but our checker conflates them into `globals` (see CLAUDE.md note on cross-
     * file global scope conflation). Without this filter, `classMemberInitializerWithLamdaScoping4`
     * would report TS2301 instead of TS2663 because file 1's `export var field1` would be
     * treated as a real outer binding for file 2's bare `field1` reference.
     */
    private fun ctorParamShadowsRealOuterBinding(name: String, currentFileName: String): Boolean {
        if (name in KNOWN_GLOBALS) return true
        // 17.32b: consult per-file scope instead of walking binderResults with an
        // ad-hoc module-file filter. The per-file scope already encodes the same
        // "lib + script-file locals + own-file locals" semantics, with other-file
        // module-file locals excluded.
        val fileScope = perFileScopeOf(currentFileName) ?: return false
        return fileScope.containsKey(name)
    }

    /**
     * Walk [expr] recursively to find any [Identifier] references matching [ctorNames].
     * When found, emit TS2301 (or TS2663 if the matched name is a parameter property AND no
     * real outer binding exists — see [ctorParamShadowsRealOuterBinding]).
     * [memberName] is the class field name used in the diagnostic message.
     */
    private fun checkExprForCtorParamRefs(
        expr: Expression,
        memberName: String,
        ctorNames: Set<String>,
        ctorParamPropertyNames: Set<String>,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is Identifier -> {
                if (expr.text in ctorNames) {
                    val start = expr.pos
                    val length = expr.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val emitTs2663 = expr.text in ctorParamPropertyNames &&
                        !ctorParamShadowsRealOuterBinding(expr.text, fileName)
                    diagnostics.add(if (emitTs2663) Diagnostic(
                        message = "Cannot find name '${expr.text}'. Did you mean the instance member 'this.${expr.text}'?",
                        category = DiagnosticCategory.Error,
                        code = 2663,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ) else Diagnostic(
                        message = "Initializer of instance member variable '$memberName' cannot reference identifier '${expr.text}' declared in the constructor.",
                        category = DiagnosticCategory.Error,
                        code = 2301,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            is BinaryExpression -> {
                // B64.3-style iterative flatten to avoid StackOverflow on deep chains.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkExprForCtorParamRefs(cur, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                while (rightStack.isNotEmpty()) checkExprForCtorParamRefs(rightStack.removeLast(), memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            }
            is CallExpression -> {
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                expr.arguments.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            }
            is NewExpression -> {
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                expr.arguments?.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            }
            is PropertyAccessExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is ElementAccessExpression -> {
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                checkExprForCtorParamRefs(expr.argumentExpression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            }
            is ParenthesizedExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is PrefixUnaryExpression ->
                checkExprForCtorParamRefs(expr.operand, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is PostfixUnaryExpression ->
                checkExprForCtorParamRefs(expr.operand, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is ConditionalExpression -> {
                checkExprForCtorParamRefs(expr.condition, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                checkExprForCtorParamRefs(expr.whenTrue, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                checkExprForCtorParamRefs(expr.whenFalse, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            }
            is ArrayLiteralExpression ->
                expr.elements.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            is ObjectLiteralExpression ->
                expr.properties.forEach { prop ->
                    when (prop) {
                        is PropertyAssignment ->
                            checkExprForCtorParamRefs(prop.initializer, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                        is ShorthandPropertyAssignment ->
                            if (prop.name.text in ctorNames) {
                                val start = prop.name.pos
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                val emitTs2663 = prop.name.text in ctorParamPropertyNames &&
                                    !ctorParamShadowsRealOuterBinding(prop.name.text, fileName)
                                diagnostics.add(if (emitTs2663) Diagnostic(
                                    message = "Cannot find name '${prop.name.text}'. Did you mean the instance member 'this.${prop.name.text}'?",
                                    category = DiagnosticCategory.Error,
                                    code = 2663,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = prop.name.text.length,
                                ) else Diagnostic(
                                    message = "Initializer of instance member variable '$memberName' cannot reference identifier '${prop.name.text}' declared in the constructor.",
                                    category = DiagnosticCategory.Error,
                                    code = 2301,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = prop.name.text.length,
                                ))
                            }
                        is SpreadAssignment ->
                            checkExprForCtorParamRefs(prop.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                        else -> {}
                    }
                }
            is ArrowFunction -> {
                // Arrow function: walk the body (recurse into inner lambdas too)
                // Local var declarations inside the body shadow outer constructor params — exclude them.
                val body = expr.body
                if (body is Block) {
                    val localVars = mutableSetOf<String>()
                    collectVarDeclaredNamesInBlock(body.statements, localVars)
                    // Also collect parameter names (they shadow ctor params in nested functions)
                    for (param in expr.parameters) collectParamDeclaredNames(param.name, localVars)
                    val innerCtorNames = if (localVars.isEmpty()) ctorNames else ctorNames - localVars
                    val innerParamProps = if (localVars.isEmpty()) ctorParamPropertyNames else ctorParamPropertyNames - localVars
                    body.statements.forEach { stmt ->
                        checkExprForCtorParamRefsInStmt(stmt, memberName, innerCtorNames, innerParamProps, source, fileName)
                    }
                } else if (body is Expression) {
                    checkExprForCtorParamRefs(body, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                }
            }
            is FunctionExpression -> {
                // Function expression body — walk it
                // Local var declarations inside the body shadow outer constructor params — exclude them.
                val bodyBlock = expr.body
                val localVars = mutableSetOf<String>()
                collectVarDeclaredNamesInBlock(bodyBlock.statements, localVars)
                // Also collect parameter names
                for (param in expr.parameters) collectParamDeclaredNames(param.name, localVars)
                val innerCtorNames = if (localVars.isEmpty()) ctorNames else ctorNames - localVars
                val innerParamProps = if (localVars.isEmpty()) ctorParamPropertyNames else ctorParamPropertyNames - localVars
                bodyBlock.statements.forEach { stmt ->
                    checkExprForCtorParamRefsInStmt(stmt, memberName, innerCtorNames, innerParamProps, source, fileName)
                }
            }
            is TemplateExpression ->
                expr.templateSpans.forEach { span ->
                    checkExprForCtorParamRefs(span.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                }
            is SpreadElement ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is TypeAssertionExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is AsExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is NonNullExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is SatisfiesExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is TaggedTemplateExpression -> {
                checkExprForCtorParamRefs(expr.tag, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { span ->
                        checkExprForCtorParamRefs(span.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                    }
                    else -> {}
                }
            }
            is AwaitExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is YieldExpression ->
                expr.expression?.let { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            is DeleteExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is VoidExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is TypeOfExpression ->
                checkExprForCtorParamRefs(expr.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is CommaListExpression ->
                expr.elements.forEach { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            // Literals, ThisExpression, SuperExpression — no identifiers
            else -> {}
        }
    }

    /** Walk a statement recursively to check for constructor param references. */
    private fun checkExprForCtorParamRefsInStmt(
        stmt: Statement,
        memberName: String,
        ctorNames: Set<String>,
        ctorParamPropertyNames: Set<String>,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is ExpressionStatement ->
                checkExprForCtorParamRefs(stmt.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
            is ReturnStatement ->
                stmt.expression?.let { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            is VariableStatement ->
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkExprForCtorParamRefs(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
                }
            is IfStatement -> {
                checkExprForCtorParamRefs(stmt.expression, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                checkExprForCtorParamRefsInStmt(stmt.thenStatement, memberName, ctorNames, ctorParamPropertyNames, source, fileName)
                stmt.elseStatement?.let { checkExprForCtorParamRefsInStmt(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            }
            is Block -> stmt.statements.forEach { checkExprForCtorParamRefsInStmt(it, memberName, ctorNames, ctorParamPropertyNames, source, fileName) }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Implicit any checking (TS7006)
    // -----------------------------------------------------------------------

    /**
     * Narrow default-mode TS7006: an unannotated `var/let/const NAME = <arrow|function-expr>`
     * whose parameter has no type, no default, no contextual type → TS7006. This is the
     * ONE TS7006 sub-shape the TypeScript compiler-test harness fires by DEFAULT (no
     * @strict / @noImplicitAny) — e.g. `arrowFunctionWithObjectLiteralBody1/2`
     * (`var v = a => <any>{}`). The full `checkImplicitAnyParameters` walker is gated on
     * noImplicitAny/strict because broadening it regresses ~19 tests (FunctionDeclaration
     * params, type-annotation walking, ambient TS7005/7008, JS files, object-literal
     * contextual-typing gaps). This focused walker fires ONLY for the unannotated-var
     * arrow/function-expression initializer shape, which a corpus scan confirms has no
     * no-flag counterexample (the lone match is a `.js` file, skipped here). It runs only
     * in PURE-default mode (when the full walker is OFF) so the two never double-emit.
     */
    private fun checkImplicitAnyDefaultVarFunctions() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val savedLocals = currentFileLocals
            currentFileLocals = result.locals
            try {
                walkVarFn7006Stmts(result.sourceFile.statements, source, fileName)
            } finally {
                currentFileLocals = savedLocals
            }
        }
    }

    private fun walkVarFn7006Stmts(stmts: List<Statement>, source: String, fileName: String) {
        for (s in stmts) walkVarFn7006Stmt(s, source, fileName)
    }

    /** B332: a parameter list that contains a zero-width MISSING-name parameter is a
     *  parse-recovered signature (reserved word in name position — reservedWords2's
     *  `m(null: string)` → params `(Missing)`, `string`): tsc reports TS7006 for every
     *  annotation-less parameter there even in default mode. Display '(Missing)' for
     *  empty names (zero-width squiggle). */
    private fun maybeEmit7006ForRecoveredParams(params: List<Parameter>, source: String, fileName: String) {
        if (params.none { p -> (p.name as? Identifier)?.let { it.text.isEmpty() && it.pos >= 0 && it.pos == it.end } == true }) return
        for (param in params) {
            if (param.type != null || param.initializer != null || param.dotDotDotToken) continue
            val name = param.name as? Identifier ?: continue
            val display = if (name.text.isEmpty()) "(Missing)" else name.text
            val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
            diagnostics.add(Diagnostic(
                message = "Parameter '$display' implicitly has an 'any' type.",
                category = DiagnosticCategory.Error,
                code = 7006,
                fileName = fileName,
                line = line,
                character = character,
                start = name.pos,
                length = name.text.length,
            ))
        }
    }

    /** strictModeReservedWordInClassDeclaration: a class constructor/method parameter
     *  NAMED with a strict-mode reserved word (`constructor(private, public, static)`)
     *  parses as a normal named param (the word is a contextual keyword, isIdentifier()
     *  true) so it escapes the missing-name TS7006 recovery above — but tsc still reports
     *  TS7006 for it in default mode (the reserved name is a parse-recovery). Squiggle: the
     *  NAME, except a parameter-property (has modifiers, `public public`) squiggles the
     *  WHOLE param. Corpus-unique gate (a reserved-word class param exists in 1 test). */
    private fun emit7006ForReservedClassParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            if (param.type != null || param.initializer != null || param.dotDotDotToken) continue
            val name = param.name as? Identifier ?: continue
            if (name.text !in STRICT_MODE_RESERVED_WORDS) continue
            val isParamProp = param.modifiers.isNotEmpty()
            val start = if (isParamProp) param.pos else name.pos
            val length = if (isParamProp) (name.pos + name.text.length) - param.pos else name.text.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Parameter '${name.text}' implicitly has an 'any' type.",
                category = DiagnosticCategory.Error, code = 7006,
                fileName = fileName, line = line, character = character,
                start = start, length = length,
            ))
        }
    }

    private fun walkVarFn7006Stmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> maybeEmit7006ForRecoveredParams(stmt.parameters, source, fileName)
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> {
                        maybeEmit7006ForRecoveredParams(m.parameters, source, fileName)
                        emit7006ForReservedClassParams(m.parameters, source, fileName)
                        // Method bodies contain the same uncontextualized shapes as
                        // top-level code (`var objLit = { equals: function (x) {…} }` in
                        // a class method — constructorWithIncompleteTypeAnnotation 83).
                        m.body?.let { walkVarFn7006Stmts(it.statements, source, fileName) }
                    }
                    is Constructor -> {
                        maybeEmit7006ForRecoveredParams(m.parameters, source, fileName)
                        emit7006ForReservedClassParams(m.parameters, source, fileName)
                        m.body?.let { walkVarFn7006Stmts(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is VariableStatement -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (decl in stmt.declarationList.declarations) {
                    val init = decl.initializer
                    if (decl.type == null && init is ObjectLiteralExpression) {
                        // Uncontextualized object literal: fn-expr property values'
                        // params are implicitly any (tsc — no contextual type).
                        walkVarFn7006Expr(init, source, fileName, emitOwn = true)
                    }
                    if (decl.type == null && (init is ArrowFunction || init is FunctionExpression)) {
                        val params = when (init) {
                            is ArrowFunction -> init.parameters
                            is FunctionExpression -> init.parameters
                        }
                        emitVarFn7006Params(params, source, fileName)
                    } else if (decl.type == null && init is TypeAssertionExpression) {
                        // `var foo = <{ (): number; }> function(a) {...}` — the assertion type
                        // supplies a CONTEXTUAL signature; fn params at index >= the contextual
                        // sig's param count get no contextual type → TS7006 (contextualTyping38).
                        // Conservative: only act when the assertion type resolves to call
                        // signatures (so the contextual arity is precise — `<any>` etc. skipped).
                        val inner = init.expression
                        val params = when (inner) {
                            is ArrowFunction -> inner.parameters
                            is FunctionExpression -> inner.parameters
                            else -> null
                        }
                        if (params != null) {
                            val ctxType = getTypeFromTypeNodeSafe(init.type)
                            val ctxArity = (ctxType as? Type.Object)?.let { t ->
                                resolveStructuredTypeMembers(t)
                                t.callSignatures?.maxOfOrNull { it.parameters.size }
                            }
                            if (ctxArity != null) {
                                emitVarFn7006Params(params.drop(ctxArity), source, fileName)
                            }
                        }
                    }
                    init?.let { walkVarFn7006Expr(it, source, fileName) }
                }
            }
            // A BARE expression-statement arrow/function-expression is never contextually
            // typed — its own unannotated params fire TS7006 (fatarrowfunctionsOptionalArgs:
            // bare/parenthesized/ternary-branch/binary-operand/any-rest-call-arg positions).
            is ExpressionStatement -> walkVarFn7006Expr(stmt.expression, source, fileName, emitOwn = true)
            is ReturnStatement -> stmt.expression?.let { walkVarFn7006Expr(it, source, fileName) }
            is Block -> walkVarFn7006Stmts(stmt.statements, source, fileName)
            is IfStatement -> {
                walkVarFn7006Stmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkVarFn7006Stmt(it, source, fileName) }
            }
            is ForStatement -> walkVarFn7006Stmt(stmt.statement, source, fileName)
            is ForInStatement -> walkVarFn7006Stmt(stmt.statement, source, fileName)
            is ForOfStatement -> walkVarFn7006Stmt(stmt.statement, source, fileName)
            is WhileStatement -> walkVarFn7006Stmt(stmt.statement, source, fileName)
            is DoStatement -> walkVarFn7006Stmt(stmt.statement, source, fileName)
            is LabeledStatement -> walkVarFn7006Stmt(stmt.statement, source, fileName)
            is TryStatement -> {
                walkVarFn7006Stmts(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { walkVarFn7006Stmts(it.statements, source, fileName) }
                stmt.finallyBlock?.let { walkVarFn7006Stmts(it.statements, source, fileName) }
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                (stmt.body as? ModuleBlock)?.let { walkVarFn7006Stmts(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    private fun walkVarFn7006Expr(expr: Expression, source: String, fileName: String, emitOwn: Boolean = false) {
        when (expr) {
            is ArrowFunction -> {
                if (emitOwn) emitVarFn7006Params(expr.parameters, source, fileName)
                when (val b = expr.body) {
                    is Block -> walkVarFn7006Stmts(b.statements, source, fileName)
                    // An EXPRESSION body in an uncontextualized position is itself
                    // uncontextualized — `(b)=>(c)=>81` fires for both b and c.
                    is Expression -> walkVarFn7006Expr(b, source, fileName, emitOwn)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                if (emitOwn) emitVarFn7006Params(expr.parameters, source, fileName)
                walkVarFn7006Stmts(expr.body.statements, source, fileName)
            }
            is ParenthesizedExpression -> walkVarFn7006Expr(expr.expression, source, fileName, emitOwn)
            is TypeAssertionExpression -> walkVarFn7006Expr(expr.expression, source, fileName)
            is ObjectLiteralExpression -> {
                // Property values of an object literal in an UNcontextualized position are
                // themselves uncontextualized — `var o = { equals: function (x) {…} }`
                // fires TS7006 for `x` (constructorWithIncompleteTypeAnnotation line 83).
                for (p in expr.properties) when (p) {
                    is PropertyAssignment -> walkVarFn7006Expr(p.initializer, source, fileName, emitOwn)
                    is SpreadAssignment -> walkVarFn7006Expr(p.expression, source, fileName, emitOwn)
                    else -> {}
                }
            }
            is ConditionalExpression -> {
                walkVarFn7006Expr(expr.condition, source, fileName, emitOwn)
                walkVarFn7006Expr(expr.whenTrue, source, fileName, emitOwn)
                walkVarFn7006Expr(expr.whenFalse, source, fileName, emitOwn)
            }
            is BinaryExpression -> {
                // Non-assignment operands stay uncontextualized (`((a)=>0) + ''`,
                // `((a)=>90) instanceof Function`); assignment RHS may pick up a
                // contextual type from the target — keep the legacy no-emit there.
                // Iterative LEFT SPINE (binderBinaryExpressionStress — deep a+b+c+…
                // chains StackOverflow naive left recursion).
                val spine = ArrayList<BinaryExpression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    spine.add(cur)
                    cur = cur.left
                }
                walkVarFn7006Expr(cur, source, fileName, emitOwn)
                for (i in spine.indices.reversed()) {
                    val node = spine[i]
                    val isAssign = node.operator == SyntaxKind.Equals ||
                        (node.operator.name.endsWith("Equals") &&
                            node.operator != SyntaxKind.EqualsEquals &&
                            node.operator != SyntaxKind.EqualsEqualsEquals &&
                            node.operator != SyntaxKind.ExclamationEquals &&
                            node.operator != SyntaxKind.ExclamationEqualsEquals &&
                            node.operator != SyntaxKind.LessThanEquals &&
                            node.operator != SyntaxKind.GreaterThanEquals)
                    // B476: an arrow/fn-expr assigned to a target whose fn-type has ≠1
                    // ARITY-APPLICABLE call signature (overloaded — e.g. `f2: { (x:string,
                    // y:number):string; <T,U>(x:T,y:U):T }`) has NO single contextual
                    // signature, so the params stay implicitly any → TS7006. tsc only
                    // intersects the overloads under strictFunctionTypes, so this is gated to
                    // default (non-strict) mode (contextualTypingWithGenericAndNonGenericSignature).
                    if (node.operator == SyntaxKind.Equals && node.left is Identifier &&
                        (node.right is ArrowFunction || node.right is FunctionExpression) && !options.strict) {
                        maybeEmit7006ForOverloadedAssignTarget(node.left, node.right, source, fileName)
                    }
                    walkVarFn7006Expr(node.right, source, fileName, if (isAssign) false else emitOwn)
                }
            }
            is CallExpression -> {
                // Call args are contextually typed by the callee's signature — emit only
                // when the callee is a local FunctionDeclaration whose every parameter is
                // `any`/`...rest: any[]` (no usable contextual param types, tsc still
                // reports TS7006 for the callback's params).
                val calleeName = (expr.expression as? Identifier)?.text
                val decl = calleeName?.let { currentFileLocals?.get(it) }
                    ?.declarations?.filterIsInstance<FunctionDeclaration>()?.firstOrNull()
                val allAny = decl != null && decl.parameters.isNotEmpty() && decl.parameters.all { p ->
                    val t = p.type
                    isAnyKeywordType(t) || (p.dotDotDotToken && t is ArrayType && isAnyKeywordType(t.elementType))
                }
                if (allAny) {
                    expr.arguments.forEach { walkVarFn7006Expr(it, source, fileName, emitOwn = true) }
                }
            }
            else -> {}
        }
    }

    /**
     * B476/B478: for an assignment `<id> = <arrow/fn-expr>`, emit TS7006 for the RHS
     * function's unannotated params when the target provides NO single contextual signature,
     * so the params are implicitly any:
     *   - target type is `any` (an untyped `let`/`var` — uncalledFunctionChecksInConditional2),
     *   - target fn-type has ≠1 arity-applicable call signature (overloaded —
     *     contextualTypingWithGenericAndNonGenericSignature).
     * Exactly one applicable signature → suppressed (the caller's legacy no-emit). Gated to
     * non-strict mode by the caller (tsc only intersects overloads under strictFunctionTypes).
     * Non-fn OBJECT targets → no emit (conservative — a non-callable target is a separate
     * assignability error and the contextual-sig question is moot).
     */
    private fun maybeEmit7006ForOverloadedAssignTarget(
        target: Identifier, rhs: Expression, source: String, fileName: String,
    ) {
        val params = when (rhs) {
            is ArrowFunction -> rhs.parameters
            is FunctionExpression -> rhs.parameters
            else -> return
        }
        if (params.none { it.type == null && it.initializer == null && !it.dotDotDotToken }) return
        val reqArity = params.count { !it.dotDotDotToken && it.initializer == null }
        val lhsType = getTypeOfExpression(target)
        if (lhsType === anyType) {
            // Untyped / `any` target provides no contextual signature → params implicitly any.
            emitVarFn7006Params(params, source, fileName)
            return
        }
        val obj = lhsType as? Type.Object ?: return
        resolveStructuredTypeMembers(obj)
        val sigs = obj.callSignatures ?: return
        if (sigs.isEmpty()) return
        val applicable = sigs.count { it.parameters.size >= reqArity }
        if (applicable != 1) emitVarFn7006Params(params, source, fileName)
    }

    private fun isAnyKeywordType(t: TypeNode?): Boolean =
        t is KeywordTypeNode && t.kind == SyntaxKind.AnyKeyword

    private fun emitVarFn7006Params(parameters: List<Parameter>, source: String, fileName: String) {
        for (param in parameters) {
            if (param.isCommentPlaceholder) continue
            if (param.type != null) continue
            if (param.initializer != null) continue
            if (param.dotDotDotToken) continue
            if (param.modifiers.any { isParameterPropertyModifier(it) }) continue
            val name = param.name as? Identifier ?: continue
            if (name.text.isEmpty() || name.text == "this") continue
            val start = name.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            // tsc's span covers the name PLUS the optional `?` token when present.
            val qExtra = if (param.questionToken) 1 else 0
            diagnostics.add(Diagnostic(
                message = "Parameter '${name.text}' implicitly has an 'any' type.",
                category = DiagnosticCategory.Error,
                code = 7006,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = name.text.length + qExtra,
            ))
        }
    }

    /**
     * Round 79i: TS7009 — `new F()` where `F` is a plain function (it has call
     * signatures but no construct signature, e.g. `function F() {}`) implicitly
     * yields type `any`. Fires under noImplicitAny/strict. FP-safe: a passing
     * noImplicitAny test that `new`s a plain function would already carry TS7009
     * in its baseline (TypeScript always emits it), so adding the check can only
     * flip-or-be-neutral. Classes (which carry a construct signature) and
     * `any`-cast targets are excluded by the pure-`Function`-symbol gate.
     */
    /**
     * TS7057: a `yield` expression in a generator FUNCTION DECLARATION lacking a
     * return-type annotation has implicit-any result type. Gated noImplicitAny/strict.
     * FP-safe subset: only FunctionDeclaration generators are flagged (they are never
     * contextually typed, unlike a generator FunctionExpression/method passed as an
     * argument or assigned to a typed variable).
     *
     * (M0.4, round 652): the pass is ON THE SPINE — the driver and the
     * walkYield7057Stmts/walkYield7057Stmt/walkYield7057Expr recursion (whose sole
     * job was to REACH every expression position while threading the downward
     * `inGen` flag) are DELETED; anchors fire at YieldExpression enters, see
     * [spineIyEnterNode] / [spineIyStatus] / [spineIyFold]. Only this emission leaf
     * survives. Squiggle = the `yield` keyword (length 5) at the expression start.
     */
    private fun emitImplicitAnyYield(pos: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "'yield' expression implicitly results in an 'any' type because its containing generator lacks a return-type annotation.",
            category = DiagnosticCategory.Error,
            code = 7057,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = 5,
        ))
    }

    private fun checkNewExprImplicitAny(expr: NewExpression, source: String, fileName: String) {
        // `new <T>Expr()` (leading type args) is a different (often parse-error) form
        // than a plain `new F()` — TypeScript parses `new <any>Test2()` as a comparison,
        // emitting TS2365/TS1109/TS2693 rather than TS7009. Skip it to avoid a spurious
        // TS7009 on the identifier target our parser recovers.
        if (!expr.leadingTypeArguments.isNullOrEmpty()) return
        val callee = expr.expression
        if (callee !is Identifier) return
        // `new <` misparse recovery: the callee is a zero-width MISSING identifier
        // (B319) — TS1109/TS2365/TS2693 own this shape, never TS7009.
        if (callee.text.isEmpty()) return
        val sym = currentFileLocals?.get(callee.text) ?: globals[callee.text] ?: return
        // Only a pure plain-function target lacks a construct signature. Classes
        // (construct sig), interfaces/vars with `new()` types, and `any` casts are
        // excluded — those either carry a construct signature or aren't function symbols.
        if (!sym.flags.hasAny(SymbolFlags.Function)) return
        if (sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)) return
        if (sym.declarations.any { it is ClassDeclaration }) return
        val start = expr.pos
        val length = (expressionTrueEnd(expr) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'new' expression, whose target lacks a construct signature, implicitly has an 'any' type.",
            category = DiagnosticCategory.Error,
            code = 7009,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check for rest parameters without type annotations. Emits TS7019.
     * Fires by default (unlike TS7006 which requires noImplicitAny/strict),
     * unless strict is explicitly false. Mirrors the TS7006 behavior for
     * parameter properties in checkParamPropsInParams.
     *
     * Note: if noImplicitAny/strict is on, checkParamsForImplicitAny (called from
     * checkImplicitAnyParameters) already emits TS7019 for rest params. To avoid
     * double-emission, skip if checkImplicitAnyParameters already ran.
     */
    private fun checkImplicitAnyRestParameters() {
        // Skip if checkImplicitAnyParameters already handled everything (avoids double-emission)
        if (options.noImplicitAny || options.strict) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            // Skip JS files — TypeScript does not check implicit any in JS files
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".mjs") || fileName.endsWith(".cjs")) continue
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkRestParamsInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkRestParamsInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    checkRestParamsForImplicitAny(stmt.parameters, source, fileName)
                    stmt.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> checkRestParamsForImplicitAny(member.parameters, source, fileName)
                            is Constructor -> checkRestParamsForImplicitAny(member.parameters, source, fileName)
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) checkRestParamsForImplicitAny(member.parameters, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkRestParamsInStatements(body.statements, source, fileName)
                        else -> {}
                    }
                }
                is Block -> checkRestParamsInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkRestParamsInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { checkRestParamsInStatements(listOf(it), source, fileName) }
                }
                is ForStatement -> checkRestParamsInStatements(listOf(stmt.statement), source, fileName)
                is ReturnStatement -> stmt.expression?.let { checkRestParamsInExpr(it, source, fileName) }
                is ExpressionStatement -> checkRestParamsInExpr(stmt.expression, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkRestParamsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkRestParamsForImplicitAny(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkRestParamsInStatements(body.statements, source, fileName)
                    is Expression -> checkRestParamsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkRestParamsForImplicitAny(expr.parameters, source, fileName)
                checkRestParamsInStatements(expr.body.statements, source, fileName)
            }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> {
                    checkRestParamsForImplicitAny(m.parameters, source, fileName)
                    m.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                }
                is Constructor -> {
                    checkRestParamsForImplicitAny(m.parameters, source, fileName)
                    m.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                }
                is GetAccessor -> m.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                is SetAccessor -> m.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                is PropertyDeclaration -> m.initializer?.let { checkRestParamsInExpr(it, source, fileName) }
                else -> {}
            }
            is ParenthesizedExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is AsExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var cur: Expression = expr
                val rightStack = ArrayDeque<Expression>()
                while (cur is BinaryExpression) { rightStack.addLast(cur.right); cur = cur.left }
                checkRestParamsInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkRestParamsInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkRestParamsInExpr(expr.condition, source, fileName)
                checkRestParamsInExpr(expr.whenTrue, source, fileName)
                checkRestParamsInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkRestParamsInExpr(expr.expression, source, fileName)
                for (a in expr.arguments) checkRestParamsInExpr(a, source, fileName)
            }
            is NewExpression -> {
                checkRestParamsInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkRestParamsInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkRestParamsInExpr(expr.expression, source, fileName)
                checkRestParamsInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (e in expr.elements) checkRestParamsInExpr(e, source, fileName)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> checkRestParamsInExpr(p.initializer, source, fileName)
                is SpreadAssignment -> checkRestParamsInExpr(p.expression, source, fileName)
                is MethodDeclaration -> {
                    checkRestParamsForImplicitAny(p.parameters, source, fileName)
                    p.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                }
                is GetAccessor -> p.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                is SetAccessor -> p.body?.let { checkRestParamsInStatements(it.statements, source, fileName) }
                else -> {}
            }
            is SpreadElement -> checkRestParamsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkRestParamsInExpr(it, source, fileName) }
            is VoidExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkRestParamsInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkRestParamsInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkRestParamsInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkRestParamsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkRestParamsInExpr(expr.tag, source, fileName)
                if (expr.template is TemplateExpression) {
                    for (span in (expr.template).templateSpans) checkRestParamsInExpr(span.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (e in expr.elements) checkRestParamsInExpr(e, source, fileName)
            else -> {}
        }
    }

    private fun checkRestParamsForImplicitAny(parameters: List<Parameter>, source: String, fileName: String) {
        // First pass: find untyped rest parameters and emit TS7019
        var hasUntypedRest = false
        for (param in parameters) {
            if (!param.dotDotDotToken) continue
            if (param.isCommentPlaceholder) continue
            if (param.type != null) continue  // has type annotation — no TS7019
            // (M3.0-gap-2) An IIFE's rest parameter is contextually typed from the call
            // arguments, so tsc reports nothing. Mirror of the gate in
            // checkParamsForImplicitAny — this is the SECOND TS7019 emitter, reached by
            // the dedicated rest-parameter walker; both must carry the rule.
            if (isImmediatelyInvokedFunctionParam(param)) continue
            val name = param.name
            if (name !is Identifier) continue
            hasUntypedRest = true
            val displayName = if (name.text.isEmpty()) "(Missing)" else name.text
            // Span covers `...name` (3 chars for `...` + name length)
            val start = name.pos - 3  // position of `...`
            val length = 3 + name.text.length
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Rest parameter '$displayName' implicitly has an 'any[]' type.",
                category = DiagnosticCategory.Error,
                code = 7019,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
        // Second pass: when there's an untyped rest param in the list, also emit TS7006
        // for any untyped regular params (e.g. `function f(...x, y)` — y gets TS7006 too).
        // This matches TypeScript's behavior when parameter syntax errors are present.
        if (hasUntypedRest) {
            for (param in parameters) {
                if (param.dotDotDotToken) continue  // already handled above
                if (param.isCommentPlaceholder) continue
                if (param.type != null) continue
                if (param.initializer != null) continue
                val name = param.name
                if (name !is Identifier || name.text.isEmpty() || name.text == "this") continue
                if (param.modifiers.any { isParameterPropertyModifier(it) }) continue  // handled separately
                // (M3.0-gap-2) contextually typed from the IIFE's call arguments.
                if (isImmediatelyInvokedFunctionParam(param)) continue
                val start = name.pos
                val length = if (param.questionToken) name.text.length + 1 else name.text.length
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Parameter '${name.text}' implicitly has an 'any' type.",
                    category = DiagnosticCategory.Error,
                    code = 7006,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    /**
     * B438e (iteratorExtraParameters / asyncIteratorExtraParameters, TS2488 / TS2504):
     * an object whose `[Symbol.iterator]` (or `[Symbol.asyncIterator]`) method REQUIRES a
     * parameter is not a valid iterable — tsc requires the iterator method to be callable
     * with no arguments (`[Symbol.iterator]()`). So every iteration position over such an
     * object — `for(-await)-of`, `yield*`, array spread `[...x]`, call-arg spread `f(...x)`
     * — fails with TS2488 (sync) / TS2504 (async) carrying the object's expando type display.
     *
     * Lives on the check spine since INV.4(b) batch 2 (collection in
     * [spineCollectObjLitVar], emission in [spineResolveDeferredIterationChecks]).
     * FP firewall: fires ONLY for an object-LITERAL-typed statement-level local
     * whose computed `[Symbol.iterator]`/`[Symbol.asyncIterator]` method has a
     * REQUIRED first parameter (non-optional, non-rest), used in an iteration
     * position by name. A valid iterable (`[Symbol.iterator]()` with no params)
     * never matches → the per-file bad map stays empty. Corpus-rare shape.
     */
    private data class BadIterInfo(
        val isAsync: Boolean, val display: String, val sym: String,
        val paramStr: String, val genType: String, val reqCount: Int,
    )

    /** Detect an object literal with a `[Symbol.(async)iterator]` method requiring a parameter. */
    private fun badIteratorDisplay(obj: ObjectLiteralExpression): BadIterInfo? {
        for (m in obj.properties) {
            if (m !is MethodDeclaration) continue
            val cpn = m.name as? ComputedPropertyName ?: continue
            val pa = cpn.expression as? PropertyAccessExpression ?: continue
            if ((pa.expression as? Identifier)?.text != "Symbol") continue
            val sym = pa.name.text
            val isAsync = sym == "asyncIterator"
            if (!isAsync && sym != "iterator") continue
            val p0 = m.parameters.firstOrNull() ?: continue
            if (p0.questionToken || p0.dotDotDotToken) continue // not required → valid iterable
            val paramStr = m.parameters.joinToString(", ") { p ->
                val nm = (p.name as? Identifier)?.text ?: "_"
                val t = p.type?.let { formatTypeForDisplay(it) } ?: if (p.dotDotDotToken) "any[]" else "any"
                (if (p.dotDotDotToken) "..." else "") + nm + (if (p.questionToken) "?" else "") + ": " + t
            }
            val reqCount = m.parameters.count { !it.questionToken && !it.dotDotDotToken }
            val yieldT = inferGeneratorYieldDisplay(m.body)
            val gen = if (isAsync) "AsyncGenerator" else "Generator"
            val genType = "$gen<$yieldT, void, unknown>"
            return BadIterInfo(isAsync, "{ [Symbol.$sym]($paramStr): $genType; }", sym, paramStr, genType, reqCount)
        }
        return null
    }

    private fun inferGeneratorYieldDisplay(body: Block?): String {
        body ?: return "any"
        val types = LinkedHashSet<String>()
        fun scan(stmts: List<Statement>) {
            for (s in stmts) when (s) {
                is ExpressionStatement -> {
                    val y = s.expression as? YieldExpression
                    if (y != null && !y.asteriskToken) y.expression?.let {
                        val t = getWidenedLiteralType(getTypeOfExpression(it))
                        types.add(typeToString(t))
                    }
                }
                is Block -> scan(s.statements)
                is IfStatement -> { scan(listOf(s.thenStatement)); s.elseStatement?.let { scan(listOf(it)) } }
                is ForStatement -> scan(listOf(s.statement))
                is ForOfStatement -> scan(listOf(s.statement))
                is ForInStatement -> scan(listOf(s.statement))
                is WhileStatement -> scan(listOf(s.statement))
                is DoStatement -> scan(listOf(s.statement))
                else -> {}
            }
        }
        scan(body.statements)
        return if (types.isEmpty()) "never" else types.joinToString(" | ")
    }

    private fun checkForOfExprNonIterable(expr: Expression, source: String, fileName: String) {
        val exprType = getTypeOfExpression(expr)
        // Determine "definitely non-iterable":
        // - Type.Intrinsic with non-string/any/never/unknown name
        // - Anonymous Type.Object with no symbol, no callSig, no construct
        //   sig (rules out function types and named interfaces)
        val display: String? = when {
            exprType is Type.Intrinsic && exprType.intrinsicName !in NON_ITERABLE_SAFE_INTRINSIC_BAILOUT -> {
                exprType.intrinsicName
            }
            exprType is Type.Object &&
                exprType !is Type.Reference &&
                exprType !is Type.Interface &&
                exprType.symbol == null &&
                exprType.callSignatures.isNullOrEmpty() &&
                exprType.constructSignatures.isNullOrEmpty() &&
                exprType.tupleElementTypes == null -> {
                typeToString(exprType)
            }
            else -> null
        } ?: return
        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
        val length = expressionTrueEnd(expr) - expr.pos
        diagnostics.add(Diagnostic(
            message = "Type '$display' is not an array type or a string type.",
            category = DiagnosticCategory.Error,
            code = 2495,
            fileName = fileName,
            line = line,
            character = character,
            start = expr.pos,
            length = length.coerceAtLeast(1),
        ))
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INV.4 — the single-pass check spine (round 514).
    //
    // ONE iterative enter/leave preorder walk per file; migrated passes become
    // per-node cases in [spineEnterNode]/[spineLeaveNode] (tsc
    // checkSourceElement-style `when` dispatch — plain private handler funs, no
    // registry indirection). Contract:
    //  - dispatched as `pass("checkSpine")` at a FIXED init position (the
    //    earliest migrated pass's slot); passes migrating in from later slots
    //    move their emissions earlier in insertion order — the stable
    //    diagnostic sort hides all but exact (start,length,code,message) ties,
    //    and each migration's corpus + listAll gates decide those;
    //  - a handler sees ALL nodes: a hand-walk's accidental under-visits
    //    (arrow bodies, class/function expressions, initializers) become
    //    visits — per migrated pass, decide widen-vs-gate by the CLAUDE.md
    //    emission-direction rule, reproducing descent gates via parent-chain
    //    checks where the old walk's narrowness was an FP firewall;
    //  - the walk is EXPLICIT-STACK iterative (checks can run off the
    //    deep-stack thread; 10k-term binary chains exist).
    private fun checkSpine() {
        // Per-handler activation gates, computed once per run. (The TS2669/TS2670
        // global-augmentation handler is unconditional — it also covers .d.ts —
        // so since batch 1 the walk always runs; per-handler gates carry the
        // option/file-kind conditions.)
        spineAccessorModifierActive = options.defaultedTarget < ScriptTarget.ES2015
        spineReservedIfaceParamsActive =
            !options.strictExplicitlyFalse && !(options.noImplicitAny || options.strict)
        // TS2495 fires only when @lib EXPLICITLY excludes ES2015+ iterables
        // (and never under @noLib — TS2318 owns missing globals there).
        spineForOfNonIterableActive = !options.noLib && options.lib.isNotEmpty() &&
            options.lib.none { lname ->
                lname.startsWith("es2", ignoreCase = true) ||
                    lname.equals("esnext", ignoreCase = true)
            }
        // (CHK.22) TS2488 — the ITERABILITY check. tsc reports an invalid iterable
        // only under "uplevel iteration": `getIteratedTypeOrElementType` passes its
        // errorNode to `getIterationTypesOfIterable` ONLY when
        // `languageVersion >= ES2015 && getGlobalIterableType() !== emptyGenericType`.
        // Below that (or with the ES2015+ libs excluded, or under `noLib`) the
        // array-like leg owns the position — TS2495 / TS2461 / TS2569, whose gate is
        // [spineForOfNonIterableActive] one field up. `downlevelIteration` is
        // deliberately NOT admitted: it makes tsc CONSULT the iterable protocol but
        // still passes `undefined` as the errorNode, so no diagnostic is produced.
        spineIterableOperandActive = options.defaultedTarget >= ScriptTarget.ES2015 &&
            !options.noLib && !spineForOfNonIterableActive
        spineAbstractAccessorActive = options.noImplicitAny || options.strict
        // (M0.4) round 652: the TS7057 implicit-any-yield anchors carry the
        // legacy pass's dispatch gate as a run-level flag.
        spineIyRunActive = options.noImplicitAny || options.strict
        // TS1101 fires unless alwaysStrict is EXPLICITLY false (the old
        // checkWithStatements gate).
        spineWithStrictActive = options.alwaysStrict != false
        // INV.4(c)(iii): the unresolved-names file roots are built at THIS slot
        // (shared with the legacy walk) — the type-lib strip they consult is
        // computed here instead of at its later pass (pure split; the TS2688
        // emission stays at checkTypeLibraryEntryPoints).
        computeTypeLibResolution()
        // INV.4(d) walker 2: the arithmetic pass's run-entry state — the base
        // map its per-file copies start from, and its pass-private
        // currentParamBindingNames (seeded here, accumulating across files like
        // the legacy pass, never published back — the proven-inert leak).
        spineArithBase = EpochMap(currentLocalTypes)
        spineArithParamBindingNames = EpochSet(currentParamBindingNames)
        // INV.4(d) walker 8: the implicit-returns anchors run under the
        // PRE-SPINE resting ambient (the legacy pass ran outside the spine's
        // per-file currentFileLocals install) — capture it here.
        spineIrRestingLocals = currentFileLocals
        spineIrRestingParams = currentFunctionParams
        // (M0.4) round 624: the array-push pass's dispatches run under the
        // spine-entry resting currentFileLocals (its legacy slot's ambient).
        spinePdRestingLocals = currentFileLocals
        // (M0.4) round 625: the implicit-this anchors likewise — plus the
        // legacy dispatch gate (round 79h TS2454/TS2564 convention).
        spineItRestingLocals = currentFileLocals
        // (M0.4) round 626: the fn-typed-param-call anchors likewise.
        spineFpRestingLocals = currentFileLocals
        // (M0.4) round 631: the binding-pattern computed-key TS2537 emitters
        // likewise (the legacy pass never installed currentFileLocals).
        spineB94RestingLocals = currentFileLocals
        // (M0.4) round 649: the delete-operator anchors likewise
        // (checkDeleteReadonlyOperand's `currentFileLocals ?: globals`
        // class-name consult must see the legacy slot's resting value).
        spineDelRestingLocals = currentFileLocals
        spineItRunActive = options.noImplicitThis || options.strict ||
            !options.strictExplicitlyFalse
        // (M0.4) round 636: the property-init anchors' run gate (the legacy
        // dispatch gate, verbatim).
        spinePiRunActive = !options.strictExplicitlyFalse &&
            !options.strictPropertyInitializationExplicitlyFalse
        // (M0.4) round 638: the args-collision anchors' run gate (the legacy
        // slot-42 dispatch gate, verbatim: TS2396 only below ES2015, TS1215
        // only with module files).
        spineAcRunActive = options.defaultedTarget < ScriptTarget.ES2015 ||
            binderResults.any { isModuleFile(it.sourceFile.statements) && !isDtsFile(it.sourceFile.fileName) }
        // (M0.4) round 639: the evolving-empty-array scope dispatches' run
        // gate (the legacy driver gate, verbatim) + the legacy slot's
        // resting currentFileLocals (the pass ran first after checkSpine,
        // whose finally restores the pre-spine value) for the
        // type-resolving Part-2 push check.
        spineEvRunActive = (options.noImplicitAny || options.strict) &&
            !options.noImplicitAnyExplicitlyFalse
        // (M0.4) round 655: the implicit-any-`new` anchors' run gate (the
        // legacy slot-7a' dispatch gate, verbatim: TS7009 needs
        // noImplicitAny/strict explicitly — it is NOT a harness default).
        spineNaRunActive = options.noImplicitAny || options.strict
        // (M0.4) round 658: the B60.12 pass's file-level TP-scope base — its
        // legacy driver installed only currentFileLocals, inheriting whatever
        // its slot's ambient held (expected null: every installer restores).
        spineTpoRestingScope = currentTypeParamScope
        spineTpoRestingAst = currentTypeParamAstForOps
        spineEvRestingLocals = currentFileLocals
        // INV.4(d) walker 9: the const-assignment anchors' B116 param-typing
        // rebuild starts from the PRE-SPINE resting bases.
        spineCaRestingLocalTypes = currentLocalTypes
        spineCaRestingParamBindings = currentParamBindingNames
        // (cta-m3a): the TS2322-family post-filter window opens at SPINE entry
        // so the anchor-moved emissions sit inside it.
        ctaDiagnosticsBefore = diagnostics.size
        val savedLocals = currentFileLocals
        try {
            for (result in binderResults) {
                val sf = result.sourceFile
                // INV.6(6a): a partition worker walks only its assigned files —
                // the spine is per-file self-contained (per-file resets below),
                // so skipping a foreign file skips exactly that file's emissions.
                // (INC.17): a DIRECT partition read — not routed through
                // [checkedResults], so the census must be told explicitly.
                if (PassTiming.enabled) PassTiming.notePartitionRead()
                if (retainForRecheck) PassTiming.currentPass?.let { partitionReadingPasses.add(it) }
                val partitionHere = assignedFiles
                if (partitionHere != null && sf.fileName !in partitionHere) continue
                spineFileName = sf.fileName
                // (API.3): null for every file unless a caller asked for a span in
                // it, which is what keeps [spineEnterNode]'s hook to one field read.
                typeCaptureKeysCurrentFile =
                    if (typeCaptureKeysByFile.isEmpty()) null
                    else typeCaptureKeysByFile[sf.fileName]
                // (API.4a) read only once a span has already matched, so it is off
                // the per-node path entirely.
                typeCaptureMemberKeysCurrentFile =
                    if (typeCaptureMemberKeysByFile.isEmpty()) null
                    else typeCaptureMemberKeysByFile[sf.fileName]
                // (API.4b) likewise, and likewise read only after a span matched.
                typeCaptureScopeKeysCurrentFile =
                    if (typeCaptureScopeKeysByFile.isEmpty()) null
                    else typeCaptureScopeKeysByFile[sf.fileName]
                // (API.6) likewise, and likewise read only after a span matched.
                typeCaptureSignatureArgsCurrentFile =
                    if (typeCaptureSignatureArgsByFile.isEmpty()) null
                    else typeCaptureSignatureArgsByFile[sf.fileName]
                // (KIR) the one field the per-node hook reads — see
                // [captureHookCurrentFile].
                captureHookCurrentFile = typeCaptureKeysCurrentFile ?: checkedSink
                spineSource = sf.text
                spineIsDts = isDtsFile(spineFileName)
                spineIsJsLike = spineFileName.endsWith(".js") || spineFileName.endsWith(".jsx") ||
                    spineFileName.endsWith(".mjs") || spineFileName.endsWith(".cjs")
                spineFileIsModule = isModuleFile(sf.statements)
                // (cta-m3a): frames always-on — the anchors consume them.
                ctaSpineFileReset(sf)
                // (cpa-m3a): frames always-on — the anchors consume them.
                cpaSpineFileReset(sf)
                cpaM3LexicalScopes = result.lexicalScopes
                // (ccet-m2): the g3 frames — ALWAYS-ON since round 589; the
                // round-591 anchors and the round-592 retire consume them.
                ccetSpineFileReset(sf)
                ctaM3FlowGraph = result.flowGraph
                // Batch 14 per-file strict-mode flags (the deleted
                // checkStrictModeReservedWords preamble, verbatim): binding
                // strictness uses effectiveTarget, EXPRESSION strictness the
                // RAW target; an explicitly non-strict file (strict/
                // alwaysStrict false, no module/"use strict") suppresses the
                // target-derived paths AND the let/const-implies-strict
                // TS1212 shortcut (strictReservedExplicitNonStrict).
                val hasUseStrict = stmtsHaveUseStrictPrologue(sf.statements)
                val explicitNonStrict = options.alwaysStrict == false ||
                    (options.alwaysStrict != true && options.strictExplicitlyFalse)
                strictReservedExplicitNonStrict =
                    explicitNonStrict && !spineFileIsModule && !hasUseStrict
                spineStrictFileIsStrict = if (explicitNonStrict) {
                    spineFileIsModule || hasUseStrict
                } else {
                    options.effectiveTarget >= ScriptTarget.ES2015 ||
                        options.strict == true || options.alwaysStrict == true ||
                        spineFileIsModule || hasUseStrict
                }
                spineStrictFileIsExprStrict = if (explicitNonStrict) {
                    spineFileIsModule || hasUseStrict
                } else {
                    options.target >= ScriptTarget.ES2015 ||
                        options.strict == true || options.alwaysStrict == true ||
                        spineFileIsModule || hasUseStrict
                }
                spineStrictFileRealStrict = spineFileIsModule || hasUseStrict ||
                    options.strict == true || options.alwaysStrict == true
                // Batch 15 per-file await-context state (the deleted
                // checkAwaitContext preamble, verbatim): inline module
                // detection + the TS1262 top-level `await`-binding scan
                // (module files only; sets currentFileBindsAwaitTopLevel).
                spineAwaitFileIsModule = sf.statements.any { stmt ->
                    stmt is ImportDeclaration || stmt is ExportDeclaration ||
                        (stmt is ExportAssignment) ||
                        (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) ||
                        (stmt is FunctionDeclaration && ModifierFlag.Export in stmt.modifiers) ||
                        (stmt is ClassDeclaration && ModifierFlag.Export in stmt.modifiers)
                }
                currentFileBindsAwaitTopLevel = false
                if (!spineIsDts && spineAwaitFileIsModule) {
                    checkTopLevelAwaitNames(sf.statements, spineSource, spineFileName)
                }
                currentFileLocals = result.locals
                spineObjLitVars.clear()
                spineBadIterVars.clear()
                spineIterPositionIds.clear()
                spineYieldStarNodes.clear()
                spineParamForbiddenEmitted.clear()
                spineScopeAuditActive = spineScopeAuditEnabled
                spineScopeFill(result)
                spineUResSetup(result)
                spineTavSetup(result)
                spineUncalledSetup(result)
                spineArithSetup(result)
                spineIanySetup(result)
                spineDupIdSetup(result)
                spineDaSetup(result)
                spineArgSetup(result)
                spineUbdSetup(result)
                spineIrSetup(result)
                spineCaSetup(result)
                spineAtSetup(result)
                spineNuSetup(result)
                spineCmSetup(result)
                spineNpSetup(result)
                spineOsSetup(result)
                spinePdSetup(result)
                spineItSetup()
                spineFpSetup(result)
                spineAiSetup(result)
                spineSySetup(result)
                spineCoSetup(result)
                spineB94Setup(result)
                spineCeSetup(result)
                spinePmrSetup(result)
                spineGxSetup(result)
                spineAcSetup(result)
                spineEvSetup(result)
                spineUySetup(result)
                spineSrSetup(result)
                spineIaSetup(result)
                spineTdSetup(result)
                spineExSetup(result)
                spineSmSetup(result)
                spineClSetup()
                spineSuSetup(result)
                spineTcSetup(result)
                spineDelSetup(result)
                spineCpSetup(result)
                spineAbSetup(result)
                spineIySetup(result)
                spineAaSetup(result)
                spineIdcSetup(result)
                spineNaSetup(result)
                spineAfSetup(result)
                spineTpoSetup(result)
                // (M0.4) round 636: property-init anchors — active in every
                // non-dts file (the legacy driver's only file gate).
                spinePiActive = spinePiRunActive && !spineIsDts
                spineUResAuditActive = unresolvedAuditEnabled && spineUResActive
                try {
                    // (KIR) the sink's only route to the TREES a whole-program
                    // check walked; null in every other configuration, so this
                    // is one predicted null check per FILE.
                    checkedSink?.file(sf)
                    spineWalkFile(sf)
                } finally {
                    spineDupIdFinish(result)
                    spineScopeClear()
                    spineUResTeardown()
                    spineTavTeardown()
                    spineUncalledTeardown()
                    spineArithTeardown()
                    spineIanyTeardown()
                    spineDupIdTeardown()
                    spineDaTeardown()
                    spineArgTeardown()
                    spineUbdTeardown()
                    spineIrTeardown()
                    spineCaTeardown()
                    spineAtTeardown()
                    spineNuTeardown()
                    spineCmTeardown()
                    spineNpTeardown()
                    spineOsTeardown()
                    spinePdTeardown()
                    spineItTeardown()
                    spineFpTeardown()
                    spineAiTeardown()
                    spineSyTeardown()
                    spineCoTeardown()
                    spineB94Teardown()
                    spineCeTeardown()
                    spinePmrTeardown()
                    spineGxTeardown()
                    spineAcTeardown()
                    spineEvTeardown()
                    spineUyTeardown()
                    spineSrTeardown()
                    spineIaTeardown()
                    spineTdTeardown()
                    spineExTeardown()
                    spineSmTeardown()
                    spineClTeardown()
                    spineSuTeardown()
                    spineTcTeardown()
