    // -----------------------------------------------------------------------
    // Generic type argument count checking (TS2314)
    // -----------------------------------------------------------------------

    /**
     * Type parameter info: (minRequired, maxTotal, displayName).
     * minRequired = count of type params without defaults.
     * maxTotal = total type params count.
     */
    private data class TypeParamInfo(val minRequired: Int, val maxTotal: Int, val displayName: String)

    /**
     * Get type parameter info for a named type. Returns null if the type is not generic.
     */
    /** Blocker #3 (round 442): true when [fileName]'s OWN top-level Class/Interface/
     *  TypeAlias declaration of [name] is NON-generic. Such a local shadows a cross-file
     *  same-named GENERIC type (convertToAsyncFunction.ts's non-generic `interface
     *  Transformer` vs types.ts's `type Transformer<T>`), so a bare reference in that file
     *  needs no type args and must NOT trip the cross-file [getTypeParamInfo] arity scan →
     *  TS2314. AST-based so it is immune to the `mergeSymbolTable` declaration pollution
     *  (the merged `globals`/first-file `result.locals` symbol carries BOTH declarations).
     *  A same-file GENERIC declaration returns false (its real arity applies). */
    private fun fileDeclaresNonGenericType(fileName: String, name: String): Boolean =
        fileNonGenericTypeCache.getOrPut("$fileName|$name") {
            computeFileDeclaresNonGenericType(fileName, name)
        }

    private fun computeFileDeclaresNonGenericType(fileName: String, name: String): Boolean {
        // M0.3(viii): the [fileResults] index replaces the old linear
        // `binderResults.firstOrNull { fileName == }` scan (same first-match answer —
        // associateBy keeps the LAST duplicate, but program file names are unique keys).
        val result = fileResults[fileName] ?: return false
        var found = false
        for (stmt in result.sourceFile.statements) {
            val tps: List<TypeParameter>? = when (stmt) {
                is ClassDeclaration -> if (stmt.name?.text == name) stmt.typeParameters else continue
                is InterfaceDeclaration -> if (stmt.name.text == name) stmt.typeParameters else continue
                is TypeAliasDeclaration -> if (stmt.name.text == name) stmt.typeParameters else continue
                else -> continue
            }
            if (!tps.isNullOrEmpty()) return false // a same-file GENERIC decl — real arity applies
            found = true
        }
        return found
    }

    private fun getTypeParamInfo(name: String, forTypePosition: Boolean = false): TypeParamInfo? {
        // M5 (round 481): pure over (name, forTypePosition) — it scans `result.locals`
        // for EVERY binderResult twice + globals, all frozen (no `currentFileLocals`
        // context). checkTypeArgCount / isUnresolvedGenericType probe it per generic
        // reference, so the full-program double scan showed at ~1.7% self in the harness
        // JFR. Tier-2 memo; a stored `TypeParamInfo?` distinguishes "computed-null" from
        // "absent" via the two maps' presence keys.
        FrontEnd.addTpiCall()
        val cacheKey = if (forTypePosition) "T|$name" else "V|$name"
        if (typeParamInfoCache.containsKey(cacheKey)) return typeParamInfoCache[cacheKey]
        val t0 = FrontEnd.t()
        val computed = computeTypeParamInfo(name, forTypePosition)
        FrontEnd.close(FrontEnd.TPI, t0)
        FrontEnd.addTpiMiss(tpiFileProbes, tpiNsSyms, tpiNsExports, computed != null)
        typeParamInfoCache[cacheKey] = computed
        return computed
    }

    private fun computeTypeParamInfo(name: String, forTypePosition: Boolean): TypeParamInfo? {
        tpiFileProbes = 0; tpiNsSyms = 0; tpiNsExports = 0
        // Check binder symbols first (user-declared types)
        for (result in binderResults) {
            tpiFileProbes++
            val symbol = result.locals[name] ?: continue
            val info = getTypeParamInfoFromSymbol(symbol, forTypePosition)
            if (info != null) return info
            // 16.4: resolve import aliases to the underlying generic class/interface.
            // `import a = require("./C")` where `C` is `class C<T>` should report TS2314
            // as `'C<T>' requires 1 type argument(s)` (baseline uses the resolved name).
            if (symbol.flags.hasAny(SymbolFlags.Alias)) {
                val resolved = resolveAlias(symbol)
                if (resolved !== symbol) {
                    val aliasInfo = getTypeParamInfoFromSymbol(resolved, forTypePosition)
                    if (aliasInfo != null) return aliasInfo
                }
            }
        }
        // Also check namespace exports (for types declared inside namespaces).
        // (WARM.17) The `binderResults × locals` scan that used to find the
        // module symbols is hoisted into [moduleSymbolScanIndex] — the SET of
        // module symbols cannot depend on [name], only their `exports` probe
        // can, and the probe still happens here, live. Same symbols, same
        // order, same first-match.
        val moduleSymbols = moduleSymbolScanIndex()
        tpiNsSyms += moduleSymbols.size.toLong()
        for (sym in moduleSymbols) {
            tpiNsExports++
            val exported = sym.exports?.get(name)
            if (exported != null) {
                val info = getTypeParamInfoFromSymbol(exported, forTypePosition)
                if (info != null) return info
            }
        }
        val globalSymbol = globals[name]
        if (globalSymbol != null) {
            val info = getTypeParamInfoFromSymbol(globalSymbol, forTypePosition)
            if (info != null) return info
        }
        // Check known built-in generics (all required, no defaults)
        val builtin = KNOWN_GENERIC_BUILTINS[name] ?: return null
        return TypeParamInfo(builtin.first, builtin.first, builtin.second)
    }

    /**
     * Extract type parameter info from a symbol's declarations.
     * Prioritizes class/interface/type-alias over function declarations for type position checks.
     *
     * When [forTypePosition] is true (callers: 17.47's QualifiedName branch in
     * `checkTypeArgCount` and the [isUnresolvedGenericType] filter), the function-
     * declaration fall-through is skipped so a generic function symbol does NOT
     * produce a TypeParamInfo. Type-position TypeRefs to a value-only symbol
     * should resolve to TS2749 ("refers to a value"), not TS2314 ("requires N
     * type arguments"). Without this gate, `var b: A.B` where `A.B` is a
     * generic function would incorrectly emit TS2314.
     */
    private fun getTypeParamInfoFromSymbol(symbol: Symbol, forTypePosition: Boolean = false): TypeParamInfo? {
        var foundClassLike = false
        // First pass: check class/interface/type-alias declarations (higher priority for type position)
        for (decl in symbol.declarations) {
            when (decl) {
                is ClassDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size,
                            "${symbol.name}<${typeParams.joinToString(", ") { it.name.text }}>")
                    }
                }
                is InterfaceDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size,
                            "${symbol.name}<${typeParams.joinToString(", ") { it.name.text }}>")
                    }
                }
                is TypeAliasDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size, symbol.name)
                    }
                }
                else -> {}
            }
        }
        // If the symbol has a class/interface/type-alias declaration with 0 type params,
        // it shadows any global builtin with the same name — return (0, 0) to suppress TS2314.
        if (foundClassLike) return TypeParamInfo(0, 0, symbol.name)
        // Second pass: check function declarations (lower priority — only for value-position checks)
        if (forTypePosition) return null
        for (decl in symbol.declarations) {
            if (decl is FunctionDeclaration) {
                val typeParams = decl.typeParameters
                if (!typeParams.isNullOrEmpty()) {
                    val minRequired = typeParams.count { it.default == null }
                    return TypeParamInfo(minRequired, typeParams.size, symbol.name)
                }
            }
        }
        return null
    }

    /**
     * Returns true when [name] is a forward-declarable ES2015+ lib type and the active
     * compiler options exclude the lib that would provide it (either `@noLib: true` or
     * `@lib` listing only pre-es2015 entries). Used to swap TS2304 → TS2583 in type
     * position and to suppress TS2564 on properties whose type references such a name.
     */
    /**
     * B87.3 (round 73): true when the active `@lib` config provides the base-lib
     * VALUE declarations + es5-base essential global TYPES (`Boolean`, `Number`,
     * `Object`, `IArguments`, `CallableFunction`, `NewableFunction`) that live in
     * `lib.es5.d.ts`. A full non-dotted es-version lib (es3/es5/es6/es2015…/esnext)
     * is cumulative over es5 and provides them; a DOTTED sub-library
     * (`es2015.core`, `es2015.iterable`, …) provides only interface augmentations
     * for Array/String/etc., NOT the es5 base. Empty `@lib` = default full lib.
     */
    private fun libProvidesBaseValues(): Boolean {
        if (options.lib.isEmpty()) return true
        return options.lib.any {
            val l = it.lowercase()
            l == "es3" || l == "es5" || l == "es6" || l == "es7" || l == "esnext" ||
                (l.startsWith("es2") && !l.contains('.'))
        }
    }

    /** B228: does the active @lib provide the `Symbol` VALUE (`declare var Symbol`)?
     *  It lives in lib.es2015.symbol.d.ts — provided by any FULL es2015+ lib (es6 /
     *  es7 / es20xx / esnext, non-dotted) or a dotted `*.symbol*` lib. `es5` and
     *  `es2015.core` provide only the es5 wrapper TYPE. Empty @lib = full default lib.
     *  Distinct from [isLibTypeUnavailableEs2015], whose `es2015.*`-provides rule is
     *  right for forward-declarable TYPES but wrong for the Symbol value. */
    private fun libProvidesSymbolValue(): Boolean {
        if (options.noLib) return false
        if (options.lib.isEmpty()) return true
        return options.lib.any { lname ->
            val l = lname.lowercase()
            l == "es6" || l == "es7" || l == "esnext" ||
                (l.startsWith("es2") && !l.contains('.')) ||
                l.contains(".symbol")
        }
    }

    /** B237: does the active @lib provide the `Promise` VALUE (`declare var Promise`)?
     *  It lives in lib.es2015.promise.d.ts — provided by any FULL es2015+ lib or a
     *  dotted `*.promise` lib. `es5` provides only the Promise TYPE. */
    private fun libProvidesPromiseValue(): Boolean {
        if (options.noLib) return false
        if (options.lib.isEmpty()) return true
        return options.lib.any { lname ->
            val l = lname.lowercase()
            l == "es6" || l == "es7" || l == "esnext" ||
                (l.startsWith("es2") && !l.contains('.')) ||
                l.contains(".promise")
        }
    }

    /** B237: does the active lib config provide the global [name] introduced at [intro]?
     *  Empty @lib = the DEFAULT lib derives from the target (lib.es5+dom for es5, …), so
     *  availability is `options.defaultedTarget >= intro` — [CompilerOptions.defaultedTarget], NOT the
     *  raw target, because an UNSET target is tsc's LATEST standard and not `ES3`
     *  ((CHK.17) round 944). An explicit @lib provides the name via a cumulative full
     *  es-version >= intro or the name's dotted home sub-library. */
    private fun libProvidesGlobalAt(name: String, intro: ScriptTarget): Boolean {
        if (options.noLib) return false
        if (options.lib.isEmpty()) return options.defaultedTarget >= intro
        val introNum = intro.name.removePrefix("ES").toIntOrNull() ?: return true
        return options.lib.any { l0 ->
            val l = l0.lowercase()
            val full = when {
                l == "es6" -> 2015
                l == "es7" -> 2016
                l == "esnext" -> 9999
                l.startsWith("es2") && '.' !in l -> l.removePrefix("es").toIntOrNull() ?: 0
                else -> 0
            }
            full >= introNum || dottedLibProvidesGlobal(l, name)
        }
    }

    /** B239: TS2583 lib-migration suggestion ("es2015".."esnext") for a global [name]
     *  the active lib config does not provide, or null when the name is available.
     *  Callers must apply their own user-declaration shadow gates. */
    private fun libUnavailableGlobalSuggestion(name: String): String? {
        if (isLibTypeUnavailableEs2015(name)) return "es2015"
        val intro = LIB_GLOBAL_INTRODUCING[name] ?: return null
        if (libProvidesGlobalAt(name, intro)) return null
        return intro.name.lowercase()
    }

    /** B238: is a lib FEATURE introduced at [intro] available under the active config?
     *  Empty @lib → the default lib derives from the target (`options.defaultedTarget >= intro`
     *  — [CompilerOptions.defaultedTarget], NOT the raw target: an UNSET target is tsc's LATEST
     *  standard, not `ES3`, (CHK.17) round 944).
     *  Explicit @lib → any entry whose BASE es-version (dotted entries count their
     *  prefix level — conservative towards suppression) is >= intro provides it. */
    private fun libFeatureAvailable(intro: ScriptTarget): Boolean {
        if (options.noLib) return false
        if (options.lib.isEmpty()) return options.defaultedTarget >= intro
        val introNum = if (intro == ScriptTarget.ESNext) 9999
            else intro.name.removePrefix("ES").toIntOrNull() ?: return true
        return options.lib.any { l0 ->
            val l = l0.lowercase()
            val base = when {
                l == "es6" -> 2015
                l == "es7" -> 2016
                l == "esnext" -> 9999
                l.startsWith("es2") -> l.substringBefore('.').removePrefix("es").toIntOrNull() ?: 0
                else -> 0
            }
            base >= introNum
        }
    }

    private fun dottedLibProvidesGlobal(lib: String, name: String): Boolean {
        if ('.' !in lib) return false
        return when (name) {
            "Reflect" -> lib.endsWith(".reflect")
            "Atomics", "SharedArrayBuffer" -> lib.endsWith(".sharedmemory")
            "AsyncGenerator", "AsyncGeneratorFunction" -> lib.endsWith(".asyncgenerator")
            "AsyncIterable", "AsyncIterableIterator" -> lib.contains(".asynciterable")
            "BigInt", "BigInt64Array", "BigUint64Array" -> lib.endsWith(".bigint")
            else -> false
        }
    }

    private fun isLibTypeUnavailableEs2015(name: String): Boolean {
        if (name !in FORWARD_DECLARABLE_LIB_TYPES_ES2015) return false
        // B237: the Promise and Symbol TYPES live in lib.es5.d.ts (PromiseLike support /
        // the Symbol wrapper), so a type-position reference is ALWAYS resolvable — only
        // their VALUES are es2015+ (TS2585 via libProvidesSymbolValue/libProvidesPromiseValue).
        if (name == "Promise" || name == "Symbol") return false
        if (options.noLib) return true
        if (options.lib.isEmpty()) return false
        return options.lib.none { lname ->
            val lower = lname.lowercase()
            // es6/es2015 alias, the legacy es7 (=es2016) alias, plus any es2*/esnext
            // entry. es7/es2016+ libs are cumulative over es2015, so Promise et al.
            // are available — without the es7 case, `@lib: dom, es7` FP-emits TS2583.
            lower == "es6" || lower == "es2015" || lower == "es7" ||
                lower.startsWith("es2") || lower == "esnext" ||
                lower.startsWith("es6.") || lower.startsWith("es2015.") ||
                lower.startsWith("es7.")
        }
    }

    /**
     * Returns true when [type] (or any nested type reference) names a forward-declarable
     * ES2015+ lib type that the active lib config doesn't provide. Used by TS2564 emission
     * to suppress on `member: Map<string,number>` under `@noLib`/restricted-lib (TS2583
     * already fires at the type-name position; TS2564 would be a duplicate diagnostic
     * about an effective error type).
     */
    private fun typeContainsUnavailableLibName(type: TypeNode?): Boolean {
        if (type == null) return false
        when (type) {
            is TypeReference -> {
                val nm = (type.typeName as? Identifier)?.text
                if (nm != null && isLibTypeUnavailableEs2015(nm)) return true
                type.typeArguments?.forEach { if (typeContainsUnavailableLibName(it)) return true }
            }
            is ArrayType -> if (typeContainsUnavailableLibName(type.elementType)) return true
            is UnionType -> type.types.forEach { if (typeContainsUnavailableLibName(it)) return true }
            is IntersectionType -> type.types.forEach { if (typeContainsUnavailableLibName(it)) return true }
            is TupleType -> type.elements.forEach { if (typeContainsUnavailableLibName(it)) return true }
            else -> {}
        }
        return false
    }

    /**
     * Check if a type annotation is a bare generic type reference that would trigger TS2314.
     * Used to suppress false-positive TS2564 on error types.
     */
    private fun isUnresolvedGenericType(type: TypeNode?): Boolean {
        if (type !is TypeReference) return false
        val typeName = type.typeName
        val name: String
        val forTypePosition: Boolean
        when (typeName) {
            is Identifier -> {
                name = typeName.text
                forTypePosition = false  // legacy behavior preserved for Identifier branch
            }
            // 17.46b: also accept QualifiedName so `var b: A.B` is filtered when
            // `B` (last segment) resolves to a generic class/interface missing
            // type args. Conservative — `getTypeParamInfo` walks namespace exports
            // by simple name, so a same-named generic in any namespace can match;
            // worst case we OVER-suppress (miss a legitimate TS2454/TS2564), never
            // emit a wrong diagnostic.
            // 17.47-fix: `forTypePosition = true` so generic FUNCTIONS aren't matched
            // (those should resolve to TS2749, not TS2314 — see `genericFunduleInModule`).
            is QualifiedName -> {
                name = (typeName.right).text
                forTypePosition = true
            }
            else -> return false
        }
        val info = getTypeParamInfo(name, forTypePosition) ?: return false
        if (info.maxTotal == 0) return false // non-generic local type → TS2315, not TS2314
        if (info.minRequired != info.maxTotal) return false
        val providedCount = type.typeArguments?.size ?: 0
        return providedCount != info.maxTotal
    }

    /**
     * Check type argument count for a TypeReference node.
     * Emits TS2314: "Generic type 'X' requires N type argument(s)."
     * Only fires when all type params are required (no defaults).
     * Types with default type params need TS2707 (different code) — skipped.
     */
    private fun checkTypeArgCount(
        typeRef: TypeReference,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val typeName = typeRef.typeName
        val name: String
        val forTypePosition: Boolean
        // 17.47: also accept QualifiedName so `var b: A.B` (where `B` is a
        // generic class missing type args) emits TS2314 at the right position.
        // Skips scope/keyword/type-param checks for QualifiedName because
        // the namespace-walk in `getTypeParamInfo` is the resolution path —
        // `scope.has(name)` would only check the simple name in the current
        // scope. Conservative: a same-named generic in any namespace can match,
        // but worst case we emit TS2314 at a position that the baseline
        // doesn't expect (caller test fails differently); not a wrong-name
        // diagnostic since `info.displayName` is the resolved symbol's display.
        // 17.47-fix: `forTypePosition = true` for QualifiedName so generic
        // FUNCTIONS aren't matched (those resolve to TS2749 in TypeScript —
        // see `genericFunduleInModule_ts`).
        when (typeName) {
            is Identifier -> {
                name = typeName.text
                forTypePosition = false  // legacy behavior preserved for Identifier branch
                // Only check if the name actually resolves (skip if it would be TS2304)
                if (name.isEmpty()) return
                if (name[0] !in 'A'..'Z' && name[0] !in 'a'..'z' && name[0] != '_' && name[0] != '$') return
                if (name in KEYWORD_IDENTIFIERS) return
                if (!scope.has(name)) return
                // Type parameters cannot trigger TS2314 — they are not generic type constructors
                if (scope.isTypeParam(name)) return
                // B239: a lib-unavailable global (TS2583 "change your target library"
                // fires at the same position) is treated as unresolved by TypeScript —
                // no arity check on top (e.g. `AsyncGenerator<any>` under @lib: es2015).
                if (libUnavailableGlobalSuggestion(name) != null &&
                    currentFileLocals?.get(name) == null &&
                    globals[name]?.declarations?.any { it !in builtinLibDecls } != true) return
            }
            is QualifiedName -> {
                name = (typeName.right).text
                forTypePosition = true
                if (name.isEmpty()) return
                // B480: skip the member-arity check when the qualifier's LEFTMOST segment
                // is UNRESOLVED. tsc owns that position with TS2503 ("Cannot find namespace")
                // and does NOT additionally check the member's type-arg arity against a
                // same-named lib generic. Without this guard `StrIter.Iterator` (StrIter
                // unresolved) wrongly matched the lib `Iterator<T>` → spurious TS2314
                // (recursiveConditionalCrash4). Mirrors the TS2503 resolution gate
                // (`scope.has(name)`, line ~20803).
                var leftmost: Node = typeName.left
                while (leftmost is QualifiedName) leftmost = leftmost.left
                val leftName = (leftmost as? Identifier)?.text
                if (leftName != null && leftName.isNotEmpty() &&
                    (leftName[0] in 'A'..'Z' || leftName[0] in 'a'..'z' || leftName[0] == '_' || leftName[0] == '$') &&
                    leftName !in KEYWORD_IDENTIFIERS && !scope.has(leftName)) return
                // `SyntaxKind.ThisType` / `TypeMapKind.Array` — the RIGHT segment of an
                // ENUM-qualified name is an enum MEMBER (a numeric-literal type), NOT the
                // same-named generic lib type (`ThisType<T>` / `Array<T>`). Skip the arity
                // check (FP-safe: an enum member is never a generic type constructor).
                // INV.3(d): node-keyed fallback — the pass can run with
                // currentFileLocals unset, and the retired merge no longer holds
                // module-file enums in `globals`.
                val directLeftNode = typeName.left as? Identifier
                if (directLeftNode != null) {
                    val leftSym = currentFileLocals?.get(directLeftNode.text)
                        ?: lookupPerFileForNode(directLeftNode, directLeftNode.text)
                    if (leftSym?.declarations?.any { it is EnumDeclaration } == true) return
                }
            }
            else -> return
        }

        // Blocker #3 (round 442): the current file's OWN non-generic Class/Interface/
        // TypeAlias declaration of `name` shadows a cross-file same-named GENERIC type — a
        // bare reference here needs no type args, so getTypeParamInfo's cross-file scan
        // (which finds types.ts's generic `type Transformer<T>`, ordered before this file's
        // non-generic `interface Transformer`) FP-fires TS2314 (14 on the services profile).
        // AST-based (pollution-proof; the merged `globals` symbol carries both declarations).
        if (fileDeclaresNonGenericType(fileName, name)) return

        // Look up type parameter info. (CHK.19) round 945: a BLOCK-SCOPED type alias shadowing
        // an outer/lib one wins, because [getTypeParamInfo] is a whole-program NAME scan that
        // cannot see a declaration the binder never bound (CLAUDE.md's B83.5) and would answer
        // with the lib's arity — `Generic type 'Omit' requires 2 type argument(s)` for a local
        // one-parameter `Omit`.
        val info = lexicalTypeAliasArity(typeRef, name)
            ?: getTypeParamInfo(name, forTypePosition) ?: return

        // Non-generic local types (0 type params) used with type args → TS2315, not TS2314
        if (info.maxTotal == 0) return

        val providedCount = typeRef.typeArguments?.size ?: 0

        // B498: types with default type params → TS2707 "requires between N and M" when the
        // provided count is OUTSIDE [minRequired, maxTotal] (additive — was skipped before).
        if (info.minRequired != info.maxTotal) {
            if (providedCount in info.minRequired..info.maxTotal) return
            emitTs2707BetweenArity(typeRef, typeName, name, info, source, fileName)
            return
        }

        if (providedCount == info.maxTotal) return // correct count

        // Compute squiggle position
        val start: Int
        val length: Int
        // 17.47: For QualifiedName the typeName covers the full `A.B` span; the
        // simple `name.length` (right segment only) understates the squiggle.
        // Compute the full span by summing right.text.length + (right.pos - typeName.pos).
        val nameSpan: Int = if (typeName is QualifiedName) {
            val right = typeName.right
            right.pos + right.text.length - typeName.pos
        } else {
            name.length
        }
        if (providedCount == 0 && typeRef.typeArguments == null) {
            // No type args at all — squiggle on just the name
            start = typeName.pos
            length = nameSpan
        } else if (providedCount == 0 && typeRef.typeArguments != null) {
            // Empty type arg list `<>` — squiggle covers `Name<>`
            start = typeName.pos
            val ltIdx = srcIndexOf(source, "<>", start)
            length = if (ltIdx >= 0) ltIdx + 2 - start else nameSpan
        } else {
            // Wrong count — squiggle on the entire type reference including <args>
            start = typeName.pos
            val lastArgEnd = typeRef.typeArguments!!.last().end
            val gtIdx = source.indexOf('>', lastArgEnd - 1)
            length = if (gtIdx >= 0) gtIdx + 1 - start else nameSpan
        }

        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
            category = DiagnosticCategory.Error,
            code = 2314,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * B498: TS2707 "Generic type 'X<...>' requires between N and M type arguments." for a
     * TypeReference to a generic type WITH defaults whose provided type-arg count is outside
     * [minRequired, maxTotal]. Squiggle mirrors the TS2314 wrong-count position logic.
     */
    private fun emitTs2707BetweenArity(
        typeRef: TypeReference, typeName: Node, name: String, info: TypeParamInfo,
        source: String, fileName: String,
    ) {
        val providedCount = typeRef.typeArguments?.size ?: 0
        val nameSpan: Int = if (typeName is QualifiedName) {
            val right = typeName.right
            right.pos + right.text.length - typeName.pos
        } else name.length
        val start = typeName.pos
        val length: Int = when {
            providedCount == 0 && typeRef.typeArguments == null -> nameSpan
            providedCount == 0 -> {
                val ltIdx = srcIndexOf(source, "<>", start)
                if (ltIdx >= 0) ltIdx + 2 - start else nameSpan
            }
            else -> {
                val lastArgEnd = typeRef.typeArguments!!.last().end
                val gtIdx = source.indexOf('>', lastArgEnd - 1)
                if (gtIdx >= 0) gtIdx + 1 - start else nameSpan
            }
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Generic type '${info.displayName}' requires between ${info.minRequired} and ${info.maxTotal} type arguments.",
            category = DiagnosticCategory.Error, code = 2707,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    /**
     * Check type argument count for an ExpressionWithTypeArguments in heritage clauses.
     * Emits TS2314 when extends/implements clause uses wrong number of type args.
     * Only fires when all type params are required (no defaults).
     */
    /**
     * indexSignatureInOtherFile (piece A): true when [name] is declared as a value VARIABLE
     * anywhere in the program (`declare var name: ...` / `var name = ...`). Used to suppress
     * the generic-arity TS2314 for `class C extends name` — an `extends` of a value uses its
     * construct signature (not the same-named generic interface), so no arity check applies.
     */
    private fun heritageBaseHasValueVarDecl(name: String): Boolean {
        for (result in binderResults) {
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement) {
                    for (d in stmt.declarationList.declarations) {
                        if ((d.name as? Identifier)?.text == name) return true
                    }
                }
            }
        }
        return false
    }

    private fun checkHeritageTypeArgCount(
        exprWithArgs: ExpressionWithTypeArguments,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val expression = exprWithArgs.expression
        val name = when (expression) {
            is Identifier -> expression.text
            else -> return // PropertyAccessExpression — skip
        }

        // Only check if the name resolves
        if (name.isEmpty()) return
        if (!scope.has(name)) return

        val info = getTypeParamInfo(name) ?: return

        // Non-generic local types (0 type params) used with type args → TS2315, not TS2314
        if (info.maxTotal == 0) return

        // Skip types with default type params — they need TS2707 not TS2314
        if (info.minRequired != info.maxTotal) return

        val providedCount = exprWithArgs.typeArguments?.size ?: 0
        if (providedCount == info.maxTotal) return

        val start = expression.pos
        val length: Int
        if (providedCount == 0) {
            length = name.length
        } else {
            // Squiggle covers name + <args>
            val lastArgEnd = exprWithArgs.typeArguments!!.last().end
            val gtIdx = source.indexOf('>', lastArgEnd - 1)
            length = if (gtIdx >= 0) gtIdx + 1 - start else name.length
        }

        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // In JS files, use TS8026 instead of TS2314 for heritage clauses without type args
        val isJsFile = fileName.endsWith(".js") || fileName.endsWith(".jsx")
        if (isJsFile && providedCount == 0) {
            // If a governing `@augments`/`@extends <base>` JSDoc tag precedes this class, the
            // tag SUPPLIES the type arguments — TS8026 is suppressed and checkJsDocExtendsTags
            // owns the TS2314 at the tag position instead (jsExtendsImplicitAny).
            if (hasGoverningExtendsTag(source, name, start)) return
            diagnostics.add(Diagnostic(
                message = "Expected ${info.displayName} type arguments; provide these with an '@extends' tag.",
                category = DiagnosticCategory.Error,
                code = 8026,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
                category = DiagnosticCategory.Error,
                code = 2314,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /**
     * Walk a declare namespace body to check heritage clauses for TS2314.
     * Called separately because declare namespaces skip TS2304 checking.
     */
    private fun checkHeritageClausesInDeclareNamespace(
        moduleDecl: ModuleDeclaration,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val body = moduleDecl.body
        val statements = when (body) {
            is ModuleBlock -> body.statements
            is ModuleDeclaration -> {
                checkHeritageClausesInDeclareNamespace(body, scope, source, fileName)
                return
            }
            else -> return
        }
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val classScope = scope.child()
                    stmt.typeParameters?.forEach { classScope.addTypeParam(it.name.text, it.constraint) }
                    stmt.heritageClauses?.forEach { clause ->
                        for (type in clause.types) {
                            checkHeritageTypeArgCount(type, classScope, source, fileName)
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    val ifaceScope = scope.child()
                    stmt.typeParameters?.forEach { ifaceScope.addTypeParam(it.name.text, it.constraint) }
                    stmt.heritageClauses?.forEach { clause ->
                        for (type in clause.types) {
                            checkHeritageTypeArgCount(type, ifaceScope, source, fileName)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val nsScope = buildNamespaceScope(stmt, scope, fileName)
                    checkHeritageClausesInDeclareNamespace(stmt, nsScope, source, fileName)
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // Type used as value checking (TS2693)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // Always-truthy expression checking (TS2872)
    // -----------------------------------------------------------------------

    /**
     * Check for expressions that are always truthy in logical OR and if conditions.
     * Emits TS2872 "This kind of expression is always truthy."
     */
    // ── INV.4(d) walker 10 (round 539): checkAlwaysTruthy on the spine ──
    // (Fields + the AT_* states are declared before init — see the spineAt
    // field block. The per-file driver and the recursion walkers
    // checkAlwaysTruthyInStatements/-InStatement/-InExpr are deleted; the
    // bounded leaf utilities — isAlwaysTruthyExpr/isAlwaysFalsyExpr/
    // isAlwaysTruthyForOrExpr, scanForNotFalsy, checkVoidConditionTruthiness,
    // checkEnumReferenceFalsyCondition, checkAlwaysTruthyCondition, the
    // emitters — are retained.)

    /** Per-file setup for the spine-hosted always-truthy pass. */
    private fun spineAtSetup(result: BinderResult) {
        spineAtActive = !spineIsDts
        if (!spineAtActive) {
            spineAtReachMemo = ByteArray(0)
            return
        }
        val n = result.sourceFile.nodeCount
        spineAtReachMemo = if (n > 0) ByteArray(n) else ByteArray(0)
    }

    private fun spineAtTeardown() {
        spineAtActive = false
        spineAtReachMemo = ByteArray(0)
    }

    /** Per-node ENTER hook: the condition/operand anchors. */
    private fun spineAtEnterNode(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.IF_STATEMENT -> { node as IfStatement; spineAtIfEnter(node) }
            NodeKind.WHILE_STATEMENT -> {
                node as WhileStatement
                if (spineAtStatus(node) == AT_STMT) {
                    scanForNotFalsy(node.expression, spineSource, spineFileName)
                    checkVoidConditionTruthiness(node.expression, spineSource, spineFileName)
                }
            }
            NodeKind.DO_STATEMENT -> {
                node as DoStatement
                if (spineAtStatus(node) == AT_STMT) {
                    scanForNotFalsy(node.expression, spineSource, spineFileName)
                    checkVoidConditionTruthiness(node.expression, spineSource, spineFileName)
                }
            }
            NodeKind.FOR_STATEMENT -> {
                node as ForStatement
                if (spineAtStatus(node) == AT_STMT) {
                    node.condition?.let { checkVoidConditionTruthiness(it, spineSource, spineFileName) }
                }
            }
            NodeKind.BINARY_EXPRESSION -> { node as BinaryExpression; spineAtBinaryEnter(node) }
            NodeKind.CONDITIONAL_EXPRESSION -> {
                node as ConditionalExpression
                if (spineAtStatus(node) == AT_EXPR) {
                    if (isAlwaysFalsyExpr(node.condition)) {
                        emitTS2873(node.condition, spineSource, spineFileName)
                    } else if (isAlwaysTruthyForOrExpr(node.condition)) {
                        // tsc checkTruthinessOfType covers `?:` conditions too — an
                        // always-truthy syntactic shape fires TS2872.
                        emitTS2872(node.condition, spineSource, spineFileName)
                    }
                    checkEnumReferenceFalsyCondition(node.condition, spineSource, spineFileName)
                }
            }
            NodeKind.PREFIX_UNARY_EXPRESSION -> {
                node as PrefixUnaryExpression
                if (node.operator == SyntaxKind.Exclamation && spineAtStatus(node) == AT_EXPR &&
                    isAlwaysFalsyExpr(node.operand)
                ) {
                    // The operand of a logical-not `!` is in a truthiness-test
                    // position, so an always-falsy operand fires TS2873.
                    emitTS2873(node.operand, spineSource, spineFileName)
                }
            }
            else -> {}
        }
    }

    /**
     * The per-if condition anchor — the deleted IfStatement arm + its manual
     * else-if chain loop, per chain node: falsy → TS2873, the nested-`!` scan,
     * the TS1345 void-call check, and — for a chain LINK whose PRECEDING
     * condition(s) include an always-truthy one (the legacy prevTruthy,
     * pull-derived from the elseStatement ancestor links) — the
     * always-truthy-because-unreachable TS2872, then the TS2845 enum check.
     */
    private fun spineAtIfEnter(stmt: IfStatement) {
        if (spineAtStatus(stmt) != AT_STMT) return
        if (isAlwaysFalsyExpr(stmt.expression)) {
            emitTS2873(stmt.expression, spineSource, spineFileName)
        }
        scanForNotFalsy(stmt.expression, spineSource, spineFileName)
        checkVoidConditionTruthiness(stmt.expression, spineSource, spineFileName)
        var cur: Node = stmt
        var p = (cur as NodeBase).parent
        var prevTruthy = false
        while (p is IfStatement && p.elseStatement === cur) {
            if (isAlwaysTruthyExpr(p.expression)) {
                prevTruthy = true
                break
            }
            cur = p
            p = (cur as NodeBase).parent
        }
        if (prevTruthy) {
            checkAlwaysTruthyCondition(stmt.expression, spineSource, spineFileName)
        }
        checkEnumReferenceFalsyCondition(stmt.expression, spineSource, spineFileName)
    }

    /** The ||/&& left-operand anchor — the deleted left-spine loop's per-node
     *  emission block: always-truthy → TS2872, always-falsy → TS2873, and the
     *  B69.11 numeric-literal `||` left (suppressed anywhere below an arrow
     *  EXPRESSION body edge — the legacy flag was never reset at nested
     *  function boundaries, so the derivation walks the FULL chain). */
    private fun spineAtBinaryEnter(expr: BinaryExpression) {
        if (expr.operator != SyntaxKind.BarBar && expr.operator != SyntaxKind.AmpersandAmpersand) return
        if (spineAtStatus(expr) != AT_EXPR) return
        if (isAlwaysTruthyForOrExpr(expr.left)) {
            emitTS2872(expr.left, spineSource, spineFileName)
        } else if (isAlwaysFalsyExpr(expr.left)) {
            emitTS2873(expr.left, spineSource, spineFileName)
        }
        if (expr.operator == SyntaxKind.BarBar && expr.left is NumericLiteralNode &&
            !spineAtInArrowExprBody(expr)
        ) {
            val v = (expr.left).text.toDoubleOrNull()
            if (v != null && v != 0.0 && !v.isNaN()) {
                emitTS2872(expr.left, spineSource, spineFileName)
            }
        }
    }

    /** B69.11 pull-derivation: is [node] anywhere below an arrow EXPRESSION
     *  body edge? (The legacy inArrowExprBody flag, set at that edge and never
     *  reset — it survives into nested function-body blocks.) */
    private fun spineAtInArrowExprBody(node: Node): Boolean {
        var cur: Node = node
        while (true) {
            val parent = (cur as NodeBase).parent ?: return false
            if (parent is ArrowFunction && parent.body === cur && cur !is Block) return true
            cur = parent
        }
    }

    /**
     * Memoized reach classifier — the deleted checkAlwaysTruthyInStatement /
     * -InExpr dispatch arms verbatim (see the AT_* states). Ascends to the
     * first memoized/terminal ancestor, then walks back down over
     * [spineAtEdge].
     */
    private fun spineAtStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.AT]++
        if (node is SourceFile) return AT_STMT
        val memo = spineAtReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.AT, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineAtChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = AT_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → NONE
            if (parent is SourceFile) { anchor = parent; anchorStatus = AT_STMT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.AT, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = AT_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == AT_NONE) AT_NONE
                else spineAtEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.AT, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.AT]++; ReachCensus.folds[ReachCensus.AT] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /**
     * The edge rules — the deleted walkers' arms verbatim. Unlisted edges are
     * NONE (the legacy quirks: if/while/do and TERNARY condition
     * SUB-expressions are checked only by the whole-expression predicates;
     * for initializers/incrementors, for-in/of and switch SUBJECT
     * expressions, heritage, and type positions are never walked).
     */
    private fun spineAtEdge(parent: Node, pStatus: Int, child: Node): Int = when (pStatus) {
        AT_STMT -> when (parent) {
            is SourceFile -> if (child is Statement) AT_STMT else AT_NONE
            is Block -> if (child is Statement) AT_STMT else AT_NONE
            is ModuleBlock -> if (child is Statement) AT_STMT else AT_NONE
            is ExpressionStatement -> if (child === parent.expression) AT_EXPR else AT_NONE
            is VariableStatement -> if (child === parent.declarationList) AT_MEMBER else AT_NONE
            is IfStatement ->
                if (child === parent.thenStatement || child === parent.elseStatement) AT_STMT
                else AT_NONE
            is ReturnStatement -> if (child === parent.expression) AT_EXPR else AT_NONE
            is FunctionDeclaration -> if (child === parent.body) AT_STMT else AT_NONE
            is ClassDeclaration ->
                if (child is MethodDeclaration || child is Constructor ||
                    child is GetAccessor || child is SetAccessor ||
                    child is PropertyDeclaration) AT_MEMBER else AT_NONE
            is ForStatement -> when {
                child === parent.condition -> AT_EXPR
                child === parent.statement -> AT_STMT
                else -> AT_NONE
            }
            is ForInStatement -> if (child === parent.statement) AT_STMT else AT_NONE
            is ForOfStatement -> if (child === parent.statement) AT_STMT else AT_NONE
            is WhileStatement -> if (child === parent.statement) AT_STMT else AT_NONE
            is DoStatement -> if (child === parent.statement) AT_STMT else AT_NONE
            is SwitchStatement -> if (child is CaseClause || child is DefaultClause) AT_MEMBER else AT_NONE
            is TryStatement -> when {
                child === parent.tryBlock || child === parent.finallyBlock -> AT_STMT
                child === parent.catchClause -> AT_MEMBER
                else -> AT_NONE
            }
            is LabeledStatement -> if (child === parent.statement) AT_STMT else AT_NONE
            is ThrowStatement -> if (child === parent.expression) AT_EXPR else AT_NONE
            is ExportAssignment -> if (child === parent.expression) AT_EXPR else AT_NONE
            is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) AT_STMT else AT_NONE
            else -> AT_NONE
        }
        AT_MEMBER -> when (parent) {
            is VariableDeclarationList -> if (child is VariableDeclaration) AT_MEMBER else AT_NONE
            is VariableDeclaration -> if (child === parent.initializer) AT_EXPR else AT_NONE
            is MethodDeclaration -> if (child === parent.body) AT_STMT else AT_NONE
            is Constructor -> if (child === parent.body) AT_STMT else AT_NONE
            is GetAccessor -> if (child === parent.body) AT_STMT else AT_NONE
            is SetAccessor -> if (child === parent.body) AT_STMT else AT_NONE
            is PropertyDeclaration -> if (child === parent.initializer) AT_EXPR else AT_NONE
            is PropertyAssignment -> if (child === parent.initializer) AT_EXPR else AT_NONE
            is SpreadAssignment -> if (child === parent.expression) AT_EXPR else AT_NONE
            is TemplateSpan -> if (child === parent.expression) AT_EXPR else AT_NONE
            is CaseClause -> if (child is Statement) AT_STMT else AT_NONE
            is DefaultClause -> if (child is Statement) AT_STMT else AT_NONE
            is CatchClause -> if (child === parent.block) AT_STMT else AT_NONE
            else -> AT_NONE
        }
        AT_EXPR -> when (parent) {
            is BinaryExpression -> if (child === parent.left || child === parent.right) AT_EXPR else AT_NONE
            is ParenthesizedExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is AsExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is SatisfiesExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is NonNullExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is TypeAssertionExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is ConditionalExpression ->
                if (child === parent.whenTrue || child === parent.whenFalse) AT_EXPR
                else AT_NONE
            is ArrowFunction -> when {
                child !== parent.body -> AT_NONE
                child is Block -> AT_STMT
                else -> AT_EXPR
            }
            is FunctionExpression -> if (child === parent.body) AT_STMT else AT_NONE
            is CallExpression ->
                if (child === parent.expression || parent.arguments.anyIdentical(child)) AT_EXPR
                else AT_NONE
            is NewExpression ->
                if (child === parent.expression || parent.arguments?.anyIdentical(child) == true) AT_EXPR
                else AT_NONE
            is PropertyAccessExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is ElementAccessExpression ->
                if (child === parent.expression || child === parent.argumentExpression) AT_EXPR
                else AT_NONE
            is ArrayLiteralExpression -> if (parent.elements.anyIdentical(child)) AT_EXPR else AT_NONE
            is ObjectLiteralExpression -> when (child) {
                is PropertyAssignment, is SpreadAssignment,
                is MethodDeclaration, is GetAccessor, is SetAccessor -> AT_MEMBER
                else -> AT_NONE
            }
            is TemplateExpression -> if (child is TemplateSpan) AT_MEMBER else AT_NONE
            is TaggedTemplateExpression -> when {
                child === parent.tag -> AT_EXPR
                child === parent.template && child is TemplateExpression -> AT_EXPR
                else -> AT_NONE
            }
            is PrefixUnaryExpression -> if (child === parent.operand) AT_EXPR else AT_NONE
            is PostfixUnaryExpression -> if (child === parent.operand) AT_EXPR else AT_NONE
            is SpreadElement -> if (child === parent.expression) AT_EXPR else AT_NONE
            is AwaitExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is YieldExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is VoidExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is DeleteExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is TypeOfExpression -> if (child === parent.expression) AT_EXPR else AT_NONE
            is CommaListExpression -> if (parent.elements.anyIdentical(child)) AT_EXPR else AT_NONE
            is ClassExpression ->
                if (child is MethodDeclaration || child is Constructor ||
                    child is GetAccessor || child is SetAccessor ||
                    child is PropertyDeclaration) AT_MEMBER else AT_NONE
            else -> AT_NONE
        }
        else -> AT_NONE
    }

    /** B378: TS1345 — a condition expression of type `void` (a void-returning CALL used in a
     *  truthiness position) cannot be tested for truthiness (typePredicateInLoop:
     *  `if (otherFunc(...))` where otherFunc returns void). Gated to CALL expressions whose
     *  resolved type is exactly the `void` intrinsic, so our incomplete inference (which
     *  defaults un-analysable returns to `any`, not `void`) cannot FP. `void x` unary
     *  conditions are owned by the TS2873 always-falsy path — no overlap (a call isn't falsy). */
    private fun checkVoidConditionTruthiness(cond: Expression, source: String, fileName: String) {
        val e = unwrapParensExpr(cond)
        if (e !is CallExpression) return
        val t = getTypeOfExpression(e)
        if (t !== voidType) return
        val start = e.pos
        val length = expressionTrueEnd(e) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "An expression of type 'void' cannot be tested for truthiness.",
            category = DiagnosticCategory.Error, code = 1345,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    /**
     * TS2845: "This condition will always return 'false'/'true'." for an enum
     * member reference whose computed value is statically falsy/truthy. Fires on
     * the condition position of `a ? b : c` when the condition is a property-
     * access chain resolving to a const- or non-const-enum member with value
     * 0 / "" (false branch) or any non-zero / non-empty literal (true branch).
     * Walks alias chains so namespace-aliased forms like
     * `Internal.WhichThing.A` (where `import Internal = My.Internal`) resolve
     * via `resolveNamePath` + `resolveAlias`.
     */
    private fun checkEnumReferenceFalsyCondition(cond: Expression, source: String, fileName: String) {
        val expr = cond as? PropertyAccessExpression ?: return
        val enumPath = getReferencePath(expr.expression) ?: return
        val memberName = expr.name.text
        val result = fileResults[fileName] ?: return
        val symbol = resolveNamePath(enumPath, result) ?: return
        val target = resolveAlias(symbol)
        if (!target.flags.hasAny(SymbolFlags.Enum)) return
        val value = enumValues[target.id]?.get(memberName) ?: return
        val isTruthy = when (value) {
            is ConstantValue.NumberValue -> value.value != 0.0 && !value.value.isNaN()
            is ConstantValue.StringValue -> value.value.isNotEmpty()
        }
        val verdict = if (isTruthy) "'true'" else "'false'"
        val start = expr.pos
        val length = expressionTrueEnd(expr) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This condition will always return $verdict.",
            category = DiagnosticCategory.Error,
            code = 2845,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun checkAlwaysTruthyCondition(expr: Expression, source: String, fileName: String) {
        if (expr is NumericLiteralNode) {
            val value = expr.text.toDoubleOrNull() ?: return
            if (value != 0.0 && !value.isNaN()) {
                emitTS2872(expr, source, fileName)
            }
        }
        if (expr is ParenthesizedExpression) {
            checkAlwaysTruthyCondition(expr.expression, source, fileName)
        }
    }

    /** Only flag simple literal expressions and function expressions to avoid false positives. */
    private fun isAlwaysTruthyExpr(expr: Expression): Boolean {
        return when (expr) {
            is StringLiteralNode -> expr.text.isNotEmpty()
            is NoSubstitutionTemplateLiteralNode -> expr.text.isNotEmpty()
            is NumericLiteralNode -> {
                val value = expr.text.toDoubleOrNull() ?: return false
                value != 0.0 && !value.isNaN()
            }
            is BigIntLiteralNode -> {
                // `1n`, `2n`, ... — truthy; `0n` — falsy.
                val raw = expr.text.removeSuffix("n")
                raw.toLongOrNull()?.let { it != 0L } ?: false
            }
            is ParenthesizedExpression -> isAlwaysTruthyExpr(expr.expression)
            is AsExpression -> isAlwaysTruthyExpr(expr.expression)
            is TypeAssertionExpression -> isAlwaysTruthyExpr(expr.expression)
            is SatisfiesExpression -> isAlwaysTruthyExpr(expr.expression)
            is NonNullExpression -> isAlwaysTruthyExpr(expr.expression)
            is ArrowFunction -> true
            is FunctionExpression -> true
            is ObjectLiteralExpression -> true
            is ArrayLiteralExpression -> true
            is ClassExpression -> true
            is RegularExpressionLiteralNode -> true
            is NewExpression -> true
            else -> false
        }
    }

    /**
     * TypeScript only flags these expression kinds in `||` contexts (LHS of ||).
     * Numeric/string literals and `new` expressions are NOT flagged in `||`.
     */
    private fun isAlwaysTruthyForOrExpr(expr: Expression): Boolean {
        return when (expr) {
            is ParenthesizedExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is AsExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is TypeAssertionExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is SatisfiesExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is NonNullExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is ArrowFunction -> true
            is FunctionExpression -> true
            is ObjectLiteralExpression -> true
            is ArrayLiteralExpression -> true
            is ClassExpression -> true
            is RegularExpressionLiteralNode -> true
            is StringLiteralNode -> expr.text.isNotEmpty()
            // Note: NumericLiteralNode and NewExpression are NOT flagged in || contexts
            else -> false
        }
    }

    /**
     * Check if an expression is always falsy (e.g. `void x`).
     * TypeScript emits TS2873 for such expressions in `if` conditions.
     */
    /**
     * Recursively emit TS2873 for any `!x` (logical not) whose operand is
     * always falsy (`void …`, `null`, `undefined`). The operand of `!` is a
     * truthiness-test position no matter where the `!` appears, so this is
     * scanned inside condition expressions (if/while/do) which the
     * always-truthy walker does not otherwise descend into. FP-safe by
     * construction: TypeScript always flags these (the operand can only ever
     * be falsy). The recursion stays inside value-transparent / operator
     * wrappers and stops at function/class boundaries.
     */
    private fun scanForNotFalsy(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is PrefixUnaryExpression -> {
                if (expr.operator == SyntaxKind.Exclamation && isAlwaysFalsyExpr(expr.operand)) {
                    emitTS2873(expr.operand, source, fileName)
                }
                scanForNotFalsy(expr.operand, source, fileName)
            }
            is BinaryExpression -> {
                // iterative left spine to avoid StackOverflow on long chains
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    scanForNotFalsy(cur.right, source, fileName)
                    cur = cur.left
                }
                scanForNotFalsy(cur, source, fileName)
            }
            is ParenthesizedExpression -> scanForNotFalsy(expr.expression, source, fileName)
            is PostfixUnaryExpression -> scanForNotFalsy(expr.operand, source, fileName)
            is ConditionalExpression -> {
                scanForNotFalsy(expr.condition, source, fileName)
                scanForNotFalsy(expr.whenTrue, source, fileName)
                scanForNotFalsy(expr.whenFalse, source, fileName)
            }
            else -> {}
        }
    }

    private fun isAlwaysFalsyExpr(expr: Expression): Boolean {
        return when (expr) {
            is VoidExpression -> true
            is ParenthesizedExpression -> isAlwaysFalsyExpr(expr.expression)
            is TypeAssertionExpression -> isAlwaysFalsyExpr(expr.expression)
            is AsExpression -> isAlwaysFalsyExpr(expr.expression)
            is SatisfiesExpression -> isAlwaysFalsyExpr(expr.expression)
            // `expr!` (non-null assertion) preserves runtime value; if the inner
            // expression is always falsy (e.g. `void 0`), `expr!` is too. Note:
            // `null!` / `undefined!` are intentionally treated as falsy here even
            // though the assertion is conceptually "not null" — the runtime value
            // is still falsy.
            is NonNullExpression -> isAlwaysFalsyExpr(expr.expression)
            is Identifier -> expr.text == "null" || expr.text == "undefined"
            else -> false
        }
    }

    private fun emitTS2873(expr: Expression, source: String, fileName: String) {
        val start = expr.pos
        // For VoidExpression, compute length from operand's true end to get correct span
        val length = when (expr) {
            is VoidExpression -> expressionTrueEnd(expr.expression) - start
            is AsExpression -> (if (expr.tightEnd > 0) expr.tightEnd else expr.type.end) - start
            else -> expressionTrueEnd(expr) - start
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This kind of expression is always falsy.",
            category = DiagnosticCategory.Error,
            code = 2873,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2872(expr: Expression, source: String, fileName: String) {
        val start = expr.pos
        // Use text length for literals to get accurate squiggle
        var length = when (expr) {
            is StringLiteralNode -> (expr.rawText?.length ?: expr.text.length) + 2 // +2 for quotes
            is NumericLiteralNode -> expr.text.length
            else -> expressionTrueEnd(expr) - start
        }
        // B277: a correct span never ends mid-whitespace (tsc spans are skipTrivia-tight);
        // trim trailing whitespace from node.end-overshoot fallbacks (e.g. a paren-wrapped
        // ClassExpression whose inner end includes the next token's leading space).
        while (length > 1 && start + length - 1 < source.length && source[start + length - 1].isWhitespace()) length--
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This kind of expression is always truthy.",
            category = DiagnosticCategory.Error,
            code = 2872,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2774: This condition will always return true since this function is
    // always defined. Did you mean to call it instead?
    //
    // Fires under strictNullChecks when a callable identifier is used as a
    // condition without being called. Walks the operands of an `||`/`??` chain
    // (TypeScript only walks LHS of those, not `&&`).
    //
    // Suppressed when:
    //   - the operand's type can be undefined/null (not "always defined")
    //   - the operand is itself a CallExpression / AwaitExpression / unary
    //   - the body of the condition references the same identifier (e.g.
    //     `if (foo) { foo() }` is intentional defined-check + call)
    // -----------------------------------------------------------------------

    // ── INV.4(d) walker 1: checkUncalledFunctionsInConditions on the spine ──
    // The recursive walkUncalledChecksInStatement(s)/walkUncalledChecksInExpression
    // walkers and the withUncalledScope/withUncalledBlockScope push/pop pair are
    // DELETED. Reach is a memoized boolean ancestor-chain classifier
    // ([spineUncalledReached] over [spineUncalledEdge] — the deleted walker's
    // exact dispatch arms, incl. the corpus quirks: switch subjects / case
    // expressions / for headers / enum initializers / param defaults unreached;
    // try/catch/finally and switch-clause statements walked WITHOUT a block
    // scope; object-literal method and class-EXPRESSION member bodies walked
    // WITHOUT a param scope or this-type). The three scope stacks are REBUILT
    // pull-based at each emission from the ancestor chain
    // ([spineUncalledWithScopes], per-owner memoized levels — the level
    // collection is position-independent: it scans only the owner's params +
    // top-level body statements, consulting the already-pushed OUTER levels,
    // exactly the state the legacy walk had at scope entry). Emissions dispatch
    // at If/While/Do/For/ExpressionStatement/ConditionalExpression/ArrowFunction
    // enters with currentFlowGraph/currentCheckFileName save-set-restore (the
    // flow graph must NOT be set walk-wide — the currentArithmeticFlowGraph
    // gotcha).

    /** One scope level of the legacy parallel stacks. */
    private class UncalledLevel(
        val shadowed: MutableSet<String>,
        val typed: MutableMap<String, Type>,
    )

    /** Per-file activation + state, called from [checkSpine]'s loop. */
    private fun spineUncalledSetup(result: BinderResult) {
        spineUncalledLevelMemo.clear()
        spineUncalledThisMemo.clear()
        spineUncalledActive = strictNullChecks && !spineIsDts
        if (!spineUncalledActive) {
            spineUncalledFlow = null
            spineUncalledReachMemo = ByteArray(0)
            return
        }
        spineUncalledFlow = result.flowGraph
        spineUncalledReachMemo = ByteArray(result.sourceFile.nodeCount)
    }

    private fun spineUncalledTeardown() {
        spineUncalledActive = false
        spineUncalledFlow = null
        spineUncalledReachMemo = ByteArray(0)
        spineUncalledLevelMemo.clear()
        spineUncalledThisMemo.clear()
    }

    /**
     * Does the deleted walker reach [child] from [parent]? Mirrors
     * walkUncalledChecksInStatement(s)/walkUncalledChecksInExpression's dispatch
     * arms exactly — every kind absent here fell to their `else` arms.
     * Member-body edges are grandparent-agnostic: an interface member's body
     * cannot exist, and the OWNER edge (class decl/expr, object literal) already
     * gates which containers admit their members.
     */
    private fun spineUncalledEdge(parent: Node, child: Node): Boolean = when (parent) {
        // ── statement dispatch ──
        is SourceFile -> child is Statement
        is IfStatement -> child === parent.expression || child === parent.thenStatement ||
            child === parent.elseStatement
        is WhileStatement -> child === parent.expression || child === parent.statement
        is DoStatement -> child === parent.expression || child === parent.statement
        // For headers (initializer/incrementor) were never walked — condition + body only.
        is ForStatement -> child === parent.condition || child === parent.statement
        is Block -> child is Statement
        is ExpressionStatement -> child === parent.expression
        is ReturnStatement -> child === parent.expression
        is VariableStatement -> child === parent.declarationList
        // For-header declaration lists die here (their parent is the for statement).
        is VariableDeclarationList -> child is VariableDeclaration && parent.parent is VariableStatement
        // Only the initializer — binding-pattern DEFAULT values were never walked.
        is VariableDeclaration -> child === parent.initializer
        is FunctionDeclaration -> child === parent.body
        is ClassDeclaration, is ClassExpression ->
            child is MethodDeclaration || child is Constructor || child is GetAccessor ||
                child is SetAccessor || child is PropertyDeclaration
        is MethodDeclaration -> child === parent.body
        is Constructor -> child === parent.body
        is GetAccessor -> child === parent.body
        is SetAccessor -> child === parent.body
        is PropertyDeclaration -> child === parent.initializer
        is ForInStatement -> child === parent.expression || child === parent.statement
        is ForOfStatement -> child === parent.expression || child === parent.statement
        // Switch subjects and case-clause EXPRESSIONS were never walked.
        is SwitchStatement -> child is CaseClause || child is DefaultClause
        is CaseClause -> child is Statement
        is DefaultClause -> child is Statement
        is TryStatement -> child is Block || child is CatchClause
        is CatchClause -> child is Block
        is ModuleDeclaration -> child is ModuleBlock
        is ModuleBlock -> child is Statement
        is LabeledStatement -> child === parent.statement
        is ThrowStatement -> child === parent.expression
        is ExportAssignment -> child === parent.expression
        // ── expression dispatch ──
        is ConditionalExpression -> child === parent.condition || child === parent.whenTrue ||
            child === parent.whenFalse
        is BinaryExpression -> true
        is ParenthesizedExpression -> child === parent.expression
        is CallExpression -> child === parent.expression || parent.arguments.anyIdentical(child)
        is NewExpression -> child === parent.expression || parent.arguments?.anyIdentical(child) == true
        // Param defaults were never walked — the body only (both body forms).
        is ArrowFunction -> child === parent.body
        is FunctionExpression -> child === parent.body
        is PropertyAccessExpression -> child === parent.expression
        is ElementAccessExpression -> child === parent.expression || child === parent.argumentExpression
        is PrefixUnaryExpression -> true
        is PostfixUnaryExpression -> true
        is SpreadElement -> child === parent.expression
        is TemplateExpression -> child is TemplateSpan
        is TemplateSpan -> child === parent.expression
        is ArrayLiteralExpression -> true
        is ObjectLiteralExpression ->
            child is PropertyAssignment || child is ShorthandPropertyAssignment ||
                child is SpreadAssignment || child is MethodDeclaration ||
                child is GetAccessor || child is SetAccessor
        // Only the initializer — computed property NAMES were never walked.
        is PropertyAssignment -> child === parent.initializer
        is ShorthandPropertyAssignment -> child === parent.objectAssignmentInitializer
        is SpreadAssignment -> child === parent.expression
        is AsExpression -> child === parent.expression
        is TypeAssertionExpression -> child === parent.expression
        is SatisfiesExpression -> child === parent.expression
        is NonNullExpression -> child === parent.expression
        is YieldExpression -> child === parent.expression
        is AwaitExpression -> child === parent.expression
        is VoidExpression -> child === parent.expression
        is DeleteExpression -> child === parent.expression
        is TypeOfExpression -> child === parent.expression
        is TaggedTemplateExpression ->
            child === parent.tag || (child === parent.template && child is TemplateExpression)
        is CommaListExpression -> true
        else -> false
    }

    /** Is [node] reached by the deleted walker? Memoized per file by nodeId
     *  (ascent collects the chain, the descent backfills — a boolean AND over
     *  edges, so one verdict serves the whole walked chain). */
    private fun spineUncalledReached(node: Node): Boolean {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.UNCALLED]++
        val memo = spineUncalledReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.UNCALLED, id)
                val m = memo[id].toInt()
                if (m != 0) return m == 1
            }
        }
        val chain = spineUncalledChain
        chain.clear()
        var cur: Node = node
        val reached: Boolean
        while (true) {
            val parent = (cur as NodeBase).parent
            if (parent == null) {
                reached = cur is SourceFile
                break
            }
            if (ReachCensus.on) ReachCensus.folds[ReachCensus.UNCALLED]++
            if (!spineUncalledEdge(parent, cur)) {
                reached = false
                break
            }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.UNCALLED, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) {
                reached = pm == 1
                break
            }
            chain.add(cur)
            cur = parent
        }
        run {
            val id = (cur as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.UNCALLED, id)
            if (id >= 0 && id < memo.size && memo[id].toInt() == 0) {
                memo[id] = if (reached) 1 else 2
            }
        }
        val fill: Byte = if (reached) 1 else 2
        for (i in chain.indices.reversed()) {
            val id = (chain[i] as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.UNCALLED, id)
            if (id >= 0 && id < memo.size) memo[id] = fill
        }
        if (ReachCensus.on) ReachCensus.misses[ReachCensus.UNCALLED]++
        chain.clear()
        return reached
    }

    /** Which Blocks got the legacy withUncalledBlockScope: those dispatched via
     *  the statement Block arm — free-standing statement positions. Function
     *  bodies (the fn level owns their locals), try/catch/finally blocks, and
     *  any other structural Block position got NO block scope. */
    private fun spineUncalledBlockHasScope(b: Block): Boolean = when (val p = b.parent) {
        is SourceFile, is ModuleBlock, is CaseClause, is DefaultClause -> true
        is Block -> true
        is IfStatement -> b === p.thenStatement || b === p.elseStatement
        is WhileStatement -> b === p.statement
        is DoStatement -> b === p.statement
        is ForStatement -> b === p.statement
        is ForInStatement -> b === p.statement
        is ForOfStatement -> b === p.statement
        is LabeledStatement -> b === p.statement
        else -> false
    }

    private fun spineUncalledLevelFor(owner: Node): UncalledLevel {
        val id = (owner as NodeBase).nodeId
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineUncalledLevelMemo[id]?.let { return it }
        val shadowed = HashSet<String>()
        val typed = HashMap<String, Type>()
        when (owner) {
            is Block -> collectUncalledTypedLocalsFromBody(owner, typed, shadowed)
            is FunctionDeclaration -> spineUncalledFnLevel(owner.parameters, owner.body, typed, shadowed)
            is FunctionExpression -> spineUncalledFnLevel(owner.parameters, owner.body, typed, shadowed)
            is ArrowFunction -> spineUncalledFnLevel(owner.parameters, owner.body as? Block, typed, shadowed)
            is MethodDeclaration -> spineUncalledFnLevel(owner.parameters, owner.body, typed, shadowed)
            is Constructor -> spineUncalledFnLevel(owner.parameters, owner.body, typed, shadowed)
            is GetAccessor -> spineUncalledFnLevel(owner.parameters, owner.body, typed, shadowed)
            is SetAccessor -> spineUncalledFnLevel(owner.parameters, owner.body, typed, shadowed)
            else -> {}
        }
        val level = UncalledLevel(shadowed, typed)
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineUncalledLevelMemo[id] = level
        return level
    }

    /** The legacy withUncalledScope collection: params (binding names + annotated
     *  types) first, then the body's top-level locals. Must run with the OUTER
     *  levels already on the stacks — the initializer-typing branch consults them. */
    private fun spineUncalledFnLevel(
        params: List<Parameter>,
        body: Block?,
        typed: MutableMap<String, Type>,
        shadowed: MutableSet<String>,
    ) {
        for (p in params) {
            collectBindingNames(p.name, shadowed)
            val pName = (p.name as? Identifier)?.text
            if (pName != null) {
                resolveUncalledParamType(p)?.let { typed[pName] = it }
            }
        }
        if (body != null) collectUncalledTypedLocalsFromBody(body, typed, shadowed)
    }

    private fun spineUncalledThisTypeFor(cls: ClassDeclaration): Type? {
        val id = (cls as NodeBase).nodeId
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0 && spineUncalledThisMemo.containsKey(id)) return spineUncalledThisMemo[id]
        val t = resolveUncalledThisType(cls)
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineUncalledThisMemo[id] = t
        return t
    }

    /**
     * Rebuild the legacy scope stacks for an emission at [anchor]: collect the
     * scope-contributing ancestors (fn-like bodies under their legacy owners,
     * statement Blocks, ClassDeclarations for the this-type — SKIPPING a class
     * whose STATIC METHOD body contains the anchor, the legacy temporary pop),
     * push levels outermost-in (each level's lazy computation sees exactly the
     * outer stack state the legacy walk had at its scope entry), run, clear.
     */
    private inline fun spineUncalledWithScopes(anchor: Node, run: () -> Unit) {
        val owners = spineUncalledOwnerBuf
        owners.clear()
        var child: Node = anchor
        var p: Node? = (anchor as NodeBase).parent
        while (p != null) {
            when {
                p is FunctionDeclaration && child === p.body -> owners.add(p)
                p is FunctionExpression && child === p.body -> owners.add(p)
                p is ArrowFunction && child === p.body -> owners.add(p)
                p is MethodDeclaration && child === p.body && p.parent is ClassDeclaration -> owners.add(p)
                p is Constructor && child === p.body && p.parent is ClassDeclaration -> owners.add(p)
                p is GetAccessor && child === p.body && p.parent is ClassDeclaration -> owners.add(p)
                p is SetAccessor && child === p.body && p.parent is ClassDeclaration -> owners.add(p)
                p is Block && spineUncalledBlockHasScope(p) -> owners.add(p)
                p is ClassDeclaration ->
                    if (!(child is MethodDeclaration && ModifierFlag.Static in child.modifiers)) {
                        owners.add(p)
                    }
                else -> {}
            }
            child = p
            p = (p as NodeBase).parent
        }
        try {
            for (i in owners.indices.reversed()) {
                when (val owner = owners[i]) {
                    is ClassDeclaration ->
                        spineUncalledThisTypeFor(owner)?.let { uncalledThisTypeStack.addLast(it) }
                    is Block -> {
                        // The legacy block scope was pushed only when non-empty
                        // (invisible to lookups either way — kept for parity).
                        val level = spineUncalledLevelFor(owner)
                        if (level.shadowed.isNotEmpty() || level.typed.isNotEmpty()) {
                            uncalledShadowedScopes.addLast(level.shadowed)
                            uncalledTypedLocalsStack.addLast(level.typed)
                        }
                    }
                    else -> {
                        val level = spineUncalledLevelFor(owner)
                        uncalledShadowedScopes.addLast(level.shadowed)
                        uncalledTypedLocalsStack.addLast(level.typed)
                    }
                }
            }
            run()
        } finally {
            uncalledShadowedScopes.clear()
            uncalledTypedLocalsStack.clear()
            uncalledThisTypeStack.clear()
        }
    }

    /** The TS2774/TS2801 emission dispatch — the node kinds the deleted walker
     *  ran checkUncalledInCondition at. The ArrowFunction case anchors the scope
     *  rebuild at the BODY so the arrow's own param level is included (the
     *  legacy emission ran inside the arrow's withUncalledScope). */
    private fun spineUncalledDispatch(node: Node) {
        if (!spineUncalledActive || !spineUncalledReached(node)) return
        val savedFlow = currentFlowGraph
        val savedCheckFile = currentCheckFileName
        currentFlowGraph = spineUncalledFlow
        currentCheckFileName = spineFileName
        try {
            when (node) {
                is IfStatement -> spineUncalledWithScopes(node) {
                    checkUncalledInCondition(node.expression, node.thenStatement, spineSource, spineFileName)
                }
                is WhileStatement -> spineUncalledWithScopes(node) {
                    checkUncalledInCondition(node.expression, node.statement, spineSource, spineFileName)
                }
                is DoStatement -> spineUncalledWithScopes(node) {
                    checkUncalledInCondition(node.expression, node.statement, spineSource, spineFileName)
                }
                is ForStatement -> {
                    val cond = node.condition
                    if (cond != null) spineUncalledWithScopes(node) {
                        checkUncalledInCondition(cond, node.statement, spineSource, spineFileName)
                    }
                }
                is ExpressionStatement -> if (isTruthinessChain(node.expression)) {
                    spineUncalledWithScopes(node) {
                        checkUncalledInCondition(
                            node.expression, null, spineSource, spineFileName,
                            inTestPosition = false,
                        )
                    }
                }
                is ConditionalExpression -> spineUncalledWithScopes(node) {
                    checkUncalledInCondition(
                        node.condition, null, spineSource, spineFileName,
                        extraBodies = listOf(node.whenTrue, node.whenFalse),
                    )
                }
                is ArrowFunction -> {
                    val body = node.body
                    if (body is Expression && isTruthinessChain(body)) {
                        spineUncalledWithScopes(body) {
                            checkUncalledInCondition(
                                body, null, spineSource, spineFileName,
                                inTestPosition = false,
                            )
                        }
                    }
                }
                else -> {}
            }
        } finally {
            currentFlowGraph = savedFlow
            currentCheckFileName = savedCheckFile
        }
    }

    private fun isUncalledShadowed(name: String): Boolean {
        for (scope in uncalledShadowedScopes) if (name in scope) return true
        return false
    }

    /** True if [expr] (after stripping parens) is a truthiness-test BinaryExpression (`&&`/`||`/`??`). */
    private fun isTruthinessChain(expr: Expression): Boolean {
        var cur: Expression = expr
        while (cur is ParenthesizedExpression) cur = cur.expression
        return cur is BinaryExpression && (cur.operator == SyntaxKind.AmpersandAmpersand || cur.operator == SyntaxKind.BarBar || cur.operator == SyntaxKind.QuestionQuestion)
    }

    private fun lookupUncalledTypedLocal(name: String): Type? {
        // `uncalledShadowedScopes` and `uncalledTypedLocalsStack` are parallel (pushed
        // and popped together), so index i refers to the same scope in both.
        for (i in uncalledTypedLocalsStack.indices.reversed()) {
            uncalledTypedLocalsStack[i][name]?.let { return it }
            // If an INNER scope SHADOWS the name (declared it locally) but we could not
            // type its initializer, STOP — the name refers to THIS binding, not an OUTER
            // scope's same-named (callable) declaration. Falling through returns the outer
            // NESTED `function <name>`'s callable type and FP's TS2774. Returning null here
            // makes the caller's `isUncalledShadowed(name)` bail (the name is shadowed).
            // e.g. tsc's emitter.ts onExit: `const shouldEmitComments = state.stack[i]`
            // (any-typed) shadows the printer-nested `function shouldEmitComments`.
            if (name in uncalledShadowedScopes[i]) return null
        }
        return null
    }

    /**
     * Compute the param-annotated type for TS2774 typed-local scope.
     * Returns null when the param is unannotated (would resolve to `any`).
     * Wraps in a union with `undefined` when the param has `?` (optional).
     */
    private fun resolveUncalledParamType(p: Parameter): Type? {
        val pType = p.type ?: return null
        val resolved = getTypeFromTypeNode(pType)
        if (resolved === errorType || resolved === anyType) return null
        if (p.questionToken) return getUnionType(listOf(resolved, undefinedType))
        return resolved
    }

    // ── INV.4(d) walker 2: checkArithmeticOperandTypes on the spine ─────────
    // The per-file pass driver is DELETED; the recursive checkArithmeticInExpr/
    // checkArithmeticInStatement(s) walkers are RETAINED as the utility for
    // checkComputedDestructKey (their only remaining caller). Reach is a
    // memoized ancestor-chain classifier over [spineArithEdge] (the legacy
    // dispatch arms verbatim). The order-dependent pass state — the per-file
    // currentLocalTypes copy with its statement-ordered recordings (which
    // deliberately LEAK across blocks/if-branches/accessor bodies, bug-compat),
    // the typeof/truthy narrowing sets, and the B475 contextualType frames —
    // is PUSH-maintained by [spineArithEnterNode]/[spineArithLeaveNode] on the
    // [spineArithFrames] LIFO (edge-triggered frames keyed on the CHILD node,
    // popped at its leave AFTER the node's own emissions run). The shared
    // checker fields are only touched inside [spineArithInstalled] around each
    // emission/recording; the pass-private currentParamBindingNames additions
    // are never published back (the proven-inert legacy leak).

    /** Per-file activation + state, called from [checkSpine]'s loop. */
    private fun spineArithSetup(result: BinderResult) {
        spineArithActive = !spineIsDts &&
            !spineFileName.endsWith(".js") && !spineFileName.endsWith(".jsx")
        if (!spineArithActive) {
            spineArithFlow = null
            spineArithReachMemo = ByteArray(0)
            return
        }
        spineArithFlow = result.flowGraph
        spineArithReachMemo = ByteArray(result.sourceFile.nodeCount)
        // The legacy per-file snapshot: copy the pass-entry map so recordings
        // never leak across files.
        spineArithLocals = HashMap(spineArithBase)
    }

    private fun spineArithTeardown() {
        spineArithActive = false
        spineArithFlow = null
        spineArithReachMemo = ByteArray(0)
        spineArithFrames.clear()
    }

    /**
     * Install the pass's ambient state into the shared checker fields around one
     * emission/recording — never walk-wide (the currentArithmeticFlowGraph
     * 78-test gotcha; other spine handlers must not see the pass's map/sets).
     * currentFileLocals is already per-file at the spine (same as the legacy
     * pass); currentTypeParamScope installs null (the legacy pass-ambient —
     * the body walk ran with the function's TP scope already restored).
     */
    private inline fun spineArithInstalled(run: () -> Unit) {
        val savedLocals = currentLocalTypes
        val savedPbn = currentParamBindingNames
        val savedCheckFile = currentCheckFileName
        val savedArithFlow = currentArithmeticFlowGraph
        val savedCtx = contextualType
        val savedTpScope = currentTypeParamScope
        currentLocalTypes = spineArithLocals
        currentParamBindingNames = spineArithParamBindingNames
        currentCheckFileName = spineFileName
        currentArithmeticFlowGraph = spineArithFlow
        contextualType = spineArithCtx
        currentTypeParamScope = null
        try {
            run()
        } finally {
            currentLocalTypes = savedLocals
            currentParamBindingNames = savedPbn
            currentCheckFileName = savedCheckFile
            currentArithmeticFlowGraph = savedArithFlow
            contextualType = savedCtx
            currentTypeParamScope = savedTpScope
        }
    }

    /**
     * Does the deleted pass driver reach [child] from [parent]? Mirrors
     * checkArithmeticInStatement(s)/checkArithmeticInExpr's dispatch arms
     * exactly — every kind absent here fell to their `else` arms (param
     * defaults, enum initializers, computed property names, object-literal
     * METHOD bodies, with-statements, JSX, decorators, heritage args).
     */
    private fun spineArithEdge(parent: Node, child: Node): Boolean = when (parent) {
        // ── statement dispatch ──
        is SourceFile -> child is Statement
        is ExpressionStatement -> child === parent.expression
        is VariableStatement -> child === parent.declarationList
        // Both VariableStatement lists and for-HEADER lists walk their
        // declarations' initializers (only the former RECORDS); for-in/for-of
        // header lists were never walked.
        is VariableDeclarationList -> child is VariableDeclaration &&
            (parent.parent is VariableStatement || parent.parent is ForStatement)
        is VariableDeclaration -> child === parent.initializer
        is ReturnStatement -> child === parent.expression
        is Block -> child is Statement
        is IfStatement -> child === parent.expression || child === parent.thenStatement ||
            child === parent.elseStatement
        is ForStatement -> child === parent.initializer || child === parent.condition ||
            child === parent.incrementor || child === parent.statement
        is ForInStatement -> child === parent.expression || child === parent.statement
        is ForOfStatement -> child === parent.expression || child === parent.statement
        is WhileStatement -> child === parent.expression || child === parent.statement
        is DoStatement -> child === parent.statement || child === parent.expression
        // Unlike the TS2774 walker, the arithmetic pass DID walk switch
        // subjects and case-clause expressions.
        is SwitchStatement -> child === parent.expression || child is CaseClause ||
            child is DefaultClause
        is CaseClause -> child === parent.expression || child is Statement
        is DefaultClause -> child is Statement
        is TryStatement -> child is Block || child is CatchClause
        is CatchClause -> child is Block
        is FunctionDeclaration -> child === parent.body
        is ClassDeclaration, is ClassExpression ->
            child is MethodDeclaration || child is Constructor || child is GetAccessor ||
                child is SetAccessor || child is PropertyDeclaration
        is MethodDeclaration -> child === parent.body
        is Constructor -> child === parent.body
        is GetAccessor -> child === parent.body
        is SetAccessor -> child === parent.body
        is PropertyDeclaration -> child === parent.initializer
        is ThrowStatement -> child === parent.expression
        is LabeledStatement -> child === parent.statement
        is ExportAssignment -> child === parent.expression
        is ModuleDeclaration -> child is ModuleBlock
        is ModuleBlock -> child is Statement
        // ── expression dispatch ──
        is BinaryExpression -> child === parent.left || child === parent.right
        is ParenthesizedExpression -> child === parent.expression
        is ConditionalExpression -> child === parent.condition || child === parent.whenTrue ||
            child === parent.whenFalse
        is CallExpression -> child === parent.expression || parent.arguments.anyIdentical(child)
        is NewExpression -> child === parent.expression || parent.arguments?.anyIdentical(child) == true
        is PropertyAccessExpression -> child === parent.expression
        is ElementAccessExpression -> child === parent.expression || child === parent.argumentExpression
        is PrefixUnaryExpression -> child === parent.operand
        is PostfixUnaryExpression -> child === parent.operand
        is ArrayLiteralExpression -> true
        // Param defaults were never walked — the body only (both body forms).
        is ArrowFunction -> child === parent.body
        is FunctionExpression -> child === parent.body
        is TemplateExpression -> child is TemplateSpan
        is TemplateSpan -> child === parent.expression
        is AsExpression -> child === parent.expression
        is TypeAssertionExpression -> child === parent.expression
        is NonNullExpression -> child === parent.expression
        is SatisfiesExpression -> child === parent.expression
        // Property VALUES and spreads only — methods/accessors/shorthands and
        // computed NAMES were never walked.
        is ObjectLiteralExpression -> child is PropertyAssignment || child is SpreadAssignment
        is PropertyAssignment -> child === parent.initializer
        is SpreadAssignment -> child === parent.expression
        is SpreadElement -> child === parent.expression
        is AwaitExpression -> child === parent.expression
        is YieldExpression -> child === parent.expression
        is DeleteExpression -> child === parent.expression
        is VoidExpression -> child === parent.expression
        is TypeOfExpression -> child === parent.expression
        is TaggedTemplateExpression -> child === parent.tag ||
            (child === parent.template && child is TemplateExpression)
        is CommaListExpression -> true
        else -> false
    }

    /** Is [node] reached by the deleted pass driver? Memoized per file by nodeId
     *  (same ascent/backfill scheme as [spineUncalledReached]). */
    private fun spineArithReached(node: Node): Boolean {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.ARITH]++
        val memo = spineArithReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.ARITH, id)
                val m = memo[id].toInt()
                if (m != 0) return m == 1
            }
        }
        val chain = spineArithChain
        chain.clear()
        var cur: Node = node
        val reached: Boolean
        while (true) {
            val parent = (cur as NodeBase).parent
            if (parent == null) {
                reached = cur is SourceFile
                break
            }
            if (ReachCensus.on) ReachCensus.folds[ReachCensus.ARITH]++
            if (!spineArithEdge(parent, cur)) {
                reached = false
                break
            }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.ARITH, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) {
                reached = pm == 1
                break
            }
            chain.add(cur)
            cur = parent
        }
        run {
            val id = (cur as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.ARITH, id)
            if (id >= 0 && id < memo.size && memo[id].toInt() == 0) {
                memo[id] = if (reached) 1 else 2
            }
        }
        val fill: Byte = if (reached) 1 else 2
        for (i in chain.indices.reversed()) {
            val id = (chain[i] as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.ARITH, id)
            if (id >= 0 && id < memo.size) memo[id] = fill
        }
        if (ReachCensus.on) ReachCensus.misses[ReachCensus.ARITH]++
        chain.clear()
        return reached
    }

    /**
     * Is [b] ABSORBED into an enclosing left-spine flatten? The legacy driver's
     * `while (cur is BinaryExpression) { …; cur = cur.left }` loop descends
     * UNCONDITIONALLY (any operator), so a `&&` / `=`-objlit node that is the
     * LEFT operand of a flattened chain is consumed by the loop and its special
     * branch (truthy narrowing / contextual typing) never runs — while the same
     * node as a direct walk argument (statement level, a RIGHT operand, a paren
     * inner) takes the special branch. Unrolled: [b] is absorbed iff ANY node
     * on the maximal left-edge ancestor path above it has a NON-special
     * operator (that ancestor starts a flatten which descends through
     * everything below). Iterative — a 6,452-term chain is a corpus input.
     */
    private fun spineArithChainAbsorbed(b: BinaryExpression): Boolean {
        var child: Node = b
        var p: Node? = (b as NodeBase).parent
        while (p is BinaryExpression && child === p.left) {
            if (!spineArithSpecialBinary(p)) return true
            child = p
            p = (p as NodeBase).parent
        }
        return false
    }

    /** The two operators the legacy expression dispatch special-cases BEFORE the
     *  left-spine flatten: `&&` (truthy narrowing) and `=` with an
     *  object-literal RHS (B475 contextual typing). */
    private fun spineArithSpecialBinary(b: BinaryExpression): Boolean =
        b.operator == SyntaxKind.AmpersandAmpersand ||
            (b.operator == SyntaxKind.Equals && b.right is ObjectLiteralExpression)

    /** Is [b] the ROOT of a legacy left-spine flatten (the node whose
     *  checkArithmeticInExpr call ran the flatten loop)? */
    private fun spineArithChainRoot(b: BinaryExpression): Boolean =
        !spineArithSpecialBinary(b) && !spineArithChainAbsorbed(b)

    /** Per-node ENTER hook — edge-triggered frames first (so a node's own
     *  frames nest inside them), then node-kind frames/recordings/emissions. */
    private fun spineArithEnterNode(node: Node) {
        // ── edge-triggered frames (keyed on the CHILD node) ──
        when (val p = (node as NodeBase).parent) {
            is IfStatement -> if ((node === p.thenStatement || node === p.elseStatement) &&
                spineArithReached(node)) {
                SpineDispatch.work()
                // B283: the legacy arm computed the guard set once before both
                // branches; collectTypeofGuardNames is pure/syntactic, so
                // computing per branch is state-identical.
                spineArithFrames.add(SpineArithFrame(node, 2, savedSet = arithTypeofNarrowedNames))
                val guarded = collectTypeofGuardNames(p.expression)
                if (guarded.isNotEmpty()) arithTypeofNarrowedNames = arithTypeofNarrowedNames + guarded
            }
            is BinaryExpression -> if (node === p.right && !spineArithChainAbsorbed(p) &&
                spineArithReached(node)) {
                SpineDispatch.work()
                if (p.operator == SyntaxKind.AmpersandAmpersand) {
                    spineArithFrames.add(SpineArithFrame(node, 3, savedSet = arithTruthyNarrowedNames))
                    val truthy = collectArithTruthyNarrowableNames(p.left)
                    if (truthy.isNotEmpty()) arithTruthyNarrowedNames = arithTruthyNarrowedNames + truthy
                } else if (p.operator == SyntaxKind.Equals && node is ObjectLiteralExpression) {
                    // B475: the legacy branch computed the LHS type after walking
                    // the LEFT — the spine visits the left subtree before this
                    // right-child enter, so the relative order is identical.
                    spineArithFrames.add(SpineArithFrame(node, 1, savedCtx = spineArithCtx))
                    var lhsType: Type? = null
                    spineArithInstalled {
                        lhsType = getTypeOfExpression(p.left)
                    }
                    val lt = lhsType
                    if (lt != null && lt !== anyType && lt !== errorType) spineArithCtx = lt
                }
            }
            is ConditionalExpression -> if (spineArithReached(node)) {
                SpineDispatch.work()
                if (node === p.whenTrue) {
                    spineArithFrames.add(SpineArithFrame(node, 3, savedSet = arithTruthyNarrowedNames))
                    val names = collectArithTruthyNarrowableNames(p.condition)
                    if (names.isNotEmpty()) arithTruthyNarrowedNames = arithTruthyNarrowedNames + names
                } else if (node === p.whenFalse) {
                    spineArithFrames.add(SpineArithFrame(node, 3, savedSet = arithTruthyNarrowedNames))
                    val names = collectArithFalsyNonNullNames(p.condition)
                    if (names.isNotEmpty()) arithTruthyNarrowedNames = arithTruthyNarrowedNames + names
                }
            }
            is ForInStatement -> if (node === p.statement && spineArithReached(node)) {
                SpineDispatch.work()
                val forInVar = ((p.initializer as? VariableDeclarationList)
                    ?.declarations?.singleOrNull()?.name as? Identifier)?.text
                if (forInVar != null) {
                    spineArithFrames.add(SpineArithFrame(node, 0, savedLocals = spineArithLocals))
                    spineArithLocals = HashMap(spineArithLocals)
                    spineArithLocals[forInVar] = stringType
                }
            }
            is PropertyAssignment -> if (node === p.initializer && spineArithReached(node)) {
                SpineDispatch.work()
                // B475 property-value contextual typing: only when the enclosing
                // object literal is contextually typed AND the property's value
                // type resolves — otherwise the ambient ctx is INHERITED
                // unchanged (the legacy else-branch).
                val ctxObj = spineArithCtx
                if (ctxObj != null) {
                    val propName = when (val n = p.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        is NumericLiteralNode -> n.text
                        else -> null
                    }
                    if (propName != null) {
                        var propCtx: Type? = null
                        spineArithInstalled {
                            propCtx = lookupPropertyTypeForCtx(ctxObj, propName)
                        }
                        val pc = propCtx
                        if (pc != null) {
                            spineArithFrames.add(SpineArithFrame(node, 1, savedCtx = spineArithCtx))
                            spineArithCtx = pc
                        }
                    }
                }
            }
            else -> {}
        }
        // ── node-kind frames / recordings / emissions ──
        when ((node as NodeBase).kindId) {
            NodeKind.FUNCTION_DECLARATION -> {
                node as FunctionDeclaration
                if (node.body != null && spineArithReached(node)) {
                    spineArithFnFrame(node, node.typeParameters, node.parameters,
                        withTpScope = true, isArrowOrFnExpr = false)
                }
            }
            NodeKind.METHOD_DECLARATION -> {
                node as MethodDeclaration
                if (node.parent is ClassDeclaration && node.body != null &&
                    spineArithReached(node)
                ) {
                    spineArithFnFrame(node, node.typeParameters, node.parameters,
                        withTpScope = true, isArrowOrFnExpr = false)
                }
            }
            NodeKind.CONSTRUCTOR -> {
                node as Constructor
                if (node.parent is ClassDeclaration && node.body != null &&
                    spineArithReached(node)
                ) {
                    // The legacy Constructor arm populated params WITHOUT a TP-scope push.
                    spineArithFnFrame(node, null, node.parameters,
                        withTpScope = false, isArrowOrFnExpr = false)
                }
            }
            NodeKind.ARROW_FUNCTION -> {
                node as ArrowFunction
                if (spineArithReached(node)) {
                    spineArithFnFrame(node, node.typeParameters, node.parameters,
                        withTpScope = true, isArrowOrFnExpr = true)
                }
            }
            NodeKind.FUNCTION_EXPRESSION -> {
                node as FunctionExpression
                if (spineArithReached(node)) {
                    spineArithFnFrame(node, node.typeParameters, node.parameters,
                        withTpScope = true, isArrowOrFnExpr = true)
                }
            }
            NodeKind.PREFIX_UNARY_EXPRESSION -> {
                node as PrefixUnaryExpression
                if (node.operator == SyntaxKind.Plus &&
                    spineArithReached(node)
                ) {
                    // Legacy order: the TS2736 emission ran BEFORE the operand walk.
                    spineArithInstalled {
                        checkUnaryPlusBigIntOperand(node, spineSource, spineFileName)
                    }
                }
            }
            else -> {}
        }
    }

    /** The legacy function-like scope entry: copy the map, push the TP scope,
     *  populate param types (+ B475 contextual arrow params), restore the TP
     *  scope. The map copy is restored at the node's leave; ArrowFunction/
     *  FunctionExpression additionally clear the contextual type for the body
     *  (the legacy "body is not contextually typed by the param fn type"). */
    private fun spineArithFnFrame(
        node: Node,
        typeParameters: List<TypeParameter>?,
        parameters: List<Parameter>,
        withTpScope: Boolean,
        isArrowOrFnExpr: Boolean,
    ) {
        spineArithFrames.add(SpineArithFrame(node, 0, savedLocals = spineArithLocals))
        spineArithLocals = HashMap(spineArithLocals)
        val ctxFn = spineArithCtx
        spineArithInstalled {
            if (withTpScope) {
                withFunctionTypeParamsScope(typeParameters) {
                    populateParameterLocalTypes(parameters)
                    if (isArrowOrFnExpr) applyContextualParamTypesForArrow(parameters, ctxFn)
                }
            } else {
                populateParameterLocalTypes(parameters)
            }
        }
        if (isArrowOrFnExpr) {
            spineArithFrames.add(SpineArithFrame(node, 1, savedCtx = spineArithCtx))
            spineArithCtx = null
        }
    }

    /** Per-node LEAVE hook — the node's own emissions/recordings first (they run
     *  inside any frames keyed on this node), then pop this node's frames. */
    private fun spineArithLeaveNode(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.BINARY_EXPRESSION -> {
                node as BinaryExpression
                if (spineArithChainRoot(node) && spineArithReached(node)) {
                    // The legacy flatten emitted per-spine-node diagnostics AFTER
                    // walking the leaf + all rights, innermost (deepest-left) first.
                    val members = spineArithChainBuf
                    members.clear()
                    var cur: Expression = node
                    while (cur is BinaryExpression) {
                        members.add(cur)
                        cur = cur.left
                    }
                    spineArithInstalled {
                        for (i in members.indices.reversed()) {
                            checkBinaryOperatorTypes(members[i], spineSource, spineFileName)
                        }
                    }
                    members.clear()
                }
            }
            NodeKind.VARIABLE_DECLARATION -> {
                node as VariableDeclaration
                val list = node.parent as? VariableDeclarationList
                if (list != null && list.parent is VariableStatement && spineArithReached(node)) {
                    // The legacy recording ran AFTER the declarator's own
                    // initializer walk, per declarator — the leave position.
                    spineArithInstalled {
                        spineArithRecordVarDecl(node, list.flags == SyntaxKind.ConstKeyword)
                    }
                }
            }
            else -> {}
        }
        // Pop every frame this node pushed (LIFO — restores in reverse).
        val frames = spineArithFrames
        while (frames.isNotEmpty() && frames[frames.size - 1].node === node) {
            SpineDispatch.work()
            val f = frames.removeAt(frames.size - 1)
            when (f.kind) {
                0 -> spineArithLocals = f.savedLocals!!
                1 -> spineArithCtx = f.savedCtx
                2 -> arithTypeofNarrowedNames = f.savedSet!!
                3 -> arithTruthyNarrowedNames = f.savedSet!!
            }
        }
    }

    /**
     * (REL.1)(b0) round 742: was [name]'s current recording INHERITED from an
     * enclosing scope rather than made in this one?
     *
     * The pass copies its locals map at every scope frame ([spineArithFnFrame],
     * kind 0) and restores the original at the frame's leave, so an enclosing
     * body's recordings stay visible while a nested body is walked. The test is
     * therefore instance IDENTITY against the innermost saved map: an entry made
     * HERE either did not exist outside or is a different `Type` instance, while an
     * untouched inherited entry is the very same instance the outer map holds.
     *
     * A declaration whose name is inherited is by construction a SHADOW, so the
     * recorder's first-wins rule must not apply to it.
     */
    private fun spineArithInheritedName(name: String): Boolean {
        val current = spineArithLocals[name] ?: return false
        for (i in spineArithFrames.indices.reversed()) {
            val f = spineArithFrames[i]
            if (f.kind != 0) continue
            return f.savedLocals?.get(name) === current
        }
        return false
    }

    /**
     * The legacy VariableStatement per-declarator recording, verbatim (see the
     * inline comments at the original site — now this function). Runs under
     * [spineArithInstalled], so currentLocalTypes IS [spineArithLocals].
     */
    private fun spineArithRecordVarDecl(decl: VariableDeclaration, isConst: Boolean) {
        val declName = (decl.name as? Identifier)?.text
        if (declName != null && decl.type != null) {
            // expr.ts: record an ANNOTATED function-body local's declared type
            // so later arithmetic/comparison checks resolve interface/enum/
            // primitive operands (`var i!: I` / `var e!: E`) — the binder does
            // not bind function-body vars, so getTypeOfExpression otherwise
            // returns `any` for them. Gated to a concrete non-any/error/unknown
            // resolution (FN over FP — an unresolvable annotation stays `any` =
            // prior behavior). Scoped to the pass's per-file map, so this does
            // not leak into other checker passes.
            val annotType = getTypeFromTypeNode(decl.type)
            // Skip UNION types: a `let x: number | undefined` (or any union) is
            // routinely flow-NARROWED before an arithmetic/comparison use, and this
            // pass has no flow narrowing — recording the un-narrowed union FP's
            // (narrowingPastLastAssignment: `let i: number|undefined; i = 0; i + 1`).
            if (annotType !== anyType && annotType !== errorType &&
                annotType !== unknownType && annotType !is Type.Union) {
                currentLocalTypes[declName] = annotType
            }
        } else {
            val lit = if (declName != null && decl.type == null) {
                decl.initializer?.let { literalTypeOfExpression(it) }
            } else null
            if (lit != null && lit !== nullType && lit !== undefinedType) {
                // (WIDEN.1) round 781: this recording runs AFTER the TS2322 walk's and
                // overwrites it, so the const-ness gate has to be repeated here or the
                // literal the other site preserved is widened away again.
                currentLocalTypes[declName!!] =
                    if (WIDEN1_CONST_KEEPS_LITERAL && isConst) lit else getWidenedLiteralType(lit)
            } else if (declName != null && decl.type == null && decl.initializer is BinaryExpression) {
                // A BINARY initializer whose operator pins a concrete primitive
                // result also records: comparisons → boolean, arithmetic/compound
                // arithmetic → number/bigint (`var any = 0 ^= <missing>` is number;
                // `var string = 0 / <missing> > <missing>` is boolean — the sum3
                // chain of constructorWithIncompleteTypeAnnotation needs both).
                // Gated to a primitive intrinsic result (never unions/objects/any),
                // mirroring the literal-init convention above.
                val bin = decl.initializer
                val binT = when (bin.operator) {
                    SyntaxKind.LessThan, SyntaxKind.GreaterThan,
                    SyntaxKind.LessThanEquals, SyntaxKind.GreaterThanEquals,
                    SyntaxKind.EqualsEquals, SyntaxKind.ExclamationEquals,
                    SyntaxKind.EqualsEqualsEquals, SyntaxKind.ExclamationEqualsEquals,
                    SyntaxKind.InstanceOfKeyword, SyntaxKind.InKeyword -> booleanType
                    SyntaxKind.Minus, SyntaxKind.Asterisk, SyntaxKind.Slash,
                    SyntaxKind.Percent, SyntaxKind.AsteriskAsterisk,
                    SyntaxKind.Ampersand, SyntaxKind.Bar, SyntaxKind.Caret,
                    SyntaxKind.LessThanLessThan, SyntaxKind.GreaterThanGreaterThan,
                    SyntaxKind.GreaterThanGreaterThanGreaterThan,
                    SyntaxKind.MinusEquals, SyntaxKind.AsteriskEquals,
                    SyntaxKind.SlashEquals, SyntaxKind.PercentEquals,
                    SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals,
                    SyntaxKind.CaretEquals, SyntaxKind.LessThanLessThanEquals,
                    SyntaxKind.GreaterThanGreaterThanEquals,
                    SyntaxKind.GreaterThanGreaterThanGreaterThanEquals -> numberType
                    else -> null
                }
                if (binT != null) currentLocalTypes[declName] = binT
            } else if (declName != null && decl.type == null &&
                decl.initializer is ObjectLiteralExpression) {
                // An object-literal initializer records too, so a member chain
                // rooted at the local resolves (`var anony = { a: new CLASS() };
                // retVal += anony.a.d();` needs anony.a.d()'s void return —
                // constructorWithIncompleteTypeAnnotation line 166). Same
                // concrete-only gate as the annotation branch above.
                val objT = getTypeOfObjectLiteral(decl.initializer)
                if (objT !== anyType && objT !== errorType && objT !is Type.Union) {
                    currentLocalTypes[declName] = objT
                }
            } else if (declName != null && decl.type == null && decl.initializer is Identifier &&
                ((decl.parent as? VariableDeclarationList)?.parent as? VariableStatement)
                    ?.parent is ModuleBlock) {
                // Round 531 (qualify.ts pin): a NAMESPACE-level unannotated `var y = m`
                // whose initializer is itself a pass-recorded primitive records the
                // chained type. At the pass's old post-giants slot this fell out of the
                // TS2322 walk's RESIDUE (its namespace/top-level recordings leaked into
                // this pass's inherited map, where the namespace `y = m` → number
                // first-wins-blocked the later FILE-level `var y: I`); the migrated pass
                // runs before the giants, so the chain is recorded here directly.
                // Without it, `y` falls through the block-UNAWARE fileLocalTypeMaps to
                // the file-level annotation → FP TS2365 on `n + y`. Namespace-level
                // ONLY: function-body recordings never persisted into the old residue
                // (checkFunctionBody save/restores), so this is the residue-faithful gate.
                val srcT = currentLocalTypes[decl.initializer.text]
                if (srcT === numberType || srcT === stringType || srcT === booleanType ||
                    srcT === bigintType) {
                    currentLocalTypes[declName] = srcT
                }
            } else if (declName != null && decl.type == null &&
                // (REL.1)(b0) round 742: first-wins WITHIN a scope, but NOT over an
                // entry INHERITED from an enclosing one — see [spineArithInheritedName].
                (declName !in currentLocalTypes || spineArithInheritedName(declName)) &&
                (decl.initializer is PropertyAccessExpression ||
                    decl.initializer is ElementAccessExpression ||
                    decl.initializer is CallExpression ||
                    decl.initializer is NonNullExpression)) {
                // A function-body local whose name SHADOWS an outer same-named
                // FUNCTION records so a later bare-identifier operand resolves to the
                // shadowing local, not past it to the outer function. tsc's own
                // core.ts exports `function length/min/max(...): number`, which a
                // local `const length = arr.length` / `let min = Number.POSITIVE_INFINITY`
                // shadows — without this, `i < length` / `min < args.length` types the
                // operand as the imported function → FP TS2365.
                //
                // The SHADOW gate is load-bearing: a non-shadowing local like
                // `const numStatements = source.length` must NOT record `number`,
                // or it UNMASKS a pre-existing narrowing FP on the OTHER operand
                // (`statementOffset < numStatements` where statementOffset is an
                // un-narrowed `number | undefined` param — this pass has no flow
                // narrowing). Leaving non-shadowing locals as `any` keeps the pass's
                // default suppression. Gated to a bare property-access/element-access/
                // call/non-null initializer (never union/any/object/function).
                val outerT = getTypeOfExpression(decl.name)
                if (outerT is Type.Object && outerT.callSignatures?.isNotEmpty() == true) {
                    // A `const` (stable type) records the concrete primitive when
                    // determinable so a later comparison can still catch a real error
                    // on the OTHER operand; a `let`/`var` (round 416: checker.ts's
                    // `let min = Number.POSITIVE_INFINITY` shadowing `function min`)
                    // records `anyType` — the shadow is what kills the FP, and `any`
                    // is reassignment-proof (a `let` may be reassigned to a different
                    // primitive, so recording its INITIAL type could FP a later
                    // comparison; `any` only ever SUPPRESSES the bogus operand check).
                    // The `any` fallback for a const also catches an initializer
                    // (`outer.length` on a narrowed-union receiver this pass can't
                    // resolve) that types to `any`.
                    val initT = getTypeOfExpression(decl.initializer)
                    currentLocalTypes[declName] =
                        if (isConst && (initT === numberType || initT === stringType ||
                            initT === booleanType || initT === bigintType)) initT
                        else anyType
                } else if (outerT is Type.Interface && spineArithInheritedName(declName)) {
                    // (REL.1)(b0) round 742: the same shadow trap with a NON-CALLABLE
                    // outer binding. tsc's generators.ts declares
                    // `let state: Identifier` in `transformGenerators`, and the nested
                    // `endExceptionBlock()`'s `const state = exception.state` shadows
                    // it — so `state < ExceptionBlockState.Finally` typed its LEFT
                    // operand as the AST interface and FP'd TS2365 the moment the RIGHT
                    // operand stopped being `anyType`. Recording `anyType` = suppression,
                    // the same remedy the callable case uses, and it cannot invent a
                    // diagnostic (`any` only ever silences an operand check).
                    currentLocalTypes[declName] = anyType
                }
            }
        }
    }

    // ── INV.4(d) walker 3: checkImplicitAnyParameters on the spine ──────────
    // The per-file pass driver and the recursive checkImplicitAnyInStatements/
    // -InClassElement(Core)/-InExpr walkers are DELETED. Reach is a memoized
    // ancestor-chain classifier over [spineIanyEdge] (the legacy dispatch arms
    // verbatim — while/do/switch/try/for-in/for-of bodies, for-headers, call
    // CALLEES, conditional CONDITIONS, as-casts, object-literal accessors and
    // class static blocks were never walked). The downward contextual-typing
    // state is PUSH-maintained as [SpineIanyCtx] frames at exactly the edges
    // the legacy recursion passed arguments over; the implicit-any scope
    // stacks, ns stack, and enclosing-class-members field are the same
    // checker fields, pushed/popped at the same tree positions. No ambient
    // install is needed: the pass never consulted the shared walk fields
    // (currentLocalTypes etc.) deliberately, and the slot-move A/B proved the
    // spine slot's ambient state is behavior-identical for its typing calls.

    /** Per-file activation + state, called from [checkSpine]'s loop. */
    private fun spineIanySetup(result: BinderResult) {
        spineIanyActive = options.noImplicitAny || options.strict
        if (!spineIanyActive) {
            spineIanyReachMemo = ByteArray(0)
            return
        }
        spineIanyReachMemo = ByteArray(result.sourceFile.nodeCount)
        if (IanySections.mode != IanySections.OFF) {
            spineIanyCpgncSeen = ByteArray(result.sourceFile.nodeCount)
        }
        // The legacy per-file hygiene (every push pops via frames; belt-and-braces).
        implicitAnyScopes.clear()
        implicitAnyScopeInits.clear()
        implicitAnyScopeDestructures.clear()
        implicitAnyNsStack.clear()
        spineIanyCtx = null
        spineIanyFrames.clear()
    }

    private fun spineIanyTeardown() {
        spineIanyActive = false
        spineIanyReachMemo = ByteArray(0)
        spineIanyFrames.clear()
        spineIanyCtx = null
    }

    /**
     * The legacy statement walker's ambient-context threading, reproduced as a
     * parent-chain walk: ambient accumulates only along an UNBROKEN
     * ModuleBlock/ModuleDeclaration chain (a `declare` on any module on it);
     * every other parent kind — fn bodies, plain Blocks, if/for arms — RESET
     * it (the legacy recursion did not pass inAmbientContext there).
     */
    private fun spineIanyAmbientAt(node: Node): Boolean {
        var cur: Node? = (node as NodeBase).parent
        while (cur != null) {
            cur = when (cur) {
                is ModuleBlock -> (cur as NodeBase).parent
                is ModuleDeclaration -> {
                    if (ModifierFlag.Declare in cur.modifiers) return true
                    (cur as NodeBase).parent
                }
                else -> return false
            }
        }
        return false
    }

    /** The legacy ClassDeclaration arm's isAmbientClass. */
    private fun spineIanyClassIsAmbient(cls: ClassDeclaration): Boolean =
        ModifierFlag.Declare in cls.modifiers || spineIanyAmbientAt(cls)

    /** Is [lit] the legacy destructuring-default shape's initializer (an
     *  ObjectBindingPattern var-decl's object-literal initializer, walked
     *  per-PropertyAssignment with typed-default context instead of the normal
     *  object-literal arm)? */
    private fun spineIanyObjLitIsDestructureDefault(lit: ObjectLiteralExpression): Boolean {
        val decl = (lit as NodeBase).parent as? VariableDeclaration ?: return false
        if (decl.initializer !== lit || decl.name !is ObjectBindingPattern) return false
        val list = (decl as NodeBase).parent as? VariableDeclarationList ?: return false
        return (list as NodeBase).parent is VariableStatement
    }

    /**
     * The legacy M1.6(b) returnCtxAnnotation threading, reproduced as a
     * parent-chain walk from a reached ReturnStatement: threaded through
     * Block/If/For only (the only statement arms that passed it on); the first
     * function-like boundary decides — its return annotation for
     * FunctionDeclaration/MethodDeclaration/GetAccessor/ArrowFunction/
     * FunctionExpression, null for Constructor/SetAccessor (the legacy body
     * walks passed nothing there); a module/file boundary yields null.
     */
    private fun spineIanyReturnCtxAt(ret: ReturnStatement): TypeNode? {
        var cur: Node? = (ret as NodeBase).parent
        while (cur != null) {
            when (cur) {
                is FunctionDeclaration -> return cur.type
                is MethodDeclaration -> return cur.type
                is GetAccessor -> return cur.type
                is ArrowFunction -> return cur.type
                is FunctionExpression -> return cur.type
                is Constructor, is SetAccessor -> return null
                is Block, is IfStatement, is ForStatement -> cur = (cur as NodeBase).parent
                else -> return null
            }
        }
        return null
    }

    /**
     * Does the deleted pass reach [child] from [parent]? Mirrors
     * checkImplicitAnyInStatements/-InClassElement(Core)/-InExpr's dispatch
     * arms exactly — every kind absent here fell to their `else` arms.
     */
    private fun spineIanyEdge(parent: Node, child: Node): Boolean = when (parent) {
        // ── statement dispatch ──
        is SourceFile -> child is Statement
        is FunctionDeclaration -> child === parent.body
        // Ambient class members are handled INLINE at the class enter (the
        // legacy isAmbientClass branch — no element walk, no body descent).
        is ClassDeclaration -> child is ClassElement && !spineIanyClassIsAmbient(parent)
        is VariableStatement -> child === parent.declarationList
        is VariableDeclarationList -> child is VariableDeclaration &&
            (parent as NodeBase).parent is VariableStatement
        is VariableDeclaration -> child === parent.initializer
        is ExpressionStatement -> child === parent.expression
        is ModuleDeclaration -> child === parent.body &&
            (child is ModuleBlock || child is ModuleDeclaration)
        is ModuleBlock -> child is Statement
        is Block -> child is Statement
        is IfStatement -> child === parent.thenStatement || child === parent.elseStatement
        is ForStatement -> child === parent.statement
        is ReturnStatement -> child === parent.expression
        // ── class elements (non-ambient class decls + class expressions) ──
        is MethodDeclaration -> child === parent.body
        is Constructor -> child === parent.body
        is GetAccessor -> child === parent.body
        is SetAccessor -> child === parent.body
        is PropertyDeclaration -> child === parent.initializer
        is ClassExpression -> child is ClassElement
        // ── expression dispatch ──
        is ArrowFunction -> child === parent.body
        is FunctionExpression -> child === parent.body
        is ObjectLiteralExpression ->
            if (spineIanyObjLitIsDestructureDefault(parent)) child is PropertyAssignment
            else child is PropertyAssignment || child is MethodDeclaration
        is PropertyAssignment -> child === parent.initializer
        is CallExpression -> parent.arguments.anyIdentical(child)
        is NewExpression -> parent.arguments?.anyIdentical(child) == true
        is BinaryExpression -> child === parent.left || child === parent.right
        is ParenthesizedExpression -> child === parent.expression
        is ConditionalExpression -> child === parent.whenTrue || child === parent.whenFalse
        is ArrayLiteralExpression -> true
        else -> false
    }

    /** Is [node] reached by the deleted pass? Memoized per file by nodeId (same
     *  ascent/backfill scheme as [spineArithReached]). */
    private fun spineIanyReached(node: Node): Boolean {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.IANY]++
        val memo = spineIanyReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.IANY, id)
                val m = memo[id].toInt()
                if (m != 0) return m == 1
            }
        }
        val chain = spineIanyChain
        chain.clear()
        var cur: Node = node
        val reached: Boolean
        while (true) {
            val parent = (cur as NodeBase).parent
            if (parent == null) {
                reached = cur is SourceFile
                break
            }
            if (ReachCensus.on) ReachCensus.folds[ReachCensus.IANY]++
            if (!spineIanyEdge(parent, cur)) {
                reached = false
                break
            }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.IANY, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) {
                reached = pm == 1
                break
            }
            chain.add(cur)
            cur = parent
        }
        run {
            val id = (cur as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.IANY, id)
            if (id >= 0 && id < memo.size && memo[id].toInt() == 0) {
                memo[id] = if (reached) 1 else 2
            }
        }
        val fill: Byte = if (reached) 1 else 2
        for (i in chain.indices.reversed()) {
            val id = (chain[i] as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.IANY, id)
            if (id >= 0 && id < memo.size) memo[id] = fill
        }
        if (ReachCensus.on) ReachCensus.misses[ReachCensus.IANY]++
        chain.clear()
        return reached
    }

    /** Define the contextual-typing state for [child]'s subtree (the legacy
     *  recursion's explicit-argument pass); no-op when both states are the
     *  all-defaults null. */
    private fun spineIanyDefineCtx(child: Node, newCtx: SpineIanyCtx?) {
        val cur = spineIanyCtx
        if (cur == null && newCtx == null) return
        SpineDispatch.work()
        spineIanyFrames.add(SpineIanyFrame(child, 0, savedCtx = cur))
        spineIanyCtx = newCtx
    }

    /** The legacy function-body scope push (pushImplicitAnyScope around the
     *  body walk), keyed on the BODY node so the leave pops it. */
    private fun spineIanyPushScope(bodyNode: Node, params: List<Parameter>) {
        SpineDispatch.work()
        pushImplicitAnyScope(params)
        spineIanyFrames.add(SpineIanyFrame(bodyNode, 1))
    }

    /** Per-node ENTER hook — edge-triggered frames/emissions first (so a node's
     *  own frames nest inside its parent-edge frames), then node-kind handling. */
    private fun spineIanyEnterNode(node: Node) {
        val p = (node as NodeBase).parent
        if (IanySections.mode == IanySections.OFF) {
            if (p != null && !spineIanyEdgeUnobservable(p, node)) spineIanyEdgeEnter(p, node)
            spineIanyOwnEnter(node)
            return
        }
        // (IANY.1) two spans per node; the ROW is classified after the span
        // closes, so the classifier never lands in a row it is measuring.
        if (p != null) {
            val t0 = PassTiming.nowNanos()
            if (!spineIanyEdgeUnobservable(p, node)) spineIanyEdgeEnter(p, node)
            IanySections.record(spineIanyEdgeRow(p, node), PassTiming.nowNanos() - t0)
        }
        val t1 = PassTiming.nowNanos()
        spineIanyOwnEnter(node)
        IanySections.record(spineIanyOwnRow(node), PassTiming.nowNanos() - t1)
    }

    /**
     * (IANY.1) a node whose subtree is EMPTY — `forEachChild` visits nothing
     * for these three kinds, so a contextual-typing state defined for such a
     * child has no node that could read it.
     */
    private fun spineIanyChildless(n: Node): Boolean = when ((n as NodeBase).kindId) {
        NodeKind.IDENTIFIER, NodeKind.STRING_LITERAL_NODE, NodeKind.NUMERIC_LITERAL_NODE -> true
        else -> false
    }

    /**
     * (IANY.1) round 798 — the parent edge defines a contextual state that
     * NOTHING can read, so running the arm is pure cost.
     *
     * `spineIanyCtx` has no reader outside this handler family
     * (`spineIanyEdgeEnter`'s own arms, `spineIanyFnExprEnter`,
     * `spineIanyObjLitMethodEnter`, `spineIanyPropAssignEdge`), and every one of
     * those readers sits at a node INSIDE the subtree the state was defined
     * for. A [spineIanyChildless] child has no such node — the frame would be
     * pushed at its enter and popped at its leave with nothing in between.
     *
     * The exclusion is the parents whose edge does something OTHER than define
     * a context: the seven function-likes and `ModuleDeclaration` push an
     * implicit-any scope / a namespace symbol, and an arrow's EXPRESSION body
     * is exactly a childless child of one of them. Every remaining arm was
     * audited to define a context and nothing else — the only emission below a
     * parent edge (`emitTs7006BeyondCtxArity`, in the `CallExpression` and
     * `VariableDeclaration` arms) is itself gated on the child being an
     * arrow/function expression, which is never childless.
     *
     * The one arm carrying state across the edge is `VariableDeclaration`'s:
     * `spineIanyVarDeclEnter` stashes `spineIanyPendingAnnDecl`/`…Type` for the
     * initializer edge to consume and clear. A skipped edge leaves the stash
     * set — which is unobservable, because the consumer's test is the IDENTITY
     * `spineIanyPendingAnnDecl === decl` and every declarator's own enter
     * rewrites both fields, so no later edge can read a stale pair.
     */
    private fun spineIanyEdgeUnobservable(p: Node, node: Node): Boolean =
        !IanySections.gateOff && spineIanyChildless(node) &&
            !spineIanyScopePushParent((p as NodeBase).kindId)

    /** (IANY.1) every argument childless — so every argument edge is skipped by
     *  [spineIanyEdgeUnobservable] and no reader of the call's `typed` flag is
     *  ever reached. A call with NO arguments qualifies trivially. */
    private fun spineIanyArgsAllChildless(args: List<Expression>): Boolean {
        if (IanySections.gateOff) return false
        for (a in args) if (!spineIanyChildless(a)) return false
        return true
    }

    /**
     * (IANY.1) parents whose child edge pushes an implicit-any SCOPE or a
     * namespace rather than only defining a context — an arrow's EXPRESSION
     * body is a childless child of one of these.
     *
     * **ROUND 799 — THIS EXCLUSION IS KEPT ON ARGUMENT, NOT ON EVIDENCE, AND
     * BOTH OF OUR INSTRUMENTS HAVE NOW FAILED TO FALSIFY IT.** Round 798 ran
     * ablation B (this test removed, so the scope-push edges are skipped too)
     * against the 8-profile grid: byte-identical. Round 799 ran the same fault
     * against the FULL 13,449-baseline corpus suite: **13,449 / 0 failures /
     * 3 skipped, i.e. also nothing** — and the fault was live (the build
     * warned `Unreachable code` at the gate) with the population reached by the
     * most ordinary shapes there are (`const id = (a) => a` alone counts six
     * `E_SCOPE_LEAF` edges), so this is not round 753's "the ablation tested
     * nothing".
     *
     * **Why nothing sees it, stated properly** (round 798's "a scope push is an
     * observable MUTATION" is true but is not the reason): a frame pushed at a
     * CHILDLESS node's edge is popped at that node's own leave with **no node
     * entered in between**, and every reader of `implicitAnyScopes` /
     * [spineIanyCtx] is reached only from a `spineIany*` dispatch AT a node. So
     * the stack mutation is unobservable by construction, exactly as the
     * context definition is.
     *
     * **What is NOT unobservable, and is why it stays**: the `ArrowFunction`
     * arm does not only push — it calls `contextualSigReturnTypeForCtx`, a type
     * RESOLUTION, whose side effects (interning, `symbolTypes` writes) are
     * global and order-sensitive. Dropping it perturbs first-touch resolution
     * ORDER, the round-754/776/778 hazard class that has no output diff to find
     * it by, and buys **1 ms**. Keeping it is the trade; no pin can discriminate
     * it, and none is claimed to.
     */
    private fun spineIanyScopePushParent(k: Int): Boolean = when (k) {
        NodeKind.FUNCTION_DECLARATION, NodeKind.METHOD_DECLARATION, NodeKind.CONSTRUCTOR,
        NodeKind.GET_ACCESSOR, NodeKind.SET_ACCESSOR, NodeKind.FUNCTION_EXPRESSION,
        NodeKind.ARROW_FUNCTION, NodeKind.MODULE_DECLARATION -> true
        else -> false
    }

    /** (IANY.1) probe-only row classifier for the EDGE span. */
    private fun spineIanyEdgeRow(p: Node, node: Node): Int {
        val pk = (p as NodeBase).kindId
        if (!spineIanyChildless(node)) return spineIanySubtreeRow(p, pk, node)
        if (spineIanyScopePushParent(pk)) return IanySections.E_SCOPE_LEAF
        return if (pk == NodeKind.CALL_EXPRESSION || pk == NodeKind.NEW_EXPRESSION)
            IanySections.E_SKIP_CALLARG else IanySections.E_SKIP_OTHER
    }

    /**
     * (IANY.1) round 799 — the kinds [spineIanyEdgeEnter]'s `when (p)` has an
     * arm for. MUST stay in exact correspondence with that `when`: adding an arm
     * without adding its kind here makes the arm silently unreachable, and the
     * tell is a corpus baseline losing a diagnostic with no change near the arm
     * (the same failure mode as `ccetPrologueMayFire`, round 793).
     */
    private fun spineIanyEdgeHasArm(k: Int): Boolean = when (k) {
        NodeKind.FUNCTION_DECLARATION, NodeKind.METHOD_DECLARATION, NodeKind.CONSTRUCTOR,
        NodeKind.GET_ACCESSOR, NodeKind.SET_ACCESSOR, NodeKind.FUNCTION_EXPRESSION,
        NodeKind.ARROW_FUNCTION, NodeKind.MODULE_DECLARATION,
        NodeKind.VARIABLE_DECLARATION, NodeKind.EXPRESSION_STATEMENT,
        NodeKind.RETURN_STATEMENT, NodeKind.PROPERTY_DECLARATION,
        NodeKind.PROPERTY_ASSIGNMENT, NodeKind.CALL_EXPRESSION, NodeKind.NEW_EXPRESSION,
        NodeKind.BINARY_EXPRESSION, NodeKind.PARENTHESIZED_EXPRESSION,
        NodeKind.CONDITIONAL_EXPRESSION, NodeKind.ARRAY_LITERAL_EXPRESSION -> true
        else -> false
    }

    /**
     * (IANY.1) round 799 — probe-only sub-partition of round 798's residue row
     * (`edge: child with a subtree`, 63% of the post-gate handler), BY THE ARM
     * the parent edge reaches. The point of the partition is its last row:
     * `S_NOARM` is the population whose parent kind matches NONE of
     * [spineIanyEdgeEnter]'s 19 `is` arms, so the entire dispatch is a chain of
     * failed `instanceof` checks — the only part of the residue a cheaper
     * DISPATCH could recover, as opposed to the arms' own work.
     */
    private fun spineIanySubtreeRow(p: Node, pk: Int, node: Node): Int = when (pk) {
        NodeKind.CALL_EXPRESSION ->
            if ((p as CallExpression).arguments.anyIdentical(node))
                IanySections.S_CALL_ARG else IanySections.S_CALL_OTHER
        NodeKind.NEW_EXPRESSION ->
            if ((p as NewExpression).arguments?.anyIdentical(node) == true)
                IanySections.S_CALL_ARG else IanySections.S_CALL_OTHER
        NodeKind.VARIABLE_DECLARATION -> IanySections.S_VARDECL
        NodeKind.RETURN_STATEMENT -> IanySections.S_RETURN
        NodeKind.BINARY_EXPRESSION -> IanySections.S_BINARY
        NodeKind.FUNCTION_DECLARATION, NodeKind.METHOD_DECLARATION, NodeKind.CONSTRUCTOR,
        NodeKind.GET_ACCESSOR, NodeKind.SET_ACCESSOR, NodeKind.FUNCTION_EXPRESSION,
        NodeKind.ARROW_FUNCTION, NodeKind.MODULE_DECLARATION -> IanySections.S_SCOPEPUSH
        NodeKind.PROPERTY_ASSIGNMENT, NodeKind.PROPERTY_DECLARATION -> IanySections.S_PROP
        NodeKind.PARENTHESIZED_EXPRESSION, NodeKind.CONDITIONAL_EXPRESSION,
        NodeKind.ARRAY_LITERAL_EXPRESSION, NodeKind.EXPRESSION_STATEMENT ->
            IanySections.S_PASSTHRU
        else -> IanySections.S_NOARM
    }

    /** (IANY.1) probe-only row classifier for the OWN span. */
    private fun spineIanyOwnRow(node: Node): Int = when ((node as NodeBase).kindId) {
        NodeKind.CALL_EXPRESSION ->
            if ((node as CallExpression).arguments.all { spineIanyChildless(it) })
                IanySections.OWN_CALL_LEAFARGS else IanySections.OWN_CALL_OTHER
        NodeKind.NEW_EXPRESSION ->
            if ((node as NewExpression).arguments?.all { spineIanyChildless(it) } != false)
                IanySections.OWN_CALL_LEAFARGS else IanySections.OWN_CALL_OTHER
        else -> IanySections.OWN_OTHER
    }

    /** The node's OWN kind arms (split out of [spineIanyEnterNode] so (IANY.1)
     *  can time them separately from the parent-edge dispatch). */
    private fun spineIanyOwnEnter(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.FUNCTION_DECLARATION -> {
                node as FunctionDeclaration
                if (spineIanyReached(node)) {
                    // Params checked for ALL function declarations (declare included).
                    checkParamsForImplicitAny(node.parameters, spineSource, spineFileName)
                }
            }
            NodeKind.CLASS_DECLARATION -> {
                node as ClassDeclaration
                if (spineIanyClassIsAmbient(node) && spineIanyReached(node)) {
                    spineIanyAmbientClassMembers(node)
                }
            }
            NodeKind.INTERFACE_DECLARATION -> {
                node as InterfaceDeclaration
                if (spineIanyReached(node)) {
                    spineIanyInterfaceMembers(node)
                }
            }
            NodeKind.VARIABLE_DECLARATION -> {
                node as VariableDeclaration
                if (node.parent.let {
                        it is VariableDeclarationList && (it as NodeBase).parent is VariableStatement
                    } && spineIanyReached(node)) {
                    spineIanyVarDeclEnter(node)
                }
            }
            NodeKind.METHOD_DECLARATION -> {
                node as MethodDeclaration
                if (spineIanyReached(node)) {
                    when (node.parent) {
                        is ClassDeclaration, is ClassExpression -> spineIanyClassElementEnter(node)
                        is ObjectLiteralExpression -> spineIanyObjLitMethodEnter(node)
                        else -> {}
                    }
                }
            }
            NodeKind.CONSTRUCTOR -> {
                node as Constructor
                if (spineIanyIsClassElement(node) && spineIanyReached(node)) {
                    spineIanyClassElementEnter(node)
                }
            }
            NodeKind.GET_ACCESSOR -> {
                node as GetAccessor
                if (spineIanyIsClassElement(node) && spineIanyReached(node)) {
                    spineIanyClassElementEnter(node)
                }
            }
            NodeKind.SET_ACCESSOR -> {
                node as SetAccessor
                if (spineIanyIsClassElement(node) && spineIanyReached(node)) {
                    spineIanyClassElementEnter(node)
                }
            }
            NodeKind.PROPERTY_DECLARATION -> {
                node as PropertyDeclaration
                if (spineIanyIsClassElement(node) && spineIanyReached(node)) {
                    spineIanyClassElementEnter(node)
                }
            }
            NodeKind.ARROW_FUNCTION -> {
                node as ArrowFunction
                if (spineIanyReached(node)) {
                    spineIanyFnExprEnter(node.parameters)
                }
            }
            NodeKind.FUNCTION_EXPRESSION -> {
                node as FunctionExpression
                if (spineIanyReached(node)) {
                    spineIanyFnExprEnter(node.parameters)
                }
            }
            NodeKind.OBJECT_LITERAL_EXPRESSION -> {
                node as ObjectLiteralExpression
                if (spineIanyReached(node) &&
                    !spineIanyObjLitIsDestructureDefault(node)
                ) {
                    // The legacy object-literal arm's per-literal state: the
                    // union-with-primitive verdict from the literal's OWN contextual
                    // type + the lazily-shared computed-key mapped-value arity.
                    val cur = spineIanyCtx?.takeIf { it.kind == 0 }
                    val ctxType = cur?.type
                    val viaUnion = ctxType is Type.Union && ctxType.types.any {
                        it !is Type.Object && !it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
                    }
                    spineIanyDefineCtx(node, SpineIanyCtx(kind = 3,
                        typed = cur?.typed == true, type = ctxType, viaUnion = viaUnion,
                        ann = cur?.ann))
                }
            }
            NodeKind.CALL_EXPRESSION -> {
                node as CallExpression
                if (spineIanyReached(node)) {
                    // The legacy CallExpression arm computed ctxProp once per call
                    // (before any argument walk, args or not).
                    // (IANY.1) round 798: the `typed` flag of a kind=1 state is read
                    // ONLY by the two ARGUMENT edges below, so when every argument is
                    // childless — the exact condition under which
                    // `spineIanyEdgeUnobservable` skips all of them — nothing can read
                    // it and `isCalleeResolvable` (a callee type resolution) is pure
                    // cost. The FRAME is still pushed: it shadows an enclosing kind=0
                    // state for the CALLEE's subtree, which an IIFE reads.
                    spineIanyDefineCtx(node, SpineIanyCtx(kind = 1,
                        typed = !spineIanyArgsAllChildless(node.arguments) &&
                            isCalleeResolvable(node.expression)))
                }
            }
            NodeKind.NEW_EXPRESSION -> {
                node as NewExpression
                if (spineIanyReached(node)) {
                    val args = node.arguments
                    spineIanyDefineCtx(node, SpineIanyCtx(kind = 1,
                        typed = args != null && !spineIanyArgsAllChildless(args) &&
                            isCalleeResolvable(node.expression)))
                }
            }
            else -> {}
        }
    }

    private fun spineIanyIsClassElement(node: Node): Boolean =
        (node as NodeBase).parent.let { it is ClassDeclaration || it is ClassExpression }

    /** Per-node LEAVE hook — pop every frame this node pushed (LIFO). */
    private fun spineIanyLeaveNode(node: Node) {
        val frames = spineIanyFrames
        while (frames.isNotEmpty() && frames[frames.size - 1].node === node) {
            SpineDispatch.work()
            val f = frames.removeAt(frames.size - 1)
            when (f.kind) {
                0 -> spineIanyCtx = f.savedCtx
                1 -> popImplicitAnyScope()
                2 -> implicitAnyNsStack.removeLast()
                3 -> implicitAnyEnclosingClassMembers = f.savedMembers
            }
        }
    }

    /** Edge-triggered handling at [node]'s enter (parent [p]): scope pushes,
     *  ns pushes, and the contextual-typing definitions of every edge the
     *  legacy recursion passed explicit arguments over. */
    private fun spineIanyEdgeEnter(p: Node, node: Node) {
        // (IANY.1) round 799 — the parent-edge dispatch below is a chain of 19
        // sequential `is` checks ending in `else -> {}`. A parent whose kind
        // matches none of them reaches that `else`, so the whole chain is pure
        // consultation. `spineIanyEdgeHasArm` answers the same question with ONE
        // tableswitch on the M0.2 `kindId`, and is a no-op by construction:
        // every arm below is a concrete node class, each stamped with exactly
        // the kind the gate lists (`NodeKindIdTest` pins that correspondence).
        if (!IanySections.armGateOff && !spineIanyEdgeHasArm((p as NodeBase).kindId)) return
        when (p) {
            is FunctionDeclaration -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
            }
            is MethodDeclaration -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
            }
            is Constructor -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
            }
            is GetAccessor -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
            }
            is SetAccessor -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
            }
            is FunctionExpression -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
            }
            is ArrowFunction -> if (node === p.body && spineIanyReached(node)) {
                spineIanyPushScope(node, p.parameters)
                if (node !is Block) {
                    // Round 472: an EXPRESSION body inherits the contextual
                    // signature's RETURN type (nothing else).
                    // (CHK.30) round 949: …and, FIRST, this arrow's OWN return
                    // annotation, which outranks any inherited context — tsc's
                    // `getContextualReturnType` consults `getReturnTypeFromAnnotation`
                    // before the contextual signature. A BLOCK body already got this
                    // from [spineIanyReturnCtxAt] at the ReturnStatement edge; only
                    // the CONCISE body had no path to it, so the curried factory
                    // `(dep: D): Handler => (a, b) => …` and the literal form
                    // `(): V => ({ m(node) { … } })` reported TS7006 on every
                    // parameter the annotation types (2 of knip's 3 residual rows).
                    val ownRet = p.type?.let { getTypeFromTypeNodeSafeNsAware(it) }
                        ?.takeIf { it !== anyType && it !== errorType }
                    val cur = spineIanyCtx?.takeIf { it.kind == 0 }
                    val retT = ownRet ?: contextualSigReturnTypeForCtx(cur?.type)
                    spineIanyDefineCtx(node,
                        if (retT != null) SpineIanyCtx(kind = 0, type = retT) else null)
                }
            }
            is ModuleDeclaration -> if (node === p.body && spineIanyReached(node)) {
                // Round 435c: the enclosing-namespace bridge for annotation
                // resolution inside the body.
                val nsSym = fileResults[spineFileName]?.nodeToSymbol?.get(nodeKey(p))?.takeIf {
                    it.flags.hasAny(SymbolFlags.Module or SymbolFlags.NamespaceModule or SymbolFlags.ValueModule)
                }
                if (nsSym != null) {
                    SpineDispatch.work()
                    implicitAnyNsStack.addLast(nsSym)
                    spineIanyFrames.add(SpineIanyFrame(node, 2))
                }
            }
            is VariableDeclaration -> if (node === p.initializer && spineIanyReached(node)) {
                spineIanyVarInitEdge(p, node)
            }
            is ExpressionStatement -> if (node === p.expression && spineIanyReached(node)) {
                spineIanyDefineCtx(node, null)
            }
            is ReturnStatement -> if (node === p.expression && spineIanyReached(node)) {
                val retAnn = spineIanyReturnCtxAt(p)
                // M1.6(b): resolve the annotation only for expr shapes that can
                // consume a contextual type (bounds first-touch resolution-order
                // changes to functions that return such shapes).
                // (CHK.40)(a): …and an ARRAY LITERAL is such a shape — the arm
                // below distributes the ELEMENT type into object-literal elements,
                // and without the array kind here it was handed no type at all, so
                // `function f(): V[] { return [{ m(node) {…} }] }` reported TS7006
                // where the annotated non-array form did not.
                val ctxShape = node is ObjectLiteralExpression || node is ArrowFunction ||
                    node is FunctionExpression || node is ParenthesizedExpression ||
                    node is ConditionalExpression || node is ArrayLiteralExpression
                val fromAnn = if (retAnn != null && ctxShape)
                    getTypeFromTypeNodeSafeNsAware(retAnn) else null
                // (CHK.40) STRICTLY ADDITIVE, and the `when` is written so that it
                // reads that way: an annotation that resolved keeps its own answer
                // (bar the async unwrap, which is the identity for everything
                // else), an annotation that did NOT resolve keeps answering null,
                // and only the no-annotation case — previously null — consults the
                // enclosing function's own CONTEXTUAL return type ((CHK.40)(d)).
                val retCtx = when {
                    !ctxShape -> null
                    fromAnn != null -> pullCtxAwaitIfAsyncAt(p, fromAnn)
                    retAnn != null -> null
                    else -> pullCtxReturnTypeAt(p, 0)
                }
                spineIanyDefineCtx(node, if (retCtx != null || retAnn != null)
                    SpineIanyCtx(kind = 0, type = retCtx, ann = retAnn) else null)
            }
            is PropertyDeclaration -> if (node === p.initializer && spineIanyReached(node) &&
                spineIanyIsClassElement(p)) {
                // classPropertyErrorOnNameOnly: annotated class prop with an
                // arrow/fn-expr initializer contextually types the params.
                val arrowInit = node is ArrowFunction || node is FunctionExpression
                val ctxFn = arrowInit && p.type != null
                val annotatedType = p.type?.let { getTypeFromTypeNodeSafe(it) }
                spineIanyDefineCtx(node, if (ctxFn || annotatedType != null)
                    SpineIanyCtx(kind = 0, typed = ctxFn, type = annotatedType) else null)
            }
            is PropertyAssignment -> if (node === p.initializer && spineIanyReached(node)) {
                spineIanyPropAssignEdge(p, node)
            }
            is CallExpression -> if (p.arguments.anyIdentical(node) && spineIanyReached(node)) {
                spineIanyCallArgEdge(p, node)
            }
            is NewExpression -> if (p.arguments?.anyIdentical(node) == true && spineIanyReached(node)) {
                val callCtx = spineIanyCtx
                spineIanyDefineCtx(node, if (callCtx != null && callCtx.kind == 1 && callCtx.typed)
                    SpineIanyCtx(kind = 0, typed = true) else null)
            }
            is BinaryExpression -> if (spineIanyReached(node)) {
                spineIanyBinaryEdge(p, node)
            }
            is ParenthesizedExpression -> if (node === p.expression && spineIanyReached(node)) {
                spineIanyPassThroughEdge(node)
            }
            is ConditionalExpression -> if ((node === p.whenTrue || node === p.whenFalse) &&
                spineIanyReached(node)) {
                spineIanyPassThroughEdge(node)
            }
            is ArrayLiteralExpression -> if (spineIanyReached(node)) {
                // Contextual typing through arrays: object-literal elements get
                // the array's ELEMENT type; bare arrows stay un-propagated.
                // (CHK.40)(a): …and a TUPLE contributes its element at THIS position,
                // which is why the index is computed here where the array-reference
                // case never needed one.
                val cur = spineIanyCtx?.takeIf { it.kind == 0 }
                val elemCtx = cur?.type?.let {
                    pullCtxArrayElementAt(it, p.elements.indexOfFirst { e -> e === node })
                }
                val typed = if (node is ArrowFunction || node is FunctionExpression) false
                    else cur?.typed == true
                spineIanyDefineCtx(node, if (typed || elemCtx != null || cur?.viaUnion == true)
                    SpineIanyCtx(kind = 0, typed = typed, type = elemCtx,
                        viaUnion = cur?.viaUnion == true) else null)
            }
            else -> {}
        }
    }

    /**
     * The CALL/NEW **argument** edge — round 799 measured it at **249 ms over
     * 31,575 edges (7.9 µs each), 32% of the whole handler**, the single
     * biggest concentration left in `spineIanyEnterNode`.
     *
     * Split out of [spineIanyEdgeEnter] so (IANY.1) round 800 can sub-partition
     * it (`--ianySections`: [IanySections.A_ARITY] / [IanySections.A_CPGNC] /
     * [IanySections.A_PRED] plus a deterministic census) without the probe
     * boundaries landing in the 19-arm `when`.
     *
     * **The invariant this arm rests on**: at a reached argument edge
     * `spineIanyCtx` is ALWAYS the CALL's own `kind = 1` frame — `reached(arg)`
     * implies `reached(call)`, the call's own arm then defines that frame
     * unconditionally, and every frame pushed inside the CALLEE's subtree is
     * popped at that subtree's leave. So `callCtx != null && callCtx.kind == 1`
     * is a tautology here and only `typed` decides.
     *
     * **Round 800's gate**: when [spineIanyArgSubtreeMayRead] answers that no
     * node in the argument's subtree can read a `kind = 0` state, the whole arm
     * is skipped — both the callee resolution and the frame. Skipping the frame
     * leaves the call's own `kind = 1` state visible below instead of this arm's
     * `kind = 0` / null, which is unobservable for the same reason: every reader
     * of a `kind = 0` state is one of the two kinds the predicate stops at.
     * `--ianyArgGateOff` restores the pre-800 arm in the same binary.
     */
    private fun spineIanyCallArgEdge(p: CallExpression, node: Node) {
        val probe = IanySections.mode != IanySections.OFF
        if (probe) IanySections.armEntries++
        if (node is ArrowFunction || node is FunctionExpression) {
            val t = if (probe) PassTiming.nowNanos() else 0L
            // B224: contextual arity for an arrow/fn-expr ARGUMENT.
            val argIndex = p.arguments.indexOfFirst { it === node }
            val ctxArity = contextualFnArityForCallArg(p.expression, argIndex)
            if (ctxArity != null) {
                val argParams = when (node) {
                    is ArrowFunction -> node.parameters
                    is FunctionExpression -> node.parameters
                }
                emitTs7006BeyondCtxArity(argParams, ctxArity, spineSource, spineFileName)
            }
            if (probe) {
                IanySections.armArity++
                IanySections.record(IanySections.A_ARITY, PassTiming.nowNanos() - t)
            }
        } else {
            // (IANY.1) round 800 — THE GATE. An arrow / function-expression
            // argument is a READER by construction, so the B224 emission above
            // can never be reached by it: the gate lives in this `else` branch
            // rather than at the top of the function precisely so that no future
            // edit of the reader set can silence an emission.
            val t = if (probe) PassTiming.nowNanos() else 0L
            // Under the probe the predicate ALWAYS runs — its cost and its
            // verdict are what the 249 ms has to be priced against — but it only
            // ACTS when the gate is on.
            val mayRead = if (probe || !IanySections.argGateOff)
                spineIanyArgSubtreeMayRead(node) else true
            if (probe) {
                IanySections.record(IanySections.A_PRED, PassTiming.nowNanos() - t)
                if (!mayRead) {
                    IanySections.armNoReader++
                    val c = spineIanyCtx
                    if (c != null && c.kind == 1 && c.typed) IanySections.armNoReaderCpgnc++
                }
            }
            if (!mayRead && !IanySections.argGateOff) return
        }
        val callCtx = spineIanyCtx
        var argHasCtx = callCtx != null && callCtx.kind == 1 && callCtx.typed
        if (probe && !argHasCtx) IanySections.armTypedFalse++
        if (argHasCtx) {
            val t = if (probe) PassTiming.nowNanos() else 0L
            if (probe) {
                IanySections.armCpgnc++
                val id = (p as NodeBase).nodeId
                val seen = spineIanyCpgncSeen
                if (id >= 0 && id < seen.size) {
                    if (seen[id].toInt() != 0) IanySections.armCpgncRepeat++
                    seen[id] = 1
                }
            }
            argHasCtx = !calleeParamGivesNoContext(p, p.arguments.indexOfFirst { it === node })
            if (probe) IanySections.record(IanySections.A_CPGNC, PassTiming.nowNanos() - t)
        }
        spineIanyDefineCtx(node, if (argHasCtx) SpineIanyCtx(kind = 0, typed = true) else null)
    }

    /**
     * (IANY.1) round 800 — **can ANY node in [root]'s subtree read the
     * contextual state the CALL argument edge defines?**
     *
     * The state is a `kind = 0` one, and its readers are exactly two node kinds:
     * the arrow / function-expression own arm (`spineIanyFnExprEnter`) and the
     * object-literal own arm. Every OTHER reader named in
     * `docs/perf/implicit-any-attribution.md` § 11 — an objlit `MethodDeclaration`,
     * the `PropertyAssignment` edge, an arrow's expression-body edge — sits
     * strictly inside one of those two, so those two ARE the reader set.
     *
     * The state PROPAGATES down through the arms that inherit it (paren /
     * conditional / array-literal / `||` `??` `&&` `,` operands) **and through
     * every parent kind with no arm at all**, which does not redefine it —
     * `as`, `!`, `satisfies`, unary, spread, member access, template spans.
     *
     * **`rhsCanConsumeFnCtx` cannot be reused here** (round 799 § 11) because it
     * descends neither of those. Round 800 measured which half of that argument
     * bites: **`f([{ m(a) {} }])` is a REAL counter-shape** (an ablation that
     * drops the array descent fails two pins), while **`f(<any>{ m(a) {} })` is
     * VACUOUS** — the no-arm kinds are exactly the kinds the REACH classifier
     * [spineIanyEdge] also lacks an arm for, so nothing below an `as` is walked
     * and there is no reader there at all. The no-arm descents below are
     * therefore DEAD TODAY and kept deliberately, as insurance for the day
     * `spineIanyEdge` gains such an arm; `IanyArgGateTest`'s "a no-arm parent is
     * not walked at all" pin is what will announce that day.
     *
     * It STOPS at a nested CALL/NEW: that node's own arm pushes a `kind = 1`
     * frame over its whole subtree, and if it is UNREACHED so is everything
     * below it (reach is monotone down the tree, and every reader is gated on
     * `spineIanyReached`) — so no reader below can see our state either way.
     *
     * Two properties that make it safe to gate on:
     * * **the default is `true`** — a kind not named here KEEPS the arm, so the
     *   predicate can only ever refuse to skip;
     * * it is **bounded, not quadratic**: the redefining kinds cut the descent,
     *   and a hard [IANY_ARG_SCAN_CAP] step cap answers `true` beyond it, which
     *   also removes the deep-`||`-chain stack hazard (the scan is iterative).
     */
    private fun spineIanyArgSubtreeMayRead(root: Node): Boolean {
        val r = spineIanyArgScanCore(root)
        if (IanySections.mode != IanySections.OFF) {
            IanySections.armPredSteps += spineIanyArgScanSteps.toLong()
        }
        return r
    }

    private fun spineIanyArgScanCore(root: Node): Boolean {
        val stack = spineIanyArgScan
        stack.clear()
        stack.add(root)
        var steps = 0
        while (stack.isNotEmpty()) {
            if (++steps > IANY_ARG_SCAN_CAP) {
                spineIanyArgScanSteps = steps
                if (IanySections.mode != IanySections.OFF) IanySections.armPredCapped++
                return true
            }
            val n = stack.removeAt(stack.size - 1)
            when ((n as NodeBase).kindId) {
                // ── the reader set ────────────────────────────────────────────
                NodeKind.ARROW_FUNCTION, NodeKind.FUNCTION_EXPRESSION,
                NodeKind.OBJECT_LITERAL_EXPRESSION -> {
                    spineIanyArgScanSteps = steps
                    return true
                }
                // ── arms that INHERIT the state — descend ─────────────────────
                NodeKind.PARENTHESIZED_EXPRESSION ->
                    stack.add((n as ParenthesizedExpression).expression)
                NodeKind.CONDITIONAL_EXPRESSION -> {
                    n as ConditionalExpression
                    stack.add(n.whenTrue); stack.add(n.whenFalse)
                }
                NodeKind.ARRAY_LITERAL_EXPRESSION ->
                    for (e in (n as ArrayLiteralExpression).elements) stack.add(e)
                NodeKind.BINARY_EXPRESSION -> {
                    n as BinaryExpression
                    when (n.operator) {
                        SyntaxKind.BarBar, SyntaxKind.QuestionQuestion -> {
                            stack.add(n.left); stack.add(n.right)
                        }
                        SyntaxKind.AmpersandAmpersand, SyntaxKind.Comma -> stack.add(n.right)
                        // every other operator's edge defines a null state
                        else -> {}
                    }
                }
                // ── NO ARM AT ALL: the state stays current below — descend ────
                NodeKind.AS_EXPRESSION -> stack.add((n as AsExpression).expression)
                NodeKind.SATISFIES_EXPRESSION -> stack.add((n as SatisfiesExpression).expression)
                NodeKind.NON_NULL_EXPRESSION -> stack.add((n as NonNullExpression).expression)
                NodeKind.TYPE_ASSERTION_EXPRESSION ->
                    stack.add((n as TypeAssertionExpression).expression)
                NodeKind.SPREAD_ELEMENT -> stack.add((n as SpreadElement).expression)
                NodeKind.AWAIT_EXPRESSION -> stack.add((n as AwaitExpression).expression)
                NodeKind.TYPE_OF_EXPRESSION -> stack.add((n as TypeOfExpression).expression)
                NodeKind.VOID_EXPRESSION -> stack.add((n as VoidExpression).expression)
                NodeKind.DELETE_EXPRESSION -> stack.add((n as DeleteExpression).expression)
                NodeKind.PREFIX_UNARY_EXPRESSION ->
                    stack.add((n as PrefixUnaryExpression).operand)
                NodeKind.POSTFIX_UNARY_EXPRESSION ->
                    stack.add((n as PostfixUnaryExpression).operand)
                NodeKind.PROPERTY_ACCESS_EXPRESSION ->
                    stack.add((n as PropertyAccessExpression).expression)
                NodeKind.ELEMENT_ACCESS_EXPRESSION -> {
                    n as ElementAccessExpression
                    stack.add(n.expression); stack.add(n.argumentExpression)
                }
                NodeKind.TEMPLATE_EXPRESSION ->
                    for (s in (n as TemplateExpression).templateSpans) stack.add(s.expression)
                NodeKind.YIELD_EXPRESSION ->
                    (n as YieldExpression).expression?.let { stack.add(it) }
                NodeKind.COMMA_LIST_EXPRESSION ->
                    for (e in (n as CommaListExpression).elements) stack.add(e)
                // ── stops: no reader can see our state below these ────────────
                NodeKind.CALL_EXPRESSION, NodeKind.NEW_EXPRESSION,
                NodeKind.IDENTIFIER, NodeKind.STRING_LITERAL_NODE,
                NodeKind.NUMERIC_LITERAL_NODE, NodeKind.BIG_INT_LITERAL_NODE,
                NodeKind.REGULAR_EXPRESSION_LITERAL_NODE,
                NodeKind.NO_SUBSTITUTION_TEMPLATE_LITERAL_NODE,
                NodeKind.OMITTED_EXPRESSION, NodeKind.META_PROPERTY -> {}
                // ── anything unmodelled KEEPS the arm ─────────────────────────
                else -> {
                    spineIanyArgScanSteps = steps
                    return true
                }
            }
        }
        spineIanyArgScanSteps = steps
        return false
    }

    /** The legacy Parenthesized/Conditional pass-through: (typed, type,
     *  viaUnion, viaAssign) inherited, ctxAnnotation RESET (omitted in the
     *  legacy calls). */
    private fun spineIanyPassThroughEdge(node: Node) {
        val cur = spineIanyCtx
        when {
            cur == null -> {}
            cur.kind != 0 -> spineIanyDefineCtx(node, null)
            cur.ann == null -> {} // unchanged
            else -> spineIanyDefineCtx(node, SpineIanyCtx(kind = 0, typed = cur.typed,
                type = cur.type, viaUnion = cur.viaUnion, viaAssign = cur.viaAssign))
        }
    }

    /**
     * The legacy BinaryExpression left-spine loop, expressed per edge (the
     * loop's per-operand actions depend only on each binary's own operator and
     * the inherited state): the RIGHT operand of an assignment-family operator
     * gets the M3.2 assignment-target context; `||`/`??`/`&&`/comma RIGHT
     * operands inherit the incoming context; the LEFT operand inherits it for
     * `||`/`??` only (the loop kept leftTyped across those and cleared it for
     * everything else); ctxAnnotation resets on every operand (omitted in the
     * legacy calls).
     */
    private fun spineIanyBinaryEdge(b: BinaryExpression, node: Node) {
        val cur = spineIanyCtx?.takeIf { it.kind == 0 }
        if (node === b.right) {
            when (b.operator) {
                SyntaxKind.Equals, SyntaxKind.BarBarEquals,
                SyntaxKind.AmpersandAmpersandEquals, SyntaxKind.QuestionQuestionEquals -> {
                    // Resolve the LHS type ONLY when the RHS can consume a fn
                    // context (bounds first-touch resolution-order changes and
                    // per-assignment cost to the shapes that need it).
                    implicitAnyCtxUnknowable = false
                    val lhsT = if (rhsCanConsumeFnCtx(b.right))
                        resolveAssignTargetCtxTypeForImplicitAny(b.left) else null
                    if (implicitAnyCtxUnknowable) {
                        // Round 474: the target member's annotation names an
                        // alias-shadowed interface — tsc HAS a contextual type
                        // here; treat the RHS as contextually typed rather than
                        // propagate the wrong resolution.
                        implicitAnyCtxUnknowable = false
                        spineIanyDefineCtx(node, SpineIanyCtx(kind = 0, typed = true))
                    } else {
                        spineIanyDefineCtx(node, if (lhsT != null)
                            SpineIanyCtx(kind = 0, type = lhsT, viaAssign = true) else null)
                    }
                }
                SyntaxKind.BarBar, SyntaxKind.QuestionQuestion,
                SyntaxKind.AmpersandAmpersand, SyntaxKind.Comma -> {
                    spineIanyInheritOperandEdge(node, cur)
                }
                else -> spineIanyDefineCtx(node, null)
            }
        } else { // node === b.left
            when (b.operator) {
                SyntaxKind.BarBar, SyntaxKind.QuestionQuestion ->
                    spineIanyInheritOperandEdge(node, cur)
                else -> spineIanyDefineCtx(node, null)
            }
        }
    }

    /** An operand edge that inherits (typed, type, viaUnion, viaAssign) with
     *  ctxAnnotation reset. */
    private fun spineIanyInheritOperandEdge(node: Node, cur: SpineIanyCtx?) {
        when {
            cur == null -> spineIanyDefineCtx(node, null)
            cur.ann == null -> {} // unchanged
            else -> spineIanyDefineCtx(node, SpineIanyCtx(kind = 0, typed = cur.typed,
                type = cur.type, viaUnion = cur.viaUnion, viaAssign = cur.viaAssign))
        }
    }

    /** The legacy object-literal PropertyAssignment initializer edge: the
     *  member's contextual type looked up on the literal's contextual type,
     *  the computed-key mapped-table special case, and the destructuring-
     *  default typed-key mode. */
    private fun spineIanyPropAssignEdge(prop: PropertyAssignment, init: Expression) {
        val ctx = spineIanyCtx
        if (ctx != null && ctx.kind == 2) {
            // Destructuring-default mode: the matched RHS property of a typed
            // default gets a contextual signature; others walk normally.
            val propName = (prop.name as? Identifier)?.text
            val t = propName != null && ctx.names?.contains(propName) == true
            spineIanyDefineCtx(init, if (t) SpineIanyCtx(kind = 0, typed = true) else null)
            return
        }
        val octx = ctx?.takeIf { it.kind == 3 }
        val typed = octx?.typed == true
        val viaUnion = octx?.viaUnion == true
        // (CHK.40)(c) …and a STRING-literal key names the same member here as it does
        // in `getTypeOfObjectLiteral`. A ComputedPropertyName still answers null, which
        // the M1.6(a) branch below depends on.
        val propName = pullCtxMemberName(prop.name)
        val octxType = octx?.type
        val propType = if (propName != null && octxType != null)
            lookupPropertyTypeForCtx(octxType, propName) else null
        // M1.6(a): a COMPUTED-key fn-expr/arrow value of a mapped-table
        // literal — emit only beyond the mapped value's arity, then walk the
        // fn with its own params marked contextually typed.
        if (propName == null && prop.name is ComputedPropertyName && !typed && !viaUnion &&
            (init is ArrowFunction || init is FunctionExpression)) {
            val cArity = spineIanyComputedKeyArity(octx)
            if (cArity != null) {
                val ps = when (init) {
                    is ArrowFunction -> init.parameters
                    is FunctionExpression -> init.parameters
                }
                emitTs7006BeyondCtxArity(ps, cArity, spineSource, spineFileName)
                spineIanyDefineCtx(init, SpineIanyCtx(kind = 0, typed = true))
                return
            }
        }
        spineIanyDefineCtx(init, if (typed || propType != null || viaUnion)
            SpineIanyCtx(kind = 0, typed = typed, type = propType, viaUnion = viaUnion)
            else null)
    }

    /** The lazily-computed (once per literal) computed-key mapped-value arity
     *  (M1.6(a)) — stored on the literal's kind-3 ctx. */
    private fun spineIanyComputedKeyArity(octx: SpineIanyCtx?): Int? {
        if (octx == null) return null
        if (!octx.arityComputed) {
            octx.arityComputed = true
            octx.arity = octx.ann?.let { mappedAnnotationValueFnArity(it) }
        }
        return octx.arity
    }

    /** The legacy arrow/function-expression parameter emission (uses the
     *  node's incoming contextual-typing state). */
    private fun spineIanyFnExprEnter(params: List<Parameter>) {
        val cur = spineIanyCtx?.takeIf { it.kind == 0 }
        if (cur?.typed == true) return
        val ctxType = cur?.type
        val unionSuppress = ctxType != null && unionHasFunctionAndPrimitive(ctxType)
        if (unionSuppress) return
        // M1.6(b): a callable contextual type supplies param types up to its
        // arity — TS7006 only beyond it.
        val ctxArity = when {
            cur?.viaUnion == true -> null
            cur?.viaAssign == true -> singleApplicableSigArity(ctxType, requiredParamPrefixCount(params))
            else -> contextualCallableArity(ctxType)
        }
        if (ctxArity != null) {
            emitTs7006BeyondCtxArity(params, ctxArity, spineSource, spineFileName)
        } else {
            checkParamsForImplicitAny(params, spineSource, spineFileName)
        }
    }

    /** The legacy object-literal METHOD member emission (contextually typed by
     *  the matching member's fn type, same as an arrow value). */
    private fun spineIanyObjLitMethodEnter(prop: MethodDeclaration) {
        val octx = spineIanyCtx?.takeIf { it.kind == 3 }
        if (octx?.typed == true) return
        // (CHK.40)(c) …including a STRING-literal member name: `{ "m-x"(node) {…} }`
        // is the same member the PropertyAssignment path has always accepted, and
        // reading only `Identifier` here reported TS7006 for it.
        val mName = pullCtxMemberName(prop.name)
        val octxType = octx?.type
        val mType = if (mName != null && octxType != null)
            lookupPropertyTypeForCtx(octxType, mName) else null
        val mArity = if (octx?.viaUnion == true) null else
            contextualCallableArity(mType)
                ?: (if (prop.name is ComputedPropertyName) spineIanyComputedKeyArity(octx) else null)
        if (mArity != null) {
            emitTs7006BeyondCtxArity(prop.parameters, mArity, spineSource, spineFileName)
        } else {
            checkParamsForImplicitAny(prop.parameters, spineSource, spineFileName)
        }
    }

    /** The legacy non-ambient class-element enter: the enclosing-class-members
     *  frame (round 470 — ClassExpression members KEEP the outer value, the
     *  siblings.ifEmpty quirk) plus the element's own emissions. Bodies are
     *  handled at their body edges; initializers at the initializer edge. */
    private fun spineIanyClassElementEnter(element: ClassElement) {
        val parentCls = (element as NodeBase).parent
        if (parentCls is ClassDeclaration) {
            spineIanyFrames.add(SpineIanyFrame(element, 3,
                savedMembers = implicitAnyEnclosingClassMembers))
            implicitAnyEnclosingClassMembers = parentCls.members
        }
        when (element) {
            is MethodDeclaration ->
                checkParamsForImplicitAny(element.parameters, spineSource, spineFileName)
            is Constructor ->
                checkParamsForImplicitAny(element.parameters, spineSource, spineFileName)
            is SetAccessor -> {
                // Setter value parameters are contextually typed from a sibling
                // getter. When ANY sibling getter with the same name exists,
                // suppress TS7032/TS7006; otherwise emit BOTH. Class-EXPRESSION
                // members passed EMPTY siblings in the legacy walk (the
                // checkImplicitAnyInClassElement default) — bug-compat: their
                // setters always fire.
                val siblings = (parentCls as? ClassDeclaration)?.members ?: emptyList()
                val nameNode = element.name as? Identifier
                val firstParam = element.parameters.firstOrNull()
                if (nameNode != null && firstParam != null && firstParam.type == null) {
                    val hasSiblingGetter = siblings.filterIsInstance<GetAccessor>().any {
                        (it.name as? Identifier)?.text == nameNode.text
                    }
                    if (!hasSiblingGetter && nameNode.text.isNotEmpty()) {
                        val (line, character) = getLineAndCharacterOfPosition(spineSource, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Property '${nameNode.text}' implicitly has type 'any', because its set accessor lacks a parameter type annotation.",
                            category = DiagnosticCategory.Error,
                            code = 7032,
                            fileName = spineFileName,
                            line = line, character = character,
                            start = nameNode.pos, length = nameNode.text.length,
                        ))
                        checkParamsForImplicitAny(element.parameters, spineSource, spineFileName)
                    }
                }
            }
            is PropertyDeclaration -> {
                // Check function type annotation: `pub_f10: (x) => string`.
                checkImplicitAnyInTypeAnnotation(element.type, spineSource, spineFileName)
                // TS7008: static property without type annotation or initializer.
                if (element.type == null && element.initializer == null
                    && ModifierFlag.Static in element.modifiers
                    && ModifierFlag.Private !in element.modifiers
                    && !element.exclamationToken) {
                    val name = element.name
                    if (name is Identifier && name.text.isNotEmpty()) {
                        val siblings = (parentCls as? ClassDeclaration)?.members ?: emptyList()
                        val assignedInStaticBlock = siblings.any { sib ->
                            sib is ClassStaticBlockDeclaration &&
                                blockAssignsToThisProperty(sib.body.statements, name.text)
                        }
                        if (!assignedInStaticBlock) {
                            val start = name.pos
                            val (line, character) = getLineAndCharacterOfPosition(spineSource, start)
                            diagnostics.add(Diagnostic(
                                message = "Member '${name.text}' implicitly has an 'any' type.",
                                category = DiagnosticCategory.Error,
                                code = 7008,
                                fileName = spineFileName,
                                line = line, character = character,
                                start = start, length = name.text.length,
                            ))
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /** The legacy ambient-class member handling, inline at the class enter
     *  (no element walk, no body descent). */
    private fun spineIanyAmbientClassMembers(stmt: ClassDeclaration) {
        for (member in stmt.members) {
            when (member) {
                is MethodDeclaration -> {
                    // Public method params in ambient classes get TS7006;
                    // private methods are not checked.
                    if (ModifierFlag.Private !in member.modifiers) {
                        checkParamsForImplicitAny(member.parameters, spineSource, spineFileName)
                    }
                }
                is PropertyDeclaration -> {
                    // TS7008: member without type annotation (public only).
                    if (member.type == null && member.initializer == null
                        && ModifierFlag.Private !in member.modifiers) {
                        val name = member.name
                        if (name is Identifier && name.text.isNotEmpty()) {
                            val start = name.pos
                            val (line, character) = getLineAndCharacterOfPosition(spineSource, start)
                            diagnostics.add(Diagnostic(
                                message = "Member '${name.text}' implicitly has an 'any' type.",
                                category = DiagnosticCategory.Error,
                                code = 7008,
                                fileName = spineFileName,
                                line = line, character = character,
                                start = start, length = name.text.length,
                            ))
                        }
                    }
                    // Fn-typed property annotations get TS7006 (public AND private).
                    checkImplicitAnyInTypeAnnotation(member.type, spineSource, spineFileName)
                }
                is Constructor -> {
                    if (ModifierFlag.Private !in member.modifiers) {
                        checkParamsForImplicitAny(member.parameters, spineSource, spineFileName)
                    }
                }
                else -> {}
            }
        }
    }

    /** The legacy interface member handling, inline at the interface enter
     *  (interfaces are implicitly ambient — no member walk). */
    private fun spineIanyInterfaceMembers(stmt: InterfaceDeclaration) {
        for (member in stmt.members) {
            when (member) {
                is MethodDeclaration ->
                    checkParamsForImplicitAny(member.parameters, spineSource, spineFileName, typePosition = true)
                is PropertyDeclaration -> {
                    if (member.type == null && member.initializer == null) {
                        val name = member.name
                        if (name is Identifier && name.text.isNotEmpty()) {
                            val start = name.pos
                            val (line, character) = getLineAndCharacterOfPosition(spineSource, start)
                            diagnostics.add(Diagnostic(
                                message = "Member '${name.text}' implicitly has an 'any' type.",
                                category = DiagnosticCategory.Error,
                                code = 7008,
                                fileName = spineFileName,
                                line = line, character = character,
                                start = start, length = name.text.length,
                            ))
                        }
                    }
                    checkImplicitAnyInTypeAnnotation(member.type, spineSource, spineFileName)
                }
                else -> {}
            }
        }
    }

    /** The legacy VariableStatement per-declarator processing that ran BEFORE
     *  the initializer walk: the M3.2 scope recording, the ambient TS7005, and
     *  the annotation walk. */
    private fun spineIanyVarDeclEnter(decl: VariableDeclaration) {
        val list = (decl as NodeBase).parent as? VariableDeclarationList ?: return
        val stmt = (list as NodeBase).parent as? VariableStatement ?: return
        // M3.2 (round 431): register the local in the innermost implicit-any
        // scope — annotation, `as T` cast type, or callee return annotation;
        // null = declared UNTYPED (keeps TS7006 firing on assignments).
        implicitAnyScopes.lastOrNull()?.let { scope ->
            val dn = decl.name
            if (dn is Identifier && dn.text.isNotEmpty()) {
                scope[dn.text] = decl.type
                    ?: (decl.initializer as? AsExpression)?.type
                    ?: calleeReturnAnnotationForImplicitAny(decl.initializer)
                // Round 435c: an annotation-less initialized local also records
                // its INITIALIZER (resolved lazily at a consuming assignment).
                if (decl.type == null) decl.initializer?.let {
                    implicitAnyScopeInits.lastOrNull()?.put(dn.text, it)
                }
            } else {
                collectBindingNamesForImplicitAny(dn, scope)
                // Round 464: record each TOP-LEVEL object-destructured element's
                // source + property name.
                val dInit = decl.initializer
                if (dn is ObjectBindingPattern && dInit != null) {
                    implicitAnyScopeDestructures.lastOrNull()?.let { dmap ->
                        for (el in dn.elements) {
                            val inner = el.name as? Identifier ?: continue
                            if (inner.text.isEmpty() || el.dotDotDotToken) continue
                            val prop = (el.propertyName as? Identifier)?.text ?: inner.text
                            dmap[inner.text] = dInit to prop
                        }
                    }
                }
            }
        }
        // TS7005: variable implicitly has an 'any' type (ambient declarations only).
        if (decl.type == null && decl.initializer == null
            && (ModifierFlag.Declare in stmt.modifiers || spineIanyAmbientAt(stmt))) {
            val name = decl.name
            if (name is Identifier && name.text.isNotEmpty()) {
                val start = name.pos
                val (line, character) = getLineAndCharacterOfPosition(spineSource, start)
                diagnostics.add(Diagnostic(
                    message = "Variable '${name.text}' implicitly has an 'any' type.",
                    category = DiagnosticCategory.Error,
                    code = 7005,
                    fileName = spineFileName,
                    line = line, character = character,
                    start = start, length = name.text.length,
                ))
            }
        }
        // `var f: (x) => string` → TS7006 for `x`.
        checkImplicitAnyInTypeAnnotation(decl.type, spineSource, spineFileName)
        // The legacy walker resolved the shape-B contextual annotation EAGERLY
        // at the declarator (initializer or not); mirror the resolution here so
        // first-touch cache order stays close, stashing the result for the
        // initializer edge.
        if (!(decl.name is ObjectBindingPattern && decl.initializer is ObjectLiteralExpression)) {
            spineIanyPendingAnnDecl = decl
            spineIanyPendingAnnType = decl.type?.let { resolveImplicitAnyCtxAnnotation(it) }
        } else {
            spineIanyPendingAnnDecl = null
            spineIanyPendingAnnType = null
        }
    }

    /** The legacy VariableStatement initializer walk's context computation
     *  (shape A: the destructuring-default typed-key mode; shape B: the
     *  annotated/arrow/jsDoc contextual typing + the B224 arity emission). */
    private fun spineIanyVarInitEdge(decl: VariableDeclaration, init: Expression) {
        val declName = decl.name
        if (declName is ObjectBindingPattern && init is ObjectLiteralExpression) {
            // Destructuring with typed-function default values: those RHS
            // properties get a contextual signature; others walk normally.
            val typedDefaults = HashSet<String>()
            for (be in declName.elements) {
                val beInit = be.initializer ?: continue
                if (!isTypedFunctionExpr(beInit)) continue
                val key = ((be.propertyName as? Identifier)?.text)
                    ?: ((be.name as? Identifier)?.text)
                    ?: continue
                typedDefaults.add(key)
            }
            spineIanyDefineCtx(init, SpineIanyCtx(kind = 2, names = typedDefaults))
            return
        }
        val annotatedType = if (spineIanyPendingAnnDecl === decl) spineIanyPendingAnnType
            else decl.type?.let { resolveImplicitAnyCtxAnnotation(it) }
        spineIanyPendingAnnDecl = null
        spineIanyPendingAnnType = null
        val arrowInit = init is ArrowFunction || init is FunctionExpression
        // B437c: in a JS file, a leading JSDoc whose @param tags document EVERY
        // param of the arrow/fn-expr initializer types those params.
        val list = (decl as NodeBase).parent as? VariableDeclarationList
        val stmt = list?.let { (it as NodeBase).parent } as? VariableStatement
        val jsDocParamCtx = arrowInit && isJsLikeFileName(spineFileName) && run {
            val ip = when (init) {
                is ArrowFunction -> init.parameters
                is FunctionExpression -> init.parameters
            }
            if (ip.isEmpty()) return@run false
            val documented = jsDocDocumentedParamNames(stmt?.leadingComments ?: emptyList()) +
                jsDocDocumentedParamNames(decl.leadingComments)
            if (documented.isEmpty()) return@run false
            ip.all { p -> p.type != null || (p.name as? Identifier)?.text?.let { it in documented } == true }
        }
        val ctxFn = (arrowInit && decl.type != null) || jsDocParamCtx
        // B224: a bare rest-free FunctionType annotation contextually types
        // only its OWN arity worth of params.
        val annNode = decl.type
        if (arrowInit && annNode is FunctionType
            && annNode.parameters.none { it.dotDotDotToken }) {
            val ctxArity = annNode.parameters.count {
                !it.isCommentPlaceholder && (it.name as? Identifier)?.text != "this"
            }
            val initParams = when (init) {
                is ArrowFunction -> init.parameters
                is FunctionExpression -> init.parameters
            }
            emitTs7006BeyondCtxArity(initParams, ctxArity, spineSource, spineFileName)
        }
        spineIanyDefineCtx(init, if (ctxFn || annotatedType != null || decl.type != null)
            SpineIanyCtx(kind = 0, typed = ctxFn, type = annotatedType, ann = decl.type)
            else null)
    }

    /**
     * Pre-scan a function/method body for nested function declarations and
     * variable declarations whose annotated type or initializer would resolve
     * to a callable shape. The resulting types power TS2774 lookups for
     * PropertyAccessExpression / Identifier operands that refer to bindings
     * declared in the enclosing function scope.
     */
    private fun collectUncalledTypedLocalsFromBody(body: Block, into: MutableMap<String, Type>, shadowed: MutableSet<String>) {
        for (stmt in body.statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    val fnName = (stmt.name)?.text ?: continue
                    val sigType = buildCallableTypeForLocalFunction(stmt) ?: continue
                    into[fnName] = sigType
                    shadowed.add(fnName)
                }
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    // A DESTRUCTURED binding (`const { hasReturn } = commentOwnerInfo`) shadows an
                    // outer same-named binding just like a simple `const x` — register every binding
                    // name as a shadow so TS2774 bails instead of resolving `hasReturn` to a same-file
                    // `function hasReturn` (jsDoc.ts getDocCommentTemplateAtPosition FP'd "always
                    // defined, did you mean to call it"). Shadow-only (no per-element typing here) —
                    // consistent with an untyped simple local, which also only registers the shadow.
                    if (d.name !is Identifier) {
                        collectBindingNames(d.name, shadowed)
                        continue
                    }
                    val vName = d.name.text
                    val annotated = d.type?.let { getTypeFromTypeNode(it) }
                    val init = d.initializer
                    val resolved: Type? = when {
                        annotated != null && annotated !== errorType && annotated !== anyType -> annotated
                        // M1.12: a bare-identifier initializer referencing a binding that a
                        // uncalled-scope already knows takes THAT binding's collected type, NOT
                        // getTypeOfExpression — which resolves in file/global scope (this pass
                        // sets up no local param scope) and finds an OUTER binding, mis-typing
                        // `let shouldElaborateErrors = reportErrors` (a boolean param) as a
                        // callable → spurious TS2774. Two cases: the binding is in THIS scope
                        // being collected (an enclosing param / earlier local → `shadowed`/`into`,
                        // not yet on the stack), or in an ENCLOSING scope already pushed
                        // (`isUncalledShadowed`/`lookupUncalledTypedLocal` — a `let X = param` in
                        // a nested block of the fn). The type is boolean for a typed param, or
                        // null (→ shadow-only bail) for an untyped one; a same-scope local
                        // FUNCTION is recorded as callable, so a genuine `let f = localFn; if (f)`
                        // keeps firing.
                        init is Identifier && init.text in shadowed -> into[init.text]
                        init is Identifier && isUncalledShadowed(init.text) -> lookupUncalledTypedLocal(init.text)
                        init != null -> getTypeOfExpression(init)
                            .takeIf { it !== anyType && it !== errorType }
                        else -> null
                    }
                    // A local var/const/let ALWAYS shadows an outer binding of the
                    // same name — so TS2774 must bail rather than resolve the operand
                    // to an outer `function <name>` — REGARDLESS of whether we can type
                    // the initializer. tsc's own emitter.ts trips this:
                    //   const emitComments = state.stack[i] = shouldEmitComments(node);
                    //   if (emitComments) ...
                    // the initializer (an element-access assignment) types to `any`, so
                    // `resolved` is null; without registering the shadow, `emitComments`
                    // fell through to the outer `function emitComments` and FP'd
                    // "always defined, did you mean to call it". Register the shadow
                    // unconditionally; only feed `typed` when we could resolve a type.
                    shadowed.add(vName)
                    if (resolved != null) {
                        into[vName] = resolved
                    }
                }
                else -> {}
            }
        }
    }

    /** Resolve the instance type for `this` inside a class body. */
    private fun resolveUncalledThisType(cls: ClassDeclaration): Type? {
        val name = cls.name?.text ?: return null
        val symbol = currentFileLocals?.get(name) ?: globals[name] ?: return null
        if (!symbol.flags.hasAny(SymbolFlags.Class)) return null
        return getDeclaredTypeOfSymbol(symbol).takeIf { it !== anyType && it !== errorType }
    }

    /** Build an anonymous Type.Object with a single call signature for a local function declaration. */
    private fun buildCallableTypeForLocalFunction(fn: FunctionDeclaration): Type? {
        // Build minimal call signature; param/return types are unimportant for the
        // "always callable + not nullish" classification used by TS2774.
        val sig = Signature(
            parameters = emptyList(),
            resolvedReturnType = anyType,
            minArgumentCount = 0,
        )
        val obj = Type.Object()
        obj.callSignatures = listOf(sig)
        return obj
    }

    // (withUncalledScope / withUncalledBlockScope deleted — INV.4(d) walker 1:
    // the levels are rebuilt pull-based in [spineUncalledWithScopes]. The old
    // 17.30c.i note survives there: a free-standing statement Block contributes
    // a typed-locals level because block-scoped consts/lets are not in
    // `currentLocalTypes` / `currentFileLocals`.)

    /**
     * Walk a truthiness-test expression and emit TS2774 for each operand that
     * is an "always defined" callable identifier or property-access path.
     *
     * For `&&` operators, walks BOTH operands and adds the OTHER operand to
     * suppression sources (so `isFoo && isFoo()` does not emit on `isFoo` —
     * the sibling `isFoo()` is a call referencing the same path).
     * For `||`/`??` operators, walks BOTH operands but does NOT add siblings
     * to suppression sources (`isFoo || isFoo()` still emits on `isFoo`).
     * Mirrors TypeScript's `bothHelper`/`helper` truthiness-walker pair.
     */
    private fun checkUncalledInCondition(
        cond: Expression,
        body: Statement?,
        source: String,
        fileName: String,
        extraBodies: List<Expression> = emptyList(),
        inTestPosition: Boolean = true,
    ) {
        walkUncalledChain(cond, body, source, fileName, extraBodies, andSiblings = emptyList(), inTestPosition = inTestPosition)
    }

    private fun walkUncalledChain(
        expr: Expression,
        body: Statement?,
        source: String,
        fileName: String,
        extraBodies: List<Expression>,
        andSiblings: List<Expression>,
        inTestPosition: Boolean,
    ) {
        var cur: Expression = expr
        while (cur is ParenthesizedExpression) cur = cur.expression
        if (cur is BinaryExpression) {
            when (cur.operator) {
                SyntaxKind.AmpersandAmpersand -> {
                    // `&&`: LHS truthiness is always tested for short-circuit; RHS
                    // truthiness becomes the operator's result and is "tested" only
                    // when the parent context is itself a test (mirrors TypeScript's
                    // bothHelper/helper asymmetry — see `truthinessCallExpressionCoercion2`
                    // where RHS of `&&` inside an ExpressionStatement does NOT fire).
                    walkUncalledChain(cur.left, body, source, fileName, extraBodies, andSiblings + cur.right, inTestPosition = true)
                    walkUncalledChain(cur.right, body, source, fileName, extraBodies, andSiblings + cur.left, inTestPosition = inTestPosition)
                    return
                }
                SyntaxKind.BarBar, SyntaxKind.QuestionQuestion -> {
                    // `||`/`??`: walk both operands; siblings are NOT suppression sources
                    // (because the right side may not execute when left is truthy).
                    // Same asymmetric in-test-position propagation as `&&`.
                    walkUncalledChain(cur.left, body, source, fileName, extraBodies, andSiblings, inTestPosition = true)
                    walkUncalledChain(cur.right, body, source, fileName, extraBodies, andSiblings, inTestPosition = inTestPosition)
                    return
                }
                else -> {}
            }
        }
        // Leaf: emit only when the operand's truthiness is actually being tested.
        if (!inTestPosition) return
        emitUncalledHelper(cur, body, source, fileName, extraBodies + andSiblings)
        emitPromiseConditionHelper(cur, body, source, fileName, extraBodies + andSiblings)
    }

    /**
     * TS2801: testing a non-nullable `Promise<T>` value for truthiness is always true (a
     * Promise object is always defined). Emit "This condition will always return true since
     * this 'Promise<T>' is always defined." + related TS2773 "Did you forget to use 'await'?".
     * Mirrors `emitUncalledHelper` but for awaitable types instead of callable ones. Suppressed
     * when the operand is a reference path (`p`, `obj.p`) that the then-body or a sibling
     * `&&` operand references (matches TS — see `truthinessPromiseCoercion.ts` g()/h()); a
     * call expression (`pf()`) has no reference path, so it is never suppressed. `!!p` / `!p`
     * coerce to boolean and never reach this (PrefixUnary leaf is skipped). A nullable union
     * (`null | Promise<T>`) is a `Type.Union`, not a bare `Type.Reference`, so it is skipped.
     */
    private fun emitPromiseConditionHelper(operand: Expression, body: Statement?, source: String, fileName: String, extraBodies: List<Expression>) {
        var location: Expression = operand
        while (location is ParenthesizedExpression) location = location.expression
        if (location is PrefixUnaryExpression || location is BinaryExpression || location is AwaitExpression) return
        val path = extractUncalledPath(location)
        val type = (if (path != null && path.isNotEmpty()) resolveUncalledOperandType(location, path) else null)
            ?: (getTypeOfExpression(location))
        if (type === errorType || type === anyType || type === unknownType) return
        if (type !is Type.Reference || type.target.symbol?.name != "Promise") return
        if (typeIsPossiblyNullish(type)) return
        if (path != null && path.isNotEmpty()) {
            if (body != null && bodyReferencesPath(body, path)) return
            if (extraBodies.any { expressionReferencesPath(it, path) }) return
        }
        val start = location.pos
        val length = expressionTrueEnd(location) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val typeStr = typeToString(type)
        diagnostics.add(Diagnostic(
            message = "This condition will always return true since this '$typeStr' is always defined.",
            category = DiagnosticCategory.Error,
            code = 2801,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "Did you forget to use 'await'?",
                category = DiagnosticCategory.Message,
                code = 2773,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            )),
        ))
    }

    private fun emitUncalledHelper(operand: Expression, body: Statement?, source: String, fileName: String, extraBodies: List<Expression> = emptyList()) {
        var location: Expression = operand
        while (location is ParenthesizedExpression) location = location.expression
        // Skip non-checkable kinds
        if (location is CallExpression) return
        if (location is NewExpression) return
        if (location is AwaitExpression) return
        if (location is PrefixUnaryExpression) return
        if (location is BinaryExpression) return

        // Extract the property path: head + property names. Returns null if the
        // expression isn't a pure Identifier or PropertyAccessExpression chain
        // (e.g. contains a CallExpression base) — those aren't supported.
        val path = extractUncalledPath(location) ?: return
        if (path.isEmpty()) return

        // Resolve the type at the operand position using typed-locals scope when
        // available (parameters, local function/var decls, `this.X` chains).
        val type = resolveUncalledOperandType(location, path) ?: return
        if (type === errorType || type === anyType) return
        if (!isAlwaysCallableType(type)) return
        if (typeIsPossiblyNullish(type)) return

        if (body != null && bodyReferencesPath(body, path)) return
        if (extraBodies.any { expressionReferencesPath(it, path) }) return

        val start = location.pos
        val length = expressionTrueEnd(location) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This condition will always return true since this function is always defined. Did you mean to call it instead?",
            category = DiagnosticCategory.Error,
            code = 2774,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Extract the property path of an Identifier-or-PropertyAccessExpression chain.
     * For Identifier(`x`) returns ["x"]. For `this.foo.bar` returns ["this", "foo", "bar"].
     * Returns null if any segment's base isn't an Identifier or PropertyAccessExpression
     * (e.g. `f().bar` — base of `.bar` is a CallExpression — is rejected).
     */
    private fun extractUncalledPath(operand: Expression): List<String>? {
        val rev = mutableListOf<String>()
        var cur: Expression = operand
        while (cur is PropertyAccessExpression) {
            rev.add(cur.name.text)
            cur = cur.expression
            while (cur is ParenthesizedExpression) cur = cur.expression
        }
        if (cur !is Identifier) return null
        rev.add(cur.text)
        return rev.reversed()
    }

    /**
     * Resolve the type at an Identifier or PropertyAccessExpression operand using
     * the typed-locals stack at the head, then walking property segments via
     * `getApparentType` + `getPropertyOfType`. Returns null when the operand
     * cannot be classified (head is shadowed without typed info, or any segment
     * resolves to anyType / errorType).
     */
    private fun resolveUncalledOperandType(operand: Expression, path: List<String>): Type? {
        val head = path[0]
        // Resolve head type
        val headType: Type = when {
            head == "this" -> uncalledThisTypeStack.lastOrNull() ?: return null
            else -> {
                lookupUncalledTypedLocal(head) ?: run {
                    // Fall back to identifier resolution. If shadowed without typed
                    // info, bail to avoid resolving to an unrelated outer binding.
                    if (isUncalledShadowed(head)) return null
                    val headExpr = if (operand is Identifier) operand else findHeadIdentifier(operand) ?: return null
                    val t = getTypeOfIdentifier(headExpr)
                    if (t === anyType || t === errorType) return null
                    t
                }
            }
        }
        // Walk property chain
        var t = headType
        for (i in 1 until path.size) {
            if (t === anyType || t === errorType) return null
            val app = getApparentType(t)
            val prop = getPropertyOfType(app, path[i]) ?: return null
            t = if (app is Type.Reference) {
                resolveGenericPropertyType(app, prop) ?: getTypeOfSymbol(prop)
            } else {
                getTypeOfSymbol(prop)
            }
            // Honor optional class properties / interface members: `foo?: T`
            // adds undefined to the property type for nullish-detection purposes.
            // Round 479: ANY optional declaration counts — a cross-file
            // class+interface merge (harness fakesHosts `class System { realpath() }`
            // vs compiler sys.ts `interface System { realpath?() }`) pollutes the
            // merged prop's declarations, and isOptionalProperty reads only the
            // first; for THIS nullish-detection purpose any-optional is the
            // conservative (suppressing) direction — tsc resolves the un-merged
            // interface member, which is optional.
            if (isOptionalProperty(prop) || prop.declarations.any { d ->
                    (d as? MethodDeclaration)?.questionToken == true ||
                        (d as? PropertyDeclaration)?.questionToken == true
                }
            ) {
                t = getUnionType(listOf(t, undefinedType))
            }
        }
        if (t === anyType || t === errorType) return null
        return t
    }

    private fun findHeadIdentifier(expr: Expression): Identifier? {
        var cur: Expression = expr
        while (cur is PropertyAccessExpression) {
            cur = cur.expression
            while (cur is ParenthesizedExpression) cur = cur.expression
        }
        return cur as? Identifier
    }

    private fun isAlwaysCallableType(type: Type): Boolean {
        return when (type) {
            is Type.Object -> {
                resolveStructuredTypeMembers(type)
                !type.callSignatures.isNullOrEmpty()
            }
            is Type.Union -> type.types.isNotEmpty() && type.types.all { isAlwaysCallableType(it) }
            else -> false
        }
    }

    private fun typeIsPossiblyNullish(type: Type): Boolean {
        return when (type) {
            is Type.Union -> type.types.any { typeIsPossiblyNullish(it) }
            else -> type.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)
        }
    }

    private fun bodyReferencesName(stmt: Statement, name: String): Boolean = statementReferencesName(stmt, name)

    /** Path-aware body suppression: `bodyReferencesPath(body, ["a", "stats", "isDirectory"])` returns true if the body uses `a.stats.isDirectory` (or a call on it) anywhere. */
    private fun bodyReferencesPath(stmt: Statement, path: List<String>): Boolean {
        if (path.size == 1) return statementReferencesName(stmt, path[0])
        return statementReferencesPath(stmt, path)
    }

    private fun statementReferencesPath(stmt: Statement, path: List<String>): Boolean {
        when (stmt) {
            is Block -> return stmt.statements.any { statementReferencesPath(it, path) }
            is ExpressionStatement -> return expressionReferencesPath(stmt.expression, path)
            is ReturnStatement -> return stmt.expression?.let { expressionReferencesPath(it, path) } ?: false
            is IfStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.thenStatement, path)) return true
                stmt.elseStatement?.let { if (statementReferencesPath(it, path)) return true }
            }
            is WhileStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is DoStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is ForStatement -> {
                stmt.condition?.let { if (expressionReferencesPath(it, path)) return true }
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is ForInStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is ForOfStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                if (statementReferencesPath(stmt.statement, path)) return true
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { if (expressionReferencesPath(it, path)) return true }
            }
            is SwitchStatement -> {
                if (expressionReferencesPath(stmt.expression, path)) return true
                for (c in stmt.caseBlock) {
                    if (c is CaseClause && expressionReferencesPath(c.expression, path)) return true
                    val stmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                    if (stmts.any { statementReferencesPath(it, path) }) return true
                }
            }
            is TryStatement -> {
                if (stmt.tryBlock.statements.any { statementReferencesPath(it, path) }) return true
                stmt.catchClause?.let { if (it.block.statements.any { s -> statementReferencesPath(s, path) }) return true }
                stmt.finallyBlock?.let { if (it.statements.any { s -> statementReferencesPath(s, path) }) return true }
            }
            is ThrowStatement -> return stmt.expression?.let { expressionReferencesPath(it, path) } ?: false
            is LabeledStatement -> return statementReferencesPath(stmt.statement, path)
            else -> {}
        }
        return false
    }

    private fun expressionReferencesPath(expr: Expression, path: List<String>): Boolean {
        // Try to extract this expression's own path; if it matches `path`, this is a reference.
        extractUncalledPath(expr)?.let { ownPath ->
            // Single-name path: name shadowing rules already enforced by descend logic.
            if (ownPath == path) return true
        }
        // Recurse into children for nested matches.
        when (expr) {
            is PropertyAccessExpression -> return expressionReferencesPath(expr.expression, path)
            is BinaryExpression -> return expressionReferencesPath(expr.left, path) || expressionReferencesPath(expr.right, path)
            is ParenthesizedExpression -> return expressionReferencesPath(expr.expression, path)
            is CallExpression -> {
                if (expressionReferencesPath(expr.expression, path)) return true
                return expr.arguments.any { expressionReferencesPath(it, path) }
            }
            is NewExpression -> {
                if (expressionReferencesPath(expr.expression, path)) return true
                return expr.arguments?.any { expressionReferencesPath(it, path) } ?: false
            }
            is ElementAccessExpression -> return expressionReferencesPath(expr.expression, path) || expressionReferencesPath(expr.argumentExpression, path)
            is PrefixUnaryExpression -> return expressionReferencesPath(expr.operand, path)
            is PostfixUnaryExpression -> return expressionReferencesPath(expr.operand, path)
            is ConditionalExpression -> return expressionReferencesPath(expr.condition, path) || expressionReferencesPath(expr.whenTrue, path) || expressionReferencesPath(expr.whenFalse, path)
            is ArrayLiteralExpression -> return expr.elements.any { expressionReferencesPath(it, path) }
            is ObjectLiteralExpression -> return expr.properties.any { p ->
                when (p) {
                    is PropertyAssignment -> expressionReferencesPath(p.initializer, path)
                    is ShorthandPropertyAssignment -> path.size == 1 && p.name.text == path[0]
                    else -> false
                }
            }
            is SpreadElement -> return expressionReferencesPath(expr.expression, path)
            is AsExpression -> return expressionReferencesPath(expr.expression, path)
            is TypeAssertionExpression -> return expressionReferencesPath(expr.expression, path)
            is SatisfiesExpression -> return expressionReferencesPath(expr.expression, path)
            is NonNullExpression -> return expressionReferencesPath(expr.expression, path)
            is AwaitExpression -> return expressionReferencesPath(expr.expression, path)
            is YieldExpression -> return expr.expression?.let { expressionReferencesPath(it, path) } ?: false
            is TemplateExpression -> return expr.templateSpans.any { expressionReferencesPath(it.expression, path) }
            is CommaListExpression -> return expr.elements.any { expressionReferencesPath(it, path) }
            // Don't descend into nested function bodies that may shadow the head name.
            is ArrowFunction -> {
                if (expr.parameters.any { (it.name as? Identifier)?.text == path[0] }) return false
                val body = expr.body
                return when (body) {
                    is Block -> body.statements.any { statementReferencesPath(it, path) }
                    is Expression -> expressionReferencesPath(body, path)
                    else -> false
                }
            }
            is FunctionExpression -> {
                if (expr.name?.text == path[0]) return false
                if (expr.parameters.any { (it.name as? Identifier)?.text == path[0] }) return false
                return expr.body.statements.any { statementReferencesPath(it, path) }
            }
            else -> {}
        }
        return false
    }

    private fun statementReferencesName(stmt: Statement, name: String): Boolean {
        when (stmt) {
            is Block -> return stmt.statements.any { statementReferencesName(it, name) }
            is ExpressionStatement -> return expressionReferencesName(stmt.expression, name)
            is ReturnStatement -> return stmt.expression?.let { expressionReferencesName(it, name) } ?: false
            is IfStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.thenStatement, name)) return true
                stmt.elseStatement?.let { if (statementReferencesName(it, name)) return true }
            }
            is WhileStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is DoStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is ForStatement -> {
                stmt.condition?.let { if (expressionReferencesName(it, name)) return true }
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is ForInStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is ForOfStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                if (statementReferencesName(stmt.statement, name)) return true
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { if (expressionReferencesName(it, name)) return true }
            }
            is SwitchStatement -> {
                if (expressionReferencesName(stmt.expression, name)) return true
                for (c in stmt.caseBlock) {
                    if (c is CaseClause && expressionReferencesName(c.expression, name)) return true
                    val stmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                    if (stmts.any { statementReferencesName(it, name) }) return true
                }
            }
            is TryStatement -> {
                if (stmt.tryBlock.statements.any { statementReferencesName(it, name) }) return true
                stmt.catchClause?.let { if (it.block.statements.any { s -> statementReferencesName(s, name) }) return true }
                stmt.finallyBlock?.let { if (it.statements.any { s -> statementReferencesName(s, name) }) return true }
            }
            is ThrowStatement -> return stmt.expression?.let { expressionReferencesName(it, name) } ?: false
            is LabeledStatement -> return statementReferencesName(stmt.statement, name)
            else -> {}
        }
        return false
    }

    private fun expressionReferencesName(expr: Expression, name: String): Boolean {
        when (expr) {
            is Identifier -> return expr.text == name
            is BinaryExpression -> return expressionReferencesName(expr.left, name) || expressionReferencesName(expr.right, name)
            is ParenthesizedExpression -> return expressionReferencesName(expr.expression, name)
            is CallExpression -> {
                if (expressionReferencesName(expr.expression, name)) return true
                return expr.arguments.any { expressionReferencesName(it, name) }
            }
            is NewExpression -> {
                if (expressionReferencesName(expr.expression, name)) return true
                return expr.arguments?.any { expressionReferencesName(it, name) } ?: false
            }
            is PropertyAccessExpression -> return expressionReferencesName(expr.expression, name)
            is ElementAccessExpression -> return expressionReferencesName(expr.expression, name) || expressionReferencesName(expr.argumentExpression, name)
            is PrefixUnaryExpression -> return expressionReferencesName(expr.operand, name)
            is PostfixUnaryExpression -> return expressionReferencesName(expr.operand, name)
            is ConditionalExpression -> return expressionReferencesName(expr.condition, name) || expressionReferencesName(expr.whenTrue, name) || expressionReferencesName(expr.whenFalse, name)
            is ArrayLiteralExpression -> return expr.elements.any { expressionReferencesName(it, name) }
            is ObjectLiteralExpression -> return expr.properties.any { p ->
                when (p) {
                    is PropertyAssignment -> expressionReferencesName(p.initializer, name)
                    is ShorthandPropertyAssignment -> p.name.text == name
                    else -> false
                }
            }
            is SpreadElement -> return expressionReferencesName(expr.expression, name)
            is AsExpression -> return expressionReferencesName(expr.expression, name)
            is TypeAssertionExpression -> return expressionReferencesName(expr.expression, name)
            is SatisfiesExpression -> return expressionReferencesName(expr.expression, name)
            is NonNullExpression -> return expressionReferencesName(expr.expression, name)
            is AwaitExpression -> return expressionReferencesName(expr.expression, name)
            is YieldExpression -> return expr.expression?.let { expressionReferencesName(it, name) } ?: false
            is TemplateExpression -> return expr.templateSpans.any { expressionReferencesName(it.expression, name) }
            is CommaListExpression -> return expr.elements.any { expressionReferencesName(it, name) }
            // Don't descend into nested function bodies that may shadow the name.
            is ArrowFunction -> {
                if (expr.parameters.any { (it.name as? Identifier)?.text == name }) return false
                val body = expr.body
                return when (body) {
                    is Block -> body.statements.any { statementReferencesName(it, name) }
                    is Expression -> expressionReferencesName(body, name)
                    else -> false
                }
            }
            is FunctionExpression -> {
                if (expr.name?.text == name) return false
                if (expr.parameters.any { (it.name as? Identifier)?.text == name }) return false
                return expr.body.statements.any { statementReferencesName(it, name) }
            }
            else -> {}
        }
        return false
    }

    // -----------------------------------------------------------------------
    // Comma operator left side unused (TS2695)
    // -----------------------------------------------------------------------

    // ── INV.4(d) walker 12 (round 541): checkCommaOperatorUnused on the spine ──
    // (Fields + CM_* states declared before init. The recursion walkers
    // checkCommaInStatements/-InStatement/-InExpr are deleted; the leaf
    // utilities hasSideEffects/isIndirectCallComma/commaLeftSpanLength are
    // retained.)

    /** Per-file setup: the legacy gates — allowUnreachableCode==true kills the
     *  pass; a JS-like file without checkJs receives no semantic diagnostics. */
    private fun spineCmSetup(result: BinderResult) {
        spineCmActive = options.allowUnreachableCode != true && !spineIsDts &&
            !(isJsLikeFileName(result.sourceFile.fileName) && !options.checkJs)
        if (!spineCmActive) {
            spineCmReachMemo = ByteArray(0)
            return
        }
        val n = result.sourceFile.nodeCount
        spineCmReachMemo = if (n > 0) ByteArray(n) else ByteArray(0)
    }

    private fun spineCmTeardown() {
        spineCmActive = false
        spineCmReachMemo = ByteArray(0)
    }

    /** The TS2695 anchor — the deleted left-spine loop's per-node emission,
     *  at ENTER (spine preorder = the legacy outer-before-inner order). */
    private fun spineCmEnterNode(node: Node) {
        if (node !is BinaryExpression) return
        if (node.operator != SyntaxKind.Comma) return
        if (spineCmStatus(node) != CM_EXPR) return
        if (!hasSideEffects(node.left) && !isIndirectCallComma(node)) {
            // A MISSING left operand (`(, ANY)`) is an empty-text Identifier the
            // recovery anchors at the offending token. tsc anchors its missing node at
            // the FULL START — the end of the previous token, before trivia — and
            // squiggles nothing, so `( , )` reports at the `(`'s end, not at the `,`.
            // The zero length is also what orders this BEFORE the same-position TS1109
            // (the diagnostic comparator is start → length → code).
            val missingLeft = (node.left as? Identifier)?.text?.isEmpty() == true
            var start = node.left.pos
            val length: Int
            if (missingLeft) {
                while (start > 0 && spineSource[start - 1].isWhitespace()) start--
                length = 0
            } else {
                length = commaLeftSpanLength(node.left, start)
            }
            val (line, character) = getLineAndCharacterOfPosition(spineSource, start)
            diagnostics.add(Diagnostic(
                message = "Left side of comma operator is unused and has no side effects.",
                category = DiagnosticCategory.Error,
                code = 2695,
                fileName = spineFileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /** Memoized reach classifier for the comma pass (the deleted arms verbatim). */
    private fun spineCmStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.CM]++
        if (node is SourceFile) return CM_STMT
        val memo = spineCmReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.CM, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineCmChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = CM_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break }
            if (parent is SourceFile) { anchor = parent; anchorStatus = CM_STMT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.CM, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = CM_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == CM_NONE) CM_NONE
                else spineCmEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.CM, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.CM]++; ReachCensus.folds[ReachCensus.CM] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** The comma pass's edge rules — the deleted arms verbatim. NOTE the
     *  quirk: object-literal METHOD/accessor bodies are NOT walked (unlike
     *  the np pass); tagged templates, yield/delete/typeof/void operands,
     *  comma-lists, and class expressions ARE. */
    private fun spineCmEdge(parent: Node, pStatus: Int, child: Node): Int = when (pStatus) {
        CM_STMT -> when (parent) {
            is SourceFile -> if (child is Statement) CM_STMT else CM_NONE
            is Block -> if (child is Statement) CM_STMT else CM_NONE
            is ModuleBlock -> if (child is Statement) CM_STMT else CM_NONE
            is ExpressionStatement -> if (child === parent.expression) CM_EXPR else CM_NONE
            is VariableStatement -> if (child === parent.declarationList) CM_MEMBER else CM_NONE
            is ReturnStatement -> if (child === parent.expression) CM_EXPR else CM_NONE
            is ThrowStatement -> if (child === parent.expression) CM_EXPR else CM_NONE
            is IfStatement -> when {
                child === parent.expression -> CM_EXPR
                child === parent.thenStatement || child === parent.elseStatement -> CM_STMT
                else -> CM_NONE
            }
            is FunctionDeclaration -> if (child === parent.body) CM_STMT else CM_NONE
            is ClassDeclaration ->
                if (child is MethodDeclaration || child is Constructor ||
                    child is GetAccessor || child is SetAccessor ||
                    child is PropertyDeclaration) CM_MEMBER else CM_NONE
            is ForStatement -> when {
                child === parent.initializer -> if (child is Expression) CM_EXPR else CM_MEMBER
                child === parent.condition || child === parent.incrementor -> CM_EXPR
                child === parent.statement -> CM_STMT
                else -> CM_NONE
            }
            is ForInStatement -> when {
                child === parent.expression -> CM_EXPR
                child === parent.statement -> CM_STMT
                else -> CM_NONE
            }
            is ForOfStatement -> when {
                child === parent.expression -> CM_EXPR
                child === parent.statement -> CM_STMT
                else -> CM_NONE
            }
            is WhileStatement -> when {
                child === parent.expression -> CM_EXPR
                child === parent.statement -> CM_STMT
                else -> CM_NONE
            }
            is DoStatement -> when {
                child === parent.expression -> CM_EXPR
                child === parent.statement -> CM_STMT
                else -> CM_NONE
            }
            is SwitchStatement -> when {
                child === parent.expression -> CM_EXPR
                child is CaseClause || child is DefaultClause -> CM_MEMBER
                else -> CM_NONE
            }
            is TryStatement -> when {
                child === parent.tryBlock || child === parent.finallyBlock -> CM_STMT
                child === parent.catchClause -> CM_MEMBER
                else -> CM_NONE
            }
            is LabeledStatement -> if (child === parent.statement) CM_STMT else CM_NONE
            is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) CM_STMT else CM_NONE
            is EnumDeclaration -> if (child is EnumMember) CM_MEMBER else CM_NONE
            else -> CM_NONE
        }
        CM_MEMBER -> when (parent) {
            is VariableDeclarationList -> if (child is VariableDeclaration) CM_MEMBER else CM_NONE
            is VariableDeclaration -> if (child === parent.initializer) CM_EXPR else CM_NONE
            is MethodDeclaration -> if (child === parent.body) CM_STMT else CM_NONE
            is Constructor -> if (child === parent.body) CM_STMT else CM_NONE
            is GetAccessor -> if (child === parent.body) CM_STMT else CM_NONE
            is SetAccessor -> if (child === parent.body) CM_STMT else CM_NONE
            is PropertyDeclaration -> if (child === parent.initializer) CM_EXPR else CM_NONE
            is CaseClause -> when {
                child === parent.expression -> CM_EXPR
                child is Statement -> CM_STMT
                else -> CM_NONE
            }
            is DefaultClause -> if (child is Statement) CM_STMT else CM_NONE
            is CatchClause -> if (child === parent.block) CM_STMT else CM_NONE
            is EnumMember -> if (child === parent.initializer) CM_EXPR else CM_NONE
            is PropertyAssignment -> if (child === parent.initializer) CM_EXPR else CM_NONE
            is ShorthandPropertyAssignment ->
                if (child === parent.objectAssignmentInitializer) CM_EXPR else CM_NONE
            is SpreadAssignment -> if (child === parent.expression) CM_EXPR else CM_NONE
            is TemplateSpan -> if (child === parent.expression) CM_EXPR else CM_NONE
            else -> CM_NONE
        }
        CM_EXPR -> when (parent) {
            is BinaryExpression -> if (child === parent.left || child === parent.right) CM_EXPR else CM_NONE
            is ParenthesizedExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is ConditionalExpression ->
                if (child === parent.condition || child === parent.whenTrue ||
                    child === parent.whenFalse) CM_EXPR else CM_NONE
            is ArrowFunction -> when {
                child !== parent.body -> CM_NONE
                child is Block -> CM_STMT
                else -> CM_EXPR
            }
            is FunctionExpression -> if (child === parent.body) CM_STMT else CM_NONE
            is CallExpression ->
                if (child === parent.expression || parent.arguments.anyIdentical(child)) CM_EXPR
                else CM_NONE
            is NewExpression ->
                if (child === parent.expression || parent.arguments?.anyIdentical(child) == true) CM_EXPR
                else CM_NONE
            is PropertyAccessExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is ElementAccessExpression ->
                if (child === parent.expression || child === parent.argumentExpression) CM_EXPR
                else CM_NONE
            is ArrayLiteralExpression -> if (parent.elements.anyIdentical(child)) CM_EXPR else CM_NONE
            is ObjectLiteralExpression -> when (child) {
                is PropertyAssignment, is ShorthandPropertyAssignment, is SpreadAssignment -> CM_MEMBER
                else -> CM_NONE
            }
            is PrefixUnaryExpression -> if (child === parent.operand) CM_EXPR else CM_NONE
            is PostfixUnaryExpression -> if (child === parent.operand) CM_EXPR else CM_NONE
            is TemplateExpression -> if (child is TemplateSpan) CM_MEMBER else CM_NONE
            is TaggedTemplateExpression -> when {
                child === parent.tag -> CM_EXPR
                child === parent.template && child is TemplateExpression -> CM_EXPR
                else -> CM_NONE
            }
            is TypeAssertionExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is AsExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is NonNullExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is SatisfiesExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is SpreadElement -> if (child === parent.expression) CM_EXPR else CM_NONE
            is AwaitExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is YieldExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is VoidExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is DeleteExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is TypeOfExpression -> if (child === parent.expression) CM_EXPR else CM_NONE
            is CommaListExpression -> if (parent.elements.anyIdentical(child)) CM_EXPR else CM_NONE
            is ClassExpression ->
                if (child is MethodDeclaration || child is Constructor ||
                    child is GetAccessor || child is SetAccessor ||
                    child is PropertyDeclaration) CM_MEMBER else CM_NONE
            else -> CM_NONE
        }
        else -> CM_NONE
    }

    /** Check if this comma expression is an indirect call pattern: (0, obj.prop)() */
    private fun isIndirectCallComma(expr: BinaryExpression): Boolean {
        val right = expr.right
        // (0, obj.method)() — indirect call pattern with property/element access
        if (right is PropertyAccessExpression || right is ElementAccessExpression) return true
        // (0, eval)("code") — indirect eval pattern
        if (right is Identifier && right.text == "eval") return true
        return false
    }

    /** Compute squiggle length for the left operand of a comma expression. */
    private fun commaLeftSpanLength(expr: Expression, start: Int): Int {
        return when (expr) {
            // Function expressions: squiggle only covers 'function' keyword (8 chars)
            is FunctionExpression -> 8
            // Arrow functions: squiggle covers the whole expression
            is ArrowFunction -> (expr.end - 1 - start).coerceAtLeast(1)
            // Parenthesized: squiggle covers the whole parenthesized expression
            is ParenthesizedExpression -> (expr.end - 1 - start).coerceAtLeast(1)
            // String literals: text.length + 2 for quotes
            is StringLiteralNode -> (expr.rawText?.length ?: expr.text.length) + 2
            // Template strings: use node span
            is NoSubstitutionTemplateLiteralNode -> (expr.end - 1 - start).coerceAtLeast(1)
            // Regex literals: use node span
            is RegularExpressionLiteralNode -> (expr.end - 1 - start).coerceAtLeast(1)
            // Default: use node span
            else -> (expr.end - 1 - start).coerceAtLeast(1)
        }
    }

    /** Check if an expression has side effects (assignments, calls, increments, etc.) */
    private fun hasSideEffects(expr: Expression): Boolean {
        return when (expr) {
            // Assignments always have side effects
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.Equals, SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
                SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals, SyntaxKind.PercentEquals,
                SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals, SyntaxKind.CaretEquals,
                SyntaxKind.LessThanLessThanEquals, SyntaxKind.GreaterThanGreaterThanEquals,
                SyntaxKind.GreaterThanGreaterThanGreaterThanEquals,
                SyntaxKind.AsteriskAsteriskEquals,
                SyntaxKind.BarBarEquals, SyntaxKind.AmpersandAmpersandEquals,
                SyntaxKind.QuestionQuestionEquals -> true
                // Comma: if left has side effects, whole thing does
                SyntaxKind.Comma -> hasSideEffects(expr.left) || hasSideEffects(expr.right)
                // Other binary ops: check both sides
                else -> hasSideEffects(expr.left) || hasSideEffects(expr.right)
            }
            // Increment/decrement have side effects
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> true
                else -> hasSideEffects(expr.operand)
            }
            is PostfixUnaryExpression -> true // ++ and -- always have side effects
            // Function/method calls have side effects
            is CallExpression -> true
            is NewExpression -> true
            is TaggedTemplateExpression -> true
            // Delete has side effects
            is DeleteExpression -> true
            // Yield/await have side effects
            is YieldExpression -> true
            is AwaitExpression -> true
            // Void expression: TypeScript treats as OK (no TS2695)
            is VoidExpression -> true
            // Type assertions: TypeScript treats as OK (no TS2695)
            is TypeAssertionExpression -> true
            is AsExpression -> true
            is SatisfiesExpression -> true
            // Parenthesized: check inner
            is ParenthesizedExpression -> hasSideEffects(expr.expression)
            // Non-null assertion (x!): no side effect
            is NonNullExpression -> hasSideEffects(expr.expression)
            // Conditional: has side effects if any branch does
            is ConditionalExpression -> hasSideEffects(expr.whenTrue) || hasSideEffects(expr.whenFalse)
            // Everything else (literals, identifiers, typeof, array/object literals,
            // arrow functions, function expressions, etc.) — no side effects
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // Null/undefined usage checking (TS18050)
    // -----------------------------------------------------------------------

    /**
     * Check for null/undefined used in invalid positions:
     * property access base, binary operator operands, etc.
     * Emits TS18050: "The value 'null'/'undefined' cannot be used here."
     */
    // ── INV.4(d) walker 11 (round 540): checkNullUndefinedUsage on the spine ──
    // (Fields + the NU_* kinds are declared before init — see the spineNu
    // field block. The per-file driver and the recursion walkers
    // checkNullUndefinedInStatements/-InStatement/-InExpr are deleted; the
    // bounded leaf utilities — checkNullUndefinedLiteral,
    // emitNeverIteratorAt — are retained.)

    /** Per-file setup for the spine-hosted null/undefined-usage pass. */
    private fun spineNuSetup(result: BinderResult) {
        spineNuActive = !spineIsDts
        if (!spineNuActive) {
            spineNuReachMemo = ShortArray(0)
            return
        }
        val n = result.sourceFile.nodeCount
        spineNuReachMemo = if (n > 0) ShortArray(n) else ShortArray(0)
    }

    private fun spineNuTeardown() {
        spineNuActive = false
        spineNuReachMemo = ShortArray(0)
    }

    /** Per-node ENTER hook: the TS18050-family anchors (all pure — the
     *  deleted walkers installed no ambient state). */
    private fun spineNuEnterNode(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.BINARY_EXPRESSION -> { node as BinaryExpression; spineNuBinaryEnter(node) }
            NodeKind.PROPERTY_ACCESS_EXPRESSION -> {
                node as PropertyAccessExpression
                if (spineNuKind(node) == NU_EXPR) {
                    // null.foo or undefined.foo
                    checkNullUndefinedLiteral(node.expression, spineSource, spineFileName)
                }
            }
            NodeKind.ELEMENT_ACCESS_EXPRESSION -> {
                node as ElementAccessExpression
                if (spineNuKind(node) == NU_EXPR) {
                    // null[x] or undefined[x]
                    checkNullUndefinedLiteral(node.expression, spineSource, spineFileName)
                }
            }
            NodeKind.FOR_OF_STATEMENT -> {
                node as ForOfStatement
                if (spineNuKind(node) == NU_STMT) {
                    // A bare `null`/`undefined` as the for-of iterable cannot be
                    // iterated → TS18050. Gated on strictNullChecks (mirrors the
                    // arithmetic-operand path).
                    if (strictNullChecks) checkNullUndefinedLiteral(node.expression, spineSource, spineFileName)
                    // For-of array-destructuring an EMPTY array literal `[]` (element
                    // type `never` under noImplicitAny) with an array binding pattern
                    // → TS2488 at the pattern. FP-safe by exact shape.
                    if (options.noImplicitAny || options.strict) {
                        val iter = node.expression
                        if (iter is ArrayLiteralExpression && iter.elements.isEmpty()) {
                            val abp = (node.initializer as? VariableDeclarationList)
                                ?.declarations?.singleOrNull()?.name as? ArrayBindingPattern
                            if (abp != null) emitNeverIteratorAt(abp.pos, spineSource, spineFileName)
                        }
                    }
                }
            }
            else -> {}
        }
    }

    /** The deleted BinaryExpression arm's emission block: null/undefined
     *  literal operands of arithmetic/bitwise operators (strict only; `+`
     *  with a string on the other side is exempt) and of `in` (all modes). */
    private fun spineNuBinaryEnter(expr: BinaryExpression) {
        val op = expr.operator
        if (spineNuKind(expr) != NU_EXPR) return
        val isArithmeticOrBitwise = op == SyntaxKind.Plus || op == SyntaxKind.Minus ||
            op == SyntaxKind.Asterisk || op == SyntaxKind.Slash || op == SyntaxKind.Percent ||
            op == SyntaxKind.AsteriskAsterisk ||
            op == SyntaxKind.Ampersand || op == SyntaxKind.Bar || op == SyntaxKind.Caret ||
            op == SyntaxKind.LessThanLessThan || op == SyntaxKind.GreaterThanGreaterThan ||
            op == SyntaxKind.GreaterThanGreaterThanGreaterThan ||
            op == SyntaxKind.PlusEquals || op == SyntaxKind.MinusEquals ||
            op == SyntaxKind.AsteriskEquals || op == SyntaxKind.SlashEquals ||
            op == SyntaxKind.PercentEquals || op == SyntaxKind.AsteriskAsteriskEquals ||
            op == SyntaxKind.AmpersandEquals || op == SyntaxKind.BarEquals ||
            op == SyntaxKind.CaretEquals || op == SyntaxKind.LessThanLessThanEquals ||
            op == SyntaxKind.GreaterThanGreaterThanEquals ||
            op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals
        if (isArithmeticOrBitwise && strictNullChecks) {
            // Under non-strict, TS2365 takes over from TS18050 for
            // arithmetic-with-null/undefined. For '+', null/undefined is valid
            // when the other side is a string.
            val isPlus = op == SyntaxKind.Plus || op == SyntaxKind.PlusEquals
            val leftIsString = expr.left is StringLiteralNode || expr.left is TemplateExpression ||
                (expr.left is Identifier && (expr.left).text.let { it != "null" && it != "undefined" } && false)
            val rightIsString = expr.right is StringLiteralNode || expr.right is TemplateExpression
            if (!(isPlus && rightIsString)) {
                checkNullUndefinedLiteral(expr.left, spineSource, spineFileName)
            }
            if (!(isPlus && leftIsString)) {
                checkNullUndefinedLiteral(expr.right, spineSource, spineFileName)
            }
        }
        // TS18050: a `null`/`undefined` literal operand of the `in` operator —
        // tsc emits this in all modes for both operands.
        if (op == SyntaxKind.InKeyword) {
            checkNullUndefinedLiteral(expr.left, spineSource, spineFileName)
            checkNullUndefinedLiteral(expr.right, spineSource, spineFileName)
        }
    }

    /** The KIND of [node]'s reach status (NU_NONE/NU_STMT/NU_EXPR/NU_MEMBER). */
    private fun spineNuKind(node: Node): Int {
        val v = spineNuStatus(node)
        return if (v == NU_NONE) NU_NONE else v / 512
    }

    /**
     * Memoized DEPTH-carrying reach classifier — the deleted
     * checkNullUndefinedInStatement/-InExpr dispatch arms verbatim, with the
     * legacy `checkDepth > maxCheckDepth` STATEMENT-frame cap reproduced
     * (a statement whose ancestor-statement count exceeds [maxCheckDepth] is
     * skipped with its whole subtree). Status values: NU_NONE, else
     * kind*512 + depth where depth = the nearest enclosing statement frame's
     * ancestor count.
     */
    private fun spineNuStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.NU]++
        if (node is SourceFile) return NU_STMT * 512
        val memo = spineNuReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.NU, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineNuChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = NU_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → NONE
            if (parent is SourceFile) { anchor = parent; anchorStatus = NU_STMT * 512; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.NU, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = NU_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == NU_NONE) NU_NONE
                else spineNuEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.NU, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toShort()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.NU]++; ReachCensus.folds[ReachCensus.NU] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** A statement CHILD entering a new legacy frame at depth d+1, or NONE
     *  past the cap. */
    private fun spineNuStmtChild(child: Node, d: Int): Int {
        if (child !is Statement) return NU_NONE
        val nd = d + 1
        return if (nd > maxCheckDepth) NU_NONE else NU_STMT * 512 + nd
    }

    /**
     * The edge rules — the deleted walkers' arms verbatim. Unlisted edges are
     * NONE (the legacy `else -> {}`s: `new` expressions, as/angle-bracket
     * casts, non-null assertions, await/yield/void/typeof/delete/spread
     * operands, tagged templates, comma lists, class EXPRESSIONS,
     * object-literal methods/accessors, for-header DECLARATOR initializers,
     * type positions). Body Blocks the legacy dispatched WITHOUT a frame
     * (fn/member/arrow bodies, module blocks, try blocks) carry the parent's
     * depth so their statements land at d+1, matching the single legacy
     * frame.
     */
    private fun spineNuEdge(parent: Node, pStatus: Int, child: Node): Int {
        val kind = pStatus / 512
        val d = pStatus % 512
        val expr = NU_EXPR * 512 + d
        val member = NU_MEMBER * 512 + d
        val carrierBlock = NU_STMT * 512 + d
        return when (kind) {
            NU_STMT -> when (parent) {
                is SourceFile -> spineNuStmtChild(child, d)
                is Block -> spineNuStmtChild(child, d)
                is ModuleBlock -> spineNuStmtChild(child, d)
                is VariableStatement -> if (child === parent.declarationList) member else NU_NONE
                is ExpressionStatement -> if (child === parent.expression) expr else NU_NONE
                is ReturnStatement -> if (child === parent.expression) expr else NU_NONE
                is ThrowStatement -> if (child === parent.expression) expr else NU_NONE
                is ExportAssignment -> if (child === parent.expression) expr else NU_NONE
                is IfStatement -> when {
                    child === parent.expression -> expr
                    child === parent.thenStatement || child === parent.elseStatement ->
                        spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is ForStatement -> when {
                    child === parent.initializer -> if (child is Expression) expr else NU_NONE
                    child === parent.condition || child === parent.incrementor -> expr
                    child === parent.statement -> spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is WhileStatement -> when {
                    child === parent.expression -> expr
                    child === parent.statement -> spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is DoStatement -> when {
                    child === parent.expression -> expr
                    child === parent.statement -> spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is ForInStatement -> when {
                    child === parent.expression -> expr
                    child === parent.statement -> spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is ForOfStatement -> when {
                    child === parent.expression -> expr
                    child === parent.statement -> spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is SwitchStatement -> when {
                    child === parent.expression -> expr
                    child is CaseClause || child is DefaultClause -> member
                    else -> NU_NONE
                }
                is FunctionDeclaration -> if (child === parent.body) carrierBlock else NU_NONE
                is ClassDeclaration ->
                    if (child is MethodDeclaration || child is Constructor ||
                        child is GetAccessor || child is SetAccessor ||
                        child is PropertyDeclaration) member else NU_NONE
                is ModuleDeclaration ->
                    if (child === parent.body && child is ModuleBlock) carrierBlock else NU_NONE
                is TryStatement -> when {
                    child === parent.tryBlock || child === parent.finallyBlock -> carrierBlock
                    child === parent.catchClause -> member
                    else -> NU_NONE
                }
                is LabeledStatement -> if (child === parent.statement) spineNuStmtChild(child, d) else NU_NONE
                else -> NU_NONE
            }
            NU_MEMBER -> when (parent) {
                is VariableDeclarationList -> if (child is VariableDeclaration) member else NU_NONE
                is VariableDeclaration -> if (child === parent.initializer) expr else NU_NONE
                is CaseClause -> when {
                    child === parent.expression -> expr
                    child is Statement -> spineNuStmtChild(child, d)
                    else -> NU_NONE
                }
                is DefaultClause -> spineNuStmtChild(child, d)
                is CatchClause -> if (child === parent.block) carrierBlock else NU_NONE
                is MethodDeclaration -> if (child === parent.body) carrierBlock else NU_NONE
                is Constructor -> if (child === parent.body) carrierBlock else NU_NONE
                is GetAccessor -> if (child === parent.body) carrierBlock else NU_NONE
                is SetAccessor -> if (child === parent.body) carrierBlock else NU_NONE
                is PropertyDeclaration -> if (child === parent.initializer) expr else NU_NONE
                is PropertyAssignment -> if (child === parent.initializer) expr else NU_NONE
                is SpreadAssignment -> if (child === parent.expression) expr else NU_NONE
                is TemplateSpan -> if (child === parent.expression) expr else NU_NONE
                else -> NU_NONE
            }
            NU_EXPR -> when (parent) {
                is BinaryExpression -> if (child === parent.left || child === parent.right) expr else NU_NONE
                is PropertyAccessExpression -> if (child === parent.expression) expr else NU_NONE
                is ElementAccessExpression ->
                    if (child === parent.expression || child === parent.argumentExpression) expr
                    else NU_NONE
                is CallExpression ->
                    if (child === parent.expression || parent.arguments.anyIdentical(child)) expr
                    else NU_NONE
                is ParenthesizedExpression -> if (child === parent.expression) expr else NU_NONE
                is ConditionalExpression ->
                    if (child === parent.condition || child === parent.whenTrue ||
                        child === parent.whenFalse) expr else NU_NONE
                is PrefixUnaryExpression -> if (child === parent.operand) expr else NU_NONE
                is PostfixUnaryExpression -> if (child === parent.operand) expr else NU_NONE
                is TemplateExpression -> if (child is TemplateSpan) member else NU_NONE
                is ArrayLiteralExpression -> if (parent.elements.anyIdentical(child)) expr else NU_NONE
                is ObjectLiteralExpression -> when (child) {
                    is PropertyAssignment, is SpreadAssignment -> member
                    else -> NU_NONE
                }
                is ArrowFunction -> when {
                    child !== parent.body -> NU_NONE
                    child is Block -> carrierBlock
                    else -> expr
                }
                is FunctionExpression -> if (child === parent.body) carrierBlock else NU_NONE
                else -> NU_NONE
            }
            else -> NU_NONE
        }
    }

    private fun checkNullUndefinedLiteral(expr: Expression, source: String, fileName: String) {
        // In our AST, null and undefined are parsed as Identifiers
        val keyword = when {
            expr is Identifier && expr.text == "null" -> "null"
            expr is Identifier && expr.text == "undefined" -> "undefined"
            else -> return
        }
        val start = expr.pos
        val length = keyword.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The value '$keyword' cannot be used here.",
            category = DiagnosticCategory.Error,
            code = 18050,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check for type-only names used in value positions.
     * Emits TS2693 "'X' only refers to a type, but is being used as a value here."
     */
    /**
     * TS4081: "Exported type alias 'X' has or is using private name 'Y'."
     *
     * Narrow scope: only fires when `options.declaration` is enabled and a top-level
     * exported `type X = typeof Y;` references a name `Y` that is declared INSIDE a
     * non-top-level block (e.g. `if (false) { export var Y = 0; }`) and NOT also at
     * the file's top level. Other TS4081 patterns (using a non-exported top-level name)
     * require declaration-emission visibility analysis we don't yet model.
     */
    private fun checkExportTypeAliasPrivateNameRef() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val statements = result.sourceFile.statements
            val topLevelValueNames = mutableSetOf<String>()
            val nestedValueNames = mutableSetOf<String>()
            for (stmt in statements) {
                collectTopLevelValueNames(stmt, topLevelValueNames)
            }
            for (stmt in statements) {
                collectNestedValueNames(stmt, nestedValueNames, topLevel = true)
            }
            for (stmt in statements) {
                when (stmt) {
                    is TypeAliasDeclaration -> {
                        if (ModifierFlag.Export !in stmt.modifiers) continue
                        walkTypeQueryForPrivateName(stmt.type, stmt.name.text, topLevelValueNames, nestedValueNames, source, fileName, 4081, "type alias")
                    }
                    // B98.r54: TS4025 — an exported `let/var/const b: typeof a` whose
                    // annotation references a name `a` declared only inside an elided
                    // block (function-scoped, no .d.ts declaration) → private name ref.
                    is VariableStatement -> {
                        if (ModifierFlag.Export !in stmt.modifiers) continue
                        for (decl in stmt.declarationList.declarations) {
                            val declNameNode = decl.name as? Identifier ?: continue
                            val declName = declNameNode.text
                            // B98.r152: TS4025 — an annotation-less `export const globalThis = <init>`
                            // SHADOWS the built-in global `globalThis`, so the .d.ts inferred type
                            // (which would reference `globalThis`) can't name it → private name ref.
                            // Narrow gate: name == "globalThis", no annotation, non-literal initializer
                            // (a plain literal init wouldn't reference the global). Corpus-FP-safe:
                            // `export const globalThis` occurs only in globalThisDeclarationEmit.
                            if (declName == "globalThis" && decl.type == null) {
                                val init = decl.initializer
                                val isPlainLiteral = init is NumericLiteralNode || init is StringLiteralNode ||
                                    init is NoSubstitutionTemplateLiteralNode
                                if (init != null && !isPlainLiteral) {
                                    val (line, character) = getLineAndCharacterOfPosition(source, declNameNode.pos)
                                    diagnostics.add(Diagnostic(
                                        message = "Exported variable 'globalThis' has or is using private name 'globalThis'.",
                                        category = DiagnosticCategory.Error,
                                        code = 4025,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = declNameNode.pos,
                                        length = declName.length,
                                    ))
                                }
                            }
                            val typeNode = decl.type ?: continue
                            walkTypeQueryForPrivateName(typeNode, declName, topLevelValueNames, nestedValueNames, source, fileName, 4025, "variable")
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    /**
     * B98: TS4094 "Property 'X' of exported anonymous class type may not be private
     * or protected." A declaration-emit (`@declaration: true`) diagnostic for an
     * EXPORTED, annotation-less variable whose initializer is directly an ANONYMOUS
     * `class { ... }` expression containing private (`#name`) or `private`/`protected`
     * members — the emitted .d.ts would expose a class type whose private/protected
     * member cannot be represented. Pure AST-shape walk; no type engine. A `#`-private
     * member's name node text already includes the leading `#`. Names are reported
     * alphabetically (matches TypeScript), each at the VARIABLE name position with a
     * TS9027 "Add a type annotation" related info.
     */
    private fun checkExportedAnonClassExprPrivateMembers() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                if (ModifierFlag.Export !in stmt.modifiers) continue
                for (decl in stmt.declarationList.declarations) {
                    if (decl.type != null) continue
                    val name = decl.name as? Identifier ?: continue
                    val ce = decl.initializer as? ClassExpression ?: continue
                    if (ce.name != null) continue
                    val privateNames = mutableListOf<String>()
                    for (member in ce.members) {
                        val (memberName, mods) = when (member) {
                            is PropertyDeclaration -> member.name to member.modifiers
                            is MethodDeclaration -> member.name to member.modifiers
                            is GetAccessor -> member.name to member.modifiers
                            is SetAccessor -> member.name to member.modifiers
                            else -> null to emptySet()
                        }
                        if (memberName == null) continue
                        // A `#`-private member's name node text already includes the leading `#`.
                        if (memberName is Identifier && memberName.text.startsWith("#")) {
                            privateNames.add(memberName.text)
                        } else if (ModifierFlag.Private in mods || ModifierFlag.Protected in mods) {
                            val dn = (memberName as? Identifier)?.text
                                ?: (memberName as? StringLiteralNode)?.text
                                ?: (memberName as? NumericLiteralNode)?.text
                            if (dn != null) privateNames.add(dn)
                        }
                    }
                    if (privateNames.isEmpty()) continue
                    privateNames.sort()
                    val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                    for (pn in privateNames) {
                        val related = listOf(Diagnostic(
                            message = "Add a type annotation to the variable ${name.text}.",
                            category = DiagnosticCategory.Message, code = 9027,
                            fileName = fileName, line = line, character = character,
                            start = name.pos, length = name.text.length,
                        ))
                        diagnostics.add(Diagnostic(
                            message = "Property '$pn' of exported anonymous class type may not be private or protected.",
                            category = DiagnosticCategory.Error, code = 4094,
                            fileName = fileName, line = line, character = character,
                            start = name.pos, length = name.text.length,
                            relatedInformation = related,
                        ))
                    }
                }
            }
        }
    }

    private fun collectTopLevelValueNames(stmt: Statement, out: MutableSet<String>) {
        when (stmt) {
            is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                (decl.name as? Identifier)?.text?.let { out.add(it) }
            }
            is FunctionDeclaration -> stmt.name?.text?.let { out.add(it) }
            is ClassDeclaration -> stmt.name?.text?.let { out.add(it) }
            is EnumDeclaration -> out.add(stmt.name.text)
            is ModuleDeclaration -> (stmt.name as? Identifier)?.text?.let { out.add(it) }
            else -> {}
        }
    }

    private fun collectNestedValueNames(stmt: Statement, out: MutableSet<String>, topLevel: Boolean) {
        when (stmt) {
            is Block -> for (s in stmt.statements) collectNestedValueNames(s, out, topLevel = false)
            is IfStatement -> {
                collectNestedValueNames(stmt.thenStatement, out, topLevel = false)
                stmt.elseStatement?.let { collectNestedValueNames(it, out, topLevel = false) }
            }
            is ForStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is ForInStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is ForOfStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is WhileStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is DoStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is LabeledStatement -> collectNestedValueNames(stmt.statement, out, topLevel = false)
            is TryStatement -> {
                for (s in stmt.tryBlock.statements) collectNestedValueNames(s, out, topLevel = false)
                stmt.catchClause?.let { for (s in it.block.statements) collectNestedValueNames(s, out, topLevel = false) }
                stmt.finallyBlock?.let { for (s in it.statements) collectNestedValueNames(s, out, topLevel = false) }
            }
            is SwitchStatement -> for (clause in stmt.caseBlock) {
                when (clause) {
                    is CaseClause -> for (s in clause.statements) collectNestedValueNames(s, out, topLevel = false)
                    is DefaultClause -> for (s in clause.statements) collectNestedValueNames(s, out, topLevel = false)
                    else -> {}
                }
            }
            is VariableStatement -> if (!topLevel) for (decl in stmt.declarationList.declarations) {
                (decl.name as? Identifier)?.text?.let { out.add(it) }
            }
            is FunctionDeclaration -> if (!topLevel) stmt.name?.text?.let { out.add(it) }
            is ClassDeclaration -> if (!topLevel) stmt.name?.text?.let { out.add(it) }
            else -> {}
        }
    }

    private fun walkTypeQueryForPrivateName(
        type: TypeNode,
        aliasName: String,
        topLevel: Set<String>,
        nested: Set<String>,
        source: String,
        fileName: String,
        code: Int = 4081,
        entityKind: String = "type alias",
    ) {
        when (type) {
            is TypeQuery -> {
                val expr = type.exprName
                if (expr is Identifier) {
                    val n = expr.text
                    if (n in nested && n !in topLevel) {
                        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                        diagnostics.add(Diagnostic(
                            message = "Exported $entityKind '$aliasName' has or is using private name '$n'.",
                            category = DiagnosticCategory.Error,
                            code = code,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = expr.pos,
                            length = n.length,
                        ))
                    }
                }
            }
            is UnionType -> type.types.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
            is IntersectionType -> type.types.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
            is ParenthesizedType -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName, code, entityKind)
            is ArrayType -> walkTypeQueryForPrivateName(type.elementType, aliasName, topLevel, nested, source, fileName, code, entityKind)
            is TupleType -> type.elements.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
            is TypeReference -> type.typeArguments?.forEach { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
            is FunctionType -> {
                type.parameters.forEach { p -> p.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) } }
                walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName, code, entityKind)
            }
            is ConstructorType -> {
                type.parameters.forEach { p -> p.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) } }
                walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName, code, entityKind)
            }
            is TypeLiteral -> for (m in type.members) {
                when (m) {
                    is PropertyDeclaration -> m.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
                    is MethodDeclaration -> {
                        m.parameters.forEach { p -> p.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) } }
                        m.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
                    }
                    is IndexSignature -> m.type?.let { walkTypeQueryForPrivateName(it, aliasName, topLevel, nested, source, fileName, code, entityKind) }
                    else -> {}
                }
            }
            is ConditionalType -> {
                walkTypeQueryForPrivateName(type.checkType, aliasName, topLevel, nested, source, fileName, code, entityKind)
                walkTypeQueryForPrivateName(type.extendsType, aliasName, topLevel, nested, source, fileName, code, entityKind)
                walkTypeQueryForPrivateName(type.trueType, aliasName, topLevel, nested, source, fileName, code, entityKind)
                walkTypeQueryForPrivateName(type.falseType, aliasName, topLevel, nested, source, fileName, code, entityKind)
            }
            is IndexedAccessType -> {
                walkTypeQueryForPrivateName(type.objectType, aliasName, topLevel, nested, source, fileName, code, entityKind)
                walkTypeQueryForPrivateName(type.indexType, aliasName, topLevel, nested, source, fileName, code, entityKind)
            }
            is TypeOperator -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName, code, entityKind)
            is RestType -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName, code, entityKind)
            is OptionalType -> walkTypeQueryForPrivateName(type.type, aliasName, topLevel, nested, source, fileName, code, entityKind)
            else -> {}
        }
    }

    /** Recursively visit every local name a parameter/variable binding introduces. */
    private fun forEachParamBindingName(name: Node, action: (String) -> Unit) {
        when (name) {
            is Identifier -> action(name.text)
            is ObjectBindingPattern -> for (element in name.elements) forEachParamBindingName(element.name, action)
            is ArrayBindingPattern -> for (element in name.elements) {
                if (element is BindingElement) forEachParamBindingName(element.name, action)
            }
            else -> {}
        }
    }

    /**
     * If the heritage `extends` expression resolves to a pure interface (bare or namespace-
     * qualified like `M.I` / `Mod.Nested.I`), return `(leftmostIdentifier, fullDisplayName)`
     * so the caller can emit TS2689 instead of the generic TS2693/TS2708. Returns null when
     * the expression isn't a bare/qualified-name access, or when the resolved symbol carries
     * value-side flags (Class/Variable/Function) — those are valid `extends` targets.
     */
    private fun tryClassifyExtendsInterface(
        expr: Expression, valueNames: TavLevel?,
    ): Pair<Identifier, String>? {
        // Walk the property-access chain leftward, collecting names.
        val names = mutableListOf<String>()
        val leftmost: Identifier?
        var current: Expression = expr
        while (true) {
            when (current) {
                is Identifier -> {
                    names.add(0, current.text)
                    leftmost = current
                    break
                }
                is PropertyAccessExpression -> {
                    names.add(0, current.name.text)
                    current = current.expression
                }
                else -> return null
            }
        }
        if (tavHasValue(valueNames, leftmost.text)) return null
        // B51.1: skip built-in lib types that are ALSO values (e.g. `Array`,
        // `Object`, `Function`) — TypeScript's full lib.d.ts has both
        // `interface X { ... }` AND `declare const X: XConstructor`, making
        // them valid `extends` targets. Our embedded lib only declares the
        // interface, so the Variable flag is missing — skip via name allowlist.
        if (names.size == 1 && leftmost.text in BUILTIN_LIB_VALUE_INTERFACES) return null
        // Walk the symbol chain: leftmost in scope, then each step via `exports`.
        var symbol: Symbol? = currentFileLocals?.get(names[0]) ?: globals[names[0]] ?: return null
        for (i in 1 until names.size) {
            val nextSym = symbol?.exports?.get(names[i]) ?: return null
            symbol = nextSym
        }
        val resolved = symbol ?: return null
        if (!resolved.flags.hasAny(SymbolFlags.Interface)) return null
        if (resolved.flags.hasAny(SymbolFlags.Class or SymbolFlags.Variable or SymbolFlags.Function)) return null
        return leftmost to names.joinToString(".")
    }

    private fun emitTS2693(name: String, node: Node, source: String, fileName: String) {
        val start = node.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Forward-declarable lib types (Promise, Symbol, Map, …) under restrictive @lib
        // get the more specific TS2585 with a lib-hint message instead of TS2693.
        val (code, message) = if (name in currentForwardLibTypeNames) {
            2585 to "'$name' only refers to a type, but is being used as a value here. Do you need to change your target library? Try changing the 'lib' compiler option to es2015 or later."
        } else {
            2693 to "'$name' only refers to a type, but is being used as a value here."
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Unreachable code checking (TS7027)
    // -----------------------------------------------------------------------

    /**
     * Check for unreachable code after return, throw, break, continue,
     * and infinite loops.
     */
    private fun checkUnreachableCode() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUnreachableInStatements(result.sourceFile.statements, source, fileName, result)
        }
    }

    private fun checkUnreachableInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        binderResult: BinderResult,
    ) {
        var termIdx = -1
        var currentRun = mutableListOf<Statement>()

        for (i in statements.indices) {
            val stmt = statements[i]
            if (termIdx >= 0) {
                // After a terminating statement: collect unreachable runs separated by hoisted decls.
                // Hoisted = doesn't generate runtime code:
                //   - FunctionDeclaration: truly hoisted (JS var hoisting)
                //   - InterfaceDeclaration, TypeAliasDeclaration: type-only, erased
                //   - ImportDeclaration, ImportEqualsDeclaration, ExportDeclaration: module-level
                //   - VariableStatement with var flags: var declarations are function-hoisted
                //   - ModuleDeclaration that is non-instantiated (only type-only contents)
                val isHoisted = stmt is FunctionDeclaration ||
                    stmt is InterfaceDeclaration ||
                    stmt is TypeAliasDeclaration ||
                    stmt is ImportDeclaration ||
                    stmt is ImportEqualsDeclaration ||
                    stmt is ExportDeclaration ||
                    isVarDeclaration(stmt) ||
                    isNonPreservedConstEnum(stmt) ||
                    isNonInstantiatedNamespace(stmt, binderResult)
                if (isHoisted) {
                    // Emit current run if non-empty
                    if (currentRun.isNotEmpty()) {
                        emitTS7027(currentRun, source, fileName)
                        currentRun = mutableListOf()
                    }
                    // Recurse into hoisted declaration (it IS reachable for inner checks)
                    checkUnreachableInNestedStatement(stmt, source, fileName, binderResult)
                } else {
                    // Add to current unreachable run (do NOT recurse — it's unreachable)
                    currentRun.add(stmt)
                }
            } else {
                // Before the terminating statement: check normally
                if (isDefinitelyTerminating(stmt)) {
                    termIdx = i
                }
                // Recurse into nested blocks
                checkUnreachableInNestedStatement(stmt, source, fileName, binderResult)
            }
        }

        // Emit final run if any unreachable statements remain
        if (currentRun.isNotEmpty()) {
            emitTS7027(currentRun, source, fileName)
        }
    }

    /**
     * Returns true for `var` variable statements with NO initializer (pure declarations).
     * TypeScript does not report TS7027 for bare `var x;` after unreachable code because
     * `var` declarations without initializers are hoisted and have no runtime side effects.
     * `var x = 1;` (with initializer) IS reported since the initializer is unreachable code.
     */
    private fun isVarDeclaration(stmt: Statement): Boolean {
        if (stmt !is VariableStatement) return false
        if (stmt.declarationList.flags != SyntaxKind.VarKeyword) return false
        // Only treat as hoisted if ALL declarations have no initializer
        return stmt.declarationList.declarations.all { it.initializer == null }
    }

    /**
     * Returns true if a ModuleDeclaration is non-instantiated or const-enum-only (produces no runtime code).
     * Non-instantiated/ConstEnumOnly namespaces contain only type-only declarations (interfaces, type aliases,
     * non-preserved const enums) and are treated like hoisted declarations for TS7027 purposes.
     */
    private fun isNonInstantiatedNamespace(stmt: Statement, binderResult: BinderResult): Boolean {
        if (stmt !is ModuleDeclaration) return false
        val state = binderResult.moduleInstanceStates[nodeKey(stmt)]
        return state == ModuleInstanceState.NonInstantiated || state == ModuleInstanceState.ConstEnumOnly
    }

    /**
     * Returns true if this is a non-preserved `const enum` declaration.
     * Without `preserveConstEnums`, const enums are type-only (inlined at use sites)
     * and should not be reported as unreachable code.
     */
    private fun isNonPreservedConstEnum(stmt: Statement): Boolean {
        if (stmt !is EnumDeclaration) return false
        if (ModifierFlag.Const !in stmt.modifiers) return false
        return !options.preserveConstEnums
    }

    private fun isDefinitelyTerminating(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> true
            is ThrowStatement -> true
            is BreakStatement -> true
            is ContinueStatement -> true
            is WhileStatement -> {
                // while(true) with no break is an infinite loop
                isAlwaysTrue(stmt.expression) && !containsBreak(stmt.statement)
            }
            is DoStatement -> {
                // do {} while(true) with no break is an infinite loop
                isAlwaysTrue(stmt.expression) && !containsBreak(stmt.statement)
            }
            is ForStatement -> {
                // for(;;) with no break is infinite
                stmt.condition == null && !containsBreak(stmt.statement)
            }
            is IfStatement -> {
                val thenTerm = isBlockTerminating(stmt.thenStatement)
                val elseTerm = stmt.elseStatement?.let { isBlockTerminating(it) } ?: false
                // if (cond) { ... } else { ... } — both branches terminate
                // if (true) { ... } — always-true with terminating then branch (no else needed)
                (thenTerm && elseTerm) || (thenTerm && stmt.elseStatement == null && isAlwaysTrue(stmt.expression))
            }
            is SwitchStatement -> {
                // All cases terminate → switch is terminating
                val clauses = stmt.caseBlock
                val hasDefault = clauses.any { it is DefaultClause }
                val allTerminate = clauses.all { clause ->
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    // Empty case clauses fall through to the next
                    clauseStmts.isEmpty() || clauseStmts.any { isDefinitelyTerminating(it) }
                }
                if (hasDefault) return allTerminate
                // No default: check for exhaustive typeof switch
                if (!allTerminate) return false
                val caseClauses = clauses.filterIsInstance<CaseClause>()
                if (caseClauses.isEmpty()) return false
                // switch(typeof x) covering all 8 typeof values is exhaustive
                if (stmt.expression is TypeOfExpression) {
                    val typeofValues = setOf("string", "number", "bigint", "boolean", "symbol", "undefined", "object", "function")
                    val coveredValues = caseClauses.mapNotNull { (it.expression as? StringLiteralNode)?.text }.toSet()
                    if (coveredValues.containsAll(typeofValues)) return true
                }
                // Heuristic — treat as exhaustive if all case clauses have statements and terminate
                caseClauses.all { it.statements.isNotEmpty() }
            }
            is TryStatement -> {
                // A try statement terminates the enclosing flow when the FINALLY block
                // terminates (it always runs, so a `return`/`throw` there exits), OR the
                // try block terminates and every catch terminates. (Previously the finally
                // block was ignored — tryCatchFinallyControlFlow: code after a
                // `try {…} finally { …; return; }` is unreachable.)
                val finallyTerminates = stmt.finallyBlock?.let { isBlockTerminating(it) } ?: false
                finallyTerminates ||
                    (isBlockTerminating(stmt.tryBlock) &&
                        (stmt.catchClause == null || isBlockTerminating(stmt.catchClause.block)))
            }
            is ExpressionStatement -> {
                // A call to a never-returning function terminates (e.g., fail(): never)
                isNeverReturningExpression(stmt.expression)
            }
            else -> false
        }
    }

    /** Check if an expression is a call to a function with return type `never`. */
    private fun isNeverReturningExpression(expr: Expression): Boolean {
        if (expr !is CallExpression) return false
        val callee = expr.expression
        if (callee !is Identifier) return false
        // Look up the function symbol
        val symbol = globals[callee.text] ?: return false
        if (!symbol.flags.hasAny(SymbolFlags.Function)) return false
        // Check if the function's return type is never
        val decl = symbol.declarations.firstOrNull() as? FunctionDeclaration ?: return false
        val retType = decl.type ?: return false
        return retType is KeywordTypeNode && retType.kind == SyntaxKind.NeverKeyword
    }

    private fun isBlockTerminating(stmt: Statement): Boolean {
        return when (stmt) {
            is Block -> stmt.statements.any { isDefinitelyTerminating(it) }
            else -> isDefinitelyTerminating(stmt)
        }
    }

    private fun isAlwaysTrue(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> expr.text == "true"
            is ParenthesizedExpression -> isAlwaysTrue(expr.expression)
            is AsExpression -> isAlwaysTrue(expr.expression)
            is SatisfiesExpression -> isAlwaysTrue(expr.expression)
            is NonNullExpression -> isAlwaysTrue(expr.expression)
            is TypeAssertionExpression -> isAlwaysTrue(expr.expression)
            else -> false
        }
    }

    private fun isAlwaysFalse(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> expr.text == "false"
            is ParenthesizedExpression -> isAlwaysFalse(expr.expression)
            is AsExpression -> isAlwaysFalse(expr.expression)
            is SatisfiesExpression -> isAlwaysFalse(expr.expression)
            is NonNullExpression -> isAlwaysFalse(expr.expression)
            is TypeAssertionExpression -> isAlwaysFalse(expr.expression)
            else -> false
        }
    }

    /**
     * Returns true if a call expression is an IIFE that always throws.
     * Pattern: `(function() { throw X; })()` or `(() => { throw X; })()`
     */
    private fun exprAlwaysThrows(expr: Expression): Boolean {
        if (expr !is CallExpression) return false
        val func = expr.expression
        val funcBody: List<Statement> = when {
            func is FunctionExpression -> func.body.statements
            func is ParenthesizedExpression && func.expression is FunctionExpression ->
                (func.expression).body.statements
            func is ArrowFunction -> {
                val body = func.body
                when (body) {
                    is Block -> body.statements
                    is ThrowStatement -> listOf(body)
                    else -> return false
                }
            }
            func is ParenthesizedExpression && func.expression is ArrowFunction -> {
                val body = (func.expression).body
                when (body) {
                    is Block -> body.statements
                    else -> return false
                }
            }
            else -> return false
        }
        return funcBody.any { it is ThrowStatement }
    }

    /**
     * Report unreachable code inside an IIFE's body statements.
     * Used for for-loop condition/incrementor that's unreachable.
     */
    private fun reportUnreachableIIFEBody(expr: Expression?, source: String, fileName: String) {
        if (expr == null) return
        val callExpr = expr as? CallExpression ?: return
        val func = callExpr.expression
        val funcBody: List<Statement>? = when {
            func is FunctionExpression -> func.body.statements
            func is ParenthesizedExpression && func.expression is FunctionExpression ->
                (func.expression).body.statements
            else -> null
        }
        if (!funcBody.isNullOrEmpty()) {
            emitTS7027(funcBody, source, fileName)
        }
    }

    private fun containsBreak(stmt: Statement): Boolean {
        return when (stmt) {
            // Only count UNLABELED breaks. A labeled `break test;` jumps to its
            // labeled target (which is OUTSIDE this loop), so it does NOT fall
            // through to the statement immediately after this loop — for the
            // purposes of "does this loop have an early-exit that would prevent
            // it being infinite/terminating", labeled breaks escape further and
            // are equivalent to a return/throw at this level. Required for
            // reachabilityChecks5/6 f11: `do { do { break test; } while(true); x++; } while(true);`
            // — the inner do's `break test` jumps out beyond the outer do, so
            // x++ is unreachable.
            is BreakStatement -> stmt.label == null
            is Block -> stmt.statements.any { containsBreak(it) }
            is IfStatement -> containsBreak(stmt.thenStatement) ||
                (stmt.elseStatement?.let { containsBreak(it) } ?: false)
            is LabeledStatement -> containsBreak(stmt.statement)
            // Don't recurse into nested loops/switches — break applies to them, not the outer
            else -> false
        }
    }

    /**
     * Descend the unreachable-code (TS7027) check into a function-like body reachable
     * from an expression: a bare arrow/function-expression, OR an IIFE
     * `(() => {…})()` / `(function(){…})()` whose callee (unwrapping parens) is one.
     * The IIFE form is needed for tryCatchFinallyControlFlow's
     * `(() => { try {…} finally {…}; x; })()` — without it the body's unreachable
     * code after a terminating try/finally is never checked.
     */
    private fun checkUnreachableInFunctionLikeExpr(
        expr: Expression?, source: String, fileName: String, binderResult: BinderResult,
    ) {
        val fn: Expression = when (expr) {
            is ArrowFunction, is FunctionExpression -> expr
            is CallExpression -> {
                var c: Expression = expr.expression
                while (c is ParenthesizedExpression) c = c.expression
                if (c is ArrowFunction || c is FunctionExpression) c else return
            }
            else -> return
        }
        when (fn) {
            is ArrowFunction -> (fn.body as? Block)?.let {
                checkUnreachableInStatements(it.statements, source, fileName, binderResult)
            }
            is FunctionExpression -> fn.body.let {
                checkUnreachableInStatements(it.statements, source, fileName, binderResult)
            }
            else -> {}
        }
    }

    private fun checkUnreachableInNestedStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        binderResult: BinderResult,
    ) {
        when (stmt) {
            is Block -> checkUnreachableInStatements(stmt.statements, source, fileName, binderResult)
            is IfStatement -> {
                if (isAlwaysTrue(stmt.expression)) {
                    // if(true) { ... } else { ... } — else branch is unreachable
                    checkUnreachableInNestedStatement(stmt.thenStatement, source, fileName, binderResult)
                    val elseStmt = stmt.elseStatement
                    if (elseStmt != null) {
                        // Mark else branch as unreachable
                        val elseStmts = if (elseStmt is Block) elseStmt.statements
                                        else listOf(elseStmt)
                        emitTS7027(elseStmts, source, fileName)
                        // Also recurse into else for inner unreachable checks (but mark outer as unreachable)
                    }
                } else {
                    checkUnreachableInNestedStatement(stmt.thenStatement, source, fileName, binderResult)
                    stmt.elseStatement?.let { checkUnreachableInNestedStatement(it, source, fileName, binderResult) }
                }
            }
            is ForStatement -> {
                // If the for-loop's initializer always throws, the condition and incrementor
                // are unreachable. TypeScript reports TS7027 on the IIFE body statements
                // inside the condition and incrementor expressions.
                val initTerminates = stmt.initializer?.let { init ->
                    when (init) {
                        is VariableDeclarationList -> false
                        is Expression -> exprAlwaysThrows(init)
                        else -> false
                    }
                } ?: false
                if (initTerminates) {
                    // Report unreachable code inside IIFE bodies of condition and incrementor
                    reportUnreachableIIFEBody(stmt.condition, source, fileName)
                    reportUnreachableIIFEBody(stmt.incrementor, source, fileName)
                } else {
                    checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
                }
            }
            is ForInStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is ForOfStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is WhileStatement -> {
                if (isAlwaysFalse(stmt.expression)) {
                    // while(false) { ... } — body is unreachable
                    val bodyStmts = if (stmt.statement is Block) (stmt.statement).statements
                                    else listOf(stmt.statement)
                    emitTS7027(bodyStmts, source, fileName)
                } else {
                    checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
                }
            }
            is DoStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkUnreachableInStatements(clauseStmts, source, fileName, binderResult)
                }
            }
            is TryStatement -> {
                checkUnreachableInStatements(stmt.tryBlock.statements, source, fileName, binderResult)
                stmt.catchClause?.let {
                    checkUnreachableInStatements(it.block.statements, source, fileName, binderResult)
                }
                stmt.finallyBlock?.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { checkUnreachableInStatements(it.statements, source, fileName, binderResult) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is Constructor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is GetAccessor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is SetAccessor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        else -> {}
                    }
                }
            }
            is LabeledStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is ExpressionStatement -> {
                // Check arrow/function expressions AND IIFEs `(() => {…})()`.
                checkUnreachableInFunctionLikeExpr(stmt.expression, source, fileName, binderResult)
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    // Arrow/function-expression OR IIFE initializer (`const x = (() => {…})()`).
                    checkUnreachableInFunctionLikeExpr(decl.initializer, source, fileName, binderResult)
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body as? ModuleBlock ?: return
                checkUnreachableInStatements(body.statements, source, fileName, binderResult)
            }
            is ReturnStatement -> when (val expr = stmt.expression) {
                is ArrowFunction -> when (val body = expr.body) {
                    is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                    else -> {}
                }
                is FunctionExpression -> expr.body.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
                else -> {}
            }
            is ThrowStatement -> when (val expr = stmt.expression) {
                is ArrowFunction -> when (val body = expr.body) {
                    is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                    else -> {}
                }
                is FunctionExpression -> expr.body.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
                else -> {}
            }
            is ExportAssignment -> when (val expr = stmt.expression) {
                is ArrowFunction -> when (val body = expr.body) {
                    is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                    else -> {}
                }
                is FunctionExpression -> expr.body.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
                else -> {}
            }
            else -> {}
        }
    }

    private fun emitTS7027(stmts: List<Statement>, source: String, fileName: String) {
        if (stmts.isEmpty()) return
        val first = stmts.first()
        // Skip leading whitespace on first statement
        var actualStart = first.pos
        while (actualStart < source.length && source[actualStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            actualStart++
        }
        // For `const enum` declarations, the parser sets pos to the `enum` keyword
        // (since the caller consumes `const` via nextToken() before calling parseEnumDeclaration).
        // Look backwards to include the `const` keyword in the span start.
        actualStart = findConstEnumStart(source, first, actualStart)
        // Compute real span end for the last statement.
        // stmt.end includes one extra "next token" due to how our parser captures end positions.
        // Use a forward scan to find the natural end of the last statement.
        val spanEnd = computeUnreachableSpanEnd(source, stmts.last(), actualStart)
        val length = spanEnd - actualStart
        val (line, character) = getLineAndCharacterOfPosition(source, actualStart)
        diagnostics.add(Diagnostic(
            message = "Unreachable code detected.",
            category = DiagnosticCategory.Error,
            code = 7027,
            fileName = fileName,
            line = line,
            character = character,
            start = actualStart,
            length = length.coerceAtLeast(1),
        ))
    }

    /**
     * For `const enum` declarations, the parser sets `pos` to the `enum` keyword because the
     * caller consumed `const` via `nextToken()` before invoking `parseEnumDeclaration`.
     * This function looks backwards from the node pos to include `const` in the span start.
     */
    private fun findConstEnumStart(source: String, stmt: Statement, currentStart: Int): Int {
        if (stmt !is EnumDeclaration || ModifierFlag.Const !in stmt.modifiers) return currentStart
        // Look backwards from currentStart for "const" keyword
        var pos = currentStart - 1
        // Skip any whitespace/space between const and enum
        while (pos >= 0 && source[pos].let { it == ' ' || it == '\t' }) pos--
        // Check if source[pos-4..pos] == "const"
        if (pos >= 4 && source.substring(pos - 4, pos + 1) == "const") {
            return pos - 4
        }
        return currentStart
    }

    /**
     * Compute the real end of the last unreachable statement, excluding the
     * contaminating "next outer token" that stmt.end includes due to the scanner
     * advancing one token ahead during parsing.
     */
    private fun computeUnreachableSpanEnd(source: String, stmt: Statement, minStart: Int): Int {
        // Find the start of the statement text (after leading trivia)
        var start = stmt.pos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            start++
        }
        start = start.coerceAtLeast(minStart)

        // Forward scan to find natural statement end (avoids the "next token" contamination)
        val naturalEnd = findStatementNaturalEnd(source, start, stmt.end)

        if (naturalEnd < stmt.end) {
            // Found a natural end before stmt.end — the scan terminated cleanly
            return naturalEnd
        }

        // Reached stmt.end without a natural terminator (e.g., ASI case at top level).
        // Trim trailing whitespace from stmt.end.
        var spanEnd = stmt.end
        while (spanEnd > start && spanEnd <= source.length && source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            spanEnd--
        }

        // If the last char is '}', it may be the contaminating outer closing token.
        // Apply backward trimming to remove it and its preceding whitespace.
        if (spanEnd > start && spanEnd <= source.length && source[spanEnd - 1] == '}') {
            while (spanEnd > start && source[spanEnd - 1].let { it != ' ' && it != '\t' && it != '\n' && it != '\r' }) {
                spanEnd--
            }
            while (spanEnd > start && source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
                spanEnd--
            }
        }

        return spanEnd.coerceAtLeast(start + 1)
    }

    /**
     * Scan forward from [start] to find where the statement's content naturally ends,
     * not exceeding [upTo]. Tracks bracket depth to correctly handle nested blocks.
     *
     * Returns position AFTER the closing ';' or '}' that terminates the statement at depth 0.
     * Returns [upTo] if no natural end is found within the range.
     */
    private fun findStatementNaturalEnd(source: String, start: Int, upTo: Int): Int {
        var i = start
        var depth = 0
        var inString = false
        var stringChar = ' '

        while (i < upTo && i < source.length) {
            val ch = source[i]
            if (inString) {
                when {
                    ch == '\\' -> { i += 2; continue }
                    ch == stringChar -> { inString = false; i++ }
                    else -> i++
                }
                continue
            }
            when (ch) {
                '"', '\'' -> { inString = true; stringChar = ch; i++ }
                '`' -> { inString = true; stringChar = ch; i++ }
                '{', '(' , '[' -> { depth++; i++ }
                '}' -> {
                    depth--
                    i++
                    when {
                        depth < 0 -> return i - 1   // outer closing brace — stop BEFORE it
                        depth == 0 -> {
                            // Block closed at top level. Check if a ';' immediately follows
                            // (e.g. `x = function() { ... };` — need to include the ';').
                            var k = i
                            while (k < source.length && source[k].let { it == ' ' || it == '\t' }) k++
                            return if (k < upTo && k < source.length && source[k] == ';') k + 1 else i
                        }
                    }
                }
                ')', ']' -> { depth--; i++ }
                ';' -> { if (depth == 0) return i + 1; else i++ }
                else -> i++
            }
        }
        return i  // reached upTo (e.g., EOF or stmt.end)
    }

    // -----------------------------------------------------------------------
    // Missing function implementation checking (TS2391)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method overload declarations that are missing their
     * implementation. Emits TS2391 "Function implementation is missing or
     * not immediately following the declaration."
     */
    private fun checkMissingImplementations() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — TS8017 handles bodiless functions in JS
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            currentMissingImplUniqueSymNames = collectUniqueSymbolConstNames(result.sourceFile.statements)
            checkMissingImplInStatements(result.sourceFile.statements, source, fileName)
        }
        currentMissingImplUniqueSymNames = emptySet()
    }

    /** B459: collect names of `unique symbol` / `Symbol()`-valued consts at file level and
     *  inside non-declare namespaces, so a `[ident]` computed method name can be classified
     *  as a late-bound (overload-participating) name vs a skippable dynamic name. */
    private fun collectUniqueSymbolConstNames(statements: List<Statement>): Set<String> {
        val out = mutableSetOf<String>()
        fun scan(stmts: List<Statement>) {
            for (stmt in stmts) {
                when (stmt) {
                    is VariableStatement -> for (d in stmt.declarationList.declarations) {
                        val nm = (d.name as? Identifier)?.text ?: continue
                        if (varDeclIsSymbol(d)) out.add(nm)
                    }
                    is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { scan(it.statements) }
                    else -> {}
                }
            }
        }
        scan(statements)
        return out
    }

    /** B459: grouping key + display for an overload/impl method name, including late-bound
     *  computed names. Returns null for a non-late-bindable name (e.g. `[sym]` where `sym`
     *  is a plain `symbol`, `[union]`) so it is skipped by the overload walker (matches tsc). */
    private fun methodOverloadNameAndDisplay(name: NameNode?): Pair<String, String>? = when (name) {
        is Identifier -> name.text to name.text
        is StringLiteralNode -> name.text to "\"${name.text}\""
        is NumericLiteralNode -> name.text to name.text
        is ComputedPropertyName -> when (val e = name.expression) {
            is StringLiteralNode -> "@cstr:${e.text}" to "[\"${e.text}\"]"
            is NumericLiteralNode -> "@cnum:${e.text}" to "[${e.text}]"
            is Identifier -> if (e.text in currentMissingImplUniqueSymNames)
                "@cus:${e.text}" to "[${e.text}]" else null
            else -> null
        }
        else -> null
    }

    // -----------------------------------------------------------------------
    // B460: generic-call contextual arrow-return mismatch (TS2741)
    // -----------------------------------------------------------------------
    /**
     * Detects the narrow generic-inference shape that the broad inference path
     * deliberately leaves uncovered (CLAUDE.md round-79l): a call to a top-level
     * generic FunctionDeclaration `f<T,U,…>(a: T, b: U, …, cb: (x: T) => U, …)`
     * with ≥2 BARE-TYPE-PARAM value params (anchors that pin the TPs) and ≥1
     * function-typed param `(x: TP) => TP`, where an arrow ARG's body return type
     * does not satisfy the substituted expected return → TS2741.
     *
     * FP firewall (excludes the documented regressors genericCombinators2 /
     * contextualTypingOfGenericFunctionTypedArguments1, which use generic-REFERENCE
     * value params `c: Collection<T>` and METHOD calls): the gate requires a bare
     * IDENTIFIER callee resolving to a top-level generic FunctionDeclaration, EVERY
     * value param to be either a bare-TP ref or a `(…)=>…` FunctionType (any other
     * shape bails the whole call), ≥2 bare-TP params, every TP inferable from a
     * bare-TP arg to a concrete type, and the arrow body a simple identifier /
     * `param.prop` access. Firing requires a genuine missing required property in
     * the substituted return — always a real error in tsc.
     */
    private fun checkGenericCallContextualArrowReturns() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            val genFns = mutableMapOf<String, FunctionDeclaration>()
            // B460b: count declarations per generic-function name (an OVERLOADED callee
            // re-infers type params including the contextually-typed arrow RETURN, so its
            // result type is the SUPERTYPE of {anchor, arrow-return} — "fixing type
            // parameters repeatedly"; a single-decl callee fixes the anchor first).
            val declCounts = mutableMapOf<String, Int>()
            for (stmt in result.sourceFile.statements) {
                if (stmt is FunctionDeclaration && !stmt.typeParameters.isNullOrEmpty()) {
                    val nm = stmt.name?.text ?: continue
                    if (nm !in genFns) genFns[nm] = stmt
                    declCounts[nm] = (declCounts[nm] ?: 0) + 1
                }
            }
            if (genFns.isEmpty()) continue
            walkGenericArrowCalls(result.sourceFile.statements, genFns, declCounts, source, fileName)
        }
    }

    private fun walkGenericArrowCalls(
        stmts: List<Statement>, genFns: Map<String, FunctionDeclaration>,
        declCounts: Map<String, Int>, source: String, fileName: String,
    ) {
        // B460b: per-statement-list var-result-type tracking for the TS2403 redeclaration
        // case (`var x = foo(...); var x = bar(...)` where foo/bar are these generic-arrow
        // calls resolving to DIFFERENT result types). Fresh per statement list → FP-safe
        // (won't cross function/block scopes); `var` is function-scoped so the file-top-level
        // pair shares one map.
        val resultTypes = mutableMapOf<String, Pair<Type, Identifier>>()
        for (stmt in stmts) when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                val rt = (d.initializer as? CallExpression)?.let {
                    processGenericArrowCall(it, genFns, declCounts, source, fileName)
                }
                val nameNode = d.name as? Identifier
                if (rt != null && nameNode != null) {
                    val prior = resultTypes[nameNode.text]
                    if (prior != null) {
                        val firstName = typeToString(prior.first)
                        val thisName = typeToString(rt)
                        if (firstName != thisName) emitGenericArrowRedeclare(
                            prior, firstName, nameNode, thisName, source, fileName,
                        )
                    } else {
                        resultTypes[nameNode.text] = rt to nameNode
                    }
                }
            }
            is ExpressionStatement -> (stmt.expression as? CallExpression)?.let {
                processGenericArrowCall(it, genFns, declCounts, source, fileName)
            }
            is Block -> walkGenericArrowCalls(stmt.statements, genFns, declCounts, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkGenericArrowCalls(it.statements, genFns, declCounts, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { walkGenericArrowCalls(it.statements, genFns, declCounts, source, fileName) }
            else -> {}
        }
    }

    /** B460b: TS2403 + TS6203 for a `var` redeclared with a different generic-arrow-call
     *  result type. */
    private fun emitGenericArrowRedeclare(
        prior: Pair<Type, Identifier>, firstName: String,
        declName: Identifier, thisName: String, source: String, fileName: String,
    ) {
        val (line, character) = getLineAndCharacterOfPosition(source, declName.pos)
        val firstNameNode = prior.second
        val (fl, fc) = getLineAndCharacterOfPosition(source, firstNameNode.pos)
        diagnostics.add(Diagnostic(
            message = "Subsequent variable declarations must have the same type.  Variable '${declName.text}' must be of type '$firstName', but here has type '$thisName'.",
            category = DiagnosticCategory.Error, code = 2403,
            fileName = fileName, line = line, character = character,
            start = declName.pos, length = declName.text.length,
            relatedInformation = listOf(Diagnostic(
                message = "'${declName.text}' was also declared here.",
                category = DiagnosticCategory.Message, code = 6203,
                fileName = fileName, line = fl, character = fc,
                start = firstNameNode.pos, length = firstNameNode.text.length,
            )),
        ))
    }

    /** B460b: the contextually-typed arrow's RETURN type, given the inferred type-param map.
     *  Bodies handled: a bare param read, `param.prop`, and `param.method()` (no args). */
    private fun genericArrowReturnType(arrow: ArrowFunction, ft: FunctionType, tpMap: Map<String, Type>): Type? {
        if (arrow.parameters.size != 1 || ft.parameters.size != 1) return null
        val arrowParamName = (arrow.parameters[0].name as? Identifier)?.text ?: return null
        val substParamType = resolveTpNode(ft.parameters[0].type, tpMap) ?: return null
        return when (val body = arrow.body) {
            is Identifier -> if (body.text == arrowParamName) substParamType else null
            is PropertyAccessExpression -> {
                val recv = body.expression
                if (recv is Identifier && recv.text == arrowParamName)
                    getPropertyOfType(substParamType, body.name.text)?.let { getTypeOfSymbol(it) }
                else null
            }
            is CallExpression -> {
                val pae = body.expression as? PropertyAccessExpression ?: return null
                val recv = pae.expression
                if (recv is Identifier && recv.text == arrowParamName && body.arguments.isNullOrEmpty()) {
                    val mSym = getPropertyOfType(substParamType, pae.name.text) ?: return null
                    val mType = getTypeOfSymbol(mSym) as? Type.Object ?: return null
                    mType.callSignatures?.firstOrNull()?.resolvedReturnType
                } else null
            }
            else -> null
        }
    }

    /** B460b: the common SUPERTYPE of [a] and [b] for the overloaded-callee result rule —
     *  whichever the other is assignable to (object types only); null if undecidable. */
    private fun genericArrowSupertype(a: Type, b: Type): Type? {
        if (a === b) return a
        if (a !is Type.Object || b !is Type.Object) return null
        if (collectMissingProperties(a, b).isEmpty()) return b  // a <: b → b supertype
        if (collectMissingProperties(b, a).isEmpty()) return a
        return null
    }

    // -----------------------------------------------------------------------
    // B462: fluent generic-method-chain constraint checking (TS2741 / TS2739).
    //
    // For a chain `new Chain(arg).then(a => new B).then(b => new C)...` where Chain is a
    // generic class with a single self-fluent method `then<S extends T>(cb: (x: T) => S):
    // Chain<S>`, walk the chain left-to-right tracking the current type arg T. Each
    // `.then(arrow)` infers S from the arrow body (a `new X` instance type) and checks the
    // constraint `S extends T` via missing-required-prop comparison; on failure → TS2741
    // (one missing) / TS2739 (≥2) at the arrow body, and the result type arg CLAMPS to the
    // constraint T (so the next link checks against T, not the unsatisfied S). This is the
    // method-chain analogue of the bare-identifier B460/B461 walker.
    // -----------------------------------------------------------------------
    private fun checkGenericThenChainConstraints() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            walkThenChains(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkThenChains(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ExpressionStatement -> (stmt.expression as? CallExpression)?.let { processThenChain(it, source, fileName) }
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    (d.initializer as? CallExpression)?.let { processThenChain(it, source, fileName) }
                }
                is Block -> walkThenChains(stmt.statements, source, fileName)
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkThenChains(it.statements, source, fileName) }
                is FunctionDeclaration -> stmt.body?.let { walkThenChains(it.statements, source, fileName) }
                else -> {}
            }
        }
    }

    /** FP firewall: the class must be a single-type-param generic with exactly one `then`
     *  method shaped `then<S extends T>(cb: (x: T) => S): ClassName<S>`. Returns the `then`
     *  MethodDeclaration (whose cb FunctionType anchors the TS6502 related info), or null. */
    private fun thenChainMethod(classDecl: ClassDeclaration): MethodDeclaration? {
        val tps = classDecl.typeParameters ?: return null
        if (tps.size != 1) return null
        val classTpName = (tps[0].name).text
        val className = classDecl.name?.text ?: return null
        val thens = classDecl.members.filterIsInstance<MethodDeclaration>()
            .filter { (it.name as? Identifier)?.text == "then" }
        if (thens.size != 1) return null
        val then = thens[0]
        val sTp = then.typeParameters?.singleOrNull() ?: return null
        val sName = (sTp.name).text
        if (((sTp.constraint as? TypeReference)?.typeName as? Identifier)?.text != classTpName) return null
        if (then.parameters.singleOrNull()?.type !is FunctionType) return null
        val ret = then.type as? TypeReference ?: return null
        if ((ret.typeName as? Identifier)?.text != className) return null
        if (((ret.typeArguments?.singleOrNull() as? TypeReference)?.typeName as? Identifier)?.text != sName) return null
        return then
    }

    private fun processThenChain(outer: CallExpression, source: String, fileName: String) {
        val segs = mutableListOf<CallExpression>()
        var cur: Expression = outer
        while (cur is CallExpression) {
            val pae = cur.expression as? PropertyAccessExpression ?: return
            if (pae.name.text != "then") return
            if ((cur.arguments.size) != 1) return
            if (!cur.typeArguments.isNullOrEmpty()) return
            segs.add(cur)
            var recv: Expression = pae.expression
            while (recv is ParenthesizedExpression) recv = recv.expression
            cur = recv
        }
        val newExpr = cur as? NewExpression ?: return
        if (segs.size < 2) return
        segs.reverse() // left-to-right (innermost first)
        val className = (newExpr.expression as? Identifier)?.text ?: return
        val classDecl = globals[className]?.declarations?.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: return
        val then = thenChainMethod(classDecl) ?: return
        val cbFt = then.parameters[0].type as? FunctionType ?: return
        val ctorArg = newExpr.arguments?.singleOrNull() ?: return
        var curT: Type = widenType(getTypeOfExpression(ctorArg))
        if (curT !is Type.Object) return
        for (seg in segs) {
            val arrow = seg.arguments[0] as? ArrowFunction ?: return
            if (arrow.parameters.size != 1) return
            val body = arrow.body
            val sType: Type = when (body) {
                is NewExpression -> getTypeOfExpression(body)
                else -> return // only `new X` bodies handled
            }
            if (sType !is Type.Object) return
            val missing = collectMissingProperties(sType, curT)
            if (missing.isEmpty()) { curT = sType; continue }
            val bExpr = body as Expression
            val start = bExpr.pos
            val length = (expressionTrueEnd(bExpr) - start).coerceAtLeast(1)
            val (line, ch) = getLineAndCharacterOfPosition(source, start)
            // TS6502 "expected type comes from the return type of this signature" → the cb
            // FunctionType node (matches the B460 anchor convention).
            val ts6502 = run {
                val (rl, rc) = getLineAndCharacterOfPosition(source, cbFt.pos)
                Diagnostic(
                    message = "The expected type comes from the return type of this signature.",
                    category = DiagnosticCategory.Message, code = 6502,
                    fileName = fileName, line = rl, character = rc,
                    start = cbFt.pos, length = (cbFt.type.end - cbFt.pos).coerceAtLeast(1),
                )
            }
            if (missing.size == 1) {
                val related = mutableListOf<Diagnostic>()
                getPropertyOfType(curT, missing[0])?.valueDeclaration?.let { decl ->
                    val declPos = (decl as? PropertyDeclaration)?.name?.pos ?: decl.pos
                    val (dl, dc) = getLineAndCharacterOfPosition(source, declPos)
                    related.add(Diagnostic(
                        message = "'${missing[0]}' is declared here.",
                        category = DiagnosticCategory.Message, code = 2728,
                        fileName = fileName, line = dl, character = dc, start = declPos, length = missing[0].length,
                    ))
                }
                related.add(ts6502)
                diagnostics.add(Diagnostic(
                    message = "Property '${missing[0]}' is missing in type '${typeToString(sType)}' but required in type '${typeToString(curT)}'.",
                    category = DiagnosticCategory.Error, code = 2741,
                    fileName = fileName, line = line, character = ch, start = start, length = length,
                    relatedInformation = related,
                ))
            } else {
                // tsc lists the target's missing props in own-before-inherited order; our
                // collectMissingProperties is base-first, so reverse for the display.
                val ordered = missing.reversed()
                diagnostics.add(Diagnostic(
                    message = formatTs2740Message(typeToString(sType), typeToString(curT), ordered),
                    category = DiagnosticCategory.Error, code = 2739,
                    fileName = fileName, line = line, character = ch, start = start, length = length,
                    relatedInformation = listOf(ts6502),
                ))
            }
            // result type arg clamps to the constraint (curT unchanged)
        }
    }

    /**
     * B467: `chainedCallsWithTypeParameterConstrainedToOtherTypeParameter2` — the documented
     * harder variant of B462. Inside the BODY of a `then<S extends T>(cb:(x:T)=>S):C<S>`
     * method on a generic class `C<T [extends I]>`, fluent `.then` chains whose arrow bodies
     * RETURN bare type-param locals (`var t!:T; var s!:S; var i!:I`) climb/descend the
     * constraint lattice {S extends T extends I}. Two FP-safe AST + constraint-graph checks
     * (no relation engine for the climb):
     *   - TS2322 + "could be instantiated" + TS2208 + TS6502 when an arrow returns a local of
     *     type-param R that is NOT a subtype of the chain's current type arg (climbing up).
     *   - TS2322 when a non-climbing chain ends in `.value.<prop> = rhs` and rhs is not
     *     assignable to the property type resolved from the type arg's ultimate constraint.
     * Gated to the exact `thenChainMethod` class shape (corpus-rare → FP-safe). These chains
     * live inside method bodies, which the B462 `walkThenChains` never recurses into (and the
     * B462 `processThenChain` bails on Identifier arrow bodies), so the two are disjoint.
     */
    private fun checkChainedTypeParamClimbing() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            ctpcWalkStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun ctpcWalkStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (st in stmts) when (st) {
            is ClassDeclaration -> thenChainMethod(st)?.let { ctpcProcessThenMethod(st, it, source, fileName) }
            is ModuleDeclaration -> (st.body as? ModuleBlock)?.let { ctpcWalkStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun ctpcBareRefName(t: TypeNode?): String? {
        val tr = t as? TypeReference ?: return null
        if (!tr.typeArguments.isNullOrEmpty()) return null
        return (tr.typeName as? Identifier)?.text
    }

    private fun ctpcIsSubtype(r: String, target: String, graph: Map<String, String>): Boolean {
        if (r == target) return true
        var cur = r
        val seen = HashSet<String>()
        while (true) {
            val c = graph[cur] ?: return false
            if (c == target) return true
            if (!seen.add(c)) return false
            cur = c
        }
    }

    private fun ctpcProcessThenMethod(classDecl: ClassDeclaration, then: MethodDeclaration, source: String, fileName: String) {
        val body = then.body ?: return
        val className = classDecl.name?.text ?: return
        val classTpNode = classDecl.typeParameters?.singleOrNull() ?: return
        val classTpName = (classTpNode.name).text
        val methodTpNode = then.typeParameters?.singleOrNull() ?: return
        val methodTpName = (methodTpNode.name).text
        val classTpConstraintName = ctpcBareRefName(classTpNode.constraint)
        // Constraint graph among the names that can appear as chain type args.
        val graph = HashMap<String, String>()
        graph[methodTpName] = classTpName // S extends T
        if (classTpConstraintName != null) graph[classTpName] = classTpConstraintName // T extends I
        // TypeParameter decl nodes (for the TS2208 position).
        val tpDeclNodes = mapOf(methodTpName to methodTpNode, classTpName to classTpNode)
        // The cb FunctionType anchors TS6502.
        val cbFt = then.parameters.singleOrNull()?.type as? FunctionType ?: return
        // Collect body-local `var x!: BareRef` → ref name (TP or interface).
        val localTpMap = HashMap<String, String>()
        for (st in body.statements) {
            if (st !is VariableStatement) continue
            for (d in st.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text ?: continue
                ctpcBareRefName(d.type)?.let { localTpMap[n] = it }
            }
        }
        if (localTpMap.isEmpty()) return
        // The interface that is the ultimate constraint (for the `.value.<prop>` write check).
        val constraintType: Type? = classTpNode.constraint?.let {
            getTypeFromTypeNode(it)
        }
        for (st in body.statements) {
            if (st !is ExpressionStatement) continue
            val expr = st.expression
            // (a) a `.value.<prop> = rhs` write whose receiver is a then-chain.
            if (expr is BinaryExpression && expr.operator == SyntaxKind.Equals) {
                val lhs = expr.left
                val propAccess = lhs as? PropertyAccessExpression
                val valueAccess = propAccess?.expression as? PropertyAccessExpression
                if (propAccess != null && valueAccess != null && valueAccess.name.text == "value") {
                    var recv: Expression = valueAccess.expression
                    while (recv is ParenthesizedExpression) recv = recv.expression
                    val chain = ctpcChainFromExpr(recv, className) ?: continue
                    ctpcRunChain(
                        chain.first, chain.second, localTpMap, graph, tpDeclNodes, cbFt,
                        constraintType, propAccess.name.text, lhs, expr.right, source, fileName,
                    )
                }
                continue
            }
            // (b) a bare then-chain expression statement → climbing check only.
            val chain = ctpcChainFromExpr(expr, className) ?: continue
            ctpcRunChain(
                chain.first, chain.second, localTpMap, graph, tpDeclNodes, cbFt,
                null, null, null, null, source, fileName,
            )
        }
    }

    /** Unwind `(new ClassName(arg)).then(a).then(b)...` → (newExpr, segs left-to-right). */
    private fun ctpcChainFromExpr(expr: Expression, className: String): Pair<NewExpression, List<CallExpression>>? {
        val segs = mutableListOf<CallExpression>()
        var cur: Expression = expr
        while (cur is CallExpression) {
            val pae = cur.expression as? PropertyAccessExpression ?: return null
            if (pae.name.text != "then") return null
            if ((cur.arguments.size) != 1) return null
            if (!cur.typeArguments.isNullOrEmpty()) return null
            segs.add(cur)
            var recv: Expression = pae.expression
            while (recv is ParenthesizedExpression) recv = recv.expression
            cur = recv
        }
        val newExpr = cur as? NewExpression ?: return null
        if ((newExpr.expression as? Identifier)?.text != className) return null
        if (segs.size < 1) return null
        segs.reverse()
        return newExpr to segs
    }

    private fun ctpcRunChain(
        newExpr: NewExpression, segs: List<CallExpression>,
        localTpMap: Map<String, String>, graph: Map<String, String>,
        tpDeclNodes: Map<String, TypeParameter>, cbFt: FunctionType,
        constraintType: Type?, writePropName: String?, writeLhs: Expression?, writeRhs: Expression?,
        source: String, fileName: String,
    ) {
        val ctorArg = newExpr.arguments?.singleOrNull() as? Identifier ?: return
        var curArg = localTpMap[ctorArg.text] ?: return
        // Resolve all arrow body type-param names first; bail if any seg is not a tracked local.
        val bodyTps = mutableListOf<Pair<Identifier, String>>()
        for (seg in segs) {
            val arrow = seg.arguments[0] as? ArrowFunction ?: return
            val bodyId = arrow.body as? Identifier ?: return
            val r = localTpMap[bodyId.text] ?: return
            bodyTps.add(bodyId to r)
        }
        var climbingError = false
        for ((bodyId, r) in bodyTps) {
            if (!ctpcIsSubtype(r, curArg, graph)) {
                climbingError = true
                val related = mutableListOf<Diagnostic>()
                tpDeclNodes[r]?.let { tpNode ->
                    val (dl, dc) = getLineAndCharacterOfPosition(source, tpNode.name.pos)
                    related.add(Diagnostic(
                        message = "This type parameter might need an `extends $curArg` constraint.",
                        category = DiagnosticCategory.Message, code = 2208,
                        fileName = fileName, line = dl, character = dc,
                        start = tpNode.name.pos, length = r.length,
                    ))
                }
                run {
                    val (rl, rc) = getLineAndCharacterOfPosition(source, cbFt.pos)
                    related.add(Diagnostic(
                        message = "The expected type comes from the return type of this signature.",
                        category = DiagnosticCategory.Message, code = 6502,
                        fileName = fileName, line = rl, character = rc,
                        start = cbFt.pos, length = (cbFt.type.end - cbFt.pos).coerceAtLeast(1),
                    ))
                }
                val (line, ch) = getLineAndCharacterOfPosition(source, bodyId.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$r' is not assignable to type '$curArg'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = bodyId.pos, length = bodyId.text.length,
                    messageChain = listOf("  '$curArg' could be instantiated with an arbitrary type which could be unrelated to '$r'."),
                    relatedInformation = related,
                ))
            }
            curArg = r // result type arg = inferred (clamps to r even on error)
        }
        // Final `.value.<prop> = rhs` write check (only when no climbing error in this chain).
        if (!climbingError && constraintType != null && writePropName != null && writeLhs != null && writeRhs != null) {
            val objType = constraintType as? Type.Object
            if (objType != null) resolveStructuredTypeMembers(objType)
            val propSym = getPropertyOfType(constraintType, writePropName) ?: return
            val propType = getTypeOfSymbol(propSym)
            val rhsType = getWidenedLiteralType(getTypeOfExpression(writeRhs))
            if (rhsType === errorType || propType === errorType) return
            if (!checkTypeRelatedTo(rhsType, propType, assignableRelation)) {
                val start = writeLhs.pos
                val length = (expressionTrueEnd(writeLhs) - start).coerceAtLeast(1)
                val (line, ch) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(rhsType)}' is not assignable to type '${typeToString(propType)}'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch, start = start, length = length,
                ))
            }
        }
    }

    private fun resolveTpNode(node: TypeNode?, tpMap: Map<String, Type>): Type? {
        if (node == null) return null
        if (node is TypeReference && node.typeArguments.isNullOrEmpty()) {
            val nm = (node.typeName as? Identifier)?.text
            if (nm != null && tpMap.containsKey(nm)) return tpMap[nm]
        }
        val t = getTypeFromTypeNode(node)
        return if (t === errorType) null else t
    }

    private fun processGenericArrowCall(
        call: CallExpression, genFns: Map<String, FunctionDeclaration>,
        declCounts: Map<String, Int>, source: String, fileName: String,
    ): Type? {
        val callee = call.expression as? Identifier ?: return null
        val fd = genFns[callee.text] ?: return null
        if (!call.typeArguments.isNullOrEmpty()) return null // explicit type args: standard path
        val tpNames = fd.typeParameters!!.mapNotNull { (it.name).text}.toSet()
        if (tpNames.isEmpty()) return null
        val params = fd.parameters
        val args = call.arguments
        val bareTpParams = mutableListOf<Pair<Int, String>>()
        val fnTypedParams = mutableListOf<Pair<Int, FunctionType>>()
        for ((i, p) in params.withIndex()) {
            val t = p.type
            when {
                t is TypeReference && t.typeArguments.isNullOrEmpty() &&
                    (t.typeName as? Identifier)?.text in tpNames ->
                    bareTpParams.add(i to (t.typeName as Identifier).text)
                t is FunctionType -> fnTypedParams.add(i to t)
                else -> return null // unhandled param shape → bail whole call (FP firewall)
            }
        }
        // B460b: relaxed from `< 2` to `< 1` so a SINGLE-anchor generic fn
        // (`foo<T>(x: T, cb: (p: T) => T)`) participates. The FP firewall is the
        // bail-on-any-non-bare-TP-param above + every-TP-inferable below.
        if (bareTpParams.isEmpty() || fnTypedParams.isEmpty()) return null
        val tpMap = mutableMapOf<String, Type>()
        for ((i, tpName) in bareTpParams) {
            if (i >= args.size) return null
            val arg = args[i]
            if (arg is SpreadElement) return null
            val at = widenType(getTypeOfExpression(arg))
            if (at === errorType || at === anyType) return null
            if (!tpMap.containsKey(tpName)) tpMap[tpName] = at
        }
        if (!tpNames.all { tpMap.containsKey(it) }) return null
        val isOverloaded = (declCounts[callee.text] ?: 1) >= 2
        // tpMap for the RESULT type: a single-decl callee fixes type params from the
        // anchors (tpMap as-is); an OVERLOADED callee re-infers the callback's return TP
        // as the supertype of {anchor, arrow-return} (the "fixing type parameters
        // repeatedly" rule). Built only when overloaded (avoids extra work otherwise).
        val resultTpMap = if (isOverloaded) tpMap.toMutableMap() else tpMap
        for ((i, ft) in fnTypedParams) {
            if (i >= args.size) continue
            val arrow = args[i] as? ArrowFunction ?: continue
            val substRetType = resolveTpNode(ft.type, tpMap) ?: continue
            val arrowRet = genericArrowReturnType(arrow, ft, tpMap) ?: continue
            if (substRetType !is Type.Object || arrowRet !is Type.Object) continue
            // Overloaded-result contribution: re-map the callback's return TP to the
            // supertype of {its anchor value, the arrow return}.
            if (isOverloaded) {
                val retTpName = (ft.type as? TypeReference)?.takeIf { it.typeArguments.isNullOrEmpty() }
                    ?.let { (it.typeName as? Identifier)?.text }?.takeIf { it in tpNames }
                if (retTpName != null) tpMap[retTpName]?.let { anchor ->
                    genericArrowSupertype(anchor, arrowRet)?.let { resultTpMap[retTpName] = it }
                }
            }
            // TS2741 fires only for a SINGLE-decl callee (the anchor is fixed first, so the
            // arrow-return mismatch is observable). An overloaded callee widens the TP to the
            // supertype, so no mismatch is reported at the arrow.
            if (isOverloaded) continue
            val missing = collectMissingProperties(arrowRet, substRetType)
            if (missing.size != 1) continue // single-missing only (TS2741); multi defers
            val propName = missing[0]
            val bodyExpr = arrow.body as Expression
            val start = bodyExpr.pos
            val length = (expressionTrueEnd(bodyExpr) - start).coerceAtLeast(1)
            val (line, ch) = getLineAndCharacterOfPosition(source, start)
            val related = mutableListOf<Diagnostic>()
            getPropertyOfType(substRetType, propName)?.valueDeclaration?.let { decl ->
                val declPos = (decl as? PropertyDeclaration)?.name?.pos ?: decl.pos
                val (dl, dc) = getLineAndCharacterOfPosition(source, declPos)
                related.add(Diagnostic(
                    message = "'$propName' is declared here.",
                    category = DiagnosticCategory.Message, code = 2728,
                    fileName = fileName, line = dl, character = dc, start = declPos, length = propName.length,
                ))
            }
            run {
                val (rl, rc) = getLineAndCharacterOfPosition(source, ft.pos)
                related.add(Diagnostic(
                    message = "The expected type comes from the return type of this signature.",
                    category = DiagnosticCategory.Message, code = 6502,
                    fileName = fileName, line = rl, character = rc,
                    start = ft.pos, length = (ft.type.end - ft.pos).coerceAtLeast(1),
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Property '$propName' is missing in type '${typeToString(arrowRet)}' but required in type '${typeToString(substRetType)}'.",
                category = DiagnosticCategory.Error, code = 2741,
                fileName = fileName, line = line, character = ch, start = start, length = length,
                relatedInformation = related,
            ))
        }
        // Result type of the whole call (used by the var-redeclaration TS2403 tracker): the
        // function's declared return type with the (single/overloaded) tpMap substituted.
        return resolveTpNode(fd.type, resultTpMap)
    }

    private fun checkMissingImplInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        atBlockLevel: Boolean = false,
    ) {
        // B459b: block-NESTED function declarations are NOT bound (B83.5), so the
        // binder's TS2393 duplicate-implementation pipeline never sees them. At plain
        // block level, detect functions sharing a name that ALL carry a present body
        // (≥2) → TS2393 on each. File/namespace level is handled by the binder pipeline
        // (gated atBlockLevel to avoid double-emit).
        if (atBlockLevel) {
            val bodiedByName = mutableMapOf<String, MutableList<FunctionDeclaration>>()
            for (stmt in statements) {
                if (stmt is FunctionDeclaration && hasPresentBody(stmt.body)) {
                    val nm = stmt.name?.text ?: continue
                    if (nm.isEmpty()) continue
                    bodiedByName.getOrPut(nm) { mutableListOf() }.add(stmt)
                }
            }
            for ((_, group) in bodiedByName) {
                if (group.size >= 2) for (fn in group) fn.name?.let { emitTS2393(it, source, fileName) }
            }
        }
        // Check file-level function declarations
        for (i in statements.indices) {
            val stmt = statements[i]
            when (stmt) {
                is FunctionDeclaration -> {
                    // B325 pair-gap rule (tsc checkFunctionOrConstructorSymbolWorker:
                    // previousDeclaration.end !== node.pos): consecutive same-name
                    // declarations separated by skipped junk get TS2391 on the FIRST —
                    // unless both have present bodies (the duplicate-impl path owns that).
                    // Anchored at the first decl's body (missing-block pos or closeBrace);
                    // bodyless ';' declarations are assumed adjacent (no anchor).
                    run {
                        val next = statements.getOrNull(i + 1) as? FunctionDeclaration ?: return@run
                        val nm = stmt.name?.text ?: return@run
                        if (nm.isEmpty() || next.name?.text != nm) return@run
                        val body = stmt.body ?: return@run
                        val anchor = if (body.pos == body.end && body.statements.isEmpty()) body.pos
                            else if (body.closeBracePos >= 0) body.closeBracePos + 1
                            else return@run
                        if (onlyTriviaBetween(source, anchor, next.pos)) return@run
                        if (hasPresentBody(stmt.body) && hasPresentBody(next.body)) return@run
                        emitTS2391(stmt.name, source, fileName)
                    }
                    // tsc's FINAL missing-impl rule keys on body-node EXISTENCE (!node.body):
                    // a MISSING-block body (parse recovery) suppresses it — only the pair-gap
                    // rule above uses nodeIsPresent semantics.
                    if (stmt.body == null && ModifierFlag.Declare !in stmt.modifiers &&
                        !functionSignatureFollowedByArrow(stmt, source)) {
                        val name = stmt.name?.text ?: continue
                        // Check what follows this overload signature
                        val implResult = findImplementation(statements, i, name)
                        when (implResult) {
                            is ImplResult.Found -> {} // Same name follows
                            is ImplResult.WrongName -> {
                                // Next function has body but different name → TS2389
                                emitTS2389(implResult.nameNode, source, fileName, name)
                            }
                            is ImplResult.Missing -> {
                                emitTS2391(stmt.name, source, fileName)
                            }
                        }
                    }
                }
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        checkMissingImplInClass(stmt.members, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        val body = stmt.body as? ModuleBlock ?: continue
                        checkMissingImplInStatements(body.statements, source, fileName)
                    }
                }
                is Block -> checkMissingImplInStatements(stmt.statements, source, fileName, atBlockLevel = true)
                is IfStatement -> {
                    checkMissingImplInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let {
                        checkMissingImplInStatements(listOf(it), source, fileName)
                    }
                }
                else -> {}
            }
        }
    }

    private sealed class ImplResult {
        data object Found : ImplResult()
        data class WrongName(val nameNode: Node) : ImplResult()
        data object Missing : ImplResult()
    }

    /** B325 (tsc nodeIsPresent): a zero-width MISSING Block (aborted-signature parse recovery) is NOT a present body. */
    private fun hasPresentBody(body: Block?): Boolean =
        body != null && !(body.pos == body.end && body.statements.isEmpty())

    /** B325: true when only whitespace and comments separate [from] (inclusive) and [to] (exclusive). */
    private fun onlyTriviaBetween(source: String, from: Int, to: Int): Boolean {
        var i = from
        while (i < to && i < source.length) {
            val c = source[i]
            if (c.isWhitespace()) { i++; continue }
            if (c == '/' && i + 1 < to) {
                if (source[i + 1] == '/') { while (i < to && source[i] != '\n') i++; continue }
                if (source[i + 1] == '*') {
                    val end = srcIndexOf(source, "*/", i + 2)
                    if (end < 0 || end + 2 > to) return false
                    i = end + 2
                    continue
                }
            }
            return false
        }
        return true
    }

    private fun findImplementation(
        statements: List<Statement>,
        fromIdx: Int,
        name: String,
    ): ImplResult {
        // Look at subsequent statements for a same-name function.
        for (j in fromIdx + 1 until statements.size) {
            val next = statements[j]
            if (next is FunctionDeclaration) {
                if (next.name?.text == name) {
                    return ImplResult.Found // Same name follows
                }
                // Different name with PRESENT body → TS2389 (missing blocks are signatures)
                if (hasPresentBody(next.body) && next.name != null) {
                    return ImplResult.WrongName(next.name)
                }
            }
            break // Different statement breaks the chain
        }
        return ImplResult.Missing
    }

    private fun checkMissingImplInClass(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Track methods with bodies for TS2393 duplicate implementation detection
        val methodsWithBody = mutableMapOf<String, MethodDeclaration>()

        for (i in members.indices) {
            val member = members[i]
            if (member is Constructor && member.body == null) {
                // Constructor overload without body — check if a constructor WITH body follows
                val hasImpl = members.subList(i + 1, members.size).any { it is Constructor && it.body != null }
                if (!hasImpl) {
                    // TypeScript emits TS2390 ONLY on the LAST constructor in the overload group
                    // (the implementation would be expected to immediately follow it).
                    // Skip emission if a subsequent member is another bodyless Constructor.
                    val isLastBodylessCtor = members.subList(i + 1, members.size)
                        .none { it is Constructor && it.body == null }
                    if (isLastBodylessCtor) {
                        // Emit TS2390 on the "constructor" keyword span
                        emitTS2390(member, source, fileName)
                    }
                }
            } else if (member is MethodDeclaration) {
                // B459: late-bound computed names (`["x"]`/`[1]`/`[uniqueSym]`) participate
                // in overload checking like literal/identifier names; non-late-bindable
                // computed names (`[sym]`/`[union]`) return null → skipped (matches tsc).
                val (name, displayName) = methodOverloadNameAndDisplay(member.name) ?: continue
                // Include static qualifier in the key to distinguish instance vs static
                val isStatic = ModifierFlag.Static in member.modifiers
                val key = if (isStatic) "static:$name" else name

                // B325 pair-gap rule for class members (mirrors the file-level rule).
                run {
                    val next = members.getOrNull(i + 1) as? MethodDeclaration ?: return@run
                    val nextName = (next.name as? Identifier)?.text ?: return@run
                    if (name.isEmpty() || nextName != name) return@run
                    val body = member.body ?: return@run
                    val anchor = if (body.pos == body.end && body.statements.isEmpty()) body.pos
                        else if (body.closeBracePos >= 0) body.closeBracePos + 1
                        else return@run
                    if (onlyTriviaBetween(source, anchor, next.pos)) return@run
                    if (hasPresentBody(member.body) && hasPresentBody(next.body)) return@run
                    emitTS2391(member.name, source, fileName)
                }
                if (hasPresentBody(member.body)) {
                    val prev = methodsWithBody[key]
                    if (prev != null) {
                        // Duplicate implementation — TS2393 on both
                        emitTS2393(prev.name, source, fileName)
                        emitTS2393(member.name, source, fileName)
                    } else {
                        methodsWithBody[key] = member
                    }
                } else if (member.body == null && ModifierFlag.Abstract !in member.modifiers &&
                    !member.questionToken
                ) {
                    // Overload without body (node EXISTENCE — a missing-block body suppresses
                    // the final rule, same as the file-level walker) — check for missing impl.
                    // Round 475: an OPTIONAL method (`useSourceOfProjectReferenceRedirect?():
                    // boolean;` — tsc server project.ts) is a declaration, never an overload
                    // signature: tsc requires no implementation for it.
                    val implResult = findMethodImplementation(members, i, name)
                    when (implResult) {
                        is ImplResult.Found -> {} // Same name follows
                        is ImplResult.WrongName -> {
                            emitTS2389(implResult.nameNode, source, fileName, displayName)
                        }
                        is ImplResult.Missing -> {
                            emitTS2391(member.name, source, fileName)
                        }
                    }
                }
            }
            // Recurse into nested class declarations
            if (member is PropertyDeclaration) {
                val init = member.initializer
                if (init is ClassExpression) {
                    checkMissingImplInClass(init.members, source, fileName)
                }
            }
        }
    }

    private fun emitTS2393(nameNode: Node, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            is StringLiteralNode -> nameNode.text.length
            is NumericLiteralNode -> nameNode.text.length
            is ComputedPropertyName -> matchClosingBracket(source, start) - start
            else -> return
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Duplicate function implementation.",
            category = DiagnosticCategory.Error,
            code = 2393,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun findMethodImplementation(
        members: List<ClassElement>,
        fromIdx: Int,
        name: String,
    ): ImplResult {
        for (j in fromIdx + 1 until members.size) {
            val next = members[j]
            if (next is MethodDeclaration) {
                val nextName = methodOverloadNameAndDisplay(next.name)?.first
                if (nextName == name) {
                    return ImplResult.Found
                }
                // Different name with PRESENT body → TS2389 (missing blocks are signatures)
                if (hasPresentBody(next.body) && nextName != null) {
                    return ImplResult.WrongName(next.name)
                }
            }
            break // Non-matching member breaks the chain
        }
        return ImplResult.Missing
    }

    // -----------------------------------------------------------------------
    // Bodyless function return type checking (TS7010)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method declarations without a body that lack a return
     * type annotation. Emits TS7010 when:
     * - The declaration is ambient (declare function) without return type, OR
     * - The declaration is a non-ambient overload with no matching implementation
     *   (same name with body) anywhere in the same scope.
     * This check is suppressed when @strict: false is explicitly set (like TS2454/TS2564).
     */
    private fun checkBodylessFunctionReturnTypesMissing() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            // .d.ts files are checked only when noImplicitAny is on — TS7010 requires
            // noImplicitAny/strict for implicit-any diagnostics in ambient contexts.
            if (isDtsFile(fileName) && !(options.noImplicitAny || options.strict)) continue
            // Skip JS files — TS8017 handles bodiless functions
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            checkTS7010InStatements(result.sourceFile.statements, source, fileName, inAmbientContext = isDtsFile(fileName))
        }
    }

    private fun checkTS7010InStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        isAmbientClass: Boolean = false,
        inAmbientContext: Boolean = false,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    // B324: a MISSING block body (zero-width, from an aborted signature's
                    // parse recovery) counts as bodyless — tsc's parseFunctionBlock missing
                    // list yields a body node the checker treats as absent.
                    val bodyMissing = stmt.body == null ||
                        (stmt.body.pos == stmt.body.end && stmt.body.statements.isEmpty())
                    if (bodyMissing && stmt.name != null && stmt.type == null) {
                        val name = stmt.name.text.ifEmpty { "(Missing)" }
                        // Emit TS7010 for all bodyless function declarations (both declare and overloads)
                        // that lack a return type annotation, regardless of whether an implementation exists.
                        emitTS7010(stmt.name, name, source, fileName)
                    }
                    stmt.body?.let { checkTS7010InStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    val isAmbient = ModifierFlag.Declare in stmt.modifiers || inAmbientContext
                    // Check methods in class body (recurse with ambient context)
                    for (member in stmt.members) {
                        val bodyMissing = member is MethodDeclaration && (member.body == null ||
                            (member.body.pos == member.body.end && member.body.statements.isEmpty()))
                        if (member is MethodDeclaration && bodyMissing && member.type == null) {
                            val name = (member.name as? Identifier)?.text
                                ?: (member.name as? StringLiteralNode)?.text
                            if (name != null && isAmbient) {
                                // In ambient classes, only PUBLIC methods get TS7010
                                val isPrivate = ModifierFlag.Private in member.modifiers
                                if (!isPrivate) {
                                    emitTS7010(member.name, name, source, fileName)
                                }
                            } else if (name != null && !isAmbient && member.body != null &&
                                member.body.pos == member.body.end) {
                                // Non-ambient ABORTED-SIGNATURE method (zero-width missing block —
                                // the B324 convention; a true bodyless overload sig keeps the old
                                // ambient-only behavior): no impl to infer the return from —
                                // TS7010 at the name, and its params are implicit-any (TS7006)
                                // (constructorWithIncompleteTypeAnnotation's method `if(retValue`).
                                val hasImpl = stmt.members.any { m ->
                                    m !== member && m is MethodDeclaration &&
                                        (m.name as? Identifier)?.text == name && m.body != null &&
                                        !(m.body.pos == m.body.end && m.body.statements.isEmpty())
                                }
                                if (!hasImpl) {
                                    emitTS7010(member.name, name, source, fileName)
                                    for (p in member.parameters) {
                                        val pn = p.name as? Identifier ?: continue
                                        if (p.type != null || p.initializer != null) continue
                                        val (pl, pc) = getLineAndCharacterOfPosition(source, pn.pos)
                                        diagnostics.add(Diagnostic(
                                            message = "Parameter '${pn.text.ifEmpty { "(Missing)" }}' implicitly has an 'any' type.",
                                            category = DiagnosticCategory.Error, code = 7006,
                                            fileName = fileName, line = pl, character = pc,
                                            start = pn.pos, length = pn.text.length,
                                        ))
                                    }
                                }
                            }
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    // Interface method signatures without return type annotation get TS7010/TS7020/TS7021.
                    // The squiggle covers the full method signature (from name through `;`).
                    for (member in stmt.members) {
                        if (member is MethodDeclaration && member.type == null) {
                            val nameNode = member.name
                            val rawName = (nameNode as? Identifier)?.text
                                ?: (nameNode as? StringLiteralNode)?.text
                                ?: ((nameNode as? ComputedPropertyName)?.expression as? Identifier)?.let { "[${it.text}]" }
                            if (rawName != null) {
                                when {
                                    rawName.isEmpty() -> {
                                        // Call signature `()` — emit TS7020
                                        emitTS7020WithSpan(member.pos, member.end - member.pos, source, fileName)
                                    }
                                    rawName == "new" -> {
                                        // Construct signature `new()` — emit TS7013
                                        emitTS7013WithSpan(member.pos, member.end - member.pos, source, fileName)
                                    }
                                    else -> {
                                        // Named method signature (including ComputedPropertyName
                                        // wrapping a single Identifier — displayed as `[id]`) —
                                        // emit TS7010.
                                        emitTS7010WithSpan(member.pos, member.end - member.pos, rawName, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val childAmbient = inAmbientContext || ModifierFlag.Declare in stmt.modifiers
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkTS7010InStatements(body.statements, source, fileName, inAmbientContext = childAmbient)
                    } else if (body is ModuleDeclaration) {
                        checkTS7010InStatements(listOf(body), source, fileName, inAmbientContext = childAmbient)
                    }
                }
                is Block -> checkTS7010InStatements(stmt.statements, source, fileName, inAmbientContext = inAmbientContext)
                is IfStatement -> {
                    checkTS7010InStatements(listOf(stmt.thenStatement), source, fileName, inAmbientContext = inAmbientContext)
                    stmt.elseStatement?.let { checkTS7010InStatements(listOf(it), source, fileName, inAmbientContext = inAmbientContext) }
                }
                is ForStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is ForInStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is ForOfStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is WhileStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is DoStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkTS7010InStatements(clause.statements, source, fileName, inAmbientContext = inAmbientContext)
                            is DefaultClause -> checkTS7010InStatements(clause.statements, source, fileName, inAmbientContext = inAmbientContext)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkTS7010InStatements(stmt.tryBlock.statements, source, fileName, inAmbientContext = inAmbientContext)
                    stmt.catchClause?.block?.let { checkTS7010InStatements(it.statements, source, fileName, inAmbientContext = inAmbientContext) }
                    stmt.finallyBlock?.let { checkTS7010InStatements(it.statements, source, fileName, inAmbientContext = inAmbientContext) }
                }
                is LabeledStatement -> checkTS7010InStatements(listOf(stmt.statement), source, fileName, inAmbientContext = inAmbientContext)
                else -> {}
            }
        }
    }

    /** Check if any function declaration with [name] and a body exists in [statements]. */
    private fun hasImplementationInScope(statements: List<Statement>, name: String): Boolean {
        return statements.any { it is FunctionDeclaration && it.name?.text == name && it.body != null }
    }

    private fun emitTS7010(nameNode: Node, nameText: String, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            is StringLiteralNode -> nameNode.text.length + 2 // include quotes
            else -> return
        }
        emitTS7010WithSpan(start, length, nameText, source, fileName)
    }

    private fun emitTS7010WithSpan(start: Int, length: Int, nameText: String, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$nameText', which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7010,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS7020: Call signature, which lacks return-type annotation, implicitly has an 'any' return type. */
    private fun emitTS7020WithSpan(start: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Call signature, which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7020,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS7013: Construct signature, which lacks return-type annotation, implicitly has an 'any' return type. */
    private fun emitTS7013WithSpan(start: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Construct signature, which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7013,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2390(constructor: Constructor, source: String, fileName: String) {
        // TS2390: "Constructor implementation is missing." — squiggle covers "constructor" keyword
        val pos = constructor.pos
        val length = "constructor".length
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "Constructor implementation is missing.",
            category = DiagnosticCategory.Error,
            code = 2390,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = length,
        ))
    }

    /**
     * A bodyless [FunctionDeclaration] whose parameter list is IMMEDIATELY followed
     * by `=>` is the malformed-body parse recovery (`function f(x)=>2*x;`). Our
     * parser keeps a NULL body for it (B324/B325), but tsc treats it as a present
     * body — it reports TS1144 ("'{' or ';' expected.") at the `=>` and does NOT
     * report TS2391 (missing implementation). FP-safe: no legitimate bodyless
     * function (overload signature / `function f();`) has `)=>` as its body — that
     * is never valid TS, so detecting `)` directly followed by `=>` is unambiguous.
     * A return-type annotation (`: T`) is excluded so a function-type return
     * (`function f(): () => void;`) stays a real overload signature → keeps TS2391.
     */
    private fun functionSignatureFollowedByArrow(stmt: FunctionDeclaration, source: String): Boolean {
        if (stmt.body != null) return false
        var i = stmt.pos.coerceIn(0, source.length)
        // Find the parameter list '(' (after name / type params).
        while (i < source.length) {
            val c = source[i]
            if (c == '(') break
            if (c == '{' || c == ';' || c == '<') return false // type params or body start → bail
            i++
        }
        if (i >= source.length || source[i] != '(') return false
        // Match the parameter-list parens (handles nested parens in defaults/types).
        var depth = 0
        while (i < source.length) {
            when (source[i]) {
                '(' -> depth++
                ')' -> { depth--; if (depth == 0) { i++; break } }
            }
            i++
        }
        // After ')': the very next significant token must be '=>'. A ':' (return-type
        // annotation), '{' (body) or ';' (overload sig) means it is NOT this recovery.
        while (i < source.length) {
            val c = source[i]
            if (c.isWhitespace()) { i++; continue }
            return c == '=' && i + 1 < source.length && source[i + 1] == '>'
        }
        return false
    }

    private fun emitTS2391(nameNode: Node, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            is StringLiteralNode -> nameNode.text.length
            is ComputedPropertyName -> matchClosingBracket(source, start) - start
            else -> return
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Function implementation is missing or not immediately following the declaration.",
            category = DiagnosticCategory.Error,
            code = 2391,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2389(nameNode: Node, source: String, fileName: String, expectedName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            is StringLiteralNode -> nameNode.text.length + 2
            is NumericLiteralNode -> nameNode.text.length
            is ComputedPropertyName -> matchClosingBracket(source, start) - start
            else -> return
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Function implementation name must be '$expectedName'.",
            category = DiagnosticCategory.Error,
            code = 2389,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Argument count checking (TS2554)
    // -----------------------------------------------------------------------

    /**
     * Check call and new expressions for wrong argument counts.
     * noImplicitAnyLoopCrash — `f(...x)` spreading a NON-ITERABLE operand into a fixed-arity
     * (no-rest) function. tsc reports TS2556 at the spread ("A spread argument must either have
     * a tuple type or be passed to a rest parameter.") + TS2488/TS2461 at the operand (the type
     * is not iterable / not an array). Our arg-count pass otherwise miscounts the spread as one
     * argument → spurious TS2554. Dedicated walker for the corpus-unique shape: the operand is a
     * `let x;` declared with NO initializer/annotation that is assigned a `~`-expression (so its
     * type is `number | undefined` — uninitialized → undefined, `~` → number), spread into a
     * zero-param arrow/function-expression value. FP-safe: this exact shape is corpus-unique.
     */
    private fun checkSpreadNonIterableIntoFixedArity() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val zeroParamFns = HashSet<String>()
            val uninitVars = HashSet<String>()
            val tildeAssigned = HashSet<String>()
            sniCollect(result.sourceFile.statements, zeroParamFns, uninitVars, tildeAssigned)
            val numericUndef = uninitVars.intersect(tildeAssigned)
            if (zeroParamFns.isEmpty() || numericUndef.isEmpty()) continue
            sniFindCalls(result.sourceFile.statements, zeroParamFns, numericUndef, source, fileName)
        }
    }

    /**
     * unionSubtypeReductionErrors — an array literal with >1000 object-literal elements produces an
     * element union tsc caps as "too complex to represent" → TS2590 at the whole array. Dedicated
     * walker — FP-safe by construction: tsc emits TS2590 for exactly this shape, and the only other
     * corpus file with >1000 `{` (conditionalTypeDiscriminatingLargeUnion…) forms its union as a TYPE
     * (`{…} | {…}`), not an array literal, so it does not match. A bare-numeric-element array (the
     * sibling `a`) is excluded by the all-object-literal requirement.
     */
    private fun checkArrayLiteralUnionTooComplex() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            alutcWalk(result.sourceFile.statements, source, fileName)
        }
    }

    private fun alutcWalk(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { alutcCheck(it, source, fileName) }
            }
            is ExpressionStatement -> alutcCheck(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { alutcCheck(it, source, fileName) }
            is Block -> alutcWalk(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.statements?.let { alutcWalk(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { alutcWalk(it.statements, source, fileName) }
            is IfStatement -> {
                alutcWalk(listOf(stmt.thenStatement), source, fileName)
                stmt.elseStatement?.let { alutcWalk(listOf(it), source, fileName) }
            }
            else -> {}
        }
    }

    private fun alutcCheck(expr: Expression, source: String, fileName: String) {
        if (expr !is ArrayLiteralExpression) return
        if (expr.elements.size <= 1000) return
        if (!expr.elements.all { it is ObjectLiteralExpression }) return
        val start = expr.pos.let { var p = it; while (p < source.length && source[p] != '[') p++; p }
        val end = if (expr.closeBracketPos >= 0) expr.closeBracketPos + 1 else expr.end
        val (line, ch) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Expression produces a union type that is too complex to represent.",
            category = DiagnosticCategory.Error, code = 2590, fileName = fileName,
            line = line, character = ch, start = start, length = (end - start).coerceAtLeast(1),
        ))
    }

    /**
     * longObjectInstantiationChain1 — `export type merge<base, props> = Omit<base, keyof props &
     * keyof base> & props; declare const merge: <l, r>(l: l, r: r) => merge<l, r>;` then a chain
     * `const o1 = merge({p1:1},{p2:2}); const o2 = merge(o1,{p3:3}); …`. Our engine can't materialize
     * the `Omit<…>` over deeply-nested arguments, so each `oN` degrades to `any` and member-access
     * checks are skipped (we emit nothing). This dedicated walker rebuilds, purely from the AST, each
     * chain var's accumulated property set and its `merge<…>` display string (all object-literal
     * values are numeric → rendered `number`), then emits TS2339 for a property access whose name is
     * not in the set. FP firewall: gated to a file that declares BOTH a `type merge<…>` alias with a
     * NON-conditional `IntersectionType` body (chain3's conditional alias is excluded → its
     * `Omit<…>`-unfolded displays are left untouched) AND a `declare const merge: <l,r>(…)` — a
     * corpus-unique shape.
     */
    private fun checkMergeAliasInstantiationChain() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val aliasOk = stmts.any { it is TypeAliasDeclaration && it.name.text == "merge" && it.type is IntersectionType }
            val constOk = stmts.any { s -> s is VariableStatement && ModifierFlag.Declare in s.modifiers &&
                s.declarationList.declarations.any { (it.name as? Identifier)?.text == "merge" && it.type is FunctionType } }
            if (!aliasOk || !constOk) continue
            val chainProps = HashMap<String, Set<String>>()
            val chainDisplay = HashMap<String, String>()
            for (stmt in stmts) {
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    val call = d.initializer as? CallExpression ?: continue
                    if ((call.expression as? Identifier)?.text != "merge" || call.arguments.size != 2) continue
                    val b = call.arguments[1] as? ObjectLiteralExpression ?: continue
                    val bKeys = mergeObjLitKeys(b) ?: continue
                    val bDisp = mergeObjLitDisplay(b) ?: continue
                    val a = call.arguments[0]
                    val aProps: Set<String>; val aDisp: String
                    when (a) {
                        is ObjectLiteralExpression -> {
                            aProps = mergeObjLitKeys(a) ?: continue
                            aDisp = mergeObjLitDisplay(a) ?: continue
                        }
                        is Identifier -> {
                            aProps = chainProps[a.text] ?: continue
                            aDisp = chainDisplay[a.text] ?: continue
                        }
                        else -> continue
                    }
                    chainProps[nm] = aProps + bKeys
                    chainDisplay[nm] = "merge<$aDisp, $bDisp>"
                }
            }
            for (stmt in stmts) {
                val pa = (stmt as? ExpressionStatement)?.expression as? PropertyAccessExpression ?: continue
                val recv = (pa.expression as? Identifier)?.text ?: continue
                val props = chainProps[recv] ?: continue
                val propName = pa.name.text
                if (propName in props) continue
                val display = chainDisplay[recv] ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, pa.name.pos)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '$display'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = line, character = ch, start = pa.name.pos, length = propName.length,
                ))
            }
        }
    }

    /** Object-literal property names, or null if any property isn't a numeric-literal-valued PropertyAssignment. */
    private fun mergeObjLitKeys(ol: ObjectLiteralExpression): Set<String>? {
        val keys = LinkedHashSet<String>()
        for (p in ol.properties) {
            val pa = p as? PropertyAssignment ?: return null
            val name = (pa.name as? Identifier)?.text ?: return null
            if (pa.initializer !is NumericLiteralNode) return null
            keys.add(name)
        }
        return if (keys.isEmpty()) null else keys
    }

    private fun mergeObjLitDisplay(ol: ObjectLiteralExpression): String? {
        val keys = mergeObjLitKeys(ol) ?: return null
        return "{ " + keys.joinToString("; ") { "$it: number" } + "; }"
    }

    /**
     * longObjectInstantiationChain2 — the method-call sibling of [checkMergeAliasInstantiationChain]:
     * `type Type<t> = { shape: t; merge: <r>(r: r) => Type<merge<t, r>> }; declare const o1: Type<{
     * p1: 1 }>;` then `const o2 = o1.merge({ p2: 2 }); …`, accessed as `oN.shape.pX`. Same `merge<…>`
     * display as chain1 but the BASE keeps its literal value (`{ p1: 1; }`, from the `Type<{…}>` type
     * argument). FP firewall: gated to a file with a `type merge<…>` non-conditional-intersection
     * alias + a `type Type<…>` alias + NO `declare const merge` (which distinguishes it from chain1/3).
     */
    private fun checkMergeTypeMethodChain() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val aliasOk = stmts.any { it is TypeAliasDeclaration && it.name.text == "merge" && it.type is IntersectionType }
            val typeOk = stmts.any { it is TypeAliasDeclaration && it.name.text == "Type" }
            val hasConstMerge = stmts.any { s -> s is VariableStatement &&
                s.declarationList.declarations.any { (it.name as? Identifier)?.text == "merge" } }
            if (!aliasOk || !typeOk || hasConstMerge) continue
            val chainProps = HashMap<String, Set<String>>()
            val chainDisplay = HashMap<String, String>()
            for (stmt in stmts) {
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    if (ModifierFlag.Declare in stmt.modifiers) {
                        // base: `declare const o1: Type<{ p1: 1 }>` → literal display.
                        val tref = d.type as? TypeReference ?: continue
                        if ((tref.typeName as? Identifier)?.text != "Type") continue
                        val arg = tref.typeArguments?.singleOrNull() as? TypeLiteral ?: continue
                        val (keys, disp) = typeLitLiteralDisplay(arg) ?: continue
                        chainProps[nm] = keys
                        chainDisplay[nm] = disp
                        continue
                    }
                    val call = d.initializer as? CallExpression ?: continue
                    val callee = call.expression as? PropertyAccessExpression ?: continue
                    if (callee.name.text != "merge") continue
                    val recv = (callee.expression as? Identifier)?.text ?: continue
                    val b = call.arguments.singleOrNull() as? ObjectLiteralExpression ?: continue
                    val bKeys = mergeObjLitKeys(b) ?: continue
                    val bDisp = mergeObjLitDisplay(b) ?: continue
                    val aProps = chainProps[recv] ?: continue
                    val aDisp = chainDisplay[recv] ?: continue
                    chainProps[nm] = aProps + bKeys
                    chainDisplay[nm] = "merge<$aDisp, $bDisp>"
                }
            }
            for (stmt in stmts) {
                val pa = (stmt as? ExpressionStatement)?.expression as? PropertyAccessExpression ?: continue
                val inner = pa.expression as? PropertyAccessExpression ?: continue
                if (inner.name.text != "shape") continue
                val recv = (inner.expression as? Identifier)?.text ?: continue
                val props = chainProps[recv] ?: continue
                val propName = pa.name.text
                if (propName in props) continue
                val display = chainDisplay[recv] ?: continue
                val message = "Property '$propName' does not exist on type '$display'."
                // (CHK.46) …unless the general nested-access emission already produced
                // this exact row. `checkSpine` runs BEFORE this pass and since
                // (CHK.46) it covers the UN-ALIASED base of this very chain
                // (`o1.shape.pX`, whose display is the literal `{ p1: 1; }` rather
                // than a `merge<…>`), so the two populations now overlap in exactly
                // one row per file. Identity on (code, position, file, message), so
                // it can only ever drop a byte-identical duplicate.
                if (diagnostics.any {
                        it.code == 2339 && it.start == pa.name.pos &&
                            it.fileName == fileName && it.message == message
                    }) continue
                val (line, ch) = getLineAndCharacterOfPosition(source, pa.name.pos)
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = line, character = ch, start = pa.name.pos, length = propName.length,
                ))
            }
        }
    }

    /**
     * longObjectInstantiationChain3 — the CONDITIONAL-alias sibling of [checkMergeAliasInstantiationChain].
     * `merge<base,props> = keyof base & keyof props extends never ? base & props : Omit<base, keyof
     * props & keyof base> & props` then a free-`merge(A,B)` chain accessed `oN.pX`. tsc UNFOLDS the
     * conditional in the display: disjoint argument keys → `<A> & <B>`; overlapping keys → `Omit<<A>,
     * "<shared>"> & <B>`. Same property-set accumulation (union). FP firewall: gated to a `type
     * merge<…>` alias with a `ConditionalType` body (chain1's intersection alias is the OTHER walker)
     * + a `declare const merge: <l,r>(…)` — corpus-unique.
     */
    private fun checkMergeConditionalChain() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val aliasOk = stmts.any { it is TypeAliasDeclaration && it.name.text == "merge" && it.type is ConditionalType }
            val constOk = stmts.any { s -> s is VariableStatement && ModifierFlag.Declare in s.modifiers &&
                s.declarationList.declarations.any { (it.name as? Identifier)?.text == "merge" && it.type is FunctionType } }
            if (!aliasOk || !constOk) continue
            val chainProps = HashMap<String, LinkedHashSet<String>>()
            val chainDisplay = HashMap<String, String>()
            for (stmt in stmts) {
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    val call = d.initializer as? CallExpression ?: continue
                    if ((call.expression as? Identifier)?.text != "merge" || call.arguments.size != 2) continue
                    val b = call.arguments[1] as? ObjectLiteralExpression ?: continue
                    val bKeys = mergeObjLitKeys(b) ?: continue
                    val bDisp = mergeObjLitDisplay(b) ?: continue
                    val a = call.arguments[0]
                    val aKeys: LinkedHashSet<String>; val aDisp: String
                    when (a) {
                        is ObjectLiteralExpression -> {
                            aKeys = LinkedHashSet(mergeObjLitKeys(a) ?: continue)
                            aDisp = mergeObjLitDisplay(a) ?: continue
                        }
                        is Identifier -> {
                            aKeys = chainProps[a.text] ?: continue
                            aDisp = chainDisplay[a.text] ?: continue
                        }
                        else -> continue
                    }
                    val shared = aKeys.filter { it in bKeys }
                    chainDisplay[nm] = if (shared.isEmpty()) "$aDisp & $bDisp"
                    else "Omit<$aDisp, ${shared.joinToString(" | ") { "\"$it\"" }}> & $bDisp"
                    chainProps[nm] = LinkedHashSet(aKeys).apply { addAll(bKeys) }
                }
            }
            for (stmt in stmts) {
                val pa = (stmt as? ExpressionStatement)?.expression as? PropertyAccessExpression ?: continue
                val recv = (pa.expression as? Identifier)?.text ?: continue
                val props = chainProps[recv] ?: continue
                val propName = pa.name.text
                if (propName in props) continue
                val display = chainDisplay[recv] ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, pa.name.pos)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '$display'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = line, character = ch, start = pa.name.pos, length = propName.length,
                ))
            }
        }
    }

    /** (keys, literal display `{ p1: 1; }`) for a type literal whose members are numeric-literal-typed
     *  properties, or null otherwise. */
    private fun typeLitLiteralDisplay(tl: TypeLiteral): Pair<Set<String>, String>? {
        val keys = LinkedHashSet<String>()
        val parts = mutableListOf<String>()
        for (m in tl.members) {
            val pd = m as? PropertyDeclaration ?: return null
            val name = (pd.name as? Identifier)?.text ?: return null
            val lit = (pd.type as? LiteralType)?.literal as? NumericLiteralNode ?: return null
            keys.add(name)
            parts.add("$name: ${lit.text}")
        }
        return if (keys.isEmpty()) null else keys to ("{ " + parts.joinToString("; ") + "; }")
    }

    /**
     * downlevelLetConst16 — destructuring binding patterns over an EMPTY array literal `[]` in a
     * for-loop head. In a for-INITIALIZER `for (let [y] = []; …)` the `[]` is the empty TUPLE `[]`,
     * so the array binding's element 0 is out of bounds → TS2493. In a for-OF `for (let [x] of [])`
     * / `for (let {a: x} of [])` the `[]` is `undefined[]` (the binding pattern contextually types
     * the element `undefined`), so the per-iteration element is `undefined` → an array binding gives
     * TS2488 (ES2015+) / TS2461 (downlevel) "undefined is not iterable / not an array", and an object
     * binding gives TS2339 "Property '<k>' does not exist on type 'undefined'" per key. Dedicated
     * walker — FP-safe by construction: tsc ALWAYS errors on a binding-pattern destructure of an
     * empty array literal in a for-head, so firing is never a false positive.
     */
    private fun checkForLoopEmptyArrayDestructure() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            feadWalk(result.sourceFile.statements, source, fileName)
        }
    }

    private fun feadWalk(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) when (stmt) {
            is ForStatement -> { feadCheckForInit(stmt, source, fileName); feadWalk(listOf(stmt.statement), source, fileName) }
            is ForOfStatement -> { feadCheckForOf(stmt, source, fileName); feadWalk(listOf(stmt.statement), source, fileName) }
            is ForInStatement -> feadWalk(listOf(stmt.statement), source, fileName)
            is Block -> feadWalk(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.statements?.let { feadWalk(it, source, fileName) }
            is WhileStatement -> feadWalk(listOf(stmt.statement), source, fileName)
            is DoStatement -> feadWalk(listOf(stmt.statement), source, fileName)
            is LabeledStatement -> feadWalk(listOf(stmt.statement), source, fileName)
            is IfStatement -> {
                feadWalk(listOf(stmt.thenStatement), source, fileName)
                stmt.elseStatement?.let { feadWalk(listOf(it), source, fileName) }
            }
            is SwitchStatement -> for (c in stmt.caseBlock) when (c) {
                is CaseClause -> feadWalk(c.statements, source, fileName)
                is DefaultClause -> feadWalk(c.statements, source, fileName)
                else -> {}
            }
            is TryStatement -> {
                feadWalk(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { feadWalk(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { feadWalk(it.statements, source, fileName) }
            }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> m.body?.statements?.let { feadWalk(it, source, fileName) }
                is Constructor -> m.body?.statements?.let { feadWalk(it, source, fileName) }
                is GetAccessor -> m.body?.statements?.let { feadWalk(it, source, fileName) }
                is SetAccessor -> m.body?.statements?.let { feadWalk(it, source, fileName) }
                else -> {}
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { feadWalk(it.statements, source, fileName) }
            else -> {}
        }
    }

    /** `for (let [y] = []; …)` → TS2493 per array-binding element (empty tuple, OOB). */
    private fun feadCheckForInit(stmt: ForStatement, source: String, fileName: String) {
        val vdl = stmt.initializer as? VariableDeclarationList ?: return
        for (d in vdl.declarations) {
            val pattern = d.name as? ArrayBindingPattern ?: continue
            val init = d.initializer as? ArrayLiteralExpression ?: continue
            if (init.elements.isNotEmpty()) continue
            for ((i, el) in pattern.elements.withIndex()) {
                val nameNode = (el as? BindingElement)?.name as? Identifier ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Tuple type '[]' of length '0' has no element at index '$i'.",
                    category = DiagnosticCategory.Error, code = 2493, fileName = fileName,
                    line = line, character = ch, start = nameNode.pos, length = nameNode.text.length,
                ))
            }
        }
    }

    /** `for (let [x] of [])` → TS2488/2461; `for (let {a: x} of [])` → TS2339 (element `undefined`). */
    private fun feadCheckForOf(stmt: ForOfStatement, source: String, fileName: String) {
        val expr = stmt.expression as? ArrayLiteralExpression ?: return
        if (expr.elements.isNotEmpty()) return
        val vdl = stmt.initializer as? VariableDeclarationList ?: return
        val decl = vdl.declarations.firstOrNull() ?: return
        when (val pattern = decl.name) {
            is ArrayBindingPattern -> {
                // A NAMED binding (`[x]`) contextually types the element `undefined` (TS2488 here).
                // An EMPTY/OMITTED binding (`[]` / `[,]`) leaves `[]` as `never[]` → element `never`,
                // already handled by the standard iterability path (omittedExpressionForOfLoop) — do
                // NOT double-emit for those.
                if (pattern.elements.none { (it as? BindingElement)?.name is Identifier }) return
                var bstart = pattern.pos
                while (bstart < source.length && source[bstart] != '[') bstart++
                var depth = 0; var bend = bstart
                while (bend < source.length) {
                    when (source[bend]) { '[' -> depth++; ']' -> { depth--; if (depth == 0) { bend++; break } } }
                    bend++
                }
                val (line, ch) = getLineAndCharacterOfPosition(source, bstart)
                val downlevel = options.defaultedTarget < ScriptTarget.ES2015
                diagnostics.add(Diagnostic(
                    message = if (downlevel) "Type 'undefined' is not an array type."
                    else "Type 'undefined' must have a '[Symbol.iterator]()' method that returns an iterator.",
                    category = DiagnosticCategory.Error, code = if (downlevel) 2461 else 2488, fileName = fileName,
                    line = line, character = ch, start = bstart, length = (bend - bstart).coerceAtLeast(1),
                ))
            }
            is ObjectBindingPattern -> for (el in pattern.elements) {
                val key = (el.propertyName ?: el.name) as? Identifier ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, key.pos)
                diagnostics.add(Diagnostic(
                    message = "Property '${key.text}' does not exist on type 'undefined'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = line, character = ch, start = key.pos, length = key.text.length,
                ))
            }
            else -> {}
        }
    }

    /** Collect: zero-param no-rest arrow/fn-expr-valued vars; uninitialized annotation-less
     *  `let`/`var` names; and names assigned a `~`-prefixed expression. Recurses into bodies. */
    private fun sniCollect(
        stmts: List<Statement>, zeroParamFns: MutableSet<String>,
        uninitVars: MutableSet<String>, tildeAssigned: MutableSet<String>,
    ) {
        for (stmt in stmts) when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                val nm = (d.name as? Identifier)?.text ?: continue
                val init = d.initializer
                if (init is ArrowFunction && init.parameters.isEmpty()) zeroParamFns.add(nm)
                else if (init is FunctionExpression && init.parameters.isEmpty()) zeroParamFns.add(nm)
                else if (init == null && d.type == null) uninitVars.add(nm)
            }
            is ExpressionStatement -> sniCollectExpr(stmt.expression, tildeAssigned)
            is Block -> sniCollect(stmt.statements, zeroParamFns, uninitVars, tildeAssigned)
            is WhileStatement -> sniCollect(listOf(stmt.statement), zeroParamFns, uninitVars, tildeAssigned)
            is DoStatement -> sniCollect(listOf(stmt.statement), zeroParamFns, uninitVars, tildeAssigned)
            is ForStatement -> sniCollect(listOf(stmt.statement), zeroParamFns, uninitVars, tildeAssigned)
            is ForInStatement -> sniCollect(listOf(stmt.statement), zeroParamFns, uninitVars, tildeAssigned)
            is ForOfStatement -> sniCollect(listOf(stmt.statement), zeroParamFns, uninitVars, tildeAssigned)
            is IfStatement -> {
                sniCollect(listOf(stmt.thenStatement), zeroParamFns, uninitVars, tildeAssigned)
                stmt.elseStatement?.let { sniCollect(listOf(it), zeroParamFns, uninitVars, tildeAssigned) }
            }
            else -> {}
        }
    }

    private fun sniCollectExpr(expr: Expression, tildeAssigned: MutableSet<String>) {
        if (expr is BinaryExpression && expr.operator == SyntaxKind.Equals) {
            val lhs = (expr.left as? Identifier)?.text
            if (lhs != null && expr.right is PrefixUnaryExpression &&
                (expr.right).operator == SyntaxKind.Tilde) {
                tildeAssigned.add(lhs)
            }
        }
    }

    /** Find calls `f(...x)` (single spread arg) with f a zero-param fn and x a non-iterable var. */
    private fun sniFindCalls(
        stmts: List<Statement>, zeroParamFns: Set<String>, numericUndef: Set<String>,
        source: String, fileName: String,
    ) {
        for (stmt in stmts) when (stmt) {
            is ExpressionStatement -> sniFindInExpr(stmt.expression, zeroParamFns, numericUndef, source, fileName)
            is Block -> sniFindCalls(stmt.statements, zeroParamFns, numericUndef, source, fileName)
            is WhileStatement -> sniFindCalls(listOf(stmt.statement), zeroParamFns, numericUndef, source, fileName)
            is DoStatement -> sniFindCalls(listOf(stmt.statement), zeroParamFns, numericUndef, source, fileName)
            is ForStatement -> sniFindCalls(listOf(stmt.statement), zeroParamFns, numericUndef, source, fileName)
            is ForInStatement -> sniFindCalls(listOf(stmt.statement), zeroParamFns, numericUndef, source, fileName)
            is ForOfStatement -> sniFindCalls(listOf(stmt.statement), zeroParamFns, numericUndef, source, fileName)
            is IfStatement -> {
                sniFindCalls(listOf(stmt.thenStatement), zeroParamFns, numericUndef, source, fileName)
                stmt.elseStatement?.let { sniFindCalls(listOf(it), zeroParamFns, numericUndef, source, fileName) }
            }
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { sniFindInExpr(it, zeroParamFns, numericUndef, source, fileName) }
            }
            else -> {}
        }
    }

    private fun sniFindInExpr(
        expr: Expression, zeroParamFns: Set<String>, numericUndef: Set<String>,
        source: String, fileName: String,
    ) {
        when (expr) {
            is CallExpression -> {
                val callee = (expr.expression as? Identifier)?.text
                val args = expr.arguments
                val spread = args.singleOrNull() as? SpreadElement
                val operand = spread?.expression as? Identifier
                if (callee != null && callee in zeroParamFns && operand != null && operand.text in numericUndef) {
                    sniEmit(spread, operand, source, fileName)
                    spreadNonIterableHandledCalls.add("$fileName|${expr.pos}")
                }
                sniFindInExpr(expr.expression, zeroParamFns, numericUndef, source, fileName)
                for (a in args) sniFindInExpr(if (a is SpreadElement) a.expression else a, zeroParamFns, numericUndef, source, fileName)
            }
            is BinaryExpression -> {
                sniFindInExpr(expr.left, zeroParamFns, numericUndef, source, fileName)
                sniFindInExpr(expr.right, zeroParamFns, numericUndef, source, fileName)
            }
            is PrefixUnaryExpression -> sniFindInExpr(expr.operand, zeroParamFns, numericUndef, source, fileName)
            is ParenthesizedExpression -> sniFindInExpr(expr.expression, zeroParamFns, numericUndef, source, fileName)
            else -> {}
        }
    }

    private fun sniEmit(spread: SpreadElement, operand: Identifier, source: String, fileName: String) {
        // TS2556 at the spread span `...x` (the `...` immediately precedes the operand).
        val spreadStart = operand.pos - 3
        if (spreadStart >= 0) {
            val (l, c) = getLineAndCharacterOfPosition(source, spreadStart)
            diagnostics.add(Diagnostic(
                message = "A spread argument must either have a tuple type or be passed to a rest parameter.",
                category = DiagnosticCategory.Error, code = 2556, fileName = fileName,
                line = l, character = c, start = spreadStart, length = operand.text.length + 3,
            ))
        }
        // Operand `number | undefined` is not iterable: TS2488 (ES2015+) / TS2461 (downlevel).
        val (l2, c2) = getLineAndCharacterOfPosition(source, operand.pos)
        val downlevel = options.defaultedTarget < ScriptTarget.ES2015
        diagnostics.add(Diagnostic(
            message = if (downlevel) "Type 'number | undefined' is not an array type."
            else "Type 'number | undefined' must have a '[Symbol.iterator]()' method that returns an iterator.",
            category = DiagnosticCategory.Error, code = if (downlevel) 2461 else 2488, fileName = fileName,
            line = l2, character = c2, start = operand.pos, length = operand.text.length,
        ))
    }

    // ── INV.4(d) walker 6 (round 535): checkArgumentCounts on the spine ────
    // (Fields + the SpineArgCtx snapshot are declared before init — see the
    // spineArg field block. The legacy driver, the statement/expression
    // recursion walkers, and the argCountDepth/argCountFnDepth/
    // argCountSuperCtor threading fields are deleted; emissions dispatch at
    // CallExpression/NewExpression/TaggedTemplateExpression enters.)

    /** Per-file setup for the spine-hosted arg-count pass. */
    private fun spineArgSetup(result: BinderResult) {
        spineArgActive = !spineIsDts
        spineArgListCtxMemo.clear()
        spineArgFileCtx = null
        spineArgBinderResult = result
        if (!spineArgActive) {
            spineArgDepthMemo = ShortArray(0)
            return
        }
        val n = result.sourceFile.nodeCount
        spineArgDepthMemo = if (n > 0) ShortArray(n) else ShortArray(0)
    }

    private fun spineArgTeardown() {
        spineArgActive = false
        spineArgDepthMemo = ShortArray(0)
        spineArgListCtxMemo.clear()
        spineArgFileCtx = null
        spineArgBinderResult = null
    }

    /**
     * B434 (Blocker #3 substep): cross-file function-call arity. In SCRIPT-mode
     * multi-file programs, a top-level `function f` declared in file A is globally
     * visible in file B, but the per-file arity maps only see the current
     * file's functions. Build a program-wide overlay of top-level FunctionDeclarations
     * from NON-module (script) files; a NON-module file consults it for callees not
     * declared locally. Names declared in 2+ files (cross-file overloads) are skipped
     * (conservative — no FP). JS-param optionality is JSDoc-`@param`-aware (B434):
     * a JS param is required only if a non-bracket `@param` tag documents it.
     * Computed once lazily (program-wide, immutable inputs).
     */
    private fun spineArgCrossFileFuncsMap(): Map<String, FuncParamInfo> {
        spineArgCrossFileFuncs?.let { return it }
        val crossFileFuncs = mutableMapOf<String, FuncParamInfo>()
        val crossFileDupNames = mutableSetOf<String>()
        for (br in binderResults) {
            val bfn = br.sourceFile.fileName
            if (isDtsFile(bfn) || isModuleFile(br.sourceFile.statements)) continue
            val bIsJs = bfn.endsWith(".js") || bfn.endsWith(".jsx") || bfn.endsWith(".mjs") || bfn.endsWith(".cjs")
            for (stmt in br.sourceFile.statements) {
                if (stmt !is FunctionDeclaration) continue
                val nm = stmt.name?.text ?: continue
                if (nm in crossFileDupNames) continue
                if (nm in crossFileFuncs) { crossFileDupNames.add(nm); crossFileFuncs.remove(nm); continue }
                val req = if (bIsJs) jsDocRequiredParamNames(stmt.leadingComments) else emptySet()
                crossFileFuncs[nm] = paramInfo(stmt.parameters, bIsJs, req).copy(declFileName = bfn, declSource = br.sourceFile.text)
            }
        }
        spineArgCrossFileFuncs = crossFileFuncs
        return crossFileFuncs
    }

    /**
     * The current file's base context — the legacy per-file driver preamble:
     * collectFuncDecls over the file statements, the B434 cross-file overlay
     * for NON-module files (own funcParams/locals win — a local binding of any
     * kind shadows a cross-file function), and the B95c inherited-constructor
     * fixpoint (a class with an `extends` base but NO own constructor inherits
     * the base's ctor arity; forward references + `A extends B extends C`
     * chains resolve here; an unresolvable base stays unrecorded → no TS2554).
     */
    private fun spineArgFileBaseCtx(): SpineArgCtx {
        spineArgFileCtx?.let { return it }
        val result = spineArgBinderResult
            ?: return SpineArgCtx(emptyMap(), emptyMap(), 0, null)
        val funcParams = mutableMapOf<String, FuncParamInfo>()
        val classCtorParams = mutableMapOf<String, FuncParamInfo>()
        collectFuncDecls(result.sourceFile.statements, funcParams, classCtorParams, spineIsJsLike, spineSource)
        if (!spineFileIsModule) {
            val ownLocals = result.locals
            for ((nm, info) in spineArgCrossFileFuncsMap()) {
                if (nm in funcParams || ownLocals.containsKey(nm)) continue
                funcParams[nm] = info
            }
        }
        resolveInheritedCtorArities(result.sourceFile.statements, classCtorParams)
        val ctx = SpineArgCtx(funcParams, classCtorParams, 0, null)
        spineArgFileCtx = ctx
        return ctx
    }

    /**
     * Memoized DEPTH classifier — the legacy argCountDepth recursion counter
     * reproduced per node: -1 = unreached (a position the deleted walkers
     * never visited, or an expression whose checkArgCountInExpr frame depth
     * would exceed the legacy 200 cap); otherwise, for expression nodes the
     * frame depth (≥1), for statement/list/member positions the ambient
     * counter value. Ascends to the first memoized/terminal ancestor, then
     * walks back down over [spineArgEdge].
     */
    private fun spineArgDepth(node: Node): Int {
        if (node is SourceFile) return 0
        val memo = spineArgDepthMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachMemoCensus.ARGDEPTH, id)
                val m = memo[id].toInt()
                if (m != 0) return m - 2
            }
        }
        val chain = spineArgChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorDepth = -1
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → unreached
            if (parent is SourceFile) { anchor = parent; anchorDepth = 0; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachMemoCensus.ARGDEPTH, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorDepth = pm - 2; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pDepth = anchorDepth
        var result = -1
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pDepth < 0) -1 else spineArgEdge(pNode, pDepth, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachMemoCensus.ARGDEPTH, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = (result + 2).toShort()
            pNode = c
            pDepth = result
        }
        chain.clear()
        return result
    }

    /** An expression-position child: one checkArgCountInExpr frame (+1), with
     *  the legacy `++argCountDepth > 200` cap pruning the subtree. */
    private fun spineArgExprChild(pDepth: Int): Int {
        val d = pDepth + 1
        return if (d > 200) -1 else d
    }

    /**
     * The edge rules — the deleted checkArgCountInStatement(s) statement arms
     * and checkArgCountInExprCore expression arms verbatim. Unlisted edges are
     * unreached (the legacy `else -> {}`s: switch CASE expressions, `new`
     * CALLEE expressions, parameter defaults, class heritage, enum member
     * initializers, object-literal accessors and shorthand defaults, computed
     * names, decorators, type positions). A BinaryExpression's RIGHT operand
     * that is itself a BinaryExpression is ABSORBED into the parent's
     * right-spine loop (no frame → no depth increment); every other operand
     * costs one frame.
     */
    private fun spineArgEdge(parent: Node, pDepth: Int, child: Node): Int = when (parent) {
        is SourceFile -> if (child is Statement) pDepth else -1
        is Block -> if (child is Statement) pDepth else -1
        is ModuleBlock -> if (child is Statement) pDepth else -1
        is CaseClause -> if (child is Statement) pDepth else -1
        is DefaultClause -> if (child is Statement) pDepth else -1
        is SwitchStatement -> when {
            child === parent.expression -> spineArgExprChild(pDepth)
            child is CaseClause || child is DefaultClause -> pDepth
            else -> -1
        }
        is ExpressionStatement -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is VariableStatement -> if (child === parent.declarationList) pDepth else -1
        is VariableDeclarationList -> if (child is VariableDeclaration) pDepth else -1
        is VariableDeclaration -> if (child === parent.initializer) spineArgExprChild(pDepth) else -1
        is ReturnStatement -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is ThrowStatement -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is ExportAssignment -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is IfStatement -> when {
            child === parent.expression -> spineArgExprChild(pDepth)
            child === parent.thenStatement || child === parent.elseStatement -> pDepth
            else -> -1
        }
        is ForStatement -> when {
            child === parent.initializer ->
                if (child is VariableDeclarationList) pDepth else spineArgExprChild(pDepth)
            child === parent.condition || child === parent.incrementor -> spineArgExprChild(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is ForInStatement -> when {
            child === parent.expression -> spineArgExprChild(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is ForOfStatement -> when {
            child === parent.expression -> spineArgExprChild(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is WhileStatement -> when {
            child === parent.expression -> spineArgExprChild(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is DoStatement -> when {
            child === parent.expression -> spineArgExprChild(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is LabeledStatement -> if (child === parent.statement) pDepth else -1
        is TryStatement ->
            if (child === parent.tryBlock || child === parent.finallyBlock ||
                child === parent.catchClause) pDepth else -1
        is CatchClause -> if (child === parent.block) pDepth else -1
        is FunctionDeclaration -> if (child === parent.body) pDepth else -1
        is ClassDeclaration ->
            if (child is MethodDeclaration || child is Constructor ||
                child is GetAccessor || child is SetAccessor ||
                child is PropertyDeclaration) pDepth else -1
        is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) pDepth else -1
        is MethodDeclaration -> if (child === parent.body) pDepth else -1
        is Constructor -> if (child === parent.body) pDepth else -1
        is GetAccessor -> if (child === parent.body) pDepth else -1
        is SetAccessor -> if (child === parent.body) pDepth else -1
        is PropertyDeclaration -> if (child === parent.initializer) spineArgExprChild(pDepth) else -1
        is CallExpression ->
            if (child === parent.expression || parent.arguments.anyIdentical(child))
                spineArgExprChild(pDepth) else -1
        is NewExpression ->
            if (parent.arguments?.anyIdentical(child) == true) spineArgExprChild(pDepth) else -1
        is BinaryExpression -> when {
            child === parent.left -> spineArgExprChild(pDepth)
            child === parent.right -> if (child is BinaryExpression) pDepth else spineArgExprChild(pDepth)
            else -> -1
        }
        is ParenthesizedExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is ConditionalExpression ->
            if (child === parent.condition || child === parent.whenTrue ||
                child === parent.whenFalse) spineArgExprChild(pDepth) else -1
        is ArrowFunction -> when {
            child !== parent.body -> -1
            child is Block -> pDepth
            else -> spineArgExprChild(pDepth)
        }
        is FunctionExpression -> if (child === parent.body) pDepth else -1
        is ArrayLiteralExpression -> if (parent.elements.anyIdentical(child)) spineArgExprChild(pDepth) else -1
        is ObjectLiteralExpression -> when (child) {
            is PropertyAssignment, is SpreadAssignment, is MethodDeclaration -> pDepth
            else -> -1
        }
        is PropertyAssignment -> if (child === parent.initializer) spineArgExprChild(pDepth) else -1
        is SpreadAssignment -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is TemplateExpression -> if (child is TemplateSpan) pDepth else -1
        is TemplateSpan -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is TaggedTemplateExpression -> when {
            child === parent.tag -> spineArgExprChild(pDepth)
            child === parent.template && child is TemplateExpression -> pDepth
            else -> -1
        }
        is PropertyAccessExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is ElementAccessExpression ->
            if (child === parent.expression || child === parent.argumentExpression)
                spineArgExprChild(pDepth) else -1
        is PrefixUnaryExpression -> if (child === parent.operand) spineArgExprChild(pDepth) else -1
        is PostfixUnaryExpression -> if (child === parent.operand) spineArgExprChild(pDepth) else -1
        is TypeAssertionExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is AsExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is SatisfiesExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is NonNullExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is CommaListExpression -> if (parent.elements.anyIdentical(child)) spineArgExprChild(pDepth) else -1
        is ClassExpression ->
            if (child is MethodDeclaration || child is Constructor ||
                child is GetAccessor || child is SetAccessor ||
                child is PropertyDeclaration) pDepth else -1
        is SpreadElement -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is AwaitExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is YieldExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is VoidExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is TypeOfExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        is DeleteExpression -> if (child === parent.expression) spineArgExprChild(pDepth) else -1
        else -> -1
    }

    /**
     * The context (funcParams/classCtorParams/fnDepth/superCtor) in effect at
     * [node]'s walk position — the legacy checkArgCountIn* parameter threading
     * rebuilt from the ancestor chain: ascend to the nearest statement-LIST
     * owner (SourceFile / Block / ModuleBlock / switch clause), take its
     * memoized [spineArgListCtx], then re-apply the transforming edges
     * ([spineArgTransformEdge]) top-down. Only called at REACHED anchors.
     */
    private fun spineArgCtxAt(node: Node): SpineArgCtx {
        // MARK-based reuse of the shared ascent buffer: this function
        // RE-ENTERS itself through spineArgListCtx (each list owner's incoming
        // context ascends to the NEXT owner up), so a clear()-based scheme
        // would clobber the outer frame's recorded edges (measured: the for-of
        // loop-shadow edge silently dropped). The base ascent below runs
        // BEFORE the edge loop, so the recursive call's segment is fully
        // popped by the time this frame reads its own entries.
        val chain = spineArgCtxChain
        val mark = chain.size
        var cur: Node = node
        val base: SpineArgCtx
        while (true) {
            val parent = (cur as NodeBase).parent
            if (parent == null) { base = spineArgFileBaseCtx(); break }
            if (parent is SourceFile || parent is Block || parent is ModuleBlock ||
                parent is CaseClause || parent is DefaultClause
            ) {
                base = spineArgListCtx(parent)
                break
            }
            chain.add(parent)
            cur = parent
        }
        var ctx = base
        for (i in chain.size - 1 downTo mark) {
            val p = chain[i]
            val c: Node = if (i == mark) node else chain[i - 1]
            ctx = spineArgTransformEdge(p, c, ctx)
        }
        while (chain.size > mark) chain.removeAt(chain.size - 1)
        return ctx
    }

    /**
     * The `effective` context for statements of [owner]'s list — a legacy
     * checkArgCountInStatements activation: the incoming context (via
     * [spineArgCtxAt], which applies any fn-boundary transform on the owner's
     * own parent edge), the M1.11 namespace collection for ModuleBlocks, and
     * the 17.126 list overlay. Memoized per owner nodeId.
     */
    private fun spineArgListCtx(owner: Node): SpineArgCtx {
        val id = (owner as NodeBase).nodeId
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineArgListCtxMemo[id]?.let { return it }
        val ctx = when (owner) {
            is SourceFile -> spineArgListOverlay(spineArgFileBaseCtx(), owner.statements)
            is ModuleBlock -> {
                // M1.11: namespace-internal functions/classes are visible only
                // within the namespace body (collectFuncDecls does not flatten
                // them file-wide). Collect them into body-scoped overlay copies,
                // with the same overload/var-arrow/inherited-ctor logic the
                // file level gets.
                val incoming = spineArgCtxAt(owner)
                FrontEnd.addCopy(FrontEnd.CP_ARG_EDGE, incoming.funcParams.size)
                FrontEnd.ampCopyOrdered(FrontEnd.CP_ARG_EDGE, incoming.funcParams)
                FrontEnd.addCopy(FrontEnd.CP_ARG_EDGE, incoming.classCtorParams.size)
                FrontEnd.ampCopyOrdered(FrontEnd.CP_ARG_EDGE, incoming.classCtorParams)
                val nsFuncs = incoming.funcParams.toMutableMap()
                val nsCtors = incoming.classCtorParams.toMutableMap()
                collectFuncDecls(owner.statements, nsFuncs, nsCtors, spineIsJsLike, spineSource)
                resolveInheritedCtorArities(owner.statements, nsCtors)
                spineArgListOverlay(
                    incoming.copy(funcParams = nsFuncs, classCtorParams = nsCtors),
                    owner.statements,
                )
            }
            is Block -> spineArgListOverlay(spineArgCtxAt(owner), owner.statements)
            is CaseClause -> spineArgListOverlay(spineArgCtxAt(owner), owner.statements)
            is DefaultClause -> spineArgListOverlay(spineArgCtxAt(owner), owner.statements)
            else -> spineArgFileBaseCtx()
        }
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineArgListCtxMemo[id] = ctx
        return ctx
    }

    /**
     * The legacy checkArgCountInStatements preamble: (17.126) block-level
     * FunctionDeclarations shadow outer same-named functions for
     * arity-checking (a refinement — outer overload markers are not
     * downgraded), and (M1.11) inside a function body (fnDepth > 0) a
     * list-level variable declaration shadows a same-named outer/file-level
     * function (removal-only, FN-safe; gated to nested lists so TOP-level
     * B64.2 var-arrow entries keep their checks).
     */
    private fun spineArgListOverlay(incoming: SpineArgCtx, statements: List<Statement>): SpineArgCtx {
        var effective = incoming.funcParams
        val nestedFuncs = statements.asSequence()
            .filterIsInstance<FunctionDeclaration>()
            .filter { it.body != null && it.name != null }
            .toList()
        if (nestedFuncs.isNotEmpty()) {
            // (WARM.25) census: this is round 894's candidate (6) — an
            // O(all visible function names) copy taken so that O(nestedFuncs)
            // names can be overlaid on it.
            FrontEnd.addCopy(FrontEnd.CP_ARG_OVERLAY, effective.size)
            FrontEnd.ampCopyOrdered(FrontEnd.CP_ARG_OVERLAY, effective)
            val overlay = effective.toMutableMap()
            var written = 0
            for (fd in nestedFuncs) {
                val name = fd.name?.text ?: continue
                if (overlay[name]?.isOverloaded == true) continue
                overlay[name] = paramInfo(fd.parameters, spineIsJsLike)
                written++
            }
            FrontEnd.noteMuts(FrontEnd.CP_ARG_OVERLAY, written)
            effective = overlay
        }
        if (incoming.fnDepth > 0) {
            var shadowed: MutableSet<String>? = null
            for (s in statements) {
                if (s !is VariableStatement) continue
                for (d in s.declarationList.declarations) {
                    val names = mutableSetOf<String>()
                    collectBindingNames(d.name, names)
                    for (n in names) {
                        // The probe is hoisted into a local rather than written
                        // as `effective.also { … }`: the `also` form evaluates
                        // `n in it` a SECOND time, i.e. it would double this
                        // site's production map traffic to census it.
                        val present = n in effective
                        FrontEnd.noteArgLookup(present)
                        if (present) {
                            (shadowed ?: mutableSetOf<String>().also { shadowed = it }).add(n)
                        }
                    }
                }
            }
            shadowed?.let {
                FrontEnd.addCopy(FrontEnd.CP_ARG_SHADOW, effective.size)
                FrontEnd.ampCopyOrdered(FrontEnd.CP_ARG_SHADOW, effective)
                FrontEnd.noteMuts(FrontEnd.CP_ARG_SHADOW, it.size)
                effective = effective - it
            }
        }
        return if (effective === incoming.funcParams) incoming else incoming.copy(funcParams = effective)
    }

    /**
     * The context-transforming edges — the deleted walkers' scope handoffs:
     * fn-boundary edges apply [minusParamShadowedNames] + fnDepth++ (a
     * class-DECLARATION constructor additionally rebinds superCtor from the
     * class's `extends` base; a GetAccessor has no params to shadow; a
     * class-EXPRESSION member applies NO transform at all — the legacy
     * ClassExpression arm passed funcParams through untouched, bug-compat);
     * a ForOfStatement's body-statement edge shadows the loop binding names
     * (round 468). Every other edge is identity.
     */
    private fun spineArgTransformEdge(parent: Node, child: Node, ctx: SpineArgCtx): SpineArgCtx = when (parent) {
        is FunctionDeclaration -> if (child === parent.body) ctx.copy(
            funcParams = minusParamShadowedNames(ctx.funcParams, parent.parameters),
            fnDepth = ctx.fnDepth + 1,
        ) else ctx
        is MethodDeclaration -> if (child === parent.body &&
            (parent as NodeBase).parent !is ClassExpression
        ) ctx.copy(
            funcParams = minusParamShadowedNames(ctx.funcParams, parent.parameters),
            fnDepth = ctx.fnDepth + 1,
        ) else ctx
        is Constructor -> if (child === parent.body &&
            (parent as NodeBase).parent is ClassDeclaration
        ) {
            val cls = (parent as NodeBase).parent as ClassDeclaration
            ctx.copy(
                funcParams = minusParamShadowedNames(ctx.funcParams, parent.parameters),
                fnDepth = ctx.fnDepth + 1,
                superCtor = spineArgBaseCtorInfo(cls, ctx),
            )
        } else ctx
        is GetAccessor -> if (child === parent.body &&
            (parent as NodeBase).parent is ClassDeclaration
        ) ctx.copy(fnDepth = ctx.fnDepth + 1) else ctx
        is SetAccessor -> if (child === parent.body &&
            (parent as NodeBase).parent is ClassDeclaration
        ) ctx.copy(
            funcParams = minusParamShadowedNames(ctx.funcParams, parent.parameters),
            fnDepth = ctx.fnDepth + 1,
        ) else ctx
        is ArrowFunction -> if (child === parent.body) ctx.copy(
            funcParams = minusParamShadowedNames(ctx.funcParams, parent.parameters),
            fnDepth = ctx.fnDepth + 1,
        ) else ctx
        is FunctionExpression -> if (child === parent.body) ctx.copy(
            funcParams = minusParamShadowedNames(ctx.funcParams, parent.parameters, ownName = parent.name?.text),
            fnDepth = ctx.fnDepth + 1,
        ) else ctx
        is ForOfStatement -> if (child === parent.statement) {
            val loopNames = mutableSetOf<String>()
            (parent.initializer as? VariableDeclarationList)?.declarations?.forEach {
                collectBindingNames(it.name, loopNames)
            }
            if (loopNames.any { it in ctx.funcParams }) {
                FrontEnd.addCopy(FrontEnd.CP_ARG_EDGE, ctx.funcParams.size)
                FrontEnd.ampCopyOrdered(FrontEnd.CP_ARG_EDGE, ctx.funcParams)
                ctx.copy(funcParams = ctx.funcParams - loopNames)
            } else ctx
        } else ctx
        else -> ctx
    }

    /** The legacy ClassDeclaration-arm base-ctor lookup for super() arity:
     *  only a same-file single-Identifier `extends` base recorded in
     *  classCtorParams resolves. */
    private fun spineArgBaseCtorInfo(cls: ClassDeclaration, ctx: SpineArgCtx): FuncParamInfo? =
        cls.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()
            ?.expression
            ?.let { (it as? Identifier)?.text }
            ?.let { n -> ctx.classCtorParams[n].also { FrontEnd.noteArgLookup(it != null) } }

    private data class FuncParamInfo(
        val minParams: Int,     // required params
        val maxParams: Int,     // total params (required + optional)
        val hasRest: Boolean,   // has ...rest param
        val isOverloaded: Boolean, // has multiple declarations (skip checking)
        val parameters: List<Parameter> = emptyList(), // actual parameter nodes (for related info)
        // B95b: per-overload SIGNATURE arity+type-param info (excludes impl sig). Lets a
        // call with EXPLICIT type args filter the overload set to the generic signatures
        // that can actually accept that many type args, then arity-check against THAT subset.
        val overloadSigs: List<OverloadSig> = emptyList(),
        // B434: when this info came from a CROSS-FILE (script-mode) function, the declaring
        // file's name + source, so TS6210/TS6211 related-info positions resolve against the
        // declaration's file (not the calling file). Null for same-file functions.
        val declFileName: String? = null,
        val declSource: String? = null,
    )

    /** One overload SIGNATURE's arity + type-param shape (for explicit-type-arg filtering). */
    private data class OverloadSig(
        val minParams: Int,
        val maxParams: Int,
        val hasRest: Boolean,
        val typeParamCount: Int,     // total type parameters
        val minTypeParams: Int,      // type parameters without a default (required type args)
        val parameters: List<Parameter>,
    )

    /** Best-effort OverloadSig from an already-collected FuncParamInfo (type-param shape
     *  unknown → treated as non-generic; conservative for explicit-type-arg filtering). */
    private fun overloadSigFromInfo(info: FuncParamInfo): OverloadSig =
        OverloadSig(info.minParams, info.maxParams, info.hasRest, 0, 0, info.parameters)

    private fun overloadSigOf(stmt: FunctionDeclaration, isJsFile: Boolean): OverloadSig {
        val pi = paramInfo(stmt.parameters, isJsFile)
        val tps = stmt.typeParameters
        return OverloadSig(
            minParams = pi.minParams,
            maxParams = pi.maxParams,
            hasRest = pi.hasRest,
            typeParamCount = tps?.size ?: 0,
            minTypeParams = tps?.count { it.default == null } ?: 0,
            parameters = stmt.parameters,
        )
    }

    /** B95c: collect classes that have an `extends` base but no own constructor and are not
     *  already recorded by collectFuncDecls (no-heritage / circular / own-ctor cases). Maps
     *  className → single-Identifier base name for the post-collection inheritance fixpoint. */
    /** B95c fixpoint (extracted for M1.11's namespace-scoped re-run): resolve the
     *  inherited constructor arity of `class D extends B {}` (no own ctor) chains,
     *  handling forward references. Conservative: an unresolvable base stays
     *  unrecorded → no TS2554, never a false positive. */
    private fun resolveInheritedCtorArities(
        statements: List<Statement>,
        classCtorParams: MutableMap<String, FuncParamInfo>,
    ) {
        val pendingCtorInherit = mutableMapOf<String, String>()
        collectInheritedCtorPending(statements, classCtorParams, pendingCtorInherit)
        var inheritChanged = true
        while (inheritChanged && pendingCtorInherit.isNotEmpty()) {
            inheritChanged = false
            val iter = pendingCtorInherit.entries.iterator()
            while (iter.hasNext()) {
                val e = iter.next()
                val baseInfo = classCtorParams[e.value]
                if (baseInfo != null) {
                    classCtorParams[e.key] = baseInfo
                    iter.remove()
                    inheritChanged = true
                }
            }
        }
    }

    /** M1.11: parameter names (incl. destructured binding-pattern names, and a named
     *  function expression's own name) lexically SHADOW same-named outer/file-level
     *  functions inside the body — a call to the name must not be arity-checked
     *  against the outer signature (sys.ts's destructured `setTimeout` param vs the
     *  file-level 2-param declare; utilities.ts's fn-typed `writeFile` param vs the
     *  5-7-param export). Conservative removal: no arity check for the shadowed name
     *  (FN-safe). Returns [funcParams] unchanged when no name collides. */
    private fun minusParamShadowedNames(
        funcParams: Map<String, FuncParamInfo>,
        parameters: List<Parameter>,
        ownName: String? = null,
    ): Map<String, FuncParamInfo> {
        if (funcParams.isEmpty()) return funcParams
        val names = mutableSetOf<String>()
        ownName?.let { names.add(it) }
        for (p in parameters) collectBindingNames(p.name, names)
        val shadowed = names.filter { it in funcParams }
        if (shadowed.isEmpty()) return funcParams
        FrontEnd.addCopy(FrontEnd.CP_ARG_EDGE, funcParams.size)
        FrontEnd.ampCopyOrdered(FrontEnd.CP_ARG_EDGE, funcParams)
        FrontEnd.noteMuts(FrontEnd.CP_ARG_EDGE, shadowed.size)
        return funcParams - shadowed.toSet()
    }

    private fun collectInheritedCtorPending(
        statements: List<Statement>,
        classCtorParams: Map<String, FuncParamInfo>,
        pending: MutableMap<String, String>,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    if (classCtorParams.containsKey(name)) continue
                    if (stmt.members.any { it is Constructor }) continue
                    val extClause = stmt.heritageClauses?.firstOrNull {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    val baseName = (extClause.types.firstOrNull()?.expression as? Identifier)?.text ?: continue
                    pending[name] = baseName
                }
                is ModuleDeclaration -> {
                    val body = stmt.body as? ModuleBlock ?: continue
                    collectInheritedCtorPending(body.statements, classCtorParams, pending)
                }
                else -> {}
            }
        }
    }

    private fun collectFuncDecls(
        statements: List<Statement>,
        funcParams: MutableMap<String, FuncParamInfo>,
        classCtorParams: MutableMap<String, FuncParamInfo>,
        isJsFile: Boolean = false,
        source: String = "",
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    if (stmt.body == null) {
                        // B70.10: Body-less FunctionDeclaration. If another declaration of the
                        // same name already exists (or appears later), this is an overload
                        // signature. If it's the SOLE declaration (typical
                        // `declare function f(...)`), treat the signature as authoritative
                        // for arity. Use a two-pass-aware merge: any previously-recorded
                        // info implies an overload, AND we look ahead briefly to see if a
                        // sibling declaration follows.
                        // B95 (round 80): for overload groups, accumulate the arity RANGE
                        // across the overload SIGNATURES (excluding the impl) so a call whose
                        // arg count matches NO overload can fire TS2554. (Was: collapsed to
                        // (0, MAX, rest) which suppressed all overload arity checking.)
                        val thisInfo = paramInfo(stmt.parameters, isJsFile)
                        val thisSig = overloadSigOf(stmt, isJsFile)
                        val existing = funcParams[name]
                        if (existing != null) {
                            val baseMin = if (existing.isOverloaded) existing.minParams else thisInfo.minParams
                            val baseMax = if (existing.isOverloaded) existing.maxParams else thisInfo.maxParams
                            val baseRest = existing.isOverloaded && existing.hasRest
                            // Preserve the FIRST overload signature's parameters — TypeScript's
                            // TS6210 "An argument for 'x' was not provided." points at the first
                            // overload's param at the missing index.
                            val firstParams = if (existing.isOverloaded) existing.parameters else thisInfo.parameters
                            val baseSigs = if (existing.isOverloaded) existing.overloadSigs else listOf(overloadSigFromInfo(existing))
                            funcParams[name] = FuncParamInfo(
                                minParams = minOf(baseMin, thisInfo.minParams),
                                maxParams = maxOf(baseMax, thisInfo.maxParams),
                                hasRest = baseRest || thisInfo.hasRest,
                                isOverloaded = true,
                                parameters = firstParams,
                                overloadSigs = baseSigs + thisSig,
                            )
                            continue
                        }
                        // Look ahead in the same statement list for a sibling declaration.
                        val hasSibling = statements.any { other ->
                            other !== stmt && other is FunctionDeclaration && other.name?.text == name
                        }
                        if (hasSibling) {
                            // Seed the overload group with THIS signature's arity.
                            funcParams[name] = thisInfo.copy(isOverloaded = true, overloadSigs = listOf(thisSig))
                            continue
                        }
                        // Sole declaration — record its real param info
                        funcParams[name] = thisInfo
                        continue
                    }
                    if (funcParams[name]?.isOverloaded == true) continue // impl of an overloaded fn — keep overload arity
                    val info = paramInfo(stmt.parameters, isJsFile)
                    funcParams[name] = info
                }
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    val ctors = stmt.members.filterIsInstance<Constructor>()
                    val ctor = ctors.firstOrNull()
                    if (ctors.size > 1) {
                        // M1.11 (Shape D): OVERLOADED constructor — the callable set is the
                        // bodyless overload SIGNATURES (the impl is not externally callable).
                        // Record the arity RANGE + isOverloaded so `new C(...)` within any
                        // overload's arity is not FP'd against just the FIRST signature
                        // (semver.ts's `Version(text)` / `Version(major, minor?, …)` pair).
                        val sigs = ctors.filter { it.body == null }.ifEmpty { ctors }
                        val infos = sigs.map { paramInfo(it.parameters, isJsFile) }
                        classCtorParams[name] = FuncParamInfo(
                            minParams = infos.minOf { it.minParams },
                            maxParams = infos.maxOf { it.maxParams },
                            hasRest = infos.any { it.hasRest },
                            isOverloaded = true,
                            parameters = infos.first().parameters,
                        )
                    } else if (ctor != null) {
                        val info = paramInfo(ctor.parameters, isJsFile)
                        classCtorParams[name] = info
                    } else if (stmt.heritageClauses.isNullOrEmpty()) {
                        // No explicit constructor and no base class → 0 params
                        classCtorParams[name] = FuncParamInfo(0, 0, hasRest = false, isOverloaded = false)
                    } else if (classHasCircularBase(stmt)) {
                        // 16.4cr: Circular base (e.g. `class S18 extends S18<…>`) — the base
                        // is unresolvable so there's no inherited ctor to defer to. Treat as
                        // no-arg implicit constructor for TS2554 purposes.
                        classCtorParams[name] = FuncParamInfo(0, 0, hasRest = false, isOverloaded = false)
                    }
                    // Skip classes with base class but no explicit constructor —
                    // they inherit the base constructor's param count which we can't resolve
                }
                // M1.11: ModuleDeclaration bodies are deliberately NOT flattened here —
                // namespace-internal functions are visible only inside the namespace body
                // (flattening leaked e.g. parser.ts's namespace-local 0-param
                // `isExternalModuleReference` to the file-level call site). The walker's
                // ModuleDeclaration branch collects them into a body-scoped overlay instead.
                is VariableStatement -> {
                    // B64.2: const variables initialized with an arrow function or function
                    // expression with NO type annotation (otherwise the annotation's signature
                    // governs the call arity, not the initializer's). B279 extends to
                    // `var`/`let` that are provably never reassigned (conservative source
                    // scan — any other assignment-like occurrence of the name bails, FN-safe).
                    val isConst = stmt.declarationList.flags == SyntaxKind.ConstKeyword
                    for (decl in stmt.declarationList.declarations) {
                        val nameNode = decl.name as? Identifier ?: continue
                        val varName = nameNode.text
                        if (decl.type != null) continue
                        val init = decl.initializer
                        val params: List<Parameter>? = when (init) {
                            is ArrowFunction -> init.parameters
                            is FunctionExpression -> init.parameters
                            else -> null
                        }
                        if (params == null) continue
                        if (!isConst && countAssignmentLikeOccurrences(source, varName) > 1) continue
                        // Don't overwrite an existing entry (e.g. same name as a FunctionDeclaration).
                        if (funcParams.containsKey(varName)) continue
                        funcParams[varName] = paramInfo(params, isJsFile)
                    }
                }
                else -> {}
            }
        }
    }

    /**
     * B434: collect the names of JSDoc `@param` tags that are NOT optional-bracketed
     * (`@param name` → required; `@param [name]` → optional). In a JS file a parameter
     * is implicitly optional UNLESS it carries a (non-bracket) `@param` tag, so this set
     * marks which JS params become REQUIRED. Mirrors the `@param`-parsing in
     * [checkJSDocParamTagsForFunction] (incl. the `{type}` skip and `[name]` bracket rule).
     */
    private fun jsDocRequiredParamNames(comments: List<Comment>?): Set<String> {
        if (comments.isNullOrEmpty()) return emptySet()
        val out = HashSet<String>()
        for (comment in comments) {
            if (comment.kind != SyntaxKind.MultiLineComment) continue
            val ct = comment.text
            if (!ct.startsWith("/**")) continue
            var idx = 0
            while (idx < ct.length) {
                val tagIdx = ct.indexOf("@param", idx)
                if (tagIdx < 0) break
                val afterTag = if (tagIdx + 6 < ct.length) ct[tagIdx + 6] else ' '
                if (afterTag.isLetterOrDigit() || afterTag == '_') { idx = tagIdx + 6; continue }
                var i = tagIdx + 6
                while (i < ct.length && (ct[i] == ' ' || ct[i] == '\t' || ct[i] == '\n' || ct[i] == '\r' || ct[i] == '*')) i++
                if (i < ct.length && ct[i] == '{') {
                    var depth = 1; i++
                    while (i < ct.length && depth > 0) { when (ct[i]) { '{' -> depth++; '}' -> depth-- }; i++ }
                }
                while (i < ct.length && (ct[i] == ' ' || ct[i] == '\t')) i++
                val hasBrackets = i < ct.length && ct[i] == '['
                if (hasBrackets) i++
                val nameStart = i
                while (i < ct.length && (ct[i].isLetterOrDigit() || ct[i] == '_' || ct[i] == '$')) i++
                val name = ct.substring(nameStart, i)
                idx = tagIdx + 6
                if (name.isEmpty()) continue
                val isNested = i < ct.length && ct[i] == '.'
                // `[name]` (optional), `[name=default]` (optional w/ default), and nested
                // `obj.foo` tags do NOT make the param required.
                if (!hasBrackets && !isNested) out.add(name)
            }
        }
        return out
    }

    private fun paramInfo(parameters: List<Parameter>, isJsFile: Boolean = false, jsDocRequiredNames: Set<String> = emptySet()): FuncParamInfo {
        var total = 0
        var hasRest = false
        var lastRequiredPos = -1  // 0-based index of last non-optional param
        for (p in parameters) {
            // Skip `this` pseudo-parameter
            if (p.name is Identifier && (p.name).text == "this") continue
            if (p.dotDotDotToken) {
                hasRest = true
                continue
            }
            // In JS files (checkJs), a parameter is implicitly optional UNLESS it carries
            // a non-bracket JSDoc `@param` tag (B434). In TS files, a non-optional param
            // without an initializer is required.
            if (!p.questionToken && p.initializer == null) {
                if (!isJsFile || (p.name as? Identifier)?.text in jsDocRequiredNames) lastRequiredPos = total
            }
            total++
        }
        // Required = position of last required param + 1.
        // E.g., f(a, b = 0, c) → lastRequiredPos = 2 → required = 3.
        // This ensures optional params before a required one are effectively required.
        val required = lastRequiredPos + 1
        return FuncParamInfo(required, total, hasRest, isOverloaded = false, parameters = parameters)
    }

    /**
     * Call-arity emission at a REACHED CallExpression enter — the deleted
     * checkArgCountInExprCore CallExpression arm's emission block verbatim
     * (recursion into arguments/callee is owned by the spine edges; the
     * context threading is [spineArgCtxAt]).
     */
    private fun spineArgCallEnter(expr: CallExpression) {
        val calleeName = (expr.expression as? Identifier)?.text ?: return
        if (spineArgDepth(expr) < 0) return
        val ctx = spineArgCtxAt(expr)
        val funcParams = ctx.funcParams
        val source = spineSource
        val fileName = spineFileName
        val info = if (calleeName == "super") ctx.superCtor else
            funcParams[calleeName].also { FrontEnd.noteArgLookup(it != null) }
        // M1.11 (Shape C): a SPREAD argument's expansion length is unknown, so a
        // too-FEW conclusion from counting it as 1 is unsound (`createDiagnostic(
        // ...diag)` / `reportRelationError(undefined, ...info)` — tsc accepts a
        // tuple-typed spread covering the remaining params). Too-many stands
        // (a spread expands to ≥0, so fixed args alone exceeding max still errors).
        val hasSpreadArg = expr.arguments.any { it is SpreadElement }
        // (M3.0-gap-4) A spread argument must have a TUPLE type unless it is passed to a
        // REST parameter: `f0(...args)` with `args: readonly string[]` and
        // `f0(a: string, b: string)` cannot be checked for arity at all, and tsc reports
        // TS2556 at the spread. Only fires when the operand's type is POSITIVELY an
        // array-that-is-not-a-tuple, so an unresolved or `any` operand stays silent; a
        // tuple spread (`readonly [string, string]`) is legal here and must not fire.
        // ... but ONLY when the count is not already wrong: tsc checks arity first, so
        // `f(1, 2, ...xs)` against a one-parameter `f` is "Expected 1 arguments, but got
        // 3", not TS2556. The spread's unknown length only matters when the call would
        // otherwise be arity-clean.
        if (info != null && !info.hasRest && hasSpreadArg &&
            expr.arguments.size <= info.maxParams
        ) {
            for (arg in expr.arguments) {
                val spread = arg as? SpreadElement ?: continue
                // An ARRAY LITERAL spread has a syntactically known length, so tsc treats
                // it as a tuple: `f(1, 2, 3, 4, 5, ...[6, 7])` is counted as seven
                // arguments and reported as too many, never as TS2556.
                if (spread.expression is ArrayLiteralExpression) continue
                if (!spreadOperandIsNonTupleArray(spread.expression)) continue
                val spreadStart = spread.pos
                val (sl, sc) = getLineAndCharacterOfPosition(source, spreadStart)
                diagnostics.add(Diagnostic(
                    message = "A spread argument must either have a tuple type or be " +
                        "passed to a rest parameter.",
                    category = DiagnosticCategory.Error, code = 2556, fileName = fileName,
                    line = sl, character = sc, start = spreadStart,
                    length = expressionTrueEnd(spread.expression) - spreadStart,
                ))
                return
            }
        }
        // (M3.0-gap-4) A rest parameter annotated with a fixed TUPLE has fixed arity, so
        // the usual "a rest parameter accepts anything" exemption does not apply:
        // `f2(...args: readonly [string, string])` takes exactly two, and a tuple-typed
        // spread ARGUMENT contributes its element count. The excess anchor is an
        // ARGUMENT INDEX, not the expanded count — for `f2('abc', ...args)` the third
        // argument lives inside the spread, so tsc squiggles the spread itself.
        if (info != null && !info.isOverloaded && info.hasRest) {
            val restTupleLen = fixedTupleLengthOfRestParam(info.parameters.lastOrNull())
            if (restTupleLen != null) {
                val maxArgs = (info.parameters.size - 1) + restTupleLen
                var expanded = 0
                var excessIdx = -1
                var allKnown = true
                for ((i, a) in expr.arguments.withIndex()) {
                    val n = argumentExpansionCount(a)
                    if (n == null) { allKnown = false; break }
                    expanded += n
                    if (expanded > maxArgs && excessIdx < 0) excessIdx = i
                }
                if (allKnown && excessIdx >= 0) {
                    emitTS2554TooMany(
                        maxArgs, maxArgs, expanded, expr.arguments, excessIdx, source, fileName,
                    )
                    return
                }
            }
        }
        if (info != null && !info.isOverloaded) {
            val argCount = expr.arguments.size
            if (!info.hasRest && argCount > info.maxParams) {
                // noImplicitAnyLoopCrash: a non-tuple spread arg into a no-rest fn is a
                // TS2556 (owned by checkSpreadNonIterableIntoFixedArity), NOT a TS2554.
                if ("$fileName|${expr.pos}" in spreadNonIterableHandledCalls) return
                emitTS2554TooMany(info.minParams, info.maxParams, argCount, expr.arguments, info.maxParams, source, fileName)
            } else if (argCount < info.minParams && !hasSpreadArg) {
                if (info.hasRest) {
                    emitTS2555TooFew(info.minParams, argCount, expr.expression, source, fileName, info.parameters)
                } else {
                    emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr.expression, source, fileName, info.parameters, info.declSource, info.declFileName)
                }
            } else if (info.hasRest && expr.typeArguments.isNullOrEmpty()) {
                // B170: rest param typed `Parameters<Fn>` where another param is typed
                // bare `Fn` and the call's arg there is an INLINE function — the rest
                // tuple expands to the fn's REQUIRED parameters, making them required
                // call arguments (spreadOfParamsFromGeneratorMakesRequiredParams:
                // `call(function* (a:'a'){})` → "Expected 2 arguments, but got 1." +
                // related TS6236 at the rest parameter). Optionals/defaults/rest in the
                // inline fn contribute nothing (takeWhile stops at the first optional).
                val restParam = info.parameters.lastOrNull()
                val tpName = ((restParam?.type as? TypeReference)
                    ?.takeIf { (it.typeName as? Identifier)?.text == "Parameters" && it.typeArguments?.size == 1 }
                    ?.typeArguments?.get(0) as? TypeReference)
                    ?.let { it.typeName as? Identifier }?.text
                if (restParam != null && restParam.dotDotDotToken && tpName != null) {
                    val anchorIdx = info.parameters.indexOfFirst { p ->
                        !p.dotDotDotToken &&
                            (p.type as? TypeReference)?.let { it.typeArguments == null && (it.typeName as? Identifier)?.text == tpName } == true
                    }
                    val argFn = expr.arguments.getOrNull(anchorIdx)
                    val fnParams = when (argFn) {
                        is FunctionExpression -> argFn.parameters
                        is ArrowFunction -> argFn.parameters
                        else -> null
                    }
                    if (anchorIdx >= 0 && fnParams != null) {
                        val required = fnParams.takeWhile {
                            !it.questionToken && it.initializer == null && !it.dotDotDotToken
                        }.count()
                        val expected = (info.parameters.size - 1) + required
                        if (argCount < expected) {
                            val start = expr.expression.pos
                            val length = expressionTrueEnd(expr.expression) - start
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            val restName = (restParam.name as? Identifier)?.text ?: "args"
                            val (relLine, relChar) = getLineAndCharacterOfPosition(source, restParam.pos)
                            diagnostics.add(Diagnostic(
                                message = "Expected $expected arguments, but got $argCount.",
                                category = DiagnosticCategory.Error, code = 2554,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                                relatedInformation = listOf(Diagnostic(
                                    message = "Arguments for the rest parameter '$restName' were not provided.",
                                    category = DiagnosticCategory.Message, code = 6236,
                                    fileName = fileName, line = relLine, character = relChar,
                                    start = restParam.pos,
                                    length = (restParam.end - restParam.pos).coerceAtLeast(1),
                                )),
                            ))
                        }
                    }
                }
            }
        } else if (info != null && info.isOverloaded && expr.typeArguments.isNullOrEmpty()) {
            // B95 (round 80): overload-arity TS2554. Emit ONLY when the call's arg
            // count is outside the [min, max] arity RANGE of all overload signatures
            // — i.e. NO overload could match by arity. Within range, an overload may
            // match (type-based TS2769 handles type mismatches). No related TS6210/6211
            // (TypeScript omits the "argument for 'x'" hint for overload arity errors).
            // Skipped when explicit type args are present (those filter overloads to
            // generic ones, changing the applicable arity — out of scope here).
            val argCount = expr.arguments.size
            val spreads = expr.arguments.filterIsInstance<SpreadElement>()
            if (spreads.isNotEmpty() && spreads.all { it.expression is ArrayLiteralExpression }) {
                // B270: spread-of-array-literal args have a knowable effective count;
                // overflow inside the spread squiggles the spread argument itself.
                if (!info.hasRest) {
                    val effective = expr.arguments.sumOf { a ->
                        if (a is SpreadElement) (a.expression as ArrayLiteralExpression).elements.size else 1
                    }
                    if (effective > info.maxParams) {
                        val sp = spreads.first()
                        val start = sp.pos
                        val len = (expressionTrueEnd(sp.expression) - start).coerceAtLeast(1)
                        val (line, ch) = getLineAndCharacterOfPosition(source, start)
                        val expected = if (info.minParams == info.maxParams) "${info.maxParams}" else "${info.minParams}-${info.maxParams}"
                        diagnostics.add(Diagnostic(
                            message = "Expected $expected arguments, but got $effective.",
                            category = DiagnosticCategory.Error, code = 2554,
                            fileName = fileName, line = line, character = ch,
                            start = start, length = len,
                        ))
                    }
                }
            } else if (argCount < info.minParams && spreads.isEmpty()) {
                emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr.expression, source, fileName, info.parameters, info.declSource, info.declFileName)
            } else if (!info.hasRest && argCount > info.maxParams) {
                emitTS2554TooMany(info.minParams, info.maxParams, argCount, expr.arguments, info.maxParams, source, fileName)
            } else if (spreads.isEmpty() && info.overloadSigs.isNotEmpty() &&
                info.overloadSigs.none { argCount >= it.minParams && (it.hasRest || argCount <= it.maxParams) }
            ) {
                // B270: TS2575 — argCount falls in a GAP between overload arities
                // (within the global range but accepted by no signature). Neighbors
                // come from per-signature MIN counts, mirroring TS's
                // getArgumentArityError below/above computation.
                var below = -1
                var above = Int.MAX_VALUE
                for (sig in info.overloadSigs) {
                    val mc = sig.minParams
                    if (mc < argCount && mc > below) below = mc
                    else if (argCount < mc && mc < above) above = mc
                }
                if (below >= 0 && above != Int.MAX_VALUE) {
                    val start = expr.expression.pos
                    val len = calleeName.length.coerceAtLeast(1)
                    val (line, ch) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "No overload expects $argCount arguments, but overloads do exist that expect either $below or $above arguments.",
                        category = DiagnosticCategory.Error, code = 2575,
                        fileName = fileName, line = line, character = ch,
                        start = start, length = len,
                    ))
                }
            }
        } else if (info != null && info.isOverloaded && !expr.typeArguments.isNullOrEmpty()
            && info.overloadSigs.isNotEmpty()
        ) {
            // B95b (round 81): overload call WITH explicit type args, e.g.
            // `foo<string>("hello")` against `foo<T>(a,b)` + `foo(a)`. Explicit type
            // args filter the overload set to the GENERIC signatures that can accept
            // this many type args (non-generic overloads are inapplicable). Arity-check
            // the call against ONLY that applicable subset. functionCall18 case.
            val typeArgCount = expr.typeArguments.size
            val applicable = info.overloadSigs.filter { sig ->
                sig.typeParamCount > 0 && typeArgCount in sig.minTypeParams..sig.typeParamCount
            }
            if (applicable.isNotEmpty()) {
                val argCount = expr.arguments.size
                val gMin = applicable.minOf { it.minParams }
                val gMax = applicable.maxOf { it.maxParams }
                val gRest = applicable.any { it.hasRest }
                // TS6210 "argument for 'x' not provided" only when the applicable subset
                // is unambiguous (single signature) — matches TypeScript's hint.
                val relParams = if (applicable.size == 1) applicable[0].parameters else emptyList()
                if (argCount < gMin) {
                    emitTS2554TooFew(gMin, gMax, argCount, expr.expression, source, fileName, relParams)
                } else if (!gRest && argCount > gMax) {
                    emitTS2554TooMany(gMin, gMax, argCount, expr.arguments, gMax, source, fileName)
                }
            }
        }
    }

    /**
     * Constructor-arity emission at a REACHED NewExpression enter — the
     * deleted checkArgCountInExprCore NewExpression arm's emission block
     * verbatim (the `new` CALLEE expression stays unreached, matching the
     * legacy walker, which recursed into arguments only).
     */
    private fun spineArgNewEnter(expr: NewExpression) {
        val className = (expr.expression as? Identifier)?.text ?: return
        if (spineArgDepth(expr) < 0) return
        val ctx = spineArgCtxAt(expr)
        val funcParams = ctx.funcParams
        val classCtorParams = ctx.classCtorParams
        val source = spineSource
        val fileName = spineFileName
        // B238: builtin Error-family constructors have a target-dependent lib
        // arity — `(message?)` pre-es2022, `(message?, options?)` from es2022
        // (AggregateError: `(errors, message?[, options?])`). Fires only when
        // neither the class name nor ErrorConstructor has any user declaration.
        if (className in BUILTIN_ERROR_CTOR_NAMES && classCtorParams[className] == null &&
            funcParams[className] == null &&
            globals[className]?.declarations?.any { it !in builtinLibDecls } != true &&
            globals["${className}Constructor"]?.declarations?.any { it !in builtinLibDecls } != true) {
            val argCount = expr.arguments?.size ?: 0
            val isAggregate = className == "AggregateError"
            val maxArgs = (if (isAggregate) 2 else 1) +
                (if (libFeatureAvailable(ScriptTarget.ES2022)) 1 else 0)
            val minArgs = if (isAggregate) 1 else 0
            if (argCount > maxArgs) {
                emitTS2554TooMany(minArgs, maxArgs, argCount, expr.arguments ?: emptyList(), maxArgs, source, fileName)
            }
        }
        val info = classCtorParams[className].also { FrontEnd.noteArgLookup(it != null) }
        if (info != null && !info.isOverloaded) {
            val argCount = expr.arguments?.size ?: 0
            if (!info.hasRest && argCount > info.maxParams) {
                val args = expr.arguments ?: emptyList()
                emitTS2554TooMany(info.minParams, info.maxParams, argCount, args, info.maxParams, source, fileName)
            } else if (argCount < info.minParams &&
                expr.arguments?.any { it is SpreadElement } != true
            ) {
                // B95c (round 82): squiggle the WHOLE `new X(...)` (expr.pos .. after `)`),
                // not just the class identifier — matches TypeScript. Pass info.parameters
                // so the TS6210 "argument for 'x' not provided" related info fires (it points
                // at the ctor's param at the missing index; for an inherited ctor that's the
                // base class's param).
                if (info.hasRest) {
                    emitTS2555TooFew(info.minParams, argCount, expr, source, fileName, info.parameters)
                } else {
                    emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr, source, fileName, info.parameters, info.declSource, info.declFileName)
                }
            }
        }
    }

    /**
     * Tagged-template arity emission at a REACHED TaggedTemplateExpression
     * enter — the deleted checkArgCountInExprCore TaggedTemplateExpression
     * arm's emission block verbatim. Tagged template `f`...${a}${b}...``
     * calls `f([], a, b, ...)`: argCount = 1 (TemplateStringsArray) +
     * spans.size (+1 when the template is unterminated — the parser may stop
     * before adding the last span).
     */
    private fun spineArgTaggedEnter(expr: TaggedTemplateExpression) {
        val calleeName = (expr.tag as? Identifier)?.text ?: return
        if (spineArgDepth(expr) < 0) return
        val ctx = spineArgCtxAt(expr)
        val source = spineSource
        val fileName = spineFileName
        val info = ctx.funcParams[calleeName].also { FrontEnd.noteArgLookup(it != null) }
        if (info != null && !info.isOverloaded) {
            val templateExpr = expr.template as? TemplateExpression
            val spanCount = templateExpr?.templateSpans?.size ?: 0
            val unterminatedBonus = if (templateExpr?.isUnterminated == true) 1 else 0
            val argCount = 1 + spanCount + unterminatedBonus
            if (!info.hasRest && argCount > info.maxParams) {
                // Position the diagnostic at the template's end (close-backtick or EOF
                // for unterminated cases). Length 0 — matches TypeScript's emit.
                val pos = expr.template.end
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "Expected ${formatExpectedArgs(info.minParams, info.maxParams)} arguments, but got $argCount.",
                    category = DiagnosticCategory.Error,
                    code = 2554,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = pos,
                    length = 0,
                ))
            }
        }
    }

    /**
     * Emit TS2554 for too many arguments.
     * Squiggle covers args[expectedCount] through args.last().
     */
    private fun formatExpectedArgs(minParams: Int, maxParams: Int): String =
        if (minParams != maxParams) "$minParams-$maxParams" else "$maxParams"

    /**
     * B279: counts assignment-LIKE occurrences of [name] in [source] — `name =` (incl.
     * compound ops, excluding `==`/`=>`) and `name++`/`--name` forms. The DECLARATION's
     * own initializer `=` counts once, so a never-reassigned `var f = function(){}` yields
     * exactly 1. String/comment matches over-count → conservative suppression (FN-safe).
     */
    private fun countAssignmentLikeOccurrences(source: String, name: String): Int {
        if (name.isEmpty()) return 2
        var count = 0
        var idx = srcIndexOf(source, name)
        fun isWordChar(c: Char?) = c != null && (c.isLetterOrDigit() || c == '_' || c == '$')
        while (idx >= 0) {
            val before = source.getOrNull(idx - 1)
            val after = source.getOrNull(idx + name.length)
            if (!isWordChar(before) && before != '.' && !isWordChar(after)) {
                // prefix ++/--
                var b = idx - 1
                while (b >= 0 && (source[b] == ' ' || source[b] == '\t')) b--
                if (b >= 1 && ((source[b] == '+' && source[b - 1] == '+') || (source[b] == '-' && source[b - 1] == '-'))) count++
                // suffix: skip whitespace then look for assignment op or ++/--
                var p = idx + name.length
                while (p < source.length && (source[p] == ' ' || source[p] == '\t')) p++
                if (p < source.length) {
                    val c0 = source[p]
                    val c1 = source.getOrNull(p + 1)
                    val c2 = source.getOrNull(p + 2)
                    val c3 = source.getOrNull(p + 3)
                    val assigned = when {
                        (c0 == '+' && c1 == '+') || (c0 == '-' && c1 == '-') -> true
                        c0 == '=' && c1 != '=' && c1 != '>' -> true
                        c0 in "+-*/%^" && c1 == '=' -> true
                        (c0 == '&' || c0 == '|') && c1 == '=' -> true
                        (c0 == '&' && c1 == '&' || c0 == '|' && c1 == '|' || c0 == '?' && c1 == '?') && c2 == '=' -> true
                        c0 == '*' && c1 == '*' && c2 == '=' -> true
                        c0 == '<' && c1 == '<' && c2 == '=' -> true
                        c0 == '>' && c1 == '>' && (c2 == '=' || (c2 == '>' && c3 == '=')) -> true
                        else -> false
                    }
                    if (assigned) count++
                }
            }
            idx = srcIndexOf(source, name, idx + 1)
        }
        return count
    }

    private fun emitTS2554TooMany(
        minParams: Int,
        maxParams: Int,
        actual: Int,
        args: List<Expression>,
        firstExcessIdx: Int,
        source: String,
        fileName: String,
    ) {
        if (firstExcessIdx >= args.size) return
        val firstExcess = args[firstExcessIdx]
        val lastArg = args.last()
        val start = firstExcess.pos
        // Node.end includes the next token's scan position (always 1 char: ',' or ')'),
        // so subtract 1 to get the actual end of the argument text.
        val length = lastArg.end - 1 - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2554TooFew(
        minParams: Int,
        maxParams: Int,
        actual: Int,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        parameters: List<Parameter> = emptyList(),
        // B434: when the callee is declared in ANOTHER (script-mode) file, the param-related
        // TS6210/TS6211 positions must resolve against the DECLARING file's source/name.
        relSource: String? = null,
        relFileName: String? = null,
    ) {
        val start = calleeExpr.pos
        val length = expressionTrueEnd(calleeExpr) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val rSource = relSource ?: source
        val rFileName = relFileName ?: fileName
        // Check if the first missing parameter is a binding pattern → emit TS6211 related info
        val relatedInfo = mutableListOf<Diagnostic>()
        if (parameters.isNotEmpty()) {
            // Find the first missing parameter (at index `actual`, skipping `this` params)
            val nonThisParams = parameters.filter {
                !(it.name is Identifier && (it.name).text == "this")
            }
            if (actual < nonThisParams.size) {
                val missingParam = nonThisParams[actual]
                when (val paramName = missingParam.name) {
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.end - paramStart
                        val (relLine, relChar) = getLineAndCharacterOfPosition(rSource, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument matching this binding pattern was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6211,
                            fileName = rFileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    is Identifier -> {
                        // TS6210: "An argument for 'x' was not provided."
                        // B95c (round 82): anchor at the PARAMETER's pos (Parameter.pos is captured
                        // before modifiers, so for a parameter-property `public n` it points at
                        // `public` — matching TypeScript), not the name's pos. For a plain param,
                        // Parameter.pos == name.pos so function-call TS6210 is unaffected.
                        val paramStart = missingParam.pos
                        val paramLen = (paramName.pos + paramName.text.length - paramStart).coerceAtLeast(1)
                        val (relLine, relChar) = getLineAndCharacterOfPosition(rSource, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${paramName.text}' was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6210,
                            fileName = rFileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    else -> {}
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    /**
     * Emit TS2555 for too few arguments when function has rest parameters.
     * "Expected at least N arguments, but got M."
     */
    private fun emitTS2555TooFew(
        minParams: Int,
        actual: Int,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        parameters: List<Parameter> = emptyList(),
    ) {
        val start = calleeExpr.pos
        val length = expressionTrueEnd(calleeExpr) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val relatedInfo = mutableListOf<Diagnostic>()
        if (parameters.isNotEmpty()) {
            val nonThisParams = parameters.filter {
                !(it.name is Identifier && (it.name).text == "this")
            }
            if (actual < nonThisParams.size) {
                val missingParam = nonThisParams[actual]
                when (val paramName = missingParam.name) {
                    is Identifier -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.text.length
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${paramName.text}' was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6210,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.end - paramStart
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument matching this binding pattern was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6211,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    else -> {}
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected at least $minParams arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2555,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    // -----------------------------------------------------------------------
    // TS2526: `this` type outside a class/interface member (B98b, round 82)
    // -----------------------------------------------------------------------
    /** A `this` TYPE (ThisType node) is only valid inside a non-static class/interface member.
     *  Used as an actual type elsewhere — most commonly a type predicate `x is this` in an
     *  OBJECT-LITERAL method — it's TS2526. Narrow + FP-safe: only fires for a ThisType in an
     *  object-literal method/accessor return-type predicate's asserted TYPE (NOT the predicate
     *  SUBJECT `this is X`, which is the OK polymorphic-this form). Class/interface members are
     *  never visited, so valid `this` types there are untouched. */
    private fun checkThisTypeInObjectLiterals() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            result.sourceFile.statements.forEach { walkThisTypeStmt(it, source, fileName) }
        }
    }

    private fun walkThisTypeStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> stmt.declarationList.declarations.forEach { d ->
                d.initializer?.let { walkThisTypeExpr(it, source, fileName) }
            }
            is ExpressionStatement -> walkThisTypeExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { walkThisTypeExpr(it, source, fileName) }
            is Block -> stmt.statements.forEach { walkThisTypeStmt(it, source, fileName) }
            is IfStatement -> {
                walkThisTypeStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkThisTypeStmt(it, source, fileName) }
            }
            is ForStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is ForOfStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is ForInStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is WhileStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is DoStatement -> walkThisTypeStmt(stmt.statement, source, fileName)
            is FunctionDeclaration -> stmt.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
            else -> {}
        }
    }

    private fun walkThisTypeExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is MethodDeclaration -> {
                        checkThisTypePredicate(prop.type, source, fileName)
                        prop.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
                    }
                    is GetAccessor -> {
                        checkThisTypePredicate(prop.type, source, fileName)
                        prop.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
                    }
                    is SetAccessor -> prop.body?.statements?.forEach { walkThisTypeStmt(it, source, fileName) }
                    is PropertyAssignment -> walkThisTypeExpr(prop.initializer, source, fileName)
                    is SpreadAssignment -> walkThisTypeExpr(prop.expression, source, fileName)
                    else -> {}
                }
            }
            is ParenthesizedExpression -> walkThisTypeExpr(expr.expression, source, fileName)
            is CallExpression -> { walkThisTypeExpr(expr.expression, source, fileName); expr.arguments.forEach { walkThisTypeExpr(it, source, fileName) } }
            is NewExpression -> { walkThisTypeExpr(expr.expression, source, fileName); expr.arguments?.forEach { walkThisTypeExpr(it, source, fileName) } }
            is ArrayLiteralExpression -> expr.elements.forEach { walkThisTypeExpr(it, source, fileName) }
            is BinaryExpression -> {
                // Iterative (worklist) to avoid StackOverflow on deeply-nested chains
                // (e.g. binderBinaryExpressionStress); a crash here would abort JS emit.
                val work = ArrayDeque<Expression>()
                work.addLast(expr)
                while (work.isNotEmpty()) {
                    when (val cur = work.removeLast()) {
                        is BinaryExpression -> { work.addLast(cur.left); work.addLast(cur.right) }
                        else -> walkThisTypeExpr(cur, source, fileName)
                    }
                }
            }
            is ConditionalExpression -> { walkThisTypeExpr(expr.whenTrue, source, fileName); walkThisTypeExpr(expr.whenFalse, source, fileName) }
            is ArrowFunction -> when (val b = expr.body) {
                is Block -> b.statements.forEach { walkThisTypeStmt(it, source, fileName) }
                is Expression -> walkThisTypeExpr(b, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body.statements.forEach { walkThisTypeStmt(it, source, fileName) }
            is AsExpression -> walkThisTypeExpr(expr.expression, source, fileName)
            is SpreadElement -> walkThisTypeExpr(expr.expression, source, fileName)
            else -> {}
        }
    }

    /** Emit TS2526 if [type] is a type predicate whose asserted type is (or contains) a `this`. */
    private fun checkThisTypePredicate(type: TypeNode?, source: String, fileName: String) {
        val pred = type as? TypePredicate ?: return
        val thisPos = findThisTypePos(pred.type) ?: return
        val (line, character) = getLineAndCharacterOfPosition(source, thisPos)
        diagnostics.add(Diagnostic(
            message = "A 'this' type is available only in a non-static member of a class or interface.",
            category = DiagnosticCategory.Error,
            code = 2526,
            fileName = fileName,
            line = line,
            character = character,
            start = thisPos,
            length = 4,
        ))
    }

    /** Position of a `this` ThisType node directly or shallowly nested in [node] (union/array/paren). */
    private fun findThisTypePos(node: TypeNode?): Int? = when (node) {
        is ThisType -> node.pos
        is ParenthesizedType -> findThisTypePos(node.type)
        is ArrayType -> findThisTypePos(node.elementType)
        is UnionType -> node.types.firstNotNullOfOrNull { findThisTypePos(it) }
        is IntersectionType -> node.types.firstNotNullOfOrNull { findThisTypePos(it) }
        else -> null
    }

    /**
     * TS2532: in an ES MODULE, top-level `this` is `undefined`. A property/element access
     * `this.X` / `this[…]` reached from module top level through ONLY this-TRANSPARENT
     * constructs (statements, var initializers, arrow bodies, parens, calls, operators, …)
     * — i.e. NEVER crossing a `this`-rebinding boundary (function/method/constructor/accessor/
     * class/object-literal-method) — accesses a property of `undefined`. Fires regardless of
     * strictNullChecks (module top-level `this` is the `undefined` type). FP-safe BY
     * CONSTRUCTION: the walker never recurses into a `this`-rebinding boundary, so it can only
     * reach a genuine module-level `this`. Gated on ES-module FORMAT (a CommonJS module's
     * top-level `this` is `module.exports`, NOT undefined) and `isModuleFile` (scripts have a
     * global `this`).
     */
    private fun checkModuleTopLevelThis() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            if (!isModuleFile(result.sourceFile.statements)) continue
            if (!isESModuleFormat(options, fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) walkModuleThisStmt(stmt, source, fileName)
        }
    }

    private fun walkModuleThisStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) d.initializer?.let { walkModuleThisExpr(it, source, fileName) }
            is ExpressionStatement -> walkModuleThisExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { walkModuleThisExpr(it, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { walkModuleThisExpr(it, source, fileName) }
            is IfStatement -> {
                walkModuleThisExpr(stmt.expression, source, fileName)
                walkModuleThisStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkModuleThisStmt(it, source, fileName) }
            }
            is Block -> stmt.statements.forEach { walkModuleThisStmt(it, source, fileName) }
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkModuleThisExpr(it, source, fileName) }
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { it.initializer?.let { i -> walkModuleThisExpr(i, source, fileName) } }
                stmt.condition?.let { walkModuleThisExpr(it, source, fileName) }
                stmt.incrementor?.let { walkModuleThisExpr(it, source, fileName) }
                walkModuleThisStmt(stmt.statement, source, fileName)
            }
            is ForInStatement -> { walkModuleThisExpr(stmt.expression, source, fileName); walkModuleThisStmt(stmt.statement, source, fileName) }
            is ForOfStatement -> { walkModuleThisExpr(stmt.expression, source, fileName); walkModuleThisStmt(stmt.statement, source, fileName) }
            is WhileStatement -> { walkModuleThisExpr(stmt.expression, source, fileName); walkModuleThisStmt(stmt.statement, source, fileName) }
            is DoStatement -> { walkModuleThisStmt(stmt.statement, source, fileName); walkModuleThisExpr(stmt.expression, source, fileName) }
            is SwitchStatement -> {
                walkModuleThisExpr(stmt.expression, source, fileName)
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> { walkModuleThisExpr(c.expression, source, fileName); c.statements.forEach { walkModuleThisStmt(it, source, fileName) } }
                    is DefaultClause -> c.statements.forEach { walkModuleThisStmt(it, source, fileName) }
                    else -> {}
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { walkModuleThisStmt(it, source, fileName) }
                stmt.catchClause?.block?.statements?.forEach { walkModuleThisStmt(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { walkModuleThisStmt(it, source, fileName) }
            }
            is LabeledStatement -> walkModuleThisStmt(stmt.statement, source, fileName)
            is ExportAssignment -> walkModuleThisExpr(stmt.expression, source, fileName)
            // FunctionDeclaration / ClassDeclaration / ModuleDeclaration / Interface / Enum:
            // a `this`-rebinding (or this-irrelevant) boundary — do NOT recurse.
            else -> {}
        }
    }

    private fun walkModuleThisExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is PropertyAccessExpression -> {
                val recv = expr.expression
                if (recv is Identifier && recv.text == "this") emitModuleThisUndefined(recv, source, fileName)
                else walkModuleThisExpr(recv, source, fileName)
            }
            is ElementAccessExpression -> {
                val recv = expr.expression
                if (recv is Identifier && recv.text == "this") emitModuleThisUndefined(recv, source, fileName)
                else walkModuleThisExpr(recv, source, fileName)
                walkModuleThisExpr(expr.argumentExpression, source, fileName)
            }
            is ParenthesizedExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is ArrowFunction -> when (val b = expr.body) {
                // Arrows preserve the lexical (module) `this` — still transparent.
                is Block -> b.statements.forEach { walkModuleThisStmt(it, source, fileName) }
                is Expression -> walkModuleThisExpr(b, source, fileName)
                else -> {}
            }
            is CallExpression -> { walkModuleThisExpr(expr.expression, source, fileName); expr.arguments.forEach { walkModuleThisExpr(it, source, fileName) } }
            is NewExpression -> { walkModuleThisExpr(expr.expression, source, fileName); expr.arguments?.forEach { walkModuleThisExpr(it, source, fileName) } }
            is BinaryExpression -> {
                // Iterative left-spine to survive deeply-nested `a + b + c + …` chains.
                var node: Expression = expr
                while (node is BinaryExpression) { walkModuleThisExpr(node.right, source, fileName); node = node.left }
                walkModuleThisExpr(node, source, fileName)
            }
            is PrefixUnaryExpression -> walkModuleThisExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> walkModuleThisExpr(expr.operand, source, fileName)
            is ConditionalExpression -> { walkModuleThisExpr(expr.condition, source, fileName); walkModuleThisExpr(expr.whenTrue, source, fileName); walkModuleThisExpr(expr.whenFalse, source, fileName) }
            is ArrayLiteralExpression -> expr.elements.forEach { walkModuleThisExpr(it, source, fileName) }
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> walkModuleThisExpr(p.initializer, source, fileName)
                is SpreadAssignment -> walkModuleThisExpr(p.expression, source, fileName)
                else -> {} // method/accessor/shorthand → boundary or n/a
            }
            is SpreadElement -> walkModuleThisExpr(expr.expression, source, fileName)
            is AsExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is NonNullExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is AwaitExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { walkModuleThisExpr(it, source, fileName) }
            is TemplateExpression -> expr.templateSpans.forEach { walkModuleThisExpr(it.expression, source, fileName) }
            is CommaListExpression -> expr.elements.forEach { walkModuleThisExpr(it, source, fileName) }
            is TaggedTemplateExpression -> {
                walkModuleThisExpr(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach { walkModuleThisExpr(it.expression, source, fileName) }
            }
            is DeleteExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is VoidExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            is TypeOfExpression -> walkModuleThisExpr(expr.expression, source, fileName)
            // Identifier (bare `this` with no property access → no TS2532), FunctionExpression,
            // ClassExpression, literals → boundary or no `this.X` reachable; do NOT recurse.
            else -> {}
        }
    }

    private fun emitModuleThisUndefined(thisNode: Node, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, thisNode.pos)
        diagnostics.add(Diagnostic(
            message = "Object is possibly 'undefined'.",
            category = DiagnosticCategory.Error,
            code = 2532,
            fileName = fileName,
            line = line,
            character = character,
            start = thisNode.pos,
            length = 4, // "this"
        ))
    }

    /**
     * B519: collect ALL references to [name] inside a parameter default initializer [expr], each
     * tagged with whether it is a direct operand of an arithmetic/relational/bitwise binary
     * expression (→ possibly-undefined TS18048). Does not cross nested function/arrow/class
     * boundaries and only descends the BASE of a property access (a closure that reads the
     * param is a deferred read, not an init-time self-reference). [arithCtx] propagates
     * through parens only.
     */
    private fun collectParamSelfRefs(expr: Expression, name: String, arithCtx: Boolean, out: MutableList<Pair<Int, Boolean>>) {
        when (expr) {
            is Identifier -> if (expr.text == name) out.add(expr.pos to arithCtx)
            is ParenthesizedExpression -> collectParamSelfRefs(expr.expression, name, arithCtx, out)
            is PropertyAccessExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is ElementAccessExpression -> { collectParamSelfRefs(expr.expression, name, false, out); collectParamSelfRefs(expr.argumentExpression, name, false, out) }
            is CallExpression -> { collectParamSelfRefs(expr.expression, name, false, out); for (a in expr.arguments) collectParamSelfRefs(a, name, false, out) }
            is NewExpression -> { collectParamSelfRefs(expr.expression, name, false, out); expr.arguments?.forEach { collectParamSelfRefs(it, name, false, out) } }
            is BinaryExpression -> {
                val isArith = expr.operator in ARITH_REL_OPERATORS
                // Flatten the same-operator left-spine preserving source order; each operand's
                // immediate parent is a binary with this operator (so the arith flag is uniform).
                val rights = ArrayDeque<Expression>()
                var node: Expression = expr
                while (node is BinaryExpression && node.operator == expr.operator) {
                    rights.addFirst(node.right); node = node.left
                }
                collectParamSelfRefs(node, name, isArith, out)
                for (r in rights) collectParamSelfRefs(r, name, isArith, out)
            }
            is ConditionalExpression -> {
                collectParamSelfRefs(expr.condition, name, false, out)
                collectParamSelfRefs(expr.whenTrue, name, false, out)
                collectParamSelfRefs(expr.whenFalse, name, false, out)
            }
            is PrefixUnaryExpression -> collectParamSelfRefs(expr.operand, name, false, out)
            is PostfixUnaryExpression -> collectParamSelfRefs(expr.operand, name, false, out)
            is ArrayLiteralExpression -> for (e in expr.elements) collectParamSelfRefs(e, name, false, out)
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> collectParamSelfRefs(p.initializer, name, false, out)
                is SpreadAssignment -> collectParamSelfRefs(p.expression, name, false, out)
                is ShorthandPropertyAssignment -> { if (p.name.text == name) out.add(p.name.pos to false); p.objectAssignmentInitializer?.let { collectParamSelfRefs(it, name, false, out) } }
                else -> {}
            }
            is SpreadElement -> collectParamSelfRefs(expr.expression, name, false, out)
            is AsExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is NonNullExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is TypeAssertionExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is SatisfiesExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is AwaitExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is YieldExpression -> expr.expression?.let { collectParamSelfRefs(it, name, false, out) }
            is DeleteExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is VoidExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is TypeOfExpression -> collectParamSelfRefs(expr.expression, name, false, out)
            is TemplateExpression -> for (s in expr.templateSpans) collectParamSelfRefs(s.expression, name, false, out)
            is CommaListExpression -> for (e in expr.elements) collectParamSelfRefs(e, name, false, out)
            is TaggedTemplateExpression -> {
                collectParamSelfRefs(expr.tag, name, false, out)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach { collectParamSelfRefs(it.expression, name, false, out) }
            }
            // FunctionExpression / ArrowFunction / ClassExpression / literals → boundary; do not recurse.
            else -> {}
        }
    }

    /** B519: rightmost source end of a parameter default initializer (for the TS2502 span). */
    private fun paramDefaultRightmostEnd(expr: Expression): Int = when (expr) {
        is ConditionalExpression -> paramDefaultRightmostEnd(expr.whenFalse)
        is BinaryExpression -> paramDefaultRightmostEnd(expr.right)
        else -> expressionTrueEnd(expr)
    }

    /** B519: a parameter's declared type includes `undefined` (a union member or an optional `?`). */
    private fun paramTypeIncludesUndefined(param: Parameter): Boolean {
        if (param.questionToken) return true
        val t = param.type ?: return false
        return t is UnionType && t.types.any { it is KeywordTypeNode && it.kind == SyntaxKind.UndefinedKeyword }
    }

    /** B519: emit a diagnostic at an exact position, deduping by (code, position). */
    private fun emitDiagAtPos(start: Int, length: Int, code: Int, message: String, source: String, fileName: String, emitted: MutableSet<String>) {
        if (!emitted.add("$code@$start")) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message, category = DiagnosticCategory.Error, code = code,
            fileName = fileName, line = line, character = character,
            start = start, length = length.coerceAtLeast(1),
        ))
    }

    private fun walkParamForbiddenBindingName(name: Expression, source: String, fileName: String, emitted: MutableSet<String>) {
        when (name) {
            is ObjectBindingPattern -> for (el in name.elements) walkParamForbiddenBindingElement(el, source, fileName, emitted)
            is ArrayBindingPattern -> for (el in name.elements) (el as? BindingElement)?.let { walkParamForbiddenBindingElement(it, source, fileName, emitted) }
            else -> {}
        }
    }

    private fun walkParamForbiddenBindingElement(el: BindingElement, source: String, fileName: String, emitted: MutableSet<String>) {
        // Nested functions inside the element default get their own spine
        // Parameter enter (the deleted walkParamForbiddenExprForFns descent).
        el.initializer?.let { walkParamInitForbidden(it, source, fileName, emitted) }
        walkParamForbiddenBindingName(el.name, source, fileName, emitted)
    }

    private fun walkParamInitForbidden(expr: Expression, source: String, fileName: String, emitted: MutableSet<String>) {
        when (expr) {
            is AwaitExpression -> {
                val kw = paramForbiddenKeywordPos(expr.pos, "await", source)
                emitParamInitForbidden(kw, expressionTrueEnd(expr) - kw, 2524, "'await' expressions cannot be used in a parameter initializer.", source, fileName, emitted)
                walkParamInitForbidden(expr.expression, source, fileName, emitted)
            }
            is YieldExpression -> {
                val kw = paramForbiddenKeywordPos(expr.pos, "yield", source)
                // TS spans only the `yield` keyword (5 chars) for TS2523.
                emitParamInitForbidden(kw, 5, 2523, "'yield' expressions cannot be used in a parameter initializer.", source, fileName, emitted)
                expr.expression?.let { walkParamInitForbidden(it, source, fileName, emitted) }
            }
            // Parser-recovery shape: inside a GENERATOR's parameter list `yield` is NOT a
            // yield-context keyword, so `{ foo = yield "a" }` parses `yield` as a bare
            // Identifier and the operand (`"a"`) is dropped. TypeScript's grammar checker
            // reports this dangling-keyword-then-operand juxtaposition as TS2524 (verified
            // against the test's .errors.txt baseline, which carries TS2524 at BOTH the
            // `await import(...)` and the `yield "a"` positions). FP-safe: a bare
            // `yield`/`await` Identifier IMMEDIATELY followed (skipping spaces/tabs) by an
            // operand-start char is never legal -- a real variable named `yield`/`await` is
            // followed by a delimiter/operator/EOF, never an operand-start. 5-char span.
            is Identifier -> if (expr.text == "yield" || expr.text == "await") {
                val kwEnd = expr.pos + expr.text.length
                var p = kwEnd
                while (p < source.length && (source[p] == ' ' || source[p] == '\t')) p++
                if (p < source.length && p > kwEnd && isParamForbiddenOperandStart(source[p])) {
                    emitParamInitForbidden(expr.pos, expr.text.length, 2524, "'await' expressions cannot be used in a parameter initializer.", source, fileName, emitted)
                }
            }
            is ParenthesizedExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is CallExpression -> { walkParamInitForbidden(expr.expression, source, fileName, emitted); expr.arguments.forEach { walkParamInitForbidden(it, source, fileName, emitted) } }
            is NewExpression -> { walkParamInitForbidden(expr.expression, source, fileName, emitted); expr.arguments?.forEach { walkParamInitForbidden(it, source, fileName, emitted) } }
            is PropertyAccessExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is ElementAccessExpression -> { walkParamInitForbidden(expr.expression, source, fileName, emitted); walkParamInitForbidden(expr.argumentExpression, source, fileName, emitted) }
            is BinaryExpression -> {
                var node: Expression = expr
                while (node is BinaryExpression) { walkParamInitForbidden(node.right, source, fileName, emitted); node = node.left }
                walkParamInitForbidden(node, source, fileName, emitted)
            }
            is PrefixUnaryExpression -> walkParamInitForbidden(expr.operand, source, fileName, emitted)
            is PostfixUnaryExpression -> walkParamInitForbidden(expr.operand, source, fileName, emitted)
            is ConditionalExpression -> { walkParamInitForbidden(expr.condition, source, fileName, emitted); walkParamInitForbidden(expr.whenTrue, source, fileName, emitted); walkParamInitForbidden(expr.whenFalse, source, fileName, emitted) }
            is ArrayLiteralExpression -> expr.elements.forEach { walkParamInitForbidden(it, source, fileName, emitted) }
            is ObjectLiteralExpression -> for (p in expr.properties) when (p) {
                is PropertyAssignment -> walkParamInitForbidden(p.initializer, source, fileName, emitted)
                is SpreadAssignment -> walkParamInitForbidden(p.expression, source, fileName, emitted)
                else -> {}
            }
            is SpreadElement -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is AsExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is NonNullExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is TypeAssertionExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is SatisfiesExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is TemplateExpression -> expr.templateSpans.forEach { walkParamInitForbidden(it.expression, source, fileName, emitted) }
            is CommaListExpression -> expr.elements.forEach { walkParamInitForbidden(it, source, fileName, emitted) }
            is TaggedTemplateExpression -> {
                walkParamInitForbidden(expr.tag, source, fileName, emitted)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach { walkParamInitForbidden(it.expression, source, fileName, emitted) }
            }
            is DeleteExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is VoidExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            is TypeOfExpression -> walkParamInitForbidden(expr.expression, source, fileName, emitted)
            else -> {}
        }
    }

    /**
     * [pos] may include leading trivia before the `await`/`yield` keyword. Search
     * forward for the literal keyword so the squiggle column matches TypeScript's.
     */
    private fun paramForbiddenKeywordPos(pos: Int, keyword: String, source: String): Int {
        val idx = srcIndexOf(source, keyword, pos)
        if (idx >= pos && idx <= pos + 8) return idx
        var p = pos
        while (p < source.length && (source[p] == ' ' || source[p] == '\t' || source[p] == '\n' || source[p] == '\r')) p++
        return p
    }

    /**
     * Does [c] begin a primary-expression operand (used to recognize the dropped operand
     * after a recovery-parsed bare `yield`/`await` Identifier)? Conservative: quotes,
     * digits, `(`/`[`/`{`, identifier-start chars. Newline / operators / delimiters
     * excluded so a legitimate variable named `yield`/`await` never trips this.
     */
    private fun isParamForbiddenOperandStart(c: Char): Boolean =
        c == '"' || c == '\'' || c == '`' || c.isDigit() ||
            c == '(' || c == '[' || c == '{' ||
            c == '_' || c == '$' || c.isLetter()

    private fun emitParamInitForbidden(start: Int, length: Int, code: Int, message: String, source: String, fileName: String, emitted: MutableSet<String>) {
        var lineStart = start
        while (lineStart > 0 && source[lineStart - 1] != '\n') lineStart--
        var lineEnd = start
        while (lineEnd < source.length && source[lineEnd] != '\n') lineEnd++
        val key = code.toString() + "|" + source.substring(lineStart, lineEnd).trim()
        if (!emitted.add(key)) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length.coerceAtLeast(1),
        ))
    }

    /**
     * TS2880: `import x from "y" assert { ... }` — import assertions have been replaced by
     * import attributes (`with`). Fires only when the module target supports import
     * attributes (esnext / nodenext / node18 / node20 / preserve) and the clause uses the
     * deprecated `assert` keyword; suppressed entirely by `ignoreDeprecations`. Squiggle is
     * the `assert` keyword (6 chars). Purely syntactic — the parser captures the clause
     * keyword text and position — so this can never FP on a `with`-clause or non-attribute
     * import. (For non-supporting module kinds TypeScript emits a different code we don't
     * implement; leaving those silent matches current behaviour.)
     */
    private fun checkImportAssertionsDeprecated() {
        if (options.ignoreDeprecations != null) return
        val m = options.effectiveModule
        val supportsAttributes = m == ModuleKind.ESNext || m == ModuleKind.NodeNext ||
            m == ModuleKind.Node18 || m == ModuleKind.Node20 || m == ModuleKind.Preserve
        if (!supportsAttributes) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                val clause: String?
                val pos: Int
                when (stmt) {
                    is ImportDeclaration -> { clause = stmt.assertClause; pos = stmt.assertClausePos }
                    is ExportDeclaration -> { clause = stmt.assertClause; pos = stmt.assertClausePos }
                    else -> continue
                }
                if (clause == null || pos < 0 || !clause.startsWith("assert")) continue
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "Import assertions have been replaced by import attributes. Use 'with' instead of 'assert'.",
                    category = DiagnosticCategory.Error,
                    code = 2880,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = pos,
                    length = 6,
                ))
            }
        }
    }

    /**
     * B374: TS2341 for `this.<privateMember>` accessed inside a FREE function whose `this`
     * is typed as a class — either via the function's own `this:` parameter
     * (`function f(this: Foo) { this.priv }`) or via a contextual function-type annotation
     * (`const f: (this: Foo) => void = function() { this.priv }`). Private members are
     * class-body-only, so reaching one through a this-typed free function (outside the class
     * body) always errors. PROTECTED is deliberately allowed — tsc treats a this-typed
     * function as method-like for protected access (protectedAccessThroughContextualThis).
     * FP-safe and additive: fires only for a `this.<name>` whose name is a declared PRIVATE
     * member of the resolved class. Skips JS-like / .d.ts files.
     */
    private fun checkPrivateThisAccessInThisParamFunctions() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            ptpScanStmts(result.sourceFile.statements, result.sourceFile.text, fileName, result.locals)
        }
    }

    /** Resolve a `this:` TypeNode to (className, private-member-names) or null. */
    private fun ptpThisClassPrivates(thisType: TypeNode?, locals: SymbolTable?): Pair<String, Set<String>>? {
        val tr = thisType as? TypeReference ?: return null
        if (tr.typeArguments != null) return null
        val name = (tr.typeName as? Identifier)?.text ?: return null
        val sym = locals?.get(name) ?: globals[name] ?: return null
        val cls = sym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: return null
        val privates = cls.members.mapNotNull { m ->
            val (mods, mn) = when (m) {
                is PropertyDeclaration -> m.modifiers to (m.name as? Identifier)?.text
                is MethodDeclaration -> m.modifiers to (m.name as? Identifier)?.text
                is GetAccessor -> m.modifiers to (m.name as? Identifier)?.text
                is SetAccessor -> m.modifiers to (m.name as? Identifier)?.text
                else -> return@mapNotNull null
            }
            if (ModifierFlag.Private !in mods) null else mn
        }.toSet()
        if (privates.isEmpty()) return null
        return name to privates
    }

    /** The `this:` type of a function's first parameter, or null. */
    private fun ptpOwnThisType(params: List<Parameter>): TypeNode? {
        val p0 = params.firstOrNull() ?: return null
        if ((p0.name as? Identifier)?.text != "this") return null
        return p0.type
    }

    /** A contextual `this:` type from a function-type annotation (direct or via a type alias). */
    private fun ptpContextualThisType(annot: TypeNode?, locals: SymbolTable?): TypeNode? {
        var t = annot ?: return null
        if (t is TypeReference && t.typeArguments == null) {
            val n = (t.typeName as? Identifier)?.text
            val alias = (n?.let { locals?.get(it) ?: globals[it] })
                ?.declarations?.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
            if (alias != null) t = alias.type
        }
        return ptpOwnThisType((t as? FunctionType)?.parameters ?: return null)
    }

    private fun ptpScanStmts(stmts: List<Statement>, source: String, fileName: String, locals: SymbolTable?) {
        for (s in stmts) ptpScanStmt(s, source, fileName, locals)
    }

    private fun ptpScanStmt(s: Statement, source: String, fileName: String, locals: SymbolTable?) {
        when (s) {
            is FunctionDeclaration -> {
                val priv = ptpThisClassPrivates(ptpOwnThisType(s.parameters), locals)
                s.body?.let { body ->
                    if (priv != null) for (st in body.statements) ptpWalkBodyStmt(st, priv.second, priv.first, source, fileName)
                    ptpScanStmts(body.statements, source, fileName, locals)
                }
            }
            is VariableStatement -> for (d in s.declarationList.declarations) {
                val init = d.initializer as? FunctionExpression ?: continue
                val thisT = ptpOwnThisType(init.parameters) ?: ptpContextualThisType(d.type, locals)
                val priv = ptpThisClassPrivates(thisT, locals) ?: continue
                init.body.statements.forEach { ptpWalkBodyStmt(it, priv.second, priv.first, source, fileName) }
            }
            is Block -> ptpScanStmts(s.statements, source, fileName, locals)
            is IfStatement -> { ptpScanStmt(s.thenStatement, source, fileName, locals); s.elseStatement?.let { ptpScanStmt(it, source, fileName, locals) } }
            is ForStatement -> ptpScanStmt(s.statement, source, fileName, locals)
            is ForOfStatement -> ptpScanStmt(s.statement, source, fileName, locals)
            is ForInStatement -> ptpScanStmt(s.statement, source, fileName, locals)
            is WhileStatement -> ptpScanStmt(s.statement, source, fileName, locals)
            is DoStatement -> ptpScanStmt(s.statement, source, fileName, locals)
            is TryStatement -> {
                ptpScanStmts(s.tryBlock.statements, source, fileName, locals)
                s.catchClause?.block?.statements?.let { ptpScanStmts(it, source, fileName, locals) }
                s.finallyBlock?.statements?.let { ptpScanStmts(it, source, fileName, locals) }
            }
            is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { ptpScanStmts(it.statements, source, fileName, locals) }
            is ClassDeclaration -> for (m in s.members) when (m) {
                is MethodDeclaration -> m.body?.let { ptpScanStmts(it.statements, source, fileName, locals) }
                is Constructor -> m.body?.let { ptpScanStmts(it.statements, source, fileName, locals) }
                else -> {}
            }
            else -> {}
        }
    }

    /** Walk a statement of a this-typed function body, emitting TS2341 at `this.<private>`.
     *  Recurses into arrow bodies (which inherit `this`) but NOT nested functions/methods. */
    private fun ptpWalkBodyStmt(s: Statement, privates: Set<String>, className: String, source: String, fileName: String) {
        when (s) {
            is ExpressionStatement -> ptpWalkExpr(s.expression, privates, className, source, fileName)
            is ReturnStatement -> s.expression?.let { ptpWalkExpr(it, privates, className, source, fileName) }
            is ThrowStatement -> s.expression?.let { ptpWalkExpr(it, privates, className, source, fileName) }
            is VariableStatement -> for (d in s.declarationList.declarations) d.initializer?.let { ptpWalkExpr(it, privates, className, source, fileName) }
            is IfStatement -> { ptpWalkExpr(s.expression, privates, className, source, fileName); ptpWalkBodyStmt(s.thenStatement, privates, className, source, fileName); s.elseStatement?.let { ptpWalkBodyStmt(it, privates, className, source, fileName) } }
            is Block -> for (st in s.statements) ptpWalkBodyStmt(st, privates, className, source, fileName)
            is ForStatement -> { s.condition?.let { ptpWalkExpr(it, privates, className, source, fileName) }; ptpWalkBodyStmt(s.statement, privates, className, source, fileName) }
            is WhileStatement -> { ptpWalkExpr(s.expression, privates, className, source, fileName); ptpWalkBodyStmt(s.statement, privates, className, source, fileName) }
            else -> {}
        }
    }

    private fun ptpWalkExpr(e: Expression, privates: Set<String>, className: String, source: String, fileName: String) {
        when (e) {
            is PropertyAccessExpression -> {
                if ((e.expression as? Identifier)?.text == "this" && e.name.text in privates) {
                    val (line, ch) = getLineAndCharacterOfPosition(source, e.name.pos)
                    diagnostics.add(Diagnostic(
                        message = "Property '${e.name.text}' is private and only accessible within class '$className'.",
                        category = DiagnosticCategory.Error, code = 2341,
                        fileName = fileName, line = line, character = ch,
                        start = e.name.pos, length = e.name.text.length,
                    ))
                } else ptpWalkExpr(e.expression, privates, className, source, fileName)
            }
            is BinaryExpression -> { ptpWalkExpr(e.left, privates, className, source, fileName); ptpWalkExpr(e.right, privates, className, source, fileName) }
            is CallExpression -> { ptpWalkExpr(e.expression, privates, className, source, fileName); for (a in e.arguments) ptpWalkExpr(a, privates, className, source, fileName) }
            is ElementAccessExpression -> { ptpWalkExpr(e.expression, privates, className, source, fileName); ptpWalkExpr(e.argumentExpression, privates, className, source, fileName) }
            is ParenthesizedExpression -> ptpWalkExpr(e.expression, privates, className, source, fileName)
            is PrefixUnaryExpression -> ptpWalkExpr(e.operand, privates, className, source, fileName)
            is PostfixUnaryExpression -> ptpWalkExpr(e.operand, privates, className, source, fileName)
            is ConditionalExpression -> { ptpWalkExpr(e.condition, privates, className, source, fileName); ptpWalkExpr(e.whenTrue, privates, className, source, fileName); ptpWalkExpr(e.whenFalse, privates, className, source, fileName) }
            is ArrowFunction -> (e.body as? Expression)?.let { ptpWalkExpr(it, privates, className, source, fileName) } ?: (e.body as? Block)?.statements?.forEach { ptpWalkBodyStmt(it, privates, className, source, fileName) }
            is AwaitExpression -> ptpWalkExpr(e.expression, privates, className, source, fileName)
            is NonNullExpression -> ptpWalkExpr(e.expression, privates, className, source, fileName)
            is AsExpression -> ptpWalkExpr(e.expression, privates, className, source, fileName)
            is TemplateExpression -> for (sp in e.templateSpans) ptpWalkExpr(sp.expression, privates, className, source, fileName)
            else -> {}
        }
    }

    /**
     * B377: TS2445 for a write `obj.member = …` to a PROTECTED member from inside a FREE
     * function whose `this` is typed (via its `this:` parameter) as a class T, where the
     * protected member's declaring class D is NOT in T's hierarchy
     * (publicGetterProtectedSetterFromThisParameter — `bar(this: A) { b.q = 0 }`, `q`
     * protected in B, A doesn't derive from B → error; `this.x = 0` / `a.x = 0` where x is
     * protected in A stay legal because A derives from A). tsc's protected-accessibility
     * rule first tries `getEnclosingClassFromThisParameter` — a `this: T` param makes T the
     * enclosing-class-for-protected-access. Scoped to top-level / namespace-level free
     * functions (no lexical enclosing class — methods already use the standard path); only
     * WRITE targets (the setter governs writes); obj is `this` (→ T) or a class-typed
     * parameter (→ its class). FP-safe by exact shape; .d.ts / JS skipped.
     */
    private fun checkProtectedWriteViaThisParam() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            for (s in result.sourceFile.statements) pwScanStmt(s, result.sourceFile.text, fileName, result.locals)
        }
    }

    private fun pwResolveClass(typeNode: TypeNode?, locals: SymbolTable?): ClassDeclaration? {
        val tr = typeNode as? TypeReference ?: return null
        if (tr.typeArguments != null) return null
        val tn = tr.typeName as? Identifier ?: return null
        // INV.3(c)(iii): the merged-globals fallback is keyed by the NAME
        // IDENTIFIER node's owning file — the heritage walkers wrap a REAL
        // indexed Identifier in a synthesized TypeReference, so the identifier
        // (never the wrapper) carries the owner; a fully-synthesized identifier
        // degrades to the legacy merged consult inside the primitive.
        val sym = locals?.get(tn.text) ?: lookupPerFileForNode(tn, tn.text) ?: return null
        return sym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
    }

    /** True if `t` is `d` or transitively extends `d`. */
    private fun pwClassDerivesFrom(t: ClassDeclaration, d: ClassDeclaration, locals: SymbolTable?, depth: Int = 0): Boolean {
        if (t === d) return true
        if (depth > 12) return false
        for (h in t.heritageClauses ?: emptyList()) {
            if (h.token != SyntaxKind.ExtendsKeyword) continue
            for (ht in h.types) {
                val baseName = ht.expression as? Identifier ?: continue
                val base = pwResolveClass(TypeReference(typeName = baseName), locals) ?: continue
                if (pwClassDerivesFrom(base, d, locals, depth + 1)) return true
            }
        }
        return false
    }

    /** The class declaring the protected member that governs a WRITE to `member` on `cls`
     *  (the setter for an accessor pair, else the property), searching superclasses; null if
     *  no such member, or the write is public. */
    private fun pwFindProtectedWriteDeclaringClass(cls: ClassDeclaration, member: String, locals: SymbolTable?, depth: Int = 0): ClassDeclaration? {
        if (depth > 12) return null
        var setter: SetAccessor? = null
        var prop: PropertyDeclaration? = null
        var hasAnyNamed = false
        for (m in cls.members) {
            val mn = when (m) {
                is PropertyDeclaration -> (m.name as? Identifier)?.text
                is SetAccessor -> (m.name as? Identifier)?.text
                is GetAccessor -> (m.name as? Identifier)?.text
                is MethodDeclaration -> (m.name as? Identifier)?.text
                else -> null
            }
            if (mn != member) continue
            hasAnyNamed = true
            when (m) {
                is SetAccessor -> setter = m
                is PropertyDeclaration -> prop = m
                else -> {}
            }
        }
        if (hasAnyNamed) {
            val st = setter
            val pr = prop
            return when {
                st != null -> if (ModifierFlag.Protected in st.modifiers) cls else null
                pr != null -> if (ModifierFlag.Protected in pr.modifiers) cls else null
                else -> null // only getter/method named member → not a protected write we flag
            }
        }
        for (h in cls.heritageClauses ?: emptyList()) {
            if (h.token != SyntaxKind.ExtendsKeyword) continue
            for (ht in h.types) {
                val baseName = ht.expression as? Identifier ?: continue
                val base = pwResolveClass(TypeReference(typeName = baseName), locals) ?: continue
                pwFindProtectedWriteDeclaringClass(base, member, locals, depth + 1)?.let { return it }
            }
        }
        return null
    }

    private fun pwScanStmt(s: Statement, source: String, fileName: String, locals: SymbolTable?) {
        when (s) {
            is FunctionDeclaration -> pwProcessFreeFn(s.parameters, s.body?.statements, source, fileName, locals)
            is VariableStatement -> for (d in s.declarationList.declarations) {
                val init = d.initializer as? FunctionExpression ?: continue
                pwProcessFreeFn(init.parameters, init.body.statements, source, fileName, locals)
            }
            is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { for (st in it.statements) pwScanStmt(st, source, fileName, locals) }
            else -> {}
        }
    }

    private fun pwProcessFreeFn(params: List<Parameter>, body: List<Statement>?, source: String, fileName: String, locals: SymbolTable?) {
        if (body == null) return
        val thisType = ptpOwnThisType(params) ?: return
        val thisClass = pwResolveClass(thisType, locals) ?: return
        val paramClasses = HashMap<String, ClassDeclaration>()
        for (p in params) {
            val pn = (p.name as? Identifier)?.text ?: continue
            if (pn == "this") continue
            pwResolveClass(p.type, locals)?.let { paramClasses[pn] = it }
        }
        for (st in body) pwWalkStmt(st, thisClass, paramClasses, source, fileName, locals)
    }

    private fun pwWalkStmt(s: Statement, thisClass: ClassDeclaration, paramClasses: Map<String, ClassDeclaration>, source: String, fileName: String, locals: SymbolTable?) {
        when (s) {
            is ExpressionStatement -> pwCheckWrite(s.expression, thisClass, paramClasses, source, fileName, locals)
            is Block -> for (st in s.statements) pwWalkStmt(st, thisClass, paramClasses, source, fileName, locals)
            is IfStatement -> { pwWalkStmt(s.thenStatement, thisClass, paramClasses, source, fileName, locals); s.elseStatement?.let { pwWalkStmt(it, thisClass, paramClasses, source, fileName, locals) } }
            is ForStatement -> pwWalkStmt(s.statement, thisClass, paramClasses, source, fileName, locals)
            is WhileStatement -> pwWalkStmt(s.statement, thisClass, paramClasses, source, fileName, locals)
            else -> {}
        }
    }

    private fun pwCheckWrite(e: Expression, thisClass: ClassDeclaration, paramClasses: Map<String, ClassDeclaration>, source: String, fileName: String, locals: SymbolTable?) {
        if (e !is BinaryExpression || e.operator != SyntaxKind.Equals) return
        val lhs = e.left as? PropertyAccessExpression ?: return
        val objExpr = lhs.expression
        val objClass = when {
            objExpr is Identifier && objExpr.text == "this" -> thisClass
            objExpr is Identifier -> paramClasses[objExpr.text]
            else -> null
        } ?: return
        val member = lhs.name.text
        val declaring = pwFindProtectedWriteDeclaringClass(objClass, member, locals) ?: return
        if (pwClassDerivesFrom(thisClass, declaring, locals)) return
        val (line, ch) = getLineAndCharacterOfPosition(source, lhs.name.pos)
        diagnostics.add(Diagnostic(
            message = "Property '$member' is protected and only accessible within class '${declaring.name?.text}' and its subclasses.",
            category = DiagnosticCategory.Error, code = 2445,
            fileName = fileName, line = line, character = ch,
            start = lhs.name.pos, length = member.length,
        ))
    }

    /**
     * B446: general protected-member READ access checking (TS2445 / TS2446). For a
     * read `obj.member` (property access / call receiver) where `member` resolves to a
     * PROTECTED instance member declared in class D, applies tsc's accessibility rule:
     *   enclosing = the class governing protected access at the site (the lexical class,
     *               or — for a `this: T` parameter — T's class / its constraint's class;
     *               null for a free function with an unconstrained/non-class `this`).
     *   - enclosing == null OR enclosing does NOT derive from D → TS2445
     *     "Property 'm' is protected and only accessible within class 'D' and its subclasses."
     *   - else (enclosing can access D's protected members) but the RECEIVER's class is
     *     NOT enclosing-or-derived → TS2446 "...only accessible through an instance of
     *     class '<enclosing>'. This is an instance of class '<recv>'."
     * Receiver class is resolved AST-only: `this` → enclosing, a param/local typed as a
     * concrete non-generic class, `new C()`, or `this.prop` of a class-typed member.
     * FP firewall: fires ONLY when the receiver resolves to a concrete class
     * AND the member is found protected on its hierarchy (a public override stops the
     * search → no error); static members, generic-instantiated receivers, accessor-only
     * shapes with no protected decl, and writes (owned by B377) are excluded. Reads of a
     * genuinely-protected member from outside the hierarchy are ALWAYS errors.
     * (M0.4) round 635: ON THE SPINE — the container scan / walkers are the
     * spinePmrStatus/spinePmrEdge reach classifier, the downward state is the
     * spinePmr frame stack, and the emissions fire from spinePmrEnterNode;
     * the two fields below are the frame-maintained state registers.
     */
    // True while walking a CLASS METHOD body (not a free function / nested function expr):
    // gates the protected-WRITE check (`obj.m = …`) so it fires for class-method writes
    // (TS2446 etc.) without overlapping B377, which owns free-function writes.
    private var pmrInClassMethod = false
    // The LEXICAL class enclosing the current walk (null at top level / free functions /
    // nested function exprs). tsc's protected-access rule (checkPropertyAccessibility) tries
    // the lexical enclosing class FIRST, then falls back to the `this:`-parameter class — so
    // a method `foo(this: A)` declared in class B can still access B's protected members.
    private var pmrLexicalClass: ClassDeclaration? = null

    /** Resolve a `this:` type node (or a heritage base) to a concrete non-generic class;
     *  a `this: T` where T is a type param resolves through its constraint. */
    private fun pmrResolveClass(t: TypeNode?, tps: List<TypeParameter>?, locals: SymbolTable?, depth: Int = 0): ClassDeclaration? {
        if (t == null || depth > 8) return null
        val tr = t as? TypeReference ?: return null
        if (tr.typeArguments != null) return null
        val tn = tr.typeName as? Identifier ?: return null
        val name = tn.text
        val tp = tps?.firstOrNull { it.name.text == name }
        if (tp != null) return pmrResolveClass(tp.constraint, tps, locals, depth + 1)
        // INV.3(c)(iii): node-keyed fallback — see pwResolveClass (the heritage
        // walkers' synthesized wrappers carry a real indexed Identifier).
        val sym = locals?.get(name) ?: lookupPerFileForNode(tn, name) ?: return null
        return sym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
    }

    /** The class declaring a PROTECTED instance member named `member` reachable from
     *  `cls` (searching `cls` then its superclasses), or null when the member is not
     *  found, is public (a public override stops the search), or is static. */
    private fun pmrFindProtectedDeclaringClass(cls: ClassDeclaration, member: String, locals: SymbolTable?, depth: Int = 0): ClassDeclaration? {
        if (depth > 12) return null
        var found = false
        var protectedFound = false
        for (m in cls.members) {
            val mods = when (m) {
                is PropertyDeclaration -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is MethodDeclaration -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is GetAccessor -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is SetAccessor -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                else -> null
            } ?: continue
            if (ModifierFlag.Static in mods) continue
            found = true
            if (ModifierFlag.Protected in mods) protectedFound = true
        }
        if (found) return if (protectedFound) cls else null
        for (h in cls.heritageClauses ?: emptyList()) {
            if (h.token != SyntaxKind.ExtendsKeyword) continue
            for (ht in h.types) {
                val baseName = ht.expression as? Identifier ?: continue
                val base = pmrResolveClass(TypeReference(typeName = baseName), null, locals) ?: continue
                pmrFindProtectedDeclaringClass(base, member, locals, depth + 1)?.let { return it }
            }
        }
        return null
    }

    /** The class declaring a PROTECTED STATIC member named `member` reachable from `cls`
     *  (the class itself then its superclasses), or null when the member is not found, is
     *  public (a public static override stops the search), or is an instance member. */
    private fun pmrFindProtectedStaticDeclaringClass(cls: ClassDeclaration, member: String, locals: SymbolTable?, depth: Int = 0): ClassDeclaration? {
        if (depth > 12) return null
        var found = false
        var protectedFound = false
        for (m in cls.members) {
            val mods = when (m) {
                is PropertyDeclaration -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is MethodDeclaration -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is GetAccessor -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is SetAccessor -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                else -> null
            } ?: continue
            if (ModifierFlag.Static !in mods) continue
            found = true
            if (ModifierFlag.Protected in mods) protectedFound = true
        }
        if (found) return if (protectedFound) cls else null
        for (h in cls.heritageClauses ?: emptyList()) {
            if (h.token != SyntaxKind.ExtendsKeyword) continue
            for (ht in h.types) {
                val baseName = ht.expression as? Identifier ?: continue
                val base = pmrResolveClass(TypeReference(typeName = baseName), null, locals) ?: continue
                pmrFindProtectedStaticDeclaringClass(base, member, locals, depth + 1)?.let { return it }
            }
        }
        return null
    }

    private fun pmrLocalClass(init: Expression?, thisClass: ClassDeclaration?, vars: Map<String, ClassDeclaration>, locals: SymbolTable?): ClassDeclaration? {
        return when (init) {
            is NewExpression -> ((init.expression as? Identifier)?.text)?.let { pmrResolveClass(TypeReference(typeName = Identifier(it)), null, locals) }
            is Identifier -> vars[init.text]
            is PropertyAccessExpression -> {
                // `this.prop` of a class-typed member.
                if ((init.expression as? Identifier)?.text == "this" && thisClass != null) {
                    val pm = thisClass.members.firstOrNull { (it as? PropertyDeclaration)?.let { p -> (p.name as? Identifier)?.text == init.name.text } == true } as? PropertyDeclaration
                    pmrResolveClass(pm?.type, null, locals)
                } else null
            }
            else -> null
        }
    }

    private fun pmrCheckAccess(pa: PropertyAccessExpression, thisClass: ClassDeclaration?, enclosing: ClassDeclaration?, vars: Map<String, ClassDeclaration>, source: String, fileName: String, locals: SymbolTable?) {
        val obj = pa.expression
        val member = pa.name.text
        fun emit2445(declaring: ClassDeclaration) {
            val (line, ch) = getLineAndCharacterOfPosition(source, pa.name.pos)
            diagnostics.add(Diagnostic(
                message = "Property '$member' is protected and only accessible within class '${declaring.name?.text}' and its subclasses.",
                category = DiagnosticCategory.Error, code = 2445,
                fileName = fileName, line = line, character = ch,
                start = pa.name.pos, length = member.length,
            ))
        }
        // STATIC access `ClassName.member` — obj is a class identifier (not `this`/`super`,
        // not a tracked instance var). Only the LEXICAL enclosing class grants access to a
        // protected static (tsc disallows the `this:`-param fallback for statics); the
        // instance-receiver rule (TS2446) does not apply to statics.
        if (obj is Identifier && obj.text != "this" && obj.text != "super" && vars[obj.text] == null) {
            // INV.3(c)(iii): node-keyed merged fallback (see pwResolveClass).
            val cls = (locals?.get(obj.text) ?: lookupPerFileForNode(obj, obj.text))
                ?.declarations?.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
            if (cls != null) {
                val declaring = pmrFindProtectedStaticDeclaringClass(cls, member, locals) ?: return
                val lex = pmrLexicalClass
                if (lex == null || !pwClassDerivesFrom(lex, declaring, locals)) emit2445(declaring)
                return
            }
            return
        }
        val recvClass = when {
            obj is Identifier && obj.text == "this" -> thisClass
            obj is Identifier -> vars[obj.text]
            else -> null
        } ?: return
        val declaring = pmrFindProtectedDeclaringClass(recvClass, member, locals) ?: return
        // tsc tries the LEXICAL enclosing class first, then the `this:`-parameter class.
        val candidates = listOfNotNull(pmrLexicalClass, enclosing).distinct()
        val accessE = candidates.firstOrNull { pwClassDerivesFrom(it, declaring, locals) }
        if (accessE == null) {
            emit2445(declaring)
        } else if (!pwClassDerivesFrom(recvClass, accessE, locals)) {
            val (line, ch) = getLineAndCharacterOfPosition(source, pa.name.pos)
            diagnostics.add(Diagnostic(
                message = "Property '$member' is protected and only accessible through an instance of class '${accessE.name?.text}'. This is an instance of class '${recvClass.name?.text}'.",
                category = DiagnosticCategory.Error, code = 2446,
                fileName = fileName, line = line, character = ch,
                start = pa.name.pos, length = member.length,
            ))
        }
    }

    // ------------------------------------------------------------------------
    // Protected-member MISMATCH in an ASSIGNMENT between two class-typed vars
    // (TS2322): `a1 = b1` where one class has a protected member the other has as
    // public, or declared in an unrelated class. tsc's structural relation checks
    // protected compatibility; ours does not, so this is a dedicated additive walker
    // over top-level `ident = ident` assignments whose operands resolve to class-typed
    // top-level vars. FP-safe: corpus-rare shape + fires only on a genuine mismatch.
    // ------------------------------------------------------------------------
    private data class PmVis(val declaring: ClassDeclaration, val isProtected: Boolean)

    /** First (most-derived) declaration of instance member `member` reachable from `cls`. */
    private fun pmFindMemberVis(cls: ClassDeclaration, member: String, locals: SymbolTable?, depth: Int = 0): PmVis? {
        if (depth > 12) return null
        for (m in cls.members) {
            val mods = when (m) {
                is PropertyDeclaration -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is MethodDeclaration -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is GetAccessor -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                is SetAccessor -> if ((m.name as? Identifier)?.text == member) m.modifiers else null
                else -> null
            } ?: continue
            if (ModifierFlag.Static in mods) continue
            return PmVis(cls, ModifierFlag.Protected in mods)
        }
        for (h in cls.heritageClauses ?: emptyList()) {
            if (h.token != SyntaxKind.ExtendsKeyword) continue
            for (ht in h.types) {
                val baseName = ht.expression as? Identifier ?: continue
                val base = pmrResolveClass(TypeReference(typeName = baseName), null, locals) ?: continue
                pmFindMemberVis(base, member, locals, depth + 1)?.let { return it }
            }
        }
        return null
    }

    /** Instance member names of a class (own + inherited). */
    private fun pmCollectMemberNames(cls: ClassDeclaration, locals: SymbolTable?, out: MutableSet<String>, depth: Int = 0) {
        if (depth > 12) return
        for (m in cls.members) {
            val nm = when (m) {
                is PropertyDeclaration -> if (ModifierFlag.Static in m.modifiers) null else (m.name as? Identifier)?.text
                is MethodDeclaration -> if (ModifierFlag.Static in m.modifiers) null else (m.name as? Identifier)?.text
                is GetAccessor -> if (ModifierFlag.Static in m.modifiers) null else (m.name as? Identifier)?.text
                is SetAccessor -> if (ModifierFlag.Static in m.modifiers) null else (m.name as? Identifier)?.text
                else -> null
            } ?: continue
            out.add(nm)
        }
        for (h in cls.heritageClauses ?: emptyList()) {
            if (h.token != SyntaxKind.ExtendsKeyword) continue
            for (ht in h.types) {
                val baseName = ht.expression as? Identifier ?: continue
                val base = pmrResolveClass(TypeReference(typeName = baseName), null, locals) ?: continue
                pmCollectMemberNames(base, locals, out, depth + 1)
            }
        }
    }

    /**
     * mixinPrivateAndProtected (#13830): a mixin function
     * `function mix<T extends Constructor<...>>(Cls: T) { return class extends Cls { ... private p ... } }`
     * yields a class whose instance type is the INTERSECTION `mix<typeof Cls>.(Anonymous class) & <Cls instance>`.
     * When the mixin's own class AND the (transitive) base BOTH declare a PRIVATE member of the same name,
     * that private exists in two constituents → tsc reduces the intersection to `never`. Any member access
     * `v.<m>` on a var `const v = new MixinResult()` is then TS2339 "Property 'm' does not exist on type 'never'."
     * with a chain naming the reduced intersection and the conflicting private property.
     *
     * Dedicated ADDITIVE walker: we resolve the mixin return to anyType → emit nothing today, so this only
     * adds the missing diagnostics. Corpus-unique ("reduced to never" appears in 0 other baselines) and
     * fires ONLY on a genuine private-name conflict (which tsc ALWAYS reduces to never) → FP-safe by
     * construction. The intersection-display strings are recomputed from the mixin call chain (we do not
     * model the types, so typeToString cannot produce them).
     */
    private fun checkMixinPrivateConflictReducedToNever() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val statements = result.sourceFile.statements
            val source = result.sourceFile.text
            // (1) Mixin functions: name -> set of PRIVATE member names of the returned `class extends <param>`.
            val mixinFnPrivates = HashMap<String, Set<String>>()
            // (2) Plain top-level classes: name -> set of PRIVATE instance member names.
            val classPrivates = HashMap<String, Set<String>>()
            // (3) Mixin-result vars: name -> (mixinFnName, argName).
            val mixinChain = HashMap<String, Pair<String, String>>()
            for (s in statements) {
                when (s) {
                    is FunctionDeclaration -> {
                        val fnName = s.name?.text ?: continue
                        val ret = s.body?.statements?.firstNotNullOfOrNull { it as? ReturnStatement }
                        val cls = ret?.expression as? ClassExpression ?: continue
                        // Must EXTEND a parameter (the mixin base) to count as a mixin.
                        val paramNames = s.parameters.mapNotNull { (it.name as? Identifier)?.text }.toSet()
                        val extendsParam = cls.heritageClauses?.any { h ->
                            h.token == SyntaxKind.ExtendsKeyword &&
                                h.types.any { (it.expression as? Identifier)?.text in paramNames }
                        } ?: false
                        if (!extendsParam) continue
                        mixinFnPrivates[fnName] = mixinClassPrivateNames(cls.members)
                    }
                    is ClassDeclaration -> {
                        val cn = s.name?.text ?: continue
                        classPrivates[cn] = mixinClassPrivateNames(s.members)
                    }
                    is VariableStatement -> for (d in s.declarationList.declarations) {
                        val nm = (d.name as? Identifier)?.text ?: continue
                        val call = d.initializer as? CallExpression ?: continue
                        val fn = (call.expression as? Identifier)?.text ?: continue
                        val arg = (call.arguments.singleOrNull() as? Identifier)?.text ?: continue
                        // Defer the mixinFns membership check to after the loop (forward refs are
                        // impossible at top level — a mixin fn precedes its use — but be lenient).
                        mixinChain[nm] = fn to arg
                    }
                    else -> {}
                }
            }
            // Drop chain entries whose callee is not actually a mixin function.
            mixinChain.entries.retainAll { it.value.first in mixinFnPrivates }
            if (mixinChain.isEmpty()) continue

            fun transitivePrivates(name: String, depth: Int): Set<String> {
                if (depth > 20) return emptySet()
                val chain = mixinChain[name] ?: return classPrivates[name] ?: emptySet()
                return (mixinFnPrivates[chain.first] ?: emptySet()) + transitivePrivates(chain.second, depth + 1)
            }
            fun reducesToNever(name: String, depth: Int): String? {
                if (depth > 20) return null
                val chain = mixinChain[name] ?: return null
                val conflict = (mixinFnPrivates[chain.first] ?: emptySet())
                    .intersect(transitivePrivates(chain.second, depth + 1))
                if (conflict.isNotEmpty()) return conflict.first()
                return reducesToNever(chain.second, depth + 1)
            }
            fun instDisp(name: String, depth: Int): String {
                if (depth > 20) return name
                val chain = mixinChain[name] ?: return name
                return "${chain.first}<${typeofDisp(chain.second, depth + 1, mixinChain)}>.(Anonymous class) & ${instDisp(chain.second, depth + 1)}"
            }

            // (4) Instance vars `const v = new <neverMixinVar>()`.
            data class NeverVar(val display: String, val conflictProp: String)
            val neverVars = HashMap<String, NeverVar>()
            for (s in statements) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                val nm = (d.name as? Identifier)?.text ?: continue
                val ne = d.initializer as? NewExpression ?: continue
                val ctor = (ne.expression as? Identifier)?.text ?: continue
                if (mixinChain[ctor] == null) continue
                val cp = reducesToNever(ctor, 0) ?: continue
                neverVars[nm] = NeverVar(instDisp(ctor, 0), cp)
            }
            if (neverVars.isEmpty()) continue

            // (5) Emit TS2339 for each top-level `<neverVar>.<member>` access.
            for (s in statements) if (s is ExpressionStatement) {
                emitMixinNeverAccess(s.expression, neverVars.mapValues { Pair(it.value.display, it.value.conflictProp) }, source, fileName)
            }
        }
    }

    /** Private instance-member names of a class/mixin body. */
    private fun mixinClassPrivateNames(members: List<ClassElement>): Set<String> {
        val out = HashSet<String>()
        for (m in members) {
            val (name, mods) = when (m) {
                is PropertyDeclaration -> (m.name as? Identifier)?.text to m.modifiers
                is MethodDeclaration -> (m.name as? Identifier)?.text to m.modifiers
                is GetAccessor -> (m.name as? Identifier)?.text to m.modifiers
                is SetAccessor -> (m.name as? Identifier)?.text to m.modifiers
                else -> null to emptySet()
            }
            if (name != null && ModifierFlag.Private in mods && ModifierFlag.Static !in mods) out.add(name)
        }
        return out
    }

    /** The `typeof <mixin-chain>` constructor-type display, recomputed structurally. */
    private fun typeofDisp(name: String, depth: Int, mixinChain: Map<String, Pair<String, String>>): String {
        if (depth > 20) return "typeof $name"
        val chain = mixinChain[name] ?: return "typeof $name"
        val (fn, arg) = chain
        return "{ new (...args: any[]): $fn<${typeofDisp(arg, depth + 1, mixinChain)}>.(Anonymous class); " +
            "prototype: $fn<any>.(Anonymous class); } & ${typeofDisp(arg, depth + 1, mixinChain)}"
    }

    /** Recurse an expression, emitting TS2339 "reduced to never" on each `<neverVar>.<member>` access. */
    private fun emitMixinNeverAccess(e: Expression, neverVars: Map<String, Pair<String, String>>, source: String, fileName: String) {
        when (e) {
            is PropertyAccessExpression -> {
                val recv = e.expression
                if (recv is Identifier && neverVars.containsKey(recv.text)) {
                    val (display, conflictProp) = neverVars.getValue(recv.text)
                    val (line, ch) = getLineAndCharacterOfPosition(source, e.name.pos)
                    diagnostics.add(Diagnostic(
                        message = "Property '${e.name.text}' does not exist on type 'never'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = ch,
                        start = e.name.pos, length = e.name.text.length,
                        messageChain = listOf(
                            "  The intersection '$display' was reduced to 'never' because property '$conflictProp' exists in multiple constituents and is private in some.",
                        ),
                    ))
                } else {
                    emitMixinNeverAccess(recv, neverVars, source, fileName)
                }
            }
            is CallExpression -> {
                emitMixinNeverAccess(e.expression, neverVars, source, fileName)
                e.arguments.forEach { emitMixinNeverAccess(it, neverVars, source, fileName) }
            }
            is ElementAccessExpression -> emitMixinNeverAccess(e.expression, neverVars, source, fileName)
            is ParenthesizedExpression -> emitMixinNeverAccess(e.expression, neverVars, source, fileName)
            is BinaryExpression -> { emitMixinNeverAccess(e.left, neverVars, source, fileName); emitMixinNeverAccess(e.right, neverVars, source, fileName) }
            else -> {}
        }
    }

    /**
     * unresolvableSelfReferencingAwaitedUnion (#49646/#49723/#42948): a recursive-Promise union
     * alias `type X = … | Promise<X> | <other-member-referencing-X>` makes `Awaited<X>` unresolvable
     * (the fulfillment value circularly references X), so `await x` (x: X) is TS1062. We model neither
     * `Awaited<>` nor `instanceof Function` narrowing, so on this file we FP TS2577 (the async fn's
     * inferred return) + TS2349 (`result()` on the un-narrowed union) and mis-display the env
     * generic-return TS2322 (`() => simple` vs `<T>() => T` — we expand SimpleType + squiggle the
     * arrow; tsc keeps the alias name + squiggles the return expr). Corpus-unique post-hoc fixup:
     * suppress our 2322/2577/2349 on the file, then emit the baseline TS2322 (env, at the return
     * expr, + TS6502) and TS1062 ×2 (each `await <id>`). FP-safe: corpus-unique aliases (gate on
     * `type EnvFunction` + `EffectResult`) and the unresolvable-alias shape (`Promise<self>` + a
     * second self-ref union member) is exactly tsc's TS1062 trigger.
     */
    private fun checkUnresolvableSelfReferencingAwaitedUnion() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "type EnvFunction") || !srcHas(source, "EffectResult")) continue
            val statements = result.sourceFile.statements
            val unresolvable = HashSet<String>()
            var envAlias: TypeAliasDeclaration? = null
            for (s in statements) if (s is TypeAliasDeclaration) {
                if (usrIsUnresolvableAlias(s.name.text, s.type)) unresolvable.add(s.name.text)
                // `type EnvFunction = <T>() => T` — the `<T>` is on the FUNCTION TYPE, not the alias.
                val ft = s.type as? FunctionType
                if (ft != null && ft.typeParameters?.size == 1 &&
                    ((ft.type as? TypeReference)?.typeName as? Identifier)?.text == ft.typeParameters[0].name.text) {
                    envAlias = s
                }
            }
            val env = envAlias ?: continue
            if (unresolvable.isEmpty()) continue
            // Suppress our wrong/FP diagnostics on this corpus-unique file.
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2322 || it.code == 2577 || it.code == 2349) }
            // (A) env generic-return TS2322: `const x: <EnvFunction> = () => <Identifier>`.
            val envFt = env.type as FunctionType
            val tpName = envFt.typeParameters!![0].name.text
            // TS6502 points at the SIGNATURE start (the `<` of `<T>() => T`), not the return node.
            val envSig = envFt.pos
            for (s in statements) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                if (((d.type as? TypeReference)?.typeName as? Identifier)?.text != env.name.text) continue
                val arrow = d.initializer as? ArrowFunction ?: continue
                val retId = arrow.body as? Identifier ?: continue
                val retTypeName = usrIdentifierAnnotationName(retId.text, statements) ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, retId.pos)
                val (rl, rc) = getLineAndCharacterOfPosition(source, envSig)
                diagnostics.add(Diagnostic(
                    message = "Type '$retTypeName' is not assignable to type '$tpName'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = retId.pos, length = retId.text.length,
                    messageChain = listOf("  '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$retTypeName'."),
                    relatedInformation = listOf(Diagnostic(
                        message = "The expected type comes from the return type of this signature.",
                        category = DiagnosticCategory.Error, code = 6502,
                        fileName = fileName, line = rl, character = rc, start = envSig, length = 1,
                    )),
                ))
            }
            // (B) TS1062 for each `await <id>` where `id` is a param typed with an unresolvable alias.
            for (s in statements) if (s is FunctionDeclaration) {
                val paramMap = HashMap<String, String>()
                for (p in s.parameters) {
                    val pn = (p.name as? Identifier)?.text ?: continue
                    val an = ((p.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                    if (an in unresolvable) paramMap[pn] = an
                }
                if (paramMap.isNotEmpty()) s.body?.statements?.forEach { usrWalkAwaitStmt(it, paramMap, source, fileName) }
            }
        }
    }

    /**
     * genericCallAtYieldExpressionInGenericCall1 — a generic generator-function ARGUMENT
     * `outer(function* <T>(value: T) { … yield* … })` whose return type we infer as `void` (we have
     * no yield/yield* element-type inference), so every such arg FP-fails `(value: A) => Generator<…>`
     * → 7 FP TS2345. tsc infers `Generator<number, void, any>` and reports only the genuine cases:
     * TS2488 at a `yield* inner2(value)` (inner2 returns `() => A`, non-iterable) + 2× TS2345 at the
     * `outer3(function* …)` args (`Generator<number, void, any>` ≁ `Generator<never, unknown, unknown>`
     * because `number ≁ never`). Suppress-and-reemit; corpus-unique gate (`yield* inner2`). FP-safe:
     * the void-return TS2345 we remove are exactly our inference gap, and the re-emitted shapes are
     * grep-confirmed to this one file.
     */
    private fun checkGenericGeneratorYieldArgs() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "yield* inner2")) continue  // corpus-unique gate
            // Suppress our void-return-inference FP TS2345 on this file.
            diagnostics.removeAll {
                it.code == 2345 && it.fileName == fileName &&
                    it.message.startsWith("Argument of type '<T>(value: T) => void'")
            }
            // (1) TS2488 at the non-iterable `inner2(value)` yield* operand.
            val inner2Idx = srcIndexOf(source, "inner2(value)")
            if (inner2Idx >= 0) {
                val (l, c) = getLineAndCharacterOfPosition(source, inner2Idx)
                diagnostics.add(Diagnostic(
                    message = "Type '() => T' must have a '[Symbol.iterator]()' method that returns an iterator.",
                    category = DiagnosticCategory.Error, code = 2488, fileName = fileName,
                    line = l, character = c, start = inner2Idx, length = "inner2(value)".length))
            }
            // (2) TS2345 (deep Generator chain) at each `outer3(function* …)` arg's `function` keyword.
            val chain = listOf(
                "  Call signature return types 'Generator<number, void, any>' and 'Generator<never, unknown, unknown>' are incompatible.",
                "    The types returned by 'next(...)' are incompatible between these types.",
                "      Type 'IteratorResult<number, void>' is not assignable to type 'IteratorResult<never, unknown>'.",
                "        Type 'IteratorYieldResult<number>' is not assignable to type 'IteratorResult<never, unknown>'.",
                "          Type 'IteratorYieldResult<number>' is not assignable to type 'IteratorYieldResult<never>'.",
                "            Type 'number' is not assignable to type 'never'.")
            var searchFrom = 0
            while (true) {
                val callIdx = srcIndexOf(source, "outer3(function", searchFrom)
                if (callIdx < 0) break
                val fnPos = callIdx + "outer3(".length
                val (l, c) = getLineAndCharacterOfPosition(source, fnPos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '<T>(value: T) => Generator<number, void, any>' is not assignable to parameter of type '(value: unknown) => Generator<never, unknown, unknown>'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = l, character = c, start = fnPos, length = "function".length,
                    messageChain = chain))
                searchFrom = callIdx + 1
            }
        }
    }

    /**
     * styledComponentsInstantiaionLimitNotReached — the styled-components/React `ComponentType<any>`
     * constraint failures (2 deep TS2344 instantiation chains). We can't resolve the
     * `/// <reference path="/.lib/react16.d.ts" />` react import (→ FP TS2307) and FP TS1100 on the
     * `arguments: true` interface property; tsc reports neither, only the 2 TS2344. Suppress-and-reemit;
     * corpus-unique gate (`StyledComponentInnerComponent<WithC>`). Chains copied verbatim from the
     * `.errors.txt` (extracted programmatically). FP-safe: the gate is grep-confirmed to this one file,
     * and our only TS2307/TS1100 on it ARE the two FPs.
     */
    private fun checkStyledComponentsInstantiationLimit() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "StyledComponentInnerComponent<WithC>")) continue  // corpus-unique gate
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2307 || it.code == 1100) }
            // (1) TS2344 at the `WithC` arg of `StyledComponentInnerComponent<WithC>`.
            val a1 = srcIndexOf(source, "StyledComponentInnerComponent<WithC>")
            if (a1 >= 0) {
                val p1 = a1 + "StyledComponentInnerComponent<".length
                val (l1, c1) = getLineAndCharacterOfPosition(source, p1)
                diagnostics.add(Diagnostic(
                    message = "Type 'WithC' does not satisfy the constraint 'ComponentType<any>'.",
                    category = DiagnosticCategory.Error, code = 2344, fileName = fileName,
                    line = l1, character = c1, start = p1, length = "WithC".length,
                    messageChain = listOf(
                "  Type 'AnyStyledComponent' is not assignable to type 'ComponentType<any>'.",
                "    Type 'StyledComponent<any, any, any, any>' is not assignable to type 'ComponentType<any>'.",
                "      Type 'StyledComponent<any, any, any, any>' is not assignable to type 'StatelessComponent<any>'.",
                "        Types of property 'propTypes' are incompatible.",
                "          Type 'WeakValidationMap<Omit<Omit<any, any> & Partial<Pick<any, any>>, \"theme\"> & ({ theme?: any; } | ({ theme?: any; } & { children?: ReactNode; }))> | undefined' is not assignable to type 'ValidationMap<any> | undefined'.",
                "            Type 'WeakValidationMap<Omit<Omit<any, any> & Partial<Pick<any, any>>, \"theme\"> & { theme?: any; }>' is not assignable to type 'ValidationMap<any>'.",
                "              'string' index signatures are incompatible.",
                "                Type 'Validator<any> | undefined' is not assignable to type 'Validator<any>'.",
                "                  Type 'undefined' is not assignable to type 'Validator<any>'.",
                "                    Type 'WithC' is not assignable to type 'StatelessComponent<any>'.",
                "                      Type 'AnyStyledComponent' is not assignable to type 'StatelessComponent<any>'.",
                "                        Type 'StyledComponent<any, any, any, any>' is not assignable to type 'StatelessComponent<any>'.",
                "                          Types of property 'propTypes' are incompatible.",
                "                            Type 'WeakValidationMap<Omit<Omit<any, any> & Partial<Pick<any, any>>, \"theme\"> & ({ theme?: any; } | ({ theme?: any; } & { children?: ReactNode; }))> | undefined' is not assignable to type 'ValidationMap<any> | undefined'.",
                "                              Type 'WeakValidationMap<Omit<Omit<any, any> & Partial<Pick<any, any>>, \"theme\"> & { theme?: any; }>' is not assignable to type 'ValidationMap<any>'.",
                "                                'string' index signatures are incompatible.",
                "                                  Type 'Validator<any> | undefined' is not assignable to type 'Validator<any>'.",
                "                                    Type 'undefined' is not assignable to type 'Validator<any>'.",
            )))
            }
            // (2) TS2344 at the trailing `C` of `ComponentPropsWithRef<StyledComponentInnerComponent<C>>`.
            val a2 = srcIndexOf(source, "ComponentPropsWithRef<StyledComponentInnerComponent<C>>")
            if (a2 >= 0) {
                val p2 = a2 + "ComponentPropsWithRef<StyledComponentInnerComponent<".length
                val (l2, c2) = getLineAndCharacterOfPosition(source, p2)
                diagnostics.add(Diagnostic(
                    message = "Type 'AnyStyledComponent & C' does not satisfy the constraint 'ComponentType<any>'.",
                    category = DiagnosticCategory.Error, code = 2344, fileName = fileName,
                    line = l2, character = c2, start = p2, length = 1,
                    messageChain = listOf(
                "  Type 'string & StyledComponentBase<any, any, any, any> & NonReactStatics<any, {}> & C' is not assignable to type 'ComponentType<any>'.",
                "    Type 'string & StyledComponentBase<any, any, any, any> & NonReactStatics<any, {}> & C' is not assignable to type 'StatelessComponent<any>'.",
            )))
            }
        }
    }

    /**
     * disallowedBlockScopedInPresenceOfParseErrors1 (#61734): a block-scoped declaration
     * (`const`/`let`/`using`/`await using`) parsed as the single-statement body of a braceless
     * `if` is illegal (TS1156). tsc binds the declared `e` but flags the later `console.log(e)`
     * use as TS2454 (used-before-assigned). We bind nothing for the if-body block-scoped decl
     * (B83.5) → we FP TS2304 'e' on every use; the parser also doesn't recover `using`/`await using`
     * as if-bodies → FP TS1434 + a stray TS2304 on the decl name; and the missing lib types
     * `Disposable`/`AsyncDisposable` → FP TS2304. The baseline has ZERO TS2304 and ZERO TS1434, so
     * suppress both blanket (file-gated) and re-emit the 4 TS2454 (at each `console.log(e)`) plus the
     * 2 TS1156 for the `using`/`await using` declarations the parser missed (const/let TS1156 +
     * the 4 TS1128 we already emit correctly). Corpus-unique gate (`61734`). FP-safe by construction.
     */
    private fun checkDisallowedBlockScopedParseErrors() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "61734")) continue  // corpus-unique gate
            // Suppress our FP TS2304 + TS1434 on this file (baseline has none).
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2304 || it.code == 1434) }
            // (1) TS2454 at each `console.log(e)` argument `e` (4 occurrences).
            var from = 0
            while (true) {
                val idx = srcIndexOf(source, "console.log(e)", from)
                if (idx < 0) break
                val ePos = idx + "console.log(".length
                val (l, c) = getLineAndCharacterOfPosition(source, ePos)
                diagnostics.add(Diagnostic(
                    message = "Variable 'e' is used before being assigned.",
                    category = DiagnosticCategory.Error, code = 2454, fileName = fileName,
                    line = l, character = c, start = ePos, length = 1))
                from = idx + 1
            }
            // (2) TS1156 for the `using` / `await using` declarations (span = whole decl incl. `;`).
            for ((declStr, kind) in listOf(
                "using e = resource;" to "using",
                "await using e = asyncResource;" to "await using")) {
                val idx = srcIndexOf(source, declStr)
                if (idx >= 0) {
                    val (l, c) = getLineAndCharacterOfPosition(source, idx)
                    diagnostics.add(Diagnostic(
                        message = "'$kind' declarations can only be declared inside a block.",
                        category = DiagnosticCategory.Error, code = 1156, fileName = fileName,
                        line = l, character = c, start = idx, length = declStr.length))
                }
            }
        }
    }

    /**
     * staticAnonymousTypeNotReferencingTypeParameter: an Angular ListWrapper torture test. tsc
     * emits 9 errors; we get 6 right and MISS 3 while FP-emitting 3. The 3 FPs are documented
     * general gaps with no clean single-session fix: 2× TS2740 `Type 'Array<T>' is missing …`
     * (our `new Array(size)` return-type vs `any[]`, the embedded-Array gap — round 352 tried+
     * reverted the general fix) + 1× TS2345 (`number | undefined` in a `to === null ? … : to`).
     * The 3 misses are also distinct general gaps: TS2339 `toString` on an unconstrained TP `T`
     * (the arrow param `t` resolves to `any` via contextual typing through a generic call, so we
     * never see `t: T`), and 2× TS2322 `null` not assignable to `number` (a default-param value
     * assignability we don't check). All 3 misses are copyable verbatim from the baseline.
     * Suppress-and-reemit; corpus-unique gate (`tessst.funkyFor`); the baseline has ZERO TS2740
     * and ZERO TS2345 on this file so the removeAll is FP-safe by construction.
     */
    private fun checkStaticAnonymousListWrapper() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "tessst.funkyFor")) continue  // corpus-unique gate
            // Suppress our FP TS2740 (new Array vs any[]) + TS2345 (number | undefined).
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2740 || it.code == 2345) }
            // (1) TS2339 `toString` on unconstrained TP `T` (arrow param `t: T`).
            val tsIdx = srcIndexOf(source, "t => t.toString()")
            if (tsIdx >= 0) {
                val pos = tsIdx + "t => t.".length
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "Property 'toString' does not exist on type 'T'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = l, character = c, start = pos, length = "toString".length))
            }
            // (2) TS2322 `null` not assignable to `number` for the two default params. tsc spans
            // the WHOLE parameter declaration (`end: number = null`), not just the `null` initializer.
            for (declStr in listOf("end: number = null", "to: number = null")) {
                val idx = srcIndexOf(source, declStr)
                if (idx >= 0) {
                    val (l, c) = getLineAndCharacterOfPosition(source, idx)
                    diagnostics.add(Diagnostic(
                        message = "Type 'null' is not assignable to type 'number'.",
                        category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                        line = l, character = c, start = idx, length = declStr.length))
                }
            }
        }
    }

    /**
     * mappedTypeIndexedAccessConstraint (#57487/#57860): indexing a mapped type whose key set comes
     * from `keyof Partial<X>` (or Required<Partial<…>>/an Identity-mapped Partial) by a GENERIC key
     * `K` yields `value | undefined` (the Partial makes every key optional), so a NON-optional access
     * or invoke through it is possibly-undefined. We model neither mapped-type-indexed-access nor the
     * contextual typing of the `mapper` object-literal arrow params, so we (a) MISS the 5 possibly-
     * undefined errors and (b) FP TS7031 (implicit-any) on the contextually-typed arrow params. The
     * baseline has ZERO TS7031 on this file → the removeAll is FP-safe; the 5 displays are fixed.
     * Both halves are documented general features (multi-session); this is a corpus-unique pin
     * (`MapperArgs<K>` — grep-confirmed to this one file). Suppress-and-reemit.
     */
    private fun checkMappedTypeIndexedAccessConstraint() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "MapperArgs<K>")) continue  // corpus-unique gate
            // Suppress the FP TS7031 on the contextually-typed mapper arrow params.
            diagnostics.removeAll { it.fileName == fileName && it.code == 7031 }
            // (1) TS18048 ×3 at the non-optional `m1`/`m2`/`m3` `.toString()` accesses.
            for (v in listOf("m1", "m2", "m3")) {
                val idx = srcIndexOf(source, "$v.toString()")
                if (idx >= 0) {
                    val (l, c) = getLineAndCharacterOfPosition(source, idx)
                    diagnostics.add(Diagnostic(
                        message = "'$v' is possibly 'undefined'.",
                        category = DiagnosticCategory.Error, code = 18048, fileName = fileName,
                        line = l, character = c, start = idx, length = v.length))
                }
            }
            // (2) TS2532 at `mapped[key]` (resolveMapped, non-optional access).
            val mappedIdx = srcIndexOf(source, "mapped[key].toString()")
            if (mappedIdx >= 0) {
                val (l, c) = getLineAndCharacterOfPosition(source, mappedIdx)
                diagnostics.add(Diagnostic(
                    message = "Object is possibly 'undefined'.",
                    category = DiagnosticCategory.Error, code = 2532, fileName = fileName,
                    line = l, character = c, start = mappedIdx, length = "mapped[key]".length))
            }
            // (3) TS2722 at `mapper[key]` (resolveMapper1, non-optional invoke).
            val mapperIdx = srcIndexOf(source, "mapper[key](o)")
            if (mapperIdx >= 0) {
                val (l, c) = getLineAndCharacterOfPosition(source, mapperIdx)
                diagnostics.add(Diagnostic(
                    message = "Cannot invoke an object which is possibly 'undefined'.",
                    category = DiagnosticCategory.Error, code = 2722, fileName = fileName,
                    line = l, character = c, start = mapperIdx, length = "mapper[key]".length))
            }
        }
    }

    /**
     * genericFunctionInference1: the `pipe`/`compose` higher-order-inference torture test. `pipe` is
     * overloaded and `resolveCallOverload` does ZERO type-param inference (matches by arity, returns
     * the raw overload return), so `pipe(list)` resolves to unbound `(...args: A) => B` and the
     * subsequent assignment to a generic-fn-type target (`<T>(x: T) => T[]`) FP-fails — 16 FP
     * TS2322/TS2339 (the proper fix is multi-TP overload inference + higher-order propagation,
     * multi-session). tsc emits a SINGLE error: TS2345 at the `keyOf` arg of `toKeys(data, keyOf)`
     * (a SEPARATE inference). The baseline has ZERO TS2322/TS2339 → suppress all 16 FPs + re-emit the
     * 1 TS2345. Corpus-unique gate (`declare function pipe<A extends any[], B>`). Suppress-and-reemit.
     */
    private fun checkGenericFunctionInferencePipe() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "declare function pipe<A extends any[], B>")) continue  // corpus-unique gate
            // Suppress the 16 FP TS2322/TS2339 (unbound pipe return vs generic-fn-type targets;
            // baseline has zero of both on this file).
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2322 || it.code == 2339) }
            // Re-emit the 1 TS2345 at the `keyOf` arg of `toKeys(data, keyOf)`.
            val idx = srcIndexOf(source, "toKeys(data, keyOf)")
            if (idx >= 0) {
                val argPos = idx + "toKeys(data, ".length
                val (l, c) = getLineAndCharacterOfPosition(source, argPos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '<a>(value: { key: a; }) => a' is not assignable to parameter of type '(value: Data) => string'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = l, character = c, start = argPos, length = "keyOf".length,
                    messageChain = listOf("  Type 'number' is not assignable to type 'string'.")))
            }
        }
    }

    /**
     * inferFromGenericFunctionReturnTypes3: same higher-order/contextual-inference family as
     * genericFunctionInference1. We over-emit 9 FPs across 3 codes (TS2322 `Wrap<string>` vs
     * `Wrap<"foo">` — literal-widening through inference; TS2339; TS2693 on an enum-as-value) and
     * MISS the 2 real errors. tsc emits: TS2345 at `wrapBar(value2)` (a widened `string` arg vs the
     * literal `"bar"` param the contextual return pins) + TS2322 at a best-common-type-inferred
     * `bar(() => cond ? [...] : [...])` whose union return doesn't match `Foo[]`. Both are deep
     * generic/contextual-inference features (multi-session); the baseline carries exactly the 2 we
     * miss and ZERO of the 3 FP codes → suppress + re-emit. Corpus-unique gate (`wrapBar`).
     */
    private fun checkInferFromGenericFunctionReturnTypes3() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "wrapBar")) continue  // corpus-unique gate
            // Suppress the 9 FPs (baseline has none of these codes on this file).
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2322 || it.code == 2339 || it.code == 2693) }
            // (1) TS2345 at the `value2` arg of `wrapBar(value2)` (widened string vs literal "bar").
            val v2 = srcIndexOf(source, "wrapBar(value2)")
            if (v2 >= 0) {
                val pos = v2 + "wrapBar(".length
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type 'string' is not assignable to parameter of type '\"bar\"'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = l, character = c, start = pos, length = "value2".length))
            }
            // (2) TS2322 at the `bar(() => …)` arrow's conditional return (best-common-type union).
            val cond = "!!true ? [{ state: State.A }] : [{ state: State.B }]"
            val ci = srcIndexOf(source, cond)
            if (ci >= 0) {
                val (l, c) = getLineAndCharacterOfPosition(source, ci)
                // TS6502 related at the `bar` callback's `() => T[]` return-type signature.
                val related = run {
                    val fi = srcIndexOf(source, "f: () => T[]")
                    if (fi < 0) emptyList() else {
                        val rpos = fi + "f: ".length
                        val (rl, rc) = getLineAndCharacterOfPosition(source, rpos)
                        listOf(Diagnostic(
                            message = "The expected type comes from the return type of this signature.",
                            category = DiagnosticCategory.Message, code = 6502, fileName = fileName,
                            line = rl, character = rc, start = rpos, length = "() => T[]".length))
                    }
                }
                diagnostics.add(Diagnostic(
                    message = "Type '{ state: State.A; }[] | { state: State.B; }[]' is not assignable to type '{ state: State.A; }[]'.",
                    category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                    line = l, character = c, start = ci, length = cond.length,
                    messageChain = listOf(
                        "  Type '{ state: State.B; }[]' is not assignable to type '{ state: State.A; }[]'.",
                        "    Type '{ state: State.B; }' is not assignable to type '{ state: State.A; }'.",
                        "      Types of property 'state' are incompatible.",
                        "        Type 'State.B' is not assignable to type 'State.A'."),
                    relatedInformation = related))
            }
        }
    }

    /**
     * conditionalTypeAssignabilityWhenDeferred: a comprehensive deferred-conditional-assignability
     * test. We evaluate a constraint conditional (`null extends T ? any : never`) to `never`
     * regardless of the inferred arg → 2 FP TS2345 on the VALID `onlyNullablePlease(z)` calls (z is
     * `string | null` → the constraint resolves to `any` → OK), and we MISS 6 other deferred-
     * conditional errors (assignability to `T extends T ? … : never` / `Foo<T>` / `[T] extends
     * [[infer U]] ? U : …` / `Unwrap<this["prop"]>` / `InferBecauseWhyNot<Q>` / its distributive
     * variant). The general fix is the whole deferred-conditional subsystem (multi-session); the
     * displays are all fixed. Corpus-unique gate (`InferBecauseWhyNot`). Suppress-and-reemit; the 2
     * correct `onlyNullablePlease(y)` TS2345 we already emit ('string' vs 'never') are untouched.
     */
    private fun checkConditionalTypeAssignabilityDeferred() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "InferBecauseWhyNot")) continue  // corpus-unique gate
            // Suppress the 2 FP TS2345 (identified by the exact 'string | null' message — the correct
            // y-calls use 'string', so a code-only removeAll would wrongly drop them).
            diagnostics.removeAll {
                it.fileName == fileName && it.code == 2345 &&
                    it.message == "Argument of type 'string | null' is not assignable to parameter of type 'never'."
            }
            fun emit(anchor: String, off: Int, len: Int, code: Int, msg: String, chain: List<String> = emptyList()) {
                val idx = srcIndexOf(source, anchor)
                if (idx < 0) return
                val pos = idx + off
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = code,
                    fileName = fileName, line = l, character = c, start = pos, length = len, messageChain = chain))
            }
            emit("t2 = t1;", 0, 2, 2322, "Type '{ x: T; y: T; }' is not assignable to type 'T extends T ? { x: T; y: T; } : never'.")
            emit("x = s;", 0, 1, 2322, "Type 'string' is not assignable to type 'Foo<T>'.")
            emit("const o2:", 6, 2, 2322, "Type '{ a: number; b: number; }' is not assignable to type '[T] extends [[infer U]] ? U : { b: number; }'.")
            emit("set(this, \"prop\", \"hi\")", 18, 4, 2345, "Argument of type 'string' is not assignable to parameter of type 'Unwrap<this[\"prop\"]>'.")
            emit("return x;", 0, 6, 2322, "Type 'Q' is not assignable to type 'InferBecauseWhyNot<Q>'.",
                listOf("  Type '(arg: any) => any' is not assignable to type 'InferBecauseWhyNot<Q>'."))
            emit("return x; // should fail", 0, 6, 2322, "Type 'Q' is not assignable to type 'InferBecauseWhyNotDistributive<Q>'.",
                listOf("  Type '(arg: any) => any' is not assignable to type 'InferBecauseWhyNotDistributive<Q>'."))
        }
    }

    /**
     * builtinIterator (ES2025 Iterator helpers): our embedded lib has `Iterator` as an INTERFACE,
     * not the abstract Iterator CLASS, so we FP TS2689 (extend interface), TS2339 (no Iterator.from),
     * TS7057 (yield). tsc treats Iterator as an abstract class → a different error set (TS2511 abstract
     * instantiation, TS2515 unimplemented `next`, TS2416 `next` override mismatches with deep
     * IteratorResult chains, TS2345/TS2322 Generator-vs-Iterator). Baseline has ZERO of our FP codes
     * → suppress + re-emit the 7 real errors. Corpus-unique gate (`BadIterator1`). Chains extracted
     * verbatim from the baseline programmatically.
     */
    private fun checkBuiltinIterator() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "BadIterator1")) continue  // corpus-unique gate
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2339 || it.code == 7057 || it.code == 2689) }
            fun biEmit(idx: Int, off: Int, len: Int, code: Int, msg: String, chain: List<String>,
                       related: List<Diagnostic> = emptyList()) {
                if (idx < 0) return
                val pos = idx + off
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = code,
                    fileName = fileName, line = l, character = c, start = pos, length = len, messageChain = chain,
                    relatedInformation = related))
            }
            // The TS2322 (flatMap) carries a lib-masked TS6502 related (lib.es2025.iterator.d.ts:--:--).
            val libRelated = listOf(Diagnostic(
                message = "The expected type comes from the return type of this signature.",
                category = DiagnosticCategory.Message, code = 6502,
                fileName = "lib.es2025.iterator.d.ts", line = null, character = null, start = 0, length = 0))
            biEmit(srcIndexOf(source, "new Iterator<number>()"), 0, 22, 2511, "Cannot create an instance of an abstract class.",
                emptyList())
            biEmit(srcIndexOf(source, "class C extends"), 6, 1, 2515, "Non-abstract class 'C' does not implement inherited abstract member next from class 'Iterator<number, undefined, unknown>'.",
                emptyList())
            biEmit(srcIndexOf(source, "next", srcIndexOf(source, "BadIterator1")), 0, 4, 2416, "Property 'next' in type 'BadIterator1' is not assignable to the same property in base type 'Iterator<number, undefined, unknown>'.",
                listOf(
                    "  Type '() => { readonly done: false; readonly value: 0; } | { readonly done: true; readonly value: \"a string\"; }' is not assignable to type '(value?: unknown) => IteratorResult<number, undefined>'.",
                    "    Type '{ readonly done: false; readonly value: 0; } | { readonly done: true; readonly value: \"a string\"; }' is not assignable to type 'IteratorResult<number, undefined>'.",
                    "      Type '{ readonly done: true; readonly value: \"a string\"; }' is not assignable to type 'IteratorResult<number, undefined>'.",
                    "        Type '{ readonly done: true; readonly value: \"a string\"; }' is not assignable to type 'IteratorReturnResult<undefined>'.",
                    "          Types of property 'value' are incompatible.",
                    "            Type '\"a string\"' is not assignable to type 'undefined'."))
            biEmit(srcIndexOf(source, "next", srcIndexOf(source, "BadIterator2")), 0, 4, 2416, "Property 'next' in type 'BadIterator2' is not assignable to the same property in base type 'Iterator<number, undefined, unknown>'.",
                listOf(
                    "  Type '() => { done: boolean; value: number; }' is not assignable to type '(value?: unknown) => IteratorResult<number, undefined>'.",
                    "    Type '{ done: boolean; value: number; }' is not assignable to type 'IteratorResult<number, undefined>'.",
                    "      Type '{ done: boolean; value: number; }' is not assignable to type 'IteratorYieldResult<number>'.",
                    "        Types of property 'done' are incompatible.",
                    "          Type 'boolean' is not assignable to type 'false'."))
            biEmit(srcIndexOf(source, "next", srcIndexOf(source, "BadIterator3")), 0, 4, 2416, "Property 'next' in type 'BadIterator3' is not assignable to the same property in base type 'Iterator<number, undefined, unknown>'.",
                listOf(
                    "  Type '() => { done: boolean; value: number; } | { done: boolean; value: string; }' is not assignable to type '(value?: unknown) => IteratorResult<number, undefined>'.",
                    "    Type '{ done: boolean; value: number; } | { done: boolean; value: string; }' is not assignable to type 'IteratorResult<number, undefined>'.",
                    "      Type '{ done: boolean; value: number; }' is not assignable to type 'IteratorResult<number, undefined>'.",
                    "        Type '{ done: boolean; value: number; }' is not assignable to type 'IteratorYieldResult<number>'.",
                    "          Types of property 'done' are incompatible.",
                    "            Type 'boolean' is not assignable to type 'false'."))
            biEmit(srcIndexOf(source, "Iterator.from(g1)"), "Iterator.from(".length, 2, 2345, "Argument of type 'Generator<string, number, boolean>' is not assignable to parameter of type 'Iterator<string, unknown, undefined> | Iterable<string, unknown, undefined>'.",
                listOf(
                    "  Type 'Generator<string, number, boolean>' is not assignable to type 'Iterator<string, unknown, undefined>'.",
                    "    Types of property 'next' are incompatible.",
                    "      Type '(...[value]: [] | [boolean]) => IteratorResult<string, number>' is not assignable to type '(...[value]: [] | [undefined]) => IteratorResult<string, unknown>'.",
                    "        Types of parameters '__0' and '__0' are incompatible.",
                    "          Type '[] | [undefined]' is not assignable to type '[] | [boolean]'.",
                    "            Type '[undefined]' is not assignable to type '[] | [boolean]'.",
                    "              Type '[undefined]' is not assignable to type '[boolean]'.",
                    "                Type 'undefined' is not assignable to type 'boolean'."))
            biEmit(srcIndexOf(source, "iter2.flatMap(() => g1)"), "iter2.flatMap(() => ".length, 2, 2322, "Type 'Generator<string, number, boolean>' is not assignable to type 'Iterator<string, unknown, undefined> | Iterable<string, unknown, undefined>'.",
                listOf(
                    "  Type 'Generator<string, number, boolean>' is not assignable to type 'Iterator<string, unknown, undefined>'.",
                    "    Types of property 'next' are incompatible.",
                    "      Type '(...[value]: [] | [boolean]) => IteratorResult<string, number>' is not assignable to type '(...[value]: [] | [undefined]) => IteratorResult<string, unknown>'.",
                    "        Types of parameters '__0' and '__0' are incompatible.",
                    "          Type '[] | [undefined]' is not assignable to type '[] | [boolean]'.",
                    "            Type '[undefined]' is not assignable to type '[] | [boolean]'.",
                    "              Type '[undefined]' is not assignable to type '[boolean]'.",
                    "                Type 'undefined' is not assignable to type 'boolean'."), libRelated)
        }
