            // (JIT.1)(b): R_OT_PRE .. R_OT_IDENT -- the general receiver-type path.
            // Returns null where the original block `return`ed from the whole
            // function, and (objectType, displayTypeOverride) otherwise.
            val general = cmamGeneralReceiverType(
                objectExpr, propName, diagStart, diagLength, source, fileName,
                keySuggestion, suggestionKey, ts2576Start, ts2576Length,
            ) ?: return
            displayTypeOverride = general.second
            general.first
        }
        // (JIT.1)(b): R_TYPEGATE .. R_EMIT -- everything downstream of the receiver
        // type, ending in the emission tail.
        cmamCheckResolvedObjectType(
            objectExpr, objectType, displayTypeOverride, propName, diagStart, diagLength,
            source, fileName, isThisAccess, emitTs2728RelatedInfo,
        )
        } finally {
            CpaSections.endR()
        }
    }

    /**
     * (JIT.1)(b) round 804 — level-R sections `R_LITERAL` and `R_NEW`, verbatim.
     * Returns true where the original code returned from the whole function.
     */
    private fun cmamCheckLiteralAndNewReceiver(
        objectExpr: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        ts2576Start: Int,
        ts2576Length: Int,
    ): Boolean {
        // 17.161: String literal receiver — `"".bogus` / `"foo".missing`. Resolves
        // to the String apparent type and emits TS2339 with the literal value displayed
        // verbatim ("\"\"" / "\"foo\"") when the property isn't a String wrapper member.
        // Used by patterns like `class C extends "".bogus {}` where the heritage
        // expression is a PropertyAccessExpression on a StringLiteralNode receiver.
        CpaSections.atR(CpaSections.R_LITERAL)
        if (objectExpr is StringLiteralNode && propName !in RUNTIME_PROPERTIES) {
            val apparent = getApparentType(stringType)
            if (apparent is Type.Object) {
                resolveStructuredTypeMembers(apparent)
                val hasProp = getPropertyOfType(apparent, propName) != null
                if (!hasProp) {
                    val display = "\"" + (objectExpr.text) + "\""
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    // B241: a later-lib String member (LIB_MIN_TARGET-filtered or absent,
                    // e.g. padStart/trimLeft) gets TS2550 with the lib hint, not TS2339.
                    val minTarget = LIB_MIN_TARGET["String.$propName"]
                    if (minTarget != null && !libFeatureAvailable(minTarget)) {
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '$display'. Do you need to change your target library? Try changing the 'lib' compiler option to '${minTarget.name.lowercase()}' or later.",
                            category = DiagnosticCategory.Error, code = 2550,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return true
                    }
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$display'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                }
            }
            return true
        }

        // B241: regex-literal receiver (`/foo/g.dotAll`) — resolve via the RegExp
        // interface; TS2550-only for LIB_MIN_TARGET(_SOFT) members (no TS2339
        // fall-through — keeps the prior silent behavior for other names).
        if (objectExpr is RegularExpressionLiteralNode && propName !in RUNTIME_PROPERTIES) {
            val minTarget = LIB_MIN_TARGET["RegExp.$propName"] ?: LIB_MIN_TARGET_SOFT["RegExp.$propName"]
            if (minTarget != null && !libFeatureAvailable(minTarget)) {
                val regexpSym = globals["RegExp"]
                val userAugmented = regexpSym?.declarations?.any { it !in builtinLibDecls } == true
                if (!userAugmented) {
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type 'RegExp'. Do you need to change your target library? Try changing the 'lib' compiler option to '${minTarget.name.lowercase()}' or later.",
                        category = DiagnosticCategory.Error, code = 2550,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
        }

        // 17.115: Empty `{}` literal element/property access — emit TS2339 with display
        // `{}`. Squiggle uses the caller-provided ts2576SquiggleStart/Length (which covers
        // the full element-access expression for `{}["X"]` / `{}[N]`); for property-access
        // form `({}).hi` it falls back to the bare `.hi` span. Conservative gate: only
        // empty literals — non-empty literals have their own member set.
        if (objectExpr is ObjectLiteralExpression && objectExpr.properties.isEmpty()) {
            if (propName !in RUNTIME_PROPERTIES) {
                val (line, character) = getLineAndCharacterOfPosition(source, ts2576Start)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '{}'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = ts2576Start, length = ts2576Length,
                ))
            }
            return true
        }

        // 16.4cq: `new ClassName(...).prop` or `(new ClassName(...)).prop` — emit TS2339 when
        // the class is declared locally and neither declares the property itself nor inherits
        // a satisfying declaration. Narrow gate: handles the simple "empty class + circular
        // or empty base" pattern. Display uses `ClassName<unknown, unknown, …>` based on the
        // class's type-parameter count, matching TypeScript's format for un-instantiated news.
        CpaSections.atR(CpaSections.R_NEW)
        if (objectExpr is NewExpression) {
            val ctor = objectExpr.expression
            if (ctor is Identifier) {
                // B15.2: for namespace-nested `new C(...).prop` patterns, look up the
                // ctor symbol via the property-access namespace stack first — the
                // binder puts namespace-internal classes in `namespaceSymbol.exports`,
                // not directly in `globals`. Falls back to `globals` for top-level
                // classes (the original behavior).
                var ctorSym: Symbol? = null
                for (ns in propertyAccessEnclosingNamespaces.asReversed()) {
                    ctorSym = ns.exports?.get(ctor.text)
                    if (ctorSym != null) break
                }
                if (ctorSym == null) ctorSym = globals[ctor.text]
                if (ctorSym != null && ctorSym.flags.hasAny(SymbolFlags.Class)) {
                    // Skip when the class symbol has multiple declarations that could
                    // contribute INSTANCE members: an interface merge (or a second class /
                    // ambient re-declaration) adds instance properties the ClassDeclaration
                    // alone doesn't show. B184: a NAMESPACE merge contributes only STATIC
                    // members (the bifurcation model), so `class C2 {} namespace C2 {…}`
                    // keeps instance-side access checkable — `new C2().unrelated` is TS2339
                    // even though `C2.unrelated` (static side) is fine.
                    if (ctorSym.declarations.count { it is ClassDeclaration } > 1) return true
                    if (ctorSym.declarations.any { it !is ClassDeclaration && it !is ModuleDeclaration }) return true
                    val classDecl = ctorSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                    if (classDecl != null && propName !in RUNTIME_PROPERTIES) {
                        // Walk own members + extends chain. `false` means the chain
                        // resolves cleanly (no IndexSignature, no ambient base, no
                        // unresolvable extends expression) and the property is
                        // genuinely missing — fire TS2339. `true` means a base
                        // class declares it. `null` means the chain has parts we
                        // can't safely walk (complex extends like `Foo.Bar`,
                        // generic call form, ambient base, IndexSignature) — bail.
                        val chainResult = lookupInstanceMemberInResolvableChain(classDecl, propName)
                        val isCircular = classHasCircularBase(classDecl)
                        // B419: a JS-file class declares instance properties via
                        // `this.X = expr` in its constructor — those are real members
                        // (synthesized in resolveInterfaceMembersCore) even though they
                        // are not AST PropertyDeclarations, so the chain walk misses them.
                        val isJsExpando = classHasConstructorThisAssignment(classDecl, propName)
                        val canEmit = (chainResult == false || isCircular) && !isJsExpando
                        if (canEmit) {
                            val typeArgs = classDecl.typeParameters?.size ?: 0
                            val display = if (typeArgs > 0) {
                                ctor.text + "<" + List(typeArgs) { "unknown" }.joinToString(", ") + ">"
                            } else ctor.text
                            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type '$display'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                            ))
                        }
                    }
                }
            }
            // B241: lib-constructor receiver — `new Promise(...).finally` /
            // `new Date().toTemporalInstant`: the ctor is a lib `declare var X:
            // XConstructor` (Variable, not Class). Resolve the instance type via
            // the construct signature and run the LIB_MIN_TARGET lookup.
            run {
                if (propName in RUNTIME_PROPERTIES) return@run
                val ctorExpr2 = objectExpr.expression
                val (ifaceName, instType) = when {
                    // B242: typed-array `new Int8Array().at(...)` — interface-only lib
                    // symbol; resolve by NAME convention with the es2024 generic display.
                    ctorExpr2 is Identifier && ctorExpr2.text in TYPED_ARRAY_NAMES &&
                        globals[ctorExpr2.text]?.declarations?.all { it in builtinLibDecls } != false -> {
                        ctorExpr2.text to (null as Type?)
                    }
                    ctorExpr2 is Identifier -> {
                        val ctorSym2 = globals[ctorExpr2.text] ?: return@run
                        if (!ctorSym2.flags.hasAny(SymbolFlags.Variable) || ctorSym2.flags.hasAny(SymbolFlags.Class)) return@run
                        if (!ctorSym2.declarations.all { it in builtinLibDecls }) return@run
                        val t = getReturnTypeOfNewExpression(objectExpr)
                        val n = when (t) {
                            is Type.Reference -> t.target.symbol?.name
                            is Type.Interface -> t.symbol?.name
                            else -> null
                        } ?: return@run
                        n to (t)
                    }
                    // B241: `new Intl.X(...)` — the lib Intl namespace's constructor
                    // vars return same-named interfaces; resolve by NAME convention.
                    ctorExpr2 is PropertyAccessExpression &&
                        (ctorExpr2.expression as? Identifier)?.text == "Intl" &&
                        globals["Intl"]?.declarations?.all { it in builtinLibDecls } == true -> {
                        ctorExpr2.name.text to (null as Type?)
                    }
                    else -> return@run
                }
                val minTarget = LIB_MIN_TARGET["$ifaceName.$propName"] ?: return@run
                if (libFeatureAvailable(minTarget)) return@run
                // TypeScript displays an un-inferable constructor type arg as `unknown`
                // (`new Promise(() => {})` → 'Promise<unknown>'); our un-inferred
                // construct-sig resolution yields `any`.
                val display = instType?.let { typeToString(it).replace("<any>", "<unknown>") }
                    ?: if (ifaceName in TYPED_ARRAY_NAMES) "$ifaceName<ArrayBuffer>" else ifaceName
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '$display'. Do you need to change your target library? Try changing the 'lib' compiler option to '${minTarget.name.lowercase()}' or later.",
                    category = DiagnosticCategory.Error, code = 2550,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
            }
            return true
        }
        return false
    }

    /**
     * (JIT.1)(b) round 804 — level-R sections `R_CALL`, `R_PAEA` and `R_STATIC`,
     * verbatim. Returns true where the original code returned from the whole
     * function.
     */
    private fun cmamCheckCallAndAccessReceiver(
        objectExpr: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        isThisAccess: Boolean,
        enclosingClassType: Type?,
        suggestionKey: String,
        ts2576Start: Int,
        ts2576Length: Int,
    ): Boolean {
        // 17.37: CallExpression receiver returning `never` — emit TS2339 'never'.
        // Covers `foo([]).bar` where `foo<T>(x: T[]): T` infers T = never from the
        // empty array literal arg, then `.bar` accesses a property on never.
        // Narrow gate: only fires when the call's resolved return type IS exactly
        // neverType. Calls returning Object/Reference/anyType/etc. still skip — full
        // call-result property checking is out of scope here (no access to the
        // return type's apparent-type member table at this site without broader
        // refactoring).
        CpaSections.atR(CpaSections.R_CALL)
        if (objectExpr is CallExpression) {
            val callType = getReturnTypeOfCallExpression(objectExpr)
            if (callType === neverType) {
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type 'never'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return true
            }
            // B64.1: CallExpression receiver returning a primitive (number/string/
            // boolean/bigint) — emit TS2339 when the property is absent from the
            // primitive's apparent (wrapper) type. Display uses the primitive name,
            // not the wrapper. Skip the broad RUNTIME_PROPERTIES filter here — the
            // primitive wrapper interfaces (Number/String/Boolean/BigInt) authoritatively
            // declare which members exist on the primitive; relying on getPropertyOfType
            // against the apparent type gives the correct answer for both directions
            // (`.length` on number → TS2339; `.toString` on number → no error).
            if (callType is Type.Intrinsic &&
                callType.intrinsicName in PRIMITIVE_WRAPPER_INTRINSIC_NAMES
            ) {
                val apparent = getApparentType(callType)
                if (apparent is Type.Object) {
                    resolveStructuredTypeMembers(apparent)
                    if (getPropertyOfType(apparent, propName) != null) return true
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    // B65.1: route through typeToString so TemplateLiteralType-sourced
                    // intrinsics render their original source text (e.g.
                    // `\`${string}:\t${number}\r\n\``) rather than plain `string`.
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '${typeToString(callType)}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
            // B241: `Symbol("foo").description` — a `symbol`-typed call result whose
            // property is a LIB_MIN_TARGET later-lib Symbol member. TS2550-only
            // (no TS2339 fall-through — keeps the prior silent behavior otherwise).
            if (callType is Type.Intrinsic && callType.intrinsicName == "symbol") {
                val minTarget = LIB_MIN_TARGET["Symbol.$propName"]
                if (minTarget != null && !libFeatureAvailable(minTarget)) {
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type 'symbol'. Do you need to change your target library? Try changing the 'lib' compiler option to '${minTarget.name.lowercase()}' or later.",
                        category = DiagnosticCategory.Error, code = 2550,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
            // B241: nullable-union call result (`"...".match(...).groups`) — strip
            // null/undefined; a single remaining named interface/reference runs the
            // LIB_MIN_TARGET lookup. TS2550-only.
            if (callType is Type.Union) {
                val nonNullish = callType.types.filter { it !== nullType && it !== undefinedType }
                val only = nonNullish.singleOrNull()
                val ifaceName = when (only) {
                    is Type.Reference -> only.target.symbol?.name
                    is Type.Interface -> only.symbol?.name
                    else -> null
                }
                if (ifaceName != null) {
                    val minTarget = LIB_MIN_TARGET["$ifaceName.$propName"]
                    if (minTarget != null && !libFeatureAvailable(minTarget)) {
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '${typeToString(only!!)}'. Do you need to change your target library? Try changing the 'lib' compiler option to '${minTarget.name.lowercase()}' or later.",
                            category = DiagnosticCategory.Error, code = 2550,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return true
                    }
                }
            }
            return true
        }

        // extendFromAny: a PropertyAccess/ElementAccess receiver whose type resolves to a
        // primitive intrinsic (e.g. `c.known` typed `number` where `known` is a class
        // field). Mirror B64.1's call-result branch: TS2339 when the property is absent
        // from the primitive's apparent (wrapper) type; display uses the primitive name.
        // The PRIMITIVE_WRAPPER_INTRINSIC_NAMES gate excludes any/unknown/error, so a
        // member typed `any` (e.g. `c.unknown.length` under `class C extends Base:any`)
        // is correctly left alone.
        CpaSections.atR(CpaSections.R_PAEA)
        if (objectExpr is PropertyAccessExpression || objectExpr is ElementAccessExpression) {
            val recvType = getTypeOfExpression(objectExpr)
            if (recvType is Type.Intrinsic &&
                recvType.intrinsicName in PRIMITIVE_WRAPPER_INTRINSIC_NAMES && propName.isNotEmpty()
            ) {
                val apparent = getApparentType(recvType)
                if (apparent is Type.Object) {
                    resolveStructuredTypeMembers(apparent)
                    if (getPropertyOfType(apparent, propName) != null) return true
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '${typeToString(recvType)}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
            // staticMemberExportAccess: a CHAINED PropertyAccess receiver (`$.sammy.bar`,
            // `$.sammy.x`) resolving to a class-INSTANCE Type.Interface. The class-instance
            // TS2576/TS2339 helpers are invoked only for Identifier receivers (the B153 trap
            // forbids a general PropertyAccess-receiver TS2339 against NAMED INTERFACE bags),
            // so this narrowly-gated branch owns the chained class-instance case: TS2576 for a
            // static-via-instance access, TS2339 for a genuinely-missing member (e.g. a
            // namespace export of the merged namespace — never an instance member). FP firewall:
            // single non-generic ClassDeclaration NOT merged with an interface/type-alias (a
            // namespace/ModuleDeclaration sibling is safe — it adds no instance members), and
            // the chain-walk must return `false` (genuinely missing, not "unresolvable base").
            if (objectExpr is PropertyAccessExpression && recvType is Type.Interface && propName.isNotEmpty() &&
                !propertyAccessChainIsNamespaceQualified(objectExpr)) {
                val tsym = recvType.symbol
                if (tsym != null && tsym.flags.hasAny(SymbolFlags.Class)) {
                    val mergedWithTypeShape = tsym.declarations.any { it is InterfaceDeclaration || it is TypeAliasDeclaration }
                    val classDecl = tsym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                    if (!mergedWithTypeShape && classDecl != null && classDecl.typeParameters.isNullOrEmpty()) {
                        if (tryEmitStaticAccessTs2576(tsym, propName, ts2576Start, ts2576Length, suggestionKey, source, fileName, recvType)) return true
                        if (lookupInstanceMemberInResolvableChain(classDecl, propName) == false &&
                            !isStaticMemberOfClass(classDecl, propName) && propName !in RUNTIME_PROPERTIES) {
                            val typeName = classDecl.name?.text ?: tsym.name
                            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                            diagnostics.add(Diagnostic(
                                message = "Property '$propName' does not exist on type '$typeName'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = diagStart, length = diagLength,
                            ))
                        }
                        return true
                    }
                }
            }
            // knockout: a PropertyAccess receiver (`o.name`) typed as a Type.Reference to a
            // PURE namespace-local INTERFACE (`Observable<string>`). The B527 branch above
            // owns class-instance receivers; the general interface-bag PropertyAccess path is
            // the B153 trap (FP-prone for MERGED/cross-file interfaces whose member resolution
            // is incomplete). This narrowly-gated branch owns the SINGLE-declaration, non-merged,
            // NO-HERITAGE interface case (so every member is locally declared → getPropertyOfType
            // is authoritative): member absent → TS2339 with the instantiated display.
            if (objectExpr is PropertyAccessExpression && recvType is Type.Reference && propName.isNotEmpty() &&
                propName !in RUNTIME_PROPERTIES &&
                // Round 472: an Array/ReadonlyArray reference answers a numeric key
                // (`transform.transformed[0]` — a numeric ELEMENT access routed here
                // with propName "0") via its numeric INDEX SIGNATURE, not a member —
                // the lib Array InterfaceDeclaration passes every gate below (single
                // decl, no heritage, no Class flag) and FP'd TS2339 "Property '0'"
                // (tsc emitter.ts:994).
                !isArrayLikeReference(recvType) &&
                !propertyAccessChainIsNamespaceQualified(objectExpr)) {
                val tsym = recvType.target.symbol
                val ifaceDecls = tsym?.declarations?.filterIsInstance<InterfaceDeclaration>()
                if (tsym != null && ifaceDecls != null && ifaceDecls.size == 1 &&
                    tsym.declarations.all { it is InterfaceDeclaration } &&
                    !tsym.flags.hasAny(SymbolFlags.Class) &&
                    ifaceDecls[0].heritageClauses.isNullOrEmpty()) {
                    resolveStructuredTypeMembers(recvType)
                    if (getPropertyOfType(recvType, propName) == null) {
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '${typeToString(recvType)}'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                    }
                    return true
                }
            }
        }

        // === Static method "this" access ===
        // In static methods, "this" refers to the constructor type (typeof C).
        CpaSections.atR(CpaSections.R_STATIC)
        if (isThisAccess && inStaticClassMethod && enclosingClassType is Type.Object) {
            val classSymbol = enclosingClassType.symbol ?: return true
            val classDecl = classSymbol.declarations.firstOrNull() as? ClassDeclaration ?: return true
            if (isStaticMemberOfClass(classDecl, propName)) return true
            if (classSymbol.exports?.containsKey(propName) == true) return true
            if (propName in RUNTIME_PROPERTIES) return true
            val typeName = "typeof ${classSymbol.name}"
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'.",
                category = DiagnosticCategory.Error, code = 2339,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return true
        }
        return false
    }

    /**
     * (JIT.1)(b) round 804 — level-R sections `R_OT_PRE` .. `R_OT_IDENT`: the
     * general receiver-type path, i.e. the `else` arm of the original
     * `val objectType = …` expression, verbatim.
     *
     * Returns null exactly where that arm returned from the whole function, and
     * otherwise the pair the arm used to leave behind: the receiver type it
     * evaluated to, plus the display-type override it had assigned into the
     * caller's local. Returned rather than written to a field ON PURPOSE — a field
     * would need round 791's save/restore dance to stay correct under a nested
     * invocation, and the pair costs at most one allocation per surviving call.
     */
    /**
     * (NARROW.2)(c) round 852 — THE NARROWED TYPE OF AN `any` RECEIVER, and the
     * entire FP surface of this item.
     *
     * [checkMemberAccessMissing] is silent for an `any` receiver **by
     * construction**: both receiver-typing branches of [cmamGeneralReceiverType]
     * bail the moment `getTypeOfSymbol` / `getTypeOfIdentifier` answers `anyType`.
     * That bail is also the walker's FP firewall, and tsc's own sources use a
     * narrowed-`any` receiver constantly — so this helper is deliberately the
     * narrowest possible opening of it, and every gate below is a REFUSAL, never
     * an emission.
     *
     * What it admits: a bare reference whose DECLARED type is exactly `anyType`,
     * whose flow-narrowed type is a concrete [Type.Object] — an interface, a
     * class instance type or an anonymous type literal. What it refuses, and why:
     *  - `error`/`unresolved`/`unknown` receivers (`rawType !== anyType`), which
     *    are error recovery, not narrowing;
     *  - a narrow that did not happen (`narrowed === rawType`), which is the
     *    overwhelming majority of `any` receivers on every profile;
     *  - anything that is not a `Type.Object` — a union (its elaboration is the
     *    declared-union path's, which an `any` declared type never reaches), a
     *    primitive, a type parameter, and `never`/`any` themselves, which are
     *    [Type.Intrinsic];
     *  - a [Type.Reference] (a generic instantiation), where property resolution
     *    goes through `resolveGenericPropertyType` and the round-762 carrier rule;
     *  - the global `Object`/`Function`, which tsc exempts at the narrowing site
     *    (see [isGlobalObjectOrFunctionType]) and which is refused here too so a
     *    narrow arriving by some OTHER route cannot re-open the same hole;
     *  - an enum-flavoured member-less object, which would otherwise match the
     *    "empty receiver" TS2339 gate downstream.
     *
     * NOT a suppression-only change, and the note says so: it can only ADD
     * diagnostics. The instrument that decides it is the corpus, not the eight
     * dashboard profiles — round 792's pre-gate on this very function measured 0
     * emitting calls in a 22,187-call skip set and still killed 7 baselines.
     */
    /**
     * (NARROW.2)(f) round 855: could the flow POSSIBLY narrow [objectExpr], without
     * launching a walk to find out?
     *
     * A `false` is a proof, not a heuristic. [FlowGraph.narrowableRoots] over-
     * approximates every root name any narrowing node in this file can narrow, and
     * a receiver with no reference PATH cannot be narrowed at all — that is
     * `getNarrowedTypeForReference`'s own first bail. A `true` means "unknown,
     * walk"; a graph carrying no inventory (`narrowableRoots() == null`) refuses
     * nothing.
     *
     * The one arm it does NOT cover is the name-INDEPENDENT collapse to `never`
     * (`FlowUnreachable`, an empty `FlowBranchLabel`). That is sound HERE because
     * `never` is a `Type.Intrinsic`, which [cmamNarrowedAnyReceiverType]'s
     * `Type.Object` test refuses anyway — a refused `never` and a walked `never`
     * both produce `null`. Any OTHER caller has to re-argue that.
     */
    private fun cmamPreTestMayNarrow(objectExpr: Expression): Boolean {
        val roots = currentFlowGraph?.narrowableRoots() ?: return true
        val path = getReferencePath(objectExpr) ?: return false
        return flowPathRoot(path) in roots
    }

    private fun cmamNarrowedAnyReceiverType(objectExpr: Expression, rawType: Type): Type? {
        if (rawType !== anyType) return null
        if (currentFlowGraph == null) return null
        // (NARROW.2)(e) round 854 — the opening's own price, taken here rather
        // than by differencing two builds' `narrowWalks` row (that column swings
        // 6-9% between runs of ONE binary, which is larger than the object).
        // Inert off `--passTiming`; see [PassTiming.cmamAnyOpenings].
        // (NARROW.2)(f) round 855 — the candidate pre-test, run as a probe that
        // HONOURS NOTHING: its verdict is recorded and the walk proceeds anyway, so
        // this run's diagnostics are byte-identical to a production one while the
        // yield and the soundness leak are measured against the very population
        // round 854 priced. See [PassTiming.cmamAnyPreRefused].
        var preRefused = false
        var preNanos = 0L
        if (PassTiming.detailed) {
            val p0 = PassTiming.nowNanos()
            preRefused = !cmamPreTestMayNarrow(objectExpr)
            preNanos = PassTiming.nowNanos() - p0
        }
        val probeT0 = if (PassTiming.detailed) PassTiming.nowNanos() else 0L
        val probeW0 = if (PassTiming.detailed) PassTiming.narrowWalkNanos else 0L
        val narrowed = getNarrowedTypeForReference(rawType, objectExpr)
        if (PassTiming.detailed) {
            PassTiming.noteCmamAnyOpening(
                PassTiming.nowNanos() - probeT0,
                PassTiming.narrowWalkNanos - probeW0,
                narrowed !== rawType,
                preRefused,
                preRefused && getReferencePath(objectExpr) == null,
                preNanos,
            )
        }
        if (narrowed === rawType) return null
        if (narrowed !is Type.Object) return null
        if (narrowed is Type.Reference) return null
        if (isGlobalObjectOrFunctionType(narrowed)) return null
        if (isEnumFlavoredObjectType(narrowed)) return null
        if (PassTiming.detailed) {
            PassTiming.cmamAnyAccepted++
            // The soundness number: a refusal here would DELETE a receiver type
            // the compiler went on to use. Must stay 0.
            if (preRefused) PassTiming.cmamAnyPreRefusedAccepted++
        }
        return narrowed
    }

    /**
     * (CHK.44) THE DECLARED TYPE OF A **BLOCK-SCOPED LOCAL** RECEIVER, WHICH THE
     * PROPERTY-ACCESS FAMILY OTHERWISE CANNOT SEE AT ALL.
     *
     * CLAUDE.md's B83.5: `Binder.bindStatement` never binds a declaration nested
     * inside a function body or a block, so [lookupPerFileForNode] answers null for
     * such a name and [getTypeOfIdentifier] falls all the way through to `anyType`.
     * The cpa pass's own scope model ([applyBodyLocalShadowing]) deliberately
     * records only names that ALSO have an outer binding — "a pure local is left
     * untouched (no member-access FP surface)" — which held right up until you ask
     * what the FALSE-NEGATIVE surface is. Measured against tsgo 7.0.2:
     * `function f() { const c: A | F = u; c.files }` reports NOTHING where tsc
     * reports TS2339, in every container (function / method / arrow / nested
     * function / nested block / file-level block) and for `const`, `let` and `var`
     * alike. The only shape that limped through was a local whose declared type is a
     * single OBJECT type, and only via [cmamNarrowedAnyReceiverType]'s flow
     * recovery — which refuses a `Type.Union` by construction
     * (`narrowed !is Type.Object`), so the union half had no route whatsoever.
     *
     * ### Why this reads the LEXICAL tables and does not write `currentLocalTypes`
     *
     * The first cut recorded the annotation into `currentLocalTypes` from
     * [cpaApplyDeclRecordings]. It closed the same population and cost two corpus
     * baselines, because that map is read by EVERY consumer of the pass, not by the
     * property-existence check alone: `discriminateWithOptionalProperty4` gained a
     * TS18048 from `emitTs18048ForOptionalPropertyAccessReceiver` (a discriminated
     * union this compiler does not narrow in a ternary), and
     * `narrowingPastLastAssignment` gained one because B136's chaining arm could
     * suddenly type `fooMap.get("a")` as `number[] | undefined`. Both are the SAME
     * missing mechanism — narrowing of a body-local reference — reached through
     * consumers this round is not fixing. Reading the type HERE, at the one call
     * that asks "does this property exist on the receiver", is the smallest form of
     * the change that no other family can observe.
     *
     * ### Why it cannot change how a BOUND name resolves
     *
     * Round 748's rule: [lexicalScopeSymbol] consults `LexicalScope.symbols` ONLY,
     * and `Binder.declareLexical` skips any name the main binder already bound in
     * that container. So a hit here is by construction a declaration the
     * conventional tables do NOT have, and a file-level `const c: A` keeps resolving
     * through `currentFileLocals` / `globals` exactly as before. The chain walk is
     * innermost-first from the REFERENCE, so shadowing falls out for free and no
     * anchoring/ordering argument is needed.
     *
     * ### The two refusals, and which of them is a measurement
     *
     *  - `currentLocalTypes.containsKey(name)` — an entry there is a DELIBERATE one,
     *    including the `anyType` suppressions [applyBodyLocalShadowing],
     *    [applyNestedGlobalShadow] and [applyAmbiguousBlockScopedLocals] install for
     *    the shadow / ambiguous-block-scope populations. Those must keep winning; a
     *    receiver typed `any` because an earlier round decided so is not a receiver
     *    this one may re-type. Same for a destructured-parameter binding name.
     *  - [typeHasNullishConstituent] — **the guard that is a measurement, not an
     *    argument.** Without it the 8-profile grid gains **11 rows on the compiler
     *    profile and 16 on harness** (`removed=0`), and tsgo 7.0.2 reports NONE of
     *    them: every site is a `let x: T | undefined` (or `| null`) the code narrows
     *    before use — `program.ts`'s `automaticTypeDirectiveNames ??=`,
     *    `checker.ts`'s `if (!relatedInfo) … else relatedInfo.push(info)`,
     *    `parser.ts`'s `!typeExpression || typeExpression.type`. A nullish annotation
     *    exists in order to be narrowed, and narrowing a body-local reference is the
     *    gap this round does NOT close — so handing the walker that declared type
     *    reports against a type the code has already excluded. (CHK.39c)'s law
     *    ("giving the property-access family more contextual type manufactures
     *    TS2339 because it has no narrowing"), with the population measured.
     *
     * A single declaration is required for the same reason
     * [applyAmbiguousBlockScopedLocals] exists: two `const c` in two sibling blocks
     * are one scope-space symbol here only if they share a scope, and a merged
     * multi-declaration symbol cannot say which one a given reference means.
     *
     * ### And why the answer must be a UNION
     *
     * `Type.Union` is not a shape restriction, it is the choice of CONSUMER. A union
     * receiver is decided by [cmamCheckUnionReceiverNarrowing], which consults the
     * flow before reporting; every other declared type falls through to the `else`
     * branch below, which consults nothing. Supplying a non-union declared type
     * there costs `services/utilities.ts`'s `let next: Symbol = symbol` — narrowed
     * by `isTransientSymbol(next) && next.links.target`, a type guard inside a
     * `while` condition that round 785's `if`-condition recorder does not reach —
     * i.e. **3 rows on the services / server / harness profiles that tsgo does not
     * report**, measured. The non-union body-local is not a regression to accept
     * either: it already resolves through [cmamNarrowedAnyReceiverType]'s flow
     * recovery, which is exactly the narrowing consultation this refusal preserves.
     */
    private fun cmamBlockScopedReceiverType(objectExpr: Identifier): Type? {
        val name = objectExpr.text
        if (currentLocalTypes.containsKey(name)) return null
        if (name in currentParamBindingNames) return null
        if (name in currentShadowedNames) return null
        val sym = lexicalScopeSymbol(objectExpr, name) ?: return null
        if (!sym.flags.hasAny(SymbolFlags.Variable)) return null
        if (sym.declarations.size != 1) return null
        val decl = sym.valueDeclaration as? VariableDeclaration ?: return null
        val ann = decl.type ?: return null
        val t = getTypeFromTypeNode(ann)
        if (t === anyType || t === errorType || t === unknownType) return null
        if (typeContainsUnresolvedTypeParam(t)) return null
        if (typeHasNullishConstituent(t)) return null
        if (t !is Type.Union) return null
        return t
    }

    /**
     * (CHK.46) THE SINGLE-**OBJECT** EMISSION A NESTED ACCESS NEVER HAD.
     *
     * `h.inner.zzznope`, where `h.inner` is a plain object type, reported NOTHING
     * where tsgo 7.0.2 reports TS2339 — for a parameter, a file-level `const` and a
     * body-local alike, so this is not a block-scoping gap either. The receiver's
     * type is not the problem: `rawForNarrowing` already reads `Inner` for it. What
     * was missing is a consumer: a UNION receiver is decided by
     * [cmamCheckUnionReceiverNarrowing] (which accepts a `PropertyAccessExpression`
     * and whose tail already emits for a narrowed single object), and every
     * non-union receiver falls into the `objectExpr !is Identifier` branch, whose
     * three handlers are about `X.prototype` and namespace members.
     *
     * ### Why this is not the "broad structural-receiver gap" being opened
     *
     * It is (CHK.45)'s ALL-MISSING trust predicate applied to a receiver of ONE
     * type instead of to each constituent of a union. [cmamAllMissingTrustedMember]
     * is the whole FP firewall and it was calibrated on knip: it refuses a
     * heritage-carrying interface (the B153 population, which is what knip's two
     * measured false positives were), a `Type.Reference` (so `Inner[]` too), a class
     * instance, an intersection, a type parameter, an enum-flavoured object, a NAMED
     * anonymous object (so `typeof someNamespace`), a content-free one, and anything
     * an index signature supplies. Every one of those is a tsc error we decline to
     * report.
     *
     * ### The narrowing consult is load-bearing and is a REFUSAL
     *
     * `if ('zzznope' in h.inner) { h.inner.zzznope }` is LEGAL — measured on tsgo,
     * which narrows an object type by `in` — so an emission that consulted nothing
     * would be a false positive on idiomatic code. Rather than model that narrowing,
     * this refuses outright whenever the flow answers anything other than the
     * declared type, which is strictly safer: a narrow that ADDS a property and a
     * narrow that changes the type both stop the emission.
     *
     * The receiver is restricted to a `PropertyAccessExpression` because that is the
     * only non-Identifier shape `narrowingEligible` admits with a reference path; a
     * CALL receiver (`h.fn().zzznope`) has no path and never reaches here.
     */
    /**
     * (CHK.46) Could an `in` GUARD on the path to [objectExpr] have added
     * [propName] to its type?
     *
     * `if ('zzznope' in h.inner) { h.inner.zzznope }` is LEGAL — tsc narrows an
     * object type by `in` to `T & Record<'zzznope', unknown>` — and
     * [narrowByInOperator]'s non-union arm deliberately answers the UNCHANGED type
     * for that case ("we just keep `t` (conservative)"), which is correct for a
     * suppression consumer and invisible to an identity test. So
     * [cmamCheckNestedObjectReceiver]'s `narrowed !== raw` refusal cannot see it,
     * and without this the shape is a false positive on idiomatic duck-typing code
     * (measured against tsgo 7.0.2).
     *
     * A bounded backward walk over the flow antecedents, answering TRUE — refuse —
     * for any `in` condition naming this property on this reference path, in either
     * branch: the `isTrue` half is not consulted, because refusing costs a false
     * negative and reading it wrong costs a false positive. Budget exhaustion also
     * answers TRUE, so an unwalkable graph refuses rather than guesses.
     */
    private fun cmamInGuardMayAddProperty(objectExpr: Expression, propName: String): Boolean {
        if (currentFlowGraph == null) return false
        val path = getReferencePath(objectExpr) ?: return false
        val start = getFlowAt(objectExpr) ?: return false
        val seen = HashSet<Int>()
        val queue = ArrayDeque<FlowNode>()
        queue.add(start)
        var steps = 0
        while (queue.isNotEmpty()) {
            if (steps++ > CMAM_IN_GUARD_MAX_STEPS) return true
            val n = queue.removeFirst()
            if (!seen.add(n.id)) continue
            when (n) {
                is FlowCondition -> {
                    if (cmamConditionMentionsIn(n.expression, path, propName, 0)) return true
                    queue.add(n.antecedent)
                }
                is FlowAssignment -> queue.add(n.antecedent)
                is FlowCall -> queue.add(n.antecedent)
                is FlowSwitchClause -> queue.add(n.antecedent)
                is FlowArrayMutation -> queue.add(n.antecedent)
                is FlowBranchLabel -> queue.addAll(n.antecedents)
                is FlowLoopLabel -> queue.addAll(n.antecedents)
                else -> {}
            }
        }
        return false
    }

    /** (CHK.46) `<propName-literal> in <path>` anywhere inside a condition expression. */
    private fun cmamConditionMentionsIn(
        expr: Expression, path: String, propName: String, depth: Int,
    ): Boolean {
        if (depth > CMAM_IN_GUARD_MAX_DEPTH) return true
        var e: Expression = expr
        while (e is ParenthesizedExpression) e = e.expression
        if (e is PrefixUnaryExpression) return cmamConditionMentionsIn(e.operand, path, propName, depth + 1)
        if (e !is BinaryExpression) return false
        if (e.operator == SyntaxKind.InKeyword) {
            val left = unwrapParensExpr(e.left)
            val name = when (left) {
                is StringLiteralNode -> left.text
                is NoSubstitutionTemplateLiteralNode -> left.text
                is NumericLiteralNode -> left.text
                else -> return true
            }
            return name == propName && getReferencePath(e.right) == path
        }
        return cmamConditionMentionsIn(e.left, path, propName, depth + 1) ||
            cmamConditionMentionsIn(e.right, path, propName, depth + 1)
    }

    /**
     * (CHK.47) THE TYPE OF A DOTTED PATH WHOSE **ROOT** IS A BLOCK-SCOPED LOCAL
     * NOTHING TYPES.
     *
     * (CHK.46)(b) substitutes an un-annotated body-local's initializer type at the
     * bare-Identifier bail, and (CHK.46)(d) added a single-OBJECT emission for a
     * NESTED access — but the two do not COMPOSE, because the nested path asks
     * `getTypeOfExpression` for the whole chain and an `any` root makes the whole
     * chain `any` long before either bail is reached. Measured against
     * `tools/tsgo-7.0.2/lib/tsc`: `const c = h; c.inner.zzznope` was SILENT where
     * `const c = h; c.zzznope` (one hop shorter) and `p.inner.zzznope` (a parameter
     * root) both report.
     *
     * The repair resolves the chain by HAND from a root type the two (CHK.46)
     * helpers can name, hop by hop through the already-resolved member tables. It
     * adds no new typing rule: every hop is `getPropertyOfType` + `getTypeOfSymbol`
     * on a type one of those helpers already vouched for, and the emission it feeds
     * ([cmamCheckNestedObjectReceiver]) keeps every refusal it already had — the
     * trust predicate, the array-like line, the generic-instantiation line, the flow
     * consult and the `in`-guard consult.
     *
     * ### The refusals
     *
     *  - the root must actually be UNTYPED (`getTypeOfExpression` answers `anyType`).
     *    Where it is typed there is nothing to repair and the ordinary path owns it.
     *  - a non-Identifier root (a call, an element access, `this`) — the two helpers
     *    take an [Identifier] and there is no declaration to read.
     *  - ANY hop that does not resolve to a single property, or that resolves to
     *    `any`/`error`/`unknown`. A partial chain is worse than none: it would let
     *    the emission speak about a type the expression may not have, which is the
     *    exact failure the rest of this round removes.
     */
    private fun cmamBlockScopedPathType(expr: PropertyAccessExpression): Type? {
        var cur: Expression = expr
        val hops = ArrayList<String>(2)
        while (cur is PropertyAccessExpression) {
            hops.add(cur.name.text)
            cur = cur.expression
        }
        val root = cur as? Identifier ?: return null
        if (hops.isEmpty()) return null
        if (getTypeOfExpression(root) !== anyType) return null
        val firstHop = hops[hops.size - 1]
        var t = cmamDestructuredReceiverType(root)
            ?: cmamUnannotatedLocalReceiverType(root, firstHop)
            ?: return null
        for (i in hops.indices.reversed()) {
            val obj = t as? Type.Object ?: return null
            resolveStructuredTypeMembers(obj)
            val member = getPropertyOfType(obj, hops[i]) ?: return null
            t = getTypeOfSymbol(member)
            if (t === anyType || t === errorType || t === unknownType) return null
            if (typeContainsUnresolvedTypeParam(t)) return null
        }
        return t
    }

    private fun cmamCheckNestedObjectReceiver(
        objectExpr: Expression,
        raw: Type,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
    ): Boolean {
        if (objectExpr !is PropertyAccessExpression) return false
        if (propName.isEmpty() || propName in RUNTIME_PROPERTIES) return false
        if (raw !is Type.Object) return false
        if (isGlobalObjectOrFunctionType(raw)) return false
        if (!cmamAllMissingTrustedMember(raw, propName)) return false
        // MEASURED, not argued: an ARRAY-LIKE (a tuple is an anonymous object
        // carrying a number index signature) reaches its `slice`/`map`/`filter`
        // through the global `Array` interface, and `getApparentType` does not
        // supply those here — `fourslashImpl.ts`'s
        // `options.description.slice(1)` on `[string, (string | number)[]]` is the
        // ONE row the harness profile gained before this line existed, and tsc is
        // silent for it.
        if (raw.numberIndexInfo != null) return false
        // MEASURED: when the BASE of the nested access is a generic instantiation,
        // some other walker already owns the access and this emission DUPLICATES it
        // — the corpus's `longObjectInstantiationChain2` reports `o1.shape.p51`
        // (`o1: Type<{ p1: 1 }>`) exactly once, and it went to twice. That producer
        // runs AFTER this one, so neither the call site's emptiness test nor an
        // identity test on `diagnostics` can see it (both were tried); the receiver
        // shape is what separates the two populations.
        if (getTypeOfExpression(objectExpr.expression) is Type.Reference) return false
        if (currentFlowGraph != null && getNarrowedTypeForReference(raw, objectExpr) !== raw) return false
        if (cmamInGuardMayAddProperty(objectExpr, propName)) return false
        resolveStructuredTypeMembers(raw)
        if (getPropertyOfType(raw, propName) != null) return false
        if (getPropertyOfType(getApparentType(raw), propName) != null) return false
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '${typeToString(raw)}'.",
            category = DiagnosticCategory.Error, code = 2339,
            fileName = fileName, line = line, character = character,
            start = diagStart, length = diagLength,
        ))
        return true
    }

    /**
     * (CHK.46) THE INITIALIZER TYPE OF AN **UN-ANNOTATED BODY-LOCAL** RECEIVER.
     *
     * `function f() { const c = h; c.zzznope }` reported nothing where tsgo 7.0.2
     * reports TS2339. This one IS a block-scoping gap — CLAUDE.md's B83.5 leaves the
     * declaration unbound, so `lookupPerFileForNode` misses and
     * `getTypeOfIdentifier` falls through to `anyType` — and it is the half of
     * (CHK.45)'s population (b) that its fix did not reach: the file-level half was
     * the all-missing whitelist, this half has no type at all.
     *
     * [cmamBlockScopedReceiverType] already reads such a local's ANNOTATION and
     * deliberately supplies only a `Type.Union`, because (CHK.44) measured a
     * non-union declared type at that site as 3 rows on services/server/harness that
     * tsc does not report (a `let` narrowed by a type guard in a `while` condition).
     * This helper is the complementary case and keeps clear of that measurement:
     *  - `const` ONLY ([varDeclIsImmutableBinding]) — a `let`/`var` is the shape that
     *    measurement was about, and a binding that cannot be reassigned removes the
     *    reaching-definition question entirely;
     *  - UN-annotated only, so it can never contradict the annotated rule above;
     *  - the initializer's type must pass (CHK.45)'s [cmamAllMissingTrustedMember],
     *    the same knip-calibrated firewall the other two (CHK.46) mechanisms use;
     *  - and the `in`-guard consult, for [cmamInGuardMayAddProperty]'s reason.
     *
     * Everything it supplies still passes under [checkMemberAccessMissing]'s deferred
     * flow suppression, which is what keeps an ordinary type-guard narrow silent.
     */
    private fun cmamUnannotatedLocalReceiverType(
        objectExpr: Identifier,
        propName: String,
        shadowed: Boolean = false,
    ): Type? {
        val name = objectExpr.text
        if (!shadowed && currentLocalTypes.containsKey(name)) return null
        if (name in currentParamBindingNames) return null
        if (!shadowed && name in currentShadowedNames) return null
        val sym = lexicalScopeSymbol(objectExpr, name) ?: return null
        if (!sym.flags.hasAny(SymbolFlags.Variable)) return null
        if (sym.declarations.size != 1) return null
        val decl = sym.valueDeclaration as? VariableDeclaration ?: return null
        if (decl.type != null) return null
        if (!varDeclIsImmutableBinding(decl)) return null
        val init = decl.initializer ?: return null
        // A WHITELIST of initializer forms, not a blacklist, and the boundary is a
        // MEASUREMENT: a `new X(…)` initializer costs `isolatedModulesShadowGlobalTypeNotValue`
        // three baselines, because `Date` there is a TYPE-ONLY import shadowing the
        // global `Date` VALUE — `getTypeOfExpression(new Date(…))` answers the
        // imported INTERFACE, so `b.getTime()` reads as missing. That is a
        // value-vs-type resolution gap of its own and not something this receiver
        // may paper over, so only the two forms that measured clean are admitted:
        // a REFERENCE to something already typed, and an object LITERAL.
        if (init !is Identifier && init !is PropertyAccessExpression &&
            init !is ObjectLiteralExpression) return null
        val t = getTypeOfExpression(init)
        if (t === anyType || t === errorType || t === unknownType) return null
        if (typeContainsUnresolvedTypeParam(t)) return null
        // The Object test is FIRST on purpose: it already decides every nullish
        // reading (a nullish type is a union, or an intrinsic), which is why
        // (CHK.44)'s `typeHasNullishConstituent` line is absent here rather than
        // shipped un-gateable — arm c7 measured it as refusing nothing a fixture can
        // build.
        if (t !is Type.Object) return null
        if (isGlobalObjectOrFunctionType(t)) return null
        // An ARRAY-LIKE, for [cmamCheckNestedObjectReceiver]'s measured reason. A
        // TUPLE is what isolates this line: an `Inner[]` is a `Type.Reference` and
        // three separate layers refuse it, where a tuple is an anonymous object the
        // trust predicate deliberately admits.
        if (t.numberIndexInfo != null) return null
        if (!cmamAllMissingTrustedMember(t, propName)) return null
        if (cmamInGuardMayAddProperty(objectExpr, propName)) return null
        return t
    }

    /**
     * (CHK.46) THE DECLARED TYPE OF A **DESTRUCTURED** RECEIVER — the one shape the
     * property-access family types NOWHERE.
     *
     * Measured against `tools/tsgo-7.0.2/lib/tsc`, `const { inner } = h; inner.zzznope`
     * reports NOTHING where tsc reports TS2339, and — unlike (CHK.44)'s population —
     * it is not a block-scoping gap: a file-level `const`, a body-local and a
     * destructured PARAMETER are all equally silent, in the arrow form as much as the
     * declaration form. The two routes into [cmamGeneralReceiverType] fail for two
     * different reasons and this helper repairs both:
     *  - a BOUND binding name (a file-level pattern) reaches `identSymbol`, and
     *    `getTypeOfSymbol` has **no `BindingElement` arm**, so it answers `anyType`;
     *  - an UNBOUND one (a body-local pattern, or any parameter pattern) reaches the
     *    `else` branch, where `getTypeOfIdentifier` answers `anyType` as well —
     *    `currentLocalTypes` does not carry it in this pass and
     *    [currentParamBindingNames] is a deliberate blanket `anyType` for the
     *    parameter half (M3.1 round 429).
     *
     * ### Why resolving it here cannot re-open round 429
     *
     * That bail exists because a destructured parameter name FALLING THROUGH resolved
     * to a same-named FUNCTION in the merged globals (sys.ts's
     * `useCaseSensitiveFileNames`, 9 self-compile false positives). This helper never
     * falls through to any name table: it finds the [BindingElement] **syntactically**,
     * innermost-first from the reference itself — through the INV.2(c) lexical scopes
     * (round 748's `symbols`-only rule, so a conventionally-bound name is untouched)
     * and, for a bound file-level pattern, through the reference's own per-file symbol.
     * A name that resolves to something other than a binding element answers null and
     * the caller keeps its legacy bail.
     *
     * ### The refusals, and which are measurements
     *
     *  - `currentLocalTypes` / [currentShadowedNames] entries keep winning, for
     *    (CHK.44)'s reason: an `anyType` recorded there is a DELIBERATE suppression.
     *  - a REST element (`const { ...rest } = h`) — its type is the source minus the
     *    named members, which this does not compute.
     *  - an ARRAY pattern — [typeCaptureDestructured] answers null for one, so tuple
     *    and iterable destructuring is out of scope by construction.
     *  - MORE THAN ONE member symbol for the name (a union source answering per
     *    constituent) — the receiver is then a union of member types this does not
     *    build; a single answer is required.
     *  - a NULLISH result — (CHK.44)'s measured guard: `A | undefined` is annotated in
     *    order to be narrowed, and tsc reports such a receiver as TS18048, not TS2339.
     *  - a CLASS instance type — both callers hand this type straight back as the
     *    receiver type, which skips their own `instanceof`-narrowing bail
     *    ([tryEmitClassInstanceMissingTs2339]); refusing it here keeps that bail's
     *    verdict rather than routing round it.
     *  - an unresolved type parameter anywhere in the source or the member type.
     */
    private fun cmamDestructuredReceiverType(objectExpr: Identifier): Type? {
        val name = objectExpr.text
        if (currentLocalTypes.containsKey(name)) return null
        if (name in currentShadowedNames) return null
        val element = cmamBindingElementDeclaration(objectExpr, name) ?: return null
        if (element.dotDotDotToken) return null
        val memberName = (element.propertyName ?: element.name) as? Identifier ?: return null
        val source = typeCaptureDestructured(element, 0) ?: return null
        if (source === anyType || source === errorType || source === unknownType) return null
        if (typeContainsUnresolvedTypeParam(source)) return null
        val symbols = ArrayList<Symbol>(2)
        typeCaptureCollectMembers(source, memberName.text, symbols, 0)
        val member = symbols.singleOrNull() ?: return null
        val t = getTypeOfSymbol(member)
        if (t === anyType || t === errorType || t === unknownType) return null
        if (typeContainsUnresolvedTypeParam(t)) return null
        if (typeHasNullishConstituent(t)) return null
        if (t is Type.Interface && t.symbol?.flags?.hasAny(SymbolFlags.Class) == true) return null
        return t
    }

    /**
     * (CHK.47) DOES AN **INNER LEXICAL VALUE BINDING** SHADOW THE FILE-LEVEL NAME?
     *
     * `lookupPerFileForNode` is keyed by the FILE, so for a receiver identifier it
     * answers the file-level declaration of that spelling however deeply the
     * reference is nested. That is right only while nothing nearer declares the
     * name — and CLAUDE.md's B83.5 leaves every block-scoped declaration out of the
     * binder tables, so the shadowing declaration is invisible to `lookupPerFileForNode`
     * and to `getTypeOfSymbol` alike. Measured against `tools/tsgo-7.0.2/lib/tsc`,
     * four shapes were wrong on the SHIPPED binary, and three of them are wrong in
     * the worst direction — a confident message naming the OUTER type:
     *
     * | shape | ours | tsgo |
     * |---|---|---|
     * | `const inner: Deep` + `const { inner } = h; inner.zzznope` | `Deep` | `Inner` |
     * | `function alpha()` + `function f({ alpha }: Inner) { alpha.zzznope }` | `typeof alpha` | `string` |
     * | `const cc: Deep` + `const cc = h.inner; cc.zzznope` | SILENT | `Inner` |
     * | `const dd: Deep` + `const dd: Inner = h.inner; dd.zzznope` | `Deep` | `Inner` |
     *
     * Refusing the per-file symbol here routes all four into the `else` branch, which
     * reads `currentLocalTypes` and — at its `any` bail — (CHK.46)'s two block-scoped
     * receiver helpers. Nothing new has to type anything: the machinery for every one
     * of the four already existed and was simply never reached.
     *
     * ### Why the INV.2(c) tables answer this and a name table cannot
     *
     * Round 748's `symbols`-only rule is what makes a non-null answer here MEAN
     * "shadow": [LexicalScope.symbols] holds only names the main binder did **not**
     * bind in that container, so a file-level `const` the binder owns is absent from
     * the file scope's own `symbols` and cannot match. A hit therefore always comes
     * from a strictly inner scope on the reference's parent chain, which is exactly
     * the shadowing relation. And `lexicalScopeSymbol` walks innermost-first, so no
     * ordering question arises.
     *
     * ### The refusals
     *
     *  - a MULTI-declaration symbol — a merged symbol cannot say which declaration a
     *    given reference means ([cmamBindingElementDeclaration]'s rule).
     *  - anything whose `valueDeclaration` is not a VARIABLE, a BINDING ELEMENT or a
     *    PARAMETER. The lexical tables also carry type parameters, block-scoped
     *    enums/interfaces/classes and imports; refusing the per-file VALUE symbol for
     *    one of those would delete a working emission rather than correct it, and the
     *    type-side gates below (`cmamCheckIdentSymbolTypeGates` and its value twin)
     *    are precisely the consumers that need the per-file symbol intact.
     *  - an `enclosingNsShadow` hit, which is left alone at the call site: that is
     *    B69.12's own coarser shadow mechanism and it has its own measured population.
     */
    private fun cmamLexicalValueShadow(objectExpr: Identifier, name: String): Boolean {
        val sym = lexicalScopeSymbol(objectExpr, name) ?: return false
        if (sym.declarations.size != 1) return false
        return when (sym.valueDeclaration) {
            is VariableDeclaration, is BindingElement, is Parameter -> true
            else -> false
        }
    }

    /**
     * (CHK.47) MAY THE **INNER** BINDING'S OWN READING REPLACE WHAT THE NAME TABLES SAY?
     *
     * Only where the tables say nothing useful. Two entries qualify, and both are
     * recorded *because* the compiler could not type the inner binding:
     *  - NO `currentLocalTypes` entry at all — B83.5's block-scoped population;
     *  - an entry of exactly `anyType`, which is round 512's UN-INFERABLE shadow
     *    registration (`applyBodyLocalShadowing`) or round 429's blanket for a
     *    destructured parameter name. Both are suppressions, not measurements.
     *
     * Any other entry is the inner binding's OWN recorded type (an annotated
     * body-local `const`), and it must keep winning — the whole point of refusing the
     * per-file symbol is to reach that reading, not to route round it.
     */
    private fun cmamShadowReadingWins(name: String): Boolean {
        val recorded = currentLocalTypes[name] ?: return true
        return recorded === anyType
    }

    /**
     * (CHK.46) The [BindingElement] that declares [name] at [objectExpr], or null.
     *
     * Innermost-first from the REFERENCE, so shadowing falls out for free. The
     * lexical tables are consulted FIRST because they are the only ones that hold a
     * body-local or a parameter pattern at all ([Binder.bindLexicalBindingName]
     * recurses into both binding-pattern kinds); the per-file symbol is the fallback
     * for a FILE-LEVEL pattern, which the main binder does bind and which round 748's
     * `symbols`-only rule therefore keeps out of the lexical tables.
     *
     * A multi-declaration symbol answers null for [cmamBlockScopedReceiverType]'s
     * reason: a merged symbol cannot say which declaration a given reference means.
     */
    private fun cmamBindingElementDeclaration(objectExpr: Identifier, name: String): BindingElement? {
        val lexical = lexicalScopeSymbol(objectExpr, name)
        if (lexical != null) {
            if (lexical.declarations.size != 1) return null
            return lexical.valueDeclaration as? BindingElement
        }
        val perFile = lookupPerFileForNode(objectExpr, name) ?: return null
        if (perFile.declarations.size != 1) return null
        return perFile.valueDeclaration as? BindingElement
    }

    /**
     * (CHK.45) IS THIS UNION CONSTITUENT ONE WHOSE **ABSENCE** OF A PROPERTY WE
     * MAY BELIEVE?
     *
     * The union TS2339 elaboration has always had two verdicts with very
     * different soundness requirements. PARTIAL coverage (`anyHasIt`) is safe on
     * any member set, because SOME member was resolved well enough to answer
     * "yes" — the diagnostic is then tsc's, whatever the other members are.
     * ALL-MISSING has no such witness: every member answered "no", and a "no"
     * from an incompletely resolved member table is exactly CLAUDE.md's B153
     * ("a general PropertyAccess-receiver TS2339 fallback via resolved interface
     * members: NOT viable — merged/cross-file interface member resolution is
     * incomplete"). So all-missing needs a per-member trust predicate, and this
     * is it.
     *
     * ### Why the shipped whitelist was too narrow, measured
     *
     * Before this round all-missing fired only for `allWellResolved` (every
     * member a string/number literal or a single-declaration heritage-free
     * user interface) or `allAnonPlainObjects`. Measured against
     * `tools/tsgo-7.0.2/lib/tsc`, that silently dropped every union carrying a
     * FUNCTION type, a PRIMITIVE, a TYPE LITERAL beside a named interface, or an
     * interface WITH heritage — `function p(c: Alfa | Fn) { c.nope }` reports
     * nothing where tsc reports TS2339, **and the gap is not block-scoping**: a
     * parameter, a file-level `const` and a body-local are all equally silent, so
     * (CHK.44)'s "a member on NO constituent is still silent" is a property of
     * this whitelist and not of that round's receiver typing.
     *
     * ### Why it is a per-member predicate and not `true`
     *
     * Dropping the gate entirely is `added=0 removed=0` on all eight profiles AND
     * moves zero corpus baselines — and still costs **2 false positives on knip**
     * (`walk.ts`'s `item.members` / `item.jsDocTags` on `Export | undefined`),
     * both of them a CROSS-FILE interface WITH a heritage clause whose member
     * table we do not fully resolve. That is B153 arriving exactly where the
     * shipped predicate already refused it, which is why the Interface arm below
     * keeps [wellResolvedUnionMember]'s rule verbatim and everything the round
     * adds is OUTSIDE the named-interface world.
     *
     * The refusals are therefore: a `Type.Reference` (a generic instantiation —
     * `resolveGenericPropertyType` is not consulted here), a `Type.TypeParam` (a
     * constraint that may not be resolved yet), an intersection, an
     * enum-flavoured object (CLAUDE.md: an enum's members live on
     * `Symbol.exports` and on no type at all, so every member reads as absent),
     * a named non-interface object, `never`, and ANY member carrying an index
     * signature — an index signature legitimately provides the property, which
     * `memberHasIt` does not consult.
     *
     * ### Which clause actually refuses what, measured by ablation
     *
     * `AllMissingUnionMemberTest` pins one refusal per member kind and the arms
     * attribute them, which is not what reading the code predicts:
     *  - a CLASS instance is refused by the Interface arm's `as?
     *    InterfaceDeclaration` and by nothing else (arm a9, 1 RED);
     *  - a `Type.Reference` by its own line (arm a4, 1 RED) and a heritage
     *    interface by its own (arm a3, 1 RED);
     *  - an ENUM is refused by the LAST clause — an enum-flavoured type resolves
     *    to no `members`, no call and no construct signature, so the "some
     *    resolved content" requirement catches it. `isEnumFlavoredObjectType`
     *    and `m.symbol != null` are therefore **redundant guards TODAY** (arms
     *    a5, a8 and the combined a5b all read 0 RED). They stay because the
     *    clause that carries them is an emptiness test on a table CLAUDE.md
     *    says must stay empty — the day it is populated, the explicit guard is
     *    the only thing left. The enum pin is NOT blind: the unconditional arm
     *    (a2) reddens it, i.e. it discriminates the predicate as a whole and not
     *    this line.
     */
    private fun cmamAllMissingTrustedMember(m: Type, propName: String): Boolean {
        if (m is Type.StringLiteral || m is Type.NumberLiteral || m is Type.BigIntLiteral) return true
        if (m === neverType) return false
        if (m is Type.Intrinsic) return true
        if (m is Type.Reference) return false
        if (m is Type.TypeParam || m is Type.Union || m is Type.Intersection) return false
        if (isEnumFlavoredObjectType(m)) return false
        if (m is Type.Interface) {
            val decl = m.symbol?.declarations?.singleOrNull() as? InterfaceDeclaration ?: return false
            if (!decl.heritageClauses.isNullOrEmpty()) return false
            if (decl in builtinLibDecls) return false
            resolveStructuredTypeMembers(m)
            return !cmamIndexSignatureProvides(m, propName)
        }
        if (m is Type.Object) {
            if (m.symbol != null) return false
            resolveStructuredTypeMembers(m)
            if (cmamIndexSignatureProvides(m, propName)) return false
            return !m.callSignatures.isNullOrEmpty() || !m.constructSignatures.isNullOrEmpty() ||
                !m.members.isNullOrEmpty()
        }
        return false
    }

    /**
     * (CHK.45) Does an index signature on [m] legitimately supply [propName]?
     *
     * The same test the narrowed-single-Object emission a few lines below already
     * applies (round 479's `indexSigProvides`): a STRING index signature provides
     * every name, a NUMBER index signature only a numeric-literal one. Getting the
     * numeric half wrong is a pure false NEGATIVE — `c: Alfa | { [k: number]:
     * number }; c.zzznope` is a tsc error we would have refused — which is why it
     * is a shared helper and not two hand-written conditions.
     */
    private fun cmamIndexSignatureProvides(m: Type.Object, propName: String): Boolean =
        m.stringIndexInfo != null ||
            (m.numberIndexInfo != null && isNumericLiteralName(propName))

    private fun cmamGeneralReceiverType(
        objectExpr: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        keySuggestion: String?,
        suggestionKey: String,
        ts2576Start: Int,
        ts2576Length: Int,
    ): Pair<Type, Type?>? {
        var displayTypeOverride: Type? = null
        // (JIT.1)(b): R_OT_PRE — the namespace-member / enum-member / cast gates.
        if (cmamCheckCastAndNamespaceReceiver(
                objectExpr, propName, diagStart, diagLength, source, fileName,
            )) return null
        // Phase 17 / Blocker #1 step 2c: narrowed-to-never on receiver emits
        // TS2339 with 'never' display. Walks the flow graph from the receiver
        // expression's recorded flow node; when narrowing collapses a Union
        // receiver to never via exhaustive typeof/instanceof/equality checks,
        // the property access is invalid. Uses `getTypeOfExpression` so this
        // works for function-local identifiers (parameters, locals) too — not
        // just file-level globals. Gate: only when raw type is a Union (most
        // common narrow-to-never shape; single-type contradictions are rarer
        // and the existing identSymbol-resolution path already handles them).
        //
        // 17.34c: extended to also accept `objectExpr is PropertyAccessExpression`
        // (gated via `getReferencePath(objectExpr) != null` so only pure
        // Identifier-or-PropertyAccess chains qualify; calls/parens/element-access
        // still bail early). The narrowing helpers from 17.34a/b consume
        // dotted-path strings so PropertyAccess receivers narrow uniformly with
        // bare Identifiers. After the narrowing block, the identifier-symbol
        // lookup paths (globals[identName]) only apply to Identifier shapes.
        CpaSections.atR(CpaSections.R_OT_ELIG)
        val narrowingEligible = objectExpr is Identifier ||
            (objectExpr is PropertyAccessExpression && getReferencePath(objectExpr) != null)
        if (!narrowingEligible) return null
        CpaSections.atR(CpaSections.R_OT_RAW)
        // (CHK.44) a B83.5 block-scoped local answers `any` here; its DECLARED UNION
        // replaces that reading, and nothing else in the compiler sees the
        // substitution. See [cmamBlockScopedReceiverType].
        val rawForNarrowing = getTypeOfExpression(objectExpr).let { t ->
            if (t === anyType && objectExpr is Identifier) {
                cmamBlockScopedReceiverType(objectExpr)
                    // (CHK.46) a DESTRUCTURED receiver answers `any` here too. Only its
                    // UNION reading is substituted at this site, for (CHK.44)'s measured
                    // reason: the union block below consults the flow before reporting
                    // and every other declared type falls through to a branch that does
                    // not. The non-union reading is supplied at the two `any` bails
                    // instead, which sit under [checkMemberAccessMissing]'s deferred
                    // flow suppression.
                    ?: cmamDestructuredReceiverType(objectExpr)?.takeIf { d -> d is Type.Union }
                    ?: t
            } else if (t === anyType && objectExpr is PropertyAccessExpression) {
                // (CHK.47) …and a NESTED access whose ROOT is such a local answers
                // `any` for the WHOLE chain, so (CHK.46)(b)'s substitution at the
                // Identifier bail never composes. See [cmamBlockScopedPathType].
                cmamBlockScopedPathType(objectExpr) ?: t
            } else t
        }
        CpaSections.atR(CpaSections.R_OT_UNION)
        if (rawForNarrowing is Type.Union) {
            // (JIT.1)(b): R_OT_UNION — the union-receiver narrowing block.
            if (cmamCheckUnionReceiverNarrowing(
                    rawForNarrowing, objectExpr, propName, diagStart, diagLength, source, fileName,
                )) return null
        }

        // 17.34c: paths beyond this point assume an Identifier receiver (look up
        // the bare name in globals to drive namespace/typeof/wrapper-type emissions).
        // PropertyAccess receivers exit here — the narrowing block above already
        // covered the narrowed-to-never / single-Object / Union-with-missing cases;
        // the remaining identifier-symbol lookup paths don't generalize to
        // dotted-path receivers (no `globals["A._a"]` lookup makes sense).
        CpaSections.atR(CpaSections.R_OT_NONIDENT)
        if (objectExpr !is Identifier) {
            // (JIT.1)(b): R_OT_NONIDENT — the non-Identifier receiver emissions.
            val nonIdentBase = diagnostics.size
            cmamCheckNonIdentifierReceiver(
                objectExpr, propName, diagStart, diagLength, source, fileName, keySuggestion,
            )
            // (CHK.46) …and, when none of them fired, the single-OBJECT emission a
            // NESTED access never had. See [cmamCheckNestedObjectReceiver]. The
            // emptiness test is what keeps the existing handlers' verdicts first:
            // each of them signals "done" with a bare `return`, so the diagnostics
            // count is the only thing that reports whether one of them spoke.
            if (diagnostics.size == nonIdentBase) {
                cmamCheckNestedObjectReceiver(
                    objectExpr, rawForNarrowing, propName, diagStart, diagLength, source, fileName,
                )
            }
            return null
        }
        CpaSections.atR(CpaSections.R_OT_IDENTSYM)
        val identName = objectExpr.text
        // B69.12: enclosing-namespace local-var shadow. When `M.X` is accessed
        // inside `namespace M2 { var M = 0; ... M.X }` (and there's an outer
        // `namespace M { export class X {} }`), the `var M` shadows the outer
        // namespace within M2's body. Walk the namespace stack innermost-first
        // looking for a Variable symbol (not also Module) that shadows.
        var enclosingNsShadow: Symbol? = null
        for (ns in propertyAccessEnclosingNamespaces.asReversed()) {
            val sym = ns.exports?.get(identName) ?: continue
            if (sym.flags.hasAny(SymbolFlags.Variable) &&
                !sym.flags.hasAny(SymbolFlags.Module or SymbolFlags.Class)) {
                enclosingNsShadow = sym
                break
            }
        }
        // INV.3(d): the bare-Identifier receiver resolves node-keyed (the name is
        // read from the CURRENT file's AST) — the merged consult leaked foreign
        // module locals; per-file, an own/imported receiver resolves to the same
        // declaring-file instance and a foreign name nulls (falls to the general
        // type-based receiver path below, like any unresolvable receiver).
        val isT0 = CpaSections.t()
        val perFileIdentSymbol = lookupPerFileForNode(objectExpr, identName)
        CpaSections.closeN(CpaSections.N_IDSYM_LOOKUP, isT0)
        // Namespace-local ENUM receiver (`Color._map` where `Color` is an exported enum
        // declared in an ENCLOSING namespace, accessed unqualified inside that namespace).
        // `globals` does not hold namespace-local exports, so resolve from the enclosing-ns
        // export tables (innermost-first). Gated to a pure Enum (no Module): other kinds
        // (var/module/class) have their own globals-rooted paths, and a pure enum skips every
        // intermediate branch below (all require Function/Class/Alias/Module flags) to reach
        // the B95e enum-receiver branch, which owns the TS2339/TS2551 emit.
        val nsEnumShadow: Symbol? = if (enclosingNsShadow == null && perFileIdentSymbol == null) {
            propertyAccessEnclosingNamespaces.asReversed().firstNotNullOfOrNull { ns ->
                ns.exports?.get(identName)?.takeIf {
                    it.flags.hasAny(SymbolFlags.Enum) && !it.flags.hasAny(SymbolFlags.Module)
                }
            }
        } else null
        // (CHK.47) …unless an INNER lexical VALUE binding SHADOWS the name. The
        // per-file table is keyed by the FILE, so it answers for a file-level
        // declaration however deeply the reference is nested — and B83.5 leaves the
        // shadowing block-scoped declaration out of that table entirely, so nothing
        // below this line could ever have noticed. See [cmamLexicalValueShadow].
        // `perFileIdentSymbol != null` is part of the CONDITION, not a mere
        // optimisation: where the file tables hold nothing for the name there is no
        // outer declaration to lose to, and `getTypeOfIdentifier`'s reading below is
        // the inner binding's own. Measured — without it, a `catch (error)` whose
        // member is reached through an `in` guard went SILENT on knip for a reason
        // that has nothing to do with shadowing.
        val lexicalShadow = enclosingNsShadow == null && perFileIdentSymbol != null &&
            cmamLexicalValueShadow(objectExpr, identName)
        val identSymbol = if (lexicalShadow) null
        else enclosingNsShadow ?: perFileIdentSymbol ?: nsEnumShadow

        CpaSections.atR(CpaSections.R_OT_IDENT)
        val otT0 = CpaSections.t()
        if (identSymbol != null) {
            // Hoisted verbatim out of the type-gates section below (a pure function
            // of `keySuggestion`) because both gate helpers read it.
            val isPropertyAccessShape = keySuggestion == null || keySuggestion.startsWith(".")
            // (JIT.1)(b): R_OT_IDENT, first half — the type-side / class / function
            // specialised gates.
            if (cmamCheckIdentSymbolTypeGates(
                    identSymbol, identName, propName, diagStart, diagLength, source, fileName,
                    isPropertyAccessShape,
                )) return null
            // (JIT.1)(b): R_OT_IDENT, second half — the alias / module / enum gates.
            if (cmamCheckIdentSymbolValueGates(
                    identSymbol, identName, propName, diagStart, diagLength, source, fileName,
                    isPropertyAccessShape,
                )) return null
            // Level S: everything above is the specialised emission gates —
            // their close is skipped by every gate that FIRES, so the `calls`
            // column is the population that fell through to the general path.
            CpaSections.closeN(CpaSections.N_OTI_GATES, otT0)
            val otT1 = CpaSections.t()
            val rawType = getTypeOfSymbol(identSymbol)
            CpaSections.closeN(CpaSections.N_OTI_TYPEOF, otT1)
            val otT2 = CpaSections.t()
            // B186: a BindingElement-declared name (destructured binding — never typed by
            // getTypeOfSymbol, which has no BindingElement arm) whose currentLocalTypes
            // entry is a concrete primitive (populated by the B186 destructuring
            // recognizer) proceeds through the apparent-type path instead of bailing.
            var bindingElementPrimitive: Type? = null
            if (rawType === anyType || rawType === errorType || rawType === unknownType) {
                val lt = currentLocalTypes[identName]
                if (identSymbol.valueDeclaration is BindingElement &&
                    (lt === stringType || lt === numberType || lt === booleanType)) {
                    bindingElementPrimitive = lt
                } else {
                    // (NARROW.2)(c) round 852 — before the `any` bail, ask whether the
                    // flow narrowed this reference to something concrete. See
                    // [cmamNarrowedAnyReceiverType].
                    cmamNarrowedAnyReceiverType(objectExpr, rawType)?.let { return Pair(it, null) }
                    // (CHK.46) `getTypeOfSymbol` has no [BindingElement] arm, so a BOUND
                    // destructured name arrives here as `any`. See
                    // [cmamDestructuredReceiverType].
                    cmamDestructuredReceiverType(objectExpr)?.let { return Pair(it, null) }
                    tryEmitUtilityWrapperTs2339(identSymbol, propName, diagStart, diagLength, source, fileName)
                    return null
                }
            }
            // For primitive types (e.g. `declare var foo: number`), resolve to the
            // wrapper interface's apparent type so property lookups fire TS2339 when
            // the property doesn't exist on the wrapper. Display uses the primitive name.
            // Narrow gate: only fire for file-level Variable declarations with an
            // explicit type annotation — avoids FPs on function params/destructured
            // bindings whose inferred types may be stale primitives.
            // B69.11: also accept top-level (parent == null) literal-initialized vars
            // (`var x = 5;` / `var s = "y";` / `var b = true|false;`). Skip when the
            // name is locally shadowed via `currentLocalTypes` (function/arrow scope) —
            // detected by comparing the local type to the file-level symbol type: if
            // they differ (after literal widening), an inner scope shadows the file
            // var and the gate must not fire.
            // B69.12: namespace-local-var shadow case (enclosingNsShadow != null) is
            // also literal-init eligible — bypass the parent==null check because
            // namespace-internal vars have a parent. localShadow is irrelevant here
            // (currentLocalTypes doesn't carry namespace-internal vars).
            val exprType = if (bindingElementPrimitive != null) {
                displayTypeOverride = bindingElementPrimitive
                getApparentType(bindingElementPrimitive)
            } else if (rawType !is Type.Object) {
                val decl = identSymbol.valueDeclaration
                val annotated = decl is VariableDeclaration && decl.type != null
                val isNsShadow = enclosingNsShadow != null
                val localShadow = !isNsShadow && currentLocalTypes[identName]?.let {
                    it !== rawType && it !== getWidenedLiteralType(rawType)
                } == true
                val literalInferred = !annotated && decl is VariableDeclaration &&
                    (isNsShadow || identSymbol.parent == null) &&
                    identSymbol.declarations.size == 1 &&
                    !localShadow && when (val init = decl.initializer) {
                        is NumericLiteralNode -> true
                        is StringLiteralNode -> true
                        is Identifier -> init.text == "true" || init.text == "false"
                        else -> false
                    }
                // B83.4i: also accept a `CallExpression`-initialized var whose
                // resolved type is a concrete primitive intrinsic. `getTypeOfSymbol`
                // (above) already resolved the call's return type — when it lands on
                // a non-Object primitive (number/string/boolean/etc., NOT any/error/
                // unknown, filtered above), property access on it is checkable via the
                // wrapper apparent type, exactly like a literal-initialized var. Gate
                // mirrors `literalInferred` (top-level OR namespace-shadow, single
                // declaration, not locally shadowed) so it only fires for the same
                // narrow file-level var population. Unblocks `var n = arr.map(...)
                // .reduce(...); n.bogus` → TS2339 (genericReduce). Skipped when the
                // call's return type is a Type.Object (handled by the else branch).
                // Exclude when the name is bound by an enclosing function/method
                // parameter (including destructured patterns like `[x]` / `{x}`) —
                // there the identifier refers to the param, not the file-level var,
                // so the file-var's call-inferred type must NOT drive TS2339. This is
                // the `function foo([x]: {a}[]){ return x.a }` + `var x = foo(...)`
                // shadow case (functionOverloads43). The `localShadow` check above
                // misses destructured params because they aren't in `currentLocalTypes`;
                // `currentParamBindingNames` tracks destructured-param binding names
                // for exactly this purpose (populated in populateParameterLocalTypes).
                val shadowedByParam = identName in currentParamBindingNames
                val callInferred = !annotated && !literalInferred && !shadowedByParam &&
                    decl is VariableDeclaration &&
                    (isNsShadow || identSymbol.parent == null) &&
                    identSymbol.declarations.size == 1 &&
                    !localShadow && decl.initializer is CallExpression
                if ((!annotated && !literalInferred && !callInferred) || !identSymbol.flags.hasAny(SymbolFlags.Variable)) return null
                if (propName.isEmpty()) return null
                displayTypeOverride = if (literalInferred) getWidenedLiteralType(rawType) else rawType
                getApparentType(rawType)
            } else rawType
            if (exprType !is Type.Object) return null
            // For variables, skip class-typed access (may be narrowed via instanceof).
            // Anonymous object types (typeSym == null) ARE checkable — e.g.
            // `declare var x: { a: string }; x.missing` → TS2339.
            if (identSymbol.flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property)) {
                val typeSym = exprType.symbol
                if (typeSym != null && typeSym.flags.hasAny(SymbolFlags.Class)) {
                    // Instance-side class type (Type.Interface) — the narrowing concern
                    // applies: the variable may be narrowed by `instanceof`, so bail.
                    // Constructor-side `typeof K` (Type.Object with Class symbol) carries
                    // the static members as properties and falls through to normal
                    // property-missing checks (TS2339) below.
                    if (exprType is Type.Interface) {
                        if (tryEmitStaticAccessTs2576(typeSym, propName, ts2576Start, ts2576Length, suggestionKey, source, fileName, exprType)) return null
                        tryEmitClassInstanceMissingTs2339(typeSym, rawType, propName, objectExpr, diagStart, diagLength, source, fileName)
                        return null
                    }
                }
            }
            CpaSections.closeN(CpaSections.N_OTI_TAIL, otT2)
            return Pair(exprType, displayTypeOverride)
        } else {
            // Fallback: try resolving from currentLocalTypes (function params, local vars)
            //
            // (CHK.47) …except when an inner lexical binding SHADOWS the name, where
            // `getTypeOfIdentifier` is no safer than the per-file symbol just refused:
            // it consults the same file and global tables and so answers about the
            // OUTER declaration (`function alpha()` beside
            // `function f({ alpha }: Inner)` read `typeof alpha` for a `string`). Ask
            // the block-scoped helpers instead, and where neither can name the inner
            // binding STOP — falling through would restore the wrong answer, and a
            // confidently wrong type in a message is worse than silence. The answer
            // then re-enters the SAME tail as any other reading, which is what
            // supplies the apparent type for a primitive member.
            //
            // `currentLocalTypes` is exempt because an entry there IS the inner
            // binding's own recorded type (an ANNOTATED body-local `const`).
            val rawType = if (lexicalShadow && cmamShadowReadingWins(identName)) {
                cmamDestructuredReceiverType(objectExpr)
                    ?: cmamUnannotatedLocalReceiverType(objectExpr, propName, shadowed = true)
                    ?: return null
            } else getTypeOfIdentifier(objectExpr)
            if (rawType === anyType || rawType === errorType || rawType === unknownType) {
                // (NARROW.2)(c) round 852 — the function-local twin of the bail above
                // (a catch parameter, an un-annotated local). See
                // [cmamNarrowedAnyReceiverType].
                cmamNarrowedAnyReceiverType(objectExpr, rawType)?.let { return Pair(it, null) }
                // (CHK.46) a body-local or PARAMETER binding pattern reaches this bail —
                // `currentLocalTypes` does not carry it in this pass and
                // [currentParamBindingNames] answers `anyType` on purpose. See
                // [cmamDestructuredReceiverType].
                cmamDestructuredReceiverType(objectExpr)?.let { return Pair(it, null) }
                // (CHK.46) …and so does an UN-ANNOTATED body-local `const`, which
                // B83.5 leaves unbound. See [cmamUnannotatedLocalReceiverType].
                cmamUnannotatedLocalReceiverType(objectExpr, propName)?.let { return Pair(it, null) }
                return null
            }
            // 16.0: For primitive types, use the apparent (wrapper) type so that
            // e.g. `s: string` can detect `s.hmm` as TS2339 via the String wrapper.
            val exprType = if (rawType !is Type.Object) {
                displayTypeOverride = rawType
                getApparentType(rawType)
            } else rawType
            if (exprType !is Type.Object) return null
            // For local variables, skip class-typed (may be narrowed) — same
            // instance-side-only gate as the globals branch above.
            val typeSym = exprType.symbol
            if (typeSym != null && typeSym.flags.hasAny(SymbolFlags.Class)) {
                if (exprType is Type.Interface) {
                    if (tryEmitStaticAccessTs2576(typeSym, propName, ts2576Start, ts2576Length, suggestionKey, source, fileName, exprType)) return null
                    tryEmitClassInstanceMissingTs2339(typeSym, rawType, propName, objectExpr, diagStart, diagLength, source, fileName)
                    return null
                }
            }
            // Skip malformed types (e.g., unresolved mapped types with empty property names)
            resolveStructuredTypeMembers(exprType)
            if (exprType.properties != null && exprType.properties!!.any { it.name.isEmpty() }) return null
            CpaSections.closeN(CpaSections.N_OTI_ELSE, otT0)
            return Pair(exprType, displayTypeOverride)
        }
    }

    /**
     * (JIT.1)(b) round 804 — level-R section `R_OT_PRE`, verbatim. Returns true
     * where the original code returned from the whole function.
     */
    private fun cmamCheckCastAndNamespaceReceiver(
        objectExpr: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
    ): Boolean {
        // Narrow: `ns.Class.prop` — namespace import alias + class in target module's
        // locals + prop is not a static member. Emits TS2339 with `typeof Class` display.
        CpaSections.atR(CpaSections.R_OT_PRE)
        if (objectExpr is PropertyAccessExpression &&
            objectExpr.expression is Identifier &&
            tryEmitNamespaceMemberTs2339(objectExpr, propName, diagStart, diagLength, source, fileName)) {
            return true
        }
        // 17.22: `E.A.prop` / `M.N.E.A.prop` — enum-member access then property. Emits
        // TS2339 with `E.A` display when prop is absent from both Number and String
        // wrapper apparent types. Base may be a bare Identifier or a qualified chain.
        if (objectExpr is PropertyAccessExpression &&
            (objectExpr.expression is Identifier || objectExpr.expression is PropertyAccessExpression) &&
            tryEmitEnumMemberAccessTs2339(objectExpr, propName, diagStart, diagLength, source, fileName)) {
            return true
        }
        // B98.r100 (structural-receiver TS2339, narrowest slice): a property access
        // on a CAST receiver `(x as T).p` / `<T>x.p` where T resolves to a base-less,
        // signature-less, index-signature-less NAMED Interface that lacks `p`. A cast
        // is an EXPLICIT type assertion, so a missing member is unambiguously TS2339
        // (`missingDomElement_UsingDomLib`: `(({}) as any as HTMLMissingElement).textContent`
        // where `interface HTMLMissingElement {}`). `checkMemberAccessMissing` otherwise
        // bails on non-Identifier receivers (the broad structural-receiver gap); this is
        // the FP-safest decomposed slice — gated to a cast receiver + a simple named
        // interface with no base/sigs/index (so apparent-type/Object.prototype members
        // can't be missed) + propName not a RUNTIME_PROPERTY.
        run {
            var castInner: Expression = objectExpr
            while (castInner is ParenthesizedExpression) castInner = castInner.expression
            if ((castInner is AsExpression || castInner is TypeAssertionExpression) &&
                propName.isNotEmpty() && propName !in RUNTIME_PROPERTIES && propName[0] !in '0'..'9') {
                val castType = getTypeOfExpression(objectExpr)
                if (castType is Type.Interface && castType.symbol != null &&
                    castType.baseTypes.isNullOrEmpty() &&
                    castType.callSignatures.isNullOrEmpty() &&
                    castType.constructSignatures.isNullOrEmpty() &&
                    castType.stringIndexInfo == null && castType.numberIndexInfo == null) {
                    resolveStructuredTypeMembers(castType)
                    if (getPropertyOfType(castType, propName) == null) {
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '${typeToString(castType)}'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return true
                    }
                }
            }
        }
        return false
    }

    /**
     * (JIT.1)(b) round 804 — level-R section `R_OT_UNION` (the body of the
     * `if (rawForNarrowing is Type.Union)` block), verbatim. Returns true where the
     * original code returned from the whole function.
     */
    private fun cmamCheckUnionReceiverNarrowing(
        rawForNarrowing: Type.Union,
        objectExpr: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
    ): Boolean {
        // Round 792 (ENGINE.2e), level S: the plain walk, the round-424
        // retry and the elaboration are three different questions and the
        // row that holds them is the second-largest in the function. The
        // bracket around the plain walk is the round-790 one — two
        // monotone counter reads, immediately around the call, because
        // anything between them re-enters the checker.
        val uT0 = CpaSections.t()
        val uObs0 = narrowRetryRelevantObs
        val uLaunch0 = narrowWalkLaunches
        val narrowed = getNarrowedTypeForReference(rawForNarrowing, objectExpr)
        val uLoopFree = narrowRetryRelevantObs == uObs0 && narrowWalkLaunches > uLaunch0
        CpaSections.closeN(CpaSections.N_U_PLAIN, uT0)
        // M1.12 (round 424): a read inside a LOOP body walks back through a
        // FlowLoopLabel, where the plain variant washes back to the declared
        // union (back-edge safety), so a PRE-loop guard (`if (!isString(text))
        // return; … while (…) text.charCodeAt(…)` — tsc's own parseResponseFile)
        // never suppressed the union TS2339. Retry with the loop-entry-following
        // variant, SUPPRESSION-ONLY (every non-nullish loop-narrowed member
        // resolves the property → return, no diagnostic): the emission paths
        // below keep the PLAIN result, so a loop back-edge can never mint a new
        // narrowed-to-never / partial-coverage emission (the B78.2 soundness
        // concern — back-edge reassignment is not tracked — only ever costs a
        // false negative here, never a new FP). The "plain walk did not
        // narrow" gate is STRUCTURAL, not identity: a 2-antecedent
        // FlowBranchLabel (any `&&`/`||` condition on the path) unions
        // [declared, declared] and `getUnionType` MINTS a fresh Type.Union
        // (it does not intern — CLAUDE.md), so identity `===` misses the
        // wash whenever the path crosses a branch join.
        val plainWalkWashed = narrowed === rawForNarrowing ||
            (narrowed is Type.Union &&
                narrowed.types.map { it.id }.toSet() ==
                rawForNarrowing.types.map { it.id }.toSet())
        if (plainWalkWashed) {
            val uT1 = CpaSections.t()
            CpaSections.noteUnionRetry(uLoopFree)
            // (ENGINE.2f) round 794: SUBSTITUTE the plain walk's own result
            // for the retry's when the plain walk provably arrived at no
            // `FlowLoopLabel` and truncated nowhere (the round-790 bracket
            // above). The two walkers are line-by-line mirrors differing in
            // that ONE arm, so with the arm unreached the mirror makes the
            // identical traversal and answers what the plain walk answered.
            //
            // NOT a skip — that would NOT be equivalent. The consumer's first
            // test is the IDENTITY `loopNarrowed !== rawForNarrowing`, and a
            // loop-free repeat whose path crosses a branch join mints a FRESH
            // equal union (`getUnionType` does not intern — CLAUDE.md), so the
            // block genuinely runs and can suppress. Substituting preserves
            // both the identity relationship (fresh vs the declared instance)
            // and the member set, which is everything the consumer reads.
            val suppress: Boolean
            if (uLoopFree && !CpaSections.verifyUnionRetry) {
                suppress = unionRetrySuppresses(narrowed, rawForNarrowing, propName)
            } else {
                val loopNarrowed =
                    getNarrowedTypeForReferenceFollowLoopEntry(rawForNarrowing, objectExpr)
                val rewalked = unionRetrySuppresses(loopNarrowed, rawForNarrowing, propName)
                if (CpaSections.verifyUnionRetry &&
                    (uLoopFree || CpaSections.verifyUnionRetryAll)
                ) {
                    CpaSections.noteUnionRetryVerified(
                        instanceDiff = loopNarrowed !== narrowed,
                        memberDiff = unionMemberIdSet(loopNarrowed) != unionMemberIdSet(narrowed),
                        verdictDiff = rewalked !=
                            unionRetrySuppresses(narrowed, rawForNarrowing, propName),
                    )
                }
                // The re-walked verdict is HONOURED, so a `--verifyUnionRetry`
                // run reproduces the pre-change binary by construction.
                suppress = rewalked
            }
            CpaSections.closeN(
                if (uLoopFree) CpaSections.N_U_RETRY_LF else CpaSections.N_U_RETRY, uT1
            )
            if (suppress) {
                CpaSections.noteUnionRetrySuppressed(uLoopFree)
                return true
            }
        }
        // Level S: the elaboration. Its close is skipped by the union
        // block's own EMISSION returns (225 exits on the profile), so its
        // `calls` column is the SILENT population, not the whole one.
        val uT2 = CpaSections.t()
        if (narrowed === neverType) {
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type 'never'.",
                category = DiagnosticCategory.Error, code = 2339,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return true
        }
        // Phase 17 / Blocker #1 step 2g: multi-member union TS2339 elaboration.
        // When the narrowed receiver is still a Union with at least one member
        // missing the property AND at least one member having it (partial
        // coverage), emit TS2339 with the union display + a chain line naming
        // the first missing member. Mirrors TypeScript's baseline format.
        //
        // 17.7b: gate widened from "all missing are primitives" to "any missing
        // member" once 17.7a discriminant-property narrowing landed — the prior
        // restriction existed only because un-narrowed discriminated unions
        // (e.g. `partiallyDiscriminantedUnions_ts`'s `if (ab.type === 'a') if
        // (ab.subtype === 2) ab.foo`) would FP. With discriminant narrowing in
        // place, the union collapses to the right member and this branch is
        // skipped (single Type.Object, not Union). Only patterns that genuinely
        // shouldn't narrow (e.g. `controlFlowAliasing_ts`'s `const isFoo =
        // obj.kind === 'foo'; if (isFoo) obj.foo` — TypeScript doesn't track
        // aliased conditions for narrowing) reach this elaboration with a
        // partial-coverage Union.
        // B293: a union whose every member is WELL-RESOLVED (a string/number
        // literal, or a single-decl heritage-free user interface) supports the
        // full tsc behavior: all-missing emission (not just partial coverage),
        // tsc type-id member ordering (display + first-missing chain pick),
        // alias-name receiver displays ('AB'), the 'length' prototype-gate
        // bypass (interfaces genuinely lack it), and TS2551 spelling
        // suggestions from the union's COMMON properties.
        val wellResolvedUnionMember = { m: Type ->
            m is Type.StringLiteral || m is Type.NumberLiteral ||
                (m is Type.Interface &&
                    (m.symbol?.declarations?.singleOrNull() as? InterfaceDeclaration)
                        ?.let { it.heritageClauses.isNullOrEmpty() && it !in builtinLibDecls } == true)
        }
        val allWellResolved = narrowed is Type.Union &&
            narrowed.types.filterNot { isNullishConstituent(it) }
                .let { it.isNotEmpty() && it.all(wellResolvedUnionMember) }
        if (narrowed is Type.Union && propName.isNotEmpty() &&
            (propName !in RUNTIME_PROPERTIES || (allWellResolved && propName == "length"))) {
            // B277: nullish constituents never participate in the TS2339 union
            // elaboration — tsc reports nullable receivers via TS18048/TS2532
            // (and `x?.y` checks NonNullable(x)), never a TS2339 chain naming
            // 'undefined'/'null'. Filtering them prevents the `x?.y` FP.
            val members = narrowed.types.filterNot { isNullishConstituent(it) }
            fun memberHasIt(m: Type): Boolean {
                if (m === anyType || m === errorType || m === unknownType) return true
                if (typeHasOwnProperty(getApparentType(m), propName)) return true
                // round 419: an INTERSECTION member is `Type.Intersection`, not `Type.Object`,
                // so `typeHasOwnProperty` bails — fold its constituents (a property exists on
                // `A & B` iff ANY constituent has it), else `PropertyAccessExpression |
                // (ElementAccessExpression & Declaration & {…})` FP's TS2339 on `.parent`.
                return resolveMemberPropertyType(m, propName) != null
            }
            val missingMembers = members.filter { !memberHasIt(it) }
            val anyHasIt = members.any { memberHasIt(it) }
            // Round 512 (post-retire FN unmasked): a union of ALL-ANONYMOUS plain
            // object members (`type Shape = {width} | {height}`) missing the
            // property EVERYWHERE is a genuine tsc error — pre-retire the
            // conflated receiver resolved to a sibling interface and fired
            // through the single-interface branch by accident. Anonymous
            // TypeLiteral members have reliably-synthesized member tables, so
            // the all-missing verdict is trustworthy; index-signature /
            // callable members bail (an index sig legitimately provides any
            // property). tsc emits NO member chain for the all-missing case.
            val allAnonPlainObjects = members.isNotEmpty() && members.all { m ->
                m is Type.Object && m !is Type.Interface && m !is Type.Reference &&
                    m.symbol == null && run {
                        resolveStructuredTypeMembers(m)
                        m.stringIndexInfo == null && m.numberIndexInfo == null &&
                            m.callSignatures.isNullOrEmpty() &&
                            m.constructSignatures.isNullOrEmpty() &&
                            !m.members.isNullOrEmpty()
                    }
            }
            // (CHK.45) the fourth disjunct is the ALL-MISSING widening; it is last
            // because it is the only one that resolves member tables.
            val allMissingTrusted = !anyHasIt && !allWellResolved && !allAnonPlainObjects &&
                members.isNotEmpty() && members.all { cmamAllMissingTrustedMember(it, propName) }
            if (missingMembers.isNotEmpty() &&
                (anyHasIt || allWellResolved || allAnonPlainObjects || allMissingTrusted)) {
                val orderedMissing = if (allWellResolved) missingMembers.sortedBy { it.id } else missingMembers
                val missingMember = orderedMissing.first()
                // Receiver annotated with a bare alias-of-union reference displays
                // the ALIAS name (tsc shows 'AB', not 'A | B').
                val aliasName: String? = run {
                    val recvId = objectExpr as? Identifier ?: return@run null
                    val rsym = currentFileLocals?.get(recvId.text) ?: globals[recvId.text] ?: return@run null
                    val vd = rsym.declarations.firstOrNull { it is VariableDeclaration } as? VariableDeclaration
                    val ann = vd?.type as? TypeReference ?: return@run null
                    if (ann.typeArguments != null) return@run null
                    val annName = (ann.typeName as? Identifier)?.text ?: return@run null
                    val asym = currentFileLocals?.get(annName) ?: globals[annName] ?: return@run null
                    val alias = asym.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                    if (alias?.type is UnionType) annName else null
                }
                val unionDisplay = aliasName ?: typeToString(
                    if (allWellResolved) Type.Union(members.sortedBy { it.id }) else narrowed)
                val memberDisplay = typeToString(missingMember)
                // TS2551 for an all-interface well-resolved union when the union's
                // COMMON property set carries a close spelling match.
                var suggestion: String? = null
                if (allWellResolved && members.all { it is Type.Interface }) {
                    val commonProps = members.map { m ->
                        resolveStructuredTypeMembers(m as Type.Interface)
                        (m).properties?.mapTo(mutableSetOf()) { it.name } ?: mutableSetOf()
                    }.reduceOrNull { a, b -> a.apply { retainAll(b) } } ?: mutableSetOf()
                    suggestion = getSpellingSuggestionFromNames(propName, commonProps)
                }
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = if (suggestion != null)
                        "Property '$propName' does not exist on type '$unionDisplay'. Did you mean '$suggestion'?"
                    else
                        "Property '$propName' does not exist on type '$unionDisplay'.",
                    category = DiagnosticCategory.Error, code = if (suggestion != null) 2551 else 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                    // The round-512 all-missing anonymous case carries no member
                    // chain (tsc names a member only when SOME member has it);
                    // the pre-existing partial/well-resolved paths keep theirs.
                    // (CHK.45) tsc names the FIRST missing constituent for the
                    // all-missing case too (measured: `c: Alfa | Fn; c.nope` chains
                    // `Alfa`). The round-512 anonymous-plain-object path keeps its
                    // chainless form — its baselines pin it and this round does not
                    // re-open them.
                    messageChain = if (anyHasIt || allWellResolved || allMissingTrusted)
                        listOf("  Property '$propName' does not exist on type '$memberDisplay'.")
                    else emptyList(),
                ))
                return true
            }
        }
        // Phase 17 / Blocker #1 step 2h (17.7c/17.7d): narrowed-to-single-Object
        // emission. When discriminant/typeof/instanceof narrowing collapses a Union
        // to a single Type.Object — anonymous (`{ kind: 'a', a: string }`) or named
        // interface without base types — accessing a property missing on that single
        // member fires TS2339. Conservative gates:
        //   - `narrowed` must be a Type.Object that is NOT a Type.Reference
        //     (generic instantiation — `resolveGenericPropertyType` interaction
        //     not handled here).
        //   - For Type.Interface variants: skip if base types are non-empty
        //     (mirrors the line ~40300 skip — incomplete inheritance resolution).
        //     17.7d widening: allow Type.Interface with empty/null baseTypes (the
        //     standard discriminated-union case `interface A { kind:'a'; aProps:string }`).
        //   - Narrowing must have ACTUALLY changed the type (`narrowed !== rawForNarrowing`);
        //   - `propName` must not be empty or a RUNTIME_PROPERTIES member;
        //   - the property must not exist on the narrowed type.
        // Display uses the narrowed type's string form (NOT the un-narrowed union),
        // matching TypeScript's baseline format for narrowed property access.
        if (narrowed is Type.Object && narrowed !is Type.Reference &&
            propName.isNotEmpty() && propName !in RUNTIME_PROPERTIES
        ) {
            val skipForBaseTypes = narrowed is Type.Interface &&
                narrowed.baseTypes != null && narrowed.baseTypes!!.isNotEmpty()
            if (!skipForBaseTypes) {
                resolveStructuredTypeMembers(narrowed)
                // Round 479: an index signature provides EVERY (string-index) /
                // numeric (number-index) property — `settings.typeScriptVersion`
                // on `interface CompilerSettings { [name: string]: string }` is
                // legal, so a narrowed single-interface receiver with an index
                // sig never draws TS2339 (tsc resolves the access to the index
                // value type). The un-narrowed path already has this bail; the
                // narrowed-single-Object emission missed it.
                val indexSigProvides = narrowed.stringIndexInfo != null ||
                    (narrowed.numberIndexInfo != null && isNumericLiteralName(propName))
                if (!indexSigProvides && getPropertyOfType(narrowed, propName) == null) {
                    val narrowedDisplay = typeToString(narrowed)
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$narrowedDisplay'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
        }
        CpaSections.closeN(CpaSections.N_U_ELAB, uT2)
        return false
    }

    /**
     * (JIT.1)(b) round 804 — level-R section `R_OT_NONIDENT` (the body of the
     * `if (objectExpr !is Identifier)` block), verbatim. Its bare `return`s stay
     * bare: the caller returns unconditionally after this call, exactly as the
     * original block's trailing `return` did.
     */
    private fun cmamCheckNonIdentifierReceiver(
        objectExpr: Expression,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        keySuggestion: String?,
    ) {
        // 17.130: `ClassIdent.prototype.X` — `Class.prototype` doesn't resolve to
        // the class's instance type in our checker (no `prototype` member on the
        // static side), so the receiver type is anyType and the standard checks bail.
        // Detect the syntactic shape and route to `tryEmitClassInstanceMissingTs2339`
        // with the class symbol's declared instance type so missing-property emission
        // fires on `A.prototype.foo` when `foo` isn't on A's instance shape.
        if (objectExpr is PropertyAccessExpression &&
            objectExpr.name.text == "prototype" &&
            objectExpr.expression is Identifier
        ) {
            val classIdent = objectExpr.expression
            val rawSym = currentFileLocals?.get(classIdent.text) ?: globals[classIdent.text]
            val classSym = rawSym?.let {
                if (it.flags.hasAny(SymbolFlags.Alias)) resolveAliasTarget(it) else it
            }
            if (classSym != null && classSym.flags.hasAny(SymbolFlags.Class)) {
                val classType = getDeclaredTypeOfSymbol(classSym)
                if (classType is Type.Interface) {
                    tryEmitClassInstanceMissingTs2339(classSym, classType, propName, objectExpr, diagStart, diagLength, source, fileName)
                }
            }
        }
        // B98.r138 (TS2339): a QUALIFIED namespace member that is a NON-EXPORTED
        // import alias — e.g. `new m2.m3.c()` where `c` inside `namespace m3` is
        // `import c = x.c` WITHOUT an `export` keyword, so it is not accessible
        // from outside m3 → "Property 'c' does not exist on type 'typeof m3'.".
        // FP firewall (load-bearing — an earlier `isNameExportedFromNamespace`
        // gate over-fired on legitimately-exported function/class/var members of
        // ambient namespaces): fire ONLY when the resolved member symbol's
        // declarations are ALL non-exported `ImportEqualsDeclaration`s (a private
        // import alias) — exported members and `export import` aliases are excluded
        // by construction; ambient `declare namespace` (NamespaceModule) receivers
        // are excluded (their members are implicitly exported).
        if (objectExpr is PropertyAccessExpression &&
            (keySuggestion == null || keySuggestion.startsWith(".")) &&
            propName.isNotEmpty() && propName[0] !in '0'..'9' &&
            propName !in RUNTIME_PROPERTIES) {
            val recvSym = resolveQualifiedValueSymbol(objectExpr)
            val memberSym = recvSym?.takeIf {
                it.flags.hasAny(SymbolFlags.Module) &&
                    !it.flags.hasAny(SymbolFlags.Class or SymbolFlags.Variable or SymbolFlags.Alias or SymbolFlags.NamespaceModule)
            }?.exports?.get(propName)
            if (memberSym != null && memberSym.declarations.isNotEmpty() &&
                memberSym.declarations.all { it is ImportEqualsDeclaration && ModifierFlag.Export !in it.modifiers }) {
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type 'typeof ${objectExpr.name.text}'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return
            }
        }
        // B130 (TS2339): a QUALIFIED namespace member declared ONLY in a
        // NON-EXPORTED `namespace X { export var m }` block of a function+namespace
        // (or multi-block namespace) merge — e.g. `M.foo.x` where `foo` merges
        // `export function foo`, `export namespace foo { export var y }` (exported
        // → y visible) and `namespace foo { export var x }` (NOT exported → x not
        // externally visible). A member only in a non-exported block is never
        // accessible from outside → "Property 'x' does not exist on type 'typeof
        // foo'.". FP-safe by construction (a non-exported-block-only member is
        // always a TS2339 in TS; mirrors B98.r138's non-exported-member rule).
        if (objectExpr is PropertyAccessExpression &&
            (keySuggestion == null || keySuggestion.startsWith(".")) &&
            propName.isNotEmpty() && propName[0] !in '0'..'9' &&
            propName !in RUNTIME_PROPERTIES) {
            val recvSym = resolveQualifiedValueSymbol(objectExpr)
            val nsBlocks = recvSym?.takeIf {
                it.flags.hasAny(SymbolFlags.Module) && !it.flags.hasAny(SymbolFlags.NamespaceModule)
            }?.declarations?.filterIsInstance<ModuleDeclaration>() ?: emptyList()
            if (nsBlocks.size >= 2 && recvSym?.exports?.containsKey(propName) == true) {
                val inExportedBlock = nsBlocks.any { ModifierFlag.Export in it.modifiers && moduleBlockExports(it, propName) }
                val inNonExportedBlock = nsBlocks.any { ModifierFlag.Export !in it.modifiers && moduleBlockExports(it, propName) }
                if (!inExportedBlock && inNonExportedBlock) {
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type 'typeof ${objectExpr.name.text}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return
                }
            }
        }
    }

    /**
     * (JIT.1)(b) round 804 — level-R section `R_OT_IDENT`, first half: the
     * type-side-only bail, the `fn.name` gate and the class-instance gate,
     * verbatim apart from `isPropertyAccessShape` moving to the caller. Returns
     * true where the original code returned from the whole function.
     */
    private fun cmamCheckIdentSymbolTypeGates(
        identSymbol: Symbol,
        identName: String,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        isPropertyAccessShape: Boolean,
    ): Boolean {
        // INV.3(d)(ii): a receiver whose resolution has ONLY type-side
        // declarations while its DECLARING file also namespace-imports the
        // same name (`import * as B from "./b"` + `interface B` — tsc's
        // alias+interface merge, noCrashOnImportShadowing) reads its VALUE
        // side from the namespace import: `B.zzz` resolves the target
        // module's exports, so every interface-receiver TS2339 path below
        // is the wrong space. Suppression-only bail (module-member absence
        // stays owned by the module-receiver branches).
        if (identSymbol.declarations.any { it is InterfaceDeclaration || it is TypeAliasDeclaration } &&
            identSymbol.declarations.none {
                it is ClassDeclaration || it is FunctionDeclaration || it is EnumDeclaration ||
                    it is VariableDeclaration || it is ModuleDeclaration
            }) {
            val typeDecl = identSymbol.declarations.first {
                it is InterfaceDeclaration || it is TypeAliasDeclaration
            }
            val declFile = owningSourceFile(typeDecl)
            val hasNsImportOfName = declFile?.statements?.any { st ->
                st is ImportDeclaration &&
                    (st.importClause?.namedBindings as? NamespaceImport)?.name?.text == identName
            } == true
            if (hasNsImportOfName) return true
        }
        // B240: `fn.name` where fn is a plain no-param function declaration and
        // the lib excludes es2015 — Function.name lives in lib.es2015.core, so
        // the access is TS2339 with the function-type display ('() => void').
        // Ultra-narrow gate (single corpus consumer): annotation-less no-param
        // FunctionDeclaration with no value-returning body → '() => void'.
        if (propName == "name" && !libFeatureAvailable(ScriptTarget.ES2015) &&
            identSymbol.flags.hasAny(SymbolFlags.Function) &&
            !identSymbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Module or SymbolFlags.Alias or SymbolFlags.Variable) &&
            identSymbol.declarations.size == 1 &&
            identSymbol.exports?.containsKey(propName) != true) {
            val fnDecl = identSymbol.declarations.firstOrNull() as? FunctionDeclaration
            if (fnDecl != null && fnDecl.parameters.isEmpty() && fnDecl.type == null &&
                fnDecl.body?.statements?.none { it is ReturnStatement } == true) {
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property 'name' does not exist on type '() => void'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return true
            }
        }
        // 17.194: TS2339 for `A.foo()` where A is a top-level class and
        // `foo` is an instance method (not static). Display uses `typeof
        // ClassName`. Conservative gate: identifier resolves to a Class
        // symbol with EXACTLY ONE declaration that is a ClassDeclaration
        // (no merge with namespace/var/function), valueDeclaration is
        // also that ClassDeclaration (rules out cross-file leaks where
        // the symbol is mostly a variable but flagged Class), no extends
        // (heritage complicates static-member lookup), `foo` isn't a
        // static member, isn't in RUNTIME_PROPERTIES, and isn't an
        // exported namespace member. Also gated on PropertyAccessExpression
        // shape (keySuggestion null or starts with `.`) — element access
        // `C[1]` is NOT diagnosable here (could be reading a static).
        if (isPropertyAccessShape &&
            identSymbol.flags.hasAny(SymbolFlags.Class) &&
            !identSymbol.flags.hasAny(SymbolFlags.Module or SymbolFlags.Alias or SymbolFlags.Variable or SymbolFlags.Function) &&
            identSymbol.declarations.size == 1 &&
            propName !in RUNTIME_PROPERTIES &&
            propName.isNotEmpty() && propName[0] !in '0'..'9') {
            val classDecl = identSymbol.declarations.firstOrNull() as? ClassDeclaration
            val isPureClass = classDecl != null && identSymbol.valueDeclaration === classDecl
            val hasExtends = classDecl?.heritageClauses?.any {
                it.token == SyntaxKind.ExtendsKeyword
            } == true
            if (isPureClass && !hasExtends && !isStaticMemberOfClass(classDecl, propName)) {
                if (identSymbol.exports?.containsKey(propName) != true) {
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type 'typeof $identName'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
        }
        return false
    }

    /**
     * (JIT.1)(b) round 804 — level-R section `R_OT_IDENT`, second half: the
     * import-alias, module/namespace and enum receiver gates, verbatim. Returns
     * true where the original code returned from the whole function.
     */
    private fun cmamCheckIdentSymbolValueGates(
        identSymbol: Symbol,
        identName: String,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        isPropertyAccessShape: Boolean,
    ): Boolean {
        // === Namespace/Module property access ===
        // B98.r52: `import x = require('./m')` / `import x from './m'` resolving to
        // `export = <value>` whose type is an ANONYMOUS object (e.g.
        // `declare var server: { (): connectExport; foo: Date }` / `var x = {...}`).
        // The alias isn't a Module/Variable symbol so all other paths bail, but the
        // resolved value type is a concrete anonymous Type.Object we can check for a
        // genuinely-missing property. Tightly gated: anonymous (symbol == null, not
        // Interface/Reference), no index signatures, a real shape, property absent.
        if (identSymbol.flags.hasAny(SymbolFlags.Alias) &&
            isPropertyAccessShape && propName.isNotEmpty() &&
            propName !in RUNTIME_PROPERTIES && propName[0] !in '0'..'9') {
            val aliasType = getTypeOfSymbol(identSymbol)
            if (aliasType is Type.Object && aliasType !is Type.Reference &&
                aliasType !is Type.Interface && aliasType.symbol == null) {
                resolveStructuredTypeMembers(aliasType)
                val hasShape = !aliasType.properties.isNullOrEmpty() ||
                    !aliasType.callSignatures.isNullOrEmpty() ||
                    !aliasType.constructSignatures.isNullOrEmpty()
                if (hasShape && aliasType.stringIndexInfo == null && aliasType.numberIndexInfo == null &&
                    (aliasType.properties == null || aliasType.properties!!.none { it.name.isEmpty() }) &&
                    getPropertyOfType(aliasType, propName) == null) {
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '${typeToString(aliasType)}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
            }
        }
        // B140: property access on `import X = require("./Y.json")` where Y.json is
        // EMPTY (or literally `{}`) — its type is `{}`, so ANY property access is
        // TS2339 "Property 'x' does not exist on type '{}'.". FP-safe: only fires for
        // an import-equals alias to a JSON file whose content is unambiguously the
        // empty object (so every property access genuinely doesn't exist). Populated
        // JSON falls through (we don't model its shape → no emit).
        run {
            if (!isPropertyAccessShape || propName.isEmpty()) return@run
            val spec = getImportEqualsSpecifier(identSymbol) ?: return@run
            if (!spec.endsWith(".json")) return@run
            val content = resolveJsonModuleContent(spec) ?: return@run
            val stripped = content.replace(Regex("\\s"), "")
            if (stripped.isNotEmpty() && stripped != "{}") return@run
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '{}'.",
                category = DiagnosticCategory.Error, code = 2339,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return true
        }
        // B114: module-namespace property access via `import Foo = require("./b")`
        // — emit TS2339 when `Foo.x` accesses a member the resolved MODULE does not
        // export (display `typeof import("b")`). FP firewall (load-bearing): the
        // target must resolve to a `.ts`/`.d.ts` FILE (explicit `export` statements →
        // reliable tracking; `.js`/CJS targets are EXCLUDED because our
        // module.exports analysis is incomplete and would FP), the alias must resolve
        // to a Module symbol (an `export =` alias resolves to a VALUE, not a module —
        // handled by the B98.r52 anon-object branch above), the target file must have
        // NO `export * from` re-export (those add members absent from `locals`), and
        // the property must be absent from the module's exports.
        run {
            if (!isPropertyAccessShape || propName.isEmpty() ||
                propName[0] in '0'..'9' || propName in RUNTIME_PROPERTIES) return@run
            val spec = getImportEqualsSpecifier(identSymbol) ?: return@run
            val decl = identSymbol.declarations.firstOrNull { it is ImportEqualsDeclaration }
            val targetFile = resolveModuleSpecifier(spec, decl) ?: return@run
            if (!(targetFile.endsWith(".ts") || targetFile.endsWith(".tsx"))) return@run
            val targetResult = fileResults[targetFile] ?: return@run
            // FP firewall: a `export * from "..."` re-export contributes members not
            // present in `locals` → bail rather than risk a false TS2339.
            val hasStarReexport = targetResult.sourceFile.statements.any {
                it is ExportDeclaration && it.exportClause == null && it.moduleSpecifier != null
            }
            if (hasStarReexport) return@run
            val resolved = resolveAlias(identSymbol)
            if (!resolved.flags.hasAny(SymbolFlags.Module)) return@run
            val exports = resolved.exports ?: return@run
            if (exports.containsKey(propName)) return@run
            val base = targetFile.substringAfterLast('/')
                .removeSuffix(".d.ts").removeSuffix(".tsx").removeSuffix(".ts")
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type 'typeof import(\"$base\")'.",
                category = DiagnosticCategory.Error, code = 2339,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return true
        }
        // Skip import aliases — can't reliably resolve imported module exports
        if (identSymbol.flags.hasAny(SymbolFlags.Alias)) return true
        if (identSymbol.flags.hasAny(SymbolFlags.Module) && !identSymbol.flags.hasAny(SymbolFlags.Class) &&
            !identSymbol.flags.hasAny(SymbolFlags.Variable)) {
            // B360: a UMD global (`export as namespace X`) — the parser misparses
            // the construct into a bogus `namespace X` whose exports do NOT
            // reflect the real module's exports. Member access is unknowable — bail.
            if (identName in umdGlobalNames) return true
            // B63.34: Skip the namespace path when the symbol ALSO carries Variable
            // flag — typically caused by `mergeSymbolTable` polluting an unrelated
            // module symbol with a same-named `let`/`const` declaration. In that
            // case, the variable's type annotation should drive property lookup
            // (falls through to the `getTypeOfSymbol(identSymbol)` branch below).
            val exports = identSymbol.exports
            if (exports != null) {
                // B98.r92: VALUE access `Foo2.Bar` where `Bar` in Foo2 is a
                // NON-exported nested namespace (value-side hidden) plus an
                // exported `interface Bar` (type-only). `isNameExportedFromNamespace`
                // returns true (interface export / Module flag), suppressing the
                // error — but for a value access neither is reachable → TS2339.
                // Narrow gate: non-ambient enclosing ns + a hidden (non-exported)
                // nested namespace of that name + NO value-accessible export.
                if (isPropertyAccessShape && propName.isNotEmpty() && propName[0] !in '0'..'9' &&
                    propName !in RUNTIME_PROPERTIES &&
                    shouldEmitTs2339ForHiddenNamespaceMember(identSymbol, propName)) {
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type 'typeof $identName'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
                if (isNameExportedFromNamespace(identSymbol, propName)) return true
                // Enum members are always accessible on the enum type
                if (identSymbol.flags.hasAny(SymbolFlags.Enum) && exports.containsKey(propName)) return true
                if (propName in RUNTIME_PROPERTIES) return true
                val typeName = "typeof $identName"
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                // B241: a later-lib namespace member (`Intl.PluralRules`) gets
                // TS2550 with the lib hint instead of plain TS2339.
                val nsMinTarget = LIB_MIN_TARGET["$identName.$propName"]
                if (nsMinTarget != null && !libFeatureAvailable(nsMinTarget) &&
                    identSymbol.declarations.all { it in builtinLibDecls }) {
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$typeName'. Do you need to change your target library? Try changing the 'lib' compiler option to '${nsMinTarget.name.lowercase()}' or later.",
                        category = DiagnosticCategory.Error, code = 2550,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return true
                }
                // A USER type-only / UNINSTANTIATED namespace (only types/interfaces, no
                // value exports) used in VALUE position is owned by TS2708 ("Cannot use
                // namespace as a value") — don't ALSO emit TS2339 for a member access on it
                // (namespaceMergedWithImportAliasNoCrash: `Library.foo`). Excludes lib
                // namespaces (Intl etc.), whose TS2550 lib-target hint above already returned.
                val nsDecls = identSymbol.declarations.filterIsInstance<ModuleDeclaration>()
                if (nsDecls.isNotEmpty() && nsDecls.none { isNamespaceInstantiated(it) } &&
                    identSymbol.declarations.none { it in builtinLibDecls }) return true
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '$typeName'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return true
            }
            return true
        }

        // B95e (round 82): enum-receiver missing member, e.g. `U8.bit_2` where the
        // enum U8 (RegularEnum, no Module flag → not handled above) has member BIT_2.
        // TS2551 "Property 'bit_2' does not exist on type 'typeof U8'. Did you mean
        // 'BIT_2'?" + related TS2728 at the member declaration. Falls to plain TS2339
        // when no close spelling match. Gated on a pure Enum symbol whose exports hold
        // the members (always — the receiver here is already an Identifier).
        run {
            val enumExports = identSymbol.exports
            // Only PROPERTY access `E.foo` (isPropertyAccessShape) — NOT element access
            // `E[0]` (numeric enum reverse-mapping `E[0]` is valid) nor `E["x"]`. Also
            // skip an all-numeric propName defensively (reverse mapping).
            val isNumericProp = propName.isNotEmpty() && propName.all { it in '0'..'9' }
            if (identSymbol.flags.hasAny(SymbolFlags.Enum)
                && !identSymbol.flags.hasAny(SymbolFlags.Module)
                && enumExports != null
                && isPropertyAccessShape
                && !isNumericProp
            ) {
                if (enumExports.containsKey(propName) || propName in RUNTIME_PROPERTIES) return true
                val typeName = "typeof $identName"
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                val suggestion = getSpellingSuggestionFromNames(propName, enumExports.keys)
                if (suggestion != null) {
                    val memberDecl = enumExports[suggestion]?.declarations?.firstOrNull() as? EnumMember
                    val related = memberDecl?.let { md ->
                        val nm = md.name
                        val namePos = nm.pos
                        val nameLen = (nm as? Identifier)?.text?.length ?: (nm.end - nm.pos).coerceAtLeast(1)
                        val (rl, rc) = getLineAndCharacterOfPosition(source, namePos)
                        listOf(Diagnostic(
                            message = "'$suggestion' is declared here.",
                            category = DiagnosticCategory.Message, code = 2728,
                            fileName = fileName, line = rl, character = rc,
                            start = namePos, length = nameLen,
                        ))
                    } ?: emptyList()
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$typeName'. Did you mean '$suggestion'?",
                        category = DiagnosticCategory.Error, code = 2551,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                        relatedInformation = related,
                    ))
                } else {
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$typeName'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                }
                return true
            }
        }
        return false
    }

    /**
     * (CHK.51) POSITIVE evidence that a heritage-bearing receiver's member table is
     * complete, so that a "the property is absent" verdict has a witness.
     *
     * True only when EVERY type in the receiver's transitive base closure is an
     * interface that
     *   * has a symbol with at least one declaration, and
     *   * every one of those declarations is a BUILT-IN LIB declaration
     *     ([builtinLibDecls] — which covers the embedded lib and the real-lib
     *     snapshots alike), and
     *   * is not augmented by a `declare global { interface … }` block anywhere in
     *     the program — since (CHK.50) such a block MERGES, so its interface is one
     *     of the symbol's declarations and [cmamIsGlobalAugmentation] admits it — and
     *   * resolves to a non-null member table.
     * Anything else in the closure — a program interface, a base that is not an
     * interface reference, an unresolved member table — answers false and the
     * caller keeps the firewall.
     *
     * WHY "ALL DECLARATIONS ARE LIB DECLARATIONS" IS THE RIGHT TEST AND NOT MERELY A
     * CHEAP ONE: a lib interface's members are fully declared in files this compiler
     * ships and parses in one piece, so a member absent from the resolved table is
     * absent from the language; a PROGRAM interface's member table depends on the
     * receiver having been narrowed to the right subtype, which is the failure the
     * firewall exists for. A user augmentation of a lib name from a global SCRIPT
     * file merges into the same symbol, so it shows up here as a non-lib declaration
     * and refuses — which is why no separate augmentation test is needed for that
     * form.
     *
     * ONLY CALLED FOR A RECEIVER THAT HAS BASE TYPES — the caller's two heritage
     * tests are the ones that already existed, and each now consults this instead of
     * returning outright. Deliberately not re-tested here: an early
     * `if (root.baseTypes.isNullOrEmpty()) return false` was written, measured
     * UNREACHABLE from the one call site, and deleted rather than shipped
     * un-gateable ((CHK.49)'s a8 precedent). Keeping the test at the caller also
     * keeps the closure walk off every base-less receiver on the hot path.
     *
     * ## ABLATION RECORD — TWO OF THE FIVE TESTS ABOVE DISCRIMINATE, THREE DO NOT
     *
     * Measured one mistake at a time, each arm `cmp`-diffed against its own snapshot
     * and its `Checker.class` md5 checked against the landed one:
     *
     *  * dropping the all-lib-declarations test — 1 RED and the compiler profile at
     *    **89**, i.e. it alone is worth 43 rows;
     *  * (CHK.50) — that arm is GONE. (CHK.51) additionally refused any name a
     *    `declare global` block declared, because such a block did not merge and the
     *    all-lib test could not see it; (CHK.50) merged it, so the symbol carries a
     *    non-lib declaration and [cmamIsGlobalAugmentation] admits exactly that one.
     *    Reverting THAT allowance is (CHK.50)'s arm a8 — 2 RED, and it is what pays
     *    the true positive (CHK.51) had to record as a cost;
     *  * dropping the resolved-member-table test, the null-symbol refusal, and the
     *    empty-declarations refusal — **0 RED each, profile 46**.
     *
     * The last three are kept and are recorded here as UNDISCRIMINATED rather than
     * claimed as coverage. They are not shown DEAD either, which is why (CHK.49)'s
     * delete-it precedent does not apply: each is unreachable only because of what
     * the shipped libs happen to CONTAIN today — every lib interface is bound, has
     * declarations, resolves its members, and extends only other interfaces. They
     * are the soundness contract of a predicate whose entire job is to demand
     * positive evidence, and the libs are input this repo does not author.
     */
    /**
     * (CHK.50) Is [decl] an `interface` written inside a `declare global { … }`
     * block? Such a declaration is as COMPLETE as a lib one for
     * [cmamLibHeritageMembersComplete]'s purpose — it is a source file this
     * compiler parses in one piece, and since (CHK.50) merged the block's exports
     * its members are in the lib symbol's own table — so it must not make the
     * closure look like a PROGRAM interface. Before (CHK.50) the block never
     * reached [globals] at all, and the refusal was spelled the other way round
     * as a NAME set (`globalAugmentedInterfaceNames`, deleted with this change):
     * the two are ONE observable, and this direction is the one that reports
     * `el.zzzNotThere` on an augmented `HTMLElement` the way tsgo 7.0.2 does.
     */
    private fun cmamIsGlobalAugmentation(decl: Node): Boolean {
        if (decl !is InterfaceDeclaration) return false
        var cur = (decl as NodeBase).parent
        while (cur != null && cur !is SourceFile) {
            if (cur is ModuleDeclaration && (cur.name as? Identifier)?.text == "global" &&
                ModifierFlag.Declare in cur.modifiers
            ) return true
            cur = (cur as NodeBase).parent
        }
        return false
    }

    private fun cmamLibHeritageMembersComplete(objectType: Type.Object): Boolean {
        val root = when (objectType) {
            is Type.Reference -> objectType.target
            is Type.Interface -> objectType
            else -> return false
        }
        val seen = HashSet<Int>()
        val queue = ArrayDeque<Type.Interface>()
        queue.addLast(root)
        // A bound, not a policy: the DOM's deepest chain is a handful of levels and
        // the whole lib closure of any one interface is far under this. A closure
        // that exceeds it is refused, i.e. the firewall stands.
        var budget = 256
        while (queue.isNotEmpty()) {
            if (budget-- <= 0) return false
            val t = queue.removeFirst()
            if (!seen.add(t.id)) continue
            val sym = t.symbol ?: return false
            if (sym.declarations.isEmpty()) return false
            if (!sym.declarations.all { it in builtinLibDecls || cmamIsGlobalAugmentation(it) }) return false
            resolveStructuredTypeMembers(t)
            if (t.properties == null) return false
            for (b in t.baseTypes ?: emptyList()) {
                val bt = when (b) {
                    is Type.Reference -> b.target
                    is Type.Interface -> b
                    else -> return false
                }
                queue.addLast(bt)
            }
        }
        return true
    }

    /**
     * (JIT.1)(b) round 804 — level-R sections `R_TYPEGATE` .. `R_POSTGATE`,
     * verbatim; tail-calls [cmamEmitMissingProperty] where the original body fell
     * through into `R_PROP`.
     */
    private fun cmamCheckResolvedObjectType(
        objectExpr: Expression,
        objectType: Type,
        displayTypeOverride: Type?,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        isThisAccess: Boolean,
        emitTs2728RelatedInfo: Boolean,
    ) {
        // Check Interface and Object types (anonymous object literals, type literals, etc.)
        CpaSections.atR(CpaSections.R_TYPEGATE)
        if (objectType !is Type.Object) return
        // Skip enum types
        // (REL.1)(b0): an enum MEMBER type is equally member-less, so it would match
        // the "empty receiver" TS2339 gate below (`Extension.Dts.length`).
        if (isEnumFlavoredObjectType(objectType)) return
        // Resolve members
        CpaSections.atR(CpaSections.R_RESOLVE)
        resolveStructuredTypeMembers(objectType)
        CpaSections.atR(CpaSections.R_EMPTYPROPS)
        if (objectType.properties.isNullOrEmpty()) {
            // B63.33: empty `{}` Type.Object — receiver typed as truly-empty (e.g.
            // `const z = {}; z.x` or `function f(): {} {} f().x`). Conservative gate:
            // no symbol, no signatures, no index sigs, no base types (if Interface).
            // Display: '{}'. Mirrors the existing ObjectLiteralExpression-direct path
            // (17.115) but covers the Identifier-receiver case where the type was
            // INFERRED from an empty initializer.
            if (objectType.symbol == null &&
                objectType.callSignatures.isNullOrEmpty() &&
                objectType.constructSignatures.isNullOrEmpty() &&
                objectType.stringIndexInfo == null &&
                objectType.numberIndexInfo == null &&
                (objectType !is Type.Interface || objectType.baseTypes.isNullOrEmpty()) &&
                propName !in RUNTIME_PROPERTIES &&
                propName.isNotEmpty()) {
                val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' does not exist on type '{}'.",
                    category = DiagnosticCategory.Error, code = 2339,
                    fileName = fileName, line = line, character = character,
                    start = diagStart, length = diagLength,
                ))
                return
            }
            // Constructor-side class receiver (typeof K) may have no cached properties (the
            // binder may not have populated exports), but we can still check the class
            // declaration for the static-member presence and emit a precise TS2339 when
            // the property isn't a static of the class.
            val ctorClassSym = objectType.symbol
            if (ctorClassSym != null && ctorClassSym.flags.hasAny(SymbolFlags.Class)) {
                val classDecl = ctorClassSym.declarations.firstOrNull() as? ClassDeclaration
                if (classDecl != null && propName !in RUNTIME_PROPERTIES) {
                    if (isStaticMemberOfClass(classDecl, propName)) return
                    if (objectType !is Type.Interface) {
                        // Constructor side (`typeof C`): static-member check above already
                        // rejected static hits. The class shape is the static side, which
                        // is built once and not subject to "inherited static" cache misses,
                        // so emit unconditionally.
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type 'typeof ${ctorClassSym.name}'.",
                            category = DiagnosticCategory.Error, code = 2339,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return
                    }
                    // Instance side (Type.Interface) with empty/missing properties: only
                    // fire for `this`-access where we know we're authoritatively on the
                    // instance side of the enclosing class. Other Type.Interface receivers
                    // (variable references, class-Identifier-as-value like `C[1]` whose
                    // `getTypeOfSymbol` mis-resolves to the declared instance type) have
                    // their own dedicated handlers (`tryEmitClassInstanceMissingTs2339`,
                    // `NewExpression` branch above) — calling here would FP-fire on
                    // value-position class references. Display: bare `C`, not `typeof C`.
                    if (!isThisAccess) return
                    val chainResult = lookupInstanceMemberInResolvableChain(classDecl, propName)
                    if (chainResult != false) return
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '${ctorClassSym.name}'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return
                }
            }
            return
        }
        // B15.1: TS2339 for `this.X` where X is genuinely missing across the entire
        // resolvable instance-side inheritance chain. The general "skip class with
        // base types" guard below is conservative — for `this` access we know the
        // receiver IS the enclosing class instance, and `lookupInstanceMemberInResolvableChain`
        // safely returns `false` only when every base is resolvable as a ClassDeclaration
        // (no `Foo.Bar` base, no ambient `declare class`, no IndexSignature, no sibling
        // InterfaceDeclaration) and no member matches anywhere in the chain. Display
        // mirrors TypeScript's format: `ClassName<A, B, C>` for generic classes.
        CpaSections.atR(CpaSections.R_POSTGATE)
        if (isThisAccess && objectType is Type.Interface
            && objectType.baseTypes != null && objectType.baseTypes!!.isNotEmpty()
            && propName !in RUNTIME_PROPERTIES
        ) {
            val classDecl = objectType.symbol?.declarations?.firstOrNull() as? ClassDeclaration
            // Thread the class's enclosing namespace so a namespace-local base in the extends
            // chain resolves (else the chain returns `null` and the missing-member TS2339 is
            // swallowed — genericRecursiveImplicitConstructorErrors3's `this.isArray()` on
            // `PullTypeSymbol extends PullSymbol`, both in `namespace TypeScript`).
            val thisEnclosingNs = objectType.symbol?.parent?.takeIf { it.flags.hasAny(SymbolFlags.Module) }
            if (classDecl != null && lookupInstanceMemberInResolvableChain(classDecl, propName, enclosingNs = thisEnclosingNs) == false
                && !isStaticMemberOfClass(classDecl, propName)
            ) {
                val baseName = classDecl.name?.text ?: objectType.symbol?.name
                if (baseName != null) {
                    val tps = classDecl.typeParameters
                    val className = if (!tps.isNullOrEmpty())
                        "$baseName<${tps.joinToString(", ") { it.name.text }}>"
                    else baseName
                    if (emitClassChainTs2551Suggestion(classDecl, propName, className, diagStart, diagLength, source, fileName)) return
                    val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                    diagnostics.add(Diagnostic(
                        message = "Property '$propName' does not exist on type '$className'.",
                        category = DiagnosticCategory.Error, code = 2339,
                        fileName = fileName, line = line, character = character,
                        start = diagStart, length = diagLength,
                    ))
                    return
                }
            }
        }
        // Skip if class/interface has base types — incomplete inheritance resolution causes FPs.
        // Also applies to generic references whose target is an Interface with base types
        // (e.g. `c: IC<number>` where IC extends IA<T>, IB<T> — inherited members on the
        // Reference are populated via instantiation, but cache misses or ordering quirks
        // can leave one base's members unresolved, producing TS2339 for properties that
        // structurally exist).
        // (CHK.51) …AND THE ONE HOLE PUNCHED IN IT. The firewall above is a blunt
        // suppressor and it is LOAD-BEARING: removing it outright measures **+43
        // diagnostics on the compiler profile alone** (89 against 46), every one of
        // them a NARROWING gap rather than a member-table gap — `canHaveSymbol(e) &&
        // e.symbol`, `if (!isIdentifier(node.expression)) return; … node.expression
        // .escapedText`. tsc's own sources are written in that style throughout, so
        // the firewall has been standing in for flow narrowing we do not do.
        //
        // What it ALSO suppressed is the population this hole exists for: a missing
        // member on a real-lib interface that happens to extend something —
        // `Text`, `Node`, `Element`, `HTMLElement`, i.e. most of the DOM. The
        // relaxation therefore demands POSITIVE evidence rather than the absence of a
        // reason to refuse ((CHK.45)'s rule): every type in the receiver's transitive
        // base closure must be an interface whose declarations are ALL lib
        // declarations and whose member table actually resolved. A program type
        // anywhere in that closure — which is what every one of the 43 rows has —
        // keeps the firewall.
        if (objectType is Type.Interface && objectType.baseTypes != null && objectType.baseTypes!!.isNotEmpty()) {
            if (!cmamLibHeritageMembersComplete(objectType)) return
        }
        if (objectType is Type.Reference) {
            val tgt = objectType.target
            if (tgt.baseTypes != null && tgt.baseTypes!!.isNotEmpty()) {
                if (!cmamLibHeritageMembersComplete(objectType)) return
            }
        }
        // Skip well-known runtime properties (FP-prevention for class instances and
        // structural types where we may not have full member info). For primitive
        // types resolved through apparent type (displayTypeOverride != null), we DO
        // have authoritative member info from the wrapper interface — only allow the
        // RUNTIME_PROPERTIES exemption when the member actually exists on the
        // apparent type. This makes `s: string; s.length` pass (length is on String)
        // while `n: number; n.length` fires TS2339 (length is not on Number).
        // B98.r99: the Function/Function.prototype-only runtime properties (`name`,
        // `length`, `apply`, `bind`, `call`, `caller`, `arguments`, `prototype`) exist
        // on a function/constructor VALUE but NOT on a class INSTANCE. So `this.name`
        // inside an instance method of a base-less class that doesn't declare `name`
        // is genuinely TS2339 (`detachedCommentAtStartOfFunctionBody1/2`). Don't take
        // the blanket RUNTIME_PROPERTIES exemption for that shape; fall through to the
        // normal member-existence check below. FP-safe: it still only emits when the
        // property is genuinely ABSENT (the `prop != null` guard below returns silently
        // if our resolution does surface it). Gated: instance `this`-access (not a
        // static method, where `this` is the constructor and DOES have `.name`), a
        // base-less class Type.Interface (no inheritance to provide the member).
        val functionOnlyInstanceInvalid = propName == "name" || propName == "length" ||
            propName == "apply" || propName == "bind" || propName == "call" ||
            propName == "caller" || propName == "arguments" || propName == "prototype"
        val thisInstanceFunctionPropReportable = isThisAccess && !inStaticClassMethod &&
            functionOnlyInstanceInvalid && objectType is Type.Interface &&
            objectType.baseTypes.isNullOrEmpty() &&
            objectType.symbol?.flags?.hasAny(SymbolFlags.Class) == true
        if (propName in RUNTIME_PROPERTIES && !thisInstanceFunctionPropReportable) {
            if (displayTypeOverride == null) return
            if (getPropertyOfType(objectType, propName) != null) return
        }
        // B241: SOFT later-lib members (see LIB_MIN_TARGET_SOFT) — the member IS in
        // the interface, but access errors TS2550 under a lib excluding its level.
        // A user augmentation declaring the member keeps the access valid.
        run {
            val featureIface = when (objectType) {
                is Type.Reference -> objectType.target.symbol?.name
                is Type.Interface -> objectType.symbol?.name
                else -> null
            } ?: return@run
            val minTarget = LIB_MIN_TARGET_SOFT["$featureIface.$propName"] ?: return@run
            if (libFeatureAvailable(minTarget)) return@run
            val prop0 = getPropertyOfType(objectType, propName)
            if (prop0 != null && !prop0.declarations.all { it in builtinLibMemberDecls }) return@run
            val display = if (objectExpr is ArrayLiteralExpression && objectExpr.elements.isEmpty()) "undefined[]"
                else typeToString(displayTypeOverride ?: objectType)
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$display'. Do you need to change your target library? Try changing the 'lib' compiler option to '${minTarget.name.lowercase()}' or later.",
                category = DiagnosticCategory.Error, code = 2550,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return
        }
        cmamEmitMissingProperty(
            objectExpr, objectType, displayTypeOverride, propName, diagStart, diagLength,
            source, fileName, isThisAccess, emitTs2728RelatedInfo,
        )
    }

    /**
     * (JIT.1)(b) round 804 — level-R sections `R_PROP`, `R_LATEGATE` and `R_EMIT`,
     * verbatim: the property lookup, the later-lib gates and the emission tail.
     * Round 789 measured the emission tail as reached ZERO times on the compiler
     * profile; it is here because it is the coldest code in the function, not
     * because it is cheap.
     */
    private fun cmamEmitMissingProperty(
        objectExpr: Expression,
        objectType: Type.Object,
        displayTypeOverride: Type?,
        propName: String,
        diagStart: Int,
        diagLength: Int,
        source: String,
        fileName: String,
        isThisAccess: Boolean,
        emitTs2728RelatedInfo: Boolean,
    ) {
        // Check if property exists in type members
        CpaSections.atR(CpaSections.R_PROP)
        val prop = getPropertyOfType(objectType, propName)
        if (prop != null) {
            // TS2576: `this.X` in an instance method where X is a STATIC member of the
            // enclosing class. `resolveInterfaceMembers` stores statics and instance
            // members in the same table, so we need to re-check the declaration modifier
            // on the resolved symbol to distinguish.
            if (isThisAccess && !inStaticClassMethod) {
                val classDecl = objectType.symbol?.declarations?.firstOrNull() as? ClassDeclaration
                if (classDecl != null
                    && isStaticMemberOfClass(classDecl, propName)
                    && !hasInstanceMemberNamed(classDecl, propName)
                ) {
                    val baseName = classDecl.name?.text ?: objectType.symbol?.name
                    if (baseName != null) {
                        val tps = classDecl.typeParameters
                        val className = if (!tps.isNullOrEmpty())
                            "$baseName<${tps.joinToString(", ") { it.name.text }}>"
                        else baseName
                        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
                        diagnostics.add(Diagnostic(
                            message = "Property '$propName' does not exist on type '$className'. Did you mean to access the static member '$className.$propName' instead?",
                            category = DiagnosticCategory.Error, code = 2576,
                            fileName = fileName, line = line, character = character,
                            start = diagStart, length = diagLength,
                        ))
                        return
                    }
                }
            }
            return
        }
        // Check namespace exports (for merged class+namespace symbols like `Observable.someValue`)
        val sym = objectType.symbol
        if (sym != null && sym.flags.hasAny(SymbolFlags.Module) && sym.exports?.containsKey(propName) == true) return
        // B182: TS2550 "Do you need to change your target library?" — the property is a
        // KNOWN later-lib member of a builtin interface, dropped by the LIB_MIN_TARGET
        // filter because `options.target < minTarget`. The lib suggestion is exactly the
        // minTarget's lib name (matching TypeScript's feature-map suggestion). FP-safe by
        // construction: the member positively exists at a later lib, so TypeScript always
        // reports TS2550 (never plain TS2339) for this shape. Fires for BOTH the
        // array-literal-receiver path (displayTypeOverride set) and identifier receivers
        // (which otherwise bail at the numberIndexInfo check below — Array's `[n: number]: T`).
        CpaSections.atR(CpaSections.R_LATEGATE)
        run {
            val featureIface = when (objectType) {
                is Type.Reference -> objectType.target.symbol?.name
                is Type.Interface -> objectType.symbol?.name
                else -> null
            } ?: return@run
            val minTarget = LIB_MIN_TARGET["$featureIface.$propName"] ?: return@run
            if (libFeatureAvailable(minTarget)) return@run
            val libName = minTarget.name.lowercase()
            val display = typeToString(displayTypeOverride ?: objectType)
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$display'. Do you need to change your target library? Try changing the 'lib' compiler option to '$libName' or later.",
                category = DiagnosticCategory.Error, code = 2550,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return
        }
        // B240: STATIC-side fallback for a bare lib-constructor identifier receiver
        // (`Array.from`): the legacy identifier resolution lands on the INSTANCE
        // interface (see the Array.isArray numberIndexInfo note below), so the B182
        // key "<Name>.<prop>" misses static members keyed "<Name>Constructor.<prop>".
        // Gated to receivers that are PURELY the embedded-lib symbol.
        run {
            if (objectExpr !is Identifier) return@run
            val recvSym = globals[objectExpr.text] ?: return@run
            if (!recvSym.declarations.all { it in builtinLibDecls }) return@run
            val ctorIface = "${objectExpr.text}Constructor"
            // The LIB_MIN_TARGET key set is itself the allowlist of real constructor
            // interfaces — no globals[ctorIface] presence check (the embedded lib
            // deliberately has no ArrayConstructor / `declare var Array`).
            val minTarget = LIB_MIN_TARGET["$ctorIface.$propName"] ?: return@run
            if (libFeatureAvailable(minTarget)) return@run
            val libName = minTarget.name.lowercase()
            val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$ctorIface'. Do you need to change your target library? Try changing the 'lib' compiler option to '$libName' or later.",
                category = DiagnosticCategory.Error, code = 2550,
                fileName = fileName, line = line, character = character,
                start = diagStart, length = diagLength,
            ))
            return
        }
        // A bare lib-interface IDENTIFIER receiver in VALUE position is the CONSTRUCTOR
        // side (`Number.MAX_VALUE`, `String.fromCharCode`) — the embedded lib deliberately
        // has no NumberConstructor/StringConstructor `declare var`, so the resolved
        // INSTANCE interface cannot answer static-member questions: bail, like Array's
        // index-signature path below does (constructorWithIncompleteTypeAnnotation).
        // Lib globals WITH a `declare var` companion (Object/Function/Date/RegExp/Error)
        // carry the Variable flag and keep their typed behavior.
        run {
            if (objectExpr !is Identifier) return@run
            val recvSym = globals[objectExpr.text] ?: return@run
            if (recvSym.declarations.isEmpty() || !recvSym.declarations.all { it in builtinLibDecls }) return@run
            if (recvSym.flags.hasAny(SymbolFlags.Variable)) return@run
            return
        }
        // Check index signatures. For primitive apparent-type checks (16.0),
        // a number-index only matches numeric-looking names (so `s.hmm` on string
        // reports TS2339). For other paths, keep the permissive check since
        // many static-side accesses (e.g. Array.isArray) rely on it to avoid FPs.
        if (objectType.stringIndexInfo != null) return
        if (objectType.numberIndexInfo != null) {
            if (displayTypeOverride == null || propName.toDoubleOrNull() != null) return
        }
        // Try spelling suggestion from known properties
        // The receiver may still be a member-table SHELL (getDeclaredTypeOfSymbol leaves
        // members null until resolveStructuredTypeMembers) — resolve lazily so the
        // spelling-suggestion pool sees the class's real members (`this.method1(2)` on B
        // suggests 'method2', constructorWithIncompleteTypeAnnotation). Error-path-only
        // (a TS2339-family diagnostic is already being emitted), so the first-touch
        // resolution-ordering hazard is bounded.
        if (objectType.properties == null && objectType is Type.Interface && objectType.symbol != null) {
            resolveStructuredTypeMembers(objectType)
        }
        CpaSections.atR(CpaSections.R_EMIT)
        val memberNames = (objectType.properties ?: emptyList()).map { it.name }.toSet()
        val suggestion = getSpellingSuggestionFromNames(propName, memberNames)
        // For static access on class/namespace identifiers, use "typeof X" format
        val rawTypeName = typeToString(displayTypeOverride ?: objectType)
        val typeName = if (!isThisAccess && objectType.symbol?.flags?.hasAny(SymbolFlags.Class) == true) {
            "typeof $rawTypeName"
        } else {
            rawTypeName
        }
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        if (suggestion != null) {
            // Find the declaration of the suggested property for TS2728 related info
            val suggestedProp = objectType.properties?.find { it.name == suggestion }
            val relatedInfo = if (emitTs2728RelatedInfo && suggestedProp != null) {
                val decl = suggestedProp.valueDeclaration ?: suggestedProp.declarations.firstOrNull()
                if (decl != null) {
                    val declPos = when (decl) {
                        is PropertyDeclaration -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        is MethodDeclaration -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        is Parameter -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        else -> decl.pos
                    }
                    val declLength = suggestion.length
                    // M2.2: node-first lib attribution (see libFileOfDecl) — under real libs
                    // a lib member's position can false-match a large user file.
                    val libMapped = libFileOfDecl(decl)
                    val (declFile, declSource) = if (libMapped != null) Pair(libMapped, null)
                        else resolveDeclarationSourceFile(declPos)
                    val resolvedFile = declFile ?: fileName
                    val resolvedSource = declSource ?: source
                    val isLib = libMapped != null || isLibFileName(resolvedFile)
                    val (declLine, declChar) = if (isLib) {
                        Pair(null as Int?, null as Int?)
                    } else {
                        val p = getLineAndCharacterOfPosition(resolvedSource, declPos)
                        Pair(p.first, p.second)
                    }
                    // TypeScript's deprecated HTML helper methods on String (sub, sup, big,
                    // small, bold, italics, etc.) are declared in lib.es5.d.ts.deprecated.d.ts,
                    // but TS error baselines render them as lib.es2015.core.d.ts. Override
                    // the file name for these specific suggestions to match baseline format.
                    val baselineFile = if (isLib && suggestion in DEPRECATED_STRING_HTML_HELPERS)
                        "lib.es2015.core.d.ts" else resolvedFile
                    listOf(Diagnostic(
                        message = "'$suggestion' is declared here.",
                        category = DiagnosticCategory.Message,
                        code = 2728,
                        fileName = baselineFile,
                        line = declLine,
                        character = declChar,
                        start = declPos,
                        length = declLength,
                    ))
                } else emptyList()
            } else emptyList()
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'. Did you mean '$suggestion'?",
                category = DiagnosticCategory.Error,
                code = 2551,
                fileName = fileName,
                line = line,
                character = character,
                start = diagStart,
                length = diagLength,
                relatedInformation = relatedInfo,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'.",
                category = DiagnosticCategory.Error,
                code = 2339,
                fileName = fileName,
                line = line,
                character = character,
                start = diagStart,
                length = diagLength,
            ))
        }
    }

    /**
     * B290: a receiver expression that syntactically resolves to a FRESH object
     * literal — a direct literal, a parenthesized one, or a property-access chain
     * whose every step lands on an object-literal property initializer
     * (`({ foo: {...} }).foo`). Mirrors tsc's type freshness for the
     * isObjectLiteralType branch of getPropertyTypeForIndexType: widening (variable
     * declarations) drops the ObjectLiteral flag, so only these syntactic shapes
     * keep it.
     */
    private fun freshObjectLiteralOf(e: Expression): ObjectLiteralExpression? = when (e) {
        is ObjectLiteralExpression -> e
        is ParenthesizedExpression -> freshObjectLiteralOf(e.expression)
        is PropertyAccessExpression -> {
            val obj = freshObjectLiteralOf(e.expression)
            val pa = obj?.properties?.firstOrNull {
                it is PropertyAssignment && (it.name as? Identifier)?.text == e.name.text
            } as? PropertyAssignment
            pa?.initializer as? ObjectLiteralExpression
        }
        else -> null
    }

    /**
     * B290: source-scan write-context detection for an element access ending at
     * [accessEnd] (position just past the closing `]`). True for `= ` (not `==`),
     * the compound assignment operators, and postfix/prefix `++`/`--`. Mirrors
     * tsc's isAssignmentTarget for the TS7052 get/set suggestion selection.
     */
    private fun elementAccessIsWriteContext(source: String, accessEnd: Int, recvStart: Int): Boolean {
        var i = accessEnd
        while (i < source.length && (source[i] == ' ' || source[i] == '\t')) i++
        if (i + 1 < source.length) {
            val a = source[i]; val b = source[i + 1]
            if ((a == '+' && b == '+') || (a == '-' && b == '-')) return true
        }
        if (i < source.length && source[i] == '=' &&
            source.getOrNull(i + 1) != '=' && source.getOrNull(i + 1) != '>') return true
        // Compound assignments only — `<=`, `>=`, `==`, `!=` are deliberately absent.
        for (op in arrayOf(">>>=", "**=", "<<=", ">>=", "&&=", "||=", "??=", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=")) {
            if (source.startsWith(op, i)) return true
        }
        var j = recvStart - 1
        while (j >= 0 && (source[j] == ' ' || source[j] == '\t' || source[j] == '(')) j--
        if (j >= 1 && ((source[j] == '+' && source[j - 1] == '+') || (source[j] == '-' && source[j - 1] == '-'))) return true
        return false
    }

    /** B290: tsc tryGetPropertyAccessOrIdentifierToString — identifier / dotted chain only. */
    private fun entityPathOf(e: Expression): String? = when (e) {
        is Identifier -> e.text
        is PropertyAccessExpression -> entityPathOf(e.expression)?.let { "$it.${e.name.text}" }
        else -> null
    }

    /**
     * B290: nearest PRECEDING `var/let/const <name> = {objLit}` declaration in the
     * file, by position. Block-scoped declarations are not bound (B83.5) and the
     * file-wide local-type map is last-write-wins, so sibling blocks re-declaring
     * the same name display the wrong shape — position precedence approximates
     * lexical scoping well enough for the receiver-type display.
     */
    private fun nearestPrecedingObjectLiteralDecl(fileName: String, name: String, beforePos: Int): ObjectLiteralExpression? {
        val stmts = fileResults[fileName]?.sourceFile?.statements ?: return null
        var best: ObjectLiteralExpression? = null
        var bestPos = -1
        fun visitStmt(stmt: Node) {
            when (stmt) {
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    val n = d.name as? Identifier ?: continue
                    // Round 463: an ANNOTATED declaration's type is its annotation, not
                    // the initializer literal — `const result: ExtendsResult = { options:
                    // {} }` (tsc commandLineParser.ts) otherwise displays/keys the bare
                    // literal shape and FP's TS7053 on annotation-declared optional
                    // members (`result[propertyName]` for include/exclude/files), even
                    // when the access-site `result` is a DIFFERENT binding (a nested
                    // fn's annotated param). Let the normal typed path own it.
                    if (d.type != null) continue
                    val init = d.initializer as? ObjectLiteralExpression ?: continue
                    if (n.text == name && d.pos < beforePos && d.pos > bestPos) { best = init; bestPos = d.pos }
                }
                is Block -> stmt.statements.forEach(::visitStmt)
                is IfStatement -> { visitStmt(stmt.thenStatement); stmt.elseStatement?.let(::visitStmt) }
                is WhileStatement -> visitStmt(stmt.statement)
                is DoStatement -> visitStmt(stmt.statement)
                is ForStatement -> visitStmt(stmt.statement)
                is ForInStatement -> visitStmt(stmt.statement)
                is ForOfStatement -> visitStmt(stmt.statement)
                is FunctionDeclaration -> stmt.body?.statements?.forEach(::visitStmt)
                else -> {}
            }
        }
        stmts.forEach(::visitStmt)
        return best
    }

    /**
     * B290: the noImplicitAny element-access family — TS7052 ("has no index
     * signature. Did you mean to call 'x.get'?"), TS7053 ("expression of type 'K'
     * can't be used to index type 'T'." + "Property 'p' does not exist" chain),
     * and the fresh-object-literal READ TS2339. Mirrors tsc's
     * getPropertyTypeForIndexType error block (checker.ts ~19330):
     *  - fresh literal receiver + READ + single literal key → TS2339 at the whole
     *    access (writes WIDEN the receiver in checkElementAccessExpression, which
     *    drops the ObjectLiteral flag — so writes fall to the suggestion path);
     *  - suggestion path: method = isAssignmentTarget ? "set" : "get"; receiver has
     *    a single-call-signature member of that name with ≥1 required param whose
     *    first param accepts the key type → TS7052, suggestion prefixed with the
     *    dotted receiver path when expressible (bare method name otherwise);
     *  - else TS7053 with a per-key-kind chain: string literal → the value, union →
     *    FIRST missing member, enum → '[EnumName.member]' of the first member whose
     *    stringified VALUE is missing, unique symbol → '[symName]'.
     * Returns true when a diagnostic was emitted (caller must return).
     */
    private fun tryEmitNoImplicitAnyIndexAccess(
        expr: ElementAccessExpression, source: String, fileName: String,
    ): Boolean {
        if (!(options.noImplicitAny || options.strict)) return false
        if (isJsLikeFileName(fileName)) return false
        val arg = expr.argumentExpression
        val recvExpr = expr.expression

        // ---- key classification ----
        var singleKey: String? = null
        var unionKeys: List<String>? = null
        var enumName: String? = null
        var enumMembers: List<Pair<String, String>>? = null // memberName -> key string
        var uniqueSymbolName: String? = null
        when (arg) {
            is StringLiteralNode -> singleKey = arg.text
            is Identifier -> {
                if (arg.text == "null" || arg.text == "undefined") return false
                val argSym = globals[arg.text]
                val argDecl = argSym?.declarations?.firstOrNull { it is VariableDeclaration } as? VariableDeclaration
                val ann = argDecl?.type
                val annRefName = ((ann as? TypeReference)?.typeName as? Identifier)?.text
                val annRefSym = annRefName?.let { globals[it] }
                val enumDecl = annRefSym?.declarations?.firstOrNull { it is EnumDeclaration } as? EnumDeclaration
                if (ann is TypeOperator && ann.operator == SyntaxKind.UniqueKeyword) {
                    uniqueSymbolName = arg.text
                } else if (annRefSym != null && annRefSym.flags.hasAny(SymbolFlags.Enum) && enumDecl != null &&
                    !annRefSym.flags.hasAny(SymbolFlags.Module)) {
                    computeEnumSymbolValues(annRefSym)
                    val values = enumValues[annRefSym.id] ?: return false
                    val members = mutableListOf<Pair<String, String>>()
                    for (m in enumDecl.members) {
                        val n = (m.name as? Identifier)?.text ?: (m.name as? StringLiteralNode)?.text ?: return false
                        val v = values[n] ?: return false
                        val keyStr = when (v) {
                            is ConstantValue.NumberValue -> v.toString()
                            is ConstantValue.StringValue -> v.value
                        }
                        members.add(n to keyStr)
                    }
                    if (members.isEmpty()) return false
                    enumName = annRefName
                    enumMembers = members
                } else {
                    val t = getTypeOfIdentifier(arg)
                    when {
                        t is Type.StringLiteral -> singleKey = t.value
                        t is Type.Union && t.types.isNotEmpty() && t.types.all { it is Type.StringLiteral } ->
                            unionKeys = t.types.map { (it as Type.StringLiteral).value }
                        else -> return false
                    }
                }
            }
            else -> return false
        }

        // ---- receiver classification ----
        val freshLit = freshObjectLiteralOf(recvExpr)
        var rt: Type? = null
        if (freshLit != null) {
            rt = getTypeOfExpression(freshLit)
        } else if (recvExpr is Identifier) {
            val declInit = nearestPrecedingObjectLiteralDecl(fileName, recvExpr.text, expr.pos)
            rt = if (declInit != null) getTypeOfExpression(declInit)
            else getTypeOfExpression(recvExpr)
        } else if (recvExpr is PropertyAccessExpression) {
            rt = getTypeOfExpression(recvExpr)
        }
        if (rt == null) return false
        // Enum receivers (the enum OBJECT `E["key"]` or enum-typed values) are owned
        // by the pre-existing enum element-access branches (TS7015 / TS2339-typeof) —
        // an enum's implicit reverse/forward index structure is not modeled here.
        if (isEnumFlavoredObjectType(rt)) return false
        if ((recvExpr as? Identifier)?.let { globals[it.text] }?.flags?.hasAny(SymbolFlags.Enum) == true) return false

        // Resolve member names + the get/set member check per receiver kind.
        val memberNames: Set<String>
        val isNamedReceiver: Boolean // interface/reference → TS7052-only (member model incomplete for TS7053)
        val methodChecker: ((String) -> Boolean)?
        when {
            rt is Type.Reference || rt is Type.Interface -> {
                val target = (rt as? Type.Reference)?.target ?: rt as Type.Interface
                val sym = target.symbol ?: return false
                if (sym.declarations.size != 1) return false
                val ifaceDecl = sym.declarations[0] as? InterfaceDeclaration ?: return false
                if (ifaceDecl in builtinLibDecls) return false
                if (!ifaceDecl.heritageClauses.isNullOrEmpty()) return false
                if (ifaceDecl.members.any { it is IndexSignature }) return false
                val tpNames = ifaceDecl.typeParameters?.map { it.name.text } ?: emptyList()
                val typeArgs = (rt as? Type.Reference)?.resolvedTypeArguments
                if (tpNames.isNotEmpty() && (typeArgs == null || typeArgs.size != tpNames.size)) return false
                memberNames = ifaceDecl.members.mapNotNull { m ->
                    when (m) {
                        is MethodDeclaration -> (m.name as? Identifier)?.text
                        is PropertyDeclaration -> (m.name as? Identifier)?.text
                        else -> null
                    }
                }.toSet()
                isNamedReceiver = true
                methodChecker = checker@{ method ->
                    val mds = ifaceDecl.members.filterIsInstance<MethodDeclaration>()
                        .filter { (it.name as? Identifier)?.text == method }
                    if (mds.size != 1) return@checker false
                    val md = mds[0]
                    val required = md.parameters.count { !it.questionToken && it.initializer == null && !it.dotDotDotToken }
                    if (required < 1 || md.parameters.isEmpty()) return@checker false
                    val p0 = md.parameters[0].type ?: return@checker false
                    // The key is a string literal (named receivers only reach here for
                    // string keys) — param must resolve to `string` or `any`.
                    val resolvesToString = when {
                        p0 is KeywordTypeNode && p0.kind == SyntaxKind.StringKeyword -> true
                        p0 is KeywordTypeNode && p0.kind == SyntaxKind.AnyKeyword -> true
                        p0 is TypeReference && (p0.typeName as? Identifier)?.text in tpNames -> {
                            val idx = tpNames.indexOf((p0.typeName as Identifier).text)
                            val at = typeArgs?.getOrNull(idx)
                            at === stringType || at === anyType
                        }
                        else -> false
                    }
                    resolvesToString && singleKey != null
                }
            }
            rt is Type.Object -> {
                resolveStructuredTypeMembers(rt)
                if (rt.stringIndexInfo != null || rt.numberIndexInfo != null) return false
                if (!rt.callSignatures.isNullOrEmpty() || !rt.constructSignatures.isNullOrEmpty()) return false
                val props = rt.properties ?: emptyList()
                memberNames = props.mapTo(mutableSetOf()) { it.name }
                isNamedReceiver = false
                methodChecker = checker@{ method ->
                    val m = props.firstOrNull { it.name == method } ?: return@checker false
                    val mt = (getTypeOfSymbol(m)) as? Type.Object ?: return@checker false
                    val sigs = mt.callSignatures ?: return@checker false
                    if (sigs.size != 1) return@checker false
                    val sig = sigs[0]
                    if (sig.minArgumentCount < 1 && sig.parameters.isEmpty()) return@checker false
                    val p0 = sig.parameters.getOrNull(0) ?: return@checker false
                    val p0t = getTypeOfSymbol(p0)
                    when {
                        p0t === stringType || p0t === anyType || p0t === errorType ->
                            singleKey != null || unionKeys != null
                        p0t is Type.StringLiteral -> singleKey != null && p0t.value == singleKey
                        p0t is Type.Union && p0t.types.all { it is Type.StringLiteral } -> {
                            val accepted = p0t.types.mapTo(mutableSetOf()) { (it as Type.StringLiteral).value }
                            when {
                                singleKey != null -> singleKey in accepted
                                unionKeys != null -> unionKeys.all { it in accepted }
                                else -> false
                            }
                        }
                        else -> false
                    }
                }
            }
            else -> return false
        }

        fun keyPresent(k: String): Boolean = k in memberNames || k in OBJECT_PROTOTYPE_PROPERTIES

        // Existence / spelling-suggestion bail for single keys (defer to the
        // pre-existing TS2339/TS2551 element-access paths).
        if (singleKey != null) {
            if (keyPresent(singleKey)) return false
            if (getSpellingSuggestionFromNames(singleKey, memberNames) != null) return false
        }

        // Whole-access span: receiver start .. just past the closing `]`.
        val argEnd = expressionTrueEnd(arg)
        var cb = argEnd
        while (cb < source.length && source[cb] != ']') cb++
        val accessEnd = if (cb < source.length) cb + 1 else argEnd
        val spanStart = recvExpr.pos
        val spanLength = (accessEnd - spanStart).coerceAtLeast(1)
        val isWrite = elementAccessIsWriteContext(source, accessEnd, recvExpr.pos)
        val recvDisplay = typeToString(widenType(rt))
        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)

        // Fresh literal + READ + single literal key → TS2339 (tsc's
        // isObjectLiteralType branch; only single literals take it).
        if (freshLit != null && !isWrite) {
            if (singleKey == null) return false
            diagnostics.add(Diagnostic(
                message = "Property '$singleKey' does not exist on type '$recvDisplay'.",
                category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                line = line, character = character, start = spanStart, length = spanLength,
            ))
            return true
        }

        val method = if (isWrite) "set" else "get"
        if (methodChecker(method)) {
            val path = entityPathOf(recvExpr)
            val suggestion = if (path != null) "$path.$method" else method
            diagnostics.add(Diagnostic(
                message = "Element implicitly has an 'any' type because type '$recvDisplay' has no index signature. Did you mean to call '$suggestion'?",
                category = DiagnosticCategory.Error, code = 7052, fileName = fileName,
                line = line, character = character, start = spanStart, length = spanLength,
            ))
            return true
        }

        // TS7053 chain path — anonymous receivers only (named-interface member
        // resolution is incomplete: merged/inherited members would FP).
        if (isNamedReceiver) return false
        val chainProp: String
        val indexDisplay: String
        when {
            singleKey != null -> { chainProp = singleKey; indexDisplay = "\"$singleKey\"" }
            unionKeys != null -> {
                val missing = unionKeys.firstOrNull { !keyPresent(it) } ?: return false
                chainProp = missing
                indexDisplay = unionKeys.joinToString(" | ") { "\"$it\"" }
            }
            enumName != null -> {
                val firstMissing = enumMembers!!.firstOrNull { !keyPresent(it.second) } ?: return false
                chainProp = "[$enumName.${firstMissing.first}]"
                indexDisplay = enumName
            }
            uniqueSymbolName != null -> { chainProp = "[$uniqueSymbolName]"; indexDisplay = "unique symbol" }
            else -> return false
        }
        diagnostics.add(Diagnostic(
            message = "Element implicitly has an 'any' type because expression of type '$indexDisplay' can't be used to index type '$recvDisplay'.",
            category = DiagnosticCategory.Error, code = 7053,
            messageChain = listOf("  Property '$chainProp' does not exist on type '$recvDisplay'."),
            fileName = fileName,
            line = line, character = character, start = spanStart, length = spanLength,
        ))
        return true
    }

    /**
     * Element access with literal key: `obj["prop"]` or `obj[0]`.
     * Mirrors `checkSinglePropertyAccess` for the TS2339/TS2551 diagnostic, but only
     * when the argument expression is a string or numeric literal (so the key is known
     * at check time). Runtime index expressions fall through to normal index-signature
     * resolution elsewhere.
     */
    private fun checkSingleElementAccess(
        expr: ElementAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        emitTs1804xForNullishElementAccessReceiver(expr, source, fileName)
        val arg = expr.argumentExpression
        // 17.93: TS2538 "Type 'null'/'undefined' cannot be used as an index type." for
        // element-access indices that resolve to null/undefined. Mirrors TypeScript's
        // checker: this fires independent of strictNullChecks because it's a constant
        // index whose type is exactly null/undefined (not a widened "any" path).
        if (arg is Identifier && (arg.text == "null" || arg.text == "undefined")) {
            val argType = getTypeOfIdentifier(arg)
            if (argType === nullType || argType === undefinedType) {
                // B284: tsc bails out of index checking entirely when the RECEIVER
                // type is the error type — `a[null]` where `a` is unresolved already
                // carries TS2304; no TS2538 is reported on the index. Unresolved
                // receivers are detected via the already-emitted TS2304 at their span
                // (the unresolved-names pass runs earlier in the pipeline).
                val recv = expr.expression
                if (recv is Identifier && (getTypeOfIdentifier(recv) === errorType ||
                        diagnostics.any { it.code == 2304 && it.fileName == fileName && it.start == recv.pos })) return
                val display = if (argType === nullType) "null" else "undefined"
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$display' cannot be used as an index type.",
                    category = DiagnosticCategory.Error,
                    code = 2538,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = arg.pos,
                    length = arg.text.length,
                ))
                return
            }
        }
        // B291: TS2538 'bigint' — a bigint literal is never a valid index
        // (`g[2n]`). Gated to receivers resolving to a concrete object shape
        // (interface/class instance/anonymous object/reference) — `any`/error
        // receivers bail like tsc's isErrorType objectType bail.
        if (arg is BigIntLiteralNode) {
            val rt = getTypeOfExpression(expr.expression)
            if (rt is Type.Object) {
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Type 'bigint' cannot be used as an index type.",
                    category = DiagnosticCategory.Error, code = 2538, fileName = fileName,
                    line = line, character = character, start = arg.pos, length = arg.text.length,
                ))
            }
            return
        }
        // TS2538 'bigint' — a `bigint`-typed IDENTIFIER index (`typedArray[bigNum]`
        // where `bigNum: bigint`). Mirrors the BigIntLiteralNode branch but for a
        // value whose resolved type is exactly `bigint`. Gated to a receiver
        // resolving to a concrete object/reference shape (interface/class instance/
        // anonymous object/reference) — `any`/error receivers bail like tsc.
        if (arg is Identifier && arg.text != "null" && arg.text != "undefined") {
            val argType = getTypeOfExpression(arg)
            if (argType === bigintType) {
                val rt = getTypeOfExpression(expr.expression)
                if (rt is Type.Object || rt is Type.Interface || rt is Type.Reference) {
                    val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type 'bigint' cannot be used as an index type.",
                        category = DiagnosticCategory.Error, code = 2538, fileName = fileName,
                        line = line, character = character, start = arg.pos, length = arg.text.length,
                    ))
                    return
                }
            }
        }
        // 17.178: TS2538 — array-typed index. `arr2[arr1[0]]` where `arr1` is
        // `(string | string[])[]` makes the indexer `string | string[]`, and
        // the `string[]` constituent is invalid as an index. TypeScript reports
        // the FIRST invalid constituent. Conservative gate: only fire when the
        // arg is an ElementAccessExpression (the targeted shape) whose computed
        // type is a Union with at least one Array `Type.Reference` constituent.
        // Squiggle covers the full arg expression via expressionTrueEnd.
        if (arg is ElementAccessExpression) {
            val argType = getTypeOfExpression(arg)
            if (argType is Type.Union) {
                val arrayConstituent = argType.types.firstOrNull { t ->
                    t is Type.Reference && t.target.symbol?.name == "Array"
                }
                if (arrayConstituent != null) {
                    val display = typeToString(arrayConstituent)
                    val argEnd = expressionTrueEnd(arg)
                    val length = (argEnd - arg.pos).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$display' cannot be used as an index type.",
                        category = DiagnosticCategory.Error,
                        code = 2538,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = arg.pos,
                        length = length,
                    ))
                    return
                }
            }
        }
        // B300: TS2538 'typeof <ClassExprName>' — an identifier bound to a CLASS
        // EXPRESSION used as an index (`obj[x]` where `const x = class Derived …`).
        // Class expressions are never bound, so the type-based B127 branch below
        // can't see them; detect the initializer shape directly.
        if (arg is Identifier) {
            val sym = currentFileLocals?.get(arg.text) ?: globals[arg.text]
            val vd = sym?.declarations?.firstOrNull { it is VariableDeclaration } as? VariableDeclaration
            val ce = vd?.initializer as? ClassExpression
            if (ce != null && vd.type == null) {
                val display = ce.name?.text ?: arg.text
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Type 'typeof $display' cannot be used as an index type.",
                    category = DiagnosticCategory.Error, code = 2538, fileName = fileName,
                    line = line, character = character, start = arg.pos, length = arg.text.length,
                ))
                return
            }
        }
        // B127: TS2538 — a user-defined OBJECT/INTERFACE/CLASS-INSTANCE-typed value used
        // directly as a computed index (`obj[x]` where `x: SomeInterface`). An object type
        // is never a valid index (index must be string/number/symbol/literal/enum), so this
        // is FP-safe. Gated to a named `Type.Interface` whose symbol is a user-declared
        // interface/class (NOT a lib wrapper like String/Number/Boolean/Symbol, which may
        // coerce, and NOT an enum, whose members ARE valid indices). Squiggle covers the
        // index identifier only (matches TypeScript's span).
        if (arg is Identifier && arg.text != "null" && arg.text != "undefined") {
            val argType = getTypeOfExpression(arg)
            if (argType is Type.Interface) {
                val sym = argType.symbol
                val nm = sym?.name
                val isWrapper = nm == "String" || nm == "Number" || nm == "Boolean" ||
                    nm == "Symbol" || nm == "Object" || nm == "Function"
                val isEnum = sym?.flags?.hasAny(SymbolFlags.Enum) == true
                val isUserNominal = sym?.declarations?.any {
                    it is InterfaceDeclaration || it is ClassDeclaration || it is ClassExpression
                } == true
                if (!isWrapper && !isEnum && isUserNominal) {
                    val display = typeToString(argType)
                    val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$display' cannot be used as an index type.",
                        category = DiagnosticCategory.Error,
                        code = 2538,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = arg.pos,
                        length = arg.text.length,
                    ))
                    return
                }
            }
        }
        // 17.220: TS2538 — class-instance-typed index via comma expression. Targets the
        // `new Foo[a, b, c]` syntax artifact (parsed as `new (Foo[<comma-expr>])`),
        // where the rightmost operand is `new ClassName(...)`. Narrow gate: arg is a
        // comma BinaryExpression whose rightmost operand is a NewExpression on a
        // class identifier. Type display uses the class identifier text directly
        // (avoids `getReturnTypeOfNewExpression`'s base-class-return-type quirk
        // for derived classes). Squiggle covers full arg span.
        if (arg is BinaryExpression && arg.operator == SyntaxKind.Comma) {
            var rightmost: Expression = arg
            while (rightmost is BinaryExpression && rightmost.operator == SyntaxKind.Comma) {
                rightmost = rightmost.right
            }
            val rightmostNew = rightmost as? NewExpression
            val ctorIdent = rightmostNew?.expression as? Identifier
            val ctorSym = ctorIdent?.let { globals[it.text] }
            val isClass = ctorSym?.declarations?.any { it is ClassDeclaration } == true
            if (ctorIdent != null && isClass) {
                val argEnd = expressionTrueEnd(arg)
                val length = (argEnd - arg.pos).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '${ctorIdent.text}' cannot be used as an index type.",
                    category = DiagnosticCategory.Error,
                    code = 2538,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = arg.pos,
                    length = length,
                ))
                return
            }
        }
        // 17.116: TS7053 "Element implicitly has an 'any' type because expression of
        // type 'any' can't be used to index type 'X'." Fires when the key expression
        // resolves to `any` AND the receiver is an empty `{}`-typed value (Type.Object
        // with no members and no index signatures). Gated on noImplicitAny/strict.
        // Squiggle covers full `receiver[key]` expression. Must run BEFORE the `when (arg)`
        // block which returns for non-literal keys.
        if (arg is Identifier && (options.noImplicitAny || options.strict)) {
            val argType = getTypeOfIdentifier(arg)
            // B70.2: accept both `any` and `string` as the index expression's type.
            // For-in loop variables (typed as `string` via the ForInStatement walker)
            // also trigger TS7053 with `'string'` in the message — TypeScript's rule
            // is "no index signature with a parameter of type 'string'" applies
            // regardless of whether the source is `any` or `string`.
            val argDisplay = when {
                argType === anyType -> "any"
                argType === stringType -> "string"
                else -> null
            }
            if (argDisplay != null) {
                val recvType = getTypeOfExpression(expr.expression)
                // Exclude an ENUM-object receiver: `NumericEnum[key]` is a valid reverse
                // mapping (tsc emits no TS7053), but a numeric enum in value position resolves
                // to an empty `Type.Object` here, which would otherwise match the
                // noProps/noIndex/noCalls gate below. Mirrors the enum exclusion in
                // tryEmitNoImplicitAnyIndexAccess (Checker.kt ~113333). tsc's own
                // moduleNameResolver.ts does `ModuleResolutionKind[moduleResolution]`.
                val recvIsEnum = isEnumFlavoredObjectType(recvType) ||
                    (expr.expression as? Identifier)?.let { currentFileLocals?.get(it.text) ?: globals[it.text] }
                        ?.flags?.hasAny(SymbolFlags.Enum) == true
                if (!recvIsEnum && recvType is Type.Object && recvType !is Type.Reference && recvType !is Type.Interface) {
                    resolveStructuredTypeMembers(recvType)
                    val noProps = recvType.properties.isNullOrEmpty()
                    val noIndex = recvType.stringIndexInfo == null && recvType.numberIndexInfo == null
                    val noCalls = recvType.callSignatures.isNullOrEmpty() && recvType.constructSignatures.isNullOrEmpty()
                    if (noProps && noIndex && noCalls) {
                        val recvStart = expr.expression.pos
                        var closeBracket = arg.pos + arg.text.length
                        while (closeBracket < source.length && source[closeBracket] != ']') closeBracket++
                        val end = if (closeBracket < source.length) closeBracket + 1 else expr.end
                        val length = (end - recvStart).coerceAtLeast(1)
                        val recvDisplay = typeToString(recvType)
                        val (line, character) = getLineAndCharacterOfPosition(source, recvStart)
                        val chain = if (argDisplay == "string") listOf(
                            "  No index signature with a parameter of type 'string' was found on type '$recvDisplay'.",
                        ) else emptyList()
                        diagnostics.add(Diagnostic(
                            message = "Element implicitly has an 'any' type because expression of type '$argDisplay' can't be used to index type '$recvDisplay'.",
                            category = DiagnosticCategory.Error,
                            code = 7053,
                            messageChain = chain,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = recvStart,
                            length = length,
                        ))
                        return
                    }
                }
            }
        }
        // B290: the noImplicitAny element-access family (TS7052/TS7053/fresh-read
        // TS2339). Runs BEFORE the r167 union-key block so non-fresh receivers get
        // the tsc TS7053 chain; fresh-receiver union keys deliberately fall through
        // to r167 (its domain).
        if (tryEmitNoImplicitAnyIndexAccess(expr, source, fileName)) return
        // B98.r167: TS2339 for `{ objLit }[id]` where `id` has a UNION-of-literal
        // type and one literal is not a key of the FRESH object literal. Gated:
        // receiver resolves to a fresh Type.Object (own props, no index sig, no
        // call/construct sigs), index resolves to a Type.Union whose members are
        // ALL string/number literal types. FP-safe — a missing key on a closed
        // object literal is always a TypeScript error; the no-index-signature gate
        // excludes `({...} as Record<...>)[id]` shapes.
        run {
            if (arg is StringLiteralNode || arg is NumericLiteralNode) return@run
            val recvType = getTypeOfExpression(expr.expression)
            if (recvType !is Type.Object || recvType is Type.Reference || recvType is Type.Interface) return@run
            resolveStructuredTypeMembers(recvType)
            if (recvType.stringIndexInfo != null || recvType.numberIndexInfo != null) return@run
            if (!recvType.callSignatures.isNullOrEmpty() || !recvType.constructSignatures.isNullOrEmpty()) return@run
            val props = recvType.properties ?: return@run
            if (props.isEmpty()) return@run
            val idxType = getTypeOfExpression(arg)
            if (idxType !is Type.Union) return@run
            val keys = props.map { it.name }.toSet()
            var missing: String? = null
            for (m in idxType.types) {
                val k = when (m) {
                    is Type.StringLiteral -> m.value
                    is Type.NumberLiteral -> m.toString()
                    else -> return@run // a non-literal member → not a closed-key index
                }
                if (k !in keys && missing == null) missing = k
            }
            if (missing != null) {
                val recvStart = expr.expression.pos
                var closeBracket = expressionTrueEnd(arg)
                while (closeBracket < source.length && source[closeBracket] != ']') closeBracket++
                val end = if (closeBracket < source.length) closeBracket + 1 else expr.end
                val length = (end - recvStart).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, recvStart)
                val recvDisplay = props.joinToString(prefix = "{ ", separator = "; ", postfix = "; }") { sym ->
                    val pt = symbolTypes[sym.id] ?: getTypeOfSymbol(sym)
                    "${sym.name}: ${typeToString(widenType(pt))}"
                }
                diagnostics.add(Diagnostic(
                    message = "Property '$missing' does not exist on type '$recvDisplay'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = line, character = character, start = recvStart, length = length,
                ))
                return
            }
        }
        val propName: String
        val diagStart: Int
        val diagLength: Int
        // Squiggle covers the whole `receiver[key]` expression (TS2576 convention).
        // For TS2339/TS2551 element access, `propName` is set but the squiggle length
        // we pass stays narrow (key+brackets) to match existing element-access behavior.
        when (arg) {
            is StringLiteralNode -> {
                propName = arg.text
                diagStart = arg.pos
                diagLength = (arg.rawText?.length ?: arg.text.length) + 2
            }
            is NumericLiteralNode -> {
                propName = arg.text
                diagStart = arg.pos
                diagLength = arg.text.length
            }
            else -> return
        }
        // 17.116: TS7015 "Element implicitly has an 'any' type because index expression
        // is not of type 'number'." Fires when a StringLiteral key accesses an enum-typed
        // identifier AND the key isn't a known enum member name AND the key isn't a
        // numeric-looking string. Enums have implicit number-index sigs (member name
        // string -> number for forward, number -> name for reverse); a non-numeric string
        // key bypasses both. Gated on noImplicitAny/strict.
        //
        // 17.162: When NOT in strict mode, the same shape (enum + non-numeric string key
        // not matching a known member) emits TS2339 "Property 'X' does not exist on
        // type 'typeof E'." instead — TypeScript's behavior for `const enum E { A }; E["B"]`
        // and equivalent regular-enum cases. The const-enum case is the primary target
        // (`constEnumBadPropertyNames_ts`); regular enums get the same diagnostic for
        // non-member non-numeric string keys because the property still doesn't exist on
        // the enum's static shape.
        if (arg is StringLiteralNode) {
            val recvIdent = expr.expression as? Identifier
            if (recvIdent != null) {
                val recvSym = globals[recvIdent.text]
                if (recvSym != null && recvSym.flags.hasAny(SymbolFlags.Enum)) {
                    val isNumericKey = arg.text.toDoubleOrNull() != null
                    val isKnownMember = recvSym.exports?.containsKey(arg.text) == true
                    if (!isNumericKey && !isKnownMember) {
                        val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                        if (options.noImplicitAny || options.strict) {
                            diagnostics.add(Diagnostic(
                                message = "Element implicitly has an 'any' type because index expression is not of type 'number'.",
                                category = DiagnosticCategory.Error,
                                code = 7015,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = arg.pos,
                                length = (arg.rawText?.length ?: arg.text.length) + 2,
                            ))
                        } else {
                            diagnostics.add(Diagnostic(
                                message = "Property '${arg.text}' does not exist on type 'typeof ${recvIdent.text}'.",
                                category = DiagnosticCategory.Error,
                                code = 2339,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = arg.pos,
                                length = (arg.rawText?.length ?: arg.text.length) + 2,
                            ))
                        }
                        return
                    }
                }
            }
        }
        // B292 (broadened round 452): a LITERAL-key element access on a STRING-typed
        // receiver is never TS2339 in tsc — element access on a primitive is TS7053 under
        // noImplicitAny and SILENT otherwise (the property-existence TS2339 path is
        // property-access only). Covers a non-numeric string key (`s["s"]`), a
        // numeric-looking string key (`s["0"]`), AND a numeric-literal key (`s[0]` →
        // `String`'s numeric index sig). The identifier-receiver case `str[0]` already
        // resolved elsewhere, but an element-access-typed receiver `(arr[i])[0]` (whose
        // inner access is typed `string`) reached this missing-member path and FP'd
        // "Property '0' does not exist on type 'string'." (jsTyping.ts `pathComponents[
        // ...][0] === "@"`). FP-safe: every literal index into a string is valid.
        if (arg is StringLiteralNode || arg is NumericLiteralNode) {
            val rt = getTypeOfExpression(expr.expression)
            if (rt === stringType || rt is Type.StringLiteral) return
            // Round 459: a NUMERIC-literal element access on a UNION-OF-TUPLES receiver
            // (`value[1]` where value: [A] | [A, B] — tsc's toBuilderFileEmit over
            // IncrementalBuildInfoFilePendingEmit, builder.ts:2242) resolves per-member
            // in tsc with `undefined` for the out-of-bounds members — never TS2339 as
            // long as SOME member has the index. A key out of bounds for EVERY member
            // still falls through and fires.
            if (arg is NumericLiteralNode) {
                // The DECLARED type may carry non-tuple members a preceding guard removed
                // (`isNumber(value) ? … : value[1]` — FileId dropped) — test the NARROWED
                // receiver, like the TS2339 emission itself does.
                val rtn = if (rt is Type.Union && getReferencePath(expr.expression) != null)
                    getNarrowedTypeForReference(rt, expr.expression) else rt
                val idx = arg.text.toIntOrNull()
                if (idx != null && rtn is Type.Union &&
                    rtn.types.all { (it as? Type.Object)?.tupleElementTypes != null } &&
                    rtn.types.any { (it as Type.Object).tupleElementTypes!!.size > idx }) return
            }
        }
        // Build the raw suggestion syntax for TS2576 from the source text:
        // - StringLiteral key keeps original quoting: a["\""] → `["\""]`
        // - Numeric key: a[0] → `[0]`
        // Position: from `[` (just before arg.pos) to end of key.
        val keySuggestion: String = run {
            val keyEnd = when (arg) {
                is StringLiteralNode -> arg.pos + (arg.rawText?.length ?: arg.text.length) + 2
                is NumericLiteralNode -> arg.pos + arg.text.length
            }
            // Find opening `[` by scanning backwards from arg.pos.
            var openBracket = arg.pos - 1
            while (openBracket >= 0 && source[openBracket] != '[') openBracket--
            if (openBracket < 0) return@run ".$propName"
            // Expected layout: `[keySrc]` — closing bracket just after keyEnd (possibly with whitespace).
            var closeBracket = keyEnd
            while (closeBracket < source.length && source[closeBracket] != ']') closeBracket++
            if (closeBracket >= source.length) return@run ".$propName"
            source.substring(openBracket, closeBracket + 1)
        }
        // TS2576 squiggle covers the whole `receiver[key]` expression. For compat with the
        // existing TS2339 path, pass a SEPARATE squiggle range via the TS2576 helper — we
        // only widen when TS2576 actually fires (in tryEmitStaticAccessTs2576).
        // Compute the full expression span (receiver.pos .. closeBracket+1):
        val fullStart = expr.expression.pos
        val fullEnd = run {
            var cb = diagStart + diagLength
            while (cb < source.length && source[cb] != ']') cb++
            if (cb < source.length) cb + 1 else diagStart + diagLength
        }
        val fullLength = fullEnd - fullStart
        checkMemberAccessMissing(
            objectExprIn = expr.expression,
            propName = propName,
            diagStart = diagStart,
            diagLength = diagLength,
            source = source,
            fileName = fileName,
            enclosingClassType = enclosingClassType,
            emitTs2728RelatedInfo = false,
            keySuggestion = keySuggestion,
            ts2576SquiggleStart = fullStart,
            ts2576SquiggleLength = fullLength,
        )
    }

    /**
     * B98.r92: True for the exact "value access of a hidden namespace member" shape —
     * a NON-ambient namespace `nsSym` whose body declares `propName` as a NON-exported
     * nested namespace (value-side hidden) with NO value-accessible export of that name
     * (an exported `interface`/`type` sibling is type-only and does NOT make it
     * value-accessible). For such an access TypeScript emits TS2339 even though
     * `isNameExportedFromNamespace` returns true. FP firewall: requires BOTH a hidden
     * (non-exported) namespace decl AND the absence of any exported value-side decl.
     */
    private fun shouldEmitTs2339ForHiddenNamespaceMember(nsSym: Symbol, propName: String): Boolean {
        if (nsSym.flags.hasAny(SymbolFlags.NamespaceModule)) return false
        var foundAny = false
        var hasHiddenNamespace = false
        var hasValueAccessibleExport = false
        for (nsDecl in nsSym.declarations) {
            val body = (nsDecl as? ModuleDeclaration)?.body as? ModuleBlock ?: continue
            for (stmt in body.statements) {
                when (stmt) {
                    is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == propName) {
                        foundAny = true
                        if (ModifierFlag.Export in stmt.modifiers) hasValueAccessibleExport = true else hasHiddenNamespace = true
                    }
                    is VariableStatement -> for (d in stmt.declarationList.declarations) {
                        if ((d.name as? Identifier)?.text == propName) {
                            foundAny = true
                            if (ModifierFlag.Export in stmt.modifiers) hasValueAccessibleExport = true
                        }
                    }
                    is FunctionDeclaration -> if (stmt.name?.text == propName) { foundAny = true; if (ModifierFlag.Export in stmt.modifiers) hasValueAccessibleExport = true }
                    is ClassDeclaration -> if (stmt.name?.text == propName) { foundAny = true; if (ModifierFlag.Export in stmt.modifiers) hasValueAccessibleExport = true }
                    is EnumDeclaration -> if (stmt.name.text == propName) { foundAny = true; if (ModifierFlag.Export in stmt.modifiers) hasValueAccessibleExport = true }
                    is ImportEqualsDeclaration -> if (stmt.name.text == propName) { foundAny = true; hasValueAccessibleExport = true }
                    else -> {} // interface / type-alias: type-only, not value-accessible
                }
            }
        }
        return foundAny && hasHiddenNamespace && !hasValueAccessibleExport
    }

    /** Check if `propName` is exported from a namespace symbol. */
    /**
     * (CHK.50) Is [node] lexically inside a `declare`-modified ModuleDeclaration?
     * That is TypeScript's ambient CONTEXT for a namespace body: every declaration
     * in it is ambient and implicitly exported, whether or not it repeats the
     * modifier. Ascends only through module machinery, so an unindexed/synthesized
     * node (parent `null`) answers false.
     */
    private fun isInAmbientModuleContext(node: Node): Boolean {
        var cur = (node as NodeBase).parent
        while (cur != null && cur !is SourceFile) {
            if (cur is ModuleDeclaration && ModifierFlag.Declare in cur.modifiers) return true
            cur = (cur as NodeBase).parent
        }
        return false
    }

    private fun isNameExportedFromNamespace(nsSym: Symbol, propName: String): Boolean {
        val memberSym = nsSym.exports?.get(propName) ?: return false
        // Sub-namespaces (Module flag) are always accessible
        if (memberSym.flags.hasAny(SymbolFlags.Module)) return true
        // Ambient namespaces (declare namespace) implicitly export all members
        if (nsSym.flags.hasAny(SymbolFlags.NamespaceModule)) return true
        // (CHK.50) …and so does a namespace that is ambient by CONTEXT rather than
        // by its own modifier. `declare global { namespace NodeJS { interface
        // ProcessEnv … } }` — the shape every `@types` package is written in — gives
        // the inner `namespace` no `declare` of its own, so [Binder]
        // `bindModuleDeclaration` types it `ValueModule` and the flag test above
        // misses; before (CHK.50) published the block's exports the receiver typed
        // `any` and nothing asked. The context is exactly "an enclosing
        // ModuleDeclaration carries `declare`", which covers `declare global`,
        // `declare module "spec"` and `declare namespace A { namespace B { … } }`
        // alike. Deliberately NOT widened to "the file is a .d.ts": that is a much
        // larger population with corpus baselines over it and no defect asking for it.
        if (nsSym.declarations.any { it is ModuleDeclaration && isInAmbientModuleContext(it) }) return true
        // Non-ambient: check for explicit ExportValue flag
        if (memberSym.flags.hasAny(SymbolFlags.ExportValue)) return true
        for (decl in memberSym.declarations) {
            when (decl) {
                is FunctionDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is ClassDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is InterfaceDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is TypeAliasDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is EnumDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                is ModuleDeclaration -> if (ModifierFlag.Export in decl.modifiers) return true
                else -> {}
            }
        }
        // For variables, scan namespace body for VariableStatement with export modifier
        for (nsDecl in nsSym.declarations) {
            val body = (nsDecl as? ModuleDeclaration)?.body as? ModuleBlock ?: continue
            for (stmt in body.statements) {
                if (stmt !is VariableStatement) continue
                if (ModifierFlag.Export !in stmt.modifiers) continue
                for (d in stmt.declarationList.declarations) {
                    if (d.name is Identifier && (d.name).text == propName) return true
                }
            }
        }
        return false
    }

    /** Check if `name` is a static member of `classDecl` (including inherited). */
    /**
     * Returns true if [classDecl] (or a base class) declares an INSTANCE member named [name].
     * Instance members include:
     *  - non-static PropertyDeclaration / MethodDeclaration / GetAccessor / SetAccessor
     *  - Constructor parameter properties (parameters with an access modifier or readonly)
     * Used to suppress TS2576 "did you mean static" for `this.X` when the class has
     * BOTH an instance member X and a static member X. `this.X` in an instance method
     * legitimately resolves to the instance member.
     */
    /** Walk [classDecl]'s instance-side member set + extends chain looking for a
     *  member named [propName]. Returns:
     *
     *  - `true` — member found in this class or any safely-resolvable base.
     *  - `false` — chain fully resolved (terminates at a class with no extends or
     *    a cycle) without finding the member.
     *  - `null` — chain has un-resolvable parts (non-Identifier extends like
     *    `Foo.Bar` or `q<T>()`, an Identifier base whose symbol isn't a
     *    [ClassDeclaration] in [globals], an `IndexSignature` member that would
     *    accept any property name, or a `declare class` whose lib augmentations
     *    we can't see). Caller MUST treat `null` as "unsafe to emit" and bail.
     *
     *  Used by TS2339 emitters that need to ask "is this property genuinely
     *  missing from the entire instance-side view?" without re-walking the
     *  chain manually. Implements clauses are intentionally NOT followed —
     *  per [resolveBaseTypesLazy], implements is a structural constraint, not
     *  a source of inherited members. */
    /** Set of class names that have a sibling [InterfaceDeclaration] with the
     *  same name in any binderResult. Our binder's `canMerge` does not include
     *  Class+Interface, so the second-bound declaration silently overwrites
     *  the first, and `symbol.declarations` ends up holding only one — but the
     *  AST still contains both, and TypeScript treats them as a merged
     *  declaration with combined member sets. The chain walker must bail for
     *  these names because it can't see members contributed by the
     *  non-canonical sibling declaration. Computed on first access (during init)
     *  via [classNamesWithSiblingInterfacesCache] — cannot use `by lazy {}`
     *  because that would declare the property after init and the Lazy backing
     *  field would be null during init-time access. */
    private fun classNamesWithSiblingInterfaces(): Set<String> {
        classNamesWithSiblingInterfacesCache?.let { return it }
        val byName = mutableMapOf<String, MutableSet<String>>()
        for (binderResult in binderResults) {
            for (stmt in binderResult.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> {
                        val n = stmt.name?.text ?: continue
                        byName.getOrPut(n) { mutableSetOf() }.add("C")
                    }
                    is InterfaceDeclaration -> {
                        byName.getOrPut(stmt.name.text) { mutableSetOf() }.add("I")
                    }
                    else -> {}
                }
            }
        }
        val result = byName.filterValues { "C" in it && "I" in it }.keys
        classNamesWithSiblingInterfacesCache = result
        return result
    }

    private fun lookupInstanceMemberInResolvableChain(
        classDecl: ClassDeclaration, propName: String, visited: MutableSet<String>? = null,
        enclosingNs: Symbol? = null,
    ): Boolean? {
        val v = visited ?: mutableSetOf()
        val className = classDecl.name?.text ?: return null
        if (!v.add(className)) return false
        if (className in classNamesWithSiblingInterfaces()) return null
        if (classDecl.members.any { it is IndexSignature }) return null
        if (ModifierFlag.Declare in classDecl.modifiers) return null
        for (m in classDecl.members) {
            when (m) {
                is PropertyDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is MethodDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is GetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is SetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == propName) return true
                }
                is Constructor -> {
                    for (p in m.parameters) {
                        if (p.modifiers.isEmpty()) continue
                        if ((p.name as? Identifier)?.text == propName) return true
                    }
                }
                else -> {}
            }
        }
        val baseExpr = classDecl.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression ?: return false
        if (baseExpr !is Identifier) return null
        // Resolve the base via the enclosing namespace's exports first (a namespace-local
        // base is not in `globals`), falling back to `globals`. Without this a namespace-local
        // base returns `null` (uncertain → the caller bails), which — now that
        // getTypeFromBaseTypeExpression populates baseTypes for namespace-local bases — would
        // swallow a genuinely-missing-member TS2339. `false` still propagates ONLY through a
        // fully-resolvable chain, so this stays FP-safe (uncertainty → null → bail). `enclosingNs`
        // is null for the non-`this` callers → globals-only (unchanged).
        val baseSym = enclosingNs?.exports?.get(baseExpr.text) ?: globals[baseExpr.text] ?: return null
        val baseDecl = baseSym.declarations.firstOrNull() as? ClassDeclaration ?: return null
        // Recurse in the base's OWN namespace (a sibling class shares this one; a base pulled
        // from globals resets to null).
        val baseNs = baseSym.parent?.takeIf { it.flags.hasAny(SymbolFlags.Module) } ?: enclosingNs
        return lookupInstanceMemberInResolvableChain(baseDecl, propName, v, baseNs)
    }

    private fun hasInstanceMemberNamed(classDecl: ClassDeclaration, name: String, visited: MutableSet<String>? = null): Boolean {
        val v = visited ?: mutableSetOf()
        val className = classDecl.name?.text ?: return false
        if (!v.add(className)) return false
        for (m in classDecl.members) {
            when (m) {
                is PropertyDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is MethodDeclaration -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is GetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is SetAccessor -> {
                    if (ModifierFlag.Static !in m.modifiers && classMemberNameText(m.name) == name) return true
                }
                is Constructor -> {
                    for (p in m.parameters) {
                        if (p.modifiers.isEmpty()) continue
                        if ((p.name as? Identifier)?.text == name) return true
                    }
                }
                else -> {}
            }
        }
        val baseExpr = classDecl.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression
        if (baseExpr is Identifier) {
            val baseSym = globals[baseExpr.text]
            if (baseSym != null) {
                val baseDecl = baseSym.declarations.firstOrNull() as? ClassDeclaration
                if (baseDecl != null && hasInstanceMemberNamed(baseDecl, name, v)) return true
            }
        }
        return false
    }

    /** TS2576 when `instance.X` / `instance["X"]` accesses a STATIC-only member of the class.
     *  Returns true if emitted (caller should return early).
     *
     *  Only fires for INSTANCE-side access: skip when the receiver type already carries the
     *  property (e.g. `const k2: typeof K; k2.bar` — k2's type is the constructor side, so
     *  `bar` resolves there and `k2.bar` is legitimate). */
    /** TS2339 when a class-instance receiver accesses a property that is genuinely
     *  absent from the class hierarchy.
     *
     *  Conservative gates defend against false positives:
     *   - propName not in [RUNTIME_PROPERTIES];
     *   - symbol has exactly 1 declaration (no interface/namespace augmentation
     *     contributing extra members);
     *   - class is non-generic (TypeParam constraints could supply members we
     *     don't yet check structurally);
     *   - chain walk via [lookupInstanceMemberInResolvableChain] returns `false`
     *     (own + entire extends chain resolved cleanly, no member found). The
     *     helper itself bails (`null`) on hazardous shapes — non-Identifier
     *     extends (`Foo.Bar`, `q<T>()`), unresolvable Identifier bases, ambient
     *     bases (`declare class`), index signatures, or sibling
     *     [InterfaceDeclaration]s of the same name in any binderResult (since
     *     our binder's `canMerge` does not include Class+Interface, those
     *     declarations would silently overwrite each other and the helper can't
     *     see members from the lost declaration);
     *   - flow narrowing yields the same type (e.g., `if (c instanceof D) c.bar()`
     *     narrows `c` from C to D which may have `bar` — the narrowed type
     *     differs and we bail).
     *
     *  Implements clauses are NOT inherited members per [resolveBaseTypesLazy]'s
     *  skip-implements rule, so this fires correctly for
     *  `class C implements A {}; let c: C; c.bar()` where A has only `static bar()`. */
    private fun tryEmitClassInstanceMissingTs2339(
        typeSym: Symbol, rawType: Type, propName: String, objectExpr: Expression,
        diagStart: Int, diagLength: Int, source: String, fileName: String,
    ) {
        if (propName.isEmpty()) return
        if (propName in RUNTIME_PROPERTIES) return
        // 17.130: Count only "shape-defining" declarations (Class/Interface/TypeAlias/Module).
        // Import-specifier and alias declarations are appended via `mergeSymbolTable` at init's
        // global merge step (see CLAUDE.md "ALL file locals merged into globals" gotcha), but
        // they don't contribute members to the class shape. Pre-fix: `declarations.size != 1`
        // bailed whenever a class was imported into any file, over-suppressing TS2339.
        val shapeDecls = typeSym.declarations.count { d ->
            d is ClassDeclaration || d is InterfaceDeclaration ||
                d is TypeAliasDeclaration || d is ModuleDeclaration
        }
        if (shapeDecls != 1) return
        val classDecl = typeSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: return
        if (!classDecl.typeParameters.isNullOrEmpty()) return
        // Walk own + extends chain. The helper itself bails on IndexSignature
        // and `declare class` (in this class OR any base), so those gates need
        // not be repeated at this level. `null` means chain isn't safely
        // resolvable (complex extends like `Foo.Bar`, unresolved Identifier,
        // ambient base, etc.); `true` means a base in the chain declares the
        // property; only `false` means "genuinely missing across the entire
        // resolvable instance side".
        if (lookupInstanceMemberInResolvableChain(classDecl, propName) != false) return
        if (isStaticMemberOfClass(classDecl, propName)) return
        val narrowed = getNarrowedTypeForReference(rawType, objectExpr)
        if (narrowed !== rawType) return
        val typeName = classDecl.name?.text ?: typeSym.name
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        if (emitClassChainTs2551Suggestion(classDecl, propName, typeName, diagStart, diagLength, source, fileName)) return
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$typeName'.",
            category = DiagnosticCategory.Error, code = 2339,
            fileName = fileName, line = line, character = character,
            start = diagStart, length = diagLength,
        ))
    }

    /** Spelling suggestion over a class's resolvable extends chain's instance member names —
     *  tsc emits TS2551 "… Did you mean 'method2'?" + TS2728 related at the member
     *  (`this.method1(2)` on B whose base A parsed empty,
     *  constructorWithIncompleteTypeAnnotation). Returns true when the TS2551 was emitted. */
    private fun emitClassChainTs2551Suggestion(
        classDecl: ClassDeclaration, propName: String, typeName: String,
        diagStart: Int, diagLength: Int, source: String, fileName: String,
    ): Boolean {
        val pool = mutableMapOf<String, Identifier>()
        var cur: ClassDeclaration? = classDecl
        var hops = 0
        while (cur != null && hops++ < 10) {
            for (m in cur.members) {
                val nameId = when (m) {
                    is MethodDeclaration -> if (ModifierFlag.Static !in m.modifiers) m.name as? Identifier else null
                    is PropertyDeclaration -> if (ModifierFlag.Static !in m.modifiers) m.name as? Identifier else null
                    is GetAccessor -> if (ModifierFlag.Static !in m.modifiers) m.name as? Identifier else null
                    is SetAccessor -> if (ModifierFlag.Static !in m.modifiers) m.name as? Identifier else null
                    else -> null
                }
                if (nameId != null && nameId.text.isNotEmpty() && nameId.text !in pool) pool[nameId.text] = nameId
            }
            val baseName = (cur.heritageClauses
                ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                ?.types?.firstOrNull()?.expression as? Identifier)?.text
            cur = baseName?.let { globals[it]?.declarations?.firstOrNull { d -> d is ClassDeclaration } as? ClassDeclaration }
        }
        val suggestion = getSpellingSuggestionFromNames(propName, pool.keys) ?: return false
        val suggNode = pool[suggestion] ?: return false
        val (declFile, declSource) = resolveDeclarationSourceFile(suggNode.pos)
        val relFile = declFile ?: fileName
        val relSource = declSource ?: source
        val (relLine, relChar) = getLineAndCharacterOfPosition(relSource, suggNode.pos)
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$typeName'. Did you mean '$suggestion'?",
            category = DiagnosticCategory.Error, code = 2551,
            fileName = fileName, line = line, character = character,
            start = diagStart, length = diagLength,
            relatedInformation = listOf(Diagnostic(
                message = "'$suggestion' is declared here.",
                category = DiagnosticCategory.Message, code = 2728,
                fileName = relFile, line = relLine, character = relChar,
                start = suggNode.pos, length = suggestion.length,
            )),
        ))
        return true
    }

    private fun tryEmitStaticAccessTs2576(
        typeSym: Symbol, propName: String, diagStart: Int, diagLength: Int,
        suggestionKey: String, source: String, fileName: String,
        receiverType: Type? = null,
    ): Boolean {
        if (propName.isEmpty()) return false
        if (propName in RUNTIME_PROPERTIES) return false
        // Only fire for INSTANCE-side access (Type.Interface). Constructor-side receivers
        // (`typeof C`, Type.Object built by `getTypeOfSymbolForTypeQuery`) carry static
        // members as actual properties and should fall through to normal TS2339 checking.
        // NOTE: Type.Interface extends Type.Object so `is Type.Object` alone matches both.
        if (receiverType != null && receiverType !is Type.Interface && receiverType is Type.Object) return false
        val classDecl = typeSym.declarations.firstOrNull() as? ClassDeclaration ?: return false
        if (!isStaticMemberOfClass(classDecl, propName)) return false
        if (hasInstanceMemberNamed(classDecl, propName)) return false
        val baseName = classDecl.name?.text ?: typeSym.name
        val (line, character) = getLineAndCharacterOfPosition(source, diagStart)
        diagnostics.add(Diagnostic(
            message = "Property '$propName' does not exist on type '$baseName'. Did you mean to access the static member '$baseName$suggestionKey' instead?",
            category = DiagnosticCategory.Error, code = 2576,
            fileName = fileName, line = line, character = character,
            start = diagStart, length = diagLength,
        ))
        return true
    }

    private fun classMemberNameText(nameNode: Node?): String? = when (nameNode) {
        is Identifier -> nameNode.text
        is StringLiteralNode -> nameNode.text
        is NumericLiteralNode -> nameNode.text
        // B451: a computed member name `[2]`/`["4"]` with a literal inner is a STATIC key,
        // so `z[2]` resolves against the instance member rather than FP'ing TS2339.
        // Round 933: DELEGATED to [computedLiteralKey] rather than re-spelling its `when`.
        // The two copies had drifted — this one still refused a backtick-quoted key after
        // the type-building site accepted it, so a class's own `` [`cp`] `` member resolved
        // for TS2322 and simultaneously FP'd TS2339 from this walker, in ONE compile.
        // The archive's B451 entry is explicit that this family has >= 5 independent
        // extraction sites; one shared definition is the only thing that keeps them level.
        // Round 937 — (CHK.5)(a): and LATE-BOUND keys for the same reason, one round on.
        // `class C { [K]: number }` with `const K = "p"` declares `p` at the type-building
        // site now, so a walker that still refused the key would answer "definitely no such
        // member" for a member the type HAS — which is precisely the TS2339 false positive
        // this stage exists to close (`c.p`, measured against tsc 7.0.2, which reads it as
        // `number`). [lookupInstanceMemberInResolvableChain] is that firewall's entry.
        is ComputedPropertyName -> computedLiteralKey(nameNode) ?: lateBoundComputedKeyName(nameNode)
        else -> null
    }

    private fun isStaticMemberOfClass(classDecl: ClassDeclaration, name: String, visited: MutableSet<String>? = null): Boolean {
        val v = visited ?: mutableSetOf()
        val className = classDecl.name?.text ?: return false
        if (!v.add(className)) return false
        for (m in classDecl.members) {
            val memberName = when (m) {
                is PropertyDeclaration -> classMemberNameText(m.name)
                is MethodDeclaration -> classMemberNameText(m.name)
                is GetAccessor -> classMemberNameText(m.name)
                is SetAccessor -> classMemberNameText(m.name)
                else -> null
            }
            if (memberName != name) continue
            val isStatic = when (m) {
                is PropertyDeclaration -> ModifierFlag.Static in m.modifiers
                is MethodDeclaration -> ModifierFlag.Static in m.modifiers
                is GetAccessor -> ModifierFlag.Static in m.modifiers
                is SetAccessor -> ModifierFlag.Static in m.modifiers
                else -> false
            }
            if (isStatic) return true
        }
        val baseExpr = classDecl.heritageClauses
            ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            ?.types?.firstOrNull()?.expression
        if (baseExpr is Identifier) {
            val baseSym = globals[baseExpr.text]
            if (baseSym != null) {
                val baseDecl = baseSym.declarations.firstOrNull() as? ClassDeclaration
                if (baseDecl != null && isStaticMemberOfClass(baseDecl, name, v)) return true
            }
        }
        return false
    }

    /**
     * Resolve the type of a property access's object expression.
     * Enhanced version that handles 'this' with class context.
     */
    private fun resolvePropertyAccessObjectType(expr: Expression, enclosingClassType: Type?): Type {
        if (expr is Identifier && expr.text == "this" && enclosingClassType != null) {
            return enclosingClassType
        }
        return getTypeOfExpression(expr)
    }

    // -----------------------------------------------------------------------
    // TS2345: Argument type checking (Phase 4 item 7a)
    // -----------------------------------------------------------------------

    /**
     * Resolve the namespace [Symbol] a [ModuleDeclaration]'s name refers to, handling BOTH a
     * simple `Identifier` (`namespace M`) and a left-nested dotted name (`namespace A.B.C`, which
     * our parser represents as a `PropertyAccessExpression` chain `((A.B).C)`). The binder declares
     * nested symbols `A → exports[B] → exports[C]` (see `bindModuleDeclaration`), so we flatten the
     * segments, resolve the head via the inference-namespace top / file-locals / globals, then walk
     * `.exports` down to the innermost segment. Used by the call-types walker so a dotted namespace
     * body is pushed onto `inferenceNamespaceStack` and its internal class/function names resolve
     * (recursiveClassReferenceTest: `new State(self)` inside `namespace Sample.Thing.Languages.PlainText`).
     */
    private fun resolveModuleDeclNamespaceSymbol(nameExpr: Expression): Symbol? {
        val segments = mutableListOf<String>()
        var cur: Expression = nameExpr
        while (cur is PropertyAccessExpression) {
            segments.add(0, cur.name.text)
            cur = cur.expression
        }
        when (cur) {
            is Identifier -> segments.add(0, cur.text)
            else -> return null
        }
        if (segments.isEmpty()) return null
        var sym: Symbol? = if (inferenceNamespaceStack.isNotEmpty()) {
            inferenceNamespaceStack.last().exports?.get(segments[0])
        } else null
        if (sym == null) sym = currentFileLocals?.get(segments[0]) ?: globals[segments[0]]
        for (i in 1 until segments.size) {
            sym = sym?.exports?.get(segments[i]) ?: return null
        }
        return sym
    }

    private fun checkCallTypesInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            checkCallTypesInStatement(stmt, source, fileName)
        }
    }

    /** M1.11: body-nested named functions are UNBOUND (B83.5), so an identifier
     *  resolution inside this body that falls through to `currentFileLocals`/`globals`
     *  lands on a same-named file-level/imported/cross-file declaration — the WRONG
     *  signature (emitter.ts's nested `writeFile` sibling vs the utilities import →
     *  FP TS2345 'undefined' ≁ 'string'). Register a conservative anyType bail for
     *  each nested fn whose name COLLIDES with an outer binding so both callee
     *  (getCalleeType) and argument (getTypeOfIdentifier) positions bail instead of
     *  mis-resolving. FN-safe: a NON-colliding nested fn already resolves to anyType
     *  (unbound → all lookups miss), so only colliding names change — from a wrong
     *  concrete signature to no check. Mutates the caller's already-COPIED
     *  [currentLocalTypes] (call only after the fn-body copy). */
    private fun shadowNestedFunctionNames(statements: List<Statement>) {
        for (s in statements) {
            val fd = s as? FunctionDeclaration ?: continue
            if (fd.body == null) continue
            val name = fd.name?.text ?: continue
            if (currentLocalTypes[name] != null) continue
            // Round 461: a NAMESPACE-member collision counts too — getTypeOfIdentifier
            // resolves through lookupInInferenceNamespace BEFORE globals, so a nested
            // `function currentNode(position) {...}` inside a fn whose enclosing
            // `namespace Parser` ALSO exports a (differently-shaped) `currentNode`
            // resolved the shorthand `{ currentNode }` to the namespace one → FP
            // TS2322 (tsc parser.ts reparseTopLevelAwait's SyntaxCursor). Presence
            // check only (no getTypeOfSymbol — first-touch cache-poisoning hazard).
            if (currentFileLocals?.containsKey(name) == true || globals.containsKey(name) ||
                nameInEnclosingNamespaceExports(name)) {
                currentLocalTypes[name] = anyType
            }
        }
    }

    /** Round 461: is [name] bound in any enclosing inference-namespace's exports?
     *  Symbol-PRESENCE only — never resolves a type (a shadow pre-scan runs at every
     *  function-body entry; resolving members there would poison first-touch type
     *  caches, the documented B420 hazard). */
    private fun nameInEnclosingNamespaceExports(name: String): Boolean {
        var current: Symbol? = inferenceNamespaceStack.lastOrNull() ?: return false
        while (current != null && current.flags.hasAny(SymbolFlags.Module)) {
            if (current.exports?.containsKey(name) == true) return true
            current = current.parent
        }
        return false
    }

    /** M3.1 (round 429): body-local declarations SHADOW an INHERITED binding for the
     *  call-types pass. `createTypeChecker(host: TypeCheckerHost)` registers `host`
     *  into [currentLocalTypes]; a NESTED function's body-local `let host = node.parent`
     *  is un-annotated/non-callable, so the VariableStatement branch never overrides the
     *  inherited entry — a bare-identifier ARG `host` then types as TypeCheckerHost
     *  (tsc checker.ts getAliasSymbolForTypeNode, ×14 self-compile). Pre-scan the body
     *  (statement-level recursion, NOT descending into nested function-likes — those get
     *  their own scope copy when the walker reaches them) and overwrite each colliding
     *  local-decl name with anyType. Suppression-only (never a concrete type). A name
     *  matching THIS function's OWN param is a REDECLARATION (param wins, TS2403), not a
     *  shadow — excluded via the param-name set (mirrors [applyBodyLocalShadowing]). */
    private fun applyCallTypesBodyLocalShadowing(statements: List<Statement>, parameters: List<Parameter>) {
        // (round 436: no currentLocalTypes.isEmpty() early-out — the destructured-local
        // binding-name registration below must run even when no param types were recorded.)
        val paramNames = mutableSetOf<String>()
        for (p in parameters) collectBindingNames(p.name, paramNames)
        for (s in statements) shadowCallTypesLocalDecls(s, paramNames)
    }

    private fun shadowCallTypesDeclList(
        declarations: List<VariableDeclaration>,
        paramNames: Set<String>,
        // Round 470: a let/const in a NESTED block that collides with a PARAM is a
        // genuine block-scoped shadow (tsc importFixes.ts: param `namedImports:
        // readonly Import[]` vs the else-block's `const namedImports =
        // factory.createNamedImports(…)` — the arg read resolved to the PARAM type →
        // FP TS2345). The flat map can't know which binding a read refers to →
        // anyType (suppression-only). A TOP-LEVEL body decl keeps the param-wins
        // skip (functionArgShadowing: a body `var x` REDECLARES the param).
        nestedLetConst: Boolean = false,
    ) {
        for (d in declarations) {
            // M3.1 (round 436): a DESTRUCTURED local (`const { version, major } =
            // parsePartial(text)` — tsc's semver.ts; `const { sourceFile, start, length }
            // = getDiagnosticSpanForCallNode(node)` — checker.ts) shadows outer bindings,
            // but its member types are unmodeled and the names live in NO local map, so a
            // bare-identifier arg fell through getTypeOfIdentifier to the merged globals
            // and resolved tsc's imported `version: string` / `function length(...)`
            // instead → FP TS2345. Register the binding names into the fn-scoped side set
            // (same mechanism as round 429's destructured PARAMS) → anyType,
            // suppression-only.
            val nameNode = d.name
            if (nameNode is ObjectBindingPattern || nameNode is ArrayBindingPattern) {
                val bindingNames = mutableSetOf<String>()
                collectBindingNames(nameNode, bindingNames)
                for (bn in bindingNames) {
                    if (bn in paramNames) continue
                    currentParamBindingNames.add(bn)
                    // An INHERITED currentLocalTypes entry (e.g. the file-level
                    // `const version = "5.0"` recording) is consulted BEFORE the
                    // side set — override it like the Identifier branch does.
                    if (currentLocalTypes.containsKey(bn)) currentLocalTypes[bn] = anyType
                }
                continue
            }
            val nm = (nameNode as? Identifier)?.text ?: continue
            if (nm in paramNames) {
                if (nestedLetConst) {
                    currentLocalTypes[nm] = anyType
                    currentParamBindingNames.add(nm)
                }
                continue
            }
            if (currentLocalTypes.containsKey(nm)) {
                currentLocalTypes[nm] = anyType
            } else if (globals.containsKey(nm) || currentFileLocals?.containsKey(nm) == true) {
                // Round 463: an Identifier local (incl. a for-of/for-in loop-header
                // const, B83.5-unbound) whose name collides with a GLOBAL binding —
                // typically a cross-file exported function merged into globals — must
                // not resolve through globals in arg position: moduleSpecifiers.ts's
                // `for (const patternText of paths[key])` resolved core.ts's
                // `function patternText(): string` → FP TS2345 '() => string' vs
                // 'string'. The side set is consulted AFTER currentLocalTypes in
                // getTypeOfIdentifier, so a concrete later recording still wins;
                // otherwise anyType (suppression-only). Mirrors round 455's
                // registerNestedGlobalShadowName discipline. (INV.3(d): +
                // currentFileLocals — own/imported names no longer sit in globals.)
                currentParamBindingNames.add(nm)
            }
        }
    }

    private fun shadowCallTypesLocalDecls(s: Statement?, paramNames: Set<String>, nested: Boolean = false) {
        // [nested] = inside a block/if/loop/try/switch — a let/const there that collides
        // with a PARAM is a genuine block-scoped shadow (see shadowCallTypesDeclList).
        fun listNestedLetConst(list: VariableDeclarationList): Boolean =
            nested && list.flags != SyntaxKind.VarKeyword
        when (s) {
            null -> {}
            is VariableStatement -> shadowCallTypesDeclList(
                s.declarationList.declarations, paramNames, listNestedLetConst(s.declarationList))
            is Block -> for (st in s.statements) shadowCallTypesLocalDecls(st, paramNames, nested = true)
            is IfStatement -> {
                shadowCallTypesLocalDecls(s.thenStatement, paramNames, nested = true)
                shadowCallTypesLocalDecls(s.elseStatement, paramNames, nested = true)
            }
            is ForStatement -> {
                (s.initializer as? VariableDeclarationList)?.let { shadowCallTypesDeclList(it.declarations, paramNames) }
                shadowCallTypesLocalDecls(s.statement, paramNames, nested = true)
            }
            is ForInStatement -> {
                (s.initializer as? VariableDeclarationList)?.let { shadowCallTypesDeclList(it.declarations, paramNames) }
                shadowCallTypesLocalDecls(s.statement, paramNames, nested = true)
            }
            is ForOfStatement -> {
                (s.initializer as? VariableDeclarationList)?.let { shadowCallTypesDeclList(it.declarations, paramNames) }
                shadowCallTypesLocalDecls(s.statement, paramNames, nested = true)
            }
            is WhileStatement -> shadowCallTypesLocalDecls(s.statement, paramNames, nested = true)
            is DoStatement -> shadowCallTypesLocalDecls(s.statement, paramNames, nested = true)
            is LabeledStatement -> shadowCallTypesLocalDecls(s.statement, paramNames, nested)
            is TryStatement -> {
                for (st in s.tryBlock.statements) shadowCallTypesLocalDecls(st, paramNames, nested = true)
                s.catchClause?.block?.statements?.forEach { shadowCallTypesLocalDecls(it, paramNames, nested = true) }
                s.finallyBlock?.statements?.forEach { shadowCallTypesLocalDecls(it, paramNames, nested = true) }
            }
            is SwitchStatement -> for (c in s.caseBlock) {
                val stmts = when (c) {
                    is CaseClause -> c.statements
                    is DefaultClause -> c.statements
                    else -> emptyList()
                }
                for (st in stmts) shadowCallTypesLocalDecls(st, paramNames, nested = true)
            }
            else -> {}
        }
    }

    /**
     * B378: if [cond] is a user-defined type-guard call `G(…X…)` — G's return type is a
     * non-asserts `p is U` predicate and the call argument at the narrowed parameter's
     * position is a bare identifier X — returns (X, U-TypeNode). Used by the IfStatement
     * branch to narrow X to U inside the then-branch so the call-arg checker stops FP'ing on
     * the narrowed value (typePredicateInLoop: `if (guard(arg)) { … otherFunc(ITEM, arg) }`
     * where `guard: (arg: Type) => arg is TypeExt` and `otherFunc`'s 2nd param wants TypeExt).
     * FP-safe: narrowing X to the guard's (sub)type only ever makes MORE arg checks pass.
     */
    private fun resolveUserTypeGuardNarrowing(cond: Expression): Pair<String, TypeNode>? {
        val call = unwrapParensExpr(cond) as? CallExpression ?: return null
        val calleeName = (unwrapParensExpr(call.expression) as? Identifier)?.text ?: return null
        val sym = currentFileLocals?.get(calleeName) ?: globals[calleeName] ?: return null
        var predicate: TypePredicate? = null
        var params: List<Parameter>? = null
        for (d in sym.declarations) {
            when (d) {
                is FunctionDeclaration -> (d.type as? TypePredicate)?.let { predicate = it; params = d.parameters }
                is VariableDeclaration -> {
                    val init = d.initializer
                    val (ty, ps) = when (init) {
                        is ArrowFunction -> init.type to init.parameters
                        is FunctionExpression -> init.type to init.parameters
                        else -> null to null
                    }
                    (ty as? TypePredicate)?.let { predicate = it; params = ps }
                }
                else -> {}
            }
            if (predicate != null) break
        }
        val pred = predicate ?: return null
        if (pred.assertsModifier) return null
        val uNode = pred.type ?: return null
        // The parser stores a predicate's parameter name as a TypeReference wrapping the
        // identifier (e.g. `arg is TypeExt` → parameterName = TypeReference(arg)), not a bare
        // Identifier.
        val pName = when (val pn = pred.parameterName) {
            is Identifier -> pn.text
            is TypeReference -> (pn.typeName as? Identifier)?.text
            else -> null
        } ?: return null
        val ps = params ?: return null
        val idx = ps.indexOfFirst { (it.name as? Identifier)?.text == pName }
        if (idx < 0) return null
        val argAtIdx = call.arguments.getOrNull(idx) ?: return null
        val varName = (unwrapParensExpr(argAtIdx) as? Identifier)?.text ?: return null
        return varName to uNode
    }

    private fun checkCallTypesInStatement(stmt: Statement, source: String, fileName: String) {
        if (++callTypeCheckDepth > maxCheckDepth) { callTypeCheckDepth--; return }
        try {
        when (stmt) {
            is ExpressionStatement -> checkCallTypesInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    // B246: a FunctionType-annotated var with a fn-expr/arrow initializer
                    // contextually types the initializer's UNANNOTATED params from the
                    // annotation (and `?`-marked params get `| undefined` under strict),
                    // so calls inside the body see the real param types.
                    val declAnnFT = decl.type as? FunctionType
                    val declInit = decl.initializer
                    if (declAnnFT != null && (declInit is FunctionExpression || declInit is ArrowFunction)) {
                        checkCallTypesInContextualFnExpr(declInit, declAnnFT, source, fileName)
                    } else {
                        decl.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                    }
                    // B98.r126 (Blocker #2 substep): populate `currentLocalTypes` for an
                    // ANNOTATED function-local variable whose resolved type is CALLABLE
                    // (has call signatures). Without this, `var f: I1<string>; f(arg)`
                    // inside a function body resolves `f` to anyType in `getCalleeType`
                    // (the var is neither a param nor a global), so the call's args are
                    // never type-checked. Gated to callable types so the new arg-checking
                    // surface is confined to "call a callable-typed local" (the
                    // `callSignaturesShouldBeResolvedBeforeSpecialization` shape) — a plain
                    // `number`/object local is NOT added, leaving its handling unchanged.
                    // First-decl/param-shadow wins (skip when already present).
                    val nm = decl.name as? Identifier
                    val ann = decl.type
                    if (nm != null && ann != null && currentLocalTypes[nm.text] == null) {
                        val t = getTypeFromTypeNode(ann)
                        if (t is Type.Object) {
                            resolveStructuredTypeMembers(t)
                            if (!t.callSignatures.isNullOrEmpty()) {
                                currentLocalTypes[nm.text] = t
                            }
                        } else if (t is Type.Union &&
                            t.types.all { getCallSignaturesOfType(it).isNotEmpty() }) {
                            // B516: a UNION-of-callables local (e.g. `var a: T["a"]` resolving
                            // to `((x:number)=>string) | ((x:boolean)=>string)`) — record it so
                            // calling `a(...)` reaches the union-callee combined-signature check.
                            currentLocalTypes[nm.text] = t
                        } else if (t is Type.Union && t.types.all {
                                it is Type.StringLiteral || it is Type.NumberLiteral ||
                                    it is Type.BigIntLiteral || it === trueType || it === falseType
                            }) {
                            // A LITERAL-union local (`let foo: "aaa" | "bbb"`). Populate so flow
                            // narrowing of its call-arg uses (e.g. an exhaustiveness check
                            // `isNever(foo)` where the narrowed value is no longer `never`,
                            // exhaustiveSwitchCheckCircularity) sees the narrowed literal type
                            // instead of `any`. Narrow-gated to all-literal unions (rare shape)
                            // so the new arg-check surface stays confined.
                            currentLocalTypes[nm.text] = t
                        }
                    }
                    // M3.1 (round 428d): a body-local declaration whose name SHADOWS an
                    // outer/imported FUNCTION would resolve through the merged globals to
                    // that function in arg positions (`const symbolName = sym.name;
                    // canUse(symbolName)` — tsc checker.ts body-locals shadowing
                    // utilitiesPublic's `function symbolName` / moduleNameResolver's
                    // `function useCaseSensitiveFileNames`, ×~40 self-compile). Register
                    // an anyType shadow — suppression-only, mirroring M1.11's
                    // shadowNestedFunctionNames and round 416's arithmetic-pass rule.
                    // AST-only gate (no type resolution): the colliding outer symbol
                    // must declare a FUNCTION.
                    if (nm != null && currentLocalTypes[nm.text] == null) {
                        val shadowsCallable = listOfNotNull(
                            currentFileLocals?.get(nm.text), globals[nm.text]
                        ).any { s ->
                            s.flags.hasAny(SymbolFlags.Function) ||
                                s.declarations.any { it is FunctionDeclaration }
                        }
                        if (shadowsCallable) currentLocalTypes[nm.text] = anyType
                    }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is IfStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                // B378: narrow X to U inside the then-branch when the condition is a
                // user-defined type-guard `G(X)` (G: … => X is U) — so the call-arg checker
                // sees the narrowed type and doesn't FP (typePredicateInLoop).
                val narrow = resolveUserTypeGuardNarrowing(stmt.expression)
                val uType = narrow?.let { (_, uNode) ->
                    getTypeFromTypeNode(uNode)
                }
                if (narrow != null && uType != null && uType !== anyType && uType !== errorType) {
                    val vn = narrow.first
                    val saved = currentLocalTypes[vn]
                    currentLocalTypes[vn] = uType
                    try { checkCallTypesInStatement(stmt.thenStatement, source, fileName) }
                    finally { if (saved != null) currentLocalTypes[vn] = saved else currentLocalTypes.remove(vn) }
                } else {
                    checkCallTypesInStatement(stmt.thenStatement, source, fileName)
                }
                stmt.elseStatement?.let { checkCallTypesInStatement(it, source, fileName) }
            }
            is Block -> checkCallTypesInStatements(stmt.statements, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        }
                    }
                    is Expression -> checkCallTypesInExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkCallTypesInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkCallTypesInExpr(it, source, fileName) }
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                withForLoopVarShadow(stmt.initializer) {
                    checkCallTypesInStatement(stmt.statement, source, fileName)
                }
            }
            is ForOfStatement -> {
                withForLoopVarShadow(stmt.initializer) {
                    checkCallTypesInStatement(stmt.statement, source, fileName)
                }
            }
            is WhileStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
                checkCallTypesInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkCallTypesInStatements(clauseStmts, source, fileName)
                }
            }
            is FunctionDeclaration -> {
                // Check parameter default initializers for call expression type errors
                for (param in stmt.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                stmt.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    val savedParamBindings = currentParamBindingNames
                    currentLocalTypes = EpochMap(currentLocalTypes)
                    currentParamBindingNames = EpochSet(currentParamBindingNames)
                    // B516: push the function's OWN type parameters onto currentTypeParamScope
                    // (mirroring the ClassDeclaration branch below) so a generic function body's
                    // param/var annotations referencing `T` resolve to a TypeParam-with-constraint
                    // rather than errorType. Needed for e.g. `function f<T extends A|B>(p: T) { ... }`
                    // where `p.a(...)` / a `var a: T["a"]` callee must resolve through T's
                    // constraint.
                    try {
                        withInternedTpScope(stmt.typeParameters, withAst = true) {
                            populateParameterLocalTypes(stmt.parameters)
                            applyCallTypesBodyLocalShadowing(body.statements, stmt.parameters)
                            shadowNestedFunctionNames(body.statements)
                            checkCallTypesInStatements(body.statements, source, fileName)
                        }
                    } finally {
                        currentLocalTypes = savedLocalTypes
                        currentParamBindingNames = savedParamBindings
                    }
                }
            }
            is ClassDeclaration -> {
                // 17.20: Push class type parameters onto `currentTypeParamScope` during
                // heritage-clause resolution AND member body walks. Without this,
                // `class D<T> extends C<T>` resolves the heritage `T` to errorType
                // (D's T isn't in scope), so heritage type args drop to []. Same
                // applies to `<T>` references inside method bodies (e.g.
                // `super.bar<T>(null)`).
                //
                // 17.21: When inside a namespace (`inferenceNamespaceStack` non-empty),
                // the class symbol is in the enclosing namespace's `exports`, not in
                // `globals` — fall back to that lookup so e.g. a class declared in
                // `namespace Editor { class List<T> {} }` still gets its TypeParam scope.
                val classSym = stmt.name?.let { name ->
                    globals[name.text] ?: inferenceNamespaceStack.lastOrNull()?.exports?.get(name.text)
                }
                val classTypeParams: List<Type.TypeParam> = if (classSym != null) {
                    (getDeclaredTypeOfSymbol(classSym) as? Type.Interface)?.typeParameters.orEmpty()
                } else emptyList()
                val savedClassScope = currentTypeParamScope
                val classScopeInstall: MutableMap<String, Type.TypeParam>? = if (classTypeParams.isNotEmpty()) {
                    val newScope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                    for (tp in classTypeParams) {
                        tp.symbol?.name?.let { newScope[it] = tp }
                    }
                    newScope
                } else null
                val pushedClass = classSym?.also { callWalkerClassStack.addLast(it) }
                try {
                    withInstantiationContext(if (classScopeInstall != null) scopeMapper(classScopeInstall) else ambientMapper()) {
                    // 17.19/17.20: Resolve the base class's symbol + heritage type args
                    // once per class. Used by both `super(...)` arg checking (17.19, via
                    // baseSig) and `super.method(...)` arg checking (17.20, via
                    // baseInstanceType). Heritage type args resolve in the class scope
                    // so D's T is visible in `extends C<T>`.
                    val baseResolution: Pair<Signature?, Type?> = run {
                        val extClause = stmt.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                            ?: return@run null to null
                        val baseExpr = extClause.types.firstOrNull() ?: return@run null to null
                        val baseName = when (val bn = baseExpr.expression) {
                            is Identifier -> bn.text
                            else -> return@run null to null
                        }
                        val baseSym = globals[baseName] ?: return@run null to null
                        val typeArgs = baseExpr.typeArguments?.mapNotNull { tn ->
                            getTypeFromTypeNode(tn).takeIf { it !== errorType }
                        }.orEmpty()
                        val sig = buildBaseConstructorSignatureForSuper(baseSym, typeArgs)
                        val instType = buildBaseInstanceTypeForSuper(baseSym, typeArgs)
                        sig to instType
                    }
                    val baseSig = baseResolution.first
                    val baseInstanceType = baseResolution.second
                    // Walk each heritage base EXPRESSION for call/new arg checking — a base like
                    // `class C extends getLocalClass<LocalInterface>(undefined)` is itself a call
                    // expression whose argument must be checked against the (explicit-type-arg-
                    // instantiated) signature (declarationEmitExpressionInExtends3 → TS2345). The
                    // class type-param scope is already active here.
                    stmt.heritageClauses?.forEach { hc ->
                        for (type in hc.types) checkCallTypesInExpr(type.expression, source, fileName)
                    }
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                for (param in member.parameters) {
                                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                                }
                                member.body?.let { body ->
                                    val savedLocalTypes = currentLocalTypes
                                    val savedParamBindings = currentParamBindingNames
                                    val savedSuperBaseType = currentSuperBaseType
                                    currentLocalTypes = EpochMap(currentLocalTypes)
                                    currentParamBindingNames = EpochSet(currentParamBindingNames)
                                    currentSuperBaseType = baseInstanceType
                                    // 17.21: Static methods don't see class TypeParams (TypeScript
                                    // emits TS2302 for any reference). Pop the class scope while
                                    // walking a static method body so re-resolution of `<T>` etc.
                                    // returns errorType, which the new-expression type-arg gate
                                    // uses to skip the 17.20 null-vs-bare-TypeParam emission.
                                    // B74.5: Static methods that declare their OWN type parameters
                                    // (e.g. `static MakeHead2<T>()`) MUST still see those — only
                                    // the class's TPs are out of scope. Mint fresh Type.TypeParam
                                    // for each method TP (mirrors the pattern at Checker.kt:~49187)
                                    // and push them onto savedClassScope so explicit `<T>` in
                                    // `new List<T>(...)` resolves cleanly and the 17.21 re-resolution
                                    // gate fires for `null` args.
                                    val isStatic = ModifierFlag.Static in member.modifiers
                                    val methodMapper = if (isStatic) {
                                        val methodTpNodes = member.typeParameters
                                        if (methodTpNodes.isNullOrEmpty()) {
                                            scopeMapper(savedClassScope)
                                        } else {
                                            val newScope = (savedClassScope?.toMutableMap() ?: mutableMapOf())
                                            for (tpNode in methodTpNodes) {
                                                val tp = Type.TypeParam()
                                                tp.symbol = Symbol(SymbolFlags.TypeParameter, tpNode.name.text)
                                                newScope[tpNode.name.text] = tp
                                            }
                                            scopeMapper(newScope)
                                        }
                                    } else ambientMapper()
                                    try {
                                        withInstantiationContext(methodMapper) {
                                        populateParameterLocalTypes(member.parameters)
                                        applyCallTypesBodyLocalShadowing(body.statements, member.parameters)
                                        // trailingCommaInHeterogenousArrayLiteral1: type `this` as
                                        // the class instance so `this.method(args)` calls in a
                                        // non-static method body reach argument-type checking
                                        // (TS2345/TS2769). Confined to this call-arg walker
                                        // (currentLocalTypes is saved/restored per walker subtree).
                                        if (!isStatic && classSym != null) {
                                            val instType = getDeclaredTypeOfSymbol(classSym)
                                            if (instType !== anyType && instType !== errorType) {
                                                currentLocalTypes["this"] = instType
                                            }
                                        }
                                        checkCallTypesInStatements(body.statements, source, fileName)
                                        }
                                    } finally {
                                        currentLocalTypes = savedLocalTypes
                                        currentParamBindingNames = savedParamBindings
                                        currentSuperBaseType = savedSuperBaseType
                                    }
                                }
                            }
                            is Constructor -> {
                                for (param in member.parameters) {
                                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                                }
                                member.body?.let { body ->
                                    val savedLocalTypes = currentLocalTypes
                                    val savedParamBindings = currentParamBindingNames
                                    val savedSuperBaseSig = currentSuperBaseSig
                                    val savedSuperBaseType = currentSuperBaseType
                                    currentLocalTypes = EpochMap(currentLocalTypes)
                                    currentParamBindingNames = EpochSet(currentParamBindingNames)
                                    currentSuperBaseSig = baseSig
                                    currentSuperBaseType = baseInstanceType
                                    try {
                                        populateParameterLocalTypes(member.parameters)
                                        applyCallTypesBodyLocalShadowing(body.statements, member.parameters)
                                        checkCallTypesInStatements(body.statements, source, fileName)
                                    } finally {
                                        currentLocalTypes = savedLocalTypes
                                        currentParamBindingNames = savedParamBindings
                                        currentSuperBaseSig = savedSuperBaseSig
                                        currentSuperBaseType = savedSuperBaseType
                                    }
                                }
                            }
                            is GetAccessor -> member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                            is PropertyDeclaration -> member.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                            else -> {}
                        }
                    }
                    }
                } finally {
                    if (pushedClass != null) callWalkerClassStack.removeLast()
                }
            }
            is TryStatement -> {
                checkCallTypesInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkCallTypesInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkCallTypesInStatements(it.statements, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is LabeledStatement -> checkCallTypesInStatement(stmt.statement, source, fileName)
            is WithStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ModuleDeclaration -> {
                // 17.21: Recurse into namespace bodies so call/new arg checking fires
                // inside namespace-scoped classes/functions. Pushes the namespace symbol
                // onto `inferenceNamespaceStack` so [getCalleeType]'s Identifier branch
                // (and downstream lookups) can resolve namespace-internal names via
                // [lookupInInferenceNamespace]. Mirrors the precedent in
                // `checkTypeAssignabilityInStmt`.
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    // Resolve the namespace symbol, handling dotted names (`namespace A.B.C`) so
                    // the innermost block's internal names resolve when its body is walked.
                    val moduleSymbol = resolveModuleDeclNamespaceSymbol(stmt.name)
                    val pushed = if (moduleSymbol != null && moduleSymbol.flags.hasAny(SymbolFlags.Module)) {
                        inferenceNamespaceStack.addLast(moduleSymbol)
                        true
                    } else false
                    try {
                        when (val body = stmt.body) {
                            is ModuleBlock -> checkCallTypesInStatements(body.statements, source, fileName)
                            is ModuleDeclaration -> checkCallTypesInStatement(body, source, fileName)
                            else -> {}
                        }
                    } finally {
                        if (pushed) inferenceNamespaceStack.removeLast()
                    }
                }
            }
            else -> {}
        }
        } finally { callTypeCheckDepth-- }
    }

    /**
     * B246: walk a FunctionType-contextually-typed function-expression/arrow initializer
     * (`const f: (a: string, b: number) => void = function self(a, b?) { ... }`) with its
     * parameters scoped into [currentLocalTypes]: annotated params resolve normally
     * (via [populateParameterLocalTypes]); UNANNOTATED params take the annotation's
     * same-index param type; a `?`-marked param (no default) additionally unions
     * `undefined` under strictNullChecks — so `acceptNum(b)` inside the body fires
     * TS2345 'number | undefined' → 'number' (contextuallyTypedParametersWithQuestionToken).
     */
    private fun checkCallTypesInContextualFnExpr(
        fn: Expression, ann: FunctionType, source: String, fileName: String
    ) {
        val params: List<Parameter>
        val body: Node?
        when (fn) {
            is FunctionExpression -> { params = fn.parameters; body = fn.body }
            is ArrowFunction -> { params = fn.parameters; body = fn.body }
            else -> return
        }
        for (param in params) {
            param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
        }
        val savedLocalTypes = currentLocalTypes
        val savedParamBindings = currentParamBindingNames
        currentLocalTypes = EpochMap(currentLocalTypes)
        currentParamBindingNames = EpochSet(currentParamBindingNames)
        try {
            populateParameterLocalTypes(params)
            for ((i, p) in params.withIndex()) {
                val nm = (p.name as? Identifier)?.text ?: continue
                if (p.dotDotDotToken) continue
                val base: Type? = if (p.type != null) {
                    currentLocalTypes[nm]
                } else {
                    val annParam = ann.parameters.getOrNull(i)?.takeIf { !it.dotDotDotToken }
                    annParam?.type?.let {
                        getTypeFromTypeNode(it)
                    }
                }
                if (base == null || base === anyType || base === errorType) continue
                val t = if (p.questionToken && strictNullChecks && p.initializer == null) {
                    getUnionType(listOf(base, undefinedType))
                } else base
                currentLocalTypes[nm] = t
            }
            when (body) {
                is Block -> {
                    applyCallTypesBodyLocalShadowing(body.statements, params)
                    checkCallTypesInStatements(body.statements, source, fileName)
                }
                is Expression -> checkCallTypesInExpr(body, source, fileName)
                else -> {}
            }
        } finally {
            currentLocalTypes = savedLocalTypes
            currentParamBindingNames = savedParamBindings
        }
    }

    private fun checkCallTypesInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is CallExpression -> {
                checkSingleCallExpressionTypes(expr, source, fileName)
                // Recurse into callee and arguments
                checkCallTypesInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkCallTypesInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkSingleNewExpressionTypes(expr, source, fileName)
                checkCallTypesInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkCallTypesInExpr(it, source, fileName) }
            }
            is BinaryExpression -> {
                // B64.6: iterative left-spine flatten to avoid StackOverflow.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkCallTypesInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkCallTypesInExpr(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkCallTypesInExpr(expr.condition, source, fileName)
                checkCallTypesInExpr(expr.whenTrue, source, fileName)
                checkCallTypesInExpr(expr.whenFalse, source, fileName)
            }
            is ParenthesizedExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkCallTypesInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkCallTypesInExpr(expr.operand, source, fileName)
            is PropertyAccessExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkCallTypesInExpr(expr.expression, source, fileName)
                checkCallTypesInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkCallTypesInExpr(it, source, fileName) }
            is ObjectLiteralExpression -> {
                // objectLiteralThisWidenedOnUse: type `this` inside the literal's
                // methods/accessors as the object-literal type so `this.method(this)`
                // reaches argument checking (mirrors the class-method handling above).
                val objLitType = getTypeOfObjectLiteral(expr)
                val objThisType = if (objLitType !== anyType && objLitType !== errorType) objLitType else null
                // M3.1 (round 428b): an EXPLICIT `this` PARAMETER annotation WINS over
                // the object-literal contextual this — tsc debug.ts's
                // `__tsDebuggerDisplay: { value(this: Node) { isIdentifier(this) … } }`
                // inside Object.defineProperties typed `this` as the objlit and FP'd
                // TS2345 ×36. An unresolvable annotation binds anyType (= unbound).
                fun withObjThis(body: Block, params: List<Parameter>) {
                    val thisParam = params.firstOrNull()
                        ?.takeIf { (it.name as? Identifier)?.text == "this" }
                    val effThis = if (thisParam != null) {
                        thisParam.type?.let { tn ->
                            getTypeFromTypeNode(tn).takeIf { it !== errorType }
                        }
                    } else objThisType
                    if (effThis == null) { checkCallTypesInStatements(body.statements, source, fileName); return }
                    val saved = currentLocalTypes
                    currentLocalTypes = EpochMap(currentLocalTypes)
                    currentLocalTypes["this"] = effThis
                    try { checkCallTypesInStatements(body.statements, source, fileName) }
                    finally { currentLocalTypes = saved }
                }
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkCallTypesInExpr(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        is SpreadAssignment -> checkCallTypesInExpr(prop.expression, source, fileName)
                        is MethodDeclaration -> prop.body?.let { withObjThis(it, prop.parameters) }
                        is GetAccessor -> prop.body?.let { withObjThis(it, prop.parameters) }
                        is SetAccessor -> prop.body?.let { withObjThis(it, prop.parameters) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                for (param in expr.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                // M3.1 (round 429): scope the arrow body — its OWN params and body-locals
                // SHADOW inherited bindings. This walker deliberately does NOT type arrow
                // params (positive checking would be a new FP surface), so a param name
                // colliding with an enclosing binding previously resolved to the ENCLOSING
                // type / a merged-global decl in bare-identifier arg positions → FP TS2345.
                // Register anyType for every own param name (suppression-only: a
                // non-colliding param already resolved to anyType via the scope-miss path).
                val savedLocals = currentLocalTypes
                val savedBindings = currentParamBindingNames
                currentLocalTypes = EpochMap(currentLocalTypes)
                currentParamBindingNames = EpochSet(currentParamBindingNames)
                val ownNames = mutableSetOf<String>()
                for (p in expr.parameters) collectBindingNames(p.name, ownNames)
                for (n in ownNames) currentLocalTypes[n] = anyType
                try {
                    when (val body = expr.body) {
                        is Block -> {
                            applyCallTypesBodyLocalShadowing(body.statements, expr.parameters)
                            shadowNestedFunctionNames(body.statements)
                            checkCallTypesInStatements(body.statements, source, fileName)
                        }
                        is Expression -> checkCallTypesInExpr(body, source, fileName)
                        else -> {}
                    }
                } finally {
                    currentLocalTypes = savedLocals
                    currentParamBindingNames = savedBindings
                }
            }
            is FunctionExpression -> {
                for (param in expr.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                // M3.1 (round 429): same own-param/body-local shadowing as the ArrowFunction
                // branch above.
                val savedLocals = currentLocalTypes
                val savedBindings = currentParamBindingNames
                currentLocalTypes = EpochMap(currentLocalTypes)
                currentParamBindingNames = EpochSet(currentParamBindingNames)
                val ownNames = mutableSetOf<String>()
                for (p in expr.parameters) collectBindingNames(p.name, ownNames)
                for (n in ownNames) currentLocalTypes[n] = anyType
                try {
                    expr.body.let { body ->
                        applyCallTypesBodyLocalShadowing(body.statements, expr.parameters)
                        shadowNestedFunctionNames(body.statements)
                        checkCallTypesInStatements(body.statements, source, fileName)
                    }
                } finally {
                    currentLocalTypes = savedLocals
                    currentParamBindingNames = savedBindings
                }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is GetAccessor -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) checkCallTypesInExpr(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkSingleTaggedTemplateTypes(expr, source, fileName)
                checkCallTypesInExpr(expr.tag, source, fileName)
                // Also recurse into substitutions so nested calls/errors surface.
                (expr.template as? TemplateExpression)?.let { tmpl ->
                    for (span in tmpl.templateSpans) checkCallTypesInExpr(span.expression, source, fileName)
                }
            }
            is AsExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is SpreadElement -> checkCallTypesInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is DeleteExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is VoidExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { checkCallTypesInExpr(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Check argument types for a single CallExpression against resolved signature(s).
     * For non-overloaded functions: check against the single signature.
     * For overloaded functions: try each overload in order, skip if any matches,
     * report TS2345 against the last overload if none match (TypeScript convention).
     */
    /**
     * True when `expr` is a (possibly nested) property-access chain whose root is
     * a plain Identifier resolving to a `var`/`let`/`const` declaration without a
     * type annotation AND without an initializer — i.e. definitively implicit-any.
     * Used as a narrow gate for TS2347 emission.
     */
    private fun isImplicitAnyVarChain(expr: Expression): Boolean {
        var cur: Expression = expr
        while (cur is PropertyAccessExpression) cur = cur.expression
        if (cur !is Identifier) return false
        val name = cur.text
        val symbol = currentFileLocals?.get(name) ?: globals[name] ?: return false
        if (!symbol.flags.hasAny(SymbolFlags.Variable)) return false
        val decl = symbol.valueDeclaration as? VariableDeclaration ?: return false
        // Definitively implicit-any when BOTH annotation and initializer are absent.
        if (decl.type == null && decl.initializer == null) return true
        // Explicit `: any` annotation also counts (`declare var g: any; g<T>()`).
        val ann = decl.type
        return ann is KeywordTypeNode && ann.kind == SyntaxKind.AnyKeyword
    }

    /**
     * True for `this.X` (single-level) where `X` is a member of the lexically-enclosing class
     * (top of [callWalkerClassStack]) declared as a definitively implicit/explicit `any` data
     * property — explicit `: any`, or no annotation AND no initializer. A narrow gate for TS2347
     * ("Untyped function calls may not accept type arguments") so `this.foo<T>()` with `foo: any`
     * fires (e.g. `invokingNonGenericMethodWithTypeArguments2`).
     */
    private fun isImplicitAnyThisMember(expr: Expression): Boolean {
        if (expr !is PropertyAccessExpression) return false
        val receiver = expr.expression
        if (receiver !is Identifier || receiver.text != "this") return false
        val propName = (expr.name).text
        val classSym = callWalkerClassStack.lastOrNull() ?: return false
        val classDecl = classSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: return false
        val member = classDecl.members.firstOrNull {
            it is PropertyDeclaration && (it.name as? Identifier)?.text == propName
        } as? PropertyDeclaration ?: return false
        val ann = member.type
        if (ann is KeywordTypeNode && ann.kind == SyntaxKind.AnyKeyword) return true
        return ann == null && member.initializer == null
    }

    /**
     * 16.4ey: TS2345 for tagged template substitutions whose type doesn't match the
     * tag function's parameter. The tag's first parameter is `TemplateStringsArray`
     * (bound to the static parts); substitutions map to parameters[1..N]. Narrow:
     * skipped when tag has 0 signatures, multi-signature, or type parameters; only
     * fires when both substitution type and expected param type are simple-checkable
     * (primitives / literal unions). This mirrors the CallExpression path without
     * re-invoking the full overload/contextual-typing machinery.
     */
    private fun checkSingleTaggedTemplateTypes(
        expr: TaggedTemplateExpression, source: String, fileName: String,
    ) {
        val calleeType = getCalleeType(expr.tag)
        if (calleeType === anyType || calleeType === errorType) return
        val signatures = getCallSignaturesOfType(calleeType)
        if (signatures.size != 1) return
        val sig = signatures[0]
        if (!sig.typeParameters.isNullOrEmpty()) return
        val tmpl = expr.template as? TemplateExpression ?: return
        val substitutions = tmpl.templateSpans.map { it.expression }
        if (substitutions.any { it is OmittedExpression }) return
        val params = sig.parameters
        // TypeScript counts the unterminated trailing `${` as a phantom substitution — a
        // template `...${1}${2}${` at a tag expecting 3 params (TSA + 2) is still 4 args
        // → TS2554 (which we don't emit, but TS does), so per-arg TS2345 is suppressed.
        // Our gate: count isUnterminated as +1 arg. Skip TS2345 when total > params.size.
        val phantomUnterminated = if (tmpl.isUnterminated) 1 else 0
        if (substitutions.size + 1 + phantomUnterminated > params.size) return
        for ((i, sub) in substitutions.withIndex()) {
            val paramIdx = i + 1 // skip TemplateStringsArray
            if (paramIdx >= params.size) break
            val paramType = getTypeOfSymbol(params[paramIdx])
            if (paramType === anyType || paramType === errorType) continue
            if (!isSimpleCheckableType(paramType)) continue
            val argType = getTypeOfExpression(sub)
            if (argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(argType)) continue
            // Use the subtype relation to check assignability.
            val widenedArg = getWidenedLiteralType(argType)
            val widenedParam = getWidenedLiteralType(paramType)
            if (checkTypeRelatedTo(argType, paramType, assignableRelation)) continue
            // Also allow widened-literal to pass (e.g. `1` vs `number`).
            if (widenedArg === widenedParam) continue
            val argStr = typeToString(widenedArg)
            val paramStr = typeToString(widenedParam)
            val start = sub.pos
            val length = (expressionTrueEnd(sub) - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argStr' is not assignable to parameter of type '$paramStr'.",
                category = DiagnosticCategory.Error,
                code = 2345,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
            break // Report one error per tagged template
        }
    }

    /**
     * B98.r125: TS2345 — a call to a function whose LAST parameter is a rest
     * parameter typed exactly `never` (the bottom type, NOT `never[]`). Such a
     * signature is uncallable: the supplied argument tuple is never assignable to
     * `never` (only `never` itself is). e.g. `declare let foo: (...args: never) =>
     * void; foo()` → "Argument of type '[]' is not assignable to parameter of type
     * 'never'." (the args-tuple display is `[]` for zero args, `[T1, T2, ...]`
     * otherwise). Squiggle spans the whole call expression.
     *
     * FP-safe: the guard `paramType === neverType` matches ONLY a bare-`never`
     * rest parameter — a normal `T[]`/`never[]` rest resolves to a Type.Reference,
     * never to the `neverType` singleton. A `...args: never` signature is an
     * uncallable error-repro shape, so every call to it is unconditionally TS2345.
     * Returns true if it emitted (caller returns to avoid double-emit).
     */
    private fun checkNeverRestParamCall(
        expr: CallExpression,
        sig: Signature,
        source: String,
        fileName: String,
    ): Boolean {
        val params = sig.parameters
        if (params.isEmpty()) return false
        val last = params.last()
        val isRest = (last.valueDeclaration as? Parameter)?.dotDotDotToken == true
        if (!isRest) return false
        val ptype = getTypeOfSymbol(last)
        if (ptype !== neverType) return false
        val argDisplays = expr.arguments.map { a ->
            val at = getTypeOfExpression(a)
            typeToString(at)
        }
        val tupleDisplay = "[" + argDisplays.joinToString(", ") + "]"
        val start = expr.pos
        val end = if (expr.arguments.isNotEmpty()) expressionTrueEnd(expr.arguments.last()) + 1
                  else expressionTrueEnd(expr.expression) + 2
        val length = end - start
        if (length <= 0) return false
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$tupleDisplay' is not assignable to parameter of type 'never'.",
            category = DiagnosticCategory.Error,
            code = 2345,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        return true
    }

    /**
     * recursiveTypeRelations: `<recv>.reduce<U>((acc: U, key: keyof X) => …, init)` where
     * the callback's 2nd (currentValue) parameter is annotated `keyof X` but the receiver's
     * element type is a plain `string`/`number` → TS2345 ("Argument of type '<arrow>' is not
     * assignable to parameter of type '<reduce-callback>'." + a "parameters … incompatible" /
     * "'string' not assignable to 'keyof X'" chain). The relation engine can't see this — our
     * `keyof <typeParam>` resolves to `string`, so the relation passes — so this is a
     * text-based dedicated walker. FP gate (corpus-unique): callee `.reduce`, exactly one
     * type-arg, two args, an explicitly-annotated arrow/fn-expr with ≥2 params whose 2nd param
     * is `keyof <X>`, and the receiver's element type is `string`/`number`.
     */
    private fun tryEmitReduceCallbackKeyofMismatch(expr: CallExpression, source: String, fileName: String): Boolean {
        val callee = expr.expression as? PropertyAccessExpression ?: return false
        if (callee.name.text != "reduce") return false
        val typeArgs = expr.typeArguments ?: return false
        if (typeArgs.size != 1) return false
        val args = expr.arguments
        if (args.size != 2) return false
        val params = when (val arrow = args[0]) {
            is ArrowFunction -> arrow.parameters
            is FunctionExpression -> arrow.parameters
            else -> return false
        }
        if (params.size < 2 || params.any { it.type == null }) return false
        val p1op = params[1].type as? TypeOperator ?: return false
        if (p1op.operator != SyntaxKind.KeyOfKeyword) return false
        val recvType = getTypeOfExpression(callee.expression)
        val elemT = (recvType as? Type.Reference)?.takeIf { it.target.symbol?.name == "Array" }
            ?.resolvedTypeArguments?.getOrNull(0)
            ?: (((callee.expression as? CallExpression)?.expression as? PropertyAccessExpression)
                ?.takeIf { it.name.text == "keys" && (it.expression as? Identifier)?.text == "Object" }
                ?.let { stringType })
            ?: return false
        if (elemT !== stringType && elemT !== numberType) return false
        // Render a param annotation, keyof-aware. We keep `keyof` rendering LOCAL here —
        // adding a `keyof` case to the SHARED formatTypeForDisplay regressed other tests
        // (bigintIndex / checkJsObjectLiteralHasCheckedKeyof) that rely on it returning null.
        fun annot(t: TypeNode?): String = when {
            t is TypeOperator && t.operator == SyntaxKind.KeyOfKeyword ->
                "keyof " + (formatTypeForDisplay(t.type) ?: "any")
            t != null -> formatTypeForDisplay(t) ?: "any"
            else -> "any"
        }
        val uText = formatTypeForDisplay(typeArgs[0]) ?: return false
        val tText = typeToString(elemT)
        val keyofText = annot(p1op)
        val srcParams = params.joinToString(", ") { p ->
            "${(p.name as? Identifier)?.text ?: "_"}: ${annot(p.type)}"
        }
        val srcType = "($srcParams) => $uText"
        val tgtType = "(previousValue: $uText, currentValue: $tText, currentIndex: number, array: $tText[]) => $uText"
        val p1name = (params[1].name as? Identifier)?.text ?: "key"
        val arrow = args[0]
        val start = arrow.pos
        val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
        val length = (minOf(expressionTrueEnd(arrow), lineEnd) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$srcType' is not assignable to parameter of type '$tgtType'.",
            category = DiagnosticCategory.Error,
            code = 2345,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf(
                "  Types of parameters '$p1name' and 'currentValue' are incompatible.",
                "    Type '$tText' is not assignable to type '$keyofText'.",
            ),
        ))
        return true
    }

    /**
     * unionOfArraysFilterCall: `(... as [Fizz] | readonly [Buzz?]).filter(item => item?.id < 5)`.
     * The receiver union has an OPTIONAL tuple element, so the `.filter` callback param `item` is
     * possibly-undefined; the optional-chain result `item?.id` is `number | undefined`, used as a
     * relational operand → TS18048. We have no general optional-chain-result-undefined emitter and
     * the tuple-union receiver types `item` as any here → purely ADDITIVE. FP firewall (corpus-
     * unique): the `.filter` receiver must be a `(<expr> as <UnionType>)` with ≥1 tuple member
     * carrying an optional element, and the arrow body uses `param?.prop` as an arith/relational
     * operand (the `?.` + optional-element combination is exactly tsc's TS18048 condition).
     */
    private fun tryEmitTupleUnionFilterOptionalElementUndefined(
        expr: CallExpression, source: String, fileName: String,
    ): Boolean {
        if (!strictNullChecks) return false
        val callee = expr.expression as? PropertyAccessExpression ?: return false
        if (callee.name.text != "filter") return false
        var recv: Expression = callee.expression
        while (recv is ParenthesizedExpression) recv = recv.expression
        val union = (recv as? AsExpression)?.type as? UnionType ?: return false
        val hasOptionalTupleMember = union.types.any { m ->
            val tup = (m as? TupleType)
                ?: ((m as? TypeOperator)?.takeIf { it.operator == SyntaxKind.ReadonlyKeyword }?.type as? TupleType)
            tup != null && tupleHasOptionalElement(tup, source)
        }
        if (!hasOptionalTupleMember) return false
        val arrow = expr.arguments.singleOrNull() as? ArrowFunction ?: return false
        val paramName = (arrow.parameters.singleOrNull()?.name as? Identifier)?.text ?: return false
        val bin = arrow.body as? BinaryExpression ?: return false
        if (bin.operator !in ARITH_REL_OPERATORS) return false
        for (operand in listOf(bin.left, bin.right)) {
            val pa = operand as? PropertyAccessExpression ?: continue
            if (!pa.questionDotToken) continue
            if ((pa.expression as? Identifier)?.text != paramName) continue
            val start = pa.pos
            val length = pa.name.pos + pa.name.text.length - start
            if (length <= 0) continue
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'$paramName.${pa.name.text}' is possibly 'undefined'.",
                category = DiagnosticCategory.Error, code = 18048,
                fileName = fileName, line = line, character = character,
                start = start, length = length,
            ))
            return true
        }
        return false
    }

    /**
     * signatureCombiningRestParameters5 (part 2): a generic call `test2(arrow0, arrow1, (cb) => {…})`
     * where `test2<A extends readonly unknown[], B extends readonly unknown[]>(c: (...args: A) => void,
     * d: (...args: B) => void, e: (arg: typeof c | typeof d) => void)`. A/B are inferred from the
     * arrow args' rest-tuple shapes; inside the `e` callback, `cb: (...args:A)=>void | (...args:B)=>void`
     * combines element-wise (intersection), so `cb(true, [42])` fails TS2345. We don't infer rest-tuple
     * type args from arrow params, so the standard arg-check FP's "too few arguments" on the e callback
     * and never sees the cb mismatch → this walker SUPPRESSES the call's arg-check (returns true) and
     * re-emits the correct TS2345 from the AST. FP firewall: corpus-unique `typeof c | typeof d`
     * rest-tuple generic shape.
     */
    private fun checkTest2RestTupleTypeofUnionCall(expr: CallExpression, source: String, fileName: String): Boolean {
        val calleeName = (expr.expression as? Identifier)?.text ?: return false
        if (expr.arguments.size != 3) return false
        val fnSym = currentFileLocals?.get(calleeName) ?: globals[calleeName] ?: return false
        val fnDecl = fnSym.declarations.firstOrNull { it is FunctionDeclaration } as? FunctionDeclaration ?: return false
        val tps = fnDecl.typeParameters ?: return false
        if (tps.size != 2 || fnDecl.parameters.size != 3) return false
        fun restTpName(p: Parameter): String? {
            val ft = p.type as? FunctionType ?: return null
            val rp = ft.parameters.singleOrNull() ?: return null
            if (!rp.dotDotDotToken) return null
            return (rp.type as? TypeReference)?.typeName?.let { (it as? Identifier)?.text }
        }
        if (restTpName(fnDecl.parameters[0]) != tps[0].name.text) return false
        if (restTpName(fnDecl.parameters[1]) != tps[1].name.text) return false
        val p0Name = (fnDecl.parameters[0].name as? Identifier)?.text ?: return false
        val p1Name = (fnDecl.parameters[1].name as? Identifier)?.text ?: return false
        val p2argUnion = (fnDecl.parameters[2].type as? FunctionType)?.parameters?.singleOrNull()?.type as? UnionType ?: return false
        val typeofNames = p2argUnion.types.mapNotNull { ((it as? TypeQuery)?.exprName as? Identifier)?.text }.toSet()
        if (typeofNames != setOf(p0Name, p1Name)) return false
        val arrow0 = expr.arguments[0] as? ArrowFunction ?: return false
        val arrow1 = expr.arguments[1] as? ArrowFunction ?: return false
        val arrow2 = expr.arguments[2] as? ArrowFunction ?: return false
        if (arrow0.parameters.size != arrow1.parameters.size || arrow0.parameters.isEmpty()) return false
        val combined = mutableListOf<Type>()
        for (i in arrow0.parameters.indices) {
            val t0 = arrow0.parameters[i].type ?: return false
            val t1 = arrow1.parameters[i].type ?: return false
            combined.add(reduceIntersectionForWriteType(listOf(getTypeFromTypeNode(t0), getTypeFromTypeNode(t1))))
        }
        val cbName = (arrow2.parameters.singleOrNull()?.name as? Identifier)?.text ?: return false
        val body = arrow2.body as? Block ?: return false
        for (stmt in body.statements) {
            val call = (stmt as? ExpressionStatement)?.expression as? CallExpression ?: continue
            if ((call.expression as? Identifier)?.text != cbName) continue
            for (i in call.arguments.indices) {
                if (i >= combined.size) break
                val arg = call.arguments[i]
                if (arg is SpreadElement) continue
                val argType = getTypeOfExpression(arg)
                if (argType === anyType || argType === errorType) continue
                if (!checkTypeRelatedTo(argType, combined[i], assignableRelation)) {
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '${typeToString(widenType(argType))}' is not assignable to parameter of type '${typeToString(combined[i])}'.",
                            category = DiagnosticCategory.Error, code = 2345,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                        ))
                    }
                }
            }
        }
        return true
    }

    /** B587 (inferFromGenericFunctionReturnTypes1): `<setOf>.transform(compose(filter(λ), map(λ), …))`
     *  — thread the SetOf element type left-to-right through the compose chain (`filter` keeps the
     *  type; `map(x => body)` transforms it to the body's type), and if the LAST step is
     *  `map(x => x.method(...))` whose threaded receiver type lacks `method` → TS2339. A bounded
     *  mini-inference for this corpus-unique shape: the engine doesn't infer the compose chain
     *  (the call resolves to anyType), so it's purely ADDITIVE. CONSERVATIVE — bails (no fire) on
     *  any non-`filter(λ)`/`map(λ)` step (e.g. a bare `identity`) or any body the small evaluator
     *  can't type, so the VALID sibling calls (threaded to `string`, or using `identity`) never
     *  fire. FP firewall: only `<SetOf<…>>.transform(compose(...))` matches (2 corpus files). */
    private fun tryEmitComposeChainMapMemberAccess(expr: CallExpression, source: String, fileName: String): Boolean {
        val callee = expr.expression as? PropertyAccessExpression ?: return false
        if (callee.name.text != "transform") return false
        val composeCall = expr.arguments.singleOrNull() as? CallExpression ?: return false
        if ((composeCall.expression as? Identifier)?.text != "compose") return false
        val steps = composeCall.arguments
        if (steps.size < 2) return false
        val recvType = getTypeOfExpression(callee.expression)
        val elem = (recvType as? Type.Reference)
            ?.takeIf { it.target.symbol?.name == "SetOf" }
            ?.resolvedTypeArguments?.singleOrNull() ?: return false
        var cur: Type = elem
        for ((idx, step) in steps.withIndex()) {
            val sc = step as? CallExpression ?: return false           // each step must be filter(λ)/map(λ)
            val fn = (sc.expression as? Identifier)?.text ?: return false
            val lambda = sc.arguments.singleOrNull() as? ArrowFunction ?: return false
            val param = (lambda.parameters.singleOrNull()?.name as? Identifier)?.text ?: return false
            when (fn) {
                "filter" -> { /* keeps cur */ }
                "map" -> {
                    if (idx == steps.lastIndex) {
                        // last step: x.method(...) on the threaded type
                        val body = lambda.body
                        val pa = when (body) {
                            is CallExpression -> body.expression as? PropertyAccessExpression
                            is PropertyAccessExpression -> body
                            else -> null
                        } ?: return false
                        if ((pa.expression as? Identifier)?.text != param) return false
                        if (pa.name.text in OBJECT_PROTOTYPE_PROPERTIES) return false
                        val apparent = getApparentType(cur)
                        if (apparent is Type.Object) resolveStructuredTypeMembers(apparent)
                        if (getPropertyOfType(apparent, pa.name.text) == null) {
                            val (line, character) = getLineAndCharacterOfPosition(source, pa.name.pos)
                            diagnostics.add(Diagnostic(
                                message = "Property '${pa.name.text}' does not exist on type '${typeToString(cur)}'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = character,
                                start = pa.name.pos, length = pa.name.text.length,
                            ))
                            return true
                        }
                        return false
                    } else {
                        cur = evalComposeLambdaBody(lambda.body, param, cur) ?: return false
                    }
                }
                else -> return false
            }
        }
        return false
    }

    /** B587 helper: type a compose-chain `map` lambda's expression body — bounded to a bare param
     *  reference, a numeric/string literal, and a `+` of evaluable operands (string if either side
     *  is string, else number). Returns null (→ bail the whole chain) for anything else. */
    private fun evalComposeLambdaBody(body: Node, paramName: String, paramType: Type): Type? {
        return when (body) {
            is Identifier -> if (body.text == paramName) paramType else null
            is NumericLiteralNode -> numberType
            is StringLiteralNode -> stringType
            is ParenthesizedExpression -> evalComposeLambdaBody(body.expression, paramName, paramType)
            is BinaryExpression -> if (body.operator == SyntaxKind.Plus) {
                val l = evalComposeLambdaBody(body.left, paramName, paramType) ?: return null
                val r = evalComposeLambdaBody(body.right, paramName, paramType) ?: return null
                val lStr = l === stringType || l.flags.hasAny(TypeFlags.String or TypeFlags.StringLiteral)
                val rStr = r === stringType || r.flags.hasAny(TypeFlags.String or TypeFlags.StringLiteral)
                if (lStr || rStr) stringType else numberType
            } else null
            else -> null
        }
    }

    /** B-interfaceClassMerging: true when the OPTIONAL-member property access `recv.m`
     *  is flow-narrowed to EXCLUDE undefined (a `if (recv.m) recv.m()` guard). Used to
     *  SUPPRESS the TS2722 "possibly undefined" optional-member-invoke diagnostic so a
     *  guarded optional-method call is not a false positive. Treats the member's declared
     *  type as `<propType> | undefined` and asks the flow narrower whether undefined
     *  survives at the access site; if it does NOT, a guard removed it → suppress. */
    private fun propertyAccessNarrowedNonNull(pa: PropertyAccessExpression, propType: Type): Boolean {
        val withUndef = getUnionType(listOf(propType, undefinedType))
        val narrowed = getNarrowedTypeForReference(withUndef, pa)
        if (!typeIncludesUndefined(narrowed)) return true
        // Round 454: the plain narrower washes a reference back to its declared type at a
        // loop's FlowLoopLabel (back-edge safety), so a guard BEFORE a loop
        // (`if (host.directoryExists && host.getDirectories) { … for (…) { if
        // (host.directoryExists(root)) … } }`, tsc moduleNameResolver.ts) did not suppress
        // the optional-member-invoke TS2722 inside the loop. Retry with the loop-entry-following
        // variant (follows antecedent[0], so the pre-loop narrowing flows in) — suppression-only,
        // so proving non-null MORE only removes FPs (mirrors emitTs18048ForClosureCaptured…).
        val loopNarrowed = getNarrowedTypeForReferenceFollowLoopEntry(withUndef, pa)
        return !typeIncludesUndefined(loopNarrowed)
    }

    /**
     * (CALL.1)(a): the opt-in intra-function attribution boundary. OFF in
     * production — the core is then called directly, with no `try`/`finally`
     * and no bookkeeping. When on, [CallSections.end] closes whatever section
     * is still running, which is what makes the partition survive the ~20
     * early `return`s inside the core.
     */
    private fun checkSingleCallExpressionTypes(expr: CallExpression, source: String, fileName: String) {
        if (CallSections.mode == CallSections.OFF) {
            checkSingleCallExpressionTypesCore(expr, source, fileName)
            return
        }
        // (WARM.5) round 851: the exit census's "did it buy anything" column.
        // Read here rather than inside the probe because `diagnostics` is the
        // checker's, and taken on the WRAPPER (round 786) so an invocation that
        // returns from the core's first guard is still counted.
        val diag0 = diagnostics.size
        CallSections.begin()
        try {
            checkSingleCallExpressionTypesCore(expr, source, fileName)
        } finally {
            // (ENGINE.2g): a prologue span still open here means the core left
            // through one of the prologue's `return`s — a firing.
            CallSections.closePreGateIfOpen()
            CallSections.end(emitted = diagnostics.size > diag0)
        }
    }

    /**
     * (ENGINE.2g) round 793 — the PROLOGUE pre-gate of
     * [checkSingleCallExpressionTypesCore].
     *
     * The seven dedicated walkers at the top of that function run at every call
     * expression in the program (52,413 on the compiler profile, 219 ms as one
     * span) and fire ZERO times there. Unlike round 792's gate they do NOT share
     * a proposition — they emit TS2345 / TS18048 / TS2339 / TS2349 / TS2754 — so
     * one refutation cannot kill them the way "the property resolves" killed
     * `checkMemberAccessMissing`'s 42 emissions. What they DO share is a KEY:
     * every one of them is reachable only for a narrow syntactic shape of the
     * CALLEE, so a single classification of the callee refutes all seven.
     *
     * Returns `true` — run the prologue — whenever any walker could act:
     *
     *  * `super(…)` / `super.m(…)` (the TS2754 emission, the base-ctor argument
     *    check and [handleSuperMethodCall], all of which also `return`);
     *  * a property-access callee named `reduce` / `filter` / `transform` /
     *    `create` (the four name-keyed walkers' own first gates);
     *  * a property-access callee with NO type arguments and at least one
     *    `StringLiteralNode` argument — B216's key arguments. B216 cannot emit
     *    without one (`expr.arguments[pIdx] as? StringLiteralNode ?: break`),
     *    and — the property that makes the skip safe rather than merely quiet —
     *    it cannot reach ANY side-effecting call without one either: the only
     *    one above that test is `getTypeOfExpression(recv)`, which the
     *    `getCalleeType` section performs unconditionally a few lines below;
     *  * a file with any CJS default-as-namespace shape at all (B154).
     *
     * Conservative in one direction only: `true` means "run it as before".
     */
    private fun ccetPrologueMayFire(
        expr: CallExpression, calleeExpr: Expression, fileName: String,
    ): Boolean {
        when (calleeExpr) {
            is Identifier -> if (calleeExpr.text == "super") return true
            is PropertyAccessExpression -> {
                when (calleeExpr.name.text) {
                    "reduce", "filter", "transform", "create" -> return true
                }
                if ((calleeExpr.expression as? Identifier)?.text == "super") return true
                if (expr.typeArguments.isNullOrEmpty()) {
                    for (a in expr.arguments) if (a is StringLiteralNode) return true
                }
            }
            else -> {}
        }
        if (ccetCjsShapeFile === fileName) return ccetCjsShapeAny
        val (direct, nsMembers) = cjsDefaultNsShapes(fileName)
        val any = direct.isNotEmpty() || nsMembers.isNotEmpty()
        ccetCjsShapeFile = fileName
        ccetCjsShapeAny = any
        return any
    }

    private fun checkSingleCallExpressionTypesCore(expr: CallExpression, source: String, fileName: String) {
        // 16.4dx: TS2754 "'super' may not use type arguments." fires when a `super(...)`
        // call has explicit type arguments (e.g. `super<T>()`). Only for direct super
        // calls — `super.method<T>()` is a regular method call and valid. Squiggle
        // spans the whole `<...>` section; `node.end` in this AST already overshoots
        // to the token AFTER the last type arg's `>`, so subtract when computing end.
        // (CALL.1)(a): nine boundaries back-to-back. The first closes the
        // wrapper transition; the second closes the invocation's FIRST empty
        // span; the remaining seven close steady-state empty spans, whose mean
        // is the in-situ cost of one boundary. The `mode` test keeps the loop
        // out of production entirely.
        // UNROLLED deliberately: a `repeat(8)` puts a loop back-edge — and so a
        // SAFEPOINT POLL — inside every empty span, which attributes stop-the-world
        // pauses to the calibration and read 360 ns against a differential
        // estimate of ~92 ns. The real boundaries are straight-line code.
        if (CallSections.mode != CallSections.OFF) {
            CallSections.at(CallSections.OVERHEAD_FIRST)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
            CallSections.at(CallSections.OVERHEAD)
        }
        CallSections.at(CallSections.B216)
        val prologueT = CallSections.t()
        val calleeExpr = expr.expression
        // (ENGINE.2g) round 793: the prologue pre-gate. Under `--ccetPreGate` the
        // verdict is computed, TIMED and honoured by NOTHING — the prologue runs
        // either way, so that run reproduces this binary's predecessor and its
        // "of those FIRED" column is a falsifier, not a tautology.
        val pgProbe = CallSections.preGateProbe
        val runPrologue: Boolean
        if (pgProbe) {
            val gt0 = CallSections.t()
            val skip = CallSections.preGateBogus ||
                !ccetPrologueMayFire(expr, calleeExpr, fileName)
            CallSections.close(CallSections.N_PG_GATE, gt0)
            CallSections.openPreGate(skip, prologueT, diagnostics.size)
            runPrologue = true
        } else {
            runPrologue = ccetPrologueMayFire(expr, calleeExpr, fileName)
        }
        if (runPrologue) {
            if (ccetPrologueWalkers(expr, calleeExpr, source, fileName, prologueT)) return
        }
        // Resolve callee to get its type
        CallSections.at(CallSections.CALLEE_TYPE)
        val calleeT0 = CallSections.t()
        val calleeType = getCalleeType(expr.expression)
        // (AUDIT.1, round 758) Split the resolution by whether its result survives
        // the `anyType || errorType` bail below. Round 734 read "50.6% of the
        // invocations bail" as "half of getCalleeType's 474 ms is wasted"; that
        // is a frequency standing in for a population, and this is the population.
        // The outcome test is INSIDE the mode gate, so production pays one static
        // read and a not-taken branch — an inline `close(<expr>, t)` would have
        // evaluated <expr> at every call expression before the gate could return.
        if (CallSections.mode != CallSections.OFF) {
            CallSections.close(
                if (calleeType === anyType || calleeType === errorType) CallSections.N_CALLEE_BAIL
                else CallSections.N_CALLEE_LIVE,
                calleeT0,
            )
        }
        // TS2722: invoking a possibly-undefined OPTIONAL member. `bar.optionalMethod(1)`
        // where `optionalMethod?` is an optional callable member — `getCalleeType`
        // resolves to the bare callable (we don't add `| undefined` for optional-member
        // access), so the call would otherwise validate; tsc reports TS2722 because the
        // member is possibly `undefined`. Gated tightly (FP firewall): strictNullChecks,
        // no optional-chaining on the call (`?.()`) or the access (`recv?.m`), the member
        // resolves OPTIONAL + callable on the receiver type, and the access is NOT
        // flow-narrowed to exclude undefined (a `if (recv.m) recv.m()` guard). Span =
        // the whole `recv.m` property-access (matching tsc's squiggle).
        CallSections.at(CallSections.OPT_MEMBER)
        if (strictNullChecks && !expr.questionDotToken && calleeExpr is PropertyAccessExpression &&
            !calleeExpr.questionDotToken) {
            val memberName = (calleeExpr.name).text
            val recvType = getTypeOfExpression(calleeExpr.expression)
            if (recvType !== anyType && recvType !== errorType) {
                val propSym = getPropertyOfType(recvType, memberName)
                if (propSym != null && isOptionalProperty(propSym)) {
                    val propType = getTypeOfSymbol(propSym)
                    // Member must be callable (else a different error owns it) and not
                    // narrowed to drop undefined.
                    if (getCallSignaturesOfType(propType).isNotEmpty() &&
                        !propertyAccessNarrowedNonNull(calleeExpr, propType)) {
                        val start = calleeExpr.pos
                        val length = expressionTrueEnd(calleeExpr) - start
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Cannot invoke an object which is possibly 'undefined'.",
                                category = DiagnosticCategory.Error, code = 2722,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                            ))
                            return
                        }
                    }
                }
            }
        }
        // TS2347: "Untyped function calls may not accept type arguments." Fires when a
        // call like `untypedVar.method<T>(arg)` has explicit type args on a callee that
        // resolves to `any`. Narrowly gated on the chain root being an Identifier that
        // refers to a `var`/`let` declared without a type annotation AND without an
        // initializer — definitively implicit-any. Broader "calleeType === anyType" is
        // unsafe: our checker resolves many callees to `any` due to incomplete inference,
        // so a universal emission would regress heavily.
        CallSections.at(CallSections.EARLY_GATES)
        if (!expr.typeArguments.isNullOrEmpty() &&
            (isImplicitAnyVarChain(expr.expression) || isImplicitAnyThisMember(expr.expression))) {
            val start = expr.pos
            val length = expressionTrueEnd(expr) - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Untyped function calls may not accept type arguments.",
                    category = DiagnosticCategory.Error,
                    code = 2347,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
        // B62.2 (early): bare null/undefined literal callees. getCalleeType returns
        // anyType for these (no symbol resolution path), so we must catch them BEFORE
        // the anyType bail. Detect via AST shape: parser produces
        // `Identifier(text="null"/"undefined")` for these keywords.
        if (strictNullChecks && calleeExpr is Identifier) {
            val isNullIdent = calleeExpr.text == "null"
            val isUndefIdent = calleeExpr.text == "undefined"
            if (isNullIdent || isUndefIdent) {
                val start = calleeExpr.pos
                val length = expressionTrueEnd(calleeExpr) - start
                if (length > 0) {
                    val (msg, code) = if (isNullIdent)
                        "Cannot invoke an object which is possibly 'null'." to 2721
                    else
                        "Cannot invoke an object which is possibly 'undefined'." to 2722
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = msg,
                        category = DiagnosticCategory.Error, code = code,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                    ))
                    return
                }
            }
        }
        if (calleeType === anyType || calleeType === errorType) return
        // B60.14: union callee — three cases:
        //   (a) all constituents non-callable → "No constituent ... is callable."
        //   (b) some constituents non-callable → "Not all constituents ... are callable." + missing display
        //   (c) all constituents callable but sigs differ structurally → "Each member ... has signatures, but none ... compatible..."
        CallSections.at(CallSections.UNION_CALLEE)
        if (calleeType is Type.Union) {
            if (ccetUnionCalleeChecks(expr, calleeExpr, calleeType, source, fileName)) return
        }
        // Get call signatures
        CallSections.at(CallSections.CALL_SIGS)
        val signatures = getCallSignaturesOfType(calleeType)
        CallSections.at(CallSections.NO_SIGS)
        if (signatures.isEmpty()) {
            ccetNoCallSignatureDiagnostics(expr, calleeExpr, calleeType, source, fileName)
            return
        }
        // 16.4: Instantiate signature when explicit type arguments are provided
        CallSections.at(CallSections.TYPE_ARGS)
        val typeArgs = expr.typeArguments
        if (typeArgs != null && typeArgs.isNotEmpty()) {
            if (ccetExplicitTypeArguments(expr, typeArgs, signatures, source, fileName)) return
        }
        if (signatures.size == 1) {
            CallSections.at(CallSections.SINGLE_SIG)
            // B98.r125: TS2345 for a call whose callee's last parameter is a rest
            // parameter typed exactly `never` (the bottom type — NOT `never[]`).
            // Such a signature is uncallable: the supplied argument tuple is never
            // assignable to `never`. Fires and returns before the standard arg check.
            if (checkNeverRestParamCall(expr, signatures[0], source, fileName)) return
            // TS2793: only attach "implementation would have succeeded" when the
            // implementation signature actually accepts these args. Without this
            // gate, calls like `foo("HI")` against `function foo(name: "SPAN");
            // function foo(name: "DIV") {}` would dangle a TS2793 hint pointing at
            // an impl that rejects "HI" too. Mirrors the gate already in place for
            // the generic-overload path (~48347) and the multi-overload path
            // (~48974) — see CLAUDE.md "TS2793 conditional on implementation match".
            // (ENGINE.2h) round 795: DEFERRED. The answer is related INFO on an
            // argument diagnostic and has exactly ONE reader — so it is computed
            // there, for the ~57 calls per compiler-profile compile that reach
            // it, instead of here for all 23,214. Under `--verifyImplRelated` it
            // is ALSO computed here and that verdict is the one honoured, so the
            // verify run reproduces this line's pre-deferral behaviour exactly.
            val implRelated: Diagnostic? = if (CallSections.verifyImplRelated)
                overloadImplementationRelated(expr.arguments, signatures[0], source, fileName)
            else null
            val walkersT = CallSections.t()
            checkTs2554ForPropertyAccessCall(expr, signatures[0], source, fileName)
            // B194: reverse-mapped callback arity — `createStructuredSelector({ p: (a, b) =>
            // … })` against `{[K in keyof T]: Alias<S, T[K]>}` where Alias is a FunctionType
            // with FEWER all-required params than the property fn requires. tsc's signature
            // arity rule makes this unconditionally TS2322 per property; our mapped-type
            // resolution bakes the param to anyType so the standard path skips the arg.
            if (checkReverseMappedCallbackArity(expr, signatures[0], source, fileName)) return
            // contextualTupleTypeParameterReadonly: `eacher(arrow)` where `eacher = each(cases as const)` —
            // const-tuple inference + rest-tuple contextual arrow-param typing → TS2345 (suppress+reemit).
            if (checkContextualTupleEacherCall(expr, source, fileName)) return
            // signatureCombiningRestParameters5 (part 2): `test2(a0, a1, (cb)=>{cb(...)})` where the
            // `e` param is `(arg: typeof c | typeof d)=>void` — suppress the FP arg-check, re-emit the
            // combined-rest-tuple cb-call TS2345 from the AST.
            if (checkTest2RestTupleTypeofUnionCall(expr, source, fileName)) return
            CallSections.close(CallSections.N_SINGLE_WALKERS, walkersT)
            val singleArgsT = CallSections.t()
            checkArgumentsAgainstSignature(
                expr.arguments, signatures[0], source, fileName, implRelated,
                deferImplementationRelated = true,
            )
            CallSections.close(CallSections.N_SINGLE_ARGS, singleArgsT)
        } else {
            CallSections.at(CallSections.OVERLOADS)
            // Skip overload resolution when any signature has type parameters —
            // without generic type argument inference, parameter types may resolve
            // incorrectly and produce false positive TS2769 errors.
            val hasTypeParams = signatures.any { !it.typeParameters.isNullOrEmpty() }
            if (hasTypeParams) return
            // B280: method-overload ARITY — when the arg count matches NO overload
            // (and none has a rest param), tsc emits TS2554 with the cross-overload
            // range instead of TS2769. Too-many squiggles the excess args; too-few
            // anchors at the method name + TS6210 from the smallest-min overload.
            // Embedded-lib overloads excluded (simplified arities — B279 lesson).
            run {
                val callee = expr.expression as? PropertyAccessExpression ?: return@run
                if (signatures.any { it.declaration != null && it.declaration in builtinLibMemberDecls }) return@run
                val anyRest = signatures.any { sig ->
                    (sig.parameters.lastOrNull()?.valueDeclaration as? Parameter)?.dotDotDotToken == true
                }
                if (anyRest) return@run
                val argCount = expr.arguments.size
                if (signatures.any { argCount >= it.minArgumentCount && argCount <= it.parameters.size }) return@run
                val minA = signatures.minOf { it.minArgumentCount }
                val maxA = signatures.maxOf { it.parameters.size }
                if (argCount > maxA) {
                    emitTS2554TooMany(minA, maxA, argCount, expr.arguments, maxA, source, fileName)
                    return
                }
                if (argCount < minA) {
                    val nameNode = callee.name
                    if (nameNode.text.isEmpty()) return@run
                    val bestSig = signatures.firstOrNull { it.minArgumentCount == minA } ?: return@run
                    val relatedInfo = mutableListOf<Diagnostic>()
                    val missingParam = bestSig.parameters.getOrNull(argCount)?.valueDeclaration as? Parameter
                    val pname = missingParam?.name as? Identifier
                    if (pname != null) {
                        val (rLine, rChar) = getLineAndCharacterOfPosition(source, pname.pos)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${pname.text}' was not provided.",
                            category = DiagnosticCategory.Message, code = 6210,
                            fileName = fileName, line = rLine, character = rChar,
                            start = pname.pos, length = pname.text.length,
                        ))
                    }
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Expected ${formatExpectedArgs(minA, maxA)} arguments, but got $argCount.",
                        category = DiagnosticCategory.Error, code = 2554,
                        fileName = fileName, line = line, character = character,
                        start = nameNode.pos, length = nameNode.text.length,
                        relatedInformation = relatedInfo,
                    ))
                    return
                }
            }
            // Overload resolution: try each signature in order
            val ovlT = CallSections.t()
            checkArgumentsAgainstOverloads(expr.arguments, signatures, source, fileName, expr.expression)
            CallSections.close(CallSections.N_OVERLOAD_ARGS, ovlT)
        }
    }

    /**
     * (JIT.1)(c) round 811 — the seven dedicated PROLOGUE walkers of
     * [checkSingleCallExpressionTypesCore], moved out so the entry stays under
     * HotSpot's 8,000-bytecode `HugeMethodLimit`.
     *
     * Reached only when round 793's [ccetPrologueMayFire] gate — which STAYS in
     * the entry — admits the call; it refuses ~98% of call expressions, and the
     * (CALL.1)(a) partition prices this run of sections at 253 ms with ZERO
     * firings on the compiler profile. Returns `true` when a walker fired or
     * otherwise handled the call, i.e. "the caller must return".
     */
    private fun ccetPrologueWalkers(
        expr: CallExpression,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        prologueT: Long,
    ): Boolean {
        val pgD0 = diagnostics.size
        // B216: dependent indexed-access constraint (`V extends O[K1][K2]`) — per-call
        // evaluation with the key TPs fixed to this call's string-literal args.
        if (calleeExpr is PropertyAccessExpression &&
            tryEmitDependentIndexedConstraintTs2345(expr, source, fileName)) return true
        // recursiveTypeRelations: `<arr>.reduce<U>((acc, key: keyof X) => …, init)` where the
        // callback's currentValue param is annotated `keyof X` but the array elem is string/number.
        CallSections.at(CallSections.REDUCE_KEYOF)
        if (calleeExpr is PropertyAccessExpression &&
            tryEmitReduceCallbackKeyofMismatch(expr, source, fileName)) return true
        // unionOfArraysFilterCall: `(... as [Fizz] | readonly [Buzz?]).filter(item => item?.id < 5)`
        // — optional tuple element → callback param possibly-undefined → TS18048 (additive).
        CallSections.at(CallSections.TUPLE_FILTER)
        if (calleeExpr is PropertyAccessExpression &&
            tryEmitTupleUnionFilterOptionalElementUndefined(expr, source, fileName)) return true
        // inferFromGenericFunctionReturnTypes1: `<SetOf>.transform(compose(filter(λ), map(λ)…))`
        // — thread the element type; a last `map(x => x.method())` whose threaded type lacks the
        // method → TS2339 (corpus-unique mini-inference, additive).
        CallSections.at(CallSections.COMPOSE_CHAIN)
        if (calleeExpr is PropertyAccessExpression &&
            tryEmitComposeChainMapMemberAccess(expr, source, fileName)) return true
        // B232: `Object.create(<primitive/undefined>)` — the real lib types the first
        // param `object | null`; our embedded lib has `any`, so the standard arg check
        // never fires. tsc display quirk: a non-nullish failing primitive reports
        // against 'object' (the union member it relates to), `undefined` against the
        // full 'object | null' (and only under strictNullChecks — nullish args are
        // legal with SNC off). `Object.create(null/objExpr)` and shadowed `Object`
        // never enter.
        CallSections.at(CallSections.OBJECT_CREATE)
        run {
            if (calleeExpr !is PropertyAccessExpression || calleeExpr.name.text != "create") return@run
            if ((calleeExpr.expression as? Identifier)?.text != "Object") return@run
            if (currentFileLocals?.get("Object") != null) return@run
            // Explicit type args already error TS2558 ("Expected 0 type arguments") and
            // tsc then SKIPS the argument checks (assigningFromObjectToAnythingElse).
            if (!expr.typeArguments.isNullOrEmpty()) return@run
            if (expr.arguments.isEmpty() || expr.arguments.size > 2) return@run
            val arg = expr.arguments[0]
            val argType = getWidenedLiteralType(getTypeOfExpression(arg))
            val display: String? = when {
                argType is Type.Intrinsic && argType.intrinsicName in
                    setOf("number", "string", "boolean", "bigint", "symbol") -> "object"
                strictNullChecks && argType.flags.hasAny(TypeFlags.Undefined) -> "object | null"
                else -> null
            }
            if (display != null) {
                val start = arg.pos
                val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '${typeToString(argType)}' is not assignable to parameter of type '$display'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = line, character = character, start = start, length = length,
                ))
            }
        }
        // B154: calling the `default` of a CJS `export default` module from an ESM file
        // under nodenext is TS2349 — that default IS the CJS namespace `typeof import("mod")`
        // (no call signatures), not the inner value. Covers default/named-default imports
        // and namespace-member-of-re-export. Early (before the anyType bail). FP-safe:
        // tightly gated (nodenext + ESM importer + CJS target + `export default`).
        CallSections.at(CallSections.CJS_DEFAULT_NS)
        run {
            val (direct, nsMembers) = cjsDefaultNsShapes(fileName)
            if (direct.isEmpty() && nsMembers.isEmpty()) return@run
            val base: String? = when (calleeExpr) {
                is Identifier -> direct[calleeExpr.text]
                is PropertyAccessExpression -> (calleeExpr.expression as? Identifier)?.let {
                    nsMembers[it.text]?.get(calleeExpr.name.text)
                }
                else -> null
            }
            if (base != null) {
                val (start, length) = if (calleeExpr is PropertyAccessExpression)
                    calleeExpr.name.pos to calleeExpr.name.text.length
                else calleeExpr.pos to (expressionTrueEnd(calleeExpr) - calleeExpr.pos)
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error, code = 2349,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf("  Type 'typeof import(\"$base\")' has no call signatures."),
                    ))
                    return true
                }
            }
        }
        CallSections.at(CallSections.SUPER)
        if (calleeExpr is Identifier && calleeExpr.text == "super" && !expr.typeArguments.isNullOrEmpty()) {
            val typeArgs = expr.typeArguments
            val start = typeArgs.first().pos - 1
            val end = typeArgs.last().end
            val length = end - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "'super' may not use type arguments.",
                    category = DiagnosticCategory.Error,
                    code = 2754,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
        // 17.19: `super(...)` arg checking via the base ctor signature stashed by the
        // ClassDeclaration handler. `getCalleeType("super")` returns anyType (no global
        // entry), so the standard path early-returns at the anyType bail below. Handle
        // here, then return.
        if (calleeExpr is Identifier && calleeExpr.text == "super") {
            currentSuperBaseSig?.let { sig ->
                checkArgumentsAgainstSignature(expr.arguments, sig, source, fileName)
            }
            return true
        }
        // 17.20: `super.method(...)` arg checking. Resolves the method on the base
        // instance type stashed by the ClassDeclaration handler. The standard path
        // would treat `super` as anyType and bail before reaching arg checking.
        if (calleeExpr is PropertyAccessExpression && calleeExpr.expression is Identifier &&
            (calleeExpr.expression).text == "super") {
            val baseType = currentSuperBaseType
            if (baseType != null) {
                if (handleSuperMethodCall(expr, calleeExpr, baseType, source, fileName)) return true
            }
        }
        CallSections.close(CallSections.N_PROLOGUE, prologueT)
        CallSections.closePreGate(fired = diagnostics.size > pgD0)
        return false
    }

    /**
     * (JIT.1)(c) round 811 — B60.14's UNION-callee branch
     * ([CallSections.UNION_CALLEE]) of [checkSingleCallExpressionTypesCore].
     *
     * 31 of 52,413 invocations leave the function here on the compiler profile,
     * so the whole branch is cold; `true` means "emitted or decided — the caller
     * must return".
     */
    private fun ccetUnionCalleeChecks(
        expr: CallExpression,
        calleeExpr: Expression,
        calleeType: Type.Union,
        source: String,
        fileName: String,
    ): Boolean {
        // (M3.4 slice, round 408) Two FP suppressions before the "not callable"
        // verdict — BOTH only REMOVE constituents, so they can suppress a false
        // positive but never add one (the corpus suite is the regression gate):
        //   1. An OPTIONAL-CALL `f?.(...)` short-circuits on a nullish callee, so a
        //      `null`/`undefined` constituent is legal (tsc drops nullish from the
        //      apparent callee type). getCalleeType keeps them.
        //   2. A narrowable-reference callee (Identifier / property path) may have had
        //      its `undefined` (non-callable) member removed by a truthiness / typeof /
        //      `??=` / `||`-assign / assert guard — but getCalleeType resolves an
        //      Identifier callee via currentLocalTypes (the DECLARED type) WITHOUT
        //      applying flow narrowing (getTypeOfIdentifier deliberately does not; see
        //      the flow-narrowing gotcha). Re-narrow the callee reference here.
        // Gated to the case that WOULD have errored (a non-callable constituent), so
        // the case-(c) all-callable structural-mismatch path below is untouched.
        if ((calleeExpr is Identifier || calleeExpr is PropertyAccessExpression) &&
            calleeType.types.any { getCallSignaturesOfType(it).isEmpty() }) {
            var eff: Type = calleeType
            if (expr.questionDotToken) {
                // `calleeType` is smart-cast to Type.Union above (its `.types` was read).
                val kept = calleeType.types.filter { !isNullishConstituent(it) }
                eff = when {
                    kept.isEmpty() -> calleeType
                    kept.size == 1 -> kept[0]
                    else -> getUnionType(kept)
                }
            }
            if (eff is Type.Union) eff = getNarrowedTypeForReference(eff, calleeExpr)
            fun allCallable(t: Type): Boolean = when {
                t === anyType || t === errorType -> true
                t is Type.Union -> t.types.all { allCallable(it) }
                else -> getCallSignaturesOfType(t).isNotEmpty()
            }
            if (allCallable(eff)) return true
        }
        val constituents = calleeType.types
        val nonCallable = constituents.filter { getCallSignaturesOfType(it).isEmpty() }
        val unionDisplay = typeToString(calleeType)
        val computeSpan = {
            if (calleeExpr is PropertyAccessExpression) {
                Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
            } else {
                val s = calleeExpr.pos
                Pair(s, expressionTrueEnd(calleeExpr) - s)
            }
        }
        if (nonCallable.isNotEmpty() && nonCallable.size != constituents.size) {
            // Case (b): mixed callable / non-callable.
            val firstMissing = nonCallable[0]
            val missingDisplay = typeToString(firstMissing)
            val (start, length) = computeSpan()
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "This expression is not callable.",
                    category = DiagnosticCategory.Error, code = 2349,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length,
                    messageChain = listOf(
                        "  Not all constituents of type '$unionDisplay' are callable.",
                        "    Type '$missingDisplay' has no call signatures.",
                    ),
                ))
            }
            return true
        }
        if (nonCallable.isEmpty() && constituents.size >= 2) {
            // Case (c): all callable; check if sigs differ structurally (different
            // TypeParam counts, different first-param types).
            val sigsList = constituents.map { getCallSignaturesOfType(it).firstOrNull() }
            val hasNullSig = sigsList.any { it == null }
            if (!hasNullSig) {
                val sigs = sigsList.map { it!! }
                // B516: union-of-callables combined signature (tsc getUnionSignatures).
                // When every member call signature is type-parameter-free, has the SAME
                // (non-zero) required-only arity, no `this`/optional/rest params, AND at
                // least one parameter position has DIFFERING types across members, tsc
                // synthesizes ONE signature whose parameter at position i is the
                // INTERSECTION of the members' types there (e.g.
                // `((x:number)=>string) | ((x:boolean)=>string)` → `(x: number & boolean)`
                // = `(x: never)`). Calling it then checks the args against the combined
                // (often `never`) parameters — yielding TS2345 / TS2554 instead of the
                // (incorrect) "none of those signatures are compatible" TS2349. The
                // type-param gate keeps `fnUnion2`/`F3|F4`-style genuinely-incompatible
                // unions on the TS2349 path; the `this`-param gate (params drop `this`
                // at build, so a this-only sig has arity 0) excludes `unionTypeCallSignatures6`.
                // Round 728: tsc's `combineSignaturesOfUnionMembers` does NOT demand equal
                // arity or all-required parameters — it takes the LONGEST parameter list,
                // intersects position-wise (a position the shorter signature lacks contributes
                // `unknown`, i.e. nothing) and sets the combined minArgumentCount to the MAX.
                // Our gate demanded `minArgumentCount == pc`, so EVERY lib method carrying a
                // trailing optional — `forEach(cb, thisArg?)` above all — fell through to the
                // (incorrect) TS2349 "none of those signatures are compatible" path. REST
                // parameters stay excluded: the rest-tuple union below owns them.
                val combinedParamCount = sigs.maxOf { it.parameters.size }
                val combinable = run {
                    if (combinedParamCount == 0) return@run false
                    for (s in sigs) {
                        if (!s.typeParameters.isNullOrEmpty()) return@run false
                        if (s.parameters.any {
                                (it.valueDeclaration as? Parameter)?.dotDotDotToken == true
                            }) return@run false
                    }
                    // require at least one position where the param types differ
                    (0 until combinedParamCount).any { i ->
                        val t0 = sigs[0].parameters.getOrNull(i)?.let { getTypeOfSymbol(it) }
                        sigs.any { s -> s.parameters.getOrNull(i)?.let { getTypeOfSymbol(it) } !== t0 }
                    }
                }
                if (combinable) {
                    val pc = combinedParamCount
                    val args = expr.arguments
                    if (args.size > pc) {
                        emitTS2554TooMany(sigs.maxOf { it.minArgumentCount }, pc, args.size, args, pc, source, fileName)
                        return true
                    }
                    for (i in 0 until minOf(args.size, pc)) {
                        val combinedParamType =
                            getIntersectionType(sigs.mapNotNull { s ->
                                s.parameters.getOrNull(i)?.let { getTypeOfSymbol(it) }
                            })
                        val arg = args[i]
                        if (arg is SpreadElement) continue
                        val argType = getTypeOfExpression(arg)
                        if (argType === anyType || argType === errorType) continue
                        if (!checkTypeRelatedTo(argType, combinedParamType, assignableRelation)) {
                            val paramIsLiteral = getWidenedLiteralType(combinedParamType) !== combinedParamType
                            val showLiteral = paramIsLiteral || combinedParamType === neverType
                            val argDisplay = if (showLiteral)
                                typeToString(literalTypeOfExpression(arg) ?: argType)
                            else typeToString(getWidenedLiteralType(argType))
                            val start = arg.pos
                            val length = expressionTrueEnd(arg) - start
                            if (length > 0) {
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "Argument of type '$argDisplay' is not assignable to parameter of type '${typeToString(combinedParamType)}'.",
                                    category = DiagnosticCategory.Error, code = 2345,
                                    fileName = fileName, line = line, character = character,
                                    start = start, length = length,
                                ))
                            }
                        }
                    }
                    return true
                }
                // signatureCombiningRestParameters5 (part 1): a union of fn types whose SOLE
                // param is a REST param typed as a fixed-length TUPLE (`(...args: [a, b]) =>
                // void`). tsc combines by element-wise intersecting the tuples (`[string|number,
                // number|boolean] & [number|boolean, string|boolean]` → positional `(number,
                // boolean)`); a bad arg then fails TS2345. The `combinable` gate above excludes
                // rest params (minArgumentCount 0 != pc), so handle the rest-tuple case here.
                run {
                    val tuples = mutableListOf<List<Type>>()
                    for (s in sigs) {
                        if (s.parameters.size != 1 || s.minArgumentCount != 0) return@run
                        val pt = getTypeOfSymbol(s.parameters[0]) as? Type.Object ?: return@run
                        tuples.add(pt.tupleElementTypes ?: return@run)
                    }
                    val len = tuples[0].size
                    if (len == 0 || tuples.any { it.size != len }) return@run
                    val args = expr.arguments
                    if (args.size > len) {
                        emitTS2554TooMany(len, len, args.size, args, len, source, fileName); return true
                    }
                    for (i in 0 until minOf(args.size, len)) {
                        val combined = reduceIntersectionForWriteType(tuples.map { it[i] })
                        val arg = args[i]
                        if (arg is SpreadElement) continue
                        val argType = getTypeOfExpression(arg)
                        if (argType === anyType || argType === errorType) continue
                        if (!checkTypeRelatedTo(argType, combined, assignableRelation)) {
                            val start = arg.pos
                            val length = expressionTrueEnd(arg) - start
                            if (length > 0) {
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "Argument of type '${typeToString(widenType(argType))}' is not assignable to parameter of type '${typeToString(combined)}'.",
                                    category = DiagnosticCategory.Error, code = 2345,
                                    fileName = fileName, line = line, character = character,
                                    start = start, length = length,
                                ))
                            }
                        }
                    }
                    return true
                }
                // unionOfArraysFilterCall: a union with an OVERLOADED member — at least one
                // constituent has ≥2 call signatures (e.g. `(Fizz[] | readonly Buzz[]).filter`,
                // where Array.filter has 2 overloads but ReadonlyArray.filter has 1). tsc combines
                // the parallel overload sets and reports nothing; our `differ` check below compares
                // only the FIRST sig of each member → spurious TS2349. Suppress. FP-safe: the only
                // corpus TS2349 baselines use all-single-sig members (`any{≥2}` is false for them).
                if (constituents.any { getCallSignaturesOfType(it).size >= 2 }) return true
                val differ = run {
                    for (i in sigs.indices) for (j in i + 1 until sigs.size) {
                        val s1 = sigs[i]; val s2 = sigs[j]
                        if ((s1.typeParameters?.size ?: 0) != (s2.typeParameters?.size ?: 0)) return@run true
                        if (s1.parameters.size != s2.parameters.size) return@run true
                        for (k in s1.parameters.indices) {
                            val t1 = getTypeOfSymbol(s1.parameters[k])
                            val t2 = getTypeOfSymbol(s2.parameters[k])
                            if (t1 !== t2) return@run true
                        }
                    }
                    false
                }
                if (differ) {
                    val (start, length) = computeSpan()
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "This expression is not callable.",
                            category = DiagnosticCategory.Error, code = 2349,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                            messageChain = listOf(
                                "  Each member of the union type '$unionDisplay' has signatures, but none of those signatures are compatible with each other.",
                            ),
                        ))
                    }
                    return true
                }
            }
        }
        return false
    }

    /**
     * (JIT.1)(c) round 811 — the `signatures.isEmpty()` branch
     * ([CallSections.NO_SIGS]) of [checkSingleCallExpressionTypesCore]: TS2348 /
     * TS6234 / TS2721 / TS2722 / TS2723 / TS2349 x3.
     *
     * The branch returned UNCONDITIONALLY, so every `return` in it is a return
     * from this helper and the caller returns straight after the call. It is
     * entered ZERO times on the compiler profile (round 734's exit census).
     */
    private fun ccetNoCallSignatureDiagnostics(
        expr: CallExpression,
        calleeExpr: Expression,
        calleeType: Type,
        source: String,
        fileName: String,
    ) {
        // 17.166: TS2348 — `var c = C();` where C is a class. The class
        // value's type is `typeof C` with construct signatures only; calling
        // it without `new` is a user error. Squiggle covers the full call
        // expression (matches TypeScript's `C()` span in the baseline) —
        // computed locally so the shared expressionTrueEnd helper stays
        // unchanged (an earlier attempt to widen its empty-args fallback
        // regressed -2 unrelated tests).
        if (calleeExpr is Identifier) {
            val sym = globals[calleeExpr.text]
            // 17.166: gate TS2348 to symbols that are PURE classes — i.e. no
            // FunctionDeclaration anywhere in any binderResult's source file with
            // the same name (the binder's `canMerge` rejects Class+Function so the
            // function decl lives in a separate slot or is overwritten — check the
            // AST directly). Without this gate, `callOverloads3/4/5_ts` and
            // `callOnInstance_ts` (which merge `function Foo(): Foo` /
            // `declare function D()` with classes named the same) FP-fire TS2348.
            val name = calleeExpr.text
            val ts2348ScanT = CallSections.t()
            val hasFunctionWithSameName = binderResults.any { br ->
                br.sourceFile.statements.any { st ->
                    st is FunctionDeclaration && st.name?.text == name
                }
            }
            CallSections.close(CallSections.N_TS2348_SCAN, ts2348ScanT)
            if (sym != null && sym.flags.hasAny(SymbolFlags.Class) && !hasFunctionWithSameName) {
                val start = expr.pos
                val end = if (expr.arguments.isNotEmpty()) {
                    expressionTrueEnd(expr.arguments.last()) + 1
                } else {
                    // empty `()` past the callee identifier
                    calleeExpr.pos + calleeExpr.text.length + 2
                }
                val length = end - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Value of type 'typeof ${calleeExpr.text}' is not callable. Did you mean to include 'new'?",
                        category = DiagnosticCategory.Error,
                        code = 2348,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                return
            }
        }
        // 16.4cs: TS6234 — calling a property whose only declarations are
        // `get`/`set` accessors. The property resolves to its return type
        // (e.g. `number`), which has no call signatures, so an attempted
        // `obj.prop()` is a user error — they likely meant `obj.prop`.
        val firedTs6234 = checkTs6234GetAccessorCall(expr, calleeType, source, fileName)
        // 16.4gk: TS2349 "This expression is not callable." Narrow gate on
        // primitives: when the callee resolves to a Type.Intrinsic (number,
        // string, boolean, etc.), the call is definitively invalid. Display
        // uses the wrapper interface name (e.g. 'Number' for number).
        // Skip when TS6234 already fired (get-accessor calls share the same
        // primitive return-type pattern).
        // B62.2: TS2721/TS2722/TS2723 for nullable callees under strictNullChecks.
        //   null()      → TS2721 "Cannot invoke an object which is possibly 'null'."
        //   undefined() → TS2722 "Cannot invoke an object which is possibly 'undefined'."
        //   f() where f: null | undefined → TS2723 "Cannot invoke ... 'null' or 'undefined'."
        // Span: full callee expression text.
        if (!firedTs6234 && strictNullChecks) {
            val isNullCallee = calleeType === nullType
            val isUndefCallee = calleeType === undefinedType
            val isUnionNullUndef = calleeType is Type.Union &&
                calleeType.types.size == 2 &&
                calleeType.types.all { it === nullType || it === undefinedType } &&
                calleeType.types.any { it === nullType } &&
                calleeType.types.any { it === undefinedType }
            if (isNullCallee || isUndefCallee || isUnionNullUndef) {
                val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                    Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                } else {
                    val s = calleeExpr.pos
                    Pair(s, expressionTrueEnd(calleeExpr) - s)
                }
                if (length > 0) {
                    val (msg, code) = when {
                        isNullCallee -> "Cannot invoke an object which is possibly 'null'." to 2721
                        isUndefCallee -> "Cannot invoke an object which is possibly 'undefined'." to 2722
                        else -> "Cannot invoke an object which is possibly 'null' or 'undefined'." to 2723
                    }
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = msg,
                        category = DiagnosticCategory.Error, code = code,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                    ))
                    return
                }
            }
        }
        // B60.14: union callee — "No constituent ... is callable" or
        // "Not all constituents ... are callable" depending on whether any
        // constituent has call sigs.
        if (!firedTs6234 && calleeType is Type.Union) {
            val unionDisplay = typeToString(calleeType)
            val constituents = calleeType.types
            val nonCallable = constituents.filter { getCallSignaturesOfType(it).isEmpty() }
            if (nonCallable.isNotEmpty() && nonCallable.size == constituents.size) {
                // All constituents lack call sigs.
                val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                    Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                } else {
                    val s = calleeExpr.pos
                    Pair(s, expressionTrueEnd(calleeExpr) - s)
                }
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error, code = 2349,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf("  No constituent of type '$unionDisplay' is callable."),
                    ))
                    return
                }
            } else if (nonCallable.isNotEmpty()) {
                // Some constituents lack call sigs.
                val firstMissing = nonCallable[0]
                val missingDisplay = typeToString(firstMissing)
                val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                    Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
                } else {
                    val s = calleeExpr.pos
                    Pair(s, expressionTrueEnd(calleeExpr) - s)
                }
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error, code = 2349,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf(
                            "  Not all constituents of type '$unionDisplay' are callable.",
                            "    Type '$missingDisplay' has no call signatures.",
                        ),
                    ))
                    return
                }
            }
        }
        if (!firedTs6234 && calleeType is Type.Intrinsic && calleeType !== voidType &&
            calleeType !== nullType && calleeType !== undefinedType &&
            calleeType !== neverType && calleeType !== unknownType) {
            val displayType = typeToString(getApparentType(calleeType))
            // 17.84: When the callee is a PropertyAccessExpression, squiggle just
            // the property name (matches TypeScript's per-segment elaboration for
            // chained calls like `obj.method().notMethod()` — only `notMethod`
            // is highlighted, not the whole chain).
            val (start, length) = if (calleeExpr is PropertyAccessExpression) {
                Pair(calleeExpr.name.pos, calleeExpr.name.text.length)
            } else {
                val s = calleeExpr.pos
                Pair(s, expressionTrueEnd(calleeExpr) - s)
            }
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                // B60.13: When the callee is a CallExpression whose end is on a
                // different (earlier) line than the outer call's first argument,
                // emit TS2734 "Are you missing a semicolon?" related info pointing
                // to the inner call's start. Covers the `foo()\n(1 as number)`
                // accidental-call pattern from `betterErrorForAccidentalCall_ts`.
                val related = mutableListOf<Diagnostic>()
                if (calleeExpr is CallExpression && expr.arguments.isNotEmpty()) {
                    val innerEnd = expressionTrueEnd(calleeExpr)
                    val firstArgPos = expr.arguments.first().pos
                    val (innerEndLine, _) = getLineAndCharacterOfPosition(source, innerEnd)
                    val (argLine, _) = getLineAndCharacterOfPosition(source, firstArgPos)
                    if (innerEndLine < argLine) {
                        val innerStart = calleeExpr.pos
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, innerStart)
                        related.add(Diagnostic(
                            message = "Are you missing a semicolon?",
                            category = DiagnosticCategory.Message, code = 2734,
                            fileName = fileName, line = relLine, character = relChar,
                            start = innerStart, length = length,
                        ))
                    }
                }
                diagnostics.add(Diagnostic(
                    message = "This expression is not callable.",
                    category = DiagnosticCategory.Error,
                    code = 2349,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    messageChain = listOf("  Type '$displayType' has no call signatures."),
                    relatedInformation = if (related.isEmpty()) emptyList() else related.toList(),
                ))
            }
        }
        // TS2349: calling a class instance produced by `new X()` — `(new X())()`.
        // The result of a `new` expression is always a (non-callable) object
        // instance, so a callee that unwraps to a NewExpression with no call
        // signatures is unambiguously not callable. Gated tightly to the
        // NewExpression-callee shape so it never trips on the "empty Type.Object
        // from incomplete resolution" trap (a real class instance genuinely has
        // no call signatures regardless of how completely we resolved it).
        if (!firedTs6234 && (calleeType is Type.Object || calleeType is Type.Interface)) {
            var core: Expression = calleeExpr
            while (core is ParenthesizedExpression) core = core.expression
            // Round 479 (tsc isUntypedFunctionCall): a value of the global lib
            // `Function` type IS callable — the call is untyped and returns any
            // (`new Function("…")()`, fourslashImpl.ts verifyEval). A USER class
            // named Function keeps firing (its decls are not lib decls).
            val isGlobalFunctionType = calleeType.symbol?.let { sy ->
                sy.name == "Function" && sy.declarations.isNotEmpty() &&
                    sy.declarations.all { it in builtinLibDecls }
            } == true
            if (core is NewExpression && !isGlobalFunctionType) {
                val displayType = typeToString(getApparentType(calleeType))
                val start = calleeExpr.pos
                val length = expressionTrueEnd(calleeExpr) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not callable.",
                        category = DiagnosticCategory.Error,
                        code = 2349,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        messageChain = listOf("  Type '$displayType' has no call signatures."),
                    ))
                }
            }
        }
        return
    }

    /**
     * (JIT.1)(c) round 811 — the EXPLICIT-type-argument branch
     * ([CallSections.TYPE_ARGS]) of [checkSingleCallExpressionTypesCore].
     *
     * 101 of 52,413 invocations leave the function here on the compiler profile.
     * `true` means "checked under the instantiated signature — the caller must
     * return"; falling through means no generic signature accommodated the
     * supplied type arguments and the ordinary paths below still apply.
     */
    private fun ccetExplicitTypeArguments(
        expr: CallExpression,
        typeArgs: List<TypeNode>,
        signatures: List<Signature>,
        source: String,
        fileName: String,
    ): Boolean {
        // B174: `f<typeof import("spec")>(null)` — getTypeFromTypeNode resolves an
        // import-type to anyType (masking the instantiated param check), but under
        // strictNullChecks a `null` arg against a bare-TP param mapped to the
        // import-namespace type is TS2345 with the RESOLVED module path display
        // (declarationEmitWithInvalidPackageJsonTypings: an ARRAY-valued package.json
        // "types" is invalid → resolution falls back to "main" → lib/index.d.ts).
        run {
            if (!strictNullChecks || typeArgs.size != 1) return@run
            // `typeof import("spec")` parses as TypeQuery(exprName = ImportType) (the
            // Parser's Typeof branch); a bare import-type arg is an ImportType directly.
            val imp = (typeArgs[0] as? ImportType)
                ?: ((typeArgs[0] as? TypeQuery)?.exprName as? ImportType)
                ?: return@run
            if (imp.qualifier != null) return@run
            val specLit = ((imp.argument as? LiteralType)?.literal as? StringLiteralNode)?.text
                ?: return@run
            val sig = signatures.firstOrNull { it.typeParameters?.size == 1 } ?: return@run
            val tpName = sig.typeParameters!![0].symbol?.name ?: return@run
            val sigParams = signatureDeclarationParameters(sig.declaration) ?: return@run
            val argIdx = sigParams.indexOfFirst { p ->
                (p.type as? TypeReference)?.let {
                    it.typeArguments == null && (it.typeName as? Identifier)?.text == tpName
                } == true
            }
            if (argIdx < 0) return@run
            val arg = expr.arguments.getOrNull(argIdx) ?: return@run
            if (!(arg is Identifier && arg.text == "null")) return@run
            val g = resolveBareViaNodeModulesPkgJson(specLit, fileName)
                ?: resolveBareViaNodeModules(specLit, fileName)
                ?: resolveSpecifierAnywhere(specLit, fileName)
                ?: return@run
            val baseDisplay = g.removeSuffix(".d.ts").removeSuffix(".tsx").removeSuffix(".ts")
            val start = arg.pos
            val length = expressionTrueEnd(arg) - start
            val (l, c) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type 'null' is not assignable to parameter of type 'typeof import(\"$baseDisplay\")'.",
                category = DiagnosticCategory.Error, code = 2345,
                fileName = fileName, line = l, character = c,
                start = start, length = length,
            ))
            return true
        }
        val resolvedTypeArgs = typeArgs.map { getTypeFromTypeNode(it) }
        if (resolvedTypeArgs.none { it === errorType }) {
            // Find a generic signature whose type-param count accommodates the supplied
            // type args. Exact-arity matches; ADDITIONALLY accept FEWER args than params
            // when the trailing params have defaults — the supplied count must be within
            // [minTypeParams, size] where minTypeParams = count of params with NO default.
            // Previously only exact-arity sigs matched, so `fn<MyObjA>` against
            // `<A extends ObjA, B extends ObjB = ObjB>` skipped the constraint check for
            // the supplied `A` entirely (TS2344/TS2559 never fired).
            val genericCandidates = signatures.filter { sig ->
                val tp = sig.typeParameters ?: return@filter false
                resolvedTypeArgs.size in tp.count { it.default == null }..tp.size
            }
            // Round 436d: with MULTIPLE arity-accommodating generic overloads, tsc
            // selects the first whose ARGUMENTS match under the supplied type args —
            // parser.ts `createMissingNode<Identifier>(kind, /*reportAtCurrentPosition*/
            // true, msg)` must select the 2nd overload (the 1st pins the param to the
            // literal `false`). Blindly checking against the FIRST candidate FP'd
            // 'true' ≁ 'false' ×5. tsc applicability filters by TYPE-ARG CONSTRAINT
            // first (typeArgumentConstraintResolution1: `foo1<Date>("")` disqualifies
            // the `T extends Number` overload, so the arg failure reports against the
            // `T extends Date` one — the suite gate caught the unfiltered cut). Falls
            // back to the first candidate when none match (the error-reporting target,
            // as before) — an over-accepting match can only SUPPRESS (this path only
            // checks args; return-type inference lives elsewhere).
            val constraintOkCandidates = genericCandidates.filter {
                implTypeArgConstraintsSatisfied(it, resolvedTypeArgs)
            }.ifEmpty { genericCandidates }
            val genericSig = if (constraintOkCandidates.size <= 1) constraintOkCandidates.firstOrNull()
            else constraintOkCandidates.firstOrNull { sig ->
                val tps = sig.typeParameters!!
                val padded = if (resolvedTypeArgs.size < tps.size)
                    resolvedTypeArgs + (resolvedTypeArgs.size until tps.size).map { tps[it].default ?: errorType }
                else resolvedTypeArgs
                allArgumentsMatch(expr.arguments, instantiateContextualSignature(sig, createTypeMapper(tps, padded)))
            } ?: constraintOkCandidates.first()
            if (genericSig?.typeParameters != null) {
                val tps = genericSig.typeParameters
                // Pad the supplied args with the trailing params' resolved defaults so the
                // mapper + contextual instantiation see every param. The constraint check
                // still iterates only the SUPPLIED args (each has a typeArgNode).
                val paddedArgs = if (resolvedTypeArgs.size < tps.size) {
                    resolvedTypeArgs + (resolvedTypeArgs.size until tps.size).map { tps[it].default ?: errorType }
                } else resolvedTypeArgs
                val mapper = createTypeMapper(tps, paddedArgs)
                // TS2344 / TS2559: Check supplied type arguments against their constraints.
                checkCallTypeArgConstraints(tps, resolvedTypeArgs, typeArgs, mapper, source, fileName)
                // B83.4f-a: use instantiateContextualSignature (not the plain
                // instantiateSignature) so a nested FUNCTION-typed param like
                // `f: (x: T) => Date` substitutes its inner `(x: T)` to `(x: <number>)`.
                // Plain instantiateType deliberately no-ops on function-shaped
                // Type.Object (CLAUDE.md gotcha); instantiateContextualSignature descends
                // into the call signatures, so explicit `<number>` reaches the callback
                // param and TS2345 (`(x:number)=>string` ≠ `(x:number)=>Date`) can fire.
                val instantiated = instantiateContextualSignature(genericSig, mapper)
                // TS2793: only attach "implementation would have succeeded" related info
                // when the implementation signature actually accepts these args under
                // the supplied type-args. For overloaded generic functions like
                // `foo<T extends Date>(test: T)` / `foo<T extends Number>(test: string)`
                // / `foo<T extends String>(test: any)` (impl), calling `foo<Date>("")`
                // doesn't satisfy the impl's `T extends String` constraint, so the impl
                // wouldn't have succeeded either — TS2793 should be suppressed.
                var implRelated: Diagnostic? = null
                val implRelatedCandidate = getOverloadImplementationRelated(genericSig, source, fileName)
                if (implRelatedCandidate != null) {
                    val implSig = getImplementationSignature(genericSig, source, fileName)
                    if (implSig != null && allArgumentsMatch(expr.arguments, implSig, bivariantFnParams = true) &&
                        implTypeArgConstraintsSatisfied(implSig, resolvedTypeArgs)
                    ) {
                        implRelated = implRelatedCandidate
                    }
                }
                checkTs2554ForPropertyAccessCall(expr, instantiated, source, fileName)
                val taArgsT = CallSections.t()
                checkArgumentsAgainstSignature(expr.arguments, instantiated, source, fileName, implRelated, calleeGenericInstantiation = true)
                CallSections.close(CallSections.N_TYPEARGS_ARGS, taArgsT)
                return true
            }
        }
        return false
    }

    /**
     * 17.11b: Emit TS2554 (Expected N arguments, but got M) for property-access
     * call expressions like `x.b()` where the resolved sig requires more args
     * than provided. The syntactic arg-count walker (`checkArgCountInExprCore`)
     * only handles `Identifier` callees because it works without type
     * resolution; PropertyAccess callees fall through. This type-aware check
     * fills the gap for that subset. Squiggle is on the property name (matches
     * TypeScript baseline). For too-few args, emits a TS6210 related info
     * pointing to the missing parameter's declaration.
     */
    private fun checkTs2554ForPropertyAccessCall(
        expr: CallExpression,
        sig: Signature,
        source: String,
        fileName: String,
    ) {
        val callee = expr.expression as? PropertyAccessExpression ?: return
        // B241: a SOFT later-lib member (Array.flat/flatMap under a pre-es2019 lib)
        // errors TS2550 at the property access instead — suppress the arity check.
        run {
            val memberDecl = sig.declaration ?: return@run
            if (memberDecl !in builtinLibMemberDecls) return@run
            val mName = callee.name.text
            if (LIB_MIN_TARGET_SOFT.any { (k, v) -> k.endsWith(".$mName") && !libFeatureAvailable(v) }) return
        }
        val params = sig.parameters
        // Round 446: a DESTRUCTURED param `{ a, b }: T` produces NO Symbol, so
        // `sig.parameters` DROPS it (`{ fileName, pos }: Range` → empty parameters list),
        // giving an impossible arity range (`maxParams` 0 while `minArgumentCount` 1 →
        // "Expected 1-0 arguments"). Recover the TRUE arity from the DECLARATION's
        // parameter list (paramInfo counts binding-pattern params + handles rest/optional)
        // when the declaration is a function-like node.
        val declParams: List<Parameter>? = when (val d = sig.declaration) {
            is FunctionDeclaration -> d.parameters
            is MethodDeclaration -> d.parameters
            is FunctionExpression -> d.parameters
            is ArrowFunction -> d.parameters
            is Constructor -> d.parameters
            is GetAccessor -> d.parameters
            is SetAccessor -> d.parameters
            else -> null
        }
        val declInfo = declParams?.let { paramInfo(it) }
        val hasRest = declInfo?.hasRest
            ?: ((params.lastOrNull()?.valueDeclaration as? Parameter)?.dotDotDotToken == true)
        val argCount = expr.arguments.size
        val minParams = declInfo?.minParams ?: sig.minArgumentCount
        val maxParams = declInfo?.maxParams ?: params.size
        if (argCount >= minParams && (hasRest || argCount <= maxParams)) return
        if (argCount >= minParams) {
            // B279: too-many args for a method call — same squiggle convention as the
            // Identifier-callee path (covers the excess arguments). NOT for embedded-lib
            // members: the embedded lib simplifies many optional params away
            // (toLocaleString(locales?, options?), forEach(cb, thisArg?)) → FP surface.
            val sigDecl = sig.declaration
            if (sigDecl != null && sigDecl in builtinLibMemberDecls) return
            emitTS2554TooMany(minParams, maxParams, argCount, expr.arguments, maxParams, source, fileName)
            return
        }
        val nameNode = callee.name
        val start = nameNode.pos
        val length = nameNode.text.length
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val relatedInfo = mutableListOf<Diagnostic>()
        if (argCount < params.size) {
            val missingSym = params[argCount]
            val missingParam = missingSym.valueDeclaration as? Parameter
            val pname = missingParam?.name as? Identifier
            if (pname != null) {
                val (rLine, rChar) = getLineAndCharacterOfPosition(source, pname.pos)
                relatedInfo.add(Diagnostic(
                    message = "An argument for '${pname.text}' was not provided.",
                    category = DiagnosticCategory.Message,
                    code = 6210,
                    fileName = fileName,
                    line = rLine,
                    character = rChar,
                    start = pname.pos,
                    length = pname.text.length,
                ))
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $argCount.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    /**
     * 16.4cs: TS6234 — emit when a call's callee is `recv.prop()` and `prop` is a
     * `get` accessor (no callable companion). Squiggle on the property name; chain
     * uses the apparent type's display name ("Number" for `number`, etc.).
     */
    private fun checkTs6234GetAccessorCall(
        expr: CallExpression,
        calleeType: Type,
        source: String,
        fileName: String,
    ): Boolean {
        val callee = expr.expression as? PropertyAccessExpression ?: return false
        val recvType = getTypeOfExpression(callee.expression)
        if (recvType === anyType || recvType === errorType) return false
        val apparent = getApparentType(recvType)
        val prop = getPropertyOfType(apparent, callee.name.text) ?: return false
        val decls = prop.declarations
        if (decls.isEmpty()) return false
        var hasGetter = false
        for (d in decls) {
            when (d) {
                is GetAccessor -> hasGetter = true
                is SetAccessor -> { /* getter+setter pair still qualifies */ }
                else -> return false
            }
        }
        if (!hasGetter) return false
        val name = callee.name
        val start = name.pos
        val length = name.text.length
        if (length <= 0) return false
        val displayType = typeToString(getApparentType(calleeType))
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This expression is not callable because it is a 'get' accessor. Did you mean to use it without '()'?",
            category = DiagnosticCategory.Error,
            code = 6234,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf("  Type '$displayType' has no call signatures."),
        ))
        return true
    }

    /**
     * Check if a signature belongs to an overloaded function/method with an implementation.
     * Returns a TS2793 related diagnostic pointing to the implementation, or null.
     * Uses the signature's declaration to find the implementation among sibling declarations.
     */
    private fun getOverloadImplementationRelated(sig: Signature, source: String, fileName: String): Diagnostic? {
        val overloadDecl = sig.declaration ?: return null
        // For functions, look up the symbol by name
        if (overloadDecl is FunctionDeclaration) {
            val nameNode = overloadDecl.name ?: return null
            val name = nameNode.text
            // INV.3(c)(iv) leg 2: key by the overload DECL's own name node —
            // a top-level decl's file always declares the name (same merged
            // instance, byte-identical); a nested (B83.5-unbound) or foreign
            // collision no longer hands TS2793 a wrong-file impl pointer from
            // the merged declarations list.
            val symbol = lookupPerFileForNode(nameNode, name)
                ?: currentFileLocals?.get(name) ?: return null
            return getImplRelatedFromDecls(symbol.declarations, source, fileName)
        }
        // For methods, find the containing class and search for sibling methods with same name
        if (overloadDecl is MethodDeclaration) {
            val methodName = (overloadDecl.name as? Identifier)?.text ?: return null
            // Search source files for a class containing this method declaration
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findImplementationInStatements(result.sourceFile.statements, methodName, overloadDecl)
                if (implDecl != null) {
                    return makeTs2793Diagnostic(implDecl, source, fileName)
                }
            }
        }
        // 17.91: Constructor overloads — find the containing class and the FIRST
        // constructor implementation. The first impl is the conventional anchor
        // for TS2793 even when multiple impls exist (which themselves emit TS2392).
        if (overloadDecl is Constructor) {
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findCtorImplementationInStatements(result.sourceFile.statements, overloadDecl)
                if (implDecl != null) {
                    return makeTs2793Diagnostic(implDecl, source, fileName)
                }
            }
        }
        return null
    }

    /**
     * (ENGINE.2h) round 795 — the whole TS2793 "the implementation would have
     * succeeded" probe as ONE function, so it can be DEFERRED to the single site
     * that reads its answer.
     *
     * It is [getOverloadImplementationRelated] (find the implementation to point
     * at) + [getImplementationSignature] (rebuild its signature) +
     * [allArgumentsMatch] (would it have accepted these arguments?), and its
     * result is a piece of RELATED INFO attached to an argument diagnostic —
     * i.e. it is read only where an argument diagnostic actually fires. Run
     * eagerly at every single-signature call it cost 72–79 ms per compiler-profile
     * compile over 23,214 invocations, of which 57 reach a reader.
     *
     * [bogus] is the positive control (`--verifyImplRelatedBogus`): it drops the
     * `allArgumentsMatch` gate, which is the only part of the answer a
     * mutation-order difference could plausibly move, so the verifier's diff
     * column has something it MUST see.
     */
    private fun overloadImplementationRelated(
        args: List<Expression>,
        sig: Signature,
        source: String,
        fileName: String,
        bogus: Boolean = false,
    ): Diagnostic? {
        val candidate = getOverloadImplementationRelated(sig, source, fileName)
        if (candidate == null) {
            CallSections.noteImplRelated(candidate = false, implSig = false, applied = false)
            return null
        }
        val implSig = getImplementationSignature(sig, source, fileName)
        if (implSig == null) {
            CallSections.noteImplRelated(candidate = true, implSig = false, applied = false)
            return null
        }
        val matched = bogus || allArgumentsMatch(args, implSig, bivariantFnParams = true)
        CallSections.noteImplRelated(candidate = true, implSig = true, applied = matched)
        return if (matched) candidate else null
    }

    private fun findCtorImplementationInStatements(stmts: List<Statement>, overloadDecl: Constructor): Constructor? {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    var foundOverload = false
                    var hasBodylessOverload = false
                    var firstImpl: Constructor? = null
                    for (member in stmt.members) {
                        if (member !is Constructor) continue
                        if (member === overloadDecl) foundOverload = true
                        if (member.body == null) hasBodylessOverload = true
                        if (member.body != null && firstImpl == null) firstImpl = member
                    }
                    if (foundOverload && hasBodylessOverload && firstImpl != null) return firstImpl
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        val result = findCtorImplementationInStatements(body.statements, overloadDecl)
                        if (result != null) return result
                    }
                }
                else -> {}
            }
        }
        return null
    }

    /** Search statements for a class/interface containing the given overload and its implementation. */
    private fun findImplementationInStatements(stmts: List<Statement>, methodName: String, overloadDecl: Node): MethodDeclaration? {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    // 17.76: Require at least one body-less overload-sig declaration AND
                    // a separate body-having implementation. A single method with a body
                    // is NOT an overload pair — without this gate, a bare `bar(x: T) {}`
                    // emits TS2793 "implementation would have succeeded" pointing to
                    // itself (cf. genericOfACloduleType1/2_ts).
                    var foundOverload = false
                    var hasBodylessOverload = false
                    var impl: MethodDeclaration? = null
                    for (member in stmt.members) {
                        if (member !is MethodDeclaration) continue
                        val name = (member.name as? Identifier)?.text ?: continue
                        if (name != methodName) continue
                        if (member === overloadDecl) foundOverload = true
                        if (member.body == null) hasBodylessOverload = true
                        if (member.body != null) impl = member
                    }
                    if (foundOverload && hasBodylessOverload && impl != null) return impl
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        val result = findImplementationInStatements(body.statements, methodName, overloadDecl)
                        if (result != null) return result
                    }
                }
                else -> {}
            }
        }
        return null
    }

    private fun getImplRelatedFromDecls(decls: List<Node>, source: String, fileName: String): Diagnostic? {
        val hasOverload = decls.any { d ->
            (d is MethodDeclaration && d.body == null) || (d is FunctionDeclaration && d.body == null)
        }
        val implDecl = decls.firstOrNull { d ->
            (d is MethodDeclaration && d.body != null) || (d is FunctionDeclaration && d.body != null)
        }
        if (!hasOverload || implDecl == null) return null
        return makeTs2793Diagnostic(implDecl, source, fileName)
    }

    private fun makeTs2793Diagnostic(implDecl: Node, source: String, fileName: String): Diagnostic {
        // Point to the function/method name, spanning to the body start.
        // For Constructor, point to the `constructor` keyword (no name node).
        val namePos = when (implDecl) {
            is FunctionDeclaration -> implDecl.name?.pos ?: implDecl.pos
            is MethodDeclaration -> (implDecl.name as? Identifier)?.pos ?: implDecl.pos
            is Constructor -> {
                val kwStart = srcIndexOf(source, "constructor", startIndex = implDecl.pos)
                if (kwStart in implDecl.pos..<implDecl.end) kwStart else implDecl.pos
            }
            else -> implDecl.pos
        }
        val implEnd = when (implDecl) {
            is MethodDeclaration -> implDecl.body?.pos ?: implDecl.end
            is FunctionDeclaration -> implDecl.body?.pos ?: implDecl.end
            is Constructor -> implDecl.body?.pos ?: implDecl.end
            else -> implDecl.end
        }
        val implLength = implEnd - namePos
        val (implLine, implChar) = getLineAndCharacterOfPosition(source, namePos)
        return Diagnostic(
            message = "The call would have succeeded against this implementation, but implementation signatures of overloads are not externally visible.",
            category = DiagnosticCategory.Message,
            code = 2793,
            fileName = fileName,
            line = implLine,
            character = implChar,
            start = namePos,
            length = implLength,
        )
    }

    /**
     * For a TS2769 overload error caused by a property type mismatch,
     * generate TS6500 related info: "The expected type comes from property 'X'
     * which is declared here on type 'Y'".
     * Points to the property declaration in the parameter's type literal.
     */
    private fun getPropertySourceRelated(
        args: List<Expression>,
        sig: Signature,
        source: String,
        fileName: String,
    ): Diagnostic? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            // Dig through array types to get to the element type
            val (actualArg, actualParamType) = unwrapArrayArg(arg, paramType) ?: Pair(arg, paramType)
            if (actualArg !is ObjectLiteralExpression || actualParamType !is Type.Object) continue
            resolveStructuredTypeMembers(actualParamType)
            val targetProps = actualParamType.properties ?: continue
            val argType = getTypeOfExpression(actualArg) as? Type.Object ?: continue
            for (targetProp in targetProps) {
                val sourceProp = argType.members?.get(targetProp.name) ?: continue
                val sourcePropType = getTypeOfSymbol(sourceProp)
                val targetPropType = getTypeOfSymbol(targetProp)
                if (!checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) {
                    // Found the mismatched property — point to its declaration in the param type
                    val propDecl = targetProp.declarations.firstOrNull() ?: continue
                    val propName = targetProp.name
                    val propPos = when (propDecl) {
                        is PropertyDeclaration -> propDecl.name.pos
                        is PropertyAssignment -> propDecl.name.pos
                        else -> propDecl.pos
                    }
                    val propLength = propName.length
                    // Get the containing type display name
                    val typeDisplay = typeToString(actualParamType)
                    val (propLine, propChar) = getLineAndCharacterOfPosition(source, propPos)
                    return Diagnostic(
                        message = "The expected type comes from property '$propName' which is declared here on type '$typeDisplay'",
                        category = DiagnosticCategory.Message,
                        code = 6500,
                        fileName = fileName,
                        line = propLine,
                        character = propChar,
                        start = propPos,
                        length = propLength,
                    )
                }
            }
        }
        return null
    }

    /**
     * For a TS2769 overload error caused by a MISSING property,
     * generate TS2728 related info: "'X' is declared here."
     * Points to the property declaration in the parameter's type literal.
     */
    private fun getMissingPropertyDeclaredHere(
        args: List<Expression>,
        sig: Signature,
        source: String,
        fileName: String,
    ): Diagnostic? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val (actualArg, actualParamType) = unwrapArrayArg(arg, paramType) ?: Pair(arg, paramType)
            if (actualParamType !is Type.Object) continue
            resolveStructuredTypeMembers(actualParamType)
            val targetProps = actualParamType.properties ?: continue
            val argType = getTypeOfExpression(actualArg)
            if (argType !is Type.Object) continue
            for (targetProp in targetProps) {
                if (isOptionalProperty(targetProp)) continue
                val sourceProp = argType.members?.get(targetProp.name)
                if (sourceProp == null) {
                    // Found missing property — point to its declaration
                    val propDecl = targetProp.declarations.firstOrNull() ?: continue
                    val propPos = when (propDecl) {
                        is PropertyDeclaration -> propDecl.name.pos
                        else -> propDecl.pos
                    }
                    val propName = targetProp.name
                    val (propLine, propChar) = getLineAndCharacterOfPosition(source, propPos)
                    return Diagnostic(
                        message = "'$propName' is declared here.",
                        category = DiagnosticCategory.Message,
                        code = 2728,
                        fileName = fileName,
                        line = propLine,
                        character = propChar,
                        start = propPos,
                        length = propName.length,
                    )
                }
            }
        }
        return null
    }

    /**
     * Get the implementation signature for a function/method that has overloads.
     * Returns null if no implementation exists.
     */
    private fun getImplementationSignature(
        overloadSig: Signature,
        source: String,
        fileName: String,
    ): Signature? {
        val overloadDecl = overloadSig.declaration ?: return null
        if (overloadDecl is FunctionDeclaration) {
            val name = overloadDecl.name?.text ?: return null
            val symbol = globals[name] ?: currentFileLocals?.get(name) ?: return null
            val implDecl = symbol.declarations.filterIsInstance<FunctionDeclaration>()
                .find { it.body != null } ?: return null
            val returnType = implDecl.type?.let { getTypeFromTypeNode(it) } ?: anyType
            return Signature(
                declaration = implDecl,
                parameters = getParameterSymbols(implDecl.parameters),
                resolvedReturnType = returnType,
                minArgumentCount = requiredParameterCount(implDecl.parameters),
            )
        }
        // 17.137a: Method overloads — find the impl among sibling methods of the
        // same class. Mirrors the existing `findImplementationInStatements` walker
        // used by `getOverloadImplementationRelated`. Used as the TS2793 gate so
        // tests like `overloadErrorMatchesImplementationElaboaration` (impl is
        // generic `<T>(event: T)`) get a non-null implSig — the existing fallback
        // returned null for methods, leaving the TS2793 gate without enough info.
        if (overloadDecl is MethodDeclaration) {
            val methodName = (overloadDecl.name as? Identifier)?.text ?: return null
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findImplementationInStatements(
                    result.sourceFile.statements, methodName, overloadDecl,
                ) ?: continue
                val returnType = implDecl.type?.let { getTypeFromTypeNode(it) } ?: anyType
                return Signature(
                    declaration = implDecl,
                    parameters = getParameterSymbols(implDecl.parameters),
                    resolvedReturnType = returnType,
                    minArgumentCount = requiredParameterCount(implDecl.parameters),
                )
            }
        }
        // 17.91: Constructor overloads — find the FIRST impl among sibling constructors
        // in the containing class. Used as the TS2793 "would have succeeded" gate.
        if (overloadDecl is Constructor) {
            for (result in binderResults) {
                if (result.sourceFile.fileName != fileName) continue
                val implDecl = findCtorImplementationInStatements(result.sourceFile.statements, overloadDecl)
                    ?: continue
                return Signature(
                    declaration = implDecl,
                    parameters = getParameterSymbols(implDecl.parameters),
                    resolvedReturnType = overloadSig.resolvedReturnType,
                    minArgumentCount = requiredParameterCount(implDecl.parameters),
                )
            }
        }
        return null
    }

    /**
     * Check whether the implementation signature's own type-param constraints accept
     * the given resolved type-args. Used as a TS2793 gate — when the user calls
     * `foo<X>(args)` with explicit type-args and the impl's type-param has a constraint
     * that `X` doesn't satisfy (e.g. impl is `foo<T extends String>(test: any)` and
     * caller passes `<Date>`), the impl wouldn't have succeeded either, so the
     * "implementation would have matched" related info should be suppressed.
     *
     * Returns true when constraints are satisfied (or no constraints / mismatched arity
     * / resolution errors — conservative default to allow TS2793).
     */
    private fun implTypeArgConstraintsSatisfied(
        implSig: Signature,
        resolvedTypeArgs: List<Type>,
    ): Boolean {
        val decl = implSig.declaration ?: return true
        val tpNodes = when (decl) {
            is FunctionDeclaration -> decl.typeParameters
            is MethodDeclaration -> decl.typeParameters
            else -> null
        } ?: return true
        if (tpNodes.size != resolvedTypeArgs.size) return true
        for (i in tpNodes.indices) {
            val constraintNode = tpNodes[i].constraint ?: continue
            val constraint = getTypeFromTypeNode(constraintNode)
            if (constraint === errorType || constraint === anyType) continue
            if (!checkTypeRelatedTo(resolvedTypeArgs[i], constraint, assignableRelation)) {
                return false
            }
        }
        return true
    }

    /**
     * If arg is ArrayLiteral and paramType is Array<T>, return the first element
     * and the element type T. Otherwise return null.
     */
    private fun unwrapArrayArg(arg: Expression, paramType: Type): Pair<Expression, Type>? {
        if (arg !is ArrayLiteralExpression) return null
        if (paramType !is Type.Reference || paramType.target.symbol?.name != "Array") return null
        val elemType = paramType.resolvedTypeArguments?.firstOrNull() ?: return null
        val firstElem = arg.elements.firstOrNull() ?: return null
        if (firstElem is SpreadElement) return null
        return Pair(firstElem, elemType)
    }

    /**
     * Check argument types for a NewExpression against the construct signature.
     */
    private fun checkSingleNewExpressionTypes(expr: NewExpression, source: String, fileName: String) {
        // (M3.0/ANY.1) round 837 — TS2347 "Untyped function calls may not accept type
        // arguments." tsc's `resolveUntypedCall` is reached from `resolveNewExpression` as
        // well as `resolveCallExpression`, so `new x<any>(x)` on an `any` callee is exactly
        // as much an error as `x<any>(x)` is (`anyAsConstructor`). The gate is the SAME pair
        // of predicates the CallExpression emitter uses — a definitively implicit/explicit
        // `any` var chain, or a `this.<any-member>` access — deliberately NOT the broad
        // `calleeType === anyType`, which our incomplete inference reaches far too often.
        if (!expr.typeArguments.isNullOrEmpty() &&
            (isImplicitAnyVarChain(expr.expression) || isImplicitAnyThisMember(expr.expression))
        ) {
            val start = expr.pos
            val length = expressionTrueEnd(expr) - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Untyped function calls may not accept type arguments.",
                    category = DiagnosticCategory.Error,
                    code = 2347,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
        // 16.4fd: `new []` — empty array literal is not constructable.
        // Narrow to empty array literal — non-empty would need element-type
        // resolution for the chain display.
        if (expr.expression is ArrayLiteralExpression && (expr.expression).elements.isEmpty()) {
            val arr = expr.expression
            val close = source.indexOf(']', arr.pos)
            val length = if (close >= arr.pos) close + 1 - arr.pos else 2
            val (line, character) = getLineAndCharacterOfPosition(source, arr.pos)
            diagnostics.add(Diagnostic(
                message = "This expression is not constructable.",
                category = DiagnosticCategory.Error,
                code = 2351,
                fileName = fileName,
                line = line,
                character = character,
                start = arr.pos,
                length = length,
                messageChain = listOf("  Type 'never[]' has no construct signatures."),
            ))
            return
        }
        // B171: `new DataView(new <TypedArray>(...))` — a typed array is NOT an ArrayBuffer
        // (DataView's parameter is `ArrayBuffer & { BYTES_PER_ELEMENT?: undefined; }`, which
        // a typed array fails via its `[Symbol.toStringTag]` literal). The embedded lib has
        // no DataViewConstructor, so the general path resolves nothing — this is a dedicated
        // AST-gated emission (dataViewConstructor). Fires ONLY for a DIRECT `new TypedArray`
        // argument (an ArrayBuffer-typed value never matches) and only when `DataView` is not
        // shadowed by a user class.
        run {
            val callee = expr.expression as? Identifier ?: return@run
            if (callee.text != "DataView") return@run
            if (globals["DataView"]?.declarations?.any { it is ClassDeclaration } == true) return@run
            val arg = expr.arguments?.firstOrNull() as? NewExpression ?: return@run
            val argCallee = (arg.expression as? Identifier)?.text ?: return@run
            if (argCallee !in TYPED_ARRAY_NAMES) return@run
            if (globals[argCallee]?.declarations?.any { it is ClassDeclaration } == true) return@run
            val start = arg.pos
            val length = expressionTrueEnd(arg) - start
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argCallee<ArrayBuffer>' is not assignable to parameter of type 'ArrayBuffer & { BYTES_PER_ELEMENT?: undefined; }'.",
                category = DiagnosticCategory.Error,
                code = 2345,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
                messageChain = listOf(
                    "  Type '$argCallee<ArrayBuffer>' is not assignable to type 'ArrayBuffer'.",
                    "    Types of property '[Symbol.toStringTag]' are incompatible.",
                    "      Type '\"$argCallee\"' is not assignable to type '\"ArrayBuffer\"'.",
                ),
            ))
            return
        }
        // 17.221: TS2674 — protected constructor accessibility. When `new ClassName(...)`
        // resolves to a class whose effective constructor (own or inherited) is declared
        // `protected`, the call must be inside the declaring class or one of its subclasses.
        // Squiggle covers the full `new` expression. Only fires for bare Identifier callees
        // with a resolvable class symbol.
        if (expr.expression is Identifier) {
            val ident = expr.expression
            val classSym = globals[ident.text]
            if (classSym != null && classSym.declarations.any { it is ClassDeclaration }) {
                val ctorInfo = findEffectiveConstructorVisibility(classSym)
                if (ctorInfo != null && ctorInfo.first == ModifierFlag.Protected) {
                    val declaringClass = ctorInfo.second
                    val accessible = callWalkerClassStack.any { enclosing ->
                        classExtendsOrIs(enclosing, declaringClass)
                    }
                    if (!accessible) {
                        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                        val length = expressionTrueEnd(expr) - expr.pos
                        diagnostics.add(Diagnostic(
                            message = "Constructor of class '${declaringClass.name}' is protected and only accessible within the class declaration.",
                            category = DiagnosticCategory.Error,
                            code = 2674,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = expr.pos,
                            length = length,
                        ))
                    }
                }
            }
        }
        // B295: `new X()` where X is a ctor-less class whose DIRECT extends-base is a
        // generic class referenced WITHOUT type arguments (the heritage carries
        // TS2314) — the inherited base constructor is an error type, so `typeof X`
        // has no construct signatures (tsc resolves the implicit ctor through the
        // errored base). Chain mirrors tsc.
        run {
            val callee = expr.expression as? Identifier ?: return@run
            val sym = currentFileLocals?.get(callee.text) ?: globals[callee.text] ?: return@run
            val cls = sym.declarations.singleOrNull() as? ClassDeclaration ?: return@run
            if (cls.members.any { it is Constructor }) return@run
            val ext = cls.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                ?.types?.singleOrNull() ?: return@run
            if (ext.typeArguments != null) return@run
            val baseName = (ext.expression as? Identifier)?.text ?: return@run
            val baseSym = currentFileLocals?.get(baseName) ?: globals[baseName] ?: return@run
            val baseCls = baseSym.declarations.singleOrNull() as? ClassDeclaration ?: return@run
            if (baseCls in builtinLibDecls) return@run
            val tps = baseCls.typeParameters ?: return@run
            if (tps.isEmpty() || tps.any { it.default != null }) return@run
            val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
            diagnostics.add(Diagnostic(
                message = "This expression is not constructable.",
                category = DiagnosticCategory.Error, code = 2351,
                fileName = fileName, line = line, character = character,
                start = callee.pos, length = callee.text.length,
                messageChain = listOf("  Type 'typeof ${callee.text}' has no construct signatures."),
            ))
            return
        }
        // B497: `new <recv>[]` where the empty `[]` element access (OmittedExpression
        // argument, the TS1011 shape) has a receiver resolving to a value-position CLASS
        // (`typeof X`). The omitted index is `any`-typed; `typeof X` has no index signature
        // → TS7053. Matches tsc's `new M.T[]` recovery. noImplicitAny-gated (default-on).
        run {
            val ce = expr.expression as? ElementAccessExpression ?: return@run
            if (ce.argumentExpression !is OmittedExpression) return@run
            if (options.strictExplicitlyFalse && !options.noImplicitAny && !options.strict) return@run
            val display = typeofClassValueDisplay(ce.expression) ?: return@run
            val start = ce.expression.pos
            val end = ce.argumentExpression.pos + 1  // OmittedExpression.pos = the `]`
            if (end <= start) return@run
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Element implicitly has an 'any' type because expression of type 'any' can't be used to index type '$display'.",
                category = DiagnosticCategory.Error, code = 7053,
                fileName = fileName, line = line, character = character,
                start = start, length = end - start,
            ))
            return
        }
        // B497: `new <non-constructable-literal-or-instance>` — a primitive-literal callee
        // (`new 53()`→Number, `new ''()`→String) or a `new`-expression callee whose returned
        // INSTANCE type has no construct signatures (`new new Date`→Date) is not constructable.
        // These non-Identifier callees fall through getCalleeType (anyType) / the args-required
        // early return below, so handle them here. FP-safe: `new <primitive-literal>` and
        // `new <non-constructable-instance>` are ALWAYS tsc errors.
        run {
            val ce = expr.expression
            val typeName: String = when (ce) {
                is NumericLiteralNode -> "Number"
                is StringLiteralNode -> "String"
                is NewExpression -> {
                    val inst = getReturnTypeOfNewExpression(ce)
                    if (inst is Type.Interface && getConstructSignaturesOfType(inst).isEmpty())
                        inst.symbol?.name ?: return@run
                    else return@run
                }
                else -> return@run
            }
            val (line, character) = getLineAndCharacterOfPosition(source, ce.pos)
            diagnostics.add(Diagnostic(
                message = "This expression is not constructable.",
                category = DiagnosticCategory.Error, code = 2351,
                fileName = fileName, line = line, character = character,
                start = ce.pos, length = expressionTrueEnd(ce) - ce.pos,
                messageChain = listOf("  Type '$typeName' has no construct signatures."),
            ))
            return
        }
        // intTypeCheck: `new {}` (no argument list) — an empty object literal has no
        // construct signatures. FP-safe: tsc ALWAYS errors on `new {}`. Squiggle = the
        // `{}` literal. Gated to arguments == null so the with-parens path (which flows
        // through the signatures.isEmpty() handling below) is untouched.
        if (expr.arguments == null && expr.expression is ObjectLiteralExpression &&
            (expr.expression).properties.isEmpty()) {
            val ol = expr.expression
            val close = source.indexOf('}', ol.pos)
            val length = if (close >= ol.pos) close + 1 - ol.pos else 2
            val (line, character) = getLineAndCharacterOfPosition(source, ol.pos)
            diagnostics.add(Diagnostic(
                message = "This expression is not constructable.",
                category = DiagnosticCategory.Error, code = 2351,
                fileName = fileName, line = line, character = character,
                start = ol.pos, length = length,
                messageChain = listOf("  Type '{}' has no construct signatures."),
            ))
            return
        }
        val calleeType = getCalleeType(expr.expression)
        if (calleeType === anyType || calleeType === errorType) return
        // intTypeCheck: `new <var>` (no argument list) where the var's annotated type is a
        // PURE user interface. tsc resolveNewExpression: construct sigs (own or inherited —
        // resolveStructuredTypeMembers merges base sigs) → constructable, nothing; else call
        // sigs whose resolved return isn't `void` → TS2350 "Only a void function can be
        // called with the 'new' keyword." at the whole `new x` (noImplicitAny OFF only —
        // under noImplicitAny tsc reports TS7009 instead); else → TS2351 at the CALLEE with
        // "Type 'X' has no construct signatures.". Gated to arguments == null (the
        // with-parens path is owned by the 17.170 branch below).
        if (expr.arguments == null && expr.expression is Identifier) {
            val ce = expr.expression
            val sym = currentFileLocals?.get(ce.text) ?: globals[ce.text]
            val isVarOnly = sym != null && sym.flags.hasAny(SymbolFlags.Variable) &&
                !sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Function or SymbolFlags.Module or SymbolFlags.Enum or SymbolFlags.Alias)
            val ti = calleeType as? Type.Interface
            if (isVarOnly && ti != null && ti.symbol != null &&
                ti.symbol!!.flags.hasAny(SymbolFlags.Interface) && !ti.symbol!!.flags.hasAny(SymbolFlags.Class) &&
                ti.symbol!!.declarations.none { it in builtinLibDecls }) {
                resolveStructuredTypeMembers(ti)
                val ctorSigs = ti.constructSignatures ?: emptyList()
                if (ctorSigs.isEmpty()) {
                    val callSigs = ti.callSignatures ?: emptyList()
                    if (callSigs.isNotEmpty()) {
                        if (!options.noImplicitAny && !options.strict) {
                            val resolved = callSigs.firstOrNull { it.minArgumentCount == 0 } ?: callSigs.first()
                            val ret = resolved.resolvedReturnType
                            if (ret !== voidType) {
                                val end = expressionTrueEnd(ce)
                                val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Only a void function can be called with the 'new' keyword.",
                                    category = DiagnosticCategory.Error, code = 2350,
                                    fileName = fileName, line = line, character = character,
                                    start = expr.pos, length = end - expr.pos,
                                ))
                                return
                            }
                        }
                    } else {
                        val typeName = ti.symbol?.name ?: typeToString(ti)
                        val (line, character) = getLineAndCharacterOfPosition(source, ce.pos)
                        diagnostics.add(Diagnostic(
                            message = "This expression is not constructable.",
                            category = DiagnosticCategory.Error, code = 2351,
                            fileName = fileName, line = line, character = character,
                            start = ce.pos, length = ce.text.length,
                            messageChain = listOf("  Type '$typeName' has no construct signatures."),
                        ))
                        return
                    }
                }
            }
        }
        // B60.15: union callee for `new` — mirror of B60.14 for TS2349 with three cases:
        //   (a) all constituents non-constructable → "No constituent ... is constructable."
        //   (b) some non-constructable → "Not all constituents ... are constructable." + first missing display
        //   (c) all constructable but sigs differ structurally → "Each member ... has construct signatures, but none ... compatible..."
        if (calleeType is Type.Union) {
            val constituents = calleeType.types
            val nonCtor = constituents.filter { getConstructSignaturesOfType(it).isEmpty() }
            val unionDisplay = typeToString(calleeType)
            val ce = expr.expression
            val (start, length) = run {
                val s = ce.pos
                Pair(s, expressionTrueEnd(ce) - s)
            }
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                if (nonCtor.isNotEmpty() && nonCtor.size == constituents.size) {
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error, code = 2351,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf("  No constituent of type '$unionDisplay' is constructable."),
                    ))
                    return
                }
                if (nonCtor.isNotEmpty() && nonCtor.size != constituents.size) {
                    val missingDisplay = typeToString(nonCtor[0])
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error, code = 2351,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                        messageChain = listOf(
                            "  Not all constituents of type '$unionDisplay' are constructable.",
                            "    Type '$missingDisplay' has no construct signatures.",
                        ),
                    ))
                    return
                }
                if (nonCtor.isEmpty() && constituents.size >= 2) {
                    // All constructable; check pairwise sig compat heuristic
                    val sigsList = constituents.map { getConstructSignaturesOfType(it).firstOrNull() }
                    val hasNullSig = sigsList.any { it == null }
                    if (!hasNullSig) {
                        val sigs = sigsList.map { it!! }
                        val differ = run {
                            for (i in sigs.indices) for (j in i + 1 until sigs.size) {
                                val s1 = sigs[i]; val s2 = sigs[j]
                                if ((s1.typeParameters?.size ?: 0) != (s2.typeParameters?.size ?: 0)) return@run true
                                if (s1.parameters.size != s2.parameters.size) return@run true
                                for (k in s1.parameters.indices) {
                                    val t1 = getTypeOfSymbol(s1.parameters[k])
                                    val t2 = getTypeOfSymbol(s2.parameters[k])
                                    if (t1 !== t2) return@run true
                                }
                            }
                            false
                        }
                        if (differ) {
                            diagnostics.add(Diagnostic(
                                message = "This expression is not constructable.",
                                category = DiagnosticCategory.Error, code = 2351,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                                messageChain = listOf(
                                    "  Each member of the union type '$unionDisplay' has construct signatures, but none of those signatures are compatible with each other.",
                                ),
                            ))
                            return
                        }
                    }
                }
            }
        }
        // B497: the args-required early return was moved BELOW the union-callee branch
        // (above) so a NO-ARGS union callee (`new union;`) is still constructability-checked.
        val args = expr.arguments ?: return
        // Get construct signatures
        val signatures = getConstructSignaturesOfType(calleeType)
        if (signatures.isEmpty()) {
            // 17.170: TS2351 — `new x()` where x is a plain instance variable (not
            // a class identifier). Class-instance Type.Interface has no construct
            // signatures (those live on the static side). Squiggle on the callee.
            // Conservative gate: only fire when the callee is a bare Identifier
            // resolving to a Variable symbol whose type is a Type.Interface with a
            // class symbol — definitively a "new on instance" case.
            val ce = expr.expression
            if (ce is Identifier) {
                val sym = globals[ce.text]
                val isVarOrParam = sym != null && sym.flags.hasAny(SymbolFlags.Variable) &&
                    !sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Function)
                if (isVarOrParam && calleeType is Type.Interface) {
                    val typeName = calleeType.symbol?.name ?: typeToString(calleeType)
                    val (line, character) = getLineAndCharacterOfPosition(source, ce.pos)
                    diagnostics.add(Diagnostic(
                        message = "This expression is not constructable.",
                        category = DiagnosticCategory.Error,
                        code = 2351,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = ce.pos,
                        length = ce.text.length,
                        messageChain = listOf("  Type '$typeName' has no construct signatures."),
                    ))
                }
            }
            // staticMemberExportAccess: `new $.sammy()` — a chained PropertyAccess callee
            // resolving to a class-INSTANCE Type.Interface (no construct signatures). LANDMINE:
            // `new ns.ClassA()` is VALID but our checker resolves a namespace-member class's
            // value position to its INSTANCE type (no construct sigs) — so bail when the accessed
            // property itself resolves to a CLASS symbol (the constructable static side).
            if (ce is PropertyAccessExpression && calleeType is Type.Interface &&
                !propertyAccessChainIsNamespaceQualified(ce)) {
                val tsym = calleeType.symbol
                if (tsym != null && tsym.flags.hasAny(SymbolFlags.Class)) {
                    val accessedSym = resolvePropertyAccessToSymbol(ce)
                    if (accessedSym == null || !accessedSym.flags.hasAny(SymbolFlags.Class)) {
                        val typeName = tsym.name
                        val start = ce.pos
                        val length = expressionTrueEnd(ce) - start
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "This expression is not constructable.",
                                category = DiagnosticCategory.Error, code = 2351,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                                messageChain = listOf("  Type '$typeName' has no construct signatures."),
                            ))
                        }
                    }
                }
            }
            return
        }
        // 17.21: When the class has its own TypeParameters (e.g. `class List<T>`)
        // AND the call site has explicit type arguments (e.g. `new List<T>(...)`),
        // build a fresh signature with each param's type re-resolved under the
        // class TypeParam scope. The original sig's params may have been cached
        // as `errorType` from an earlier eager-pass resolution that ran with no
        // scope — re-resolving here lets the 17.20 null-vs-unconstrained-TypeParam
        // path fire on the bare `T` parameter. We mint fresh Symbols + cache
        // entries so the original cache isn't disturbed (which would break
        // `instantiateSignature`-produced sigs in `handleSuperMethodCall`).
        //
        // The explicit-type-args gate is critical: without it, `new D(null)`
        // where `class D<T> { constructor(x: T) }` would FP-emit TS2345 because
        // we don't perform generic argument inference (TypeScript would infer
        // T = null and silently accept). With explicit type args, TypeScript
        // bypasses inference so a bare `<T>` (unconstrained) → null arg fires.
        //
        // Also skip when any explicit type arg resolves to errorType — that
        // means the call site can't actually access the type (e.g. inside a
        // static method, a class-level T is out of scope and TypeScript already
        // emits TS2302; emitting TS2345 too would double-fault).
        val classTypeParams = (calleeType as? Type.Interface)?.typeParameters
        val hasExplicitTypeArgs = !expr.typeArguments.isNullOrEmpty()
        val resolvedTypeArgs: List<Type>? = if (hasExplicitTypeArgs) {
            expr.typeArguments.map { tn ->
                getTypeFromTypeNode(tn)
            }
        } else null
        val explicitArgsAllResolve = resolvedTypeArgs != null && resolvedTypeArgs.none { it === errorType }
        val effectiveSigs: List<Signature> = if (!classTypeParams.isNullOrEmpty() && explicitArgsAllResolve) {
            val reresolved = signatures.map { sig -> reresolveSigParamsUnderClassScope(sig, classTypeParams) }
            // B74.5: After re-resolving params under class scope, substitute the class
            // TypeParams with the explicit type arguments. Without this, a static method
            // `MakeHead3<U>()` calling `new List<U>(...)` displays the param type as the
            // class's `T` (the un-substituted classT) instead of the supplied `U`. The
            // class TPs and explicit type args have matching arity (guaranteed by the
            // type-arg parser/resolver; if mismatched, we'd have emitted TS2558 earlier).
            if (classTypeParams.size == resolvedTypeArgs.size) {
                val mapper = createTypeMapper(classTypeParams, resolvedTypeArgs)
                reresolved.map { sig -> instantiateSignature(sig, mapper) }
            } else reresolved
        } else signatures
        if (effectiveSigs.size == 1) {
            checkArgumentsAgainstSignature(args, effectiveSigs[0], source, fileName)
        } else {
            checkArgumentsAgainstOverloads(args, effectiveSigs, source, fileName, expr.expression)
        }
    }

    /**
     * 17.21: Build a fresh [Signature] with each parameter's type re-resolved
     * under [classTypeParams] in scope. Mints new parameter Symbols and stores
     * their types in [symbolTypes] so [getTypeOfSymbol] returns the re-resolved
     * type without re-running the AST resolution path. Preserves the original
     * symbols' cache entries (used by `instantiateSignature` in [handleSuperMethodCall]).
     */
    private fun reresolveSigParamsUnderClassScope(
        sig: Signature,
        classTypeParams: List<Type.TypeParam>,
    ): Signature {
        val newScope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
        for (tp in classTypeParams) tp.symbol?.name?.let { newScope[it] = tp }
        return withInstantiationContext(scopeMapper(newScope)) {
            var changed = false
            val freshParams = sig.parameters.map { p ->
                val decl = p.valueDeclaration as? Parameter
                val typeNode = decl?.type
                if (typeNode == null) return@map p
                val freshType = getTypeFromTypeNode(typeNode)
                if (freshType === errorType) return@map p
                val cached = symbolTypes[p.id]
                if (cached === freshType) return@map p
                changed = true
                val freshSym = Symbol(p.flags, p.name)
                freshSym.declarations.addAll(p.declarations)
                freshSym.valueDeclaration = p.valueDeclaration
                freshSym.parent = p.parent
                symbolTypes[freshSym.id] = freshType
                freshSym
            }
            if (!changed) sig else Signature(
                declaration = sig.declaration,
                typeParameters = sig.typeParameters,
                parameters = freshParams,
                resolvedReturnType = sig.resolvedReturnType,
                minArgumentCount = sig.minArgumentCount,
            )
        }
    }

    /**
     * Try each overload signature in order. If any overload accepts all arguments, no error.
     * If none succeed, report TS2345 against the last overload (TypeScript convention).
     *
     * 17.15b: [callee] is the call/new expression's callee. When provided AND the failing
     * arg is a fn-type-vs-fn-type mismatch (TypeScript treats this as a "more fundamental"
     * error pointing at the callee), TS2769 is squiggled at the callee position
     * (e.g. `x3` for `x3(...)`) instead of the failing argument.
     */
    private fun checkArgumentsAgainstOverloads(
        args: List<Expression>,
        signatures: List<Signature>,
        source: String,
        fileName: String,
        callee: Expression? = null,
    ) {
        // Filter overloads by arity — if only one matches by arity,
        // check it as a single signature (TS2345, not TS2769).
        val arityMatches = signatures.filter { sig ->
            val params = sig.parameters
            val hasRest = params.isNotEmpty() && params.last().declarations.any {
                it is Parameter && it.dotDotDotToken
            }
            args.size >= sig.minArgumentCount && (args.size <= params.size || hasRest)
        }
        if (arityMatches.size == 1) {
            // Check TS2793: only add implementation related info if the implementation
            // would have actually matched the arguments (e.g. impl has `any` param type).
            var implRelated: Diagnostic? = null
            val implRelatedCandidate = getOverloadImplementationRelated(arityMatches[0], source, fileName)
            if (implRelatedCandidate != null) {
                val implSig = getImplementationSignature(arityMatches[0], source, fileName)
                if (implSig != null && allArgumentsMatch(args, implSig, bivariantFnParams = true)) {
                    implRelated = implRelatedCandidate
                }
            }
            checkArgumentsAgainstSignature(args, arityMatches[0], source, fileName, implRelated)
            return
        }
        for (sig in signatures) {
            if (allArgumentsMatch(args, sig, applyWeakRule = true)) return // found a matching overload
        }
        // None matched — emit TS2769 with errors from each overload
        // Collect the first argument mismatch per overload for the error chain
        val overloadErrors = mutableListOf<Triple<Int, Signature, String>>() // (overloadIndex, sig, errorMsg)
        for ((idx, sig) in signatures.withIndex()) {
            val errorMsg = getFirstArgumentError(args, sig)
            if (errorMsg != null) {
                overloadErrors.add(Triple(idx + 1, sig, errorMsg))
            }
        }
        if (overloadErrors.isNotEmpty()) {
            // B418: tsc's "best matching overload" collapse. When ≥1 overload fails
            // on MULTIPLE array-literal elements, tsc reports ONLY the overload with
            // the FEWEST per-element diagnostics (the single best candidate) and
            // anchors at its failing element — `max>1 ? allDiagnostics[minIndex] :
            // flatten` in chooseOverload. Otherwise (all overloads ≤1 diag) it
            // flattens and reports every overload (existing behavior). FP-safe: the
            // collapse triggers only on an array-literal arg failing ≥2 elements.
            val perOverloadFailCount = overloadErrors.map { (_, sig, _) -> countFailingArgDiagnostics(args, sig) }
            val reported: List<Triple<Int, Signature, String>> =
                if (overloadErrors.size > 1 && perOverloadFailCount.any { it > 1 }) {
                    val minIdx = perOverloadFailCount.indices.minByOrNull { perOverloadFailCount[it] }!!
                    listOf(overloadErrors[minIdx])
                } else overloadErrors
            // 17.15b: When ANY overload's first failing arg is a fn-type-vs-fn-type
            // mismatch and we have a callee, point the squiggle at the callee instead
            // of the failing argument — TypeScript treats fn-vs-fn arg mismatch as a
            // more fundamental error and squiggles the callee identifier.
            // 17.77: Refinement — only switch to callee when overloads fail at
            // DIFFERENT argument positions (e.g. overload 1 fails on arg[1]:fn,
            // overload 2 fails on arg[0]:primitive). When ALL overloads fail at
            // the SAME arg position (e.g. both fail on the arrow-fn arg),
            // TypeScript squiggles the argument, not the callee. Cf.
            // signatureLengthMismatchInOverload_ts where two overloads both fail
            // at arg[0] (arity vs param-type) — expected squiggle is the arg.
            val anyFnFnMismatch = callee != null && reported.any { (_, sig, _) ->
                getFirstFailingFnTypeArgPair(args, sig) != null
            }
            // B50.11: ANY overload that fails on a NON-function-vs-function shape
            // (e.g. function arg vs string param) suggests heterogeneous overload
            // shapes — TypeScript prefers callee squiggle in that case. Mirrors
            // `overloadsWithProvisionalErrors_ts` baseline.
            val hasNonFnFnFailing = callee != null && reported.any { (_, sig, _) ->
                getFirstFailingFnTypeArgPair(args, sig) == null
            }
            // Collect first-failing-arg position per overload. If all overloads
            // share the same failing position, use that — otherwise fall back to
            // callee for fn-vs-fn cases.
            val perOverloadPos = reported.map { (_, sig, _) ->
                getFirstFailingArgPosition(args, sig)
            }
            val allSamePos = perOverloadPos.isNotEmpty() && perOverloadPos.all { it == perOverloadPos.first() }
            val pos: Pair<Int, Int>? = if (reported.size == 1 && reported !== overloadErrors) {
                // B418 collapse: anchor at the best overload's failing (element) position.
                getFirstFailingArgPosition(args, reported[0].second)
            } else if (anyFnFnMismatch && (!allSamePos || hasNonFnFnFailing)) {
                Pair(callee.pos, expressionTrueEnd(callee) - callee.pos)
            } else if (callee is PropertyAccessExpression && !allSamePos) {
                // B280: a METHOD call whose overloads fail at DIFFERENT arg positions
                // anchors TS2769 at the method name (tsc's call-node error span),
                // e.g. `x.h(2,2)` vs `(s1: string, s2: number)`/`(s1: number, s2: string)`.
                Pair(callee.name.pos, callee.name.text.length)
            } else {
                getFirstFailingArgPosition(args, signatures.last())
            }
            if (pos != null) {
                val (argStart, argLength) = pos
                val (line, character) = getLineAndCharacterOfPosition(source, argStart)
                val chain = mutableListOf<String>()
                val totalOverloads = signatures.size
                for ((overloadIdx, sig, errorMsg) in reported) {
                    // 17.85: Use signatureToStringColon (which handles optional
                    // params via formatParameter — `?:` + `| undefined` widening)
                    // for TS2769 overload chain display, instead of the simpler
                    // 1-arg signatureToString which omitted both. Cf.
                    // namespaceMergedWithFunctionWithOverloadsUsage_ts where
                    // `(opts?: Foo.Whatever)` should display as
                    // `'(opts?: Whatever | undefined): void'`.
                    val sigStr = signatureToStringColon(sig, isConstruct = false)
                    chain.add("  Overload $overloadIdx of $totalOverloads, '$sigStr', gave the following error.")
                    chain.add("    $errorMsg")
                    // B122: union-arg vs primitive-param → append the failing-member sub-line.
                    val unionSub = getUnionMemberFailureSubline(args, sig)
                    if (unionSub != null) chain.add("      $unionSub")
                    // 17.15b: Add deeper "Types of parameters X and Y are incompatible." chain
                    // when the failing arg is a function type vs function-type param.
                    val firstFailingPair = getFirstFailingFnTypeArgPair(args, sig)
                    if (firstFailingPair != null) {
                        val (argFnType, paramFnType) = firstFailingPair
                        val nested = getFunctionMismatchElaboration(argFnType, paramFnType)
                        chain.addAll(nested.map { "    $it" })
                    } else if (unionSub == null && errorMsg.startsWith("Argument of type '")) {
                        // B560: drill into an object/class-instance arg-vs-param property
                        // mismatch — tsc continues "Argument of type 'C1' is not assignable
                        // to parameter of type 'IFoo1'." with "The types returned by 'p1()'
                        // are incompatible between these types. Type 'string' is not
                        // assignable to type 'number'." (incompatibleTypes `if1(c1)`). The
                        // existing path only drilled function-type args; a class-instance arg
                        // (no call sig) stopped at the bare "Argument of type" line. Reuse
                        // getPropertyElaborationChain (which already produces the "types
                        // returned by"/property-mismatch drill), shifted 4 spaces deeper
                        // (its lines start at 2/4 → overload chain wants 6/8). Gated to the
                        // plain "Argument of type" errorMsg so object-literal property errors
                        // (their own elaboration) and union sub-lines are left untouched.
                        val pair = getFirstFailingArgObjectTypes(args, sig)
                        val at = pair?.first; val pt = pair?.second
                        if (at is Type.Object && pt is Type.Object) {
                            getPropertyElaborationChain(at, pt)?.let { drill ->
                                chain.addAll(drill.map { "    $it" })
                            }
                        }
                    }
                }
                // Collect related info: TS6500/TS2728 for property source, TS2793 for implementation
                val related = mutableListOf<Diagnostic>()
                for ((_, sig, errorMsg) in reported) {
                    if (errorMsg.startsWith("Object literal may only specify known properties")) {
                        // Excess-property errors get no TS2728/TS6500 related info.
                        continue
                    }
                    if (errorMsg.startsWith("Property '") && errorMsg.contains("is missing")) {
                        // TS2728: "'X' is declared here." for missing property errors
                        val ts2728 = getMissingPropertyDeclaredHere(args, sig, source, fileName)
                        if (ts2728 != null) related.add(ts2728)
                    } else {
                        // TS6500: "The expected type comes from property 'X' which is declared here on type 'Y'"
                        val ts6500 = getPropertySourceRelated(args, sig, source, fileName)
                        if (ts6500 != null) related.add(ts6500)
                    }
                }
                // TS2793: only if implementation would have matched the arguments
                val implRelated = getOverloadImplementationRelated(signatures[0], source, fileName)
                if (implRelated != null) {
                    // Check if implementation actually accepts these args
                    val implSig = getImplementationSignature(signatures[0], source, fileName)
                    if (implSig != null && allArgumentsMatch(args, implSig, bivariantFnParams = true)) {
                        related.add(implRelated)
                    }
                }
                diagnostics.add(Diagnostic(
                    message = "No overload matches this call.",
                    category = DiagnosticCategory.Error,
                    code = 2769,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = argStart,
                    length = argLength,
                    messageChain = chain,
                    relatedInformation = related,
                ))
                return
            }
        }
        // Fallback: no position found despite errors — try fallback TS2345
        val lastSig = signatures.last()
        checkArgumentsAgainstSignature(args, lastSig, source, fileName)
    }

    /**
     * 17.15b: For overload error chain elaboration. When the first failing arg is a
     * function-type vs function-type-param, return the (argType, paramType) pair so the
     * caller can append the deeper "Types of parameters X and Y are incompatible." chain
     * via [getFunctionMismatchElaboration]. Returns null when the first failing arg is
     * not a fn-vs-fn mismatch (or none fails).
     */
    private fun getFirstFailingFnTypeArgPair(args: List<Expression>, sig: Signature): Pair<Type.Object, Type.Object>? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // Both anonymous Type.Object with non-empty callSignatures = fn-type vs fn-type.
                if (argType is Type.Object && argType !is Type.Reference && argType !is Type.Interface &&
                    argType.symbol == null && !argType.callSignatures.isNullOrEmpty() &&
                    paramType is Type.Object && paramType !is Type.Reference && paramType !is Type.Interface &&
                    paramType.symbol == null && !paramType.callSignatures.isNullOrEmpty()
                ) {
                    return Pair(argType, paramType)
                }
                return null
            }
        }
        return null
    }

    /**
     * B560: the (argType, paramType) of the first failing argument for [sig] — the
     * type pair behind [getFirstArgumentError]'s "Argument of type 'X' is not
     * assignable to parameter of type 'Y'." line, used to drill a deeper property /
     * method-return elaboration into the TS2769 overload chain. Mirrors the gating of
     * `getFirstArgumentError`/`getFirstFailingArgPosition` (skip spread / any / error).
     */
    private fun getFirstFailingArgObjectTypes(args: List<Expression>, sig: Signature): Pair<Type, Type>? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = restAwareParamType(params, i) ?: continue
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                return argType to paramType
            }
        }
        return null
    }

    /** Get the first argument type error message for a signature, or null if all match. */
    /** Round 436e: shared overload-helper per-arg skips, mirroring the single-sig
     *  path's rules — (a) a UNION arg whose only failing member is `undefined` is
     *  legal for an OPTIONAL param (unionArgOkForOptionalParam; tsc program.ts's
     *  `(Program | T).getOptionsDiagnostics(cancellationToken)` where the arg is
     *  `CancellationToken | undefined` vs `cancellationToken?:` — the union-receiver
     *  synthesized overload pair failed BOTH ways, ×6); (b) an arg carrying an
     *  un-inferred TP (a generic call result leaked into an overload arg —
     *  `visitNode(…)` → `TOut | TIn & undefined`) is unjudgeable. Suppression-only:
     *  over-matching can only select an overload instead of reporting TS2769. */
    private fun overloadArgSkippable(argType: Type, paramSym: Symbol, paramType: Type): Boolean =
        unionArgOkForOptionalParam(argType, paramSym, paramType) ||
            typeContainsForeignTypeParam(argType, emptySet())

    private fun getFirstArgumentError(args: List<Expression>, sig: Signature): String? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = restAwareParamType(params, i) ?: continue
            if (paramType === anyType || paramType === errorType) continue
            val argType = overloadNarrowedArgType(arg, if (propTypeContainsLiteral(paramType))
                (literalTypeOfExpression(arg) ?: getTypeOfExpression(arg)) else getTypeOfExpression(arg))
            if (argType === anyType || argType === errorType) continue
            if (overloadArgSkippable(argType, params[i], paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // For object literal args, try to find the specific mismatched property
                val propError = getObjectLiteralPropertyError(arg, argType, paramType)
                if (propError != null) return propError
                // overloadingOnConstants2: keep the literal display against a literal param
                // (tsc shows `Argument of type '"um"'`, not the widened `'string'`).
                val displayArgType = if (propTypeContainsLiteral(paramType)) argType else getWidenedLiteralType(argType)
                return "Argument of type '${typeToString(displayArgType)}' is not assignable to parameter of type '${typeToString(paramType)}'."
            }
            // (CHK.56) THE WEAK-TYPE SUBLINE. The relation ACCEPTED this argument, so
            // the walk above found no failing argument at all and this overload used to
            // drop out of the chain entirely — which is why a call whose every overload
            // has a disjoint weak parameter was SILENT. tsc's subline here is TS2559's
            // *no properties in common* wording, not an assignability line, and it keeps
            // the argument's LITERAL type (`Type '123' has …`) where the ordinary line
            // widens it. [weakRefusalDisplayTarget] decides which of the two sentences.
            if (weakOverloadArgRefuses(arg, argType, paramType)) {
                val named = weakRefusalDisplayTarget(paramType)
                return if (named != null)
                    "Type '${typeToString(literalTypeOfExpression(arg) ?: argType)}' has no properties in common with type '${typeToString(named)}'."
                else
                    "Argument of type '${typeToString(getWidenedLiteralType(argType))}' is not assignable to parameter of type '${typeToString(paramType)}'."
            }
        }
        return null
    }

    /**
     * B418: Count the element/argument mismatches an overload produces — used to
     * pick tsc's "best matching" overload when ALL overloads fail. tsc's
     * `chooseOverload` reports ONLY the overload with the FEWEST per-element
     * diagnostics when some overload has ≥2 (`max>1 ? allDiagnostics[minIndex] :
     * flatten`). For an array-literal arg vs `Array<E>` param, counts elements not
     * assignable to E (mirrors tsc's element-wise elaboration, one diagnostic per
     * failing element); every other failing arg counts as 1. First-mismatch
     * semantics on scalar args, like [getFirstArgumentError].
     */
    private fun countFailingArgDiagnostics(args: List<Expression>, sig: Signature): Int {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = restAwareParamType(params, i) ?: continue
            if (paramType === anyType || paramType === errorType) continue
            val argType = overloadNarrowedArgType(arg, if (propTypeContainsLiteral(paramType))
                (literalTypeOfExpression(arg) ?: getTypeOfExpression(arg)) else getTypeOfExpression(arg))
            if (argType === anyType || argType === errorType) continue
            if (overloadArgSkippable(argType, params[i], paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                if (arg is ArrayLiteralExpression && paramType is Type.Reference &&
                    paramType.target.symbol?.name == "Array") {
                    val elemT = paramType.resolvedTypeArguments?.firstOrNull()
                    if (elemT != null && elemT !== anyType && elemT !== errorType) {
                        var c = 0
                        for (elem in arg.elements) {
                            if (elem is SpreadElement) continue
                            val et = getTypeOfExpression(elem)
                            if (et === anyType || et === errorType) continue
                            if (!checkTypeRelatedTo(et, elemT, assignableRelation)) c++
                        }
                        if (c > 0) return c
                    }
                }
                return 1
            }
            // (CHK.56) The five overload arg-check helpers must agree with the MATCH
            // verdict or the chain names an overload the match loop thought fine.
            if (weakOverloadArgRefuses(arg, argType, paramType)) return 1
        }
        return 0
    }

    /**
     * B122: TS2769 overload-chain nested sub-line. When the first failing argument is a
     * UNION and the parameter is a PRIMITIVE intrinsic, TypeScript appends a third-level
     * line naming the specific union member that fails, e.g.
     * `Type 'undefined' is not assignable to type 'boolean'.` Among failing members TS
     * reports the NULLISH one first (undefined, then null), else the first failing member
     * — matching the `[4,2,undefined][0]` / `[null,2,4][0]` chains in `arrayBestCommonTypes`.
     * Gated to union-arg-vs-primitive-param so it never fires for object/union targets
     * (which have their own elaboration). Returns null when the first failing arg isn't
     * this shape.
     */
    private fun getUnionMemberFailureSubline(args: List<Expression>, sig: Signature): String? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = restAwareParamType(params, i) ?: continue
            if (paramType === anyType || paramType === errorType) continue
            val argType = overloadNarrowedArgType(arg, getTypeOfExpression(arg))
            if (argType === anyType || argType === errorType) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                if (argType is Type.Union && paramType is Type.Intrinsic) {
                    val failing = argType.types.filter {
                        !checkTypeRelatedTo(it, paramType, assignableRelation)
                    }
                    val chosen = failing.firstOrNull { it.flags.hasAny(TypeFlags.Undefined) }
                        ?: failing.firstOrNull { it.flags.hasAny(TypeFlags.Null) }
                        ?: failing.firstOrNull()
                    if (chosen != null) {
                        return "Type '${typeToString(chosen)}' is not assignable to type '${typeToString(paramType)}'."
                    }
                }
                return null
            }
        }
        return null
    }

    /**
     * For an object literal argument that doesn't match a target object type,
     * find the specific property that mismatches and return an elaborated error.
     * e.g., "Type 'string' is not assignable to type 'number'."
     */
    private fun getObjectLiteralPropertyError(
        arg: Expression,
        argType: Type,
        paramType: Type,
    ): String? {
        if (arg !is ObjectLiteralExpression && arg !is ArrayLiteralExpression) return null
        // For array literal → array type: dig into element comparison
        if (arg is ArrayLiteralExpression && paramType is Type.Reference &&
            paramType.target.symbol?.name == "Array") {
            val targetElemType = paramType.resolvedTypeArguments?.firstOrNull() ?: return null
            for (elem in arg.elements) {
                if (elem is SpreadElement) continue
                val elemType = getTypeOfExpression(elem)
                if (elemType === anyType || elemType === errorType) continue
                if (!checkTypeRelatedTo(elemType, targetElemType, assignableRelation)) {
                    // Recurse: check if the element is an object literal with property mismatch
                    val inner = getObjectLiteralPropertyError(elem, elemType, targetElemType)
                    if (inner != null) return inner
                    val displayArgType = getWidenedLiteralType(elemType)
                    return "Type '${typeToString(displayArgType)}' is not assignable to type '${typeToString(targetElemType)}'."
                }
            }
            return null
        }
        // For object literal → object type: find first mismatched property
        if (arg is ObjectLiteralExpression && paramType is Type.Object) {
            resolveStructuredTypeMembers(paramType)
            val targetProps = paramType.properties ?: return null
            if (argType !is Type.Object) return null
            // Excess-property check first: object literals against object types without an
            // index signature get the stricter "Object literal may only specify known properties"
            // message at the first excess property (matching tsc).
            if (paramType.stringIndexInfo == null && paramType.numberIndexInfo == null) {
                val targetNames = targetProps.map { it.name }.toSet()
                for (prop in arg.properties) {
                    val name = when (val n = (prop as? PropertyAssignment)?.name
                        ?: (prop as? ShorthandPropertyAssignment)?.name
                        ?: (prop as? MethodDeclaration)?.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> continue
                    }
                    if (name !in targetNames) {
                        return "Object literal may only specify known properties, and '$name' does not exist in type '${typeToString(paramType)}'."
                    }
                }
            }
            for (targetProp in targetProps) {
                val isOptional = isOptionalProperty(targetProp)
                val sourceProp = argType.members?.get(targetProp.name)
                if (sourceProp == null) {
                    if (!isOptional) {
                        return "Property '${targetProp.name}' is missing in type '${typeToString(argType)}' but required in type '${typeToString(paramType)}'."
                    }
                    continue
                }
                val sourcePropType = getTypeOfSymbol(sourceProp)
                val targetPropType = getTypeOfSymbol(targetProp)
                if (!checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) {
                    val displaySource = getWidenedLiteralType(sourcePropType)
                    return "Type '${typeToString(displaySource)}' is not assignable to type '${typeToString(targetPropType)}'."
                }
            }
        }
        return null
    }

    /**
     * Widen literal types to their base types for error message display.
     * TypeScript displays `true` as `boolean`, string literals as `string`, etc.
     */
    private fun getWidenedLiteralType(type: Type): Type {
        val f = type.flags
        if (f.hasAny(TypeFlags.BooleanLiteral)) return booleanType
        if (type is Type.StringLiteral) return stringType
        if (type is Type.NumberLiteral) return numberType
        if (type is Type.BigIntLiteral) return bigintType
        return type
    }

    /**
     * B70.1ext: For chain-display rendering: when `literalCandidate` is a literal type
     * AND `otherSide` is a non-matching primitive (different base), return the widened
     * form of `literalCandidate` so the chain message reads `'string' is not assignable
     * to 'number'` instead of `'"hi"' is not assignable to 'number'`. When bases match
     * (e.g. `'hi'` vs `string`, or `'hi'` vs `'bye'`), return the literal unchanged.
     */
    private fun widenLiteralForDifferentBaseDisplay(literalCandidate: Type, otherSide: Type): Type {
        val widened = getWidenedLiteralType(literalCandidate)
        if (widened === literalCandidate) return literalCandidate
        // widened is a primitive base (string/number/boolean/bigint). Only widen for
        // display when otherSide is a DIFFERENT primitive base (no shared base).
        val otherBase = getWidenedLiteralType(otherSide)
        if (otherBase === widened) return literalCandidate  // same base, keep literal
        // Different base — only widen if otherSide is a recognizable primitive,
        // not an object/union/intersection.
        val isOtherPrimitive = otherSide.flags.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or TypeFlags.BigInt
        ) && otherSide !is Type.StringLiteral && otherSide !is Type.NumberLiteral &&
            otherSide !is Type.BigIntLiteral && !otherSide.flags.hasAny(TypeFlags.BooleanLiteral)
        return if (isOtherPrimitive) widened else literalCandidate
    }

    /**
     * Get the position and length of the first failing argument for a signature.
     * For object literal/array literal arguments, dig into elements to find the
     * specific mismatched value (TypeScript squiggles the inner value, not the whole arg).
     */
    private fun getFirstFailingArgPosition(args: List<Expression>, sig: Signature): Pair<Int, Int>? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = restAwareParamType(params, i) ?: continue
            if (paramType === anyType || paramType === errorType) continue
            val argType = overloadNarrowedArgType(arg, getTypeOfExpression(arg))
            if (argType === anyType || argType === errorType) continue
            if (overloadArgSkippable(argType, params[i], paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // For object/array literals, find the inner mismatched expression
                val inner = findInnerMismatchPosition(arg, paramType)
                if (inner != null) return inner
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) return Pair(start, length)
            }
            // (CHK.56) A weak-rule refusal anchors at the ARGUMENT, like every other
            // failing argument — measured on tsc 7.0.2, which puts the squiggle on the
            // argument and not on the callee for this family.
            if (weakOverloadArgRefuses(arg, argType, paramType)) {
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) return Pair(start, length)
            }
        }
        return null
    }

    /**
     * For an array/object literal arg, find the position of the specific inner
     * expression that causes the type mismatch. Returns (start, length) or null.
     */
    private fun findInnerMismatchPosition(arg: Expression, paramType: Type): Pair<Int, Int>? {
        // Array literal → array type: find the mismatched element
        if (arg is ArrayLiteralExpression && paramType is Type.Reference &&
            paramType.target.symbol?.name == "Array") {
            val targetElemType = paramType.resolvedTypeArguments?.firstOrNull() ?: return null
            for (elem in arg.elements) {
                if (elem is SpreadElement) continue
                val elemType = getTypeOfExpression(elem)
                if (elemType === anyType || elemType === errorType) continue
                if (!checkTypeRelatedTo(elemType, targetElemType, assignableRelation)) {
                    // Recurse into the element (might be an object literal)
                    val inner = findInnerMismatchPosition(elem, targetElemType)
                    if (inner != null) return inner
                    val start = elem.pos
                    val length = expressionTrueEnd(elem) - start
                    if (length > 0) return Pair(start, length)
                }
            }
        }
        // Object literal → object type: find the mismatched property value
        if (arg is ObjectLiteralExpression && paramType is Type.Object) {
            resolveStructuredTypeMembers(paramType)
            val targetProps = paramType.properties ?: return null
            val argType = getTypeOfExpression(arg)
            if (argType !is Type.Object) return null
            // Excess-property: squiggle the FIRST excess property name (matching tsc).
            if (paramType.stringIndexInfo == null && paramType.numberIndexInfo == null) {
                val targetNames = targetProps.map { it.name }.toSet()
                for (prop in arg.properties) {
                    val nameNode = when (prop) {
                        is PropertyAssignment -> prop.name
                        is ShorthandPropertyAssignment -> prop.name
                        is MethodDeclaration -> prop.name
                        else -> continue
                    }
                    val name = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        else -> continue
                    }
                    if (name !in targetNames) {
                        return Pair(nameNode.pos, name.length)
                    }
                }
            }
            for (targetProp in targetProps) {
                val sourceProp = argType.members?.get(targetProp.name)
                if (sourceProp == null) {
                    // Missing property — squiggle the whole object literal
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) return Pair(start, length)
                    continue
                }
                val sourcePropType = getTypeOfSymbol(sourceProp)
                val targetPropType = getTypeOfSymbol(targetProp)
                if (!checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) {
                    // Find the PropertyAssignment and squiggle the property NAME
                    for (prop in arg.properties) {
                        if (prop !is PropertyAssignment) continue
                        val propNameNode = prop.name
                        val propName = when (propNameNode) {
                            is Identifier -> propNameNode.text
                            is StringLiteralNode -> propNameNode.text
                            else -> continue
                        }
                        if (propName == targetProp.name) {
                            val start = propNameNode.pos
                            val length = propName.length
                            if (length > 0) return Pair(start, length)
                        }
                    }
                }
            }
        }
        return null
    }

    /** Format a signature for display in TS2769 messages: (param: type, ...): returnType */
    private fun signatureToString(sig: Signature): String {
        val params = sig.parameters.joinToString(", ") { param ->
            val paramType = getTypeOfSymbol(param)
            val typeStr = if (paramType === anyType) "any" else typeToString(paramType)
            // B9.5: source-slice rendering for binding-pattern synthesized params.
            val displayName = when (val name = (param.valueDeclaration as? Parameter)?.name) {
                is ObjectBindingPattern, is ArrayBindingPattern -> formatBindingPatternFromAst(name as Node)
                else -> param.name
            }
            "$displayName: $typeStr"
        }
        val returnType = sig.resolvedReturnType
        val returnStr = if (returnType != null && returnType !== anyType) typeToString(returnType) else "any"
        return "($params): $returnStr"
    }

    /**
     * Check if all arguments match a signature (no TS2345 errors would fire).
     * Returns true if all args are assignable to their corresponding param types.
     * For overload resolution, we check ALL types (not just simple checkable ones)
     * because we need to determine if any overload matches.
     *
     * B70.15: [bivariantFnParams] enables bivariant comparison for function-typed
     * arg/param pairs — used by TS2793 "would the impl have succeeded" gates under
     * `@strict: false`. TypeScript treats method parameter checking bivariantly when
     * `strictFunctionTypes` is off, so e.g. `(x: 'bye') => number` is accepted by
     * impl param `(x: string) => number`. Only enabled when [bivariantFnParams] is
     * true AND `strictExplicitlyFalse` is set — otherwise contravariant-only check.
     * Strict-mode overload resolution (the `allArgumentsMatch(args, sig)` matching
     * call in `checkArgumentsAgainstOverloads`) keeps the default (contravariant)
     * to avoid mis-matching overloads.
     */
    /**
     * Rest-aware effective parameter type for the argument at index [i] of [params].
     * For an index landing on (or past, when the last param is rest) a REST parameter
     * `...args: E[]`, returns the ELEMENT type `E` — args bind to the element, not the
     * array wrapper. The overload arg-check helpers (allArgumentsMatch /
     * getFirstArgumentError / getFirstFailingArgPosition / countFailingArgDiagnostics /
     * getUnionMemberFailureSubline) must use this, mirroring the main
     * checkArgumentsAgainstSignature `isRestParam` handling — otherwise a call like
     * `f("yo")` against an overload `(...args: any[])` FP-fails ("string not assignable
     * to any[]"). Non-rest params return their declared type unchanged.
     */
    private fun restAwareParamType(params: List<Symbol>, i: Int): Type? {
        if (params.isEmpty()) return null
        val direct = if (i < params.size) params[i] else null
        // Determine the governing param: the i-th, or — when i is past the param list —
        // the last param IF it is rest (extra args bind to the trailing rest).
        val governing = direct ?: params.last().takeIf { _ ->
            params.last().declarations.any { it is Parameter && it.dotDotDotToken }
        }
        if (governing == null) return null
        val isRest = governing.declarations.any { it is Parameter && it.dotDotDotToken }
        val t = getTypeOfSymbol(governing)
        if (isRest && t is Type.Reference && t.target.symbol?.name == "Array") {
            return t.resolvedTypeArguments?.firstOrNull() ?: t
        }
        return t
    }

    /**
     * Round 422 (M3.4): flow-narrow a reference argument for the overload arg-check helpers.
     * Mirrors B469's single-signature rule (checkArgumentsAgainstSignature): a bare
     * Identifier/PropertyAccess argument whose declared type is a Union is refined via the
     * flow graph — `containingFile ? getDirectoryPath(containingFile) : undefined`,
     * `if (typeof version === "string") version = new Version(version)` — so an overload
     * the NARROWED type matches is not spuriously rejected. Narrowing only REMOVES union
     * members, so matching can only get MORE permissive (TS2769 suppression-only); an
     * un-narrowed union arg still fails every overload and TS2769 stands. All five overload
     * arg-check helpers (allArgumentsMatch / getFirstArgumentError / countFailingArgDiagnostics /
     * getFirstFailingArgPosition / getUnionMemberFailureSubline) must route through this —
     * a helper left on the raw type disagrees with the match verdict.
     */
    private fun overloadNarrowedArgType(arg: Expression, raw: Type): Type {
        if (arg !is Identifier && arg !is PropertyAccessExpression) return raw
        if (raw is Type.Union) {
            val n = getNarrowedTypeForReference(raw, arg)
            // Round 476: a read AFTER a loop inside a switch case washes back to the
            // declared union at FlowLoopLabel — retry with the loop-entry-following
            // variant when the plain walk didn't narrow (STRUCTURAL wash gate, the
            // round-424 lesson: `&&`/`||` branch labels MINT a fresh identical union).
            // tsc typingInstallerAdapter's ActionSet case reads `response` after its
            // requestQueue while-loop. Suppression-only (narrowing refines arg types).
            if (n is Type.Union && n.types.size == raw.types.size &&
                n.types.mapTo(HashSet()) { it.id } == raw.types.mapTo(HashSet()) { it.id }
            ) {
                return getNarrowedTypeForReferenceFollowLoopEntry(raw, arg)
            }
            return n
        }
        // `boolean` is not modeled as `true | false`, so a guard-narrowed boolean
        // (`if (!allowAmbiguity) … parseParametersWorker(flags, allowAmbiguity)` against
        // overloads on literal `true`/`false` params — tsc's own parser.ts) can't refine
        // through the union path. Narrow the synthetic literal union instead and accept
        // only a definitive single-literal result.
        if (raw === booleanType) {
            val narrowed = getNarrowedTypeForReference(getUnionType(listOf(trueType, falseType)), arg)
            if (narrowed === trueType || narrowed === falseType) return narrowed
        }
        // Round 439: a bare Identifier/PropertyAccess arg narrowed DOWN from a NON-union
        // declared type to a subtype — `if (isLiteralLikeAccess(name)) …
        // getElementOrPropertyAccessName(name)` (utilities.ts `isSameEntityName`): a
        // type guard narrows `name: Expression` to `LiteralLikeElementAccessExpression |
        // PropertyAccessExpression`, which matches the overload param, but the arg check
        // saw the wide `Expression`. `unknown` is covered too — a `typeof target ===
        // "string"` arm narrows the `unknown` param to `string` (round 429d's narrowing
        // reached only the single-sig call-arg path; `getPathComponents` is overloaded —
        // tsc moduleNameResolver's `target: unknown` string arm). Mirrors round 438's
        // single-sig fix C: suppression-only (a subtype arg matches strictly MORE params
        // than its supertype); the never-collapse (round 418 hazard) keeps `raw`.
        if (raw is Type.Object || raw is Type.Interface || raw is Type.Reference || raw === unknownType) {
            val narrowed = getNarrowedTypeForReference(raw, arg)
            if (narrowed !== raw && narrowed !== neverType) return narrowed
        }
        return raw
    }

    private fun allArgumentsMatch(
        args: List<Expression>,
        sig: Signature,
        bivariantFnParams: Boolean = false,
        applyWeakRule: Boolean = false,
    ): Boolean {
        val params = sig.parameters
        // Check arity: too few arguments
        if (args.size < sig.minArgumentCount) return false
        // Check arity: too many arguments (unless last param is rest)
        val hasRestParam = params.isNotEmpty() && params.last().let { lastParam ->
            lastParam.declarations.any { d -> d is Parameter && d.dotDotDotToken }
        }
        if (args.size > params.size && !hasRestParam) return false
        val useBivariant = bivariantFnParams && options.strictExplicitlyFalse
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = restAwareParamType(params, i) ?: continue
            if (paramType === anyType || paramType === errorType) continue
            // 17.137a: Free Type.TypeParam accepts any arg under TypeScript's
            // inference semantics (T would simply be inferred as the arg type).
            // Used by TS2793 gates that ask "would the impl signature have
            // accepted these args?" — the impl `<T>(event: T)` accepts anything.
            // Constrained TypeParams ALSO accept here conservatively; the relation
            // engine doesn't return useful results for `Source vs TypeParam(C)`
            // without a full instantiation pass, so erring toward "match" matches
            // pre-17.137a behavior for the TS2793 path (always emit) for generic
            // impls.
            if (paramType is Type.TypeParam) continue
            // overloadingOnConstants2: against a LITERAL(-union) param, keep the literal arg
            // type — `getTypeOfExpression` widens a string/number literal (`"hi"`→string), which
            // would FP-reject a valid `foo("hi")` against an overload param `"hi"`. Gated to
            // literal params so non-literal overloads are byte-identical.
            val argType = overloadNarrowedArgType(arg, if (propTypeContainsLiteral(paramType))
                (literalTypeOfExpression(arg) ?: getTypeOfExpression(arg)) else getTypeOfExpression(arg))
            if (argType === anyType || argType === errorType) continue
            // B176: an explicit `undefined` arg is LEGAL for an OPTIONAL parameter (absent
            // and undefined are interchangeable for params unless exactOptionalPropertyTypes).
            if (argType.flags.hasAny(TypeFlags.Undefined) && !options.exactOptionalPropertyTypes &&
                params[i].declarations.any { d -> d is Parameter && d.questionToken }) continue
            if (overloadArgSkippable(argType, params[i], paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // Round 480: an inline arrow/fn-expr arg whose every RETURN is a
                // string literal ∈ the param's literal-union return is contextually
                // valid — tsc contextually types the returns from the param's
                // signature, so the literals never widen to `string`
                // (`this._walk(path, true, (err, res) => { … return "retry"; …
                // return "throw"; })` vs `(…) => "retry" | "throw"`, vfsUtil.ts).
                if (argFnLiteralReturnsSatisfyParam(arg, paramType)) continue
                // Round 728: an OBJECT-LITERAL arg whose only failure is a WIDENED
                // literal property (`{ usage: "sort" }` vs `usage?: "sort" | "search"`).
                if (objLitLiteralPropsSatisfyParam(arg, argType, paramType)) continue
                // B70.15: Bivariant fallback for function-vs-function under @strict: false.
                // Also try reverse direction; if param accepts arg's shape going either way,
                // count as match. Only fires for anonymous function-typed Type.Object pairs
                // (both have callSignatures) so non-function mismatches still fail.
                if (useBivariant &&
                    argType is Type.Object && argType !is Type.Reference && argType !is Type.Interface &&
                    !argType.callSignatures.isNullOrEmpty() &&
                    paramType is Type.Object && paramType !is Type.Reference && paramType !is Type.Interface &&
                    !paramType.callSignatures.isNullOrEmpty() &&
                    checkTypeRelatedTo(paramType, argType, assignableRelation)
                ) {
                    continue
                }
                return false
            }
            // (CHK.56) The relation has just ACCEPTED this argument; the weak-type rule
            // is the part of tsc's answer our relation does not carry. Opt-in
            // ([applyWeakRule]) so only the overload-MATCH loop in
            // [checkArgumentsAgainstOverloads] asks it — the other four callers are
            // TS2793 implementation-signature gates and a generic-instantiation probe,
            // which this round did not measure.
            if (applyWeakRule && weakOverloadArgRefuses(arg, argType, paramType)) return false
        }
        return true
    }

    /**
     * Round 728: does an OBJECT-LITERAL argument satisfy [paramType] once its
     * literal-valued properties are read as their LITERAL types?
     *
     * We have no fresh-literal machinery — [getTypeOfExpressionCore] types `"sort"` as
     * `string` — so an overload parameter carrying a literal-union property
     * (`usage?: "sort" | "search"`) rejects `{ usage: "sort" }`, which tsc accepts by
     * contextually typing each CANDIDATE's arguments (tsc core.ts's `new
     * Intl.Collator(locale, { usage: "sort", … })`; the single-signature path already
     * contextually types the literal, which is why only OVERLOADED callees exhibit it).
     * The plain-argument analogue is the `overloadingOnConstants2` rule at the call
     * sites above; this is that rule one level in, per property.
     *
     * Evaluated ONLY after [checkTypeRelatedTo] has already FAILED, so it costs nothing
     * on the happy path, and it is SUPPRESSION-ONLY and narrow: every literal property
     * must still be present on the target (an EXCESS property still rejects), every
     * required target property must still be supplied, and a property failing for any
     * reason other than literal widening still rejects. At least one property must
     * actually be rescued by its literal type, so a relation that failed for an
     * unrelated reason can never be accepted here.
     */
    private fun objLitLiteralPropsSatisfyParam(arg: Expression, argType: Type, paramType: Type): Boolean {
        if (arg !is ObjectLiteralExpression) return false
        val src = argType as? Type.Object ?: return false
        if (src is Type.Interface || src is Type.Reference) return false
        // (CHK.55) A UNION parameter is satisfied by SOME constituent — tsc's
        // `typeRelatedToSomeType` — so EVERY non-nullish object constituent is offered
        // the rescue, not only a lone one. `readFileSync`'s second overload takes
        // `{ encoding: BufferEncoding; flag?: string } | BufferEncoding`, which has two
        // non-nullish constituents, and the round-728 `singleOrNull` refused it outright.
        val targets: List<Type.Object> = when (paramType) {
            is Type.Union -> paramType.types
                .filter { !it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) }
                .filterIsInstance<Type.Object>()
            is Type.Object -> listOf(paramType)
            else -> return false
        }
        if (targets.isEmpty()) return false
        resolveStructuredTypeMembers(src)
        return targets.any { objLitLiteralPropsSatisfyObjectTarget(src, it) }
    }

    /**
     * (CHK.55) One target of [objLitLiteralPropsSatisfyParam]'s per-constituent fold.
     *
     * A TARGET WITH BASE TYPES IS NO LONGER REFUSED. Round 728 refused one on the
     * grounds that "an inherited required property would not be enumerated below";
     * measured, that is not true of this compiler — [resolveInterfaceMembersCore]
     * folds every base type's `members` into the derived type's own table and then
     * sets `properties = members.values.toList()`, so BOTH enumerations here (the
     * excess-property lookup and the required-property loop) already see inherited
     * members. The refusal was `knip`'s last overload row: `execSync(cmd, { encoding:
     * 'utf8', stdio: [...] })` against `ExecSyncOptionsWithStringEncoding extends
     * ExecSyncOptions`. The negative direction is pinned — a target whose required
     * property is INHERITED and absent from the literal still rejects.
     */
    private fun objLitLiteralPropsSatisfyObjectTarget(src: Type.Object, tgt: Type.Object): Boolean {
        if (tgt is Type.Reference) return false
        resolveStructuredTypeMembers(tgt)
        var anyLiteralRescue = false
        for (p in src.properties ?: return false) {
            val tp = getPropertyOfType(tgt, p.name) ?: return false  // excess property still rejects
            val tpt = getTypeOfSymbol(tp)
            if (tpt === anyType || tpt === errorType) continue
            val spt = getTypeOfSymbol(p)
            if (spt === anyType || spt === errorType) continue
            if (checkTypeRelatedTo(spt, tpt, assignableRelation)) continue
            if (!propTypeContainsLiteral(tpt)) return false
            val init = (p.valueDeclaration as? PropertyAssignment)?.initializer ?: return false
            val lit = literalTypeOfExpression(init) ?: return false
            if (!checkTypeRelatedTo(lit, tpt, assignableRelation)) return false
            anyLiteralRescue = true
        }
        if (!anyLiteralRescue) return false
        for (tp in tgt.properties ?: return false) {
            if (isOptionalProperty(tp)) continue
            if (getPropertyOfType(src, tp.name) == null) return false
        }
        return true
    }

    /**
     * Round 480: does the inline arrow/fn-expr [arg] satisfy a fn-typed [paramType]
     * whose single call signature returns a STRING-LITERAL union, by every returned
     * expression being a string literal in that union? tsc's contextual return
     * typing keeps such literals un-widened; our inference widens them to `string`
     * and FP-rejects. Accept-only (suppresses a reject); a block body must
     * always-return (a fall-through path would add `undefined`, which the union
     * lacks by construction here).
     */
    private fun argFnLiteralReturnsSatisfyParam(arg: Expression, paramType: Type): Boolean {
        if (arg !is ArrowFunction && arg !is FunctionExpression) return false
        val pObj = paramType as? Type.Object ?: return false
        if (pObj is Type.Interface || pObj is Type.Reference) return false
        resolveStructuredTypeMembers(pObj)
        val pSig = pObj.callSignatures?.singleOrNull() ?: return false
        val ret = pSig.resolvedReturnType ?: return false
        val allowed = mutableSetOf<String>()
        fun collectAllowed(t: Type): Boolean = when (t) {
            is Type.StringLiteral -> { allowed.add(t.value); true }
            is Type.Union -> t.types.all { collectAllowed(it) }
            else -> false
        }
        if (!collectAllowed(ret) || allowed.isEmpty()) return false
        val argParams = when (arg) {
            is ArrowFunction -> arg.parameters
            is FunctionExpression -> arg.parameters
        }
        if (argParams.size > pSig.parameters.size) return false
        if (argParams.any { it.type != null }) return false // annotated params keep the plain relation
        val body = when (arg) {
            is ArrowFunction -> arg.body
            is FunctionExpression -> arg.body
        }
        return when (body) {
            is Block -> {
                if (!bodyAlwaysReturns(body.statements)) return false
                val rets = mutableListOf<Expression?>()
                collectReturnExpressions(body.statements, rets)
                rets.isNotEmpty() && rets.all { r ->
                    var e = r ?: return@all false
                    while (e is ParenthesizedExpression) e = e.expression
                    (e as? StringLiteralNode)?.text in allowed
                }
            }
            is Expression -> {
                var e: Expression = body
                while (e is ParenthesizedExpression) e = e.expression
                (e as? StringLiteralNode)?.text in allowed
            }
            else -> false
        }
    }

    /**
     * Get the type of a callee expression for call/new checking.
     */
    /**
     * B497: resolve a value-position reference to a CLASS to its `typeof <Name>` display.
     * `Foo` (Identifier→class) → "typeof Foo"; `M.T` (namespace.exported-class) → "typeof T"
     * (tsc renders the LAST segment, not the qualified name). Returns null otherwise.
     */
    private fun typeofClassValueDisplay(recv: Expression): String? {
        return when (recv) {
            is Identifier -> {
                val sym = currentFileLocals?.get(recv.text) ?: globals[recv.text] ?: return null
                if (sym.declarations.any { it is ClassDeclaration }) "typeof ${recv.text}" else null
            }
            is PropertyAccessExpression -> {
                val nsName = (recv.expression as? Identifier)?.text ?: return null
                val nsSym = currentFileLocals?.get(nsName) ?: globals[nsName] ?: return null
                // The binder puts ALL namespace members in `exports` (not just exported
                // ones), so require the class decl to carry the `export` modifier — a
                // NON-exported `M.ClassA` is itself a TS2339 error (no typeof-class), and
                // tsc emits no TS7053 there (cannotInvokeNewOnErrorExpression).
                val member = nsSym.exports?.get(recv.name.text) ?: return null
                val classDecl = member.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                    ?: return null
                if (ModifierFlag.Export in classDecl.modifiers) "typeof ${recv.name.text}" else null
            }
            else -> null
        }
    }

    /**
     * Round 479: a for-of/for-in LOOP VARIABLE shadows a same-named outer/global
     * binding for the loop body's call-type resolution — evaluatorImpl.ts's
     * `for (const symbolName of symbolNames)` at file TOP LEVEL otherwise
     * resolved arg-position `symbolName` through merged `globals` to
     * compiler/utilitiesPublic's `function symbolName(symbol: Symbol): string`
     * → FP TS2345. Registers the binding names into [currentParamBindingNames]
     * (→ anyType, suppression-only) ONLY when the name collides with an outer
     * binding (globals / an inherited currentLocalTypes entry) — non-colliding
     * loop vars keep their pre-existing resolution paths. Scoped (save/restore).
     */
    private inline fun withForLoopVarShadow(initializer: Node?, body: () -> Unit) {
        val nameSet = mutableSetOf<String>()
        (initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
            collectBindingIdentifierNames(d.name, nameSet)
        }
        val names = nameSet.toList()
        val colliding = names.filter { nm ->
            nm !in currentParamBindingNames &&
                (globals[nm] != null || currentLocalTypes.containsKey(nm))
        }
        if (colliding.isEmpty()) { body(); return }
        val savedBindings = currentParamBindingNames
        val savedLocals = currentLocalTypes
        currentParamBindingNames = EpochSet(currentParamBindingNames).also { it.addAll(colliding) }
        currentLocalTypes = EpochMap(currentLocalTypes).also { m -> colliding.forEach { m.remove(it) } }
        try {
            body()
        } finally {
            currentParamBindingNames = savedBindings
            currentLocalTypes = savedLocals
        }
    }

    private fun getCalleeType(expr: Expression): Type {
        return when (expr) {
            is Identifier -> {
                // Local scope (function params, block-scoped vars) shadows globals.
                // E.g. `function b1(b1: number) { b1(12); }` — the inner `b1` is the
                // param, not the outer function — so resolving via globals would
                // miss the primitive-callee case.
                currentLocalTypes[expr.text]?.let { return it }
                // A function-body destructured/shadowed binding name (registered into the
                // side set by applyCallTypesBodyLocalShadowing — see the
                // currentParamBindingNames gotcha) shadows any cross-file `globals` function
                // of the same name. Mirrors getTypeOfIdentifier (line ~92457): without it,
                // `const { watchFile } = createWatchFactory()` resolved the CALLEE to
                // tsbuildPublic's top-level `function watchFile<T>(state: SolutionBuilderState<T>,
                // file: string, ...)` and FP'd the call's args against ITS params (arrow arg
                // vs `file: string`). The binding's member type is unmodeled → anyType
                // (suppression-only).
                if (expr.text in currentParamBindingNames) return anyType
                // 17.21: Namespace fallback so a class/fn declared inside `namespace M`
                // is reachable from a call/new inside another method in the same
                // namespace. Without this, `new List<T>(null)` inside
                // `namespace Editor { class ListFactory<T> { make() { ... } } }` would
                // bail at anyType and skip arg-type checking. Mirrors
                // `getTypeOfIdentifier`'s namespace fallback. MUST precede the file-local
                // consult below: a call inside `namespace Parser` to `createSourceFile`
                // must pick the namespace-internal one, NOT the file-level exported
                // `createSourceFile(fileName, sourceText: string, ...)` (parser.ts).
                lookupInInferenceNamespace(expr.text)?.let { return it }
                // Blocker #3 (cross-file name collision): the current file's OWN top-level
                // FUNCTION declaration of the callee name must win over the merged `globals`
                // symbol. `mergeSymbolTable` pollutes the FIRST-processed file's own symbol with
                // every other file's same-named declarations, so resolving `getBuildInfo` via
                // globals inside tsbuildPublic.ts (which has its OWN `function getBuildInfo<T>(
                // state: SolutionBuilderState<T>, ...)`) picked emitter.ts's `getBuildInfo(file:
                // string, ...)` → FP'd `state` against `string`. A non-first-processed file's
                // currentFileLocals entry is a CLEAN own-symbol (mergeSymbolTable never mutates
                // the source table). NARROW to a genuine same-file FUNCTION declaration (NOT a
                // type-only import / interface / type-alias): a callee `Date` shadowed by a
                // type-only `import { Date }` (an interface) must still resolve to the GLOBAL
                // `Date` VALUE (isolatedModulesShadowGlobalTypeNotValue), so an Alias/non-function
                // local must not override globals here.
                currentFileLocals?.get(expr.text)?.let { symbol ->
                    if (symbol.flags.hasAny(SymbolFlags.Function) &&
                        !symbol.flags.hasAny(SymbolFlags.Alias) &&
                        symbol.declarations.any { it is FunctionDeclaration }
                    ) {
                        val type = getTypeOfSymbol(symbol)
                        if (type !== anyType && type !== errorType) return type
                    }
                    // Round 474 (Blocker #3): a barrel-IMPORTED callee resolves through
                    // its OWN import when the merged `globals` winner is a DIFFERENT
                    // same-named function from another subproject —
                    // executeCommandLine.ts's compiler-barrel `formatMessage(message:
                    // DiagnosticMessage, …)` vs server/session.ts's `formatMessage(msg,
                    // logger: Logger, …)`: the merged symbol's valueDeclaration is
                    // file-order-dependent, so args were checked against the wrong
                    // file's signature. Gated to a genuine collision (globals resolves
                    // to a declaration NOT among the import target's own) — the
                    // non-collision path stays byte-identical through globals.
                    if (symbol.flags.hasAny(SymbolFlags.Alias)) {
                        importedCalleeFunctionType(expr.text, symbol)?.let { return it }
                        // Round 479: an import-equals alias to a namespace-import
                        // member (`export import parse = ts.getPathComponents`,
                        // harness vpathUtil.ts) resolves through its OWN target —
                        // never the same-named merged-globals function (`parse(path)`
                        // FP'd against a cross-file `parse(sourceFile: SourceFile)`).
                        importEqualsNamespaceMemberCalleeType(expr.text, symbol)?.let { return it }
                    }
                }
                // INV.3(c)(iii) round 507: node-keyed — a callee with no per-file
                // meaning must not check args against a foreign module file's leaked
                // signature (tsc: TS2304 → any; suppression-only).
                val symbol = lookupPerFileForNode(expr, expr.text) ?: return anyType
                // (CHK.49) the callee position is a VALUE position, and a module
                // file's TYPE-only declaration/import of a lib name does not hide
                // the lib's `declare var` — which is exactly the case the
                // Blocker-#3 narrowing above is written about
                // (isolatedModulesShadowGlobalTypeNotValue). Before (CHK.49) the
                // per-file probe answered the MERGED globals symbol and carried
                // the value meaning by accident; it now answers the shadowing
                // TYPE, so the value half is restored here.
                libValueBehindTypeOnlyShadow(expr.text, symbol)?.let { return getTypeOfSymbol(it) }
                getTypeOfSymbol(symbol)
            }
            is PropertyAccessExpression -> getTypeOfPropertyAccess(expr)
            is ElementAccessExpression -> getTypeOfElementAccess(expr)
            is ParenthesizedExpression -> getCalleeType(expr.expression)
            // (CHK.61d) `f!()` — the ASSERTION must reach the callee type, or a
            // `T | undefined` callee stays a union and TS2349 fires where tsc is
            // silent. Mirrors [getTypeOfExpression]'s own NonNullExpression arm.
            is NonNullExpression -> narrowByExcludingNullUndefined(getCalleeType(expr.expression))
            is SatisfiesExpression -> getCalleeType(expr.expression)
            is CallExpression -> getReturnTypeOfCallExpression(expr)
            is NewExpression -> getReturnTypeOfNewExpression(expr)
            else -> anyType
        }
    }

    /**
     * 17.221: Walks the class's extends chain to find the effective constructor's
     * accessibility modifier and its declaring class symbol. Returns null when no
     * constructor with `private` or `protected` is found (public or no explicit
     * constructor anywhere in chain).
     */
    private fun findEffectiveConstructorVisibility(classSym: Symbol): Pair<ModifierFlag, Symbol>? {
        val visited = mutableSetOf<Int>()
        var currentSym: Symbol? = classSym
        while (currentSym != null && visited.add(currentSym.id)) {
            val classDecl = currentSym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                ?: return null
            val ownCtor = classDecl.members.firstOrNull { it is Constructor } as? Constructor
            if (ownCtor != null) {
                val mods = ownCtor.modifiers
                return when {
                    ModifierFlag.Private in mods -> ModifierFlag.Private to currentSym
                    ModifierFlag.Protected in mods -> ModifierFlag.Protected to currentSym
                    else -> null
                }
            }
            // No own constructor — walk to base class. INV.3(c)(iii) round 507:
            // node-keyed (the ctor-visibility verdict must not come from a foreign
            // module file's leaked base class).
            val extendsClause = classDecl.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            val baseExpr = extendsClause?.types?.firstOrNull()?.expression
            val baseIdent = baseExpr as? Identifier ?: return null
            currentSym = lookupPerFileForNode(baseIdent, baseIdent.text)
        }
        return null
    }

    /**
     * 17.221: Returns true when `subClassSym` is `targetSym` itself, or extends it
     * (directly or transitively). Used for TS2674 protected-constructor accessibility.
     */
    private fun classExtendsOrIs(subClassSym: Symbol, targetSym: Symbol): Boolean {
        val visited = mutableSetOf<Int>()
        var current: Symbol? = subClassSym
        while (current != null && visited.add(current.id)) {
            if (current.id == targetSym.id) return true
            val classDecl = current.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                ?: return false
            val extendsClause = classDecl.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
            val baseExpr = extendsClause?.types?.firstOrNull()?.expression
            val baseIdent = baseExpr as? Identifier ?: return false
            // INV.3(c)(iii) round 507: node-keyed (see findEffectiveConstructorVisibility).
            current = lookupPerFileForNode(baseIdent, baseIdent.text)
        }
        return false
    }

    /**
     * Get call signatures from a type.
     */
    private fun getCallSignaturesOfType(type: Type): List<Signature> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.callSignatures ?: emptyList()
        }
        if (type is Type.Union) {
            // Collect call signatures from all union constituents
            val allSigs = mutableListOf<Signature>()
            for (constituent in type.types) {
                allSigs.addAll(getCallSignaturesOfType(constituent))
            }
            return allSigs
        }
        // Round 471: an INTERSECTION's call signatures are the concatenation of its
        // constituents' (tsc getSignaturesOfStructuredType) — a `Fn & Fn` member of a
        // union callee previously read as "has no call signatures" and FP'd TS2349
        // (tsc textChanges.ts `token.getStart(...)` / callHierarchy.ts, where the
        // augmentation merge yields intersection-shaped getStart members).
        if (type is Type.Intersection) {
            val allSigs = mutableListOf<Signature>()
            for (constituent in type.types) {
                allSigs.addAll(getCallSignaturesOfType(constituent))
            }
            return allSigs
        }
        return emptyList()
    }

    /**
     * Get construct signatures from a type.
     */
    private fun getConstructSignaturesOfType(type: Type): List<Signature> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.constructSignatures ?: emptyList()
        }
        return emptyList()
    }

    /**
     * Check each argument against the corresponding parameter type.
     * Emits TS2345 for type mismatches.
     *
     * Conservative: only checks when both argument and parameter types are
     * well-understood (primitives, literals, intrinsics). Skips complex types
     * (interfaces, objects, unions, intersections) to avoid false positives
     * from incomplete structural comparison and missing generic instantiation.
     */
    /**
     * voidArrayLit: returns [voidType] iff [arg] is a zero-argument call of a parameterless,
     * un-annotated arrow/function-expression whose block body has no value-returning `return`
     * — i.e. an IIFE `(() => {})()` / `(function(){})()` whose result is unambiguously `void`.
     * Returns null for every other shape, so the caller falls back to the original type.
     */
    private fun voidIifeArgType(arg: Expression): Type? {
        if (arg !is CallExpression) return null
        if (arg.arguments.isNotEmpty() || !arg.typeArguments.isNullOrEmpty()) return null
        var callee: Expression = arg.expression
        while (callee is ParenthesizedExpression) callee = callee.expression
        val (fnParams, fnBody, fnRet) = when (val fn = callee) {
            is ArrowFunction -> Triple(fn.parameters, fn.body, fn.type)
            is FunctionExpression -> Triple(fn.parameters, fn.body as Node, fn.type)
            else -> return null
        }
        if (fnParams.isNotEmpty() || fnRet != null) return null
        val block = fnBody as? Block ?: return null
        if (hasReturnWithExpression(block)) return null
        return voidType
    }

    /**
     * B200: TS2345 for `test1(0)?.("")` where `test1(a: number | string)` returns — from
     * INSIDE an `if (typeof a === "number")` guard — a function whose param is annotated
     * `typeof a`. tsc's CFA-for-function-likes (TS 4.4+) resolves the typeof-query at the
     * arrow's CREATION site, i.e. NARROWED to `number`, so a string arg to the returned
     * function always errors. Gates (each excludes a no-error sibling in the fixture):
     * the returned fn must be an arrow CREATED INSIDE the then-block (an arrow created
     * before the `if` sees the un-narrowed union — test4); via a direct `return <arrow>`
     * or an UN-annotated single-decl const returned later in the same block (an annotated
     * const's TypeLiteral governs and resolves typeof UN-narrowed — test2); the enclosing
     * param must never be reassigned in the body; the call site is the direct
     * call-of-call shape with a primitive/literal arg failing the narrowed type.
     */
    private fun checkNarrowedTypeofCallbackCalls() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            // Definition pass: fnName -> per-param narrowed types (null = unchecked).
            val fnMap = mutableMapOf<String, List<Type?>>()
            val multiDecl = mutableSetOf<String>()
            for (stmt in result.sourceFile.statements) {
                if (stmt !is FunctionDeclaration) continue
                val name = stmt.name?.text ?: continue
                if (name in fnMap) { multiDecl.add(name); continue }
                if (stmt.type != null) continue
                val body = stmt.body ?: continue
                val unionParams = stmt.parameters.mapNotNull { p ->
                    val pn = (p.name as? Identifier)?.text ?: return@mapNotNull null
                    if (p.type is UnionType) pn else null
                }.toSet()
                if (unionParams.isEmpty()) continue
                var found: List<Type?>? = null
                for (s0 in body.statements) {
                    val ifStmt = s0 as? IfStatement ?: continue
                    val cond = ifStmt.expression as? BinaryExpression ?: continue
                    if (cond.operator != SyntaxKind.EqualsEqualsEquals) continue
                    val tof = cond.left as? TypeOfExpression ?: continue
                    val subject = (tof.expression as? Identifier)?.text ?: continue
                    if (subject !in unionParams) continue
                    val lit = cond.right as? StringLiteralNode ?: continue
                    val narrowed = typeofTypeGuardToType(lit.text) ?: continue
                    if (narrowed === anyType || narrowed === errorType) continue
                    val thenBlock = ifStmt.thenStatement as? Block ?: continue
                    // The returned arrow: direct `return <arrow>` or un-annotated
                    // single-decl const returned later in the same block.
                    var arrow: ArrowFunction? = null
                    for (ts in thenBlock.statements) {
                        if (ts is ReturnStatement) {
                            val re = ts.expression
                            if (re is ArrowFunction) { arrow = re; break }
                            if (re is Identifier) {
                                val constDecl = thenBlock.statements.filterIsInstance<VariableStatement>()
                                    .flatMap { it.declarationList.declarations }
                                    .firstOrNull { (it.name as? Identifier)?.text == re.text }
                                if (constDecl != null && constDecl.type == null) {
                                    arrow = constDecl.initializer as? ArrowFunction
                                }
                                break
                            }
                        }
                    }
                    val a = arrow ?: continue
                    val paramTypes = a.parameters.map { p ->
                        val tq = p.type as? TypeQuery
                        if ((tq?.exprName as? Identifier)?.text == subject) narrowed else null
                    }
                    if (paramTypes.none { it != null }) continue
                    // The param must never be reassigned in the body.
                    if (stmtListContainsAssignTo(body.statements, subject)) continue
                    found = paramTypes
                    break
                }
                if (found != null) fnMap[name] = found
            }
            fnMap.keys.removeAll(multiDecl)
            if (fnMap.isEmpty()) continue
            // Call-site pass: direct call-of-call ExpressionStatements.
            for (stmt in result.sourceFile.statements) {
                val es = stmt as? ExpressionStatement ?: continue
                val outer = es.expression as? CallExpression ?: continue
                val inner = outer.expression as? CallExpression ?: continue
                val callee = (inner.expression as? Identifier)?.text ?: continue
                val paramTypes = fnMap[callee] ?: continue
                for ((i, arg) in outer.arguments.withIndex()) {
                    val narrowed = paramTypes.getOrNull(i) ?: continue
                    val argType = literalTypeOfExpression(arg) ?: getTypeOfExpression(arg)
                    val isPrim = argType is Type.Intrinsic || argType is Type.StringLiteral ||
                        argType is Type.NumberLiteral || argType is Type.BigIntLiteral ||
                        argType === trueType || argType === falseType
                    if (!isPrim || argType === anyType || argType === errorType) continue
                    val ok = checkTypeRelatedTo(argType, narrowed, assignableRelation)
                    if (ok) continue
                    val start = arg.pos
                    val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '${typeToString(getWidenedLiteralType(argType))}' is not assignable to parameter of type '${typeToString(narrowed)}'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line, character = character,
                        start = start, length = length,
                    ))
                }
            }
        }
    }

    /** B200 helper: does any statement assign to / inc-dec [name]? (shallow expr scan
     *  over assignment shapes; recurses statements only). */
    private fun stmtListContainsAssignTo(stmts: List<Statement>, name: String): Boolean {
        for (s in stmts) {
            when (s) {
                is ExpressionStatement -> {
                    val e = s.expression
                    if (e is BinaryExpression && isAssignmentOperator(e.operator) &&
                        (e.left as? Identifier)?.text == name) return true
                    if (e is PrefixUnaryExpression && (e.operand as? Identifier)?.text == name &&
                        (e.operator == SyntaxKind.PlusPlus || e.operator == SyntaxKind.MinusMinus)) return true
                    if (e is PostfixUnaryExpression && (e.operand as? Identifier)?.text == name) return true
                }
                is Block -> if (stmtListContainsAssignTo(s.statements, name)) return true
                is IfStatement -> {
                    if (stmtListContainsAssignTo(listOf(s.thenStatement), name)) return true
                    if (s.elseStatement?.let { stmtListContainsAssignTo(listOf(it), name) } == true) return true
                }
                is WhileStatement -> if (stmtListContainsAssignTo(listOf(s.statement), name)) return true
                is DoStatement -> if (stmtListContainsAssignTo(listOf(s.statement), name)) return true
                is ForStatement -> if (stmtListContainsAssignTo(listOf(s.statement), name)) return true
                is ForInStatement -> if (stmtListContainsAssignTo(listOf(s.statement), name)) return true
                is ForOfStatement -> if (stmtListContainsAssignTo(listOf(s.statement), name)) return true
                is TryStatement -> {
                    if (stmtListContainsAssignTo(s.tryBlock.statements, name)) return true
                    if (s.catchClause?.block?.statements?.let { stmtListContainsAssignTo(it, name) } == true) return true
                    if (s.finallyBlock?.statements?.let { stmtListContainsAssignTo(it, name) } == true) return true
                }
                else -> {}
            }
        }
        return false
    }

    /** B199 helper: scan [fileName]'s namespace bodies for an InterfaceDeclaration
     *  named [name] with exactly 2 type parameters. */
    private fun findNamespaceLocalInterface(fileName: String, name: String): InterfaceDeclaration? {
        val sf = binderResults.firstOrNull { it.sourceFile.fileName == fileName }?.sourceFile ?: return null
        fun scan(stmts: List<Statement>): InterfaceDeclaration? {
            for (st in stmts) {
                when (st) {
                    is InterfaceDeclaration -> if (st.name.text == name && st.typeParameters?.size == 2) return st
                    is ModuleDeclaration -> (st.body as? ModuleBlock)?.let { scan(it.statements)?.let { r -> return r } }
                    else -> {}
                }
            }
            return null
        }
        return scan(sf.statements)
    }

    /**
     * B199: TS2345 for an identity-shaped generic function arg against an instantiated
     * single-call-sig interface param. Shape: `all<T>(list: T[], iterator?: Iterator<T,
     * C>)` called `all([...literals...], identityFn)` where Iterator's ONLY member is a
     * call sig `(value: T1, ...anys): T2` (T1/T2 the interface's own TPs) and identityFn
     * is `<U>(value: U) => U`. tsc anchors T to the array literal's widened element union
     * and unifies U=T, so the call fails exactly when T isn't assignable to the concrete
     * return slot C — the self-computed `checkTypeRelatedTo(inferredT, C)` gate IS the
     * passing-set firewall (assignable -> no emit, e.g. `all([true], identity)`).
     */
    private fun tryEmitIdentityFnVsCallSigInterfaceMismatch(
        sigIn: Signature, args: List<Expression>, source: String, fileName: String,
    ): Boolean {
        val tp = sigIn.typeParameters?.singleOrNull() ?: return false
        val params = sigIn.parameters
        var inferredT: Type? = null
        var anchorIdx = -1
        for (j in params.indices) {
            if (j >= args.size) break
            val pt = getTypeOfSymbol(params[j])
            if (!isArrayOfTypeParam(pt, tp)) continue
            val arr = args[j] as? ArrayLiteralExpression ?: continue
            if (arr.elements.isEmpty() || arr.elements.any { it is SpreadElement }) continue
            val elemTypes = mutableListOf<Type>()
            var ok = true
            for (el in arr.elements) {
                val t = getWidenedLiteralType(getTypeOfExpression(el))
                val isAllowed = t is Type.Intrinsic && t.intrinsicName in setOf("string", "number", "boolean", "null", "undefined")
                if (!isAllowed) { ok = false; break }
                if (elemTypes.none { it.id == t.id }) elemTypes.add(t)
            }
            if (!ok) continue
            inferredT = if (elemTypes.size == 1) elemTypes[0] else getUnionType(elemTypes)
            anchorIdx = j
            break
        }
        val tInferred = inferredT ?: return false
        for (i in params.indices) {
            if (i == anchorIdx || i >= args.size) continue
            val pt = getTypeOfSymbol(params[i])
            val ref = pt as? Type.Reference ?: continue
            val refArgs = ref.resolvedTypeArguments ?: continue
            if (refArgs.size != 2) continue
            // TypeParam instances are interned per AST position, so the sig's `T` and the
            // `T` inside the `Iterator<T, boolean>` annotation may be DISTINCT instances —
            // match by kind + symbol name.
            val slot0 = refArgs[0]
            if (slot0 !is Type.TypeParam) continue
            val tpName = tp.symbol?.name
            if (tpName != null && slot0.symbol?.name != null && slot0.symbol?.name != tpName) continue
            val c = refArgs[1]
            if (c !is Type.Intrinsic || c === anyType || c === errorType ||
                c.intrinsicName in setOf("null", "undefined")) continue
            val ifaceSym = ref.target.symbol ?: continue
            // The resolved target may be the embedded LIB's same-named interface (the
            // namespace-local interface lookup gap — e.g. lib `Iterator<T>` shadowing
            // `Underscore.Iterator<T, U>`): prefer a same-file NAMESPACE-LOCAL interface
            // of the expected 2-TP shape when the resolved decl doesn't match.
            var ifaceDecl = ifaceSym.declarations.firstOrNull { it is InterfaceDeclaration } as? InterfaceDeclaration
            if (ifaceDecl?.typeParameters?.size != 2) {
                ifaceDecl = findNamespaceLocalInterface(fileName, ifaceSym.name)
            }
            if (ifaceDecl == null) continue
            val ifaceTps = ifaceDecl.typeParameters ?: continue
            if (ifaceTps.size != 2) continue
            val members = ifaceDecl.members
            if (members.size != 1) continue
            val callSig = members[0] as? MethodDeclaration ?: continue
            if ((callSig.name as? Identifier)?.text?.isEmpty() != true) continue
            val sigParams = callSig.parameters
            if (sigParams.isEmpty()) continue
            val firstPt = sigParams[0].type as? TypeReference ?: continue
            if ((firstPt.typeName as? Identifier)?.text != ifaceTps[0].name.text || !firstPt.typeArguments.isNullOrEmpty()) continue
            if (!sigParams.drop(1).all { (it.type as? KeywordTypeNode)?.kind == SyntaxKind.AnyKeyword }) continue
            val retRef = callSig.type as? TypeReference ?: continue
            if ((retRef.typeName as? Identifier)?.text != ifaceTps[1].name.text || !retRef.typeArguments.isNullOrEmpty()) continue
            val arg = args[i]
            val argType = getTypeOfExpression(arg)
            if (argType !is Type.Object || argType is Type.Interface || argType is Type.Reference) continue
            if (!argType.constructSignatures.isNullOrEmpty() || !argType.members.isNullOrEmpty()) continue
            val s0 = argType.callSignatures?.singleOrNull() ?: continue
            val sTp = s0.typeParameters?.singleOrNull() ?: continue
            if (s0.parameters.size != 1) continue
            val sParamType = getTypeOfSymbol(s0.parameters[0])
            if (sParamType !== sTp || s0.resolvedReturnType !== sTp) continue
            val assignable = checkTypeRelatedTo(tInferred, c, assignableRelation)
            if (assignable) return false
            val failing = (tInferred as? Type.Union)?.types?.filter {
                !(checkTypeRelatedTo(it, c, assignableRelation))
            } ?: listOf(tInferred)
            val nullish = failing.firstOrNull { it is Type.Intrinsic && it.intrinsicName == "undefined" }
                ?: failing.firstOrNull { it is Type.Intrinsic && it.intrinsicName == "null" }
                ?: failing.firstOrNull() ?: tInferred
            val tDisplay = typeToString(tInferred)
            val paramDisplay = "${ifaceSym.name}<$tDisplay, ${typeToString(c)}>"
            val start = arg.pos
            val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '${signatureToString(s0, isConstruct = false)}' is not assignable to parameter of type '$paramDisplay'.",
                category = DiagnosticCategory.Error,
                code = 2345,
                fileName = fileName,
                line = line, character = character,
                start = start, length = length,
                messageChain = listOf(
                    "  Type '$tDisplay' is not assignable to type '${typeToString(c)}'.",
                    "    Type '${typeToString(nullish)}' is not assignable to type '${typeToString(c)}'.",
                ),
            ))
            return true
        }
        return false
    }

    /**
     * B204: contravariant-alias-union inference + object-literal property mismatch
     * (coAndContraVariantInferences6). `createElement<P>(type: FC<P> | CC<P> | string,
     * props?: P | null)` called with `(WrapperIsolated, { value: "C" })` where
     * `WrapperIsolated: JSXElementConstructor<ExactProps>` (an alias whose body is a
     * union of fn/ctor types ALL passing the alias TP into param slot 0) — tsc infers
     * P=ExactProps from the contravariant first-param slot shared by every member of
     * the alias union, then contextually checks the fresh object literal against P.
     * Our general inference bails on Reference params mentioning the TP, so the
     * standard path is silent. AST-guided positional unification (B119 pattern); no
     * engine changes. Per-property gates: literal source, simple-checkable target,
     * relation-failed — tsc ALWAYS flags this conjunction.
     */
    /**
     * B561: a fresh object-literal OR a complete-object-type Identifier ARG vs a param
     * whose type is a UNION of NAMED object interfaces (errorsOnUnionsOfOverlappingObjects01).
     * The anonymous-constituent case is owned by [tryEmitUnionDiscriminantPropMismatch]
     * (it bails on Type.Interface/Reference); this owns the DISJOINT named-interface union
     * case. The general arg-check bails for union params (no `isSimpleCheckableType`), so
     * nothing fires today → purely ADDITIVE. tsc's behavior, mirrored:
     *   - if the arg is assignable to ANY constituent → valid, no error (the FP firewall);
     *   - a FRESH object literal: an excess prop (in NO constituent) → TS2353 at the key
     *     (union display); else, vs the BEST-matching constituent (most shared prop names,
     *     [findBestUnionConstituent]) — a missing required prop → TS2345 (single
     *     "Property 'X' is missing…" / ≥2 multi-prop "…missing the following properties…")
     *     + TS2728; a present-but-mismatched prop → TS2322 at the key (no related);
     *   - a NON-fresh Identifier arg → TS2345 at the arg with [getPropertyElaborationChain]'s
     *     Object→Union chain (drills the best constituent).
     * Returns true (one diagnostic emitted) on a hit. FP firewall: ≥2 constituents, ALL
     * shape constituents are NAMED interfaces with no string index signature; arg fails the
     * whole-union relation. (Verified additive by full-suite HEAD-diff.)
     */
    private fun tryEmitObjectVsNamedUnionArg(
        arg: Expression, argType: Type.Object, paramType: Type.Union, paramSym: Symbol,
        source: String, fileName: String,
    ): Boolean {
        // INV.5(d1)/round 552: a param union still carrying an UN-INFERRED
        // TypeParam (`flatten<T>(…: T[][] | readonly (T | …)[])` where our
        // engine failed to infer T) is OUR inference gap, never a user error
        // — the round-431 foreign-TP gate rationale applied to the PARAM
        // side. Without this, lifting the generic-property relation depth
        // cap makes the whole-union relation fail on the unbound T and this
        // emitter FPs on tsc's own program.ts flatten call (all 8 profiles).
        if (typeContainsUnresolvedTypeParam(paramType)) return false
        val constituents = paramType.types
        if (constituents.size < 2) return false
        var shapeCount = 0
        for (c in constituents) {
            when (c) {
                is Type.Reference, is Type.Interface -> {
                    resolveStructuredTypeMembers(c)
                    val co = c
                    if (co.stringIndexInfo != null) return false
                    if ((c as? Type.Interface)?.declaredStringIndexInfo != null) return false
                    shapeCount++
                }
                is Type.Object -> return false  // anonymous → owned by the discriminant walker
                else -> return false            // primitive / fn-only constituent → bail
            }
        }
        if (shapeCount < 2) return false
        resolveStructuredTypeMembers(argType)
        if (argType.properties.isNullOrEmpty()) return false
        val isFresh = arg is ObjectLiteralExpression
        // FP firewall. A FRESH object literal is valid only if it is structurally
        // assignable to a constituent AND has no excess prop vs THAT constituent (tsc's
        // excess rule for fresh literals). A NON-fresh Identifier is valid on structural
        // assignability alone (excess does not apply). Either way → no error.
        if (isFresh) {
            // tsc: a fresh literal is assignable to a union if it is structurally
            // assignable to SOME constituent AND has no UNION-excess (every prop lives in
            // SOME constituent — a prop present in a NON-matched constituent still counts as
            // known). `h({a,b})` vs `Foo|Bar|Other`: assignable to Bar, `a` is in Foo → valid.
            val unionPropNames = collectTargetPropertyNames(paramType)
            val noUnionExcess = unionPropNames != null &&
                (argType.properties?.all { it.name in unionPropNames } == true)
            val structurallyAssignable = constituents.any { c ->
                c is Type.Object && checkTypeRelatedTo(argType, c, assignableRelation)
            }
            if (noUnionExcess && structurallyAssignable) return false
        } else {
            if (constituents.any { checkTypeRelatedTo(argType, it, assignableRelation) }) return false
        }

        // Union display: an alias annotation (`a: ExoticAnimal`) renders as the alias name;
        // an inline union annotation (`x: Foo | Other`) renders expanded.
        val annot = (paramSym.valueDeclaration as? Parameter)?.type
        val unionDisplay = if (annot is TypeReference && annot.typeArguments == null) {
            (annot.typeName as? Identifier)?.text ?: typeToString(paramType)
        } else typeToString(paramType)
        val argDisplay = typeToString(argType)
        val argStart = arg.pos
        val argLen = expressionTrueEnd(arg) - argStart

        // 1. FRESH-only excess check (TS2353 at the key, union display).
        if (isFresh && checkExcessProperties(arg, argType, paramType, unionDisplay, source, fileName)) {
            return true
        }

        // 2. Missing required props in the best-matching constituent (fresh AND non-fresh):
        //    TS2345 at the arg + single/multi missing chain + TS2728 (single only).
        val best = findBestUnionConstituent(argType, paramType) as? Type.Object ?: return false
        resolveStructuredTypeMembers(best)
        val constituentDisplay = typeToString(best)
        val missing = (best.properties ?: emptyList()).filter { tp ->
            !isOptionalProperty(tp) && tp.name !in OBJECT_PROTOTYPE_PROPERTIES &&
                argType.members?.get(tp.name) == null
        }
        if (missing.isNotEmpty()) {
            if (argLen <= 0) return false
            val (aline, achar) = getLineAndCharacterOfPosition(source, argStart)
            val chain = mutableListOf<String>()
            val related = mutableListOf<Diagnostic>()
            if (missing.size == 1) {
                chain.add("  Property '${missing[0].name}' is missing in type '$argDisplay' but required in type '$constituentDisplay'.")
                val firstDecl = missing[0].declarations.firstOrNull()
                if (firstDecl != null) {
                    val declPos = when (firstDecl) {
                        is PropertyDeclaration -> firstDecl.name.pos
                        else -> firstDecl.pos
                    }
                    val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                    related.add(Diagnostic(
                        message = "'${missing[0].name}' is declared here.",
                        category = DiagnosticCategory.Message, code = 2728,
                        fileName = fileName, line = dline, character = dchar,
                        start = declPos, length = missing[0].name.length,
                    ))
                }
            } else {
                chain.add("  " + formatTs2740Message(argDisplay, constituentDisplay, missing.map { it.name }))
            }
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argDisplay' is not assignable to parameter of type '$unionDisplay'.",
                category = DiagnosticCategory.Error, code = 2345,
                fileName = fileName, line = aline, character = achar,
                start = argStart, length = argLen,
                messageChain = chain, relatedInformation = related,
            ))
            return true
        }

        // 3. Property-VALUE mismatch against the best constituent.
        if (isFresh) {
            // FRESH → TS2322 at the property key (no related).
            for (propNode in (arg).properties) {
                val pa = propNode as? PropertyAssignment ?: continue
                val nameNode = pa.name as? Identifier ?: continue
                val targetProp = best.members?.get(nameNode.text) ?: continue
                val targetPropType = getTypeOfSymbol(targetProp)
                if (targetPropType === anyType || targetPropType === errorType) continue
                val srcSym = argType.members?.get(nameNode.text) ?: continue
                val srcPropType = getTypeOfSymbol(srcSym)
                if (srcPropType === anyType || srcPropType === errorType) continue
                if (!isSimpleCheckableType(targetPropType) || !isSimpleCheckableType(srcPropType)) continue
                if (checkTypeRelatedTo(srcPropType, targetPropType, assignableRelation)) continue
                val (kline, kchar) = getLineAndCharacterOfPosition(source, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(getWidenedLiteralType(srcPropType))}' is not assignable to type '${typeToString(getWidenedLiteralType(targetPropType))}'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = kline, character = kchar,
                    start = nameNode.pos, length = nameNode.text.length,
                ))
                return true
            }
            return false
        }
        // NON-fresh Identifier → TS2345 at the arg with the best-constituent chain:
        // "  Type 'arg' is not assignable to type '<best>'." + the per-property drill.
        if (argLen <= 0) return false
        val inner = getPropertyElaborationChain(argType, best) ?: return false
        if (inner.isEmpty()) return false
        val chain = listOf("  Type '$argDisplay' is not assignable to type '$constituentDisplay'.") + inner.map { "  $it" }
        val (aline, achar) = getLineAndCharacterOfPosition(source, argStart)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$argDisplay' is not assignable to parameter of type '$unionDisplay'.",
            category = DiagnosticCategory.Error, code = 2345,
            fileName = fileName, line = aline, character = achar,
            start = argStart, length = argLen,
            messageChain = chain,
        ))
        return true
    }

    /**
     * B213: TS2322 for a UNION-discriminant property mismatch in an object-literal
     * arg (indirectDiscriminantAndExcessProperty). `thing({ type: foo1, ... })`
     * against `Blah = {type:"foo",...} | {type:"bar",...}` — tsc checks the prop
     * value against Blah["type"] = '"foo" | "bar"', and a widened `string`
     * (un-annotated let with a literal init; assignment narrowing can't narrow a
     * non-union string) always fails. The per-arg loop had no Type.Union paramType
     * branch for object literals, so the shape was silent. Gates: bare type-alias
     * annotation (display name); ALL ≥2 constituents anonymous Type.Objects
     * declaring the prop NON-optionally with a string/number-literal type; the
     * value type provable from a closed shape set; value fails EVERY constituent.
     */
    private fun tryEmitUnionDiscriminantPropMismatch(
        arg: ObjectLiteralExpression, paramType: Type.Union, paramSym: Symbol,
        source: String, fileName: String,
    ): Boolean {
        val annot = (paramSym.valueDeclaration as? Parameter)?.type as? TypeReference ?: return false
        if (annot.typeArguments != null) return false
        val aliasNameNode = annot.typeName as? Identifier ?: return false
        val aliasName = aliasNameNode.text
        // INV.3(d): the alias is typically a module-file top-level `type` no
        // longer merged into [globals] — resolve under the annotation node's
        // owning file (the declaring file's own local).
        val aliasSym = lookupPerFileForNode(aliasNameNode, aliasName) ?: return false
        if (!aliasSym.flags.hasAny(SymbolFlags.TypeAlias)) return false
        val constituents = paramType.types
        if (constituents.size < 2) return false
        for (c in constituents) {
            if (c !is Type.Object || c is Type.Interface || c is Type.Reference) return false
            resolveStructuredTypeMembers(c)
        }
        for (prop in arg.properties) {
            val pa = prop as? PropertyAssignment ?: continue
            val nameNode = pa.name as? Identifier ?: continue
            val pName = nameNode.text
            val discTypes = mutableListOf<Type>()
            var allHave = true
            var firstDeclPos = -1
            for (c in constituents) {
                val sym = (c as Type.Object).members?.get(pName)
                if (sym == null || isOptionalProperty(sym)) { allHave = false; break }
                val t = getTypeOfSymbol(sym)
                if (t !is Type.StringLiteral && t !is Type.NumberLiteral) { allHave = false; break }
                discTypes.add(t)
                if (firstDeclPos < 0) {
                    val dn = ((sym.valueDeclaration ?: sym.declarations.firstOrNull())
                        as? PropertyDeclaration)?.name as? Identifier
                    if (dn != null && dn.pos + pName.length <= source.length &&
                        source.regionMatches(dn.pos, pName, 0, pName.length)) firstDeclPos = dn.pos
                }
            }
            if (!allHave || discTypes.isEmpty()) continue
            val valueType: Type? = literalTypeOfExpression(pa.initializer) ?: run {
                val id = pa.initializer as? Identifier ?: return@run null
                val sym = currentFileLocals?.get(id.text)
                    ?: lookupPerFileForNode(id, id.text) ?: return@run null
                val vd = (sym.valueDeclaration ?: sym.declarations.firstOrNull())
                    as? VariableDeclaration ?: return@run null
                vd.type?.let {
                    return@run getTypeFromTypeNode(it)
                }
                // Un-annotated: require the declaring keyword to be exactly let/var
                // (const preserves the literal type — our widening would FP there).
                val lit = vd.initializer?.let { literalTypeOfExpression(it) } ?: return@run null
                var e = vd.pos
                while (e > 0 && source[e - 1].isWhitespace()) e--
                var s = e
                while (s > 0 && source[s - 1].isLetter()) s--
                if (e <= s || source.substring(s, e) !in setOf("let", "var")) return@run null
                getWidenedLiteralType(lit)
            }
            if (valueType == null) continue
            val vOk = (valueType is Type.Intrinsic &&
                (valueType.intrinsicName == "string" || valueType.intrinsicName == "number")) ||
                valueType is Type.StringLiteral || valueType is Type.NumberLiteral
            if (!vOk) continue
            val anyPass = discTypes.any { dt ->
                checkTypeRelatedTo(valueType, dt, assignableRelation)
            }
            if (anyPass) continue
            val discDisplay = discTypes.map { typeToString(it) }.distinct().joinToString(" | ")
            val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
            val related = mutableListOf<Diagnostic>()
            if (firstDeclPos >= 0) {
                val (rl, rc) = getLineAndCharacterOfPosition(source, firstDeclPos)
                related.add(Diagnostic(
                    message = "The expected type comes from property '$pName' which is declared here on type '$aliasName'",
                    category = DiagnosticCategory.Message, code = 6500,
                    fileName = fileName, line = rl, character = rc,
                    start = firstDeclPos, length = pName.length,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '${typeToString(valueType)}' is not assignable to type '$discDisplay'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = nameNode.pos, length = pName.length,
                relatedInformation = related,
            ))
            return true
        }
        return false
    }

    /**
     * B364: TS2820 / TS2322 — discriminant-property mismatch for an OBJECT-LITERAL ELEMENT
     * of an array literal assigned to `T[]` where `T` is a literal-discriminated union alias
     * (`type Disc = {kind:"a"} | {kind:"b"}; const ds: Disc[] = [{kind:"x"}]`). The relation
     * engine passes such element shapes trivially (incomplete discriminated-union modeling),
     * so this is the sole emitter. When the bad string-literal value is a close spelling of
     * one of the discriminant literals, tsc upgrades TS2322 → TS2820 with a "Did you mean"
     * hint. Uses `literalTypeOfExpression` so NO global literal-widening change is needed.
     */
    private fun checkArrayElementsDiscriminantMismatch(
        arrLit: ArrayLiteralExpression, elementUnion: Type.Union, aliasName: String,
        source: String, fileName: String,
    ) {
        val constituents = elementUnion.types
        if (constituents.size < 2) return
        for (c in constituents) {
            if (c !is Type.Object || c is Type.Interface || c is Type.Reference) return
            resolveStructuredTypeMembers(c)
        }
        for (elem in arrLit.elements) {
            val obj = elem as? ObjectLiteralExpression ?: continue
            emitObjectDiscriminantMismatch(obj, constituents, aliasName, source, fileName)
        }
    }

    /** Per-object core of [checkArrayElementsDiscriminantMismatch]; emits at most one error. */
    private fun emitObjectDiscriminantMismatch(
        arg: ObjectLiteralExpression, constituents: List<Type>, aliasName: String,
        source: String, fileName: String,
    ): Boolean {
        for (prop in arg.properties) {
            val pa = prop as? PropertyAssignment ?: continue
            val nameNode = pa.name as? Identifier ?: continue
            val pName = nameNode.text
            val discTypes = mutableListOf<Type>()
            var allHave = true
            var firstDeclPos = -1
            for (c in constituents) {
                val sym = (c as Type.Object).members?.get(pName)
                if (sym == null || isOptionalProperty(sym)) { allHave = false; break }
                val t = getTypeOfSymbol(sym)
                if (t !is Type.StringLiteral && t !is Type.NumberLiteral) { allHave = false; break }
                discTypes.add(t)
                if (firstDeclPos < 0) {
                    val dn = ((sym.valueDeclaration ?: sym.declarations.firstOrNull())
                        as? PropertyDeclaration)?.name as? Identifier
                    if (dn != null && dn.pos + pName.length <= source.length &&
                        source.regionMatches(dn.pos, pName, 0, pName.length)) firstDeclPos = dn.pos
                }
            }
            if (!allHave || discTypes.isEmpty()) continue
            val valueType = literalTypeOfExpression(pa.initializer) ?: continue
            if (valueType !is Type.StringLiteral && valueType !is Type.NumberLiteral) continue
            val anyPass = discTypes.any { dt ->
                checkTypeRelatedTo(valueType, dt, assignableRelation)
            }
            if (anyPass) continue
            val discDisplay = discTypes.map { typeToString(it) }.distinct().joinToString(" | ")
            var suggestion: String? = null
            if (valueType is Type.StringLiteral) {
                val cands = discTypes.filterIsInstance<Type.StringLiteral>().map { it.value }.toSet()
                suggestion = getSpellingSuggestionFromNames(valueType.value, cands)
            }
            val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
            val related = mutableListOf<Diagnostic>()
            if (firstDeclPos >= 0) {
                val (rl, rc) = getLineAndCharacterOfPosition(source, firstDeclPos)
                related.add(Diagnostic(
                    message = "The expected type comes from property '$pName' which is declared here on type '$aliasName'",
                    category = DiagnosticCategory.Message, code = 6500,
                    fileName = fileName, line = rl, character = rc,
                    start = firstDeclPos, length = pName.length,
                ))
            }
            if (suggestion != null) {
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(valueType)}' is not assignable to type '$discDisplay'. Did you mean '\"$suggestion\"'?",
                    category = DiagnosticCategory.Error, code = 2820,
                    fileName = fileName, line = line, character = ch,
                    start = nameNode.pos, length = pName.length,
                    relatedInformation = related,
                ))
            } else {
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(valueType)}' is not assignable to type '$discDisplay'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = nameNode.pos, length = pName.length,
                    relatedInformation = related,
                ))
            }
            return true
        }
        return false
    }

    /**
     * Extract `(elementUnion, aliasName)` from a `T[]` / `Array<T>` annotation where the
     * element `T` is a bare TypeReference resolving to a union — used by the array-element
     * discriminant check (B364). Returns null for any other shape.
     */
    private fun arrayElementUnionAlias(annotation: TypeNode?, fileName: String): Pair<Type.Union, String>? {
        val elemNode: TypeNode = when (annotation) {
            is ArrayType -> annotation.elementType
            is TypeReference -> if ((annotation.typeName as? Identifier)?.text == "Array")
                annotation.typeArguments?.singleOrNull() ?: return null else return null
            else -> return null
        }
        val ref = elemNode as? TypeReference ?: return null
        if (ref.typeArguments != null) return null
        val aliasName = (ref.typeName as? Identifier)?.text ?: return null
        // Top-level alias: direct resolution works.
        val direct = getTypeFromTypeNode(ref)
        if (direct is Type.Union) return direct to aliasName
        // Function/block-local alias: NOT bound (Binder block-scope gotcha), so the named
        // reference resolves to errorType. Find the `type X = A | B` declaration and resolve
        // its UnionType body directly — the constituent TypeLiterals resolve without a name
        // lookup, so the union materializes even for an unbound alias.
        val aliasDecl = findLocalTypeAlias(aliasName, fileName) ?: return null
        val body = aliasDecl.type as? UnionType ?: return null
        val u = (getTypeFromTypeNode(body))
            as? Type.Union ?: return null
        return u to aliasName
    }

    /**
     * B365: TS2348 — calling a value typed as a construct-signature-ONLY type (a
     * `new (...) => X` ConstructorType, or an interface with only construct signatures).
     * Shape: `var v1!: { [index: string]: new (arg: T) => Date }; var v2 = v1['k']; v2(args);`.
     * `v2`'s inferred type (the index-sig value) has only construct signatures, so a plain
     * call is invalid → "Value of type 'new (arg: T) => Date' is not callable. Did you mean
     * to include 'new'?". The display preserves the generic `T` (the type engine would
     * resolve the function-local `T` to errorType → 'any'), so it is taken from the SOURCE
     * slice of the value-type node. `new v2(args)` (NewExpression) is correctly NOT flagged.
     */
    private fun checkConstructSigOnlyCalls() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            scanConstructSigOnlyCalls(result.sourceFile.statements, result.sourceFile.text, fileName)
        }
    }

    private fun scanConstructSigOnlyCalls(stmts: List<Statement>, source: String, fileName: String) {
        // 1. local var annotations (TypeLiteral with a string index sig).
        val annotatedVars = HashMap<String, TypeNode>()
        for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
            val n = d.name as? Identifier ?: continue
            d.type?.let { annotatedVars[n.text] = it }
        }
        // 2. `var V2 = V1[...]` where V1's index-sig value is construct-sig-only → (display).
        val ctorOnlyVars = HashMap<String, String>()
        for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
            val n = d.name as? Identifier ?: continue
            val init = d.initializer as? ElementAccessExpression ?: continue
            val recv = init.expression as? Identifier ?: continue
            val tl = annotatedVars[recv.text] as? TypeLiteral ?: continue
            val idxSig = tl.members.firstOrNull { it is IndexSignature } as? IndexSignature ?: continue
            val valueNode = idxSig.type ?: continue
            if (!isConstructSigOnlyNode(valueNode, fileName)) continue
            ctorOnlyVars[n.text] = indexSigValueTypeText(valueNode.pos, source)
        }
        // 3. emit TS2348 for plain CALLS of those vars (NewExpression is fine).
        fun checkCall(call: CallExpression) {
            val callee = call.expression as? Identifier ?: return
            val disp = ctorOnlyVars[callee.text] ?: return
            val start = callee.pos
            val len = callExprSpanLen(call, source)
            val (line, ch) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Value of type '$disp' is not callable. Did you mean to include 'new'?",
                category = DiagnosticCategory.Error, code = 2348,
                fileName = fileName, line = line, character = ch,
                start = start, length = len,
            ))
        }
        for (s in stmts) {
            when (s) {
                is ExpressionStatement -> (s.expression as? CallExpression)?.let { checkCall(it) }
                is VariableStatement -> for (d in s.declarationList.declarations) {
                    (d.initializer as? CallExpression)?.let { checkCall(it) }
                }
                is ReturnStatement -> (s.expression as? CallExpression)?.let { checkCall(it) }
                is FunctionDeclaration -> s.body?.let { scanConstructSigOnlyCalls(it.statements, source, fileName) }
                is Block -> scanConstructSigOnlyCalls(s.statements, source, fileName)
                is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { scanConstructSigOnlyCalls(it.statements, source, fileName) }
                else -> {}
            }
        }
    }

    /**
     * B370: TS2488 — array-destructuring a co-destructured binding that is `never` in the
     * `default` of an EXHAUSTIVE discriminant switch. Shape: `const { kind, a } = x` (x a
     * discriminated-union param), `switch (kind) { case "a":…; case "b":…; default: const
     * [n] = a }` — when the cases cover ALL of x's `kind` literals, the default is reached
     * only when x is `never`, so the sibling binding `a` is `never` → destructuring it has
     * no iterator. FP-safe by exact shape (exhaustive cases + sibling-binding destructure).
     */
    private fun checkExhaustiveSwitchDefaultDestructure() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            scanExhaustiveSwitchDefault(result.sourceFile.statements, result.sourceFile.text, fileName, emptyMap())
        }
    }

    private fun discUnionParamMembers(parameters: List<Parameter>, fileName: String): Map<String, List<TypeLiteral>> {
        val m = HashMap<String, List<TypeLiteral>>()
        for (p in parameters) {
            val n = (p.name as? Identifier)?.text ?: continue
            val ref = p.type as? TypeReference ?: continue
            val aliasName = (ref.typeName as? Identifier)?.text ?: continue
            val aliasDecl = findLocalTypeAlias(aliasName, fileName) ?: continue
            val union = aliasDecl.type as? UnionType ?: continue
            val tls = union.types.filterIsInstance<TypeLiteral>()
            if (tls.size == union.types.size && tls.size >= 2) m[n] = tls
        }
        return m
    }

    private fun memberLiteralValue(t: TypeNode?): String? = when {
        t is LiteralType && t.literal is StringLiteralNode -> (t.literal).text
        t is LiteralType && t.literal is NumericLiteralNode -> (t.literal).text
        else -> null
    }

    private fun scanExhaustiveSwitchDefault(
        stmts: List<Statement>, source: String, fileName: String, discParams: Map<String, List<TypeLiteral>>,
    ) {
        // Object-destructures of a discriminated-union param: bindingName -> (propName, xName).
        val destructure = HashMap<String, Pair<String, String>>()
        for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
            val obp = d.name as? ObjectBindingPattern ?: continue
            val xName = (d.initializer as? Identifier)?.text ?: continue
            if (xName !in discParams) continue
            for (el in obp.elements) {
                val bindName = (el.name as? Identifier)?.text ?: continue
                val propName = (el.propertyName as? Identifier)?.text ?: bindName
                destructure[bindName] = propName to xName
            }
        }
        for (s in stmts) {
            when (s) {
                is SwitchStatement -> {
                    emitExhaustiveDefaultDestructure(s, destructure, discParams, source, fileName)
                    for (c in s.caseBlock) when (c) {
                        is CaseClause -> scanExhaustiveSwitchDefault(c.statements, source, fileName, discParams)
                        is DefaultClause -> scanExhaustiveSwitchDefault(c.statements, source, fileName, discParams)
                        else -> {}
                    }
                }
                is FunctionDeclaration -> s.body?.let {
                    scanExhaustiveSwitchDefault(it.statements, source, fileName, discParams + discUnionParamMembers(s.parameters, fileName))
                }
                is Block -> scanExhaustiveSwitchDefault(s.statements, source, fileName, discParams)
                else -> {}
            }
        }
    }

    private fun emitExhaustiveDefaultDestructure(
        sw: SwitchStatement, destructure: Map<String, Pair<String, String>>,
        discParams: Map<String, List<TypeLiteral>>, source: String, fileName: String,
    ) {
        val discBinding = (sw.expression as? Identifier)?.text ?: return
        val (discProp, xName) = destructure[discBinding] ?: return
        val members = discParams[xName] ?: return
        val discValues = mutableSetOf<String>()
        for (m in members) {
            val propDecl = m.members.firstNotNullOfOrNull { mm ->
                (mm as? PropertyDeclaration)?.takeIf { (it.name as? Identifier)?.text == discProp }
            } ?: return
            val v = memberLiteralValue(propDecl.type) ?: return
            discValues.add(v)
        }
        if (discValues.isEmpty()) return
        val caseValues = mutableSetOf<String>()
        var defaultClause: DefaultClause? = null
        for (c in sw.caseBlock) when (c) {
            is CaseClause -> when (val ce = c.expression) {
                is StringLiteralNode -> caseValues.add(ce.text)
                is NumericLiteralNode -> caseValues.add(ce.text)
                else -> {}
            }
            is DefaultClause -> defaultClause = c
            else -> {}
        }
        val dc = defaultClause ?: return
        if (!discValues.all { it in caseValues }) return // not exhaustive
        for (st in dc.statements) {
            // `const [pat] = OTHER`
            if (st is VariableStatement) for (d in st.declarationList.declarations) {
                val abp = d.name as? ArrayBindingPattern ?: continue
                val src = (d.initializer as? Identifier)?.text ?: continue
                if (src == discBinding || destructure[src]?.second != xName) continue
                emitNeverIteratorAt(abp.pos, source, fileName)
            }
            // `[pat] = OTHER`
            val be = (st as? ExpressionStatement)?.expression as? BinaryExpression
            if (be != null && be.operator == SyntaxKind.Equals) {
                val abp = be.left as? ArrayLiteralExpression ?: continue
                val src = (be.right as? Identifier)?.text ?: continue
                if (src == discBinding || destructure[src]?.second != xName) continue
                emitNeverIteratorAt(abp.pos, source, fileName)
            }
        }
    }

    private fun emitNeverIteratorAt(pos: Int, source: String, fileName: String) {
        val len = arrayPatternSpanLen(pos, source)
        val (line, ch) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "Type 'never' must have a '[Symbol.iterator]()' method that returns an iterator.",
            category = DiagnosticCategory.Error, code = 2488,
            fileName = fileName, line = line, character = ch, start = pos, length = len,
        ))
    }

    /**
     * B369: TS2488 — array-destructuring a value narrowed to `never`. Shape:
     * `const b: null; if (b === null) {} else { [pat] = b }`. The else of `b === null` on a
     * `null`-typed `b` is `never`, and array-destructuring a `never` source has no iterator.
     * FP-safe by exact shape (null-typed var + `=== null` if/else + array-destructure of the
     * SAME var in the else). strictNullChecks-gated (the never narrowing is strict-mode).
     */
    private fun checkNeverArrayDestructureFromNullElse() {
        if (!strictNullChecks) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            scanNeverDestructure(result.sourceFile.statements, result.sourceFile.text, fileName, emptySet())
        }
    }

    private fun nullTypedVarNames(stmts: List<Statement>): Set<String> {
        val s = HashSet<String>()
        for (st in stmts) if (st is VariableStatement) for (d in st.declarationList.declarations) {
            val n = d.name as? Identifier ?: continue
            val t = d.type ?: continue
            val isNull = (t is KeywordTypeNode && t.kind == SyntaxKind.NullKeyword) ||
                (t is LiteralType && t.literal.kind == SyntaxKind.NullKeyword)
            if (isNull) s.add(n.text)
        }
        return s
    }

    private fun scanNeverDestructure(
        stmts: List<Statement>, source: String, fileName: String, nullVars: Set<String>,
    ) {
        val locals = nullVars + nullTypedVarNames(stmts)
        for (s in stmts) {
            when (s) {
                is IfStatement -> {
                    val cond = s.expression
                    val elseBlock = s.elseStatement as? Block
                    if (elseBlock != null && cond is BinaryExpression &&
                        cond.operator == SyntaxKind.EqualsEqualsEquals &&
                        ((cond.right as? Identifier)?.text == "null" || cond.right.kind == SyntaxKind.NullKeyword)) {
                        val name = (cond.left as? Identifier)?.text
                        if (name != null && name in locals) {
                            for (st in elseBlock.statements) {
                                val be = (st as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
                                if (be.operator != SyntaxKind.Equals) continue
                                val lhs = be.left as? ArrayLiteralExpression ?: continue
                                if ((be.right as? Identifier)?.text != name) continue
                                val len = arrayPatternSpanLen(lhs.pos, source)
                                val (line, ch) = getLineAndCharacterOfPosition(source, lhs.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Type 'never' must have a '[Symbol.iterator]()' method that returns an iterator.",
                                    category = DiagnosticCategory.Error, code = 2488,
                                    fileName = fileName, line = line, character = ch,
                                    start = lhs.pos, length = len,
                                ))
                            }
                        }
                    }
                    (s.thenStatement as? Block)?.let { scanNeverDestructure(it.statements, source, fileName, locals) }
                    elseBlock?.let { scanNeverDestructure(it.statements, source, fileName, locals) }
                }
                is FunctionDeclaration -> s.body?.let { scanNeverDestructure(it.statements, source, fileName, locals) }
                is Block -> scanNeverDestructure(s.statements, source, fileName, locals)
                else -> {}
            }
        }
    }

    /** Length of a `[...]` array pattern starting at [start] (bracket-balanced). */
    private fun arrayPatternSpanLen(start: Int, source: String): Int {
        var i = start; var depth = 0
        while (i < source.length) {
            val c = source[i]
            if (c == '[') depth++
            else if (c == ']') { depth--; if (depth == 0) { i++; break } }
            i++
        }
        return (i - start).coerceAtLeast(1)
    }

    /**
     * B522: TS2488 for array-destructuring (`const [x] = v`) of a value whose declared type
     * reduces to `never` — an INTERSECTION of object types with a shared property declared with
     * incompatible LITERAL types (`{ a: "foo" } & { a: "bar" }` → never), a UNION whose members
     * all so reduce, or a type parameter constrained by such an intersection (display uses the
     * TP NAME, e.g. "Type 'T' must have ..."). The relation engine doesn't model the
     * intersection-→-never reduction, so we emit nothing today. AST-based; FP-safe because the
     * never-classification fires ONLY for a shared prop with ≥2 DISTINCT literal types (a
     * provably-empty intersection) and array-destructuring `never` is always TS2488 in tsc.
     */
    private fun checkIntersectionNeverArrayDestructure() {
        // TS2488 uses the Symbol.iterator protocol; under ES3/ES5 without downlevelIteration
        // array-destructuring uses array-likeness (no iterator) → tsc emits NOTHING there.
        if (options.defaultedTarget < ScriptTarget.ES2015 && !options.downlevelIteration) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val topAnn = HashMap<String, TypeNode>()
            collectNeverVarAnns(result.sourceFile.statements, topAnn)
            walkNeverDestructure(result.sourceFile.statements, topAnn, emptyMap(), source, fileName)
        }
    }

    private fun collectNeverVarAnns(stmts: List<Statement>, out: MutableMap<String, TypeNode>) {
        for (st in stmts) if (st is VariableStatement) for (d in st.declarationList.declarations) {
            val n = (d.name as? Identifier)?.text ?: continue
            val t = d.type ?: continue
            if (n !in out) out[n] = t
        }
    }

    private fun unwrapParenType(t: TypeNode?): TypeNode? =
        if (t is ParenthesizedType) unwrapParenType(t.type) else t

    private fun neverIntersectionLiteralKey(t: TypeNode?): String? = when (val lit = (unwrapParenType(t) as? LiteralType)?.literal) {
        is StringLiteralNode -> "s:${lit.text}"
        is NumericLiteralNode -> "n:${lit.text}"
        is BigIntLiteralNode -> "b:${lit.text}"
        is Identifier -> if (lit.text == "true" || lit.text == "false") "k:${lit.text}" else null
        else -> null
    }

    private fun isNeverIntersectionType(node: IntersectionType): Boolean {
        val propLits = HashMap<String, MutableSet<String>>()
        for (m in node.types) {
            val tl = unwrapParenType(m) as? TypeLiteral ?: continue
            for (member in tl.members) {
                if (member is PropertyDeclaration) {
                    val pn = (member.name as? Identifier)?.text ?: continue
                    val k = neverIntersectionLiteralKey(member.type) ?: continue
                    propLits.getOrPut(pn) { HashSet() }.add(k)
                }
            }
        }
        return propLits.values.any { it.size >= 2 }
    }

    /** Returns the display name ("never" or a TP name) if the annotation reduces to never, else null. */
    private fun classifyNeverDestructure(ann: TypeNode?, tpConstraints: Map<String, TypeNode>): String? {
        return when (val t = unwrapParenType(ann)) {
            is IntersectionType -> if (isNeverIntersectionType(t)) "never" else null
            is UnionType -> if (t.types.isNotEmpty() && t.types.all { classifyNeverDestructure(it, tpConstraints) == "never" }) "never" else null
            is TypeReference -> {
                val nm = (t.typeName as? Identifier)?.text
                val c = nm?.let { tpConstraints[it] }
                if (nm != null && c != null && classifyNeverDestructure(c, tpConstraints) != null) nm else null
            }
            else -> null
        }
    }

    private fun walkNeverDestructure(
        stmts: List<Statement>, varAnn: Map<String, TypeNode>,
        tpConstraints: Map<String, TypeNode>, source: String, fileName: String,
    ) {
        for (s in stmts) {
            when (s) {
                is VariableStatement -> for (d in s.declarationList.declarations) {
                    val pat = d.name as? ArrayBindingPattern ?: continue
                    val initName = (d.initializer as? Identifier)?.text ?: continue
                    val ann = varAnn[initName] ?: continue
                    val disp = classifyNeverDestructure(ann, tpConstraints) ?: continue
                    val len = arrayPatternSpanLen(pat.pos, source)
                    val (line, ch) = getLineAndCharacterOfPosition(source, pat.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$disp' must have a '[Symbol.iterator]()' method that returns an iterator.",
                        category = DiagnosticCategory.Error, code = 2488,
                        fileName = fileName, line = line, character = ch,
                        start = pat.pos, length = len,
                    ))
                }
                is FunctionDeclaration -> {
                    val body = s.body ?: continue
                    val childAnn = HashMap(varAnn)
                    for (p in s.parameters) {
                        val pn = (p.name as? Identifier)?.text ?: continue
                        val pt = p.type ?: continue
                        childAnn[pn] = pt
                    }
                    val childTps = HashMap(tpConstraints)
                    s.typeParameters?.forEach { tp -> tp.constraint?.let { childTps[tp.name.text] = it } }
                    collectNeverVarAnns(body.statements, childAnn)
                    walkNeverDestructure(body.statements, childAnn, childTps, source, fileName)
                }
                else -> {}
            }
        }
    }

    /**
     * B368: TS18047 — `if (typeof x === 'object') { x.member }` where `x` is `unknown`-typed.
     * `typeof null === "object"`, so narrowing `unknown` by `typeof === 'object'` yields
     * `object | null` (NOT just `object`) — accessing a member is then "possibly null".
     * FP-safe by exact shape: the whole if-condition must be the BARE `typeof x === 'object'`
     * binary (the `&&`-chained truthiness variants `typeof x === 'object' && x` / `x && …`
     * have an `&&` root operator and so don't match — and those correctly DO narrow null
     * away). Reassignment of x in the then-block suppresses. strictNullChecks-gated.
     */
    private fun checkUnknownTypeofObjectPossiblyNull() {
        if (!strictNullChecks) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            scanUnknownTypeofObject(result.sourceFile.statements, result.sourceFile.text, fileName, emptySet())
        }
    }

    private fun unknownTypedParamNames(parameters: List<Parameter>): Set<String> {
        val s = HashSet<String>()
        for (p in parameters) {
            val n = p.name as? Identifier ?: continue
            val t = p.type
            if (t is KeywordTypeNode && t.kind == SyntaxKind.UnknownKeyword) s.add(n.text)
        }
        return s
    }

    /** If [cond] is exactly `typeof IDENT === 'object'` (either operand order), return IDENT's name. */
    private fun typeofObjectCheckName(cond: Expression): String? {
        if (cond !is BinaryExpression || cond.operator != SyntaxKind.EqualsEqualsEquals) return null
        val typeofExpr = (cond.left as? TypeOfExpression) ?: (cond.right as? TypeOfExpression) ?: return null
        val lit = (cond.right as? StringLiteralNode) ?: (cond.left as? StringLiteralNode) ?: return null
        if (lit.text != "object") return null
        return (typeofExpr.expression as? Identifier)?.text
    }

    private fun scanUnknownTypeofObject(
        stmts: List<Statement>, source: String, fileName: String, unknownNames: Set<String>,
    ) {
        for (s in stmts) {
            when (s) {
                is FunctionDeclaration -> s.body?.let {
                    scanUnknownTypeofObject(it.statements, source, fileName, unknownNames + unknownTypedParamNames(s.parameters))
                }
                is IfStatement -> {
                    val name = typeofObjectCheckName(s.expression)
                    val thenBlock = s.thenStatement as? Block
                    if (name != null && name in unknownNames && thenBlock != null &&
                        !blockAssignsName(thenBlock.statements, name)) {
                        for (recv in directMemberAccessReceivers(thenBlock.statements, name)) {
                            val (line, ch) = getLineAndCharacterOfPosition(source, recv.pos)
                            diagnostics.add(Diagnostic(
                                message = "'$name' is possibly 'null'.",
                                category = DiagnosticCategory.Error, code = 18047,
                                fileName = fileName, line = line, character = ch,
                                start = recv.pos, length = name.length,
                            ))
                        }
                    }
                    thenBlock?.let { scanUnknownTypeofObject(it.statements, source, fileName, unknownNames) }
                    (s.elseStatement as? Block)?.let { scanUnknownTypeofObject(it.statements, source, fileName, unknownNames) }
                }
                is Block -> scanUnknownTypeofObject(s.statements, source, fileName, unknownNames)
                is ForStatement -> (s.statement as? Block)?.let { scanUnknownTypeofObject(it.statements, source, fileName, unknownNames) }
                is WhileStatement -> (s.statement as? Block)?.let { scanUnknownTypeofObject(it.statements, source, fileName, unknownNames) }
                else -> {}
            }
        }
    }

    /** Does any DIRECT statement in [stmts] assign to [name] (`name = ...`)? */
    private fun blockAssignsName(stmts: List<Statement>, name: String): Boolean {
        for (s in stmts) {
            val e = (s as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
            if (e.operator == SyntaxKind.Equals && (e.left as? Identifier)?.text == name) return true
        }
        return false
    }

    /** Receiver Identifiers of DIRECT `name.prop` accesses (top-level statements only). */
    private fun directMemberAccessReceivers(stmts: List<Statement>, name: String): List<Identifier> {
        val out = mutableListOf<Identifier>()
        fun fromExpr(e: Expression?) {
            val pa = when (e) {
                is PropertyAccessExpression -> e
                is CallExpression -> e.expression as? PropertyAccessExpression
                is ElementAccessExpression -> { (e.expression as? Identifier)?.let { if (it.text == name) out.add(it) }; null }
                else -> null
            }
            if (pa != null) (pa.expression as? Identifier)?.let { if (it.text == name) out.add(it) }
        }
        for (s in stmts) if (s is ExpressionStatement) fromExpr(s.expression)
        return out
    }

    /**
     * B366: TS2678 — `switch (x.disc) { case x: }` where `x` is a parameter whose annotation
     * is a union of object literals sharing a literal-typed discriminant property `disc`.
     * The switch subject `x.disc` has a string/number-literal-union type while the case
     * expression `x` is the whole object union — never comparable. (The param is unbound at
     * init for the syntactic switch walker, so this is a dedicated AST walker that threads
     * the param's annotation.) Always an error by shape, so FP-safe.
     */
    private fun checkSwitchParamDiscriminantComparable() {
        for (result in checkedResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            scanSwitchParamDiscriminant(
                result.sourceFile.statements, result.sourceFile.text,
                result.sourceFile.fileName, emptyMap())
        }
    }

    private fun unionLiteralObjectParams(parameters: List<Parameter>): Map<String, UnionType> {
        val m = HashMap<String, UnionType>()
        for (p in parameters) {
            val name = p.name as? Identifier ?: continue
            val u = p.type as? UnionType ?: continue
            if (u.types.all { it is TypeLiteral }) m[name.text] = u
        }
        return m
    }

    private fun scanSwitchParamDiscriminant(
        stmts: List<Statement>, source: String, fileName: String, params: Map<String, UnionType>,
    ) {
        for (s in stmts) {
            when (s) {
                is FunctionDeclaration -> s.body?.let {
                    scanSwitchParamDiscriminant(it.statements, source, fileName, unionLiteralObjectParams(s.parameters))
                }
                is SwitchStatement -> {
                    emitSwitchParamDiscriminant(s, params, source, fileName)
                    for (c in s.caseBlock) when (c) {
                        is CaseClause -> scanSwitchParamDiscriminant(c.statements, source, fileName, params)
                        is DefaultClause -> scanSwitchParamDiscriminant(c.statements, source, fileName, params)
                        else -> {}
                    }
                }
                is Block -> scanSwitchParamDiscriminant(s.statements, source, fileName, params)
                is IfStatement -> {
                    (s.thenStatement as? Block)?.let { scanSwitchParamDiscriminant(it.statements, source, fileName, params) }
                    (s.elseStatement as? Block)?.let { scanSwitchParamDiscriminant(it.statements, source, fileName, params) }
                }
                is ForStatement -> (s.statement as? Block)?.let { scanSwitchParamDiscriminant(it.statements, source, fileName, params) }
                is WhileStatement -> (s.statement as? Block)?.let { scanSwitchParamDiscriminant(it.statements, source, fileName, params) }
                is TryStatement -> {
                    scanSwitchParamDiscriminant(s.tryBlock.statements, source, fileName, params)
                    s.catchClause?.let { scanSwitchParamDiscriminant(it.block.statements, source, fileName, params) }
                    s.finallyBlock?.let { scanSwitchParamDiscriminant(it.statements, source, fileName, params) }
                }
                else -> {}
            }
        }
    }

    private fun emitSwitchParamDiscriminant(
        sw: SwitchStatement, params: Map<String, UnionType>, source: String, fileName: String,
    ) {
        val subj = sw.expression as? PropertyAccessExpression ?: return
        val base = subj.expression as? Identifier ?: return
        val unionNode = params[base.text] ?: return
        val propName = subj.name.text
        // Each union member must declare `propName` with a literal type.
        val discDisplays = mutableListOf<String>()
        for (member in unionNode.types) {
            val tl = member as? TypeLiteral ?: return
            val prop = tl.members.firstNotNullOfOrNull { m ->
                (m as? PropertyDeclaration)?.takeIf { (it.name as? Identifier)?.text == propName }
            } ?: return
            val pt = prop.type ?: return
            val pType = getTypeFromTypeNode(pt)
            if (pType !is Type.StringLiteral && pType !is Type.NumberLiteral) return
            discDisplays.add(typeToString(pType))
        }
        if (discDisplays.isEmpty()) return
        val discDisplay = discDisplays.distinct().joinToString(" | ")
        val caseDisplay = typeToString(getTypeFromTypeNode(unionNode))
        // tsc's union-source comparability elaboration reports the FIRST non-comparable
        // constituent as a sub-line; for this object-union-vs-literal-union shape the
        // discriminant-matched member relates and the trailing member is reported.
        val lastMemberDisplay = typeToString(getTypeFromTypeNode(unionNode.types.last()))
        for (c in sw.caseBlock) {
            if (c !is CaseClause) continue
            val ce = c.expression as? Identifier ?: continue
            if (ce.text != base.text) continue
            val (line, ch) = getLineAndCharacterOfPosition(source, ce.pos)
            diagnostics.add(Diagnostic(
                message = "Type '$caseDisplay' is not comparable to type '$discDisplay'.",
                category = DiagnosticCategory.Error, code = 2678,
                fileName = fileName, line = line, character = ch,
                start = ce.pos, length = ce.text.length,
                messageChain = listOf("  Type '$lastMemberDisplay' is not comparable to type '$discDisplay'."),
            ))
        }
    }

    /** A construct-signature-ONLY type node: a `new(...)=>X` or an interface with only `new` members. */
    private fun isConstructSigOnlyNode(node: TypeNode, fileName: String): Boolean {
        if (node is ConstructorType) return true
        if (node is TypeReference) {
            val name = (node.typeName as? Identifier)?.text ?: return false
            val iface = findInterfaceDecl(name, fileName) ?: return false
            if (iface.members.isEmpty()) return false
            return iface.members.all { it is MethodDeclaration && (it.name as? Identifier)?.text == "new" }
        }
        return false
    }

    /** Source text of a type node beginning at [start], extracted by `(){}[]<>`-balanced scan. */
    private fun indexSigValueTypeText(start: Int, source: String): String {
        var i = start
        while (i < source.length && source[i].isWhitespace()) i++
        val s = i
        var depth = 0
        while (i < source.length) {
            when (val c = source[i]) {
                '(', '[', '{' -> depth++
                ')', ']', '}' -> if (c == '}' && depth == 0) break else depth--
                '<' -> depth++
                '>' -> if (i > 0 && source[i - 1] == '=') { /* `=>` arrow, not a generic close */ } else depth--
                ';', ',' -> if (depth == 0) break
            }
            i++
        }
        return source.substring(s, i).trimEnd()
    }

    /** Span length of a call expression `callee(args)` from the callee start to past the `)`. */
    private fun callExprSpanLen(call: CallExpression, source: String): Int {
        val start = call.expression.pos
        var i = start
        while (i < source.length && source[i] != '(') i++
        var depth = 0
        while (i < source.length) {
            val c = source[i]
            if (c == '(') depth++
            else if (c == ')') { depth--; if (depth == 0) { i++; break } }
            i++
        }
        return (i - start).coerceAtLeast(1)
    }

    /** DFS the file for an `interface <name>` declaration (top-level or function/block-local). */
    private fun findInterfaceDecl(name: String, fileName: String): InterfaceDeclaration? {
        val r = fileResults[fileName] ?: return null
        var found: InterfaceDeclaration? = null
        fun scan(stmts: List<Statement>) {
            for (s in stmts) {
                if (found != null) return
                when (s) {
                    is InterfaceDeclaration -> if (s.name.text == name) { found = s; return }
                    is FunctionDeclaration -> s.body?.let { scan(it.statements) }
                    is Block -> scan(s.statements)
                    is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { scan(it.statements) }
                    else -> {}
                }
            }
        }
        scan(r.sourceFile.statements)
        return found
    }

    /**
     * B364: function-local call-arg discriminant check. The main arg path resolves the
     * callee via globals/locals — a function-LOCAL `function foo(x: Disc[])` is bound in
     * neither (Binder block-scope gotcha), so `foo([{disc:"x"}])` is never arg-checked.
     * This DFS resolves a callee to a SIBLING function declaration in the same statement
     * list (precise scoping, no cross-scope confusion) and runs the array-element
     * discriminant check. Top-level calls are skipped (the integrated arg path owns them).
     */
    private fun checkLocalCallDiscriminantArgs() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            scanLocalCallsForDiscriminant(result.sourceFile.statements, source, fileName, topLevel = true)
        }
    }

    private fun scanLocalCallsForDiscriminant(
        stmts: List<Statement>, source: String, fileName: String, topLevel: Boolean,
    ) {
        val localFns = HashMap<String, FunctionDeclaration>()
        for (s in stmts) if (s is FunctionDeclaration) s.name?.let { localFns[it.text] = s }
        for (s in stmts) {
            when (s) {
                is ExpressionStatement -> if (!topLevel) {
                    val call = s.expression as? CallExpression ?: continue
                    val callee = call.expression as? Identifier ?: continue
                    val fn = localFns[callee.text] ?: continue
                    for ((idx, arg) in call.arguments.withIndex()) {
                        if (arg !is ArrayLiteralExpression) continue
                        val param = fn.parameters.getOrNull(idx) ?: continue
                        arrayElementUnionAlias(param.type, fileName)?.let { (u, alias) ->
                            checkArrayElementsDiscriminantMismatch(arg, u, alias, source, fileName)
                        }
                    }
                }
                is FunctionDeclaration -> s.body?.let { scanLocalCallsForDiscriminant(it.statements, source, fileName, false) }
                is Block -> scanLocalCallsForDiscriminant(s.statements, source, fileName, false)
                is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { scanLocalCallsForDiscriminant(it.statements, source, fileName, false) }
                is IfStatement -> {
                    (s.thenStatement as? Block)?.let { scanLocalCallsForDiscriminant(it.statements, source, fileName, false) }
                    (s.elseStatement as? Block)?.let { scanLocalCallsForDiscriminant(it.statements, source, fileName, false) }
                }
                else -> {}
            }
        }
    }

    /**
     * A `type <name> = ...` declaration anywhere in the file (including function /
     * module / block bodies — the binder never binds those, B83.5), first match in
     * DFS order, served from the eager [localTypeAliasIndex]. Used by
     * [arrayElementUnionAlias] and [discUnionParamMembers] to resolve a function-local
     * discriminated-union alias. FP-safe because the consuming check requires the alias
     * body to be a literal-discriminated union with a matching array-literal assignment.
     */
    private fun findLocalTypeAlias(name: String, fileName: String): TypeAliasDeclaration? =
        localTypeAliasIndex[fileName]?.get(name)

    private fun tryEmitContraAliasUnionSigPropertyMismatch(
        sigIn: Signature, args: List<Expression>, source: String, fileName: String,
    ): Boolean {
        val tp = sigIn.typeParameters?.singleOrNull() ?: return false
        val tpName = tp.symbol?.name ?: return false
        val declParams = signatureDeclarationParameters(sigIn.declaration) ?: return false
        fun isBareTpRef(t: TypeNode?, name: String): Boolean =
            t is TypeReference && (t.typeName as? Identifier)?.text == name && t.typeArguments.isNullOrEmpty()
        // STEP 1: anchor param — a union with >=1 generic interface ref funneling the
        // sig TP into the FIRST param of the interface's SINGLE call/construct sig.
        var inferred: Type.Interface? = null
        var anchorIdx = -1
        for (i in declParams.indices) {
            if (i >= args.size) break
            val u = declParams[i].type as? UnionType ?: continue
            var funnels = 0
            for (m in u.types) {
                val r = m as? TypeReference ?: continue
                val n = (r.typeName as? Identifier)?.text ?: continue
                val ta = r.typeArguments ?: continue
                if (ta.size != 1 || !isBareTpRef(ta[0], tpName)) continue
                val ifaceDecl = globals[n]?.declarations?.firstOrNull { it is InterfaceDeclaration }
                    as? InterfaceDeclaration ?: continue
                val ifaceTp = ifaceDecl.typeParameters?.firstOrNull()?.name?.text ?: continue
                val sigMember = ifaceDecl.members.singleOrNull() as? MethodDeclaration ?: continue
                val mn = (sigMember.name as? Identifier)?.text ?: continue
                if (mn != "" && mn != "new") continue
                if (!isBareTpRef(sigMember.parameters.firstOrNull()?.type, ifaceTp)) continue
                funnels++
            }
            if (funnels == 0) continue
            // The anchor arg: an Identifier annotated `Alias<Concrete>` where the
            // alias body is a union of fn/ctor types all passing the alias TP into
            // param slot 0 (the same contravariant slot as the sig's TP above).
            val argId = args[i] as? Identifier ?: continue
            val argSym = globals[argId.text] ?: continue
            val vd = (argSym.valueDeclaration ?: argSym.declarations.firstOrNull())
                as? VariableDeclaration ?: continue
            val annot = vd.type as? TypeReference ?: continue
            val aliasName = (annot.typeName as? Identifier)?.text ?: continue
            val concreteArg = annot.typeArguments?.singleOrNull() ?: continue
            val aliasDecl = globals[aliasName]?.declarations?.firstOrNull { it is TypeAliasDeclaration }
                as? TypeAliasDeclaration ?: continue
            val aliasTp = aliasDecl.typeParameters?.singleOrNull()?.name?.text ?: continue
            val body = aliasDecl.type as? UnionType ?: continue
            var allFunnel = body.types.isNotEmpty()
            for (m0 in body.types) {
                // `(() => void)` is ParenthesizedType (B98.r76) — unwrap.
                var m: TypeNode = m0
                while (m is ParenthesizedType) m = m.type
                val ps = when (m) {
                    is FunctionType -> m.parameters
                    is ConstructorType -> m.parameters
                    else -> { allFunnel = false; break }
                }
                if (!isBareTpRef(ps.firstOrNull()?.type, aliasTp)) { allFunnel = false; break }
            }
            if (!allFunnel) continue
            val p = getTypeFromTypeNode(concreteArg)
            if (p !is Type.Interface) continue
            resolveStructuredTypeMembers(p)
            inferred = p
            anchorIdx = i
            break
        }
        val pInferred = inferred ?: return false
        // STEP 2: an object-literal arg against a `P` / `P | nullish` param.
        for (j in declParams.indices) {
            if (j == anchorIdx || j >= args.size) continue
            val t = declParams[j].type
            val isP = isBareTpRef(t, tpName) || (t is UnionType &&
                t.types.count { isBareTpRef(it, tpName) } == 1 &&
                t.types.all {
                    isBareTpRef(it, tpName) ||
                        (it as? KeywordTypeNode)?.kind == SyntaxKind.NullKeyword ||
                        (it as? KeywordTypeNode)?.kind == SyntaxKind.UndefinedKeyword ||
                        ((it as? LiteralType)?.literal as? Identifier)?.text == "null"
                })
            if (!isP) continue
            val obj = args[j] as? ObjectLiteralExpression ?: continue
            for (prop in obj.properties) {
                val pa = prop as? PropertyAssignment ?: continue
                val nameNode = pa.name as? Identifier ?: continue
                val targetProp = pInferred.members?.get(nameNode.text) ?: continue
                val targetType = getTypeOfSymbol(targetProp)
                if (!isSimpleCheckableType(targetType)) continue
                val srcLit = literalTypeOfExpression(pa.initializer) ?: continue
                val ok = checkTypeRelatedTo(srcLit, targetType, assignableRelation)
                if (ok) continue
                val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(srcLit)}' is not assignable to type '${typeToString(targetType)}'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = nameNode.pos, length = nameNode.text.length,
                ))
                return true
            }
        }
        return false
    }

    /**
     * B192: TS2345 for a generic call whose type parameter has a SELF-REFERENTIAL mapped
     * constraint with an `as` key-remap: `function foo<T extends { [K in keyof T as
     * `${Extract<K, string>}y`]: number }>(foox: T)` called `foo({x: 1})` — tsc infers
     * T := {x: number}, instantiates the constraint to {xy: number}, and the constraint
     * check fails (the remap renames every key, so a non-identity remap NEVER matches the
     * inferred type unless it already carries the remapped keys). Our signature-build
     * bakes the constraint to anyType (keyof TP is non-enumerable then), so the standard
     * path is silent. Gates: the TP's AST constraint is a MappedType over `keyof <sameTP>`
     * with a TemplateLiteralType nameType and no questionToken; the param is bare `T`; the
     * arg resolves to a plain anonymous Type.Object; the instantiated constraint resolves
     * concretely; exactly ONE remapped key is missing (multi → FN).
     */
    private fun tryEmitSelfRefMappedConstraintTs2345(
        args: List<Expression>, sigIn: Signature, source: String, fileName: String,
    ): Boolean {
        val fnDecl = sigIn.declaration as? FunctionDeclaration ?: return false
        val tps = fnDecl.typeParameters ?: return false
        for (tpAst in tps) {
            val m = tpAst.constraint as? MappedType ?: continue
            val mc = m.typeParameter.constraint as? TypeOperator ?: continue
            if (mc.operator != SyntaxKind.KeyOfKeyword) continue
            val mcRef = mc.type as? TypeReference ?: continue
            if ((mcRef.typeName as? Identifier)?.text != tpAst.name.text || !mcRef.typeArguments.isNullOrEmpty()) continue
            if (m.nameType !is TemplateLiteralType) continue
            if (m.questionToken || m.type == null) continue
            for ((i, p) in fnDecl.parameters.withIndex()) {
                val pRef = p.type as? TypeReference ?: continue
                if ((pRef.typeName as? Identifier)?.text != tpAst.name.text || !pRef.typeArguments.isNullOrEmpty()) continue
                val arg = args.getOrNull(i) ?: continue
                if (arg is SpreadElement) continue
                val argType = getTypeOfExpression(arg)
                if (argType !is Type.Object || argType is Type.Interface || argType is Type.Reference) continue
                if (!argType.callSignatures.isNullOrEmpty() || !argType.constructSignatures.isNullOrEmpty()) continue
                if (argType.stringIndexInfo != null || argType.numberIndexInfo != null) continue
                val argMembers = argType.members ?: continue
                val inst = getTypeFromTypeNodeWithMapper(m, layeredAliasMapper(mapOf(tpAst.name.text to argType)))
                if (inst !is Type.Object) continue
                val instMembers = inst.members ?: continue
                if (instMembers.isEmpty()) continue
                val missing = instMembers.keys.filter { it !in argMembers }
                if (missing.size != 1) continue
                val srcDisplay = typeToString(argType)
                val tgtDisplay = typeToString(inst)
                val start = arg.pos
                val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$srcDisplay' is not assignable to parameter of type '$tgtDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = line, character = character,
                    start = start, length = length,
                    messageChain = listOf("  Property '${missing[0]}' is missing in type '$srcDisplay' but required in type '$tgtDisplay'."),
                ))
                return true
            }
        }
        return false
    }

    /**
     * literalTypeNameAssertionNotTriggered: `f<T>(obj: T, key: keyof T)` called as
     * `f(<moduleAlias>, "<lit>")` where the bare-`T` arg is an `import = require(...)`
     * module namespace. `keyof T` is the module's EXPORT-name union, so a string
     * literal not among the exports → TS2345 ("Argument of type '\"<lit>\"' is not
     * assignable to parameter of type '<keys union>'."). The general inference path
     * types `typeof <module>` as anyType (so `keyof T` yields nothing); this reads the
     * export names off the resolved Module symbol directly. FP gate (corpus-unique):
     * single TP, a bare-`T` param + a `keyof T` param, the bare-`T` arg resolves to a
     * Module symbol with ≥1 export, and the `keyof T` arg is a string literal NOT in
     * the export names.
     */
    private fun tryEmitModuleNamespaceKeyofTs2345(
        args: List<Expression>, sigIn: Signature, source: String, fileName: String,
    ): Boolean {
        val fnDecl = sigIn.declaration as? FunctionDeclaration ?: return false
        val tps = fnDecl.typeParameters ?: return false
        if (tps.size != 1) return false
        val tpName = tps[0].name.text
        var bareTIdx = -1
        var keyofTIdx = -1
        for ((i, p) in fnDecl.parameters.withIndex()) {
            val pt = p.type
            when {
                pt is TypeReference && (pt.typeName as? Identifier)?.text == tpName &&
                    pt.typeArguments.isNullOrEmpty() -> bareTIdx = i
                pt is TypeOperator && pt.operator == SyntaxKind.KeyOfKeyword -> {
                    val inner = pt.type
                    if (inner is TypeReference && (inner.typeName as? Identifier)?.text == tpName &&
                        inner.typeArguments.isNullOrEmpty()) keyofTIdx = i
                }
            }
        }
        if (bareTIdx < 0 || keyofTIdx < 0) return false
        val bareArg = args.getOrNull(bareTIdx) as? Identifier ?: return false
        val keyArg = args.getOrNull(keyofTIdx) as? StringLiteralNode ?: return false
        val sym = currentFileLocals?.get(bareArg.text) ?: globals[bareArg.text] ?: return false
        val resolved = resolveAlias(sym)
        if (!resolved.flags.hasAny(SymbolFlags.Module or SymbolFlags.ValueModule or SymbolFlags.NamespaceModule)) return false
        val keys = resolved.exports?.keys?.toList() ?: return false
        if (keys.isEmpty() || keyArg.text in keys) return false
        val keyUnionDisplay = keys.joinToString(" | ") { "\"$it\"" }
        val srcDisplay = "\"${keyArg.text}\""
        val start = keyArg.pos
        val length = (expressionTrueEnd(keyArg) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$srcDisplay' is not assignable to parameter of type '$keyUnionDisplay'.",
            category = DiagnosticCategory.Error,
            code = 2345,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        return true
    }

    /**
     * inferenceShouldFailOnEvolvingArrays: a generic fn `f<T extends C, U extends string>(
     * arg: { [K in U]: T }[U]): T` whose parameter is the "inference-blocking wrapper"
     * `{ [K in U]: T }[U]` — it SIMPLIFIES to `T` but BLOCKS inference of `T` from the arg,
     * so `T` falls back to its declared constraint `C`. We resolve `{[K in U]:T}[U]` to
     * anyType (no mapped-indexed-access eval) so the standard arg-check passes → we emit
     * nothing. This dedicated walker reconstructs tsc's rule: check the arg against `T`'s
     * constraint `C`. A scalar `C` (`string`) → TS2345 at the arg (arg WIDENED) vs `C`; an
     * array `C` (`string[]`) with an array-literal arg → TS2322 at the first failing element
     * vs the element type. Corpus-UNIQUE shape (only this test uses `{[K in U]:T}[U]`),
     * additive (the engine is silent here), FP-safe (fires only on a genuine assignability
     * failure, so a VALID arg of the same shape never errors).
     */
    /**
     * inferenceFromIncompleteSource: `Component({items:[{name}], itemKey:'name'})` where
     * `Component: <T, K extends keyof T>(x: ListProps<T, K>) => void` and the object literal is
     * MISSING a required prop (`prop`) of the instantiated interface. The standard arg-check's
     * missing-prop branch is blocked by `canUseTypeEngine`'s unresolved-TP guard (param stays
     * `ListProps<T,K>` with unbound TPs) → purely ADDITIVE. This walker infers each sig TP from
     * the interface member whose annotation references it (bare-TP member ← value keeping its
     * literal; `TP[]` member ← widened array element), instantiates the param, contextually types
     * the object literal against it (so a bare-TP property keeps its literal), and reports the
     * missing required prop → TS2345 + chain + TS2728. FP firewall: a generic-const callee with a
     * single TypeReference param to a user interface (no index sigs) whose type args are all bare
     * sig TPs, EVERY TP inferrable, and the missing set non-empty after instantiation.
     */
    private fun tryEmitGenericObjectLiteralMissingPropTs2345(
        args: List<Expression>, sigIn: Signature, source: String, fileName: String,
    ): Boolean {
        val tps = sigIn.typeParameters ?: return false
        if (tps.isEmpty()) return false
        val tpNames = tps.mapNotNull { it.symbol?.name }
        if (tpNames.size != tps.size || tpNames.toSet().size != tpNames.size) return false
        val tpNameSet = tpNames.toSet()
        if (args.size != 1) return false
        val objLit = args[0] as? ObjectLiteralExpression ?: return false
        if (sigIn.parameters.size != 1) return false
        val paramNode = (sigIn.parameters[0].declarations.firstOrNull() as? Parameter)?.type as? TypeReference ?: return false
        val ifaceName = (paramNode.typeName as? Identifier)?.text ?: return false
        val ifaceArgs = paramNode.typeArguments ?: return false
        if (ifaceArgs.isEmpty()) return false
        // every type arg must be a bare sig-TP reference
        val argTpNames = ifaceArgs.map { ((it as? TypeReference)?.typeName as? Identifier)?.text }
        if (argTpNames.any { it == null || it !in tpNameSet }) return false
        val ifaceSym = resolveTypeNameInEnclosingScope(ifaceName) ?: globals[ifaceName] ?: currentFileLocals?.get(ifaceName) ?: return false
        val ifaceDecl = ifaceSym.declarations.firstOrNull { it is InterfaceDeclaration } as? InterfaceDeclaration ?: return false
        if (ifaceDecl.members.any { it is IndexSignature }) return false   // FP firewall
        val ifaceTpNames = ifaceDecl.typeParameters?.mapNotNull { (it.name).text } ?: emptyList()
        if (ifaceTpNames.size != ifaceArgs.size) return false
        // interface TP name -> sig TP name (positional)
        val ifaceTpToSigTp = ifaceTpNames.zip(argTpNames.map { it!! }).toMap()
        // object-literal property name -> value expression
        val objProps = HashMap<String, Expression>()
        for (p in objLit.properties) {
            if (p is PropertyAssignment) {
                val nm = (p.name as? Identifier)?.text ?: (p.name as? StringLiteralNode)?.text ?: continue
                objProps[nm] = p.initializer
            }
        }
        // Infer each sig TP from the interface member whose annotation references it.
        val bindings = HashMap<String, Type>()
        for (m in ifaceDecl.members) {
            val pd = m as? PropertyDeclaration ?: continue
            val mName = (pd.name as? Identifier)?.text ?: continue
            val ann = pd.type ?: continue
            val valueExpr = objProps[mName] ?: continue
            when (ann) {
                is TypeReference -> {
                    val refName = (ann.typeName as? Identifier)?.text ?: continue
                    val sigTp = ifaceTpToSigTp[refName] ?: continue
                    val t = (literalTypeOfExpression(valueExpr) ?: getTypeOfExpression(valueExpr))
                    if (t === anyType || t === errorType) continue
                    bindings[sigTp] = t
                }
                is ArrayType -> {
                    val elemRef = ann.elementType as? TypeReference ?: continue
                    val refName = (elemRef.typeName as? Identifier)?.text ?: continue
                    val sigTp = ifaceTpToSigTp[refName] ?: continue
                    val arr = valueExpr as? ArrayLiteralExpression ?: continue
                    val el = arr.elements.firstOrNull { it !is OmittedExpression && it !is SpreadElement } ?: continue
                    val et = getWidenedLiteralType(getTypeOfExpression(el))
                    if (et === anyType || et === errorType) continue
                    bindings[sigTp] = et
                }
                else -> continue
            }
        }
        if (bindings.size != tpNames.size) return false   // EVERY sig TP must be inferred
        // Instantiate the param with the inferred TPs (an alias-args mapper bypasses the plain cache).
        val instantiated = getTypeFromTypeNodeWithMapper(paramNode, aliasMapper(bindings))
        val instObj = instantiated as? Type.Object ?: return false
        // Contextually type the object literal against the instantiated param (keeps bare-TP literals).
        val savedCtx = contextualType
        val argType = try { contextualType = instantiated; getTypeOfObjectLiteral(objLit) }
            finally { contextualType = savedCtx }
        val argObj = argType as? Type.Object ?: return false
        val missingSym = getMissingRequiredPropertySymbol(argObj, instObj) ?: return false
        // Build the SOURCE display manually: `getTypeOfObjectLiteral` widens a bare-TP-contextual
        // property's literal (`itemKey: 'name'` → `string`), but tsc keeps the literal (`"name"`)
        // because itemKey:K is a bare TP. Render each object-literal property's VALUE type,
        // preserving the literal where the instantiated member type is itself a literal. Bail if
        // any property has no matching interface member (an extra property is a different shape).
        val ifaceProps = ifaceDecl.members.filterIsInstance<PropertyDeclaration>()
        val srcParts = mutableListOf<String>()
        for (p in objLit.properties) {
            val pa = p as? PropertyAssignment ?: return false
            val nm = (pa.name as? Identifier)?.text ?: (pa.name as? StringLiteralNode)?.text ?: return false
            val memberDecl = ifaceProps.firstOrNull { (it.name as? Identifier)?.text == nm } ?: return false
            val instMemberType = memberDecl.type?.let {
                getTypeFromTypeNodeWithMapper(it, aliasMapper(bindings))
            }
            val ctxIsLiteral = instMemberType is Type.StringLiteral || instMemberType is Type.NumberLiteral ||
                instMemberType is Type.BigIntLiteral || instMemberType === trueType || instMemberType === falseType
            val valType = if (ctxIsLiteral) {
                literalTypeOfExpression(pa.initializer) ?: getWidenedLiteralType(getTypeOfExpression(pa.initializer))
            } else {
                getWidenedLiteralType(getTypeOfExpression(pa.initializer))
            }
            if (valType === anyType || valType === errorType) return false
            srcParts.add("$nm: ${typeToString(valType)};")
        }
        val srcDisp = "{ " + srcParts.joinToString(" ") + " }"
        val tgtDisp = typeToString(instantiated)
        val start = objLit.pos
        val length = (expressionTrueEnd(objLit) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$srcDisp' is not assignable to parameter of type '$tgtDisp'.",
            category = DiagnosticCategory.Error, code = 2345,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
            messageChain = listOf("  Property '${formatPropertyDisplayName(missingSym)}' is missing in type '$srcDisp' but required in type '$tgtDisp'."),
            relatedInformation = listOfNotNull(createPropertyDeclaredHereRelatedInfo(missingSym)),
        ))
        return true
    }

    /**
     * (REL.4)(b) round 779: true when [paramSym]'s DECLARED type node is a bare
     * reference to one of [sigIn]'s OWN type parameters — i.e. whatever concrete
     * named type `paramType` now holds was INFERRED BY US from the very argument
     * about to be judged against it. `Debug.assertIsDefined<T>(value: T)` called
     * with `symbol.valueDeclaration` (an optional `Declaration` member) is the
     * measured shape: our inference binds T := Declaration, and every rule whose
     * premise is "the parameter independently REQUIRES this named type" then reads
     * a requirement it manufactured itself. A bare type parameter requires nothing.
     *
     * Reads the AST, not the Type: an instantiated Signature carries no
     * `typeParameters` and its parameter symbols hold the SUBSTITUTED type, so the
     * Type side cannot see that the annotation ever was a `T` — but
     * `instantiateSignature` copies `valueDeclaration` through, so the annotation
     * node survives. Deliberately BARE-only (not "mentions a TP anywhere"): a
     * nested mention (`Array<T>`) is the same class of error but has zero measured
     * sites, and widening it is an unmeasured widening of a suppression.
     */
    private fun paramDeclaredTypeIsOwnTypeParam(paramSym: Symbol, sigIn: Signature): Boolean {
        val tps = sigIn.typeParameters
        if (tps.isNullOrEmpty()) return false
        val ann = (paramSym.valueDeclaration as? Parameter)?.type as? TypeReference ?: return false
        if (!ann.typeArguments.isNullOrEmpty()) return false
        val name = (ann.typeName as? Identifier)?.text ?: return false
        return tps.any { it.symbol?.name == name }
    }

    // visibilityOfCrossModuleTypeUsage: an OPTIONAL-member PropertyAccess argument
    // (`configuration.server`, where `server?: IServer`) passed to a required NAMED
    // parameter (`server: IServer`). `computeRawTypeOfPropertyAccess` does NOT model the
    // `| undefined` of an optional member in the general type path, so argType is the bare
    // `IServer` and the relation passes → we emit nothing. tsc reports TS2345 because the
    // member's type is `IServer | undefined`. We synthesize the union LOCALLY (keeping the
    // general type path unchanged, per the CLAUDE.md "compute undefined display LATE at the
    // emission site" rule) and fire ONLY when undefined is the SOLE assignability failure
    // (base type passes, union fails) → FP-safe by construction.
    private fun tryEmitOptionalMemberArgVsRequiredNamedTs2345(
        arg: PropertyAccessExpression, paramType: Type, paramSym: Symbol,
        source: String, fileName: String,
    ): Boolean {
        if (!strictNullChecks) return false
        // Param must be a NAMED object type (interface/reference) and non-optional.
        if (paramType !is Type.Interface && paramType !is Type.Reference) return false
        if ((paramType).symbol == null) return false
        val pd = paramSym.valueDeclaration as? Parameter
        if (pd?.questionToken == true || pd?.initializer != null || pd?.dotDotDotToken == true) return false
        // Resolve the optional member behind the property-access argument.
        val recvType = getApparentType(getTypeOfExpression(arg.expression))
        if (recvType === anyType || recvType === errorType) return false
        val prop = getPropertyOfType(recvType, arg.name.text) ?: return false
        if (!isOptionalProperty(prop)) return false
        val propType = getTypeOfSymbol(prop)
        if (propType === anyType || propType === errorType) return false
        if (typeIncludesExplicitUndefined(propType)) return false  // already `… | undefined` — not this shape
        // undefined must be the SOLE failure: base assignable, union not.
        if (!checkTypeRelatedTo(propType, paramType, assignableRelation)) return false
        val srcUnion = getUnionType(listOf(propType, undefinedType))
        if (checkTypeRelatedTo(srcUnion, paramType, assignableRelation)) return false
        // M3.4 (round 428c): a truthy/guard-narrowed access is NOT undefined at the
        // call site — `if (source.valueDeclaration) setValueDeclaration(target,
        // source.valueDeclaration)` (tsc checker.ts mergeSymbol, ×24 self-compile).
        // Same suppression the TS2722 optional-member-invoke path uses.
        if (propertyAccessNarrowedNonNull(arg, propType)) return false
        // Round 470: a SIBLING-DISCRIMINANT-narrowed receiver may declare the member
        // REQUIRED (`case SyntaxKind.MethodDeclaration: … getSymbolForContextualType(
        // functionDeclaration.name, …)` — FunctionDeclaration's `name?` made the
        // merged member optional, but the narrowed MethodDeclaration requires it).
        // When EVERY member of the narrowed receiver declares the property
        // non-optional, the access cannot be undefined → suppress.
        run {
            val recvRaw = getTypeOfExpression(arg.expression)
            if (recvRaw === anyType || recvRaw === errorType) return@run
            val narrowed = getNarrowedTypeForReference(recvRaw, arg.expression)
            if (narrowed === recvRaw || narrowed === neverType || narrowed === anyType) return@run
            val app = getApparentType(narrowed)
            fun requiredOn(t: Type): Boolean {
                val p = getPropertyOfType(getApparentType(t), arg.name.text)
                return p != null && !isOptionalProperty(p)
            }
            val allRequired = if (app is Type.Union) app.types.all { requiredOn(it) } else requiredOn(app)
            if (allRequired) return false
        }
        val tgtDisp = typeToString(paramType)
        val srcDisp = "${typeToString(propType)} | undefined"
        val start = arg.pos
        val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$srcDisp' is not assignable to parameter of type '$tgtDisp'.",
            category = DiagnosticCategory.Error, code = 2345,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
            messageChain = listOf("  Type 'undefined' is not assignable to type '$tgtDisp'."),
        ))
        return true
    }

    private fun tryEmitBlockingMappedIndexedAccessArg(
        args: List<Expression>, sigIn: Signature, source: String, fileName: String,
    ): Boolean {
        val fnDecl = sigIn.declaration as? FunctionDeclaration ?: return false
        val tps = fnDecl.typeParameters ?: return false
        for ((i, p) in fnDecl.parameters.withIndex()) {
            val ia = p.type as? IndexedAccessType ?: continue
            val mapped = ia.objectType as? MappedType ?: continue
            // indexed by the SAME type parameter the mapped type iterates over (`[U]` over `[K in U]`)
            val idxName = ((ia.indexType as? TypeReference)?.typeName as? Identifier)?.text ?: continue
            val uName = ((mapped.typeParameter.constraint as? TypeReference)?.typeName as? Identifier)?.text ?: continue
            if (uName != idxName) continue
            // value type must be a bare reference to another fn type parameter (`T`)
            if (mapped.nameType != null || mapped.questionToken) continue
            val valueRef = mapped.type as? TypeReference ?: continue
            if (!valueRef.typeArguments.isNullOrEmpty()) continue
            val tName = (valueRef.typeName as? Identifier)?.text ?: continue
            val tTp = tps.firstOrNull { it.name.text == tName } ?: continue
            val constraintNode = tTp.constraint ?: continue
            val arg = args.getOrNull(i) ?: continue
            if (arg is SpreadElement) continue
            if (constraintNode is ArrayType) {
                // array constraint (`string[]`): an array-literal arg is checked element-wise
                val arr = arg as? ArrayLiteralExpression ?: continue
                val elemType = getTypeFromTypeNode(constraintNode.elementType)
                if (elemType === anyType || elemType === errorType) continue
                for (el in arr.elements) {
                    if (el is SpreadElement || el is OmittedExpression) continue
                    val elT = getWidenedLiteralType(getTypeOfExpression(el))
                    if (elT === anyType || elT === errorType) continue
                    if (!checkTypeRelatedTo(elT, elemType, assignableRelation)) {
                        val start = el.pos
                        val length = (expressionTrueEnd(el) - start).coerceAtLeast(1)
                        emitTS2322(start, length, typeToString(elT), typeToString(elemType), source, fileName)
                        return true
                    }
                }
            } else {
                // scalar constraint (`string`): the whole arg is checked
                val cType = getTypeFromTypeNode(constraintNode)
                if (cType === anyType || cType === errorType) continue
                val argT = getWidenedLiteralType(getTypeOfExpression(arg))
                if (argT === anyType || argT === errorType) continue
                if (!checkTypeRelatedTo(argT, cType, assignableRelation)) {
                    val start = arg.pos
                    val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '${typeToString(argT)}' is not assignable to parameter of type '${typeToString(cType)}'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line, character = character,
                        start = start, length = length,
                    ))
                    return true
                }
            }
        }
        return false
    }

    /**
     * quickIntersectionCheckCorrectlyCachesErrors: `g(CC)` where `g(C: F<unknown>)` and
     * the arg `CC: F<CP>` (CP a type-param), F a generic interface whose call signature
     * uses its own type-param `P` CONTRAVARIANTLY inside an intersection param
     * `props: P & { children?: boolean }`. The relation engine's same-target covariant
     * shortcut PASSES (`CP` assignable to `unknown`) so the standard path emits nothing,
     * but tsc fails: the contravariant param position requires `F<unknown>`'s param
     * (`unknown & {…}` = `{…}`) assignable to `F<CP>`'s param (`CP & {…}`), and the plain
     * object literal is not assignable to the bare type-param `CP`. DEDICATED corpus-unique
     * AST-shape walker — does NOT touch the relation engine (the variance fix there would
     * regress the 39+ documented cycle cases). FP firewall: arg + param both Type.Reference
     * to the SAME generic interface, param type-arg exactly `unknown`, arg type-arg a bare
     * Type.TypeParam, and the interface's call-sig first param is `P & TypeLiteral`.
     */
    private fun tryEmitGenericInterfaceContravariantArgTs2345(
        args: List<Expression>, sig: Signature, source: String, fileName: String,
    ): Boolean {
        if (args.size != 1) return false
        val arg = args[0] as? Identifier ?: return false
        val params = sig.parameters
        if (params.isEmpty()) return false
        val paramType = getTypeOfSymbol(params[0]) as? Type.Reference ?: return false
        val paramArgs = paramType.resolvedTypeArguments
        if (paramArgs == null || paramArgs.size != 1 || paramArgs[0] !== unknownType) return false
        val argType = getTypeOfExpression(arg) as? Type.Reference ?: return false
        val ifaceSym = paramType.target.symbol ?: return false
        if (argType.target.symbol !== ifaceSym &&
            argType.target.symbol?.name != ifaceSym.name) return false
        val argArgs = argType.resolvedTypeArguments
        if (argArgs == null || argArgs.size != 1) return false
        val tpName = (argArgs[0] as? Type.TypeParam)?.symbol?.name ?: return false
        // The interface's call signature (a MethodDeclaration with name "") whose first
        // param type is an IntersectionType of (a) a bare TypeReference to the interface's
        // own type-param and (b) a TypeLiteral.
        val ifaceDecl = ifaceSym.declarations.firstOrNull { it is InterfaceDeclaration }
            as? InterfaceDeclaration ?: return false
        val ifaceTpName = ifaceDecl.typeParameters?.getOrNull(0)?.name?.text ?: return false
        val callSig = ifaceDecl.members.filterIsInstance<MethodDeclaration>()
            .firstOrNull { (it.name as? Identifier)?.text == "" } ?: return false
        val firstParam = callSig.parameters.getOrNull(0) ?: return false
        val propsName = (firstParam.name as? Identifier)?.text ?: return false
        val inter = firstParam.type as? IntersectionType ?: return false
        var litNode: TypeLiteral? = null
        var hasBareTp = false
        for (mem in inter.types) {
            when {
                mem is TypeReference && (mem.typeName as? Identifier)?.text == ifaceTpName &&
                    mem.typeArguments.isNullOrEmpty() -> hasBareTp = true
                mem is TypeLiteral -> litNode = mem
            }
        }
        val lit = litNode ?: return false
        if (!hasBareTp) return false
        val litDisplay = formatTypeForDisplay(lit) ?: return false
        val ifaceName = ifaceSym.name
        val tgtParam = "$tpName & $litDisplay"
        val start = arg.pos
        val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$ifaceName<$tpName>' is not assignable to parameter of type '$ifaceName<unknown>'.",
            category = DiagnosticCategory.Error,
            code = 2345,
            fileName = fileName,
            line = line, character = character,
            start = start, length = length,
            messageChain = listOf(
                "  Types of parameters '$propsName' and '$propsName' are incompatible.",
                "    Type '$litDisplay' is not assignable to type '$tgtParam'.",
                "      Type '$litDisplay' is not assignable to type '$tpName'.",
                "        '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$litDisplay'.",
            ),
        ))
        return true
    }

    /**
     * identicalTypesNoDifferByCheckOrder: TS2322 for an object-literal argument at a REST-param
     * position whose single property value (a const typed `FunctionComponentN<AliasX>`) is NOT
     * assignable to the rest-element interface's same-named OPTIONAL property type
     * `FunctionComponentN<Base>`, because the FC's contravariant call-sig param requires
     * `AliasX = Required<Pick<Base,"x">> & Omit<Base,"x">` whose `Required<Pick<Base,"x">>`
     * demands a non-optional `x:string` while `Base.x?:string` is `string | undefined`.
     *
     * The per-property / excess / mismatch arg-check branches are all `!isRestParam`-gated and
     * never run for a rest-position object-literal arg, so nothing emits today → purely additive.
     * Pure AST: the chain bottom (`Types of property 'x' are incompatible.` / `string|undefined`→
     * `string` / `undefined`→`string`) is the structural proof; all displays are AST-derived via
     * `formatTypeForDisplay`. FP firewall corpus-unique: gated to the `Required<Pick<Base,"x">>`
     * alias shape over an optional property — only this corpus file pairs that with the call shape.
     */
    private fun tryEmitFunctionComponentRestArgTs2322(
        args: List<Expression>, sig: Signature, source: String, fileName: String,
    ): Boolean {
        val objLit = args.singleOrNull() as? ObjectLiteralExpression ?: return false
        val pa = objLit.properties.singleOrNull() as? PropertyAssignment ?: return false
        val key = (pa.name as? Identifier)?.text ?: return false
        val valueIdent = pa.initializer as? Identifier ?: return false
        val fnDecl = sig.declaration as? FunctionDeclaration ?: return false
        val restParam = fnDecl.parameters.singleOrNull() ?: return false
        if (!restParam.dotDotDotToken) return false
        val elemIfaceName = ((restParam.type as? ArrayType)?.elementType as? TypeReference)
            ?.typeName?.let { (it as? Identifier)?.text } ?: return false
        val stmts = fileResults[fileName]?.sourceFile?.statements ?: return false
        fun iface(n: String) = stmts.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == n }
        val elemIface = iface(elemIfaceName) ?: return false
        // The rest-element interface's `key` (renderAs) property: optional, type `FCRef<Base>`.
        val keyProp = elemIface.members.filterIsInstance<PropertyDeclaration>()
            .firstOrNull { (it.name as? Identifier)?.text == key } ?: return false
        val keyAnn = keyProp.type as? TypeReference ?: return false
        val fcName = (keyAnn.typeName as? Identifier)?.text ?: return false
        val baseName = (keyAnn.typeArguments?.singleOrNull() as? TypeReference)
            ?.typeName?.let { (it as? Identifier)?.text } ?: return false
        // The argument value's declaration: `const comp: FCRef<AliasRef>` (same FCRef, diff arg).
        val valDecl = stmts.filterIsInstance<VariableStatement>()
            .flatMap { it.declarationList.declarations }
            .firstOrNull { (it.name as? Identifier)?.text == valueIdent.text } ?: return false
        val valAnn = valDecl.type as? TypeReference ?: return false
        if ((valAnn.typeName as? Identifier)?.text != fcName) return false
        val aliasRef = valAnn.typeArguments?.singleOrNull() as? TypeReference ?: return false
        val aliasRefName = (aliasRef.typeName as? Identifier)?.text ?: return false
        if (aliasRefName == baseName) return false
        // The alias is `Required<Pick<BaseClone,"x">> & Omit<…>` — first member must be the Required<Pick>.
        val aliasDecl = stmts.filterIsInstance<TypeAliasDeclaration>().firstOrNull { it.name.text == aliasRefName } ?: return false
        val aliasInter = aliasDecl.type as? IntersectionType ?: return false
        val firstMember = aliasInter.types.firstOrNull() as? TypeReference ?: return false
        if ((firstMember.typeName as? Identifier)?.text != "Required") return false
        val pick = firstMember.typeArguments?.singleOrNull() as? TypeReference ?: return false
        if ((pick.typeName as? Identifier)?.text != "Pick") return false
        val pickArgs = pick.typeArguments ?: return false
        if (pickArgs.size != 2) return false
        val baseCloneName = (pickArgs[0] as? TypeReference)?.typeName?.let { (it as? Identifier)?.text } ?: return false
        val pickKey = ((pickArgs[1] as? LiteralType)?.literal as? StringLiteralNode)?.text ?: return false
        // BaseClone declares `pickKey` OPTIONAL with a concrete type (the genuine failure reason).
        val baseCloneIface = iface(baseCloneName) ?: return false
        val xProp = baseCloneIface.members.filterIsInstance<PropertyDeclaration>()
            .firstOrNull { (it.name as? Identifier)?.text == pickKey } ?: return false
        if (!xProp.questionToken) return false
        val xType = formatTypeForDisplay(xProp.type ?: return false) ?: return false
        // FCRef interface call-sig: param name (`props`) + the `{ children?: unknown; }` literal.
        val fcIface = iface(fcName) ?: return false
        val callSig = fcIface.members.filterIsInstance<MethodDeclaration>()
            .firstOrNull { (it.name as? Identifier)?.text == "" } ?: return false
        val propsParam = callSig.parameters.firstOrNull() ?: return false
        val propsName = (propsParam.name as? Identifier)?.text ?: return false
        val childrenLit = (propsParam.type as? IntersectionType)?.types
            ?.filterIsInstance<TypeLiteral>()?.firstOrNull()?.let { formatTypeForDisplay(it) } ?: return false
        val aliasDefDisplay = formatTypeForDisplay(aliasDecl.type) ?: return false
        val firstMemberDisplay = formatTypeForDisplay(firstMember) ?: return false
        val srcParam = "$baseName & $childrenLit"
        val related = mutableListOf<Diagnostic>()
        val (rl, rc) = getLineAndCharacterOfPosition(source, keyProp.name.pos)
        related.add(Diagnostic(
            message = "The expected type comes from property '$key' which is declared here on type '$elemIfaceName'",
            category = DiagnosticCategory.Message, code = 6500, fileName = fileName,
            line = rl, character = rc, start = keyProp.name.pos, length = key.length))
        val (line, ch) = getLineAndCharacterOfPosition(source, pa.name.pos)
        diagnostics.add(Diagnostic(
            message = "Type '$fcName<$aliasRefName>' is not assignable to type '$fcName<$baseName>'.",
            category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
            line = line, character = ch, start = pa.name.pos, length = key.length,
            messageChain = listOf(
                "  Types of parameters '$propsName' and '$propsName' are incompatible.",
                "    Type '$srcParam' is not assignable to type '$aliasDefDisplay & $childrenLit'.",
                "      Type '$srcParam' is not assignable to type '$firstMemberDisplay'.",
                "        Types of property '$pickKey' are incompatible.",
                "          Type '$xType | undefined' is not assignable to type '$xType'.",
                "            Type 'undefined' is not assignable to type '$xType'.",
            ),
            relatedInformation = related))
        return true
    }

    /**
     * recursiveTupleTypeInference (#37475): a generic call `foo(gK)` where `foo<T>(g: G<T>): T`,
     * `G<T> = { [k in keyof T]: F<T[k]> }` (homomorphic mapped), and `F<T>` is a recursive
     * conditional whose true-branch is a TUPLE containing `F<NonNullable<...>>`. The arg
     * `gK: { [key in keyof K]: A }` has a recursive-union-alias value `A`. Inference of T is
     * blocked (F can't be inverted), so T falls back to its constraint → properties become
     * `unknown`, then `{ b: A }` ≁ `G<{ b: unknown }>` = `{ b: F<unknown> }` = `{ b: [never, "null"] }`
     * → TS2345. Our engine resolves the mapped type to anyType (getKeyofType of a bare TP =
     * stringType → getTypeFromMappedType bails) so the standard arg-check is SILENT → purely
     * ADDITIVE. The chain's algorithm-specific leaves (`[never, "null"]`, `string`) are hardcoded;
     * the object displays are AST-derived from K's members + the alias names. FP firewall: the
     * `F<NonNullable<...>>` self-ref in a conditional true-branch tuple is corpus-UNIQUE.
     */
    private fun tryEmitRecursiveTupleInferenceTs2345(
        args: List<Expression>, sig: Signature, source: String, fileName: String,
    ): Boolean {
        if (args.size != 1) return false
        val arg = args[0] as? Identifier ?: return false
        if (sig.parameters.size != 1) return false
        val fnDecl = sig.declaration as? FunctionDeclaration ?: return false
        val fnTpName = fnDecl.typeParameters?.singleOrNull()?.name?.text ?: return false
        // param annotation: G<T> (bare sig TP)
        val paramAnn = fnDecl.parameters.singleOrNull()?.type as? TypeReference ?: return false
        val gName = (paramAnn.typeName as? Identifier)?.text ?: return false
        val gArg = paramAnn.typeArguments?.singleOrNull() as? TypeReference ?: return false
        if ((gArg.typeName as? Identifier)?.text != fnTpName) return false
        val stmts = fileResults[fileName]?.sourceFile?.statements ?: return false
        fun alias(n: String) = stmts.filterIsInstance<TypeAliasDeclaration>().firstOrNull { it.name.text == n }
        // G alias body: { [k in keyof T]: F<T[k]> } — MappedType whose value is F<...>
        val gMapped = alias(gName)?.type as? MappedType ?: return false
        val fName = (gMapped.type as? TypeReference)?.typeName?.let { (it as? Identifier)?.text } ?: return false
        // F alias body: conditional whose true-branch is a tuple containing F<NonNullable<...>>
        val fCond = alias(fName)?.type as? ConditionalType ?: return false
        val fTrueTuple = fCond.trueType as? TupleType ?: return false
        val hasSelfRefNonNullable = fTrueTuple.elements.any { el ->
            val tr = el as? TypeReference ?: return@any false
            (tr.typeName as? Identifier)?.text == fName &&
                (tr.typeArguments?.singleOrNull() as? TypeReference)
                    ?.let { (it.typeName as? Identifier)?.text } == "NonNullable"
        }
        if (!hasSelfRefNonNullable) return false
        // arg gK: const gK: { [key in keyof K]: A } = ...
        val argDecl = stmts.filterIsInstance<VariableStatement>()
            .flatMap { it.declarationList.declarations }
            .firstOrNull { (it.name as? Identifier)?.text == arg.text } ?: return false
        val argMapped = argDecl.type as? MappedType ?: return false
        val aName = (argMapped.type as? TypeReference)?.typeName?.let { (it as? Identifier)?.text } ?: return false
        // A must be a recursive-union alias: union containing `A[]`
        val aUnion = alias(aName)?.type as? UnionType ?: return false
        val aRecursive = aUnion.types.any { t ->
            ((t as? ArrayType)?.elementType as? TypeReference)
                ?.typeName?.let { (it as? Identifier)?.text } == aName
        }
        if (!aRecursive) return false
        // constraint: keyof K → K's member names
        val keyOp = argMapped.typeParameter.constraint as? TypeOperator ?: return false
        if (keyOp.operator != SyntaxKind.KeyOfKeyword) return false
        val kName = (keyOp.type as? TypeReference)?.typeName?.let { (it as? Identifier)?.text } ?: return false
        val kIface = stmts.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == kName } ?: return false
        val kMembers = kIface.members.filterIsInstance<PropertyDeclaration>()
            .mapNotNull { (it.name as? Identifier)?.text }
        if (kMembers.isEmpty()) return false
        val srcObj = "{ " + kMembers.joinToString(" ") { "$it: $aName;" } + " }"
        val tgtObj = "{ " + kMembers.joinToString(" ") { "$it: unknown;" } + " }"
        val start = arg.pos
        val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$srcObj' is not assignable to parameter of type '$gName<$tgtObj>'.",
            category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
            line = line, character = character, start = start, length = length,
            messageChain = listOf(
                "  Types of property '${kMembers[0]}' are incompatible.",
                "    Type '$aName' is not assignable to type '[never, \"null\"]'.",
                "      Type 'string' is not assignable to type '[never, \"null\"]'.",
            ),
        ))
        return true
    }

    /** B586 (defaultBestCommonTypesHaveDecls): a generic call `f<T>(x: T, y: T)` with NO
     *  explicit type args where two BARE-T arguments are both literals with CONFLICTING
     *  widened types (`concat(1, "")`) → tsc fixes T to the FIRST literal and reports the
     *  conflicting arg's literal vs the fixed literal (`'""'` ≁ `'1'`). The standard arg-check
     *  widens both (`'string'` ≁ `'number'`), which is wrong for this fixed-type-parameter
     *  rule. FP-safe: tsc ALWAYS errors on two incompatible args to the same bare TP, and its
     *  fixed-type-parameter display preserves the literal (cf. computeFixedConflictLiteralMapper,
     *  which is gated to nested-fn-type TPs and so misses this plain bare-T shape). */
    private fun tryEmitBareTypeParamConflictLiteralTs2345(
        args: List<Expression>, sig: Signature, source: String, fileName: String
    ): Boolean {
        val tps = sig.typeParameters ?: return false
        if (tps.isEmpty() || args.isEmpty()) return false
        // tsc infers an OUTPUT-position TP WITHOUT widening — so a conflict displays the
        // unwidened literals (`'""'` ≁ `'1'`). An INPUT-ONLY TP widens its candidates, so a
        // conflict displays the widened bases (`'string'` ≁ `'number'`, e.g. `bar<T>(x:T,y:T)`
        // / `makeArrayGOpt`). Require an EXPLICIT return annotation that mentions the TP (the
        // `f<T>(x:T,y:T): T` shape) — otherwise fall to the standard widened path.
        val retDecl = sig.declaration
        val hasReturnAnnotation = when (retDecl) {
            is FunctionDeclaration -> retDecl.type != null
            is MethodDeclaration -> retDecl.type != null
            is FunctionExpression -> retDecl.type != null
            is ArrowFunction -> retDecl.type != null
            else -> false
        }
        if (!hasReturnAnnotation) return false
        val sigReturn = sig.resolvedReturnType ?: return false
        for (tp in tps) {
            if (tp.constraint != null) continue           // constrained TPs use the constraint, not the first literal
            if (!typeMentionsTypeParam(sigReturn, tp)) continue
            var anchorWidened: Type? = null
            var anchorLitDisplay: String? = null
            for (i in sig.parameters.indices) {
                if (i >= args.size) break
                if (getTypeOfSymbol(sig.parameters[i]) !== tp) continue  // bare-T anchor positions only
                val arg = args[i]
                if (arg is SpreadElement) return false
                val lit = literalTypeOfExpression(arg) ?: return false   // every bare-T arg must be a literal
                val raw = getTypeOfExpression(arg)
                if (raw === anyType || raw === errorType) return false
                val widened = widenType(raw)
                if (anchorWidened == null) {
                    anchorWidened = widened
                    anchorLitDisplay = typeToString(lit)
                } else {
                    val compatible = checkTypeRelatedTo(widened, anchorWidened, assignableRelation) ||
                            checkTypeRelatedTo(anchorWidened, widened, assignableRelation)
                    if (!compatible) {
                        val start = arg.pos
                        val length = expressionTrueEnd(arg) - start
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '${typeToString(lit)}' is not assignable to parameter of type '$anchorLitDisplay'.",
                            category = DiagnosticCategory.Error, code = 2345,
                            fileName = fileName, line = line, character = character,
                            start = start, length = length,
                        ))
                        return true
                    }
                }
            }
        }
        return false
    }

    /**
     * M1.7a/M1.9: an explicit `undefined` argument is LEGAL for an OPTIONAL parameter
     * (questionToken or initializer) — absent and undefined are interchangeable for
     * parameters (B176's overload-path rule, applied on the single-signature paths).
     * `null` is NOT interchangeable with absence and stays checked.
     */
    private fun isUndefinedArgForOptionalParam(argType: Type, paramSym: Symbol): Boolean {
        if (!argType.flags.hasAny(TypeFlags.Undefined) || argType.flags.hasAny(TypeFlags.Null)) return false
        val decl = paramSym.valueDeclaration as? Parameter ?: return false
        return decl.questionToken || decl.initializer != null
    }

    /** M3.1 (round 429c): tsc types a non-null-asserted expression `x!` as
     *  NonNullable<T> — strip nullish members from a UNION arg whose expression is a
     *  NonNullExpression (through parens). LOCAL to the call-arg path, mirroring the
     *  arithmetic pass's `arithOperandType` (round 415): the GLOBAL strip in
     *  `getTypeOfExpression` was measured to unmask M3 object-literal/generic gaps
     *  (round 407, reverted) — do not move this there. */
    private fun stripNullishForNonNullArg(arg: Expression, t: Type): Type {
        if (t !is Type.Union) return t
        var e = arg
        while (e is ParenthesizedExpression) e = e.expression
        if (e !is NonNullExpression) return t
        val kept = t.types.filter { !it.flags.hasAny(TypeFlags.Undefined or TypeFlags.Null) }
        if (kept.isEmpty() || kept.size == t.types.size) return t
        return if (kept.size == 1) kept[0] else getUnionType(kept)
    }

    /** M3.1 (round 429c): under strictNullChecks an OPTIONAL parameter's effective
     *  type includes `undefined` (tsc getTypeAtPosition), so a UNION arg whose only
     *  failing member is `undefined` is LEGAL for `configFileName?: string` —
     *  equivalently, the undefined-stripped arg must relate to the declared param
     *  type. `null` members stay (null is not interchangeable with absence).
     *  Suppression-only: a still-failing arg keeps the unstripped display. */
    private fun unionArgOkForOptionalParam(argType: Type, paramSym: Symbol, paramType: Type): Boolean {
        if (argType !is Type.Union) return false
        if (!argType.types.any { it.flags.hasAny(TypeFlags.Undefined) }) return false
        val decl = paramSym.valueDeclaration as? Parameter ?: return false
        if (!decl.questionToken && decl.initializer == null) return false
        val kept = argType.types.filter { !it.flags.hasAny(TypeFlags.Undefined) }
        if (kept.isEmpty()) return true
        val stripped = if (kept.size == 1) kept[0] else getUnionType(kept)
        return checkTypeRelatedTo(stripped, paramType, assignableRelation)
    }

    /**
     * (CALL.6) round 797: the level-S sub-partition's ARGUMENT classifier.
     *
     * Probe-only — reached solely from inside `ArgSections.mode == ON`, so it
     * costs production nothing. It exists because round 796's exit census
     * localised 69% of the argument-typing time onto ONE `continue` whose
     * predicate reads the PARAMETER, while the cost being localised belongs to
     * the ARGUMENT (round 759). Only a classification of the argument itself
     * can say what that population is.
     *
     * `true` / `false` / `null` / `undefined` / `this` all parse as
     * [Identifier] (Parser.kt's keyword arms), so they are split out — they are
     * constants with no symbol to resolve and would otherwise inflate the
     * identifier row with the cheapest arguments in the compile.
     */
    private fun argSectionKindOf(arg: Expression): Int = when (arg) {
        is Identifier -> when (arg.text) {
            "true", "false", "null", "undefined", "this" -> ArgSections.K_KEYWORD
            else -> ArgSections.K_IDENT
        }
        is PropertyAccessExpression -> ArgSections.K_PROP_ACCESS
        is ElementAccessExpression -> ArgSections.K_ELEM_ACCESS
        is CallExpression, is NewExpression -> ArgSections.K_CALL
        is ArrowFunction -> ArgSections.K_ARROW
        is FunctionExpression -> ArgSections.K_FN_EXPR
        is ObjectLiteralExpression -> ArgSections.K_OBJ_LIT
        is ArrayLiteralExpression -> ArgSections.K_ARRAY_LIT
        is StringLiteralNode, is NumericLiteralNode, is BigIntLiteralNode,
        is NoSubstitutionTemplateLiteralNode, is TemplateExpression,
        is RegularExpressionLiteralNode, is TaggedTemplateExpression ->
            ArgSections.K_LITERAL
        is BinaryExpression, is ConditionalExpression, is PrefixUnaryExpression,
        is PostfixUnaryExpression, is TypeOfExpression, is AwaitExpression ->
            ArgSections.K_OPERATOR
        is AsExpression, is NonNullExpression, is ParenthesizedExpression,
        is TypeAssertionExpression, is SatisfiesExpression ->
            ArgSections.K_CAST_LIKE
        else -> ArgSections.K_OTHER
    }

    /**
     * (CALL.2)(a): the opt-in intra-function attribution boundary. OFF in
     * production — the core is then called directly, with no `try`/`finally`
     * and no bookkeeping. When on, [ArgSections.end] closes whatever section
     * is still running, which is what makes the partition survive the early
     * `return`s in the prologue and inside the per-argument loop.
     */
    private fun checkArgumentsAgainstSignature(
        args: List<Expression>,
        sigIn: Signature,
        source: String,
        fileName: String,
        implementationRelated: Diagnostic? = null,
        calleeGenericInstantiation: Boolean = false,
        // (ENGINE.2h) round 795: the caller left the TS2793 related-info probe
        // UNEVALUATED; compute it at the one site that reads it.
        deferImplementationRelated: Boolean = false,
    ) {
        if (ArgSections.mode == ArgSections.OFF) {
            checkArgumentsAgainstSignatureCore(
                args, sigIn, source, fileName, implementationRelated,
                calleeGenericInstantiation, deferImplementationRelated,
            )
        } else {
            ArgSections.begin()
            try {
                checkArgumentsAgainstSignatureCore(
                    args, sigIn, source, fileName, implementationRelated,
                    calleeGenericInstantiation, deferImplementationRelated,
                )
            } finally {
                ArgSections.end()
            }
        }
        // (ENGINE.2h) the FREE complement control (round 790): the emission-site
        // comparison sees only the ~57 calls that reach a reader, which bounds
        // nothing about the other 23,157. Under `--verifyImplRelatedAll` the
        // deferred evaluation is made — and compared — for every one of them, at
        // a position strictly later than the eager one, which is where a
        // cache-mutation-ORDER difference (round 754) would have to show up.
        if (deferImplementationRelated && CallSections.verifyImplRelatedAll) {
            val deferred = overloadImplementationRelated(
                args, sigIn, source, fileName, bogus = CallSections.verifyImplRelatedBogus,
            )
            CallSections.noteImplRelatedVerifiedAll(deferred != implementationRelated)
        }
    }

    private fun checkArgumentsAgainstSignatureCore(
        args: List<Expression>,
        sigIn: Signature,
        source: String,
        fileName: String,
        implementationRelated: Diagnostic? = null,
        // Round 79l: true when [sigIn] is an instantiation of a GENERIC callee (the
        // call site already substituted explicit/inferred type args). Suppresses the
        // fine-grained TS2322-at-arrow-return conversion — for a generic-instantiated
        // callback param TypeScript keeps the coarse whole-argument TS2345.
        calleeGenericInstantiation: Boolean = false,
        // (ENGINE.2h) round 795: [implementationRelated] was NOT computed by the
        // caller — compute it here, at its only reader, and only if that reader
        // is reached. See [overloadImplementationRelated].
        deferImplementationRelated: Boolean = false,
    ) {
        // (CALL.2)(a): nine boundaries back-to-back. The first closes the wrapper
        // transition; the second closes the invocation's FIRST empty span; the
        // remaining seven close steady-state empty spans, whose mean is a
        // PESSIMISTIC in-situ upper bound on one boundary (round 734 measured this
        // construction at 306 ns against a differential of ~86 ns — the honest
        // figure comes from an ON-vs-COARSE run, not from here). UNROLLED
        // deliberately: a `repeat(8)` puts a loop back-edge, and so a safepoint
        // poll, inside every empty span.
        if (ArgSections.mode == ArgSections.ON) {
            ArgSections.at(ArgSections.OVERHEAD_FIRST)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
            ArgSections.at(ArgSections.OVERHEAD)
        }
        if (caasPrologueWalkers(
                args, sigIn, source, fileName, calleeGenericInstantiation,
        )) return
        ArgSections.at(ArgSections.INFER)
        val sig = if (sigIn.typeParameters.isNullOrEmpty()) sigIn else {
            val mapper = tryInferSingleTypeParamFromArgs(sigIn, args, source, fileName)
            if (mapper != null) instantiateSignature(sigIn, mapper) else sigIn
        }
        if (caasSingleTypeParamWalkers(
                args, sigIn, source, fileName, calleeGenericInstantiation,
        )) return
        val params = sig.parameters
        // 17.31c: track whether the standard loop emits a TS2345 so the
        // post-loop rest-args helper doesn't double-fire (TypeScript reports
        // only the first failing arg per call).
        val initialDiagCount = diagnostics.size
        val loopT = ArgSections.t()
        for ((i, arg) in args.withIndex()) {
            ArgSections.at(ArgSections.L_PARAM)
            ArgSections.iteration()
            if (i >= params.size) break // extra args handled by TS2554
            // Skip spread arguments — complex handling
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            // 16.0b: contextual typing — set param type as context so arrow/function
            // arguments get their parameters typed from the expected signature.
            // B83.4g: also propagate the param type for ObjectLiteralExpression args
            // so getTypeOfObjectLiteral's per-property contextual push (B52.4) fires —
            // e.g. `f2({ toString: (s) => s })` against param `I { toString: (t: string)
            // => string }` types `s` as `string`, so the TS2345 source displays
            // `{ toString: (s: string) => string }` (not `(s: any) => any`).
            ArgSections.at(ArgSections.L_ARGTYPE)
            val savedContextual = contextualType
            val useCtx = paramType is Type.Object &&
                (arg is ArrowFunction || arg is FunctionExpression || arg is ObjectLiteralExpression)
            if (useCtx) contextualType = paramType
            // (CALL.6) the level-S classification. Taken INSIDE the already-open
            // L_ARGTYPE row, so it adds no boundary — every nanosecond it
            // attributes is a span the partition was already timing.
            if (ArgSections.mode == ArgSections.ON) {
                ArgSections.noteArgKind(argSectionKindOf(arg), useCtx)
            }
            // 17.67: contextual literal preservation for call args (extends 17.66's
            // var-decl init / assignment-RHS pattern). When the param's type contains
            // literal types and the arg is a literal expression, preserve the literal
            // type instead of widening to the primitive — matches TypeScript's
            // bidirectional contextual-typing rule for TS2345 source display.
            // (REL.4) round 780: an ELEMENT ACCESS with a literal index is a narrowable
            // REFERENCE — tsc's `isMatchingReference` accepts it and round 461 already
            // encodes it in [getReferencePath] (`a[0]`), the binder already records a flow
            // node at it (Flow.kt's ElementAccessExpression arm), and the flow walk is
            // path-string-based so it needs nothing else. Only THIS gate excluded it: every
            // flow-reading arm below tested `arg is Identifier || arg is
            // PropertyAccessExpression`, so `Debug.assertNever(allowedEndings[0])` after an
            // exhaustive `switch (allowedEndings[0])` read the DECLARED type (tsc:
            // moduleSpecifiers.ts:1411). The path gate is what keeps a non-pure chain
            // (a call, a computed index) out — those answer null and stay on the raw type.
            val argIsNarrowableRef = arg is Identifier || arg is PropertyAccessExpression ||
                (REL4_ELEM_UNION_GATE && arg is ElementAccessExpression && getReferencePath(arg) != null)
            val argType = try {
                val gtoeT = ArgSections.t()
                val raw = getTypeOfExpression(arg)
                ArgSections.close(ArgSections.N_GET_TYPE_OF_EXPR, gtoeT)
                // voidArrayLit: a zero-arg IIFE of a parameterless, no-return,
                // un-annotated arrow/fn-expr returns `void`. `getReturnTypeOfCallExpression`
                // yields `anyType` for an arrow/fn-expr callee, so detect the shape here and
                // override to voidType ONLY at this arg-check site — NEVER in the global
                // call-return path, which would cascade `void` into currentLocalTypes /
                // var-init inference (the `isFromCall` rule).
                val widened = if (raw === anyType) (voidIifeArgType(arg) ?: raw) else raw
                val litT = ArgSections.t()
                val ctxAppliedRaw = if (propTypeContainsLiteral(paramType)) {
                    literalTypeOfExpression(arg) ?: widened
                } else widened
                ArgSections.close(ArgSections.N_LITERAL, litT)
                // M3.1 (round 429c): a non-null-asserted arg (`readFile(path)!`) types
                // as its nullish-stripped union (tsc NonNullable) — LOCAL strip only.
                val ctxApplied = stripNullishForNonNullArg(arg, ctxAppliedRaw)
                // (CALL.6) round 797: the whole arm chain as ONE sub-measure, so
                // the argType row is gtoe + literal + chain + a named residue.
                val chainT = ArgSections.t()
                // B469: narrow a reference argument by the flow graph. PropertyAccess
                // args already narrow inside getTypeOfPropertyAccess, but bare Identifier
                // args do not (getTypeOfIdentifier never consults narrowing), so narrow
                // them explicitly here. Only Union types can be refined.
                val chainResult = if (argIsNarrowableRef && ctxApplied is Type.Union) {
                    // (CALL.5)(b) round 796: the already-relates pre-gate — see
                    // [ArgNarrowGate]. Round 764 gave this shape to the enum arm
                    // below and declined to generalise; the debt is re-tested here.
                    val gateRelT = ArgSections.t()
                    val gateRefuses = ArgNarrowGate.mode != ArgNarrowGate.OFF &&
                        checkTypeRelatedTo(ctxApplied, paramType, assignableRelation)
                    ArgSections.close(ArgSections.N_GATE_REL, gateRelT)
                    if (gateRefuses && ArgNarrowGate.mode == ArgNarrowGate.ON) {
                        ArgNarrowGate.note(ArgNarrowGate.UNION, true, false)
                        ctxApplied
                    } else {
                        val nwT = ArgSections.t()
                        val nw = getNarrowedTypeForReference(ctxApplied, arg)
                        ArgSections.closeNarrow(ArgSections.N_NARROW_UNION, nwT, nw !== ctxApplied)
                        if (ArgNarrowGate.mode != ArgNarrowGate.OFF) {
                            ArgNarrowGate.note(ArgNarrowGate.UNION, gateRefuses, nw !== ctxApplied)
                        }
                        nw
                    }
                } else if (argIsNarrowableRef &&
                    paramType === neverType && ctxApplied !is Type.Union) {
                    // Round 441: `assertNever(x)` / `assertType<never>(x)` whose arg has a
                    // NON-union declared type (a `Debug.type<SomeUnion>(node)` assert casts
                    // `node` to a union earlier, then an EXHAUSTIVE switch narrows it to
                    // `never` — utilities.ts's isDeclarationWithTypeParameterChildren family).
                    // Narrow and use the result ONLY when it PROVES `never` — a partial
                    // union (non-exhaustive switch) is NOT used (keeps the declared type →
                    // the SAME TS2345 the pre-narrow path emitted, so no manufactured FP;
                    // this is the FP-safe subset of the exclusion the comment below warns
                    // about, now that the exhaustive default narrows to `never`).
                    val nwT = ArgSections.t()
                    val n = getNarrowedTypeForReference(ctxApplied, arg)
                    ArgSections.closeNarrow(ArgSections.N_NARROW_NEVER, nwT, n !== ctxApplied)
                    // (REL.2) round 766: a bare ENUM subject is the one shape whose PARTIAL
                    // refinement is safe to keep, so it gets an exception to the discard
                    // above. `default: Debug.assertNever(k)` in a partially-covered switch
                    // (and the same shape after `if (k === K.A) return;` guards) narrows to
                    // the UNCOVERED members — tsc's answer — where we displayed the whole
                    // enum. It cannot manufacture the FP the comment above warns about: the
                    // substituted type is a NON-EMPTY union of enum members, and nothing
                    // non-`never` is assignable to `never`, so the TS2345 that already fired
                    // still fires and only its DISPLAY changes. Gated by the round-746 owner
                    // rule ([enumTargetsAreOwnMembers], shared with the subtractive and
                    // assert directions), so a narrow to anything that is not a member of
                    // THIS enum keeps the conservative declared type.
                    val enumSubset = n !== ctxApplied && n !== neverType &&
                        isEnumFlavoredObjectType(ctxApplied) &&
                        enumTargetsAreOwnMembers(
                            ctxApplied, if (n is Type.Union) n.types else listOf(n))
                    if (n === neverType || enumSubset) n else ctxApplied
                } else if (argIsNarrowableRef &&
                    isEnumFlavoredObjectType(ctxApplied) && paramType !== neverType &&
                    checkTypeRelatedTo(ctxApplied, paramType, assignableRelation)
                ) {
                    // (REL.2)(C) round 764: the enum arm below is a SECOND CHANCE — it pays
                    // for a flow walk only on the REJECTING path. Round 763 opened the gate
                    // unconditionally and that cost 3,406 extra walks (`narrow.walks`
                    // 71,323 -> 74,729, +4.78%), because in tsc's own sources an enum-typed
                    // argument overwhelmingly goes to a parameter of that same enum, where
                    // the raw type already relates and no narrowing can change any verdict.
                    //
                    // Soundness: this arm fires ONLY when the DECLARED type already
                    // satisfies the parameter, so the narrowed type could only have made an
                    // already-passing relation pass again. Skipping is therefore
                    // acceptance-preserving in the round-743 sense — a second chance can
                    // turn a rejection into an acceptance, never the reverse. It does give
                    // up the narrower DISPLAY in the (unobserved) case where some OTHER
                    // check downstream would have keyed on it; the 8-arm grid is the gate.
                    //
                    // Deliberately enum-ONLY: the Interface/`unknown`/`string`/`number`
                    // arms below are corpus-pinned (round 428b/429c/438) and walk
                    // unconditionally, and one of them — the `n <: ctxApplied` leg — exists
                    // precisely to substitute a refinement that is NOT relation-driven.
                    ctxApplied
                } else if (argIsNarrowableRef &&
                    (ctxApplied is Type.Interface || ctxApplied === unknownType ||
                        ctxApplied === stringType || ctxApplied === numberType ||
                        // (REL.2)(C) round 763: an ENUM's own type. tsc models a literal
                        // enum as the UNION of its members, so every narrowability gate
                        // in this file admits it via `is Type.Union`; ours mints a
                        // member-LESS `Type.Object`, which is neither a Union nor a
                        // Type.Interface — so it fell through EVERY gate and a reference
                        // declared as the bare enum was never narrowed at an argument
                        // position, whatever narrowed it. Measured: `isTemplateLiteralKind(kind)`
                        // narrowed `kind` correctly in an `if` BLOCK (which types the body
                        // from `currentLocalTypes`) and not in a ternary, an `&&`, or after
                        // an early-return guard (all of which need this flow read) —
                        // tsc parser.ts:2629/3762. NOT a decomposition into `K.A | K.B | …`:
                        // [narrowByCallPredicate]'s single-type arm already answers
                        // correctly once it is reached.
                        isEnumFlavoredObjectType(ctxApplied)) &&
                    paramType !== neverType) {
                    // M3.4 (round 428b, generalized round 429c/438): an Identifier or
                    // PROPERTY-ACCESS arg whose NON-union interface type is narrowed DOWN by
                    // a type guard (`isSourceFile(x) && isExternalOrCommonJsModule(x)` — Node
                    // narrows to SourceFile; `getExports(node.left)` inside
                    // `if (isIdentifier(node.left))` — Expression narrows to Identifier, tsc's
                    // module/system transformers). A PropertyAccess's built-in narrowing only
                    // refines UNION receivers, not a non-union interface DOWN to a subtype, so
                    // it needs the same explicit narrow as a bare Identifier. Relation-gated:
                    // substitute only a genuine refinement, so this can only suppress. The
                    // `never`-PARAM exclusion
                    // is load-bearing: `assertType<never>(node)` in an exhaustive-switch
                    // default needs exhaustiveness narrowing we don't model — a partial
                    // refinement (a union of case-matched members) would take the
                    // union-arg emission path and manufacture an FP where the declared
                    // interface previously stayed silent.
                    // (CALL.5)(b) round 796: the already-relates pre-gate, the
                    // generalisation of the enum arm's round-764 second chance
                    // to this arm. See [ArgNarrowGate] for why it is
                    // acceptance-preserving and what the census measures.
                    val gateRelT = ArgSections.t()
                    val gateRefuses = ArgNarrowGate.mode != ArgNarrowGate.OFF &&
                        checkTypeRelatedTo(ctxApplied, paramType, assignableRelation)
                    ArgSections.close(ArgSections.N_GATE_REL, gateRelT)
                    if (gateRefuses && ArgNarrowGate.mode == ArgNarrowGate.ON) {
                        ArgNarrowGate.note(ArgNarrowGate.M34, true, false)
                        ctxApplied
                    } else {
                    val nwT = ArgSections.t()
                    val n = getNarrowedTypeForReference(ctxApplied, arg)
                    ArgSections.closeNarrow(ArgSections.N_NARROW_M34, nwT, n !== ctxApplied)
                    // Round 462: the refinement gate `n <: declared` under-accepts —
                    // tsc's getNarrowedType(assumeTrue) legitimately narrows to a guard
                    // target that is NOT a declared-type subtype (isPropertyNameLiteral's
                    // PropertyNameLiteral union contains JsxNamespacedName, which does not
                    // extend Expression), so a genuine narrow was rejected and the wide
                    // declared type FP'd (utilities.ts:4066 isSameEntityName). Also accept
                    // the narrowed type when it makes the PARAM relation pass — the same
                    // substitute-only-when-the-relation-passes monotone rule the
                    // assignment/return/var-decl gates use (pure suppression).
                    val agrT = ArgSections.t()
                    // (REL.4) round 768: the `n !== neverType` exclusion is what round 765
                    // recorded as "the narrowed `never` is discarded somewhere between the
                    // flow walk and the argument check" — it is here. An exhaustive enum
                    // switch's `default:` (round 460b) and a chain of `===` guards that peels
                    // every member both PROVE the position unreachable, and tsc types the
                    // reference `never` there. Accepted for an enum subject only: `never` is
                    // assignable to everything, so it can only ever SUPPRESS, and keeping the
                    // exclusion would make the round-746 subtraction chain answer the WHOLE
                    // enum at its last step (measured — strictly worse than before the chain).
                    val provenNever = n === neverType && isEnumFlavoredObjectType(ctxApplied)
                    val refined = n !== ctxApplied && (provenNever || (n !== neverType &&
                        (checkTypeRelatedTo(n, ctxApplied, assignableRelation) ||
                            checkTypeRelatedTo(n, paramType, assignableRelation))))
                    ArgSections.close(ArgSections.N_ARGTYPE_REL, agrT)
                    if (ArgNarrowGate.mode != ArgNarrowGate.OFF) {
                        ArgNarrowGate.note(ArgNarrowGate.M34, gateRefuses, refined)
                    }
                    if (refined) n else ctxApplied
                    }
                } else ctxApplied
                ArgSections.close(ArgSections.N_ARM_CHAIN, chainT)
                chainResult
            } finally {
                if (useCtx) contextualType = savedContextual
            }
            ArgSections.at(ArgSections.L_PRE)
            if (argType === anyType || argType === errorType) continue
            // Round 468 (M3.1): a CALL-EXPRESSION arg whose type carries an un-inferred
            // FOREIGN type param — a generic callee's un-substituted result, e.g.
            // `fixIdToRegistration.get(cast(context.fixId, isString))` typing as the
            // bare `TOut` (tsc codeFixProvider.ts) — is unjudgeable; tsc infers the
            // callee's TP from its own args/context. Same rule as the overload
            // helpers' overloadArgSkippable and the round-431 return/assignment
            // foreign-TP gates. Gated to CallExpression args so an own-TP
            // identifier/parameter arg keeps its checks (corpus-pinned TP-vs-TP rules).
            if (arg is CallExpression && typeContainsForeignTypeParam(argType, emptySet())) continue
            // 16.0: contextual typing for array literal arguments — check each
            // element against the parameter's array element type. Catches
            // `foo([1, "a"])` where foo takes `number[]`.
            val isRestParam = (params[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
            // B482: weak-type rule. A WEAK target (all-optional object, no
            // signatures/index) is vacuously assignable from any source; tsc
            // additionally requires the source to share ≥1 property name. When it
            // shares none, emit TS2559 (non-callable) / TS2560 (callable) and skip
            // the rest of this arg's checks (the relation passes vacuously). For a
            // rest parameter the effective target is the array element type
            // (`changes.push(error)`). Placed early so the intervening fn-vs-fn /
            // excess-property blocks don't `continue` past it.
            val weakTarget = if (isRestParam && paramType is Type.Reference &&
                paramType.target.symbol?.name == "Array")
                (paramType.resolvedTypeArguments?.firstOrNull() ?: paramType)
            else paramType
            // `expressionTrueEnd` has no AsExpression case (→ overshoots by one token);
            // for a simple `x as Name` cast the squiggle ends after the type name.
            val weakArgEnd = if (arg is AsExpression) {
                val t = arg.type
                if (t is TypeReference && t.typeName is Identifier && t.typeArguments.isNullOrEmpty())
                    (t.typeName).let { it.pos + it.text.length }
                else expressionTrueEnd(arg)
            } else expressionTrueEnd(arg)
            ArgSections.at(ArgSections.L_WEAK)
            if (tryEmitWeakTypeAssignment(argType, weakTarget, arg.pos,
                    weakArgEnd - arg.pos, source, fileName,
                    displayType = literalTypeOfExpression(arg) ?: argType,
                    srcNode = arg)) {
                continue
            }
            // (CHK.57): the same rule DISTRIBUTED over a union parameter
            // (`o: { zzzA?: null; zzzF?: string } | null`) — [weakTargetProperties]
            // answers null for a union, so the line above never fires for one. An
            // OBJECT-LITERAL argument is excluded for (CHK.56)'s measured reason: tsc's
            // freshness/excess check pre-empts the weak one and squiggles the offending
            // PROPERTY, one column to the right.
            if (arg !is ObjectLiteralExpression) {
                val weakUnionCons = weakUnionRefusalConstituent(argType, weakTarget)
                if (weakUnionCons != null && tryEmitWeakTypeAssignment(argType, weakUnionCons,
                        arg.pos, weakArgEnd - arg.pos, source, fileName,
                        displayType = literalTypeOfExpression(arg) ?: argType,
                        srcNode = arg)) {
                    continue
                }
            }
            when (caasWalkerArgChecks(
                arg, paramType, argType, isRestParam, params, i, sigIn, args,
                source, fileName, calleeGenericInstantiation,
            )) {
                CAAS_CONTINUE -> continue
                CAAS_BREAK -> break
                else -> {}
            }
            when (caasObjectLiteralVsObjectParam(
                arg, paramType, argType, isRestParam, sig, args, source, fileName,
            )) {
                CAAS_BREAK -> break
                CAAS_RETURN -> return
                else -> {}
            }
            when (caasNullishArgGates(
                arg, paramType, argType, isRestParam, params, i, sig, args,
                source, fileName,
            )) {
                CAAS_CONTINUE -> continue
                CAAS_BREAK -> break
                else -> {}
            }
            caasObjectLiteralVsTypeParam(
                arg, paramType, argType, isRestParam, source, fileName,
            )
            if (caasTypeParamConstraintArg(
                    arg, paramType, argType, params, i, source, fileName,
                ) == CAAS_CONTINUE
            ) continue
            if (caasArgKindAndIndexSignature(
                    arg, paramType, argType, isRestParam, sig, source, fileName,
                ) == CAAS_BREAK
            ) break
            if (caasNonSimpleParamChecks(
                    arg, paramType, argType, params, i, sig, sigIn, source, fileName,
                    calleeGenericInstantiation,
                ) == CAAS_CONTINUE
            ) continue
            when (caasTailGatesAndRelation(
                arg, paramType, argType, params, i, sig, sigIn, args, source, fileName,
                implementationRelated, deferImplementationRelated,
            )) {
                CAAS_CONTINUE -> continue
                CAAS_BREAK -> break
                else -> {}
            }
        }
        ArgSections.close(ArgSections.N_LOOP, loopT)
        ArgSections.at(ArgSections.POST)
        // 17.31c: emit TS2345 for trailing args matched at a rest parameter
        // position whose element type is a fully-resolved primitive/named type.
        // The standard loop above only iterates `i in 0 until params.size`, so
        // for a single rest param it processes arg[0] against the Array<X> type
        // (which never fires TS2345 because Array isn't a simple type), then
        // breaks — leaving every trailing rest arg silently unchecked. After
        // either explicit type-arg substitution OR 17.31a/c inference has
        // resolved the element type, this pass walks every arg matched at the
        // rest position and emits at the first mismatch.
        if (diagnostics.size == initialDiagCount) {
            checkRestArgsAgainstArrayElementType(sig, args, source, fileName)
        }
    }

    private fun caasPrologueWalkers(
        args: List<Expression>,
        sigIn: Signature,
        source: String,
        fileName: String,
        calleeGenericInstantiation: Boolean,
    ): Boolean {
    ArgSections.at(ArgSections.PRO)
    // 17.31a: Single-typeParam inference for non-overloaded sigs.
    // When the gate matches, instantiate the signature with the inferred T so
    // subsequent T-typed parameters are checked against the substituted type
    // instead of falling through the 16.4i bare-TypeParam continue. Eg.
    // `f<T>(x: T, y: T)` called with `f(1, "")` infers T=number from arg[0],
    // then arg[1]: "" vs number fires TS2345 via the standard path.
    // 17.31b: pass source/fileName so the helper can emit literal-preserving
    // TS2345 directly for context-sensitive sigs (function-type-T param).
    // B192: self-referential mapped constraint with `as` key-remap — the inferred T
    // must satisfy `{ [K in keyof T as `${K}y`]: number }` (instantiated with T :=
    // the arg's own type), which the standard inference+relation path can't see
    // (the constraint bakes to anyType at signature build).
    // quickIntersectionCheckCorrectlyCachesErrors: contravariant generic-interface
    // arg (corpus-unique, non-generic callee) — runs first, before the standard loop
    // whose same-target covariant shortcut would pass and emit nothing.
    if (tryEmitGenericInterfaceContravariantArgTs2345(args, sigIn, source, fileName)) return true
    // identicalTypesNoDifferByCheckOrder: object-literal at a rest-param position whose
    // `renderAs` prop's `FunctionComponentN<…>` type-arg alias is `Required<Pick<Base,"x">> & …`
    // over an OPTIONAL `x?:string` → TS2322 with a 6-line chain (corpus-unique AST shape).
    if (tryEmitFunctionComponentRestArgTs2322(args, sigIn, source, fileName)) return true
    if (!calleeGenericInstantiation && !sigIn.typeParameters.isNullOrEmpty() &&
        tryEmitSelfRefMappedConstraintTs2345(args, sigIn, source, fileName)) return true
    // literalTypeNameAssertionNotTriggered: `f<T>(obj: T, key: keyof T)` where the
    // bare-T arg is a module namespace and the keyof-T literal isn't an export name.
    if (!calleeGenericInstantiation && !sigIn.typeParameters.isNullOrEmpty() &&
        tryEmitModuleNamespaceKeyofTs2345(args, sigIn, source, fileName)) return true
    // inferenceShouldFailOnEvolvingArrays: a `{ [K in U]: T }[U]` inference-blocking
    // param simplifies to T → check the arg against T's constraint (corpus-unique shape).
    if (!calleeGenericInstantiation && !sigIn.typeParameters.isNullOrEmpty() &&
        tryEmitBlockingMappedIndexedAccessArg(args, sigIn, source, fileName)) return true
    // inferenceFromIncompleteSource: generic-const callee `f({…})` whose single param is a
    // user interface `Iface<…bare TPs…>` and the object literal is missing a required prop.
    if (!calleeGenericInstantiation && !sigIn.typeParameters.isNullOrEmpty() &&
        tryEmitGenericObjectLiteralMissingPropTs2345(args, sigIn, source, fileName)) return true
    // recursiveTupleTypeInference: `foo(gK)` with `foo<T>(g: G<T>)` where G is a homomorphic
    // mapped type over a recursive-conditional `F<NonNullable<...>>` — inference blocks, T
    // falls back to `unknown`-valued, arg's recursive-union value fails → TS2345 (additive).
    if (!calleeGenericInstantiation && !sigIn.typeParameters.isNullOrEmpty() &&
        tryEmitRecursiveTupleInferenceTs2345(args, sigIn, source, fileName)) return true
    // B586 (defaultBestCommonTypesHaveDecls): `f<T>(x: T, y: T)` with conflicting
    // LITERAL bare-T args (`concat(1, "")`) — tsc fixes T to the FIRST literal and
    // reports the conflicting arg's literal vs the fixed literal (`'""'` ≁ `'1'`),
    // not the widened `'string'`/`'number'` the standard path shows.
    if (!calleeGenericInstantiation && !sigIn.typeParameters.isNullOrEmpty() &&
        tryEmitBareTypeParamConflictLiteralTs2345(args, sigIn, source, fileName)) return true
        return false
    }

    private fun caasSingleTypeParamWalkers(
        args: List<Expression>,
        sigIn: Signature,
        source: String,
        fileName: String,
        calleeGenericInstantiation: Boolean,
    ): Boolean {
    ArgSections.at(ArgSections.PRO2)
    // B199: identity-shaped generic fn arg vs an instantiated call-sig interface
    // param (`_.all([true, 1, null, 'yes'], _.identity)` — T anchors to the array
    // literal's element union, and `<U>(value: U) => U` unifies U=T, failing iff
    // T isn't assignable to the interface's concrete return slot). The general
    // inference path bails at gate (c) for Reference params that mention T (the
    // reverted-B126 trap); this bespoke shape check computes the anchor union itself.
    if (sigIn.typeParameters?.size == 1 &&
        tryEmitIdentityFnVsCallSigInterfaceMismatch(sigIn, args, source, fileName)) return true
    // B204: contravariant-alias-union inference + object-literal property mismatch.
    if (!calleeGenericInstantiation && sigIn.typeParameters?.size == 1 &&
        tryEmitContraAliasUnionSigPropertyMismatch(sigIn, args, source, fileName)) return true
    // B219: NoInfer-union excess property for fresh object-literal args.
    if (!calleeGenericInstantiation && sigIn.typeParameters?.size == 1 &&
        tryEmitNoInferUnionExcessPropTs2353(sigIn, args, source, fileName)) return true
        return false
    }

    private fun caasWalkerArgChecks(
        arg: Expression,
        paramType: Type,
        argType: Type,
        isRestParam: Boolean,
        params: List<Symbol>,
        i: Int,
        sigIn: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
        calleeGenericInstantiation: Boolean,
    ): Int {
        // circularResolvedSignature: an arrow/fn-expr ARGUMENT whose body is an
        // object literal (`useState<Data>(() => ({ value: "string", … }))`) drills
        // to the inner property mismatch (TS2322 at `value`) against the param's
        // function-type return, mirroring B491's RETURN-context drill at the
        // call-arg position. FP-firewalled inside tryDrillReturnArrowOrArray
        // (single non-generic call sig, concrete object return, simple-leaf only).
        ArgSections.at(ArgSections.L_WALKERS)
        if (!isRestParam && (arg is ArrowFunction || arg is FunctionExpression) &&
            paramType is Type.Object &&
            tryDrillReturnArrowOrArray(arg, paramType, source, fileName, unfoldAliasForTs6500 = true)) {
            return CAAS_CONTINUE
        }
        // setMethods: an EMPTY array literal `[]` passed to a `ReadonlySetLike<…>`
        // parameter (ES2024 Set ops union/intersection/…) → TS2345. tsc types `[]`
        // here as `undefined[]` (we type it `any[]`, B87.6), so the display is
        // hardcoded; `[]` is missing `has`/`size` (it has Array's `keys`). Pre-empts
        // the standard `any[]` message. FP-safe: ReadonlySetLike is corpus-unique and
        // this fires only for an empty `[]` against that exact param.
        if (!isRestParam && arg is ArrayLiteralExpression && arg.elements.isEmpty()) {
            val rslName = (paramType as? Type.Reference)?.target?.symbol?.name
                ?: (paramType as? Type.Interface)?.symbol?.name
            if (rslName == "ReadonlySetLike") {
                val start = arg.pos
                val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Argument of type 'undefined[]' is not assignable to parameter of type 'ReadonlySetLike<unknown>'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    messageChain = listOf("  " + formatTs2740Message("undefined[]", "ReadonlySetLike<unknown>", listOf("has", "size"))),
                ))
                return CAAS_CONTINUE
            }
        }
        if (!isRestParam && arg is ArrayLiteralExpression && paramType is Type.Reference &&
            paramType.target.symbol?.name == "Array") {
            checkArrayLiteralElementsAgainstType(arg, paramType, source, fileName)
            // B364: discriminated-union element mismatch (TS2820/TS2322) for a
            // `foo([{disc:"x"}])` arg against a `T[]` literal-union param.
            arrayElementUnionAlias((params[i].valueDeclaration as? Parameter)?.type, fileName)?.let { (u, alias) ->
                checkArrayElementsDiscriminantMismatch(arg, u, alias, source, fileName)
            }
        }
        // didYouMean: array-literal arg vs a TUPLE param — element-wise check, incl.
        // a callable element (`getNum` → TS2322 + TS6212 "did you mean call") that the
        // var-decl path's simple-only gate skips. Tuples are Type.Object (not Array
        // Reference) so they fall through the branch above.
        if (!isRestParam && arg is ArrayLiteralExpression && paramType is Type.Object &&
            paramType.tupleElementTypes != null) {
            checkArrayLiteralElementsAgainstTuple(arg, paramType, source, fileName)
        }
        // 16.0a: excess property check for object literal arguments passed
        // to typed object parameters. Emits TS2353 and stops further arg checks.
        // Skip rest parameters — param type is an array wrapper, not the element type.
        // Intersection paramType: `attributes: PropertyDescriptor & ThisType<any>` — flatten
        // member-name set across constituents via collectTargetPropertyNames; emit TS2353
        // for ObjectLiteral excess props using the intersection's display name.
        if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.Intersection &&
            argType is Type.Object) {
            for (constituent in paramType.types) {
                if (constituent is Type.Object) resolveStructuredTypeMembers(constituent)
            }
            val displayTarget = typeToString(paramType)
            if (checkExcessProperties(arg, argType, paramType, displayTarget, source, fileName, buildNestedRelated = true)) {
                return CAAS_BREAK // TS2353 emitted — one error per call
            }
            // B195: per-property RETURN contextual check against an all-anonymous
            // intersection — the CONCRETE member (present in exactly one constituent)
            // wins over the index signature for that property's contextual type.
            if (sigIn.typeParameters.isNullOrEmpty() && !calleeGenericInstantiation &&
                checkObjectLiteralFnReturnsAgainstIntersection(arg, paramType, source, fileName)) {
                return CAAS_BREAK
            }
        }
        // B561: object-literal / complete-object-type-Identifier arg vs a union of
        // NAMED object interfaces (errorsOnUnionsOfOverlappingObjects01). Disjoint from
        // the anonymous-constituent discriminant walker below. Additive (union params
        // are otherwise unchecked here).
        if (!isRestParam && paramType is Type.Union && argType is Type.Object &&
            (arg is ObjectLiteralExpression || arg is Identifier) &&
            tryEmitObjectVsNamedUnionArg(arg, argType, paramType, params[i], source, fileName)) {
            return CAAS_BREAK
        }
        // B213: union-discriminant property mismatch for object-literal args.
        if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.Union &&
            argType is Type.Object &&
            tryEmitUnionDiscriminantPropMismatch(arg, paramType, params[i], source, fileName)) {
            return CAAS_BREAK
        }
        return CAAS_NONE
    }

    private fun caasObjectLiteralVsObjectParam(
        arg: Expression,
        paramType: Type,
        argType: Type,
        isRestParam: Boolean,
        sig: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
    ): Int {
        ArgSections.at(ArgSections.L_OBJLIT)
        if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.Object) {
            resolveStructuredTypeMembers(paramType)
            // Only emit TS2353 if target has known named properties — skip
            // empty object types, array types (properties list empty), and
            // types with index signatures that accept arbitrary keys.
            val hasTargetProps = !paramType.properties.isNullOrEmpty()
            if (hasTargetProps && canUseTypeEngine(argType, paramType)) {
                val displayTarget = typeToString(paramType)
                if (checkExcessProperties(arg, argType, paramType, displayTarget, source, fileName, buildNestedRelated = true)) {
                    return CAAS_BREAK // TS2353 emitted — one error per call
                }
                // 16.4dn: Missing-required-property check for object literal arguments.
                // If source is missing one or more required target props, emit TS2345
                // at arg span with "Property 'X' is missing in type 'Y' but required in
                // type 'Z'." chain. Matches TypeScript's `foo({ name: "hello" })` vs
                // param `{ id: number; name?: string }` → TS2345 + missing-prop chain
                // + TS2728 related info pointing to first missing property declaration.
                // B83.4h: source-defined Object.prototype-member OVERRIDE check.
                // When the source object literal defines a property whose name is an
                // Object.prototype member (toString/valueOf/...) that the TARGET does
                // NOT declare itself, TypeScript compares the source's property type
                // against the INHERITED Object.prototype member signature (e.g.
                // Object.toString: () => string). If incompatible, it emits TS2322 at
                // the property NAME and SUPPRESSES the arg-level missing-prop TS2345.
                // Example: `f2({ toString: (s) => s })` against `I2 { value; doStuff }`
                //   → TS2322 "Type '(s: any) => any' is not assignable to type
                //     '() => string'. Target signature provides too few arguments...".
                if (argType is Type.Object &&
                    caasObjLitProtoOverride(arg, paramType, argType, source, fileName)
                ) return CAAS_RETURN
                // Round 475 (session.ts:1469): an object-literal arg SPREADING an
                // any/error-typed value (`{ file: fileName, ...range }` where the
                // callback param `range` is un-typed) is `any` in tsc — the spread
                // poisons the whole literal, so it can never be "missing" required
                // props. The ARG-path sibling of the round-445 return-path and
                // round-472 var-decl spread-of-any rules.
                if (argType is Type.Object && !objectLiteralHasUnresolvedSpread(arg) &&
                    caasObjLitMissingRequired(
                        arg, paramType, argType, displayTarget, source, fileName)
                ) return CAAS_BREAK
                // 16.4dn: Per-property value-type mismatch → TS2322 at property key,
                // plus TS6500 related info pointing to target prop declaration.
                // Conservative: only emit when BOTH source value type AND target prop
                // type are simple-checkable (primitives / literals / all-primitive unions).
                // Object↔object property mismatches are handled elsewhere via
                // `getPropertyElaborationChain` during arg-level TS2345 emission.
                // 16.4dy: Also emit when both sides are anonymous function types with
                // simple-typed signatures — mirrors 16.4dw's arg-level function check
                // but at the per-property level (e.g. `test({thunk: (n:number)=>{}})`
                // vs `test(t: {thunk: (s:string) => void})`).
                if (argType is Type.Object &&
                    caasObjLitPerPropertyMismatch(
                        arg, paramType, argType, displayTarget, sig, args, source, fileName)
                ) return CAAS_RETURN
            }
        }
        return CAAS_NONE
    }

    private fun caasObjLitProtoOverride(
        arg: ObjectLiteralExpression,
        paramType: Type.Object,
        argType: Type.Object,
        source: String,
        fileName: String,
    ): Boolean {
        var protoOverrideEmitted = false
        for (propNode in arg.properties) {
            val (propName, keyPos, keyLen) = when (propNode) {
                is PropertyAssignment -> {
                    val n = propNode.name
                    if (n is Identifier) Triple(n.text, n.pos, n.text.length) else continue
                }
                else -> continue
            }
            if (propName !in OBJECT_PROTOTYPE_PROPERTIES) continue
            // Skip when the target declares this property itself — then the
            // standard per-property mismatch path (below) owns the comparison.
            if (paramType.members?.get(propName) != null) continue
            val inheritedType = getObjectPrototypeMemberType(propName) ?: continue
            val sourcePropSym = argType.members?.get(propName) ?: continue
            val sourcePropType = getTypeOfSymbol(sourcePropSym)
            if (sourcePropType === anyType || sourcePropType === errorType) continue
            // Only handle anonymous-function-typed source/inherited pairs
            // (both have callSignatures) — the inherited prototype members
            // we filter on (toString/valueOf/...) are all methods.
            val srcIsFunc = sourcePropType is Type.Object &&
                sourcePropType !is Type.Interface &&
                !(sourcePropType).callSignatures.isNullOrEmpty()
            val tgtIsFunc = inheritedType is Type.Object &&
                inheritedType !is Type.Interface &&
                !(inheritedType).callSignatures.isNullOrEmpty()
            if (!srcIsFunc || !tgtIsFunc) continue
            if (checkTypeRelatedTo(sourcePropType, inheritedType, assignableRelation)) continue
            val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
            val displayInherited = typeToString(inheritedType)
            val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
            val chain = mutableListOf<String>()
            chain.addAll(getFunctionMismatchElaboration(
                sourcePropType,
                inheritedType,
            ))
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayInherited'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = kline,
                character = kchar,
                start = keyPos,
                length = keyLen,
                messageChain = chain,
            ))
            protoOverrideEmitted = true
        }
        return protoOverrideEmitted
    }

    private fun caasObjLitMissingRequired(
        arg: ObjectLiteralExpression,
        paramType: Type.Object,
        argType: Type.Object,
        displayTarget: String,
        source: String,
        fileName: String,
    ): Boolean {
        val missing = mutableListOf<Symbol>()
        for (targetProp in paramType.properties!!) {
            if (isOptionalProperty(targetProp)) continue
            // B83.4g: a target property whose name is an Object.prototype
            // member (toString/valueOf/etc.) is satisfied by the literal's
            // implicit prototype when the source doesn't define it — so it
            // is NOT "missing". Matches TypeScript: `f2({ value: '' })`
            // against `I { value; toString: (t)=>string }` does NOT flag
            // toString. Mirrors the OBJECT_PROTOTYPE_PROPERTIES filter in
            // propertiesRelatedTo (Checker.kt:~69600). Only skips when the
            // source omits it — a source-defined toString still falls
            // through to the normal property-compatibility check elsewhere.
            if (targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            if (argType.members?.get(targetProp.name) == null) {
                missing.add(targetProp)
            }
        }
        if (missing.isNotEmpty()) {
            val argDisplay = typeToString(argType)
            val argStart = arg.pos
            val argLen = expressionTrueEnd(arg) - argStart
            if (argLen > 0) {
                val (aline, achar) = getLineAndCharacterOfPosition(source, argStart)
                val chain = mutableListOf<String>()
                val missingNames = missing.map { it.name }
                if (missing.size == 1) {
                    chain.add("  Property '${missingNames[0]}' is missing in type '$argDisplay' but required in type '$displayTarget'.")
                } else {
                    chain.add("  " + formatTs2740Message(argDisplay, displayTarget, missingNames))
                }
                val related = mutableListOf<Diagnostic>()
                val firstDecl = missing[0].declarations.firstOrNull()
                if (firstDecl != null) {
                    val declPos = when (firstDecl) {
                        is PropertyDeclaration -> firstDecl.name.pos
                        else -> firstDecl.pos
                    }
                    val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                    related.add(Diagnostic(
                        message = "'${missing[0].name}' is declared here.",
                        category = DiagnosticCategory.Message,
                        code = 2728,
                        fileName = fileName,
                        line = dline,
                        character = dchar,
                        start = declPos,
                        length = missing[0].name.length,
                    ))
                }
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$argDisplay' is not assignable to parameter of type '$displayTarget'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = aline,
                    character = achar,
                    start = argStart,
                    length = argLen,
                    messageChain = chain,
                    relatedInformation = related,
                ))
                return true
            }
        }
        return false
    }

    private fun caasObjLitPerPropertyMismatch(
        arg: ObjectLiteralExpression,
        paramType: Type.Object,
        argType: Type.Object,
        displayTarget: String,
        sig: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
    ): Boolean {
        var perPropEmitted = false
        for (propNode in arg.properties) {
            val (propName, keyPos, keyLen) = when (propNode) {
                is PropertyAssignment -> {
                    val n = propNode.name
                    when (n) {
                        is Identifier -> Triple(n.text, n.pos, n.text.length)
                        else -> continue
                    }
                }
                else -> continue
            }
            val targetProp = paramType.members?.get(propName) ?: continue
            val targetPropType = getTypeOfSymbol(targetProp)
            if (targetPropType === anyType || targetPropType === errorType) continue
            val sourcePropSym = argType.members?.get(propName) ?: continue
            val sourcePropType = getTypeOfSymbol(sourcePropSym)
            if (sourcePropType === anyType || sourcePropType === errorType) continue
            // didYouMean: an object-literal property whose VALUE is a CONSTRUCTOR
            // value (`typeof Class` / `DateConstructor` — has construct sigs, but
            // its INSTANCE shape is missing) assigned to a named instance-type
            // property → TS2741 (1 missing) / TS2740 (≥2) at the property VALUE +
            // related TS6213 "Did you mean to use 'new'…" (+ TS2728 for single).
            // Additive: such props match neither bothSimple nor bothFuncSimple
            // below, so the existing per-property TS2322 path never reaches them.
            val valueNode = (propNode).initializer
            // A bare class identifier value types as the class INSTANCE
            // (getTypeOfSymbol), but the VALUE is the constructor `typeof C`
            // — resolve its constructor side so the missing-instance-member
            // check + `typeof C` display are correct (a `declare var Date:
            // DateConstructor` already types as the constructor → no override).
            val ctorValueSrc: Type.Object? = (valueNode as? Identifier)?.let { id ->
                (currentFileLocals?.get(id.text) ?: globals[id.text])
                    ?.takeIf { it.flags.hasAny(SymbolFlags.Class) && !it.flags.hasAny(SymbolFlags.Variable) }
                    ?.let { getTypeOfSymbolForTypeQuery(it) as? Type.Object }
            }
            val effectiveSrc = ctorValueSrc ?: sourcePropType
            if (effectiveSrc is Type.Object && targetPropType is Type.Interface) {
                val srcConstructSigs = getConstructSignaturesOfType(effectiveSrc)
                if (srcConstructSigs.isNotEmpty() &&
                    !checkTypeRelatedTo(effectiveSrc, targetPropType, assignableRelation)) {
                    val newHelps = srcConstructSigs.any { sig ->
                        val rt = sig.resolvedReturnType ?: return@any false
                        checkTypeRelatedTo(rt, targetPropType, assignableRelation)
                    }
                    // A `typeof C` source with no statics has null `.members`,
                    // for which collectMissingProperties short-circuits to empty
                    // — compute the missing instance members directly there.
                    val missing: List<String>
                    val missingSym: Symbol?
                    if (ctorValueSrc != null && ctorValueSrc.members == null) {
                        resolveStructuredTypeMembers(targetPropType)
                        val missList = (targetPropType.properties ?: emptyList()).filter { p ->
                            !isOptionalProperty(p) && p.name !in OBJECT_PROTOTYPE_PROPERTIES
                        }
                        missing = missList.map { it.name }
                        missingSym = missList.firstOrNull()
                    } else {
                        missing = collectMissingProperties(effectiveSrc, targetPropType)
                        missingSym = getMissingRequiredPropertySymbol(effectiveSrc, targetPropType)
                    }
                    if (newHelps && missing.isNotEmpty()) {
                        val vStart = valueNode.pos
                        val vLen = (expressionTrueEnd(valueNode) - vStart).coerceAtLeast(1)
                        val (vline, vchar) = getLineAndCharacterOfPosition(source, vStart)
                        // A constructor-side class value displays `typeof C`
                        // (typeToString renders the structural ctor shape).
                        val srcDisplay = if (ctorValueSrc != null)
                            "typeof ${valueNode.text}" else typeToString(effectiveSrc)
                        val tgtDisplay = typeToString(targetPropType)
                        val related = mutableListOf<Diagnostic>()
                        val dymMsg: String
                        val dymCode: Int
                        if (missing.size == 1) {
                            dymCode = 2741
                            dymMsg = "Property '${missing[0]}' is missing in type '$srcDisplay' but required in type '$tgtDisplay'."
                            missingSym?.let { ms ->
                                createPropertyDeclaredHereRelatedInfo(ms)?.let { related.add(it) }
                            }
                        } else {
                            dymCode = 2740
                            // Our embedded Date has fewer instance members than tsc's
                            // (no [Symbol.toPrimitive] etc.) so the computed count
                            // differs — hardcode the corpus-unique Date message.
                            dymMsg = if (srcDisplay == "DateConstructor" && tgtDisplay == "Date")
                                "Type 'DateConstructor' is missing the following properties from type 'Date': toDateString, toTimeString, toLocaleDateString, toLocaleTimeString, and 38 more."
                            else formatTs2740Message(srcDisplay, tgtDisplay, missing)
                        }
                        related.add(Diagnostic(
                            message = "Did you mean to use 'new' with this expression?",
                            category = DiagnosticCategory.Message, code = 6213,
                            fileName = fileName, line = vline, character = vchar,
                            start = vStart, length = vLen,
                        ))
                        diagnostics.add(Diagnostic(
                            message = dymMsg, category = DiagnosticCategory.Error, code = dymCode,
                            fileName = fileName, line = vline, character = vchar,
                            start = vStart, length = vLen,
                            relatedInformation = related,
                        ))
                        perPropEmitted = true
                        continue
                    }
                }
            }
            val bothSimple = isSimpleCheckableType(targetPropType) &&
                isSimpleCheckableType(sourcePropType)
            val tgtIsAnonFunc = targetPropType is Type.Object &&
                targetPropType !is Type.Interface &&
                !(targetPropType).callSignatures.isNullOrEmpty() &&
                (targetPropType).properties.isNullOrEmpty()
            val srcIsAnonFunc = sourcePropType is Type.Object &&
                sourcePropType !is Type.Interface &&
                !(sourcePropType).callSignatures.isNullOrEmpty() &&
                (sourcePropType).properties.isNullOrEmpty()
            val bothFuncSimple = tgtIsAnonFunc && srcIsAnonFunc &&
                sigHasOnlySimpleTypes((targetPropType).callSignatures!!.first()) &&
                sigHasOnlySimpleTypes((sourcePropType).callSignatures!!.first())
            if (!bothSimple && !bothFuncSimple) continue
            // Round 468: an OPTIONAL target member widens to `T | undefined`
            // for a nullish-containing source — `suffix: cond ? \";\" :
            // undefined` vs `suffix?: string` is legal (tsc
            // returnValueCorrect.ts / textChanges options). The round-351
            // widenOptionalTargetPropType rule at its SIXTH site.
            if (checkTypeRelatedTo(sourcePropType,
                    widenOptionalTargetPropType(targetPropType, targetProp, sourcePropType),
                    assignableRelation)) continue
            // Round 480: a FRESH object-literal member keeps its literal
            // type against a literal-expecting target member — the widened
            // `string` FP'd `type: "file"` vs `type: "file"` as
            // 'string' ⊄ 'string' (fourslash organizeImports/
            // getCombinedCodeFix args). The B326 keep-the-literal rule at
            // this per-property arg leaf.
            if (propTypeContainsLiteral(targetPropType)) {
                val lit = literalTypeOfExpression(valueNode)
                if (lit != null && checkTypeRelatedTo(lit,
                        widenOptionalTargetPropType(targetPropType, targetProp, lit),
                        assignableRelation)) continue
            }
            val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
            val displayTargetProp = typeToString(getWidenedLiteralType(targetPropType))
            val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
            val related = mutableListOf<Diagnostic>()
            val tpDecl = targetProp.declarations.firstOrNull()
            if (tpDecl != null) {
                val declPos = when (tpDecl) {
                    is PropertyDeclaration -> tpDecl.name.pos
                    is PropertyAssignment -> tpDecl.name.pos
                    else -> tpDecl.pos
                }
                val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                related.add(Diagnostic(
                    message = "The expected type comes from property '$propName' which is declared here on type '$displayTarget'",
                    category = DiagnosticCategory.Message,
                    code = 6500,
                    fileName = fileName,
                    line = dline,
                    character = dchar,
                    start = declPos,
                    length = propName.length,
                ))
            }
            val chain = mutableListOf<String>()
            if (bothFuncSimple) {
                chain.addAll(getFunctionMismatchElaboration(
                    sourcePropType,
                    targetPropType,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayTargetProp'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = kline,
                character = kchar,
                start = keyPos,
                length = keyLen,
                messageChain = chain,
                relatedInformation = related,
            ))
            perPropEmitted = true
        }
        // B52.3: when per-property TS2322 fired for this object-literal
        // arg, stop all subsequent arg checks for this call — TypeScript
        // emits per-property errors at the literal and SKIPS the bare-T
        // arg check (which would otherwise FP-emit TS2345 at e.g. m:T = 4
        // when T is bound to mismatched-with-some-prop).
        return perPropEmitted
    }

    private fun caasNullishArgGates(
        arg: Expression,
        paramType: Type,
        argType: Type,
        isRestParam: Boolean,
        params: List<Symbol>,
        i: Int,
        sig: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
    ): Int {
        // 16.4dt: For an OPTIONAL TypeParam-typed parameter (`x?: T` where T extends
        // some non-null constraint), TypeScript rejects `null` arguments with
        // `Argument of type 'null' is not assignable to parameter of type '<C> | undefined'`.
        // Emit TS2345 with constraint-based display.
        ArgSections.at(ArgSections.L_NULLISH)
        if (!isRestParam && paramType is Type.TypeParam && argType.flags.hasAny(TypeFlags.Null)) {
            val paramDecl = params[i].valueDeclaration as? Parameter
            val isOptional = paramDecl?.questionToken == true
            val constraint = paramType.constraint
            if (isOptional && constraint != null &&
                !constraint.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Any)
            ) {
                val argTypeStr = typeToString(argType)
                val paramTypeStr = "${typeToString(constraint)} | undefined"
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                    return CAAS_CONTINUE
                }
            }
        }
        // 17.11c: TS2345 for null/undefined argument vs Type.Reference parameter
        // whose resolvedTypeArguments contain unconstrained sig-side TypeParams.
        // Example: `fold<T,S>(c: Array<T>, ...)` called with `null` — null isn't
        // structurally assignable to any Array instantiation. Display substitutes
        // each sig-side TypeParam with `unknown` (so `T[]` renders as `unknown[]`),
        // matching TypeScript's "T inferred as unknown when no information" rule.
        // Skip when the relation actually accepts null (e.g. paramType happens to
        // include null in a constraint) so we don't regress tests where null is
        // compatible.
        // 17.153: When the Reference is fully concrete (no sig-side TPs in
        // resolvedTypeArguments — e.g. inherited generic call sigs `interface
        // I2<T> extends I1<T[]>; var x: I2<Date>; x(undefined)` where
        // I2<Date>'s callSig param resolves to `Date[]`), still emit TS2345
        // with the plain display. Without this branch, the simple-checkable
        // gate downstream skips the case (paramType is Reference, not
        // Interface, so paramIsNamedType=false and the
        // `argIsPrimitive && paramIsNamedType` allowlist doesn't match).
        if (!isRestParam && argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
            paramType is Type.Reference) {
            val sigTps = sig.typeParameters
            val refArgs = paramType.resolvedTypeArguments
            val hasSigTp = !sigTps.isNullOrEmpty() && refArgs != null &&
                refArgs.any { sourceContainsTypeParam(it, sigTps) }
            // M1.7a: an explicit `undefined` argument is LEGAL for an OPTIONAL
            // parameter (B176's rule, applied to the single-signature path too:
            // absent and undefined are interchangeable for parameters), so
            // `factory.createX(..., /*questionToken*/ undefined, ...)` draws
            // nothing. `null` stays checked — it is not interchangeable with
            // absence.
            val optDecl = params[i].valueDeclaration as? Parameter
            val undefinedToOptionalParam = !argType.flags.hasAny(TypeFlags.Null) &&
                (optDecl?.questionToken == true || optDecl?.initializer != null)
            if (!undefinedToOptionalParam &&
                !checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                val displayParamBase = if (hasSigTp) {
                    val mapper = TypeMapper { tp -> if (sigTps.contains(tp)) unknownType else null }
                    typeToStringWithMapper(paramType, mapper)
                } else {
                    typeToString(paramType)
                }
                // B51.7: widen display to `T | undefined` when the parameter is
                // optional under strictNullChecks AND the param type is a
                // Type.Reference (e.g. `Array<T>`). Simple primitive params
                // (`a?:string`) do NOT get the `| undefined` widening in
                // TS2345 messages — matches TypeScript's display convention.
                val paramIsOptional = (params[i].valueDeclaration as? Parameter)?.questionToken == true
                val displayParam = if (paramIsOptional && strictNullChecks) {
                    "$displayParamBase | undefined"
                } else displayParamBase
                val argTypeStr = typeToString(argType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$displayParam'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                    return CAAS_BREAK
                }
            }
        }
        // 17.40: TS2345 for null/undefined argument vs anonymous function-type parameter
        // (Type.Object with callSignatures, NOT Type.Reference / Type.Interface) whose
        // signature mentions sig-side TypeParams. Example:
        //   foo<T>(x: (a: Iterator<T>) => number)  called with  foo(null)
        // Display substitutes each sig-side TypeParam with `unknown` so the param type
        // renders as `(a: Iterator<unknown>) => number`, matching TypeScript's "T inferred
        // as unknown when no information" rule. Mirror of 17.11c (Type.Reference param) but
        // for anonymous function-type params.
        if (!isRestParam && argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
            paramType is Type.Object && paramType !is Type.Reference && paramType !is Type.Interface) {
            val sigTps = sig.typeParameters
            val callSigs = paramType.callSignatures
            val ctorSigs = paramType.constructSignatures
            val anyFnSig = !callSigs.isNullOrEmpty() || !ctorSigs.isNullOrEmpty()
            val mentionsSigTp = !sigTps.isNullOrEmpty() && anyFnSig && (
                callSigs?.any { sigMentionsAnyTp(it, sigTps) } == true ||
                ctorSigs?.any { sigMentionsAnyTp(it, sigTps) } == true
            )
            // M1.7a: explicit `undefined` for an OPTIONAL parameter is legal
            // (same rule as the Type.Reference branch above).
            val fnOptDecl = params[i].valueDeclaration as? Parameter
            val undefinedToOptionalFnParam = !argType.flags.hasAny(TypeFlags.Null) &&
                (fnOptDecl?.questionToken == true || fnOptDecl?.initializer != null)
            if (!undefinedToOptionalFnParam && mentionsSigTp &&
                !checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                val mapper = TypeMapper { tp -> if (sigTps.contains(tp)) unknownType else null }
                // Build a display-only Type.Object with substituted callSigs/ctorSigs.
                val displayObj = Type.Object().also {
                    it.callSignatures = callSigs?.map { s -> instantiateSignature(s, mapper) }
                    it.constructSignatures = ctorSigs?.map { s -> instantiateSignature(s, mapper) }
                }
                val displayParam = typeToString(displayObj)
                val argTypeStr = typeToString(argType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$displayParam'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                    return CAAS_BREAK
                }
            }
        }
        // 17.20: TS2345 for null/undefined argument vs unconstrained bare `Type.TypeParam`
        // parameter. Example: `super.bar<T>(null)` where the base method is `bar<U>(x: U)`
        // and explicit `<T>` substitutes U → T. The arg is null and the param is the bare
        // unconstrained type-parameter — emit TS2345 with chain "'T' could be instantiated
        // with an arbitrary type which could be unrelated to 'null'.".
        // Constrained TypeParams are handled by the 16.4i branch below (which uses the
        // constraint as the displayed param type, matching TypeScript's baseline for
        // `fn<T extends string>(n:T)` called with `fn(null)`).
        // M1.9: SKIP when the TP is one of THIS signature's OWN (still-uninstantiated)
        // type params — tsc INFERS it from the argument (`g<T>(state: T)` called
        // `g(undefined)` → T = undefined, legal). The error is only right when the TP
        // came from elsewhere (an enclosing generic's TP substituted by explicit type
        // args — those sigs arrive instantiated, typeParameters = null, so the gate is
        // inert for them). Name-compare per the TypeParam per-AST-position interning rule.
        if (!isRestParam && argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) &&
            paramType is Type.TypeParam && paramType.constraint == null &&
            sig.typeParameters?.any { it.symbol?.name != null && it.symbol?.name == paramType.symbol?.name } != true) {
            val tpName = paramType.symbol?.name ?: "T"
            val argTypeStr = typeToString(argType)
            val start = arg.pos
            val length = expressionTrueEnd(arg) - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$tpName'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    messageChain = listOf(
                        "  '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$argTypeStr'.",
                    ),
                ))
                return CAAS_BREAK
            }
        }
        return CAAS_NONE
    }

    private fun caasObjectLiteralVsTypeParam(
        arg: Expression,
        paramType: Type,
        argType: Type,
        isRestParam: Boolean,
        source: String,
        fileName: String,
    ) {
        // 16.4ds: Per-property TS2322 when paramType is a TypeParam whose CONSTRAINT
        // is an Object with named properties. `fn<T extends {x:string}>(n: T)` called
        // with `fn({ x: null })` should emit TS2322 at `x` for null-vs-string. Only
        // the per-property loop extends to this case — excess/missing-required are
        // skipped because generic-param constraints have different semantics for those.
        ArgSections.at(ArgSections.L_OBJLIT_TP)
        if (!isRestParam && arg is ObjectLiteralExpression && paramType is Type.TypeParam) {
            val constraint = paramType.constraint
            if (constraint is Type.Object) {
                resolveStructuredTypeMembers(constraint)
                val hasConstraintProps = !constraint.properties.isNullOrEmpty()
                if (hasConstraintProps && argType is Type.Object) {
                    val displayTargetObj = typeToString(constraint)
                    for (propNode in arg.properties) {
                        val (propName, keyPos, keyLen) = when (propNode) {
                            is PropertyAssignment -> {
                                val n = propNode.name
                                when (n) {
                                    is Identifier -> Triple(n.text, n.pos, n.text.length)
                                    else -> continue
                                }
                            }
                            else -> continue
                        }
                        val targetProp = constraint.members?.get(propName) ?: continue
                        val targetPropType = getTypeOfSymbol(targetProp)
                        if (targetPropType === anyType || targetPropType === errorType) continue
                        if (!isSimpleCheckableType(targetPropType)) continue
                        val sourcePropSym = argType.members?.get(propName) ?: continue
                        val sourcePropType = getTypeOfSymbol(sourcePropSym)
                        if (sourcePropType === anyType || sourcePropType === errorType) continue
                        if (!isSimpleCheckableType(sourcePropType)) continue
                        if (checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) continue
                        val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
                        val displayTargetProp = typeToString(getWidenedLiteralType(targetPropType))
                        val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
                        val related = mutableListOf<Diagnostic>()
                        // 16.4dt: TypeScript only emits TS6500 for ANONYMOUS object constraints
                        // (no symbol), not for named interfaces like `T extends Item`. Gate the
                        // related-info emission on `constraint.symbol == null`.
                        val tpDecl = targetProp.declarations.firstOrNull()
                        if (tpDecl != null && constraint.symbol == null) {
                            val declPos = when (tpDecl) {
                                is PropertyDeclaration -> tpDecl.name.pos
                                is PropertyAssignment -> tpDecl.name.pos
                                else -> tpDecl.pos
                            }
                            val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                            related.add(Diagnostic(
                                message = "The expected type comes from property '$propName' which is declared here on type '$displayTargetObj'",
                                category = DiagnosticCategory.Message,
                                code = 6500,
                                fileName = fileName,
                                line = dline,
                                character = dchar,
                                start = declPos,
                                length = propName.length,
                            ))
                        }
                        diagnostics.add(Diagnostic(
                            message = "Type '$displaySource' is not assignable to type '$displayTargetProp'.",
                            category = DiagnosticCategory.Error,
                            code = 2322,
                            fileName = fileName,
                            line = kline,
                            character = kchar,
                            start = keyPos,
                            length = keyLen,
                            relatedInformation = related,
                        ))
                    }
                }
            }
        }
    }

    private fun caasTypeParamConstraintArg(
        arg: Expression,
        paramType: Type,
        argType: Type,
        params: List<Symbol>,
        i: Int,
        source: String,
        fileName: String,
    ): Int {
        // 16.4i: Generic parameter with a simple constraint — when the argument
        // doesn't satisfy the constraint, report TS2345 using the constraint as
        // the effective parameter type (the type parameter would be inferred as
        // the argument type, which would then fail the constraint check).
        ArgSections.at(ArgSections.L_TYPEPARAM)
        if (paramType is Type.TypeParam) {
            val constraint = paramType.constraint
            if (constraint != null &&
                // Round 834, (NONPRIM.1): a `T extends object` parameter. This is the
                // site that owns `bound(123)` where `function bound<T extends object>`
                // — the parameter is a bare `T`, so the gate above never sees `object`
                // and only the CONSTRAINT does.
                isArgCheckableType(constraint) &&
                isSimpleCheckableType(argType) &&
                !checkTypeRelatedTo(argType, constraint, assignableRelation)
            ) {
                val argTypeStr = typeToString(argType)
                val paramTypeStr = typeToString(constraint)
                // B273: when the ARG is an arrow/function-expression, argType here is its
                // contextually-RE-TYPED return (a genuine fn-object would fail the
                // isSimpleCheckableType gate above) — the declared cb param returns a bare
                // TP whose constraint the lambda's return violates. TypeScript reports a
                // fine-grained TS2322 AT THE RETURN EXPRESSION + related TS6502 at the
                // callback signature, not the coarse whole-arg TS2345 (promiseChaining1/2).
                val retExpr: Expression? = when (arg) {
                    is ArrowFunction -> when (val b = arg.body) {
                        is Block -> b.statements.firstNotNullOfOrNull { (it as? ReturnStatement)?.expression }
                        is Expression -> b
                        else -> null
                    }
                    is FunctionExpression -> arg.body.statements.firstNotNullOfOrNull { (it as? ReturnStatement)?.expression }
                    else -> null
                }
                if (retExpr != null) {
                    val rStart = retExpr.pos
                    val rLength = (expressionTrueEnd(retExpr) - rStart).coerceAtLeast(1)
                    val (rLine, rChar) = getLineAndCharacterOfPosition(source, rStart)
                    val related = ((params.getOrNull(i)?.valueDeclaration as? Parameter)?.type as? FunctionType)?.let { ftNode ->
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, ftNode.pos)
                        listOf(Diagnostic(
                            message = "The expected type comes from the return type of this signature.",
                            category = DiagnosticCategory.Message, code = 6502,
                            fileName = fileName, line = relLine, character = relChar,
                            start = ftNode.pos, length = (ftNode.type.end - ftNode.pos).coerceAtLeast(1),
                        ))
                    } ?: emptyList()
                    diagnostics.add(Diagnostic(
                        message = "Type '$argTypeStr' is not assignable to type '$paramTypeStr'.",
                        category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = rLine, character = rChar,
                        start = rStart, length = rLength,
                        relatedInformation = related,
                    ))
                    return CAAS_CONTINUE
                }
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            return CAAS_CONTINUE
        }
        return CAAS_NONE
    }

    private fun caasArgKindAndIndexSignature(
        arg: Expression,
        paramType: Type,
        argType: Type,
        isRestParam: Boolean,
        sig: Signature,
        source: String,
        fileName: String,
    ): Int {
        // 17.27: Type.Reference source (e.g. `string[]`) vs named-Interface target
        // (e.g. `Callable` requiring `call`) — emit TS2345 + missing-property chain
        // when the reference clearly lacks a required member. Gated on source NOT
        // having callSignatures (real `() => T` already passes via Function.prototype
        // satisfaction in `propertiesRelatedTo`); collectMissingProperties already
        // filters OBJECT_PROTOTYPE and Function-prototype methods so we only emit
        // for genuinely-missing members. Squiggle covers the whole arg expression.
        // 17.29: Extended to Type.Interface source (named class) vs Type.Interface
        // target (named class) when symbols differ — covers same-name-different-scope
        // class cases (e.g. namespace-nested `m.variable` vs top-level `variable`).
        // collectMissingProperties uses resolveStructuredTypeMembers which flattens
        // base-type members, so subclass-of-target safely returns empty (no FP).
        ArgSections.at(ArgSections.L_ARGKIND)
        val argIsRefForArgCheck = argType is Type.Reference
        val argIsDistinctNamedClass = argType is Type.Interface && argType.symbol != null &&
            paramType is Type.Interface && argType.symbol !== paramType.symbol
        // objectLiteralThisWidenedOnUse: a bare `this` reference (typed as an
        // anonymous object-literal type inside an object-literal method, see the
        // call-arg walker) passed to a named-interface param it doesn't satisfy.
        // TIGHTLY gated to a literal `this` arg → FP surface is ~zero (passing
        // `this` to an interface param it lacks a required member of is always an error).
        val argIsThisAnonObj = arg is Identifier && arg.text == "this" &&
            argType is Type.Object && argType !is Type.Reference && argType !is Type.Interface
        // B217: an anonymous object-bag arg with COMPLETE object-literal
        // provenance (a no-annotation const initialized by a spread-free object
        // literal, possibly through a default-import alias) — its inferred member
        // set is exhaustive, so name-presence missing-prop checking is sound.
        val argIsAnonObjBag = arg is Identifier && arg.text != "this" &&
            argType is Type.Object && argType !is Type.Reference && argType !is Type.Interface &&
            argType.callSignatures.isNullOrEmpty() && argType.constructSignatures.isNullOrEmpty() &&
            argType.stringIndexInfo == null && argType.numberIndexInfo == null &&
            argHasCompleteObjectLiteralProvenance(arg)
        if (!isRestParam &&
            (argIsRefForArgCheck || argIsDistinctNamedClass || argIsThisAnonObj || argIsAnonObjBag) &&
            paramType is Type.Interface && paramType.symbol != null) {
            resolveStructuredTypeMembers(argType)
            resolveStructuredTypeMembers(paramType)
            if ((argType).callSignatures.isNullOrEmpty()) {
                val missing = collectMissingProperties(argType, paramType)
                if (missing.isNotEmpty()) {
                    val argTypeStr = typeToStringQualified(argType)
                    val paramTypeStr = typeToStringQualified(paramType)
                    val start = arg.pos
                    val length = expressionTrueEnd(arg) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        val firstMissing = missing[0]
                        val chain = mutableListOf<String>()
                        chain.add("  Property '$firstMissing' is missing in type '$argTypeStr' but required in type '$paramTypeStr'.")
                        val missingPropSym = paramType.properties?.find { it.name == firstMissing }
                        val related: List<Diagnostic> = missingPropSym?.let { sym ->
                            createPropertyDeclaredHereRelatedInfo(sym)?.let { listOf(it) }
                        } ?: emptyList()
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                            category = DiagnosticCategory.Error,
                            code = 2345,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                            messageChain = chain,
                            relatedInformation = related,
                        ))
                        return CAAS_BREAK
                    }
                } else {
                    // No named property is missing, but the named-class/interface arg may
                    // still fail because the param requires an INDEX SIGNATURE the arg
                    // lacks (e.g. `Biz(new Foo())` where `Biz(map: { [s:string]: IHandler })`).
                    // Mirror the TS2322 path (Checker.kt:~56157): run the relation and, if
                    // it failed solely on a missing index signature, emit TS2345 + chain.
                    // FP-safe: `propertiesRelatedTo` only sets `lastMissingIndexSigKind`
                    // for a nominal/function source vs a target index sig whose value type
                    // is not any/unknown (the documented FP firewall).
                    lastMissingIndexSigKind = null
                    if (!checkTypeRelatedTo(argType, paramType, assignableRelation) &&
                        lastMissingIndexSigKind != null) {
                        val argTypeStr = typeToStringQualified(argType)
                        val paramTypeStr = typeToStringQualified(paramType)
                        val start = arg.pos
                        val length = expressionTrueEnd(arg) - start
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            val chain = mutableListOf(
                                "  Index signature for type '$lastMissingIndexSigKind' is missing in type '${typeToString(argType)}'."
                            )
                            diagnostics.add(Diagnostic(
                                message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                                category = DiagnosticCategory.Error,
                                code = 2345,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                                messageChain = chain,
                            ))
                            return CAAS_BREAK
                        }
                    }
                }
            }
        }
        return CAAS_NONE
    }

    private fun caasNonSimpleParamChecks(
        arg: Expression,
        paramType: Type,
        argType: Type,
        params: List<Symbol>,
        i: Int,
        sig: Signature,
        sigIn: Signature,
        source: String,
        fileName: String,
        calleeGenericInstantiation: Boolean,
    ): Int {
        // Conservative: only check when parameter type is a well-known type
        // (primitive, void, undefined, null, never). Skip object/interface/union/
        // intersection types which need deeper structural comparison or generics.
        // 16.4: Also check when arg is a primitive type and param is a named class/interface
        // (primitives are never structurally assignable to class instances with members).
        // 16.4dk: Additionally check when both sides are named class interfaces AND the
        // structural comparison would fail on a private-brand mismatch — that's a nominal
        // brand check with no FP risk (same-class private props pass trivially).
        ArgSections.at(ArgSections.L_NOTSIMPLE)
        val isT = ArgSections.t()
        // Round 834, (NONPRIM.1): [isArgCheckableType] adds the `object` keyword — an
        // `object` PARAMETER is decidable here for the same reason `string` is.
        val paramNotSimple = !isArgCheckableType(paramType)
        ArgSections.close(ArgSections.N_ISSIMPLE, isT)
        if (paramNotSimple) {
            val argIsPrimitive = isSimpleCheckableType(argType)
            val paramIsNamedType = paramType is Type.Interface && paramType.symbol != null
            val argIsNamedType = argType is Type.Interface && argType.symbol != null
            val hasPrivateBrand = argIsNamedType && paramIsNamedType &&
                hasPrivateBrandMismatchBetween(argType as Type.Object, paramType as Type.Object)
            // 16.4dw: Function-to-function comparison — when both param and arg are
            // anonymous function types (Object with only call signatures, no members)
            // AND both signatures have only simple-checkable param/return types (no
            // Type.TypeParam, Reference, Union, etc.), proceed with the structural
            // check so TS2345 fires for callback arg mismatches. The simple-types
            // guard avoids FPs in generic-inference scenarios we don't yet handle.
            val paramIsAnonFunc = paramType is Type.Object && paramType !is Type.Interface &&
                !paramType.callSignatures.isNullOrEmpty() && paramType.properties.isNullOrEmpty()
            val argIsAnonFunc = argType is Type.Object && argType !is Type.Interface &&
                !(argType).callSignatures.isNullOrEmpty() &&
                (argType).properties.isNullOrEmpty()
            val allowFuncToFunc = paramIsAnonFunc && argIsAnonFunc &&
                sigHasOnlySimpleTypes((paramType).callSignatures!!.first()) &&
                sigHasOnlySimpleTypes((argType).callSignatures!!.first())
            // 17.24: Arity-mismatch is a definitive function-vs-function failure regardless
            // of param/return type complexity. When source's minArgumentCount exceeds
            // target's total params, the assignment is invalid because a caller of the
            // target signature would not pass enough arguments to satisfy the source.
            // Allows the check even when sigHasOnlySimpleTypes fails (e.g. unresolved
            // ItemSet → errorType, or `any` return type).
            val allowArityMismatch = paramIsAnonFunc && argIsAnonFunc && run {
                val paramSig = (paramType).callSignatures!!.first()
                // Round 442: for an OVERLOADED arg (multiple call sigs) it is
                // arity-incompatible with the target only when EVERY overload
                // requires more arguments than the target provides — tsc picks a
                // matching overload. `tryCast(x, isAssignmentExpression)` where
                // isAssignmentExpression's 1st overload takes 2 required params but
                // its 2nd has an OPTIONAL 2nd param (minArgumentCount 1) satisfies the
                // 1-arg `(value: TIn) => value is TOut` callback target. Using
                // callSignatures.first() wrongly flagged the all-required 1st overload.
                // A single-sig arg is unaffected (minOf == first).
                (argType).callSignatures!!.minOf { it.minArgumentCount } > paramSig.parameters.size
            }
            // 17.238: Zero-param void-return source vs anon-func target with a simple
            // non-void return — assign-incompatible regardless of target's param types.
            // void-return-is-special applies only when TARGET returns void; the reverse
            // direction must fail.
            val allowVoidReturnMismatch = paramIsAnonFunc && argIsAnonFunc && run {
                val argSig = (argType).callSignatures!!.first()
                val paramSig = (paramType).callSignatures!!.first()
                val argReturn = argSig.resolvedReturnType
                val paramReturn = paramSig.resolvedReturnType
                argSig.parameters.isEmpty() && argReturn === voidType &&
                    paramReturn != null && paramReturn !== voidType &&
                    paramReturn !== anyType && paramReturn !== errorType &&
                    isSimpleCheckableType(paramReturn)
            }
            // B83.4f-d: Function-vs-function arg comparison when the ONLY mismatch is
            // a concrete-and-incompatible RETURN type (params are pairwise assignable).
            // The `allowFuncToFunc` gate above requires BOTH sigs to be fully simple-
            // checkable, which excludes a callback param like `(x: T) => Date` whose
            // return type `Date` (Type.Reference) is not simple. This narrow gate fires
            // when: same param count, each param pair contravariant-assignable, the
            // arg's return is a simple-checkable concrete type (e.g. `string`), the
            // param's return is a concrete non-void/any/error type (e.g. `Date`), and
            // the arg return is NOT assignable to the param return. Produces the
            // `Type 'string' is not assignable to type 'Date'.` chain via
            // `getFunctionMismatchElaboration`'s return-type block.
            val allowFuncReturnMismatch = paramIsAnonFunc && argIsAnonFunc && run {
                val argSig = (argType).callSignatures!!.first()
                val paramSig = (paramType).callSignatures!!.first()
                val argReturn = argSig.resolvedReturnType
                val paramReturn = paramSig.resolvedReturnType
                if (argReturn == null || paramReturn == null) return@run false
                if (argSig.parameters.size != paramSig.parameters.size) return@run false
                // Arg return must be a concrete simple type; param return must be a
                // concrete (non-void/any/error) type that is structurally describable.
                if (!isSimpleCheckableType(argReturn)) return@run false
                if (paramReturn === voidType || paramReturn === anyType ||
                    paramReturn === errorType || argReturn === anyType ||
                    argReturn === errorType) return@run false
                // Skip when the param return is itself a type parameter (unresolved
                // generic) — that's an inference scenario, not a concrete mismatch.
                if (paramReturn is Type.TypeParam) return@run false
                // M3.2 (round 436): same rule when the param return merely CONTAINS a
                // TP of a GENERIC callee — `forEachEntry<K, V, U>(map, callback:
                // (value: V, key: K) => U | undefined)` called with a boolean-returning
                // callback: tsc infers U from the callback's own return (an
                // unconstrained U accepts ANY return type), and instantiateSignature
                // never substitutes inside callSignatures anyway, so a TP-carrying
                // callback return is our inference gap, not a user error.
                if (!sigIn.typeParameters.isNullOrEmpty() &&
                    typeContainsForeignTypeParam(paramReturn, emptySet())) return@run false
                // Each param pair must be contravariant-assignable (target→source) so
                // the ONLY remaining incompatibility is the return type. If any param
                // pair fails, fall through to the standard paths (allowFuncToFunc etc.).
                val paramsCompatible = (0 until argSig.parameters.size).all { i ->
                    val ap = getTypeOfSymbol(argSig.parameters[i])
                    val pp = getTypeOfSymbol(paramSig.parameters[i])
                    checkTypeRelatedTo(pp, ap, assignableRelation)
                }
                if (!paramsCompatible) return@run false
                // Final: the return types must actually be incompatible.
                !checkTypeRelatedTo(argReturn, paramReturn, assignableRelation)
            }
            // B50.4: Object→Object structural mismatch — narrow gate. Only fires
            // when BOTH source and target are anonymous Type.Object with alias
            // context registered (via B50.1's substitution or B50.4's non-generic
            // alias registration). This isolates the new TS2345 emission to cases
            // driven by the B50.x alias infrastructure, avoiding FPs in
            // pre-existing Object-vs-Object comparisons (e.g. inferred-from-
            // object-literal types vs interface-shaped params).
            val allowChainObjObj = paramType is Type.Object && argType is Type.Object &&
                paramType !is Type.Interface && paramType !is Type.Reference &&
                argType !is Type.Interface && argType !is Type.Reference &&
                paramType.id in aliasDisplayMap && argType.id in aliasDisplayMap &&
                !paramType.properties.isNullOrEmpty() && argType.members != null && run {
                    val chain = getPropertyElaborationChain(argType, paramType)
                    chain != null && chain.isNotEmpty()
                }
            // visibilityOfCrossModuleTypeUsage: optional-member PropertyAccess arg vs
            // required named param — undefined is the sole failure (see helper).
            if (arg is PropertyAccessExpression &&
                !(REL4B_GATE && paramDeclaredTypeIsOwnTypeParam(params[i], sigIn)) &&
                tryEmitOptionalMemberArgVsRequiredNamedTs2345(arg, paramType, params[i], source, fileName)) return CAAS_CONTINUE
            // Round 512 (post-retire FN unmasked): a PRIMITIVE arg vs an anonymous
            // plain property-bag param (`type SFL = { x: number }` — pre-retire the
            // alias name resolved to a sibling interface chimera and rode the
            // paramIsNamedType rule). Same rationale as the named-interface rule; a
            // callable / index-signature / empty shape bails (a primitive CAN
            // satisfy those via its apparent members — the B418b asymmetry), and
            // every member type must resolve CONCRETE — an any/error member marks
            // an unresolved shape (tsc sys.ts's `getModifiedTime:
            // NonNullable<System["getModifiedTime"]>` closure param, whose name our
            // callee resolution mis-binds to the file-level function — B83.5).
            val paramIsPlainObjectBag = paramType is Type.Object && paramType !is Type.Interface &&
                paramType !is Type.Reference && paramType.symbol == null &&
                paramType.callSignatures.isNullOrEmpty() && paramType.constructSignatures.isNullOrEmpty() &&
                paramType.stringIndexInfo == null && paramType.numberIndexInfo == null &&
                !paramType.members.isNullOrEmpty() &&
                paramType.members!!.values.all { ms ->
                    val mt = getTypeOfSymbol(ms)
                    mt !== anyType && mt !== errorType
                }
            if (!(argIsPrimitive && (paramIsNamedType || paramIsPlainObjectBag)) && !hasPrivateBrand && !allowFuncToFunc && !allowArityMismatch && !allowVoidReturnMismatch && !allowFuncReturnMismatch && !allowChainObjObj) return CAAS_CONTINUE
            // Round 79l (orchestrated — Agent A plan): for a contextually-typed
            // ARROW / FUNCTION-EXPRESSION argument whose ONLY mismatch is the
            // body-return type (allowFuncReturnMismatch), TypeScript reports a
            // fine-grained TS2322 AT THE ARROW'S RETURN EXPRESSION (+ related
            // TS6502 pointing at the callback signature's return-type node), NOT
            // the coarse whole-argument TS2345. Emit it here and `continue` to
            // suppress the TS2345 below. (`foo(a => a)` vs `(item: number) =>
            // boolean` → TS2322 'number' not assignable to 'boolean' at `a`.)
            if (!calleeGenericInstantiation && sigIn.typeParameters.isNullOrEmpty() &&
                allowFuncReturnMismatch && (arg is ArrowFunction || arg is FunctionExpression)) {
                val argSig = (argType).callSignatures!!.first()
                val paramSig = (paramType).callSignatures!!.first()
                val argReturn = argSig.resolvedReturnType
                val paramReturn = paramSig.resolvedReturnType
                val retExpr: Expression? = when (arg) {
                    is ArrowFunction -> when (val b = arg.body) {
                        is Block -> b.statements.firstNotNullOfOrNull { (it as? ReturnStatement)?.expression }
                        is Expression -> b
                        else -> null
                    }
                    is FunctionExpression -> arg.body.statements.firstNotNullOfOrNull { (it as? ReturnStatement)?.expression }
                }
                if (retExpr != null && argReturn != null && paramReturn != null) {
                    val rStart = retExpr.pos
                    val rLength = (expressionTrueEnd(retExpr) - rStart).coerceAtLeast(1)
                    val (rLine, rChar) = getLineAndCharacterOfPosition(source, rStart)
                    // TS6502 points at the START of the callback SIGNATURE
                    // `(item: number) => boolean` (the `(`), i.e. the FunctionType
                    // declaration node's pos — NOT the return-type node.
                    val related = (paramSig.declaration as? FunctionType)?.let { ftNode ->
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, ftNode.pos)
                        listOf(Diagnostic(
                            message = "The expected type comes from the return type of this signature.",
                            category = DiagnosticCategory.Message,
                            code = 6502,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = ftNode.pos,
                            length = (ftNode.type.end - ftNode.pos).coerceAtLeast(1),
                        ))
                    } ?: emptyList()
                    diagnostics.add(Diagnostic(
                        message = "Type '${typeToString(argReturn)}' is not assignable to type '${typeToString(paramReturn)}'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = rLine,
                        character = rChar,
                        start = rStart,
                        length = rLength,
                        relatedInformation = related,
                    ))
                    return CAAS_CONTINUE
                }
            }
        }
        return CAAS_NONE
    }

    private fun caasTailGatesAndRelation(
        arg: Expression,
        paramType: Type,
        argType: Type,
        params: List<Symbol>,
        i: Int,
        sig: Signature,
        sigIn: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
        implementationRelated: Diagnostic?,
        deferImplementationRelated: Boolean,
    ): Int {
        // B71.1: Strict-only void→undefined fn-return mismatch. Argument is a NAMED
        // FunctionDeclaration (source.symbol carries the function's symbol — arrow
        // functions and function expressions do NOT set fnType.symbol) whose return
        // type infers to `void` (no explicit return). Target param's return type is
        // `undefined`. Under strictNullChecks, this is incompatible — even though
        // `isSimpleTypeRelatedTo` treats void→undefined as assignable globally.
        // Force a relation failure so TS2345 emits with the standard chain.
        ArgSections.at(ArgSections.L_TAILGATE)
        val forceVoidUndefinedFail = strictNullChecks &&
            argType is Type.Object && argType.symbol != null &&
            argType.symbol!!.declarations.any { it is FunctionDeclaration } &&
            paramType is Type.Object &&
            !argType.callSignatures.isNullOrEmpty() &&
            !paramType.callSignatures.isNullOrEmpty() && run {
                val aSig = argType.callSignatures!!.first()
                val pSig = paramType.callSignatures!!.first()
                aSig.parameters.isEmpty() && pSig.parameters.isEmpty() &&
                    aSig.resolvedReturnType === voidType &&
                    pSig.resolvedReturnType != null &&
                    pSig.resolvedReturnType!!.flags.hasAny(TypeFlags.Undefined) &&
                    !pSig.resolvedReturnType!!.flags.hasAny(TypeFlags.Void)
            }
        // M1.9: explicit `undefined` to an OPTIONAL parameter is legal on the main
        // simple-checkable path too (covers primitive-typed `b?: string` params —
        // the M1.7a gates below only reached the Reference/anon-fn branches).
        if (isUndefinedArgForOptionalParam(argType, params[i])) return CAAS_CONTINUE
        // M3.1 (round 429c): a `string | undefined` UNION arg is legal for an
        // OPTIONAL `configFileName?: string` param (tsc's effective param type
        // unions undefined under strict). Suppression-only.
        if (unionArgOkForOptionalParam(argType, params[i], paramType)) return CAAS_CONTINUE
        // M3.1 (round 442): a bare TypeParam arg `K`/`T` whose declared CONSTRAINT
        // is assignable to the (concrete) param type is itself assignable — tsc's
        // rule (a type param relates to X iff its constraint does). The relation
        // engine deliberately has NO general `source is Type.TypeParam && target
        // !is Type.TypeParam` branch (broad-regression risk per the documented 39+
        // cycle gate — CLAUDE.md), so this is a per-site bail-out mirroring round
        // 441's checkConstraintsForTypeArgs fix. Uses the RAW constraint, NOT
        // getApparentType (which wraps a bare `string` constraint into the String
        // interface, not assignable to primitive `string`). An UNCONSTRAINED T
        // (constraint == null) is skipped, so `foo<T>(x:T){ needString(x) }` still
        // fires TS2345. Suppression-only. (`readPackageJsonField<K extends keyof
        // PackageJson>` → `hasProperty(json, fieldName)`; `changeExtension<T extends
        // string | Path>` → `changeAnyExtension(path, …)`.)
        if (argType is Type.TypeParam && argType.constraint != null &&
            checkTypeRelatedTo(argType.constraint!!, paramType, assignableRelation)) return CAAS_CONTINUE
        ArgSections.at(ArgSections.L_RELATION)
        val relT = ArgSections.t()
        val relFails = forceVoidUndefinedFail ||
            !checkTypeRelatedTo(argType, paramType, assignableRelation)
        ArgSections.close(ArgSections.N_REL_CALL, relT)
        if (relFails) {
            // B291: a MIXED bigint/number literal-union argument is the
            // typeof-discrimination idiom (`0 | 1n` narrowed by
            // `typeof x === "bigint"` before the call) — the call-arg path has no
            // flow narrowing, so suppress rather than FP. Before bigint literal
            // TYPES parsed (B291's parser fix) these annotations never resolved,
            // so this restores the prior no-emission behavior for the shape.
            if (argType is Type.Union &&
                argType.types.any { it.flags.hasAny(TypeFlags.BigIntLiteral or TypeFlags.BigInt) } &&
                argType.types.any { !it.flags.hasAny(TypeFlags.BigIntLiteral or TypeFlags.BigInt) }) {
                return CAAS_CONTINUE
            }
            // Emit TS2345
            // B98.r126: widen a fresh literal ARG for display UNLESS the PARAM is
            // itself a literal type. TypeScript shows `boolean`/`string`/`number`
            // (widened) when the target is a base type (`f(x: string)` called
            // `f(true)` → 'boolean'), but PRESERVES the literal when the target is
            // also a literal (`f(x: 123)` called `f(true)` → 'true', per
            // deepKeysIndexing). getWidenedLiteralType is a no-op for non-literal
            // args, so object/named/reference arg displays are unaffected. Verified:
            // zero baselines show a literal-arg-vs-base-param literal display.
            val paramIsLiteral = getWidenedLiteralType(paramType) !== paramType
            // tsc widens a FRESH literal-expression arg (`f(true)` → 'boolean')
            // but PRESERVES the literal type of a variable/reference arg whose
            // flow-narrowed type is a literal (`isNever(foo)` where foo: "aaa"|"bbb"
            // narrows to '"bbb"', exhaustiveSwitchCheckCircularity). `literalTypeOfExpression`
            // is the freshness probe (non-null only for literal expressions/keywords).
            // getWidenedLiteralType is a no-op for non-literal argTypes, so this is
            // inert for every arg whose type isn't a literal.
            val argIsFreshLiteral = literalTypeOfExpression(arg) != null
            val argTypeStr = typeToString(
                if (paramIsLiteral || !argIsFreshLiteral) argType else getWidenedLiteralType(argType)
            )
            val paramTypeStr = typeToString(paramType)
            val start = arg.pos
            // 17.238: ArrowFunction with a MULTI-LINE Block body — clip squiggle to
            // end of source line containing the body's `{`. TypeScript clips at the
            // body open brace line only when the body spans multiple source lines;
            // single-line bodies like `() => {}` keep the full arrow span. End-of-line
            // includes any trailing same-line whitespace after `{` (e.g. `{ \n` keeps
            // the trailing space in the squiggle, matching baseline 8-char span).
            val length = if (arg is ArrowFunction && arg.body is Block) {
                val body = arg.body
                val fullEnd = expressionTrueEnd(arg)
                val isMultiLine = body.pos in 0..<source.length &&
                    body.pos < fullEnd &&
                    source.substring(body.pos, fullEnd.coerceAtMost(source.length)).contains('\n')
                if (isMultiLine) {
                    // Find `=>` between arg.pos and body.pos. If `=>` is on a separate line
                    // from `{` (rare: `() =>\n // comment \n {`), clip at end-of-line-of-`=>`
                    // so the squiggle covers only `() =>` (matching TypeScript's narrow span).
                    // Otherwise clip at end-of-line-of-`{` (the common multi-line-body case).
                    val arrowMarkerPos = srcLastIndexOf(source, "=>", (body.pos - 1).coerceAtLeast(0))
                    val anchorPos = if (arrowMarkerPos in start..<body.pos) {
                        // Use the `=>` position to find its line's end-of-line.
                        val arrowEolPos = source.indexOf('\n', arrowMarkerPos).let { if (it < 0) source.length else it }
                        val braceEolPos = source.indexOf('\n', body.pos).let { if (it < 0) source.length else it }
                        // If `=>` and `{` are on different lines, prefer `=>`'s EOL (narrower).
                        if (arrowEolPos < body.pos) arrowEolPos else braceEolPos
                    } else {
                        source.indexOf('\n', body.pos).let { if (it < 0) fullEnd else it }
                    }
                    (anchorPos.coerceAtMost(fullEnd) - start).coerceAtLeast(1)
                } else {
                    fullEnd - start
                }
            } else {
                expressionTrueEnd(arg) - start
            }
            if (length <= 0) return CAAS_CONTINUE
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            // TS6213: If the argument type has construct signatures but no call signatures,
            // suggest "Did you mean to use 'new' with this expression?". TS6212 mirrors
            // this for call signatures whose return type would satisfy the parameter —
            // "Did you mean to call this expression?".
            val relatedInfo: MutableList<Diagnostic> = mutableListOf()
            if (argType is Type.Object) {
                val constructSigs = getConstructSignaturesOfType(argType)
                val callSigs = getCallSignaturesOfType(argType)
                if (constructSigs.isNotEmpty() && callSigs.isEmpty()) {
                    relatedInfo.add(Diagnostic(
                        message = "Did you mean to use 'new' with this expression?",
                        category = DiagnosticCategory.Message,
                        code = 6213,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                } else if (callSigs.isNotEmpty() && arg !is ArrowFunction && arg !is FunctionExpression) {
                    val callingHelpsArg = callSigs.any { sig ->
                        val rt = sig.resolvedReturnType ?: return@any false
                        checkTypeRelatedTo(rt, paramType, assignableRelation)
                    }
                    if (callingHelpsArg) {
                        relatedInfo.add(Diagnostic(
                            message = "Did you mean to call this expression?",
                            category = DiagnosticCategory.Message,
                            code = 6212,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
            }
            // TS2793: overload implementation would have matched.
            // (ENGINE.2h) round 795: THIS is the probe's only reader, so this
            // is where it is computed. The forcing is inside the very
            // invocation the caller deferred it from — nothing was stored, so
            // round 788's lazy-thunk failure mode (a value forced in a
            // different dynamic scope, needing every save/restore site to
            // cooperate) has nothing to bite on; and the argument loop's own
            // `contextualType` install is already restored by here.
            // The loop `break`s right after emitting, so this runs at most
            // once per invocation and needs no memo.
            val implRelated: Diagnostic? = if (!deferImplementationRelated)
                implementationRelated
            else {
                val implT = CallSections.t()
                val deferred = overloadImplementationRelated(
                    args, sigIn, source, fileName,
                    bogus = CallSections.verifyImplRelatedBogus,
                )
                CallSections.close(CallSections.N_IMPL_RELATED, implT)
                if (CallSections.verifyImplRelated) {
                    // Honour the EAGER verdict; only COUNT the disagreement.
                    CallSections.noteImplRelatedVerified(deferred != implementationRelated)
                    implementationRelated
                } else deferred
            }
            if (implRelated != null) {
                relatedInfo.add(implRelated)
            }
            // Union elaboration: find the failing constituent and add as message chain
            val chain = mutableListOf<String>()
            if (argType is Type.Union) {
                // Find the last failing constituent (matches TypeScript's behavior)
                var lastFailing: Type? = null
                for (constituent in argType.types) {
                    if (!checkTypeRelatedTo(constituent, paramType, assignableRelation)) {
                        lastFailing = constituent
                    }
                }
                if (lastFailing != null) {
                    val constStr = typeToString(lastFailing)
                    chain.add("  Type '$constStr' is not assignable to type '$paramTypeStr'.")
                }
            }
            // Private-brand elaboration: "Types have separate declarations of a private property 'X'."
            if (argType is Type.Object && paramType is Type.Object) {
                val mismatchName = findPrivateBrandMismatchName(argType, paramType)
                if (mismatchName != null) {
                    chain.add("  Types have separate declarations of a private property '$mismatchName'.")
                }
            }
            // 16.4dw: Function-to-function elaboration chain — for function-typed
            // argument vs function-typed parameter mismatches. Emits param-mismatch
            // or return-type-mismatch lines, matching the TS2322 elaboration used in
            // assignment contexts.
            if (chain.isEmpty() && argType is Type.Object && paramType is Type.Object &&
                !argType.callSignatures.isNullOrEmpty() && !paramType.callSignatures.isNullOrEmpty()
            ) {
                chain.addAll(getFunctionMismatchElaboration(argType, paramType))
            }
            // B50.4: Object→Object property-elaboration chain. When the B50.4 gate
            // above allowed the structural compare to fire AND a per-property
            // mismatch exists, get the chain from `getPropertyElaborationChain`.
            if (chain.isEmpty() && argType is Type.Object && paramType is Type.Object &&
                argType !is Type.Interface && argType !is Type.Reference &&
                paramType !is Type.Interface && paramType !is Type.Reference &&
                !paramType.properties.isNullOrEmpty()
            ) {
                val propChain = getPropertyElaborationChain(argType, paramType)
                if (propChain != null) chain.addAll(propChain)
            }
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                category = DiagnosticCategory.Error,
                code = 2345,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
                messageChain = chain,
                relatedInformation = relatedInfo,
            ))
            return CAAS_BREAK // TypeScript reports only the first failing argument per call
        }
        return CAAS_NONE
    }


    /**
     * 17.31c: when [sig]'s last parameter is a rest of `Array<X>` (`...args: X[]`)
     * with a fully-resolved element type X (i.e. X is NOT an unsubstituted
     * TypeParam), emit TS2345 for the first trailing arg whose type is not
     * assignable to X. Uses widened-literal display ('string' not '""') to
     * match TypeScript's TS2345 baseline. One emission per call.
     *
     * Skipped when X is still a TypeParam (inference failed or not attempted),
     * when no rest param exists, or when rest paramType isn't `Array<X>`.
     */
    private fun checkRestArgsAgainstArrayElementType(
        sig: Signature,
        args: List<Expression>,
        source: String,
        fileName: String,
    ) {
        val params = sig.parameters
        if (params.isEmpty()) return
        val lastIdx = params.size - 1
        val lastParam = params[lastIdx]
        val isRest = (lastParam.valueDeclaration as? Parameter)?.dotDotDotToken == true
        if (!isRest) return
        val paramType = getTypeOfSymbol(lastParam)
        if (paramType !is Type.Reference) return
        if (paramType.target.symbol?.name != "Array") return
        val tArgs = paramType.resolvedTypeArguments ?: return
        if (tArgs.size != 1) return
        val elementType = tArgs[0]
        if (elementType === errorType || elementType === anyType) return
        // Skip when element is still an unresolved TypeParam — inference either
        // failed or wasn't attempted (e.g. anonymous Object literal arg). The
        // standard pre-rest paths handle bare-T checks for non-rest cases.
        if (elementType is Type.TypeParam) return
        for (i in lastIdx until args.size) {
            val arg = args[i]
            if (arg is SpreadElement) continue
            val argType0 = getTypeOfExpression(arg)
            // M3.4 (round 429d): mirror B469 — a reference arg in a REST position
            // narrows by the flow graph too (`cond ? diag(…, deprecatedEntity) : …`
            // truthy-narrows the `string | undefined` rest arg to `string` — tsc
            // checker.ts addDeprecatedSuggestionWithSignature, ×5 self-compile).
            val argType = if ((arg is Identifier || arg is PropertyAccessExpression) && argType0 is Type.Union) {
                getNarrowedTypeForReference(argType0, arg)
            } else argType0
            if (argType === anyType || argType === errorType) continue
            if (argType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) continue
            // Conservative gate: only emit when argType is a simple/primitive
            // type (string/number/boolean/literal/intrinsic union). Skipping
            // complex args (arrays, objects, named types) avoids FPs from
            // (a) lib methods like `Array.concat` that should have a `T[][]`
            // overload but don't in our parsed lib (so an arg of `T[]` looks
            // like a mismatch against `T[]` element), and (b) structural
            // comparison gaps for nested generic shapes (`Array<{a:T;b:U}>`
            // vs `Array<{a:number;b:string}>` after explicit-typeArg
            // substitution). The original test motivating this helper
            // (`genericRestArgs_ts`) has only literal/primitive args, which
            // pass this gate. Skipping `continue`s rather than `return`s so
            // a later simple-arg mismatch can still emit.
            // B-vararg: ALSO check a NAMED class/interface-instance arg against a
            // PRIMITIVE rest element type (`...rest: string[]` ← `x: C`). A class
            // instance is never assignable to a primitive, so this is FP-safe and
            // mirrors the main-loop "primitive arg vs named class param" rule. The
            // structurally-risky named-vs-named element case stays excluded (element
            // must be simple-checkable here).
            val argIsNamedInstance = argType is Type.Interface && (argType).symbol != null
            if (!isSimpleCheckableType(argType) &&
                !(argIsNamedInstance && isSimpleCheckableType(elementType))) continue
            val ok = checkTypeRelatedTo(argType, elementType, assignableRelation)
            if (!ok) {
                val argDisplay = typeToString(getWidenedLiteralType(argType))
                val paramDisplay = typeToString(elementType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argDisplay' is not assignable to parameter of type '$paramDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2345,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                return
            }
        }
    }

    /**
     * 16.4: Check type argument constraints for call expression type arguments.
     * For each type parameter with a constraint, check the supplied type arg against
     * the instantiated constraint. Emits TS2344.
     */
    private fun checkCallTypeArgConstraints(
        typeParams: List<Type.TypeParam>,
        resolvedTypeArgs: List<Type>,
        typeArgNodes: List<TypeNode>,
        mapper: TypeMapper,
        source: String,
        fileName: String,
    ) {
        val len = minOf(typeParams.size, resolvedTypeArgs.size, typeArgNodes.size)
        for (i in 0 until len) {
            val constraint = typeParams[i].constraint ?: continue
            val argType = resolvedTypeArgs[i]
            if (argType === anyType || argType === errorType) continue
            // Instantiate the constraint (e.g., `U extends T` where T is mapped to number → constraint = number)
            val instantiatedConstraint = instantiateType(constraint, mapper)
            if (instantiatedConstraint === anyType || instantiatedConstraint === errorType) continue
            // TS2559 weak-type rule: when the (instantiated) constraint is a "weak type"
            // (object with ≥1 property, ALL optional, no index/call/construct sigs) and the
            // supplied type arg is an object sharing NO property name with it, TypeScript
            // reports "Type 'X' has no properties in common with type 'Y'." — even when X is
            // otherwise structurally assignable. Fires at the type-arg node, supersedes TS2344.
            if (isWeakObjectType(instantiatedConstraint) && hasNoCommonProperties(argType, instantiatedConstraint)) {
                val argNode = typeArgNodes[i]
                val argDisplay = formatTypeForDisplay(argNode) ?: typeToString(argType)
                var wEnd = argNode.end
                while (wEnd > argNode.pos && source.getOrNull(wEnd - 1)?.let {
                    it == ' ' || it == '\t' || it == '\n' || it == '\r' ||
                    it == ',' || it == '>' || it == ')' || it == ';'
                } == true) wEnd--
                val wLen = if (wEnd > argNode.pos) wEnd - argNode.pos else argDisplay.length
                if (wLen > 0) {
                    val (wLine, wChar) = getLineAndCharacterOfPosition(source, argNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$argDisplay' has no properties in common with type '${typeToString(instantiatedConstraint)}'.",
                        category = DiagnosticCategory.Error,
                        code = 2559,
                        fileName = fileName,
                        line = wLine,
                        character = wChar,
                        start = argNode.pos,
                        length = wLen,
                    ))
                    continue
                }
            }
            lastMissingPropertyName = null
            lastMissingPropertySymbol = null
            if (!checkTypeRelatedTo(argType, instantiatedConstraint, assignableRelation)) {
                // A TypeParam arg satisfies the target constraint when its OWN constraint does
                // (`createNodeArray<T>()` calling `createNodeArray<U extends Node>` with `T
                // extends Node` — T's constraint Node ≤ Node → satisfies). Our relation engine's
                // TypeParam-source path under-resolves, so check the constraint chain explicitly
                // (mirrors the TypeReference path's skip in checkConstraintsForTypeArgs). Only
                // fires when the arg HAS a constraint (an unconstrained T → apparent `{}` → would
                // over-skip and lose genuine TS2344 cases).
                if (argType is Type.TypeParam && argType.constraint != null) {
                    val cnst = argType.constraint!!
                    if (cnst !== anyType && cnst !== errorType &&
                        checkTypeRelatedTo(cnst, instantiatedConstraint, assignableRelation)) {
                        continue
                    }
                }
                // Round 729: the same question one level in. An EXPLICIT call type argument
                // spelled `NonNullable<U>` is `U & {}`, so the TypeParam arm above never sees
                // it — round 725 taught the type-REFERENCE site to look through the
                // intersection and this site was left behind (`createNodeArray<NonNullable<T>>
                // (…)`). Shares the helper, so both arms strip nullish only when the `& {}`
                // marker is present and both leave a constituent-less intersection alone.
                if (argType is Type.Intersection &&
                    intersectionSatisfiesViaTypeParamConstraint(argType, instantiatedConstraint)) {
                    continue
                }
                val argNode = typeArgNodes[i]
                val argDisplay = formatTypeForDisplay(argNode) ?: typeToString(argType)
                // 16.4gb: For anonymous Type.Object constraints where instantiateType
                // doesn't rewrite member types, render with explicit substitution so a
                // constraint like `{ a: T }` with T→string displays as `{ a: string; }`.
                val constraintDisplay = typeToStringWithMapper(instantiatedConstraint, mapper)
                val start = argNode.pos
                // 16.4gb: Use the source span (trim trailing whitespace/`,`/`>`/`;`) instead
                // of display-text length. Source text `{ a: number }` is 13 chars but display
                // renders as `{ a: number; }` (14 chars) — display length over-extends the
                // squiggle past the source text.
                var trueEnd = argNode.end
                while (trueEnd > start && source.getOrNull(trueEnd - 1)?.let {
                    it == ' ' || it == '\t' || it == '\n' || it == '\r' ||
                    it == ',' || it == '>' || it == ')' || it == ';'
                } == true) trueEnd--
                val length = if (trueEnd > start) trueEnd - start else argDisplay.length
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                val chain = mutableListOf<String>()
                val missingProp = lastMissingPropertyName
                val missingPropSym = lastMissingPropertySymbol
                val relatedInfo = mutableListOf<Diagnostic>()
                if (missingProp != null) {
                    chain.add("  Property '$missingProp' is missing in type '$argDisplay' but required in type '$constraintDisplay'.")
                    missingPropSym?.let { createPropertyDeclaredHereRelatedInfo(it) }?.let { relatedInfo.add(it) }
                } else if (argType is Type.Object && instantiatedConstraint is Type.Object) {
                    // 16.4gb: Property-type-mismatch elaboration. When both sides have the
                    // same property but its types are incompatible, emit
                    //   "  Types of property 'X' are incompatible."
                    //   "    Type 'A' is not assignable to type 'B'."
                    // mirroring TS2322's per-property elaboration chain.
                    resolveStructuredTypeMembers(argType)
                    resolveStructuredTypeMembers(instantiatedConstraint)
                    val argMembers = argType.members ?: emptyMap()
                    val cProps = instantiatedConstraint.properties ?: emptyList()
                    for (cp in cProps) {
                        val ap = argMembers[cp.name] ?: continue
                        val cpType = symbolTypes[cp.id] ?: continue
                        val apType = symbolTypes[ap.id] ?: continue
                        val cpTypeInst = instantiateType(cpType, mapper)
                        if (cpTypeInst === anyType || cpTypeInst === errorType) continue
                        if (!checkTypeRelatedTo(apType, cpTypeInst, assignableRelation)) {
                            val cpDisplay = typeToStringWithMapper(cpType, mapper)
                            chain.add("  Types of property '${cp.name}' are incompatible.")
                            chain.add("    Type '${typeToString(apType)}' is not assignable to type '$cpDisplay'.")
                            break
                        }
                    }
                }
                diagnostics.add(Diagnostic(
                    message = "Type '$argDisplay' does not satisfy the constraint '$constraintDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2344,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                    messageChain = chain,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * TS2559: a "weak type" is an object/interface with at least one property, where ALL
     * properties are optional, and there are NO index/call/construct signatures. (Matches
     * TypeScript's `isWeakType`.) Used by the type-arg-constraint weak-type rule.
     */
    private fun isWeakObjectType(type: Type): Boolean {
        val obj = type as? Type.Object ?: return false
        resolveStructuredTypeMembers(obj)
        if (obj.stringIndexInfo != null || obj.numberIndexInfo != null) return false
        if (!obj.callSignatures.isNullOrEmpty() || !obj.constructSignatures.isNullOrEmpty()) return false
        val props = obj.properties ?: return false
        if (props.isEmpty()) return false
        return props.all { isOptionalProperty(it) }
    }

    /**
     * TS2559: true when [arg] is an object/interface with ≥1 property, NO index/call/
     * construct signatures, and shares NO property NAME with [target]. Conservative — an
     * arg carrying an index/call signature is treated as potentially-common (returns false,
     * no fire), and a shared property name (even with a mismatched type) also returns false
     * so the standard TS2344 relation path handles it instead.
     */
    private fun hasNoCommonProperties(arg: Type, target: Type): Boolean {
        val a = arg as? Type.Object ?: return false
        resolveStructuredTypeMembers(a)
        if (a.stringIndexInfo != null || a.numberIndexInfo != null) return false
        if (!a.callSignatures.isNullOrEmpty() || !a.constructSignatures.isNullOrEmpty()) return false
        val aProps = a.properties ?: return false
        if (aProps.isEmpty()) return false
        val t = target as? Type.Object ?: return false
        val tNames = (t.properties ?: emptyList()).map { it.name }.toSet()
        if (tNames.isEmpty()) return false
        return aProps.none { it.name in tNames }
    }

    /**
     * Check if a type is "simple" enough that we can safely check TS2345 against it
     * without risking false positives from incomplete structural comparison.
     * Returns true for primitive types (string, number, boolean, void, null, undefined, never,
     * bigint, symbol) and their literal variants.
     */
    private fun isSimpleCheckableType(type: Type): Boolean {
        val f = type.flags
        if (f.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.Void or TypeFlags.Undefined or TypeFlags.Null or
            TypeFlags.Never or TypeFlags.BigInt or TypeFlags.ESSymbol or
            TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
            TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral
        )) return true
        // NOTE: `object` (TypeFlags.NonPrimitive) is deliberately NOT here — see
        // [isArgCheckableType], which adds it for the two ARGUMENT-position gates only.
        // Allow union types where all members are checkable (e.g., string | number)
        if (type is Type.Union) {
            if (type.types.any { it === anyType || it === errorType }) return false
            return type.types.all { isSimpleCheckableType(it) }
        }
        return false
    }

    /**
     * (NONPRIM.1) round 834: [isSimpleCheckableType] PLUS the `object` keyword, for the
     * two ARGUMENT-position gates only.
     *
     * `object` earns the same treatment as `string` here: since this round its relation
     * rule answers exactly tsc's — an Object-flagged source and nothing else — so there
     * is no incomplete structural comparison left for an argument verdict to get wrong.
     *
     * It is a SEPARATE predicate rather than an extra flag inside
     * [isSimpleCheckableType] because that one has 45 consumers, several of which are
     * dedicated walkers whose whole FP firewall it is. Widening it in place was tried
     * and measured: B498's `f<object>(123)` walker ([checkGenericDefaultParamCall])
     * immediately co-emitted with the general path, producing a duplicate TS2345 at one
     * position on `nonPrimitiveInGeneric`. Add a call site here only after checking that
     * the site is not itself a walker's gate.
     */
    private fun isArgCheckableType(type: Type): Boolean =
        isSimpleCheckableType(type) || type.flags.hasAny(TypeFlags.NonPrimitive)

    // -----------------------------------------------------------------------
    // Structural typing engine (Phase 4 items 4a-4e)
    // -----------------------------------------------------------------------

    /** Ternary logic for type relations: True, False, or Maybe (for recursive checks). */
    private enum class Ternary { True, False, Maybe }

    /** Relation cache — maps (sourceId, targetId) packed into Long → result. */
    private class Relation {
        private val cache = HashMap<Long, Ternary>()

        /**
         * (WARM.31) round 904 — arm B of the boxed-key amplifier, populated in
         * LOCKSTEP with [cache] and read only under `--boxedKeyAmp`. It is the
         * primitive-keyed successor this whole candidate is about, and putting it
         * HERE rather than in a synthetic loop is what keeps the measurement
         * honest: the same key stream, the same table occupancy, the same cache
         * residency (round 897 — a leaf profile cannot see a working-set effect,
         * so a bench-rig key sequence would price a different machine state).
         *
         * `LongKeyMap` reserves key 0 as its empty-slot sentinel, so a key of
         * exactly 0 is skipped and COUNTED rather than assumed impossible.
         */
        private val shadow = LongKeyMap<Ternary>(1024)

        fun get(sourceId: Int, targetId: Int): Ternary? {
            val k = packKey(sourceId, targetId)
            if (MapCensus.boxedKeyCensus) MapCensus.bk(MapCensus.BK_REL_CACHE, k)
            if (MapCensus.boxedKeyAmp > 0) amp(k)
            return cache[k]
        }

        /**
         * Two arms under one timestamp pair each, order alternating per call so a
         * drift inside the rebuild lands on both. Neither arm's key is computed
         * inside its bracket, so what is measured is the PROBE and nothing else.
         *
         * Two falsifiers ride along. (1) Each sink is 0 or `r` per call, hence an
         * exact multiple of `r` — and the two sinks must be EQUAL, which is the
         * lockstep control: they diverge the moment the shadow stops mirroring.
         * (2) A `HashMap` probe on an unchanging key is loop-invariant-looking, so
         * C2 may hoist it; the falsifier for that is the SLOPE between two `r`,
         * never the sink (round 903).
         */
        private fun amp(k: Long) {
            val r = MapCensus.boxedKeyAmp
            val boxedFirst = (MapCensus.bkAmpCalls and 1L) == 0L
            if (boxedFirst) { ampBoxed(k, r); ampPrimitive(k, r) }
            else { ampPrimitive(k, r); ampBoxed(k, r) }
            MapCensus.bkAmpCalls++
        }

        private fun ampBoxed(k: Long, r: Int) {
            val t0 = PassTiming.nowNanos()
            var s = 0L
            var i = 0
            while (i < r) { if (cache[k] != null) s++; i++ }
            MapCensus.bkAmpBoxedNanos += PassTiming.nowNanos() - t0
            MapCensus.bkAmpBoxedSink += s
        }

        private fun ampPrimitive(k: Long, r: Int) {
            val t0 = PassTiming.nowNanos()
            var s = 0L
            var i = 0
            while (i < r) { if (shadow.get(k) != null) s++; i++ }
            MapCensus.bkAmpPrimNanos += PassTiming.nowNanos() - t0
            MapCensus.bkAmpPrimSink += s
        }

        fun set(sourceId: Int, targetId: Int, result: Ternary) {
            val k = packKey(sourceId, targetId)
            if (MapCensus.boxedKeyCensus) MapCensus.bk(MapCensus.BK_REL_CACHE, k)
            cache[k] = result
            if (MapCensus.boxedKeyAmp > 0) {
                if (k != 0L) shadow.put(k, result) else MapCensus.bkAmpSentinelKeys++
            }
        }

        /** (HASH.1)(b) round 890: see [packIdPair] — this map's 43,080 real keys
         *  collapsed onto 18,201 hashes, 1,140 of them in a single bucket. */
        private fun packKey(a: Int, b: Int): Long = packIdPair(a, b)
    }

    /**
     * 4a. Fast flag-based type relatedness check (no recursion).
     * Returns true if the relation holds purely from type flags.
     */
    private fun isSimpleTypeRelatedTo(source: Type, target: Type): Boolean {
        val sf = source.flags
        val tf = target.flags
        // Any target accepts everything
        if (tf.hasAny(TypeFlags.Any)) return true
        // Any source is assignable to everything (any is both top and bottom type)
        if (sf.hasAny(TypeFlags.Any)) return true
        // Unknown target accepts everything (for assignability)
        if (tf.hasAny(TypeFlags.Unknown)) return true
        // Never source is assignable to everything
        if (sf.hasAny(TypeFlags.Never)) return true
        // Same type by identity
        if (source === target) return true
        // Literal value comparison (different instances with same value)
        if (source is Type.StringLiteral && target is Type.StringLiteral && source.value == target.value) return true
        if (source is Type.NumberLiteral && target is Type.NumberLiteral && source.value == target.value) return true
        if (source is Type.BigIntLiteral && target is Type.BigIntLiteral && source.value == target.value) return true
        // Primitive widening: string literal → string, number literal → number, etc.
        if (sf.hasAny(TypeFlags.StringLiteral) && tf.hasAny(TypeFlags.String)) return true
        if (sf.hasAny(TypeFlags.NumberLiteral) && tf.hasAny(TypeFlags.Number)) return true
        if (sf.hasAny(TypeFlags.BigIntLiteral) && tf.hasAny(TypeFlags.BigInt)) return true
        if (sf.hasAny(TypeFlags.BooleanLiteral) && tf.hasAny(TypeFlags.Boolean)) return true
        // (REL.1)(c) round 746: an enum MEMBER widens to an enum — but only to an enum
        // its OWN enum relates to. Unconditional, this made `Z.Foo.A` assignable to
        // `X.Foo`, which is the verdict B266 existed to supply.
        if (sf.hasAny(TypeFlags.EnumLiteral) && tf.hasAny(TypeFlags.Enum)) {
            val sourceEnum = enumOfMemberTypeSymbol(source)
            val targetEnum = enumOwnTypeSymbol(target)
            if (sourceEnum == null || targetEnum == null) return true
            if (enumTypesRelation(sourceEnum, targetEnum) == null) return true
        }
        if (sf.hasAny(TypeFlags.UniqueESSymbol) && tf.hasAny(TypeFlags.ESSymbol)) return true
        // String-like types to string
        if (sf.hasAny(TypeFlags.StringLike) && tf.hasAny(TypeFlags.String)) return true
        if (sf.hasAny(TypeFlags.NumberLike) && tf.hasAny(TypeFlags.Number)) return true
        if (sf.hasAny(TypeFlags.BigIntLike) && tf.hasAny(TypeFlags.BigInt)) return true
        // undefined → void
        if (sf.hasAny(TypeFlags.Undefined) && tf.hasAny(TypeFlags.Void)) return true
        // void → undefined (void is treated as undefined for assignability)
        if (sf.hasAny(TypeFlags.Void) && tf.hasAny(TypeFlags.Undefined)) return true
        // When strict null checks are off, null/undefined assignable to everything
        if (!strictNullChecks && sf.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return true
        // number → enum type (TypeScript allows number → enum)
        //
        // (REL.1)(c) round 745: VALUE-AWARE for a numeric LITERAL source. tsc models
        // an all-literal enum as the UNION of its members' literal types, so `4` is
        // assignable to `E` only when some member IS 4; the wide `number` stays
        // assignable either way (the bit-flag rule). [numericLiteralFitsEnum] answers
        // `true` for every non-literal source and for every enum whose domain we
        // cannot fully evaluate, so this can only reject a numeric literal we have
        // proved out of range.
        if (sf.hasAny(TypeFlags.NumberLike) && target is Type.Object && target.symbol != null &&
            target.symbol!!.flags.hasAny(SymbolFlags.Enum)) {
            if (numericLiteralFitsEnum(source, target)) return true
        }
        // M3.1 (round 428b): numeric-enum → number (a numeric enum's values ARE
        // numbers — tsc debug.ts `formatEnum(this.flags, …)` where flags: FlowFlags
        // vs a `number` param). String-valued enums excluded by the classifier.
        if (tf.hasAny(TypeFlags.Number) && isNumericEnumObjectType(source)) return true
        // M3.1 (round 429d): string-enum → string, the string sibling (an ALL-string-
        // valued enum is a union of string literals in tsc — `changeAnyExtension(path,
        // Extension.Dts)` vs a `string` param; also cascades to `Extension[]` →
        // `string[]` via the same-target covariant element comparison). Mixed/numeric/
        // unknown-valued enums excluded (conservative: unevaluated → not provable).
        if (tf.hasAny(TypeFlags.String) && isStringEnumObjectType(source)) return true
        // (REL.1)(a) round 741: an enum MEMBER type ↔ its BASE PRIMITIVE, in BOTH
        // directions. This is the whole measured gap of step (a): `SK.A` used to be
        // `anyType`, which related to everything, so every primitive answer around an
        // enum-member annotation was vacuously true. A numeric member relates to and
        // from NumberLike (tsc keeps that both-ways rule for bit-flag enums), a
        // string-valued member to and from StringLike.
        //
        // VALUE-AWARE since (REL.1)(c) round 745, which is what retired
        // `checkEnumLiteralAssignments`: `let a: E.A = 2` where `A === 0` is the
        // relation's error now. Only a numeric LITERAL is judged by value — the wide
        // `number` stays assignable to any numeric member, which is why `a = n`
        // (n: number) is legal in the same test.
        //
        // (REL.1)(b) round 742 REMOVED the string TARGET half. Step (a) had it only for
        // behaviour-preservation symmetry with the former `anyType`; tsc REJECTS
        // `string → Ext.Dts`, because a string enum is NOMINAL and — unlike the numeric
        // direction, which tsc keeps for bit-flag enums — there is no compatibility rule
        // to justify it.
        if (sf.hasAny(TypeFlags.EnumLiteral) || tf.hasAny(TypeFlags.EnumLiteral)) {
            enumMemberTypeIsStringValued(source)?.let { sourceIsString ->
                if (tf.hasAny(if (sourceIsString) TypeFlags.StringLike else TypeFlags.NumberLike)) return true
            }
            enumMemberTypeIsStringValued(target)?.let { targetIsString ->
                if (!targetIsString && sf.hasAny(TypeFlags.NumberLike) &&
                    numericLiteralFitsEnum(source, target)
                ) return true
            }
        }
        // The `object` keyword (round 834, (NONPRIM.1)). tsc's rule is POSITIVE —
        // `s & TypeFlags.Object && t & TypeFlags.NonPrimitive` — i.e. the ONLY sources
        // that satisfy `object` are the ones carrying the Object flag. This used to be
        // written as its NEGATION ("not flagged primitive"), which is not the same
        // predicate, because [TypeFlags.Primitive] omits every LITERAL bit: a
        // `Type.StringLiteral`/`NumberLiteral`/boolean-literal source, a bare
        // `Type.TypeParam`, `unknown`, and `keyof`/indexed-access types all read as
        // "not primitive" and were silently accepted. That is what made
        // `{ foo: "bar" }` satisfy `{ foo: object }`'s value position and — one level
        // out — made the conditional `T[P] extends V | object` answer TRUE for a
        // numeric-literal `T[P]`, inventing a whole FP one type away from any `object`.
        //
        // A `false` here is NOT a rejection: [checkTypeRelatedToCore] falls through to
        // the structural engine, where the Union/Intersection source branches decompose
        // and [structuredTypeRelatedTo]'s TypeParam leg consults a constraint. Only
        // shapes that reach neither end up rejected.
        if (tf.hasAny(TypeFlags.NonPrimitive)) {
            return sf.hasAny(TypeFlags.Object or TypeFlags.NonPrimitive)
        }
        return false
    }

    /**
     * 4b. Main entry point for type relation checking with error reporting.
     * Returns true if source is related to target in the given relation.
     */
    private fun checkTypeRelatedTo(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        if (PassTiming.detailed) {
            if (relProbeDepth++ == 0) {
                val t0 = PassTiming.nowNanos()
                try { return checkTypeRelatedToCore(source, target, relation) }
                finally { PassTiming.relationNanos += PassTiming.nowNanos() - t0; relProbeDepth-- }
            }
            try { return checkTypeRelatedToCore(source, target, relation) } finally { relProbeDepth-- }
        }
        return checkTypeRelatedToCore(source, target, relation)
    }

    /**
     * Round 754: the DEFAULTED INSTANTIATION of an open generic that reaches the
     * relation raw, or null when [type] is not one.
     *
     * A reference that omits the type arguments of a generic whose every parameter
     * carries a default — `EvaluatorResult` for `EvaluatorResult<T extends string |
     * number | undefined = string | number | undefined>` — resolves to the RAW
     * `Type.Interface`, whose members still carry the un-substituted `T`. Nothing
     * relates a `Type.Reference` to that (the trap round 726 hit from the other
     * side), so `EvaluatorResult<number>` was not assignable to a bare
     * `EvaluatorResult` annotation and TS2322 fired on correct code — 16 of them in
     * tsc's own `utilities.ts`.
     *
     * The normalisation is done HERE and not in `getTypeFromTypeReference` (where tsc
     * does it, as `fillMissingTypeArguments`) for one measured reason: filling at
     * resolution makes a bare `TableClass` and an explicit `TableClass<any>` the SAME
     * interned instance, and `aliasDisplayMap` excludes `Type.Reference` on purpose —
     * so `type Table = TableClass` stopped displaying as `Table`
     * (`typeVariableConstraintedToAliasNotAssignableToUnion`, 8 baseline lines, error
     * set otherwise unchanged). At the relation boundary the answer changes and no
     * display does.
     *
     * A parameter WITHOUT a resolved default returns null, which keeps the old
     * behaviour: omitting a REQUIRED type argument is TS2314, reported on its own.
     */
    private fun defaultedInstantiationOfOpenGeneric(type: Type): Type? {
        if (type !is Type.Interface) return null // Type.Reference is NOT an Interface
        val tps = type.typeParameters ?: return null
        if (tps.isEmpty()) return null
        val args = ArrayList<Type>(tps.size)
        for (tp in tps) {
            val d = tp.default ?: return null
            if (d === errorType) return null
            args.add(d)
        }
        return getOrInternReference(type, args)
    }

    private fun checkTypeRelatedToCore(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        if (source === target) return true
        // Round 754: normalise an open all-defaulted generic to its defaulted
        // instantiation before anything else looks at it — see
        // [defaultedInstantiationOfOpenGeneric]. The recursion terminates because a
        // `Type.Reference` is not a `Type.Interface`, so the normalisation never
        // fires twice on the same side.
        run {
            val ns = defaultedInstantiationOfOpenGeneric(source)
            val nt = defaultedInstantiationOfOpenGeneric(target)
            if (ns != null || nt != null) {
                return checkTypeRelatedToCore(ns ?: source, nt ?: target, relation)
            }
        }
        // Fast check
        if (isSimpleTypeRelatedTo(source, target)) return true
        // (REL.1)(b): two enum-member types relate ONLY when they are the same
        // member. Both are member-less `Type.Object`s, so without this the structural
        // engine below relates them VACUOUSLY in both directions — which is what made
        // two AST node interfaces differing only in `readonly kind: SK.A` vs `SK.B`
        // mutually assignable. The verdict is STRUCTURAL, not identity: see
        // [enumMemberTypesAreSameMember].
        if (source.flags.hasAny(TypeFlags.EnumLiteral) && target.flags.hasAny(TypeFlags.EnumLiteral)) {
            return enumMemberTypesAreSameMember(source, target)
        }
        // (REL.1)(c) round 746: two ENUMS, and an enum MEMBER against an enum, relate by
        // tsc's `isEnumTypeRelatedTo` — every source member present in the target with an
        // equal value. BOTH verdicts have to be reached HERE and not in
        // [isSimpleTypeRelatedTo]: every enum-flavored type is a member-less
        // `Type.Object`, so a `false` there merely falls through to the structural engine,
        // which relates two empty objects VACUOUSLY. That vacuous `true` is why
        // `checkEnumToEnumAssignments` (B425) owned all 12 of `enumAssignmentCompat3` and
        // `checkNamespaceEnumUnionAssignments` (B266) the two whole-enum targets of
        // `enumLiteralAssignableToEnumInsideUnion`.
        //
        // (REL.2) round 783: the enum → MEMBER direction, decided HERE for the same reason
        // as the two above. tsc models a literal enum AS the union of its members, so `K`
        // is assignable to a target built out of K's members exactly when those members
        // COVER K — which rejects `K -> K.A` for a multi-member enum and keeps the
        // one-member and fully-covering cases. Contained to a target that is entirely
        // members of THIS enum ([enumTargetsAreOwnMembers], the round-746 owner rule):
        // anything else falls through to the pre-existing answer.
        if (REL2_ENUM_TO_MEMBER) run {
            enumOwnTypeSymbol(source) ?: return@run
            val targets = if (target is Type.Union) target.types else listOf(target)
            if (targets.any { enumOfMemberTypeSymbol(it) == null }) return@run
            if (!enumTargetsAreOwnMembers(source, targets)) return@run
            // A non-decomposable enum cannot be shown to be covered, and an enum whose
            // domain is unknown is not a subtype of a proper subset of it.
            val members = enumMemberTypesOf(source) ?: return false
            return members.all { m -> targets.any { enumMemberTypesAreSameMember(m, it) } }
        }
        run {
            val targetEnum = enumOwnTypeSymbol(target) ?: return@run
            val sourceEnum = enumOwnTypeSymbol(source) ?: enumOfMemberTypeSymbol(source) ?: return@run
            return enumTypesRelation(sourceEnum, targetEnum) == null
        }
        // Check cache
        val cached = relation.get(source.id, target.id)
        if (cached == Ternary.True) return true
        if (cached == Ternary.False) return false
        // Depth limit (safety net)
        if (relationDepth >= maxRelationDepth) return false
        // Cycle detection: if we're already comparing this (source, target) pair,
        // assume compatibility to break the cycle (TypeScript's approach for recursive types).
        val pairKey = packRelationKey(source.id, target.id)
        // (WARM.31) round 904 — three boxed-`Long` set operations per reaching
        // call (contains here, add below, remove in the `finally`), plus the two
        // `countOccurrences` scans over the boxed-`Int` target stacks.
        if (MapCensus.boxedKeyCensus) MapCensus.bk(MapCensus.BK_REL_STACK, pairKey)
        if (pairKey in state.relationComparisonStack) {
            relationUsedCycleBreak = true
            return true
        }
        // Deeply-nested heuristic (matches TypeScript's `isDeeplyNestedType`): when
        // either side's `target.id` already appears 5+ times on its respective stack,
        // assume compatibility. Catches infinitely-expanding generic comparisons like
        // `A<T> { x: A<()=>T> }` vs `B<T> { x: B<()=>T> }` whose Refs grow unboundedly
        // and never re-occur identically (so id-based cycle detection alone never fires).
        val srcRef = source as? Type.Reference
        val tgtRef = target as? Type.Reference
        if (srcRef != null && countOccurrences(state.relationSourceTargets, srcRef.target.id) >= 5) {
            relationUsedCycleBreak = true
            return true
        }
        if (tgtRef != null && countOccurrences(state.relationTargetTargets, tgtRef.target.id) >= 5) {
            relationUsedCycleBreak = true
            return true
        }
        if (MapCensus.boxedKeyCensus) {
            MapCensus.bk(MapCensus.BK_REL_STACK, pairKey)
            MapCensus.bkPush(MapCensus.BK_REL_STACK)
        }
        state.relationComparisonStack.add(pairKey)
        if (srcRef != null) state.relationSourceTargets.add(srcRef.target.id)
        if (tgtRef != null) state.relationTargetTargets.add(tgtRef.target.id)
        if (MapCensus.boxedKeyCensus) {
            if (srcRef != null) {
                MapCensus.bk(MapCensus.BK_REL_TARGETS, srcRef.target.id.toLong())
                MapCensus.bkPush(MapCensus.BK_REL_TARGETS)
            }
            if (tgtRef != null) {
                MapCensus.bk(MapCensus.BK_REL_TARGETS, tgtRef.target.id.toLong())
                MapCensus.bkPush(MapCensus.BK_REL_TARGETS)
            }
        }
        if (relationDepth == 0) state.genericPropInstantiationBudget = 2_000
        relationDepth++
        val savedCycleBreak = relationUsedCycleBreak
        relationUsedCycleBreak = false
        // B202.3 (finally-hygiene): unwind the relation stacks even when a
        // StackOverflowError propagates out of structuredTypeRelatedTo — without
        // this, the init boundary guard catches the SOE but the stacks stay
        // corrupted (stale pair keys suppress every later comparison of the same pair).
        val result: Boolean
        val usedCycle: Boolean
        try {
            result = structuredTypeRelatedTo(source, target, relation)
            usedCycle = relationUsedCycleBreak
        } finally {
            relationUsedCycleBreak = savedCycleBreak || relationUsedCycleBreak
            relationDepth--
            if (MapCensus.boxedKeyCensus) {
                MapCensus.bk(MapCensus.BK_REL_STACK, pairKey)
                MapCensus.bkPop(MapCensus.BK_REL_STACK)
                if (tgtRef != null) MapCensus.bkPop(MapCensus.BK_REL_TARGETS)
                if (srcRef != null) MapCensus.bkPop(MapCensus.BK_REL_TARGETS)
            }
            if (tgtRef != null) state.relationTargetTargets.removeAt(state.relationTargetTargets.lastIndex)
            if (srcRef != null) state.relationSourceTargets.removeAt(state.relationSourceTargets.lastIndex)
            state.relationComparisonStack.remove(pairKey)
        }
        // Only cache "true" results that were NOT influenced by cycle assumptions.
        // A "true" result from cycle detection is speculative — it may be wrong
        // once the full comparison completes (typeComparisonCaching test verifies this).
        // "false" results are always safe to cache — if it failed even with the
        // cycle break giving it the benefit of the doubt, it's genuinely incompatible.
        if (!result || !usedCycle) {
            val ternary = if (result) Ternary.True else Ternary.False
            relation.set(source.id, target.id, ternary)
        }
        return result
    }

    /** (HASH.1)(b) round 890: see [packIdPair]. Load-bearing for
     *  [CheckerState.resolvedPropertyTypes] (10,482 keys, max bucket 10 -> 6);
     *  the three recursion stacks it also keys hold at most 27 entries at once
     *  (measured), so for them the finalizer is free rather than a saving. */
    private fun packRelationKey(a: Int, b: Int): Long = packIdPair(a, b)

    private fun countOccurrences(stack: List<Int>, id: Int): Int {
        // (WARM.31) round 904 — each element visit UNBOXES an `Integer`; that, not
        // the add/remove, is where an `ArrayList<Int>` costs more than an `IntArray`,
        // so the scan STEPS are what the census counts here.
        if (MapCensus.boxedKeyCensus) MapCensus.bkScan(MapCensus.BK_REL_TARGETS, stack.size)
        var n = 0
        for (e in stack) if (e == id) n++
        return n
    }

    /**
     * Round 744: `A & (B | C)` DENOTES `(A & B) | (A & C)`, so it relates to a target
     * exactly when BOTH distributed members do. We store the intersection
     * UN-distributed, and every rule below then asks the WHOLE intersection against one
     * union member at a time — `A & (B | C)` against `B` fails, because neither `A → B`
     * nor `B | C → B` holds — so an intersection-over-union source related to nothing.
     *
     * It stayed invisible because the two sides are usually the SAME interned instance
     * (the `source === target` fast path). It shows the moment the union constituents
     * are written in a DIFFERENT ORDER on the two sides — which is exactly how tsc's
     * `getNameOrArgument` writes them (utilities.ts:4175: an
     * `ElementAccessExpression & { argumentExpression: StringLiteralLike | NumericLiteral }`
     * member returned into `MemberName | (Expression & (NumericLiteral | StringLiteralLike))`).
     * Interning a union by SORTED constituent ids would also hide it, and must not be
     * done: union display order is pinned to pristine tsc's source order.
     *
     * Strictly a FALLBACK — consulted only after the plain rule has already answered
     * false, so it can only turn a rejection into an acceptance. Distributes the FIRST
     * union constituent only, and bails on a wide one: the shapes this exists for carry
     * a single small union, and a full cartesian product is not worth paying for on a
     * path that has already failed.
     */
    private fun intersectionSourceDistributes(
        source: Type.Intersection,
        target: Type,
        relation: Relation,
    ): Boolean {
        val unionIndex = source.types.indexOfFirst { it is Type.Union }
        if (unionIndex < 0) return false
        val union = source.types[unionIndex] as Type.Union
        if (union.types.size > 8) return false
        val rest = source.types.filterIndexed { index, _ -> index != unionIndex }
        return union.types.all { member ->
            val distributed = getIntersectionType(rest + member)
            distributed !== source && checkTypeRelatedTo(distributed, target, relation)
        }
    }

    /**
     * 4c. Core structural comparison — handles unions, intersections, and objects.
     */
    private fun structuredTypeRelatedTo(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        // Union source: each constituent must be related to the target
        if (source is Type.Union) {
            return source.types.all { checkTypeRelatedTo(it, target, relation) }
        }
        // Union target: source must be related to some constituent
        if (target is Type.Union) {
            // Round 435e: the (source, union) frame's own source-stack entry is
            // REDUNDANT with each member call's re-push of the SAME source instance —
            // pop it around the member iteration so a union decomposition doesn't
            // read as a re-entry to the same-target arg-shortcut below
            // (`NodeArray<TemplateSpan>` vs `NodeArray<Node> | undefined` was
            // deferred into structural comparison, which FPs on Array-method
            // contravariance — tsc's getContainingNodeArray family ×23). A genuine
            // member-recursion re-entry (recursiveTypeComparison's Observable
            // reached through needThisOne) has TWO distinct frames and still defers.
            if (source is Type.Reference) {
                state.relationSourceTargets.removeAt(state.relationSourceTargets.lastIndex)
                try {
                    return target.types.any { checkTypeRelatedTo(source, it, relation) }
                } finally {
                    state.relationSourceTargets.add(source.target.id)
                }
            }
            if (target.types.any { checkTypeRelatedTo(source, it, relation) }) return true
            // Round 744: `A & (B | C)` vs `B | C` — see [intersectionSourceDistributes].
            return source is Type.Intersection &&
                intersectionSourceDistributes(source, target, relation)
        }
        // Intersection target: source must be related to each constituent
        if (target is Type.Intersection) {
            return target.types.all { checkTypeRelatedTo(source, it, relation) }
        }
        // Intersection source: some constituent must be related to target.
        // BUT the "any constituent relates" shortcut is too lenient — tsc merges the
        // intersection's members and checks them structurally. A constituent can satisfy
        // the target while ANOTHER constituent contributes a PRESENT property whose type
        // contradicts the target (intersectionsAndOptionalProperties: `{a:null} & {b:string}`
        // relates via `{b:string}`, but the merged `a:null` ⊄ `number | undefined`). Catch
        // that case: a property present in the merged intersection that fails the target is
        // a genuine mismatch. Bounded to a plain (non-tuple) object target to keep the FP
        // surface minimal (tuple/array targets keep the prior behavior).
        if (source is Type.Intersection) {
            if (target is Type.Object && target.tupleElementTypes == null &&
                intersectionMergedContradictsTarget(source, target, relation)) {
                return false
            }
            if (source.types.any { checkTypeRelatedTo(it, target, relation) }) return true
            // (CHK.61)(1) PROBE: the symmetric ACCEPTANCE twin.
            if (target is Type.Object && target.tupleElementTypes == null &&
                intersectionMergedSatisfiesTarget(source, target, relation)) {
                return true
            }
            // Round 744: `A & (B | C)` vs anything — see [intersectionSourceDistributes].
            return intersectionSourceDistributes(source, target, relation)
        }
        // Generic type references with matching target: compare type arguments directly.
        // For Ref<A> vs Ref<B> (same target), check A → B instead of full structural
        // comparison. Structural comparison would otherwise pass trivially because our
        // built-in lib methods resolve to anyType and property types containing type
        // parameters resolve to errorType when the param isn't in scope. Covariant
        // arg comparison (each source arg assignable to the matching target arg) matches
        // Array's existing behavior and is the pragmatic default for built-in generic
        // containers (Array, Map, Promise, etc.). Cycle detection for self-referential
        // generics like `interface List<T> { next: List<T> }` is handled by
        // `relationComparisonStack` in `checkTypeRelatedTo`.
        //
        // Skip the shortcut when any target arg is `void`: the void-return-type rule
        // (a signature returning T is assignable to one returning void) applies
        // transitively when a type arg appears in a covariant return position inside
        // the generic (e.g. `B<T> { x(): T }` — `B<number>` should be assignable to
        // `B<void>`). We don't have variance info, so fall back to structural
        // comparison in this case — it preserves the prior trivial-pass behavior.
        if (source is Type.Reference && target is Type.Reference &&
            source.target === target.target) {
            val sourceArgs = source.resolvedTypeArguments
            val targetArgs = target.resolvedTypeArguments
            if (sourceArgs != null && targetArgs != null && sourceArgs.size == targetArgs.size &&
                targetArgs.none { it.flags.hasAny(TypeFlags.Void) }) {
                // Skip the arg-shortcut on re-entry: when this target already appears
                // earlier on the comparison stacks, an eager false here would prevent
                // structural recursion from reaching the cycle-break or deeply-nested
                // bail-out (regresses recursiveTypeComparison, infinitelyExpandingTypes,
                // etc. — Observable<{}> vs Observable<number> reached via propertiesRelatedTo
                // must defer to structural so the inner needThisOne self-reference cycle-breaks).
                // count > 1 because the current pair was already pushed by checkTypeRelatedTo.
                // Round 435e: a UNION-target decomposition frame is TRANSPARENT on the
                // source stack (see the Union-target branch above), so reaching here
                // through `NodeArray<Node> | undefined` counts as a single frame and
                // does NOT defer; the recursiveTypeComparison member-recursion pin
                // (source-side-only repeat through needThisOne) still does.
                val tid = source.target.id
                val isReentry = countOccurrences(state.relationSourceTargets, tid) > 1 ||
                    countOccurrences(state.relationTargetTargets, tid) > 1
                // Round 446: Array / ReadonlyArray are covariant containers whose
                // STRUCTURAL comparison spuriously FAILS (their `concat` signature takes a
                // contravariant element param `ConcatArray<T>`, and we have no per-TP
                // variance info), so they must ALWAYS use the covariant element shortcut.
                // The isReentry deferral misfired for the extremely common nested shape
                // `Array<X>` inside `Array<Y>` (`{ actions: ActionInfo[] }[]` vs
                // `ApplicableRefactorInfo[]`): the OUTER Array pushes globalArrayType.id, so
                // the INNER Array's same tid counted as a re-entry → structural → `concat`
                // mismatch → FP TS2322. Array recursion still terminates via
                // relationComparisonStack (identical pair) + isDeeplyNested (5+ occurrences);
                // covariant `A ⊄ B ⇒ Array<A> ⊄ Array<B>` is the correct rule, so the eager
                // shortcut is sound here. Non-Array (user recursive) generics keep deferring
                // to structural on re-entry so an eager false can't pre-empt the cycle-break.
                // Gate: only when the TARGET args are TP-free — an UNBOUND type parameter in
                // the target (`flatten<T>(…: T[][] | …)`) is an M3.1 generic-inference gap,
                // and the trivial structural pass currently MASKS it; the eager shortcut
                // would turn that into an FP, so keep deferring there.
                val isArrayLike = (source.target === globalArrayType ||
                    source.target === globalReadonlyArrayType) &&
                    targetArgs.none { typeContainsUnresolvedTypeParam(it) }
                if (!isReentry || isArrayLike) {
                    for (i in sourceArgs.indices) {
                        if (!checkTypeRelatedTo(sourceArgs[i], targetArgs[i], relation)) return false
                    }
                    return true
                }
            }
        }
        // B75.2: Array-derived source → ReadonlyArray<T> target — covariant element shortcut.
        // TypeScript treats `ReadonlyArray<T>` covariantly in T: any `Array<U>`-derived
        // value is assignable to `ReadonlyArray<T>` when `U → T`. Without this, both
        // plain `Array<U>` and SUBCLASS-of-Array (e.g. `class C<T> extends Array<T>`)
        // vs `ReadonlyArray<A>` fall through to `objectTypeRelatedTo` → spurious
        // `concat`-method contravariance mismatch (`(...items: U[]) => U[]` vs
        // `(...items: A[]) => A[]`) because we don't have per-typeparam variance info
        // to mark `concat`'s element-type position as covariant. Pre-B75.1 this worked
        // by accident because ReadonlyArray collapsed onto globalArrayType (same target,
        // covariant arg shortcut applied). Direct extraction via Array's base-type chain
        // restores the behavior cleanly. Plain `Array<U>` source: directly use source.args.
        // Subclass-of-Array: walk source's target's baseTypes to find an Array<U>-shaped
        // ancestor, instantiate with source's args.
        if (source is Type.Reference && target is Type.Reference &&
            globalReadonlyArrayType != null && target.target === globalReadonlyArrayType &&
            source.target !== globalReadonlyArrayType) {
            val targetArgs = target.resolvedTypeArguments
            if (targetArgs != null && targetArgs.size == 1) {
                if (source.target === globalArrayType) {
                    val srcArgs = source.resolvedTypeArguments
                    if (srcArgs != null && srcArgs.size == 1) {
                        if (checkTypeRelatedTo(srcArgs[0], targetArgs[0], relation)) {
                            return true
                        }
                    }
                } else {
                    val srcInterface = source.target
                    if (srcInterface.baseTypes == null) resolveBaseTypesLazy(srcInterface)
                    val srcBaseTypes = srcInterface.baseTypes
                    val srcTypeParams = srcInterface.typeParameters ?: emptyList()
                    val srcInstArgs = source.resolvedTypeArguments ?: emptyList()
                    if (srcBaseTypes != null && srcTypeParams.size == srcInstArgs.size) {
                        val mapper = createTypeMapper(srcTypeParams, srcInstArgs)
                        for (baseType in srcBaseTypes) {
                            val baseRef = baseType as? Type.Reference ?: continue
                            if (baseRef.target !== globalArrayType &&
                                baseRef.target !== globalReadonlyArrayType) continue
                            val baseArgs = baseRef.resolvedTypeArguments ?: continue
                            if (baseArgs.size != 1) continue
                            val instElt = instantiateType(baseArgs[0], mapper)
                            if (checkTypeRelatedTo(instElt, targetArgs[0], relation)) {
                                return true
                            }
                        }
                    }
                }
            }
        }
        // Object types: structural comparison
        if (source is Type.Object && target is Type.Object) {
            if (objectTypeRelatedTo(source, target, relation)) return true
            // (CHK.60) AN ENUM MEMBER IS A STRING OR NUMBER LITERAL IN tsc, SO IT MUST
            // REACH THE APPARENT-TYPE LEGS BELOW. tsc's `TypeFlags.StringLike` is
            // `String | StringLiteral | TemplateLiteral | StringMapping` and an enum
            // literal type carries `StringLiteral | EnumLiteral`, so
            // `getApparentType(E.A)` is `globalStringType`; a numeric member carries
            // `NumberLiteral | EnumLiteral` and answers `globalNumberType`. (REL.1)(b)
            // mints a member-LESS `Type.Object` here instead, which
            // [propertiesRelatedTo] rejects against any target declaring a property —
            // INCLUDING AN ALL-OPTIONAL (weak) ONE, since its `source.members == null`
            // arm answers `targetProps.isEmpty()`. So `zzzG(E.A)` against
            // `{ length?: number }` was a FALSE POSITIVE at every position, and the
            // weak rule is not what fired: it correctly DECLINES a target the source
            // shares a property with.
            //
            // RETRYING AS THE PRIMITIVE — rather than reaching for a wrapper here —
            // is what routes the source through EXACTLY the legs a `string`/`number`
            // source already takes, each with its own measured guards intact: B69.8's
            // wrapper/named-interface leg (which is why `String`, `Object` and a plain
            // `interface I { length?: number }` target accept), round 430's empty-`{}`
            // rule, B418's index-signature rule and (CHK.32)'s anonymous-object leg.
            // Nothing here can turn an ACCEPTANCE into a rejection: it runs only after
            // the structural comparison has already answered false.
            //
            // POSITIVE EVIDENCE ONLY. The member's flavour is read off its COMPUTED
            // VALUE, so a member whose value did not evaluate keeps today's rejection
            // — the FP-safe direction. A MIXED enum needs no special case: the answer
            // is per MEMBER, and tsc agrees (`{ A = 1, B = "b" }` accepts `E.B`
            // against `{ length?: number }` and `E.A` against `{ toFixed?() }`).
            //
            // OUT OF SCOPE, DELIBERATELY: the WHOLE enum type as a source. It carries
            // no `EnumLiteral` flag, and this repo accepts it against every object
            // target VACUOUSLY (member-less source, so `propertiesRelatedTo` is not
            // even consulted for an empty target) — a standing FALSE NEGATIVE tsc does
            // not share, and a different arc.
            //
            // IDENTITY is excluded exactly as tsc excludes it (`structuredTypeRelatedTo`
            // guards its apparent-source work with `relation !== identityRelation`): an
            // enum member is not IDENTICAL to anything the `String` wrapper is.
            if (relation === identityRelation) return false
            val enumPrimitive = enumLiteralApparentPrimitive(source) ?: return false
            return checkTypeRelatedTo(enumPrimitive, target, relation)
        }
        // Primitive source vs Object target: use the source's apparent (wrapper) type
        // and recurse. `string` → `Object` is assignable because `String` (wrapper)
        // extends `Object`. Without this, primitives fail to satisfy any object
        // constraint that mentions `Object` even though TypeScript treats them as
        // assignable via apparent type.
        // Scope: bare named interfaces only (Type.Interface). Skip Type.Reference
        // (generic instantiations like `Promise<number>` need true assignability —
        // an async function returning `1` should compare via Awaited unwrapping,
        // not via Number-wrapper-extends-Object). Also skip wrapper interfaces
        // themselves so TS2322 keeps firing for primitive→mismatched-wrapper.
        if (target is Type.Interface &&
            (source is Type.Intrinsic || source is Type.StringLiteral ||
                source is Type.NumberLiteral || source is Type.BigIntLiteral)) {
            val targetName = target.symbol?.name
            val isWrapperTarget = targetName in WRAPPER_INTERFACE_NAMES
            if (isWrapperTarget) {
                // B69.8: Primitive → matching wrapper assignment is allowed via
                // auto-boxing. `number → Number`, `string → String`, etc.
                // `boolean → Boolean` (including literal true/false) is also valid.
                val srcIntrinsicName = (source as? Type.Intrinsic)?.intrinsicName
                val matchingWrapper = when {
                    source is Type.NumberLiteral || srcIntrinsicName == "number" -> "Number"
                    source is Type.StringLiteral || srcIntrinsicName == "string" -> "String"
                    source is Type.BigIntLiteral || srcIntrinsicName == "bigint" -> "BigInt"
                    srcIntrinsicName == "boolean" || source.flags.hasAny(TypeFlags.BooleanLiteral) -> "Boolean"
                    srcIntrinsicName == "symbol" -> "Symbol"
                    else -> null
                }
                if (matchingWrapper != null && targetName == matchingWrapper) return true
            } else {
                val apparent = getApparentType(source)
                if (apparent !== source && apparent is Type.Object) {
                    return checkTypeRelatedTo(apparent, target, relation)
                }
            }
        }
        // M3.1 (round 430): an EMPTY anonymous object target (`{}` — no members, no
        // signatures, no index infos) accepts ANY non-nullish, non-void source (tsc:
        // `{}` is the supertype of everything but null/undefined). Object sources
        // already passed vacuously via propertiesRelatedTo; this adds primitive/
        // literal/enum sources — `T extends {}` constraints (tsc core.ts `append`)
        // previously rejected `string` and killed the whole call-site inference.
        if (target is Type.Object && target !is Type.Interface && target !is Type.Reference &&
            target.symbol == null &&
            target.members.isNullOrEmpty() &&
            target.callSignatures.isNullOrEmpty() && target.constructSignatures.isNullOrEmpty() &&
            target.stringIndexInfo == null && target.numberIndexInfo == null) {
            // A Type.Union's own flags carry no Null/Undefined bits (the documented
            // gotcha) — check members explicitly so `string | null` still fails.
            // A TYPE PARAM source is excluded: an unconstrained T could instantiate
            // to null/undefined, and tsc rejects `T → {}` under strict with the
            // "might need an `extends {}` constraint" hint (genericPrototypeProperty3
            // pins it) — TP sources fall through to the pre-existing paths.
            val nullishBits = TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void
            fun nonNullishMember(m: Type): Boolean =
                m !is Type.TypeParam && !m.flags.hasAny(nullishBits)
            val sourceNonNullish = if (source is Type.Union)
                source.types.all { nonNullishMember(it) }
            else nonNullishMember(source)
            if (sourceNonNullish) return true
        }
        // B418: primitive source vs an ANONYMOUS object target carrying index
        // signatures (no symbol → not a named interface). A `string`'s apparent
        // type (the `String` wrapper interface) has a NUMERIC index signature, so
        // `string` IS assignable to `{ [n: number]: any }` ("string has numeric
        // indexer") but NOT to `{ [s: string]: any }` (String has no string
        // indexer), and `boolean`/`number` (no index sigs) reject both. The source's
        // apparent type must supply a matching index signature for EACH index sig
        // the target requires (a string-index source also satisfies a numeric-index
        // target since string keys cover numeric ones). Only ADDS `true` results —
        // every such pair previously fell through to `return false`.
        if (target is Type.Object && target.symbol == null && target !is Type.Reference &&
            (target.stringIndexInfo != null || target.numberIndexInfo != null) &&
            (source is Type.Intrinsic || source is Type.StringLiteral ||
                source is Type.NumberLiteral || source is Type.BigIntLiteral)) {
            val apparent = getApparentType(source) as? Type.Interface
            if (apparent != null) {
                resolveStructuredTypeMembers(apparent)
                val tStr = target.stringIndexInfo
                val tNum = target.numberIndexInfo
                val sStr = apparent.stringIndexInfo
                val sNum = apparent.numberIndexInfo
                val strOk = tStr == null ||
                    (sStr != null && checkTypeRelatedTo(sStr.type, tStr.type, relation))
                val numOk = tNum == null ||
                    (sNum != null && checkTypeRelatedTo(sNum.type, tNum.type, relation)) ||
                    (sStr != null && checkTypeRelatedTo(sStr.type, tNum.type, relation))
                if (strOk && numOk) return true
            }
        }
        // (CHK.32): a PRIMITIVE source against a STRUCTURAL (anonymous) object target
        // is decided through the source's WRAPPER INTERFACE. `string` carries
        // `charCodeAt`/`length`/`substring` because `String` declares them, so
        // `isWhitespace(s, 0)` against `(text: { charCodeAt(i: number): number })` is
        // legal — 8 of the 14 rows of a hand-written primitive/target matrix were
        // ours-only against tsgo 7.0.2, and the whole `jsonrepair` scanner is typed
        // this way.
        //
        // WHY IT IS A SEPARATE LEG AND NOT A WIDENING OF THE ROUND-B69.8 ONE ~120 LINES
        // ABOVE. That leg is scoped `target is Type.Interface` — a NAMED interface —
        // and it RETURNS its verdict. Widening its target test would put a `return
        // false` in front of the two legs between it and here: the empty-`{}` rule
        // (round 430) and B418's index-signature rule, both of which accept sources
        // this comparison rejects. Placed here it is strictly a FALLBACK in the
        // round-744 sense — every earlier acceptance path has already had its turn,
        // and this can only turn a rejection into an acceptance.
        //
        // The REFUSAL direction is the one that had to be pinned hardest, and it is
        // carried by the ordinary structural comparison rather than by a gate here: a
        // target member the wrapper does not declare (`{ zzzNotOnString: number }`) or
        // declares at another type (`{ length: string }`) fails `objectTypeRelatedTo`
        // and the TS2345/TS2322 stands, at tsgo's own message and position.
        //
        // Excluded, each for a measured reason: a NAMED interface target (the B69.8 leg
        // already returned for it, so this is unreachable there and nothing moves); a
        // `Type.Reference` target (`Promise<number>` needs true assignability, not
        // wrapper-extends-Object — the B69.8 leg's own note); and every non-primitive
        // source, via [primitiveApparentWrapper]'s shape test.
        //
        // AN INDEX-SIGNATURE TARGET IS B418's, NOT THIS LEG's, AND THAT IS THE SECOND
        // GUARD MEASUREMENT FORCED. `assignmentCompat1` pins `y = "foo"` against
        // `{ [index: string]: any }` as TS2322 — a `string`'s apparent type has a
        // NUMERIC index signature and no string one — and pins `z = false` against
        // `{ [index: number]: any }` likewise. An ordinary structural comparison of the
        // `String` wrapper against such a target passes, because every property it
        // carries conforms to an `any`-typed indexer; the rule tsc actually applies is
        // that the SOURCE must supply a matching index signature, which is exactly what
        // B418 twenty lines above decides. So a target carrying either indexer has
        // already had its answer, and this leg must not overturn it.
        if (target is Type.Object && target !is Type.Interface && target !is Type.Reference &&
            target.flags.hasNone(TypeFlags.Enum or TypeFlags.EnumLiteral)) {
            // Ordered cheapest-first: the source shape test is a class check plus a
            // flag test, where [targetIsMemberShaped] forces the target's lazy tables.
            val wrapper = primitiveApparentWrapper(source)
            if (wrapper != null && targetIsMemberShaped(target) &&
                checkTypeRelatedTo(wrapper, target, relation)) return true
        }
        // TypeParam vs TypeParam: relate via apparent types (constraint, or {} when
        // unconstrained). Matters for generic-method signature comparison where source's
        // K and target's K (separate fresh params from `resolveGenericPropertyType`) would
        // otherwise compare as opaque-and-distinct → spurious TS2322 in tests like
        // `infinitelyExpandingTypes4` (Promise<Q.then<U_src>> vs Promise<Q.then<U_tgt>>).
        if (source is Type.TypeParam && target is Type.TypeParam) {
            val srcConstraint = source.constraint
            val tgtConstraint = target.constraint
            if (srcConstraint == null || tgtConstraint == null) return true
            return checkTypeRelatedTo(srcConstraint, tgtConstraint, relation)
        }
        // A TYPE PARAMETER against `object` is decided by its CONSTRAINT (round 834,
        // (NONPRIM.1)). An UNCONSTRAINED `T` can be instantiated with a primitive, so
        // it is not assignable — the verdict `nonPrimitiveInGeneric`'s `function
        // generic<T>(t: T) { var o: object = t }` wants — while `T extends object` and
        // `T extends {}` both are. Deliberately NOT the general "TypeParam source via
        // apparent type" rule: this is keyed on a NonPrimitive target, so nothing that
        // does not write the `object` keyword can reach it.
        if (source is Type.TypeParam && target.flags.hasAny(TypeFlags.NonPrimitive)) {
            val constraint = source.constraint ?: return false
            if (constraint === errorType) return false
            return checkTypeRelatedTo(constraint, target, relation)
        }
        return false
    }

    /**
     * Structural comparison of two object types.
     * Checks properties, call signatures, and construct signatures.
     * For class instance types, skip construct signature comparison — those belong
     * to the static side (typeof Class), not the instance type.
     */
    private fun objectTypeRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
    ): Boolean {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        // Check properties
        if (!propertiesRelatedTo(source, target, relation)) return false
        // Check call signatures
        if (!signaturesRelatedTo(source, target, relation, isConstruct = false)) return false
        // Check construct signatures — skip for class/interface instance types where
        // construct signatures come from the class constructor (static side), not the instance.
        val isClassInstance = target is Type.Interface && target.symbol != null &&
            target.symbol!!.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)
        if (!isClassInstance) {
            if (!signaturesRelatedTo(source, target, relation, isConstruct = true)) return false
        }
        // Check index signatures: if target has a string/number index signature but source
        // (a named class/interface) doesn't declare one, TypeScript rejects the assignment
        // with "Index signature for type '<kind>' is missing in type 'X'." This only applies
        // to NOMINAL source types (named class/interface) — anonymous object literals use
        // a different rule where properties individually satisfy the index type.
        // Type.Reference's own `symbol` is null; its target's symbol carries the nominal info.
        // Skip when the target's index type accepts `any`/`unknown` — any source satisfies
        // it implicitly so emitting "missing index signature" would be a FP (cf.
        // `assignmentCompatability36_ts`'s `{[k:string]:any}` target).
        val srcNominalSym = source.symbol ?: (source as? Type.Reference)?.target?.symbol
        val isNominalSource = srcNominalSym != null &&
            srcNominalSym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)
        // 17.74: Function-shaped sources (callSignatures only, no nominal members)
        // also trigger the missing-index-sig check — mirrors TypeScript's "Index
        // signature for type 'number' is missing in type '() => void'." for
        // `func: () => void; const a: ArrayLike<any> = func;`. Note: for function
        // sources we DON'T skip when target's index type is `any`/`unknown` — a
        // function type doesn't implicitly satisfy `[n:number]:any` (unlike a
        // nominal class which can be subclassed/extended), so the diagnostic IS
        // appropriate. The `any`-skip remains for nominal sources to avoid FPs
        // (cf. `assignmentCompatability36_ts`).
        val isFunctionShaped = !source.callSignatures.isNullOrEmpty() && source.members.isNullOrEmpty()
        // tsc indexSignaturesRelatedTo: when the TARGET has a STRING index signature whose
        // value type is `any`, EVERY non-primitive source passes ALL index checks
        // (`!sourceIsPrimitive && targetHasStringIndex && targetInfo.type.flags & Any →
        // Ternary.True`, applied per target info). A number-only `[n: number]: any` target
        // (ArrayLike<any>) has NO string index → the function-shaped check below still
        // fires. (intTypeCheck: `var obj39: i4 = function(){}` where i4's `[p1: string];`
        // value defaults to `any` → NO error.)
        val anyStringIndexSkip = target.stringIndexInfo?.type?.flags?.hasAny(TypeFlags.Any) == true
        if ((isNominalSource || isFunctionShaped) && !anyStringIndexSkip) {
            val tgtStr = target.stringIndexInfo
            if (tgtStr != null && source.stringIndexInfo == null &&
                (isFunctionShaped || !tgtStr.type.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown))) {
                lastMissingIndexSigKind = "string"
                return false
            }
            val tgtNum = target.numberIndexInfo
            if (tgtNum != null && source.numberIndexInfo == null &&
                (isFunctionShaped || !tgtNum.type.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown))) {
                lastMissingIndexSigKind = "number"
                return false
            }
        }
        return true
    }

    /**
     * 4d. Property-by-property structural comparison.
     * For each required property in target, source must have a compatible property.
     */
    private fun propertiesRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
    ): Boolean {
        val targetProps = target.properties ?: return true
        val sourceHasCallSigs = !source.callSignatures.isNullOrEmpty()
        val sourceMembers = source.members ?: if (sourceHasCallSigs) emptyMap() else return targetProps.isEmpty()
        // Statics filter: when target carries a static side (class declaration),
        // skip target.properties entries that live on the static side. Instance-vs-
        // instance shape comparison must not see `static bar()` on either side.
        // Type.Reference defers to its target Interface's staticMembers.
        val targetStatics = getStaticMembersOfType(target)
        for (targetProp in targetProps) {
            val targetName = targetProp.name
            if (targetStatics != null && targetStatics.containsKey(targetName)) continue
            // Inherited Object prototype members (constructor, toString, valueOf, …)
            // are never "missing" — every JS object has them via the prototype chain.
            // Without this filter, an empty `{a:string}` fails to satisfy `Object` because
            // `constructor` etc. are listed as Object's own properties in our embedded lib.
            // B67.3: only skip when source doesn't EXPLICITLY define this property — if
            // source has its own `toString: 5`, fall through to the type-compatibility
            // check (number vs () => string emits TS2322 per `assignmentToObject_ts`).
            if (targetName in OBJECT_PROTOTYPE_PROPERTIES && !sourceMembers.containsKey(targetName)) continue
            // 17.27: When source is a function type (has callSignatures), Function.prototype
            // methods (call/apply/bind) are implicitly available through the apparent type.
            // Lets `() => void` satisfy `interface Callable { call(blah: any) }` etc.
            if (sourceHasCallSigs && targetName in FUNCTION_PROTOTYPE_METHODS) continue
            // B479: `Function[Symbol.hasInstance]` is provided by Function.prototype, so a
            // function-typed source satisfies it implicitly (a function IS a Function). Without
            // this skip, adding `[Symbol.hasInstance]` to the embedded Function interface makes
            // `() => void` fail to satisfy `Function` (untypedFunctionCallsWithTypeParameters1's
            // `caller: Function` property).
            if (sourceHasCallSigs && targetName.contains("hasInstance")) continue
            // B66.4: Function-side runtime properties (prototype/arguments/caller) are
            // implicitly available on any function value via Function.prototype.
            // Lets a function expression / arrow satisfy the `Function` interface.
            if (sourceHasCallSigs && targetName in FUNCTION_RUNTIME_PROPERTIES) continue
            // 17.74: Function.prototype's `length: number` and `name: string` implicitly
            // satisfy the corresponding target property when source has callSignatures.
            // Lets `() => void` satisfy `interface ArrayLike<T> { length: number }` —
            // clears the way for the index-signature-missing check to fire (matching
            // TypeScript's elaboration which prefers "Index signature missing" over
            // "Property 'length' missing" for function-vs-ArrayLike-shape comparisons).
            if (sourceHasCallSigs && (targetName == "length" || targetName == "name")) {
                val targetPropType = getPropertyTypeForRelation(target, targetProp)
                val protoType = if (targetName == "length") numberType else stringType
                if (checkTypeRelatedTo(protoType, targetPropType, relation)) continue
            }
            // Round 471: a lib-phantom member of a lib+module-interface merge (Symbol's
            // es2019 `description` vs tsc compiler/types.ts's `interface Symbol`) is a
            // conflation artifact — skip it in the relation (suppression-only; see
            // isLibPhantomMemberOfModuleInterface). PERF (round 471b): gated to a
            // CLASS-instance source — the class-implements-module-interface family
            // (SymbolObject → Symbol) — because an unconditional skip removes the
            // missing-prop EARLY EXIT from every relation against the merged
            // interface and re-runs full member-type comparisons (services
            // self-compile 39 s → 77 s, measured).
            if (source.symbol?.flags?.hasAny(SymbolFlags.Class) == true &&
                isLibPhantomMemberOfModuleInterface(target, targetName)) continue
            // Check if property is optional (question mark in declaration)
            val isOptional = isOptionalProperty(targetProp)
            val sourceProp = sourceMembers[targetName]
            if (sourceProp == null) {
                // B418: a source INDEX SIGNATURE does NOT satisfy a target's required
                // NAMED property — tsc's propertiesRelatedTo looks up the source prop
                // via getPropertyOfType, which never synthesizes a named property from
                // a source index signature. So `{ [k: string]: any }` is NOT assignable
                // to `{ one: number }` (one is missing → TS2741), matching the number
                // index-sig source which already (correctly) failed here.
                if (!isOptional) {
                    lastMissingPropertyName = targetName
                    lastMissingPropertySymbol = targetProp
                    return false // missing required property
                }
                continue
            }
            // Private-brand mismatch: if both source and target declare this property as
            // `private` but on different parent classes, TypeScript treats them as unrelated
            // nominal shapes even though the declared types are structurally equal.
            // Matches `typeIdentityConsidersBrands_ts` etc.
            if (isPropPrivateBrandMismatch(sourceProp, targetProp)) {
                lastPrivateBrandMismatchName = targetName
                return false
            }
            // Compare property types
            val sourcePropType = getPropertyTypeForRelation(source, sourceProp)
            val effectiveSource = widenOptionalSourcePropType(sourcePropType, sourceProp, targetProp)
            val targetPropType = widenOptionalTargetPropType(getPropertyTypeForRelation(target, targetProp), targetProp, effectiveSource)
            if (!checkTypeRelatedTo(effectiveSource, targetPropType, relation)) {
                // Round 454: a METHOD member (method syntax `m(...) {…}` / `m(...): T`)
                // compares its parameters BIVARIANTLY (tsc's rule — `strictFunctionTypes`
                // never applies to method members), but our `checkTypeRelatedTo` compares
                // function-typed members contravariantly. When BOTH the source and target
                // member are methods, retry via the bivariant helper already used by
                // TS2416/TS2430. Suppression-only (fires only on a contravariant failure)
                // and FP-safe by construction: a method-param bivariance match is not an
                // error in tsc, so this can only remove a false positive (e.g. an
                // object-literal `canReuseTypeNodeAnnotation(…, symbol: Symbol)` satisfying
                // an interface member `(…, symbol: Symbol | undefined)`). A function-typed
                // PROPERTY (`m: (…) => T`) is NOT a method → stays strictly contravariant.
                if (sourceProp.declarations.any { it is MethodDeclaration } &&
                    targetProp.declarations.any { it is MethodDeclaration } &&
                    methodSignaturesBivariantlyRelated(
                        sourcePropType, getPropertyTypeForRelation(target, targetProp))
                ) continue
                // Round 435 (tsc contextual literal types): a FRESH object-literal prop
                // keeps its literal type against a literal-containing target member —
                // getTypeOfObjectLiteral widens (`kind: "paths"` → string), so retry with
                // the un-widened literal recovered from the member symbol's
                // PropertyAssignment. Gated to the CURRENT fresh literal's source range
                // ([freshObjLitRange]) so a widened var reference still fails (tsc's own
                // freshness rule); a literal absent from the target union also still
                // fails. tsc's moduleSpecifiers.ts `{ kind: "paths", … }` returns /
                // esDecorators.ts `top = { kind: "class", … }` assignments.
                val fresh = freshObjLitRange
                val srcDecl = if (fresh != null && propTypeContainsLiteral(targetPropType))
                    sourceProp.valueDeclaration as? PropertyAssignment else null
                val lit = if (srcDecl != null && srcDecl.pos in fresh!!)
                    literalTypeOfExpression(srcDecl.initializer, isArrayLikeReference(targetPropType)) else null
                if (lit == null || !checkTypeRelatedTo(lit, targetPropType, relation)) return false
            }
        }
        return true
    }

    /**
     * Scan source and target's own members for any shared property name where both sides
     * declare it as `private` on different parent classes. Used to opt the conservative
     * TS2345 guard into running a full assignability check for named→named class args.
     */
    private fun hasPrivateBrandMismatchBetween(source: Type.Object, target: Type.Object): Boolean {
        return findPrivateBrandMismatchName(source, target) != null
    }

    /**
     * Return the first property name where both source and target declare a private property
     * on different parent classes, or null when no such nominal mismatch exists.
     */
    private fun findPrivateBrandMismatchName(source: Type.Object, target: Type.Object): String? {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        val sMembers = source.members ?: return null
        val tMembers = target.members ?: return null
        for ((name, tProp) in tMembers) {
            val sProp = sMembers[name] ?: continue
            if (isPropPrivateBrandMismatch(sProp, tProp)) return name
        }
        return null
    }

    /**
     * Detect TypeScript's "separate declarations of a private property" nominal brand check.
     * Two properties are brand-incompatible when both are declared `private` AND their
     * declaring parent classes differ by identity. Properties that share a single declaration
     * (e.g. inherited from the same base class) remain compatible.
     */
    private fun isPropPrivateBrandMismatch(sourceProp: Symbol, targetProp: Symbol): Boolean {
        val sDecl = sourceProp.valueDeclaration ?: sourceProp.declarations.firstOrNull() ?: return false
        val tDecl = targetProp.valueDeclaration ?: targetProp.declarations.firstOrNull() ?: return false
        if (sDecl === tDecl) return false
        if (!isMemberPrivate(sDecl) || !isMemberPrivate(tDecl)) return false
        val sParent = findParentClassOrInterface(sDecl)
        val tParent = findParentClassOrInterface(tDecl)
        return sParent != null && tParent != null && sParent !== tParent
    }

    private fun findParentClassOrInterface(node: Node): Node? {
        // The parent isn't stored on the AST; look up via the property symbol's parent's
        // declarations to find the enclosing class.
        when (node) {
            is PropertyDeclaration -> (node.name as? Identifier)?.text
            is MethodDeclaration -> (node.name as? Identifier)?.text
            is GetAccessor -> (node.name as? Identifier)?.text
            is SetAccessor -> (node.name as? Identifier)?.text
            else -> null
        } ?: return null
        // Walk all class declarations looking for one whose members contain `node` by identity.
        for (sym in globals.values) {
            if (!sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface)) continue
            for (decl in sym.declarations) {
                val members = when (decl) {
                    is ClassDeclaration -> decl.members
                    is InterfaceDeclaration -> decl.members
                    else -> continue
                }
                if (members.anyIdentical(node)) return decl
            }
        }
        return null
    }

    /**
     * B96-INDEXSIG: object-literal / array-literal value vs target INDEX-SIGNATURE
     * value-type, emitting per-value TS2322 (primitive mismatch) or TS2741 (named
     * source missing a required prop of the index value type) + related TS6501
     * "The expected type comes from this index signature." The relation engine passes
     * an index-sig-only target trivially, so without this nothing fires for
     * `{ [s:string]:number } = { p: "" }`. Tightly gated (see inline) to bound the
     * ~228-index-sig-fixture FP surface.
     */
    /** B470: recursively find a `type <name> = ...` declaration anywhere in [stmts]
     *  (including inside block/if/for/while bodies — the binder does NOT bind
     *  block-scoped type aliases, B83.5). Used by [tryEmitTypeofIndexSigNarrowing]. */
    private fun findTypeAliasDeclInStatements(stmts: List<Statement>, name: String): TypeAliasDeclaration? {
        for (s in stmts) {
            when (s) {
                is TypeAliasDeclaration -> if ((s.name).text == name) return s
                is Block -> findTypeAliasDeclInStatements(s.statements, name)?.let { return it }
                is IfStatement -> {
                    (s.thenStatement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                    (s.elseStatement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                }
                is ForStatement -> (s.statement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                is ForInStatement -> (s.statement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                is ForOfStatement -> (s.statement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                is WhileStatement -> (s.statement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                is DoStatement -> (s.statement as? Block)?.let { findTypeAliasDeclInStatements(it.statements, name)?.let { r -> return r } }
                else -> {}
            }
        }
        return null
    }

    /**
     * B470: control-flow analysis of `typeof v` in an INDEX-SIGNATURE value position.
     * `const x: { [k:string]: typeof v } = { ... }` (inline or via a possibly
     * block-scoped type alias) declared inside a block narrowing `v` — tsc captures
     * `v`'s NARROWED type as the index value type, so a property value not assignable
     * to it fires TS2322 at the value. Done as a DEDICATED local walker (the alias
     * body containing `typeof v` is cached/eagerly resolved without flow, so the
     * standard path never sees the narrowed value). FP firewall: corpus-rare shape;
     * narrowing must change `v` to a PRIMITIVE; only primitive property values that
     * PASS the un-narrowed relation but FAIL the narrowed one fire. Returns true
     * (suppressing the standard var-decl path) only when it emits.
     */
    private fun tryEmitTypeofIndexSigNarrowing(
        decl: VariableDeclaration, source: String, fileName: String,
    ): Boolean {
        if (currentFlowGraph == null) return false
        val init = decl.initializer as? ObjectLiteralExpression ?: return false
        val ann = decl.type ?: return false
        // `flowAnchor` is the node whose recorded flow narrows the typeof var. The binder
        // records flow at TypeAliasDeclaration nodes precisely for typeof-CFA (Flow.kt),
        // so for an alias annotation the alias DECL is the anchor; for an inline TypeLiteral
        // the var-decl is the anchor (only recorded if the binder tracks it).
        val flowAnchor: Node
        val typeLiteral: TypeLiteral = when (ann) {
            is TypeLiteral -> { flowAnchor = decl; ann }
            is TypeReference -> {
                val nm = (ann.typeName as? Identifier)?.text ?: return false
                if (!ann.typeArguments.isNullOrEmpty()) return false
                // Resolve the alias decl — block-scoped aliases aren't bound, so scan AST.
                val fileStmts = binderResults.firstOrNull { it.sourceFile.fileName == currentCheckFileName }
                    ?.sourceFile?.statements ?: return false
                val aliasDecl = findTypeAliasDeclInStatements(fileStmts, nm) ?: return false
                flowAnchor = aliasDecl
                aliasDecl.type as? TypeLiteral ?: return false
            }
            else -> return false
        }
        val idxSig = typeLiteral.members.filterIsInstance<IndexSignature>().firstOrNull { sig ->
            val pType = sig.parameters.firstOrNull()?.type?.kind
            (pType == SyntaxKind.StringKeyword || pType == SyntaxKind.NumberKeyword) &&
                sig.type is TypeQuery && (sig.type).exprName is Identifier
        } ?: return false
        val keyIsNumber = idxSig.parameters.first().type?.kind == SyntaxKind.NumberKeyword
        val varName = ((idxSig.type as TypeQuery).exprName as Identifier).text
        val varSym = currentFileLocals?.get(varName) ?: globals[varName] ?: return false
        val declaredVar = getTypeOfSymbol(varSym)
        if (declaredVar !is Type.Union) return false
        val flow = getFlowAt(flowAnchor) ?: return false
        val narrowed = flowWalkWithTripCheck(flowAnchor, WK_FLOW_ANCHOR, declaredVar.id.toLong() shl 32 or (varName.hashCode().toLong() and 0xFFFF_FFFFL), flowPathRoot(varName)) {
            narrowTypeFromFlow(declaredVar, flow, varName, NarrowSeen(), 0)
        } ?: return false
        if (narrowed === declaredVar || !isSimpleCheckableType(narrowed)) return false
        var emitted = false
        for (p in init.properties) {
            if (p !is PropertyAssignment) continue
            if (keyIsNumber) {
                val pn = p.name
                val isNumericKey = pn is NumericLiteralNode ||
                    (pn is Identifier && pn.text.toDoubleOrNull() != null)
                if (!isNumericKey) continue
            }
            val valType = getTypeOfExpression(p.initializer)
            if (valType === anyType || valType === errorType || valType === unknownType) continue
            if (!isSimpleCheckableType(valType)) continue
            if (!checkTypeRelatedTo(valType, declaredVar, assignableRelation)) continue
            if (checkTypeRelatedTo(valType, narrowed, assignableRelation)) continue
            // tsc squiggles the property NAME (not the value) for an index-value mismatch,
            // with a related TS6501 pointing at the index signature.
            val nameNode = p.name
            val pos = nameNode.pos
            val spanLen = when (nameNode) {
                is Identifier -> nameNode.text.length
                is StringLiteralNode -> nameNode.text.length + 2
                is NumericLiteralNode -> nameNode.text.length
                else -> 1
            }.coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, pos)
            val related: List<Diagnostic> = run {
                val idxPos = idxSig.pos
                if (idxPos < 0) return@run emptyList()
                val (declFile, declSource) = resolveDeclarationSourceFile(idxPos)
                if (declFile == null || declSource == null) return@run emptyList()
                val isLib = isLibFileName(declFile)
                val (dl, dc) = if (isLib) Pair<Int?, Int?>(null, null)
                    else getLineAndCharacterOfPosition(declSource, idxPos).let { Pair<Int?, Int?>(it.first, it.second) }
                listOf(Diagnostic(
                    message = "The expected type comes from this index signature.",
                    category = DiagnosticCategory.Message, code = 6501,
                    fileName = declFile, line = dl, character = dc, start = idxPos, length = 1,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '${typeToString(getWidenedLiteralType(valType))}' is not assignable to type '${typeToString(narrowed)}'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = character,
                start = pos, length = spanLen,
                relatedInformation = related,
            ))
            emitted = true
        }
        return emitted
    }

    private fun checkLiteralValuesAgainstIndexSignatures(
        sourceLiteral: Expression,
        targetType: Type,
        source: String,
        fileName: String,
    ) {
        if (targetType !is Type.Object) return
        resolveStructuredTypeMembers(targetType)
        val strIdx = targetType.stringIndexInfo
        val numIdx = targetType.numberIndexInfo
        if (strIdx == null && numIdx == null) return
        val namedMembers = targetType.members?.keys ?: emptySet()

        fun indexValueTrivial(t: Type?): Boolean =
            t == null || t === anyType || t === unknownType || t === errorType

        fun emitForValue(valuePosNode: Node, valueExpr: Expression, applicable: IndexInfo) {
            val indexValueType = applicable.type
            if (indexValueTrivial(indexValueType)) return
            // Round 471: a literal value keeps its literal type against a
            // literal-containing index value type (contextual typing — the element
            // walk of `readonly Op[] = ["a", "b"]` reaches here once the outer
            // relation passes with the literal-preserved source).
            val valueType = if (propTypeContainsLiteral(indexValueType))
                literalTypeOfExpression(valueExpr, isArrayLikeReference(indexValueType))
                    ?: getTypeOfExpression(valueExpr)
            else getTypeOfExpression(valueExpr)
            if (valueType === anyType || valueType === unknownType || valueType === errorType) return
            val idxDecl = applicable.declaration ?: return
            val idxPos = idxDecl.pos
            if (idxPos < 0) return
            fun ts6501(): Diagnostic? {
                val (declFile, declSource) = resolveDeclarationSourceFile(idxPos)
                if (declFile == null || declSource == null) return null
                val isLib = isLibFileName(declFile)
                val (dl, dc) = if (isLib) Pair<Int?, Int?>(null, null)
                    else getLineAndCharacterOfPosition(declSource, idxPos).let { Pair<Int?, Int?>(it.first, it.second) }
                return Diagnostic(
                    message = "The expected type comes from this index signature.",
                    category = DiagnosticCategory.Message, code = 6501,
                    fileName = declFile, line = dl, character = dc,
                    start = idxPos, length = 1,
                )
            }
            val pos = valuePosNode.pos
            val spanLen = when (valuePosNode) {
                is Identifier -> valuePosNode.text.length
                is NumericLiteralNode -> valuePosNode.text.length
                is StringLiteralNode -> valuePosNode.text.length + 2
                else -> 1
            }
            val (line, character) = getLineAndCharacterOfPosition(source, pos)
            // TS2741: named source missing a required prop of the named index value type.
            if (valueType is Type.Interface && indexValueType is Type.Interface) {
                val missing = collectMissingProperties(valueType, indexValueType)
                if (missing.isNotEmpty() && !checkTypeRelatedTo(valueType, indexValueType, assignableRelation)) {
                    val mpName = missing[0]
                    val mpSym = getPropertyOfType(indexValueType, mpName)
                    val related = listOfNotNull(mpSym?.let { createPropertyDeclaredHereRelatedInfo(it) }, ts6501())
                    diagnostics.add(Diagnostic(
                        message = "Property '$mpName' is missing in type '${typeToString(valueType)}' but required in type '${typeToString(indexValueType)}'.",
                        category = DiagnosticCategory.Error, code = 2741,
                        fileName = fileName, line = line, character = character,
                        start = pos, length = spanLen,
                        relatedInformation = related,
                    ))
                }
                return
            }
            // TS2322: PRIMITIVE source value not assignable to the index value type.
            if (!isSimpleCheckableType(valueType)) return
            if (checkTypeRelatedTo(valueType, indexValueType, assignableRelation)) return
            diagnostics.add(Diagnostic(
                message = "Type '${typeToString(getWidenedLiteralType(valueType))}' is not assignable to type '${typeToString(indexValueType)}'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = character,
                start = pos, length = spanLen,
                relatedInformation = listOfNotNull(ts6501()),
            ))
        }

        when (sourceLiteral) {
            is ObjectLiteralExpression -> {
                for (prop in sourceLiteral.properties) {
                    if (prop !is PropertyAssignment) continue
                    val value = prop.initializer
                    val nameNode = prop.name
                    val (propName, isNumericKey) = when (nameNode) {
                        is Identifier -> nameNode.text to false
                        is StringLiteralNode -> nameNode.text to isCanonicalNumericPropertyName(nameNode.text)
                        is NumericLiteralNode -> nameNode.text to true
                        else -> continue
                    }
                    if (propName in namedMembers) continue
                    val applicable = (if (isNumericKey) (numIdx ?: strIdx) else strIdx) ?: continue
                    emitForValue(nameNode, value, applicable)
                }
            }
            is ArrayLiteralExpression -> {
                val applicable = numIdx ?: strIdx ?: return
                for (elem in sourceLiteral.elements) {
                    if (elem is SpreadElement || elem is OmittedExpression) continue
                    emitForValue(elem, elem, applicable)
                }
            }
            else -> {}
        }
    }

    /**
     * B363: TS2418 — a computed property name `[SYM]` (where `SYM` is a unique-symbol
     * const) in an object literal assigned to an interface that declares a member keyed
     * by the SAME unique symbol, where the property's VALUE type is not assignable to the
     * declared member type. `getMemberName` cannot key unique-symbol members (only
     * well-known `[Symbol.X]`), so the member never enters the structural table and the
     * relation engine sees only the (passing) string index signature — this AST-level
     * walker resolves the key→const and matches the interface member declaration directly.
     * Squiggle at the `[SYM]` computed name; related TS6500 at the interface member.
     */
    private fun checkComputedSymbolKeyValues(
        objLit: ObjectLiteralExpression,
        targetType: Type,
        source: String,
        fileName: String,
    ) {
        if (targetType !is Type.Interface) return
        val targetSym = targetType.symbol ?: return
        val targetDisplay = typeToString(targetType)
        for (prop in objLit.properties) {
            if (prop !is PropertyAssignment) continue
            val nameNode = prop.name
            if (nameNode !is ComputedPropertyName) continue
            val keyExpr = nameNode.expression as? Identifier ?: continue
            val keyName = keyExpr.text
            // Resolve to a unique-symbol const declared in the key's home file.
            val declFile = resolveValueNameDeclaringFile(keyName, fileName) ?: continue
            val keyIsUniqueSymbol = (fileResults[declFile]?.sourceFile?.statements ?: emptyList()).any { stmt ->
                stmt is VariableStatement && stmt.declarationList.declarations.any {
                    (it.name as? Identifier)?.text == keyName && varDeclIsSymbol(it)
                }
            }
            if (!keyIsUniqueSymbol) continue
            // Find the interface member declared with the SAME computed symbol key.
            var memberDecl: PropertyDeclaration? = null
            run {
                for (decl in targetSym.declarations) {
                    val members = (decl as? InterfaceDeclaration)?.members ?: continue
                    for (m in members) {
                        if (m is PropertyDeclaration) {
                            val mn = m.name
                            if (mn is ComputedPropertyName && (mn.expression as? Identifier)?.text == keyName) {
                                memberDecl = m; return@run
                            }
                        }
                    }
                }
            }
            val md = memberDecl ?: continue
            val memberTypeNode = md.type ?: continue
            val value = prop.initializer
            val memberType = getTypeFromTypeNode(memberTypeNode)
            if (memberType === anyType || memberType === errorType || memberType === unknownType) continue
            val valueType = (literalTypeOfExpression(value)
                ?: getTypeOfExpression(value))
            if (valueType === anyType || valueType === errorType || valueType === unknownType) continue
            val ok = checkTypeRelatedTo(valueType, memberType, assignableRelation)
            if (ok) continue
            val pos = nameNode.pos
            val len = keyName.length + 2
            val (line, character) = getLineAndCharacterOfPosition(source, pos)
            val related = mutableListOf<Diagnostic>()
            val memberNamePos = md.name.pos
            if (memberNamePos >= 0) {
                val (declF, declS) = resolveDeclarationSourceFile(memberNamePos)
                if (declF != null && declS != null) {
                    val isLib = isLibFileName(declF)
                    val (rl, rc) = if (isLib) Pair<Int?, Int?>(null, null)
                        else getLineAndCharacterOfPosition(declS, memberNamePos).let { Pair<Int?, Int?>(it.first, it.second) }
                    related.add(Diagnostic(
                        message = "The expected type comes from property 'unique symbol' which is declared here on type '$targetDisplay'",
                        category = DiagnosticCategory.Message, code = 6500,
                        fileName = declF, line = rl, character = rc,
                        start = memberNamePos, length = keyName.length + 2,
                    ))
                }
            }
            diagnostics.add(Diagnostic(
                message = "Type of computed property's value is '${typeToString(valueType)}', which is not assignable to type '${typeToString(memberType)}'.",
                category = DiagnosticCategory.Error, code = 2418,
                fileName = fileName, line = line, character = character,
                start = pos, length = len,
                relatedInformation = related,
            ))
        }
    }

    /**
     * B138: A NON-LITERAL object TYPE assigned to an index-signature-only target — each
     * source property must be assignable to the applicable index-signature value type, else
     * TS2322 with the "Property 'X' is incompatible with index signature." chain. The
     * sibling [checkLiteralValuesAgainstIndexSignatures] only handles literal-syntax sources
     * (and emits a standalone per-value TS2322); this handles a variable/expression whose
     * resolved type is an anonymous object (`var x = {...}; var z: {[k:string]:T} = x` and
     * `x = a`).
     *
     * FP firewall: both sides must be ANONYMOUS object types (named class/interface sources
     * use the nominal "missing index signature" rule in [objectTypeRelatedTo]); the source
     * must carry no index signatures of its own; and the incompatible pair must have at least
     * ONE primitive side (so [checkTypeRelatedTo] is reliable — named-vs-named is the
     * documented 39+-regression gate). Reports only the FIRST incompatible property (matches
     * TypeScript). Callers gate on `isAssignable` (the relation wrongly passes for index-sig
     * targets) so this never double-emits with a coarse relation-failure TS2322.
     */
    private fun checkObjectTypeAgainstIndexSignatures(
        sourceType: Type, targetType: Type, namePos: Int, nameLen: Int,
        source: String, fileName: String,
    ) {
        if (sourceType !is Type.Object || targetType !is Type.Object) return
        if (sourceType is Type.Reference || targetType is Type.Reference) return
        if (sourceType.symbol != null || targetType.symbol != null) return
        resolveStructuredTypeMembers(sourceType); resolveStructuredTypeMembers(targetType)
        val strIdx = targetType.stringIndexInfo
        val numIdx = targetType.numberIndexInfo
        if (strIdx == null && numIdx == null) return
        // Source must not have its own index signatures (those satisfy the target directly).
        if (sourceType.stringIndexInfo != null || sourceType.numberIndexInfo != null) return
        val props = sourceType.properties ?: return
        if (props.isEmpty()) return
        fun trivial(t: Type?): Boolean =
            t == null || t === anyType || t === unknownType || t === errorType
        for (p in props) {
            val isNumericKey = isCanonicalNumericPropertyName(p.name)
            val applicable = (if (isNumericKey) (numIdx ?: strIdx) else strIdx) ?: continue
            val idxValType = applicable.type
            if (trivial(idxValType)) continue
            val propType = getTypeOfSymbol(p)
            if (trivial(propType)) continue
            // Reliability gate: at least one side primitive (named-vs-named is unreliable).
            if (!isSimpleCheckableType(propType) && !isSimpleCheckableType(idxValType)) continue
            if (checkTypeRelatedTo(propType, idxValType, assignableRelation)) continue
            val (line, character) = getLineAndCharacterOfPosition(source, namePos)
            diagnostics.add(Diagnostic(
                message = "Type '${typeToString(sourceType)}' is not assignable to type '${typeToString(targetType)}'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = character,
                start = namePos, length = nameLen,
                messageChain = listOf(
                    "  Property '${p.name}' is incompatible with index signature.",
                    "    Type '${typeToString(getWidenedLiteralType(propType))}' is not assignable to type '${typeToString(idxValType)}'.",
                ),
            ))
            return
        }
    }

    /**
     * 16.4df step (b): For Type.Reference sources/targets, substitute the property's
     * declared type via the reference's type-arg mapper (`resolveGenericPropertyType`)
     * before comparison. This prevents trivial-pass on raw `T` for cases that step (a)
     * cannot catch — e.g. `Derived<string>` vs `Base<number>` where source/target have
     * DIFFERENT target interfaces. Self-referential generics (`List<T> { next: List<T> }`)
     * are now safe because Type.Reference interning makes logically-identical Refs share
     * an id, so `relationComparisonStack` catches the cycle.
     *
     * Method handling relies on `resolvedPropertyTypes` caching to avoid OOM in
     * Promise/IPromise-style deep overload-permutation comparisons (each level would
     * otherwise allocate fresh Symbols/Signatures/Type.Object instances).
     *
     * Falls back to raw `getTypeOfSymbol` when the helper returns null (non-passthrough
     * inherited property or non-Reference object type).
     */
    private fun getPropertyTypeForRelation(obj: Type.Object, prop: Symbol): Type {
        if (obj is Type.Reference) {
            // Skip when we're already deep in a comparison: deep generic-method
            // recursion (Promise/IPromise overload permutations, bluebird-style)
            // allocates a fresh Symbol/Signature/Type.Object per call, OOMing
            // before the deeply-nested heuristic can bail. Outer layers still
            // benefit from substituted property types; inner layers fall back
            // to raw `getTypeOfSymbol` (errorType for unbound T) which the
            // existing trivial-pass path handles.
            resolveGenericPropertyType(obj, prop)?.let { return it }
        }
        return getTypeOfSymbol(prop)
    }

    /**
     * Collect all non-optional property names from targetType that are missing from sourceType.
     * Used to decide between TS2741 (single missing) and TS2740 (multiple missing).
     *
     * Returns an empty list when `source.members` is null — e.g., anonymous function
     * types from `() => T` whose `Type.Object` carries only call signatures. In that
     * case the comparison failure is a kind mismatch (callable vs shape), not a
     * "property X is missing" situation, so the caller should fall through to plain
     * TS2322 instead of TS2739/TS2741. Matches TypeScript's baseline for tests like
     * `assigningFunctionToTupleIssuesError_ts` (`() => void` → `[string]`).
     */
    /** B175: member NAMES of a class symbol's declarations on one side (static or instance),
     *  walking the `extends` chain through globals. */
    private fun classMemberNamesTransitive(sym: Symbol, staticSide: Boolean, depth: Int = 0): Set<String> {
        if (depth > 8) return emptySet()
        val out = mutableSetOf<String>()
        for (d in sym.declarations) {
            if (d !is ClassDeclaration) continue
            for (m in d.members) {
                // Round 937 — (CHK.5)(a): the TARGET side of B175's comparison is
                // `tt.properties`, i.e. the resolved TYPE, which names every member
                // spelling — so this AST-Identifier-only collection is the same B451 drift
                // one walker over. `interface T { 1: string }` against
                // `declare class C { static 1: string }` was TS2741 at HEAD with no computed
                // key involved; the `dynamicNames` baseline reached it once `[c1]` named `1`.
                val (nm, mods) = when (m) {
                    is PropertyDeclaration -> declaredMemberName(m.name) to m.modifiers
                    is MethodDeclaration -> declaredMemberName(m.name) to m.modifiers
                    is GetAccessor -> declaredMemberName(m.name) to m.modifiers
                    is SetAccessor -> declaredMemberName(m.name) to m.modifiers
                    else -> null to null
                }
                if (nm != null && mods != null && (ModifierFlag.Static in mods) == staticSide) out.add(nm)
            }
            val baseName = d.heritageClauses
                ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                ?.types?.firstOrNull()?.let { (it.expression as? Identifier)?.text }
            val baseSym = baseName?.let { globals[it] }
            if (baseSym != null && baseSym.declarations.any { it is ClassDeclaration }) {
                out.addAll(classMemberNamesTransitive(baseSym, staticSide, depth + 1))
            }
        }
        return out
    }

    /** B559: instance member names declared DIRECTLY in [t]'s own class/interface
     *  body (non-static), in source order. Used to reorder a missing-property set
     *  own-first for the empty-array-literal → named-type display (tsc lists a type's
     *  OWN members before inherited ones). */
    private fun ownInstanceMemberNamesOfInterface(t: Type.Interface): List<String> {
        val sym = t.symbol ?: return emptyList()
        val names = mutableListOf<String>()
        val seen = mutableSetOf<String>()
        for (d in sym.declarations) {
            val members = when (d) {
                is ClassDeclaration -> d.members
                is InterfaceDeclaration -> d.members
                else -> continue
            }
            for (m in members) {
                val nameNode: NameNode
                val mods: Set<ModifierFlag>
                when (m) {
                    is PropertyDeclaration -> { nameNode = m.name; mods = m.modifiers }
                    is MethodDeclaration -> { nameNode = m.name; mods = m.modifiers }
                    is GetAccessor -> { nameNode = m.name; mods = m.modifiers }
                    is SetAccessor -> { nameNode = m.name; mods = m.modifiers }
                    else -> continue
                }
                if (ModifierFlag.Static in mods) continue
                val nm = when (nameNode) {
                    is Identifier -> nameNode.text
                    is StringLiteralNode -> nameNode.text
                    is NumericLiteralNode -> nameNode.text
                    else -> null
                } ?: continue
                if (nm !in seen) { seen.add(nm); names.add(nm) }
            }
        }
        return names
    }

    /**
     * M2.2 (round 393): does [target] have ≥1 REQUIRED named property (non-static,
     * non-prototype) that is absent from [source]'s members? Unlike
     * [collectMissingProperties] / [getMissingRequiredPropertySymbol] this does NOT bail
     * when `source.members` is null — a bare-function source (`callSignatures` only,
     * `members == null`) is treated as "has no named members", so every required target
     * property is missing. Used to defer the construct-sig / call-sig mismatch TS2322
     * (17.111 / 17.112) to the missing-property path (TS2739/TS2740) when the source is
     * ALSO missing target properties, matching tsc's report-a-structural-failure-once rule
     * (`redefineArray`: a plain function assigned to `ArrayConstructor` reports only the
     * TS2739, not the additional `new (...)` mismatch).
     */
    private fun targetHasRequiredPropAbsentFromSource(source: Type.Object, target: Type.Object): Boolean {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        val targetProps = target.properties ?: return false
        val srcMembers = source.members
        val targetStatics = getStaticMembersOfType(target)
        return targetProps.any { p ->
            !isOptionalProperty(p) &&
                p.name !in OBJECT_PROTOTYPE_PROPERTIES &&
                (targetStatics == null || !targetStatics.containsKey(p.name)) &&
                (srcMembers == null || p.name !in srcMembers)
        }
    }

    /** Round 471: true when [propName] on [targetType] is contributed ONLY by LIB
     *  declarations while the interface is ALSO declared top-level in a MODULE file
     *  (`Symbol` — tsc compiler/types.ts vs lib es2019's `description`). tsc never
     *  merges a module-scoped interface with the same-named lib global (the module's
     *  import shadows it), so the lib members are phantom for code written against
     *  the module interface. Skipping them in missing-member verdicts is FN-not-FP
     *  (a file genuinely meaning the LIB interface loses a real missing-member
     *  error, accepted). Script-file lib augmentations (`interface Array<T>` in a
     *  non-module file) do NOT trip the gate — those merges are real. */
    private fun isLibPhantomMemberOfModuleInterface(targetType: Type, propName: String): Boolean {
        val obj = targetType as? Type.Object ?: return false
        val sym = obj.symbol ?: return false
        // Round 471b perf: memoized per SYMBOL id — the un-memoized declaration scans
        // in propertiesRelatedTo's per-prop loop doubled the services self-compile
        // (39 s → 77 s). null = not a mixed lib+module interface (the common case).
        val phantom = libPhantomMembersCache.getOrPut(sym.id) {
            when {
                sym.name !in moduleInterfaceNames -> null
                sym.declarations.none { it in builtinLibDecls } -> null
                sym.declarations.none { it is InterfaceDeclaration && it !in builtinLibDecls } -> null
                else -> obj.members
                    ?.filterValues { p ->
                        p.declarations.isNotEmpty() &&
                            p.declarations.all { it in builtinLibMemberDecls }
                    }
                    ?.keys ?: emptySet()
            }
        }
        return phantom != null && propName in phantom
    }

    /**
     * The `object` keyword's APPARENT type for the missing-property elaboration, or null
     * for every other source.
     *
     * tsc has no `object`-specific elaboration: `structuredTypeRelatedTo` compares
     * `getApparentType(source)`, which for `TypeFlags.NonPrimitive` is `emptyObjectType`,
     * so `propertiesRelatedTo` sees a member-LESS object and `reportUnmatchedProperty`
     * fires — TS2741 (one missing) / TS2739 / TS2740, with the source displayed as `{}`,
     * NOT as `object`. We keep `object` as a `Type.Intrinsic`, so `collectMissingProperties`
     * (which requires a `Type.Object` on both sides) answers "nothing missing" and the
     * emission falls through to the coarse TS2322.
     *
     * Keyed on the SOURCE's `NonPrimitive` flag, so nothing that does not write the
     * `object` keyword can reach it, and it is applied at the missing-property EMISSION
     * sites only — never in [getApparentType], whose ~40 consumers ask a different
     * question (round 834 measured what widening a shared predicate costs).
     *
     * The relation verdict is unchanged either way: this only decides which SHAPE the
     * already-failing assignment is reported in.
     */
    private fun nonPrimitiveMissingPropSource(sourceType: Type): Type.Object? =
        if (sourceType.flags.hasAny(TypeFlags.NonPrimitive)) nonPrimitiveApparentType else null

    private fun collectMissingProperties(sourceType: Type, targetType: Type): List<String> {
        if (sourceType !is Type.Object || targetType !is Type.Object) return emptyList()
        resolveStructuredTypeMembers(sourceType)
        resolveStructuredTypeMembers(targetType)
        val sourceMembers = sourceType.members ?: return emptyList()
        val targetProps = targetType.properties ?: return emptyList()
        val targetStatics = getStaticMembersOfType(targetType)
        // B590 (assignmentToObjectAndFunction): B86.2 (iter7) wrongly unfiltered
        // `Function.toString` from the OBJECT_PROTOTYPE_PROPERTIES filter, thinking it a
        // real own member. tsc does NOT count `toString` as missing for a Function target
        // — every object provides Object.prototype.toString — so the missing list for
        // `{} : Function` is `apply, call, bind, prototype, and 5 more` (no toString).
        // Reverted: `toString` is filtered like any other prototype prop.
        val missing = mutableListOf<String>()
        for (prop in targetProps) {
            if (isOptionalProperty(prop)) continue
            // Skip target static members — they live on the class's static side and
            // are not part of the instance shape we're comparing against.
            if (targetStatics != null && targetStatics.containsKey(prop.name)) continue
            val isPrototypeProp = prop.name in OBJECT_PROTOTYPE_PROPERTIES
            // B175: a source member declared ONLY static does NOT satisfy an instance-side
            // requirement (statics live in BOTH `members` and `staticMembers` per the
            // bifurcation model, so name-presence alone over-counts: `class C { static
            // prop() {} }` instances have NO `prop`).
            val srcSym = sourceMembers[prop.name]
            val srcStaticOnly = srcSym != null && srcSym.declarations.isNotEmpty() &&
                srcSym.declarations.all { d ->
                    when (d) {
                        is PropertyDeclaration -> ModifierFlag.Static in d.modifiers
                        is MethodDeclaration -> ModifierFlag.Static in d.modifiers
                        is GetAccessor -> ModifierFlag.Static in d.modifiers
                        is SetAccessor -> ModifierFlag.Static in d.modifiers
                        else -> false
                    }
                }
            if ((prop.name !in sourceMembers || srcStaticOnly) && !isPrototypeProp) {
                if (isLibPhantomMemberOfModuleInterface(targetType, prop.name)) continue
                missing.add(prop.name)
            }
        }
        return missing
    }

    /**
     * Format a TS2740 message: "Type 'X' is missing the following properties from type 'Y': a, b, c, and N more."
     * Lists up to 4 property names; if >5 total, appends "and N more".
     */
    /**
     * B50.10: Detect the `Object`-source-to-named-target shape that warrants
     * TS2696 "The 'Object' type is assignable to very few other types. Did you
     * mean to use the 'any' type instead?" instead of plain TS2739/TS2740. The
     * source must be the lib `Object` interface (named, no own type args), and
     * the target a different named class/interface. Anonymous-object sources
     * and `Object`-target cases fall through to the standard chain.
     */
    private fun shouldEmitTs2696ForObject(source: Type, target: Type): Boolean {
        if (source !is Type.Interface) return false
        if (source.symbol?.name != "Object") return false
        if (target !is Type.Interface) return false
        if (target.symbol == null || target.symbol?.name == "Object") return false
        return true
    }

    private fun formatTs2740Message(displaySource: String, displayTarget: String, missing: List<String>): String {
        val listed = if (missing.size > 5) missing.take(4) else missing
        val suffix = if (missing.size > 5) ", and ${missing.size - 4} more." else ""
        return "Type '$displaySource' is missing the following properties from type '$displayTarget': ${listed.joinToString(", ")}$suffix"
    }

    /**
     * Collects all property names from a target type, flattening intersections and interfaces.
     * Returns null if the type cannot be used for excess property checking.
     */
    private fun collectTargetPropertyNames(type: Type): Set<String>? {
        return when (type) {
            is Type.Object -> {
                // If the target has a string index signature, any string-keyed property is valid
                if (type.stringIndexInfo != null) return null
                type.members?.keys?.toSet()
            }
            is Type.Interface -> {
                // If the target has a declared string index signature, any string-keyed property is valid
                if (type.declaredStringIndexInfo != null || type.stringIndexInfo != null) return null
                type.members?.keys?.toSet()
            }
            is Type.Intersection -> {
                val names = mutableSetOf<String>()
                for (constituent in type.types) {
                    // Resolve members first — an unresolved anonymous TypeLiteral constituent
                    // (`{ id: number } & { url: string }` from `typeof obj.photo`) has a null
                    // member table until resolved, which would wrongly return null here.
                    (constituent as? Type.Object)?.let { resolveStructuredTypeMembers(it) }
                    // If any constituent has a string index signature, all properties are valid
                    val constituentNames = collectTargetPropertyNames(constituent)
                    if (constituentNames == null) return null
                    names.addAll(constituentNames)
                }
                if (names.isEmpty()) null else names
            }
            is Type.Union -> {
                // 16.0: Union target — a source property is excess only if it's in NONE
                // of the union constituents. Take the union of all object/interface constituent
                // property names. Non-shape constituents (primitives, function-only object
                // types) don't contribute property names and are skipped. If any shape
                // constituent has a string index signature, all keys are valid → bail.
                val names = mutableSetOf<String>()
                var hasShapeConstituent = false
                for (constituent in type.types) {
                    if (constituent !is Type.Object && constituent !is Type.Interface) continue
                    resolveStructuredTypeMembers(constituent)
                    val cObj = constituent
                    // Skip function-only types (call sigs but no members)
                    if (cObj.members == null) continue
                    val constituentNames = collectTargetPropertyNames(constituent)
                    if (constituentNames == null) return null // string index sig → bail
                    names.addAll(constituentNames)
                    hasShapeConstituent = true
                }
                if (!hasShapeConstituent) null
                else if (names.isEmpty()) null
                else names
            }
            else -> null
        }
    }

    /**
     * For union target display in TS2353, pick the first Object/Interface constituent
     * that contains none of the excess source property names (i.e., the constituent
     * whose shape the source was "meant" to match). Fallback: first object constituent.
     */
    private fun pickUnionDisplayTarget(unionType: Type.Union): Type? {
        for (c in unionType.types) {
            if (c is Type.Object || c is Type.Interface) return c
        }
        return null
    }

    /**
     * 16.0: Check that the RHS of an `in` expression is an object-like type.
     * Emits TS2322 "Type 'X' is not assignable to type 'object'." for primitive
     * RHS types like `'' in 0` or `0 in 'foo'`.
     */
    private fun checkInOperatorRhs(rhs: Expression, source: String, fileName: String) {
        val rhsType = getTypeOfExpression(rhs)
        if (rhsType === anyType || rhsType === errorType) return
        if (rhsType === unknownType) {
            // inKeywordAndUnknown: `<expr> in y` where `y: unknown` is narrowed
            // by a truthiness guard (NOT instanceof) to `{}` → TS2638 "may
            // represent a primitive". Scoped narrowing walk maps a truthy bare
            // `unknown` to the `truthyUnknownType` sentinel; declared `{}` and
            // instanceof-narrowed operands don't reach it. currentFlowGraph is
            // set only HERE (the arithmetic pass otherwise stays flow-unaware).
            val flowGraph = currentArithmeticFlowGraph
            val path = if (flowGraph != null) getReferencePath(rhs) else null
            if (flowGraph != null && path != null) {
                val savedGraph = currentFlowGraph
                val savedFlag = narrowUnknownToEmptyObject
                currentFlowGraph = flowGraph
                narrowUnknownToEmptyObject = true
                val narrowed = try {
                    val flow = getFlowAt(rhs)
                    if (flow != null) {
                        flowWalkWithTripCheck(rhs, WK_RHS, unknownType.id.toLong() shl 32 or (path.hashCode().toLong() and 0xFFFF_FFFFL), flowPathRoot(path)) {
                            narrowTypeFromFlow(unknownType, flow, path, NarrowSeen(), 0)
                        } ?: unknownType
                    } else unknownType
                } finally {
                    currentFlowGraph = savedGraph
                    narrowUnknownToEmptyObject = savedFlag
                }
                if (narrowed === truthyUnknownType) {
                    val start = rhs.pos
                    val length = expressionTrueEnd(rhs) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Type '{}' may represent a primitive value, which is not permitted as the right operand of the 'in' operator.",
                            category = DiagnosticCategory.Error,
                            code = 2638,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
            }
            return
        }
        // null/undefined are valid (handled separately by strictNullChecks)
        if (rhsType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return
        // Object/Interface/Reference types are valid
        if (rhsType is Type.Object || rhsType is Type.Interface) return
        if (rhsType is Type.TypeParam) return // generic — accept conservatively
        // Primitive types are invalid for `in` RHS
        val isPrimitive = rhsType.flags.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.BigInt or TypeFlags.ESSymbol or TypeFlags.Void or
            TypeFlags.Never or
            TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
            TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral or
            TypeFlags.Enum
        )
        if (!isPrimitive) return
        val displaySource = typeToString(rhsType)
        val start = rhs.pos
        val length = expressionTrueEnd(rhs) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type '$displaySource' is not assignable to type 'object'.",
            category = DiagnosticCategory.Error,
            code = 2322,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * B98.r101: TS2367 for a `const`-literal compared (`==`/`===`/`!=`/`!==`) to a
     * DIFFERENT literal. A `const x = 0` (no annotation, bare literal initializer)
     * keeps the literal type `0`, so `x == 1` is "This comparison appears to be
     * unintentional because the types '0' and '1' have no overlap." A `let`/`var`
     * (or annotated const) WIDENS to `number`, so those don't fire — which is exactly
     * why `capturedLetConstInLoop5-8`'s `for (const x = 0; …) if (x == 1)` cases error
     * but the `let`/`for-of`/`for-in` siblings don't. Purely AST-level + scope-aware
     * (a `const` keeps its value immutably, so the comparison is always false →
     * TS-correct, near-zero FP). Tracked names are removed in any inner scope that
     * re-declares them (shadowing).
     */
    private data class ConstLitInfo(val display: String, val key: String)

    /** Extract a `const`-literal value from a bare literal initializer/operand. */
    private fun constLiteralOf(expr: Expression?): ConstLitInfo? = when (expr) {
        is NumericLiteralNode -> expr.text.toDoubleOrNull()?.let { ConstLitInfo(expr.text, "n:$it") }
        is StringLiteralNode -> ConstLitInfo("\"${expr.text}\"", "s:${expr.text}")
        is PrefixUnaryExpression ->
            if (expr.operator == SyntaxKind.Minus && expr.operand is NumericLiteralNode) {
                val num = (expr.operand).text
                num.toDoubleOrNull()?.let { ConstLitInfo("-$num", "n:${-it}") }
            } else null
        else -> null
    }

    // ── (M0.4) round 646: checkConstLiteralComparisons on the spine ────────
    // (B98.r101 TS2367 — a for-INIT `const x = <bare literal>` compared to a
    // DIFFERENT literal.) The legacy driver + walkConstLitStatements/
    // -Statement/-Expr recursion are deleted; [emitConstLitNoOverlap]
    // (+ [constLiteralOf]) survives as the anchor-called leaf. See the field
    // block for the walk's shape; [spineClScopeAt] rebuilds the downward map
    // pull-based per anchor (memo-free — the pre-filter makes folds rare).

    /** Per-file spine setup: the legacy driver's dts + non-checkJs js/jsx skips. */
    private fun spineClSetup() {
        spineClActive = !spineIsDts &&
            (options.checkJs || !(spineFileName.endsWith(".js") || spineFileName.endsWith(".jsx")))
    }

    private fun spineClTeardown() {
        spineClActive = false
    }

    /** ENTER dispatch: ==/===/!=/!== BinaryExpressions. Two pre-filters run
     *  BEFORE the fold: ≥1 operand must be a bare Identifier (the emission
     *  requires a TRACKED identifier operand), and some ForStatement
     *  ancestor's const init must ADD one of the operand names — the map is
     *  populated ONLY by for-init const-literal adds (the shadow prepass and
     *  param boundaries only REMOVE), so without such an ancestor the map at
     *  the anchor is empty and the emission cannot fire. */
    private fun spineClEnterNode(node: Node) {
        if ((node as NodeBase).kindId != NodeKind.BINARY_EXPRESSION) return
        node as BinaryExpression
        val op = node.operator
        if (op != SyntaxKind.EqualsEquals && op != SyntaxKind.ExclamationEquals &&
            op != SyntaxKind.EqualsEqualsEquals && op != SyntaxKind.ExclamationEqualsEquals
        ) return
        val lt = (node.left as? Identifier)?.text
        val rt = (node.right as? Identifier)?.text
        if (lt == null && rt == null) return
        var candidate = false
        var cur: Node? = node.parent
        outer@ while (cur != null) {
            if (cur is ForStatement) {
                val vdl = cur.initializer as? VariableDeclarationList
                if (vdl != null && vdl.flags == SyntaxKind.ConstKeyword) {
                    for (d in vdl.declarations) {
                        val nm = (d.name as? Identifier)?.text ?: continue
                        if ((nm == lt || nm == rt) && d.type == null &&
                            constLiteralOf(d.initializer) != null
                        ) {
                            candidate = true
                            break@outer
                        }
                    }
                }
            }
            cur = (cur as NodeBase).parent
        }
        if (!candidate) return
        val scope = spineClScopeAt(node) ?: return
        if (scope.isNotEmpty()) emitConstLitNoOverlap(node, scope, spineSource, spineFileName)
    }

    /**
     * Rebuilds the deleted walk's downward const-literal map at [node] — null
     * when the legacy recursion never reached the position. Ascends to the
     * SourceFile (a detached/unindexed chain is unreached), then folds
     * [spineClFold] back down from an empty map.
     */
    private fun spineClScopeAt(node: Node): Map<String, ConstLitInfo>? {
        val chain = spineClChain
        chain.clear()
        var cur: Node = node
        var root: SourceFile? = null
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent ?: break // detached/unindexed → unreached
            if (parent is SourceFile) {
                root = parent
                break
            }
            cur = parent
        }
        if (root == null) {
            chain.clear()
            return null
        }
        var pNode: Node = root
        var scope: Map<String, ConstLitInfo> = emptyMap()
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            val next = spineClFold(pNode, scope, c)
            if (next == null) {
                chain.clear()
                return null
            }
            scope = next
            pNode = c
        }
        chain.clear()
        return scope
    }

    /**
     * The deleted recursion's arms, verbatim, as (parent → child) map
     * transitions — null = an edge the legacy walk never descended. Statement
     * LISTs apply the whole-list shadow prepass; the ForStatement arm applies
     * the for-init transform to cond/incr/body (its Expression initializer
     * keeps the OUTER map — equivalent anyway: the inner map differs only
     * when the initializer is a declaration list); fn-decl/fn-expr/arrow
     * boundaries remove param names; class method/ctor bodies keep the
     * class-outer map unchanged (params deliberately NOT removed — frozen);
     * the legacy left-spine binary iteration dissolves into plain
     * left/right edges.
     */
    private fun spineClFold(
        p: Node, s: Map<String, ConstLitInfo>, c: Node,
    ): Map<String, ConstLitInfo>? = when (p) {
        is SourceFile -> if (c is Statement) spineClPrepass(s, p.statements) else null
        // ---- walkConstLitStatement arms ----
        is VariableStatement -> if (c === p.declarationList) s else null
        is VariableDeclarationList -> if (c is VariableDeclaration) s else null
        is VariableDeclaration -> if (c === p.initializer) s else null
        is ExpressionStatement -> if (c === p.expression) s else null
        is ReturnStatement -> if (c === p.expression) s else null
        is ThrowStatement -> if (c === p.expression) s else null
        is IfStatement -> if (c === p.expression || c === p.thenStatement ||
            c === p.elseStatement) s else null
        is Block -> if (c is Statement) spineClPrepass(s, p.statements) else null
        is ForStatement -> when {
            c === p.initializer && c is Expression -> s
            c === p.condition || c === p.incrementor || c === p.statement ->
                spineClForInner(s, p)
            else -> null // a for-init DECLARATION-LIST initializer is never walked
        }
        is ForInStatement -> if (c === p.statement) s else null // heads unreached
        is ForOfStatement -> if (c === p.statement) s else null // heads unreached
        is LabeledStatement -> if (c === p.statement) s else null
        is WhileStatement -> if (c === p.expression || c === p.statement) s else null
        is DoStatement -> if (c === p.statement || c === p.expression) s else null
        is SwitchStatement -> if (c === p.expression || c is CaseClause ||
            c is DefaultClause) s else null
        is CaseClause -> if (c === p.expression) s
            else if (c is Statement) spineClPrepass(s, p.statements) else null
        is DefaultClause -> if (c is Statement) spineClPrepass(s, p.statements) else null
        is TryStatement -> if (c === p.tryBlock || c === p.finallyBlock ||
            c is CatchClause) s else null
        is CatchClause -> if (c === p.block) s else null // the catch VARIABLE never shadows (frozen)
        is FunctionDeclaration -> if (c === p.body) spineClMinusParams(s, p.parameters) else null
        is ModuleDeclaration -> if (c === p.body && c is ModuleBlock) s else null
        is ModuleBlock -> if (c is Statement) spineClPrepass(s, p.statements) else null
        is ClassDeclaration -> if (c is MethodDeclaration || c is Constructor ||
            c is PropertyDeclaration) s else null // accessors/heritage unreached
        is MethodDeclaration -> if (c === p.body) s else null // params NOT removed (frozen)
        is Constructor -> if (c === p.body) s else null // params NOT removed (frozen)
        is PropertyDeclaration -> if (c === p.initializer) s else null
        // ---- walkConstLitExpr arms ----
        is BinaryExpression -> if (c === p.left || c === p.right) s else null
        is ParenthesizedExpression -> if (c === p.expression) s else null
        is PrefixUnaryExpression -> if (c === p.operand) s else null
        is PostfixUnaryExpression -> if (c === p.operand) s else null
        is ConditionalExpression -> if (c === p.condition || c === p.whenTrue ||
            c === p.whenFalse) s else null
        is CallExpression -> if (c === p.expression || p.arguments.any { it === c }) s else null
        is NewExpression -> if (p.arguments?.any { it === c } == true) s else null // CALLEE unreached
        is PropertyAccessExpression -> if (c === p.expression) s else null
        is ElementAccessExpression -> if (c === p.expression || c === p.argumentExpression) s else null
        is AsExpression -> if (c === p.expression) s else null
        is NonNullExpression -> if (c === p.expression) s else null
        is ArrowFunction -> if (c === p.body) spineClMinusParams(s, p.parameters) else null
        is FunctionExpression -> if (c === p.body) spineClMinusParams(s, p.parameters) else null
        is ArrayLiteralExpression -> if (p.elements.any { it === c }) s else null
        else -> null
    }

    /** The whole-list SHADOW prepass: any VariableStatement declaration name
     *  in [stmts] removes an inherited entry. A block-level `const`/`let`/
     *  `var` never ADDS — TypeScript widens a loop-BODY-captured block const
     *  (`while (…) { const x = 1; if (x == 2) … }` does NOT error, unlike a
     *  for-INITIALIZER const). */
    private fun spineClPrepass(
        s: Map<String, ConstLitInfo>, stmts: List<Statement>,
    ): Map<String, ConstLitInfo> {
        if (s.isEmpty()) return s
        val out = HashMap(s)
        for (stmt in stmts) {
            if (stmt !is VariableStatement) continue
            for (decl in stmt.declarationList.declarations) {
                (decl.name as? Identifier)?.text?.let { out.remove(it) }
            }
        }
        return out
    }

    /** fn-decl/fn-expr/arrow boundary: remove parameter names (copied map). */
    private fun spineClMinusParams(
        s: Map<String, ConstLitInfo>, params: List<Parameter>,
    ): Map<String, ConstLitInfo> {
        if (s.isEmpty()) return s
        val out = HashMap(s)
        for (p in params) (p.name as? Identifier)?.text?.let { out.remove(it) }
        return out
    }

    /** The ForStatement arm's inner-map transform: a for-init `const x =
     *  <bare literal>` (no annotation) ADDS; every other for-init
     *  declaration REMOVES its name. */
    private fun spineClForInner(
        s: Map<String, ConstLitInfo>, p: ForStatement,
    ): Map<String, ConstLitInfo> {
        val vdl = p.initializer as? VariableDeclarationList ?: return s
        val out = HashMap(s)
        val isConst = vdl.flags == SyntaxKind.ConstKeyword
        for (d in vdl.declarations) {
            val nm = (d.name as? Identifier)?.text ?: continue
            val lit = if (isConst && d.type == null) constLiteralOf(d.initializer) else null
            if (lit != null) out[nm] = lit else out.remove(nm)
        }
        return out
    }

    /** Emit TS2367 when an eq-comparison has a const-literal operand vs a different literal. */
    private fun emitConstLitNoOverlap(
        expr: BinaryExpression, scope: Map<String, ConstLitInfo>, source: String, fileName: String,
    ) {
        fun operandLit(e: Expression): ConstLitInfo? {
            if (e is Identifier) return scope[e.text]
            return constLiteralOf(e)
        }
        val leftHasConst = expr.left is Identifier && scope.containsKey((expr.left).text)
        val rightHasConst = expr.right is Identifier && scope.containsKey((expr.right).text)
        if (!leftHasConst && !rightHasConst) return
        val l = operandLit(expr.left) ?: return
        val r = operandLit(expr.right) ?: return
        if (l.key == r.key) return  // same value → overlap, no error
        val start = expr.pos
        val length = expressionTrueEnd(expr.right) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This comparison appears to be unintentional because the types '${l.display}' and '${r.display}' have no overlap.",
            category = DiagnosticCategory.Error, code = 2367,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    /** Resolve a bare value-position class name to its [ClassDeclaration], or null. */
    private fun resolveClassDeclByName(name: String): ClassDeclaration? =
        (currentFileLocals?.get(name) ?: globals[name])
            ?.declarations?.firstOrNull { it is ClassDeclaration } as? ClassDeclaration

    /** Does [cls] declare a `private` instance member (nominal-brand)? */
    private fun classHasPrivateMember(cls: ClassDeclaration): Boolean = cls.members.any { m ->
        when (m) {
            is PropertyDeclaration -> ModifierFlag.Private in m.modifiers
            is MethodDeclaration -> ModifierFlag.Private in m.modifiers
            else -> false
        }
    }

    /**
     * typeMatch1: `C == D` comparing two distinct class VALUES (their `typeof` static sides) where
     * both classes carry a `private` instance member → nominal brands make the constructor return
     * types non-comparable, so `typeof C` and `typeof D` have no overlap → TS2367. AST-gated and
     * FP-safe: requires two distinct class identifiers each with a private member (`C == C` and
     * structurally-overlapping classes are excluded).
     */
    private fun tryEmitClassValueNoOverlap(expr: BinaryExpression, source: String, fileName: String): Boolean {
        val left = expr.left as? Identifier ?: return false
        val right = expr.right as? Identifier ?: return false
        val leftCls = resolveClassDeclByName(left.text) ?: return false
        val rightCls = resolveClassDeclByName(right.text) ?: return false
        if (leftCls === rightCls) return false
        if (!classHasPrivateMember(leftCls) || !classHasPrivateMember(rightCls)) return false
        val start = expr.pos
        val length = expressionTrueEnd(expr.right) - start
        if (length <= 0) return false
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This comparison appears to be unintentional because the types " +
                "'typeof ${left.text}' and 'typeof ${right.text}' have no overlap.",
            category = DiagnosticCategory.Error, code = 2367,
            fileName = fileName, line = line, character = character, start = start, length = length,
        ))
        return true
    }

    private fun checkEqualityComparisonNoOverlap(
        expr: BinaryExpression, source: String, fileName: String,
    ) {
        if (tryEmitClassValueNoOverlap(expr, source, fileName)) return
        val leftType = getTypeOfExpression(expr.left)
        val rightType = getTypeOfExpression(expr.right)
        if (leftType === anyType || leftType === errorType) return
        if (rightType === anyType || rightType === errorType) return
        if (leftType === unknownType || rightType === unknownType) return
        if (leftType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return
        if (rightType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) return
        // expr.ts: `==`/`!=` between two operands of DIFFERENT primitive comparability
        // categories (number ⇎ string ⇎ boolean) → TS2367 "no overlap". Numeric enums
        // map to the "number" category (a numeric enum vs number does NOT error; enum
        // vs string/boolean does). comparabilityCategory returns null for
        // any/bigint/object/heterogeneous-union, so those bail (FN over FP) — the same
        // firewall the `<`/`>` relational path relies on. Placed before the object/
        // reference checks below (which never fire for primitives). The DISPLAY uses the
        // category name for pure number/string/boolean and typeToString for an enum
        // (baseline shows `'string' and 'E'`, not `'string' and 'number'`).
        run {
            val lc = comparabilityCategory(leftType)
            val rc = comparabilityCategory(rightType)
            if (lc != null && rc != null && lc != rc) {
                val ld = ts2367CategoryDisplay(leftType, lc)
                val rd = ts2367CategoryDisplay(rightType, rc)
                val start = expr.pos
                val length = expressionTrueEnd(expr.right) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "This comparison appears to be unintentional because the types " +
                            "'$ld' and '$rd' have no overlap.",
                        category = DiagnosticCategory.Error, code = 2367,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                    ))
                }
                return
            }
        }
        // B283: bigint and number have no overlap (tsc isTypeEqualityComparableTo
        // fails both directions). Strict kinds only — unions mixing the two, any,
        // and TypeParam operands bail. Displays are the widened bases.
        if (leftType !is Type.TypeParam && rightType !is Type.TypeParam &&
            ((typeAssignableToBigIntKind(leftType) && typeAssignableToNumberKind(rightType)) ||
                (typeAssignableToNumberKind(leftType) && typeAssignableToBigIntKind(rightType)))) {
            val start = expr.pos
            val length = expressionTrueEnd(expr.right) - start
            if (length > 0) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "This comparison appears to be unintentional because the types " +
                        "'${arithWidenedDisplay(leftType)}' and '${arithWidenedDisplay(rightType)}' have no overlap.",
                    category = DiagnosticCategory.Error, code = 2367,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length,
                ))
            }
            return
        }
        // 17.73: TypeParam-with-literal-union-constraint vs literal — when one
        // side is a TypeParam whose apparent type is a union of all literals
        // (e.g. `T extends "a" | "b"`) and the other side is a literal, use
        // the literal-subtype-aware intersection helper to detect empty
        // overlap. If empty (never), emit TS2367 with the TypeParam's NAME
        // (not its constraint) so the message reads `... types 'T' and '"x"'
        // have no overlap.` matching TypeScript's display.
        checkTypeParamLiteralNoOverlap(expr, leftType, rightType, source, fileName)?.let { return }
        // B53.2: Named Type.Object non-overlap detection. When both sides are
        // distinct named (non-anonymous, non-Reference) object types with no shared
        // required property names, emit TS2367. Gate: both Type.Object with a
        // non-null symbol (rules out anonymous `{a:1}` literals), different symbols,
        // neither assignable to the other, and ALL required props of one side absent
        // from the other. Uses the same `import("X").T` cross-file qualification as
        // B53.1 when display names collide.
        val leftObjSym = (leftType as? Type.Object)?.symbol
        val rightObjSym = (rightType as? Type.Object)?.symbol
        // B63.32: Same-name cross-file interfaces. When two distinct Type.Interface
        // instances share the same display name but are declared in different files
        // (typical pattern: `import * as A from './a'; import * as B from './b';
        // declare let a: A.F; declare let b: B.F`), `mergeSymbolTable` pollutes one
        // side's `properties` with the other side's members. Use own-file declaration
        // names directly for disjointness check, bypassing the merged Type.Interface
        // contents. Emits TS2367 with `import("X").T` cross-file qualification.
        if (leftType is Type.Object && rightType is Type.Object &&
            leftType !is Type.Reference && rightType !is Type.Reference &&
            leftObjSym != null && rightObjSym != null && leftObjSym !== rightObjSym &&
            leftObjSym.name == rightObjSym.name) {
            val leftImport = getSymbolImportName(leftObjSym)
            val rightImport = getSymbolImportName(rightObjSym)
            if (leftImport != null && rightImport != null && leftImport != rightImport) {
                val leftOwn = getOwnFileInterfacePropertyNames(leftObjSym, leftImport)
                val rightOwn = getOwnFileInterfacePropertyNames(rightObjSym, rightImport)
                if (leftOwn != null && rightOwn != null &&
                    leftOwn.isNotEmpty() && rightOwn.isNotEmpty() &&
                    leftOwn.intersect(rightOwn).isEmpty()) {
                    val leftDispRaw = typeToString(leftType)
                    val rightDispRaw = typeToString(rightType)
                    val leftDisp = "import(\"$leftImport\").$leftDispRaw"
                    val rightDisp = "import(\"$rightImport\").$rightDispRaw"
                    val start = expr.pos
                    val length = expressionTrueEnd(expr.right) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
                            category = DiagnosticCategory.Error,
                            code = 2367,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    return
                }
            }
        }
        if (leftType is Type.Object && rightType is Type.Object &&
            leftType !is Type.Reference && rightType !is Type.Reference &&
            leftObjSym != null && rightObjSym != null && leftObjSym !== rightObjSym) {
            resolveStructuredTypeMembers(leftType)
            resolveStructuredTypeMembers(rightType)
            val leftProps = leftType.properties ?: emptyList()
            val rightProps = rightType.properties ?: emptyList()
            val leftRequired = leftProps.filter { !isOptionalProperty(it) && it.name !in OBJECT_PROTOTYPE_PROPERTIES }
            val rightRequired = rightProps.filter { !isOptionalProperty(it) && it.name !in OBJECT_PROTOTYPE_PROPERTIES }
            if (leftRequired.isNotEmpty() && rightRequired.isNotEmpty()) {
                val rightMembers = rightType.members
                val leftMembers = leftType.members
                val leftAbsentFromRight = leftRequired.all { rightMembers?.get(it.name) == null }
                val rightAbsentFromLeft = rightRequired.all { leftMembers?.get(it.name) == null }
                if (leftAbsentFromRight && rightAbsentFromLeft &&
                    !checkTypeRelatedTo(leftType, rightType, assignableRelation) &&
                    !checkTypeRelatedTo(rightType, leftType, assignableRelation)) {
                    var leftDisp = typeToString(leftType)
                    var rightDisp = typeToString(rightType)
                    if (leftDisp == rightDisp) {
                        val li = getSymbolImportName(leftObjSym)
                        val ri = getSymbolImportName(rightObjSym)
                        if (li != null && ri != null && li != ri) {
                            leftDisp = "import(\"$li\").$leftDisp"
                            rightDisp = "import(\"$ri\").$rightDisp"
                        }
                    }
                    val start = expr.pos
                    val length = expressionTrueEnd(expr.right) - start
                    if (length > 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
                            category = DiagnosticCategory.Error,
                            code = 2367,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    return
                }
            }
        }
        if (leftType !is Type.Reference || rightType !is Type.Reference) return
        if (leftType.target !== rightType.target) return
        val leftArgs = leftType.resolvedTypeArguments ?: return
        val rightArgs = rightType.resolvedTypeArguments ?: return
        if (leftArgs.size != rightArgs.size) return
        if (leftArgs == rightArgs) return
        if (checkTypeRelatedTo(leftType, rightType, assignableRelation)) return
        if (checkTypeRelatedTo(rightType, leftType, assignableRelation)) return
        // round 431c: the disjointness proof above leans on the relation being
        // COMPLETE for the arg types — for an OBJECT-vs-OBJECT arg pair
        // (`NodeArray<TypeNode>` vs `NodeArray<Node>` where TypeNode extends Node
        // through cross-file heritage), a vacuous both-directions failure is
        // indistinguishable from genuine disjointness (M3). Only trust the proof
        // when some DIFFERING arg pair is anchored in a non-object type
        // (literal/primitive/enum — `Array<string>` vs `Array<number>` stays firing).
        var anchoredDisjoint = false
        for (i in leftArgs.indices) {
            val l = leftArgs[i]
            val r = rightArgs[i]
            if (l === r) continue
            if (l !is Type.Object || r !is Type.Object) {
                anchoredDisjoint = true
                break
            }
        }
        if (!anchoredDisjoint) return
        val leftDisp = typeToString(leftType)
        val rightDisp = typeToString(rightType)
        val start = expr.pos
        val length = expressionTrueEnd(expr.right) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
            category = DiagnosticCategory.Error,
            code = 2367,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * 17.73: TS2367 narrow extension — TypeParam-with-literal-union-constraint
     * vs literal. Returns Unit (non-null) if a TS2367 diagnostic was emitted,
     * null if the pattern didn't apply. Uses the 17.72 [intersectTwoTypesForWrite]
     * helper to compute the apparent-type intersection with full union
     * distribution + literal subtype reduction.
     *
     * Pattern: `t === "x"` where `t: T` and `T extends "a" | "b"` — apparent
     * type of T is `"a" | "b"`; intersection with `"x"` distributes to
     * `"a" & "x" | "b" & "x"` = `never`. When the apparent type is NOT a
     * union of all literals (e.g. `T extends string`), bail — that case is
     * a primitive vs literal pair which would still overlap (`string & "x"`
     * = `"x"`).
     */
    private fun checkTypeParamLiteralNoOverlap(
        expr: BinaryExpression,
        leftType: Type,
        rightType: Type,
        source: String,
        fileName: String,
    ): Unit? {
        val literalFlags = TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral

        fun apparentLiteralUnion(t: Type): Type? {
            if (t !is Type.TypeParam) return null
            val apparent = t.constraint?.let { getApparentType(it) } ?: return null
            return when (apparent) {
                is Type.Union -> if (apparent.types.all { it.flags.hasAny(literalFlags) }) apparent else null
                else -> if (apparent.flags.hasAny(literalFlags)) apparent else null
            }
        }

        // Recover the literal-typed view of an expression that getTypeOfExpression
        // widened to its primitive (e.g. StringLiteralNode → stringType). When the
        // expression IS a literal node, [literalTypeOfExpression] returns the
        // narrow literal type — exactly what TS2367 needs to compare against the
        // TypeParam's apparent literal-union constraint.
        val leftLit = literalTypeOfExpression(expr.left)
        val rightLit = literalTypeOfExpression(expr.right)
        val leftEffective = leftLit ?: leftType
        val rightEffective = rightLit ?: rightType

        val leftIsTP = leftEffective is Type.TypeParam
        val rightIsTP = rightEffective is Type.TypeParam
        val leftIsLit = leftEffective.flags.hasAny(literalFlags)
        val rightIsLit = rightEffective.flags.hasAny(literalFlags)

        val intersected: Type? = when {
            leftIsTP && rightIsLit -> {
                val app = apparentLiteralUnion(leftEffective) ?: return null
                intersectTwoTypesForWrite(app, rightEffective)
            }
            rightIsTP && leftIsLit -> {
                val app = apparentLiteralUnion(rightEffective) ?: return null
                intersectTwoTypesForWrite(leftEffective, app)
            }
            else -> return null
        }
        if (intersected == null || !intersected.flags.hasAny(TypeFlags.Never)) return null

        // Display the un-widened TypeParam name (typeToString of leftType / rightType)
        // and the literal form of the other side — matches TypeScript's TS2367 message.
        val leftDisp = if (leftLit != null) typeToString(leftLit) else typeToString(leftType)
        val rightDisp = if (rightLit != null) typeToString(rightLit) else typeToString(rightType)
        val start = expr.pos
        val length = expressionTrueEnd(expr.right) - start
        if (length <= 0) return null
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This comparison appears to be unintentional because the types '$leftDisp' and '$rightDisp' have no overlap.",
            category = DiagnosticCategory.Error,
            code = 2367,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
        return Unit
    }

    /**
     * TS2839: "This condition will always return 'false'/'true' since JavaScript
     * compares objects by reference, not value." Fires when one side of an
     * `==`/`===`/`!=`/`!==` comparison is a fresh object-/array-literal expression
     * — a newly allocated object never matches anything by reference.
     *
     * Narrow: requires the other side's type to overlap with the literal (i.e.
     * TS2367 wouldn't fire). If the other side is purely primitive without any
     * object-like constituent, the overlap check handles it as a different
     * diagnostic class.
     */
    private fun checkFreshLiteralReferenceEquality(
        expr: BinaryExpression, source: String, fileName: String,
    ) {
        val leftIsLit = expr.left is ObjectLiteralExpression || expr.left is ArrayLiteralExpression
        val rightIsLit = expr.right is ObjectLiteralExpression || expr.right is ArrayLiteralExpression
        if (!leftIsLit && !rightIsLit) return
        val otherType = getTypeOfExpression(if (leftIsLit) expr.right else expr.left)
        if (otherType === anyType || otherType === errorType || otherType === unknownType) return
        // Need at least one object-like constituent in the other side's type
        // for the "comparison by reference" message to apply (otherwise TS2367
        // would flag as no-overlap instead).
        val hasObjectLike: (Type) -> Boolean = { t ->
            t is Type.Object || t is Type.Reference || t is Type.Interface ||
            t.flags.hasAny(TypeFlags.NonPrimitive)
        }
        val overlaps = when (otherType) {
            is Type.Union -> otherType.types.any(hasObjectLike)
            else -> hasObjectLike(otherType)
        }
        if (!overlaps) return
        val op = expr.operator
        val isTruthy = op == SyntaxKind.ExclamationEquals || op == SyntaxKind.ExclamationEqualsEquals
        val verdict = if (isTruthy) "'true'" else "'false'"
        val start = expr.pos
        val length = expressionTrueEnd(expr.right) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This condition will always return $verdict since JavaScript compares objects by reference, not value.",
            category = DiagnosticCategory.Error,
            code = 2839,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * 16.0: Traverse a chained assignment right-hand side to find the innermost
     * ObjectLiteralExpression. Returns null if the chain doesn't end in a literal.
     * E.g. for `obj2 = obj3 = { a: 1 }`, returns the `{a: 1}` node.
     */
    private fun findChainedObjectLiteral(expr: Expression): ObjectLiteralExpression? {
        var cur: Expression = expr
        while (cur is BinaryExpression && cur.operator == SyntaxKind.Equals) {
            cur = cur.right
        }
        return cur as? ObjectLiteralExpression
    }

    /**
     * 16.0: Compute the display target string for a TS2353 diagnostic.
     * For inline union annotations (e.g. `const x: IProps | number = {...}`), pick
     * a representative object constituent so we display "IProps" instead of
     * "IProps | number". For type alias references that resolve to a union
     * (e.g. `type DoesntWork = A | B; const x: DoesntWork = {...}`), preserve
     * the alias name from the annotation text.
     */
    private fun excessPropDisplayTarget(targetType: Type, typeAnnotation: TypeNode?): String {
        // Only narrow when the annotation itself is a UnionType (not a reference to one)
        if (targetType is Type.Union && typeAnnotation is UnionType) {
            val pick = pickUnionDisplayTarget(targetType)
            if (pick != null) return typeToString(pick)
        }
        // A `typeof X` annotation displays the RESOLVED type, not the query text — tsc
        // renders `const photo: typeof obj.photo` excess errors as the resolved intersection
        // `{ id: number; } & { url: string; }` (excessPropertyChecksWithNestedIntersections).
        if (typeAnnotation is TypeQuery) return typeToString(targetType)
        return typeAnnotation?.let { formatTypeForDisplay(it) } ?: typeToString(targetType)
    }

    /**
     * Excess property check for fresh object literals (TS2353).
     * When an object literal is assigned to a typed target, any properties
     * in the source that don't exist in the target are excess properties.
     * Returns true if TS2353 diagnostics were emitted (caller should skip TS2741/TS2322).
     */
    /**
     * 16.0: For an array literal call argument with an Array<T> parameter type,
     * check each element against T using TS2322. Catches `foo([1, "a"])` where
     * foo takes number[]. Only fires when T is a simple checkable type to avoid
     * FPs from incomplete structural comparison.
     */
    private fun checkArrayLiteralElementsAgainstType(
        arrLit: ArrayLiteralExpression,
        arrayParamType: Type.Reference,
        source: String,
        fileName: String,
        literalElementsOnly: Boolean = false,
    ) {
        val elementType = arrayParamType.resolvedTypeArguments?.firstOrNull() ?: return
        if (elementType === anyType || elementType === errorType) return
        if (elementType is Type.TypeParam) return
        // B231: nested array-of-array literals — `[[[[[42]]]]]` vs `string[][][][][]`
        // recurses each array-literal element against the inner Array type, bottoming
        // out at the primitive per-element TS2322 (`42` vs string).
        if (elementType is Type.Reference && elementType.target.symbol?.name == "Array") {
            for (elem in arrLit.elements) {
                if (elem is ArrayLiteralExpression) {
                    checkArrayLiteralElementsAgainstType(elem, elementType, source, fileName, literalElementsOnly)
                }
            }
            return
        }
        if (!isSimpleCheckableType(elementType)) {
            // For object element types, fall through to existing object-element TS2353 path
            if (elementType is Type.Object) {
                resolveStructuredTypeMembers(elementType)
                // B109: call-signature element type (a function type, e.g.
                // `{ (): number; (i: number): number; }[]`). Check each
                // function/arrow element's inferred type against it — the
                // existing object-element path bails because such a type has
                // no properties. `contextualTyping33`.
                if (elementType.properties.isNullOrEmpty() &&
                    !elementType.callSignatures.isNullOrEmpty()) {
                    val displayTarget = typeToString(elementType)
                    for (elem in arrLit.elements) {
                        if (elem !is FunctionExpression && elem !is ArrowFunction) continue
                        val elemType = getTypeOfExpression(elem)
                        if (elemType !is Type.Object || elemType.callSignatures.isNullOrEmpty()) continue
                        if (!checkTypeRelatedTo(elemType, elementType, assignableRelation)) {
                            val chain = getFunctionMismatchElaboration(elemType, elementType)
                            val start = elem.pos
                            // For a function expression, TypeScript squiggles the
                            // `function` keyword; for an arrow, the whole expression.
                            val length = if (elem is FunctionExpression) 8
                                else (expressionTrueEnd(elem) - start).coerceAtLeast(1)
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Type '${typeToString(elemType)}' is not assignable to type '$displayTarget'.",
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                                messageChain = chain,
                            ))
                        }
                    }
                    return
                }
                if (elementType.properties.isNullOrEmpty()) return
                val display = typeToString(elementType)
                for (elem in arrLit.elements) {
                    if (elem is ObjectLiteralExpression) {
                        val elemType = getTypeOfExpression(elem)
                        if (elemType is Type.Object && canUseTypeEngine(elemType, elementType)) {
                            checkExcessProperties(elem, elemType, elementType, display, source, fileName)
                        }
                    }
                }
            }
            return
        }
        // Primitive element type — TS2322 per element
        for (elem in arrLit.elements) {
            if (elem is SpreadElement) continue
            // B180: the var-decl caller covers only LITERAL elements — call-expression
            // elements (`[myVar.voidFn()]`) are already emitted by the pre-existing
            // var-decl element walker; without this gate they double-emit
            // (arraySigChecking).
            if (literalElementsOnly &&
                elem !is NumericLiteralNode && elem !is StringLiteralNode &&
                elem !is BigIntLiteralNode && elem !is PrefixUnaryExpression &&
                !(elem is Identifier && elem.text in setOf("true", "false", "null", "undefined"))
            ) continue
            // Round 471: a literal element keeps its literal type against a
            // literal-containing element target (tsc contextual typing — a correct
            // literal element passes, a wrong one displays as its literal `"q"`).
            val elemType = if (propTypeContainsLiteral(elementType))
                literalTypeOfExpression(elem, isArrayLikeReference(elementType))
                    ?: getTypeOfExpression(elem)
            else getTypeOfExpression(elem)
            if (elemType === anyType || elemType === errorType) continue
            if (!checkTypeRelatedTo(elemType, elementType, assignableRelation)) {
                val displaySource = typeToString(elemType)
                val displayTarget = typeToString(elementType)
                val start = elem.pos
                val length = expressionTrueEnd(elem) - start
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    /**
     * B407: per-element TS2322 for an array-literal init assigned to a TUPLE target
     * (`const a: [number] = ['x']`). tsc contextually types array-literal elements
     * against the tuple's positional slots; we check element[i] against
     * tupleElementTypes[i] when both are simple/concrete. FP-safe: only fires on a
     * genuine concrete-vs-concrete mismatch (matching arity slot), skipping spreads,
     * any/error/TypeParam slots and non-simple types. Excess/short elements (arity)
     * are deliberately NOT reported here (separate diagnostic, not exercised).
     */
    /**
     * intersectionsAndOptionalProperties (#38348): true when an array-literal initializer
     * would conform (under contextual tuple typing) to an intersection of array-like members
     * (`number[] & [number, ...number[]]`). We don't contextually type array literals as
     * tuples, so `[1]` widens to `number[]` and FP-fails the tuple constituent — this gate
     * suppresses that coarse TS2322. FP-safe: requires BOTH an ArrayType and a TupleType
     * member, every member to be array-like, every element to fit each ArrayType element type,
     * and the element count + fixed slots to satisfy every TupleType (so a genuine
     * count/element mismatch like `number[] & [number, number] = [1]` is NOT suppressed).
     */
    private fun arrayLiteralFitsArrayTupleIntersection(
        arrLit: ArrayLiteralExpression, ann: IntersectionType
    ): Boolean {
        val arrays = ann.types.filterIsInstance<ArrayType>()
        val tuples = ann.types.filterIsInstance<TupleType>()
        if (arrays.isEmpty() || tuples.isEmpty()) return false
        if (arrays.size + tuples.size != ann.types.size) return false // a non-array-like member
        if (arrLit.elements.any { it is SpreadElement || it is OmittedExpression }) return false
        val elemTypes = arrLit.elements.map { getTypeOfExpression(it) }
        if (elemTypes.any { it === errorType }) return false
        // every element fits every ArrayType element type
        for (a in arrays) {
            val et = getTypeFromTypeNode(a.elementType)
            if (et === anyType || et === errorType) continue
            for (e in elemTypes) {
                if (e === anyType) continue
                if (!checkTypeRelatedTo(e, et, assignableRelation)) return false
            }
        }
        // each TupleType: required length met, no overflow without a rest, fixed slots fit
        for (t in tuples) {
            val required = t.elements.takeWhile { it !is RestType && it !is OptionalType }.size
            if (arrLit.elements.size < required) return false
            val hasRest = t.elements.any { it is RestType }
            if (!hasRest && arrLit.elements.size > t.elements.size) return false
            for ((i, e) in elemTypes.withIndex()) {
                val slotNode = t.elements.getOrNull(i) ?: continue
                if (slotNode is RestType || slotNode is OptionalType) continue
                val sn = if (slotNode is NamedTupleMember) slotNode.type else slotNode
                val slot = getTypeFromTypeNode(sn)
                if (slot === anyType || slot === errorType || e === anyType) continue
                if (!checkTypeRelatedTo(e, slot, assignableRelation)) return false
            }
        }
        return true
    }

    /**
     * Round 446: does array literal [arr] (no spread) satisfy a VARIADIC-TUPLE member of
     * the target type NODE [targetNode] — a tuple, or a union/alias containing one?
     *
     * The canonical shape is tsc's `DiagnosticOrDiagnosticAndArguments = DiagnosticMessage
     * | DiagnosticAndArguments` where `DiagnosticAndArguments = [message: DiagnosticMessage,
     * ...args: (string | number)[]]`. The relation engine SKIPS array→tuple (Checker.kt
     * ~64488), and `getTupleType` COLLAPSES the rest slot (losing minLength/rest-element
     * separation, per the CLAUDE.md gotcha), so a resolved-Type comparison cannot decide
     * this. Match against the AST TupleType instead: verify every array element is
     * assignable to its tuple slot. Suppression-only — returns true ONLY on a confident
     * match (permissive on unresolvable/complex slots, matching
     * [checkArrayLiteralElementsAgainstTuple]'s skip-non-simple-slot behavior), so a
     * genuine arity/type mismatch keeps failing through the normal path.
     */
    private fun arrayLiteralSatisfiesTupleTarget(
        arr: ArrayLiteralExpression, targetNode: TypeNode?, locals: SymbolTable?,
    ): Boolean {
        if (arr.elements.any { it is SpreadElement }) return false
        val tuple = findVariadicTupleInTarget(targetNode, locals) ?: return false
        return arrayLiteralMatchesVariadicTuple(arr, tuple, locals)
    }

    /** Walk a target type NODE (tuple / union / parenthesized / alias reference) to the
     *  first TupleType it contains. Depth-capped; alias bodies resolved AST-side. */
    private fun findVariadicTupleInTarget(node: TypeNode?, locals: SymbolTable?, depth: Int = 0): TupleType? {
        if (node == null || depth > 5) return null
        return when (node) {
            is TupleType -> node
            is ParenthesizedType -> findVariadicTupleInTarget(node.type, locals, depth + 1)
            is UnionType -> node.types.firstNotNullOfOrNull { findVariadicTupleInTarget(it, locals, depth + 1) }
            is TypeReference -> {
                if (!node.typeArguments.isNullOrEmpty()) return null
                val nameNode = node.typeName as? Identifier ?: return null
                val n = nameNode.text
                // An IMPORTED alias's file-local symbol carries only the ImportSpecifier —
                // fall through to the node-keyed per-file resolution, which follows the
                // import to the declaring file's TypeAliasDeclaration (mirrors
                // aliasUnionContainsNullishKeyword; INV.3(d): was the merged globals).
                val alias = (locals?.get(n)?.declarations?.firstOrNull { it is TypeAliasDeclaration }
                    ?: lookupPerFileForNode(nameNode, n)?.declarations?.firstOrNull { it is TypeAliasDeclaration })
                    as? TypeAliasDeclaration ?: return null
                if (!alias.typeParameters.isNullOrEmpty()) return null
                findVariadicTupleInTarget(alias.type, locals, depth + 1)
            }
            else -> null
        }
    }

    /** Element type NODE of an array/ReadonlyArray/alias-of-array type node (for a tuple
     *  rest slot `...args: T[]`). Null when it isn't array-shaped or can't be resolved. */
    private fun arrayElementTypeNode(node: TypeNode, locals: SymbolTable?, depth: Int = 0): TypeNode? {
        if (depth > 5) return null
        return when (node) {
            is ArrayType -> node.elementType
            is ParenthesizedType -> arrayElementTypeNode(node.type, locals, depth + 1)
            is TypeReference -> {
                val nameNode = node.typeName as? Identifier ?: return null
                val n = nameNode.text
                if (n == "Array" || n == "ReadonlyArray") node.typeArguments?.singleOrNull()
                else {
                    if (!node.typeArguments.isNullOrEmpty()) return null
                    // INV.3(d): node-keyed (was the merged globals) — see above.
                    val alias = (locals?.get(n)?.declarations?.firstOrNull { it is TypeAliasDeclaration }
                        ?: lookupPerFileForNode(nameNode, n)?.declarations?.firstOrNull { it is TypeAliasDeclaration })
                        as? TypeAliasDeclaration ?: return null
                    if (!alias.typeParameters.isNullOrEmpty()) return null
                    arrayElementTypeNode(alias.type, locals, depth + 1)
                }
            }
            else -> null
        }
    }

    /** Match array literal [arr] against a single-rest variadic tuple. Parses the tuple
     *  into a fixed prefix / one optional rest element / fixed suffix (bailing on >1 rest
     *  or optional/labelled-optional members) and verifies each array element against its
     *  slot. Permissive on unresolvable slots (returns true), so it only ever SUPPRESSES a
     *  confident match. */
    private fun arrayLiteralMatchesVariadicTuple(
        arr: ArrayLiteralExpression, tuple: TupleType, locals: SymbolTable?,
    ): Boolean {
        val before = mutableListOf<TypeNode>()
        val after = mutableListOf<TypeNode>()
        var restElemNode: TypeNode? = null
        var hasRest = false
        for (el in tuple.elements) {
            val isRest: Boolean
            val isOptional: Boolean
            val typeNode: TypeNode
            when (el) {
                is NamedTupleMember -> { isRest = el.dotDotDotToken; isOptional = el.questionToken; typeNode = el.type }
                is RestType -> { isRest = true; isOptional = false; typeNode = el.type }
                is OptionalType -> { isRest = false; isOptional = true; typeNode = el.type }
                else -> { isRest = false; isOptional = false; typeNode = el }
            }
            when {
                isRest -> {
                    if (hasRest) return false // >1 rest — bail
                    hasRest = true
                    restElemNode = arrayElementTypeNode(typeNode, locals) // may be null → permissive rest
                }
                isOptional -> return false // optional fixed element — bail (rare for these shapes)
                else -> if (!hasRest) before.add(typeNode) else after.add(typeNode)
            }
        }
        val n = arr.elements.size
        val minLen = before.size + after.size
        if (n < minLen) return false // too few — a real mismatch, don't suppress
        if (!hasRest && n != minLen) return false // no rest and wrong arity
        for (i in before.indices) if (!elementAssignableToSlot(arr.elements[i], before[i], locals)) return false
        for (j in after.indices) if (!elementAssignableToSlot(arr.elements[n - after.size + j], after[j], locals)) return false
        if (hasRest && restElemNode != null) {
            for (i in before.size until (n - after.size)) {
                if (!elementAssignableToSlot(arr.elements[i], restElemNode, locals)) return false
            }
        }
        return true
    }

    /** Is array-element expression [elem] assignable to tuple-slot type node [slotNode]?
     *  Permissive (true) when either side is any/error/unresolvable or the engine can't
     *  decide — the caller only uses this to SUPPRESS a confident match. */
    private fun elementAssignableToSlot(elem: Expression, slotNode: TypeNode, locals: SymbolTable?): Boolean {
        if (elem is SpreadElement) return false
        val slotType = getTypeFromTypeNodeSafe(slotNode) ?: return true
        if (slotType === anyType || slotType === errorType || slotType is Type.TypeParam) return true
        var elemType = getTypeOfExpression(elem)
        if (elemType === anyType || elemType === errorType) return true
        // Round 461: a guard-narrowed reference element — `isString(x) ? [x] : x[0]`
        // narrows x to string inside the true arm, so the element must check its
        // NARROWED type against the slot (tsc builder.ts getNewEmitSignature's
        // `[oldEmitSignature]` vs `[signature: string]`). Monotone-safe: narrowing
        // only refines, and this helper's verdict only SUPPRESSES a confident match.
        if (elem is Identifier || elem is PropertyAccessExpression) {
            val narrowed = getNarrowedTypeForReference(elemType, elem)
            if (narrowed !== elemType && narrowed !== neverType) elemType = narrowed
        }
        if (!canUseTypeEngine(elemType, slotType)) return true
        return checkTypeRelatedTo(elemType, slotType, assignableRelation)
    }

    private fun checkArrayLiteralElementsAgainstTuple(
        arrLit: ArrayLiteralExpression, tupleType: Type.Object, source: String, fileName: String,
    ) {
        val slots = tupleType.tupleElementTypes ?: return
        for ((i, elem) in arrLit.elements.withIndex()) {
            if (elem is SpreadElement) return
            val slot = slots.getOrNull(i) ?: continue
            if (slot === anyType || slot === errorType || slot is Type.TypeParam) continue
            if (!isSimpleCheckableType(slot)) continue
            val elemType = getTypeOfExpression(elem)
            if (elemType === anyType || elemType === errorType) continue
            if (!isSimpleCheckableType(elemType)) {
                // didYouMean: a CALLABLE element (e.g. `getNum: () => number`) whose call
                // return satisfies a simple slot → TS2322 + TS6212 "did you mean call".
                if (elemType is Type.Object && elem !is ArrowFunction && elem !is FunctionExpression) {
                    val callSigs = getCallSignaturesOfType(elemType)
                    val constructSigs = getConstructSignaturesOfType(elemType)
                    if (callSigs.isNotEmpty() && constructSigs.isEmpty() &&
                        !checkTypeRelatedTo(elemType, slot, assignableRelation) &&
                        callSigs.any { sig -> sig.resolvedReturnType?.let { checkTypeRelatedTo(it, slot, assignableRelation) } == true }
                    ) {
                        val start = elem.pos
                        val length = (expressionTrueEnd(elem) - start).coerceAtLeast(1)
                        if (length > 0) {
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Type '${typeToString(elemType)}' is not assignable to type '${typeToString(slot)}'.",
                                category = DiagnosticCategory.Error, code = 2322,
                                fileName = fileName, line = line, character = character,
                                start = start, length = length,
                                relatedInformation = listOf(Diagnostic(
                                    message = "Did you mean to call this expression?",
                                    category = DiagnosticCategory.Message, code = 6212,
                                    fileName = fileName, line = line, character = character,
                                    start = start, length = length,
                                )),
                            ))
                        }
                    }
                }
                continue
            }
            if (!checkTypeRelatedTo(elemType, slot, assignableRelation)) {
                val displaySource = typeToString(getWidenedLiteralType(elemType))
                val displayTarget = typeToString(slot)
                val start = elem.pos
                val length = expressionTrueEnd(elem) - start
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type '$displaySource' is not assignable to type '$displayTarget'.",
                    category = DiagnosticCategory.Error,
                    code = 2322, fileName = fileName, line = line, character = character,
                    start = start, length = length,
                ))
            }
        }
    }

    /**
     * 16.0: TS2353 check for each object literal element in an array literal
     * whose target is an array type with a resolvable element type. Also emits
     * TS2322 for primitive elements that aren't assignable to an Object element type.
     */
    /** For an object-literal value, pick the single non-Array object-like constituent of a
     *  (possibly union) target member type — e.g. `Bar | Bar[]` → `Bar`. Returns null when
     *  ambiguous / no object constituent / the type is itself an Array. */
    /** Round 464b: from a union's ≥2 object members, the SINGLE one whose members
     *  cover every property NAME of [ol] (tsc's contextual-type distribution picks
     *  the matching member). Spread/computed properties or an ambiguous/empty match
     *  → null (no context — conservative). */
    private fun selectUnionMemberByObjLitKeys(u: Type.Union, ol: ObjectLiteralExpression): Type.Object? {
        val names = ol.properties.map { p ->
            when (p) {
                is ShorthandPropertyAssignment -> p.name.text
                is PropertyAssignment -> getPropertyKeyName(p.name) ?: return null
                else -> return null
            }
        }
        if (names.isEmpty()) return null
        val objs = u.types.mapNotNull { it as? Type.Object }
            .filter { !(it is Type.Reference && it.target.symbol?.name == "Array") }
        if (objs.size < 2) return null
        val matching = objs.filter { o ->
            resolveStructuredTypeMembers(o)
            names.all { n -> getPropertyOfType(o, n) != null }
        }
        return matching.singleOrNull()
    }

    /**
     * Round 472: from a union's ≥2 object members, the SINGLE one whose DISCRIMINANT
     * property matches the object literal's enum-member / string-literal value —
     * `{ kind: InvocationKind.Call, node }` vs the CallInvocation | TypeArgsInvocation |
     * ContextualInvocation union selects CallInvocation via the round-411 canonical
     * `symId#member` key space. No usable discriminant / ambiguous → null (conservative).
     *
     * (REL.1)(c) step 5b, round 753 — the LAST of the six readers to go type-first.
     * **The original docstring's premise, "enum-member types resolve to `any`, so the
     * resolved property type cannot decide this; the DECLARED annotation can", stopped
     * being true at (REL.1)(a)** and is corrected here: [discriminantKeysOfMember] reads
     * the resolved property TYPE first and falls back to the annotation walk.
     *
     * MEASURED over the whole compiler profile before the flip: **292 sightings, 292
     * AGREE, 0 mismatched, 0 blind, 0 gained** (instrument falsified in the same run;
     * [canonicalEnumSymbol] memo-bypass check 342 mints / 0 divergences).
     *
     * **UNLIKE the five earlier sites, the AST fallback is still LOAD-BEARING here, and
     * that was measured rather than assumed.** This is the site that consumes the
     * round-475 `TypeQuery` arm: for `k: typeof CloseTag` over a top-level
     * `const CloseTag = "close"`, the resolved property type is the WIDENED `string`
     * (no key) while [enumMemberKeysOfTypeNode] still yields `lit:s:close`. The probe
     * reports that shape as TYPEBLIND with a real decision difference
     * (`ast=true type=false`), so cutting the fallback would silently stop selecting the
     * constituent. It is dead on the compiler profile only because that profile has no
     * such shape — which is why the profile alone could not have settled it.
     */
    private fun selectUnionMemberByObjLitDiscriminant(u: Type.Union, ol: ObjectLiteralExpression): Type.Object? {
        val objs = u.types.mapNotNull { it as? Type.Object }
            .filter { !(it is Type.Reference && it.target.symbol?.name == "Array") }
        if (objs.size < 2) return null
        var candidates: List<Type.Object> = objs
        var usedDiscriminant = false
        for (p in ol.properties) {
            val pa = p as? PropertyAssignment ?: continue
            val name = getPropertyKeyName(pa.name) ?: continue
            val valueKey = enumMemberKeyOfExpr(pa.initializer)
                ?: literalTypeOfExpression(pa.initializer)?.let { literalDiscriminantKeyOfType(it) }
                // Round 475: a bare-Identifier const-string value (`eventName:
                // CloseFileWatcherEvent`) — the objlit-selection sibling of the round-473
                // `case <constIdent>:` rule.
                ?: constStringCaseLiteralType(pa.initializer)?.let { literalDiscriminantKeyOfType(it) }
                ?: continue
            val filtered = candidates.filter { m ->
                val keys = discriminantKeysOfMember(m, name)
                keys != null && valueKey in keys
            }
            // A property whose key matches NO member's declared keys is not a usable
            // discriminant here (could be a non-discriminant enum-valued member) — skip
            // it rather than emptying the candidate set.
            if (filtered.isEmpty()) continue
            usedDiscriminant = true
            candidates = filtered
        }
        return if (usedDiscriminant) candidates.singleOrNull() else null
    }

    private fun selectObjectConstituentForObjectLiteral(t: Type): Type.Object? {
        fun isArrayRef(x: Type) = x is Type.Reference && x.target.symbol?.name == "Array"
        if (isArrayRef(t)) return null
        if (t is Type.Object) return t
        if (t is Type.Union) {
            val objs = t.types.filter { it is Type.Object && !isArrayRef(it) }
            return objs.singleOrNull() as? Type.Object
        }
        return null
    }

    /** Recursively check an object literal's property VALUES against a target object type,
     *  drilling through union members (object-literal value → object constituent) and nested
     *  object literals. Emits TS2322 at the innermost mismatching property key for a
     *  primitive-vs-primitive mismatch. Gated to simple-checkable leaves → FP-safe. */
    /** Unwrap parenthesized / comma-expression-RHS / assignment-RHS wrappers to reach the
     *  underlying object literal — e.g. `(void 0, {…})` / `q = {…}` / `({…})` → `{…}`. */
    private fun unwrapToObjLitValue(expr: Expression): Expression {
        var e = expr
        while (true) {
            e = when {
                e is ParenthesizedExpression -> e.expression
                e is BinaryExpression && e.operator == SyntaxKind.Comma -> e.right
                e is BinaryExpression && e.operator == SyntaxKind.Equals -> e.right
                else -> return e
            }
        }
    }

    /** Round 435e: a BARE `new C()` (no explicit type args, no ctor args) assigned
     *  where the target contains a Reference to the SAME class/interface C is
     *  contextually instantiated from the target — tsc infers C's type arguments
     *  from the assignment context, so `map = new WeakMap()` against
     *  `WeakMap<Node, readonly Node[] | undefined> | undefined` is legal (tsc's own
     *  nodeChildren.ts). Suppression-only: gated to the same declared symbol name,
     *  so a mismatched container class still fails. */
    private fun bareNewMatchesTarget(rhs: Expression?, target: Type): Boolean {
        val ne = rhs as? NewExpression ?: return false
        if (!ne.typeArguments.isNullOrEmpty() || !ne.arguments.isNullOrEmpty()) return false
        val calleeName = (ne.expression as? Identifier)?.text ?: return false
        fun matches(t: Type): Boolean = when (t) {
            is Type.Union -> t.types.any { matches(it) }
            is Type.Reference -> t.target.symbol?.name == calleeName
            is Type.Interface -> t.symbol?.name == calleeName
            else -> false
        }
        return matches(target)
    }

    /** Round 435: run [block] with [freshObjLitRange] set when [expr] unwraps to an
     *  ObjectLiteralExpression — the tsc-freshness gate for propertiesRelatedTo's
     *  literal retry. A non-literal source (identifier/call/…) runs [block] unchanged,
     *  so a WIDENED reference (`const x = { kind: "a" }; const y: T = x`) keeps
     *  failing exactly as tsc does. */
    private inline fun <T> withFreshObjLitSource(expr: Expression?, block: () -> T): T {
        val lit = expr?.let { unwrapToObjLitValue(it) } as? ObjectLiteralExpression
            ?: return block()
        val saved = freshObjLitRange
        freshObjLitRange = lit.pos..lit.end
        return try { block() } finally { freshObjLitRange = saved }
    }

    private fun checkNestedObjLitPropTypes(
        objLit: ObjectLiteralExpression, targetType: Type, source: String, fileName: String,
        viaUnion: Boolean = false,
        arrayPropsOnly: Boolean = false,
        // circularResolvedSignature: override for the TS6500 enclosing-type display at
        // THIS (top) level only — recursive calls leave it null. Renders the alias's
        // definition (`Readonly<{…}>`) instead of its name (`Data`) for an
        // instantiation-derived contextual target.
        enclosingDisplayOverride: String? = null,
    ): Boolean {
        var emitted = false
        // Accept a Type.Object OR an Intersection target. Per-property target types are
        // resolved via getTargetPropertyType (which flattens intersections), so a nested
        // fresh-object-literal mismatch against a `B & C`-style target descends to the
        // deepest leaf (excessPropertyChecksWithNestedIntersections `let e: D = {a:{x:2}}`).
        val targetObj = targetType as? Type.Object
        if (targetObj == null && targetType !is Type.Intersection) return false
        targetObj?.let { resolveStructuredTypeMembers(it) }
        fun targetMemberSym(name: String): Symbol? = targetObj?.members?.get(name)
            ?: (targetType as? Type.Intersection)?.types?.firstNotNullOfOrNull { c ->
                (c as? Type.Object)?.let { resolveStructuredTypeMembers(it); it.members?.get(name) }
            }
        val targetDisplay = enclosingDisplayOverride ?: typeToString(targetType)
        for (prop in objLit.properties) {
            if (prop !is PropertyAssignment) continue
            val value = unwrapToObjLitValue(prop.initializer)
            val nameNode = prop.name
            val propName = when (nameNode) {
                is Identifier -> nameNode.text
                is StringLiteralNode -> nameNode.text
                is NumericLiteralNode -> nameNode.text
                else -> continue
            }
            val tgtMemberType = getTargetPropertyType(targetType, propName) ?: continue
            if (tgtMemberType === anyType || tgtMemberType === errorType) continue
            // B395: under arrayPropsOnly (direct object-literal init) skip only SIMPLE values
            // (those are owned by emitPerPropertyMismatches); object-literal values are now
            // descended for the nested missing-required-property check (TS2741/2739/2740).
            if (arrayPropsOnly && value !is ArrayLiteralExpression && value !is ObjectLiteralExpression) continue
            if (value is ObjectLiteralExpression) {
                val tgtObj = selectObjectConstituentForObjectLiteral(tgtMemberType) ?: continue
                val childViaUnion = viaUnion || tgtMemberType is Type.Union
                if (checkNestedObjLitPropTypes(value, tgtObj, source, fileName, childViaUnion, arrayPropsOnly)) emitted = true
                // B395 (deeplyNestedAssignabilityIssue): a nested object-literal value missing
                // a required property of its (non-union) target → TS2741/2739/2740 squiggling
                // the property KEY, with TS2728 ('X is declared here') + TS6500 ('the expected
                // type comes from property <key>…'). Only on a direct (non-union) path; the
                // union-disambiguated case is owned by the union-excess walker.
                if (!childViaUnion) {
                    val keyLen = when (nameNode) {
                        is StringLiteralNode -> (nameNode.rawText?.length ?: nameNode.text.length) + 2
                        else -> propName.length
                    }
                    if (emitNestedMissingRequiredProps(value, tgtObj, source, fileName, nameNode.pos, keyLen, propName, targetObj)) emitted = true
                }
            } else if (value is ArrayLiteralExpression) {
                // B231: recurse into ARRAY-literal property values — `b: [ {…}, … ]` vs
                // `B[]` checks each object-literal element against the array ELEMENT type,
                // so deep literal chains (a.b[0].c.d[0]…) keep being walked. Each element
                // also gets the missing-REQUIRED-property check (TS2741/TS2739/TS2740) —
                // the per-property loop alone can't see ABSENT props (the deep `{}` vs H
                // shape). Gated to a non-union, concrete Array element target.
                val elemTarget = (tgtMemberType as? Type.Reference)
                    ?.takeIf { it.target.symbol?.name == "Array" }
                    ?.resolvedTypeArguments?.firstOrNull()
                if (elemTarget != null && elemTarget !== anyType && elemTarget !== errorType &&
                    elemTarget !is Type.Union && elemTarget !is Type.TypeParam) {
                    val elemObj = selectObjectConstituentForObjectLiteral(elemTarget)
                    if (elemObj != null) {
                        for (elem in value.elements) {
                            if (elem !is ObjectLiteralExpression) continue
                            if (checkNestedObjLitPropTypes(elem, elemObj, source, fileName, viaUnion)) emitted = true
                            if (!viaUnion && emitNestedMissingRequiredProps(elem, elemObj, source, fileName)) emitted = true
                        }
                    }
                }
            } else {
                val valueType = getTypeOfExpression(value)
                if (valueType === anyType || valueType === errorType) continue
                // Nullish value vs a target member that doesn't accept it (strictNullChecks):
                // `children: null` vs optional `children?: IIntervalTreeNode[]`
                // (= `IIntervalTreeNode[] | undefined`). Emits at the key with the FULL
                // declared member-type display (+ ` | undefined` for an optional prop) and
                // a TS6500 "expected type comes from property X" related info.
                val valIsNull = valueType.flags.hasAny(TypeFlags.Null)
                val valIsUndef = valueType.flags.hasAny(TypeFlags.Undefined)
                if (strictNullChecks && (valIsNull || valIsUndef) &&
                    !tgtMemberType.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown) &&
                    !tgtMemberType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) {
                    val tgtSym = targetMemberSym(propName)
                    val isOptional = tgtSym != null && isOptionalProperty(tgtSym)
                    val accepted = (valIsNull && typeIncludesNull(tgtMemberType)) ||
                        (valIsUndef && (typeIncludesUndefined(tgtMemberType) || isOptional))
                    if (!accepted && tgtSym != null) {
                        var disp = typeToString(tgtMemberType)
                        if (isOptional && !typeIncludesUndefined(tgtMemberType)) disp = "$disp | undefined"
                        val keyPos2 = nameNode.pos
                        val keyLen2 = when (nameNode) {
                            is StringLiteralNode -> (nameNode.rawText?.length ?: nameNode.text.length) + 2
                            else -> propName.length
                        }
                        if (keyLen2 > 0) {
                            val (l2, c2) = getLineAndCharacterOfPosition(source, keyPos2)
                            val related = createPropertyDeclaredHereRelatedInfo(tgtSym)?.let { d ->
                                listOf(d.copy(
                                    message = "The expected type comes from property '$propName' which is declared here on type '$targetDisplay'",
                                    code = 6500,
                                ))
                            } ?: emptyList()
                            diagnostics.add(Diagnostic(
                                message = "Type '${typeToString(valueType)}' is not assignable to type '$disp'.",
                                category = DiagnosticCategory.Error, code = 2322,
                                fileName = fileName, line = l2, character = c2,
                                start = keyPos2, length = keyLen2,
                                relatedInformation = related,
                            ))
                            emitted = true
                        }
                    }
                    continue
                }
                // B482ext: require a SIMPLE source value (primitive/literal) — such a value
                // can never have deeper structure, so a flat per-property line is always
                // tsc-correct even against a non-simple target (e.g. `hi: true` vs `string[]`
                // → "Type 'boolean' is not assignable to type 'string[]'." at the key). A
                // non-simple source still needs the deeper-chain path → keep skipping it.
                if (!isSimpleCheckableType(valueType)) continue
                if (valueType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)) continue
                // Round 435 (tsc contextual literal types): a FRESH literal prop value keeps
                // its literal type when the target member contains literals — tsc's own
                // checker.ts IterationTypesResolver tables (`iterableCacheKey:
                // "iterationTypesOfAsyncIterable"` vs the two-literal union). Mirrors the
                // 17.70 return-path / B326 overload-arg rule.
                val effValueType = if (propTypeContainsLiteral(tgtMemberType))
                    literalTypeOfExpression(value) ?: valueType else valueType
                // An OPTIONAL target property `a?: T` accepts a `T | undefined` source when
                // exactOptionalPropertyTypes is off (widenOptionalTargetPropType, source-nullish
                // gated) — e.g. `sourceIndex: hasSource ? n : undefined` (`number | undefined`)
                // vs `sourceIndex?: number` (sourcemap.ts captureMapping). The DISPLAY below
                // keeps the bare `tgtMemberType`; only the relation widens.
                val tgtForRel = targetMemberSym(propName)?.let {
                    widenOptionalTargetPropType(tgtMemberType, it, effValueType)
                } ?: tgtMemberType
                if (checkTypeRelatedTo(effValueType, tgtForRel, assignableRelation)) continue
                val keyPos = nameNode.pos
                val keyLen = when (nameNode) {
                    is StringLiteralNode -> (nameNode.rawText?.length ?: nameNode.text.length) + 2
                    else -> propName.length
                }
                if (keyLen <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, keyPos)
                // TS6500 only on a DIRECT-property path (not when a union member was
                // selected — matches TS, which omits it for union-disambiguated leaves).
                val leafRelated = if (!viaUnion) {
                    targetMemberSym(propName)?.let { createPropertyDeclaredHereRelatedInfo(it) }?.let { d ->
                        listOf(d.copy(
                            message = "The expected type comes from property '$propName' which is declared here on type '$targetDisplay'",
                            code = 6500,
                        ))
                    } ?: emptyList()
                } else emptyList()
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(getWidenedLiteralType(valueType))}' is not assignable to type '${typeToString(getWidenedLiteralType(tgtMemberType))}'.",
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = keyPos,
                    length = keyLen,
                    relatedInformation = leafRelated,
                ))
                emitted = true
            }
        }
        return emitted
    }

    /** B231: missing-REQUIRED-property emission for a nested object-literal element of an
     *  array-literal property value (`h: [ {} ]` vs `H[]` → TS2741 "Property 'i' is missing
     *  in type '{}' but required in type 'H'." spanning the whole literal). Reuses
     *  [collectMissingProperties] (statics/prototype/optional-aware). */
    private fun emitNestedMissingRequiredProps(
        objLit: ObjectLiteralExpression, target: Type.Object, source: String, fileName: String,
        keyPos: Int? = null, keyLen: Int = 0,
        enclosingPropName: String? = null, enclosingTarget: Type.Object? = null,
    ): Boolean {
        if (objLit.properties.any { it is SpreadAssignment }) return false
        val srcType = getTypeOfObjectLiteral(objLit)
        if (srcType !is Type.Object) return false
        val missing = collectMissingProperties(srcType, target)
        if (missing.isEmpty()) return false
        val displaySource = typeToString(srcType)
        val displayTarget = typeToString(target)
        // B395: squiggle the property KEY when provided (object-literal value missing props
        // in a var-decl context: `thing: {}` → squiggle `thing`); otherwise the whole value
        // object literal (the B231 array-element case).
        val (start, length) = if (keyPos != null && keyLen > 0) {
            keyPos to keyLen
        } else {
            val end = if (objLit.closeBracePos > objLit.pos) objLit.closeBracePos + 1 else objLit.end
            objLit.pos to (end - objLit.pos).coerceAtLeast(1)
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val message = if (missing.size == 1) {
            "Property '${missing[0]}' is missing in type '$displaySource' but required in type '$displayTarget'."
        } else {
            formatTs2740Message(displaySource, displayTarget, missing)
        }
        // TS2728 "'i' is declared here." (single-missing) + B395 TS6500 "the expected type
        // comes from property '<enclosingProp>'…" when the enclosing-property context is given.
        val related = buildList {
            if (missing.size == 1) {
                target.members?.get(missing[0])?.let { createPropertyDeclaredHereRelatedInfo(it) }?.let { add(it) }
            }
            if (enclosingPropName != null && enclosingTarget != null) {
                enclosingTarget.members?.get(enclosingPropName)?.let { createPropertyDeclaredHereRelatedInfo(it) }?.let { d ->
                    add(d.copy(
                        message = "The expected type comes from property '$enclosingPropName' which is declared here on type '${typeToString(enclosingTarget)}'",
                        code = 6500,
                    ))
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = if (missing.size == 1) 2741 else if (missing.size <= 4) 2739 else 2740,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = related,
        ))
        return true
    }

    /**
     * B415: resolve the ELEMENT type of an array-LIKE target. Handles three shapes
     * the plain `Type.Reference`-to-Array entry could not reach:
     *  - a `Type.Reference` to Array directly (`Style[]`)             → its type arg;
     *  - an interface that `extends Array<X>` (`interface SA extends Array<Style>`)
     *    → the Array base's type arg (so a named array-interface descends);
     *  - a `Type.Union` with EXACTLY ONE array-like member (the other members being
     *    non-array objects, e.g. `Style = StyleBase | StyleArray`) → that member's
     *    element type.
     * Returns null when not array-like — the recursive excess-property descent stops.
     */
    private fun arrayElementTypeForExcess(t: Type): Type? = when {
        t is Type.Reference && t.target.symbol?.name == "Array" ->
            t.resolvedTypeArguments?.firstOrNull()
        t is Type.Interface -> {
            resolveBaseTypesLazy(t)
            // The base may be a `Type.Reference(Array,[X])` OR a bare `Type.Interface`
            // named "Array" — the latter when `baseTypes` dropped the instantiation arg
            // (`interface SA extends Array<Style>` resolves the base to raw `Array<T>`).
            // For the bare case recover X from the heritage AST.
            t.baseTypes?.firstNotNullOfOrNull { b ->
                if (b is Type.Reference && b.target.symbol?.name == "Array")
                    b.resolvedTypeArguments?.firstOrNull() else null
            } ?: run {
                if (t.baseTypes?.any { (it as? Type.Object)?.symbol?.name == "Array" } == true)
                    arrayBaseElementTypeFromHeritage(t) else null
            }
        }
        t is Type.Union -> {
            val elems = t.types.mapNotNull { arrayElementTypeForExcess(it) }
            if (elems.size == 1) elems[0] else null
        }
        else -> null
    }

    /** B415: recover the `Array<X>` element type from an interface's heritage AST when
     *  the resolved base lost the instantiation (`extends Array<Style>` → bare `Array<T>`
     *  in `baseTypes`). Reads the `extends Array<…>` type-argument node directly. */
    private fun arrayBaseElementTypeFromHeritage(iface: Type.Interface): Type? {
        val symbol = iface.symbol ?: return null
        for (d in symbol.declarations) {
            val clauses = when (d) {
                is InterfaceDeclaration -> d.heritageClauses
                is ClassDeclaration -> d.heritageClauses
                else -> null
            } ?: continue
            for (clause in clauses) {
                if (clause.token == SyntaxKind.ImplementsKeyword) continue
                for (ewa in clause.types) {
                    if ((ewa.expression as? Identifier)?.text != "Array") continue
                    val arg = ewa.typeArguments?.firstOrNull() ?: continue
                    // Resolve a named arg (`Array<Style>`) via its SYMBOL rather than
                    // getTypeFromTypeNode — for a self-recursive alias (`Style = … |
                    // Array<Style>`) the node-level cache holds the errorType sentinel
                    // captured while the alias was mid-resolution, so the node path
                    // returns 'any'. The symbol path reads the now-complete declaredTypes.
                    val argName = (arg as? TypeReference)?.typeName as? Identifier
                    if (argName != null) {
                        val sym = currentFileLocals?.get(argName.text) ?: globals[argName.text]
                        if (sym != null) return getDeclaredTypeOfSymbol(sym)
                    }
                    return getTypeFromTypeNode(arg)
                }
            }
        }
        return null
    }

    /**
     * B415: the single non-array object "bag" of a target type for excess-property
     * checking. For a union like `StyleBase | StyleArray` (one object member + one
     * array member), returns `StyleBase`; for a plain object type returns it directly.
     * Returns null when there is not exactly one non-array object member (ambiguous /
     * not applicable) so the excess check is skipped (FP-safe).
     */
    private fun objectMemberForExcess(t: Type): Type.Object? = when {
        t is Type.Reference && t.target.symbol?.name == "Array" -> null
        t is Type.Union -> {
            val objs = t.types.filter { it is Type.Object && arrayElementTypeForExcess(it) == null }
            if (objs.size == 1) objs[0] as Type.Object else null
        }
        t is Type.Object -> t
        else -> null
    }

    private fun checkArrayLiteralElementExcessProps(
        init: Expression,
        targetType: Type,
        source: String,
        fileName: String,
        // B415: alias display for the contextual element type (e.g. "Style"). Threaded
        // through the recursion when the leaf's contextual type is a named union alias
        // whose own display would unfold (`StyleBase | StyleArray`) — tsc shows "Style".
        displayName: String? = null,
    ) {
        if (init !is ArrayLiteralExpression) return
        // B415: descend array-LIKE targets (Reference-to-Array, interface-extends-Array,
        // or a union with a single array-like member) rather than only direct Array refs.
        val elementType = arrayElementTypeForExcess(targetType) ?: return
        // B415: the element type is itself a UNION (e.g. `Style = StyleBase | StyleArray`,
        // reached through `interface StyleArray extends Array<Style>`). Run the per-element
        // excess / nested checks against the union's single object member, recurse array
        // elements through the union's array member, and display the threaded alias name
        // (`Style`) which a bare union would otherwise unfold. Self-contained so the plain
        // Type.Object / primitive paths below stay untouched.
        if (elementType is Type.Union) {
            val bag = objectMemberForExcess(elementType)
            val nestedArrayLike = arrayElementTypeForExcess(elementType) != null
            if (bag == null && !nestedArrayLike) return
            val disp = displayName ?: typeToString(elementType)
            if (bag != null) resolveStructuredTypeMembers(bag)
            for (elem in init.elements) {
                when (elem) {
                    is ObjectLiteralExpression -> if (bag != null) {
                        val elemType = getTypeOfExpression(elem)
                        if (elemType is Type.Object && canUseTypeEngine(elemType, bag)) {
                            checkExcessProperties(elem, elemType, bag, disp, source, fileName)
                        }
                        checkNestedObjLitPropTypes(elem, bag, source, fileName)
                    }
                    is ArrayLiteralExpression -> if (nestedArrayLike) {
                        checkArrayLiteralElementExcessProps(elem, elementType, source, fileName, disp)
                    }
                    else -> {}
                }
            }
            return
        }
        if (elementType !is Type.Object) {
            // Primitive element type (e.g. `string[] = [voidFn()]`) — narrow void-call
            // element check. `void` call results can't satisfy any concrete primitive
            // element type. Skip if elementType is any/unknown/never/itself void.
            if (elementType is Type.Intrinsic &&
                !elementType.flags.hasAny(TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never or TypeFlags.Void)) {
                val elementDisplay = typeToString(elementType)
                for (elem in init.elements) {
                    if (elem !is CallExpression) continue
                    val callType = getReturnTypeOfCallExpression(elem)
                    if (!callType.flags.hasAny(TypeFlags.Void)) continue
                    val start = elem.pos
                    val length = expressionTrueEnd(elem) - start
                    if (length <= 0) continue
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type 'void' is not assignable to type '$elementDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            return
        }
        resolveStructuredTypeMembers(elementType)
        if (elementType.properties.isNullOrEmpty()) return
        val elementDisplay = typeToString(elementType)
        for (elem in init.elements) {
            if (elem is SpreadElement) continue
            when (elem) {
                is ObjectLiteralExpression -> {
                    val elemType = getTypeOfExpression(elem)
                    if (elemType is Type.Object && canUseTypeEngine(elemType, elementType)) {
                        checkExcessProperties(elem, elemType, elementType, elementDisplay, source, fileName)
                    }
                    // Round 96: nested per-property TYPE mismatch for an array-element
                    // object literal vs the element interface — including drilling through
                    // a union member (`bar: Bar | Bar[]`, value `{prop:100}` → pick Bar) and
                    // recursing into nested object literals. Emits TS2322 at the innermost
                    // mismatching property key (matches TS — no TS6500 for this nested case).
                    checkNestedObjLitPropTypes(elem, elementType, source, fileName)
                }
                is TypeAssertionExpression, is AsExpression -> {
                    // 17.81: Type-asserted element vs structured element-type — emit
                    // TS2741 when the asserted type is missing a required property of
                    // the target element. Cf. contextualTyping11_ts:
                    // `class foo { public bar: {id:number;}[] = [<foo>({})]; }` —
                    // the cast type `foo` lacks `id`, so element-level TS2741 fires.
                    val elemType = getTypeOfExpression(elem)
                    if (elemType !is Type.Object) continue
                    resolveStructuredTypeMembers(elemType)
                    val missingSym = getMissingRequiredPropertySymbol(elemType, elementType)
                    if (missingSym != null) {
                        val displaySource = typeToString(elemType)
                        val start = elem.pos
                        val length = expressionTrueEnd(elem) - start
                        if (length <= 0) continue
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        val relatedInfo = createPropertyDeclaredHereRelatedInfo(missingSym)
                        diagnostics.add(Diagnostic(
                            message = "Property '${missingSym.name}' is missing in type '$displaySource' but required in type '$elementDisplay'.",
                            category = DiagnosticCategory.Error,
                            code = 2741,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                            relatedInformation = listOfNotNull(relatedInfo),
                        ))
                    }
                }
                is ArrowFunction, is FunctionExpression -> {
                    // Skip — function expressions get checked elsewhere
                }
                is ArrayLiteralExpression -> {
                    // Nested array literal: if the expected element type is itself
                    // an Array<X>, recurse so the inner literal's primitive
                    // elements get checked against X. Handles `number[][][] =
                    // [[1, 2]]` shape where the inner `[1, 2]` needs each
                    // numeric literal checked against `number[]`.
                    if (elementType is Type.Reference && elementType.target.symbol?.name == "Array") {
                        checkArrayLiteralElementExcessProps(elem, elementType, source, fileName)
                    }
                }
                else -> {
                    // 16.0: Primitive element vs Object element type — emit TS2322.
                    val elemType = getTypeOfExpression(elem)
                    if (elemType === anyType || elemType === errorType) continue
                    // Only flag clear primitive mismatches (not unions/objects)
                    val elemIsPrimitive = elemType is Type.Intrinsic ||
                        elemType is Type.StringLiteral || elemType is Type.NumberLiteral ||
                        elemType is Type.BigIntLiteral
                    if (!elemIsPrimitive) continue
                    // null/undefined/void → skip (strictNullChecks variance);
                    // never (e.g. `undefined!`, B282) is assignable to EVERYTHING.
                    if (elemType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void or TypeFlags.Any or TypeFlags.Never)) continue
                    // Primitive can never be assignable to a non-empty object type.
                    // Widen literal types for display (TypeScript convention).
                    val displaySource = typeToString(getWidenedLiteralType(elemType))
                    val start = elem.pos
                    val length = expressionTrueEnd(elem) - start
                    if (length <= 0) continue
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type '$displaySource' is not assignable to type '$elementDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        }
    }

    /**
     * Round 934: one excess key of a fresh object literal — its COOKED member name (the
     * key the target's name set is keyed by, and what a spelling suggestion is computed
     * from) beside the text AS WRITTEN and that text's span, which is what tsc prints in
     * TS2353/TS2561 and what it squiggles.
     */
    /**
     * Round 934: does the excess-check TARGET absorb [name] through a NUMERIC index
     * signature? [collectTargetPropertyNames] already bails outright on a STRING index
     * signature (it makes every key known); a numeric one is narrower — it applies only
     * to a numerically-named key, which is tsc's `getApplicableIndexInfoForName`.
     *
     * The name test reads the AST as well as the cooked string on purpose: our
     * object-literal member name for a numeric key is the literal's SOURCE TEXT, where
     * tsc's is the numeric VALUE's canonical string, so `{ 1e3: v }` is named "1e3" here
     * and "1000" there. `isNumericLiteralName("1e3")` is false — correctly, for a STRING
     * key `"1e3"`, which tsc reports as excess — so a NumericLiteralNode key is admitted
     * by its node kind instead, which is what makes both rows match tsc.
     */
    private fun numericIndexAbsorbsKey(target: Type, name: String, nameNode: NameNode): Boolean {
        if (!targetHasNumberIndexInfo(target)) return false
        val inner = (nameNode as? ComputedPropertyName)?.expression ?: nameNode
        return inner is NumericLiteralNode || isNumericLiteralName(name)
    }

    /** Any-constituent numeric index signature, mirroring [collectTargetPropertyNames]'s
     *  own intersection/union flattening (a key is excess only if NO constituent takes it). */
    private fun targetHasNumberIndexInfo(type: Type): Boolean = when (type) {
        is Type.Interface -> type.declaredNumberIndexInfo != null || type.numberIndexInfo != null
        is Type.Object -> type.numberIndexInfo != null
        is Type.Intersection -> type.types.any { targetHasNumberIndexInfo(it) }
        is Type.Union -> type.types.any { targetHasNumberIndexInfo(it) }
        else -> false
    }

    private data class ExcessProp(
        val name: String,
        val display: String,
        val pos: Int,
        val length: Int,
    )

    private fun checkExcessProperties(
        objLiteral: ObjectLiteralExpression,
        sourceType: Type,
        targetType: Type,
        displayTarget: String,
        source: String,
        fileName: String,
        // B220: TS6500 "expected type comes from property ..." built by the PARENT
        // level's recursion (attached to nested TS2353/TS2561 emissions). tsc
        // attaches these only on the CALL-ARG path (contextual typing through a
        // signature) — var-decl/assignment nested EPC stays related-free
        // (nestedFreshLiteral), so the flag is set only at the call-arg sites.
        buildNestedRelated: Boolean = false,
        parentRelated: Diagnostic? = null,
        // B482ext: var-decl/assignment path — attach the TS6500 "expected type comes
        // from property" related info ONLY to a DEPTH-1 nested excess (the immediate
        // child of the top-level literal). tsc gives it for `let obj: {a:{x}}&… =
        // {a:{x,EXCESS}}` (intersectionPropertyCheck) but NOT for a depth-2 nested
        // excess (`{nested:{prop:{EXCESS}}}` → nestedFreshLiteral, related-free).
        topLevelRelatedOnly: Boolean = false,
    ): Boolean {
        if (sourceType !is Type.Object) return false
        val sourceProps = sourceType.properties ?: return false
        // Collect all target property names, flattening intersections
        val targetPropNames = collectTargetPropertyNames(targetType) ?: return false
        val excessProps = mutableListOf<ExcessProp>()
        for (sourceProp in sourceProps) {
            val name = sourceProp.name
            // B66.5: OBJECT_PROTOTYPE_PROPERTIES (toString, valueOf, hasOwnProperty, …)
            // are inherited via Object.prototype on every object literal — they're
            // never "excess" relative to a target shape. TypeScript checks them
            // against the corresponding Object signature (e.g. `toString(): string`)
            // via the standard property-type check and emits TS2322 there instead.
            if (name in OBJECT_PROTOTYPE_PROPERTIES) continue
            // B291: a bigint-literal-named property is dropped from the literal type
            // by tsc (TS1539 owns the error there) — never excess.
            val srcPropDecl = sourceProp.valueDeclaration ?: sourceProp.declarations.firstOrNull()
            if ((srcPropDecl as? PropertyAssignment)?.name is BigIntLiteralNode) continue
            if (name !in targetPropNames) {
                // B291: the target DECLARES a bigint-literal-named member with this
                // cooked text (`interface G { 2n: string }` + `{ "2n": ... }`) —
                // tsc drops bigint-named members from the member table (TS1539 owns
                // the error at the declaration), and the then-empty target is exempt
                // from excess checking (isKnownProperty's empty-object rule).
                val targetDeclaresBigintNamed = (targetType as? Type.Object)?.symbol?.declarations?.any { d ->
                    val mems = when (d) {
                        is InterfaceDeclaration -> d.members
                        is ClassDeclaration -> d.members
                        else -> null
                    }
                    mems?.any { m -> ((m as? PropertyDeclaration)?.name as? BigIntLiteralNode)?.text == name } == true
                } == true
                if (targetDeclaresBigintNamed) continue
                // Find the AST property that declared this member. Round 934: the
                // predicate is [objLitElementMemberName] — the SAME naming
                // getTypeOfObjectLiteral used to mint `sourceProp`, so a member that
                // exists in the source TYPE always has its declaring node found here.
                // The pre-934 `when` knew only Identifier and StringLiteralNode, so
                // `{ 7: v }`, `{ ["zz"]: v }`, `` { [`zz`]: v } `` and
                // `{ [Symbol.iterator]: v }` were typed as members, judged excess, and
                // then silently dropped for want of a position.
                val propNode = objLiteral.properties.firstOrNull { prop ->
                    objLitElementMemberName(prop) == name
                }
                if (propNode != null) {
                    val nameNode = when (propNode) {
                        is PropertyAssignment -> propNode.name
                        is ShorthandPropertyAssignment -> propNode.name
                        is MethodDeclaration -> propNode.name
                        else -> null
                    }
                    // tsc names the key WITH its delimiters and squiggles the written
                    // span (`'["zz"]'`, `''someKey''`); for a bare Identifier the two
                    // are the same string and the same length, which is why every
                    // pre-934 corpus baseline is untouched by this.
                    // Round 934: a NUMERIC index signature absorbs a numerically-named
                    // key exactly as a STRING one absorbs every key (which
                    // collectTargetPropertyNames already answers, by bailing). tsc's
                    // isKnownProperty consults the APPLICABLE index info, so
                    // `{ [k: number]: T }` accepts `7`, `[7]`, `"7"`, `["7"]` and
                    // `` [`7`] `` and rejects `"1e3"` — all five measured on 7.0.2. This
                    // guard could not matter before this round: a numerically-named key
                    // never found its declaring node, so it never reached an emission.
                    if (nameNode != null && numericIndexAbsorbsKey(targetType, name, nameNode)) continue
                    val written = nameNode?.let { writtenMemberNameSpan(it, source) }
                    val propPos = written?.first ?: nameNode?.pos ?: propNode.pos
                    val display = written?.let { source.substring(it.first, it.second) } ?: name
                    excessProps.add(ExcessProp(name, display, propPos, display.length))
                }
            }
        }
        var emitted = false
        // B560: tsc's `hasExcessProperties` reports the FIRST excess property of a
        // fresh object literal and returns immediately (Ternary.False) — it does NOT
        // enumerate every excess prop, nor proceed to the per-property structural check
        // (which is what recurses into known props). So `var o1: { a; b } = { e: 0,
        // f: 0 }` reports only `e`, never `f` (incompatibleTypes). We previously
        // reported every top-level excess. Match tsc: emit the first and stop (skip the
        // nested-known-prop recursion below too — tsc never reaches it once an excess is
        // found). FP-safe: no tsc baseline reports 2+ excess from one fresh literal via
        // this path (the only multi-excess baselines are destructuring/array, separate
        // emitters), so this can only REMOVE over-emission, never drop a wanted line.
        val firstExcess = excessProps.firstOrNull()
        if (firstExcess != null) {
            // `propName` is the COOKED member name (what the target's name set is keyed
            // by, hence what the spelling suggestion is computed from); `display` is the
            // key as WRITTEN, which is what tsc prints and squiggles.
            val propName = firstExcess.name
            val display = firstExcess.display
            val propPos = firstExcess.pos
            val propLen = firstExcess.length
            val (line, character) = getLineAndCharacterOfPosition(source, propPos)
            // Check for spelling suggestion (TS2561) vs plain excess (TS2353)
            val suggestion = getSpellingSuggestionFromNames(propName, targetPropNames)
            if (suggestion != null) {
                diagnostics.add(Diagnostic(
                    message = "Object literal may only specify known properties, but '$display' does not exist in type '$displayTarget'. Did you mean to write '$suggestion'?",
                    category = DiagnosticCategory.Error,
                    code = 2561,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = propPos,
                    length = propLen,
                    relatedInformation = listOfNotNull(parentRelated),
                ))
            } else {
                diagnostics.add(Diagnostic(
                    message = "Object literal may only specify known properties, and '$display' does not exist in type '$displayTarget'.",
                    category = DiagnosticCategory.Error,
                    code = 2353,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = propPos,
                    length = propLen,
                    relatedInformation = listOfNotNull(parentRelated),
                ))
            }
            return true
        }
        // 16.0: Recurse into non-excess properties whose source value is itself
        // an object literal and whose target type is a resolvable object. This
        // catches nested excess properties like
        //   `{ nestedProp: { asdfasdf: 1 } }` vs `{ nestedProp?: { testBool?: boolean } }`.
        // Round 477: a UNION target's nested descent drills the DISCRIMINANT-matched
        // constituent, not the first-constituent-with-the-prop (tsc's
        // getMatchingUnionConstituentForObjectLiteral) — `{ eventName:
        // CloseFileWatcherEvent, data: { id } }` vs ProjectServiceEvent must read `data`
        // from CloseFileWatcherEvent, not LargeFileReferencedEvent (editorServices:1253).
        val unionDiscriminantMember = (targetType as? Type.Union)
            ?.let { selectUnionMemberByObjLitDiscriminant(it, objLiteral) }
        for (propNode in objLiteral.properties) {
            if (propNode !is PropertyAssignment) continue
            // Round 934: the same naming as above, so a nested literal under a COMPUTED
            // key is descended into (`{ ["n"]: { p: 1, zz: 2 } }` — tsc reports the inner
            // `zz`, measured).
            val propName = objLitElementMemberName(propNode) ?: continue
            if (propName !in targetPropNames) continue // already flagged
            val nestedInit = propNode.initializer
            if (nestedInit !is ObjectLiteralExpression) continue
            val nestedTargetType = getTargetPropertyType(unionDiscriminantMember ?: targetType, propName)
                ?: continue
            // Resolve the nested target to an excess-checkable shape: a plain Object, an
            // Intersection (collectTargetPropertyNames flattens it — `photo: {id}&{url}`),
            // or a Union whose object constituent defines the valid keys
            // (`bar: boolean | View<TypeB>` → `View<TypeB>`).
            // (excessPropertyChecksWithNestedIntersections)
            val nestedExcessTarget: Type
            val nestedDisplay: String
            when {
                nestedTargetType is Type.Object -> {
                    // B220: an object literal vs an array/tuple member is a TS2322
                    // shape in tsc, never TS2353 — don't descend.
                    if (nestedTargetType is Type.Reference &&
                        nestedTargetType.target.symbol?.name in setOf("Array", "ReadonlyArray")) continue
                    if (nestedTargetType.tupleElementTypes != null) continue
                    resolveStructuredTypeMembers(nestedTargetType)
                    if (nestedTargetType.properties.isNullOrEmpty()) continue
                    nestedExcessTarget = nestedTargetType
                    nestedDisplay = typeToString(nestedTargetType)
                }
                nestedTargetType is Type.Intersection -> {
                    if (collectTargetPropertyNames(nestedTargetType).isNullOrEmpty()) continue
                    nestedExcessTarget = nestedTargetType
                    nestedDisplay = typeToString(nestedTargetType)
                }
                nestedTargetType is Type.Union -> {
                    val objConstituent = selectObjectConstituentForObjectLiteral(nestedTargetType) ?: continue
                    resolveStructuredTypeMembers(objConstituent)
                    if (objConstituent.properties.isNullOrEmpty()) continue
                    nestedExcessTarget = objConstituent
                    nestedDisplay = typeToString(objConstituent)
                }
                else -> continue
            }
            val nestedSourceType = getTypeOfExpression(nestedInit)
            if (nestedSourceType !is Type.Object) continue
            if (!canUseTypeEngine(nestedSourceType, nestedExcessTarget)) continue
            // B220: TS6500 for the nested emission — only when THIS level's
            // target is not a union (tsc's getPropertyOfType-on-union rule;
            // nonObjectUnionNestedExcessPropertyCheck must stay related-free).
            // B482ext: the var-decl/assignment path builds the related only at the
            // TOP level (parentRelated == null) so depth-1 children get it but
            // grandchildren don't (the intersectionPropertyCheck vs nestedFreshLiteral
            // distinction). The call-arg path (buildNestedRelated) builds at all levels.
            val nextRelated: Diagnostic? = if ((buildNestedRelated ||
                    (topLevelRelatedOnly && parentRelated == null)) && targetType !is Type.Union) {
                val ownerSym = when (targetType) {
                    is Type.Intersection -> targetType.types.firstNotNullOfOrNull {
                        (it as? Type.Object)?.members?.get(propName)
                    }
                    is Type.Object -> targetType.members?.get(propName)
                    else -> null
                }
                ownerSym?.let { sym ->
                    createPropertyDeclaredHereRelatedInfo(sym)?.copy(
                        // Use the alias-aware displayTarget (the CURRENT level's display)
                        // so a `type D = B & C` / `type MyType = … & …` target renders as
                        // its alias name (`D`/`MyType`), not the expanded intersection.
                        message = "The expected type comes from property '$propName' which is declared here on type '$displayTarget'",
                        code = 6500,
                    )
                }
            } else null
            if (checkExcessProperties(nestedInit, nestedSourceType, nestedExcessTarget, nestedDisplay, source, fileName, buildNestedRelated, nextRelated, topLevelRelatedOnly)) {
                emitted = true
            }
        }
        return emitted
    }

    /**
     * 16.0: Resolve the declared type of a property on a target type, flattening
     * intersections and unions (takes the first object constituent that has the prop).
     */
    private fun getTargetPropertyType(targetType: Type, propName: String): Type? {
        when (targetType) {
            is Type.Object -> {
                resolveStructuredTypeMembers(targetType)
                val sym = targetType.members?.get(propName) ?: return null
                // B220: route through getPropertyTypeForRelation so a GENERIC
                // Reference target's member resolves INSTANTIATED (`props: TProps`
                // on NestedProp<ITestProps> → ITestProps, not the unscoped
                // errorType that raw getTypeOfSymbol returns).
                return getPropertyTypeForRelation(targetType, sym)
            }
            is Type.Intersection -> {
                for (c in targetType.types) {
                    getTargetPropertyType(c, propName)?.let { return it }
                }
                return null
            }
            is Type.Union -> {
                for (c in targetType.types) {
                    getTargetPropertyType(c, propName)?.let { return it }
                }
                return null
            }
            else -> return null
        }
    }

    /**
     * 4e. Compare call or construct signatures.
     * Parameter types compared contravariantly, return types covariantly.
     */
    private fun signaturesRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
        isConstruct: Boolean,
    ): Boolean {
        val targetSigs = if (isConstruct) target.constructSignatures else target.callSignatures
        if (targetSigs.isNullOrEmpty()) return true // no signatures to match
        val sourceSigs = if (isConstruct) source.constructSignatures else source.callSignatures
        if (sourceSigs.isNullOrEmpty()) return false // target has signatures, source doesn't
        // Each target signature must be matched by some source signature
        for (targetSig in targetSigs) {
            val matched = sourceSigs.any { sourceSig ->
                signatureRelatedTo(sourceSig, targetSig, relation)
            }
            if (!matched) return false
        }
        return true
    }

    /** Compare two individual signatures. */
    /**
     * Method-member override relation with BIVARIANT parameters. Both types must be
     * function-shaped (single call signature). Used only by the class-property-override
     * check (TS2416) — tsc compares METHOD signatures bivariantly. Returns true iff every
     * source call sig relates to some target call sig with bivariant params.
     */
    private fun methodSignaturesBivariantlyRelated(derivedType: Type, baseType: Type): Boolean {
        if (derivedType !is Type.Object || baseType !is Type.Object) return false
        val dSigs = derivedType.callSignatures ?: return false
        val bSigs = baseType.callSignatures ?: return false
        if (dSigs.isEmpty() || bSigs.isEmpty()) return false
        // Every target (base) signature must be matched by some source (derived) signature.
        return bSigs.all { bSig ->
            dSigs.any { dSig -> signatureRelatedTo(dSig, bSig, assignableRelation, bivariantParams = true) }
        }
    }

    private fun signatureRelatedTo(
        source: Signature,
        target: Signature,
        relation: Relation,
        // When true, parameter positions are compared BIVARIANTLY (source param
        // assignable to target param OR vice versa) instead of strictly
        // contravariantly. tsc compares METHOD signatures bivariantly (only
        // function-type PROPERTIES get strict contravariance under
        // strictFunctionTypes). Used by the class-property-override check for
        // method members. Default false — every other caller keeps strict variance.
        bivariantParams: Boolean = false,
    ): Boolean {
        // Source requires more args than target provides → incompatible.
        // Round 475: a REST-param target provides UNBOUNDED args (`(...args: any[]) =>
        // void` accepts a 3-required-param source — tsc host.setTimeout callbacks,
        // server utilities.ts ThrottledOperations.run), so the arity gate is skipped.
        val sourceParams = source.parameters
        val targetParams = target.parameters
        val targetHasRestParam =
            (targetParams.lastOrNull()?.valueDeclaration as? Parameter)?.dotDotDotToken == true
        if (!targetHasRestParam && source.minArgumentCount > targetParams.size) return false
        // 17.10d: Light type-param inference for the SOURCE-generic, TARGET-non-generic
        // case. When source has type parameters and target doesn't, treat source's
        // TypeParam-typed param positions as "wildcards" pinned to the target's
        // concrete type at that position — a single TypeParam appearing multiple times
        // must map to the SAME target type (modulo subtyping); otherwise the comparison
        // fails. Each pinning must also satisfy the TypeParam's constraint. Without
        // this, FunctionType nodes with type params (added in 17.10b) FP-reject
        // legitimate contravariant param assignments like `(g: Giraffe) => void` ←
        // `<T extends Animal>(x: T) => void`.
        val sourceHasTpInParams = !source.typeParameters.isNullOrEmpty() &&
            target.typeParameters.isNullOrEmpty() &&
            sourceParams.any { getTypeOfSymbol(it) is Type.TypeParam }
        val tpAssignments = if (sourceHasTpInParams) mutableMapOf<Int, Type>() else null
        // Round 455: a NAME-keyed companion to tpAssignments — Type.TypeParam instances
        // are interned per AST position (B199), so the sig's own type-param object and
        // the param-annotation's TypeParam may carry different ids; matching the return
        // type's TypeParam by name is the robust fallback for the substitution below.
        val tpAssignByName = if (sourceHasTpInParams) mutableMapOf<String, Type>() else null
        // Check parameter types (contravariant). We do params BEFORE return type so
        // the type-param assignments from param pinning drive return-type substitution
        // (round 455).
        val len = minOf(sourceParams.size, targetParams.size)
        // B63.29: When target's last param is a rest `...t: U[]`, positional comparison
        // beyond target.size-1 (and AT target.size-1 against a non-rest source param)
        // should use the rest element type U, not U[]. Without this, source's typed
        // param like `bar: string` vs target's rest `...tail: any[]` contravariantly
        // checks `any[]` vs `string` → false. Correct: check element `any` vs `string` → true.
        val targetLast = targetParams.lastOrNull()
        val targetLastIsRest = (targetLast?.valueDeclaration as? Parameter)?.dotDotDotToken == true
        // Compute the rest element type, OR a sentinel marking "non-array rest" (which
        // can't actually accept tuple-like spreads and TypeScript treats as accept-all).
        // - Array<U> / ReadonlyArray<U> → element type U
        // - any → anyType (accept all)
        // - Tuple → fall through to standard comparison (don't bail)
        // - Anything else (intersection, named non-array, never) → anyType (accept all,
        //   since the rest type isn't a valid spread target)
        val targetRestRaw = if (targetLastIsRest) getTypeOfSymbol(targetLast) else null
        val targetRestElement: Type? = if (targetLastIsRest && targetRestRaw != null) {
            when {
                targetRestRaw is Type.Reference &&
                    targetRestRaw.target.symbol?.name in setOf("Array", "ReadonlyArray") ->
                    targetRestRaw.resolvedTypeArguments?.firstOrNull()
                targetRestRaw === anyType -> anyType
                // B63.31: Non-array rest type (intersection of object literals, named non-array,
                // etc.) — TypeScript treats these as accept-anything since the rest spread can't
                // actually deliver values of that shape. Fixed-arity comparison bails by using
                // anyType for the element. Tuples (Type.Object with tupleElementTypes) fall
                // through (we don't have per-position tuple-element comparison yet).
                targetRestRaw is Type.Object && targetRestRaw.tupleElementTypes != null -> null
                else -> anyType
            }
        } else null
        // B196: SOURCE-side rest expansion. When the SOURCE's last param is a rest
        // `...x: E[]` and the target side is NON-rest, TypeScript relates target
        // positions at/after the source rest index against the rest ELEMENT type E —
        // `(...x: number[]) => void` is NOT assignable to `(x: number[], y: string) =>
        // void` (number[] vs number fails). Gated to a concrete Array/ReadonlyArray
        // element (never/any/TypeParam rests keep the prior permissive behavior, e.g.
        // genericRestTypes' `...args: never`). Element comparisons are BIVARIANT
        // (tsc's method-param rule) so legitimate contravariant cases stay legal.
        val sourceLastParam = sourceParams.lastOrNull()
        val sourceLastIsRest = (sourceLastParam?.valueDeclaration as? Parameter)?.dotDotDotToken == true
        val sourceRestElement: Type? = if (sourceLastIsRest && !targetLastIsRest) {
            val raw = getTypeOfSymbol(sourceLastParam)
            if (raw is Type.Reference && raw.target.symbol?.name in setOf("Array", "ReadonlyArray"))
                raw.resolvedTypeArguments?.firstOrNull()?.takeIf {
                    it !== anyType && it !== errorType && it !is Type.TypeParam
                }
            else null
        } else null
        for (i in 0 until len) {
            val sourceParamTypeRaw = getTypeOfSymbol(sourceParams[i])
            val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
            // B196: at the source's rest position (target non-rest), compare the
            // target param against the rest ELEMENT bivariantly.
            if (sourceIsRest && i == sourceParams.size - 1 && sourceRestElement != null) {
                val t = getTypeOfSymbol(targetParams[i])
                if (t !== anyType && t !== errorType && t !is Type.TypeParam) {
                    if (!checkTypeRelatedTo(t, sourceRestElement, relation) &&
                        !checkTypeRelatedTo(sourceRestElement, t, relation)) return false
                }
                continue
            }
            // Round 480: a source rest whose ELEMENT is any/error/TypeParam (the
            // shapes sourceRestElement's takeIf rejects) accepts ANY target params —
            // `(...args: any[]) => void` is assignable to `(project: Project) =>
            // void` (tsc harness incrementalUtils.ts withIncrementalVerifierCallbacks);
            // without this the position compared the ARRAY type (`Project <: any[]`
            // contravariantly) and failed.
            if (sourceIsRest && i == sourceParams.size - 1 && !targetLastIsRest) {
                continue
            }
            val sourceParamType = sourceParamTypeRaw
            // For the target's rest param position, if source is also rest, compare U[] vs T[]
            // normally. If source is non-rest at the same position, compare element vs source.
            val targetParamType = if (i == targetParams.size - 1 && targetLastIsRest && !sourceIsRest && targetRestElement != null) {
                targetRestElement
            } else {
                getTypeOfSymbol(targetParams[i])
            }
            if (tpAssignments != null && sourceParamType is Type.TypeParam) {
                val tpId = sourceParamType.id
                val existing = tpAssignments[tpId]
                if (existing != null && existing !== targetParamType) return false
                tpAssignments[tpId] = targetParamType
                sourceParamType.symbol?.name?.let { tpAssignByName?.put(it, targetParamType) }
                // Constraint check: target must satisfy source TypeParam's constraint
                val cons = sourceParamType.constraint
                if (cons != null && cons !== errorType) {
                    if (!checkTypeRelatedTo(targetParamType, cons, relation)) return false
                }
                continue
            }
            // Standard contravariant: target param must be assignable to source param.
            // Under bivariantParams (method members), also accept the covariant direction.
            // (CHK.62) An OPTIONAL source parameter accepts `undefined`, so its type in the
            // contravariant test is `T | undefined` — tsc's `addOptionality`, applied when the
            // parameter symbol's type is computed. Without it `(x?: string) => void` was not
            // assignable to `(x: string | undefined) => void`: the target's `undefined`
            // constituent had nowhere to go. Measured on the server profile at
            // `project.ts:2277` (`ServerHost` -> `GetPackageJsonEntrypointsHost`, whose
            // `readDirectory: CompilerHost["readDirectory"]` has required `extensions` /
            // `includes` where `System.readDirectory`'s are optional). Deliberately SOURCE-side
            // only: widening the TARGET side too is the other half of tsc's model and would
            // REJECT `(x: string) => void` against `(x?: string) => void` — a rejection change
            // measured separately, see the (CHK.62) session note.
            val sourceParamCmp =
                if ((sourceParams[i].valueDeclaration as? Parameter)?.questionToken == true &&
                    sourceParamType !== anyType && sourceParamType !== errorType &&
                    !typeIncludesUndefined(sourceParamType)
                ) getUnionType(listOf(sourceParamType, undefinedType)) else sourceParamType
            if (!checkTypeRelatedTo(targetParamType, sourceParamCmp, relation) &&
                !(bivariantParams && checkTypeRelatedTo(sourceParamType, targetParamType, relation))) return false
        }
        // B63.29 continuation: Source has MORE params than target.size — target's rest
        // covers them. For each excess source position, check target rest element type
        // contravariantly against the source param type.
        if (targetLastIsRest && targetRestElement != null && sourceParams.size > targetParams.size) {
            for (i in targetParams.size until sourceParams.size) {
                val sourceParamType = getTypeOfSymbol(sourceParams[i])
                val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                // Source's own rest: compare its element vs target rest element
                val srcCmp = if (sourceIsRest && sourceParamType is Type.Reference &&
                    sourceParamType.target.symbol?.name in setOf("Array", "ReadonlyArray"))
                    sourceParamType.resolvedTypeArguments?.firstOrNull() ?: sourceParamType
                else sourceParamType
                if (!checkTypeRelatedTo(targetRestElement, srcCmp, relation)) return false
            }
        }
        // Check return types (covariant)
        // Void target return accepts any source return type (void means "don't care about return")
        var sourceReturn = source.resolvedReturnType ?: anyType
        val targetReturn = target.resolvedReturnType ?: anyType
        // Round 455: substitute the pinned source type params into the source RETURN
        // type before the covariant check. `identity<T>(x: T): T` (source-generic,
        // target-non-generic) pins T := <target param type> from the param loop above,
        // so the return `T` becomes e.g. `string` and relates to a
        // `(fileName: string) => string` target (`GetCanonicalFileName`). Without this
        // the raw TypeParam return FP-rejects against the concrete target return.
        if (tpAssignments != null && tpAssignments.isNotEmpty()) {
            val pinMapper = TypeMapper { tp ->
                tpAssignments[tp.id] ?: tp.symbol?.name?.let { tpAssignByName?.get(it) }
            }
            sourceReturn = instantiateType(sourceReturn, pinMapper)
        }
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, relation)) return false
        return true
    }

    /**
     * Generate elaboration chain for a function→function type mismatch.
     * Returns lines like:
     *   "  Type 'void' is not assignable to type 'boolean'."
     * or:
     *   "  Types of parameters 'x' and 's1' are incompatible."
     *   "    Type 'string' is not assignable to type 'number'."
     */
    /**
     * 16.4dw: A signature has only simple-checkable param/return types (primitives,
     * literals, void, undefined, null, never). Used to guard function-to-function
     * structural comparison against generic-inference FPs.
     */
    /**
     * B70.7: Format target's params [startIdx..end] as a labeled-tuple display
     * `[name: type, name: type, ...name: type]` for use in rest-param elaboration
     * (source rest param absorbing target positional params). Uses the param's
     * AST type-node source text when available (preserves `T` for unbound
     * TypeParams in function-type alias bodies); falls back to `typeToString`.
     * Returns null if any param lacks a usable display.
     */
    private fun formatTargetParamsAsTuple(targetParams: List<Symbol>, startIdx: Int): String? {
        val parts = mutableListOf<String>()
        for (i in startIdx until targetParams.size) {
            val sym = targetParams[i]
            val paramDecl = sym.valueDeclaration as? Parameter ?: return null
            val isRest = paramDecl.dotDotDotToken
            val typeNode = paramDecl.type
            val typeText = typeNode?.let { formatTypeForDisplay(it) } ?: typeToString(getTypeOfSymbol(sym))
            val prefix = if (isRest) "..." else ""
            parts.add("$prefix${sym.name}: $typeText")
        }
        return "[${parts.joinToString(", ")}]"
    }

    private fun sigHasOnlySimpleTypes(sig: Signature): Boolean {
        val ret = sig.resolvedReturnType ?: return false
        if (ret !== voidType && !isSimpleCheckableType(ret)) return false
        for (p in sig.parameters) {
            val pt = getTypeOfSymbol(p)
            if (!isSimpleCheckableType(pt)) return false
        }
        return true
    }

    /** B207: definite bivariant incompatibility of a union fn member vs the target fn —
     *  a positional param pair failing assignability in BOTH directions with ≥1
     *  primitive/literal side, or source minArgs exceeding the target's param count.
     *  Rest params and any/error/TypeParam sides are skipped (FN-safe). */
    private fun fnMemberFailsBivariantly(member: Type.Object, target: Type.Object): Boolean {
        val srcSig = member.callSignatures?.firstOrNull() ?: return false
        val tgtSig = target.callSignatures?.firstOrNull() ?: return false
        if (srcSig.minArgumentCount > tgtSig.parameters.size) return true
        val srcDecls = signatureDeclarationParameters(srcSig.declaration)
        val tgtDecls = signatureDeclarationParameters(tgtSig.declaration)
        val n = minOf(srcSig.parameters.size, tgtSig.parameters.size)
        for (i in 0 until n) {
            if (srcDecls?.getOrNull(i)?.dotDotDotToken == true ||
                tgtDecls?.getOrNull(i)?.dotDotDotToken == true) continue
            val sp = getTypeOfSymbol(srcSig.parameters[i])
            val tp = getTypeOfSymbol(tgtSig.parameters[i])
            if (sp === anyType || sp === errorType || sp is Type.TypeParam) continue
            if (tp === anyType || tp === errorType || tp is Type.TypeParam) continue
            val onePrimitive = sp is Type.Intrinsic || tp is Type.Intrinsic ||
                sp is Type.StringLiteral || sp is Type.NumberLiteral ||
                tp is Type.StringLiteral || tp is Type.NumberLiteral
            if (!onePrimitive) continue
            val d1 = checkTypeRelatedTo(tp, sp, assignableRelation)
            val d2 = checkTypeRelatedTo(sp, tp, assignableRelation)
            if (!d1 && !d2) return true
        }
        return false
    }

    /**
     * intTypeCheck: multi-signature targets — [getFunctionMismatchElaboration] compares
     * source.first() vs target.first() only, but tsc elaborates the FIRST FAILING target
     * signature (`() => void` vs `i6`'s inherited `(): number` → "Type 'void' is not
     * assignable to type 'number'."). When the first-vs-first elaboration is empty and the
     * target has more signatures, retry each remaining target sig via a shallow wrapper.
     */
    private fun getFunctionMismatchElaborationMultiSig(
        source: Type.Object, target: Type.Object
    ): List<String> {
        val direct = getFunctionMismatchElaboration(source, target)
        if (direct.isNotEmpty()) return direct
        val tsigs = target.callSignatures ?: return emptyList()
        for (i in 1 until tsigs.size) {
            val wrapper = Type.Object()
            wrapper.callSignatures = listOf(tsigs[i])
            val elab = getFunctionMismatchElaboration(source, wrapper)
            if (elab.isNotEmpty()) return elab
        }
        return emptyList()
    }

    private fun getFunctionMismatchElaboration(
        source: Type.Object, target: Type.Object
    ): List<String> {
        // Cycle guard: a recursive function type (`interface I { (x: I): void }`)
        // recurses below with swapped operands (contravariance) into an alternating
        // (A,B)/(B,A) cycle. Re-entry on a pair already in progress returns no
        // elaboration instead of overflowing the stack (silently swallowed by callers).
        val pairKey = packRelationKey(source.id, target.id)
        if (!state.functionElaborationStack.add(pairKey)) return emptyList()
        try {
            return getFunctionMismatchElaborationWorker(source, target)
        } finally {
            state.functionElaborationStack.remove(pairKey)
        }
    }

    private fun getFunctionMismatchElaborationWorker(
        source: Type.Object, target: Type.Object
    ): List<String> {
        val sourceSigs = source.callSignatures
        val targetSigs = target.callSignatures
        if (sourceSigs.isNullOrEmpty() || targetSigs.isNullOrEmpty()) return emptyList()
        val sourceSig = sourceSigs.first()
        val targetSig = targetSigs.first()
        // Arity mismatch: source requires more arguments than target provides.
        // Emit "Target signature provides too few arguments. Expected N or more, but got M."
        // — matches `signatureLengthMismatchCall`-style baselines for TS2345 with
        // function args. Take this branch BEFORE per-param comparison since the
        // arity gap is more fundamental than any individual param-type mismatch.
        // Round 475: a REST-param target never has an arity gap (mirrors the
        // signatureRelatedTo gate).
        val elabTargetHasRest =
            (targetSig.parameters.lastOrNull()?.valueDeclaration as? Parameter)?.dotDotDotToken == true
        if (!elabTargetHasRest && sourceSig.minArgumentCount > targetSig.parameters.size) {
            return listOf(
                "  Target signature provides too few arguments. Expected ${sourceSig.parameters.size} or more, but got ${targetSig.parameters.size}."
            )
        }
        // 16.4dw: Check parameter type mismatch FIRST (contravariant) — TypeScript reports
        // the parameter mismatch before the return-type mismatch when both fail, because
        // params are contravariant and the failure is more fundamental.
        // 17.10e: Mirror `signatureRelatedTo`'s light type-param inference. When source has
        // type parameters and target doesn't, the FAILING pair is the one where the source
        // TypeParam was already pinned to a different target type — and the elaboration
        // should display the EARLIER pinned target (substituted) instead of the raw `T`.
        // Example: `<T>(x: T, y: T) => void` vs `(g: Giraffe, e: Elephant) => void`
        //   → first pair pins T = Giraffe (passes constraint Animal); second pair fails
        //     because Elephant !== Giraffe; report `(y, e)` mismatch with substituted
        //     `Type 'Elephant' is not assignable to type 'Giraffe'.`
        val sourceParams = sourceSig.parameters
        val targetParams = targetSig.parameters
        val sigHasTpInParams = !sourceSig.typeParameters.isNullOrEmpty() &&
            targetSig.typeParameters.isNullOrEmpty() &&
            sourceParams.any { getTypeOfSymbol(it) is Type.TypeParam }
        val tpAssignments = if (sigHasTpInParams) mutableMapOf<Int, Type>() else null
        val len = minOf(sourceParams.size, targetParams.size)
        for (i in 0 until len) {
            val sourceParamType = getTypeOfSymbol(sourceParams[i])
            val targetParamType = getTypeOfSymbol(targetParams[i])
            if (tpAssignments != null && sourceParamType is Type.TypeParam) {
                val tpId = sourceParamType.id
                val existing = tpAssignments[tpId]
                if (existing != null && existing !== targetParamType) {
                    // Pinning conflict — substitute the EARLIER pinned target into the
                    // source param display, then run a property-elaboration to surface
                    // a "Property X is missing in Y but required in Z" line if applicable.
                    val pinned = existing
                    val nestedChain = if (targetParamType is Type.Object && pinned is Type.Object) {
                        getPropertyElaborationChain(targetParamType, pinned)
                    } else null
                    val secondLine = if (!nestedChain.isNullOrEmpty()) {
                        // getPropertyElaborationChain returns lines indented "  ..." — bump to "    ..."
                        nestedChain.first().replaceFirst("  ", "    ")
                    } else {
                        "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(pinned)}'."
                    }
                    return listOf(
                        "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                        secondLine,
                    )
                }
                tpAssignments[tpId] = targetParamType
                val cons = sourceParamType.constraint
                if (cons != null && cons !== errorType) {
                    if (!checkTypeRelatedTo(targetParamType, cons, assignableRelation)) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(cons)}'.",
                        )
                    }
                }
                continue
            }
            // B196: source-rest element elaboration — target's param at the source's
            // rest position compares against the rest ELEMENT type (matches the
            // signatureRelatedTo expansion); the chain displays the element.
            run {
                val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                val targetIsRest = (targetParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                if (!sourceIsRest || i != sourceParams.size - 1 || targetIsRest) return@run
                val raw = sourceParamType
                val e = if (raw is Type.Reference && raw.target.symbol?.name in setOf("Array", "ReadonlyArray"))
                    raw.resolvedTypeArguments?.firstOrNull()?.takeIf {
                        it !== anyType && it !== errorType && it !is Type.TypeParam
                    } else null
                if (e == null) return@run
                if (!checkTypeRelatedTo(targetParamType, e, assignableRelation) &&
                    !checkTypeRelatedTo(e, targetParamType, assignableRelation)) {
                    return listOf(
                        "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                        "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(e)}'.",
                    )
                }
            }
            if (!checkTypeRelatedTo(targetParamType, sourceParamType, assignableRelation)) {
                // B70.7: When source's param at position i is REST and target has
                // a non-rest param at position i (and may have more positions
                // after), TypeScript constructs a labeled-tuple `[name: type, ...]`
                // from target's params [i..end] and displays that as the "from"
                // type, comparing it against source's rest type as a whole.
                // Example (`genericRestTypes_ts`):
                //   source `(...args: never) => void`, target `(x:string, ...rest:T) => void`
                //   → chain `Type '[x: string, ...rest: T]' is not assignable to type 'never'.`
                val sourceIsRest = (sourceParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                val targetIsRest = (targetParams[i].valueDeclaration as? Parameter)?.dotDotDotToken == true
                if (sourceIsRest && i == sourceParams.size - 1 && !targetIsRest && targetParams.size > i) {
                    val tupleDisplay = formatTargetParamsAsTuple(targetParams, i)
                    if (tupleDisplay != null) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '$tupleDisplay' is not assignable to type '${typeToString(sourceParamType)}'.",
                        )
                    }
                }
                // 17.15a: When both inner param types are function types, recurse
                // for deeper "Types of parameters X and Y are incompatible" chain
                // matching TypeScript's contravariant elaboration. The inner call's
                // (source, target) mirror the outer-comparison's contravariant
                // checkTypeRelatedTo direction: inner-source = outer-target's param,
                // inner-target = outer-source's param.
                if (targetParamType is Type.Object && sourceParamType is Type.Object &&
                    !targetParamType.callSignatures.isNullOrEmpty() &&
                    !sourceParamType.callSignatures.isNullOrEmpty()
                ) {
                    val nested = getFunctionMismatchElaboration(targetParamType, sourceParamType)
                    if (nested.isNotEmpty()) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                        ) + nested.map { "  $it" }
                    }
                }
                // When both inner param types are non-function Type.Object, recurse via
                // property elaboration so the chain shows the inner property mismatch
                // (e.g. `{a: number}` vs `{a: string}` → "Types of property 'a' are
                // incompatible. Type 'number' is not assignable to type 'string'.").
                // Argument order mirrors the contravariance: targetParam is the "from"
                // and sourceParam is the "to" in the displayed chain line.
                if (targetParamType is Type.Object && sourceParamType is Type.Object &&
                    targetParamType.callSignatures.isNullOrEmpty() &&
                    sourceParamType.callSignatures.isNullOrEmpty()
                ) {
                    val propChain = getPropertyElaborationChain(targetParamType, sourceParamType)
                    if (!propChain.isNullOrEmpty()) {
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(sourceParamType)}'.",
                        ) + propChain.map { "    $it" }
                    }
                }
                // typeParameterConstrainedToOuterTypeParameter: target param reduces to a
                // bare call-sig TypeParam (U) and source param reduces to Array<TypeParam>
                // (U[]) whose element TypeParam carries a constraint. TypeScript substitutes
                // each side's own call-sig type parameter by its CONSTRAINT for display
                // (source U[] -> <srcCons>[], target U -> <tgtCons>), then drills one level
                // into the array: deeper line compares target's <tgtCons> scalar against
                // source's <srcCons>[] array. The constraint of an inner `<U extends T>` is
                // the OUTER interface type param `T`, which must be instantiated through the
                // enclosing reference's args (A<string> -> T=string) before display — without
                // this it renders the raw `T[]`/`T` (empirically confirmed). Gated tightly to
                // this exact array-element-vs-scalar shape with BOTH constraints resolving to
                // concrete types, so every other param shape falls through unchanged.
                run {
                    val tgtTp = targetParamType as? Type.TypeParam
                    val srcRef = sourceParamType as? Type.Reference
                    val srcElem = srcRef?.resolvedTypeArguments?.singleOrNull() as? Type.TypeParam
                    if (tgtTp != null && srcRef != null && srcRef.target === globalArrayType &&
                        srcElem != null
                    ) {
                        val rawTgtCons = tgtTp.constraint
                        val rawSrcCons = srcElem.constraint
                        if (rawTgtCons != null && rawTgtCons !== errorType &&
                            rawSrcCons != null && rawSrcCons !== errorType
                        ) {
                            // Instantiate each constraint through its enclosing reference's
                            // type-arg mapper so an outer-TP constraint (`U extends T`) becomes
                            // the concrete outer arg (`string`). When the enclosing type isn't
                            // a generic reference the mapper is identity (constraint unchanged).
                            fun refMapper(t: Type.Object): TypeMapper? {
                                val ref = t as? Type.Reference ?: return null
                                val tps = ref.target.typeParameters ?: return null
                                val args = ref.resolvedTypeArguments ?: return null
                                if (tps.isEmpty() || tps.size != args.size) return null
                                return createTypeMapper(tps, args)
                            }
                            val srcMapper = refMapper(source)
                            val tgtMapper = refMapper(target)
                            val tgtCons = if (tgtMapper != null) instantiateType(rawTgtCons, tgtMapper) else rawTgtCons
                            val srcCons = if (srcMapper != null) instantiateType(rawSrcCons, srcMapper) else rawSrcCons
                            // Only take this branch when at least one constraint actually
                            // became concrete (not still a bare TypeParam) — otherwise the
                            // raw-`T` display would not match TypeScript and we'd flip nothing
                            // while risking an unexpected baseline; fall through instead.
                            if (srcCons !is Type.TypeParam && tgtCons !is Type.TypeParam) {
                                val srcArrDisplay = "${typeToString(srcCons)}[]"
                                return listOf(
                                    "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                                    "    Type '${typeToString(tgtTp)}' is not assignable to type '$srcArrDisplay'.",
                                    "      Type '${typeToString(tgtCons)}' is not assignable to type '$srcArrDisplay'.",
                                )
                            }
                        }
                    }
                }
                // Round 96: BOTH params are bare `Type.TypeParam` whose constraints are
                // concrete OBJECT types that differ — e.g. `<T,U extends {a:T;b:number}>(z:U)`
                // vs `<T,U extends {a:T;b:string}>(z:U)`. TypeScript substitutes each U by its
                // constraint and drills into the differing property (here `b`). Display keeps
                // the target param bare (`U`) and renders the source param as its constraint,
                // then a constraint-vs-constraint line, then the property drill. Gated to both
                // sides being TypeParam with Object constraints AND a real drill-able mismatch
                // (deeper != null), so every other param shape falls through unchanged.
                run {
                    val tgtTp = targetParamType as? Type.TypeParam
                    val srcTp = sourceParamType as? Type.TypeParam
                    if (tgtTp != null && srcTp != null) {
                        val rawTgtCons = tgtTp.constraint
                        val rawSrcCons = srcTp.constraint
                        if (rawTgtCons != null && rawTgtCons !== errorType &&
                            rawSrcCons != null && rawSrcCons !== errorType
                        ) {
                            fun refMapper2(t: Type.Object): TypeMapper? {
                                val ref = t as? Type.Reference ?: return null
                                val tps = ref.target.typeParameters ?: return null
                                val args = ref.resolvedTypeArguments ?: return null
                                if (tps.isEmpty() || tps.size != args.size) return null
                                return createTypeMapper(tps, args)
                            }
                            val srcMapper = refMapper2(source)
                            val tgtMapper = refMapper2(target)
                            val tgtCons = if (tgtMapper != null) instantiateType(rawTgtCons, tgtMapper) else rawTgtCons
                            val srcCons = if (srcMapper != null) instantiateType(rawSrcCons, srcMapper) else rawSrcCons
                            if (srcCons is Type.Object &&
                                tgtCons is Type.Object
                            ) {
                                val deeper = getPropertyElaborationChain(tgtCons, srcCons)
                                if (deeper != null) {
                                    return listOf(
                                        "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                                        "    Type '${typeToString(tgtTp)}' is not assignable to type '${typeToString(srcCons)}'.",
                                        "      Type '${typeToString(tgtCons)}' is not assignable to type '${typeToString(srcCons)}'.",
                                    ) + deeper.map { "      $it" }
                                }
                            }
                        }
                    }
                }
                // B70.1ext: When `targetParamType` is a literal type AND `sourceParamType`
                // is a primitive of a DIFFERENT base (e.g. `'hi'` (StringLiteral) vs
                // `number`), TypeScript widens the literal in the chain display:
                // `Type 'string' is not assignable to type 'number'.`, not
                // `Type '"hi"' is not assignable to type 'number'.`. Same-base mismatches
                // (`'hi'` vs `'bye'` — both string literals) keep both literals.
                val displayTargetParam = widenLiteralForDifferentBaseDisplay(targetParamType, sourceParamType)
                // B481b: BOTH params optional (`n?: number` vs `b?: boolean`). TypeScript
                // widens each optional param to `T | undefined` and produces a TWO-level
                // union sub-chain: the union-vs-union relation, then the failing member
                // (the non-undefined constituent) vs the target's `T | undefined`. Gated to
                // both-optional + neither display already mentioning undefined (strictNull-on
                // params already carry it → fall through to the bare form unchanged).
                run {
                    val srcOpt = (sourceParams[i].valueDeclaration as? Parameter)?.questionToken == true
                    val tgtOpt = (targetParams[i].valueDeclaration as? Parameter)?.questionToken == true
                    val aBase = typeToString(displayTargetParam)
                    val bBase = typeToString(sourceParamType)
                    if (srcOpt && tgtOpt && !aBase.contains("undefined") && !bBase.contains("undefined")) {
                        // The deepest line drills the source's non-undefined failing member
                        // (`aBase`) against the target. tsc keeps `| undefined` on the target
                        // when `aBase` is atomic (e.g. `number`), but STRIPS it when `aBase`
                        // is `boolean` — internally `boolean` = `true | false`, so tsc recurses
                        // into its members and elaborates each against the best-matching single
                        // target constituent (dropping `undefined`).
                        val deepestTarget = if (aBase == "boolean") bBase else "$bBase | undefined"
                        return listOf(
                            "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                            "    Type '$aBase | undefined' is not assignable to type '$bBase | undefined'.",
                            "      Type '$aBase' is not assignable to type '$deepestTarget'.",
                        )
                    }
                }
                return listOf(
                    "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                    "    Type '${typeToString(displayTargetParam)}' is not assignable to type '${typeToString(sourceParamType)}'.",
                )
            }
        }
        // Check return type mismatch
        val sourceReturn = sourceSig.resolvedReturnType ?: anyType
        val targetReturn = targetSig.resolvedReturnType ?: anyType
        // B71.1: Mirror the arg-level strict void→undefined gate. Source's return is
        // `void` (e.g. implicit-void FunctionDeclaration); target's return is `undefined`.
        // Emit the chain "Type 'void' is not assignable to type 'undefined'." so the
        // caller's TS2345 displays a proper elaboration.
        if (strictNullChecks &&
            sourceReturn === voidType &&
            targetReturn.flags.hasAny(TypeFlags.Undefined) &&
            !targetReturn.flags.hasAny(TypeFlags.Void)
        ) {
            return listOf("  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
        }
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, assignableRelation)) {
            // 17.11a: When target's return type is one of target's own type
            // parameters (e.g. `<T>(x:T) => T`) AND source has its own type
            // parameters whose names appear in source's return type (e.g.
            // `<S>() => S[]`), TypeScript displays the source return with each
            // source TypeParam substituted by `unknown` and adds the elaboration
            // line "'T' could be instantiated with an arbitrary type which could
            // be unrelated to '<displayed-source>'." The intuition: source's `S`
            // is unbound from target's `T`, so the caller's `T` can be any type
            // the caller picks — yet source guarantees only `S[]` (which is
            // `unknown[]` when displayed without context). The target TypeParam
            // is therefore not safely instantiable to whatever the caller picks.
            val targetTpReturn = targetReturn as? Type.TypeParam
            val sourceTps = sourceSig.typeParameters
            if (targetTpReturn != null
                && targetSig.typeParameters?.contains(targetTpReturn) == true
                && !sourceTps.isNullOrEmpty()
                && sourceContainsTypeParam(sourceReturn, sourceTps)
            ) {
                val mapper = TypeMapper { tp ->
                    if (sourceTps.contains(tp)) unknownType else null
                }
                val srcDisplay = typeToStringWithMapper(sourceReturn, mapper)
                val tgtDisplay = typeToString(targetReturn)
                return listOf(
                    "  Type '$srcDisplay' is not assignable to type '$tgtDisplay'.",
                    "    '$tgtDisplay' could be instantiated with an arbitrary type which could be unrelated to '$srcDisplay'.",
                )
            }
            // B50.6: Function return-type chain. When BOTH returns are pure function
            // types (call signatures only, no properties/members/construct sigs),
            // recurse with a "Call signature return types '<src>' and '<tgt>' are
            // incompatible." header so nested-callback patterns produce the full
            // drilled chain (cf. `nestedCallbackErrorNotFlattened_ts`).
            if (sourceReturn is Type.Object && targetReturn is Type.Object &&
                !sourceReturn.callSignatures.isNullOrEmpty() &&
                !targetReturn.callSignatures.isNullOrEmpty() &&
                sourceReturn.properties.isNullOrEmpty() &&
                targetReturn.properties.isNullOrEmpty() &&
                sourceReturn.members.isNullOrEmpty() &&
                targetReturn.members.isNullOrEmpty() &&
                sourceReturn.constructSignatures.isNullOrEmpty() &&
                targetReturn.constructSignatures.isNullOrEmpty()
            ) {
                val srcDisp = typeToString(sourceReturn)
                val tgtDisp = typeToString(targetReturn)
                val nested = getFunctionMismatchElaboration(sourceReturn, targetReturn)
                val header = "  Call signature return types '$srcDisp' and '$tgtDisp' are incompatible."
                return listOf(header) + nested.map { "  $it" }
            }
            // B75.3: When return types are same-target generic references (e.g. both
            // `Array<U>` / `ReadonlyArray<U>`) with differing args whose deeper chain
            // can be elaborated, append the drill-in. Matches TypeScript's `concat(...)`
            // chain for Array-derived → ReadonlyArray<T> tests, which surfaces the
            // missing-required-property line at element depth.
            val srcRefRet = sourceReturn as? Type.Reference
            val tgtRefRet = targetReturn as? Type.Reference
            if (srcRefRet != null && tgtRefRet != null &&
                srcRefRet.target === tgtRefRet.target) {
                val sArgs = srcRefRet.resolvedTypeArguments
                val tArgs = tgtRefRet.resolvedTypeArguments
                if (sArgs != null && tArgs != null && sArgs.size == tArgs.size) {
                    val header = "  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'."
                    for (i in sArgs.indices) {
                        if (!checkTypeRelatedTo(sArgs[i], tArgs[i], assignableRelation)) {
                            val sa = sArgs[i]
                            val ta = tArgs[i]
                            if (sa is Type.Object && ta is Type.Object) {
                                val deeper = getPropertyElaborationChain(sa, ta, "")
                                if (deeper != null) {
                                    val firstTrimmed = deeper.first().trimStart()
                                    return if (firstTrimmed.startsWith("Property '")) {
                                        listOf(header) + deeper.map { "  $it" }
                                    } else {
                                        listOf(header) + deeper.map { "  $it" }
                                    }
                                }
                            }
                            return listOf(header)
                        }
                    }
                }
            }
            // Union-source return drill: when the source return is a union (e.g.
            // `string | undefined`) and the target is not, append the FIRST failing
            // member so the chain shows `Type 'undefined' is not assignable to type
            // 'string'.` after the union line (interfaceClassMerging's method-return
            // mismatch). The caller indents these by +2 spaces.
            if (sourceReturn is Type.Union && targetReturn !is Type.Union) {
                val failing = sourceReturn.types.firstOrNull {
                    !checkTypeRelatedTo(it, targetReturn, assignableRelation)
                }
                if (failing != null) {
                    return listOf(
                        "  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.",
                        "    Type '${typeToString(failing)}' is not assignable to type '${typeToString(targetReturn)}'.",
                    )
                }
            }
            return listOf("  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
        }
        return emptyList()
    }

    /**
     * 17.11a: True when [type] (or any TypeParam reachable via Type.Reference args
     * / Union / Intersection) is one of the source-side TypeParam instances in
     * [sourceTps]. Used to gate the "could be instantiated with an arbitrary type"
     * elaboration so we don't substitute when source's return is a concrete type
     * unrelated to its own type parameters.
     */
    private fun sourceContainsTypeParam(type: Type, sourceTps: List<Type.TypeParam>): Boolean {
        return when (type) {
            is Type.TypeParam -> sourceTps.contains(type)
            is Type.Reference -> {
                val args = type.resolvedTypeArguments ?: return false
                args.any { sourceContainsTypeParam(it, sourceTps) }
            }
            is Type.Union -> type.types.any { sourceContainsTypeParam(it, sourceTps) }
            is Type.Intersection -> type.types.any { sourceContainsTypeParam(it, sourceTps) }
            else -> false
        }
    }

    /**
     * 17.40: Does any of `sig`'s param types or return type mention any TypeParam in
     * `tps`? Used to detect when an anonymous function-type parameter's signature
     * carries sig-side TypeParams that would need `unknown` substitution for display
     * in TS2345 messages (`(a: Iterator<T>) => number` → `(a: Iterator<unknown>) => number`
     * when the call provides no info to infer T).
     */
    private fun sigMentionsAnyTp(sig: Signature, tps: List<Type.TypeParam>): Boolean {
        val ret = sig.resolvedReturnType
        if (ret != null && sourceContainsTypeParam(ret, tps)) return true
        return sig.parameters.any { sourceContainsTypeParam(getTypeOfSymbol(it), tps) }
    }

    /**
     * Generate elaboration chain for an Object→Object type mismatch by
     * recursively comparing properties to find the deepest incompatible path.
     *
     * Returns lines like:
     *   "  Types of property 'x' are incompatible."
     *   "    Type 'number' is not assignable to type 'string'."
     * or for nested paths:
     *   "  The types of 'x.y' are incompatible between these types."
     *   "    Type 'string' is not assignable to type 'number'."
     */
    /**
     * Per-property TS2322 + TS6500 emission for object-literal initializers (var-decl,
     * property assignment) where the target is a known object type.
     *
     * Walks the source object literal's properties in source order. For each property
     * whose value type doesn't match the target's same-named property AND both sides
     * are simple-checkable (primitives / literals / all-primitive unions), emits a
     * TS2322 at the property KEY position with a TS6500 "expected type comes from"
     * related info pointing to the target property's declaration.
     *
     * Returns true if at least one TS2322 was emitted — caller should then suppress
     * the wider variable-name TS2322. Conservative: skips computed property names,
     * spread elements, methods, and shorthand property assignments.
     */
    private fun emitPerPropertyMismatchesForObjectLiteral(
        init: ObjectLiteralExpression,
        sourceType: Type.Object,
        targetType: Type.Object,
        displayTarget: String,
        source: String, fileName: String,
    ): Boolean {
        var emitted = false
        for (propNode in init.properties) {
            if (propNode !is PropertyAssignment) continue
            val nameNode = propNode.name
            val (propName, keyPos, keyLen) = when (nameNode) {
                is Identifier -> Triple(nameNode.text, nameNode.pos, nameNode.text.length)
                is NumericLiteralNode -> Triple(nameNode.text, nameNode.pos, nameNode.text.length)
                is StringLiteralNode -> Triple(
                    nameNode.text,
                    nameNode.pos,
                    (nameNode.rawText?.length ?: nameNode.text.length) + 2,
                )
                else -> continue
            }
            val targetProp = targetType.members?.get(propName) ?: continue
            // B490: instantiate the property type through a generic target (`I<string>`'s
            // `x` is `Comparable<string>`, not `Comparable<T>`) — getPropertyTypeForRelation
            // falls back to getTypeOfSymbol for non-Reference targets (no behavior change
            // for non-generic interfaces).
            val targetPropType = getPropertyTypeForRelation(targetType, targetProp)
            if (targetPropType === anyType || targetPropType === errorType) continue
            val sourceProp = sourceType.members?.get(propName) ?: continue
            val sourcePropType = getPropertyTypeForRelation(sourceType, sourceProp)
            if (sourcePropType === anyType || sourcePropType === errorType) continue
            if (checkTypeRelatedTo(sourcePropType, targetPropType, assignableRelation)) continue
            // Round 435: fresh literal prop value vs a literal-containing target member —
            // retry with the UN-widened literal type (see checkNestedObjLitPropTypes).
            if (propTypeContainsLiteral(targetPropType)) {
                val lit = literalTypeOfExpression(unwrapToObjLitValue(propNode.initializer))
                if (lit != null && checkTypeRelatedTo(lit, targetPropType, assignableRelation)) continue
            }
            // (CHK.32) a fresh ARRAY literal vs a TUPLE target member — the same
            // retry one shape over: `getTypeOfArrayLiteral` answers `number[]`
            // for `[a, b]`, and an array is not a tuple, so `range: [start, end]`
            // against a `Range = [number, number]` was a false TS2322 at the
            // property. Measured on the `yaml` library, where every CST token
            // carries one.
            val arrayValue = unwrapToObjLitValue(propNode.initializer) as? ArrayLiteralExpression
            if (arrayValue != null &&
                tupleTypeForArrayLiteralValue(arrayValue, targetPropType) != null
            ) {
                continue
            }
            // Deep-leaf descent (excessPropertyChecksWithNestedIntersections): when the
            // property VALUE is itself a FRESH object literal and the target prop type is an
            // object/intersection, tsc descends into it and reports the deepest simple-leaf
            // mismatch at the deepest key (`{ a: { x: 2 } }` vs `{ a: A }` → `number ≁ string`
            // at `x`), NOT a coarse chain at THIS key. Try the descent; on emit, suppress the
            // coarse chain here. The descent only fires for genuine simple-leaf mismatches, so
            // a property whose value mismatch is non-leaf (function type, etc.) falls through.
            val freshVal = unwrapToObjLitValue(propNode.initializer)
            if (freshVal is ObjectLiteralExpression &&
                (targetPropType is Type.Object || targetPropType is Type.Intersection) &&
                checkNestedObjLitPropTypes(freshVal, targetPropType, source, fileName)) {
                emitted = true
                continue
            }
            // B491 (deepElaborationsIntoArrowExpressions): the property value is an
            // arrow/fn returning a single expression and the target member is a
            // function type whose return is a simple/literal type that the arrow's
            // return violates (`{ y: () => "b" }` vs `{ y(): "a" }`). tsc reports at
            // the arrow's RETURN expression (`"b"`) with TS6502 ("the expected type
            // comes from the return type of this signature"), NOT at the property key
            // with a coarse fn-vs-fn chain. Drill there; suppress the coarse key emit.
            var drilledArrowReturn = false
            run {
                val targetSig = (targetPropType as? Type.Object)?.callSignatures?.singleOrNull()
                    ?.takeIf { it.typeParameters.isNullOrEmpty() } ?: return@run
                val targetRet = targetSig.resolvedReturnType ?: return@run
                if (targetRet === anyType || targetRet === errorType) return@run
                if (!isSimpleCheckableType(targetRet)) return@run
                val arrowRet = singleReturnExprOf(propNode.initializer) ?: return@run
                val srcRet = (literalTypeOfExpression(arrowRet)
                    ?: getTypeOfExpression(arrowRet))
                if (srcRet === anyType || srcRet === errorType) return@run
                if (checkTypeRelatedTo(srcRet, targetRet, assignableRelation)) return@run
                val start = arrowRet.pos
                val length = (expressionTrueEnd(arrowRet) - start).coerceAtLeast(1)
                val (l, c) = getLineAndCharacterOfPosition(source, start)
                val related = mutableListOf<Diagnostic>()
                val methodDecl = targetProp.declarations.firstOrNull()
                if (methodDecl != null) {
                    val mpos = when (methodDecl) {
                        is MethodDeclaration -> methodDecl.name.pos
                        is PropertyDeclaration -> methodDecl.name.pos
                        else -> methodDecl.pos
                    }
                    val (rl, rc) = getLineAndCharacterOfPosition(source, mpos)
                    related.add(Diagnostic(
                        message = "The expected type comes from the return type of this signature.",
                        category = DiagnosticCategory.Message, code = 6502,
                        fileName = fileName, line = rl, character = rc,
                        start = mpos, length = 1,
                    ))
                }
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(srcRet)}' is not assignable to type '${typeToString(targetRet)}'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = l, character = c,
                    start = start, length = length,
                    relatedInformation = related,
                ))
                emitted = true
                drilledArrowReturn = true
            }
            if (drilledArrowReturn) continue
            // B490 (genericAssignmentCompatWithInterfaces1): tsc reports a fresh object
            // literal's property mismatch ELEMENTWISE (at the property key, with the
            // value-type-vs-property-type elaboration chain), NOT as a collapsed whole-
            // object error at the var name. The original gate only handled SIMPLE
            // (primitive) property types; broaden to OBJECT property types via the same
            // elaboration chain the collapsed path uses — only when that chain is non-empty
            // (a real per-property elaboration), so we never emit a bare object-type error
            // where the engine can't explain the mismatch.
            val bothSimple = isSimpleCheckableType(targetPropType) && isSimpleCheckableType(sourcePropType)
            // B590 (assignmentToObjectAndFunction): a SIMPLE (primitive) source prop can
            // never have deeper structure, so a flat per-property leaf at the key is always
            // tsc-correct even when the target prop type is NON-simple (e.g. `toString: 0`
            // vs `Object.toString: () => string` → `Type 'number' ≁ '() => string'` at the
            // `toString` key, NOT a coarse whole-object chain at the var name). Mirrors
            // B482ext's `checkNestedObjLitPropTypes` simple-leaf rule.
            val srcSimple = isSimpleCheckableType(sourcePropType)
            val objChain: List<String>? = if (!bothSimple) {
                if (srcSimple) null
                else if (sourcePropType is Type.Object && targetPropType is Type.Object) {
                    getPropertyElaborationChain(sourcePropType, targetPropType)?.takeIf { it.isNotEmpty() } ?: continue
                } else continue
            } else null
            val displaySource = typeToString(getWidenedLiteralType(sourcePropType))
            val displayTargetProp = typeToString(getWidenedLiteralType(targetPropType))
            val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
            val related = mutableListOf<Diagnostic>()
            val tpDecl = targetProp.declarations.firstOrNull()
            // B590: tsc attaches NO TS6500 "expected type comes from property" when the
            // target prop is declared in a builtin lib interface (e.g. `Object.toString`).
            if (tpDecl != null && tpDecl !in builtinLibMemberDecls) {
                val declPos = when (tpDecl) {
                    is PropertyDeclaration -> tpDecl.name.pos
                    is PropertyAssignment -> tpDecl.name.pos
                    else -> tpDecl.pos
                }
                val (dline, dchar) = getLineAndCharacterOfPosition(source, declPos)
                related.add(Diagnostic(
                    message = "The expected type comes from property '$propName' which is declared here on type '$displayTarget'",
                    category = DiagnosticCategory.Message,
                    code = 6500,
                    fileName = fileName,
                    line = dline,
                    character = dchar,
                    start = declPos,
                    length = propName.length,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$displayTargetProp'.",
                category = DiagnosticCategory.Error,
                code = 2322,
                fileName = fileName,
                line = kline,
                character = kchar,
                start = keyPos,
                length = keyLen,
                messageChain = objChain ?: emptyList(),
                relatedInformation = related,
            ))
            emitted = true
        }
        return emitted
    }

    /**
     * B252: third sibling of the B138 index-signature pre-check family — a FRESH
     * object-literal initializer property whose value is a FUNCTION LITERAL whose
     * inferred RETURN type is an array of an anonymous object that violates the
     * contextual return's index-sig-ONLY element interface
     * (`{ f: (w) => [{'k': bad}] }` vs `{ f?: (w) => NamedTransform[] }` where
     * `NamedTransform` has only `[name: string]: Transform3D`). The relation engine
     * passes (index-sig value-types are deliberately unchecked there — B138 gotcha),
     * so this PRE-check fires the TS2322 + 4-level chain + TS6500 related info at the
     * property NAME (contextualTypeArrayReturnType). First failing property only.
     */
    private fun checkObjectLiteralFnPropReturnIndexSig(
        init: ObjectLiteralExpression,
        sourceType: Type.Object,
        targetType: Type.Object,
        typeAnnotation: TypeNode?,
        source: String, fileName: String,
    ): Boolean {
        resolveStructuredTypeMembers(targetType)
        for (propNode in init.properties) {
            if (propNode !is PropertyAssignment) continue
            if (propNode.initializer !is ArrowFunction && propNode.initializer !is FunctionExpression) continue
            val nameNode = propNode.name
            val (propName, keyPos, keyLen) = when (nameNode) {
                is Identifier -> Triple(nameNode.text, nameNode.pos, nameNode.text.length)
                is NumericLiteralNode -> Triple(nameNode.text, nameNode.pos, nameNode.text.length)
                is StringLiteralNode -> Triple(
                    nameNode.text, nameNode.pos,
                    (nameNode.rawText?.length ?: nameNode.text.length) + 2,
                )
                else -> continue
            }
            val targetProp = targetType.members?.get(propName) ?: continue
            val tgtPropType = getTypeOfSymbol(targetProp) as? Type.Object ?: continue
            val tgtSig = tgtPropType.callSignatures?.singleOrNull() ?: continue
            if (!tgtPropType.constructSignatures.isNullOrEmpty()) continue
            if (!tgtPropType.properties.isNullOrEmpty()) continue
            val tgtRet = tgtSig.resolvedReturnType as? Type.Reference ?: continue
            if (tgtRet.target.symbol?.name != "Array") continue
            val tgtElem = tgtRet.resolvedTypeArguments?.singleOrNull() as? Type.Object ?: continue
            resolveStructuredTypeMembers(tgtElem)
            val idxValType = tgtElem.stringIndexInfo?.type ?: continue
            if (idxValType === anyType || idxValType === errorType || idxValType === unknownType) continue
            if (!tgtElem.members.isNullOrEmpty()) continue
            val sourceProp = sourceType.members?.get(propName) ?: continue
            val srcPropType = getTypeOfSymbol(sourceProp) as? Type.Object ?: continue
            val srcSig = srcPropType.callSignatures?.singleOrNull() ?: continue
            val srcRet = srcSig.resolvedReturnType as? Type.Reference ?: continue
            if (srcRet.target.symbol?.name != "Array") continue
            val srcElem = srcRet.resolvedTypeArguments?.singleOrNull() as? Type.Object ?: continue
            if (srcElem is Type.Reference || srcElem.symbol != null) continue
            if (srcElem.stringIndexInfo != null || srcElem.numberIndexInfo != null) continue
            val srcProps = srcElem.properties ?: continue
            if (srcProps.isEmpty()) continue
            for (p in srcProps) {
                val pType = getTypeOfSymbol(p)
                if (pType === anyType || pType === errorType) continue
                // relation-reliability gate (mirrors B138): at least one side primitive
                if (!isSimpleCheckableType(pType) && !isSimpleCheckableType(idxValType)) continue
                if (checkTypeRelatedTo(pType, idxValType, assignableRelation)) continue
                // quoted display: a string-literal-keyed source property keeps its
                // source quote char UNCONDITIONALLY (baseline shows ''ry'' even though
                // 'ry' is identifier-valid — do NOT use formatPropertyDisplayName)
                val pDeclName = (p.declarations.firstOrNull() as? PropertyAssignment)?.name
                val quotedName = if (pDeclName is StringLiteralNode) {
                    val q = if (pDeclName.singleQuote) "'" else "\""
                    "$q${p.name}$q"
                } else p.name
                val tgtPropDisplay =
                    (targetProp.declarations.firstOrNull() as? PropertyDeclaration)?.type
                        ?.let { formatTypeForDisplay(it) }
                        ?: typeToString(tgtPropType)
                val related = mutableListOf<Diagnostic>()
                val tpDecl = targetProp.declarations.firstOrNull()
                if (tpDecl is PropertyDeclaration) {
                    val (dline, dchar) = getLineAndCharacterOfPosition(source, tpDecl.name.pos)
                    related.add(Diagnostic(
                        message = "The expected type comes from property '$propName' which is declared here on type " +
                            "'${typeAnnotation?.let { formatTypeForDisplay(it) } ?: typeToString(targetType)}'",
                        category = DiagnosticCategory.Message, code = 6500,
                        fileName = fileName, line = dline, character = dchar,
                        start = tpDecl.name.pos, length = propName.length,
                    ))
                }
                val (kline, kchar) = getLineAndCharacterOfPosition(source, keyPos)
                diagnostics.add(Diagnostic(
                    message = "Type '${typeToString(srcPropType)}' is not assignable to type '$tgtPropDisplay'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = kline, character = kchar,
                    start = keyPos, length = keyLen,
                    messageChain = listOf(
                        "  Type '${typeToString(srcRet)}' is not assignable to type '${typeToString(tgtRet)}'.",
                        "    Type '${typeToString(srcElem)}' is not assignable to type '${typeToString(tgtElem)}'.",
                        "      Property '$quotedName' is incompatible with index signature.",
                        "        Type '${typeToString(getWidenedLiteralType(pType))}' is not assignable to type '${typeToString(idxValType)}'.",
                    ),
                    relatedInformation = related,
                ))
                return true
            }
        }
        return false
    }

    /**
     * unionTypeWithRecursiveSubtypeReduction2: gate for the Union→Object elaboration
     * drill (CHANGE 1/2 in getPropertyElaborationChain). TIGHT gate — round 96 reverted
     * an UNtightened version (covering ~167 baselines, a hidden +1 regression). Fire ONLY
     * when the source union's constituents are ALL bare named class/interface INSTANCE
     * object types and the target is a single bare named object type. A corpus scan for
     * an all-named-union-vs-bare-named-target truncation returns ONLY this test (tsc
     * ALWAYS drills there), so adding the drill matches tsc everywhere it applies.
     */
    private fun unionToObjectDrillApplies(source: Type.Union, target: Type.Object): Boolean {
        if (!isBareNamedObjectType(target)) return false
        if (source.types.isEmpty()) return false
        return source.types.all { isBareNamedObjectType(it) }
    }

    private fun isBareNamedObjectType(t: Type): Boolean {
        if (t !is Type.Object) return false
        val s = typeToString(t)
        if (s.isEmpty() || s[0].isDigit()) return false
        if (!s.all { it.isLetterOrDigit() || it == '_' || it == '$' }) return false
        return s !in BARE_NAMED_OBJECT_TYPE_EXCLUDE
    }

    /** For a SUBCLASS-of-Array source (`class C<T> extends Array<T>` instantiated as
     *  `C<A>`), resolve the element type flowing into the `Array`/`ReadonlyArray`
     *  base (here `A`). Mirrors the B75.2 base-type walk used by the relation engine.
     *  Returns null if `source.target` is not a class deriving (directly) from an
     *  Array-shaped base. */
    private fun arrayElementTypeOfSubclass(source: Type.Reference): Type? {
        val srcInterface = source.target
        if (srcInterface.baseTypes == null) resolveBaseTypesLazy(srcInterface)
        val srcBaseTypes = srcInterface.baseTypes ?: return null
        val srcTypeParams = srcInterface.typeParameters ?: emptyList()
        val srcInstArgs = source.resolvedTypeArguments ?: emptyList()
        if (srcTypeParams.size != srcInstArgs.size) return null
        val mapper = createTypeMapper(srcTypeParams, srcInstArgs)
        for (baseType in srcBaseTypes) {
            val baseRef = baseType as? Type.Reference ?: continue
            if (baseRef.target !== globalArrayType && baseRef.target !== globalReadonlyArrayType) continue
            val baseArgs = baseRef.resolvedTypeArguments ?: continue
            if (baseArgs.size != 1) continue
            return instantiateType(baseArgs[0], mapper)
        }
        return null
    }

    private fun getPropertyElaborationChain(
        source: Type,
        target: Type,
        path: String = "",
    ): List<String>? {
        // 17.42: handle Type.Intersection source by merging members from object-like
        // constituents. For `Type.Intersection({fooProp: string}, Bar)` vs target
        // `FooBar`, the merged source has `fooProp: string` and `barProp: string`,
        // and a target prop like `fooProp: boolean` produces the standard
        // "Types of property 'fooProp' are incompatible. Type 'string' is not
        // assignable to type 'boolean'." chain. Pairs with 17.41's substitution
        // (so the pre-substitution `T & Bar` source becomes `{...} & Bar`).
        if (source is Type.Intersection && target is Type.Object) {
            return getIntersectionPropertyElaborationChain(source, target, path)
        }
        // B413: Intersection → Intersection elaboration for discriminated intersections
        // (errorMessageOnIntersectionsWithDiscriminants01). For `A = Common & {foo:1}` vs
        // `B = Common & {bar:1}` where Common is a discriminated union, tsc distributes the
        // source intersection-of-union into constituents, reports the first failing
        // constituent against the target alias, then drills into the discriminant-matched
        // target constituent and its missing required property. Purely additive: returns
        // null (no behavior change) for any shape it doesn't recognize.
        if (source is Type.Intersection && target is Type.Intersection) {
            getDiscriminatedIntersectionElaboration(source, target)?.let { return it }
        }
        // B50.4: Object → Union elaboration — emit the per-level "Type X vs '<union>'"
        // line, then drill into the best-matching constituent with "Type X vs '<best>'"
        // + nested chain. Resets `path` so the constituent's per-property chain
        // doesn't carry the outer caller's path prefix. Matches TypeScript's chain
        // shape for `typeAssignabilityErrorMessage_ts`-style cases.
        if (source is Type.Object && target is Type.Union) {
            val best = findBestUnionConstituent(source, target)
            if (best is Type.Object) {
                val perLevel = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                val drillIn = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(best)}'."
                val deeper = getPropertyElaborationChain(source, best, "")
                return if (deeper != null) {
                    listOf(perLevel) + listOf("  $drillIn") + deeper.map { "    $it" }
                } else {
                    listOf(perLevel, "  $drillIn")
                }
            }
            return null
        }
        // unionTypeWithRecursiveSubtypeReduction2 (CHANGE 1): Union → Object elaboration,
        // the inverse of the Object→Union branch above. The relation engine reduces a
        // union source to its failing constituent; tsc emits "Type '<union>' is not
        // assignable to type '<target>'." then either the missing-required-property
        // terminal (OMITTING a per-constituent line — `c = p` shape) or the failing
        // constituent's structural chain WITH a per-constituent "Type '<failing>' is not
        // assignable to type '<target>'." line (nested `p = c` shape). Picks the LAST
        // failing constituent (tsc reports the last on a tie). Tight corpus-unique gate.
        if (source is Type.Union && target is Type.Object && unionToObjectDrillApplies(source, target)) {
            val failing = source.types.lastOrNull {
                !checkTypeRelatedTo(it, target, assignableRelation)
            } as? Type.Object
            if (failing != null) {
                val perLevel = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                val deeper = getPropertyElaborationChain(failing, target, "")
                return if (deeper != null) {
                    if (deeper.first().trimStart().startsWith("Property '")) {
                        // missing-required-property terminal — no per-constituent line
                        listOf(perLevel) + deeper.map { "  $it" }
                    } else {
                        // structural chain — include the per-constituent line
                        listOf(
                            perLevel,
                            "    Type '${typeToString(failing)}' is not assignable to type '${typeToString(target)}'.",
                        ) + deeper.map { "    $it" }
                    }
                } else {
                    val missing = getMissingRequiredPropertySymbol(failing, target)
                    if (missing != null) {
                        listOf(
                            perLevel,
                            "    Property '${missing.name}' is missing in type '${typeToString(failing)}' but required in type '${typeToString(target)}'.",
                        )
                    } else listOf(perLevel)
                }
            }
            return null
        }
        if (source !is Type.Object || target !is Type.Object) return null
        // B58.2: tuple-tuple elaboration uses "Type at position N in source is
        // not compatible with type at position N in target." per TypeScript
        // convention. When both sides have tupleElementTypes and the same arity,
        // iterate positionally and emit per-mismatch chain.
        val srcTuple = source.tupleElementTypes
        val tgtTuple = target.tupleElementTypes
        if (srcTuple != null && tgtTuple != null && srcTuple.size == tgtTuple.size) {
            for (i in srcTuple.indices) {
                val sElem = srcTuple[i]
                val tElem = tgtTuple[i]
                if (!checkTypeRelatedTo(sElem, tElem, assignableRelation)) {
                    val chain = mutableListOf<String>()
                    chain.add("  Type at position $i in source is not compatible with type at position $i in target.")
                    chain.add("    Type '${typeToString(sElem)}' is not assignable to type '${typeToString(tElem)}'.")
                    return chain
                }
            }
            return null
        }
        // Cycle detection: don't re-enter elaboration for the same type pair
        val pairKey = packRelationKey(source.id, target.id)
        if (MapCensus.boxedKeyCensus) MapCensus.bk(MapCensus.BK_ELAB, pairKey)
        if (pairKey in state.elaborationStack) return null
        if (MapCensus.boxedKeyCensus) {
            MapCensus.bk(MapCensus.BK_ELAB, pairKey)
            MapCensus.bkPush(MapCensus.BK_ELAB)
        }
        state.elaborationStack.add(pairKey)
        try {
            // B75.3: Plain `Array<U>` source vs `ReadonlyArray<T>` target — elaborate
            // the ELEMENT pair directly (covariant). Without this, falling through to
            // `propertiesRelatedTo` produces a misleading `concat` method chain even
            // though TypeScript correctly reports the element-type mismatch as a
            // missing-required-property line. Matches the pre-B75.1 behavior where
            // Array and ReadonlyArray collapsed onto the same target.
            //
            // Scope: source.target === globalArrayType (plain Array<U>), NOT subclass
            // of Array. Subclass-of-Array (e.g. `class C<T> extends Array<T>`) keeps
            // the structural concat-chain (TypeScript renders that for named subclasses).
            if (source is Type.Reference && target is Type.Reference &&
                globalReadonlyArrayType != null &&
                target.target === globalReadonlyArrayType &&
                source.target === globalArrayType) {
                val srcArgs = source.resolvedTypeArguments
                val tgtArgs = target.resolvedTypeArguments
                if (srcArgs != null && tgtArgs != null && srcArgs.size == 1 && tgtArgs.size == 1) {
                    val sa = srcArgs[0]
                    val ta = tgtArgs[0]
                    if (!checkTypeRelatedTo(sa, ta, assignableRelation)) {
                        val argChain = if (sa is Type.Object && ta is Type.Object) {
                            getPropertyElaborationChain(sa, ta, "")
                        } else null
                        return if (path.isEmpty()) {
                            val header = "  Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'."
                            if (argChain != null) {
                                val firstTrimmed = argChain.first().trimStart()
                                if (firstTrimmed.startsWith("Property '")) {
                                    argChain
                                } else {
                                    listOf(header) + argChain.map { "  $it" }
                                }
                            } else {
                                listOf(header)
                            }
                        } else {
                            val ctx = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                            if (argChain != null) {
                                listOf(ctx) + argChain.map { "  $it" }
                            } else {
                                listOf(ctx, "    Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'.")
                            }
                        }
                    }
                }
            }
            // arrayOfSubtypeIsAssignableToReadonlyArray: SUBCLASS-of-Array source
            // (`class C<T> extends Array<T>` → `C<A>`) vs `ReadonlyArray<T>` target.
            // tsc elaborates the `concat(...)` RETURN-type collapse —
            //   "The types returned by 'concat(...)' are incompatible...
            //      Type 'A[]' is not assignable to type 'B[]'...
            //        Property 'b' is missing in type 'A' but required in type 'B'."
            // — NOT the param-contravariance `concat` method chain the general property
            // iteration produces (which also wrongly reports `B[]` not assignable to
            // `A[]`). The relation engine's B75.2 covariant shortcut already decided
            // assignability via the source's Array-ancestor element type; mirror that
            // extraction to build the correct elaboration. The plain-Array case is owned
            // by the B75.3 branch above (`source.target === globalArrayType`), so this
            // gates to a genuine subclass. Corpus-unique: the only subclass-of-Array vs
            // ReadonlyArray FAILING assignment in the corpus (0 baselines rely on the old
            // chain; the only other such-shaped test passes → elaboration unreached).
            if (source is Type.Reference && target is Type.Reference &&
                globalReadonlyArrayType != null &&
                target.target === globalReadonlyArrayType &&
                source.target !== globalArrayType &&
                source.target !== globalReadonlyArrayType) {
                val srcElem = arrayElementTypeOfSubclass(source)
                val tgtArgs = target.resolvedTypeArguments
                if (srcElem != null && tgtArgs != null && tgtArgs.size == 1) {
                    val tgtElem = tgtArgs[0]
                    if (!checkTypeRelatedTo(srcElem, tgtElem, assignableRelation)) {
                        val chain = mutableListOf<String>()
                        chain.add("  The types returned by 'concat(...)' are incompatible between these types.")
                        chain.add("    Type '${typeToString(srcElem)}[]' is not assignable to type '${typeToString(tgtElem)}[]'.")
                        val deeper = if (srcElem is Type.Object && tgtElem is Type.Object) {
                            getPropertyElaborationChain(srcElem, tgtElem, "")
                        } else null
                        if (deeper != null) {
                            chain.addAll(deeper.map { "    $it" })
                        } else if (srcElem is Type.Object && tgtElem is Type.Object) {
                            val missing = getMissingRequiredPropertySymbol(srcElem, tgtElem)
                            if (missing != null) {
                                lastChainMissingPropSymbol = missing
                                chain.add("      Property '${missing.name}' is missing in type '${typeToString(srcElem)}' but required in type '${typeToString(tgtElem)}'.")
                            }
                        }
                        return chain
                    }
                }
            }
            // Generic ref mismatch: when source and target share a target interface but
            // differ in type arguments (e.g. `Bar<string>` vs `Bar<number>`), elaborate
            // with the first failing arg pair. For top-level (path == "") the main
            // TS2322 message already shows "Type 'A<X>' vs 'A<Y>'.", so emit only the
            // deeper chain. For nested calls (path != "") include a context line at
            // this level so the chain reads "  Types of prop X incompatible.
            //   Type 'A<X>[]' vs 'A<Y>[]'.    Type 'X' vs 'Y'."
            if (source is Type.Reference && target is Type.Reference &&
                source.target === target.target) {
                val sourceArgs = source.resolvedTypeArguments
                val targetArgs = target.resolvedTypeArguments
                if (sourceArgs != null && targetArgs != null && sourceArgs.size == targetArgs.size) {
                    for (i in sourceArgs.indices) {
                        val sa = sourceArgs[i]
                        val ta = targetArgs[i]
                        if (!checkTypeRelatedTo(sa, ta, assignableRelation)) {
                            // Try richer elaboration when both args are object types.
                            // unionTypeWithRecursiveSubtypeReduction2 (CHANGE 2): a UNION
                            // element (`(Class | Property)[]` vs `Class[]`) drills via the
                            // Union→Object branch (CHANGE 1, same tight gate).
                            val argChain = if (sa is Type.Object && ta is Type.Object) {
                                getPropertyElaborationChain(sa, ta, "")
                            } else if (sa is Type.Union && ta is Type.Object &&
                                unionToObjectDrillApplies(sa, ta)) {
                                getPropertyElaborationChain(sa, ta, "")
                            } else null
                            return if (path.isEmpty()) {
                                val header = "  Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'."
                                if (argChain != null) {
                                    // Skip the header when argChain's first line is a
                                    // "Property 'X' is missing in type 'A' but required
                                    // in type 'B'." terminal — that line already mentions
                                    // both source and target type names so the header is
                                    // redundant (matches TypeScript's `promisesWithConstraints`-
                                    // style output). For deeper structural chains
                                    // ("The types returned by '...'", "Types of property '...'",
                                    // etc.), include the header to identify the parent
                                    // arg pair being compared (matches `generics4`-style output).
                                    val firstTrimmed = argChain.first().trimStart()
                                    // B559: both the single-prop "Property 'X' is missing…"
                                    // and the multi-prop "Type 'X' is missing the following
                                    // properties from type 'Y': …" lines are missing-property
                                    // TERMINALS that already name both types → no header.
                                    if (firstTrimmed.startsWith("Property '") ||
                                        firstTrimmed.contains("is missing the following properties")) {
                                        argChain
                                    } else {
                                        listOf(header) + argChain.map { "  $it" }
                                    }
                                } else {
                                    listOf(header)
                                }
                            } else {
                                val ctx = "  Type '${typeToString(source)}' is not assignable to type '${typeToString(target)}'."
                                if (argChain != null) {
                                    listOf(ctx) + argChain.map { "  $it" }
                                } else {
                                    listOf(ctx, "    Type '${typeToString(sa)}' is not assignable to type '${typeToString(ta)}'.")
                                }
                            }
                        }
                    }
                }
            }
            resolveStructuredTypeMembers(source)
            resolveStructuredTypeMembers(target)
            val targetProps = target.properties ?: return null
            val sourceMembers = source.members ?: return null

            // Private-brand mismatch: emit the nominal-brand elaboration for the first
            // property that's declared private on both sides in different classes.
            for (targetProp in targetProps) {
                val sourceProp = sourceMembers[targetProp.name] ?: continue
                if (isPropPrivateBrandMismatch(sourceProp, targetProp)) {
                    return listOf("  Types have separate declarations of a private property '${targetProp.name}'.")
                }
            }

            // 17.14c: Asymmetric privacy mismatch — target has a private property whose
            // source counterpart isn't private (or vice versa). Matches TypeScript's
            // "Property 'X' is private in type 'A' but not in type 'B'." for the
            // `assignmentCompatability40-42` family. Emitted at the FIRST asymmetric
            // mismatch — symmetric brand mismatches above take precedence.
            for (targetProp in targetProps) {
                val sourceProp = sourceMembers[targetProp.name] ?: continue
                val tDecl = targetProp.valueDeclaration ?: targetProp.declarations.firstOrNull()
                val sDecl = sourceProp.valueDeclaration ?: sourceProp.declarations.firstOrNull()
                if (tDecl == null || sDecl == null) continue
                val tPriv = isMemberPrivate(tDecl)
                val sPriv = isMemberPrivate(sDecl)
                if (tPriv && !sPriv) {
                    return listOf("  Property '${targetProp.name}' is private in type '${typeToString(target)}' but not in type '${typeToString(source)}'.")
                }
                if (sPriv && !tPriv) {
                    return listOf("  Property '${targetProp.name}' is private in type '${typeToString(source)}' but not in type '${typeToString(target)}'.")
                }
            }

            // Collect all incompatible properties
            data class IncompatibleProp(
                val name: String,
                val sourceType: Type,
                val targetType: Type,
                val sourceWidenedForOptional: Boolean,
            )
            val incompatible = mutableListOf<IncompatibleProp>()
            for (targetProp in targetProps) {
                val targetName = targetProp.name
                val sourceProp = sourceMembers[targetName] ?: continue
                // Use substituted property types (Blocker #1 step (b)/(d)) so generic
                // inheritance mismatches like `B<number> extends A<string>` produce
                // "Types of property 'x' are incompatible. Type 'string' is not
                // assignable to type 'number'." instead of falling out silently.
                val sourcePropType = getPropertyTypeForRelation(source, sourceProp)
                val effectiveSource = widenOptionalSourcePropType(sourcePropType, sourceProp, targetProp)
                val targetPropType = widenOptionalTargetPropType(getPropertyTypeForRelation(target, targetProp), targetProp, effectiveSource)
                val sourceWidened = effectiveSource !== sourcePropType
                if (!checkTypeRelatedTo(effectiveSource, targetPropType, assignableRelation)) {
                    incompatible.add(IncompatibleProp(targetName, effectiveSource, targetPropType, sourceWidened))
                }
            }
            if (incompatible.isEmpty()) {
                // No property-type mismatch — try the missing-required-property path.
                // Matches `propertiesRelatedTo`'s missing-prop logic so structural
                // failures via missing members still produce an informative chain
                // (e.g. `Animal[]` vs `Giraffe[]` → "Property 'g' is missing in
                // type 'Animal' but required in type 'Giraffe'.").
                val missing = getMissingRequiredPropertySymbol(source, target)
                if (missing != null) {
                    // B559: tsc reports ≥2 missing required props as a single
                    // "Type 'X' is missing the following properties from type 'Y': a, b"
                    // line (own-members-first), and exactly 1 as "Property 'X' is missing
                    // in type 'Y' but required in type 'Z'." (Our leaf previously always
                    // used the single-prop form.) Gate kept at `missing != null` so this
                    // only changes the FORMAT, never whether the chain line appears.
                    val allMissing = collectMissingProperties(source, target)
                    return if (allMissing.size >= 2) {
                        // tsc attaches NO single "declared here" TS2728 for a multi-prop
                        // missing line (there is no single property to point at), so clear
                        // the symbol `getMissingRequiredPropertySymbol` just set.
                        lastChainMissingPropSymbol = null
                        val own = if (target is Type.Interface) ownInstanceMemberNamesOfInterface(target) else emptyList()
                        val ordered = own.filter { it in allMissing } + allMissing.filter { it !in own }
                        listOf("  " + formatTs2740Message(typeToString(source), typeToString(target), ordered))
                    } else {
                        listOf(
                            "  Property '${missing.name}' is missing in type '${typeToString(source)}' but required in type '${typeToString(target)}'."
                        )
                    }
                }
                return null
            }

            // Prefer leaf mismatches (non-Object types) over recursive ones
            // This avoids following circular property paths (A.p→D→C.q→B→A.p...)
            // when there's a direct primitive mismatch like A.s:string vs B.s:number
            // B50.4: Object→Union prop pair is NOT a leaf — the top-of-function
            // Object→Union branch can drill into the best constituent. Only treat
            // truly-non-Object sources/targets as leaves.
            val leaf = incompatible.firstOrNull {
                (it.sourceType !is Type.Object && it.sourceType !is Type.Union) ||
                (it.targetType !is Type.Object && it.targetType !is Type.Union)
            }
            val chosen = leaf ?: incompatible.first()

            val propPath = if (path.isEmpty()) chosen.name else "$path.${chosen.name}"
            val outerLine = if (path.isEmpty()) {
                "  Types of property '${chosen.name}' are incompatible."
            } else {
                "  The types of '$propPath' are incompatible between these types."
            }
            // Try to go deeper into nested object properties (if not a leaf)
            if (leaf == null) {
                // B86.7c: nested nullable-target collapse. When the chosen property's
                // source is an Object and its target is a Union of exactly ONE
                // non-nullish Object constituent + nullish-only siblings (e.g. source
                // `{ bar: ... }` vs target `{ bar: ... } | undefined`), TypeScript does
                // NOT emit the per-level Object→Union drill-in chain. It collapses
                // directly through the single non-nullish constituent, carrying the
                // property path so the deeper line reads "The types of 'foo.bar' are
                // incompatible between these types." Recurse into the non-nullish
                // constituent with the SAME propPath (collapsed form), preserving the
                // outer chain shape. Gate is narrow: exactly one non-nullish Object
                // constituent, all other constituents nullish.
                val sObj = chosen.sourceType as? Type.Object
                val tUnion = chosen.targetType as? Type.Union
                if (sObj != null && tUnion != null) {
                    val nonNullish = tUnion.types.filterNot { isNullishConstituent(it) }
                    if (nonNullish.size == 1 && nonNullish[0] is Type.Object) {
                        val collapsed = getPropertyElaborationChain(sObj, nonNullish[0], propPath)
                        if (collapsed != null &&
                            collapsed.first().trimStart().startsWith("The types of '")) {
                            return collapsed
                        }
                    }
                }
                val deeper = getPropertyElaborationChain(chosen.sourceType, chosen.targetType, propPath)
                if (deeper != null) {
                    // Two chain forms depending on what the deeper recursion produced:
                    //   1. **Collapsed form** — pure Object property nesting (no
                    //      Array/Reference elements in the middle). Deeper's first
                    //      line already reads "The types of '$propPath' are
                    //      incompatible between these types." naming the full path,
                    //      so the outer need not prepend its own "Types of property
                    //      'x' are incompatible." line. Matches TypeScript's
                    //      collapsed chain (e.g. `multiLineErrors_ts`).
                    //   2. **Per-level form** — chain went through an Array/Reference
                    //      element in the middle (deeper's first line starts with
                    //      "Type 'A[]' is not assignable to type 'B[]'." from the
                    //      same-target-ref shortcut). The path context isn't in the
                    //      deeper line, so we prepend the outer "Types of property
                    //      'X' are incompatible." line and indent the deeper chain
                    //      by 2 more spaces (e.g. `typeMatch2_ts`'s `{ f2: Animal[] }`
                    //      vs `{ f2: Giraffe[] }`).
                    val isCollapsed = deeper.first().trimStart().startsWith("The types of '")
                    return if (isCollapsed) deeper
                        else listOf(outerLine) + deeper.map { "  $it" }
                }
            }
            // Report at this level
            val sourcePropStr = typeToString(chosen.sourceType)
            val targetPropStr = typeToString(chosen.targetType)
            // Method-property collapsed form: when both prop types are pure function
            // types (call signatures only, no own properties/members) AND the
            // function-mismatch elaboration produces exactly one line — which is the
            // case for return-type-only mismatch, since param mismatch returns two
            // lines via `Types of parameters '...' incompatible.` — TypeScript collapses
            // the chain to "The types returned by 'X()' are incompatible between these
            // types." instead of "Types of property 'X' are incompatible. Type '() => A'
            // is not assignable to type '() => B'." (cf. `generics4_ts`'s `f(): boolean`
            // vs `f(): string`). For param mismatches and arity mismatches, fall through
            // to the standard "Types of property" + function-type-display + funcExtra path.
            val srcObjForCollapse = chosen.sourceType as? Type.Object
            val tgtObjForCollapse = chosen.targetType as? Type.Object
            val funcMismatch: List<String>? = if (
                srcObjForCollapse != null && tgtObjForCollapse != null &&
                !srcObjForCollapse.callSignatures.isNullOrEmpty() &&
                !tgtObjForCollapse.callSignatures.isNullOrEmpty() &&
                srcObjForCollapse.properties.isNullOrEmpty() &&
                tgtObjForCollapse.properties.isNullOrEmpty() &&
                srcObjForCollapse.members.isNullOrEmpty() &&
                tgtObjForCollapse.members.isNullOrEmpty()
            ) {
                getFunctionMismatchElaboration(srcObjForCollapse, tgtObjForCollapse)
            } else null
            // Use collapsed "types returned by" form for return-type mismatch.
            // funcMismatch's first line is "  Type 'A' is not assignable to type 'B'.".
            // Arity mismatch ("Target signature provides too few...") and param mismatch
            // ("Types of parameters...") keep the standard "Types of property" + function-
            // type-display + funcExtra format.
            // B75.3: funcMismatch may now have MULTIPLE lines when the return type
            // drills deeper into a generic element pair (e.g. `A[]` vs `B[]` →
            // `Property 'b' is missing...`). The deeper lines are property-drill chains,
            // not param-mismatch chains, so the collapsed "types returned by" form is
            // still appropriate. Gate on FIRST line shape only.
            if (funcMismatch != null && funcMismatch.isNotEmpty() &&
                funcMismatch[0].trimStart().startsWith("Type '")) {
                // B75.2: TypeScript renders the method-name suffix as `(...)` when the
                // target signature has at least one parameter, `()` when it has none.
                // Mirrors `Type '() => A' is not assignable to type '() => B'.` collapsed
                // header convention. Use target's first call signature's parameter list
                // (we already passed the `!callSignatures.isNullOrEmpty()` gate above).
                val tgtFirstSig = tgtObjForCollapse!!.callSignatures!!.first()
                val parenSuffix = if (tgtFirstSig.parameters.isNotEmpty()) "(...)" else "()"
                val collapsedHeader = if (path.isEmpty()) {
                    "  The types returned by '${chosen.name}$parenSuffix' are incompatible between these types."
                } else {
                    "  The types returned by '$propPath$parenSuffix' are incompatible between these types."
                }
                return listOf(collapsedHeader) + funcMismatch.map { "  $it" }
            }
            // If the chosen mismatched property is a function (call signatures only),
            // append parameter-mismatch / return-type lines to deepen the chain.
            // The chain line ("    Type 'A' is not assignable to type 'B'.") sits at
            // 4-space depth; the function-mismatch lines sit two levels deeper at
            // 6 and 8 spaces. `getFunctionMismatchElaboration` emits at 2/4 spaces,
            // so prepend 4 extra spaces to each line.
            val funcExtra: List<String> = run {
                val srcObj = chosen.sourceType as? Type.Object ?: return@run emptyList()
                val tgtObj = chosen.targetType as? Type.Object ?: return@run emptyList()
                if (srcObj.callSignatures.isNullOrEmpty() || tgtObj.callSignatures.isNullOrEmpty()) {
                    return@run emptyList()
                }
                getFunctionMismatchElaboration(srcObj, tgtObj).map { "    $it" }
            }
            // When the source prop was widened from `T` to `T | undefined` because the
            // source declares it optional but the target requires it (strictNullChecks),
            // add the deeper "Type 'undefined' is not assignable to type '$target'." chain
            // line to match TypeScript's elaboration depth (cf. `assignmentCompatability11`,
            // `…15`, `…21`, `…25`, `…39`, `…43`, etc.).
            val undefinedExtra: List<String> = if (chosen.sourceWidenedForOptional) {
                listOf("      Type 'undefined' is not assignable to type '$targetPropStr'.")
            } else emptyList()
            // B86.7c: per-failing-constituent elaboration for Union sources. When the
            // source prop type is a Union and the leaf line "Type '<union>' is not
            // assignable to type '<target>'." is emitted, TypeScript follows it with a
            // sub-line naming the SPECIFIC constituent that fails (e.g. for
            // `number | undefined` vs `string | null`, the `undefined` member is the
            // elaborated failing constituent). Gate is narrow: only fire when source is
            // a Union, no funcExtra/undefinedExtra already applies, and at least one
            // constituent genuinely fails assignability to the target prop type.
            // Prefer the nullish failing constituent (matches TypeScript's display
            // ordering for nullable targets); fall back to the first failing one.
            val unionConstituentExtra: List<String> =
                if (chosen.sourceType is Type.Union && undefinedExtra.isEmpty() && funcExtra.isEmpty()) {
                    // Narrow gate: only elaborate when the failing constituent is NULLISH
                    // (null/undefined/void). Non-nullish failing constituents (e.g. a
                    // plain `number` vs `string | null`) are NOT shown by TypeScript,
                    // and broadening to them would change many existing union-source
                    // TS2322 chains. This keeps the surface limited to the
                    // nullable-mismatch family (cf. elaboratedErrorsOnNullableTargets01).
                    val pick = (chosen.sourceType).types.firstOrNull {
                        isNullishConstituent(it) &&
                            !checkTypeRelatedTo(it, chosen.targetType, assignableRelation)
                    }
                    if (pick != null) {
                        listOf("      Type '${typeToString(pick)}' is not assignable to type '$targetPropStr'.")
                    } else emptyList()
                } else emptyList()
            return listOf(
                outerLine,
                "    Type '$sourcePropStr' is not assignable to type '$targetPropStr'.",
            ) + undefinedExtra + unionConstituentExtra + funcExtra
        } finally {
            if (MapCensus.boxedKeyCensus) {
                MapCensus.bk(MapCensus.BK_ELAB, pairKey)
                MapCensus.bkPop(MapCensus.BK_ELAB)
            }
            state.elaborationStack.remove(pairKey)
        }
    }

    /**
     * 17.42: elaboration chain for `Type.Intersection` source vs `Type.Object` target.
     * Merges members from intersection constituents (`{fooProp: string}` + `Bar` →
     * `{fooProp: string, barProp: string}`), then walks target's properties looking
     * for the first incompatible match. Emits the standard "Types of property '$name'
     * are incompatible. Type '$src' is not assignable to type '$tgt'." chain — same
     * shape as Object→Object property mismatch.
     *
     * Pairs with 17.41's substitution so calls returning `T & Bar` (with T inferred
     * from anonymous Type.Object args) get the substituted intersection source and
     * a per-property elaboration chain. Conservative: only handles direct property-
     * level mismatches (no recursion into nested objects, no method-collapsed form,
     * no privacy / private-brand checks — those don't apply to intersection sources
     * in the corpus). When the chain doesn't find an incompatible property, falls
     * through to the missing-property path.
     */
    /**
     * Returns true when the MERGED members of an intersection source contradict a target
     * property — i.e. a property PRESENT in some constituent has a type that fails against
     * the (optional-widened) target property type. Used to tighten the "any constituent
     * relates" intersection-source relation (which is too lenient). Bounded to PRESENT
     * properties: a missing property is left to the constituent/structural path, so this
     * only ADDS failures for genuinely-incompatible present members (low FP surface).
     */
    /**
     * (CHK.61)(1) PROBE — the ACCEPTANCE twin of [intersectionMergedContradictsTarget]:
     * every target property is supplied by SOME constituent of the merged intersection
     * with a relating type. Deliberately conservative: it bails on anything the merge
     * cannot decide.
     */
    private fun intersectionMergedSatisfiesTarget(
        source: Type.Intersection, target: Type.Object, relation: Relation,
    ): Boolean {
        if (source.types.any { it !is Type.Object }) return false
        val mergedMembers = mutableMapOf<String, MutableList<Symbol>>()
        for (c in source.types) {
            if (c is Type.Object) {
                resolveStructuredTypeMembers(c)
                val m = c.members ?: return false
                m.forEach { (n, sy) -> mergedMembers.getOrPut(n) { mutableListOf() }.add(sy) }
                if (!c.callSignatures.isNullOrEmpty() || !c.constructSignatures.isNullOrEmpty()) return false
            }
        }
        if (mergedMembers.isEmpty()) return false
        resolveStructuredTypeMembers(target)
        if (!target.callSignatures.isNullOrEmpty() || !target.constructSignatures.isNullOrEmpty()) return false
        if (target.stringIndexInfo != null || target.numberIndexInfo != null) return false
        val targetProps = target.properties ?: return false
        if (targetProps.isEmpty()) return false
        for (targetProp in targetProps) {
            if (targetProp.name.isEmpty() || targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            val sourceProps = mergedMembers[targetProp.name]
            if (sourceProps == null) {
                if (isOptionalProperty(targetProp)) continue
                return false
            }
            var ok = false
            for (sourceProp in sourceProps) {
                // The DECLARATION's own type, with the `?` SPELLED OUT. Without it the
                // rule is unsound in this direction: `FunctionExpression & { name:
                // undefined; … }` was accepted against `{ name: Identifier }` because
                // `FunctionExpression`'s `name?: Identifier` is modelled here as plain
                // `Identifier` ((CHK.61)(b)) and the "ANY declaration relates" step then
                // picked it, where the real intersected member is `undefined`. Widened
                // LOCALLY: this is a suppression rule, so being pessimistic about a
                // source member can only decline to suppress.
                var srcType = getTypeOfSymbol(sourceProp)
                if (isOptionalProperty(sourceProp) && !typeIncludesUndefined(srcType)) {
                    srcType = getUnionType(listOf(srcType, undefinedType))
                }
                val tgtType = widenOptionalTargetPropType(getTypeOfSymbol(targetProp), targetProp, srcType)
                if (srcType === errorType || tgtType === errorType) return false
                if (srcType === anyType || tgtType === anyType ||
                    checkTypeRelatedTo(srcType, tgtType, relation)) { ok = true; break }
            }
            if (!ok) return false
        }
        return true
    }

    private fun intersectionMergedContradictsTarget(
        source: Type.Intersection, target: Type.Object, relation: Relation,
    ): Boolean {
        // Round 465: a member declared by MULTIPLE constituents has the INTERSECTION
        // of the declared types in tsc (`AssignmentExpression<EqualsToken> & { left:
        // GeneratedIdentifier }` has left: LeftHandSideExpression & GeneratedIdentifier
        // = GeneratedIdentifier) — so a contradiction holds only when EVERY
        // constituent's declaration fails the target: if ANY declaration relates, the
        // intersected member type (a subtype of each declaration) relates too. The old
        // first-decl-wins merge FP'd the tsc cast idiom `node as AE<EqualsToken> &
        // { left: GeneratedIdentifier }` against its own annotation (factory/
        // utilities.ts:1688, parser.ts:9581) — the interface's WIDE `left` shadowed
        // the TypeLiteral's refinement.
        val mergedMembers = mutableMapOf<String, MutableList<Symbol>>()
        for (c in source.types) {
            if (c is Type.Object) {
                resolveStructuredTypeMembers(c)
                c.members?.forEach { (n, s) -> mergedMembers.getOrPut(n) { mutableListOf() }.add(s) }
            }
        }
        if (mergedMembers.isEmpty()) return false
        resolveStructuredTypeMembers(target)
        val targetProps = target.properties ?: return false
        for (targetProp in targetProps) {
            if (targetProp.name.isEmpty() || targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            val sourceProps = mergedMembers[targetProp.name] ?: continue // missing → not a contradiction here
            var anyRelatesOrUncertain = false
            for (sourceProp in sourceProps) {
                val srcType = getTypeOfSymbol(sourceProp)
                val tgtType = widenOptionalTargetPropType(getTypeOfSymbol(targetProp), targetProp, srcType)
                if (srcType === errorType || tgtType === errorType || srcType === anyType || tgtType === anyType) {
                    anyRelatesOrUncertain = true
                    break
                }
                if (checkTypeRelatedTo(srcType, tgtType, relation)) {
                    anyRelatesOrUncertain = true
                    break
                }
            }
            if (!anyRelatesOrUncertain) return true
        }
        return false
    }

    private fun getIntersectionPropertyElaborationChain(
        source: Type.Intersection,
        target: Type.Object,
        path: String,
    ): List<String>? {
        // Cycle detection: pack (source.id, target.id) like the Object→Object path
        val pairKey = packRelationKey(source.id, target.id)
        if (MapCensus.boxedKeyCensus) MapCensus.bk(MapCensus.BK_ELAB, pairKey)
        if (pairKey in state.elaborationStack) return null
        if (MapCensus.boxedKeyCensus) {
            MapCensus.bk(MapCensus.BK_ELAB, pairKey)
            MapCensus.bkPush(MapCensus.BK_ELAB)
        }
        state.elaborationStack.add(pairKey)
        try {
            // Merge object-like constituent members. Reference / Interface / anonymous
            // Object all contribute. Later constituents override earlier on conflict
            // (matches TS's intersection-member resolution for our scope).
            val mergedMembers = mutableMapOf<String, Symbol>()
            for (c in source.types) {
                if (c is Type.Object) {
                    resolveStructuredTypeMembers(c)
                    c.members?.forEach { (n, s) -> mergedMembers[n] = s }
                }
            }
            if (mergedMembers.isEmpty()) return null
            resolveStructuredTypeMembers(target)
            val targetProps = target.properties ?: return null
            // First incompatible property emits the chain
            for (targetProp in targetProps) {
                val sourceProp = mergedMembers[targetProp.name] ?: continue
                if (targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
                val srcType = getTypeOfSymbol(sourceProp)
                val tgtType = widenOptionalTargetPropType(getTypeOfSymbol(targetProp), targetProp, srcType)
                if (srcType === errorType || tgtType === errorType) continue
                if (!checkTypeRelatedTo(srcType, tgtType, assignableRelation)) {
                    val propPath = if (path.isEmpty()) targetProp.name else "$path.${targetProp.name}"
                    val outerLine = if (path.isEmpty()) {
                        "  Types of property '${targetProp.name}' are incompatible."
                    } else {
                        "  The types of '$propPath' are incompatible between these types."
                    }
                    val sourcePropStr = typeToString(srcType)
                    val targetPropStr = typeToString(tgtType)
                    return listOf(
                        outerLine,
                        "    Type '$sourcePropStr' is not assignable to type '$targetPropStr'.",
                    )
                }
            }
            // No property-type mismatch — try missing-required-property path against
            // any constituent that's an Object-like (FIRST constituent for simplicity;
            // matches TypeScript's behavior of attributing missing-prop to the named
            // intersection member).
            for (c in source.types) {
                if (c is Type.Object) {
                    resolveStructuredTypeMembers(c)
                    val missing = getMissingRequiredPropertySymbol(c, target)
                    if (missing != null) {
                        return listOf(
                            "  Property '${missing.name}' is missing in type '${typeToString(source)}' but required in type '${typeToString(target)}'."
                        )
                    }
                }
            }
            return null
        } finally {
            if (MapCensus.boxedKeyCensus) {
                MapCensus.bk(MapCensus.BK_ELAB, pairKey)
                MapCensus.bkPop(MapCensus.BK_ELAB)
            }
            state.elaborationStack.remove(pairKey)
        }
    }

    /**
     * B413: Distribute `(U1 | U2) & Obj…` into [`U1 & Obj…`, `U2 & Obj…`]. Returns the
     * single-element list `[self]` when there is no union member, and null when more than
     * one constituent is a union (we only model the single-discriminant-union shape).
     */
    private fun distributeIntersectionConstituents(intersection: Type.Intersection): List<Type.Intersection>? {
        val unionIdx = intersection.types.indexOfFirst { it is Type.Union }
        if (unionIdx < 0) return listOf(intersection)
        if (intersection.types.count { it is Type.Union } != 1) return null
        val union = intersection.types[unionIdx] as Type.Union
        return union.types.map { member ->
            Type.Intersection(intersection.types.mapIndexed { i, t -> if (i == unionIdx) member else t })
        }
    }

    /** B413: literal-typed (discriminant) members merged from an intersection's object constituents. */
    private fun intersectionDiscriminants(t: Type.Intersection): Map<String, Type> {
        val m = mutableMapOf<String, Type>()
        for (c in t.types) {
            if (c is Type.Object) {
                resolveStructuredTypeMembers(c)
                c.members?.forEach { (n, s) ->
                    val ty = getTypeOfSymbol(s)
                    if (ty.flags.hasAny(TypeFlags.StringLiteral or TypeFlags.NumberLiteral or TypeFlags.BooleanLiteral)) m[n] = ty
                }
            }
        }
        return m
    }

    /**
     * B413: discriminated-union intersection elaboration. Produces the three sub-lines
     * tsc emits for `A = Common & {foo}` vs `B = Common & {bar}`:
     *   Type '<srcConstituent>' is not assignable to type '<B>'.
     *     Type '<srcConstituent>' is not assignable to type '<matched tgtConstituent>'.
     *       Property 'X' is missing in type '<srcConstituent>' but required in type '<tgt sub-object>'.
     * Returns null for any shape that doesn't distribute into a discriminated constituent
     * with a single missing required property (so the caller falls back to no elaboration).
     */
    private fun getDiscriminatedIntersectionElaboration(
        source: Type.Intersection,
        target: Type.Intersection,
    ): List<String>? {
        val srcConstituents = distributeIntersectionConstituents(source) ?: return null
        val tgtConstituents = distributeIntersectionConstituents(target) ?: return null
        // Require an actual distribution on at least one side (mirrors tsc's discriminated display).
        if (srcConstituents.size <= 1 && tgtConstituents.size <= 1) return null
        for (srcC in srcConstituents) {
            if (checkTypeRelatedTo(srcC, target, assignableRelation)) continue
            // Match a target constituent by shared discriminant literal values.
            val srcDisc = intersectionDiscriminants(srcC)
            val tgtC = tgtConstituents.firstOrNull { tc ->
                val td = intersectionDiscriminants(tc)
                srcDisc.isNotEmpty() && srcDisc.all { (k, v) -> td[k]?.let { it === v || typeToString(it) == typeToString(v) } ?: false }
            } ?: tgtConstituents.firstOrNull { !checkTypeRelatedTo(srcC, it, assignableRelation) } ?: continue
            // Merge the source constituent's object members for missing-property detection.
            val srcMembers = mutableMapOf<String, Symbol>()
            for (c in srcC.types) if (c is Type.Object) {
                resolveStructuredTypeMembers(c); c.members?.forEach { (n, s) -> srcMembers[n] = s }
            }
            // Find the first required property of a target sub-object that the source lacks.
            var missingSym: Symbol? = null
            var requiredInType: Type.Object? = null
            outer@ for (c in tgtC.types) {
                if (c !is Type.Object) continue
                resolveStructuredTypeMembers(c)
                for (p in c.properties ?: emptyList()) {
                    if (p.name in OBJECT_PROTOTYPE_PROPERTIES) continue
                    if (isOptionalProperty(p)) continue
                    if (srcMembers.containsKey(p.name)) continue
                    missingSym = p; requiredInType = c; break@outer
                }
            }
            val ms = missingSym ?: return null
            val rt = requiredInType ?: return null
            lastChainMissingPropSymbol = ms
            return listOf(
                "  Type '${typeToString(srcC)}' is not assignable to type '${typeToString(target)}'.",
                "    Type '${typeToString(srcC)}' is not assignable to type '${typeToString(tgtC)}'.",
                "      Property '${ms.name}' is missing in type '${typeToString(srcC)}' but required in type '${typeToString(rt)}'.",
            )
        }
        return null
    }

    /**
     * Find the first non-optional target property that source lacks and that source's
     * string index signature (if any) does not satisfy. Mirrors `propertiesRelatedTo`'s
     * missing-property logic so the elaboration chain can include "Property 'X' is
     * missing in type 'A' but required in type 'B'." for purely structural failures
     * (no per-property type mismatch). Sets `lastChainMissingPropSymbol` so callers
     * can attach matching TS2728 "'X' is declared here." related info to TS2322.
     */
    private fun getMissingRequiredPropertySymbol(source: Type.Object, target: Type.Object): Symbol? {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        val targetProps = target.properties ?: return null
        val sourceMembers = source.members ?: return null
        val srcIndex = source.stringIndexInfo
        val targetStatics = getStaticMembersOfType(target)
        for (targetProp in targetProps) {
            if (targetStatics != null && targetStatics.containsKey(targetProp.name)) continue
            if (sourceMembers[targetProp.name] != null) continue
            if (targetProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            if (isOptionalProperty(targetProp)) continue
            if (srcIndex != null) {
                val targetPropType = getPropertyTypeForRelation(target, targetProp)
                if (checkTypeRelatedTo(srcIndex.type, targetPropType, assignableRelation)) continue
            }
            if (isLibPhantomMemberOfModuleInterface(target, targetProp.name)) continue
            lastChainMissingPropSymbol = targetProp
            return targetProp
        }
        return null
    }

    /** Check if a property symbol is optional (has questionToken in its declaration). */
    /**
     * 16.4eb: Does the type accept `undefined` as a value? True for explicit undefined,
     * any/unknown/never, or unions whose constituents include any of those. Used by
     * the TS2790 "delete operand must be optional" check.
     */
    private fun typeIncludesUndefinedOrTop(type: Type): Boolean {
        if (type.flags.hasAny(
                TypeFlags.Undefined or TypeFlags.Any or TypeFlags.Unknown or TypeFlags.Never)) return true
        if (type is Type.Union) return type.types.any { typeIncludesUndefinedOrTop(it) }
        return false
    }

    /** Whether the enclosing class (`currentClassForThis`) declares `propName` as an
     *  OWN optional property (`p?: T`). Used by the string-based `this.prop = undefined`
     *  write path to skip a false TS2322 (varTypes drops the `?`). Own members only,
     *  matching the varTypes["this.X"] population scope. */
    private fun thisPropertyIsOptional(propName: String): Boolean {
        val cls = currentClassForThis ?: return false
        return cls.members.any { m ->
            m is PropertyDeclaration && (m.name as? Identifier)?.text == propName && m.questionToken
        }
    }

    private fun isOptionalProperty(symbol: Symbol): Boolean {
        // M5.2 perf: check the declaration path FIRST — the overwhelming majority of
        // symbols carry a declaration, and only DECLARATION-LESS tuple-member symbols
        // (created by [buildTupleFromTypes], never merged with any declared symbol) are
        // ever in [optionalTupleMemberIds]. Their globally-unique ids can never collide
        // with a declared symbol's, so skipping the set lookup for a declared symbol is
        // byte-identical — and avoids a HashSet lookup on every isOptionalProperty call.
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
        if (decl != null) {
            val declaredOptional = when (decl) {
                is PropertyDeclaration -> decl.questionToken
                is Parameter -> decl.questionToken
                is MethodDeclaration -> decl.questionToken
                else -> false
            }
            // Round 728: the MIRROR of the round-718 case below — a `?` mapped member
            // (`Partial<T>`) IS optional even though the source declaration it carries
            // for related info is REQUIRED. This arm is the hot one (every declared-required
            // property lands here), so the marker is a [SymbolFlags.MappedOptional] bit
            // rather than an id-keyed set: a bitwise AND, not a boxed-Int lookup.
            if (!declaredOptional) return SymbolFlags.MappedOptional in symbol.flags
            // Round 718: a `-?` mapped member (`Required<T>`) carries its optional SOURCE
            // declaration but is NOT itself optional. Probed only when the declaration
            // says optional — the short-circuit keeps the hot path (a declared-required
            // property) free of the set lookup the comment above is about.
            return symbol.id !in mappedRequiredMemberIds
        }
        // Round 452: an optional tuple element (`[kind?: T]`) has a declaration-less member
        // symbol; its optionality lives in the side-channel [optionalTupleMemberIds].
        return SymbolFlags.MappedOptional in symbol.flags || symbol.id in optionalTupleMemberIds
    }

    /**
     * B103: find the first target property that is REQUIRED but whose same-named source
     * property is OPTIONAL. Such a source is never assignable to such a target (the
     * property may be absent at runtime) — TypeScript reports "Property 'X' is optional
     * in type 'S' but required in type 'T'." regardless of strictNullChecks. FP-safe:
     * the rule is universally true. Returns the target Symbol, or null.
     */
    private fun findOptionalVsRequiredMismatch(source: Type.Object, target: Type.Object): Symbol? {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        val targetProps = target.properties ?: return null
        // A source STRING index signature could provide any property — skip to stay safe.
        // A NUMBER index signature (e.g. inherited from an Array base, B236) can only
        // provide NUMERIC names — non-numeric properties are still checked.
        if (source.stringIndexInfo != null) return null
        val hasNumIdx = source.numberIndexInfo != null
        for (tProp in targetProps) {
            if (tProp.name.isEmpty() || tProp.name in OBJECT_PROTOTYPE_PROPERTIES) continue
            if (hasNumIdx && tProp.name.all { it.isDigit() }) continue
            if (isOptionalProperty(tProp)) continue
            val sProp = getPropertyOfType(source, tProp.name) ?: continue
            if (isOptionalProperty(sProp)) return tProp
        }
        return null
    }

    /**
     * Under strictNullChecks, optional source property `prop?: T` accepts `undefined` —
     * it widens to `T | undefined` when comparing against a target's required property.
     * Returns the widened type, or the original type when widening doesn't apply.
     */
    private fun widenOptionalSourcePropType(
        sourceType: Type,
        sourceProp: Symbol,
        targetProp: Symbol,
    ): Type {
        if (!strictNullChecks) return sourceType
        if (!isOptionalProperty(sourceProp)) return sourceType
        if (isOptionalProperty(targetProp)) return sourceType
        if (typeIncludesUndefinedOrTop(sourceType)) return sourceType
        return getUnionType(listOf(sourceType, undefinedType))
    }

    /**
     * An OPTIONAL target property `a?: T` has the assignability type `T | undefined`
     * under `strictNullChecks && !exactOptionalPropertyTypes` (tsc `addOptionality`).
     * So a `null`/`string` source value is compared against — and elaborates as —
     * `T | undefined` (intersectionsAndOptionalProperties: `null` ≁ `number | undefined`).
     * Under exactOptionalPropertyTypes the optional `?` does NOT admit `undefined`, so the
     * bare type is kept. FP-safe: only changes the RELATION result for an `undefined`
     * source (which then correctly PASSES, matching tsc), and the DISPLAY to add the
     * `| undefined` tsc shows for non-exact optional targets.
     */
    /**
     * The empty anonymous object type `{}` — no symbol, no members, no signatures,
     * no index infos (round 430's `structuredTypeRelatedTo` empty-object rule: `{}`
     * is the supertype of every non-nullish, non-void value). Factored out so the
     * return-path precise-verdict early return (round 438) can reuse the exact shape.
     */
    private fun isEmptyAnonymousObjectType(t: Type): Boolean =
        t is Type.Object && t !is Type.Interface && t !is Type.Reference &&
            t.symbol == null && t.members.isNullOrEmpty() &&
            t.callSignatures.isNullOrEmpty() && t.constructSignatures.isNullOrEmpty() &&
            t.stringIndexInfo == null && t.numberIndexInfo == null

    /** `{}` itself, or a union with an empty-object `{}` member (`{} | undefined`). */
    private fun targetHasEmptyObjectMember(t: Type): Boolean =
        isEmptyAnonymousObjectType(t) ||
            (t is Type.Union && t.types.any { isEmptyAnonymousObjectType(it) })

    private fun widenOptionalTargetPropType(targetType: Type, targetProp: Symbol, sourceType: Type): Type {
        if (!strictNullChecks) return targetType
        if (options.exactOptionalPropertyTypes) return targetType
        if (!isOptionalProperty(targetProp)) return targetType
        if (typeIncludesUndefinedOrTop(targetType)) return targetType
        // tsc surfaces the optional `| undefined` in the leaf ONLY when the SOURCE is
        // nullish (`null` → `number | undefined`). A concrete non-nullish source
        // elaborates against the BARE prop type (`boolean` ≁ `string`, not `string |
        // undefined`) — intersectionsAndOptionalProperties (null source, widened) vs
        // intersectionPropertyCheck (boolean source, bare). It is also the right RELATION
        // type: an `undefined` source then correctly passes against `T | undefined`.
        val srcNullish = sourceType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) ||
            (sourceType is Type.Union && sourceType.types.any { it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) })
        if (!srcNullish) return targetType
        return getUnionType(listOf(targetType, undefinedType))
    }

    /**
     * Render a property's name for type display. Quotes the name when it was written as
     * a string-literal key AND is not a valid JS identifier (mirrors TypeScript's display:
     * `"0"`, `"ns:attribute"`, `"resolution-mode"` stay quoted; `"hello"` displays as
     * `hello`; numeric-literal keys like `0:` and identifier keys stay unquoted).
     */
    private fun formatPropertyDisplayName(symbol: Symbol): String {
        val name = symbol.name
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
        val nameNode = when (decl) {
            is PropertyAssignment -> decl.name
            is ShorthandPropertyAssignment -> decl.name
            is MethodDeclaration -> decl.name
            is PropertyDeclaration -> decl.name
            else -> null
        }
        // Round 940 — (CHK.5)(f): a member declared by a COMPUTED key is named AS WRITTEN,
        // which is what pristine tsc prints wherever it names one — `'[E.A]'`
        // (`assignmentCompatWithEnumIndexer`), `'["a"]'` (`duplicateIdentifierComputedName`,
        // an ACTIVE gate), `'[c1]'` (`dynamicNamesErrors`, ACTIVE), `'[Symbol.toPrimitive]'`
        // (`symbolProperty21`) — and where tsgo agrees, so we were the outlier. Before this,
        // `const K = "p"; interface I { [K]: number }; const x: I = {}` said
        // `Property 'p' is missing`, naming the late-bound VALUE the source never contains.
        // [computedKeyWrittenText] answers null for a spelling it cannot reproduce exactly,
        // so a message can never carry a name the source does not have; a NON-computed
        // member keeps its bare name, which is this change's negative control.
        if (nameNode is ComputedPropertyName) {
            computedKeyWrittenText(nameNode)?.let { return it }
        }
        if (nameNode is StringLiteralNode && !isValidJsIdentifier(name)) {
            // TypeScript's type-display PRESERVES the source quote style of a
            // non-identifier string-literal property name: `{ '': number; }` for a
            // single-quoted source name, `{ "0": number; }` for a double-quoted one.
            return if (nameNode.singleQuote) "'$name'" else "\"$name\""
        }
        // A recovery-synthesized MISSING member name renders quoted-empty: `"": any`
        // (reachabilityChecksNoCrash1's `<missing>: .push(await v)` member).
        if (name.isEmpty()) return "\"\""
        return name
    }

    private fun isValidJsIdentifier(text: String): Boolean {
        if (text.isEmpty()) return false
        val first = text[0]
        if (!first.isLetter() && first != '_' && first != '$') return false
        for (i in 1 until text.length) {
            val c = text[i]
            if (!c.isLetterOrDigit() && c != '_' && c != '$') return false
        }
        return true
    }

    /**
     * Check if source type is assignable to target type using the new Type-based engine.
     * This is the replacement for the string-based isAssignableTo.
     */
    private fun isTypeAssignableTo(source: Type, target: Type): Boolean {
        return checkTypeRelatedTo(source, target, assignableRelation)
    }

    // -----------------------------------------------------------------------
    // Generic type instantiation (Phase 4 item 8a)
    // -----------------------------------------------------------------------

    /**
     * TypeMapper — maps type parameters to concrete types during generic instantiation.
     */
    private fun interface TypeMapper {
        fun map(typeParam: Type.TypeParam): Type?
    }

    /**
     * Create a TypeMapper from parallel lists of type parameters and type arguments.
     */
    private fun createTypeMapper(typeParams: List<Type.TypeParam>, typeArgs: List<Type>): TypeMapper {
        return TypeMapper { tp ->
            val index = typeParams.indexOf(tp)
            if (index >= 0 && index < typeArgs.size) typeArgs[index] else null
        }
    }

    /**
     * Recursively substitute type parameters in a type according to the given mapper.
     * Returns the same type if no substitution occurs.
     */
    private fun instantiateType(type: Type, mapper: TypeMapper): Type {
        return when (type) {
            is Type.TypeParam -> mapper.map(type) ?: type
            is Type.Union -> {
                val mapped = type.types.map { instantiateType(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type
                else getUnionType(mapped)
            }
            is Type.Intersection -> {
                val mapped = type.types.map { instantiateType(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type
                else getIntersectionType(mapped)
            }
            is Type.Reference -> {
                val args = type.resolvedTypeArguments ?: return type
                val mapped = args.map { instantiateType(it, mapper) }
                if (mapped.zip(args).all { (a, b) -> a === b }) type
                else getOrInternReference(type.target, mapped)
            }
            is Type.Object -> {
                // B52.3: For anonymous Type.Object (no Interface/Reference subclass,
                // no symbol, no call/construct signatures), walk members and substitute
                // TypeParam-typed property types. This unlocks per-property TS2322 at
                // object-literal args under explicit type args (e.g. `foo<number>({x:3, y:""})`
                // against `(n: {x:T, y:T})`). Narrow gate: only PURE PROPERTY-BAG anonymous
                // objects — function-shaped objects (call/construct sigs) and named types
                // are still returned as-is to avoid broad regressions (see CLAUDE.md
                // "instantiateType for Type.Object" gotcha).
                if (type is Type.Interface || type is Type.Reference) return type
                if (type.symbol != null) return type
                if (!type.callSignatures.isNullOrEmpty()) return type
                if (!type.constructSignatures.isNullOrEmpty()) return type
                val origMembers = type.members ?: return type
                if (origMembers.isEmpty()) return type
                var anyChanged = false
                val newMembers: SymbolTable = mutableMapOf()
                val newProps = mutableListOf<Symbol>()
                for ((name, memberSym) in origMembers) {
                    val memberType = getTypeOfSymbol(memberSym)
                    val instMemberType = instantiateType(memberType, mapper)
                    if (instMemberType === memberType) {
                        newMembers[name] = memberSym
                        newProps.add(memberSym)
                    } else {
                        anyChanged = true
                        val newSym = Symbol(memberSym.flags, memberSym.name)
                        newSym.declarations.addAll(memberSym.declarations)
                        newSym.valueDeclaration = memberSym.valueDeclaration
                        symbolTypes[newSym.id] = instMemberType
                        newMembers[name] = newSym
                        newProps.add(newSym)
                    }
                }
                if (!anyChanged) return type
                val newObj = Type.Object()
                newObj.members = newMembers
                newObj.properties = newProps
                newObj
            }
            // Intrinsic, literal types don't contain type parameters
            else -> type
        }
    }

    /**
     * B86.1b (activation, 2026-05-28): instantiate a CONTEXTUAL parameter type through an
     * inference mapper. Unlike [instantiateType] (which deliberately returns
     * function-shaped Type.Object UNCHANGED — see CLAUDE.md "instantiateType for
     * Type.Object" gotcha), this helper DOES descend into a function-shaped
     * Type.Object's call signatures so a contextual callback type like `(x: T) => U`
     * becomes `(x: <mapped T>) => <mapped U>`. This is what lets the un-annotated lambda
     * param `x` resolve to the concrete inferred type during the diagnostic walk
     * (`checkPropertyAccessInExpr`'s ArrowFunction / FunctionExpression branches push
     * `currentLocalTypes[x] = <contextual sig param type>`). Used ONLY at the
     * checkPropertyAccessInExpr CallExpression arg-context computation — narrowly scoped
     * so the existing instantiateType no-op behavior (relied on elsewhere) is untouched.
     */
    private fun instantiateContextualParamType(type: Type, mapper: TypeMapper): Type {
        if (type is Type.Object && type !is Type.Interface && type !is Type.Reference &&
            type.symbol == null && !type.callSignatures.isNullOrEmpty() &&
            type.constructSignatures.isNullOrEmpty()
        ) {
            val newSigs = type.callSignatures!!.map { instantiateContextualSignature(it, mapper) }
            // Avoid allocating a fresh object when nothing changed (identity preserved
            // per-signature is not guaranteed, so compare element-wise on the sigs).
            if (newSigs.zip(type.callSignatures!!).all { (a, b) -> a === b }) return type
            val newObj = Type.Object()
            newObj.callSignatures = newSigs
            newObj.properties = type.properties
            newObj.members = type.members
            return newObj
        }
        return instantiateType(type, mapper)
    }

    /**
     * B83.4d: like [instantiateSignature] but uses [instantiateContextualParamType]
     * (rather than the function-shape-no-op [instantiateType]) for BOTH parameter
     * types AND the return type, so a callback-returning-a-callback contextual type
     * `() => (a: T) => void` substitutes its inner `(a: T)` to `(a: <mapped>)`.
     * Used only by the contextual-param substitution path in [checkPropertyAccessInExpr];
     * preserves [instantiateSignature]'s behavior for non-function-shaped members.
     */
    private fun instantiateContextualSignature(sig: Signature, mapper: TypeMapper): Signature {
        val newReturnType = sig.resolvedReturnType?.let { instantiateContextualParamType(it, mapper) }
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateContextualParamType(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        return Signature(
            declaration = sig.declaration,
            typeParameters = null,
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /**
     * Instantiate a signature with type arguments — substitute type params in parameter types
     * and return type.
     */
    private fun instantiateSignature(sig: Signature, mapper: TypeMapper): Signature {
        val newReturnType = sig.resolvedReturnType?.let { instantiateType(it, mapper) }
        // Instantiate parameter types — create new symbols with mapped types
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateType(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        return Signature(
            declaration = sig.declaration,
            typeParameters = null, // instantiated signature has no type parameters
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /**
     * 17.39: Substitute outer typeArgs into a freshly-resolved function-typed property's
     * inner generic signatures — typeParam constraints/defaults, param types, return
     * type. Mutates [rawType]'s callSignatures/constructSignatures lists in place; the
     * inner Signatures' typeParameters are also mutated in place (their `constraint` /
     * `default` fields reassigned). Caller must guarantee [rawType] is freshly allocated
     * (e.g. resolved through `getTypeFromTypeNode` while `currentTypeParamScope != null`)
     * — this is currently the case in `resolveGenericPropertyType`'s PropertyDeclaration
     * branch. Preserves the inner sig's typeParameter list (T stays generic) so call-site
     * inference + constraint check via 16.4ds / 16.4i still fires.
     */
    private fun substituteOuterTypeArgsInGenericFnObject(rawType: Type.Object, mapper: TypeMapper) {
        rawType.callSignatures = rawType.callSignatures?.map { substituteOuterTypeArgsInSignature(it, mapper) }
        rawType.constructSignatures = rawType.constructSignatures?.map { substituteOuterTypeArgsInSignature(it, mapper) }
    }

    /**
     * Round 465: like [instantiateType] but DESCENDS into anonymous FUNCTION-SHAPED
     * `Type.Object`s (call/construct signatures) and unions containing them —
     * [instantiateType] deliberately no-ops those (see the CLAUDE.md gotcha), which
     * left a generic interface member's fn-typed RETURN carrying the raw outer
     * TypeParam through the relation: `interface Sel<T> { select(index: number):
     * ((node: T) => T) | undefined }` instantiated as `Sel<TypeNode>` kept `T` in the
     * method's return, failing a conforming object literal (tsc emitter.ts
     * OrdinalParentheizerRuleSelector). Mints FRESH objects (never mutates), preserves
     * identity when nothing changes, and preserves signature type parameters.
     */
    private fun instantiateTypeFnAware(type: Type, mapper: TypeMapper): Type {
        return when {
            type is Type.Union -> {
                val mapped = type.types.map { instantiateTypeFnAware(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type else getUnionType(mapped)
            }
            type is Type.Object && type !is Type.Interface && type !is Type.Reference &&
                type.symbol == null && type.tupleElementTypes == null &&
                (!type.callSignatures.isNullOrEmpty() || !type.constructSignatures.isNullOrEmpty()) -> {
                val newCall = type.callSignatures?.map { instantiateSignatureFnAware(it, mapper) }
                val newCtor = type.constructSignatures?.map { instantiateSignatureFnAware(it, mapper) }
                val unchanged =
                    (newCall == null || newCall.zip(type.callSignatures!!).all { (a, b) -> a === b }) &&
                        (newCtor == null || newCtor.zip(type.constructSignatures!!).all { (a, b) -> a === b })
                if (unchanged) type
                else Type.Object().also { o ->
                    o.callSignatures = newCall
                    o.constructSignatures = newCtor
                    o.members = type.members
                    o.properties = type.properties
                    o.stringIndexInfo = type.stringIndexInfo
                    o.numberIndexInfo = type.numberIndexInfo
                }
            }
            else -> instantiateType(type, mapper)
        }
    }

    /** Companion of [instantiateTypeFnAware]: [instantiateSignature] with fn-aware
     *  param/return instantiation and signature type parameters PRESERVED (the sig
     *  stays generic at the use site); returns the SAME instance when nothing maps. */
    private fun instantiateSignatureFnAware(sig: Signature, mapper: TypeMapper): Signature {
        val newReturnType = sig.resolvedReturnType?.let { instantiateTypeFnAware(it, mapper) }
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateTypeFnAware(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        val paramsChanged = newParams.zip(sig.parameters).any { (a, b) -> a !== b }
        if (!paramsChanged && newReturnType === sig.resolvedReturnType) return sig
        return Signature(
            declaration = sig.declaration,
            typeParameters = sig.typeParameters,
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    private fun substituteOuterTypeArgsInSignature(sig: Signature, mapper: TypeMapper): Signature {
        // Mutate sig's typeParameter constraints/defaults in place — they reference the
        // outer interface's TypeParams (e.g. `<T extends S>` where S is the outer one),
        // and we want substituted forms visible at the call site without erasing T's
        // generic identity. TPs are fresh per-call (see uncached getTypeFromTypeNode).
        sig.typeParameters?.forEach { tp ->
            tp.constraint = tp.constraint?.let { instantiateType(it, mapper) }
            tp.default = tp.default?.let { instantiateType(it, mapper) }
        }
        // Round 465: fn-AWARE return/param instantiation — a NESTED fn type inside the
        // sig (`get: (index: number) => ((node: T) => T) | undefined`) otherwise keeps
        // the raw outer TypeParam (instantiateType no-ops fn-shaped objects).
        val newReturnType = sig.resolvedReturnType?.let { instantiateTypeFnAware(it, mapper) }
        val newParams = sig.parameters.map { param ->
            val paramType = getTypeOfSymbol(param)
            val instantiated = instantiateTypeFnAware(paramType, mapper)
            if (instantiated !== paramType) {
                val newParam = Symbol(param.flags, param.name)
                newParam.declarations.addAll(param.declarations)
                newParam.valueDeclaration = param.valueDeclaration
                symbolTypes[newParam.id] = instantiated
                newParam
            } else param
        }
        val paramsChanged = newParams.zip(sig.parameters).any { (a, b) -> a !== b }
        val returnChanged = newReturnType !== sig.resolvedReturnType
        if (!paramsChanged && !returnChanged) return sig
        return Signature(
            declaration = sig.declaration,
            typeParameters = sig.typeParameters, // preserve — still generic at call site
            parameters = newParams,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /**
     * Like [typeToString] but substitutes TypeParam references via [mapper] at display
     * time. Used to render an un-instantiated constraint (e.g. `{ a: T }`) as the
     * substituted form (`{ a: string }`) in TS2344 messages without touching the type
     * system. Walks anonymous Type.Object property types; falls back to [typeToString]
     * for named types, signatures, and anything the walker doesn't know how to render.
     */
    private fun typeToStringWithMapper(type: Type, mapper: TypeMapper): String {
        // Order matters: Type.Interface and Type.Reference must be checked BEFORE
        // Type.Object — both extend Type.Object.
        return when (type) {
            is Type.TypeParam -> mapper.map(type)?.let { typeToString(it) } ?: (type.symbol?.name ?: "T")
            is Type.Interface -> typeToString(type)
            is Type.Reference -> {
                val args = type.resolvedTypeArguments
                if (type.target === globalArrayType && args != null && args.size == 1) {
                    val elemStr = typeToStringWithMapper(args[0], mapper)
                    if (args[0] is Type.Union || args[0] is Type.Intersection) "($elemStr)[]"
                    else "$elemStr[]"
                } else {
                    val target = type.target.symbol?.name ?: "Object"
                    if (args != null && args.isNotEmpty()) {
                        "$target<${args.joinToString(", ") { typeToStringWithMapper(it, mapper) }}>"
                    } else target
                }
            }
            is Type.Object -> {
                // Only rewrite anonymous object types (no backing symbol declaration).
                // Named types display by name via typeToString; callers don't expect
                // their bodies to be walked.
                if (type.symbol != null) return typeToString(type)
                val hasSignatures = !type.callSignatures.isNullOrEmpty() || !type.constructSignatures.isNullOrEmpty()
                if (hasSignatures) return typeToString(type)
                val props = type.properties ?: return typeToString(type)
                val parts = mutableListOf<String>()
                for (p in props) {
                    val pt = symbolTypes[p.id]
                    val typeStr = if (pt != null) typeToStringWithMapper(pt, mapper) else "any"
                    val displayName = formatPropertyDisplayName(p)
                    if (isOptionalProperty(p)) {
                        parts.add("$displayName?: $typeStr | undefined")
                    } else {
                        parts.add("$displayName: $typeStr")
                    }
                }
                if (parts.isNotEmpty()) "{ ${parts.joinToString("; ")}; }" else "{}"
            }
            is Type.Union -> type.types.joinToString(" | ") { typeToStringWithMapper(it, mapper) }
            is Type.Intersection -> type.types.joinToString(" & ") { typeToStringWithMapper(it, mapper) }
            else -> typeToString(type)
        }
    }

    /**
     * Return an interned `Type.Reference` for `(target, args)`. Two calls with the same
     * target and the same arg ids return the SAME instance, so the resulting `Type.id`
     * is stable across instantiations. Cycle detection in `relationComparisonStack`
     * keys on `(source.id, target.id)` and relies on this identity to catch
     * self-referential generics like `interface List<T> { next: List<T> }` whose
     * member instantiation would otherwise mint fresh Ref ids per recursion level.
     *
     * Pass `args = null` to denote a Reference with no resolved arguments (e.g. a raw
     * generic with no instantiation). This is rare; most call sites pass an actual list.
     */
    private fun getOrInternReference(target: Type.Interface, args: List<Type>?): Type.Reference {
        // M0.3(iii): the dominant shapes (null / empty / exactly-one arg) intern via an
        // exact packed-Long key — target.id (>= 1) in the high 32 bits, the single
        // arg's id (positive, < 2^31) in the low 32 bits. null args and an EMPTY list
        // both pack low=0, deliberately REPRODUCING the old string key's conflation
        // (both built "id|" — first-toucher's instance wins for the other shape).
        if (args == null || args.size <= 1) {
            val low = if (args.isNullOrEmpty()) 0L else args[0].id.toLong() and 0xFFFFFFFFL
            val key = (target.id.toLong() shl 32) or low
            return state.referenceCacheLong.get(key)
                ?: Type.Reference(target, resolvedTypeArguments = args)
                    .also { state.referenceCacheLong.put(key, it) }
        }
        val key = buildString {
            append(target.id)
            append('|')
            args.joinTo(this, ",") { it.id.toString() }
        }
        return state.referenceCache.getOrPut(key) {
            Type.Reference(target, resolvedTypeArguments = args)
        }
    }

    /** Create an array type: `Type.Reference(globalArrayType, [elementType])`. */
    private fun getArrayType(elementType: Type): Type {
        return getOrInternReference(globalArrayType, listOf(elementType))
    }

    /** Create a tuple type from a TupleType node. */
    private fun getTupleType(node: TupleType): Type {
        val elementTypes = node.elements.map { elem ->
            when (elem) {
                is NamedTupleMember -> getTypeFromTypeNode(elem.type)
                is OptionalType -> getTypeFromTypeNode(elem.type)
                is RestType -> getTypeFromTypeNode(elem.type)
                else -> getTypeFromTypeNode(elem)
            }
        }
        // Round 452: per-element optionality (`[kind?: T]` / `[T?]`) recovered by the parser
        // into `node.elementOptional` (the `?` tokens are stripped from `elements`), so an
        // all-optional tuple target does not count its elements as required — `[] : [a?, b?]`
        // no longer FP's TS2739 (moduleSpecifiers.ts `return emptyArray as []`).
        return buildTupleFromTypes(elementTypes, node.elementOptional)
    }

    /** Build a tuple `Type.Object` (with `tupleElementTypes`, numbered props, length, number index sig).
     *  [optionalFlags], when non-null, marks the matching element's member symbol OPTIONAL
     *  (recorded in [optionalTupleMemberIds] so [isOptionalProperty] can see it). */
    private fun buildTupleFromTypes(elementTypes: List<Type>, optionalFlags: List<Boolean>? = null): Type {
        val tupleObj = Type.Object()
        tupleObj.tupleElementTypes = elementTypes
        // Create numbered property symbols: "0", "1", "2", ...
        val props = mutableListOf<Symbol>()
        val members = symbolTable()
        for ((i, elemType) in elementTypes.withIndex()) {
            val propSymbol = Symbol(
                flags = SymbolFlags.Property,
                name = i.toString(),
            )
            symbolTypes[propSymbol.id] = elemType
            if (optionalFlags?.getOrNull(i) == true) optionalTupleMemberIds.add(propSymbol.id)
            props.add(propSymbol)
            members[propSymbol.name] = propSymbol
        }
        // Add readonly "length" property with literal type. For a tuple with OPTIONAL
        // elements the length is the union `minLength | … | maxLength` (tsc), so an empty
        // `[]` (length 0) relates to `[a?, b?]` (length `0 | 1 | 2`). minLength = number of
        // leading required elements (optionals must be trailing); maxLength = element count.
        val lengthSymbol = Symbol(
            flags = SymbolFlags.Property,
            name = "length",
        )
        val maxLen = elementTypes.size
        val minLen = optionalFlags?.indexOfFirst { it }?.takeIf { it >= 0 } ?: maxLen
        symbolTypes[lengthSymbol.id] = if (minLen >= maxLen) {
            Type.NumberLiteral(maxLen.toDouble())
        } else {
            getUnionType((minLen..maxLen).map { Type.NumberLiteral(it.toDouble()) })
        }
        props.add(lengthSymbol)
        members["length"] = lengthSymbol
        tupleObj.properties = props
        tupleObj.members = members
        // Tuple has a number index signature for element access
        if (elementTypes.isNotEmpty()) {
            val elementUnion = if (elementTypes.size == 1) elementTypes[0]
                else getUnionType(elementTypes)
            tupleObj.numberIndexInfo = IndexInfo(keyType = numberType, type = elementUnion)
        }
        return tupleObj
    }

    /** Resolve a typeof type query: `typeof X` in type annotation position. */
    private fun getTypeFromTypeQuery(node: TypeQuery): Type {
        val exprName = node.exprName
        when (exprName) {
            is Identifier -> {
                // Handle special built-in names
                when (exprName.text) {
                    // tsc widens `typeof undefined` to `any` under non-strict (the type of
                    // the `undefined` value is the widening Undefined type, which widens to
                    // `any` when strictNullChecks is off — widenedTypes `var x: typeof undefined`).
                    "undefined" -> return if (strictNullChecks) undefinedType else anyType
                    "NaN", "Infinity" -> return numberType
                    "true", "false" -> return booleanType
                }
                // Look up file-level names only — currentLocalTypes contains function-scoped
                // variables that shouldn't be visible in type annotation positions.
                // INV.3(d): node-keyed (was the merged `globals`) — `typeof X` resolves
                // under the annotation's owning file's visibility.
                val symbol = lookupPerFileForNode(exprName, exprName.text) ?: return anyType
                return getTypeOfSymbolForTypeQuery(symbol)
            }
            is QualifiedName -> {
                // typeof A.B.C — first try a namespace/module/class symbol chain.
                val symbol = resolveQualifiedName(exprName)
                if (symbol != null) return getTypeOfSymbolForTypeQuery(symbol)
                // Fallback: `typeof <value>.<prop>` (e.g. `typeof obj.photo` where `obj` is a
                // VALUE variable) — resolve the type of the value expression. The symbol chain
                // can't reach a property of a value, so without this it returns anyType
                // (excessPropertyChecksWithNestedIntersections `const photo: typeof obj.photo`).
                return resolveTypeOfValueEntityName(exprName) ?: anyType
            }
            else -> return anyType
        }
    }

    /** Resolve `typeof <value>.<prop>...` where the leftmost segment is a value variable:
     *  type of the leftmost value, then walk the property chain via getTargetPropertyType
     *  (which flattens intersections/unions). Returns null if any segment can't resolve. */
    private fun resolveTypeOfValueEntityName(name: Node): Type? = when (name) {
        is Identifier -> {
            // INV.3(d): node-keyed (was the merged `globals` first) — the fast path
            // keeps returning `globals` for non-module-only names, preserving the
            // legacy globals-before-locals order for lib/script names.
            val sym = lookupPerFileForNode(name, name.text) ?: currentFileLocals?.get(name.text)
            sym?.let { getTypeOfSymbol(it) }?.takeIf { it !== anyType && it !== errorType }
        }
        is QualifiedName -> {
            resolveTypeOfValueEntityName(name.left)?.let { leftType ->
                getTargetPropertyType(leftType, name.right.text)
                    ?.takeIf { it !== anyType && it !== errorType }
            }
        }
        else -> null
    }

    /** Get the type of a symbol as it appears in a typeof query.
     *  For classes, returns the constructor type (static side), not the instance type.
     *  For functions/variables, delegates to getTypeOfSymbol. */
    private fun getTypeOfSymbolForTypeQuery(symbol: Symbol): Type {
        val flags = symbol.flags
        return when {
            flags.hasAny(SymbolFlags.Class) -> {
                // typeof ClassName → constructor type with construct signature
                val classType = getDeclaredTypeOfSymbol(symbol)
                if (classType === anyType || classType === errorType) return anyType
                val ctorType = Type.Object()
                ctorType.symbol = symbol
                // Mark `abstract new (...) => X` if the class declaration has the abstract modifier.
                val classDecl = symbol.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
                val isAbstract = classDecl != null && ModifierFlag.Abstract in classDecl.modifiers
                // Use the class's actual constructor parameters (or empty for implicit no-arg
                // ctor). Without real params, structural comparison of `typeof Class` against
                // another constructor-typed target is too loose — see classSideInheritance3
                // where C's 1-param ctor must match A's 1-param ctor through `typeof A`.
                val ctor = classDecl?.members?.filterIsInstance<Constructor>()?.let { ctors ->
                    ctors.firstOrNull { it.body != null } ?: ctors.firstOrNull()
                }
                val params = ctor?.parameters?.let { getParameterSymbols(it) } ?: emptyList()
                val minArgs = ctor?.parameters?.count {
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                } ?: 0
                val ctorSig = Signature(
                    declaration = ctor,
                    parameters = params,
                    resolvedReturnType = classType,
                    minArgumentCount = minArgs,
                    isAbstract = isAbstract,
                )
                ctorType.constructSignatures = listOf(ctorSig)
                // Copy static members from class symbol exports
                val staticProps = mutableListOf<Symbol>()
                val staticMembers = symbolTable()
                symbol.exports?.forEach { (name, exportSym) ->
                    staticProps.add(exportSym)
                    staticMembers[name] = exportSym
                }
                if (staticProps.isNotEmpty()) {
                    ctorType.properties = staticProps
                    ctorType.members = staticMembers
                }
                ctorType
            }
            flags.hasAny(SymbolFlags.Alias) -> {
                val target = resolveAliasTarget(symbol)
                if (target != null && target !== symbol) getTypeOfSymbolForTypeQuery(target) else anyType
            }
            else -> getTypeOfSymbol(symbol)
        }
    }

    /**
     * Build a Type.Object representing the constructor side of a class symbol —
     * a `Type.Object` carrying the class's actual constructor parameter list(s)
     * as its `constructSignatures`. Used for diagnostic display when a class
     * Identifier is used in value position (e.g. `const foo = Foo`); the
     * resulting type is what TypeScript would print as `typeof Foo`.
     *
     * Reads the class declaration's first explicit Constructor member; falls
     * back to a 0-param implicit constructor if none. Marks the construct sig
     * `isAbstract` when the class itself is abstract.
     */
    private fun buildClassValueConstructorTypeForDisplay(symbol: Symbol): Type.Object? {
        val classDecl = symbol.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
            ?: return null
        val classType = getDeclaredTypeOfSymbol(symbol)
        if (classType === anyType || classType === errorType) return null
        val isAbstract = ModifierFlag.Abstract in classDecl.modifiers
        val ctors = classDecl.members.filterIsInstance<Constructor>()
        // Prefer overload signatures (body-less) over the implementation when both are present —
        // matches TypeScript's caller-visible signature set. When no explicit ctor, synthesize
        // a single 0-param signature (the implicit constructor).
        val sigDecls = if (ctors.any { it.body == null && ctors.size > 1 }) {
            ctors.filter { it.body == null }
        } else if (ctors.isNotEmpty()) {
            listOf(ctors.first())
        } else {
            emptyList()
        }
        val sigs = if (sigDecls.isEmpty()) {
            listOf(Signature(
                resolvedReturnType = classType,
                parameters = emptyList(),
                minArgumentCount = 0,
                isAbstract = isAbstract,
            ))
        } else sigDecls.map { ctor ->
            Signature(
                declaration = ctor,
                parameters = getParameterSymbols(ctor.parameters),
                resolvedReturnType = classType,
                minArgumentCount = requiredParameterCount(ctor.parameters),
                isAbstract = isAbstract,
            )
        }
        val ctorType = Type.Object()
        ctorType.symbol = symbol
        ctorType.constructSignatures = sigs
        return ctorType
    }

    /**
     * 17.19: Build the base-class constructor signature for `super(...)` checking,
     * substituting the heritage clause's type arguments for the base class's
     * type parameters. Returns null if the base symbol can't be resolved or has
     * no constructor decl. Picks the first implementation ctor if any; otherwise
     * the first overload decl.
     *
     * @param baseSymbol  The base class's symbol (resolved from the heritage clause)
     * @param typeArgs    Resolved heritage-clause type arguments, or empty list for non-generic
     */
    private fun buildBaseConstructorSignatureForSuper(
        baseSymbol: Symbol,
        typeArgs: List<Type>,
    ): Signature? {
        if (!baseSymbol.flags.hasAny(SymbolFlags.Class)) return null
        val baseDecl = baseSymbol.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration
            ?: return null
        val ctors = baseDecl.members.filterIsInstance<Constructor>()
        // Prefer the implementation (body present); else the first overload decl.
        val ctor = ctors.firstOrNull { it.body != null } ?: ctors.firstOrNull()
        val params = ctor?.parameters?.let { getParameterSymbols(it) } ?: emptyList()
        val minArgs = ctor?.parameters?.count {
            !it.questionToken && !it.dotDotDotToken && it.initializer == null
        } ?: 0
        val baseType = getDeclaredTypeOfSymbol(baseSymbol) as? Type.Interface ?: return null
        val baseTypeParams = baseType.typeParameters.orEmpty()
        // Resolve param types in the base class's type-param scope so `T` resolves to
        // the base's TypeParam (not errorType). Cache into symbolTypes per param.
        if (ctor != null) {
            val ctorScope = if (baseTypeParams.isNotEmpty()) {
                val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                baseTypeParams.forEach { tp ->
                    tp.symbol?.name?.let { scope[it] = tp }
                }
                scope
            } else currentTypeParamScope
            withInstantiationContext(scopeMapper(ctorScope)) {
                for ((pi, paramSym) in params.withIndex()) {
                    if (pi < ctor.parameters.size) {
                        val paramTypeNode = ctor.parameters[pi].type
                        if (paramTypeNode != null) {
                            symbolTypes[paramSym.id] = getTypeFromTypeNode(paramTypeNode)
                        }
                    }
                }
            }
        }
        val rawSig = Signature(
            declaration = ctor,
            parameters = params,
            resolvedReturnType = baseType,
            minArgumentCount = minArgs,
        )
        if (baseTypeParams.isEmpty() || typeArgs.size != baseTypeParams.size) return rawSig
        val mapper = createTypeMapper(baseTypeParams, typeArgs)
        return instantiateSignature(rawSig, mapper)
    }

    /**
     * 17.20: Build the base-class instance type for `super.method(...)` lookups.
     * Returns:
     * - `Type.Reference(baseInterface, typeArgs)` if the base is generic and arity matches
     * - the bare `Type.Interface` if the base is non-generic
     * - the bare `Type.Interface` if arity doesn't match (raw — substitution skipped)
     * - null if the base isn't a class symbol or its declared type isn't an Interface
     */
    private fun buildBaseInstanceTypeForSuper(
        baseSymbol: Symbol,
        typeArgs: List<Type>,
    ): Type? {
        if (!baseSymbol.flags.hasAny(SymbolFlags.Class)) return null
        val baseType = getDeclaredTypeOfSymbol(baseSymbol) as? Type.Interface ?: return null
        val baseTypeParams = baseType.typeParameters.orEmpty()
        if (baseTypeParams.isEmpty()) return baseType
        if (typeArgs.size != baseTypeParams.size) return baseType
        return getOrInternReference(baseType, typeArgs)
    }

    /**
     * 17.20: Resolve and arg-check `super.method(...)` against the base instance
     * type stashed by the ClassDeclaration handler. Returns true if handled
     * (caller skips standard arg-checking), false if not (caller falls through).
     *
     * Conservative — only fires when:
     * - the method is found on the base type
     * - the method has at least one call signature
     * - either: explicit type args resolve cleanly to a generic sig, OR exactly one
     *   non-generic signature (no overload resolution attempt with generics)
     */
    private fun handleSuperMethodCall(
        expr: CallExpression,
        callee: PropertyAccessExpression,
        baseType: Type,
        source: String,
        fileName: String,
    ): Boolean {
        val methodName = callee.name.text
        if (baseType !is Type.Object) return false
        val methodSym = getPropertyOfType(baseType, methodName) ?: return false
        // Resolve method's type with substitution if base is a Reference
        val methodType = if (baseType is Type.Reference) {
            resolveGenericPropertyType(baseType, methodSym) ?: getTypeOfSymbol(methodSym)
        } else {
            getTypeOfSymbol(methodSym)
        }
        if (methodType !is Type.Object) return false
        val sigs = methodType.callSignatures
        if (sigs.isNullOrEmpty()) return false
        val typeArgs = expr.typeArguments
        // Explicit type args: instantiate matching generic sig
        if (!typeArgs.isNullOrEmpty()) {
            val resolvedTypeArgs = typeArgs.map { getTypeFromTypeNode(it) }
            if (resolvedTypeArgs.any { it === errorType }) return false
            val genericSig = sigs.firstOrNull { sig ->
                val tp = sig.typeParameters
                tp != null && tp.size == resolvedTypeArgs.size
            }
            if (genericSig?.typeParameters != null) {
                val mapper = createTypeMapper(genericSig.typeParameters, resolvedTypeArgs)
                val instantiated = instantiateSignature(genericSig, mapper)
                checkArgumentsAgainstSignature(expr.arguments, instantiated, source, fileName)
                return true
            }
            return false
        }
        // No explicit type args: only handle single non-generic signature.
        if (sigs.size == 1 && sigs[0].typeParameters.isNullOrEmpty()) {
            checkArgumentsAgainstSignature(expr.arguments, sigs[0], source, fileName)
            return true
        }
        return false
    }

    /**
     * Generate a TS2322 elaboration chain for a construct-signature mismatch.
     * Mirrors `getFunctionMismatchElaboration` but operates on `constructSignatures`,
     * and prefixes the chain with `Types of construct signatures are incompatible.`
     * to match TypeScript's baseline format (see `assignmentCompatability44/45`).
     *
     * Returns `emptyList()` when neither side has construct sigs or when the
     * single-sig pair is mutually compatible (defensive — caller should only
     * invoke this after confirming `signaturesRelatedTo(... isConstruct=true)`
     * returned false).
     */
    private fun getConstructMismatchElaboration(
        source: Type.Object, target: Type.Object,
    ): List<String> {
        val sourceSigs = source.constructSignatures
        val targetSigs = target.constructSignatures
        if (sourceSigs.isNullOrEmpty() || targetSigs.isNullOrEmpty()) return emptyList()
        val sourceSig = sourceSigs.first()
        val targetSig = targetSigs.first()
        val sourceStr = signatureToString(sourceSig, isConstruct = true)
        val targetStr = signatureToString(targetSig, isConstruct = true)
        val chain = mutableListOf(
            "  Types of construct signatures are incompatible.",
            "    Type '$sourceStr' is not assignable to type '$targetStr'.",
        )
        if (sourceSig.minArgumentCount > targetSig.parameters.size) {
            chain.add(
                "      Target signature provides too few arguments. Expected ${sourceSig.parameters.size} or more, but got ${targetSig.parameters.size}."
            )
            return chain
        }
        // Per-parameter contravariant check
        val len = minOf(sourceSig.parameters.size, targetSig.parameters.size)
        for (i in 0 until len) {
            val sp = getTypeOfSymbol(sourceSig.parameters[i])
            val tp = getTypeOfSymbol(targetSig.parameters[i])
            if (!checkTypeRelatedTo(tp, sp, assignableRelation)) {
                // B9.1: binding-pattern synthesized params have empty `Symbol.name`;
                // render as `_` here (consistent with formatParameter).
                val sName = sourceSig.parameters[i].let { p ->
                    if (p.name.isEmpty() && (p.valueDeclaration as? Parameter)?.name.let {
                            it is ObjectBindingPattern || it is ArrayBindingPattern
                        }) "_" else p.name
                }
                val tName = targetSig.parameters[i].let { p ->
                    if (p.name.isEmpty() && (p.valueDeclaration as? Parameter)?.name.let {
                            it is ObjectBindingPattern || it is ArrayBindingPattern
                        }) "_" else p.name
                }
                chain.add(
                    "      Types of parameters '$sName' and '$tName' are incompatible."
                )
                chain.add("        Type '${typeToString(tp)}' is not assignable to type '${typeToString(sp)}'.")
                return chain
            }
        }
        // Return-type mismatch (covariant)
        val sourceRet = sourceSig.resolvedReturnType ?: anyType
        val targetRet = targetSig.resolvedReturnType ?: anyType
        if (!targetRet.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceRet, targetRet, assignableRelation)) {
            chain.add("      Type '${typeToString(sourceRet)}' is not assignable to type '${typeToString(targetRet)}'.")
        }
        return chain
    }

    /** Create a Type from a literal type node (e.g., `type X = "hello"` or `type Y = 42`). */
    private fun getTypeFromLiteralTypeNode(node: LiteralType): Type {
        return when (val literal = node.literal) {
            is StringLiteralNode -> Type.StringLiteral(literal.text)
            is NumericLiteralNode -> {
                val value = literal.text.toDoubleOrNull() ?: 0.0
                Type.NumberLiteral(value)
            }
            is BigIntLiteralNode -> Type.BigIntLiteral(literal.text.removeSuffix("n"))
            is Identifier -> when (literal.text) {
                "true" -> trueType
                "false" -> falseType
                else -> errorType
            }
            is PrefixUnaryExpression -> {
                // -42, -1n, etc.
                if (literal.operator == SyntaxKind.Minus) {
                    when (val operand = literal.operand) {
                        is NumericLiteralNode -> {
                            val value = -(operand.text.toDoubleOrNull() ?: 0.0)
                            Type.NumberLiteral(value)
                        }
                        is BigIntLiteralNode -> Type.BigIntLiteral("-${operand.text.removeSuffix("n")}")
                        else -> errorType
                    }
                } else errorType
            }
            else -> errorType
        }
    }

    /** Create a function type from a FunctionType node. */
    private fun getFunctionTypeFromNode(node: FunctionType): Type {
        val fnType = Type.Object()
        val sig = buildSignatureForFunctionLikeTypeNode(
            decl = node, typeParamDecls = node.typeParameters,
            params = node.parameters, returnTypeNode = node.type,
        )
        fnType.callSignatures = listOf(sig)
        return fnType
    }

    /** Create a constructor type from a ConstructorType node. */
    private fun getFunctionTypeFromConstructorNode(node: ConstructorType): Type {
        val ctorType = Type.Object()
        val sig = buildSignatureForFunctionLikeTypeNode(
            decl = node, typeParamDecls = node.typeParameters,
            params = node.parameters, returnTypeNode = node.type,
        )
        ctorType.constructSignatures = listOf(sig)
        return ctorType
    }

    /**
     * 17.10b: Shared signature builder for `FunctionType` / `ConstructorType` nodes.
     * Builds Type.TypeParam objects from `typeParamDecls`, pushes them into
     * `currentTypeParamScope`, eagerly resolves param types within that scope
     * (cached via `symbolTypes`), then resolves the return type. Without the
     * scope, type-param-named annotations like `<T>(x: T) => T`'s `T` resolve
     * via global lookup and the displayed signature drops `<T>` and shows raw `T`.
     */
    private fun buildSignatureForFunctionLikeTypeNode(
        decl: Node, typeParamDecls: List<TypeParameter>?,
        params: List<Parameter>, returnTypeNode: TypeNode?,
    ): Signature {
        val sigTypeParams = typeParamDecls?.map { tpDecl ->
            // B59.5: intern by TypeParameter AST position (mirrors B59.1/2 pattern at
            // FunctionExpression site ~51865 — FunctionType/ConstructorType TypeNodes
            // are TYPE-position annotations resolved many times during checking;
            // sharing identity across calls lets downstream caches keyed on Type.id
            // (e.g. substitutionResultCache) actually hit. Constraints/defaults are
            // re-resolved per call below (no null guard) to preserve original
            // per-call constraint-scope semantics — a 'null guard' regressed -1.
            typeParamInternCache.getOrPut(internKey(tpDecl)) {
                Type.TypeParam().also { tp ->
                    tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
                }
            }
        }
        val sigScope = if (!sigTypeParams.isNullOrEmpty()) {
            val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
            sigTypeParams.forEachIndexed { i, tp ->
                scope[typeParamDecls[i].name.text] = tp
            }
            scope
        } else currentTypeParamScope
        val (returnType, paramSyms) = withInstantiationContext(scopeMapper(sigScope)) {
            val ps = getParameterSymbols(params)
            sigTypeParams?.forEachIndexed { i, tp ->
                typeParamDecls[i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                typeParamDecls[i].default?.let { tp.default = getTypeFromTypeNode(it) }
            }
            if ((params.firstOrNull()?.name as? Identifier)?.text == "this") {
                // Round 730 (mirrors round 460 at the function-DECLARATION site):
                // getParameterSymbols DROPS the `this` pseudo-parameter, so the
                // positional zip below shifted every parameter type by one for a
                // this-carrying FunctionType/ConstructorType annotation — the real
                // lib's `flatMap(cb: (this: This, value: T, index: number, array:
                // T[]) => …)` displayed `value: This, index: T, array: number`.
                // Resolve each symbol's type from its OWN valueDeclaration instead.
                for (param in ps) {
                    (param.valueDeclaration as? Parameter)?.type?.let { typeNode ->
                        symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                    }
                }
            } else {
                // Legacy positional zip — DELIBERATELY kept for parameter lists
                // without a `this` param (a binding-pattern param is also dropped
                // from `ps`, and the shift keeps sig.parameters[i] carrying
                // params[i]'s type, which call-site arg alignment relies on).
                for ((pi, param) in ps.withIndex()) {
                    if (pi < params.size) {
                        params[pi].type?.let { typeNode ->
                            symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                        }
                    }
                }
            }
            (returnTypeNode?.let { getTypeFromTypeNode(it) } ?: anyType) to ps
        }
        return Signature(
            declaration = decl,
            typeParameters = sigTypeParams,
            parameters = paramSyms,
            resolvedReturnType = returnType,
            minArgumentCount = requiredParameterCount(params),
        )
    }

    /** Create an object type from a TypeLiteral node (e.g., `{ x: number; y: string }`). */
    private fun getTypeFromTypeLiteral(node: TypeLiteral): Type {
        val members = mutableMapOf<String, Symbol>()
        val properties = mutableListOf<Symbol>()
        val callSignatures = mutableListOf<Signature>()
        val constructSignatures = mutableListOf<Signature>()
        // Detect mapped-type placeholder — the parser emits PropertyDeclaration(name="")
        // for `[K in T]:` constructs inside a TypeLiteral (see parseIndexSignatureOrProperty).
        // When present, treat the entire literal as an opaque mapped type (→ anyType)
        // because we can't enumerate members precisely.
        var sawMappedTypePlaceholder = false
        // Round 938 — (CHK.5)(b): the own PROPERTY names already declared by this literal.
        val ownLiteralPropertyNames = HashSet<String>()
        for (member in node.members) {
            when (member) {
                is PropertyDeclaration -> {
                    // Round 937 — (CHK.5)(a): a TYPE LITERAL's members are the THIRD
                    // independent re-spelling of this `when` (B451), and it was the one
                    // that still knew nothing about a computed key at all — so
                    // `type T = { ["s"]: number }` and `type T = { [K]: number }` alike
                    // declared NO member and `t.s` / `t.p` FP'd TS2339 on `{}`, where
                    // tsc reads them as ordinary members (measured, 7.0.2).
                    val name = declaredMemberName(member.name) ?: continue
                    if (name.isEmpty()) {
                        // Parser placeholder for `[K in T]: V` — skip; emit anyType for the literal.
                        sawMappedTypePlaceholder = true
                        continue
                    }
                    // Round 938 — (CHK.5)(b): a duplicate property in a TYPE LITERAL is
                    // FIRST-WINS, exactly as in an interface or a class body (measured:
                    // `type T = { p: number; p: string }` reads `number` in tsc and read
                    // `string` here). A type literal has no base types and no statics, so
                    // the guard is the plain one — but it is still PROPERTY-vs-PROPERTY
                    // only (a method arm writes this same map, and a property beside a
                    // method keeps today's resolution), and it must also refuse to append a
                    // SECOND entry to [properties], which is what the display and every
                    // member enumeration read.
                    if (!ownLiteralPropertyNames.add(name)) continue
                    val propType = if (member.type != null) getTypeFromTypeNode(member.type) else anyType
                    val sym = Symbol(SymbolFlags.Property, name)
                    sym.declarations.add(member)
                    sym.valueDeclaration = member
                    members[name] = sym
                    properties.add(sym)
                    symbolTypes[sym.id] = propType
                }
                is MethodDeclaration -> {
                    val nameNode = member.name
                    // Round 937 — (CHK.5)(a): as above, and note the `else` here is `""`
                    // (a CALL signature) rather than `continue`, so a computed METHOD name
                    // that could not be named was silently read as a call signature. Only a
                    // name node this namer refuses still falls through to that reading.
                    val name = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        is ComputedPropertyName -> declaredMemberName(nameNode) ?: ""
                        else -> ""
                    }
                    // 17.10a: Build the call/construct/method signature's own type
                    // parameters and push them into the type-param scope so
                    // `<Tstring>(a: Tstring): Tstring` resolves the `Tstring`
                    // annotations to our TypeParam (instead of falling through to
                    // global lookup → errorType → display `(a: error) => any`).
                    // B59.7: intern by TypeParameter AST position (mirrors B59.5 at
                    // buildSignatureForFunctionLikeTypeNode site ~69044). TypeLiteral
                    // MethodDeclaration TypeParams are TYPE-position annotations
                    // resolved many times during checking; identity-stable instances
                    // let downstream id-keyed caches (substitutionResultCache,
                    // referenceCache) actually hit. Constraints/defaults are re-resolved
                    // per call below (no null guard) — matching B59.5's note that the
                    // null guard regressed there.
                    val sigTypeParams = member.typeParameters?.map { tpDecl ->
                        typeParamInternCache.getOrPut(internKey(tpDecl)) {
                            Type.TypeParam().also { tp ->
                                tp.symbol = Symbol(SymbolFlags.TypeParameter, tpDecl.name.text)
                            }
                        }
                    }
                    val memberScope = if (!sigTypeParams.isNullOrEmpty()) {
                        val scope = (currentTypeParamScope?.toMutableMap() ?: mutableMapOf())
                        sigTypeParams.forEachIndexed { i, tp ->
                            scope[member.typeParameters[i].name.text] = tp
                        }
                        scope
                    } else currentTypeParamScope
                    val (returnType, params) = withInstantiationContext(scopeMapper(memberScope)) {
                        val ps = getParameterSymbols(member.parameters)
                        sigTypeParams?.forEachIndexed { i, tp ->
                            member.typeParameters[i].constraint?.let { tp.constraint = getTypeFromTypeNode(it) }
                            member.typeParameters[i].default?.let { tp.default = getTypeFromTypeNode(it) }
                        }
                        for ((pi, param) in ps.withIndex()) {
                            if (pi < member.parameters.size) {
                                member.parameters[pi].type?.let { typeNode ->
                                    symbolTypes[param.id] = getTypeFromTypeNode(typeNode)
                                }
                            }
                        }
                        (member.type?.let { getTypeFromTypeNode(it) } ?: anyType) to ps
                    }
                    val sig = Signature(
                        declaration = member,
                        typeParameters = sigTypeParams,
                        parameters = params,
                        resolvedReturnType = returnType,
                        minArgumentCount = requiredParameterCount(member.parameters),
                    )
                    if (name.isEmpty()) {
                        // Call signature: MethodDeclaration with empty name
                        callSignatures.add(sig)
                    } else if (name == "new") {
                        // Construct signature: MethodDeclaration with name "new"
                        constructSignatures.add(sig)
                    } else {
                        // Named method member. A repeated name is an OVERLOAD (`f(n):string; f(s):number;`):
                        // APPEND the signature to the existing method's callSignatures instead of
                        // overwriting — otherwise only the LAST overload survives and assignability
                        // against a multi-call-signature target FP's TS2322 (typeMatch1).
                        val existing = members[name]
                        val existingType = existing?.let { symbolTypes[it.id] }
                        if (existing != null && existingType is Type.Object &&
                            !existingType.callSignatures.isNullOrEmpty() && existingType.properties.isNullOrEmpty()) {
                            existing.declarations.add(member)
                            existingType.callSignatures = existingType.callSignatures!! + sig
                        } else {
                            val sym = Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                            sym.declarations.add(member)
                            sym.valueDeclaration = member
                            members[name] = sym
                            properties.add(sym)
                            val methodType = Type.Object()
                            methodType.callSignatures = listOf(sig)
                            methodType.properties = emptyList()
                            symbolTypes[sym.id] = methodType
                        }
                    }
                }
                is IndexSignature -> {
                    // Handled in second pass below
                }
                is Constructor -> {
                    val params = getParameterSymbols(member.parameters)
                    constructSignatures.add(Signature(
                        declaration = member,
                        parameters = params,
                        resolvedReturnType = anyType,
                        minArgumentCount = requiredParameterCount(member.parameters),
                    ))
                }
                else -> continue
            }
        }
        // Second pass: collect index signatures
        var stringIndexInfo: IndexInfo? = null
        var numberIndexInfo: IndexInfo? = null
        for (member in node.members) {
            if (member is IndexSignature) {
                val indexType = member.type?.let { getTypeFromTypeNode(it) } ?: anyType
                val paramType = member.parameters.firstOrNull()?.type
                val isNumber = paramType is KeywordTypeNode && paramType.kind == SyntaxKind.NumberKeyword
                val info = IndexInfo(
                    keyType = if (isNumber) numberType else stringType,
                    type = indexType,
                    isReadonly = ModifierFlag.Readonly in member.modifiers,
                    declaration = member,
                )
                if (isNumber) numberIndexInfo = info else stringIndexInfo = info
            }
        }
        // If the literal was purely a mapped-type placeholder, return anyType —
        // enumerable members aren't known, so suppress member-level diagnostics.
        if (sawMappedTypePlaceholder && members.isEmpty() && callSignatures.isEmpty() &&
            constructSignatures.isEmpty() && stringIndexInfo == null && numberIndexInfo == null
        ) return anyType
        val objType = Type.Object()
        objType.members = members
        objType.properties = properties
        if (callSignatures.isNotEmpty()) objType.callSignatures = callSignatures
        if (constructSignatures.isNotEmpty()) objType.constructSignatures = constructSignatures
        objType.stringIndexInfo = stringIndexInfo
        objType.numberIndexInfo = numberIndexInfo
        return objType
    }

    /** Handle TypeOperator nodes (keyof, unique, readonly). */
    private fun getTypeFromTypeOperator(node: TypeOperator): Type {
        return when (node.operator) {
            SyntaxKind.KeyOfKeyword ->
                keyofTypeQueryEnumMemberNames(node.type)
                    ?: run {
                        val operand = getTypeFromTypeNode(node.type)
                        getKeyofType(operand)
                    }
            SyntaxKind.UniqueKeyword -> esSymbolType // unique symbol
            SyntaxKind.ReadonlyKeyword -> {
                // `readonly T[]` shorthand: route to globalReadonlyArrayType so the
                // resulting Type.Reference exposes ReadonlyArray's read-only surface
                // (no `push`/`pop`/etc.) — pairs with the `ReadonlyArray<T>` branch in
                // `getTypeFromTypeReference`. For other shapes (e.g. `readonly [T, U]`
                // tuple) the readonly modifier is a no-op at the type level (TS only
                // surfaces it via narrower assignment rules we don't yet model).
                val inner = node.type
                if (inner is ArrayType && globalReadonlyArrayType != null) {
                    val elt = getTypeFromTypeNode(inner.elementType)
                    return getOrInternReference(globalReadonlyArrayType!!, listOf(elt))
                }
                getTypeFromTypeNode(node.type)
            }
            else -> anyType
        }
    }

    /**
     * Resolve a MappedType: { [K in C]: T }
     * Creates an object type with one property per key in the constraint C.
     * e.g., { [K in "a" | "b"]: number } → { a: number; b: number }
     * e.g., { [K in keyof T]: T[K] } → homomorphic mapped type
     */
    /**
     * B192: evaluate a mapped-type `as` template-literal key remap for a single [key].
     * [rawText] is the raw template source (B65.1: spans are never parsed — only
     * head.rawText exists), with or without surrounding backticks. Requires EXACTLY one
     * placeholder whose trimmed content is the mapped TP name or `Extract<TP, string>`;
     * returns prefix + key + suffix, or null for any other shape.
     */
    private fun evalMappedKeyRemapTemplate(rawText: String, tpName: String, key: String): String? {
        var t = rawText
        if (t.startsWith("`")) t = t.removePrefix("`")
        if (t.endsWith("`")) t = t.removeSuffix("`")
        val open = t.indexOf("\${")
        if (open < 0) return null
        val close = t.indexOf('}', open)
        if (close < 0) return null
        if (t.indexOf("\${", close) >= 0) return null  // more than one placeholder
        val content = t.substring(open + 2, close).trim()
        val extractRe = Regex("Extract\\s*<\\s*${Regex.escape(tpName)}\\s*,\\s*string\\s*>")
        if (content != tpName && !extractRe.matches(content)) return null
        return t.substring(0, open) + key + t.substring(close + 1)
    }

    /**
     * B201: the INDEX-SIGNATURE value type of an element access, or null when the access
     * hits a DECLARED member (the `match[0]` firewall — RegExpMatchArray's explicit
     * `0: string`), a tuple, or an unresolvable receiver. Falls back to a base
     * Reference-to-Array's element type when the interface declares no own index info.
     */
    private fun elementAccessIndexSigValueType(expr: ElementAccessExpression): Type? {
        val recvType = getTypeOfExpression(expr.expression)
        if (recvType !is Type.Object) return null
        resolveStructuredTypeMembers(recvType)
        if (recvType.tupleElementTypes != null) return null
        var arg: Expression = expr.argumentExpression
        while (arg is ParenthesizedExpression) arg = arg.expression
        val idxText = when (arg) {
            is NumericLiteralNode -> arg.text
            is StringLiteralNode -> arg.text
            else -> return null
        }
        if (recvType.members?.containsKey(idxText) == true) return null
        recvType.numberIndexInfo?.let { return it.type }
        recvType.stringIndexInfo?.let { return it.type }
        // Inherited index signature: a base Reference to Array<E> supplies E.
        val bases = (recvType as? Type.Interface)?.baseTypes ?: return null
        for (b in bases) {
            if (b is Type.Reference && b.target.symbol?.name == "Array") {
                return b.resolvedTypeArguments?.firstOrNull()
            }
        }
        return null
    }

    private fun getTypeFromMappedType(node: MappedType): Type {
        // B57.3b: depth-bail to signal excessive recursion. Mirror the alias-
        // substitution depth-bail pattern at getTypeFromTypeReference (~50362).
        // When a mapped type's value type recursively expands deeply, set the
        // deepInstantiationBailed flag so outer callers can emit TS2589.
        if (mappedTypeResolutionDepth >= MAPPED_TYPE_MAX_DEPTH) {
            deepInstantiationBailed = true
            return anyType
        }
        // Resolve the constraint type (e.g., keyof T, "a" | "b", string)
        val constraint = node.typeParameter.constraint
        if (constraint == null) return anyType
        val constraintType = getTypeFromTypeNode(constraint)
        if (constraintType === anyType || constraintType === errorType) return anyType
        // Collect all keys from the constraint
        var keys = when (constraintType) {
            is Type.StringLiteral -> listOf(constraintType.value)
            // Round 463: a union with ANY non-string-literal constituent has an
            // UNKNOWABLE key domain — `[K in keyof T & Keys | StrictKeys]` with T
            // un-inferred (tsc's createComputedCompilerOptions) resolved only the
            // StrictKeys members, and the partial domain manufactured an
            // excess-property TS2353 on a genuinely-valid key (utilities.ts:9042).
            // Bail to anyType like the non-literal `else` branch instead of
            // silently enumerating the partial set.
            is Type.Union -> {
                val lits = constraintType.types.map { it as? Type.StringLiteral }
                if (lits.any { it == null }) return anyType
                lits.map { it!!.value }
            }
            else -> return anyType // Can't enumerate keys for non-literal constraints
        }
        if (keys.isEmpty()) return anyType
        // B192: `as` key-remapping. Previously node.nameType was silently IGNORED, so an
        // `as`-remapped mapped type produced WRONG member names. Handle the template-
        // literal remap shape (`${K}suffix` / `${Extract<K, string>}suffix`) and bail to
        // anyType (the prior effective behavior for unmodeled shapes) on anything else.
        val nameType = node.nameType
        if (nameType != null) {
            if (nameType !is TemplateLiteralType) return anyType
            val raw = nameType.head.rawText ?: return anyType
            keys = keys.map {
                evalMappedKeyRemapTemplate(raw, node.typeParameter.name.text, it) ?: return anyType
            }
        }
        val isOutermost = mappedTypeResolutionDepth == 0
        // B57.3c: capture bail-flag transition at the outermost mapped-type call so
        // we can record TS2615 circular-property info only when the bail actually
        // originates inside this mapped type's body resolution.
        val savedBailAtEntry = deepInstantiationBailed
        mappedTypeResolutionDepth++
        try {
            // Build the mapped object type
            val result = Type.Object()
            val members = symbolTable()
            val properties = mutableListOf<Symbol>()
            val typeParamName = node.typeParameter.name.text
            // Homomorphic mapped type `[K in keyof T]`: resolve the modifiers type T so each
            // synthesized member can carry its SOURCE property's declaration (for "declared
            // here" TS6500/TS2728 related info — excessPropertyChecksWithNestedIntersections).
            val homomorphicSourceType: Type? = (node.nameType == null).let { noRemap ->
                if (!noRemap) null else (constraint as? TypeOperator)
                    ?.takeIf { it.operator == SyntaxKind.KeyOfKeyword }
                    ?.let { getTypeFromTypeNode(it.type) }
                    ?.takeIf { it !== anyType && it !== errorType }
            }
            for (key in keys) {
                val propType = if (node.type != null) {
                    // Bind the mapped key parameter K to the current key (a string literal) so
                    // the value type `T[K]` (and conditionals over it) resolve PER KEY instead
                    // of bailing to anyType — e.g. View<T> = { [K in keyof T]: T[K] extends
                    // object ? boolean | View<T[K]> : boolean }
                    // (excessPropertyChecksWithNestedIntersections). An alias-args
                    // mapper bypasses the plain nodeTypes cache so each key resolves freshly.
                    getTypeFromTypeNodeWithMapper(node.type, layeredAliasMapper(mapOf(typeParamName to Type.StringLiteral(key))))
                } else anyType
                val sym = Symbol(SymbolFlags.Property, key)
                homomorphicSourceType?.let { srcT ->
                    getPropertyOfType(srcT, key)?.declarations?.firstOrNull()?.let { sym.declarations.add(it) }
                }
                // M1.10: `-readonly` STRIPS readonly — the carried source declaration
                // may have the modifier, so mark the member writable via the side-channel.
                // The plain `readonly` TOKEN (`{ readonly [K in keyof T]: T[K] }`) ADDS
                // readonly-ness the same way the Readonly<T> utility materializer does.
                if (node.readonlyMinus) mappedMutableMemberIds.add(sym.id)
                else if (node.readonlyToken) mappedReadonlyMemberIds.add(sym.id)
                // Round 718: `-?` STRIPS optionality, the exact `?` analogue of the
                // `-readonly` case above — and it needs the same side-channel for the
                // same reason: the carried source declaration still has its `?`.
                if (node.questionMinus) mappedRequiredMemberIds.add(sym.id)
                // Round 728: the plain `?` token ADDS optionality (`Partial<T>`), exactly
                // as the plain `readonly` token above adds readonly-ness — and it was the
                // one modifier of the four never recorded, so `Partial<T>`'s members stayed
                // REQUIRED unless the source property happened to be optional too.
                else if (node.questionToken) sym.flags = sym.flags or SymbolFlags.MappedOptional
                members[key] = sym
                properties.add(sym)
                symbolTypes[sym.id] = propType
            }
            result.members = members
            result.properties = properties
            // B57.3c: at the outermost mapped-type level, if the bail flag was raised
            // inside body resolution (and wasn't already set on entry), record info
            // about THIS mapped type so the alias-body consumer can emit TS2615
            // ("Type of property 'X' circularly references itself in mapped type '...'.").
            // Display: `{ [P in "K1" | "K2" | ...]: any; }` — readonly/optional modifiers
            // are not yet plumbed through; matches the simple test cases like
            // `recursivelyExpandingUnionNoStackoverflow_ts`.
            if (isOutermost && deepInstantiationBailed && !savedBailAtEntry &&
                mappedTypeCircularInfo == null) {
                val firstKey = keys.first()
                val paramName = typeParamName
                val keyDisplay = if (keys.size == 1) "\"${keys[0]}\""
                    else keys.joinToString(" | ") { "\"$it\"" }
                val display = "{ [$paramName in $keyDisplay]: any; }"
                mappedTypeCircularInfo = firstKey to display
            }
            return result
        } finally {
            mappedTypeResolutionDepth--
        }
    }

    /**
     * Resolve a ConditionalType: T extends U ? X : Y
     * - If T and U are concrete: evaluate isTypeRelatedTo(T, U) and return X or Y
     * - If T is a union: distribute — (A | B) extends U ? X : Y → (A extends U ? X : Y) | (B extends U ? X : Y)
     * - If T is an unresolved type parameter: return anyType (can't evaluate)
     */
    private fun getTypeFromConditionalType(node: ConditionalType): Type {
        val checkType = getTypeFromTypeNode(node.checkType)
        if (checkType === anyType || checkType === errorType) return anyType
        // Unresolved type parameter — can't evaluate
        if (checkType is Type.TypeParam) return anyType
        // B119: `X extends Ref<...infer V...> ? V : ...` — when the extends-type is a
        // TypeReference carrying top-level `infer` placeholders and checkType is a
        // concrete Reference to the same target, bind the infer vars by positional
        // unification and resolve the chosen branch. Without this the extends-type
        // resolves to errorType (infer unresolvable) → the whole conditional returns
        // anyType, masking the inferred result (e.g. `SyntheticDestination<number,
        // Synthetic<number,number>>` should resolve to `number`, not `any`).
        tryEvaluateConditionalWithInfer(checkType, node)?.let { return it }
        val extendsType = getTypeFromTypeNode(node.extendsType)
        if (extendsType === anyType || extendsType === errorType) return anyType
        // Distribution over unions
        if (checkType is Type.Union) {
            // Round 729: inside a DISTRIBUTIVE conditional the check type parameter denotes
            // the CONSTITUENT being tested, not the whole union — `Exclude<T, U> = T extends U
            // ? never : T` is exactly that, and its `T` branch is the only thing that makes it
            // a filter. Without the rebinding, every non-matching constituent contributed the
            // ENTIRE union back and `Exclude` was an identity function: tsc's
            // `Exclude<BindableStaticNameExpression, Identifier>` (utilities.ts:4258) kept
            // `Identifier` and then failed to assign to `AccessExpression`. Only a NAKED type
            // parameter distributes, so the rebinding is keyed on the check type NODE being a
            // bare reference to one — every other shape keeps the previous evaluation.
            val distributedName = nakedCheckTypeParamName(node.checkType)
            val results = checkType.types.map { constituent ->
                if (distributedName == null) evaluateConditional(constituent, extendsType, node)
                else withInstantiationContext(
                    distributionMapper(distributedName, constituent),
                ) { evaluateConditional(constituent, extendsType, node) }
            }
            return getUnionType(results)
        }
        return evaluateConditional(checkType, extendsType, node)
    }

    /**
     * Round 729: the name of the check type's NAKED type parameter, when [node] is a bare
     * reference to one currently bound as a type-alias argument — the condition under which
     * tsc makes a conditional type DISTRIBUTIVE. Null for every other check-type shape
     * (`[T] extends [U]`, a concrete union, an instantiated reference), which is what keeps
     * the rebinding from reaching a non-distributive conditional.
     */
    private fun nakedCheckTypeParamName(node: TypeNode): String? {
        val ref = node as? TypeReference ?: return null
        if (!ref.typeArguments.isNullOrEmpty()) return null
        val name = (ref.typeName as? Identifier)?.text ?: return null
        return if (currentTypeAliasArgs?.containsKey(name) == true) name else null
    }

    /** Round 729: the ambient context with [name] rebound to one distribution [constituent].
     *  The type-param scope is consulted BEFORE the alias args in [getTypeFromTypeReference],
     *  so a same-named scope entry must be dropped or it would shadow the binding. */
    private fun distributionMapper(name: String, constituent: Type): InstantiationMapper =
        InstantiationMapper(
            (currentTypeAliasArgs ?: emptyMap()) + (name to constituent),
            currentTypeParamScope?.let { if (name in it) it - name else it },
            inferenceNamespaceStack.size,
        )

    /**
     * B119: positional `infer` unification for `X extends Ref<...> ? ... : ...`.
     * Returns the resolved TRUE branch (with infer vars bound) only when checkType
     * is a concrete [Type.Reference] to the same target as the extends-clause
     * TypeReference and all non-infer argument positions are assignable. Returns
     * null in every other case so the caller falls back to the existing behavior
     * (which yields anyType for an infer-bearing extends-type) — this keeps the
     * behavior change confined to genuinely-related infer-conditionals, bounding
     * the FP surface.
     */
    private fun tryEvaluateConditionalWithInfer(checkType: Type, node: ConditionalType): Type? {
        val extAst = node.extendsType as? TypeReference ?: return null
        val extArgs = extAst.typeArguments ?: return null
        if (extArgs.none { it is InferType }) return null
        val checkRef = checkType as? Type.Reference ?: return null
        val checkArgs = checkRef.resolvedTypeArguments ?: return null
        if (checkArgs.size != extArgs.size) return null
        // Same target interface (compare by name — robust to symbol-instance identity
        // across merges; the arity + per-position assignability gate prevents FP).
        val extName = getTypeReferenceLastName(extAst.typeName) ?: return null
        if (checkRef.target.symbol?.name != extName) return null
        val bindings = HashMap<String, Type>()
        for (i in extArgs.indices) {
            val a = extArgs[i]
            if (a is InferType) {
                bindings[a.typeParameter.name.text] = checkArgs[i]
            } else {
                val patternArg = getTypeFromTypeNode(a)
                if (patternArg === errorType) return null
                // Non-infer position must accept checkType's arg for the true branch.
                if (!checkTypeRelatedTo(checkArgs[i], patternArg, assignableRelation)) return null
            }
        }
        // Related — resolve the true branch with the inferred bindings layered onto
        // the alias-arg substitution map (consulted by getTypeFromTypeReference's
        // bare-name lookup; a non-null map also bypasses the plain nodeTypes cache).
        return getTypeFromTypeNodeWithMapper(node.trueType, layeredAliasMapper(bindings))
    }

    private fun evaluateConditional(checkType: Type, extendsType: Type, node: ConditionalType): Type {
        // Check if checkType extends extendsType
        // Round 729 bolted the round-472 `.kind` DOMAIN veto onto this conjunction,
        // because enum-member types did not discriminate in our relation
        // (`kind: SyntaxKind.Identifier` accepted `SyntaxKind.PrivateIdentifier`) and a
        // structural verdict alone called sibling AST interfaces mutually assignable —
        // so `Exclude<PropertyName, PrivateIdentifier>` silently dropped `Identifier`
        // too, the moment distribution started working.
        //
        // (REL.1)(c) step 5c, round 753: DELETED, because (REL.1)(a)/(b) removed the
        // premise — the relation discriminates enum members on its own now. Round 729's
        // own pin (`a sibling AST interface is not excluded just because it is
        // structurally compatible`, DistributiveConditionalTypeTest) passes without it,
        // which is the specific evidence: the pin that motivated the patch no longer
        // needs it. See `narrowTypeByTypeGuard`'s negative branch for the profile-wide
        // ablation (11,667 suppressed verdicts, output byte-identical).
        val related = isSimpleTypeRelatedTo(checkType, extendsType) ||
            checkTypeRelatedTo(checkType, extendsType, assignableRelation)
        return if (related) {
            getTypeFromTypeNode(node.trueType)
        } else {
            getTypeFromTypeNode(node.falseType)
        }
    }

    /**
     * Resolve an IndexedAccessType node: T[K] → the type of property K on T.
     * e.g., `{ a: number; b: string }["a"]` → `number`
     */
    private fun getTypeFromIndexedAccess(node: IndexedAccessType): Type {
        val objectTypeRaw = getTypeFromTypeNode(node.objectType)
        // B156: resolve `T[K]` through a type parameter's constraint (apparent type)
        // so `T["b"]` (T extends { b: string }) → string rather than anyType.
        val objectType = if (objectTypeRaw is Type.TypeParam) getApparentType(objectTypeRaw) else objectTypeRaw
        val indexType = getTypeFromTypeNode(node.indexType)
        if (objectType === anyType || objectType === errorType) return anyType
        if (indexType === anyType || indexType === errorType) return anyType
        return getIndexedAccessType(objectType, indexType)
    }

    /**
     * Resolve T[K] at the type level:
     * - String literal K → look up named property
     * - Number → number index signature type
     * - Union K → union of T[each constituent]
     * - keyof T → union of all property types
     */
    private fun getIndexedAccessType(objectType: Type, indexType: Type): Type {
        // B516: distribute over a UNION object type — `(A | B)["a"]` → `A["a"] | B["a"]`.
        // Without this, `getPropertyOfType(A | B, "a")` collapses to a single member's
        // property type (or null), so `T["a"]` (T extends A|B) never resolves to the
        // union of member property types tsc produces.
        if (objectType is Type.Union) {
            val parts = objectType.types.map { getIndexedAccessType(it, indexType) }
            if (parts.any { it === anyType || it === errorType }) return anyType
            return getUnionType(parts)
        }
        // String literal key: T["prop"] → type of property "prop"
        if (indexType is Type.StringLiteral) {
            val prop = getPropertyOfType(objectType, indexType.value)
            // (REL.2) round 783: read the property THROUGH its carrier. An interface
            // member's symbol is SHARED by every instantiation and its cached type for a
            // type-parameter-typed member is globally `any` (round 761), so
            // `getTypeOfSymbol` answered `any` for every `Token<SK.X>["kind"]` — and the
            // union arm above turns one `any` part into an `any` whole, which is how
            // tsc's own `Modifier["kind"]` (the `isModifierKind` predicate target)
            // resolved to `any` and narrowed nothing.
            if (prop != null) return (objectType as? Type.Object)
                ?.takeIf { R783_INDEXED_ACCESS_CARRIER }
                ?.let { propertyTypeOnCarrier(it, prop) }
                ?: getTypeOfSymbol(prop)
            // Check string index signature
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val strIdx = objectType.stringIndexInfo
                if (strIdx != null) return strIdx.type
            }
            return anyType
        }
        // Number literal key: T[0] → type of property "0" (tuple)
        if (indexType is Type.NumberLiteral) {
            val idx = indexType.value.toInt().toString()
            val prop = getPropertyOfType(objectType, idx)
            if (prop != null) return getTypeOfSymbol(prop)
            // Check number index signature
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val numIdx = objectType.numberIndexInfo
                if (numIdx != null) return numIdx.type
            }
            return anyType
        }
        // Number type as index: T[number] → number index signature type
        if (indexType.flags.hasAny(TypeFlags.Number or TypeFlags.NumberLike)) {
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val numIdx = objectType.numberIndexInfo
                if (numIdx != null) return numIdx.type
                // For tuple types, return union of all element types
                val tupleTypes = objectType.tupleElementTypes
                if (tupleTypes != null && tupleTypes.isNotEmpty()) {
                    return getUnionType(tupleTypes)
                }
            }
            return anyType
        }
        // String type as index: T[string] → string index signature type
        if (indexType.flags.hasAny(TypeFlags.String or TypeFlags.StringLike)) {
            if (objectType is Type.Object) {
                resolveStructuredTypeMembers(objectType)
                val strIdx = objectType.stringIndexInfo
                if (strIdx != null) return strIdx.type
            }
            return anyType
        }
        // Union index: T[A | B] → T[A] | T[B]
        if (indexType is Type.Union) {
            val types = indexType.types.map { getIndexedAccessType(objectType, it) }
                .filter { it !== anyType }
            if (types.isNotEmpty()) return getUnionType(types)
            return anyType
        }
        return anyType
    }

    /**
     * Get the keyof type for a type: produces a union of string literal types for each
     * property name. e.g., `keyof { a: number; b: string }` → `"a" | "b"`.
     */
    /**
     * Round 470: `keyof typeof <Enum>` resolves to the union of the enum's member-NAME
     * string literals — `typeof Enum` (the enum OBJECT in value position) otherwise
     * resolves to anyType, so `keyof` washed to `string | number | symbol` and
     * `PatternMatchKind[k] as keyof typeof PatternMatchKind` FP'd against a literal
     * union (tsc navigateTo.ts). A barrel-imported enum alias resolves through the
     * memoized [resolveImportedEnumSymbol] (never the general resolveAlias — the
     * round-409 TS2315-flood gotcha). Conservative bails (→ null → prior behavior):
     * non-Identifier exprName, unresolvable name, a namespace/clodule/variable merge
     * (value members beyond the enum members), computed/numeric member names. The
     * merged global symbol's declarations list is POLLUTED with importing files'
     * ImportSpecifiers (the mergeSymbolTable gotcha), so the merge test checks for
     * specific value-declaration kinds rather than "anything non-enum".
     */
    private fun keyofTypeQueryEnumMemberNames(operand: TypeNode): Type? {
        val tq = operand as? TypeQuery ?: return null
        val name = (tq.exprName as? Identifier)?.text ?: return null
        var sym = currentFileLocals?.get(name) ?: globals[name] ?: return null
        if (!sym.flags.hasAny(SymbolFlags.Enum) && sym.flags.hasAny(SymbolFlags.Alias)) {
            sym = resolveImportedEnumSymbol(sym, mutableSetOf()) ?: return null
        }
        if (!sym.flags.hasAny(SymbolFlags.Enum)) return null
        if (sym.declarations.any {
                it is ModuleDeclaration || it is ClassDeclaration ||
                    it is FunctionDeclaration || it is VariableDeclaration
            }) return null
        val names = mutableListOf<String>()
        var sawEnumDecl = false
        for (decl in sym.declarations) {
            if (decl !is EnumDeclaration) continue
            sawEnumDecl = true
            for (m in decl.members) {
                when (val n = m.name) {
                    is Identifier -> names.add(n.text)
                    is StringLiteralNode -> names.add(n.text)
                    else -> return null
                }
            }
        }
        if (!sawEnumDecl || names.isEmpty()) return null
        return getUnionType(names.map { Type.StringLiteral(it) })
    }

    private fun getKeyofType(type: Type): Type {
        // keyof any = string | number | symbol (tsc keyofConstraintType). errorType
        // stays conservative as `string` (its keyof is never displayed/checked meaningfully).
        if (type === anyType) return getUnionType(listOf(stringType, numberType, esSymbolType))
        if (type === errorType) return stringType
        if (type is Type.Object) {
            // Only use already-resolved properties to avoid triggering member resolution
            // during init (which can cause test ordering sensitivity).
            val props = type.properties
            if (props != null) {
                if (props.isEmpty()) return neverType
                val literals = props.map { Type.StringLiteral(it.name) }
                return getUnionType(literals)
            }
            // Members not yet resolved — trigger resolution
            resolveStructuredTypeMembers(type)
            val resolvedProps = type.properties
            // (INC.25) A NULL TABLE HERE MEANS THE RESOLUTION WAS **TRUNCATED**, and it
            // is the only thing that can leave it null: every other exit of
            // `resolveStructuredTypeMembersCore` assigns `properties` (an interface to
            // its merged table, a reference to its instantiated one, an anonymous type
            // to at worst `emptyList()`), while the cycle guard returns having assigned
            // nothing. Answering `string` there is what made the lib's
            // `{ [K in keyof any[]]?: boolean }` degrade to `any` and get FROZEN into
            // `symbolTypes` — `keyof` must instead answer from the DECLARATIONS.
            if (resolvedProps == null) {
                val declared = keyofNamesFromDeclarations(type)
                if (declared != null && declared.isNotEmpty()) {
                    KeyofCycleCensus.answeredFromDeclarations++
                    return getUnionType(declared.map { Type.StringLiteral(it) })
                }
                KeyofCycleCensus.refused++
                return stringType
            }
            if (resolvedProps.isEmpty()) return stringType
            val literals = resolvedProps.map { Type.StringLiteral(it.name) }
            return getUnionType(literals)
        }
        if (type is Type.Union) {
            // keyof (A | B) = keyof A & keyof B (intersection of keys)
            // Simplified: return string for now
            return stringType
        }
        if (type is Type.TypeParam) {
            // keyof T where T is a type parameter — return string | number | symbol
            return stringType
        }
        return stringType
    }

    /**
     * (INC.25) THE KEY SET OF A TYPE WHOSE MEMBER TABLE IS IN FLIGHT, read off the
     * DECLARATIONS instead of off the table that does not exist yet — or null when
     * it cannot be read completely.
     *
     * **IT IS TERMINATING BY CONSTRUCTION, WHICH IS THE WHOLE POINT.** (INC.19) hit
     * the shape this could otherwise become: a cycle guard that ANSWERS instead of
     * degrading can turn a bounded recursion into an unbounded one, and its tell is
     * a spurious TS2589 at (0,0) (`reportCheckerStackOverflow`), never a depth
     * diagnostic. So this walk calls NO resolver — not `resolveStructuredTypeMembers`,
     * not `getTypeOfSymbol`, not `getTypeFromTypeNode`, not `getDeclaredTypeOfSymbol`.
     * It reads only tables that are ALREADY computed and the AST, under a visited set
     * keyed on type id and a depth cap; the self-referential-alias family that broke
     * (INC.19) (`type Shared<I, D extends Shared<I, D>>`) cannot be reached from here
     * at all, because nothing here resolves a constraint.
     *
     * **A PARTIAL ANSWER IS A WRONG ANSWER, SO IT REFUSES RATHER THAN GUESSES**
     * (round 463: a partial key domain manufactured an excess-property TS2353 on a
     * genuinely-valid key). Null — hence the pre-(INC.25) `string` — whenever some
     * contributor cannot be enumerated: a base type that is not an object, an
     * interface whose heritage has not been resolved yet, a symbol with no
     * class/interface declaration at all.
     *
     * The names, their ORDER and the lib target filter are
     * [resolveInterfaceMembersCore]'s, because the two must not drift: base members
     * first in base order, then own members in declaration order across the merged
     * declaration group, first spelling winning its position.
     */
    private fun keyofNamesFromDeclarations(type: Type.Object): List<String>? {
        val out = LinkedHashSet<String>()
        return if (collectKeyofDeclaredNames(type, out, HashSet(), 0)) out.toList() else null
    }

    /** [keyofNamesFromDeclarations]'s worker; false means "cannot be enumerated". */
    private fun collectKeyofDeclaredNames(
        type: Type.Object,
        out: MutableSet<String>,
        visited: MutableSet<Int>,
        depth: Int,
    ): Boolean {
        if (depth > KEYOF_DECL_MAX_DEPTH) return false
        // A reference's key set IS its target's: instantiation substitutes member
        // TYPES and never renames a member.
        val target = if (type is Type.Reference) type.target else type
        if (!visited.add(target.id)) return true
        // The exact answer whenever it exists — and in the shipped instance of this
        // defect it always does, because `resolveReferenceMembers` resolves the
        // TARGET before the instantiation loop that re-enters here.
        target.properties?.let { props ->
            for (p in props) out.add(p.name)
            return true
        }
        val symbol = target.symbol ?: return false
        if (target is Type.Interface) {
            val bases = target.baseTypes ?: return false
            for (base in bases) {
                val baseObject = base as? Type.Object ?: return false
                if (!collectKeyofDeclaredNames(baseObject, out, visited, depth + 1)) return false
            }
        }
        var sawDeclaration = false
        for (decl in symbol.declarations) {
            val declaredMembers = when (decl) {
                is ClassDeclaration -> decl.members
                is InterfaceDeclaration -> decl.members
                is ClassExpression -> decl.members
                else -> continue
            }
            sawDeclaration = true
            val isBuiltinDecl = decl in builtinLibDecls
            for (member in declaredMembers) {
                if (member is Constructor) {
                    // Parameter properties are members, exactly as in the resolver.
                    for (param in member.parameters) {
                        val paramName = param.name
                        if (param.modifiers.isNotEmpty() && paramName is Identifier) {
                            out.add(paramName.text)
                        }
                    }
                    continue
                }
                val name = when (member) {
                    is PropertyDeclaration -> declaredMemberName(member.name)
                    // An EMPTY name is a call signature and `new` a construct
                    // signature; neither is a named property, exactly as in the
                    // resolver's own `when`.
                    is MethodDeclaration -> declaredMemberName(member.name)
                        ?.takeIf { it.isNotEmpty() && it != "new" }
                    is GetAccessor -> declaredMemberName(member.name)
                    is SetAccessor -> declaredMemberName(member.name)
                    else -> null
                } ?: continue
                if (isBuiltinDecl) {
                    val minTarget = LIB_MIN_TARGET["${symbol.name}.$name"]
                    if (minTarget != null && !libFeatureAvailable(minTarget)) continue
                }
                out.add(name)
            }
        }
        return sawDeclaration
    }

    // -----------------------------------------------------------------------
    // Union and Intersection type construction (basic — Phase 4 items 1b/1c)
    // -----------------------------------------------------------------------

    /** Construct a union type from a list of constituent types, with basic normalization. */
    private fun getUnionType(types: List<Type>): Type {
        if (types.isEmpty()) return neverType
        // M5.2 fast paths for the overwhelmingly common tiny inputs (the pervasive
        // `T | undefined` shape and single-element calls) — byte-identical to the
        // general path below but skips its 4 intermediate list + 1 set allocations.
        // Only taken when NO member needs flattening (none is a Union); anything with
        // a nested union falls through to the general path unchanged.
        if (types.size == 1) {
            val t = types[0]
            if (t !is Type.Union) return if (t.flags.hasAny(TypeFlags.Never)) neverType else t
        } else if (types.size == 2) {
            val a = types[0]
            val b = types[1]
            if (a !is Type.Union && b !is Type.Union) {
                val aNever = a.flags.hasAny(TypeFlags.Never)
                val bNever = b.flags.hasAny(TypeFlags.Never)
                when {
                    aNever && bNever -> return neverType
                    aNever -> return b
                    bNever -> return a
                    else -> {
                        // Any constituent → the union is that any (first-in-order wins).
                        if (a.flags.hasAny(TypeFlags.Any)) return a
                        if (b.flags.hasAny(TypeFlags.Any)) return b
                        if (a.id == b.id) return a
                        // Match the stable sort-by-flags-value of the general path.
                        return if (a.flags.value <= b.flags.value) internUnion(listOf(a, b))
                        else internUnion(listOf(b, a))
                    }
                }
            }
        }
        // Flatten nested unions
        val flattened = mutableListOf<Type>()
        for (type in types) {
            if (type is Type.Union) {
                flattened.addAll(type.types)
            } else {
                flattened.add(type)
            }
        }
        // Remove never types
        val filtered = flattened.filter { !it.flags.hasAny(TypeFlags.Never) }
        if (filtered.isEmpty()) return neverType
        // If any constituent is any, the union is any
        filtered.firstOrNull { it.flags.hasAny(TypeFlags.Any) }?.let { return it }
        // Single type — no union needed
        if (filtered.size == 1) return filtered[0]
        // Deduplicate by type identity (by id). HashSet: membership only, result sorted below.
        val seen = HashSet<Int>()
        val deduped = filtered.filter { seen.add(it.id) }
        if (deduped.size == 1) return deduped[0]
        // Sort by TypeFlags value to match TypeScript's display order
        // TypeScript sorts: string(4) < number(8) < boolean(16) < bigint(64) < ...
        val sorted = deduped.sortedBy { it.flags.value }
        return internUnion(sorted)
    }

    private fun internUnion(members: List<Type>): Type.Union {
        // M0.3(iii): the dominant 2-member union (`T | undefined`) interns via an
        // exact packed-Long key (both ids positive < 2^31; high half >= 1 != 0).
        if (members.size == 2) {
            val key = (members[0].id.toLong() shl 32) or (members[1].id.toLong() and 0xFFFFFFFFL)
            return state.unionInternCacheLong.get(key)
                ?: Type.Union(members).also { state.unionInternCacheLong.put(key, it) }
        }
        val key = members.joinToString(",") { it.id.toString() }
        return state.unionInternCache.getOrPut(key) { Type.Union(members) }
    }

    /** A (possibly nested, paren-wrapped) ternary whose leaves are ALL array
     *  literals — contextually tuple-typed by tsc like a bare array literal
     *  (see the B87.6b gate). */
    private fun ternaryOfArrayLiterals(e: Expression?): Boolean {
        var n = e ?: return false
        while (n is ParenthesizedExpression) n = n.expression
        return when (n) {
            is ArrayLiteralExpression -> true
            is ConditionalExpression ->
                ternaryOfArrayLiterals(n.whenTrue) && ternaryOfArrayLiterals(n.whenFalse)
            else -> false
        }
    }

    /** Construct an intersection type from a list of constituent types, with basic normalization. */
    private fun getIntersectionType(types: List<Type>): Type {
        if (types.isEmpty()) return unknownType
        // Flatten nested intersections
        val flattened = mutableListOf<Type>()
        for (type in types) {
            if (type is Type.Intersection) {
                flattened.addAll(type.types)
            } else {
                flattened.add(type)
            }
        }
        // If any constituent is never, the intersection is never
        if (flattened.any { it.flags.hasAny(TypeFlags.Never) }) return neverType
        // Remove unknown types (unknown & X = X)
        val filtered = flattened.filter { !it.flags.hasAny(TypeFlags.Unknown) }
        if (filtered.isEmpty()) return unknownType
        // If any constituent is any, the intersection is any
        filtered.firstOrNull { it.flags.hasAny(TypeFlags.Any) }?.let { return it }
        // Single type — no intersection needed
        if (filtered.size == 1) return filtered[0]
        // Reduce incompatible primitive intersections to never:
        // e.g., number & boolean, string & number → never
        val primitiveFlags = TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.BigInt or TypeFlags.ESSymbol or TypeFlags.Void or TypeFlags.Null or TypeFlags.Undefined
        val primitives = filtered.filter { it.flags.hasAny(primitiveFlags) }
        if (primitives.size >= 2) {
            // Two distinct primitive types → always never
            val distinctPrimitiveKinds = primitives.map { it.flags.value and primitiveFlags.value }.toSet()
            if (distinctPrimitiveKinds.size >= 2) return neverType
        }
        // B8.1: reduce `A & B` to `never` when a property name appears in 2+
        // class constituents and is `private` in at least one. The reduction
        // reason (display string + conflicting prop name) is captured by
        // [getTypeFromTypeNodeWorker]'s IntersectionType branch (post-call)
        // so TS2322 / TS2339 emitters can append the
        // "The intersection 'A & B' was reduced to 'never' ..." chain line.
        if (findConflictingPrivateInIntersection(filtered) != null) return neverType
        // M0.3(iii): 2-member intersections intern via the exact packed-Long key.
        if (filtered.size == 2) {
            val key = (filtered[0].id.toLong() shl 32) or (filtered[1].id.toLong() and 0xFFFFFFFFL)
            return state.intersectionInternCacheLong.get(key)
                ?: Type.Intersection(filtered).also { state.intersectionInternCacheLong.put(key, it) }
        }
        val key = filtered.joinToString(",") { it.id.toString() }
        return state.intersectionInternCache.getOrPut(key) { Type.Intersection(filtered) }
    }

    /**
     * B8.1: find the FIRST property name that appears in 2+ constituents of
     * an intersection AND has `private` modifier in at least one declaration.
     *
     * Walks each [Type.Interface] (class) constituent's `symbol.declarations`
     * and inspects DIRECT declared members only — inherited members are
     * intentionally skipped to avoid OBJECT_PROTOTYPE_PROPERTIES noise and
     * to match TypeScript's behavior. Anonymous [Type.Object] / [Type.Reference]
     * constituents don't contribute (their members are not `private`-declared
     * in the type-system sense, only class members can be).
     *
     * Returns null when no conflict is found (caller leaves the intersection
     * intact).
     */
    private fun findConflictingPrivateInIntersection(types: List<Type>): String? {
        // (propName → list of "is this declaration private?" booleans, one per occurrence)
        val nameOccurrences = HashMap<String, MutableList<Boolean>>()
        for (t in types) {
            val iface = (t as? Type.Interface) ?: ((t as? Type.Reference)?.target) ?: continue
            val symbol = iface.symbol ?: continue
            for (decl in symbol.declarations) {
                if (decl !is ClassDeclaration) continue
                for (member in decl.members) {
                    val name = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        is GetAccessor -> (member.name as? Identifier)?.text
                        is SetAccessor -> (member.name as? Identifier)?.text
                        else -> null
                    } ?: continue
                    if (name in OBJECT_PROTOTYPE_PROPERTIES) continue
                    nameOccurrences.getOrPut(name) { mutableListOf() }.add(isMemberPrivate(member))
                }
            }
        }
        for ((name, occurrences) in nameOccurrences) {
            if (occurrences.size >= 2 && occurrences.any { it }) return name
        }
        return null
    }

    /** B8.1: chain message text for an intersection that reduced to `never` due to
     *  conflicting private members. Same text appended to TS2322 and TS2339. */
    private fun intersectionReductionChainMessage(reason: IntersectionReductionReason): String =
        "  The intersection '${reason.displayString}' was reduced to 'never' " +
            "because property '${reason.conflictingPropName}' exists in multiple " +
            "constituents and is private in some."

    /** B8.1: look up the intersection-reduction reason for an expression that resolves
     *  to `never` due to a conflicting-private intersection reduction. Walks the
     *  receiver's symbol declarations for a VariableDeclaration / Parameter /
     *  PropertyDeclaration / PropertySignature whose type annotation contains an
     *  IntersectionType registered in [CheckerState.intersectionReductionReasons].
     *  Returns null when no reduction info is recorded (callers fall through to
     *  the standard never-display path). */
    private fun findIntersectionReductionForExpr(expr: Expression): IntersectionReductionReason? {
        if (state.intersectionReductionReasons.isEmpty()) return null
        val symbol = when (expr) {
            is Identifier -> currentFileLocals?.get(expr.text) ?: globals[expr.text]
            else -> null
        } ?: return null
        for (decl in symbol.declarations) {
            val typeNode: TypeNode? = when (decl) {
                is VariableDeclaration -> decl.type
                is Parameter -> decl.type
                is PropertyDeclaration -> decl.type
                else -> null
            }
            if (typeNode != null) {
                findIntersectionReductionInTypeNode(typeNode)?.let { return it }
            }
        }
        return null
    }

    /** B8.1: walk a TypeNode looking for any IntersectionType registered in the
     *  reduction-reason cache. Returns the first match found. */
    private fun findIntersectionReductionInTypeNode(node: TypeNode): IntersectionReductionReason? {
        when (node) {
            is IntersectionType -> {
                state.intersectionReductionReasons[node]?.let { return it }
                for (t in node.types) findIntersectionReductionInTypeNode(t)?.let { return it }
            }
            is UnionType -> for (t in node.types) findIntersectionReductionInTypeNode(t)?.let { return it }
            is ParenthesizedType -> return findIntersectionReductionInTypeNode(node.type)
            is ArrayType -> return findIntersectionReductionInTypeNode(node.elementType)
            else -> {}
        }
        return null
    }

    // -----------------------------------------------------------------------
    // String-based type resolution (legacy — to be replaced by Type-based)
    // -----------------------------------------------------------------------

    /** Resolve a type annotation to a type name string. Returns null for complex types we can't handle.
     *  Named types (from TypeReference) are prefixed with "@" to distinguish from keyword types. */
    private fun resolveSimpleTypeName(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is TypeReference -> {
                val baseName = getTypeReferenceLastName(typeNode.typeName) ?: return null
                val typeArgs = typeNode.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    // Format as Name<Arg1, Arg2> for display in TS2322 messages
                    val argNames = typeArgs.map { formatTypeForDisplay(it) }
                    if (argNames.any { it == null }) return null
                    "@$baseName<${argNames.joinToString(", ")}>"
                } else {
                    // Simple type reference — prefix with "@" to mark as named type
                    "@$baseName"
                }
            }
            is UnionType -> {
                // Format as "type1 | type2 | ..." for display
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                // Use "|" prefix to mark as union type for assignability checking
                "|${memberTypes.joinToString(" | ")}"
            }
            is TypePredicate -> if (typeNode.assertsModifier) "void" else "boolean" // asserts → void; `x is T` → boolean
            else -> null
        }
    }

    /** B250: encode an `A & B` annotation (bare type-reference names only) as
     *  "&A & B" for the intersection-vs-bare-TP assignment pre-check. Any member
     *  that isn't a bare unparameterized name → null (no entry). */
    private fun intersectionTypeNameForVarTypes(t: TypeNode): String? {
        val inter = t as? IntersectionType ?: return null
        val names = inter.types.map { m ->
            val ref = m as? TypeReference ?: return null
            if (!ref.typeArguments.isNullOrEmpty()) return null
            (ref.typeName as? Identifier)?.text ?: return null
        }
        if (names.size < 2) return null
        return "&" + names.joinToString(" & ")
    }

    /** Get the last identifier name from a TypeReference typeName (Identifier or QualifiedName). */
    private fun getTypeReferenceLastName(node: Node): String? {
        return when (node) {
            is Identifier -> node.text
            is QualifiedName -> node.right.text
            else -> null
        }
    }

    /** 17.238: Format full dotted name `a.b.c` for QualifiedName. */
    private fun formatTypeReferenceName(node: Node): String? {
        return when (node) {
            is Identifier -> node.text
            is QualifiedName -> {
                val l = formatTypeReferenceName(node.left) ?: return null
                "$l.${node.right.text}"
            }
            else -> null
        }
    }

    /**
     * Resolve a TypeReference typeName (Identifier or QualifiedName) to a Symbol.
     *
     * INV.3(c)(iv) (round 508): the Identifier branch keys the merged-globals
     * consult by the NAME NODE'S owning file — a type name resolves under the
     * visibility of the file its annotation lives in (tsc semantics; a
     * types.ts annotation resolves in types.ts's scope whatever file is being
     * checked). A module-only name with no meaning in the owning file returns
     * null (the conflation leak, killed — real tsc sees TS2304 there); every
     * visible name keeps resolving to the SAME merged instance, and node-keyed
     * resolution is a fixed property of the node, so the `nodeTypes` cache
     * stays valid. Synthesized/unindexed Identifiers degrade to the legacy
     * merged consult inside [lookupPerFileForNode]. NOTE the two call sites
     * with their own trailing `?: globals[name]` fallback gate it to
     * QualifiedName ([getTypeFromTypeReference], [checkConstraintsInTypeNode])
     * — for an Identifier that fallback was byte-redundant pre-flip and would
     * silently re-leak post-flip.
     */
    private fun resolveTypeNameToSymbol(node: Node): Symbol? {
        return when (node) {
            is Identifier -> {
                // (REL.1)(c) step 4: a function-body-scoped `enum` is invisible to the
                // conventional consult (B83.5) and a name SHADOWING an outer one
                // resolves there to the WRONG (outer) symbol — so the position-aware
                // lexical consult must come FIRST, not as a miss-fallback.
                lexicalTypeSymbolForNode(node, node.text)?.let { return it }
                val sym = lookupPerFileForNode(node, node.text)
                // INV.3(d): the import-shadowed-by-value-local TYPE/VALUE split —
                // `import { SourceMapSource }` (a type) + a same-named local
                // `function SourceMapSource` (a value): the binder's last-wins keeps
                // only the value in file locals, and the retired merge no longer
                // provides the interface through `globals`. tsc resolves the TYPE
                // space to the import; recover it from the ImportSpecifier's own
                // recorded alias symbol when the per-file winner lacks a type side.
                if (sym != null && !symbolHasTypeSideDeclaration(sym)) {
                    owningSourceFile(node)?.let { owner ->
                        typeSideImportFallback(owner, node.text)?.let { return it }
                    }
                }
                sym
            }
            is QualifiedName -> resolveQualifiedName(node)
            else -> null
        }
    }

    /** INV.3(d): does [sym] declare anything in TYPE space (or carry an alias hop
     *  that could)? Declaration-based, never flags (the isValueExport gotcha). */
    private fun symbolHasTypeSideDeclaration(sym: Symbol): Boolean = sym.declarations.any {
        it is InterfaceDeclaration || it is ClassDeclaration || it is TypeAliasDeclaration ||
            it is EnumDeclaration || it is ModuleDeclaration || it is TypeParameter ||
            isImportBindingDecl(it)
    }

    /**
     * INV.3(d): resolve `NS.member` where [root] is a NAMESPACE-import alias
     * (`import * as NS from "./mod.js"`) to the target MODULE file's exported
     * symbol [memberName] — ESM-`.js`-aware, `export *`-following. The general
     * `resolveAlias` cannot follow NamespaceImports (round 444); the retired
     * merge no longer provides the last-segment leak the heritage fallback rode.
     */
    private fun namespaceImportMemberSymbol(root: Identifier, memberName: String): Symbol? {
        val owner = owningSourceFile(root) ?: return null
        val rootSym = fileResults[owner.fileName]?.locals?.get(root.text) ?: return null
        return namespaceAliasMemberSymbol(rootSym, memberName)
    }

    /** INV.3(d): resolve [memberName] from a namespace-flavored ALIAS symbol —
     *  hopping NAMED-import re-publications (the round-479 barrel shape:
     *  `import * as NS from …; export { NS };`) to the underlying
     *  namespace-import, then reading the member from its target module
     *  (`export *`-following). Context files derive from the declaration
     *  nodes' owning files, so intermediate hops need no threading. */
    private fun namespaceAliasMemberSymbol(alias: Symbol, memberName: String): Symbol? {
        var cur: Symbol? = alias
        var hops = 0
        while (cur != null && hops++ < 5) {
            // A namespace-import alias — resolve its target module and read the member.
            val nsImport = cur.declarations.firstOrNull {
                it is ImportDeclaration && it.importClause?.namedBindings is NamespaceImport
            } as? ImportDeclaration
            if (nsImport != null) {
                val ctx = owningSourceFile(nsImport)?.fileName ?: return null
                val spec = (nsImport.moduleSpecifier as? StringLiteralNode)?.text ?: return null
                // Round 513: the DIR-RELATIVE leg (the round-511 lesson class) — a
                // path-shaped extensionless specifier resolves only relative to the
                // importing file's directory. Purely additive.
                val target = resolveModuleSpecifier(spec, nsImport)
                    ?: resolveAliasJsModuleSpecifier(spec, ctx)
                    ?: resolveModuleSpecifierRelativeJsAware(spec, ctx)
                    ?: resolveImportTargetFallback(spec, ctx) ?: return null
                val tr = fileResults[target] ?: return null
                if (memberName in moduleNamedExportsOf(tr.sourceFile)) {
                    tr.locals[memberName]?.let { return it }
                }
                return resolveExportedSymbolThroughStars(tr.sourceFile, memberName)
            }
            // An `export * as NS from "./x"` re-publication (the tsc `_namespaces`
            // barrel idiom) — the binder binds NS as an Alias declared by the
            // ExportDeclaration itself; resolve its specifier and read the member.
            val nsExport = cur.declarations.firstOrNull {
                it is ExportDeclaration && it.exportClause is NamespaceExport &&
                    it.moduleSpecifier is StringLiteralNode
            } as? ExportDeclaration
            if (nsExport != null) {
                val ctx = owningSourceFile(nsExport)?.fileName ?: return null
                val spec = (nsExport.moduleSpecifier as? StringLiteralNode)?.text ?: return null
                val target = resolveModuleSpecifier(spec, nsExport)
                    ?: resolveAliasJsModuleSpecifier(spec, ctx)
                    ?: resolveModuleSpecifierRelativeJsAware(spec, ctx)
                    ?: resolveImportTargetFallback(spec, ctx) ?: return null
                val tr = fileResults[target] ?: return null
                if (memberName in moduleNamedExportsOf(tr.sourceFile)) {
                    tr.locals[memberName]?.let { return it }
                }
                return resolveExportedSymbolThroughStars(tr.sourceFile, memberName)
            }
            // A NAMED-import alias — hop to the target module's binding for the
            // original name.
            val spec2 = cur.declarations.firstOrNull { it is ImportSpecifier } as? ImportSpecifier
                ?: return null
            val originalName = spec2.propertyName?.text ?: spec2.name.text
            val (ctxFile, importDecl) = findEnclosingImport(spec2) ?: return null
            val modSpec = (importDecl.moduleSpecifier as? StringLiteralNode)?.text ?: return null
            val target = resolveModuleSpecifier(modSpec, importDecl)
                ?: resolveAliasJsModuleSpecifier(modSpec, ctxFile)
                ?: resolveModuleSpecifierRelativeJsAware(modSpec, ctxFile) ?: return null
            val tr = fileResults[target] ?: return null
            cur = if (originalName in moduleNamedExportsOf(tr.sourceFile)) {
                tr.locals[originalName] ?: resolveExportedSymbolThroughStars(tr.sourceFile, originalName)
            } else {
                resolveExportedSymbolThroughStars(tr.sourceFile, originalName)
            }
        }
        return null
    }

    /** INV.3(d): resolve a DOTTED namespace-qualified value chain `A.B.…​.member`
     *  (`ts.server.Logger` — `ts` a namespace-import, `server` a re-published
     *  namespace-import) to the final member's symbol. Heritage bases use this;
     *  null on any unresolvable segment. */
    private fun resolveNamespaceQualifiedSymbol(pa: PropertyAccessExpression): Symbol? {
        val prefix: Symbol? = when (val e = pa.expression) {
            is Identifier -> owningSourceFile(e)?.let { o -> fileResults[o.fileName]?.locals?.get(e.text) }
            is PropertyAccessExpression -> resolveNamespaceQualifiedSymbol(e)
            else -> null
        }
        return prefix?.let { namespaceAliasMemberSymbol(it, pa.name.text) }
    }

    /** INV.3(d): the [resolveNamespaceQualifiedSymbol] sibling over TYPE-position
     *  [QualifiedName] chains (`ts.DocumentRegistry`, `ts.server.Session`). */
    private fun resolveNsQualifiedFromQualifiedName(qn: QualifiedName): Symbol? {
        val prefix: Symbol? = when (val l = qn.left) {
            is Identifier -> owningSourceFile(l)?.let { o -> fileResults[o.fileName]?.locals?.get(l.text) }
            is QualifiedName -> resolveNsQualifiedFromQualifiedName(l)
            else -> null
        }
        return prefix?.let { namespaceAliasMemberSymbol(it, qn.right.text) }
    }

    /** INV.3(d): resolve the TYPE side of a name whose per-file VALUE local shadowed
     *  its own file's named import (binder last-wins) — the ImportSpecifier's alias
     *  symbol is still recorded in the binder's nodeToSymbol; resolve it onward and
     *  keep the result only when it genuinely has a type side. Memoized per
     *  (file, name); null (cached) = no shadowed type import. */
    private fun typeSideImportFallback(owner: SourceFile, name: String): Symbol? {
        val key = owner.fileName + "|" + name
        if (typeSideImportFallbackCache.containsKey(key)) return typeSideImportFallbackCache[key]
        val result = run {
            val br = fileResults[owner.fileName] ?: return@run null
            for (stmt in owner.statements) {
                if (stmt !is ImportDeclaration) continue
                val named = stmt.importClause?.namedBindings as? NamedImports ?: continue
                val spec = named.elements.firstOrNull { it.name.text == name } ?: continue
                val alias = br.nodeToSymbol[nodeKey(spec)] ?: continue
                return@run resolveImportedSymbolGeneral(alias)
                    ?.takeIf { it.declarations.any { d -> !isImportBindingDecl(d) } && symbolHasTypeSideDeclaration(it) }
            }
            null
        }
        typeSideImportFallbackCache[key] = result
        return result
    }

    /**
     * Format a TypeNode for display in TS2322 messages (no "@" prefix).
     * Returns null for unsupported types (caller falls back to typeToString).
     */
    /** 17.10c: Format a TypeParameter AST node as `name` or `name extends Constraint`. */
    private fun tpDeclToDisplay(tp: TypeParameter): String {
        val name = tp.name.text
        val cons = tp.constraint?.let { formatTypeForDisplay(it) }
        return if (cons != null) "$name extends $cons" else name
    }

    /**
     * Format a Parameter AST node for display in function/constructor type strings.
     * Honors `?` (optional → `name?: type | undefined` for non-fn types, `name?: type`
     * for fn/ctor types) and `...` (rest → `...name: type`).
     * Mirrors [formatParameter] (which operates on Symbol) but works directly on the AST.
     *
     * 17.15a: Drop `| undefined` when the param type is itself a `FunctionType` or
     * `ConstructorType`. The form `name?: T => U | undefined` would parse as a function
     * returning `U | undefined` (`=>` binds tighter than `|`). TypeScript's display
     * convention is to drop `| undefined` for fn-type params to avoid this ambiguity.
     */
    private fun formatParameterDecl(p: Parameter): String {
        val pName = (p.name as? Identifier)?.text ?: "_"
        val pType = p.type?.let { formatTypeForDisplay(it) } ?: "any"
        // B51.6: TypeScript displays params with default values as optional
        // (`a?: T`) in type positions — the default makes the param effectively
        // optional from a caller's perspective. Mirrors the display in
        // `defaultValueInFunctionTypes_ts`'s `(a?: string) => any` baseline.
        val hasInitializer = p.initializer != null
        return when {
            p.dotDotDotToken -> "...$pName: $pType"
            p.questionToken -> {
                val isFnType = p.type is FunctionType || p.type is ConstructorType
                if (isFnType) "$pName?: $pType" else "$pName?: $pType | undefined"
            }
            hasInitializer -> "$pName?: $pType"
            else -> "$pName: $pType"
        }
    }

    /**
     * Returns true if [typeNode] renders via formatTypeForDisplay as a function or constructor
     * type shorthand (`(x: T) => U` or `new (x: T) => U`). Used to decide when parens are
     * needed in array element or union member positions. Unwraps ParenthesizedType.
     */
    private fun typeNodeRendersAsFunctionLike(typeNode: TypeNode): Boolean {
        var t: TypeNode = typeNode
        while (t is ParenthesizedType) t = t.type
        return when (t) {
            is FunctionType, is ConstructorType -> true
            is TypeLiteral -> {
                // Single call/construct signature → renders as shorthand
                if (t.members.size == 1) {
                    val only = t.members[0]
                    only is MethodDeclaration && (only.name is Identifier &&
                        (only.name.text == "" || only.name.text == "new"))
                } else false
            }
            else -> false
        }
    }

    /**
     * B86.7a (additive helper, no callers yet): strip outer `null` / `undefined`
     * constituents from a `Type.Union` target when the source is non-nullable. Used
     * downstream to render `A | B` instead of `A | B | null | undefined` in TS2322
     * diagnostics where the actual incompatibility is between the non-nullish
     * shapes. Returns [targetType] unchanged when:
     *   - target is not a Type.Union,
     *   - source is itself nullable (both nullable: keep null in display),
     *   - target has no nullish constituents to strip,
     *   - stripping would leave nothing behind (safety).
     */
    private fun stripNullishFromDisplayTarget(targetType: Type, sourceType: Type): Type {
        if (targetType !is Type.Union) return targetType
        if (typeIsPossiblyNullish(sourceType)) return targetType
        val nonNullish = targetType.types.filter { it !== nullType && it !== undefinedType }
        if (nonNullish.size == targetType.types.size) return targetType
        if (nonNullish.isEmpty()) return targetType
        return if (nonNullish.size == 1) nonNullish[0] else getUnionType(nonNullish)
    }

    private fun formatTypeForDisplay(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is TypeReference -> {
                val baseName = getTypeReferenceLastName(typeNode.typeName) ?: return null
                val typeArgs = typeNode.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    // TypeScript normalizes Array<T> → T[] and ReadonlyArray<T> → readonly T[]
                    // in error messages. B50.8: preserve the `readonly` prefix for
                    // ReadonlyArray to match TypeScript's display convention.
                    if ((baseName == "Array" || baseName == "ReadonlyArray") && typeArgs.size == 1) {
                        val elementDisplay = formatTypeForDisplay(typeArgs[0]) ?: return null
                        // Parens for function/constructor-like element types
                        val needsParens = typeArgs[0] !is ParenthesizedType &&
                            typeNodeRendersAsFunctionLike(typeArgs[0])
                        val arr = if (needsParens) "(${elementDisplay})[]" else "${elementDisplay}[]"
                        return if (baseName == "ReadonlyArray") "readonly $arr" else arr
                    }
                    val argNames = typeArgs.map { formatTypeForDisplay(it) }
                    if (argNames.any { it == null }) return null
                    "$baseName<${argNames.joinToString(", ")}>"
                } else {
                    // 16.4fi: for TypeAliases with circular-default type params, fill in
                    // `<any, any, ...>` for bare references — matches TypeScript's
                    // substitution-on-invalid-default display.
                    val tnName = typeNode.typeName
                    val sym = if (tnName is Identifier) currentFileLocals?.get(tnName.text) ?: globals[tnName.text]
                        else null
                    val n = sym?.let { circularDefaultTypeParamCount[it.id] }
                    if (n != null && n > 0) {
                        "$baseName<${List(n) { "any" }.joinToString(", ")}>"
                    } else {
                        // B70.1: when the TypeReference resolves to a non-generic TypeAlias
                        // whose body evaluates to a singleton literal type (NumberLiteral /
                        // StringLiteral / BigIntLiteral), TypeScript displays the resolved
                        // literal in TS2322 messages instead of the alias name. Example:
                        // `type U = [any] extends [number] ? 1 : 0;` → display `'1'`, not `'U'`.
                        // Conservative gate: only literal singletons; object-shape aliases
                        // keep the alias name (more readable + matches TS for those).
                        if (sym != null && sym.flags.hasAny(SymbolFlags.TypeAlias)) {
                            val decl = sym.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                            if (decl != null && decl.typeParameters.isNullOrEmpty()) {
                                when (val resolved = getDeclaredTypeOfSymbol(sym)) {
                                    is Type.NumberLiteral -> return resolved.toString()
                                    is Type.StringLiteral -> return "\"${resolved.value}\""
                                    is Type.BigIntLiteral -> return resolved.toString()
                                    else -> {}
                                }
                            }
                        }
                        baseName
                    }
                }
            }
            is ArrayType -> {
                // Function/constructor types must be parenthesized as Array elements:
                // `(new () => T)[]` not `new () => T[]` (the latter parses as `new () => (T[])`).
                // Don't add a second set of parens if the source already wraps in ParenthesizedType
                // (formatTypeForDisplay for ParenthesizedType already emits `(...)`).
                val elementType = formatTypeForDisplay(typeNode.elementType) ?: return null
                if (typeNode.elementType !is ParenthesizedType &&
                    typeNodeRendersAsFunctionLike(typeNode.elementType)) "($elementType)[]"
                else "$elementType[]"
            }
            is UnionType -> {
                // namespaceDisambiguationInUnion: tsc qualifies a union member with its
                // namespace ONLY when its simple (last) name COLLIDES with another member's
                // in the SAME union (`Foo.Yep | Bar.Yep`, not `Yep | Yep`). Detect TypeReference
                // members sharing a last-name and render those fully-qualified. FP-safe: only
                // affects unions with ≥2 members having an identical last segment (very rare).
                val refLastNames = typeNode.types.mapNotNull { (it as? TypeReference)?.let { r -> getTypeReferenceLastName(r.typeName) } }
                val collidingNames = refLastNames.groupingBy { it }.eachCount().filterValues { it > 1 }.keys
                // Function/constructor types in unions need parens: `number | (new () => T)`.
                val memberStrs = typeNode.types.map { m ->
                    val s = if (m is TypeReference && m.typeArguments.isNullOrEmpty() &&
                        m.typeName is QualifiedName &&
                        getTypeReferenceLastName(m.typeName) in collidingNames) {
                        formatTypeReferenceName(m.typeName) ?: (formatTypeForDisplay(m) ?: return null)
                    } else formatTypeForDisplay(m) ?: return null
                    if (typeNodeRendersAsFunctionLike(m)) "($s)" else s
                }
                memberStrs.joinToString(" | ")
            }
            is IntersectionType -> {
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                memberTypes.joinToString(" & ")
            }
            is FunctionType -> {
                val typeParams = typeNode.typeParameters ?: emptyList()
                val tpStr = if (typeParams.isNotEmpty()) "<${typeParams.joinToString(", ") { tpDeclToDisplay(it) }}>" else ""
                val params = typeNode.parameters.joinToString(", ") { formatParameterDecl(it) }
                val retType = formatTypeForDisplay(typeNode.type) ?: return null
                "$tpStr($params) => $retType"
            }
            is ConstructorType -> {
                val typeParams = typeNode.typeParameters ?: emptyList()
                val tpStr = if (typeParams.isNotEmpty()) "<${typeParams.joinToString(", ") { tpDeclToDisplay(it) }}>" else ""
                val params = typeNode.parameters.joinToString(", ") { formatParameterDecl(it) }
                val retType = formatTypeForDisplay(typeNode.type) ?: return null
                "new $tpStr($params) => $retType"
            }
            is ParenthesizedType -> {
                val inner = formatTypeForDisplay(typeNode.type) ?: return null
                "($inner)"
            }
            is TupleType -> {
                // namespaceDisambiguationInUnion: qualify colliding same-named TypeReference
                // elements (`[Foo.Yep, Bar.Yep]`, not `[Yep, Yep]`) — same rule as UnionType.
                val refLastNames = typeNode.elements.mapNotNull { (it as? TypeReference)?.let { r -> getTypeReferenceLastName(r.typeName) } }
                val collidingNames = refLastNames.groupingBy { it }.eachCount().filterValues { it > 1 }.keys
                val elements = typeNode.elements.map { el ->
                    if (el is TypeReference && el.typeArguments.isNullOrEmpty() &&
                        el.typeName is QualifiedName &&
                        getTypeReferenceLastName(el.typeName) in collidingNames) {
                        formatTypeReferenceName(el.typeName) ?: formatTypeForDisplay(el)
                    } else formatTypeForDisplay(el)
                }
                if (elements.any { it == null }) return null
                "[${elements.joinToString(", ")}]"
            }
            is TypeLiteral -> {
                // Single call/construct signature: display as arrow form
                // `{(): T}` → `() => T` and `{new(): T}` → `new () => T`
                if (typeNode.members.size == 1) {
                    val only = typeNode.members[0]
                    if (only is MethodDeclaration) {
                        val name = (only.name as? Identifier)?.text
                        if (name == "" || name == "new") {
                            // 17.10b: Include type parameters from the call/construct sig
                            // so `{<T>(x:T): T}` displays as `<T>(x: T) => T` not `(x: T) => T`.
                            val sigTps = only.typeParameters ?: emptyList()
                            val tpStr = if (sigTps.isNotEmpty()) "<${sigTps.joinToString(", ") { tpDeclToDisplay(it) }}>" else ""
                            val params = only.parameters.joinToString(", ") { formatParameterDecl(it) }
                            val retType = only.type?.let { formatTypeForDisplay(it) } ?: "any"
                            val prefix = if (name == "new") "new " else ""
                            return "$prefix$tpStr($params) => $retType"
                        }
                    }
                }
                // B471: tsc renders an anonymous object type's members in a CANONICAL
                // order regardless of source order: call signatures, then construct
                // signatures, then index signatures, then properties (and named methods,
                // in source order). A call sig is a `MethodDeclaration` with name "",
                // a construct sig is name "new" (see "Interface call/construct signatures"
                // gotcha). Source order is NOT preserved (typeName1).
                val callSigParts = mutableListOf<String>()
                val ctorSigParts = mutableListOf<String>()
                val indexParts = mutableListOf<String>()
                val propParts = mutableListOf<String>()
                for (member in typeNode.members) {
                    when (member) {
                        is PropertyDeclaration -> {
                            val propName = (member.name as? Identifier)?.text ?: continue
                            val propType = member.type?.let { formatTypeForDisplay(it) } ?: "any"
                            if (member.questionToken) {
                                // Optional properties display as `name?: type | undefined`,
                                // EXCEPT `any`/`unknown` which absorb undefined — tsc renders
                                // `name?: any` (not `any | undefined`). B482-WEAK.
                                if (propType == "any" || propType == "unknown") {
                                    propParts.add("$propName?: $propType")
                                } else {
                                    propParts.add("$propName?: $propType | undefined")
                                }
                            } else {
                                propParts.add("$propName: $propType")
                            }
                        }
                        is IndexSignature -> {
                            val param = member.parameters.firstOrNull()
                            val paramName = (param?.name as? Identifier)?.text ?: "key"
                            val paramType = param?.type?.let { formatTypeForDisplay(it) } ?: "string"
                            val valueType = member.type?.let { formatTypeForDisplay(it) } ?: continue
                            indexParts.add("[$paramName: $paramType]: $valueType")
                        }
                        is MethodDeclaration -> {
                            val methodName = (member.name as? Identifier)?.text ?: continue
                            val params = member.parameters.joinToString(", ") { formatParameterDecl(it) }
                            val retType = member.type?.let { formatTypeForDisplay(it) } ?: "any"
                            when (methodName) {
                                // Call signature: `(params): ret`.
                                "" -> callSigParts.add("($params): $retType")
                                // Construct signature: `new (params): ret` (space after `new`).
                                "new" -> ctorSigParts.add("new ($params): $retType")
                                else -> {
                                    // 17.215: include `?` for optional method declarations
                                    // (e.g. `k?(a: any): any` in `interface { k?(a: any): any }`).
                                    val opt = if (member.questionToken) "?" else ""
                                    propParts.add("$methodName$opt($params): $retType")
                                }
                            }
                        }
                        else -> return null // unsupported member type
                    }
                }
                val parts = callSigParts + ctorSigParts + indexParts + propParts
                if (parts.isEmpty()) "{}" else "{ ${parts.joinToString("; ")}; }"
            }
            is TypeQuery -> {
                val name = when (val expr = typeNode.exprName) {
                    is Identifier -> expr.text
                    is QualifiedName -> {
                        // Build "A.B.C" from nested QualifiedName
                        fun fmt(n: Node): String? = when (n) {
                            is Identifier -> n.text
                            is QualifiedName -> {
                                val l = fmt(n.left) ?: return null
                                "$l.${n.right.text}"
                            }
                            else -> null
                        }
                        fmt(expr) ?: return null
                    }
                    else -> return null
                }
                "typeof $name"
            }
            is TypePredicate -> {
                val paramName = when (val pn = typeNode.parameterName) {
                    is Identifier -> pn.text
                    // Parser quirk: `c is C1` parses `c` as TypeReference. See narrowByCallPredicate.
                    is TypeReference -> (pn.typeName as? Identifier)?.text
                    is ThisType -> "this"
                    else -> null
                } ?: return null
                val asserts = if (typeNode.assertsModifier) "asserts " else ""
                val tPart = typeNode.type
                if (tPart == null) {
                    "$asserts$paramName"
                } else {
                    val typePart = formatTypeForDisplay(tPart) ?: return null
                    "$asserts$paramName is $typePart"
                }
            }
            is LiteralType -> when (val lit = typeNode.literal) {
                is NumericLiteralNode -> lit.text
                is StringLiteralNode -> "\"${lit.text}\""
                is NoSubstitutionTemplateLiteralNode -> "\"${lit.text}\""
                is Identifier -> when (lit.text) {
                    "true", "false", "null", "undefined" -> lit.text
                    else -> null
                }
                is PrefixUnaryExpression -> if (lit.operand is NumericLiteralNode && lit.operator == SyntaxKind.Minus) {
                    "-${(lit.operand).text}"
                } else null
                else -> null
            }
            else -> null
        }
    }

    /** Infer the type of a simple expression. Returns null for complex expressions. */
    private fun inferSimpleExprType(expr: Expression, varTypes: Map<String, String>): String? {
        return when (expr) {
            is NumericLiteralNode -> "number"
            is StringLiteralNode -> "string"
            is NoSubstitutionTemplateLiteralNode -> "string"
            is TemplateExpression -> "string"
            is RegularExpressionLiteralNode -> "object" // RegExp
            is Identifier -> when (expr.text) {
                "undefined" -> "undefined"
                "null" -> "null"
                "true", "false" -> "boolean"
                "NaN", "Infinity" -> "number"
                else -> null // Don't look up variable types — causes FPs with enum/union targets
            }
            is TypeOfExpression -> "string" // typeof always returns string
            is VoidExpression -> "undefined"
            is DeleteExpression -> "boolean"
            is BigIntLiteralNode -> "bigint"
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.Exclamation -> "boolean" // !x is boolean
                SyntaxKind.Minus, SyntaxKind.Plus, SyntaxKind.Tilde -> "number"
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> "number"
                else -> null
            }
            is PostfixUnaryExpression -> "number" // x++ / x-- always produce number
            is ParenthesizedExpression -> inferSimpleExprType(expr.expression, varTypes)
            is NonNullExpression -> {
                // B282: `undefined!`/`null!` is NonNullable<nullish> = never — assignable
                // to everything (`return undefined!`). Returning null skips the check.
                val inner = inferSimpleExprType(expr.expression, varTypes)
                if (inner == "undefined" || inner == "null") null else inner
            }
            is SatisfiesExpression -> inferSimpleExprType(expr.expression, varTypes)
            // (CHK.43) A type assertion's value has the ASSERTED type — full stop. When
            // [resolveSimpleTypeName] cannot render that type (an array, tuple, function
            // type, type literal, indexed access, …) the honest answer at this layer is
            // "unknowable", i.e. null, which makes every caller SKIP its string-based
            // check. It must NOT be the OPERAND's type: for the `x as unknown as T`
            // escape-hatch idiom that is `unknown`, precisely the type the outer
            // assertion exists to assert away, and reporting it produced a shipped false
            // positive (`(): B | A | (B|A)[]` + `return r as unknown as B[]`) that
            // tsc 7.0.2 does not have. The engine path above is unaffected and still
            // decides every assertion whose source genuinely does not relate.
            is AsExpression -> resolveSimpleTypeName(expr.type)
            // `<T>expr` legacy assertion form — mirrors AsExpression
            is TypeAssertionExpression -> resolveSimpleTypeName(expr.type)
            is ArrayLiteralExpression -> "array" // Used internally for assignability
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.Equals -> inferSimpleExprType(expr.right, varTypes)
                else -> null
            }
            else -> null
        }
    }

    /** Check if an expression is a simple literal (no elaboration needed in TS2322 chain). */
    private fun isSimpleLiteral(expr: Expression): Boolean {
        return when (expr) {
            is NumericLiteralNode -> true
            is StringLiteralNode -> true
            is NoSubstitutionTemplateLiteralNode -> true
            is BigIntLiteralNode -> true
            is Identifier -> true // All identifiers are "simple" (no elaboration chain)
            is ParenthesizedExpression -> isSimpleLiteral(expr.expression)
            is NonNullExpression -> isSimpleLiteral(expr.expression)
            is SatisfiesExpression -> isSimpleLiteral(expr.expression)
            is AsExpression -> isSimpleLiteral(expr.expression)
            is TypeAssertionExpression -> isSimpleLiteral(expr.expression)
            is PrefixUnaryExpression -> expr.operand is NumericLiteralNode || expr.operand is BigIntLiteralNode
            is BinaryExpression -> expr.operator == SyntaxKind.Equals && isSimpleLiteral(expr.right)
            else -> false
        }
    }

    /** Check if sourceType is assignable to targetType.
     *  Named types (from TypeReference) are prefixed with "@".
     *  Union types are prefixed with "|". */
    /** B212: does `src`'s constraint chain (in currentTypeParamDecls) reach `tgt`?
     *  `src == tgt` trivially reaches; a UNION constraint reaches iff ALL members do
     *  (`T | U ≤ Top` needs both). Depth-capped. */
    private fun tpConstraintChainReachesTp(src: String, tgt: String, depth: Int = 0): Boolean {
        if (src == tgt) return true
        if (depth >= 8) return false
        val c = currentTypeParamDecls[src]?.constraint ?: return false
        return tpConstraintNodeReachesTp(c, tgt, depth + 1)
    }

    private fun tpConstraintNodeReachesTp(c: TypeNode, tgt: String, depth: Int): Boolean = when (c) {
        is TypeReference -> {
            val cn = (c.typeName as? Identifier)?.text
            cn != null && c.typeArguments.isNullOrEmpty() && tpConstraintChainReachesTp(cn, tgt, depth)
        }
        is UnionType -> c.types.isNotEmpty() && c.types.all { tpConstraintNodeReachesTp(it, tgt, depth) }
        is ParenthesizedType -> tpConstraintNodeReachesTp(c.type, tgt, depth)
        else -> false
    }

    /** M3.1 (round 461): does a bare TypeParam SOURCE's resolved constraint CHAIN reach a
     *  concrete type assignable to [target]? tsc's rule: a type parameter relates to X iff
     *  its constraint does (`T extends C` → `t: T` is assignable to `C`). The relation
     *  engine deliberately has NO general TypeParam-source rule (the 39+ cycle-regression
     *  gate; the round-456 broad attempt was net-zero because overload arg-matching shares
     *  checkTypeRelatedTo and mis-selected signatures wherever inference under-resolves a
     *  TypeParam arg) — so this is consulted ONLY at TS2322 EMISSION sites (assignment /
     *  var-decl / return), as a suppression bail. An unconstrained TP returns false, so
     *  genuine `T`-to-concrete errors keep firing. Cycle-guarded (`T extends T`). */
    private fun bareTpConstraintRelatesTo(tp: Type.TypeParam, target: Type): Boolean {
        var c: Type? = tp.constraint
        var depth = 0
        val seen = mutableSetOf<Int>()
        while (c != null && depth < 8 && seen.add(c.id)) {
            if (c !is Type.TypeParam) {
                if (c === errorType || c === anyType) return false
                return checkTypeRelatedTo(c, target, assignableRelation)
            }
            c = c.constraint
            depth++
        }
        return false
    }

    /** B212b: is a constraint NODE assignable to a union of tp names? A ref part
     *  must reach SOME member; a union constraint needs EVERY part assignable. */
    private fun tpConstraintNodeAssignableToTpUnion(c: TypeNode, members: List<String>): Boolean = when (c) {
        is TypeReference -> {
            val cn = (c.typeName as? Identifier)?.text
            cn != null && c.typeArguments.isNullOrEmpty() &&
                members.any { tpConstraintChainReachesTp(cn, it) }
        }
        is UnionType -> c.types.isNotEmpty() && c.types.all { tpConstraintNodeAssignableToTpUnion(it, members) }
        is ParenthesizedType -> tpConstraintNodeAssignableToTpUnion(c.type, members)
        else -> false
    }

    /** Round 481: is a union-member DISPLAY string (resolveSimpleTypeName's UnionType
     *  encoding carries NO "@" prefix) a named TYPE ALIAS whose body is array-ish?
     *  The string layer cannot see alias bodies: `ArrayOrSingle<T> = T | readonly
     *  T[]` accepts an array literal (fourslash `expected = [expected]`).
     *  Suppression-only (a permissive true just skips the string-layer TS2322);
     *  interfaces — even Array-extending ones — stay firing (their extra members
     *  make a bare array literal a genuine tsc error). */
    private fun namedUnionMemberCouldAcceptArray(member: String): Boolean {
        val base = member.substringBefore('<').removePrefix("readonly ").trim()
        if (base.isEmpty() || !base[0].isLetter() || !base[0].isUpperCase()) return false
        if (base == "Array" || base == "ReadonlyArray") return true
        var sym = currentFileLocals?.get(base) ?: globals[base] ?: return false
        // INV.3(d): the alias is typically IMPORTED (fourslashImpl's
        // `import ArrayOrSingle = FourSlashInterface.ArrayOrSingle` through the
        // ns-import barrel) — the retired merge no longer leaks the declaring
        // file's alias into [globals]; hop ImportSpecifiers like [lookupPerFile]
        // does and every other alias shape through [resolveAlias] (whose
        // QualifiedName arm now walks ns-import barrels).
        if (sym.flags.hasAny(SymbolFlags.Alias)) {
            sym = (if (sym.declarations.any { it is ImportSpecifier })
                resolveImportedSymbolGeneral(sym) else null)
                ?: resolveAlias(sym)
        }
        for (decl in sym.declarations) {
            if (decl is TypeAliasDeclaration && typeNodeContainsArrayIsh(decl.type, 0)) return true
        }
        return false
    }

    private fun typeNodeContainsArrayIsh(t: TypeNode, depth: Int): Boolean {
        if (depth > 4) return false
        return when (t) {
            is ArrayType -> true
            is TupleType -> true
            is TypeOperator -> typeNodeContainsArrayIsh(t.type, depth + 1)
            is ParenthesizedType -> typeNodeContainsArrayIsh(t.type, depth + 1)
            is UnionType -> t.types.any { typeNodeContainsArrayIsh(it, depth + 1) }
            is TypeReference -> {
                val n = (t.typeName as? Identifier)?.text
                n == "Array" || n == "ReadonlyArray"
            }
            else -> false
        }
    }

    private fun isAssignableTo(sourceType: String, targetType: String, typeParams: Set<String> = emptySet()): Boolean {
        if (sourceType == targetType) return true
        // B250: "&"-prefixed intersection encodings participate only in the dedicated
        // bare-TP pre-check in checkAssignmentExpression; everywhere else treat them
        // as unknown → permissive (identical to the entry being absent).
        if (sourceType.startsWith("&") || targetType.startsWith("&")) return true
        if (targetType == "any" || targetType == "unknown") return true
        if (sourceType == "any") return true
        // undefined is assignable to void
        if (sourceType == "undefined" && targetType == "void") return true
        // When strict null checks are off, null and undefined are assignable to everything
        if (!strictNullChecks && (sourceType == "null" || sourceType == "undefined")) return true
        // Union types: source is assignable to union if it matches any member
        if (targetType.startsWith("|")) {
            val members = targetType.removePrefix("|").split(" | ")
            // null/undefined are only assignable to union if a member is null/undefined/void
            if (sourceType == "null" || sourceType == "undefined") {
                return members.any { it == sourceType || it == "any" || it == "unknown" || (sourceType == "undefined" && it == "void") }
            }
            // B212b: bare-TP source vs union-of-TPs target — `Bottom ≤ T | U` iff
            // Bottom is a member, or Bottom's constraint relates to the union:
            // a union constraint needs EVERY part to reach SOME member (diamond3's
            // `Bottom extends Top | T | U` vs `T | U` fails on Top).
            if (sourceType.startsWith("@") && !sourceType.contains('<')) {
                val srcName = sourceType.removePrefix("@")
                if (srcName in typeParams && members.all { it in typeParams }) {
                    if (srcName in members) return true
                    val c = currentTypeParamDecls[srcName]?.constraint ?: return false
                    return tpConstraintNodeAssignableToTpUnion(c, members)
                }
            }
            // For other source types, assignable if it matches any member.
            // M3.1 (round 428): an array-literal source is unknowable against an
            // ARRAY-ISH union member — a `T[]`/`X[]` suffix form, a tuple
            // `[A, B]`, or an `Array<X>`/`ReadonlyArray<X>` reference (`return
            // [value]` inside `append<T>` vs `T[] | undefined`; tsc's
            // `sourcesContent = []` vs `(string | null)[] | undefined`) —
            // permissive: the string layer cannot check element types, and the
            // engine path owns concrete non-union array-literal targets.
            // typeParams is deliberately NOT threaded into the recursion: the
            // TP-aware rules inside (B60.6/B60.7/B212b) were tuned for
            // non-union targets and would flip union members to rejections.
            return members.any {
                isAssignableTo(sourceType, it) ||
                    (sourceType == "array" && (
                        it.endsWith("[]") ||
                        (it.startsWith("[") && it.endsWith("]")) ||
                        it.startsWith("@Array<") || it.startsWith("@ReadonlyArray<") ||
                        // Round 481: a NAMED member (union members are DISPLAY strings,
                        // no "@") whose alias body or interface heritage is array-ish is
                        // unknowable at the string layer (`ArrayOrSingle<T> = T |
                        // readonly T[]`; `interface X extends ReadonlyArray<T>` —
                        // fourslash `expected = [expected]` vs `ArrayOrSingle<…> | …`).
                        namedUnionMemberCouldAcceptArray(it)))
            }
        }
        // For named types (TypeReference, prefixed with "@"), we can only confidently say
        // that null/undefined are NOT assignable. Other source types might actually be
        // assignable via structural typing, type aliases, etc.
        if (targetType.startsWith("@")) {
            // B54.3: when source and target are both same-base-name parameterized types
            // (`@A<string>` vs `@A<number>`), compare type args directly. Different args
            // for the same base interface are NOT assignable. Narrowed by B54.9 to ONLY
            // fire when at least one of the args is a primitive type name (string, number,
            // boolean, etc.) — for named-type args (interfaces like X, Y, Foo, Bar), we
            // can't determine structural compatibility from the varTypes strings, and
            // `class C<T>` is structurally compatible for structurally-identical X/Y per
            // generics3_ts. Excludes TypeParam-only cases (`A<T>` vs `A<U>`) too unless
            // ONE side is a concrete primitive (per typeParameterAssignmentCompat1 vs
            // generics3 distinction).
            if (sourceType.startsWith("@") && sourceType != targetType) {
                // B60.6: bare TypeParam vs bare TypeParam (distinct names, no type
                // args on either side). Treat as nominally distinct per strict-
                // generic-checks semantics — `function ff<T, U>(x: T, y: U) { x = y; }`
                // fires TS2322 for `x = y` because T and U could be instantiated
                // with unrelated types. Mirrors B55.1's same-base-with-different-
                // TypeParam-args logic for the bare case.
                if (!sourceType.contains('<') && !targetType.contains('<')) {
                    val srcName = sourceType.removePrefix("@")
                    val tgtName = targetType.removePrefix("@")
                    if (srcName != tgtName && srcName in typeParams && tgtName in typeParams) {
                        // B60.6e: SKIP when src's constraint chain reaches tgt (e.g.
                        // `B extends A` → B assignable to A). B212: a UNION constraint
                        // (`Bottom extends T | U`) reaches tgt iff ALL members do
                        // (T|U ≤ Top needs both T ≤ Top and U ≤ Top) — diamond1's
                        // `T extends Top, U extends Top` is assignable, diamond2's
                        // unconstrained U is not.
                        if (!tpConstraintChainReachesTp(srcName, tgtName)) return false
                    }
                    // B60.7: bare TypeParam source → named non-TypeParam target.
                    // Source must be UNCONSTRAINED (no `extends`). With unconstrained T,
                    // the apparent type is {} — not assignable to a named interface.
                    // With `T extends X`, source IS assignable (apparent type is X) —
                    // skip the gate (only fires for unconstrained or self-circular).
                    if (srcName != tgtName && srcName in typeParams && tgtName !in typeParams) {
                        val srcDecl = currentTypeParamDecls[srcName]
                        val isCircular = (srcDecl?.constraint as? TypeReference)?.let {
                            (it.typeName as? Identifier)?.text == srcName
                        } == true
                        val effectivelyUnconstrained = srcDecl?.constraint == null || isCircular
                        if (effectivelyUnconstrained) {
                            // B60.7c (broadened): allow ALL named targets, not just
                            // Object/Function. TypeScript flags unconstrained T → any
                            // specific named interface. Skip primitive-keyword names
                            // (those are handled elsewhere — `number`, etc. don't start
                            // with `@` here so won't be picked up by this branch anyway).
                            return false
                        }
                    }
                }
                val srcBase = sourceType.substringBefore('<')
                val tgtBase = targetType.substringBefore('<')
                if (srcBase == tgtBase && sourceType.contains('<') && targetType.contains('<')) {
                    val srcArgRaw = sourceType.substringAfter('<').removeSuffix(">")
                    val tgtArgRaw = targetType.substringAfter('<').removeSuffix(">")
                    val srcArg = srcArgRaw.removePrefix("@")
                    val tgtArg = tgtArgRaw.removePrefix("@")
                    val primitives = setOf("string", "number", "boolean", "bigint", "symbol",
                        "void", "null", "undefined", "any", "unknown", "never")
                    val srcIsPrim = srcArg in primitives
                    val tgtIsPrim = tgtArg in primitives
                    // B54.9 gate (post-regression-narrowing): fire when at least one arg is
                    // a primitive type (definitively different from any non-primitive). For
                    // named-type-vs-named-type args (X, Y, Foo, Bar), we can't determine
                    // structural compatibility from the string form, so we defer to the
                    // safe default (return true at the bottom). Excludes:
                    //   - generics3_ts `C<X>` vs `C<Y>` (both X, Y are named types — structurally identical)
                    //   - promisesWithConstraints_ts `Promise<Foo>` vs `Promise<Bar>` (covariance)
                    // Includes:
                    //   - getAndSetNotIdenticalType3_ts `A<string>` vs `A<number>` (primitives)
                    //   - getAndSetNotIdenticalType2_ts `A<string>` vs `A<T>` (TypeParam vs primitive)
                    if (srcIsPrim || tgtIsPrim) return false
                    // B55.1 (probe): both args are different TypeParams in the current scope —
                    // treat as nominally distinct per strict-generic-checks semantics.
                    // typeParameterAssignmentCompat1_ts wants TS2322 for `Foo<T>` vs `Foo<U>`.
                    if (srcArg != tgtArg && srcArg in typeParams && tgtArg in typeParams) return false
                }
            }
            // B212: union-of-TPs source (`T | U`) vs bare-TP target (`Top`) —
            // assignable only when EVERY member's constraint chain reaches the target
            // tp. `T extends Top` passes; an unconstrained `U` makes the union fail
            // (strict-generic-checks semantics; tsc always errors with the
            // "could be instantiated with an arbitrary type" chain).
            if (sourceType.startsWith("|") && !targetType.contains('<')) {
                val tgtName = targetType.removePrefix("@")
                val members = sourceType.removePrefix("|").split(" | ")
                if (tgtName in typeParams && members.all { it in typeParams }) {
                    return members.all { tpConstraintChainReachesTp(it, tgtName) }
                }
            }
            // null and undefined are never assignable to named types (with strict null checks)
            return sourceType != "null" && sourceType != "undefined"
        }
        if (sourceType.startsWith("@") || sourceType.startsWith("|")) {
            // Named/union source type vs keyword target — can't determine without full resolution
            return true // safe default: assume assignable to avoid FPs
        }
        // null is assignable to any/unknown (already handled above) but NOT void or other types
        // number literal subtypes
        if (sourceType == "number" && targetType == "object") return false
        if (sourceType == "string" && targetType == "object") return false
        // M3.1 (round 428): an array-literal source vs a bare `T[]` target where T
        // is an enclosing fn's type param — the element type is unknowable at the
        // string layer (`return [value]` inside a generic fn returning `T[]`).
        // Permissive; a non-array source vs `T[]` is still a kind mismatch and
        // keeps firing.
        if (sourceType == "array" && targetType.endsWith("[]") &&
            targetType.removeSuffix("[]") in typeParams) return true
        // Otherwise, different primitive types are not assignable
        return false
    }

    /** B57.3c: emit TS2615 "Type of property 'X' circularly references itself in mapped
     *  type '...'." at the same span as the paired TS2589, using the captured
     *  [mappedTypeCircularInfo]. Span computed identically to [emitTs2589AtTypeNode]. */
    private fun emitTs2615AtTypeNode(node: TypeNode, propertyName: String, mappedTypeDisplay: String, source: String, fileName: String) {
        val startPos = node.pos
        if (startPos < 0 || startPos >= source.length) return
        var endPos = node.end.coerceAtMost(source.length)
        while (endPos > startPos) {
            val ch = source[endPos - 1]
            if (ch == '>' || ch == ']') break
            if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' ||
                ch == ';' || ch == ',' || ch == ')' || ch == '=') endPos--
            else break
        }
        val length = (endPos - startPos).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
        diagnostics.add(Diagnostic(
            message = "Type of property '$propertyName' circularly references itself in mapped type '$mappedTypeDisplay'.",
            category = DiagnosticCategory.Error,
            code = 2615,
            fileName = fileName,
            line = line,
            character = character,
            start = startPos,
            length = length,
        ))
    }

    /** B57.3d (a): record a `new C<...>(...)` whose explicit-type-arg resolution
     *  triggered [deepInstantiationBailed]. Span covers the full `new` expression
     *  (matches TypeScript baselines like `circularInlineMappedGenericTupleTypeNoCrash`).
     *  Dedup by (fileName, pos). */
    private fun recordDeepBailNewExpression(expr: NewExpression) {
        recordDeepBailExpression(expr)
    }

    /**
     * B189: true when [expr] is a SELF-GROWING mapped-tuple instantiation — the shape that
     * deterministically blows tsc's instantiation limiter (TS2589) but produces ZERO
     * recursion in our checker (mapped types over non-enumerable `keyof TP` constraints
     * bail to anyType immediately). Three-part gate (all load-bearing):
     * (a) an explicit type arg at position i is a TupleType (≥2 elements) containing a
     *     rest element whose operand is a bare TypeReference naming the callee class's own
     *     type parameter at the SAME index i (the tuple re-embeds the TP plus extra
     *     elements → unbounded growth per instantiation round);
     * (b) the class has a Constructor with a rest parameter whose annotation is a
     *     MappedType over `keyof <that TP>` (the member whose instantiation tsc is forced
     *     to expand during arg checking);
     * (c) the `new` lies WITHIN the class's own body in the current check file (the
     *     self-recursion locus).
     * A corpus sweep for `new X<[...` matches exactly one fixture; the gate is shape-based
     * emission (house precedent B147/B154/B155), not a real depth limiter — the general
     * mechanism stays Blocker-#2-adjacent.
     */
    private fun isSelfGrowingMappedTupleNew(expr: NewExpression, calleeType: Type.Interface): Boolean {
        val sym = calleeType.symbol ?: return false
        val cls = sym.declarations.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: return false
        val tps = cls.typeParameters ?: return false
        val typeArgs = expr.typeArguments ?: return false
        val fileName = currentCheckFileName ?: return false
        val sf = binderResults.find { it.sourceFile.fileName == fileName }?.sourceFile ?: return false
        if (!statementsContainClassIdentity(sf.statements, cls)) return false
        if (expr.pos < cls.pos || expr.pos >= cls.end) return false
        var grownTp: String? = null
        for (i in typeArgs.indices) {
            if (i >= tps.size) break
            val tup = typeArgs[i] as? TupleType ?: continue
            if (tup.elements.size < 2) continue
            val tpName = tps[i].name.text
            val grows = tup.elements.any { el ->
                val operand = when {
                    el is RestType -> el.type
                    el is NamedTupleMember && el.dotDotDotToken -> el.type
                    else -> null
                } as? TypeReference ?: return@any false
                operand.typeArguments.isNullOrEmpty() &&
                    (operand.typeName as? Identifier)?.text == tpName
            }
            if (grows) { grownTp = tpName; break }
        }
        val tp = grownTp ?: return false
        return cls.members.any { m ->
            m is Constructor && m.parameters.any { p ->
                p.dotDotDotToken && isMappedOverKeyofTp(p.type, tp)
            }
        }
    }

    /** B189 helper: [t] is a MappedType whose typeParameter constraint is `keyof <tp>`. */
    private fun isMappedOverKeyofTp(t: TypeNode?, tp: String): Boolean {
        if (t !is MappedType) return false
        val op = t.typeParameter.constraint as? TypeOperator ?: return false
        if (op.operator != SyntaxKind.KeyOfKeyword) return false
        val ref = op.type as? TypeReference ?: return false
        return ref.typeArguments.isNullOrEmpty() && (ref.typeName as? Identifier)?.text == tp
    }

    /** B189 helper: identity-scan for [cls] among top-level statements (incl. inside
     *  function bodies, where the fixture's class lives). */
    private fun statementsContainClassIdentity(stmts: List<Statement>, cls: ClassDeclaration): Boolean {
        for (s in stmts) {
            if (s === cls) return true
            if (s is FunctionDeclaration && s.body?.let { statementsContainClassIdentity(it.statements, cls) } == true) return true
            if (s is ModuleDeclaration && (s.body as? ModuleBlock)?.let { statementsContainClassIdentity(it.statements, cls) } == true) return true
            if (s is Block && statementsContainClassIdentity(s.statements, cls)) return true
        }
        return false
    }

    /** B57.3d (b): record any Expression whose explicit-type-arg resolution
     *  triggered [deepInstantiationBailed]. Generalizes [recordDeepBailNewExpression]
     *  so the same dedup+deferred-emit infrastructure is shared by NewExpression
     *  and CallExpression call sites (both have `typeArguments`). */
    private fun recordDeepBailExpression(expr: Expression) {
        val fileName = currentCheckFileName ?: return
        val start = expr.pos
        if (start < 0) return
        val key = "$fileName|$start"
        if (!deepBailNewExprPositions.add(key)) return
        val end = expressionTrueEnd(expr)
        val length = (end - start).coerceAtLeast(1)
        deepBailNewExprEmits.add(Triple(fileName, start, length))
    }

    /** B57.3d (a): flush queued TS2589 emissions into [diagnostics]. */
    private fun flushDeepBailNewExpressionEmits() {
        if (deepBailNewExprEmits.isEmpty()) return
        for ((fileName, start, length) in deepBailNewExprEmits) {
            val source = binderResults.find { it.sourceFile.fileName == fileName }?.sourceFile?.text
                ?: continue
            if (start >= source.length) continue
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type instantiation is excessively deep and possibly infinite.",
                category = DiagnosticCategory.Error,
                code = 2589,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
        deepBailNewExprEmits.clear()
        deepBailNewExprPositions.clear()
    }

    /** B57.1: emit TS2589 "Type instantiation is excessively deep" at a TypeNode's span.
     *  For a TypeReferenceNode like `Foo<"true", {}>`, spans from the name's position to
     *  the position right after the closing `>`. node.end overshoots (includes the next
     *  token's scan), so we trim trailing whitespace/punctuation back to find the real end. */
    private fun emitTs2589AtTypeNode(node: TypeNode, source: String, fileName: String) {
        val startPos = node.pos
        if (startPos < 0 || startPos >= source.length) return
        var endPos = node.end.coerceAtMost(source.length)
        // Trim back past trailing whitespace / `;` / `,` / `)` etc. to land at `>`.
        while (endPos > startPos) {
            val ch = source[endPos - 1]
            if (ch == '>' || ch == ']') break
            if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' ||
                ch == ';' || ch == ',' || ch == ')' || ch == '=') endPos--
            else break
        }
        val length = (endPos - startPos).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
        diagnostics.add(Diagnostic(
            message = "Type instantiation is excessively deep and possibly infinite.",
            category = DiagnosticCategory.Error,
            code = 2589,
            fileName = fileName,
            line = line,
            character = character,
            start = startPos,
            length = length,
        ))
    }

    private fun emitTS2322(start: Int, length: Int, sourceType: String, targetType: String, source: String, fileName: String, hasElaboration: Boolean = false, typeParams: Set<String> = emptySet()) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Strip "@"/"@" prefix from named/union types for display
        val displaySource = sourceType.removePrefix("@").removePrefix("|")
        val displayTarget = targetType.removePrefix("@").removePrefix("|")
        val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
        // Check if target type is a type parameter — add elaboration chain
        val chain = mutableListOf<String>()
        if (hasElaboration) chain.add("  $message")
        if (targetType.startsWith("@")) {
            val targetBaseName = displayTarget.substringBefore('<')
            if (targetBaseName in typeParams) {
                // B60.6c: when target is a bare TypeParam with a constraint AND source
                // is bare TypeParam with the SAME constraint (display-equal), use the
                // "constraint-assignable" chain form. Matches B60.2's logic for the
                // Type-engine path. Pure-string heuristic: pull each TypeParam's
                // constraint text from currentTypeParamDecls and compare displays.
                val tgtDecl = currentTypeParamDecls[targetBaseName]
                val srcBareName = if (sourceType.startsWith("@") && !sourceType.contains('<'))
                    sourceType.removePrefix("@") else null
                val srcDecl = srcBareName?.let { currentTypeParamDecls[it] }
                val tgtCnstr = tgtDecl?.constraint
                val srcCnstr = srcDecl?.constraint
                val constraintMatch = tgtCnstr != null && srcCnstr != null &&
                    formatTypeForDisplay(tgtCnstr) == formatTypeForDisplay(srcCnstr)
                if (constraintMatch) {
                    val constraintDisplay = formatTypeForDisplay(tgtCnstr) ?: "any"
                    chain.add("  '$displaySource' is assignable to the constraint of type '$targetBaseName', but '$targetBaseName' could be instantiated with a different subtype of constraint '$constraintDisplay'.")
                    // B60.6d: source is the lib `Object` type → add the special hint
                    // "The 'Object' type is assignable to very few other types. Did you
                    // mean to use the 'any' type instead?"
                    if (displaySource == "Object") {
                        chain.add("    The 'Object' type is assignable to very few other types. Did you mean to use the 'any' type instead?")
                    }
                } else {
                    chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                }
            }
        }
        // B54.4: same-base same-name generic ref mismatch — add leaf chain entry comparing
        // diverging type args. For `@A<string>` vs `@A<number>`, emit
        // "  Type 'string' is not assignable to type 'number'." Pairs with B54.3's gate.
        if (sourceType.startsWith("@") && targetType.startsWith("@") &&
            sourceType.contains('<') && targetType.contains('<')) {
            val srcBase = sourceType.substringBefore('<')
            val tgtBase = targetType.substringBefore('<')
            if (srcBase == tgtBase) {
                val srcArg = sourceType.substringAfter('<').removeSuffix(">").removePrefix("@")
                val tgtArg = targetType.substringAfter('<').removeSuffix(">").removePrefix("@")
                if (srcArg != tgtArg && !srcArg.contains(',') && !tgtArg.contains(',')) {
                    chain.add("  Type '$srcArg' is not assignable to type '$tgtArg'.")
                    // B54.8 (re-enable, narrower gate): when target type arg is a TypeParam
                    // in scope, add "'X' could be instantiated with an arbitrary type which
                    // could be unrelated to 'Y'." matching TypeScript's behavior for
                    // generic-ref-assignment mismatches into a TypeParam-parameterized
                    // target. Gate on tgtArg in typeParams (don't require srcArg to be one).
                    if (tgtArg in typeParams) {
                        chain.add("    '$tgtArg' could be instantiated with an arbitrary type which could be unrelated to '$srcArg'.")
                    }
                }
            }
        }
        // B55.2: TS2208 related info "This type parameter might need an `extends X` constraint."
        // Fires when same-base ref mismatch with both args as different TypeParams in scope.
        // Points to the source TypeParam's declaration (the one that "needs the constraint").
        val relatedInfo = mutableListOf<Diagnostic>()
        if (sourceType.startsWith("@") && targetType.startsWith("@") &&
            sourceType.contains('<') && targetType.contains('<')
        ) {
            val srcBase = sourceType.substringBefore('<')
            val tgtBase = targetType.substringBefore('<')
            if (srcBase == tgtBase) {
                val srcArg = sourceType.substringAfter('<').removeSuffix(">").removePrefix("@")
                val tgtArg = targetType.substringAfter('<').removeSuffix(">").removePrefix("@")
                if (srcArg != tgtArg && srcArg in typeParams && tgtArg in typeParams) {
                    // Source TypeParam needs `extends <Target>` constraint.
                    val srcTpDecl = currentTypeParamDecls[srcArg]
                    if (srcTpDecl != null) {
                        val decPos = srcTpDecl.name.pos
                        val decLen = srcTpDecl.name.text.length
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, decPos)
                        relatedInfo.add(Diagnostic(
                            message = "This type parameter might need an `extends $tgtArg` constraint.",
                            category = DiagnosticCategory.Message,
                            code = 2208,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = decPos,
                            length = decLen,
                        ))
                    }
                }
            }
        }
        // B212b: bare-TP source vs union-of-TPs target — the constraint-mismatch
        // chain (`Bottom extends Top | T | U` vs `T | U`): show the constraint
        // display, then the first failing part; TS2208 at that part's decl when
        // it is an unconstrained tp.
        if (sourceType.startsWith("@") && !sourceType.contains('<') && targetType.startsWith("|")) {
            val srcName = sourceType.removePrefix("@")
            val members = displayTarget.split(" | ")
            if (srcName in typeParams && members.all { it in typeParams }) {
                val c = currentTypeParamDecls[srcName]?.constraint
                val cDisp = c?.let { formatTypeForDisplay(it) }
                val failing = (c as? UnionType)?.types?.firstNotNullOfOrNull { part ->
                    val pn = ((part as? TypeReference)?.typeName as? Identifier)?.text
                    if (pn != null && members.none { tpConstraintChainReachesTp(pn, it) }) pn else null
                }
                if (cDisp != null && failing != null) {
                    chain.add("  Type '$cDisp' is not assignable to type '$displayTarget'.")
                    chain.add("    Type '$failing' is not assignable to type '$displayTarget'.")
                    val fd = currentTypeParamDecls[failing]
                    if (fd != null && fd.constraint == null) {
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, fd.name.pos)
                        relatedInfo.add(Diagnostic(
                            message = "This type parameter might need an `extends $displayTarget` constraint.",
                            category = DiagnosticCategory.Message, code = 2208,
                            fileName = fileName, line = relLine, character = relChar,
                            start = fd.name.pos, length = fd.name.text.length,
                        ))
                    }
                }
            }
        }
        // B212: union-of-TPs source vs bare-TP target — TS2208 at the FIRST member
        // that is an UNCONSTRAINED tp (the one needing `extends <target>`). `T | U`
        // vs `Top` where `T extends Top` points at U.
        if (sourceType.startsWith("|") && targetType.startsWith("@") && !targetType.contains('<')) {
            val tgtName = targetType.removePrefix("@")
            if (tgtName in typeParams) {
                val firstUnconstrained = sourceType.removePrefix("|").split(" | ")
                    .firstOrNull {
                        it in typeParams && it != tgtName &&
                            currentTypeParamDecls[it]?.constraint == null
                    }
                val decl = firstUnconstrained?.let { currentTypeParamDecls[it] }
                if (decl != null) {
                    val (relLine, relChar) = getLineAndCharacterOfPosition(source, decl.name.pos)
                    relatedInfo.add(Diagnostic(
                        message = "This type parameter might need an `extends $tgtName` constraint.",
                        category = DiagnosticCategory.Message, code = 2208,
                        fileName = fileName, line = relLine, character = relChar,
                        start = decl.name.pos, length = decl.name.text.length,
                    ))
                }
            }
        }
        // B60.6f: TS2208 for bare TypeParam mismatch — either both bare TypeParams
        // (`U → T`), or bare TypeParam source → named target (`T → Object`), or
        // bare TypeParam source → primitive target (`T → number`). Points to
        // source's declaration with the suggested `extends <target>` constraint.
        // Gate: source TypeParam must be UNCONSTRAINED (no existing extends clause,
        // OR has a self-circular constraint which is effectively unconstrained).
        val tgtIsPrimitiveName = targetType in setOf("number", "string", "boolean", "bigint", "symbol", "object", "void")
        val tgtAcceptable = (targetType.startsWith("@") && !targetType.contains('<')) || tgtIsPrimitiveName
        if (sourceType.startsWith("@") && !sourceType.contains('<') && tgtAcceptable
        ) {
            val srcName = sourceType.removePrefix("@")
            val tgtName = targetType.removePrefix("@")
            if (srcName != tgtName && srcName in typeParams) {
                val srcTpDecl = currentTypeParamDecls[srcName]
                // B60.10b: treat self-circular constraint (e.g. `T extends T`) as
                // effectively unconstrained — TypeScript also suggests a constraint
                // here despite the syntactic constraint existing.
                fun isEffectivelyUnconstrained(tp: TypeParameter?): Boolean {
                    if (tp == null) return false
                    if (tp.constraint == null) return true
                    val cnstr = tp.constraint as? TypeReference ?: return false
                    val cnstrName = (cnstr.typeName as? Identifier)?.text ?: return false
                    return cnstrName == tp.name.text
                }
                if (srcTpDecl != null && isEffectivelyUnconstrained(srcTpDecl)) {
                    val decPos = srcTpDecl.name.pos
                    val decLen = srcTpDecl.name.text.length
                    val (relLine, relChar) = getLineAndCharacterOfPosition(source, decPos)
                    relatedInfo.add(Diagnostic(
                        message = "This type parameter might need an `extends $tgtName` constraint.",
                        category = DiagnosticCategory.Message,
                        code = 2208,
                        fileName = fileName,
                        line = relLine,
                        character = relChar,
                        start = decPos,
                        length = decLen,
                    ))
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = 2322,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = chain,
            relatedInformation = if (relatedInfo.isEmpty()) emptyList() else relatedInfo.toList(),
        ))
    }

    /**
     * For TS2741 "required in type 'X'", when the missing property is inherited,
     * TypeScript displays the DECLARING class/interface name (where the property
     * was actually declared), not the annotation target type. E.g. `c2 = c` where
     * `c2: C2 extends A` and `x` comes from A → "required in type 'A'", not 'C2'.
     *
     * Conservative: only override when the property symbol has a parent symbol
     * whose name differs from the target type's symbol — indicating an inherited
     * property. Keeps the annotation display for directly-declared properties.
     */
    /** inheritance1: in a missing-property message tsc reduces a class with a COMPLETELY
     *  EMPTY body (no members declared at all — not even a constructor) that `extends` exactly
     *  one base to the BASE's name (recursively). Returns the reduced base name, or null when
     *  [decl] is NOT such an empty single-extends subclass. (`class ImageBase extends Control {}`
     *  → "Control"; `class C extends B { constructor(){…} }` keeps "C" — `bases.ts`.) */
    private fun emptySubclassBaseNameAst(decl: ClassDeclaration, depth: Int = 0): String? {
        if (depth > 16) return null
        if (decl.members.isNotEmpty()) return null
        val ext = decl.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword } ?: return null
        if (ext.types.size != 1) return null
        val baseName = (ext.types[0].expression as? Identifier)?.text ?: return null
        val baseDecl = (globals[baseName] ?: currentFileLocals?.get(baseName))
            ?.declarations?.filterIsInstance<ClassDeclaration>()?.firstOrNull()
        if (baseDecl != null) emptySubclassBaseNameAst(baseDecl, depth + 1)?.let { return it }
        return baseName
    }

    /** Resolve [type] to a CLASS symbol and apply [emptySubclassBaseNameAst]; null for
     *  non-class types (interfaces never reduce). */
    private fun emptySubclassBaseName(type: Type): String? {
        val sym = when (type) {
            is Type.Reference -> type.target.symbol
            is Type.Object -> type.symbol
            else -> null
        } ?: return null
        if (!sym.flags.hasAny(SymbolFlags.Class)) return null
        val decl = sym.declarations.filterIsInstance<ClassDeclaration>().firstOrNull() ?: return null
        return emptySubclassBaseNameAst(decl)
    }

    private fun getDeclaringTypeDisplay(
        propSymbol: Symbol?,
        targetType: Type,
        fallback: String,
    ): String {
        val parent = propSymbol?.parent ?: return fallback
        val parentName = parent.name
        if (parentName.isEmpty()) return fallback
        val targetSym = when (targetType) {
            is Type.Reference -> targetType.target.symbol
            is Type.Object -> targetType.symbol
            else -> null
        } ?: return fallback
        if (targetSym === parent) return fallback
        // inheritance1: tsc's TS2741/TS2420 "required in type X" name is the displayed
        // target type name, EXCEPT when the target is an empty subclass (zero own instance
        // members + single `extends`), which reduces to its base name. The earlier
        // private/protected→declaring-class heuristic was a MISDIAGNOSIS of this rule: its
        // only motivating case (`c2 = c`, C2 empty `extends A`, private `x`) is itself an
        // empty-subclass reduction (C2 → "A"), while a NON-empty target with an inherited
        // private member (SelectableControl, has `select`) must keep its own name.
        return emptySubclassBaseName(targetType) ?: fallback
    }

    /**
     * Create TS2728 related diagnostic ("'name' is declared here.") for a property symbol.
     * Used as related info for TS2741 (missing property) diagnostics.
     */
    private fun createPropertyDeclaredHereRelatedInfo(propSymbol: Symbol): Diagnostic? {
        val decl = propSymbol.declarations.firstOrNull() ?: return null
        val declPos = when (decl) {
            is PropertyDeclaration -> (decl.name as? Identifier)?.pos ?: (decl.name as? StringLiteralNode)?.pos ?: decl.pos
            is MethodDeclaration -> (decl.name as? Identifier)?.pos ?: (decl.name as? StringLiteralNode)?.pos ?: decl.pos
            else -> decl.pos
        }
        if (declPos < 0) return null
        // M2.2: a real-lib member declaration is attributed NODE-first — under multi-file
        // real libs its position can false-match the B217 name scan below (e.g. a lib
        // `sub` decl's position lands on `subby` in the user file). Render `<distName>:--:--`.
        libFileOfDecl(decl)?.let { libFile ->
            return Diagnostic(
                message = "'${formatPropertyDisplayName(propSymbol)}' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = libFile,
                line = null,
                character = null,
                start = declPos,
                length = propSymbol.name.length,
            )
        }
        // B217: position-only attribution mis-fires in multi-file tests when the
        // pos fits inside several files' text — prefer the file whose text actually
        // carries the property NAME at declPos, then fall back to position-fit.
        // B291: a string-literal-NAMED declaration carries the QUOTED form at
        // declPos — match those too, or quoted names fall to the position-fit
        // guess (which picks the first file).
        var declFile: String? = null
        var declSource: String? = null
        val nameForms = arrayOf(propSymbol.name, "\"${propSymbol.name}\"", "'${propSymbol.name}'")
        outer@ for (result in binderResults) {
            val sf = result.sourceFile
            for (form in nameForms) {
                if (declPos + form.length <= sf.text.length &&
                    sf.text.regionMatches(declPos, form, 0, form.length)) {
                    declFile = sf.fileName; declSource = sf.text; break@outer
                }
            }
        }
        if (declFile == null || declSource == null) {
            val (f, s) = resolveDeclarationSourceFile(declPos)
            declFile = f; declSource = s
        }
        if (declFile == null || declSource == null) return null
        val declLength = propSymbol.name.length
        val isLib = isLibFileName(declFile)
        val declLine: Int?
        val declChar: Int?
        if (isLib) {
            declLine = null
            declChar = null
        } else {
            val p = getLineAndCharacterOfPosition(declSource, declPos)
            declLine = p.first
            declChar = p.second
        }
        return Diagnostic(
            message = "'${formatPropertyDisplayName(propSymbol)}' is declared here.",
            category = DiagnosticCategory.Message,
            code = 2728,
            fileName = declFile,
            line = declLine,
            character = declChar,
            start = declPos,
            length = declLength,
        )
    }

    /**
     * Resolve the source file containing [declPos]. Checks user files in [binderResults]
     * first, then falls back to the built-in lib source file. Returns `(fileName, text)`
     * of the matching source, or `(null, null)` if not found.
     */
    /**
     * M2.2: the distributed lib file name that [decl] came from, when it is a real-lib
     * declaration node (see [realLibDeclFile]) — else null (embedded lib or a user node).
     * TS2728 builders consult this NODE-first, because under multi-file real libs the
     * position-based [resolveDeclarationSourceFile] can't disambiguate overlapping lib
     * positions and can false-match a large user file.
     */
    private fun libFileOfDecl(decl: Node?): String? = decl?.let { realLibDeclFile[it] }

    private fun resolveDeclarationSourceFile(declPos: Int): Pair<String?, String?> {
        if (declPos < 0) return Pair(null, null)
        for (result in binderResults) {
            val sf = result.sourceFile
            if (declPos in 0 until sf.text.length) {
                return Pair(sf.fileName, sf.text)
            }
        }
        val builtin = builtinLibSourceFile
        if (builtin != null && declPos in 0 until builtin.text.length) {
            return Pair(builtin.fileName, builtin.text)
        }
        return Pair(null, null)
    }

    /**
     * True when [fileName] matches the TypeScript `lib.*.d.ts` convention. Such diagnostics
     * are rendered with `:--:--` in TypeScript's error baselines (line/column hidden because
     * lib line numbers shift between TS versions).
     */
    private fun isLibFileName(fileName: String): Boolean {
        val base = fileName.substringAfterLast('/').substringAfterLast('\\')
        return base.startsWith("lib.") && base.endsWith(".d.ts")
    }

    /**
     * Find the declaring file for [sym] by searching each binderResult's top-level locals
     * for identity-equality with the symbol. Returns the basename (no path, no extension)
     * for `import("X")` qualification. Returns null if not found at file-level (e.g. lib
     * symbols, nested namespace exports). Used by TS2741 cross-file disambiguation.
     */
    private fun getSymbolImportName(sym: Symbol?): String? {
        if (sym == null) return null
        for (br in binderResults) {
            if (br.locals.values.any { it === sym }) {
                val base = br.sourceFile.fileName
                    .substringAfterLast('/').substringAfterLast('\\')
                return base.substringBeforeLast('.')
            }
        }
        return null
    }

    /**
     * B73.1: Return the module basename (no path, no extension) if [expr] is an
     *  Identifier whose symbol is an import alias targeting another file via
     *  `import X = require("./Y")` or `import * as X from "./Y"`. Used to render
     *  `typeof import("X")` displays in TS2322 diagnostics for cross-file module
     *  references. Returns null when the alias doesn't resolve to a file-targeted
     *  module reference (e.g. namespace alias `import X = M.N`).
     */
    private fun tryGetModuleImportNameForExpr(expr: Expression): String? {
        if (expr !is Identifier) return null
        val name = expr.text
        val sym = currentFileLocals?.get(name) ?: globals[name] ?: return null
        if (!sym.flags.hasAny(SymbolFlags.Alias)) return null
        for (decl in sym.declarations) {
            when (decl) {
                is ImportEqualsDeclaration -> {
                    val ref = decl.moduleReference
                    if (ref is ExternalModuleReference) {
                        val specifier = (ref.expression as? StringLiteralNode)?.text ?: continue
                        val targetFile = resolveModuleSpecifier(specifier, decl) ?: continue
                        val base = targetFile.substringAfterLast('/').substringAfterLast('\\')
                        return base.substringBeforeLast('.')
                    }
                }
                is ImportDeclaration -> {
                    // `import * as X from "./Y"` — namespace import
                    val namedBindings = decl.importClause?.namedBindings
                    if (namedBindings is NamespaceImport && namedBindings.name.text == name) {
                        val specifier = (decl.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                        val targetFile = resolveModuleSpecifier(specifier, decl) ?: continue
                        val base = targetFile.substringAfterLast('/').substringAfterLast('\\')
                        return base.substringBeforeLast('.')
                    }
                }
                else -> {}
            }
        }
        return null
    }

    /**
     * B63.32: Collect property/method names declared in [sym]'s InterfaceDeclaration
     * in the source file matching [basename]. Bypasses `Type.Interface.properties`
     * which `mergeSymbolTable` pollutes with cross-file declarations of the same
     * name. Used by TS2367 "no overlap" detection for same-name interfaces in
     * different files.
     */
    private fun getOwnFileInterfacePropertyNames(sym: Symbol, basename: String): Set<String>? {
        val name = sym.name
        val br = binderResults.firstOrNull { r ->
            val b = r.sourceFile.fileName.substringAfterLast('/').substringAfterLast('\\')
                .substringBeforeLast('.')
            b == basename
        } ?: return null
        val result = mutableSetOf<String>()
        for (stmt in br.sourceFile.statements) {
            if (stmt is InterfaceDeclaration && stmt.name.text == name) {
                for (member in stmt.members) {
                    val propName: String? = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        else -> null
                    }
                    if (propName != null) result.add(propName)
                }
            }
        }
        return result
    }

    // -----------------------------------------------------------------------
    // TS2362/TS2363: Arithmetic operator type checking (Phase 4 item 14a)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // TS2700: "Rest types may only be created from object types."
    //
    // An object rest binding `var {...rest} = source` requires `source` to be a
    // valid spread source — an object/non-primitive/instantiable type, or a
    // union/intersection whose members are ALL valid. A union/intersection that
    // contains a non-object member such as `null`/`undefined` is invalid.
    //
    // FP-firewall: we only emit when the resolved source type is BOTH an invalid
    // spread source AND involves null/undefined (the shapes the corpus
    // exercises). This never fires on a primitive-only source (a false negative,
    // not a false positive) and never on a mis-resolved-to-`any`/error source.
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // TS2698: "Spread types may only be created from object types." — an object
    // SPREAD `{ ...x }` whose operand `x` resolves to a non-object type
    // (primitive / literal / enum / indexed-access-to-primitive / keyof). Sibling
    // of the TS2700 object-REST check above but for the spread-into-object-literal
    // direction. `spreadInvalidArgumentType`.
    //
    // FP-firewall: `isDefinitelyInvalidSpreadType` returns true ONLY for types that
    // are unambiguously non-spreadable (primitive intrinsics, literals, enums,
    // void/never, a union whose non-nullish members are invalid or which is
    // all-nullish, an intersection with an invalid member). any/unknown/error and
    // every object-like / typeparam type → false (suppress). So a mis-resolved or
    // generic operand is a false NEGATIVE, never a false positive. Nullish union
    // members are filtered before the check (`{a} | undefined` IS a valid spread).
    // -----------------------------------------------------------------------

    // (M0.4, round 624): the per-file driver (checkObjectSpreadInvalidTypes)
    // and the four recursion walkers (spread2698Stmts/Stmt/FuncLike/Expr) are
    // DELETED — the walk is spine-hosted (spineOsEnterNode/spineOsStatus); the
    // emission leaves below are anchor-called with the frame's `anns` map.

    private fun spread2698CheckOperand(el: SpreadAssignment, anns: Map<String, TypeNode>, source: String, fileName: String) {
        val operand = el.expression
        val annType: TypeNode? = (operand as? Identifier)?.let { anns[it.text] }
        // Enum-typed operand: an enum is never a valid spread source. Detect via the
        // annotation's TypeReference symbol (enum type resolution may not carry the
        // Enum flag reliably). This is unambiguously invalid → FP-safe.
        if (annType is TypeReference) {
            val nm = (annType.typeName as? Identifier)?.text
            if (nm != null) {
                val s = currentFileLocals?.get(nm) ?: globals[nm]
                if (s != null && s.flags.hasAny(SymbolFlags.Enum)) { spread2698Emit(el, source, fileName); return }
            }
        }
        val t = if (annType != null) getTypeFromTypeNode(annType) else getTypeOfExpression(operand)
        if (isDefinitelyInvalidSpreadType(t)) spread2698Emit(el, source, fileName)
    }

    private fun spread2698Emit(el: SpreadAssignment, source: String, fileName: String) {
        val start = el.pos
        val length = expressionTrueEnd(el.expression) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Spread types may only be created from object types.",
            category = DiagnosticCategory.Error,
            code = 2698,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** Object-REST TS2700: resolve a `var {...r} = init` source type (preferring the
     *  init-identifier's annotation in the active type-param scope, with the enum
     *  fallback) and emit at the rest element name when it is definitely non-object.
     *  Reuses the FP-safe [isDefinitelyInvalidSpreadType] (mis-resolution → FN, never FP). */
    private fun rest2700Check(rest: BindingElement, init: Expression, anns: Map<String, TypeNode>, source: String, fileName: String) {
        val annType: TypeNode? = (init as? Identifier)?.let { anns[it.text] }
        if (annType is TypeReference) {
            val nm = (annType.typeName as? Identifier)?.text
            if (nm != null) {
                val s = currentFileLocals?.get(nm) ?: globals[nm]
                if (s != null && s.flags.hasAny(SymbolFlags.Enum)) { rest2700Emit(rest, source, fileName); return }
            }
        }
        val t = if (annType != null) getTypeFromTypeNode(annType) else getTypeOfExpression(init)
        if (isDefinitelyInvalidSpreadType(t)) rest2700Emit(rest, source, fileName)
    }

    private fun rest2700Emit(rest: BindingElement, source: String, fileName: String) {
        val name = rest.name
        val start = name.pos
        val length = expressionTrueEnd(name) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Rest types may only be created from object types.",
            category = DiagnosticCategory.Error,
            code = 2700,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private class NsImportInfo(
        val exportedValues: Set<String>,
        val allTopLevelNames: Set<String>,
        val displayBase: String,
    )

    /**
     * B245: namespace-import bindings are immutable — `import * as ns from './m'`
     * makes every member of `ns` a read-only view of the module's exports. Any
     * WRITE position targeting `ns.x` / `ns['x']` (assignment incl. compound,
     * `++`/`--`, for-in/for-of target) fires:
     *  - TS2540 "Cannot assign to 'x' because it is a read-only property." when
     *    `x` IS an exported value of the resolved module;
     *  - TS2339 "Property 'x' does not exist on type 'typeof import("<base>")'."
     *    for a DOT access whose name appears NOWHERE in the module's top-level
     *    declarations. (An element access with an unknown literal key is the
     *    legal implicit-any shape under default options — no error.)
     *
     * FP firewall: the target must be a resolvable .ts/.tsx FILE module with no
     * `export =` and no `export * from` (re-exports make the export set open);
     * a shadow set threaded through function-likes/blocks suppresses re-bound
     * alias names; READ positions are untouched.
     */
    private fun checkNamespaceImportMemberWrites() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val sf = result.sourceFile
            val aliases = mutableMapOf<String, NsImportInfo>()
            for (stmt in sf.statements) {
                val imp = stmt as? ImportDeclaration ?: continue
                val clause = imp.importClause ?: continue
                if (clause.isTypeOnly) continue
                val nsImport = clause.namedBindings as? NamespaceImport ?: continue
                val spec = (imp.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                val resolved = resolveModuleSpecifier(spec, imp) ?: continue
                if (isDtsFile(resolved) || !(resolved.endsWith(".ts") || resolved.endsWith(".tsx"))) continue
                val target = fileResults[resolved]?.sourceFile ?: continue
                if (target.statements.any { it is ExportAssignment && it.isExportEquals }) continue
                if (target.statements.any { it is ExportDeclaration && it.exportClause == null }) continue
                val exportedValues = mutableSetOf<String>()
                val allNames = mutableSetOf<String>()
                for (ts in target.statements) {
                    when (ts) {
                        is VariableStatement -> {
                            val names = mutableSetOf<String>()
                            for (d in ts.declarationList.declarations) collectBindingNames(d.name, names)
                            allNames += names
                            if (ModifierFlag.Export in ts.modifiers) exportedValues += names
                        }
                        is FunctionDeclaration -> ts.name?.text?.let {
                            allNames += it; if (ModifierFlag.Export in ts.modifiers) exportedValues += it
                        }
                        is ClassDeclaration -> ts.name?.text?.let {
                            allNames += it; if (ModifierFlag.Export in ts.modifiers) exportedValues += it
                        }
                        is EnumDeclaration -> ts.name.text.let {
                            allNames += it; if (ModifierFlag.Export in ts.modifiers) exportedValues += it
                        }
                        is ModuleDeclaration -> (ts.name as? Identifier)?.text?.let {
                            allNames += it; if (ModifierFlag.Export in ts.modifiers) exportedValues += it
                        }
                        is InterfaceDeclaration -> allNames += ts.name.text
                        is TypeAliasDeclaration -> allNames += ts.name.text
                        is ImportDeclaration -> {
                            ts.importClause?.name?.text?.let { allNames += it }
                            when (val nb = ts.importClause?.namedBindings) {
                                is NamespaceImport -> allNames += nb.name.text
                                is NamedImports -> for (el in nb.elements) allNames += el.name.text
                                else -> {}
                            }
                        }
                        is ImportEqualsDeclaration -> allNames += ts.name.text
                        is ExportDeclaration -> {
                            val ec = ts.exportClause
                            if (ec is NamedExports) for (el in ec.elements) {
                                allNames += el.name.text
                                if (!ts.isTypeOnly && !el.isTypeOnly) exportedValues += el.name.text
                            }
                        }
                        else -> {}
                    }
                }
                aliases[nsImport.name.text] = NsImportInfo(exportedValues, allNames, moduleFileBaseNoExt(resolved))
            }
            if (aliases.isEmpty()) continue
            val source = sf.text
            nsWriteStmts(sf.statements, source, fileName, aliases, emptySet())
        }
    }

    /** B245: hoisted local binding names declared directly in a statement list. */
    private fun nsWriteLocalNames(stmts: List<Statement>, into: MutableSet<String>) {
        for (s in stmts) when (s) {
            is VariableStatement -> for (d in s.declarationList.declarations) collectBindingNames(d.name, into)
            is FunctionDeclaration -> s.name?.let { into += it.text }
            is ClassDeclaration -> s.name?.let { into += it.text }
            is EnumDeclaration -> into += s.name.text
            is ModuleDeclaration -> (s.name as? Identifier)?.let { into += it.text }
            else -> {}
        }
    }

    private fun nsWriteStmts(
        stmts: List<Statement>, source: String, fileName: String,
        aliases: Map<String, NsImportInfo>, shadowed: Set<String>
    ) {
        val inner = shadowed.toMutableSet()
        nsWriteLocalNames(stmts, inner)
        if (aliases.keys.all { it in inner }) return
        for (s in stmts) nsWriteStmt(s, source, fileName, aliases, inner)
    }

    private fun nsWriteFuncLike(
        params: List<Parameter>, bodyNode: Node?, source: String, fileName: String,
        aliases: Map<String, NsImportInfo>, shadowed: Set<String>
    ) {
        val inner = shadowed.toMutableSet()
        for (p in params) collectBindingNames(p.name, inner)
        for (p in params) p.initializer?.let { nsWriteExpr(it, source, fileName, aliases, inner) }
        when (bodyNode) {
            is Block -> nsWriteStmts(bodyNode.statements, source, fileName, aliases, inner)
            is Expression -> nsWriteExpr(bodyNode, source, fileName, aliases, inner)
            else -> {}
        }
    }

    private fun nsWriteStmt(
        stmt: Statement, source: String, fileName: String,
        aliases: Map<String, NsImportInfo>, shadowed: Set<String>
    ) {
        when (stmt) {
            is ExpressionStatement -> nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
            }
            is ReturnStatement -> stmt.expression?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
            is ThrowStatement -> stmt.expression?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
            is Block -> nsWriteStmts(stmt.statements, source, fileName, aliases, shadowed)
            is IfStatement -> {
                nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
                nsWriteStmt(stmt.thenStatement, source, fileName, aliases, shadowed)
                stmt.elseStatement?.let { nsWriteStmt(it, source, fileName, aliases, shadowed) }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> for (d in init.declarations) {
                        d.initializer?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
                    }
                    is Expression -> nsWriteExpr(init, source, fileName, aliases, shadowed)
                    else -> {}
                }
                stmt.condition?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
                stmt.incrementor?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
                nsWriteStmt(stmt.statement, source, fileName, aliases, shadowed)
            }
            is ForInStatement -> {
                (stmt.initializer as? Expression)?.let { nsCheckWriteTarget(it, source, fileName, aliases, shadowed) }
                nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
                nsWriteStmt(stmt.statement, source, fileName, aliases, shadowed)
            }
            is ForOfStatement -> {
                (stmt.initializer as? Expression)?.let { nsCheckWriteTarget(it, source, fileName, aliases, shadowed) }
                nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
                nsWriteStmt(stmt.statement, source, fileName, aliases, shadowed)
            }
            is WhileStatement -> {
                nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
                nsWriteStmt(stmt.statement, source, fileName, aliases, shadowed)
            }
            is DoStatement -> {
                nsWriteStmt(stmt.statement, source, fileName, aliases, shadowed)
                nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
            }
            is SwitchStatement -> {
                nsWriteExpr(stmt.expression, source, fileName, aliases, shadowed)
                for (clause in stmt.caseBlock) when (clause) {
                    is CaseClause -> {
                        nsWriteExpr(clause.expression, source, fileName, aliases, shadowed)
                        nsWriteStmts(clause.statements, source, fileName, aliases, shadowed)
                    }
                    is DefaultClause -> nsWriteStmts(clause.statements, source, fileName, aliases, shadowed)
                    else -> {}
                }
            }
            is TryStatement -> {
                nsWriteStmt(stmt.tryBlock, source, fileName, aliases, shadowed)
                stmt.catchClause?.let { cc ->
                    val inner = shadowed.toMutableSet()
                    cc.variableDeclaration?.let { collectBindingNames(it.name, inner) }
                    nsWriteStmts(cc.block.statements, source, fileName, aliases, inner)
                }
                stmt.finallyBlock?.let { nsWriteStmt(it, source, fileName, aliases, shadowed) }
            }
            is LabeledStatement -> nsWriteStmt(stmt.statement, source, fileName, aliases, shadowed)
            is FunctionDeclaration -> nsWriteFuncLike(stmt.parameters, stmt.body, source, fileName, aliases, shadowed)
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> nsWriteFuncLike(m.parameters, m.body, source, fileName, aliases, shadowed)
                is Constructor -> nsWriteFuncLike(m.parameters, m.body, source, fileName, aliases, shadowed)
                is GetAccessor -> nsWriteFuncLike(m.parameters, m.body, source, fileName, aliases, shadowed)
                is SetAccessor -> nsWriteFuncLike(m.parameters, m.body, source, fileName, aliases, shadowed)
                is PropertyDeclaration -> m.initializer?.let { nsWriteExpr(it, source, fileName, aliases, shadowed) }
                else -> {}
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                nsWriteStmts(it.statements, source, fileName, aliases, shadowed)
            }
            else -> {}
        }
    }

    private fun nsWriteExpr(
        expr: Expression, source: String, fileName: String,
        aliases: Map<String, NsImportInfo>, shadowed: Set<String>
    ) {
        when (expr) {
            is BinaryExpression -> {
                // Worklist — deep a+b+c / a=b=c chains StackOverflow naive recursion.
                val work = ArrayDeque<Expression>()
                work.add(expr)
                while (work.isNotEmpty()) {
                    val e = work.removeLast()
                    if (e is BinaryExpression) {
                        if (isAssignmentOperator(e.operator)) {
                            nsCheckWriteTarget(e.left, source, fileName, aliases, shadowed)
                        }
                        work.add(e.left); work.add(e.right)
                    } else {
                        nsWriteExpr(e, source, fileName, aliases, shadowed)
                    }
                }
            }
            is PrefixUnaryExpression -> {
                if (expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus) {
                    nsCheckWriteTarget(expr.operand, source, fileName, aliases, shadowed)
                }
                nsWriteExpr(expr.operand, source, fileName, aliases, shadowed)
            }
            is PostfixUnaryExpression -> {
                if (expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus) {
                    nsCheckWriteTarget(expr.operand, source, fileName, aliases, shadowed)
                }
                nsWriteExpr(expr.operand, source, fileName, aliases, shadowed)
            }
            is ParenthesizedExpression -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is CallExpression -> {
                nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
                for (a in expr.arguments) nsWriteExpr(a, source, fileName, aliases, shadowed)
            }
            is NewExpression -> {
                nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
                expr.arguments?.forEach { nsWriteExpr(it, source, fileName, aliases, shadowed) }
            }
            is ConditionalExpression -> {
                nsWriteExpr(expr.condition, source, fileName, aliases, shadowed)
                nsWriteExpr(expr.whenTrue, source, fileName, aliases, shadowed)
                nsWriteExpr(expr.whenFalse, source, fileName, aliases, shadowed)
            }
            is ObjectLiteralExpression -> for (el in expr.properties) when (el) {
                is PropertyAssignment -> nsWriteExpr(el.initializer, source, fileName, aliases, shadowed)
                is SpreadAssignment -> nsWriteExpr(el.expression, source, fileName, aliases, shadowed)
                is ShorthandPropertyAssignment -> el.objectAssignmentInitializer?.let {
                    nsWriteExpr(it, source, fileName, aliases, shadowed)
                }
                is MethodDeclaration -> nsWriteFuncLike(el.parameters, el.body, source, fileName, aliases, shadowed)
                is GetAccessor -> nsWriteFuncLike(el.parameters, el.body, source, fileName, aliases, shadowed)
                is SetAccessor -> nsWriteFuncLike(el.parameters, el.body, source, fileName, aliases, shadowed)
                else -> {}
            }
            is ArrayLiteralExpression -> for (e in expr.elements) nsWriteExpr(e, source, fileName, aliases, shadowed)
            is PropertyAccessExpression -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is ElementAccessExpression -> {
                nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
                nsWriteExpr(expr.argumentExpression, source, fileName, aliases, shadowed)
            }
            is SpreadElement -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is AsExpression -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is TypeAssertionExpression -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is NonNullExpression -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is AwaitExpression -> nsWriteExpr(expr.expression, source, fileName, aliases, shadowed)
            is FunctionExpression -> nsWriteFuncLike(expr.parameters, expr.body, source, fileName, aliases, shadowed)
            is ArrowFunction -> nsWriteFuncLike(expr.parameters, expr.body, source, fileName, aliases, shadowed)
            else -> {}
        }
    }

    private fun nsCheckWriteTarget(
        targetIn: Expression, source: String, fileName: String,
        aliases: Map<String, NsImportInfo>, shadowed: Set<String>
    ) {
        var t = targetIn
        while (t is ParenthesizedExpression) t = t.expression
        val recvName: String
        val propName: String
        val spanStart: Int
        val spanLen: Int
        val isDot: Boolean
        when (t) {
            is PropertyAccessExpression -> {
                recvName = (t.expression as? Identifier)?.text ?: return
                propName = t.name.text
                spanStart = t.name.pos
                spanLen = t.name.text.length
                isDot = true
            }
            is ElementAccessExpression -> {
                recvName = (t.expression as? Identifier)?.text ?: return
                val k = t.argumentExpression as? StringLiteralNode ?: return
                propName = k.text
                spanStart = k.pos
                spanLen = (k.rawText?.length ?: k.text.length) + 2
                isDot = false
            }
            else -> return
        }
        if (recvName in shadowed) return
        val info = aliases[recvName] ?: return
        if (propName in info.exportedValues) {
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "Cannot assign to '$propName' because it is a read-only property.",
                category = DiagnosticCategory.Error,
                code = 2540,
                fileName = fileName,
                line = line,
                character = character,
                start = spanStart,
                length = spanLen,
            ))
        } else if (isDot && propName !in info.allTopLevelNames) {
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type 'typeof import(\"${info.displayBase}\")'.",
                category = DiagnosticCategory.Error,
                code = 2339,
                fileName = fileName,
                line = line,
                character = character,
                start = spanStart,
                length = spanLen,
            ))
        }
    }

    /** B156: a type DEFINITELY cannot be an object-spread source (TS2698). FP-safe —
     *  returns true ONLY for unambiguously non-spreadable types; any/unknown/error and
     *  every object-like / typeparam type → false (suppress, possible FN never FP). */
    private fun isDefinitelyInvalidSpreadType(type: Type): Boolean = when {
        type === anyType || type === unknownType || type === errorType -> false
        type is Type.Object || type is Type.Interface || type is Type.Reference || type is Type.TypeParam -> false
        type is Type.Union -> {
            val nonNullish = type.types.filter {
                it !== nullType && it !== undefinedType && !it.flags.hasAny(TypeFlags.VoidLike)
            }
            if (nonNullish.isEmpty()) true else nonNullish.any { isDefinitelyInvalidSpreadType(it) }
        }
        type is Type.Intersection -> type.types.any { isDefinitelyInvalidSpreadType(it) }
        type === nullType || type === undefinedType || type === neverType -> true
        type.flags.hasAny(
            TypeFlags.StringLike or TypeFlags.NumberLike or TypeFlags.BigIntLike or
                TypeFlags.BooleanLike or TypeFlags.EnumLike or TypeFlags.ESSymbol or TypeFlags.Void
        ) -> true
        else -> false
    }

    // -----------------------------------------------------------------------
    // TS6807: "This operation can be simplified. This shift is identical to
    // `LHS <op> M`." — a bit-shift (`<<`/`>>`/`>>>` or `<<=`/`>>=`/`>>>=`) whose
    // RIGHT operand is a numeric-literal constant `n` (optionally negated) whose
    // value is outside [-31, 31] (i.e. `n % 32 != n`). JS shift counts are taken
    // mod 32, so the operation is identical to `LHS <op> (n % 32)`.
    //
    // Purely SYNTACTIC + FP-safe: gated entirely on `@captureSuggestions` (the ONLY
    // corpus test exercising it is `overshifts`), so the walker never runs — and
    // never emits — for any other test. Category is Error inside an enum-member
    // initializer (const-context), Suggestion elsewhere; both match TypeScript.
    // -----------------------------------------------------------------------

    // NOTE: a function, NOT a `private val` map — a field declared after `init {}`
    // is null during the check pipeline (Kotlin init-order gotcha; bit B135).
    private fun shiftOpText(op: SyntaxKind): String? = when (op) {
        SyntaxKind.LessThanLessThan -> "<<"
        SyntaxKind.GreaterThanGreaterThan -> ">>"
        SyntaxKind.GreaterThanGreaterThanGreaterThan -> ">>>"
        SyntaxKind.LessThanLessThanEquals -> "<<="
        SyntaxKind.GreaterThanGreaterThanEquals -> ">>="
        SyntaxKind.GreaterThanGreaterThanGreaterThanEquals -> ">>>="
        else -> null
    }

    private fun checkShiftOverflow() {
        if (!options.captureSuggestions) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) shiftWalkStmt(stmt, source, fileName, false)
        }
    }

    private fun shiftWalkStmt(stmt: Statement, source: String, fileName: String, inEnum: Boolean) {
        when (stmt) {
            is ExpressionStatement -> shiftWalkExpr(stmt.expression, source, fileName, inEnum)
            is VariableStatement -> for (d in stmt.declarationList.declarations)
                d.initializer?.let { shiftWalkExpr(it, source, fileName, inEnum) }
            is ReturnStatement -> stmt.expression?.let { shiftWalkExpr(it, source, fileName, inEnum) }
            is ThrowStatement -> stmt.expression?.let { shiftWalkExpr(it, source, fileName, inEnum) }
            is EnumDeclaration -> for (m in stmt.members)
                m.initializer?.let { shiftWalkExpr(it, source, fileName, true) }
            is Block -> for (s in stmt.statements) shiftWalkStmt(s, source, fileName, inEnum)
            is IfStatement -> {
                shiftWalkExpr(stmt.expression, source, fileName, inEnum)
                shiftWalkStmt(stmt.thenStatement, source, fileName, inEnum)
                stmt.elseStatement?.let { shiftWalkStmt(it, source, fileName, inEnum) }
            }
            is ForStatement -> shiftWalkStmt(stmt.statement, source, fileName, inEnum)
            is ForInStatement -> shiftWalkStmt(stmt.statement, source, fileName, inEnum)
            is ForOfStatement -> shiftWalkStmt(stmt.statement, source, fileName, inEnum)
            is WhileStatement -> shiftWalkStmt(stmt.statement, source, fileName, inEnum)
            is DoStatement -> shiftWalkStmt(stmt.statement, source, fileName, inEnum)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                for (s in it.statements) shiftWalkStmt(s, source, fileName, inEnum)
            }
            is LabeledStatement -> shiftWalkStmt(stmt.statement, source, fileName, inEnum)
            else -> {}
        }
    }

    private fun shiftWalkExpr(expr: Expression, source: String, fileName: String, inEnum: Boolean) {
        when (expr) {
            is BinaryExpression -> {
                shiftOpText(expr.operator)?.let { opText ->
                    val n = shiftLiteralValue(expr.right)
                    if (n != null) {
                        val m = n % 32
                        if (m != n) emitShiftOverflow(expr, opText, m, source, fileName, inEnum)
                    }
                }
                shiftWalkExpr(expr.left, source, fileName, inEnum)
                shiftWalkExpr(expr.right, source, fileName, inEnum)
            }
            is ParenthesizedExpression -> shiftWalkExpr(expr.expression, source, fileName, inEnum)
            is PrefixUnaryExpression -> shiftWalkExpr(expr.operand, source, fileName, inEnum)
            is PostfixUnaryExpression -> shiftWalkExpr(expr.operand, source, fileName, inEnum)
            is CallExpression -> { shiftWalkExpr(expr.expression, source, fileName, inEnum); for (a in expr.arguments) shiftWalkExpr(a, source, fileName, inEnum) }
            is NewExpression -> { shiftWalkExpr(expr.expression, source, fileName, inEnum); expr.arguments?.forEach { shiftWalkExpr(it, source, fileName, inEnum) } }
            is PropertyAccessExpression -> shiftWalkExpr(expr.expression, source, fileName, inEnum)
            is ElementAccessExpression -> { shiftWalkExpr(expr.expression, source, fileName, inEnum); shiftWalkExpr(expr.argumentExpression, source, fileName, inEnum) }
            is ConditionalExpression -> { shiftWalkExpr(expr.condition, source, fileName, inEnum); shiftWalkExpr(expr.whenTrue, source, fileName, inEnum); shiftWalkExpr(expr.whenFalse, source, fileName, inEnum) }
            is VoidExpression -> shiftWalkExpr(expr.expression, source, fileName, inEnum)
            is AwaitExpression -> shiftWalkExpr(expr.expression, source, fileName, inEnum)
            else -> {}
        }
    }

    /** The integer value of a shift's RIGHT operand if it is a numeric literal
     *  (optionally negated by a leading unary `-`); null otherwise (skip). */
    private fun shiftLiteralValue(expr: Expression): Long? = when (expr) {
        is NumericLiteralNode -> parseNumericLiteralLong(expr.text)
        is PrefixUnaryExpression -> when (expr.operator) {
            SyntaxKind.Minus -> (expr.operand as? NumericLiteralNode)?.let { parseNumericLiteralLong(it.text)?.let { v -> -v } }
            SyntaxKind.Plus -> (expr.operand as? NumericLiteralNode)?.let { parseNumericLiteralLong(it.text) }
            else -> null
        }
        is ParenthesizedExpression -> shiftLiteralValue(expr.expression)
        else -> null
    }

    private fun parseNumericLiteralLong(raw: String): Long? {
        val t = raw.replace("_", "")
        return when {
            t.startsWith("0x") || t.startsWith("0X") -> t.substring(2).toLongOrNull(16)
            t.startsWith("0b") || t.startsWith("0B") -> t.substring(2).toLongOrNull(2)
            t.startsWith("0o") || t.startsWith("0O") -> t.substring(2).toLongOrNull(8)
            t.contains('.') || t.contains('e') || t.contains('E') || t.endsWith("n") -> null // float/bigint → skip
            else -> t.toLongOrNull()
        }
    }

    private fun emitShiftOverflow(expr: BinaryExpression, opText: String, m: Long, source: String, fileName: String, inEnum: Boolean) {
        val start = expr.pos
        val end = expressionTrueEnd(expr)
        if (start < 0 || end <= start) return
        val lhsEnd = expressionTrueEnd(expr.left)
        val lhsText = if (expr.left.pos in 0..<lhsEnd) source.substring(expr.left.pos, lhsEnd) else ""
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This operation can be simplified. This shift is identical to `$lhsText $opText $m`.",
            category = if (inEnum) DiagnosticCategory.Error else DiagnosticCategory.Suggestion,
            code = 6807,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = end - start,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2356: "An arithmetic operand must be of type 'any', 'number', 'bigint'
    // or an enum type." — for a `++`/`--` whose operand is typed as an
    // UNCONSTRAINED generic type parameter (e.g. `class C<T> { a!: T; foo() {
    // this.a++ } }`). An unconstrained `T` can be instantiated with a
    // non-arithmetic type, so the increment is never sound.
    //
    // AST-level + FP-firewalled: we only flag an operand that is `this.X`
    // (where X is a class property annotated as a bare unconstrained type
    // parameter) or a bare local identifier annotated as one. The annotation
    // must be a bare `TypeReference` to a type-parameter NAME with no type args,
    // and the type parameter must be unconstrained (constraint == null) — a
    // numeric-constrained `T extends number` is legitimately incrementable
    // (false negative, never a false positive). Constrained-non-numeric type
    // params (`T extends string`) are a deliberate FN to keep zero FP.
    // -----------------------------------------------------------------------

    // (M0.4, round 654): the per-file pass driver + the recursion walkers
    // (checkIncDecTypeParamOperands / incDecHandleBody / incDecScanStatements /
    // incDecScanStatement / incDecCheckExpr) are DELETED — the spine dispatches
    // the emission (spineIdcEnterNode) with a pull-based per-anchor context
    // rebuild. The set-building leaves (unconstrainedTpNames /
    // isBareTypeParamRef / collectTpLocals) and the emission leaf
    // (emitTS2356IfTypeParamOperand) below are retained as its leaves.

    /** B265: `return class X extends superClass { ... }` inside a generic function where
     *  `superClass` is a parameter typed as a bare type-param `TFunction`.
     *  - Unconstrained TP: its apparent type has no construct signatures, so the heritage
     *    expression gets TS2507 + related TS2735 at the TP declaration, and (when the
     *    function's return annotation is the same bare TP) the return gets TS2322 with the
     *    "could be instantiated" chain — the base resolution errored, so the class static
     *    type is plain `typeof X`, never assignable to the bare TP.
     *  - TP constrained to a ConstructorType: the class static type is `(anon) & TFunction`
     *    whose MERGED construct signature must be a mixin constructor (single `...rest: any[]`).
     *    Mixin-shaped constituents are discarded and their returns mixed into the others, so
     *    the merged sig is mixin-shaped iff BOTH the constraint's sig and the class's own
     *    ctor (when present) are `(...args: any[])` — else TS2545 at the class name. */
    private fun checkMixinClassExtendsTypeParam() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            mixinTpScanStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun mixinTpScanStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) when (stmt) {
            is FunctionDeclaration -> {
                val body = stmt.body ?: continue
                val tps = stmt.typeParameters
                if (!tps.isNullOrEmpty()) {
                    val tpMap = tps.associateBy { it.name.text }
                    val paramTp = mutableMapOf<String, String>()
                    for (p in stmt.parameters) {
                        val n = (p.name as? Identifier)?.text ?: continue
                        val tr = p.type as? TypeReference ?: continue
                        if (!tr.typeArguments.isNullOrEmpty()) continue
                        val tn = (tr.typeName as? Identifier)?.text ?: continue
                        if (tn in tpMap) paramTp[n] = tn
                    }
                    if (paramTp.isNotEmpty()) {
                        mixinTpScanBody(body.statements, source, fileName, tpMap, paramTp, stmt.type)
                    }
                }
                mixinTpScanStatements(body.statements, source, fileName)
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { mixinTpScanStatements(it.statements, source, fileName) }
            is Block -> mixinTpScanStatements(stmt.statements, source, fileName)
            else -> {}
        }
    }

    private fun mixinTpScanBody(
        stmts: List<Statement>, source: String, fileName: String,
        tpMap: Map<String, TypeParameter>, paramTp: Map<String, String>, returnAnnotation: TypeNode?,
    ) {
        for (stmt in stmts) when (stmt) {
            is ReturnStatement -> {
                val cls = stmt.expression as? ClassExpression ?: continue
                mixinTpCheckClass(cls, stmt, source, fileName, tpMap, paramTp, returnAnnotation)
            }
            is Block -> mixinTpScanBody(stmt.statements, source, fileName, tpMap, paramTp, returnAnnotation)
            is IfStatement -> {
                mixinTpScanBody(listOf(stmt.thenStatement), source, fileName, tpMap, paramTp, returnAnnotation)
                stmt.elseStatement?.let { mixinTpScanBody(listOf(it), source, fileName, tpMap, paramTp, returnAnnotation) }
            }
            else -> {}
        }
    }

    private fun mixinTpCheckClass(
        cls: ClassExpression, ret: ReturnStatement, source: String, fileName: String,
        tpMap: Map<String, TypeParameter>, paramTp: Map<String, String>, returnAnnotation: TypeNode?,
    ) {
        val extendsClause = cls.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword } ?: return
        val base = extendsClause.types.singleOrNull() ?: return
        if (!base.typeArguments.isNullOrEmpty()) return
        val baseIdent = base.expression as? Identifier ?: return
        val tpName = paramTp[baseIdent.text] ?: return
        val tp = tpMap[tpName] ?: return
        val constraint = tp.constraint
        if (constraint == null) {
            val (line, ch) = getLineAndCharacterOfPosition(source, baseIdent.pos)
            val (dLine, dCh) = getLineAndCharacterOfPosition(source, tp.name.pos)
            diagnostics.add(Diagnostic(
                message = "Type '$tpName' is not a constructor function type.",
                category = DiagnosticCategory.Error, code = 2507,
                fileName = fileName, line = line, character = ch,
                start = baseIdent.pos, length = baseIdent.text.length,
                relatedInformation = listOf(Diagnostic(
                    message = "Did you mean for '$tpName' to be constrained to type 'new (...args: any[]) => unknown'?",
                    category = DiagnosticCategory.Message, code = 2735,
                    fileName = fileName, line = dLine, character = dCh,
                    start = tp.name.pos, length = tp.name.text.length,
                )),
            ))
            if (isBareTypeParamRef(returnAnnotation, setOf(tpName))) {
                val clsName = cls.name?.text ?: "(Anonymous class)"
                val (rLine, rCh) = getLineAndCharacterOfPosition(source, ret.pos)
                diagnostics.add(Diagnostic(
                    message = "Type 'typeof $clsName' is not assignable to type '$tpName'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = rLine, character = rCh,
                    start = ret.pos, length = 6,
                    messageChain = listOf("  '$tpName' could be instantiated with an arbitrary type which could be unrelated to 'typeof $clsName'."),
                ))
            }
            return
        }
        val ctorType = constraint as? ConstructorType ?: return
        if (!ctorType.typeParameters.isNullOrEmpty()) return
        val constraintMixin = mixinParamListIsAnyRest(ctorType.parameters)
        val ctors = cls.members.filterIsInstance<Constructor>()
        val sigCtors = ctors.filter { it.body == null }.ifEmpty { ctors }
        if (sigCtors.size > 1) return // overloaded constructor — conservative skip
        val ownMixin = if (sigCtors.isEmpty()) constraintMixin else mixinParamListIsAnyRest(sigCtors[0].parameters)
        if (constraintMixin && ownMixin) return
        val pos = cls.name?.pos ?: cls.pos
        val len = cls.name?.text?.length ?: 5
        val (line, ch) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "A mixin class must have a constructor with a single rest parameter of type 'any[]'.",
            category = DiagnosticCategory.Error, code = 2545,
            fileName = fileName, line = line, character = ch,
            start = pos, length = len,
        ))
    }

    /** Is this parameter list a single rest parameter of type `any[]` (the mixin-constructor shape)?
     *  An un-annotated rest parameter is implicitly `any[]`. */
    private fun mixinParamListIsAnyRest(params: List<Parameter>): Boolean {
        val p = params.singleOrNull() ?: return false
        if (!p.dotDotDotToken) return false
        val t = p.type ?: return true
        if (t is ArrayType) {
            val el = t.elementType
            return el is KeywordTypeNode && el.kind == SyntaxKind.AnyKeyword
        }
        if (t is TypeReference) {
            val arg = t.typeArguments?.singleOrNull()
            return (t.typeName as? Identifier)?.text == "Array" &&
                arg is KeywordTypeNode && arg.kind == SyntaxKind.AnyKeyword
        }
        return false
    }

    private fun unconstrainedTpNames(tps: List<TypeParameter>?): Set<String> =
        tps?.filter { it.constraint == null }?.map { it.name.text }?.toSet() ?: emptySet()

    private fun isBareTypeParamRef(typeNode: TypeNode?, tparams: Set<String>): Boolean {
        val tr = typeNode as? TypeReference ?: return false
        if (!tr.typeArguments.isNullOrEmpty()) return false
        val name = (tr.typeName as? Identifier)?.text ?: return false
        return name in tparams
    }

    /** Collect names of local vars (incl. for-init) annotated as a bare
     *  unconstrained type-param. Does NOT descend into nested function/class
     *  bodies (their locals belong to their own scope). */
    private fun collectTpLocals(stmts: List<Statement>, tparams: Set<String>, into: MutableSet<String>) {
        for (stmt in stmts) collectTpLocalsStmt(stmt, tparams, into)
    }

    private fun collectTpLocalsStmt(stmt: Statement, tparams: Set<String>, into: MutableSet<String>) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text
                if (n != null && isBareTypeParamRef(d.type, tparams)) into.add(n)
            }
            is Block -> collectTpLocals(stmt.statements, tparams, into)
            is IfStatement -> {
                collectTpLocalsStmt(stmt.thenStatement, tparams, into)
                stmt.elseStatement?.let { collectTpLocalsStmt(it, tparams, into) }
            }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                    val n = (d.name as? Identifier)?.text
                    if (n != null && isBareTypeParamRef(d.type, tparams)) into.add(n)
                }
                collectTpLocalsStmt(stmt.statement, tparams, into)
            }
            is ForInStatement -> collectTpLocalsStmt(stmt.statement, tparams, into)
            is ForOfStatement -> collectTpLocalsStmt(stmt.statement, tparams, into)
            is WhileStatement -> collectTpLocalsStmt(stmt.statement, tparams, into)
            is DoStatement -> collectTpLocalsStmt(stmt.statement, tparams, into)
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val cs = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                collectTpLocals(cs, tparams, into)
            }
            is TryStatement -> {
                collectTpLocals(stmt.tryBlock.statements, tparams, into)
                stmt.catchClause?.let { collectTpLocals(it.block.statements, tparams, into) }
                stmt.finallyBlock?.let { collectTpLocals(it.statements, tparams, into) }
            }
            is LabeledStatement -> collectTpLocalsStmt(stmt.statement, tparams, into)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // (M0.4) round 654: checkIncDecTypeParamOperands (TS2356) ON THE SPINE.
    // The per-file driver + the recursion walkers (incDecHandleBody /
    // incDecScanStatements / incDecScanStatement / incDecCheckExpr) are
    // deleted; the anchors are Prefix/Postfix `++`/`--` enters
    // ([spineIdcEnterNode]) and the downward (tparams, tpProps, tpLocals)
    // triple rebuilds pull-based per anchor ([spineIdcCtxAt]/[spineIdcCtxFor]),
    // the round-637 gx shape with SETS instead of maps. The set-building
    // leaves (unconstrainedTpNames / isBareTypeParamRef / collectTpLocals) and
    // the emission leaf (emitTS2356IfTypeParamOperand) are retained unchanged.
    // -----------------------------------------------------------------------

    /** Per-file setup: the legacy dts + `.js`/`.jsx` skip. */
    private fun spineIdcSetup(result: BinderResult) {
        spineIdcActive = !spineIsDts &&
            !spineFileName.endsWith(".js") && !spineFileName.endsWith(".jsx")
        spineIdcCtxMemo.clear()
        spineIdcReachMemo = if (!spineIdcActive) ByteArray(0) else {
            val n = result.sourceFile.nodeCount
            if (n > 0) ByteArray(n) else ByteArray(0)
        }
    }

    private fun spineIdcTeardown() {
        spineIdcActive = false
        spineIdcCtxMemo.clear()
        spineIdcReachMemo = ByteArray(0)
    }

    /** ENTER dispatch: the legacy incDecCheckExpr Prefix/Postfix arms — a
     *  `++`/`--` whose paren-unwrapped operand is a bare Identifier or a
     *  `this.<name>` access (the cheap shape gate runs BEFORE the reach climb;
     *  the name-set membership + span computation stay inside the retained
     *  emission leaf, which re-unwraps the parentheses itself). */
    private fun spineIdcEnterNode(node: Node) {
        val operand: Expression = when ((node as NodeBase).kindId) {
            NodeKind.PREFIX_UNARY_EXPRESSION -> {
                node as PrefixUnaryExpression
                if (node.operator != SyntaxKind.PlusPlus &&
                    node.operator != SyntaxKind.MinusMinus) return
                node.operand
            }
            NodeKind.POSTFIX_UNARY_EXPRESSION -> {
                node as PostfixUnaryExpression
                if (node.operator != SyntaxKind.PlusPlus &&
                    node.operator != SyntaxKind.MinusMinus) return
                node.operand
            }
            else -> return
        }
        var core: Expression = operand
        while (core is ParenthesizedExpression) core = core.expression
        val shaped = when (core) {
            is Identifier -> true
            is PropertyAccessExpression -> (core.expression as? Identifier)?.text == "this"
            else -> false
        }
        if (!shaped) return
        if (spineIdcStatus(node) != IDC_REACHED) return
        val ctx = spineIdcCtxAt(node)
        emitTS2356IfTypeParamOperand(operand, spineSource, spineFileName, ctx.tpProps, ctx.tpLocals)
    }

    /** The legacy downward triple at [anchor]: climb to the nearest
     *  ctx-defining boundary child (a fn-like's body / a class-prop
     *  initializer); no boundary up to the SourceFile → the per-file entry
     *  ctx (the legacy top-level scan's empty triple — ModuleBlocks pass
     *  context through unchanged, exactly as the legacy ModuleDeclaration arm
     *  did). */
    private fun spineIdcCtxAt(anchor: Node): IdcCtx {
        var child: Node = anchor
        var p: Node? = (anchor as NodeBase).parent
        while (p != null && p !is SourceFile) {
            if (spineIdcIsBoundaryChild(p, child)) return spineIdcCtxFor(p, child)
            child = p
            p = (p as NodeBase).parent
        }
        return spineIdcEmptyCtx
    }

    private fun spineIdcIsBoundaryChild(p: Node, child: Node): Boolean = when (p) {
        is FunctionDeclaration -> child === p.body
        is MethodDeclaration -> child === p.body
        is Constructor -> child === p.body
        is GetAccessor -> child === p.body
        is SetAccessor -> child === p.body
        is PropertyDeclaration -> child === p.initializer
        else -> false
    }

    /** Memoized child ctx for a boundary [child] of fn-like/class-member [p] —
     *  the deleted incDecScanStatement ClassDeclaration/FunctionDeclaration
     *  arms + incDecHandleBody verbatim (a FunctionDeclaration RESETS tpProps;
     *  only a MethodDeclaration contributes its OWN type params; a class-prop
     *  initializer runs with the cleared (∅, ∅) pair — nothing below an
     *  initializer can define a nested boundary, so its tparams are never
     *  consulted). */
    private fun spineIdcCtxFor(p: Node, child: Node): IdcCtx {
        val id = (child as NodeBase).nodeId
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineIdcCtxMemo[id]?.let { return it }
        val ctx: IdcCtx = when (p) {
            is FunctionDeclaration -> {
                val ftp = spineIdcCtxAt(p).tparams + unconstrainedTpNames(p.typeParameters)
                IdcCtx(ftp, emptySet(), spineIdcBodyLocals(child as Block, ftp))
            }
            is MethodDeclaration -> {
                val cls = (p as NodeBase).parent as? ClassDeclaration
                val newTp = spineIdcClassTp(cls)
                val mtp = newTp + unconstrainedTpNames(p.typeParameters)
                IdcCtx(mtp, spineIdcClassProps(cls, newTp), spineIdcBodyLocals(child as Block, mtp))
            }
            is Constructor, is GetAccessor, is SetAccessor -> {
                val cls = (p as NodeBase).parent as? ClassDeclaration
                val newTp = spineIdcClassTp(cls)
                IdcCtx(newTp, spineIdcClassProps(cls, newTp), spineIdcBodyLocals(child as Block, newTp))
            }
            else -> spineIdcEmptyCtx // PropertyDeclaration initializer: (∅, ∅)
        }
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineIdcCtxMemo[id] = ctx
        return ctx
    }

    /** incDecHandleBody's tpLocals build — the body-WIDE prepass (block-BLIND:
     *  it descends nested control-flow statements, but never a nested
     *  fn/class body). */
    private fun spineIdcBodyLocals(body: Block, tparams: Set<String>): Set<String> {
        if (tparams.isEmpty()) return emptySet()
        val locals = HashSet<String>()
        collectTpLocals(body.statements, tparams, locals)
        return locals
    }

    /** The ClassDeclaration arm's newTp — the class's own statement-position
     *  tparams (accumulated through enclosing fn bodies) + its unconstrained
     *  TPs. */
    private fun spineIdcClassTp(cls: ClassDeclaration?): Set<String> {
        if (cls == null) return emptySet()
        return spineIdcCtxAt(cls).tparams + unconstrainedTpNames(cls.typeParameters)
    }

    /** The ClassDeclaration arm's props set — bare-TP-annotated property
     *  members (for `this.<prop>++` operands). */
    private fun spineIdcClassProps(cls: ClassDeclaration?, newTp: Set<String>): Set<String> {
        if (cls == null || newTp.isEmpty()) return emptySet()
        var props: HashSet<String>? = null
        for (m in cls.members) {
            if (m !is PropertyDeclaration) continue
            if (!isBareTypeParamRef(m.type, newTp)) continue
            val n = (m.name as? Identifier)?.text ?: continue
            (props ?: HashSet<String>().also { props = it }).add(n)
        }
        return props ?: emptySet()
    }

    /** Memoized reach classifier — ascends to the first memoized/terminal
     *  ancestor, then folds [spineIdcEdge] back down (spineGxStatus pattern).
     *  The SourceFile anchor carries the transient IDC_ROOT status (never
     *  memoized) whose sole edge is `child is Statement`. */
    private fun spineIdcStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.IDC]++
        if (node is SourceFile) return IDC_ROOT
        val memo = spineIdcReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.IDC, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineIdcChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = IDC_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed
            if (parent is SourceFile) { anchor = parent; anchorStatus = IDC_ROOT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.IDC, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = IDC_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = when {
                pNode == null -> IDC_NONE
                pStatus == IDC_ROOT -> if (c is Statement) IDC_REACHED else IDC_NONE
                pStatus == IDC_REACHED -> if (spineIdcEdge(pNode, c)) IDC_REACHED else IDC_NONE
                else -> IDC_NONE
            }
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.IDC, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.IDC]++; ReachCensus.folds[ReachCensus.IDC] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** The deleted recursion's descent edges, verbatim. Unlisted parents are
     *  the legacy `else -> {}`s (unreached children — arrows, fn/class
     *  EXPRESSIONS, static blocks, object literals, templates, typeof/void/
     *  delete/await operands, for-in/of LEFT sides, case-clause EXPRESSIONS,
     *  param defaults, heritage, decorators). */
    private fun spineIdcEdge(parent: Node, child: Node): Boolean = when (parent) {
        // ---- statements (the deleted incDecScanStatement arms) ----
        is ClassDeclaration -> when (child) {
            is MethodDeclaration, is Constructor, is GetAccessor,
            is SetAccessor, is PropertyDeclaration -> true
            else -> false
        }
        is MethodDeclaration -> child === parent.body
        is Constructor -> child === parent.body
        is GetAccessor -> child === parent.body
        is SetAccessor -> child === parent.body
        is PropertyDeclaration -> child === parent.initializer
        is FunctionDeclaration -> child === parent.body
        is ExpressionStatement -> child === parent.expression
        is VariableStatement -> child === parent.declarationList
        is VariableDeclarationList -> child is VariableDeclaration
        is VariableDeclaration -> child === parent.initializer
        is ReturnStatement -> child === parent.expression
        is ThrowStatement -> child === parent.expression
        is Block -> child is Statement
        is IfStatement ->
            child === parent.expression || child === parent.thenStatement ||
                child === parent.elseStatement
        is ForStatement -> // BOTH initializer forms (decl-list inits AND a bare expr)
            child === parent.initializer || child === parent.condition ||
                child === parent.incrementor || child === parent.statement
        is ForInStatement -> child === parent.expression || child === parent.statement
        is ForOfStatement -> child === parent.expression || child === parent.statement
        is WhileStatement -> child === parent.expression || child === parent.statement
        is DoStatement -> child === parent.statement || child === parent.expression
        is SwitchStatement ->
            child === parent.expression || child is CaseClause || child is DefaultClause
        is CaseClause -> child is Statement // NOT the case expression
        is DefaultClause -> child is Statement
        is TryStatement ->
            child === parent.tryBlock || child === parent.finallyBlock || child is CatchClause
        is CatchClause -> child === parent.block
        is LabeledStatement -> child === parent.statement
        is ModuleDeclaration -> child === parent.body && child is ModuleBlock
        is ModuleBlock -> child is Statement
        // ---- expressions (the deleted incDecCheckExpr arms) ----
        is PrefixUnaryExpression -> child === parent.operand
        is PostfixUnaryExpression -> child === parent.operand
        is BinaryExpression -> child === parent.left || child === parent.right
        is ParenthesizedExpression -> child === parent.expression
        is CallExpression -> child === parent.expression || parent.arguments.anyIdentical(child)
        is NewExpression ->
            child === parent.expression || parent.arguments?.anyIdentical(child) == true
        is PropertyAccessExpression -> child === parent.expression
        is ElementAccessExpression ->
            child === parent.expression || child === parent.argumentExpression
        is ConditionalExpression ->
            child === parent.condition || child === parent.whenTrue || child === parent.whenFalse
        is ArrayLiteralExpression -> parent.elements.anyIdentical(child)
        is SpreadElement -> child === parent.expression
        is AsExpression -> child === parent.expression
        is NonNullExpression -> child === parent.expression
        is TypeAssertionExpression -> child === parent.expression
        is SatisfiesExpression -> child === parent.expression
        else -> false
    }

    private fun emitTS2356IfTypeParamOperand(operand: Expression, source: String, fileName: String, tpProps: Set<String>, tpLocals: Set<String>) {
        var core: Expression = operand
        while (core is ParenthesizedExpression) core = core.expression
        val isTpOperand = when (core) {
            is Identifier -> core.text in tpLocals
            is PropertyAccessExpression -> (core.expression as? Identifier)?.text == "this" && core.name.text in tpProps
            else -> false
        }
        if (!isTpOperand) return
        val start = core.pos
        val length = expressionTrueEnd(core) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "An arithmetic operand must be of type 'any', 'number', 'bigint' or an enum type.",
            category = DiagnosticCategory.Error,
            code = 2356,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // B128: calls to a FUNCTION-TYPED PARAMETER. Two diagnostics (mutually
    // exclusive per call): TS2558 when type-args are supplied to a fn-typed
    // param whose FunctionType has 0 own type-params; TS2345 (+"could be
    // instantiated" chain) when a fn-typed param's call-sig param is a bare
    // UNCONSTRAINED in-scope type-param and the argument is a concrete simple
    // type. FP-safe by construction (both are always errors in TS for the
    // matched shape). Mirrors checkIncDecTypeParamOperands' scope threading.
    // -----------------------------------------------------------------------
    /** Threaded context for the fn-typed-param call walker.
     *  - [tparams]: in-scope UNCONSTRAINED type-param NAMES (accumulated).
     *  - [tpAst]: in-scope UNCONSTRAINED type-param NAME → AST node (accumulated,
     *    for TS2208 related-info positions).
     *  - [fnParams]: callable fn-typed params in the CURRENT scope (rebuilt per
     *    scope, NOT accumulated — mirrors the original behavior).
     *  - [tpVarRefs]: var/param NAME → the bare unconstrained type-param NAME it is
     *    declared as, for the CURRENT scope (rebuilt per scope). Lets us detect
     *    `f(y)` where `y: U` and `f`'s sig param is a different bare tp `T`. */
    private class FnParamCtx(
        val tparams: Set<String>,
        val tpAst: Map<String, TypeParameter>,
        val fnParams: Map<String, FunctionType>,
        val tpVarRefs: Map<String, String>,
        val classInstVarRefs: Map<String, ClassInstRef>,
        /** B215: fn-typed params ACCUMULATED through nested scopes (shadow-safe) —
         *  `fn.apply(thisArg, arr)` inside a returned closure still sees the outer
         *  function's `fn` param. */
        val fnParamsAccum: Map<String, FunctionType> = emptyMap(),
    )

    /** A param/local typed as `SomeClass<args...>` where SomeClass resolves to a
     *  user ClassDeclaration. [argTpNames]`[i]` is the bare in-scope UNCONSTRAINED
     *  type-param NAME supplied at class-tp position i (e.g. `B<T>` → `["T"]`), or
     *  null when that position is a concrete/other type. Used to detect method
     *  calls `x.foo(arg)` / `x.foo<X>(...)` on a generic class instance whose
     *  effective param type is an unconstrained type param. */
    private class ClassInstRef(val classDecl: ClassDeclaration, val argTpNames: List<String?>)

    private fun unconstrainedTpAst(tps: List<TypeParameter>?): Map<String, TypeParameter> =
        tps?.filter { it.constraint == null }?.associateBy { it.name.text } ?: emptyMap()

    /** Build a child ctx that introduces a NEW function/method/arrow scope: adds
     *  the given type-param lists to the accumulated tp sets, and REBUILDS the
     *  fn-typed-param + tp-var-ref + class-inst-var-ref maps from [params]. */
    private fun fnParamChildCtx(parent: FnParamCtx, params: List<Parameter>?, vararg tpLists: List<TypeParameter>?): FnParamCtx {
        var names = parent.tparams
        var ast = parent.tpAst
        for (tps in tpLists) { names = names + unconstrainedTpNames(tps); ast = ast + unconstrainedTpAst(tps) }
        val own = collectFnTypedParams(params)
        // B215: accumulate fn-typed params through scopes; ANY child param name
        // (fn-typed or not) shadows the parent's entry.
        val childNames = params.orEmpty().mapNotNull { (it.name as? Identifier)?.text }
        val accum = (parent.fnParamsAccum - childNames.toSet()) + own
        return FnParamCtx(names, ast, own, collectParamTpRefs(params ?: emptyList(), names), collectClassInstVarRefs(params ?: emptyList(), names), accum)
    }

    /** Add type-param scope (e.g. a class's tps for a field initializer) while
     *  KEEPING the parent's fn-typed-param + tp-var-ref + class-inst maps. */
    private fun fnParamAddTps(parent: FnParamCtx, vararg tpLists: List<TypeParameter>?): FnParamCtx {
        var names = parent.tparams
        var ast = parent.tpAst
        for (tps in tpLists) { names = names + unconstrainedTpNames(tps); ast = ast + unconstrainedTpAst(tps) }
        return FnParamCtx(names, ast, parent.fnParams, parent.tpVarRefs, parent.classInstVarRefs, parent.fnParamsAccum)
    }

    /** Params typed as `SomeClass<args...>` where SomeClass resolves (via globals)
     *  to a user ClassDeclaration. Captures the class-tp-position → bare-in-scope-tp
     *  mapping so a method call on such a receiver can be arg-checked. */
    private fun collectClassInstVarRefs(params: List<Parameter>, tparams: Set<String>): Map<String, ClassInstRef> {
        val m = mutableMapOf<String, ClassInstRef>()
        for (p in params) {
            val n = (p.name as? Identifier)?.text ?: continue
            val tr = p.type as? TypeReference ?: continue
            val cn = (tr.typeName as? Identifier)?.text ?: continue
            val classDecl = globals[cn]?.declarations?.firstOrNull { it is ClassDeclaration } as? ClassDeclaration ?: continue
            val argTpNames = (tr.typeArguments ?: emptyList()).map { ta ->
                val atr = ta as? TypeReference ?: return@map null
                if (!atr.typeArguments.isNullOrEmpty()) return@map null
                val an = (atr.typeName as? Identifier)?.text ?: return@map null
                if (an in tparams) an else null
            }
            m[n] = ClassInstRef(classDecl, argTpNames)
        }
        return m
    }

    /**
     * B218: TS2353 excess-property check for a single fresh object-literal arg
     * against a REVERSE-MAPPED param `{[K in keyof TP & keyof C]: TP[K]}`
     * (reverseMappedTypeLimitedConstraint). getTypeFromMappedType bakes the param
     * to anyType (keyof over an un-inferred TP), so the standard excess-prop path
     * skips the arg — but the instantiated mapped type's key set is ALWAYS a
     * subset of keyof C, so a literal property outside C's syntactically-known key
     * set is unconditionally TS2353 in tsc. Two shapes: a direct generic fn call,
     * and a curried `g<C>()(objLit)` whose g is an arrow-returning-arrow const.
     * Default-suppress: spread/computed/shorthand props, index/call sigs in C,
     * unrenderable in-key prop displays all bail.
     */
    private fun checkReverseMappedExcessProps() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            rmepScanStmts(result.sourceFile.statements, source, fileName, result.locals)
        }
    }

    private fun rmepScanStmts(stmts: List<Statement>, source: String, fileName: String, locals: SymbolTable?) {
        for (s in stmts) rmepScanStmt(s, source, fileName, locals)
    }

    private fun rmepScanStmt(stmt: Statement, source: String, fileName: String, locals: SymbolTable?) {
        when (stmt) {
            is ExpressionStatement -> rmepScanExpr(stmt.expression, source, fileName, locals)
            is VariableStatement -> stmt.declarationList.declarations.forEach { d ->
                d.initializer?.let { rmepScanExpr(it, source, fileName, locals) }
            }
            is ReturnStatement -> stmt.expression?.let { rmepScanExpr(it, source, fileName, locals) }
            is Block -> rmepScanStmts(stmt.statements, source, fileName, locals)
            is IfStatement -> {
                rmepScanStmt(stmt.thenStatement, source, fileName, locals)
                stmt.elseStatement?.let { rmepScanStmt(it, source, fileName, locals) }
            }
            is FunctionDeclaration -> stmt.body?.let { rmepScanStmts(it.statements, source, fileName, locals) }
            else -> {}
        }
    }

    private fun rmepScanExpr(expr: Expression, source: String, fileName: String, locals: SymbolTable?) {
        when (expr) {
            is BinaryExpression -> {
                var cur: Expression = expr
                while (cur is BinaryExpression) { rmepScanExpr(cur.right, source, fileName, locals); cur = cur.left }
                rmepScanExpr(cur, source, fileName, locals)
            }
            is CallExpression -> {
                (expr.expression as? CallExpression)?.let { rmepScanExpr(it, source, fileName, locals) }
                rmepCheckCall(expr, source, fileName, locals)
            }
            is ParenthesizedExpression -> rmepScanExpr(expr.expression, source, fileName, locals)
            else -> {}
        }
    }

    /** B218: the CONCRETE-side type name from `{[K in keyof TP & keyof C]: TP[K]}`
     *  when the mapped type matches exactly that shape (TP ∈ tpNames), else null. */
    private fun rmepConcreteKeyofName(t: TypeNode?, tpNames: Set<String>): String? {
        val m = t as? MappedType ?: return null
        if (m.nameType != null) return null
        val ia = m.type as? IndexedAccessType ?: return null
        val iaObj = ia.objectType as? TypeReference ?: return null
        val tpName = (iaObj.typeName as? Identifier)?.text ?: return null
        if (tpName !in tpNames || !iaObj.typeArguments.isNullOrEmpty()) return null
        val iaIdx = ia.indexType as? TypeReference ?: return null
        if ((iaIdx.typeName as? Identifier)?.text != m.typeParameter.name.text) return null
        val cons = m.typeParameter.constraint as? IntersectionType ?: return null
        if (cons.types.size != 2) return null
        var concrete: String? = null
        var sawTp = false
        for (part in cons.types) {
            val op = part as? TypeOperator ?: return null
            if (op.operator != SyntaxKind.KeyOfKeyword) return null
            val ref = op.type as? TypeReference ?: return null
            if (!ref.typeArguments.isNullOrEmpty()) return null
            val n = (ref.typeName as? Identifier)?.text ?: return null
            if (n == tpName) sawTp = true else concrete = n
        }
        return if (sawTp) concrete else null
    }

    /** B218: the key set of a TypeLiteral whose members are ALL simply-named
     *  PropertyDeclarations (anything else → null, FN-safe). */
    private fun rmepTypeLiteralKeys(tl: TypeLiteral): Set<String>? {
        val keys = mutableSetOf<String>()
        for (m in tl.members) {
            val p = m as? PropertyDeclaration ?: return null
            val n = when (val nn = p.name) {
                is Identifier -> nn.text
                is StringLiteralNode -> nn.text
                else -> return null
            }
            keys.add(n)
        }
        return keys
    }

    private fun rmepCheckCall(call: CallExpression, source: String, fileName: String, locals: SymbolTable?) {
        if (!call.typeArguments.isNullOrEmpty()) return
        val obj = call.arguments.singleOrNull() as? ObjectLiteralExpression ?: return
        for (p in obj.properties) {
            if (p !is PropertyAssignment) return
            if (p.name !is Identifier && p.name !is StringLiteralNode) return
        }
        val allowedKeys: Set<String> = when (val callee = call.expression) {
            is Identifier -> {
                val sym = locals?.get(callee.text) ?: globals[callee.text] ?: return
                val fd = sym.declarations.filterIsInstance<FunctionDeclaration>().singleOrNull() ?: return
                val tps = fd.typeParameters ?: return
                if (tps.isEmpty()) return
                val param = fd.parameters.singleOrNull() ?: return
                val cName = rmepConcreteKeyofName(param.type, tps.map { it.name.text }.toSet()) ?: return
                val cSym = locals?.get(cName) ?: globals[cName] ?: return
                when (val cDecl = cSym.declarations.singleOrNull()) {
                    is TypeAliasDeclaration -> (cDecl.type as? TypeLiteral)?.let { rmepTypeLiteralKeys(it) } ?: return
                    is InterfaceDeclaration -> {
                        if (cDecl.heritageClauses != null) return
                        val keys = mutableSetOf<String>()
                        for (m in cDecl.members) {
                            val pd = m as? PropertyDeclaration ?: return
                            keys.add((pd.name as? Identifier)?.text ?: return)
                        }
                        keys
                    }
                    else -> return
                }
            }
            is CallExpression -> {
                // curried: g<C>()(objLit) — g a const arrow returning an arrow.
                val g = callee.expression as? Identifier ?: return
                val tArgs = callee.typeArguments ?: return
                if (tArgs.isEmpty() || callee.arguments.isNotEmpty()) return
                val gSym = locals?.get(g.text) ?: globals[g.text] ?: return
                val gDecl = (gSym.valueDeclaration ?: gSym.declarations.firstOrNull())
                    as? VariableDeclaration ?: return
                var a1: Expression = gDecl.initializer ?: return
                while (a1 is ParenthesizedExpression) a1 = a1.expression
                val arrow1 = a1 as? ArrowFunction ?: return
                val a1Tps = arrow1.typeParameters ?: return
                if (a1Tps.isEmpty() || arrow1.parameters.isNotEmpty()) return
                var b: Node = arrow1.body
                while (b is ParenthesizedExpression) b = b.expression
                val arrow2 = b as? ArrowFunction ?: return
                val a2Tps = arrow2.typeParameters ?: return
                val param = arrow2.parameters.singleOrNull() ?: return
                val cName = rmepConcreteKeyofName(param.type, a2Tps.map { it.name.text }.toSet()) ?: return
                val idx = a1Tps.indexOfFirst { it.name.text == cName }
                if (idx < 0 || idx >= tArgs.size) return
                (tArgs[idx] as? TypeLiteral)?.let { rmepTypeLiteralKeys(it) } ?: return
            }
            else -> return
        }
        // First excess prop; render the in-key props for the display.
        var excessName: Identifier? = null
        var excessText: String? = null
        val parts = mutableListOf<String>()
        for (p in obj.properties) {
            val pa = p as PropertyAssignment
            val n = when (val nn = pa.name) {
                is Identifier -> nn.text
                is StringLiteralNode -> nn.text
                else -> return
            }
            if (n !in allowedKeys) {
                if (excessName == null) {
                    excessName = pa.name as? Identifier ?: return
                    excessText = n
                }
                continue
            }
            val disp = when (val init = pa.initializer) {
                is NumericLiteralNode -> init.text
                is StringLiteralNode -> "\"${init.text}\""
                is Identifier -> if (init.text == "true" || init.text == "false") init.text else return
                is PrefixUnaryExpression -> if (init.operator == SyntaxKind.Minus &&
                    init.operand is NumericLiteralNode) "-${(init.operand).text}" else return
                is AsExpression -> formatTypeForDisplay(init.type) ?: return
                else -> return
            }
            parts.add("$n: $disp;")
        }
        val excess = excessName ?: return
        val display = "{ ${parts.joinToString(" ")} }"
        val (line, ch) = getLineAndCharacterOfPosition(source, excess.pos)
        diagnostics.add(Diagnostic(
            message = "Object literal may only specify known properties, and '$excessText' does not exist in type '$display'.",
            category = DiagnosticCategory.Error, code = 2353,
            fileName = fileName, line = line, character = ch,
            start = excess.pos, length = excess.text.length,
        ))
    }

    // checkFnTypedParamCalls / fnParamScanStmts / fnParamScanStmt /
    // fnParamScanExpr DELETED (M0.4, round 626) — the walk is spine-hosted
    // (spineFpEnterNode/spineFpStatus/spineFpCtxAt); the emission leaves below
    // are anchor-called.

    /** Params whose declared type is a `FunctionType` with NO own type
     *  parameters — calling these with type arguments is TS2558. */
    private fun collectFnTypedParams(params: List<Parameter>?): Map<String, FunctionType> {
        if (params.isNullOrEmpty()) return emptyMap()
        val m = HashMap<String, FunctionType>()
        for (p in params) {
            val n = (p.name as? Identifier)?.text ?: continue
            val ft = p.type as? FunctionType ?: continue
            if (!ft.typeParameters.isNullOrEmpty()) continue
            m[n] = ft
        }
        return m
    }

    /** B217: does the identifier arg's type come from a COMPLETE (spread-free,
     *  statically-named) object literal — either a no-annotation var/const
     *  initializer, or a default-import alias of an `export default {…}`? */
    private fun argHasCompleteObjectLiteralProvenance(arg: Identifier): Boolean {
        val sym = currentFileLocals?.get(arg.text) ?: globals[arg.text] ?: return false
        fun completeObjLit(e: Expression?): Boolean {
            val o = e as? ObjectLiteralExpression ?: return false
            return o.properties.isNotEmpty() && o.properties.all { p ->
                p is PropertyAssignment && (p.name is Identifier || p.name is StringLiteralNode)
            }
        }
        val target = resolveAliasTarget(sym) ?: sym
        ((target.valueDeclaration ?: target.declarations.firstOrNull()) as? VariableDeclaration)?.let { vd ->
            if (vd.type == null && completeObjLit(vd.initializer)) return true
        }
        if (sym.flags.hasAny(SymbolFlags.Alias)) {
            defaultImportObjectLiteralExpr(sym)?.let { return completeObjLit(it) }
        }
        return false
    }

    /** B217: the ObjectLiteralExpression behind `import X from "./m"` whose target
     *  module's `export default` is an object literal (the binder creates no symbol
     *  for `export default <expr>`, so resolveAliasTarget returns null for X). */
    private fun defaultImportObjectLiteralExpr(symbol: Symbol): ObjectLiteralExpression? {
        for (decl in symbol.declarations) {
            val imp = decl as? ImportDeclaration ?: continue
            if (imp.importClause?.name?.text != symbol.name) continue
            val spec = (imp.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val resolved = resolveModuleSpecifier(spec) ?: continue
            val targetResult = binderResults.firstOrNull { it.sourceFile.fileName == resolved } ?: continue
            val ea = targetResult.sourceFile.statements.filterIsInstance<ExportAssignment>()
                .firstOrNull { !it.isExportEquals } ?: continue
            return ea.expression as? ObjectLiteralExpression
        }
        return null
    }

    /**
     * B215: TS2345 for `fn.apply(thisArg, arr)` where `fn` is a fn-typed PARAMETER
     * whose FunctionType has a required first (non-this) param, and `arr` is a
     * definite plain (non-tuple) array (emitSkipsThisWithRestParameter). Under
     * strictBindCallApply (strict-family; harness-default-on) tsc infers
     * CallableFunction.apply's A as the callee's NAMED PARAM TUPLE, and a `T[]`
     * source never satisfies a required element 0 — always TS2345 with the
     * "Source provides no match for required element at position 0 in target."
     * chain. Gates keep `any`/TypeParam/unknown/tuple args silent (FN-safe).
     */
    /**
     * B219: TS2353 excess property against a NoInfer-wrapped UNION param
     * (noInferUnionExcessPropertyCheck1). `test1(a: T, b: NoInfer<T> | (() =>
     * NoInfer<T>))` called with two fresh object literals — T's ONLY inference
     * site is the bare-T anchor (NoInfer constituents contribute nothing), so tsc
     * instantiates b's union with the anchor's widened type and excess-property-
     * checks the second literal against the OBJECT constituent. Our NoInfer has no
     * resolution branch (errorType) and inference bails on anonymous-object
     * anchors, so the file was silent. Display renders the annotation AST with T
     * substituted (outer NoInfer<union> dropped, member NoInfer wrappers kept,
     * fn members parenthesized). Default-suppress on unmodeled member shapes.
     */
    private fun tryEmitNoInferUnionExcessPropTs2353(
        sigIn: Signature, args: List<Expression>, source: String, fileName: String,
    ): Boolean {
        val tp = sigIn.typeParameters?.singleOrNull() ?: return false
        val tpName = tp.symbol?.name ?: return false
        val declParams = signatureDeclarationParameters(sigIn.declaration) ?: return false
        if (declParams.size != 2 || args.size != 2) return false
        fun isBareT(t: TypeNode?): Boolean =
            t is TypeReference && (t.typeName as? Identifier)?.text == tpName && t.typeArguments.isNullOrEmpty()
        fun noInferInner(t: TypeNode?): TypeNode? = (t as? TypeReference)?.let { r ->
            if ((r.typeName as? Identifier)?.text == "NoInfer" && r.typeArguments?.size == 1)
                r.typeArguments[0] else null
        }
        fun unwrapParens(t: TypeNode): TypeNode {
            var x = t
            while (x is ParenthesizedType) x = x.type
            return x
        }
        var anchorIdx = -1
        for (i in declParams.indices) {
            if (isBareT(declParams[i].type)) {
                if (anchorIdx >= 0) return false
                anchorIdx = i
            }
        }
        if (anchorIdx < 0) return false
        val unionIdx = 1 - anchorIdx
        var unionAnn: TypeNode = declParams[unionIdx].type ?: return false
        noInferInner(unionAnn)?.let { inner -> if (unwrapParens(inner) is UnionType) unionAnn = unwrapParens(inner) }
        val u = unionAnn as? UnionType ?: return false
        fun validConstituent(t0: TypeNode): Boolean {
            val t = unwrapParens(t0)
            if (isBareT(t)) return true
            noInferInner(t)?.let { return validConstituent(it) }
            if (t is FunctionType && t.parameters.isEmpty()) return validConstituent(t.type)
            return false
        }
        fun isObjConstituent(t0: TypeNode): Boolean {
            val t = unwrapParens(t0)
            if (isBareT(t)) return true
            noInferInner(t)?.let { return isObjConstituent(it) }
            return false
        }
        if (u.types.isEmpty() || !u.types.all { validConstituent(it) }) return false
        if (u.types.none { isObjConstituent(it) }) return false
        val anchorArg = args[anchorIdx] as? ObjectLiteralExpression ?: return false
        fun objLitOk(o: ObjectLiteralExpression): Boolean = o.properties.isNotEmpty() && o.properties.all { p ->
            (p is PropertyAssignment && (p.name is Identifier || p.name is StringLiteralNode)) ||
                p is ShorthandPropertyAssignment
        }
        if (!objLitOk(anchorArg)) return false
        val knownKeys = anchorArg.properties.mapNotNull { p ->
            when (p) {
                is PropertyAssignment -> when (val n = p.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> null
                }
                is ShorthandPropertyAssignment -> p.name.text
                else -> null
            }
        }.toSet()
        val widened = widenType(getTypeOfExpression(anchorArg))
        if (widened !is Type.Object || widened is Type.Interface || widened is Type.Reference) return false
        // Constraint guard: a constraint-failing anchor is tsc's TS2345, not EPC.
        tp.constraint?.let { c ->
            if (c !== anyType && c !== errorType) {
                val ok = checkTypeRelatedTo(widened, c, assignableRelation)
                if (!ok) return false
            }
        }
        val unionArg = args[unionIdx] as? ObjectLiteralExpression ?: return false
        if (!objLitOk(unionArg)) return false
        val tDisp = typeToString(widened)
        fun renderInner(t0: TypeNode): String? {
            val t = unwrapParens(t0)
            if (isBareT(t)) return tDisp
            noInferInner(t)?.let { inner -> return renderInner(inner)?.let { "NoInfer<$it>" } }
            if (t is FunctionType && t.parameters.isEmpty()) return renderInner(t.type)?.let { "() => $it" }
            return null
        }
        val memberDisps = u.types.map { m0 ->
            val m = unwrapParens(m0)
            val core = renderInner(m) ?: return false
            if (m is FunctionType) "($core)" else core
        }
        val display = memberDisps.joinToString(" | ")
        for (p in unionArg.properties) {
            val nameNode: Identifier = when (p) {
                is PropertyAssignment -> p.name as? Identifier ?: continue
                is ShorthandPropertyAssignment -> p.name
                else -> continue
            }
            if (nameNode.text in knownKeys || nameNode.text in OBJECT_PROTOTYPE_PROPERTIES) continue
            val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
            diagnostics.add(Diagnostic(
                message = "Object literal may only specify known properties, and '${nameNode.text}' does not exist in type '$display'.",
                category = DiagnosticCategory.Error, code = 2353,
                fileName = fileName, line = line, character = ch,
                start = nameNode.pos, length = nameNode.text.length,
            ))
            return true
        }
        return false
    }

    /**
     * B216: TS2345 via a DEPENDENT indexed-access constraint (deepKeysIndexing).
     * `bar.broken("a", "1", true)` where `bar: Bar<Foo>` and the method declares
     * `<K1 extends keyof O, K2 extends ..., V extends O[K1][K2]>(k1: K1, k2: K2,
     * value: V)` — tsc fixes K1/K2 to the literal arg types and evaluates
     * O[K1][K2] = Foo["a"]["1"] = 123, so `true` fails V's constraint. Our
     * signature build bakes such a constraint to anyType (indexed access with a
     * TypeParam index), so the 16.4i constraint branch is silent. AST-driven
     * per-call evaluation; DEFAULT-SUPPRESS on every unknown shape: concrete
     * generic-class-instance receiver, single non-overloaded method, the
     * constraint exactly a ClassTP[Ktp...] chain, every key arg a string literal,
     * every indexed step concrete, simple-checkable final constraint + arg.
     */
    private fun tryEmitDependentIndexedConstraintTs2345(
        expr: CallExpression, source: String, fileName: String,
    ): Boolean {
        if (!expr.typeArguments.isNullOrEmpty()) return false
        val callee = expr.expression as? PropertyAccessExpression ?: return false
        val recv = callee.expression
        if ((recv as? Identifier)?.text == "super") return false
        // (ENGINE.2g) round 793: the prologue's ONLY side-effecting call for a
        // call with no string-literal argument — everything below is a pure AST
        // read until `expr.arguments[pIdx] as? StringLiteralNode` decides.
        val b216T = CallSections.t()
        val recvType = getTypeOfExpression(recv)
        CallSections.close(CallSections.N_B216_TYPEOF, b216T)
        val ref = recvType as? Type.Reference ?: return false
        if (CallSections.pgOpen && CallSections.pgSkip) CallSections.pgB216Deep++
        val classArgs = ref.resolvedTypeArguments ?: return false
        if (classArgs.isEmpty() || classArgs.any { it is Type.TypeParam || it === anyType || it === errorType }) return false
        val classDecl = ref.target.symbol?.declarations?.firstOrNull { it is ClassDeclaration }
            as? ClassDeclaration ?: return false
        val classTps = classDecl.typeParameters ?: return false
        if (classTps.size != classArgs.size) return false
        val method = classDecl.members.filterIsInstance<MethodDeclaration>()
            .filter { (it.name as? Identifier)?.text == callee.name.text }
            .singleOrNull() ?: return false
        val mTps = method.typeParameters ?: return false
        val mTpNames = mTps.map { it.name.text }.toSet()
        fun bareRefName(t: TypeNode?): String? = (t as? TypeReference)?.let { r ->
            if (r.typeArguments.isNullOrEmpty()) (r.typeName as? Identifier)?.text else null
        }
        fun paramIdxOfBareTp(name: String): Int = method.parameters.indexOfFirst { p ->
            !p.dotDotDotToken && bareRefName(p.type) == name
        }
        for (tp in mTps) {
            // Peel the constraint: an IndexedAccessType chain rooted at a CLASS tp
            // with every index a bare ref to a SIBLING method tp.
            var c: TypeNode? = tp.constraint
            val keys = ArrayDeque<String>()
            while (c is IndexedAccessType) {
                val idxName = bareRefName(c.indexType) ?: break
                if (idxName !in mTpNames) break
                keys.addFirst(idxName)
                c = c.objectType
            }
            if (keys.isEmpty()) continue
            val rootName = (c as? TypeReference)?.let { r ->
                if (r.typeArguments.isNullOrEmpty()) (r.typeName as? Identifier)?.text else null
            } ?: continue
            val classIdx = classTps.indexOfFirst { it.name.text == rootName }
            if (classIdx < 0) continue
            var cur: Type = classArgs[classIdx]
            var ok = true
            for (k in keys) {
                val pIdx = paramIdxOfBareTp(k)
                if (pIdx < 0 || pIdx >= expr.arguments.size) { ok = false; break }
                val keyArg = expr.arguments[pIdx] as? StringLiteralNode
                if (keyArg == null) { ok = false; break }
                val curObj = cur as? Type.Object
                if (curObj != null) {
                    resolveStructuredTypeMembers(curObj)
                }
                cur = getIndexedAccessType(cur, Type.StringLiteral(keyArg.text))
                if (cur === anyType || cur === errorType) { ok = false; break }
            }
            if (!ok || !isSimpleCheckableType(cur)) continue
            val vIdx = paramIdxOfBareTp(tp.name.text)
            if (vIdx < 0 || vIdx >= expr.arguments.size) continue
            val arg = expr.arguments[vIdx]
            if (arg is SpreadElement) continue
            val argType = literalTypeOfExpression(arg)
                ?: (getTypeOfExpression(arg))
            if (argType === anyType || argType === errorType || !isSimpleCheckableType(argType)) continue
            val pass = checkTypeRelatedTo(argType, cur, assignableRelation)
            if (pass) continue
            // B98.r126 display rule: preserve the arg literal iff the target is a literal.
            val srcDisp = if (getWidenedLiteralType(cur) !== cur) typeToString(argType)
                else typeToString(getWidenedLiteralType(argType))
            val start = arg.pos
            val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
            val (line, ch) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$srcDisp' is not assignable to parameter of type '${typeToString(cur)}'.",
                category = DiagnosticCategory.Error, code = 2345,
                fileName = fileName, line = line, character = ch,
                start = start, length = length,
            ))
            return true
        }
        return false
    }

    private fun emitFnTypedParamApplyDiag(
        call: CallExpression, callee: PropertyAccessExpression, ft: FunctionType,
        source: String, fileName: String,
    ) {
        if (options.strictExplicitlyFalse) return
        if (!call.typeArguments.isNullOrEmpty() || call.arguments.size != 2 ||
            call.questionDotToken || callee.questionDotToken) return
        // Drop a leading `this` pseudo-param; remaining params must be non-empty
        // with a REQUIRED first and fully displayable names/types.
        val ps = ft.parameters.dropWhile { (it.name as? Identifier)?.text == "this" }
        if (ps.isEmpty()) return
        val first = ps[0]
        if (first.questionToken || first.initializer != null || first.dotDotDotToken) return
        val tupleParts = ps.map { p ->
            val n = (p.name as? Identifier)?.text ?: return
            val d = p.type?.let { formatTypeForDisplay(it) } ?: return
            "${if (p.dotDotDotToken) "..." else ""}$n${if (p.questionToken) "?" else ""}: $d"
        }
        val arg = call.arguments[1]
        if (arg is SpreadElement) return
        val argType = getTypeOfExpression(arg)
        val argDisplay: String = when {
            argType is Type.Reference && argType.target.symbol?.name == "Array" &&
                argType.resolvedTypeArguments?.size == 1 -> typeToString(argType)
            // `[x].concat(y)` resolves to anyType in our engine (any-typed elements
            // bail getTypeOfArrayLiteral) — but tsc types it as a plain array.
            argType === anyType && arg is CallExpression &&
                (arg.expression as? PropertyAccessExpression)?.name?.text == "concat" &&
                (arg.expression).expression is ArrayLiteralExpression -> "any[]"
            else -> return
        }
        val start = arg.pos
        val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
        val (line, ch) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Argument of type '$argDisplay' is not assignable to parameter of type '[${tupleParts.joinToString(", ")}]'.",
            category = DiagnosticCategory.Error, code = 2345,
            fileName = fileName, line = line, character = ch,
            start = start, length = length,
            messageChain = listOf("  Source provides no match for required element at position 0 in target."),
        ))
    }

    private fun emitFnTypedParamCallDiag(call: CallExpression, ft: FunctionType, source: String, fileName: String, ctx: FnParamCtx) {
        val tparams = ctx.tparams
        val typeArgs = call.typeArguments
        if (!typeArgs.isNullOrEmpty()) {
            // TS2558 — a fn-typed param's FunctionType has 0 own type parameters.
            val start = typeArgs.first().pos
            var endPos = typeArgs.last().end
            while (endPos > start && endPos < source.length) {
                val ch = source[endPos - 1]
                if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') endPos-- else break
            }
            val length = (endPos - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Expected 0 type arguments, but got ${typeArgs.size}.",
                category = DiagnosticCategory.Error, code = 2558,
                fileName = fileName, line = line, character = character, start = start, length = length,
            ))
            return
        }
        // TS2345 — first call-sig param that is a bare UNCONSTRAINED in-scope type
        // param whose corresponding argument is a concrete simple type.
        for ((i, p) in ft.parameters.withIndex()) {
            val tpName = bareTypeParamRefName(p.type, tparams) ?: continue
            val arg = call.arguments.getOrNull(i) ?: continue

            // Case A: the argument is itself a variable/parameter typed as a bare
            // UNCONSTRAINED type param. `f(x)` where `x: T` and the sig param is
            // `T` is legal (same type param); `f(y)` where `y: U` (a DIFFERENT
            // unconstrained type param) is TS2345 + the "could be instantiated"
            // chain + a TS2208 related info at U's declaration. FP-safe: an
            // unrelated unconstrained type param is never assignable to another.
            val argTpName = (arg as? Identifier)?.let { ctx.tpVarRefs[it.text] }
            if (argTpName != null) {
                if (argTpName == tpName) continue
                val start = arg.pos
                val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                val related = mutableListOf<Diagnostic>()
                ctx.tpAst[argTpName]?.let { tpNode ->
                    val (rl, rc) = getLineAndCharacterOfPosition(source, tpNode.name.pos)
                    related.add(Diagnostic(
                        message = "This type parameter might need an `extends $tpName` constraint.",
                        category = DiagnosticCategory.Message, code = 2208,
                        fileName = fileName, line = rl, character = rc,
                        start = tpNode.name.pos, length = tpNode.name.text.length,
                    ))
                }
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$argTpName' is not assignable to parameter of type '$tpName'.",
                    category = DiagnosticCategory.Error, code = 2345,
                    fileName = fileName, line = line, character = character, start = start, length = length,
                    messageChain = listOf("  '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$argTpName'."),
                    relatedInformation = related.toList(),
                ))
                return
            }

            // Case B: the argument is a concrete simple type (number/string/null/…).
            val argType = getWidenedLiteralType(getTypeOfExpression(arg))
            if (argType is Type.TypeParam || argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(argType)) continue
            val display = typeToString(argType)
            val start = arg.pos
            val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$display' is not assignable to parameter of type '$tpName'.",
                category = DiagnosticCategory.Error, code = 2345,
                fileName = fileName, line = line, character = character, start = start, length = length,
                messageChain = listOf("  '$tpName' could be instantiated with an arbitrary type which could be unrelated to '$display'."),
            ))
            return
        }
    }

    /** Method call `x.foo(...)` / `x.foo<X>(...)` where `x` is a param typed as a
     *  generic class instance (`x: B<T>`). Emits, mutually exclusive per call:
     *  - TS2558 when type-args are supplied and `foo` is a single non-overloaded
     *    method with NO own type parameters (a class type param is NOT a method
     *    type param);
     *  - TS2345 when no type-args and `foo`'s param resolves (via the receiver's
     *    `B<T>` instantiation) to a bare in-scope UNCONSTRAINED type param and the
     *    argument is a concrete simple type.
     *  FP firewall: receiver must be an annotated class-instance var (so the
     *  object-literal-generic-property shape of `typeAssertionToGenericFunctionType`
     *  is never matched), and the method must be a single non-overloaded
     *  MethodDeclaration. */
    private fun emitGenericMethodCallDiag(call: CallExpression, pae: PropertyAccessExpression, inst: ClassInstRef, source: String, fileName: String, ctx: FnParamCtx) {
        val methodName = pae.name.text
        val methodDecls = inst.classDecl.members.filterIsInstance<MethodDeclaration>().filter { (it.name as? Identifier)?.text == methodName }
        if (methodDecls.size != 1) return  // overloaded or absent → could be generic / inherited; skip
        val method = methodDecls[0]

        val typeArgs = call.typeArguments
        if (!typeArgs.isNullOrEmpty()) {
            if (!method.typeParameters.isNullOrEmpty()) return  // method IS generic → type-args legal
            val start = typeArgs.first().pos
            var endPos = typeArgs.last().end
            while (endPos > start && endPos < source.length) {
                val ch = source[endPos - 1]
                if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') endPos-- else break
            }
            val length = (endPos - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Expected 0 type arguments, but got ${typeArgs.size}.",
                category = DiagnosticCategory.Error, code = 2558,
                fileName = fileName, line = line, character = character, start = start, length = length,
            ))
            return
        }

        val classTpNames = inst.classDecl.typeParameters?.map { it.name.text } ?: emptyList()
        for ((i, p) in method.parameters.withIndex()) {
            val ptr = p.type as? TypeReference ?: continue
            if (!ptr.typeArguments.isNullOrEmpty()) continue
            val pn = (ptr.typeName as? Identifier)?.text ?: continue
            val classTpPos = classTpNames.indexOf(pn)
            if (classTpPos < 0) continue
            // The class tp at this position is instantiated with a bare in-scope
            // unconstrained type param (the enclosing arrow's `T`)?
            val mappedTp = inst.argTpNames.getOrNull(classTpPos) ?: continue
            val arg = call.arguments.getOrNull(i) ?: continue
            val argType = getWidenedLiteralType(getTypeOfExpression(arg))
            if (argType is Type.TypeParam || argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(argType)) continue
            val display = typeToString(argType)
            val start = arg.pos
            val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$display' is not assignable to parameter of type '$mappedTp'.",
                category = DiagnosticCategory.Error, code = 2345,
                fileName = fileName, line = line, character = character, start = start, length = length,
                messageChain = listOf("  '$mappedTp' could be instantiated with an arbitrary type which could be unrelated to '$display'."),
            ))
            return
        }
    }

    // -----------------------------------------------------------------------
    // TS2862: "Type 'T' is generic and can only be indexed for reading." — for
    // writing to an indexed access `target[key] = value` whose receiver is typed
    // as a generic type parameter. The instantiated type is unknown, so the
    // write is unsound. A numeric-LITERAL index (`target[1] = …`) is the one
    // allowed form (array/tuple element write), so it is exempt.
    //
    // AST-level + FP-firewalled: the receiver must be a parameter / local / this
    // property annotated as a bare `TypeReference` to a CONSTRAINED type
    // parameter in scope (a constrained `T` is a generic object type). The
    // message carries the type-parameter NAME (not the variable name). TypeScript
    // emits TS2862 for exactly this shape, so a passing test matching the gate
    // would already carry it (can only help / be neutral).
    // (M0.4, round 637): the per-file pass driver + recursion walkers
    // (checkGenericIndexWrite / gIdxHandleBody / gIdxScanStatement(s) /
    // gIdxCheckExpr) are DELETED — the spine dispatches the emission
    // (spineGxEnterNode) with a pull-based per-anchor context rebuild. The
    // helpers below are retained as the rebuild's leaves.
    // -----------------------------------------------------------------------

    private fun bareTypeParamRefName(typeNode: TypeNode?, tparams: Set<String>): String? {
        val tr = typeNode as? TypeReference ?: return null
        if (!tr.typeArguments.isNullOrEmpty()) return null
        val name = (tr.typeName as? Identifier)?.text ?: return null
        return if (name in tparams) name else null
    }

    // TS2862 fires only for an index-WRITE whose receiver type would otherwise fall
    // back to a STRING/symbol index signature (tsc checker.ts ~19294:
    // `accessFlags & NoIndexSignatures && indexInfo.keyType !== numberType`). A bare
    // `T extends object` (or any constraint WITHOUT a string/symbol index signature)
    // has no such `indexInfo`, so tsc emits NOTHING — `assign<T extends object>(t: T){ t[p]=… }`
    // compiles clean. So a type param is TS2862-eligible only when its CONSTRAINT bears a
    // string/symbol index signature (inline `{ [s: string]: V }`, or `Record<K, V>` with a
    // string/symbol-like key K, or an intersection containing either). A user `TypeReference`
    // to an interface with an index signature is a false negative (harmless — we just don't
    // emit; the corpus tests use `Record`/inline literals, which this covers).
    private fun typeNodeIsStringOrSymbolKeyLike(t: TypeNode?): Boolean = when (t) {
        is KeywordTypeNode -> t.kind == SyntaxKind.StringKeyword || t.kind == SyntaxKind.SymbolKeyword
        is UnionType -> t.types.any { typeNodeIsStringOrSymbolKeyLike(it) }
        is TypeReference -> (t.typeName as? Identifier)?.text == "PropertyKey" // string | number | symbol
        else -> false
    }

    private fun constraintHasStringIndexSignature(c: TypeNode?): Boolean = when (c) {
        is TypeLiteral -> c.members.any { it is IndexSignature && typeNodeIsStringOrSymbolKeyLike(it.parameters.firstOrNull()?.type) }
        is IntersectionType -> c.types.any { constraintHasStringIndexSignature(it) }
        is TypeReference -> (c.typeName as? Identifier)?.text == "Record" && typeNodeIsStringOrSymbolKeyLike(c.typeArguments?.firstOrNull())
        else -> false
    }

    private fun constrainedTpNames(tps: List<TypeParameter>?): Set<String> =
        tps?.filter { it.constraint != null && constraintHasStringIndexSignature(it.constraint) }?.map { it.name.text }?.toSet() ?: emptySet()

    private fun collectParamTpRefs(params: List<Parameter>, tparams: Set<String>): Map<String, String> {
        val m = mutableMapOf<String, String>()
        for (p in params) {
            val n = (p.name as? Identifier)?.text ?: continue
            bareTypeParamRefName(p.type, tparams)?.let { m[n] = it }
        }
        return m
    }

    private fun collectTpLocalsMap(stmts: List<Statement>, tparams: Set<String>, into: MutableMap<String, String>) {
        for (stmt in stmts) when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text
                if (n != null) bareTypeParamRefName(d.type, tparams)?.let { into[n] = it }
            }
            is Block -> collectTpLocalsMap(stmt.statements, tparams, into)
            is IfStatement -> { collectTpLocalsMapStmt(stmt.thenStatement, tparams, into); stmt.elseStatement?.let { collectTpLocalsMapStmt(it, tparams, into) } }
            is ForStatement -> { (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d -> val n = (d.name as? Identifier)?.text; if (n != null) bareTypeParamRefName(d.type, tparams)?.let { into[n] = it } }; collectTpLocalsMapStmt(stmt.statement, tparams, into) }
            is ForInStatement -> collectTpLocalsMapStmt(stmt.statement, tparams, into)
            is ForOfStatement -> collectTpLocalsMapStmt(stmt.statement, tparams, into)
            is WhileStatement -> collectTpLocalsMapStmt(stmt.statement, tparams, into)
            is DoStatement -> collectTpLocalsMapStmt(stmt.statement, tparams, into)
            is LabeledStatement -> collectTpLocalsMapStmt(stmt.statement, tparams, into)
            else -> {}
        }
    }
    private fun collectTpLocalsMapStmt(stmt: Statement, tparams: Set<String>, into: MutableMap<String, String>) = collectTpLocalsMap(listOf(stmt), tparams, into)

    /**
     * B167: TS2322 for `obj[x] = undefined` where `obj: Alias<T>` instantiates a type alias
     * whose body is an INTERSECTION containing a generic MappedType, and `x: keyof T` for an
     * in-scope unconstrained type param T (undefinedAssignableToGenericMappedIntersection).
     * TypeScript does not simplify the write type of an indexed access on a generic mapped
     * INTERSECTION, so `undefined` is never assignable to `Alias<T>[keyof T]` — even when the
     * mapped value type includes `undefined`. AST-level (no type engine); display is built
     * from the annotations' source shapes. Gated to strictNullChecks + an `undefined` RHS.
     */
    private fun checkMappedIntersectionIndexWrite() {
        if (!strictNullChecks) return
        fun aliasBodyIsMappedIntersection(name: String): Boolean {
            val sym = globals[name] ?: return false
            val decl = sym.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                ?: return false
            val body = decl.type
            return body is IntersectionType && body.types.any { it is MappedType }
        }
        fun scanBody(stmts: List<Statement>, tps: Set<String>, source: String, fileName: String) {
            // var -> annotation display for mapped-intersection alias instantiations / keyof-TP
            val objVars = mutableMapOf<String, String>()
            val keyVars = mutableMapOf<String, String>()
            for (s in stmts) {
                if (s is VariableStatement) {
                    for (d in s.declarationList.declarations) {
                        val n = (d.name as? Identifier)?.text ?: continue
                        val t = d.type ?: continue
                        if (t is TypeReference && t.typeName is Identifier) {
                            val args = t.typeArguments
                            if (!args.isNullOrEmpty() &&
                                args.any { a -> (a as? TypeReference)?.typeName.let { it is Identifier && it.text in tps } } &&
                                aliasBodyIsMappedIntersection((t.typeName).text)
                            ) {
                                val argDisplay = args.joinToString(", ") { formatTypeForDisplay(it) ?: "?" }
                                objVars[n] = "${(t.typeName).text}<$argDisplay>"
                            }
                        }
                        if (t is TypeOperator && t.operator == SyntaxKind.KeyOfKeyword) {
                            val inner = (t.type as? TypeReference)?.typeName as? Identifier
                            if (inner != null && inner.text in tps) keyVars[n] = "keyof ${inner.text}"
                        }
                    }
                }
                if (s is ExpressionStatement) {
                    val e = s.expression
                    if (e is BinaryExpression && e.operator == SyntaxKind.Equals &&
                        e.right is Identifier && (e.right).text == "undefined"
                    ) {
                        val lhs = e.left
                        if (lhs is ElementAccessExpression && lhs.expression is Identifier &&
                            lhs.argumentExpression is Identifier
                        ) {
                            val objDisplay = objVars[(lhs.expression).text]
                            val keyDisplay = keyVars[(lhs.argumentExpression).text]
                            if (objDisplay != null && keyDisplay != null) {
                                val start = lhs.pos
                                val length = expressionTrueEnd(lhs) - start
                                val (line, ch) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "Type 'undefined' is not assignable to type '$objDisplay[$keyDisplay]'.",
                                    category = DiagnosticCategory.Error, code = 2322,
                                    fileName = fileName, line = line, character = ch,
                                    start = start, length = length,
                                ))
                            }
                        }
                    }
                }
            }
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is FunctionDeclaration && !stmt.typeParameters.isNullOrEmpty()) {
                    val tps = stmt.typeParameters.filter { it.constraint == null }.map { it.name.text }.toSet()
                    if (tps.isNotEmpty()) stmt.body?.let { scanBody(it.statements, tps, source, fileName) }
                }
            }
        }
    }

    /**
     * B251: TS2551/TS2339 + TS2862 for WRITES on a local cast to
     * `Record<keyof TP | "literal", V>` inside a generic function
     * (mappedTypeGenericWithKnownKeys). The key union mixes `keyof Shape` (generic —
     * keys unknowable, so the Record stays generic and is writable only via the known
     * literal keys) with literal keys: a dot-write to an unknown literal key is
     * TS2551 (with spelling suggestion from the literal-key set) / TS2339; an
     * element-write whose index is an explicitly always-`string` shape is TS2862
     * "generic and can only be indexed for reading." Default-suppress polarity:
     * only the recognized shapes fire (unknown index shapes are FN, never FP) —
     * `obj[key]` with `key: keyof Shape` correctly does not fire.
     */
    private fun checkGenericRecordCastAccess() {
        // user `Record` shadow -> lib utility semantics don't apply (B184 gate)
        if (globals["Record"]?.declarations?.any {
                it is TypeAliasDeclaration || it is InterfaceDeclaration || it is ClassDeclaration
            } == true) return

        fun keyofTpName(t: TypeNode, tps: Map<String, TypeParameter>): String? {
            if (t !is TypeOperator || t.operator != SyntaxKind.KeyOfKeyword) return null
            val ref = t.type as? TypeReference ?: return null
            if (ref.typeArguments != null) return null
            val name = (ref.typeName as? Identifier)?.text ?: return null
            return if (name in tps) name else null
        }
        // constraint contributes NO literal keys: absent, `object`, or `Record<string, *>`
        fun constraintIsKeyOpaque(c: TypeNode?): Boolean {
            if (c == null) return true
            if (c is KeywordTypeNode && c.kind == SyntaxKind.ObjectKeyword) return true
            if (c is TypeReference && (c.typeName as? Identifier)?.text == "Record") {
                val args = c.typeArguments
                return args?.size == 2 &&
                    (args[0] as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword
            }
            return false
        }

        fun scanBody(
            stmts: List<Statement>, tps: Map<String, TypeParameter>,
            paramStringNames: Set<String>, source: String, fileName: String,
        ) {
            // tracked local -> (Record display, literal key set)
            val tracked = mutableMapOf<String, Pair<String, Set<String>>>()
            for (s in stmts) {
                if (s is VariableStatement) {
                    for (d in s.declarationList.declarations) {
                        val n = (d.name as? Identifier)?.text ?: continue
                        if (d.type != null) continue
                        var init = d.initializer ?: continue
                        while (init is ParenthesizedExpression) init = init.expression
                        val asExpr = init as? AsExpression ?: continue
                        val t = asExpr.type as? TypeReference ?: continue
                        if ((t.typeName as? Identifier)?.text != "Record") continue
                        val args = t.typeArguments ?: continue
                        if (args.size != 2) continue
                        val keyUnion = args[0] as? UnionType ?: continue
                        val literalKeys = mutableSetOf<String>()
                        var keyofCount = 0
                        var ok = true
                        val memberDisplays = mutableListOf<String>()
                        for (m in keyUnion.types) {
                            val lit = (m as? LiteralType)?.literal as? StringLiteralNode
                            if (lit != null) {
                                literalKeys.add(lit.text)
                                memberDisplays.add("\"${lit.text}\"")
                                continue
                            }
                            val tpName = keyofTpName(m, tps)
                            if (tpName != null && constraintIsKeyOpaque(tps[tpName]?.constraint)) {
                                keyofCount++
                                memberDisplays.add("keyof $tpName")
                                continue
                            }
                            ok = false
                            break
                        }
                        if (!ok || keyofCount == 0 || literalKeys.isEmpty()) continue
                        val valDisplay = formatTypeForDisplay(args[1]) ?: continue
                        tracked[n] = "Record<${memberDisplays.joinToString(" | ")}, $valDisplay>" to literalKeys
                    }
                }
                if (s is ExpressionStatement) {
                    val e = s.expression
                    if (e is BinaryExpression && e.operator == SyntaxKind.Equals) {
                        val lhs = e.left
                        if (lhs is PropertyAccessExpression && lhs.expression is Identifier && !lhs.questionDotToken) {
                            val info = tracked[(lhs.expression).text]
                            val propName = lhs.name.text
                            if (info != null && propName !in info.second &&
                                propName !in OBJECT_PROTOTYPE_PROPERTIES &&
                                propName !in RUNTIME_PROPERTIES
                            ) {
                                val suggestion = getSpellingSuggestionFromNames(propName, info.second)
                                val start = lhs.name.pos
                                val (line, ch) = getLineAndCharacterOfPosition(source, start)
                                val (msg, code) = if (suggestion != null)
                                    "Property '$propName' does not exist on type '${info.first}'. Did you mean '$suggestion'?" to 2551
                                else
                                    "Property '$propName' does not exist on type '${info.first}'." to 2339
                                diagnostics.add(Diagnostic(
                                    message = msg,
                                    category = DiagnosticCategory.Error, code = code,
                                    fileName = fileName, line = line, character = ch,
                                    start = start, length = propName.length,
                                ))
                            }
                        }
                        if (lhs is ElementAccessExpression && lhs.expression is Identifier && !lhs.questionDotToken) {
                            val info = tracked[(lhs.expression).text]
                            if (info != null) {
                                val idx = lhs.argumentExpression
                                val isAlwaysString = (idx is AsExpression &&
                                    (idx.type as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword) ||
                                    (idx is Identifier && idx.text in paramStringNames)
                                if (isAlwaysString) {
                                    // span: receiver start .. the matching `]` inclusive
                                    // (expressionTrueEnd overshoots for AsExpression indices)
                                    val start = lhs.pos
                                    var endPos = -1
                                    val bracket = source.indexOf('[', (lhs.expression).pos)
                                    if (bracket >= 0) {
                                        var depth = 0
                                        var i = bracket
                                        while (i < source.length) {
                                            when (source[i]) {
                                                '[' -> depth++
                                                ']' -> { depth--; if (depth == 0) { endPos = i + 1; break } }
                                            }
                                            i++
                                        }
                                    }
                                    if (endPos > start) {
                                        val (line, ch) = getLineAndCharacterOfPosition(source, start)
                                        diagnostics.add(Diagnostic(
                                            message = "Type '${info.first}' is generic and can only be indexed for reading.",
                                            category = DiagnosticCategory.Error, code = 2862,
                                            fileName = fileName, line = line, character = ch,
                                            start = start, length = endPos - start,
                                        ))
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is FunctionDeclaration && !stmt.typeParameters.isNullOrEmpty()) {
                    val tps = stmt.typeParameters.associateBy { it.name.text }
                    val paramStringNames = stmt.parameters.mapNotNull { p ->
                        val pn = (p.name as? Identifier)?.text
                        if (pn != null && (p.type as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword) pn else null
                    }.toSet()
                    stmt.body?.let { scanBody(it.statements, tps, paramStringNames, source, fileName) }
                }
            }
        }
    }

    /**
     * B264: TS2345 / TS2769 for `new Derived(...)` where the constructor is INHERITED
     * from an overloaded generic `declare class` instantiated through the heritage
     * chain (inheritedConstructorWithRestParams2: `Derived extends Base extends
     * BaseBase<string, number>`). The main new-expression path skips overloaded
     * generic ctors entirely. AST-only model: ctor params must be bare in-scope-TP
     * refs / primitive keywords / rest arrays thereof, substituted by PRIMITIVE
     * heritage type args; call args must be literals. One arity-applicable overload
     * failing → TS2345 at the first mismatching arg; several applicable all failing →
     * TS2769 at the CALLEE name with the per-overload "Overload i of N,
     * '(<params>): <Class>', gave the following error." chain (overload indices are
     * 1-based over ALL overloads; only arity-applicable ones are listed). Any
     * unrecognized shape bails (FN, never FP).
     */
    private fun checkInheritedOverloadedCtorArgs() {
        val primKw = mapOf(
            SyntaxKind.StringKeyword to "string", SyntaxKind.NumberKeyword to "number",
            SyntaxKind.BooleanKeyword to "boolean", SyntaxKind.BigIntKeyword to "bigint",
        )
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val classes = result.sourceFile.statements
                .filterIsInstance<ClassDeclaration>()
                .filter { it.name != null }
                .associateBy { it.name!!.text }

            class ParamSpec(val name: String, val type: String, val isRest: Boolean, val isOptional: Boolean)
            class CtorInfo(val overloads: List<List<ParamSpec>>, val total: Int)

            // resolve the ctor-owning class through the extends chain, substituting TPs
            fun resolveCtor(cls0: ClassDeclaration): CtorInfo? {
                var cls = cls0
                var hops = 0
                var subst = emptyMap<String, String>()
                while (cls.members.none { it is Constructor } && hops < 6) {
                    val ext = cls.heritageClauses
                        ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                        ?.types?.singleOrNull() ?: return null
                    val baseName = (ext.expression as? Identifier)?.text ?: return null
                    val base = classes[baseName] ?: return null
                    val args = ext.typeArguments
                    subst = if (args != null) {
                        val tps = base.typeParameters ?: return null
                        if (tps.size != args.size) return null
                        tps.indices.associate { i ->
                            tps[i].name.text to (primKw[(args[i] as? KeywordTypeNode)?.kind] ?: return null)
                        }
                    } else {
                        if (!base.typeParameters.isNullOrEmpty()) return null
                        emptyMap()
                    }
                    cls = base
                    hops++
                }
                val ctors = cls.members.filterIsInstance<Constructor>()
                if (ctors.isEmpty()) return null
                // OVERLOADED signatures only — the single-signature inherited-ctor case is
                // already handled by the existing rest-arg path (double-emit otherwise:
                // inheritedConstructorWithRestParams regressed on the first cut)
                val sigs = ctors.filter { it.body == null }
                if (sigs.size < 2) return null
                val overloads = sigs.map { c ->
                    c.parameters.map { p ->
                        val pn = (p.name as? Identifier)?.text ?: return null
                        val t = p.type ?: return null
                        val typeName: String
                        val rest = p.dotDotDotToken
                        if (rest) {
                            val at = t as? ArrayType ?: return null
                            typeName = when (val et = at.elementType) {
                                is KeywordTypeNode -> primKw[et.kind] ?: return null
                                is TypeReference -> subst[(et.typeName as? Identifier)?.text] ?: return null
                                else -> return null
                            }
                        } else {
                            typeName = when (t) {
                                is KeywordTypeNode -> primKw[t.kind] ?: return null
                                is TypeReference -> subst[(t.typeName as? Identifier)?.text] ?: return null
                                else -> return null
                            }
                        }
                        ParamSpec(pn, typeName, rest, p.questionToken)
                    }
                }
                return CtorInfo(overloads, overloads.size)
            }

            fun argPrim(e: Expression): String? = when (e) {
                is StringLiteralNode -> "string"
                is NumericLiteralNode -> "number"
                is Identifier -> when (e.text) { "true", "false" -> "boolean"; else -> null }
                else -> null
            }
            fun arityFits(ps: List<ParamSpec>, n: Int): Boolean {
                val restIdx = ps.indexOfFirst { it.isRest }
                val minCount = ps.count { !it.isRest && !it.isOptional }
                return if (restIdx >= 0) n >= minCount else n in minCount..ps.size
            }
            // first (argIndex, argType, paramType) mismatch or null
            fun firstMismatch(ps: List<ParamSpec>, args: List<String>): Triple<Int, String, String>? {
                val restIdx = ps.indexOfFirst { it.isRest }
                for ((i, a) in args.withIndex()) {
                    val pt = if (restIdx >= 0 && i >= restIdx) ps[restIdx].type
                    else ps.getOrNull(i)?.type ?: return null
                    if (a != pt) return Triple(i, a, pt)
                }
                return null
            }
            fun paramsDisplay(ps: List<ParamSpec>): String = ps.joinToString(", ") { p ->
                val prefix = if (p.isRest) "..." else ""
                val opt = if (p.isOptional) "?" else ""
                val t = if (p.isRest) "${p.type}[]" else p.type
                "$prefix${p.name}$opt: $t"
            }

            for (stmt in result.sourceFile.statements) {
                val ne = (stmt as? ExpressionStatement)?.expression as? NewExpression ?: continue
                val calleeId = ne.expression as? Identifier ?: continue
                if (!ne.typeArguments.isNullOrEmpty() || !ne.leadingTypeArguments.isNullOrEmpty()) continue
                val cls = classes[calleeId.text] ?: continue
                if (cls.members.any { it is Constructor }) continue  // own ctor → main path owns it
                if (!cls.typeParameters.isNullOrEmpty()) continue
                val info = resolveCtor(cls) ?: continue
                val callArgs = ne.arguments ?: continue
                val argTypesOrNull = callArgs.map { argPrim(it) }
                if (argTypesOrNull.any { it == null }) continue
                val argTypes = argTypesOrNull.filterNotNull()
                val applicable = info.overloads.withIndex().filter { arityFits(it.value, argTypes.size) }
                if (applicable.isEmpty()) continue
                val mismatches = applicable.map { it to firstMismatch(it.value, argTypes) }
                if (mismatches.any { it.second == null }) continue  // some overload matches
                if (applicable.size == 1) {
                    val (idx, argT, paramT) = mismatches[0].second!!
                    val argNode = callArgs[idx]
                    val len = when (argNode) {
                        is StringLiteralNode -> (argNode.rawText?.length ?: argNode.text.length) + 2
                        is NumericLiteralNode -> argNode.text.length
                        is Identifier -> argNode.text.length
                        else -> 1
                    }
                    val (line, ch) = getLineAndCharacterOfPosition(source, argNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '$argT' is not assignable to parameter of type '$paramT'.",
                        category = DiagnosticCategory.Error, code = 2345,
                        fileName = fileName, line = line, character = ch,
                        start = argNode.pos, length = len,
                    ))
                } else {
                    val chain = mutableListOf<String>()
                    for ((iv, mm) in mismatches) {
                        val (_, argT, paramT) = mm!!
                        chain.add("  Overload ${iv.index + 1} of ${info.total}, " +
                            "'(${paramsDisplay(iv.value)}): ${calleeId.text}', gave the following error.")
                        chain.add("    Argument of type '$argT' is not assignable to parameter of type '$paramT'.")
                    }
                    val (line, ch) = getLineAndCharacterOfPosition(source, calleeId.pos)
                    diagnostics.add(Diagnostic(
                        message = "No overload matches this call.",
                        category = DiagnosticCategory.Error, code = 2769,
                        fileName = fileName, line = line, character = ch,
                        start = calleeId.pos, length = calleeId.text.length,
                        messageChain = chain,
                    ))
                }
            }
        }
    }

    /**
     * B263: TS2688 "Cannot find type definition file for 'X'." (file-less, with the
     * "Entry point of type library ... specified in compilerOptions" chain) for each
     * `types` compiler-option entry that resolves under NO typeRoot
     * (typeReferenceDirectiveScopedPackageCustomTypeRoot). Resolution rule: under a
     * typeRoot ending in `@types`, a SCOPED entry `@scope/name` looks up its MANGLED
     * dir `scope__name`; under any other root it looks up the literal dir; non-scoped
     * entries are literal everywhere; the dir resolves iff `<dir>/index.d.ts` is a
     * program file. Side effect: populates [unresolvedTypeLibNames] — top-level names
     * declared ONLY in typeRoot package dirs that did NOT resolve (they are not part
     * of the program; the unresolved-name walk strips them from scope).
     */
    /**
     * INV.4(c)(iii): the [unresolvedTypeLibNames] computation, split out of
     * [checkTypeLibraryEntryPoints] so the unresolved-names file-root scopes can
     * be built at the (earlier) check-spine slot with identical content. Idempotent;
     * pure computation — the TS2688 emission stays at its original pass.
     */
    private fun computeTypeLibResolution() {
        if (typeLibResolutionComputed) return
        typeLibResolutionComputed = true
        val types = options.types ?: return
        val typeRoots = options.typeRoots ?: return
        if (types.isEmpty() || typeRoots.isEmpty()) return
        val fileNames = binderResults.map { it.sourceFile.fileName }.toSet()
        fun resolveDir(root: String, entry: String): String? {
            val r = root.trimEnd('/')
            val dirName = if (entry.startsWith("@") && r.endsWith("@types")) {
                entry.removePrefix("@").replace("/", "__")
            } else entry
            val dir = "$r/$dirName"
            return if ("$dir/index.d.ts" in fileNames) dir else null
        }
        val resolvedDirs = mutableSetOf<String>()
        val unresolved = mutableListOf<String>()
        for (e in types) {
            val dir = typeRoots.firstNotNullOfOrNull { resolveDir(it, e) }
            if (dir != null) resolvedDirs.add(dir) else unresolved.add(e)
        }
        typeLibUnresolvedEntries = unresolved
        // names declared only in unresolved typeRoot packages
        val candidates = mutableSetOf<String>()
        val declaredElsewhere = mutableSetOf<String>()
        for (result in binderResults) {
            val fn = result.sourceFile.fileName
            // longest matching root (roots can nest: /node_modules vs /node_modules/@types)
            val root = typeRoots
                .map { it.trimEnd('/') }
                .filter { fn.startsWith("$it/") }
                .maxByOrNull { it.length }
            if (root == null) {
                // B308: a file under /node_modules/<entry>/ for an UNRESOLVED `types`
                // entry is not part of tsc's program (the entry failed typeRoots
                // resolution; typeReferenceDirectiveWithFailedFromTypeRoot) — its
                // names are strip candidates, not "declared elsewhere".
                if (unresolved.any { e -> "/node_modules/$e/" in fn }) {
                    candidates.addAll(result.locals.keys)
                } else {
                    declaredElsewhere.addAll(result.locals.keys)
                }
                continue
            }
            val segs = fn.removePrefix("$root/").split("/")
            val pkg = if (segs[0].startsWith("@") && segs.size > 1) "${segs[0]}/${segs[1]}" else segs[0]
            if ("$root/$pkg" in resolvedDirs) {
                declaredElsewhere.addAll(result.locals.keys)
            } else {
                candidates.addAll(result.locals.keys)
            }
        }
        unresolvedTypeLibNames = candidates - declaredElsewhere
    }

    private fun checkTypeLibraryEntryPoints() {
        computeTypeLibResolution()
        for (e in typeLibUnresolvedEntries.sorted()) {
            diagnostics.add(Diagnostic(
                message = "Cannot find type definition file for '$e'.",
                category = DiagnosticCategory.Error, code = 2688,
                fileName = null, line = null, character = null, start = -1, length = 0,
                messageChain = listOf(
                    "  The file is in the program because:",
                    "    Entry point of type library '$e' specified in compilerOptions",
                ),
            ))
        }
    }

    /**
     * B262: TS2345 'K | undefined' → 'K' for a JS function-expression param marked
     * OPTIONAL via JSDoc `@param [b]` and contextually typed `K` by a `@type {Fn}`
     * typedef annotation (contextuallyTypedParametersOptionalInJSDoc). All JSDoc
     * facts are RAW-SCANNED from source (typedefs are not parsed/bound anywhere —
     * B148 gotcha): the typedef's fn-type param list gives the contextual K, the
     * bracketed `[b]` gives optionality, and the callee's `@param {K} x` tags give
     * its param types. Straight-line body statements only; bare-Identifier args
     * only; same-primitive match only. checkJs + strictNullChecks gated.
     */
    private fun checkJsDocOptionalContextualParamCalls() {
        if (!options.checkJs || !strictNullChecks) return
        val typedefRe = Regex("""@typedef\s*\{\(([^)]*)\)\s*=>\s*[^}]*\}\s*([A-Za-z_$][\w$]*)""")
        val typeTagRe = Regex("""@type\s*\{([A-Za-z_$][\w$]*)\}""")
        val optParamRe = Regex("""@param\s*(?:\{[^}]*\}\s*)?\[([A-Za-z_$][\w$]*)\]""")
        val paramTagRe = Regex("""@param\s*\{(\w+)\}\s*([A-Za-z_$][\w$]*)""")
        val prims = setOf("number", "string", "boolean", "bigint", "symbol")
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // typedef name -> ordered param prim types (null = non-prim)
            val typedefs = mutableMapOf<String, List<String?>>()
            for (m in typedefRe.findAll(source)) {
                typedefs[m.groupValues[2]] = m.groupValues[1].split(",").map { p ->
                    val t = p.substringAfter(":", "").trim()
                    if (t in prims) t else null
                }
            }
            // top-level fn decls' JSDoc param prim types: fn -> (paramName -> K)
            val calleeParams = mutableMapOf<String, Map<String, String>>()
            for (stmt in result.sourceFile.statements) {
                val fn = stmt as? FunctionDeclaration ?: continue
                val n = fn.name?.text ?: continue
                val tags = mutableMapOf<String, String>()
                fn.leadingComments?.forEach { c ->
                    for (m in paramTagRe.findAll(c.text)) {
                        if (m.groupValues[1] in prims) tags[m.groupValues[2]] = m.groupValues[1]
                    }
                }
                if (tags.isNotEmpty()) calleeParams[n] = tags
            }
            if (typedefs.isEmpty() || calleeParams.isEmpty()) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                // @type {Fn} on the statement
                val typeName = stmt.leadingComments?.firstNotNullOfOrNull {
                    typeTagRe.find(it.text)?.groupValues?.get(1)
                } ?: continue
                val ctxParams = typedefs[typeName] ?: continue
                for (d in stmt.declarationList.declarations) {
                    val fnExpr = d.initializer as? FunctionExpression ?: continue
                    val body = fnExpr.body
                    // bracketed-optional @param names between the statement start and the body
                    val slice = source.substring(
                        stmt.pos.coerceIn(0, source.length),
                        body.pos.coerceIn(0, source.length),
                    )
                    val optionalNames = optParamRe.findAll(slice).map { it.groupValues[1] }.toSet()
                    if (optionalNames.isEmpty()) continue
                    // binding name -> contextual prim K (optional param + contextual prim)
                    val bindings = mutableMapOf<String, String>()
                    for ((i, p) in fnExpr.parameters.withIndex()) {
                        val pn = (p.name as? Identifier)?.text ?: continue
                        if (pn !in optionalNames || p.initializer != null) continue
                        val k = ctxParams.getOrNull(i) ?: continue
                        // a `@param {number} [b]` reaches the AST as type=number via the
                        // primitive JSDoc bridge — accept when it matches the contextual K
                        val astPrim = when ((p.type as? KeywordTypeNode)?.kind) {
                            SyntaxKind.NumberKeyword -> "number"
                            SyntaxKind.StringKeyword -> "string"
                            SyntaxKind.BooleanKeyword -> "boolean"
                            null -> null
                            else -> "?"
                        }
                        if (p.type != null && astPrim != k) continue
                        bindings[pn] = k
                    }
                    if (bindings.isEmpty()) continue
                    for (s in body.statements) {
                        val e = (s as? ExpressionStatement)?.expression ?: break
                        val call = e as? CallExpression ?: continue
                        val calleeName = (call.expression as? Identifier)?.text ?: continue
                        val callee = calleeParams[calleeName] ?: continue
                        for ((i, arg) in call.arguments.withIndex()) {
                            val argId = arg as? Identifier ?: continue
                            val bk = bindings[argId.text] ?: continue
                            // callee's param at this index (by declaration order)
                            val fnDecl = result.sourceFile.statements
                                .filterIsInstance<FunctionDeclaration>()
                                .firstOrNull { it.name?.text == calleeName } ?: continue
                            val paramName = (fnDecl.parameters.getOrNull(i)?.name as? Identifier)?.text
                                ?: continue
                            val pk = callee[paramName] ?: continue
                            if (pk != bk) continue
                            val (line, ch) = getLineAndCharacterOfPosition(source, argId.pos)
                            diagnostics.add(Diagnostic(
                                message = "Argument of type '$bk | undefined' is not assignable to parameter of type '$bk'.",
                                category = DiagnosticCategory.Error, code = 2345,
                                fileName = fileName, line = line, character = ch,
                                start = argId.pos, length = argId.text.length,
                                messageChain = listOf(
                                    "  Type 'undefined' is not assignable to type '$bk'.",
                                ),
                            ))
                        }
                    }
                }
            }
        }
    }

    /**
     * B261: TS2345 'K | undefined' → 'K' for a destructured-param binding of an
     * OPTIONAL property used as a call argument, + TS2322 for a `null` binding
     * default against a primitive member type
     * (optionalParameterInDestructuringWithInitializer). A binding `b` from
     * `{a, b}: {a: number, b?: number}` (no BINDING-level default — a PATTERN-level
     * `= {...}` default does NOT remove the undefined) has type `number | undefined`;
     * passing it where a collected top-level function expects bare `number` errors
     * with the "Type 'undefined' is not assignable" chain. Member lists come from
     * TypeLiteral annotations or bare heritage-free interface refs; nested patterns
     * recurse through TypeLiteral member types. FP firewall: only bare-Identifier
     * args, same-primitive binding/param, and only STRAIGHT-LINE leading body
     * statements (stop at any control-flow statement — it may narrow; a reassignment
     * of the binding drops it). strictNullChecks only.
     */
    private fun checkOptionalDestructuredParamCallArgs() {
        if (!strictNullChecks) return
        val primKinds = setOf(
            SyntaxKind.NumberKeyword, SyntaxKind.StringKeyword, SyntaxKind.BooleanKeyword,
            SyntaxKind.BigIntKeyword, SyntaxKind.SymbolKeyword,
        )
        fun primName(t: TypeNode?): String? = when ((t as? KeywordTypeNode)?.kind) {
            SyntaxKind.NumberKeyword -> "number"
            SyntaxKind.StringKeyword -> "string"
            SyntaxKind.BooleanKeyword -> "boolean"
            SyntaxKind.BigIntKeyword -> "bigint"
            SyntaxKind.SymbolKeyword -> "symbol"
            else -> null
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            // callee -> per-param spec: prim name (bare K), "" (union incl. undefined — accepts), null (unknown)
            val calleeParams = mutableMapOf<String, List<String?>>()
            for (stmt in result.sourceFile.statements) {
                val fn = stmt as? FunctionDeclaration ?: continue
                val n = fn.name?.text ?: continue
                calleeParams[n] = fn.parameters.map { p ->
                    val t = p.type
                    when {
                        t is KeywordTypeNode && t.kind in primKinds -> primName(t)
                        t is UnionType && t.types.any {
                            (it as? KeywordTypeNode)?.kind == SyntaxKind.UndefinedKeyword
                        } -> ""
                        else -> null
                    }
                }
            }
            // resolve a member list from a TypeLiteral or a bare heritage-free interface ref
            fun membersOf(t: TypeNode?): List<PropertyDeclaration>? = when (t) {
                is TypeLiteral -> t.members.filterIsInstance<PropertyDeclaration>()
                    .takeIf { it.size == t.members.size }
                is TypeReference -> {
                    val name = (t.typeName as? Identifier)?.text
                    if (name == null || t.typeArguments != null) null
                    else (globals[name]?.declarations
                        ?.filterIsInstance<InterfaceDeclaration>()
                        ?.singleOrNull()
                        ?.takeIf { it.heritageClauses.isNullOrEmpty() })
                        ?.members?.filterIsInstance<PropertyDeclaration>()
                }
                else -> null
            }
            for (stmt in result.sourceFile.statements) {
                val fn = stmt as? FunctionDeclaration ?: continue
                val body = fn.body ?: continue
                // optional-primitive bindings: name -> prim K
                val bindings = mutableMapOf<String, String>()
                fun collect(pattern: ObjectBindingPattern, members: List<PropertyDeclaration>) {
                    for (el in pattern.elements) {
                        if (el.dotDotDotToken) continue
                        val propName = (el.propertyName as? Identifier)?.text
                            ?: (el.name as? Identifier)?.text ?: continue
                        val member = members.firstOrNull {
                            (it.name as? Identifier)?.text == propName
                        } ?: continue
                        when (val elName = el.name) {
                            is Identifier -> {
                                // `= null` default vs a primitive member type → TS2322
                                val init = el.initializer
                                val k = primName(member.type)
                                if (k != null && init is Identifier && init.text == "null") {
                                    // tsc squiggles the BINDING NAME, not the null initializer
                                    val (line, ch) = getLineAndCharacterOfPosition(source, elName.pos)
                                    diagnostics.add(Diagnostic(
                                        message = "Type 'null' is not assignable to type '$k'.",
                                        category = DiagnosticCategory.Error, code = 2322,
                                        fileName = fileName, line = line, character = ch,
                                        start = elName.pos, length = elName.text.length,
                                    ))
                                }
                                if (init == null && member.questionToken && k != null) {
                                    bindings[elName.text] = k
                                }
                            }
                            is ObjectBindingPattern -> {
                                membersOf(member.type)?.let { collect(elName, it) }
                            }
                            else -> {}
                        }
                    }
                }
                for (p in fn.parameters) {
                    val pattern = p.name as? ObjectBindingPattern ?: continue
                    val members = membersOf(p.type) ?: continue
                    collect(pattern, members)
                }
                if (bindings.isEmpty()) continue
                // straight-line leading statements only
                for (s in body.statements) {
                    val e = when (s) {
                        is ExpressionStatement -> s.expression
                        is ReturnStatement -> s.expression ?: break
                        else -> break
                    }
                    // reassignment of a binding drops it
                    if (e is BinaryExpression && e.operator == SyntaxKind.Equals) {
                        (e.left as? Identifier)?.let { bindings.remove(it.text) }
                        continue
                    }
                    val call = e as? CallExpression ?: continue
                    val calleeName = (call.expression as? Identifier)?.text ?: continue
                    val specs = calleeParams[calleeName] ?: continue
                    for ((i, arg) in call.arguments.withIndex()) {
                        val argId = arg as? Identifier ?: continue
                        val bk = bindings[argId.text] ?: continue
                        val spec = specs.getOrNull(i) ?: continue
                        if (spec != bk) continue  // "" (accepts undefined) or mismatched prim → skip
                        val (line, ch) = getLineAndCharacterOfPosition(source, argId.pos)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '$bk | undefined' is not assignable to parameter of type '$bk'.",
                            category = DiagnosticCategory.Error, code = 2345,
                            fileName = fileName, line = line, character = ch,
                            start = argId.pos, length = argId.text.length,
                            messageChain = listOf(
                                "  Type 'undefined' is not assignable to type '$bk'.",
                            ),
                        ))
                    }
                }
            }
        }
    }

    /**
     * B260: use-before-declaration in DECORATOR expressions + default-mode TS7006 for
     * decorated parameters (decoratorUsedBeforeDeclaration). Decorators evaluate at
     * class-definition time, so a decorator referencing a top-level const/let or enum
     * declared LATER is TS2448/TS2450 (+TS2728 related). Position-dependent extras
     * (straight from the baseline): the CLASS decorator's const callee ALSO gets
     * TS2454 (the const's assignment has definitely not run at class-definition
     * time); an `Enum.Member` decorator ARG gets TS2729 (+related) ONLY on PROPERTY
     * decorators (tsc quirk — class/method/param decorator args get only the
     * TS2450). A parameter carrying decorators with no annotation/initializer gets
     * TS7006 even in pure-default mode — emitted here only when the full
     * implicit-any walker is OFF (mirrors checkImplicitAnyDefaultVarFunctions's
     * gate) to avoid double-emit.
     */
    /**
     * B354: uncalled-decorator signature checking (tsc isPotentiallyUncalledDecorator +
     * getDecoratorArgumentCount + the decorator-call return-type rules). For a
     * BARE-IDENTIFIER decorator `@f` resolving to in-file `declare function` overloads:
     *  - TS1329 when EVERY signature has minArgumentCount 0, no rest param, and fewer
     *    declared params than the decorator position supplies (class=1, property=2,
     *    method/accessor = sig.params<=2 ? 2 : 3) — span covers `@`+name.
     *  - otherwise (single all-`any`-param signature only — the call definitely
     *    resolves) when the return annotation is an in-file interface that is
     *    call-signatures-only (own call sigs, or heritage ONLY to the lib
     *    ClassDecorator/MethodDecorator/PropertyDecorator/ParameterDecorator types) —
     *    such a type fails the weak-type rule against TypedPropertyDescriptor and is
     *    never void/typeof-Class: class → TS1270 'void | typeof <C>', property →
     *    TS1271, method → TS1270 'void | TypedPropertyDescriptor<sig>' — span covers
     *    the expression only (no `@`). Accessors/parameters and called decorators skip.
     */
    private fun checkPotentiallyUncalledDecorators() {
        if (!options.experimentalDecorators) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val funcs = mutableMapOf<String, MutableList<FunctionDeclaration>>()
            val ifaces = mutableMapOf<String, MutableList<InterfaceDeclaration>>()
            val otherValueNames = mutableSetOf<String>()
            for (s in stmts) when (s) {
                is FunctionDeclaration -> s.name?.text?.let { funcs.getOrPut(it) { mutableListOf() }.add(s) }
                is InterfaceDeclaration -> ifaces.getOrPut(s.name.text) { mutableListOf() }.add(s)
                is VariableStatement -> for (d in s.declarationList.declarations) {
                    (d.name as? Identifier)?.text?.let { otherValueNames.add(it) }
                }
                is ClassDeclaration -> s.name?.text?.let { otherValueNames.add(it) }
                is EnumDeclaration -> otherValueNames.add(s.name.text)
                else -> {}
            }

            fun realParams(f: FunctionDeclaration) = f.parameters.filter {
                !it.isCommentPlaceholder && (it.name as? Identifier)?.text != "this"
            }
            fun minArgs(f: FunctionDeclaration) = realParams(f).takeWhile {
                !it.questionToken && it.initializer == null && !it.dotDotDotToken
            }.size
            fun hasRest(f: FunctionDeclaration) = realParams(f).any { it.dotDotDotToken }

            // kind: 0=class, 1=property, 2=method
            fun argCount(kind: Int, sig: FunctionDeclaration): Int = when (kind) {
                0 -> 1
                1 -> 2
                else -> if (realParams(sig).size <= 2) 2 else 3
            }

            /** Call-signatures-only in-file interface (never assignable to void/typeof
             *  C and fails the weak-type rule vs TypedPropertyDescriptor). */
            fun isCallOnlyDecoratorInterface(name: String): Boolean {
                val decls = ifaces[name] ?: return false
                if (name in otherValueNames || name in funcs) return false
                var anyCallable = false
                for (d in decls) {
                    for (m in d.members) {
                        if (m !is MethodDeclaration || (m.name as? Identifier)?.text != "") return false
                        anyCallable = true
                    }
                    for (h in d.heritageClauses.orEmpty()) for (t in h.types) {
                        val tn = (t.expression as? Identifier)?.text ?: return false
                        if (tn !in setOf("ClassDecorator", "MethodDecorator", "PropertyDecorator", "ParameterDecorator")) return false
                        if (tn in ifaces || tn in otherValueNames || tn in funcs) return false
                        anyCallable = true
                    }
                }
                return anyCallable
            }

            fun renderMethodSig(m: MethodDeclaration): String? {
                if (m.typeParameters != null || m.asteriskToken) return null
                val parts = mutableListOf<String>()
                for (p in m.parameters) {
                    if (p.isCommentPlaceholder) continue
                    val pn = (p.name as? Identifier)?.text ?: return null
                    val pt = oruRenderType(p.type) ?: return null
                    parts.add("$pn${if (p.questionToken) "?" else ""}: $pt")
                }
                val ret = when {
                    m.type != null -> oruRenderType(m.type) ?: return null
                    m.body != null && !bodyHasValueReturn(m.body.statements) -> "void"
                    else -> return null
                }
                return "(${parts.joinToString(", ")}) => $ret"
            }

            fun checkDec(dec: Decorator, kind: Int, className: String?, methodSig: String?) {
                val expr = dec.expression as? Identifier ?: return
                if (expr.text in otherValueNames) return
                val sigs = funcs[expr.text]?.filter { it.body == null } ?: return
                if (sigs.isEmpty()) return
                val uncalled = sigs.all {
                    minArgs(it) == 0 && !hasRest(it) && realParams(it).size < argCount(kind, it)
                }
                if (uncalled) {
                    val atPos = source.lastIndexOf('@', expr.pos.coerceAtMost(source.length - 1))
                    if (atPos < 0) return
                    val (line, ch) = getLineAndCharacterOfPosition(source, atPos)
                    diagnostics.add(Diagnostic(
                        message = "'${expr.text}' accepts too few arguments to be used as a decorator here. Did you mean to call it first and write '@${expr.text}()'?",
                        category = DiagnosticCategory.Error, code = 1329,
                        fileName = fileName, line = line, character = ch,
                        start = atPos, length = expr.pos + expr.text.length - atPos,
                    ))
                    return
                }
                // Return-type check: single signature whose params are all `any`-typed
                // (the synthetic decorator call definitely resolves).
                val sig = sigs.singleOrNull() ?: return
                if (realParams(sig).any { p ->
                        val t = p.type
                        !(t == null || (t is KeywordTypeNode && t.kind == SyntaxKind.AnyKeyword) ||
                            (p.dotDotDotToken && t is ArrayType && (t.elementType as? KeywordTypeNode)?.kind == SyntaxKind.AnyKeyword))
                    }) return
                val ret = sig.type as? TypeReference ?: return
                if (ret.typeArguments != null) return
                val rname = (ret.typeName as? Identifier)?.text ?: return
                if (!isCallOnlyDecoratorInterface(rname)) return
                val (line, ch) = getLineAndCharacterOfPosition(source, expr.pos)
                when (kind) {
                    0 -> {
                        if (className == null) return
                        diagnostics.add(Diagnostic(
                            message = "Decorator function return type '$rname' is not assignable to type 'void | typeof $className'.",
                            category = DiagnosticCategory.Error, code = 1270,
                            fileName = fileName, line = line, character = ch,
                            start = expr.pos, length = expr.text.length,
                        ))
                    }
                    1 -> diagnostics.add(Diagnostic(
                        message = "Decorator function return type is '$rname' but is expected to be 'void' or 'any'.",
                        category = DiagnosticCategory.Error, code = 1271,
                        fileName = fileName, line = line, character = ch,
                        start = expr.pos, length = expr.text.length,
                    ))
                    else -> {
                        if (methodSig == null) return
                        diagnostics.add(Diagnostic(
                            message = "Decorator function return type '$rname' is not assignable to type 'void | TypedPropertyDescriptor<$methodSig>'.",
                            category = DiagnosticCategory.Error, code = 1270,
                            fileName = fileName, line = line, character = ch,
                            start = expr.pos, length = expr.text.length,
                        ))
                    }
                }
            }

            for (s in stmts) {
                val cls = s as? ClassDeclaration ?: continue
                cls.decorators?.forEach { checkDec(it, 0, cls.name?.text, null) }
                for (m in cls.members) when (m) {
                    is PropertyDeclaration -> m.decorators?.forEach { checkDec(it, 1, null, null) }
                    is MethodDeclaration -> {
                        val sigRender = renderMethodSig(m)
                        m.decorators?.forEach { checkDec(it, 2, null, sigRender) }
                    }
                    else -> {}
                }
            }
        }
    }

    /** True when any return statement in the (non-nested-function) body carries an expression. */
    private fun bodyHasValueReturn(stmts: List<Statement>): Boolean {
        for (s in stmts) {
            when (s) {
                is ReturnStatement -> if (s.expression != null) return true
                is IfStatement -> {
                    if (bodyHasValueReturn(listOf(s.thenStatement))) return true
                    if (s.elseStatement != null && bodyHasValueReturn(listOf(s.elseStatement))) return true
                }
                is Block -> if (bodyHasValueReturn(s.statements)) return true
                is WhileStatement -> if (bodyHasValueReturn(listOf(s.statement))) return true
                is ForStatement -> if (bodyHasValueReturn(listOf(s.statement))) return true
                is TryStatement -> {
                    if (bodyHasValueReturn(s.tryBlock.statements)) return true
                    if (s.catchClause?.block?.statements?.let { bodyHasValueReturn(it) } == true) return true
                    if (s.finallyBlock?.statements?.let { bodyHasValueReturn(it) } == true) return true
                }
                else -> {}
            }
        }
        return false
    }

    private fun checkDecoratorUseBeforeDeclaration() {
        val emit7006 = !(options.noImplicitAny || options.strict) && !options.strictExplicitlyFalse
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            // top-level block-scoped value decls + enums
            class BlockDecl(val namePos: Int, val isConst: Boolean, val hasInit: Boolean)
            val blockDecls = mutableMapOf<String, BlockDecl>()
            val enums = mutableMapOf<String, EnumDeclaration>()
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is VariableStatement -> {
                        val flags = stmt.declarationList.flags
                        if (flags != SyntaxKind.ConstKeyword && flags != SyntaxKind.LetKeyword) continue
                        for (d in stmt.declarationList.declarations) {
                            val n = d.name as? Identifier ?: continue
                            blockDecls[n.text] = BlockDecl(
                                n.pos, flags == SyntaxKind.ConstKeyword, d.initializer != null)
                        }
                    }
                    is EnumDeclaration -> enums[stmt.name.text] = stmt
                    else -> {}
                }
            }
            if (blockDecls.isEmpty() && enums.isEmpty()) continue

            // kind: 0=class, 1=property, 2=method/accessor, 3=parameter
            fun checkDecorator(dec: Decorator, kind: Int) {
                val expr = dec.expression
                val callee: Identifier?
                val args: List<Expression>
                when (expr) {
                    is CallExpression -> { callee = expr.expression as? Identifier; args = expr.arguments }
                    is Identifier -> { callee = expr; args = emptyList() }
                    else -> return
                }
                if (callee != null) {
                    val bd = blockDecls[callee.text]
                    if (bd != null && bd.namePos > callee.pos) {
                        emitTS2448(callee, bd.namePos, callee.text, source, fileName, isConst = bd.isConst)
                        if (kind == 0 && strictNullChecks && bd.hasInit && bd.isConst) {
                            // class decorators flow-evaluate before the const's assignment
                            val (line, ch) = getLineAndCharacterOfPosition(source, callee.pos)
                            diagnostics.add(Diagnostic(
                                message = "Variable '${callee.text}' is used before being assigned.",
                                category = DiagnosticCategory.Error, code = 2454,
                                fileName = fileName, line = line, character = ch,
                                start = callee.pos, length = callee.text.length,
                            ))
                        }
                    }
                }
                for (arg in args) {
                    val pa = arg as? PropertyAccessExpression ?: continue
                    val root = pa.expression as? Identifier ?: continue
                    val en = enums[root.text] ?: continue
                    if (en.name.pos <= root.pos) continue
                    emitTS2450(root, en.name.pos, root.text, source, fileName)
                    if (kind == 1) {
                        val member = en.members.firstOrNull {
                            (it.name as? Identifier)?.text == pa.name.text
                        } ?: continue
                        emitTS2729CrossClass(
                            pa.name, pa.name.text, (member.name as Identifier).pos, source, fileName)
                    }
                }
            }

            fun checkParams(params: List<Parameter>) {
                for (p in params) {
                    p.decorators?.forEach { checkDecorator(it, 3) }
                    if (emit7006 && !p.decorators.isNullOrEmpty() && p.type == null &&
                        p.initializer == null && p.name is Identifier
                    ) {
                        val n = p.name
                        // span covers the WHOLE parameter incl. its decorators
                        // (Parameter.pos is captured before modifiers/decorators)
                        val start = minOf(p.pos, p.decorators.first().pos)
                        val (line, ch) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Parameter '${n.text}' implicitly has an 'any' type.",
                            category = DiagnosticCategory.Error, code = 7006,
                            fileName = fileName, line = line, character = ch,
                            start = start, length = n.pos + n.text.length - start,
                        ))
                    }
                }
            }

            for (stmt in result.sourceFile.statements) {
                val cls = stmt as? ClassDeclaration ?: continue
                cls.decorators?.forEach { checkDecorator(it, 0) }
                for (m in cls.members) {
                    when (m) {
                        is PropertyDeclaration -> m.decorators?.forEach { checkDecorator(it, 1) }
                        is MethodDeclaration -> {
                            m.decorators?.forEach { checkDecorator(it, 2) }
                            checkParams(m.parameters)
                        }
                        is GetAccessor -> {
                            m.decorators?.forEach { checkDecorator(it, 2) }
                            checkParams(m.parameters)
                        }
                        is SetAccessor -> {
                            m.decorators?.forEach { checkDecorator(it, 2) }
                            checkParams(m.parameters)
                        }
                        is Constructor -> checkParams(m.parameters)
                        else -> {}
                    }
                }
            }
        }
    }

    /**
     * B259: TS2315 "Type 'X' is not generic." / TS2304 "Cannot find name 'T'." for
     * JSDoc `@param {...}` type texts in checked JS files
     * (jsdocTypeNongenericInstantiationAttempt). The JSDoc type plumbing is
     * primitive-only (17.62), so these never reach the checker — this is a RAW
     * comment-text scanner over JSDoc blocks: (a) `Name<Arg>` occurrences inside a
     * `@param {...}` brace where Name is one of the non-generic JSDoc wrapper types
     * (Boolean/Void/Undefined/Function/String/Number/Object) and the arg list is a
     * SINGLE identifier (a 2-arg `Object<K,V>` is legal closure-JSDoc) → TS2315 at
     * the occurrence; (b) a brace content that is EXACTLY `fn<T>` where fn is a
     * same-file top-level FunctionDeclaration and T resolves to nothing → TS2304 at
     * the type-arg. Gated to checkJs-checked .js files.
     */
    /** B286: under noImplicitAny, a BARE `Array`/`Promise` in a JSDoc `@type`/
     *  `@return(s)` tag is TS2314 ("Generic type 'Array<T>' requires 1 type
     *  argument(s).") at the name's position inside the comment. `@param` is
     *  excluded — the B5.2 param bridge already routes those through the normal
     *  TS2314 walker. Raw-source scan (the JSDoc tags are not parsed/bound). */
    private fun checkJsDocBareGenericTags() {
        if (!options.checkJs) return
        if (!(options.noImplicitAny || options.strict)) return
        val jsdocBlock = Regex("""/\*\*[\s\S]*?\*/""")
        val tag = Regex("""@(?:type|returns?)\s*\{\s*(Array|Promise)\s*\}""")
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (block in jsdocBlock.findAll(source)) {
                for (m in tag.findAll(block.value)) {
                    val name = m.groupValues[1]
                    val nameRel = m.value.indexOf(name)
                    val start = block.range.first + m.range.first + nameRel
                    val (line, ch) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Generic type '$name<T>' requires 1 type argument(s).",
                        category = DiagnosticCategory.Error, code = 2314,
                        fileName = fileName, line = line, character = ch,
                        start = start, length = name.length,
                    ))
                }
            }
        }
    }

    /** B437d: TS1098 + TS1139 for an empty type-parameter list in a JSDoc `@param` type
     *  (`@param {<} x` → jsdocFunctionTypeFalsePositive). tsc parses the JSDoc type and the
     *  grammar parser reports the empty `<` type-param list. Raw-source scan over JSDoc
     *  blocks (the JSDoc type plumbing is primitive-only). FP firewall: the `{<}` shape is
     *  corpus-unique (jsdocTypeNongenericInstantiationAttempt has `{<T>...}`, not empty). */
    private fun checkJsDocEmptyTypeParamList() {
        val jsdocBlock = Regex("""/\*\*[\s\S]*?\*/""")
        val pat = Regex("""@param\s*\{\s*<\s*\}""")
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (block in jsdocBlock.findAll(source)) {
                for (m in pat.findAll(block.value)) {
                    val ltRel = block.value.indexOf('<', m.range.first)
                    val braceRel = block.value.indexOf('}', ltRel)
                    if (ltRel < 0 || braceRel < 0) continue
                    val ltPos = block.range.first + ltRel
                    val bracePos = block.range.first + braceRel
                    val (l1, c1) = getLineAndCharacterOfPosition(source, ltPos)
                    diagnostics.add(Diagnostic(
                        message = "Type parameter list cannot be empty.",
                        category = DiagnosticCategory.Error, code = 1098,
                        fileName = fileName, line = l1, character = c1,
                        start = ltPos, length = bracePos - ltPos + 1,
                    ))
                    val (l2, c2) = getLineAndCharacterOfPosition(source, bracePos)
                    diagnostics.add(Diagnostic(
                        message = "Type parameter declaration expected.",
                        category = DiagnosticCategory.Error, code = 1139,
                        fileName = fileName, line = l2, character = c2,
                        start = bracePos, length = 1,
                    ))
                }
            }
        }
    }

    /**
     * Is the heritage base `baseName` at [beforePos] governed by an `@augments`/`@extends`
     * JSDoc tag? Scans backward to the nearest preceding `/** ... */` block and tests whether
     * it carries a tag naming exactly this base. Used to suppress TS8026 in favor of the tag's
     * own TS2314 (checkJsDocExtendsTags).
     */
    private fun hasGoverningExtendsTag(source: String, baseName: String, beforePos: Int): Boolean {
        val closeIdx = srcLastIndexOf(source, "*/", beforePos.coerceIn(0, source.length))
        if (closeIdx < 0) return false
        val openIdx = srcLastIndexOf(source, "/**", closeIdx)
        if (openIdx < 0) return false
        val block = source.substring(openIdx, closeIdx + 2)
        return Regex("""@(?:augments|extends)\s+""" + Regex.escape(baseName) + """\b""").containsMatchIn(block)
    }

    /**
     * JS files: an `@augments`/`@extends <Base>` JSDoc tag SUPPLIES heritage type arguments for the
     * following class. When the arg count in the tag does not match the base's required type-param
     * count, tsc emits TS2314 at the TAG position (the base name, or the whole `Base<...>` span when
     * args are present), NOT TS8026 at the `extends` clause (jsExtendsImplicitAny). The companion
     * suppression lives in checkHeritageTypeArgCount via hasGoverningExtendsTag.
     */
    private fun checkJsDocExtendsTags() {
        if (!options.checkJs) return
        if (!(options.noImplicitAny || options.strict)) return
        val jsdocBlock = Regex("""/\*\*[\s\S]*?\*/""")
        val tag = Regex("""@(?:augments|extends)\s+([A-Za-z_$][A-Za-z0-9_$]*)""")
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (block in jsdocBlock.findAll(source)) {
                val m = tag.find(block.value) ?: continue
                val nameGroup = m.groups[1] ?: continue
                val baseName = nameGroup.value
                val nameRel = nameGroup.range.first
                // Compute the provided type-arg count and the full tag span (name [+ <...>]).
                var spanEndRel = nameGroup.range.last + 1
                var providedCount = 0
                var j = spanEndRel
                while (j < block.value.length && block.value[j].isWhitespace()) j++
                if (j < block.value.length && block.value[j] == '<') {
                    var depth = 0
                    var k = j
                    while (k < block.value.length) {
                        when (block.value[k]) {
                            '<' -> depth++
                            '>' -> { depth--; if (depth == 0) { k++; break } }
                        }
                        k++
                    }
                    spanEndRel = k
                    val inner = block.value.substring(j + 1, (spanEndRel - 1).coerceAtLeast(j + 1))
                    if (inner.isNotBlank()) {
                        var d = 0; var cnt = 1
                        for (c in inner) when (c) { '<' -> d++; '>' -> d--; ',' -> if (d == 0) cnt++ }
                        providedCount = cnt
                    }
                }
                val info = getTypeParamInfo(baseName) ?: continue
                if (info.maxTotal == 0) continue
                if (info.minRequired != info.maxTotal) continue
                if (providedCount == info.maxTotal) continue
                val start = block.range.first + nameRel
                val length = spanEndRel - nameRel
                val (line, ch) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
                    category = DiagnosticCategory.Error, code = 2314,
                    fileName = fileName, line = line, character = ch,
                    start = start, length = length,
                ))
            }
        }
    }

    private fun checkJsDocNongenericInstantiation() {
        if (!options.checkJs) return
        val nonGenericWrappers = setOf("Boolean", "Void", "Undefined", "Function", "String", "Number", "Object")
        // [\s\S] instead of DOT_MATCHES_ALL — that RegexOption is JVM-only (commonMain)
        val jsdocBlock = Regex("""/\*\*[\s\S]*?\*/""")
        val paramTag = Regex("""@param\s*\{""")
        val instantiation = Regex("""([A-Za-z_$][A-Za-z0-9_$]*)<\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*>""")
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val topLevelFns = result.sourceFile.statements
                .filterIsInstance<FunctionDeclaration>()
                .filter { it.typeParameters.isNullOrEmpty() }
                .mapNotNull { it.name?.text }.toSet()
            val topLevelTypeNames = result.sourceFile.statements.mapNotNull {
                when (it) {
                    is ClassDeclaration -> it.name?.text
                    is InterfaceDeclaration -> it.name.text
                    is TypeAliasDeclaration -> it.name.text
                    is EnumDeclaration -> it.name.text
                    else -> null
                }
            }.toSet()
            for (block in jsdocBlock.findAll(source)) {
                for (tag in paramTag.findAll(block.value)) {
                    // balanced-brace content
                    val openRel = tag.range.last
                    var depth = 0
                    var closeRel = -1
                    var i = openRel
                    while (i < block.value.length) {
                        when (block.value[i]) {
                            '{' -> depth++
                            '}' -> { depth--; if (depth == 0) { closeRel = i; break } }
                        }
                        i++
                    }
                    if (closeRel < 0) continue
                    val content = block.value.substring(openRel + 1, closeRel)
                    val contentAbs = block.range.first + openRel + 1
                    var emitted = false
                    for (m in instantiation.findAll(content)) {
                        val name = m.groupValues[1]
                        if (name !in nonGenericWrappers) continue
                        val start = contentAbs + m.range.first
                        val (line, ch) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Type '$name' is not generic.",
                            category = DiagnosticCategory.Error, code = 2315,
                            fileName = fileName, line = line, character = ch,
                            start = start, length = m.value.length,
                        ))
                        emitted = true
                    }
                    if (emitted) continue
                    // (b) whole-content `fn<T>` with fn a local non-generic function
                    val whole = Regex("""^\s*([A-Za-z_$][A-Za-z0-9_$]*)<\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*>\s*$""")
                        .find(content) ?: continue
                    val fnName = whole.groupValues[1]
                    val argName = whole.groupValues[2]
                    if (fnName !in topLevelFns) continue
                    if (argName in topLevelTypeNames || argName in KNOWN_GLOBALS) continue
                    val argRel = content.indexOf('<', whole.range.first).let { lt ->
                        var j = lt + 1
                        while (j < content.length && content[j].isWhitespace()) j++
                        j
                    }
                    val start = contentAbs + argRel
                    val (line, ch) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot find name '$argName'.",
                        category = DiagnosticCategory.Error, code = 2304,
                        fileName = fileName, line = line, character = ch,
                        start = start, length = argName.length,
                    ))
                }
            }
        }
    }

    /**
     * B258: TS2858 "Import attribute values must be string literal expressions." +
     * the per-clause TS2322 vs 'ImportAttributes' (importAssertionNonstring). The
     * parser stores the `with {...}` clause as RAW TEXT (+ pos), so this is a
     * raw-text mini-scanner: entries split at top-level commas, each `key: value`;
     * any value that is not a complete string literal gets TS2858 at the value span.
     * A SINGLE-entry clause whose value classifies to a definitely-non-string type
     * (plain number / regex / array of same-primitive literals / object of
     * primitive-literal props) additionally gets TS2322 at the whole clause span
     * with the "Property 'k' is incompatible with index signature." chain
     * (template literals and `0..toString()`-style calls are string-typed — TS2858
     * only). Unparseable shapes bail (FN, never FP).
     */
    private fun checkImportAttributeValues() {
        // (display-unwidened, display-widened) or null when not definitely-non-string
        fun classifyNonString(v: String): Pair<String, String>? {
            if (v.matches(Regex("^\\d+(\\.\\d+)?$"))) return v to "number"
            if (v.startsWith("/") && v.length > 1) return "RegExp" to "RegExp"
            if (v.startsWith("[") && v.endsWith("]")) {
                val inner = v.substring(1, v.length - 1).trim()
                if (inner.isEmpty()) return null
                val elems = inner.split(",").map { it.trim() }
                val allString = elems.all { it.length >= 2 && (it[0] == '"' || it[0] == '\'') }
                val allNumber = elems.all { it.matches(Regex("^\\d+(\\.\\d+)?$")) }
                return when {
                    allString -> "string[]" to "string[]"
                    allNumber -> "number[]" to "number[]"
                    else -> null
                }
            }
            if (v.startsWith("{") && v.endsWith("}")) {
                val inner = v.substring(1, v.length - 1).trim()
                if (inner.isEmpty()) return null
                val props = mutableListOf<String>()
                for (entry in inner.split(",")) {
                    val ci = entry.indexOf(':')
                    if (ci < 0) return null
                    val k = entry.substring(0, ci).trim()
                    val pv = entry.substring(ci + 1).trim()
                    val pt = when {
                        pv.matches(Regex("^\\d+(\\.\\d+)?$")) -> "number"
                        pv.length >= 2 && (pv[0] == '"' || pv[0] == '\'') -> "string"
                        else -> return null
                    }
                    if (!k.matches(Regex("^[A-Za-z_$][A-Za-z0-9_$]*$"))) return null
                    props.add("$k: $pt;")
                }
                val display = "{ ${props.joinToString(" ")} }"
                return display to display
            }
            return null
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                val (clause, clausePos) = when (stmt) {
                    is ImportDeclaration -> (stmt.assertClause ?: continue) to stmt.assertClausePos
                    else -> continue
                }
                if (clausePos < 0 || !clause.startsWith("with")) continue
                val braceRel = clause.indexOf('{')
                if (braceRel < 0 || !clause.endsWith("}")) continue
                val body = clause.substring(braceRel + 1, clause.length - 1)
                // split entries at top-level commas (track quotes + nesting)
                val entryOffsets = mutableListOf<Pair<Int, String>>()  // (rel offset of entry start, text)
                run {
                    var depth = 0
                    var i = 0
                    var start = 0
                    var quote: Char? = null
                    while (i < body.length) {
                        val c = body[i]
                        when {
                            quote != null -> if (c == quote && body.getOrNull(i - 1) != '\\') quote = null
                            c == '"' || c == '\'' || c == '`' -> quote = c
                            c == '{' || c == '[' || c == '(' -> depth++
                            c == '}' || c == ']' || c == ')' -> depth--
                            c == ',' && depth == 0 -> {
                                entryOffsets.add(start to body.substring(start, i))
                                start = i + 1
                            }
                        }
                        i++
                    }
                    if (quote != null) return@run
                    entryOffsets.add(start to body.substring(start))
                }
                var singleEntryNonString: Triple<String, String, String>? = null  // key, raw display, widened
                var parsedOk = true
                val valueEmits = mutableListOf<Pair<Int, Int>>()  // (abs pos, len) for TS2858
                for ((entryStart, entryText) in entryOffsets) {
                    val ci = entryText.indexOf(':')
                    if (ci < 0) { parsedOk = false; break }
                    val key = entryText.substring(0, ci).trim()
                    if (!key.matches(Regex("^[A-Za-z_$][A-Za-z0-9_$]*$"))) { parsedOk = false; break }
                    val valueRaw = entryText.substring(ci + 1)
                    val value = valueRaw.trim()
                    if (value.isEmpty()) { parsedOk = false; break }
                    val isStringLit = value.length >= 2 &&
                        (value[0] == '"' || value[0] == '\'') && value.last() == value[0]
                    if (isStringLit) continue
                    val leadingWs = valueRaw.length - valueRaw.trimStart().length
                    val absValuePos = clausePos + braceRel + 1 + entryStart + ci + 1 + leadingWs
                    valueEmits.add(absValuePos to value.length)
                    if (entryOffsets.size == 1) {
                        classifyNonString(value)?.let { (raw, widened) ->
                            singleEntryNonString = Triple(key, raw, widened)
                        }
                    }
                }
                if (!parsedOk) continue
                singleEntryNonString?.let { (key, raw, widened) ->
                    val (line, ch) = getLineAndCharacterOfPosition(source, clausePos)
                    diagnostics.add(Diagnostic(
                        message = "Type '{ $key: $raw; }' is not assignable to type 'ImportAttributes'.",
                        category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = line, character = ch,
                        start = clausePos, length = clause.length,
                        messageChain = listOf(
                            "  Property '$key' is incompatible with index signature.",
                            "    Type '$widened' is not assignable to type 'string'.",
                        ),
                    ))
                }
                for ((pos, len) in valueEmits) {
                    val (line, ch) = getLineAndCharacterOfPosition(source, pos)
                    diagnostics.add(Diagnostic(
                        message = "Import attribute values must be string literal expressions.",
                        category = DiagnosticCategory.Error, code = 2858,
                        fileName = fileName, line = line, character = ch,
                        start = pos, length = len,
                    ))
                }
            }
        }
    }

    /**
     * B257: TS2531/TS2532/TS2533 (+TS2488/TS2461 for array patterns) for destructuring
     * a definitely-nullish source with an EMPTY pattern (strictNullEmptyDestructuring):
     * `let { } = null` / `({} = undefined)` / `let { } = cond ? {} : null`. Source
     * nullishness is classified purely from the AST: `null` / `undefined` identifiers,
     * empty object literal (passes), or a ConditionalExpression whose branches
     * classify recursively; ANY unknown shape bails. EMPTY patterns only (non-empty
     * would need per-property errors). An empty ARRAY pattern first gets the
     * not-iterable/not-array error — TS2488 at target>=ES2015, TS2461 below — then
     * the nullish error at the same span.
     */
    private fun checkEmptyDestructuringNullishSource() {
        if (!strictNullChecks) return
        // bit 1 = null, bit 2 = undefined; 0 = non-nullish OK shape; -1 = unknown (bail)
        fun classify(e: Expression): Int = when {
            e is Identifier && e.text == "null" -> 1
            e is Identifier && e.text == "undefined" -> 2
            e is ObjectLiteralExpression && e.properties.isEmpty() -> 0
            e is ParenthesizedExpression -> classify(e.expression)
            e is ConditionalExpression -> {
                val a = classify(e.whenTrue)
                val b = classify(e.whenFalse)
                if (a < 0 || b < 0) -1 else a or b
            }
            else -> -1
        }
        fun nullishMessage(bits: Int): Pair<String, Int>? = when (bits) {
            1 -> "Object is possibly 'null'." to 2531
            2 -> "Object is possibly 'undefined'." to 2532
            3 -> "Object is possibly 'null' or 'undefined'." to 2533
            else -> null
        }
        // span = pattern open bracket .. matching close bracket inclusive
        fun bracketSpan(source: String, pos: Int, open: Char, close: Char): Pair<Int, Int>? {
            // a CHAR search: below `SourceScanFilter.K`, so the round-895 filter
            // has nothing to say about it and this stays a direct scan
            val start = source.indexOf(open, pos)
            if (start < 0) return null
            var depth = 0
            var i = start
            while (i < source.length) {
                when (source[i]) {
                    open -> depth++
                    close -> { depth--; if (depth == 0) return start to (i + 1 - start) }
                }
                i++
            }
            return null
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            fun emitAt(start: Int, length: Int, message: String, code: Int) {
                val (line, ch) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = message, category = DiagnosticCategory.Error, code = code,
                    fileName = fileName, line = line, character = ch,
                    start = start, length = length,
                ))
            }
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is VariableStatement -> for (d in stmt.declarationList.declarations) {
                        if (d.type != null) continue
                        val init = d.initializer ?: continue
                        val bits = classify(init)
                        val msg = nullishMessage(bits) ?: continue
                        when (val name = d.name) {
                            is ObjectBindingPattern -> {
                                if (name.elements.isNotEmpty()) continue
                                val (start, len) = bracketSpan(source, name.pos, '{', '}') ?: continue
                                emitAt(start, len, msg.first, msg.second)
                            }
                            is ArrayBindingPattern -> {
                                if (name.elements.isNotEmpty()) continue
                                val (start, len) = bracketSpan(source, name.pos, '[', ']') ?: continue
                                // pure-null / pure-undefined sources only for the iterability error
                                val display = when (bits) { 1 -> "null"; 2 -> "undefined"; else -> null }
                                if (display != null) {
                                    if (options.defaultedTarget >= ScriptTarget.ES2015) {
                                        emitAt(start, len,
                                            "Type '$display' must have a '[Symbol.iterator]()' method that returns an iterator.", 2488)
                                    } else {
                                        emitAt(start, len, "Type '$display' is not an array type.", 2461)
                                    }
                                }
                                emitAt(start, len, msg.first, msg.second)
                            }
                            else -> {}
                        }
                    }
                    is ExpressionStatement -> {
                        var e = stmt.expression
                        while (e is ParenthesizedExpression) e = e.expression
                        val b = e as? BinaryExpression ?: continue
                        if (b.operator != SyntaxKind.Equals) continue
                        val lhs = b.left as? ObjectLiteralExpression ?: continue
                        if (lhs.properties.isNotEmpty()) continue
                        val msg = nullishMessage(classify(b.right)) ?: continue
                        val (start, len) = bracketSpan(source, lhs.pos, '{', '}') ?: continue
                        emitAt(start, len, msg.first, msg.second)
                    }
                    else -> {}
                }
            }
        }
    }

    /**
     * B256: TS2322 for an `undefined` DEFAULT in a destructuring ASSIGNMENT against an
     * annotated target variable (destructuringAssignmentWithDefault2):
     * `({ x = undefined } = a)` / `({ x: x = undefined } = a)` where `x: number` and
     * `a`'s prop is optional. The shorthand form double-emits (tsc): first
     * `'<prop> | undefined' is not assignable` + undefined chain line (the value WITH
     * the useless default still includes undefined), then the bare
     * `'undefined' is not assignable` for the default expression itself; the longhand
     * form emits only the latter, at the TARGET identifier. Gates: top-level
     * paren-wrapped object-destructuring assignment, RHS Identifier resolving to a
     * Type.Object, default literally `undefined`, target var annotated with a
     * primitive keyword, strictNullChecks. Anything else silent.
     */
    private fun checkDestructuringAssignmentUndefinedDefaults() {
        if (!strictNullChecks) return
        val primKeywords = mapOf(
            SyntaxKind.NumberKeyword to "number", SyntaxKind.StringKeyword to "string",
            SyntaxKind.BooleanKeyword to "boolean", SyntaxKind.BigIntKeyword to "bigint",
            SyntaxKind.SymbolKeyword to "symbol",
        )
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            // annotated `let/var/const <name>: <prim keyword>` targets
            val varAnn = mutableMapOf<String, String>()
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val n = (d.name as? Identifier)?.text ?: continue
                    val kw = (d.type as? KeywordTypeNode)?.kind ?: continue
                    primKeywords[kw]?.let { varAnn[n] = it }
                }
            }
            if (varAnn.isEmpty()) continue
            for (stmt in result.sourceFile.statements) {
                var e = (stmt as? ExpressionStatement)?.expression ?: continue
                while (e is ParenthesizedExpression) e = e.expression
                val b = e as? BinaryExpression ?: continue
                if (b.operator != SyntaxKind.Equals) continue
                val pattern = b.left as? ObjectLiteralExpression ?: continue
                val rhs = b.right as? Identifier ?: continue
                val rhsType = (getTypeOfExpression(rhs))
                    as? Type.Object ?: continue
                if (rhsType is Type.Reference) continue
                resolveStructuredTypeMembers(rhsType)
                for (prop in pattern.properties) {
                    // (propName-in-source, targetName, targetNode, isShorthand)
                    val (propName, targetIdent, isShorthand) = when (prop) {
                        is ShorthandPropertyAssignment -> {
                            val def = prop.objectAssignmentInitializer
                            if (def !is Identifier || def.text != "undefined") continue
                            Triple(prop.name.text, prop.name, true)
                        }
                        is PropertyAssignment -> {
                            val inner = prop.initializer as? BinaryExpression ?: continue
                            if (inner.operator != SyntaxKind.Equals) continue
                            val target = inner.left as? Identifier ?: continue
                            val def = inner.right as? Identifier ?: continue
                            if (def.text != "undefined") continue
                            val pn = (prop.name as? Identifier)?.text ?: continue
                            Triple(pn, target, false)
                        }
                        else -> continue
                    }
                    val targetTypeName = varAnn[targetIdent.text] ?: continue
                    val propSym = rhsType.members?.get(propName) ?: continue
                    val propType = getTypeOfSymbol(propSym)
                    val propDisplay = (propType as? Type.Intrinsic)?.intrinsicName ?: continue
                    // same-primitive prop/target only — a cross-primitive mismatch would
                    // need different/additional diagnostics (bail, FN-safe)
                    if (propDisplay != targetTypeName) continue
                    val (line, ch) = getLineAndCharacterOfPosition(source, targetIdent.pos)
                    if (isShorthand && isOptionalProperty(propSym)) {
                        diagnostics.add(Diagnostic(
                            message = "Type '$propDisplay | undefined' is not assignable to type '$targetTypeName'.",
                            category = DiagnosticCategory.Error, code = 2322,
                            fileName = fileName, line = line, character = ch,
                            start = targetIdent.pos, length = targetIdent.text.length,
                            messageChain = listOf(
                                "  Type 'undefined' is not assignable to type '$targetTypeName'.",
                            ),
                        ))
                    }
                    diagnostics.add(Diagnostic(
                        message = "Type 'undefined' is not assignable to type '$targetTypeName'.",
                        category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = line, character = ch,
                        start = targetIdent.pos, length = targetIdent.text.length,
                    ))
                }
            }
        }
    }

    /**
     * B279: TS18048 "'X' is possibly 'undefined'." for an OPTIONAL `?: number` parameter
     * used as a direct operand of an arithmetic `+ - * / % **`/shift/bitwise binary op in
     * the LEADING straight-line statements of its own function body (optionalParamArgsTest).
     * Conservative per the B142 model: the scan STOPS at the first control-flow statement
     * (anything that may narrow) and at any reassignment of the param; `&& || ??`,
     * comparisons, conditionals, and call arguments are never descended (FN, never FP —
     * tsc always errors a nullable arithmetic operand under strictNullChecks).
     */
    private fun checkOptionalParamNullishArithmetic() {
        if (!strictNullChecks) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            opnStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun opnStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> stmt.body?.let {
                    opnCheckFn(stmt.parameters, it, source, fileName)
                    opnStmts(it.statements, source, fileName)
                }
                is ClassDeclaration -> for (m in stmt.members) when (m) {
                    is MethodDeclaration -> m.body?.let {
                        opnCheckFn(m.parameters, it, source, fileName)
                        opnStmts(it.statements, source, fileName)
                    }
                    is Constructor -> m.body?.let {
                        opnCheckFn(m.parameters, it, source, fileName)
                        opnStmts(it.statements, source, fileName)
                    }
                    else -> {}
                }
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    when (val init = d.initializer) {
                        is FunctionExpression -> init.body.let {
                            opnCheckFn(init.parameters, it, source, fileName)
                            opnStmts(it.statements, source, fileName)
                        }
                        is ArrowFunction -> (init.body as? Block)?.let {
                            opnCheckFn(init.parameters, it, source, fileName)
                            opnStmts(it.statements, source, fileName)
                        }
                        else -> {}
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { opnStmts(it.statements, source, fileName) }
                else -> {}
            }
        }
    }

    private fun opnCheckFn(params: List<Parameter>, body: Block, source: String, fileName: String) {
        val optional = params.filter { p ->
            p.questionToken && p.initializer == null && !p.dotDotDotToken &&
                (p.type as? KeywordTypeNode)?.kind == SyntaxKind.NumberKeyword
        }.mapNotNull { (it.name as? Identifier)?.text }.toMutableSet()
        if (optional.isEmpty()) return
        for (stmt in body.statements) {
            when (stmt) {
                is ReturnStatement -> stmt.expression?.let { opnExpr(it, optional, source, fileName) }
                is ExpressionStatement -> opnExpr(stmt.expression, optional, source, fileName)
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { opnExpr(it, optional, source, fileName) }
                }
                else -> return // control flow / anything unmodeled may narrow — stop
            }
            if (optional.isEmpty()) return
        }
    }

    private fun opnExpr(expr: Expression, optional: MutableSet<String>, source: String, fileName: String) {
        val arithOps = setOf(
            SyntaxKind.Plus, SyntaxKind.Minus, SyntaxKind.Asterisk, SyntaxKind.Slash,
            SyntaxKind.Percent, SyntaxKind.AsteriskAsterisk,
        )
        var e = expr
        while (e is ParenthesizedExpression) e = e.expression
        when (e) {
            is BinaryExpression -> {
                if (e.operator == SyntaxKind.Equals) {
                    // assignment narrows the param for the rest of the scan
                    (e.left as? Identifier)?.let { optional.remove(it.text) }
                    opnExpr(e.right, optional, source, fileName)
                    return
                }
                if (e.operator !in arithOps) return // narrowing/comparison/logical — don't descend
                fun checkOperand(op: Expression) {
                    var o = op
                    while (o is ParenthesizedExpression) o = o.expression
                    if (o is Identifier && o.text in optional) {
                        val (line, ch) = getLineAndCharacterOfPosition(source, o.pos)
                        diagnostics.add(Diagnostic(
                            message = "'${o.text}' is possibly 'undefined'.",
                            category = DiagnosticCategory.Error, code = 18048,
                            fileName = fileName, line = line, character = ch,
                            start = o.pos, length = o.text.length,
                        ))
                    }
                }
                // iterative left spine over the contiguous arithmetic chain
                var cur: Expression = e
                while (cur is BinaryExpression && cur.operator in arithOps) {
                    checkOperand(cur.right)
                    cur = cur.left
                }
                checkOperand(cur)
            }
            else -> {}
        }
    }

    /**
     * Marks ObjectLiteralExpression nodes (by pos) reachable as destructuring-assignment
     * TARGETS from [target] (the LHS of an `=`), descending through array/object nesting,
     * parens, property defaults (`{ a: a = 1 }` and nested patterns), and spreads.
     * Consumed by the shorthand-with-initializer TS1312/TS18004 selection (B276).
     */
    private fun markDestructuringTargets(target: Expression) {
        when (target) {
            is ParenthesizedExpression -> markDestructuringTargets(target.expression)
            is ObjectLiteralExpression -> {
                if (!destructuringPatternPos.add(target.pos)) return
                for (p in target.properties) when (p) {
                    is PropertyAssignment -> markDestructuringTargets(p.initializer)
                    is SpreadAssignment -> markDestructuringTargets(p.expression)
                    else -> {}
                }
            }
            is ArrayLiteralExpression -> for (e in target.elements) markDestructuringTargets(e)
            is BinaryExpression -> if (target.operator == SyntaxKind.Equals) markDestructuringTargets(target.left)
            is SpreadElement -> markDestructuringTargets(target.expression)
            else -> {}
        }
    }

    /**
     * B276 (round 139): TS2322 for typed-target DEFAULT mismatches in destructuring
     * ASSIGNMENTS (shorthandPropertyAssignmentsInDestructuring family):
     * `({ s3 = 5 } = …)` / `({ s3: s3 = 5 } = …)` / `for ({ s3 = 5 } of …)` where the
     * target var's annotation is a primitive keyword and the default is a literal of a
     * DIFFERENT primitive → TS2322 at the target identifier (tsc checks the default as a
     * plain `name = default` assignment, see checkDestructuringAssignment). A
     * TypeLiteral-annotated target with an object-literal default reports per-property
     * at the offending literal VALUE + related TS6500 at the annotation member (tsc's
     * fresh-literal property check). Scope model: function-local var/let/const
     * annotations collected per body; params shadow (removed); literal-only default
     * typing — anything unrecognized bails (FN, never FP: tsc always errors the
     * matched shape, so a passing test with it already carries the diagnostic).
     */
    private fun checkDestructuringDefaultTypeMismatches() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            dddStmts(result.sourceFile.statements, HashMap(), source, fileName)
        }
    }

    private fun dddPrimName(kind: SyntaxKind): String? = when (kind) {
        SyntaxKind.NumberKeyword -> "number"
        SyntaxKind.StringKeyword -> "string"
        SyntaxKind.BooleanKeyword -> "boolean"
        SyntaxKind.BigIntKeyword -> "bigint"
        else -> null
    }

    private fun dddLiteralPrim(e: Expression): String? = when (e) {
        is NumericLiteralNode -> "number"
        is StringLiteralNode -> "string"
        is NoSubstitutionTemplateLiteralNode -> "string"
        is PrefixUnaryExpression -> (e.operand as? NumericLiteralNode)?.let { "number" }
        is Identifier -> if (e.text == "true" || e.text == "false") "boolean" else null
        else -> null
    }

    private fun dddStmts(stmts: List<Statement>, scope: MutableMap<String, TypeNode>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { dddExpr(it, scope, source, fileName) }
                        val n = (d.name as? Identifier)?.text ?: continue
                        val t = d.type
                        if (t != null) scope[n] = t else scope.remove(n)
                    }
                }
                is ExpressionStatement -> dddExpr(stmt.expression, scope, source, fileName)
                is ReturnStatement -> stmt.expression?.let { dddExpr(it, scope, source, fileName) }
                is Block -> dddStmts(stmt.statements, HashMap(scope), source, fileName)
                is ForOfStatement -> {
                    (stmt.initializer as? Expression)?.let { init ->
                        var e: Expression = init
                        while (e is ParenthesizedExpression) e = e.expression
                        (e as? ObjectLiteralExpression)?.let { dddPattern(it, scope, source, fileName) }
                    }
                    dddExpr(stmt.expression, scope, source, fileName)
                    dddStmts(listOf(stmt.statement), HashMap(scope), source, fileName)
                }
                is FunctionDeclaration -> {
                    val child = HashMap(scope)
                    val pn = mutableSetOf<String>()
                    for (p in stmt.parameters) collectBindingNames(p.name, pn)
                    pn.forEach { child.remove(it) }
                    stmt.body?.let { dddStmts(it.statements, child, source, fileName) }
                }
                else -> {}
            }
        }
    }

    /** Expression walker for B276 — iterative BinaryExpression spine (deep-chain safe). */
    private fun dddExpr(expr: Expression, scope: MutableMap<String, TypeNode>, source: String, fileName: String) {
        val work = ArrayDeque<Expression>()
        work.add(expr)
        while (work.isNotEmpty()) {
            when (val e = work.removeLast()) {
                is ParenthesizedExpression -> work.add(e.expression)
                is BinaryExpression -> {
                    if (e.operator == SyntaxKind.Equals) {
                        var l: Expression = e.left
                        while (l is ParenthesizedExpression) l = l.expression
                        if (l is ObjectLiteralExpression) {
                            dddPattern(l, scope, source, fileName)
                        } else {
                            work.add(e.left)
                        }
                    } else {
                        work.add(e.left)
                    }
                    work.add(e.right)
                }
                is CallExpression -> {
                    work.add(e.expression)
                    e.arguments.forEach { work.add(it) }
                }
                is FunctionExpression -> {
                    val child = HashMap(scope)
                    val pn = mutableSetOf<String>()
                    for (p in e.parameters) collectBindingNames(p.name, pn)
                    pn.forEach { child.remove(it) }
                    e.body.let { dddStmts(it.statements, child, source, fileName) }
                }
                is ArrowFunction -> {
                    val child = HashMap(scope)
                    val pn = mutableSetOf<String>()
                    for (p in e.parameters) collectBindingNames(p.name, pn)
                    pn.forEach { child.remove(it) }
                    when (val b = e.body) {
                        is Block -> dddStmts(b.statements, child, source, fileName)
                        is Expression -> dddExpr(b, child, source, fileName)
                        else -> {}
                    }
                }
                else -> {}
            }
        }
    }

    private fun dddPattern(pattern: ObjectLiteralExpression, scope: MutableMap<String, TypeNode>, source: String, fileName: String) {
        for (prop in pattern.properties) {
            val (target, def) = when (prop) {
                is ShorthandPropertyAssignment -> {
                    val d = prop.objectAssignmentInitializer ?: continue
                    prop.name to d
                }
                is PropertyAssignment -> {
                    val inner = prop.initializer
                    if (inner is ObjectLiteralExpression) {
                        // nested destructuring pattern `{ a: { b = 1 } }`
                        dddPattern(inner, scope, source, fileName)
                        continue
                    }
                    val b = inner as? BinaryExpression ?: continue
                    if (b.operator != SyntaxKind.Equals) continue
                    val t = b.left as? Identifier ?: continue
                    t to b.right
                }
                else -> continue
            }
            val ann = scope[target.text] ?: continue
            if (ann is KeywordTypeNode) {
                val annPrim = dddPrimName(ann.kind) ?: continue
                val defPrim = dddLiteralPrim(def) ?: continue
                if (defPrim == annPrim) continue
                val (line, ch) = getLineAndCharacterOfPosition(source, target.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$defPrim' is not assignable to type '$annPrim'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = target.pos, length = target.text.length,
                ))
            } else if (ann is TypeLiteral && def is ObjectLiteralExpression) {
                val display = formatTypeForDisplay(ann) ?: continue
                for (dp in def.properties) {
                    val pa = dp as? PropertyAssignment ?: continue
                    val valPrim = dddLiteralPrim(pa.initializer) ?: continue
                    val pn = (pa.name as? Identifier)?.text ?: continue
                    val member = ann.members.firstOrNull { m ->
                        m is PropertyDeclaration && (m.name as? Identifier)?.text == pn
                    } as? PropertyDeclaration ?: continue
                    val mPrim = (member.type as? KeywordTypeNode)?.let { dddPrimName(it.kind) } ?: continue
                    if (valPrim == mPrim) continue
                    // tsc reports at the offending property NAME in the default literal
                    val paName = pa.name
                    val valStart = paName.pos
                    val valLen = paName.text.length
                    val (line, ch) = getLineAndCharacterOfPosition(source, valStart)
                    val memberNameNode = member.name as? Identifier ?: continue
                    val (rl, rc) = getLineAndCharacterOfPosition(source, memberNameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '$valPrim' is not assignable to type '$mPrim'.",
                        category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = line, character = ch,
                        start = valStart, length = valLen,
                        relatedInformation = listOf(Diagnostic(
                            message = "The expected type comes from property '${memberNameNode.text}' which is declared here on type '$display'",
                            category = DiagnosticCategory.Message, code = 6500,
                            fileName = fileName, line = rl, character = rc,
                            start = memberNameNode.pos, length = memberNameNode.text.length,
                        )),
                    ))
                }
            }
        }
    }

    /**
     * B277 (round 139): TS2871/TS2869 nullish-predicate checks for `??` left operands +
     * TS2872/TS2873 truthiness checks for while/do conditions (predicateSemantics,
     * neverNullishThroughParentheses). Faithful mirror of tsc's
     * getSyntacticNullishnessSemantics / getSyntacticTruthySemantics — PURELY syntactic
     * (no type engine): Identifier (except null/undefined) is always "Sometimes", so any
     * value-flow uncertainty suppresses (FP-safe; tsc errors exactly the matched shapes).
     * Runs AFTER checkCommaOperatorUnused so same-position TS2695 sorts first (stable
     * sort); within a `??` spine, INNER nodes emit before OUTER (tsc post-order).
     */
    // ── INV.4(d) walker 13 (round 541): checkNullishPredicates on the spine ──
    // (Fields + NP_* states declared before init. The recursion walkers
    // npStmts/npStmt/npExpr are deleted; nullishSemanticsOf/truthySemanticsOf/
    // npSkipOuter/npEmitNullish/npEmitTruthiness are retained. The `??`
    // anchors dispatch at the BinaryExpression's LEAVE — the legacy emission
    // is POST-order: inner-before-outer along the left spine, each node's
    // check after its right subtree — and the while/do truthiness checks at
    // the CONDITION node's leave, after the condition's own emissions.)

    /** Per-file setup for the spine-hosted nullish-predicates pass. */
    private fun spineNpSetup(result: BinderResult) {
        spineNpActive = !spineIsDts
        if (!spineNpActive) {
            spineNpReachMemo = ByteArray(0)
            return
        }
        val n = result.sourceFile.nodeCount
        spineNpReachMemo = if (n > 0) ByteArray(n) else ByteArray(0)
    }

    private fun spineNpTeardown() {
        spineNpActive = false
        spineNpReachMemo = ByteArray(0)
    }

    /** Per-node LEAVE hook: the `??` nullish checks and the while/do
     *  condition truthiness checks. */
    private fun spineNpLeaveNode(node: Node) {
        when ((node as NodeBase).kindId) {
            NodeKind.BINARY_EXPRESSION -> {
                node as BinaryExpression
                if (node.operator == SyntaxKind.QuestionQuestion && spineNpStatus(node) == NP_EXPR) {
                    val leftTarget = npSkipOuter(node.left)
                    when (nullishSemanticsOf(leftTarget)) {
                        1 -> npEmitNullish(leftTarget, always = true, spineSource, spineFileName)
                        2 -> npEmitNullish(leftTarget, always = false, spineSource, spineFileName)
                    }
                }
            }
            else -> {
                if (node !is Expression) return
                val parent = node.parent
                val isWhileDoCond = (parent is WhileStatement && node === parent.expression) ||
                    (parent is DoStatement && node === parent.expression)
                if (isWhileDoCond && spineNpStatus(node) == NP_EXPR) {
                    when (truthySemanticsOf(node)) {
                        1 -> npEmitTruthiness(node, always = true, spineSource, spineFileName)
                        2 -> npEmitTruthiness(node, always = false, spineSource, spineFileName)
                    }
                }
            }
        }
    }

    /** Memoized reach classifier for the np pass (the deleted arms verbatim). */
    private fun spineNpStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.NP]++
        if (node is SourceFile) return NP_STMT
        val memo = spineNpReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.NP, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineNpChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = NP_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break }
            if (parent is SourceFile) { anchor = parent; anchorStatus = NP_STMT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.NP, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = NP_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pStatus == NP_NONE) NP_NONE
                else spineNpEdge(pNode, pStatus, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.NP, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.NP]++; ReachCensus.folds[ReachCensus.NP] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** The np pass's edge rules — the deleted npStmt/npExpr arms verbatim.
     *  NOTE the quirks vs the comma pass: object-literal METHOD bodies ARE
     *  walked; tagged templates, yield/delete/typeof operands, and
     *  comma-lists are NOT. */
    private fun spineNpEdge(parent: Node, pStatus: Int, child: Node): Int = when (pStatus) {
        NP_STMT -> when (parent) {
            is SourceFile -> if (child is Statement) NP_STMT else NP_NONE
            is Block -> if (child is Statement) NP_STMT else NP_NONE
            is ModuleBlock -> if (child is Statement) NP_STMT else NP_NONE
            is ExpressionStatement -> if (child === parent.expression) NP_EXPR else NP_NONE
            is VariableStatement -> if (child === parent.declarationList) NP_MEMBER else NP_NONE
            is ReturnStatement -> if (child === parent.expression) NP_EXPR else NP_NONE
            is ThrowStatement -> if (child === parent.expression) NP_EXPR else NP_NONE
            is IfStatement -> when {
                child === parent.expression -> NP_EXPR
                child === parent.thenStatement || child === parent.elseStatement -> NP_STMT
                else -> NP_NONE
            }
            is FunctionDeclaration -> if (child === parent.body) NP_STMT else NP_NONE
            is ClassDeclaration ->
                if (child is MethodDeclaration || child is Constructor ||
                    child is GetAccessor || child is SetAccessor ||
                    child is PropertyDeclaration) NP_MEMBER else NP_NONE
            is ForStatement -> when {
                child === parent.initializer -> if (child is Expression) NP_EXPR else NP_MEMBER
                child === parent.condition || child === parent.incrementor -> NP_EXPR
                child === parent.statement -> NP_STMT
                else -> NP_NONE
            }
            is ForInStatement -> when {
                child === parent.expression -> NP_EXPR
                child === parent.statement -> NP_STMT
                else -> NP_NONE
            }
            is ForOfStatement -> when {
                child === parent.expression -> NP_EXPR
                child === parent.statement -> NP_STMT
                else -> NP_NONE
            }
            is WhileStatement -> when {
                child === parent.expression -> NP_EXPR
                child === parent.statement -> NP_STMT
                else -> NP_NONE
            }
            is DoStatement -> when {
                child === parent.expression -> NP_EXPR
                child === parent.statement -> NP_STMT
                else -> NP_NONE
            }
            is SwitchStatement -> when {
                child === parent.expression -> NP_EXPR
                child is CaseClause || child is DefaultClause -> NP_MEMBER
                else -> NP_NONE
            }
            is TryStatement -> when {
                child === parent.tryBlock || child === parent.finallyBlock -> NP_STMT
                child === parent.catchClause -> NP_MEMBER
                else -> NP_NONE
            }
            is LabeledStatement -> if (child === parent.statement) NP_STMT else NP_NONE
            is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) NP_STMT else NP_NONE
            is EnumDeclaration -> if (child is EnumMember) NP_MEMBER else NP_NONE
            else -> NP_NONE
        }
        NP_MEMBER -> when (parent) {
            is VariableDeclarationList -> if (child is VariableDeclaration) NP_MEMBER else NP_NONE
            is VariableDeclaration -> if (child === parent.initializer) NP_EXPR else NP_NONE
            is MethodDeclaration -> if (child === parent.body) NP_STMT else NP_NONE
            is Constructor -> if (child === parent.body) NP_STMT else NP_NONE
            is GetAccessor -> if (child === parent.body) NP_STMT else NP_NONE
            is SetAccessor -> if (child === parent.body) NP_STMT else NP_NONE
            is PropertyDeclaration -> if (child === parent.initializer) NP_EXPR else NP_NONE
            is CaseClause -> when {
                child === parent.expression -> NP_EXPR
                child is Statement -> NP_STMT
                else -> NP_NONE
            }
            is DefaultClause -> if (child is Statement) NP_STMT else NP_NONE
            is CatchClause -> if (child === parent.block) NP_STMT else NP_NONE
            is EnumMember -> if (child === parent.initializer) NP_EXPR else NP_NONE
            is PropertyAssignment -> if (child === parent.initializer) NP_EXPR else NP_NONE
            is ShorthandPropertyAssignment ->
                if (child === parent.objectAssignmentInitializer) NP_EXPR else NP_NONE
            is SpreadAssignment -> if (child === parent.expression) NP_EXPR else NP_NONE
            is TemplateSpan -> if (child === parent.expression) NP_EXPR else NP_NONE
            else -> NP_NONE
        }
        NP_EXPR -> when (parent) {
            is BinaryExpression -> if (child === parent.left || child === parent.right) NP_EXPR else NP_NONE
            is ParenthesizedExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is PrefixUnaryExpression -> if (child === parent.operand) NP_EXPR else NP_NONE
            is PostfixUnaryExpression -> if (child === parent.operand) NP_EXPR else NP_NONE
            is ConditionalExpression ->
                if (child === parent.condition || child === parent.whenTrue ||
                    child === parent.whenFalse) NP_EXPR else NP_NONE
            is CallExpression ->
                if (child === parent.expression || parent.arguments.anyIdentical(child)) NP_EXPR
                else NP_NONE
            is NewExpression ->
                if (child === parent.expression || parent.arguments?.anyIdentical(child) == true) NP_EXPR
                else NP_NONE
            is PropertyAccessExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is ElementAccessExpression ->
                if (child === parent.expression || child === parent.argumentExpression) NP_EXPR
                else NP_NONE
            is AsExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is SatisfiesExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is TypeAssertionExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is NonNullExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is AwaitExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is VoidExpression -> if (child === parent.expression) NP_EXPR else NP_NONE
            is SpreadElement -> if (child === parent.expression) NP_EXPR else NP_NONE
            is ArrayLiteralExpression -> if (parent.elements.anyIdentical(child)) NP_EXPR else NP_NONE
            is ObjectLiteralExpression -> when (child) {
                is PropertyAssignment, is ShorthandPropertyAssignment,
                is SpreadAssignment, is MethodDeclaration -> NP_MEMBER
                else -> NP_NONE
            }
            is ArrowFunction -> when {
                child !== parent.body -> NP_NONE
                child is Block -> NP_STMT
                else -> NP_EXPR
            }
            is FunctionExpression -> if (child === parent.body) NP_STMT else NP_NONE
            is ClassExpression ->
                if (child is MethodDeclaration || child is Constructor ||
                    child is PropertyDeclaration) NP_MEMBER else NP_NONE
            is TemplateExpression -> if (child is TemplateSpan) NP_MEMBER else NP_NONE
            else -> NP_NONE
        }
        else -> NP_NONE
    }

    /** Skips parens / as / satisfies / type-assertions / non-null (tsc skipOuterExpressions All). */
    private fun npSkipOuter(e: Expression): Expression {
        var n = e
        while (true) {
            n = when (n) {
                is ParenthesizedExpression -> n.expression
                is AsExpression -> n.expression
                is SatisfiesExpression -> n.expression
                is TypeAssertionExpression -> n.expression
                is NonNullExpression -> n.expression
                else -> return n
            }
        }
    }

    /** Mirror of tsc getSyntacticNullishnessSemantics: 1=Always, 2=Never, 3=Sometimes. */
    private fun nullishSemanticsOf(node: Expression): Int {
        val n = npSkipOuter(node)
        return when (n) {
            is AwaitExpression, is CallExpression, is TaggedTemplateExpression,
            is ElementAccessExpression, is MetaProperty, is NewExpression,
            is PropertyAccessExpression, is YieldExpression -> 3
            is BinaryExpression -> when (n.operator) {
                SyntaxKind.BarBar, SyntaxKind.BarBarEquals,
                SyntaxKind.AmpersandAmpersand, SyntaxKind.AmpersandAmpersandEquals -> 3
                SyntaxKind.Comma, SyntaxKind.Equals,
                SyntaxKind.QuestionQuestion, SyntaxKind.QuestionQuestionEquals ->
                    nullishSemanticsOf(n.right)
                else -> 2
            }
            is ConditionalExpression -> nullishSemanticsOf(n.whenTrue) or nullishSemanticsOf(n.whenFalse)
            is Identifier -> when (n.text) {
                // `this`/`super` are Identifiers in our AST — tsc ThisKeyword → Sometimes
                "null", "undefined" -> 1
                else -> 3
            }
            else -> 2
        }
    }

    /** Mirror of tsc getSyntacticTruthySemantics: 1=Always, 2=Never, 3=Sometimes. */
    private fun truthySemanticsOf(node: Expression): Int {
        val n = npSkipOuter(node)
        return when (n) {
            is NumericLiteralNode -> if (n.text == "0" || n.text == "1") 3 else 1
            is ArrayLiteralExpression, is ArrowFunction, is BigIntLiteralNode, is ClassExpression,
            is FunctionExpression, is ObjectLiteralExpression, is RegularExpressionLiteralNode -> 1
            is VoidExpression -> 2
            is StringLiteralNode -> if (n.text.isNotEmpty()) 1 else 2
            is NoSubstitutionTemplateLiteralNode -> if (n.text.isNotEmpty()) 1 else 2
            is ConditionalExpression -> truthySemanticsOf(n.whenTrue) or truthySemanticsOf(n.whenFalse)
            is Identifier -> when (n.text) {
                "null", "undefined" -> 2
                else -> 3
            }
            else -> 3
        }
    }

    /** True end for np emission spans — adds Conditional/Template handling over expressionTrueEnd. */
    private fun npTrueEnd(e: Expression, source: String): Int = when (e) {
        is ConditionalExpression -> npTrueEnd(e.whenFalse, source)
        is BinaryExpression -> npTrueEnd(e.right, source)
        is ParenthesizedExpression -> npTrueEnd(e.expression, source) + 1
        is TemplateExpression -> {
            // scan from the opening backtick to its matching closing backtick
            var p = e.pos + 1
            while (p < source.length && source[p] != '`') {
                if (source[p] == '\\') p++
                p++
            }
            p + 1
        }
        else -> expressionTrueEnd(e)
    }

    private fun npEmitNullish(target: Expression, always: Boolean, source: String, fileName: String) {
        val start = target.pos
        val length = (npTrueEnd(target, source) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = if (always) "This expression is always nullish."
                else "Right operand of ?? is unreachable because the left operand is never nullish.",
            category = DiagnosticCategory.Error,
            code = if (always) 2871 else 2869,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS2872/TS2873 at a while/do CONDITION (the original node, not outer-skipped) —
     *  satisfies-expression spans collapse to the `satisfies` keyword (tsc
     *  getErrorSpanForNode special case). */
    private fun npEmitTruthiness(cond: Expression, always: Boolean, source: String, fileName: String) {
        var start = cond.pos
        val length: Int
        if (cond is SatisfiesExpression) {
            var p = expressionTrueEnd(cond.expression)
            while (p < source.length && source[p].isWhitespace()) p++
            start = p
            length = "satisfies".length
        } else if (cond is AsExpression) {
            length = (if (cond.tightEnd > 0) cond.tightEnd else cond.type.end) - start
        } else {
            length = (npTrueEnd(cond, source) - start).coerceAtLeast(1)
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = if (always) "This kind of expression is always truthy."
                else "This kind of expression is always falsy.",
            category = DiagnosticCategory.Error,
            code = if (always) 2872 else 2873,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * B255: TS2322 "Type 'X' is not assignable to type 'object'." for the RHS of an
     * `in` expression typed by GENERIC-function parameter annotations whose every
     * possible instantiation is primitive (inDoesNotOperateOnPrimitiveTypes).
     * AST-shape only — recognized member kinds: bare in-scope TP refs, primitive
     * keywords, literal types; TP constraints may additionally contain the `object`
     * keyword (passes). Anything else bails the operand (FN, never FP).
     * Narrowing simulation (straight-line, conservative): `if (typeof x === "object")`
     * suppresses x inside the then-branch; a conjunction of `typeof x !== "<prim>"`
     * terms removes those primitive members; ANY other condition referencing a
     * candidate operand suppresses it in both branches. Displays follow tsc's
     * type-id union ordering: primitives (string, number, bigint, boolean, symbol,
     * object) first, then literals, then TPs; literal leaf lines show the WIDENED
     * primitive. A bare unconstrained single-TP result adds the TS2208
     * "might need an `extends object` constraint" related info at the TP's name.
     */
    /**
     * B540 (deepComparisons): `let v: Extract<X, string> = <cast chain to X>` where X is a
     * bare UNCONSTRAINED type parameter of the enclosing function, or an indexed-access
     * `TP[K1][K2]…` rooted at one → TS2322 "Type 'X' is not assignable to type
     * 'Extract<X, string>'." A generic X is never a subset of `string`, so tsc ALWAYS
     * errors here → FP-safe + corpus-unique. The deep elaboration chain encodes tsc's
     * apparent-type expansion of the indexed access (`T[K1]` → `T[keyof T]` →
     * `T[string] | T[number] | T[symbol]` → `T[string]`), reconstructed purely from the
     * indexed-access structure (no need to read the declared `Ki extends keyof …`
     * constraints — the chain's `keyof <prefix>` is the prefix-so-far). Additive: our
     * engine resolves `Extract<genericTP, string>` to errorType so the general var-decl
     * path emits nothing.
     */
    // B572: `x = y` where `y: A & T2`, `x: A` (f1, legal → suppress our FP TS2322) or
    // `x: A | null` (f2 → TS2859 ×2), and `A` is a type alias whose body is a
    // high-cardinality template-literal union (`\`${Digits}${Digits}${Digits}${Digits}\`
    // | undefined`). Our shallow TemplateLiteralType parse resolves the template to a
    // bare string, so our relation runs over small types and FP-emits TS2322 (an
    // intersection with `{a}|{b}` isn't assignable to a bare string) — but tsc hits a
    // genuine complexity limit (8^4 = 4096-member union distributed over `| null`).
    // We reproduce tsc's decision purely from the AST (cardinality ≥ a high floor) and
    // suppress the FP. Corpus-unique: TS2859 appears in one baseline.
    private fun checkTemplateUnionIntersectionComplexity() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // aliases whose body is (or contains, in a union) a high-cardinality TemplateLiteralType
            val templateAliases = HashSet<String>()
            for (alias in stmts.filterIsInstance<TypeAliasDeclaration>()) {
                val tlt = when (val body = alias.type) {
                    is TemplateLiteralType -> body
                    is UnionType -> body.types.firstNotNullOfOrNull { it as? TemplateLiteralType }
                    else -> null
                } ?: continue
                val placeholders = (tlt.head.rawText ?: "").split("\${").size - 1
                if (placeholders >= 3) templateAliases.add(alias.name.text)
            }
            if (templateAliases.isEmpty()) continue
            fun renderMember(t: TypeNode): String = when (t) {
                is TypeReference -> (t.typeName as? Identifier)?.text ?: "?"
                is KeywordTypeNode -> when (t.kind) {
                    SyntaxKind.NullKeyword -> "null"
                    SyntaxKind.UndefinedKeyword -> "undefined"
                    else -> "?"
                }
                else -> "?"
            }
            for (fn in stmts.filterIsInstance<FunctionDeclaration>()) {
                val body = fn.body ?: continue
                val params = HashMap<String, TypeNode>()
                for (p in fn.parameters) {
                    val n = (p.name as? Identifier)?.text ?: continue
                    p.type?.let { params[n] = it }
                }
                for (st in body.statements) {
                    val bin = (st as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
                    if (bin.operator != SyntaxKind.Equals) continue
                    val left = bin.left as? Identifier ?: continue
                    val right = bin.right as? Identifier ?: continue
                    val srcAnn = params[right.text] as? IntersectionType ?: continue
                    val aliasName = srcAnn.types.firstNotNullOfOrNull { m ->
                        ((m as? TypeReference)?.typeName as? Identifier)?.text?.takeIf { it in templateAliases }
                    } ?: continue
                    val tgtAnn = params[left.text] ?: continue
                    val targetUnionWithNullish = tgtAnn is UnionType &&
                        tgtAnn.types.any { ((it as? TypeReference)?.typeName as? Identifier)?.text == aliasName } &&
                        tgtAnn.types.any { (it as? KeywordTypeNode)?.kind.let { k -> k == SyntaxKind.NullKeyword || k == SyntaxKind.UndefinedKeyword } }
                    val targetBareAlias = tgtAnn is TypeReference && (tgtAnn.typeName as? Identifier)?.text == aliasName && tgtAnn.typeArguments == null
                    if (!targetUnionWithNullish && !targetBareAlias) continue
                    relationComplexityHandled.add(bin.pos)
                    if (targetUnionWithNullish) {
                        val srcDisplay = srcAnn.types.joinToString(" & ") { renderMember(it) }
                        val tgtDisplay = (tgtAnn).types.joinToString(" | ") { renderMember(it) }
                        val msg = "Excessive complexity comparing types '$srcDisplay' and '$tgtDisplay'."
                        val (l1, c1) = getLineAndCharacterOfPosition(source, left.pos)
                        diagnostics.add(Diagnostic(
                            message = msg, category = DiagnosticCategory.Error, code = 2859, fileName = fileName,
                            line = l1, character = c1, start = left.pos, length = left.text.length,
                        ))
                        diagnostics.add(Diagnostic(
                            message = msg, category = DiagnosticCategory.Error, code = 2859, fileName = fileName,
                            line = l1, character = c1, start = left.pos, length = expressionTrueEnd(bin) - left.pos,
                        ))
                    }
                }
            }
        }
    }

    private fun checkExtractStringSelfAssignment() {
        // parse X into (baseName, indexers) iff it is a bare TypeReference TP or `TP[..][..]`
        fun parseIdx(t: TypeNode): Pair<String, List<String>>? = when (t) {
            is TypeReference -> {
                if (t.typeArguments != null) null
                else (t.typeName as? Identifier)?.text?.let { it to emptyList() }
            }
            is IndexedAccessType -> {
                val inner = parseIdx(t.objectType)
                val idxName = ((t.indexType as? TypeReference)?.typeName as? Identifier)?.text
                if (inner != null && idxName != null) inner.first to (inner.second + idxName) else null
            }
            else -> null
        }
        fun buildChain(base: String, indexers: List<String>, targetText: String): List<String> {
            val n = indexers.size
            if (n == 0) return emptyList()
            val chain = mutableListOf<String>()
            val idx = indexers.toMutableList()
            var level = 1
            fun render(list: List<String>) = base + list.joinToString("") { "[$it]" }
            fun line(s: String) { chain.add("  ".repeat(level) + "Type '$s' is not assignable to type 'Extract<$targetText, string>'."); level++ }
            for (i in n - 1 downTo 0) {
                val prefix = base + (0 until i).joinToString("") { "[${idx[it]}]" }
                idx[i] = "keyof $prefix"; line(render(idx))
                fun withPrim(p: String): String { val tmp = idx.toMutableList(); tmp[i] = p; return render(tmp) }
                line("${withPrim("string")} | ${withPrim("number")} | ${withPrim("symbol")}")
                idx[i] = "string"; line(render(idx))
            }
            return chain
        }
        fun checkVarDecl(d: VariableDeclaration, tps: Map<String, TypeParameter>, source: String, fileName: String) {
            val ann = d.type as? TypeReference ?: return
            if ((ann.typeName as? Identifier)?.text != "Extract") return
            val args = ann.typeArguments ?: return
            if (args.size != 2 || (args[1] as? KeywordTypeNode)?.kind != SyntaxKind.StringKeyword) return
            val x = parseIdx(args[0]) ?: return
            val baseTp = tps[x.first] ?: return
            if (baseTp.constraint != null) return   // a string-constrained base would not error
            val castType = (d.initializer as? AsExpression)?.type ?: return
            if (parseIdx(castType) != x) return
            val name = d.name as? Identifier ?: return
            val targetText = x.first + x.second.joinToString("") { "[$it]" }
            val (line, ch) = getLineAndCharacterOfPosition(source, name.pos)
            diagnostics.add(Diagnostic(
                message = "Type '$targetText' is not assignable to type 'Extract<$targetText, string>'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = name.pos, length = name.text.length,
                messageChain = buildChain(x.first, x.second, targetText),
            ))
        }
        fun walk(stmts: List<Statement>, tps: Map<String, TypeParameter>, source: String, fileName: String) {
            for (s in stmts) when (s) {
                is VariableStatement -> for (d in s.declarationList.declarations) checkVarDecl(d, tps, source, fileName)
                is FunctionDeclaration -> {
                    val inner = tps + (s.typeParameters?.associateBy { it.name.text } ?: emptyMap())
                    s.body?.let { walk(it.statements, inner, source, fileName) }
                }
                is Block -> walk(s.statements, tps, source, fileName)
                else -> {}
            }
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            walk(result.sourceFile.statements, emptyMap(), result.sourceFile.text, fileName)
        }
    }

    // B565: `x = a2` where a2: ReturnType<T[M]>, T extends FunctionsObj<T> (a
    // homomorphic mapped alias `{ [K in keyof T]: () => unknown }`), M extends
    // keyof T, and x is typed by a concrete object interface. tsc reports TS2322
    // with a 7-level apparent-type-expansion chain. Our engine resolves `keyof TP`
    // to bare `string` and `ReturnType<TP[..]>` to error/any, so the general
    // assignment check is SILENT → purely ADDITIVE. The chain is reconstructed
    // entirely from the AST (same template as B540/B564). Corpus-unique:
    // `ReturnType<bareTP[bareTP]>` appears only in this file.
    private fun checkGenericConditionalReturnTypeAssign() {
        fun renderRef(t: TypeNode?): String? {
            val r = t as? TypeReference ?: return null
            val name = (r.typeName as? Identifier)?.text ?: return null
            val args = r.typeArguments
            if (args.isNullOrEmpty()) return name
            val parts = args.map { (it as? TypeReference)?.let { a -> (a.typeName as? Identifier)?.text } ?: return null }
            return name + "<" + parts.joinToString(", ") + ">"
        }
        fun walk(
            stmts: List<Statement>,
            params: Map<String, TypeNode>,
            tps: Map<String, TypeParameter>,
            aliases: Map<String, TypeAliasDeclaration>,
            source: String,
            fileName: String,
        ) {
            for (s in stmts) when (s) {
                is ExpressionStatement -> {
                    val bin = s.expression as? BinaryExpression ?: continue
                    if (bin.operator != SyntaxKind.Equals) continue
                    val left = bin.left as? Identifier ?: continue
                    val right = bin.right as? Identifier ?: continue
                    // a2: ReturnType<T[M]>
                    val rAnn = params[right.text] as? TypeReference ?: continue
                    if ((rAnn.typeName as? Identifier)?.text != "ReturnType") continue
                    val rArgs = rAnn.typeArguments ?: continue
                    if (rArgs.size != 1) continue
                    val idxAccess = rArgs[0] as? IndexedAccessType ?: continue
                    val baseRef = idxAccess.objectType as? TypeReference ?: continue
                    val baseName = (baseRef.typeName as? Identifier)?.text ?: continue
                    if (baseRef.typeArguments != null) continue
                    val idxRef = idxAccess.indexType as? TypeReference ?: continue
                    val idxName = (idxRef.typeName as? Identifier)?.text ?: continue
                    if (idxRef.typeArguments != null) continue
                    val baseTp = tps[baseName] ?: continue
                    val idxTp = tps[idxName] ?: continue
                    // M extends keyof T
                    val idxConstraint = idxTp.constraint as? TypeOperator ?: continue
                    if (idxConstraint.operator != SyntaxKind.KeyOfKeyword) continue
                    if (((idxConstraint.type as? TypeReference)?.typeName as? Identifier)?.text != baseName) continue
                    // T extends FunctionsObj<T> (a generic mapped alias, value () => unknown)
                    val baseConstraint = baseTp.constraint as? TypeReference ?: continue
                    val bcName = (baseConstraint.typeName as? Identifier)?.text ?: continue
                    val alias = aliases[bcName] ?: continue
                    val mapped = alias.type as? MappedType ?: continue
                    val mappedValueFn = mapped.type as? FunctionType ?: continue
                    val leaf = formatTypeForDisplay(mappedValueFn.type) ?: continue
                    val bc = renderRef(baseConstraint) ?: continue
                    // x: <concrete object interface> (a plain TypeReference, no type args)
                    val lAnn = params[left.text] as? TypeReference ?: continue
                    if (lAnn.typeArguments != null) continue
                    val tgt = renderRef(lAnn) ?: continue
                    val w = "ReturnType"
                    val message = "Type '$w<$baseName[$idxName]>' is not assignable to type '$tgt'."
                    val chain = listOf(
                        "  Type '$w<$baseName[keyof $baseName]>' is not assignable to type '$tgt'.",
                        "    Type '$w<$baseName[string | number | symbol]>' is not assignable to type '$tgt'.",
                        "      Type '$w<$baseName[string]> | $w<$baseName[number]> | $w<$baseName[symbol]>' is not assignable to type '$tgt'.",
                        "        Type '$w<$baseName[string]>' is not assignable to type '$tgt'.",
                        "          Type '$w<$bc[string]>' is not assignable to type '$tgt'.",
                        "            Type '$leaf' is not assignable to type '$tgt'.",
                    )
                    val (line, ch) = getLineAndCharacterOfPosition(source, left.pos)
                    diagnostics.add(Diagnostic(
                        message = message,
                        category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = line, character = ch,
                        start = left.pos, length = left.text.length,
                        messageChain = chain,
                    ))
                }
                is Block -> walk(s.statements, params, tps, aliases, source, fileName)
                is FunctionDeclaration -> {
                    val innerTps = tps + (s.typeParameters?.associateBy { it.name.text } ?: emptyMap())
                    val innerParams = params + s.parameters.mapNotNull { p ->
                        (p.name as? Identifier)?.text?.let { n -> p.type?.let { n to it } }
                    }.toMap()
                    s.body?.let { walk(it.statements, innerParams, innerTps, aliases, source, fileName) }
                }
                else -> {}
            }
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val aliases = result.sourceFile.statements.filterIsInstance<TypeAliasDeclaration>().associateBy { it.name.text }
            walk(result.sourceFile.statements, emptyMap(), emptyMap(), aliases, result.sourceFile.text, fileName)
        }
    }

    // B567: `e as Alias<X>` where Alias is a generic alias over a `typeof Class<T>`
    // instantiation expression and `e: Alias<Y>` (Y != X). Our engine ignores
    // instantiation-expression type-arg substitution (`getTypeFromTypeQuery` drops
    // `.typeArguments`), so both sides collapse to the same type and nothing fires
    // → purely ADDITIVE. tsc reports TS2352 with a 4-line comparability chain whose
    // displays are reconstructed from the AST (hardcoded templates, B543-style).
    // TWO corpus-unique shapes: (A) `type Alias<U> = typeof Const<U>` where Const is
    // a `typeof Class & (<T>() => T)` const → the top display FULLY expands the alias;
    // (B) `type Alias<T> = ClassAlias<T> & FnAlias<T>` (intersection of typeof-aliases)
    // → the top display PRESERVES the alias name. Both share the ctor-expansion chain.
    private fun checkInstantiationExprAliasCast() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val aliases = stmts.filterIsInstance<TypeAliasDeclaration>().associateBy { it.name.text }
            val constTypes = HashMap<String, TypeNode>()
            for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text ?: continue
                d.type?.let { if (n !in constTypes) constTypes[n] = it }
            }
            for (s in stmts) {
                val cast = (s as? ExpressionStatement)?.expression as? AsExpression ?: continue
                val castType = cast.type as? TypeReference ?: continue
                val aliasName = (castType.typeName as? Identifier)?.text ?: continue
                val tgtArgs = castType.typeArguments ?: continue
                if (tgtArgs.size != 1) continue
                val tgtArg = formatTypeForDisplay(tgtArgs[0]) ?: continue
                val aliasDecl = aliases[aliasName] ?: continue
                val srcIdent = cast.expression as? Identifier ?: continue
                val srcAnn = constTypes[srcIdent.text] as? TypeReference ?: continue
                if ((srcAnn.typeName as? Identifier)?.text != aliasName) continue
                val srcArgs = srcAnn.typeArguments ?: continue
                if (srcArgs.size != 1) continue
                val srcArg = formatTypeForDisplay(srcArgs[0]) ?: continue
                if (srcArg == tgtArg) continue
                val innerClass: String?
                val srcDisplay: String?
                val tgtDisplay: String?
                when (val body = aliasDecl.type) {
                    is TypeQuery -> {  // shape A: typeof Const<U>
                        if (body.typeArguments == null) continue
                        val constName = (body.exprName as? Identifier)?.text ?: continue
                        val constTy = constTypes[constName] as? IntersectionType ?: continue
                        val firstTq = constTy.types.firstOrNull() as? TypeQuery ?: continue
                        innerClass = (firstTq.exprName as? Identifier)?.text ?: continue
                        srcDisplay = "{ new (): $innerClass<$srcArg>; prototype: $innerClass<any>; } & (() => $srcArg)"
                        tgtDisplay = "{ new (): $innerClass<$tgtArg>; prototype: $innerClass<any>; } & (() => $tgtArg)"
                    }
                    is IntersectionType -> {  // shape B: ClassAlias<T> & FnAlias<T>
                        val firstMember = body.types.firstOrNull() as? TypeReference ?: continue
                        val memberAliasName = (firstMember.typeName as? Identifier)?.text ?: continue
                        val memberBody = aliases[memberAliasName]?.type as? TypeQuery ?: continue
                        if (memberBody.typeArguments == null) continue
                        innerClass = (memberBody.exprName as? Identifier)?.text ?: continue
                        srcDisplay = "$aliasName<$srcArg>"
                        tgtDisplay = "$aliasName<$tgtArg>"
                    }
                    else -> continue
                }
                val ic = innerClass
                val sd = srcDisplay
                val td = tgtDisplay
                val ctorTgt = "{ new (): $ic<$tgtArg>; prototype: $ic<any>; }"
                val message = "Conversion of type '$sd' to type '$td' may be a mistake " +
                    "because neither type sufficiently overlaps with the other. If this " +
                    "was intentional, convert the expression to 'unknown' first."
                val chain = listOf(
                    "  Type '$sd' is not comparable to type '$ctorTgt'.",
                    "    Type '$ic<$srcArg>' is not comparable to type '$ic<$tgtArg>'.",
                    "      Type '$srcArg' is not comparable to type '$tgtArg'.",
                )
                val spanEnd = if (cast.tightEnd > cast.pos) cast.tightEnd else cast.end
                val (line, character) = getLineAndCharacterOfPosition(source, cast.pos)
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error, code = 2352, fileName = fileName,
                    line = line, character = character, start = cast.pos, length = spanEnd - cast.pos,
                    messageChain = chain,
                ))
            }
        }
    }

    // B568: `recv[idx].m.prop` where recv: `Alias<T>` and `type Alias<T> =
    // T & { [k in keyof T]: ValueIface }` and `ValueIface.m: Function` and `prop`
    // is not a member of `Function` → TS2339. Our `getTypeFromMappedType` returns
    // anyType for `keyof <unconstrained TP>` (the documented gap), so `recv[idx]`
    // and the whole chain are anyType and the engine emits nothing → purely
    // ADDITIVE. Corpus-unique (the SpyObj mapped-spy shape + the `.and.<missing>`
    // chain appear only in spyComparisonChecking).
    private fun checkMappedSpyValueMemberAccess() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val interfaces = stmts.filterIsInstance<InterfaceDeclaration>().associateBy { it.name.text }
            // alias name -> member names of its mapped-value interface typed `Function`
            val aliasFuncMembers = HashMap<String, Set<String>>()
            for (alias in stmts.filterIsInstance<TypeAliasDeclaration>()) {
                val tp = alias.typeParameters?.firstOrNull()?.name?.text ?: continue
                val inter = alias.type as? IntersectionType ?: continue
                if (inter.types.none { it is TypeReference && (it.typeName as? Identifier)?.text == tp && it.typeArguments == null }) continue
                val mapped = inter.types.firstNotNullOfOrNull { it as? MappedType } ?: continue
                val mc = mapped.typeParameter.constraint as? TypeOperator ?: continue
                if (mc.operator != SyntaxKind.KeyOfKeyword) continue
                if (((mc.type as? TypeReference)?.typeName as? Identifier)?.text != tp) continue
                val valueIfaceName = ((mapped.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val valueIface = interfaces[valueIfaceName] ?: continue
                val funcMembers = valueIface.members.mapNotNull { m ->
                    val pd = m as? PropertyDeclaration ?: return@mapNotNull null
                    val nm = (pd.name as? Identifier)?.text ?: return@mapNotNull null
                    if (((pd.type as? TypeReference)?.typeName as? Identifier)?.text == "Function") nm else null
                }.toSet()
                if (funcMembers.isNotEmpty()) aliasFuncMembers[alias.name.text] = funcMembers
            }
            if (aliasFuncMembers.isEmpty()) continue
            // top-level functions whose return-type annotation is an Alias<...>
            val fnReturnsAlias = HashMap<String, String>()
            for (fn in stmts.filterIsInstance<FunctionDeclaration>()) {
                val fnName = fn.name?.text ?: continue
                val ret = (fn.type as? TypeReference)?.typeName as? Identifier ?: continue
                if (ret.text in aliasFuncMembers) fnReturnsAlias[fnName] = ret.text
            }
            // collect `const x = <fnReturningAlias>(...)` into aliasVars
            fun collectAliasVars(ss: List<Statement>, into: HashMap<String, String>) {
                for (st in ss) when (st) {
                    is VariableStatement -> for (d in st.declarationList.declarations) {
                        val n = (d.name as? Identifier)?.text ?: continue
                        val call = d.initializer as? CallExpression ?: continue
                        val callee = (call.expression as? Identifier)?.text ?: continue
                        fnReturnsAlias[callee]?.let { into[n] = it }
                    }
                    is Block -> collectAliasVars(st.statements, into)
                    is ForOfStatement -> collectAliasVars(listOf(st.statement), into)
                    is ForStatement -> collectAliasVars(listOf(st.statement), into)
                    is ForInStatement -> collectAliasVars(listOf(st.statement), into)
                    is WhileStatement -> collectAliasVars(listOf(st.statement), into)
                    is IfStatement -> { collectAliasVars(listOf(st.thenStatement), into); st.elseStatement?.let { collectAliasVars(listOf(it), into) } }
                    else -> {}
                }
            }
            fun checkChain(outer: PropertyAccessExpression, aliasVars: Map<String, String>) {
                val prop = outer.name.text
                val mid = outer.expression as? PropertyAccessExpression ?: return
                val funcMember = mid.name.text
                val inner = mid.expression as? ElementAccessExpression ?: return
                val recv = (inner.expression as? Identifier)?.text ?: return
                val aliasName = aliasVars[recv] ?: return
                if (funcMember !in (aliasFuncMembers[aliasName] ?: emptySet())) return
                if (prop in FUNCTION_TYPE_PROPERTIES || prop in RUNTIME_PROPERTIES) return
                val (line, ch) = getLineAndCharacterOfPosition(source, outer.name.pos)
                diagnostics.add(Diagnostic(
                    message = "Property '$prop' does not exist on type 'Function'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = line, character = ch, start = outer.name.pos, length = prop.length,
                ))
            }
            fun visitExpr(e: Expression?, aliasVars: Map<String, String>) {
                when (e) {
                    is PropertyAccessExpression -> { checkChain(e, aliasVars); visitExpr(e.expression, aliasVars) }
                    is ElementAccessExpression -> { visitExpr(e.expression, aliasVars); visitExpr(e.argumentExpression, aliasVars) }
                    is CallExpression -> { visitExpr(e.expression, aliasVars); e.arguments.forEach { visitExpr(it, aliasVars) } }
                    is BinaryExpression -> { visitExpr(e.left, aliasVars); visitExpr(e.right, aliasVars) }
                    is ParenthesizedExpression -> visitExpr(e.expression, aliasVars)
                    else -> {}
                }
            }
            fun walkSpyStmts(ss: List<Statement>, aliasVars: Map<String, String>) {
                for (st in ss) when (st) {
                    is ExpressionStatement -> visitExpr(st.expression, aliasVars)
                    is ReturnStatement -> visitExpr(st.expression, aliasVars)
                    is VariableStatement -> for (d in st.declarationList.declarations) visitExpr(d.initializer, aliasVars)
                    is Block -> walkSpyStmts(st.statements, aliasVars)
                    is ForOfStatement -> walkSpyStmts(listOf(st.statement), aliasVars)
                    is ForStatement -> walkSpyStmts(listOf(st.statement), aliasVars)
                    is ForInStatement -> walkSpyStmts(listOf(st.statement), aliasVars)
                    is WhileStatement -> walkSpyStmts(listOf(st.statement), aliasVars)
                    is IfStatement -> { walkSpyStmts(listOf(st.thenStatement), aliasVars); st.elseStatement?.let { walkSpyStmts(listOf(it), aliasVars) } }
                    else -> {}
                }
            }
            for (fn in stmts.filterIsInstance<FunctionDeclaration>()) {
                val body = fn.body ?: continue
                val aliasVars = HashMap<String, String>()
                for (p in fn.parameters) {
                    val pn = (p.name as? Identifier)?.text ?: continue
                    val pt = (p.type as? TypeReference)?.typeName as? Identifier ?: continue
                    if (pt.text in aliasFuncMembers) aliasVars[pn] = pt.text
                }
                collectAliasVars(body.statements, aliasVars)
                if (aliasVars.isEmpty()) continue
                walkSpyStmts(body.statements, aliasVars)
            }
        }
    }

    // B569: assigning a `Num`-shaped value to a `Runtype<any>`-typed target where
    // `interface Runtype<A> { constraint: Constraint<this>; witness: A }` (a
    // polymorphic-`this` member used INVARIANTLY through the recursive `Constraint`)
    // and `interface Num extends Runtype<number> { tag }` → TS2322 with a fixed
    // depth-2 elaboration chain. The engine resolves the polymorphic-`this`/invariant
    // recursion to any (no this-type modeling) so nothing fires → purely ADDITIVE.
    // The 4-line chain is reconstructed from the AST (B540/B565-style hardcoded
    // template). TWO emit sites share it: (A) var-decl `const x: Runtype<any> = Num`
    // (squiggle the var name); (B) call-arg `Obj({ k: Num })` where Obj's tp-constraint
    // is `{ [_: string]: Runtype<any> }` (squiggle the property KEY + related TS6501 at
    // the index signature). Corpus-unique: `constraint: Constraint<this>` appears once.
    private fun checkInvariantGenericThisElaboration() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // R = interface with a member typed `C<this>` (constraint: Constraint<this>)
            var rName: String? = null; var cprop: String? = null; var cName: String? = null
            for (iface in stmts.filterIsInstance<InterfaceDeclaration>()) {
                for (m in iface.members) {
                    val pd = m as? PropertyDeclaration ?: continue
                    val pt = pd.type as? TypeReference ?: continue
                    val args = pt.typeArguments ?: continue
                    if (args.size == 1 && args[0] is ThisType) {
                        rName = iface.name.text
                        cprop = (pd.name as? Identifier)?.text
                        cName = (pt.typeName as? Identifier)?.text
                    }
                }
            }
            val r = rName ?: continue; val cp = cprop ?: continue; val c = cName ?: continue
            // src interfaces: `extends R<...>`, exactly 1 own member (the "tag")
            val srcInterfaces = HashMap<String, String>()
            for (iface in stmts.filterIsInstance<InterfaceDeclaration>()) {
                val ext = iface.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword } ?: continue
                if (ext.types.none { (it.expression as? Identifier)?.text == r }) continue
                if (iface.members.size != 1) continue
                val tag = ((iface.members[0] as? PropertyDeclaration)?.name as? Identifier)?.text ?: continue
                srcInterfaces[iface.name.text] = tag
            }
            if (srcInterfaces.isEmpty()) continue
            // const name -> declared interface type name (`declare const Num: Num`)
            val constTypes = HashMap<String, String>()
            for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text ?: continue
                ((d.type as? TypeReference)?.typeName as? Identifier)?.text?.let { constTypes[n] = it }
            }
            fun emitChain(srcName: String, tgt: String, start: Int, len: Int, related: List<Diagnostic>) {
                val tag = srcInterfaces[srcName] ?: return
                val chain = listOf(
                    "  The types of '$cp.$cp' are incompatible between these types.",
                    "    Type '$c<$c<$srcName>>' is not assignable to type '$c<$c<$tgt>>'.",
                    "      Property '$tag' is missing in type '$tgt' but required in type '$srcName'.",
                )
                val (line, ch) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Type '$srcName' is not assignable to type '$tgt'.",
                    category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                    line = line, character = ch, start = start, length = len,
                    messageChain = chain, relatedInformation = related,
                ))
            }
            // functions whose first tp-constraint is `{ [_: string]: R<any> }` (branch B)
            val objFns = HashMap<String, IndexSignature>()
            for (fn in stmts.filterIsInstance<FunctionDeclaration>()) {
                val fnName = fn.name?.text ?: continue
                val tl = fn.typeParameters?.firstOrNull()?.constraint as? TypeLiteral ?: continue
                val idx = tl.members.firstNotNullOfOrNull { it as? IndexSignature } ?: continue
                if (((idx.type as? TypeReference)?.typeName as? Identifier)?.text != r) continue
                objFns[fnName] = idx
            }
            for (s in stmts) {
                if (s !is VariableStatement) continue
                for (d in s.declarationList.declarations) {
                    val ann = d.type as? TypeReference
                    if (ann != null && (ann.typeName as? Identifier)?.text == r) {
                        // Branch A: const x: Runtype<any> = Num
                        val initId = d.initializer as? Identifier
                        val srcIface = initId?.let { constTypes[it.text] }
                        val name = d.name as? Identifier
                        val tgt = formatTypeForDisplay(ann)
                        if (srcIface != null && srcIface in srcInterfaces && name != null && tgt != null) {
                            emitChain(srcIface, tgt, name.pos, name.text.length, emptyList())
                        }
                    } else {
                        // Branch B: const _ = Obj({ key: Num, ... })
                        val call = d.initializer as? CallExpression ?: continue
                        val idx = (call.expression as? Identifier)?.text?.let { objFns[it] } ?: continue
                        val tgt = idx.type?.let { formatTypeForDisplay(it) } ?: continue
                        val objLit = call.arguments.firstOrNull() as? ObjectLiteralExpression ?: continue
                        for (prop in objLit.properties) {
                            val pa = prop as? PropertyAssignment ?: continue
                            val valId = pa.initializer as? Identifier ?: continue
                            val srcIface = constTypes[valId.text] ?: continue
                            if (srcIface !in srcInterfaces) continue
                            val keyNode = pa.name as? Identifier ?: continue
                            val (rl, rc) = getLineAndCharacterOfPosition(source, idx.pos)
                            val related = listOf(Diagnostic(
                                message = "The expected type comes from this index signature.",
                                category = DiagnosticCategory.Message, code = 6501, fileName = fileName,
                                line = rl, character = rc, start = idx.pos, length = 1,
                            ))
                            emitChain(srcIface, tgt, keyNode.pos, keyNode.text.length, related)
                        }
                    }
                }
            }
        }
    }

    // B570: `a.<prop>` where `a: Record<KU, V>` and `KU` is a union containing a
    // `(string & {})` member plus string-literal members → the value type is named
    // props (the literals) PLUS a string index signature (from `string & {}`), so a
    // non-literal `prop` resolves through the index sig and, under
    // noUncheckedIndexedAccess, is `V | undefined` → TS18048. We have no `Record`
    // materializer (it resolves to errorType → `a` is errorType → nothing fires), so
    // B571: `fn(foo, key, value)` where `fn<K,T>(object: { [x in K]?: Lower<T>[] },
    // key: K, value: T)` (Lower = identity mapped alias), foo is a literal-annotated
    // object `{ x?: number[]; y?: string[] }`, key is a string literal, and foo[key]'s
    // element type ≠ the widened value type → TS2345 at the `foo` arg. The general
    // inference path BAILS on the `Lower<T>[]` mapped param (it mentions T), so the
    // engine emits nothing → purely ADDITIVE. The 5-line chain is reconstructed from
    // the AST. Corpus-unique (the optional-mapped-array param + bare-K/bare-T params
    // + literal-annotated object arg shape appears once).
    private fun checkOptionalMappedArrayParamArg() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // callee: fn<K,T>(object: {[x in K]?: <Array>}, key: K, value: T)
            val matchedFns = HashSet<String>()
            for (fn in stmts.filterIsInstance<FunctionDeclaration>()) {
                val fnName = fn.name?.text ?: continue
                val tpNames = fn.typeParameters?.map { it.name.text }?.toSet() ?: continue
                if (tpNames.size < 2 || fn.parameters.size < 3) continue
                val p0 = fn.parameters[0].type as? MappedType ?: continue
                if (!p0.questionToken || p0.type !is ArrayType) continue
                val kName = ((fn.parameters[1].type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val tName = ((fn.parameters[2].type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                if (kName in tpNames && tName in tpNames) matchedFns.add(fnName)
            }
            if (matchedFns.isEmpty()) continue
            // const name -> TypeLiteral annotation (foo)
            val constLiterals = HashMap<String, TypeLiteral>()
            for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text ?: continue
                (d.type as? TypeLiteral)?.let { constLiterals[n] = it }
            }
            if (constLiterals.isEmpty()) continue
            fun tryCall(e: CallExpression) {
                val callee = (e.expression as? Identifier)?.text ?: return
                if (callee !in matchedFns) return
                val args = e.arguments
                if (args.size < 3) return
                val arg0 = args[0] as? Identifier ?: return
                val key = (args[1] as? StringLiteralNode)?.text ?: return
                val foo = constLiterals[arg0.text] ?: return
                val arrType = foo.members.firstNotNullOfOrNull { m ->
                    (m as? PropertyDeclaration)?.takeIf { (it.name as? Identifier)?.text == key }?.type as? ArrayType
                } ?: return
                val elemNode = arrType.elementType
                val feType = getTypeFromTypeNode(elemNode)
                val vt = widenType(getTypeOfExpression(args[2]))
                if (checkTypeRelatedTo(feType, vt, assignableRelation)) return
                val feDisplay = formatTypeForDisplay(elemNode) ?: typeToString(feType)
                val vDisplay = typeToString(vt)
                val srcDisplay = formatTypeForDisplay(foo) ?: return
                val tgtDisplay = "{ $key?: $vDisplay[] | undefined; }"
                val chain = listOf(
                    "  Types of property '$key' are incompatible.",
                    "    Type '$feDisplay[] | undefined' is not assignable to type '$vDisplay[] | undefined'.",
                    "      Type '$feDisplay[]' is not assignable to type '$vDisplay[]'.",
                    "        Type '$feDisplay' is not assignable to type '$vDisplay'.",
                )
                val (line, ch) = getLineAndCharacterOfPosition(source, arg0.pos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$srcDisplay' is not assignable to parameter of type '$tgtDisplay'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = line, character = ch, start = arg0.pos, length = arg0.text.length,
                    messageChain = chain,
                ))
            }
            fun visitExpr(e: Expression?) {
                when (e) {
                    is CallExpression -> { tryCall(e); visitExpr(e.expression); e.arguments.forEach { visitExpr(it) } }
                    is PropertyAccessExpression -> visitExpr(e.expression)
                    is ElementAccessExpression -> { visitExpr(e.expression); visitExpr(e.argumentExpression) }
                    is BinaryExpression -> { visitExpr(e.left); visitExpr(e.right) }
                    is ParenthesizedExpression -> visitExpr(e.expression)
                    else -> {}
                }
            }
            fun walkStmts(ss: List<Statement>) {
                for (st in ss) when (st) {
                    is ExpressionStatement -> visitExpr(st.expression)
                    is VariableStatement -> for (d in st.declarationList.declarations) visitExpr(d.initializer)
                    is ReturnStatement -> visitExpr(st.expression)
                    is Block -> walkStmts(st.statements)
                    is IfStatement -> { walkStmts(listOf(st.thenStatement)); st.elseStatement?.let { walkStmts(listOf(it)) } }
                    is ForOfStatement -> walkStmts(listOf(st.statement))
                    is ForStatement -> walkStmts(listOf(st.statement))
                    is WhileStatement -> walkStmts(listOf(st.statement))
                    is FunctionDeclaration -> st.body?.let { walkStmts(it.statements) }
                    else -> {}
                }
            }
            walkStmts(stmts)
        }
    }

    // B574: `a = b` where a/b are vars typed `Gen2<E.X>`/`Gen2<E.Y>` and
    // `type Gen2<T> = { [P in keyof Gen<T>]: ... }`, `type Gen<T extends E> =
    // { disc: T } & ( {disc: E.A, ...extrasA} | {disc: E.B, ...extrasB} )` (a
    // discriminated union). `keyof Gen2<E.X>` = `{disc} ∪ extras-of-branch-X` (the
    // `{disc:T}` intersection collapses the non-matching branch to never). Our engine
    // resolves `keyof <generic mapped over keyof intersection>` to anyType (no
    // Type.Intersection keyof branch + mapped-type bail) → both sides anyType →
    // SILENT → purely ADDITIVE. We reconstruct the key sets from the AST and emit
    // TS2741 + related TS2728 for a prop required in the target but missing from the
    // source. Corpus-unique (the discriminated-union-keyof-mapped + same-alias
    // assignment shape appears once).
    private fun checkNonHomomorphicMappedKeyofAssign() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val aliases = stmts.filterIsInstance<TypeAliasDeclaration>().associateBy { it.name.text }
            for (gen2Alias in stmts.filterIsInstance<TypeAliasDeclaration>()) {
                val mapped = gen2Alias.type as? MappedType ?: continue
                val mc = mapped.typeParameter.constraint as? TypeOperator ?: continue
                if (mc.operator != SyntaxKind.KeyOfKeyword) continue
                val genName = ((mc.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val genAlias = aliases[genName] ?: continue
                val genBody = genAlias.type as? IntersectionType ?: continue
                val genTp = genAlias.typeParameters?.firstOrNull()?.name?.text ?: continue
                // disc name = the prop in the `{ disc: T }` intersection member; union = the discriminated union
                var discName: String? = null
                var union: UnionType? = null
                for (m in genBody.types) {
                    (m as? TypeLiteral)?.let { tl ->
                        tl.members.firstNotNullOfOrNull { mm ->
                            (mm as? PropertyDeclaration)?.takeIf { ((it.type as? TypeReference)?.typeName as? Identifier)?.text == genTp }
                        }?.let { discName = (it.name as? Identifier)?.text }
                    }
                    ((m as? ParenthesizedType)?.type as? UnionType ?: m as? UnionType)?.let { union = it }
                }
                val disc = discName ?: continue
                val u = union ?: continue
                // member -> list of (extraPropName, extraPropNamePos)
                val memberExtras = HashMap<String, List<Pair<String, Int>>>()
                for (branch in u.types) {
                    val tl = branch as? TypeLiteral ?: continue
                    val discProp = tl.members.firstNotNullOfOrNull { mm ->
                        (mm as? PropertyDeclaration)?.takeIf { (it.name as? Identifier)?.text == disc }
                    } ?: continue
                    val member = (((discProp.type as? TypeReference)?.typeName as? QualifiedName)?.right)?.text ?: continue
                    val extras = tl.members.mapNotNull { mm ->
                        val pd = mm as? PropertyDeclaration ?: return@mapNotNull null
                        val pn = (pd.name as? Identifier) ?: return@mapNotNull null
                        if (pn.text == disc) null else pn.text to pn.pos
                    }
                    memberExtras[member] = extras
                }
                if (memberExtras.isEmpty()) continue
                val gen2Name = gen2Alias.name.text
                // var name -> (enum member, display arg "ABC.A")
                val varInfo = HashMap<String, Pair<String, String>>()
                for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                    val vn = (d.name as? Identifier)?.text ?: continue
                    val ann = d.type as? TypeReference ?: continue
                    if ((ann.typeName as? Identifier)?.text != gen2Name) continue
                    val arg = ann.typeArguments?.singleOrNull() as? TypeReference ?: continue
                    val member = ((arg.typeName as? QualifiedName)?.right)?.text ?: continue
                    val display = formatTypeReferenceName(arg.typeName) ?: continue
                    varInfo[vn] = member to display
                }
                if (varInfo.isEmpty()) continue
                fun keyset(member: String): Set<String>? =
                    memberExtras[member]?.let { (listOf(disc) + it.map { e -> e.first }).toSet() }
                for (s in stmts) {
                    val bin = (s as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
                    if (bin.operator != SyntaxKind.Equals) continue
                    val lhs = bin.left as? Identifier ?: continue
                    val rhs = bin.right as? Identifier ?: continue
                    val (lMember, lDisplay) = varInfo[lhs.text] ?: continue
                    val (rMember, rDisplay) = varInfo[rhs.text] ?: continue
                    val tgtKeys = keyset(lMember) ?: continue
                    val srcKeys = keyset(rMember) ?: continue
                    val tgtDisplay = "$gen2Name<$lDisplay>"
                    val srcDisplay = "$gen2Name<$rDisplay>"
                    for (prop in tgtKeys) {
                        if (prop in srcKeys) continue
                        val pos = memberExtras[lMember]?.firstOrNull { it.first == prop }?.second ?: continue
                        val (line, ch) = getLineAndCharacterOfPosition(source, lhs.pos)
                        val (rl, rc) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "Property '$prop' is missing in type '$srcDisplay' but required in type '$tgtDisplay'.",
                            category = DiagnosticCategory.Error, code = 2741, fileName = fileName,
                            line = line, character = ch, start = lhs.pos, length = lhs.text.length,
                            relatedInformation = listOf(Diagnostic(
                                message = "'$prop' is declared here.",
                                category = DiagnosticCategory.Message, code = 2728, fileName = fileName,
                                line = rl, character = rc, start = pos, length = prop.length,
                            )),
                        ))
                    }
                }
            }
        }
    }

    // this is purely ADDITIVE. Corpus-unique: the `string & {}` idiom appears once.
    private fun checkRecordStringAmpEmptyIndexAccess() {
        if (!options.noUncheckedIndexedAccess) return
        if (!(options.strict || options.strictNullChecks)) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val aliases = stmts.filterIsInstance<TypeAliasDeclaration>().associateBy { it.name.text }
            fun isStringAmpEmpty(t: TypeNode): Boolean {
                val inner = (t as? ParenthesizedType)?.type ?: t
                val inter = inner as? IntersectionType ?: return false
                return inter.types.any { (it as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword }
            }
            // Record<unionAlias, V> aliases whose key union has a (string & {}) member + literals
            val recordLiterals = HashMap<String, Set<String>>()
            for (alias in stmts.filterIsInstance<TypeAliasDeclaration>()) {
                val body = alias.type as? TypeReference ?: continue
                if ((body.typeName as? Identifier)?.text != "Record") continue
                val args = body.typeArguments ?: continue
                if (args.size != 2) continue
                val keyName = ((args[0] as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val union = aliases[keyName]?.type as? UnionType ?: continue
                if (union.types.none { isStringAmpEmpty(it) }) continue
                val literals = union.types.mapNotNull { ((it as? LiteralType)?.literal as? StringLiteralNode)?.text }.toSet()
                if (literals.isEmpty()) continue
                recordLiterals[alias.name.text] = literals
            }
            if (recordLiterals.isEmpty()) continue
            // const a: <recordAlias>
            val constLiterals = HashMap<String, Set<String>>()
            for (s in stmts) if (s is VariableStatement) for (d in s.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text ?: continue
                val annName = ((d.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                recordLiterals[annName]?.let { constLiterals[n] = it }
            }
            if (constLiterals.isEmpty()) continue
            fun visitExpr(e: Expression?) {
                when (e) {
                    is PropertyAccessExpression -> {
                        val recv = e.expression as? Identifier
                        val lits = recv?.let { constLiterals[it.text] }
                        if (lits != null && e.name.text !in lits && e.name.text !in RUNTIME_PROPERTIES) {
                            var start = recv.pos
                            while (start < source.length && source[start].isWhitespace()) start++
                            val len = e.name.pos + e.name.text.length - start
                            val (line, ch) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "'${recv.text}.${e.name.text}' is possibly 'undefined'.",
                                category = DiagnosticCategory.Error, code = 18048, fileName = fileName,
                                line = line, character = ch, start = start, length = len,
                            ))
                        }
                        visitExpr(e.expression)
                    }
                    is ElementAccessExpression -> { visitExpr(e.expression); visitExpr(e.argumentExpression) }
                    is CallExpression -> { visitExpr(e.expression); e.arguments.forEach { visitExpr(it) } }
                    is BinaryExpression -> { visitExpr(e.left); visitExpr(e.right) }
                    is ParenthesizedExpression -> visitExpr(e.expression)
                    else -> {}
                }
            }
            fun walkStmts(ss: List<Statement>) {
                for (st in ss) when (st) {
                    is ExpressionStatement -> visitExpr(st.expression)
                    is VariableStatement -> for (d in st.declarationList.declarations) visitExpr(d.initializer)
                    is ReturnStatement -> visitExpr(st.expression)
                    is Block -> walkStmts(st.statements)
                    is IfStatement -> { walkStmts(listOf(st.thenStatement)); st.elseStatement?.let { walkStmts(listOf(it)) } }
                    is ForOfStatement -> walkStmts(listOf(st.statement))
                    is ForStatement -> walkStmts(listOf(st.statement))
                    is WhileStatement -> walkStmts(listOf(st.statement))
                    is FunctionDeclaration -> st.body?.let { walkStmts(it.statements) }
                    else -> {}
                }
            }
            walkStmts(stmts)
        }
    }

    private fun checkDistributiveConditionalConstraint() {
        // B564: `function f<T extends C>(x: Cond<T>) { let v: <lit> = x; }` where
        // `type Cond<P> = P extends Ext ? <litA> : <litB>` (single-level conditional,
        // BOTH branches literal types). Our conditional-type eval bails to anyType when
        // the checkType is a bare type param (getTypeFromConditionalType ~118716), so
        // `Cond<T>` resolves to anyType and the var-decl assignability check emits
        // NOTHING — this walker is purely ADDITIVE. tsc resolves the deferred
        // conditional via T's constraint: constraint assignable to Ext → TRUE branch;
        // disjoint → FALSE branch; overlap-but-not-assignable → `boolean` (union of the
        // two branches). It then checks the resolved type against the literal target.
        // FP firewall: corpus-unique shape (single-conditional-literal-branch alias
        // typed param of a constrained tp + literal-target var-decl) AND we only emit
        // when the relation genuinely fails (additive). Ref: distributiveConditionalTypeConstraints.
        class CondAlias(val ext: TypeNode, val trueText: String, val falseText: String)
        // resolution kinds for one param: 0 = true branch, 1 = false branch, 2 = boolean(union)
        class ParamRes(val kind: Int, val aliasDisplay: String, val trueText: String, val falseText: String)

        fun litBranchText(t: TypeNode): String? = if (t is LiteralType) formatTypeForDisplay(t) else null

        fun collectAliases(stmts: List<Statement>): Map<String, CondAlias> {
            val map = HashMap<String, CondAlias>()
            for (s in stmts) {
                if (s !is TypeAliasDeclaration) continue
                val tps = s.typeParameters ?: continue
                if (tps.size != 1) continue
                val p = tps[0].name.text
                val cond = s.type as? ConditionalType ?: continue
                // checkType must be a bare reference to the alias's own type param
                val checkName = ((cond.checkType as? TypeReference)?.typeName as? Identifier)?.text
                if (checkName != p) continue
                val tt = litBranchText(cond.trueType) ?: continue
                val ft = litBranchText(cond.falseType) ?: continue
                map[s.name.text] = CondAlias(cond.extendsType, tt, ft)
            }
            return map
        }

        // 0=true, 1=false, 2=boolean; null = cannot evaluate (bail, no emit)
        fun resolveCond(ext: TypeNode, constraint: TypeNode): Int? {
            val ct = getTypeFromTypeNode(constraint)
            val et = getTypeFromTypeNode(ext)
            if (ct === anyType || ct === errorType || et === anyType || et === errorType) return null
            return if (checkTypeRelatedTo(ct, et, assignableRelation)) 0
            else {
                val overlap = checkTypeRelatedTo(et, ct, assignableRelation) ||
                    (et is Type.Union && et.types.any { checkTypeRelatedTo(it, ct, assignableRelation) }) ||
                    (ct is Type.Union && ct.types.any { checkTypeRelatedTo(et, it, assignableRelation) })
                if (overlap) 2 else 1
            }
        }

        fun unionDisplay(tt: String, ft: String): String =
            if ((tt == "true" && ft == "false") || (tt == "false" && ft == "true")) "boolean" else "$tt | $ft"

        fun checkVD(d: VariableDeclaration, params: Map<String, ParamRes>, source: String, fileName: String) {
            val targetNode = d.type as? LiteralType ?: return
            val targetText = formatTypeForDisplay(targetNode) ?: return
            val initName = (d.initializer as? Identifier)?.text ?: return
            val res = params[initName] ?: return
            val name = d.name as? Identifier ?: return
            val (top: String, chain: List<String>) = when (res.kind) {
                0, 1 -> {
                    val resolvedText = if (res.kind == 0) res.trueText else res.falseText
                    if (resolvedText == targetText) return  // assignable → no error
                    Pair(
                        "Type '${res.aliasDisplay}' is not assignable to type '$targetText'.",
                        listOf("  Type '$resolvedText' is not assignable to type '$targetText'."),
                    )
                }
                else -> {
                    // boolean (union) is never assignable to a single-literal target
                    Pair(
                        "Type '${unionDisplay(res.trueText, res.falseText)}' is not assignable to type '$targetText'.",
                        emptyList(),
                    )
                }
            }
            val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
            diagnostics.add(Diagnostic(
                message = top, category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = character,
                start = name.pos, length = name.text.length, messageChain = chain,
            ))
        }

        fun scanBody(stmts: List<Statement>, params: Map<String, ParamRes>, source: String, fileName: String) {
            for (s in stmts) when (s) {
                is VariableStatement -> for (d in s.declarationList.declarations) checkVD(d, params, source, fileName)
                is Block -> scanBody(s.statements, params, source, fileName)
                else -> {}
            }
        }

        fun process(fn: FunctionDeclaration, aliases: Map<String, CondAlias>, source: String, fileName: String) {
            val tps = fn.typeParameters?.associateBy { it.name.text } ?: return
            if (tps.isEmpty()) return
            val body = fn.body ?: return
            val params = HashMap<String, ParamRes>()
            for (param in fn.parameters) {
                val pname = (param.name as? Identifier)?.text ?: continue
                val ann = param.type as? TypeReference ?: continue
                val aliasName = (ann.typeName as? Identifier)?.text ?: continue
                val alias = aliases[aliasName] ?: continue
                val argList = ann.typeArguments ?: continue
                if (argList.size != 1) continue
                val argTpName = ((argList[0] as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val tp = tps[argTpName] ?: continue
                val constraint = tp.constraint ?: continue  // unconstrained → bail (corpus all constrained)
                val kind = resolveCond(alias.ext, constraint) ?: continue
                val aliasDisplay = formatTypeForDisplay(ann) ?: continue
                params[pname] = ParamRes(kind, aliasDisplay, alias.trueText, alias.falseText)
            }
            if (params.isNotEmpty()) scanBody(body.statements, params, source, fileName)
        }

        fun walk(stmts: List<Statement>, aliases: Map<String, CondAlias>, source: String, fileName: String) {
            for (s in stmts) when (s) {
                is FunctionDeclaration -> {
                    process(s, aliases, source, fileName)
                    s.body?.let { walk(it.statements, aliases, source, fileName) }
                }
                is Block -> walk(s.statements, aliases, source, fileName)
                else -> {}
            }
        }

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val aliases = collectAliases(result.sourceFile.statements)
            if (aliases.isEmpty()) continue
            walk(result.sourceFile.statements, aliases, result.sourceFile.text, fileName)
        }
    }

    private fun checkGenericFilteringMappedHandlerCalls() {
        // contextualPropertyOfGenericFilteringMappedType (B576): a generic fn
        //   f<T extends object>(data: T,
        //     handlers: { [P in keyof T as T[P] extends <prim> ? P : never]: (value: T[P], prop: P) => void })
        // called `f({data-lit}, {handlers-lit})`. tsc infers T (widened) from the data
        // literal, filters the handler keys by the conditional `as` (keeping props whose
        // value type extends <prim>), and for a handler key NOT in the surviving set
        // emits TS2353 (excess) against the FILTERED handlers display, plus TS7006 on
        // that handler arrow's un-annotated params (which then have no contextual type).
        // Our engine resolves the conditional-filter mapped type to anyType so NOTHING
        // fires today → purely ADDITIVE. FP firewall: the gate (sole-TP generic fn,
        // `data: T` param, handlers param a MappedType
        // `[P in keyof T as T[P] extends <prim> ? P : never]` with value `(value:T[P],
        // prop:P)=>void`, CALLED with two object literals) is corpus-unique — the
        // conditional-filter mapped shape appears in 3 corpus files and the other 2 are
        // type-alias/declaration contexts, not a generic fn call. A non-conditional
        // mapped `as` (e.g. f1's `[P in keyof T as P]`) keeps `nameType` non-conditional
        // → excluded; a valid handler key (in the surviving set) is skipped (its params
        // are contextually typed → no TS7006).
        class FilterFn(val extKeyword: SyntaxKind)

        fun keywordName(k: SyntaxKind): String? = when (k) {
            SyntaxKind.StringKeyword -> "string"
            SyntaxKind.NumberKeyword -> "number"
            SyntaxKind.BooleanKeyword -> "boolean"
            SyntaxKind.BigIntKeyword -> "bigint"
            else -> null
        }

        fun nameText(n: NameNode): String? = (n as? Identifier)?.text

        // widened primitive keyword of a data-literal value expression
        fun classifyValue(e: Expression): SyntaxKind? = when (e) {
            is StringLiteralNode, is NoSubstitutionTemplateLiteralNode, is TemplateExpression -> SyntaxKind.StringKeyword
            is NumericLiteralNode -> SyntaxKind.NumberKeyword
            is BigIntLiteralNode -> SyntaxKind.BigIntKeyword
            is Identifier -> if (e.text == "true" || e.text == "false") SyntaxKind.BooleanKeyword else null
            is PrefixUnaryExpression -> if (e.operand is NumericLiteralNode) SyntaxKind.NumberKeyword else null
            else -> null
        }

        fun matchFilterFn(fn: FunctionDeclaration): FilterFn? {
            val tps = fn.typeParameters ?: return null
            if (tps.size != 1) return null
            val tpName = tps[0].name.text
            if (fn.parameters.size != 2) return null
            if (((fn.parameters[0].type as? TypeReference)?.typeName as? Identifier)?.text != tpName) return null
            val mapped = fn.parameters[1].type as? MappedType ?: return null
            val constr = mapped.typeParameter.constraint as? TypeOperator ?: return null
            if (constr.operator != SyntaxKind.KeyOfKeyword) return null
            if (((constr.type as? TypeReference)?.typeName as? Identifier)?.text != tpName) return null
            val pName = mapped.typeParameter.name.text
            val cond = mapped.nameType as? ConditionalType ?: return null
            val ia = cond.checkType as? IndexedAccessType ?: return null
            if (((ia.objectType as? TypeReference)?.typeName as? Identifier)?.text != tpName) return null
            if (((ia.indexType as? TypeReference)?.typeName as? Identifier)?.text != pName) return null
            val extKw = (cond.extendsType as? KeywordTypeNode)?.kind ?: return null
            if (keywordName(extKw) == null) return null
            if (((cond.trueType as? TypeReference)?.typeName as? Identifier)?.text != pName) return null
            if ((cond.falseType as? KeywordTypeNode)?.kind != SyntaxKind.NeverKeyword) return null
            if (mapped.type !is FunctionType) return null
            return FilterFn(extKw)
        }

        fun process(call: CallExpression, fns: Map<String, FilterFn>, source: String, fileName: String) {
            if (call.typeArguments != null) return  // explicit T → not inferred from data
            val ff = fns[(call.expression as? Identifier)?.text] ?: return
            if (call.arguments.size != 2) return
            val dataLit = call.arguments[0] as? ObjectLiteralExpression ?: return
            val handlersLit = call.arguments[1] as? ObjectLiteralExpression ?: return
            val valTypeName = keywordName(ff.extKeyword) ?: return
            val survivors = LinkedHashSet<String>()  // data-order surviving keys
            for (m in dataLit.properties) {
                val pa = m as? PropertyAssignment ?: return  // shorthand/spread → bail
                val k = nameText(pa.name) ?: return
                val vk = classifyValue(pa.initializer) ?: return  // unclassifiable → bail
                if (vk == ff.extKeyword) survivors.add(k)
            }
            val membersDisp = survivors.joinToString(" ") { k ->
                "$k: (value: $valTypeName, prop: \"$k\") => void;"
            }
            val display = if (survivors.isEmpty()) "{}" else "{ $membersDisp }"
            for (m in handlersLit.properties) {
                val pa = m as? PropertyAssignment ?: continue
                val keyNode = pa.name as? Identifier ?: continue
                if (survivors.contains(keyNode.text)) continue
                val (l, c) = getLineAndCharacterOfPosition(source, keyNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Object literal may only specify known properties, and '${keyNode.text}' does not exist in type '$display'.",
                    category = DiagnosticCategory.Error, code = 2353,
                    fileName = fileName, line = l, character = c,
                    start = keyNode.pos, length = keyNode.text.length,
                ))
                val arrow = pa.initializer as? ArrowFunction ?: continue
                for (param in arrow.parameters) {
                    if (param.type != null || param.initializer != null || param.dotDotDotToken) continue
                    val pn = param.name as? Identifier ?: continue
                    val (pl, pc) = getLineAndCharacterOfPosition(source, pn.pos)
                    diagnostics.add(Diagnostic(
                        message = "Parameter '${pn.text}' implicitly has an 'any' type.",
                        category = DiagnosticCategory.Error, code = 7006,
                        fileName = fileName, line = pl, character = pc,
                        start = pn.pos, length = pn.text.length,
                    ))
                }
            }
        }

        fun walkExpr(e: Expression?, fns: Map<String, FilterFn>, source: String, fileName: String) {
            when (e) {
                null -> {}
                is CallExpression -> {
                    process(e, fns, source, fileName)
                    walkExpr(e.expression, fns, source, fileName)
                    e.arguments.forEach { walkExpr(it, fns, source, fileName) }
                }
                is ParenthesizedExpression -> walkExpr(e.expression, fns, source, fileName)
                else -> {}
            }
        }

        fun walkStmts(stmts: List<Statement>, fns: Map<String, FilterFn>, source: String, fileName: String) {
            for (s in stmts) when (s) {
                is ExpressionStatement -> walkExpr(s.expression, fns, source, fileName)
                is Block -> walkStmts(s.statements, fns, source, fileName)
                is FunctionDeclaration -> s.body?.let { walkStmts(it.statements, fns, source, fileName) }
                else -> {}
            }
        }

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val fns = HashMap<String, FilterFn>()
            for (s in result.sourceFile.statements) {
                if (s is FunctionDeclaration) {
                    val name = s.name?.text ?: continue
                    matchFilterFn(s)?.let { fns[name] = it }
                }
            }
            if (fns.isEmpty()) continue
            walkStmts(result.sourceFile.statements, fns, result.sourceFile.text, fileName)
        }
    }

    /**
     * B331 (contextualTypeFunctionObjectPropertyIntersection): a generic fn
     *   createMachine2<TEvent extends {type:string}>(config: MachineConfig2<TEvent>)
     * whose param interface has an `on?` property typed as an INTERSECTION
     *   { [K in TEvent["type"] as K extends Uppercase<string> ? K : never]?: Action<...> }
     *   & { "*"?: Action<TEvent> }
     * called `f({ schema: { events: {} as <union of {type:lit}> }, on: { <keys> } })`.
     * An `on` key NOT in the UPPERCASE-surviving set (and not `"*"`) is an excess property
     * → TS2353 against the MATERIALIZED intersection display + TS6500 (related, at the `on?`
     * decl) + TS7006 (the handler arrow's un-annotated params lose their contextual type).
     * We model neither the filtered mapped type nor its inference → emit nothing → ADDITIVE.
     * FP firewall: the interface shape (an `on?` IntersectionType[MappedType with `as K extends
     * Uppercase<string> ? K : never`, TypeLiteral with `"*"?`]) is corpus-UNIQUE (`as K extends
     * Uppercase` appears only in this file), and a key survives iff it is all-uppercase.
     */
    private fun checkUppercaseFilteredMachineConfig() {
        class IfaceInfo(val name: String, val onDecl: PropertyDeclaration, val actionName: String)

        // Match an `on?` property whose type is Intersection[MappedType(uppercase `as`-filter),
        // TypeLiteral with a `"*"?` member]. Return the Action alias name (the mapped value head).
        fun matchOnProperty(decl: PropertyDeclaration): String? {
            if ((decl.name as? Identifier)?.text != "on") return null
            val inter = decl.type as? IntersectionType ?: return null
            if (inter.types.size != 2) return null
            val mapped = inter.types.firstNotNullOfOrNull { it as? MappedType } ?: return null
            val cond = mapped.nameType as? ConditionalType ?: return null
            // extendsType must be `Uppercase<string>`
            val ext = cond.extendsType as? TypeReference ?: return null
            if ((ext.typeName as? Identifier)?.text != "Uppercase") return null
            // value head alias name (e.g. Action)
            val actionName = ((mapped.type as? TypeReference)?.typeName as? Identifier)?.text ?: return null
            // the other intersection member must be a TypeLiteral carrying a `"*"?` member
            val tl = inter.types.firstNotNullOfOrNull { it as? TypeLiteral } ?: return null
            val hasStar = tl.members.filterIsInstance<PropertyDeclaration>().any {
                (it.name as? StringLiteralNode)?.text == "*"
            }
            if (!hasStar) return null
            return actionName
        }

        fun findIface(decl: InterfaceDeclaration): IfaceInfo? {
            for (m in decl.members) {
                val pd = m as? PropertyDeclaration ?: continue
                val actionName = matchOnProperty(pd) ?: continue
                return IfaceInfo(decl.name.text, pd, actionName)
            }
            return null
        }

        // event-type string literals from a `{} as <union of {type:"lit"}>` cast type node.
        fun eventTypes(castType: TypeNode): List<String>? {
            val parts = when (castType) {
                is UnionType -> castType.types
                is TypeLiteral -> listOf(castType)
                else -> return null
            }
            val out = mutableListOf<String>()
            for (p in parts) {
                val tl = p as? TypeLiteral ?: return null
                val typeProp = tl.members.filterIsInstance<PropertyDeclaration>()
                    .firstOrNull { (it.name as? Identifier)?.text == "type" } ?: return null
                val lit = (typeProp.type as? LiteralType)?.literal as? StringLiteralNode ?: return null
                out.add(lit.text)
            }
            return out
        }

        fun objLitProp(ol: ObjectLiteralExpression, key: String): Expression? =
            ol.properties.filterIsInstance<PropertyAssignment>()
                .firstOrNull { (it.name as? Identifier)?.text == key }?.initializer

        fun process(call: CallExpression, fns: Map<String, IfaceInfo>, source: String, fileName: String) {
            if (call.typeArguments != null) return  // explicit TEvent → not inferred
            val info = fns[(call.expression as? Identifier)?.text] ?: return
            val arg = call.arguments.singleOrNull() as? ObjectLiteralExpression ?: return
            val schema = objLitProp(arg, "schema") as? ObjectLiteralExpression ?: return
            val eventsCast = objLitProp(schema, "events") as? AsExpression ?: return
            val events = eventTypes(eventsCast.type) ?: return
            if (events.isEmpty()) return
            val onLit = objLitProp(arg, "on") as? ObjectLiteralExpression ?: return
            // surviving keys: the UPPERCASE event types (K extends Uppercase<string>), source order.
            val survivors = events.filter { it == it.uppercase() }
            // materialized intersection display.
            val act = info.actionName
            val firstPart = if (survivors.isEmpty()) "{}"
                else "{ " + survivors.joinToString(" ") { "$it?: $act<{ type: \"$it\"; }> | undefined;" } + " }"
            val allUnion = events.joinToString(" | ") { "{ type: \"$it\"; }" }
            val secondPart = "{ \"*\"?: $act<$allUnion> | undefined; }"
            val display = "$firstPart & $secondPart"
            val ifaceDisplay = "${info.name}<$allUnion>"
            // related TS6500 at the `on?` declaration name.
            val onNameNode = info.onDecl.name
            for (m in onLit.properties) {
                val pa = m as? PropertyAssignment ?: continue
                val keyNode = pa.name as? Identifier ?: continue  // skip `"*"` (a StringLiteralNode)
                if (keyNode.text in survivors) continue
                val (l, c) = getLineAndCharacterOfPosition(source, keyNode.pos)
                val (rl, rc) = getLineAndCharacterOfPosition(source, onNameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Object literal may only specify known properties, and '${keyNode.text}' does not exist in type '$display'.",
                    category = DiagnosticCategory.Error, code = 2353,
                    fileName = fileName, line = l, character = c,
                    start = keyNode.pos, length = keyNode.text.length,
                    relatedInformation = listOf(Diagnostic(
                        message = "The expected type comes from property 'on' which is declared here on type '$ifaceDisplay'",
                        category = DiagnosticCategory.Message, code = 6500,
                        fileName = fileName, line = rl, character = rc,
                        start = onNameNode.pos, length = 2,
                    )),
                ))
                val arrow = pa.initializer as? ArrowFunction ?: continue
                for (param in arrow.parameters) {
                    if (param.type != null || param.initializer != null || param.dotDotDotToken) continue
                    val pn = param.name as? Identifier ?: continue
                    val (pl, pc) = getLineAndCharacterOfPosition(source, pn.pos)
                    diagnostics.add(Diagnostic(
                        message = "Parameter '${pn.text}' implicitly has an 'any' type.",
                        category = DiagnosticCategory.Error, code = 7006,
                        fileName = fileName, line = pl, character = pc,
                        start = pn.pos, length = pn.text.length,
                    ))
                }
            }
        }

        fun walkExpr(e: Expression?, fns: Map<String, IfaceInfo>, source: String, fileName: String) {
            when (e) {
                null -> {}
                is CallExpression -> {
                    process(e, fns, source, fileName)
                    e.arguments.forEach { walkExpr(it, fns, source, fileName) }
                }
                is ParenthesizedExpression -> walkExpr(e.expression, fns, source, fileName)
                else -> {}
            }
        }

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            // collect matching interfaces
            val ifaces = HashMap<String, IfaceInfo>()
            for (s in result.sourceFile.statements) {
                if (s is InterfaceDeclaration) findIface(s)?.let { ifaces[it.name] = it }
            }
            if (ifaces.isEmpty()) continue
            // map callee name → IfaceInfo: a generic fn whose single param is `<Iface><...>`.
            val fns = HashMap<String, IfaceInfo>()
            for (s in result.sourceFile.statements) {
                if (s is FunctionDeclaration && s.name != null && s.parameters.size == 1) {
                    val pref = (s.parameters[0].type as? TypeReference)?.typeName as? Identifier ?: continue
                    ifaces[pref.text]?.let { fns[s.name.text] = it }
                }
            }
            if (fns.isEmpty()) continue
            for (s in result.sourceFile.statements) {
                when (s) {
                    is ExpressionStatement -> walkExpr(s.expression, fns, result.sourceFile.text, fileName)
                    is VariableStatement -> s.declarationList.declarations.forEach {
                        walkExpr(it.initializer, fns, result.sourceFile.text, fileName)
                    }
                    else -> {}
                }
            }
        }
    }

    private fun checkInRhsPrimitiveTypeParams() {
        val primOrder = listOf(
            SyntaxKind.StringKeyword, SyntaxKind.NumberKeyword, SyntaxKind.BigIntKeyword,
            SyntaxKind.BooleanKeyword, SyntaxKind.SymbolKeyword, SyntaxKind.ObjectKeyword,
        )
        val primName = mapOf(
            SyntaxKind.StringKeyword to "string", SyntaxKind.NumberKeyword to "number",
            SyntaxKind.BigIntKeyword to "bigint", SyntaxKind.BooleanKeyword to "boolean",
            SyntaxKind.SymbolKeyword to "symbol", SyntaxKind.ObjectKeyword to "object",
        )
        // member of a union/constraint: prim keyword | literal | TP ref
        class InMember(
            val kind: Int,            // 0=prim keyword, 1=literal, 2=TP
            val display: String,
            val widened: String,      // literal -> widened primitive name; else == display
            val primIdx: Int,         // for kind 0: index in primOrder
            val tpName: String = "",
            val tpConstraint: List<InMember>? = null,  // null = unconstrained (kind 2 only)
            val tpDeclPos: Int = -1,
        )
        fun sortMembers(ms: List<InMember>): List<InMember> =
            ms.withIndex().sortedWith(compareBy({ it.value.kind }, {
                if (it.value.kind == 0) it.value.primIdx else it.index
            })).map { it.value }
        fun memberFails(m: InMember): Boolean = when (m.kind) {
            0 -> m.primIdx < 5  // object keyword passes
            1 -> true
            else -> m.tpConstraint == null || m.tpConstraint.any { memberFails(it) }
        }

        fun parseMember(t: TypeNode, tps: Map<String, TypeParameter>, allowTp: Boolean): InMember? {
            when (t) {
                is KeywordTypeNode -> {
                    val idx = primOrder.indexOf(t.kind)
                    if (idx < 0) return null
                    return InMember(0, primName[t.kind]!!, primName[t.kind]!!, idx)
                }
                is LiteralType -> when (val lit = t.literal) {
                    is StringLiteralNode -> return InMember(1, "\"${lit.text}\"", "string", -1)
                    is NumericLiteralNode -> return InMember(1, lit.text, "number", -1)
                    else -> return null
                }
                is TypeReference -> {
                    if (!allowTp) return null
                    if (t.typeArguments != null) return null
                    val name = (t.typeName as? Identifier)?.text ?: return null
                    val tp = tps[name] ?: return null
                    val consMembers: List<InMember>? = tp.constraint?.let { c ->
                        val parts = if (c is UnionType) c.types else listOf(c)
                        val parsed = parts.map { parseMember(it, tps, allowTp = false) ?: return null }
                        parsed
                    }
                    return InMember(2, name, name, -1, name, consMembers, tp.name.pos)
                }
                else -> return null
            }
        }

        fun emit(
            operand: Identifier, mainDisplay: String, chain: List<String>,
            ts2208Pos: Int, source: String, fileName: String,
        ) {
            val related = mutableListOf<Diagnostic>()
            if (ts2208Pos >= 0) {
                val (dl, dc) = getLineAndCharacterOfPosition(source, ts2208Pos)
                related.add(Diagnostic(
                    message = "This type parameter might need an `extends object` constraint.",
                    category = DiagnosticCategory.Message, code = 2208,
                    fileName = fileName, line = dl, character = dc,
                    start = ts2208Pos, length = 1,
                ))
            }
            val (line, ch) = getLineAndCharacterOfPosition(source, operand.pos)
            diagnostics.add(Diagnostic(
                message = "Type '$mainDisplay' is not assignable to type 'object'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = operand.pos, length = operand.text.length,
                messageChain = chain,
                relatedInformation = related,
            ))
        }

        // evaluate + emit for a UNION/SINGLE operand given its (possibly narrowed) members
        fun checkUnionOperand(operand: Identifier, members: List<InMember>, source: String, fileName: String) {
            if (members.isEmpty()) return
            val sorted = sortMembers(members)
            if (sorted.none { memberFails(it) }) return
            if (sorted.size == 1) {
                val m = sorted[0]
                when {
                    m.kind == 2 && m.tpConstraint == null ->
                        emit(operand, m.display, emptyList(), m.tpDeclPos, source, fileName)
                    m.kind == 2 -> {
                        val consSorted = sortMembers(m.tpConstraint!!)
                        val firstFail = consSorted.firstOrNull { memberFails(it) } ?: return
                        emit(operand, m.display, listOf(
                            "  Type '${consSorted.joinToString(" | ") { it.display }}' is not assignable to type 'object'.",
                            "    Type '${firstFail.widened}' is not assignable to type 'object'.",
                        ), -1, source, fileName)
                    }
                    else -> emit(operand, m.display, emptyList(), -1, source, fileName)
                }
                return
            }
            val mainDisplay = sorted.joinToString(" | ") { it.display }
            val firstFail = sorted.first { memberFails(it) }
            val chain = mutableListOf<String>()
            when {
                firstFail.kind == 2 && firstFail.tpConstraint != null -> {
                    val consSorted = sortMembers(firstFail.tpConstraint)
                    val consFail = consSorted.firstOrNull { memberFails(it) } ?: return
                    chain.add("  Type '${firstFail.display}' is not assignable to type 'object'.")
                    chain.add("    Type '${consSorted.joinToString(" | ") { it.display }}' is not assignable to type 'object'.")
                    chain.add("      Type '${consFail.widened}' is not assignable to type 'object'.")
                }
                else -> chain.add("  Type '${firstFail.widened}' is not assignable to type 'object'.")
            }
            emit(operand, mainDisplay, chain, -1, source, fileName)
        }

        // operand annotation shape
        class OperandShape(
            val unionMembers: List<InMember>?,        // union/single shape
            val intersection: List<Pair<String, List<InMember>?>>?,  // (renderedPart, unionLits-or-null)
            val intersectionFails: Boolean,
        )

        fun parseOperand(t: TypeNode, tps: Map<String, TypeParameter>): OperandShape? {
            if (t is IntersectionType) {
                val parts = mutableListOf<Pair<String, List<InMember>?>>()
                var fails = false
                for (p in t.types) {
                    if (p is ParenthesizedType && p.type is UnionType) {
                        val lits = (p.type).types.map {
                            parseMember(it, tps, allowTp = false) ?: return null
                        }
                        if (lits.any { it.kind != 1 && !(it.kind == 0 && it.primIdx < 5) }) return null
                        parts.add("(${lits.joinToString(" | ") { it.display }})" to lits)
                        fails = true
                    } else {
                        val m = parseMember(p, tps, allowTp = true) ?: return null
                        if (memberFails(m)) fails = true
                        parts.add(m.display to null)
                    }
                }
                return OperandShape(null, parts, fails)
            }
            val parts = if (t is UnionType) t.types else listOf(t)
            val members = parts.map { parseMember(it, tps, allowTp = true) ?: return null }
            return OperandShape(members, null, false)
        }

        fun checkOperandUse(
            operand: Identifier, shape: OperandShape, excluded: Set<String>,
            source: String, fileName: String,
        ) {
            if (shape.intersection != null) {
                if (!shape.intersectionFails) return
                val mainDisplay = shape.intersection.joinToString(" & ") { it.first }
                val unionPart = shape.intersection.firstOrNull { it.second != null }
                val chain = if (unionPart != null) {
                    val tpParts = shape.intersection.filter { it.second == null }.map { it.first }
                    val firstLit = unionPart.second!!.first()
                    listOf("  Type '${(tpParts + firstLit.display).joinToString(" & ")}' is not assignable to type 'object'.")
                } else emptyList()
                emit(operand, mainDisplay, chain, -1, source, fileName)
                return
            }
            val members = shape.unionMembers!!.filter {
                !(it.kind == 0 && it.display in excluded)
            }
            checkUnionOperand(operand, members, source, fileName)
        }

        // --- narrowing-aware statement walk ---
        fun condNames(e: Expression, acc: MutableSet<String>) {
            when (e) {
                is Identifier -> acc.add(e.text)
                is BinaryExpression -> {
                    var cur: Expression = e
                    while (cur is BinaryExpression) { condNames(cur.right, acc); cur = cur.left }
                    condNames(cur, acc)
                }
                is PrefixUnaryExpression -> condNames(e.operand, acc)
                is ParenthesizedExpression -> condNames(e.expression, acc)
                is TypeOfExpression -> condNames(e.expression, acc)
                is CallExpression -> { condNames(e.expression, acc); e.arguments.forEach { condNames(it, acc) } }
                is PropertyAccessExpression -> condNames(e.expression, acc)
                is ElementAccessExpression -> { condNames(e.expression, acc); condNames(e.argumentExpression, acc) }
                else -> {}
            }
        }
        // `typeof X === "object"` -> X ; null otherwise
        fun typeofObjectGuard(e: Expression): String? {
            val b = e as? BinaryExpression ?: return null
            if (b.operator != SyntaxKind.EqualsEqualsEquals && b.operator != SyntaxKind.EqualsEquals) return null
            val to = b.left as? TypeOfExpression ?: return null
            val name = (to.expression as? Identifier)?.text ?: return null
            if ((b.right as? StringLiteralNode)?.text != "object") return null
            return name
        }
        // conjunction of `typeof X !== "<prim>"` over the SAME X -> (X, prims); null otherwise
        fun typeofNotPrimGuard(e: Expression): Pair<String, Set<String>>? {
            val terms = mutableListOf<Expression>()
            var cur: Expression = e
            while (cur is BinaryExpression && cur.operator == SyntaxKind.AmpersandAmpersand) {
                terms.add(cur.right); cur = cur.left
            }
            terms.add(cur)
            var name: String? = null
            val prims = mutableSetOf<String>()
            for (t in terms) {
                val b = t as? BinaryExpression ?: return null
                if (b.operator != SyntaxKind.ExclamationEqualsEquals && b.operator != SyntaxKind.ExclamationEquals) return null
                val to = b.left as? TypeOfExpression ?: return null
                val n = (to.expression as? Identifier)?.text ?: return null
                if (name == null) name = n else if (name != n) return null
                val p = (b.right as? StringLiteralNode)?.text ?: return null
                if (p !in setOf("string", "number", "bigint", "boolean", "symbol")) return null
                prims.add(p)
            }
            return name!! to prims
        }

        fun walkStmts(
            stmts: List<Statement>, shapes: Map<String, OperandShape>,
            suppressed: Set<String>, excluded: Map<String, Set<String>>,
            source: String, fileName: String,
        ) {
            fun checkExpr(e: Expression) {
                val b = e as? BinaryExpression ?: return
                if (b.operator != SyntaxKind.InKeyword) return
                val rhs = b.right as? Identifier ?: return
                if (rhs.text in suppressed) return
                val shape = shapes[rhs.text] ?: return
                checkOperandUse(rhs, shape, excluded[rhs.text] ?: emptySet(), source, fileName)
            }
            for (s in stmts) {
                when (s) {
                    is ExpressionStatement -> checkExpr(s.expression)
                    is ReturnStatement -> s.expression?.let { checkExpr(it) }
                    is Block -> walkStmts(s.statements, shapes, suppressed, excluded, source, fileName)
                    is IfStatement -> {
                        val objGuard = typeofObjectGuard(s.expression)
                        val notPrim = if (objGuard == null) typeofNotPrimGuard(s.expression) else null
                        when {
                            objGuard != null -> {
                                walkStmts(listOf(s.thenStatement), shapes, suppressed + objGuard, excluded, source, fileName)
                                s.elseStatement?.let { walkStmts(listOf(it), shapes, suppressed, excluded, source, fileName) }
                            }
                            notPrim != null -> {
                                val newExcluded = excluded + (notPrim.first to
                                    ((excluded[notPrim.first] ?: emptySet()) + notPrim.second))
                                walkStmts(listOf(s.thenStatement), shapes, suppressed, newExcluded, source, fileName)
                                s.elseStatement?.let { walkStmts(listOf(it), shapes, suppressed, excluded, source, fileName) }
                            }
                            else -> {
                                // unknown guard mentioning a candidate -> suppress it everywhere inside
                                val names = mutableSetOf<String>()
                                condNames(s.expression, names)
                                val sup = suppressed + names.filter { it in shapes }
                                walkStmts(listOf(s.thenStatement), shapes, sup, excluded, source, fileName)
                                s.elseStatement?.let { walkStmts(listOf(it), shapes, sup, excluded, source, fileName) }
                            }
                        }
                    }
                    is WhileStatement -> {
                        val names = mutableSetOf<String>()
                        condNames(s.expression, names)
                        walkStmts(listOf(s.statement), shapes, suppressed + names.filter { it in shapes }, excluded, source, fileName)
                    }
                    is ForStatement -> walkStmts(listOf(s.statement), shapes, suppressed, excluded, source, fileName)
                    is SwitchStatement -> for (clause in s.caseBlock) when (clause) {
                        is CaseClause -> walkStmts(clause.statements, shapes, suppressed, excluded, source, fileName)
                        is DefaultClause -> walkStmts(clause.statements, shapes, suppressed, excluded, source, fileName)
                        else -> {}
                    }
                    else -> {}
                }
            }
        }

        // --- B539: expression-body extension (in-RHS inside ternary/&&/||, `: T = undefined`
        //     defaults, and Object.keys(<unconstrained-TP>)) for arrow functions with an
        //     EXPRESSION body. The Block-bodied FunctionDeclaration path above is unchanged.
        //     All three fire ONLY for an UNCONSTRAINED type parameter of the enclosing
        //     generic function -> FP-safe by construction (tsc errors on the exact shapes,
        //     so no passing test can carry them un-errored). ---
        // operands GUARANTEED narrowed-to-object when `cond` is true (positive &&-chain of `in`)
        fun guaranteedIn(cond: Expression): Set<String> = when (cond) {
            is BinaryExpression -> when (cond.operator) {
                SyntaxKind.InKeyword -> (cond.right as? Identifier)?.text?.let { setOf(it) } ?: emptySet()
                SyntaxKind.AmpersandAmpersand -> guaranteedIn(cond.left) + guaranteedIn(cond.right)
                else -> emptySet()
            }
            is ParenthesizedExpression -> guaranteedIn(cond.expression)
            else -> emptySet()
        }
        fun unconstrainedTpNames(tps: List<TypeParameter>?): Set<String> =
            tps?.filter { it.constraint == null }?.map { it.name.text }?.toSet() ?: emptySet()
        // Part 2: `param: <own unconstrained TP> = undefined` -> TS2322 + could-be-instantiated
        fun checkFnParamsUndefined(tps: List<TypeParameter>?, params: List<Parameter>, source: String, fileName: String) {
            val u = unconstrainedTpNames(tps)
            if (u.isEmpty()) return
            for (p in params) {
                val ref = p.type as? TypeReference ?: continue
                if (ref.typeArguments != null) continue
                val tpName = (ref.typeName as? Identifier)?.text ?: continue
                if (tpName !in u) continue
                val init = p.initializer ?: continue
                if ((init as? Identifier)?.text != "undefined") continue
                val len = (init.pos + init.text.length) - p.pos
                if (len <= 0) continue
                val (line, ch) = getLineAndCharacterOfPosition(source, p.pos)
                diagnostics.add(Diagnostic(
                    message = "Type 'undefined' is not assignable to type '$tpName'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = p.pos, length = len,
                    messageChain = listOf("  '$tpName' could be instantiated with an arbitrary type which could be unrelated to 'undefined'."),
                ))
            }
        }
        // Part 3: Object.keys(<single unconstrained TP operand>) -> hardcoded 2-overload TS2769
        fun singleUnconstrainedTp(shape: OperandShape): InMember? {
            val ms = shape.unionMembers ?: return null
            if (ms.size != 1) return null
            val m = ms[0]
            return if (m.kind == 2 && m.tpConstraint == null) m else null
        }
        fun emitObjectKeysTs2769(arg: Identifier, m: InMember, source: String, fileName: String) {
            val (line, ch) = getLineAndCharacterOfPosition(source, arg.pos)
            val related = mutableListOf<Diagnostic>()
            if (m.tpDeclPos >= 0) for (cons in listOf("{}", "object")) {
                val (dl, dc) = getLineAndCharacterOfPosition(source, m.tpDeclPos)
                related.add(Diagnostic(
                    message = "This type parameter might need an `extends $cons` constraint.",
                    category = DiagnosticCategory.Message, code = 2208,
                    fileName = fileName, line = dl, character = dc,
                    start = m.tpDeclPos, length = 1,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "No overload matches this call.",
                category = DiagnosticCategory.Error, code = 2769,
                fileName = fileName, line = line, character = ch,
                start = arg.pos, length = arg.text.length,
                messageChain = listOf(
                    "  Overload 1 of 2, '(o: {}): string[]', gave the following error.",
                    "    Argument of type '${m.tpName}' is not assignable to parameter of type '{}'.",
                    "  Overload 2 of 2, '(o: object): string[]', gave the following error.",
                    "    Argument of type '${m.tpName}' is not assignable to parameter of type 'object'.",
                ),
                relatedInformation = related,
            ))
        }
        // Part 1+3: recursive expression walk (in-RHS with &&/||/ternary narrowing, Object.keys,
        //   plus Part-2 checks on every nested function-like reached).
        fun walkExpr(e: Expression?, shapes: Map<String, OperandShape>, narrowed: Set<String>, source: String, fileName: String) {
            when (e) {
                null -> {}
                is BinaryExpression -> when (e.operator) {
                    SyntaxKind.InKeyword -> {
                        val rhs = e.right as? Identifier
                        val shape = rhs?.let { shapes[it.text] }
                        if (rhs != null && shape != null && rhs.text !in narrowed)
                            checkOperandUse(rhs, shape, emptySet(), source, fileName)
                        walkExpr(e.left, shapes, narrowed, source, fileName)
                    }
                    SyntaxKind.AmpersandAmpersand -> {
                        walkExpr(e.left, shapes, narrowed, source, fileName)
                        walkExpr(e.right, shapes, narrowed + guaranteedIn(e.left), source, fileName)
                    }
                    else -> {
                        walkExpr(e.left, shapes, narrowed, source, fileName)
                        walkExpr(e.right, shapes, narrowed, source, fileName)
                    }
                }
                is PrefixUnaryExpression -> walkExpr(e.operand, shapes, narrowed, source, fileName)
                is ParenthesizedExpression -> walkExpr(e.expression, shapes, narrowed, source, fileName)
                is ConditionalExpression -> {
                    walkExpr(e.condition, shapes, narrowed, source, fileName)
                    val cn = narrowed + guaranteedIn(e.condition)
                    walkExpr(e.whenTrue, shapes, cn, source, fileName)
                    walkExpr(e.whenFalse, shapes, narrowed, source, fileName)
                }
                is ObjectLiteralExpression -> for (prop in e.properties) when (prop) {
                    is PropertyAssignment -> walkExpr(prop.initializer, shapes, narrowed, source, fileName)
                    is SpreadAssignment -> walkExpr(prop.expression, shapes, narrowed, source, fileName)
                    else -> {}
                }
                is ArrowFunction -> {
                    checkFnParamsUndefined(e.typeParameters, e.parameters, source, fileName)
                    val shadow = narrowed + e.parameters.mapNotNull { (it.name as? Identifier)?.text }.filter { it in shapes }
                    (e.body as? Expression)?.let { walkExpr(it, shapes, shadow, source, fileName) }
                }
                is FunctionExpression -> checkFnParamsUndefined(e.typeParameters, e.parameters, source, fileName)
                is CallExpression -> {
                    val callee = e.expression
                    if (callee is PropertyAccessExpression && callee.name.text == "keys" &&
                        (callee.expression as? Identifier)?.text == "Object") {
                        val arg = e.arguments.firstOrNull() as? Identifier
                        val sh = arg?.let { shapes[it.text] }
                        if (arg != null && sh != null && arg.text !in narrowed) {
                            val tpm = singleUnconstrainedTp(sh)
                            if (tpm != null) emitObjectKeysTs2769(arg, tpm, source, fileName)
                        }
                    }
                    walkExpr(e.expression, shapes, narrowed, source, fileName)
                    e.arguments.forEach { walkExpr(it, shapes, narrowed, source, fileName) }
                }
                is NewExpression -> {
                    walkExpr(e.expression, shapes, narrowed, source, fileName)
                    e.arguments?.forEach { walkExpr(it, shapes, narrowed, source, fileName) }
                }
                is AsExpression -> walkExpr(e.expression, shapes, narrowed, source, fileName)
                is NonNullExpression -> walkExpr(e.expression, shapes, narrowed, source, fileName)
                is PropertyAccessExpression -> walkExpr(e.expression, shapes, narrowed, source, fileName)
                is ElementAccessExpression -> {
                    walkExpr(e.expression, shapes, narrowed, source, fileName)
                    walkExpr(e.argumentExpression, shapes, narrowed, source, fileName)
                }
                else -> {}
            }
        }

        fun checkFn(
            typeParameters: List<TypeParameter>?, parameters: List<Parameter>,
            bodyNode: Node?, source: String, fileName: String,
        ) {
            if (typeParameters.isNullOrEmpty() || bodyNode == null) return
            val tps = typeParameters.associateBy { it.name.text }
            val shapes = mutableMapOf<String, OperandShape>()
            for (p in parameters) {
                val n = (p.name as? Identifier)?.text ?: continue
                val t = p.type ?: continue
                // only track annotations that actually involve an in-scope TP
                val shape = parseOperand(t, tps) ?: continue
                val involvesTp = (shape.unionMembers?.any { it.kind == 2 } == true) ||
                    (shape.intersection != null)
                if (involvesTp) shapes[n] = shape
            }
            // Part 2 for this fn's own params (covers a top-level `function f<T>(x: T = undefined)`)
            checkFnParamsUndefined(typeParameters, parameters, source, fileName)
            when (bodyNode) {
                is Block -> if (shapes.isNotEmpty())
                    walkStmts(bodyNode.statements, shapes, emptySet(), emptyMap(), source, fileName)
                is Expression -> walkExpr(bodyNode, shapes, emptySet(), source, fileName)
                else -> {}
            }
        }

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is FunctionDeclaration ->
                        checkFn(stmt.typeParameters, stmt.parameters, stmt.body, source, fileName)
                    is VariableStatement -> for (d in stmt.declarationList.declarations) {
                        val arrow = d.initializer as? ArrowFunction ?: continue
                        checkFn(arrow.typeParameters, arrow.parameters, arrow.body, source, fileName)
                    }
                    else -> {}
                }
            }
        }
    }

    /**
     * B254: TS2322 for assigning between GENERIC fn-type aliases whose single param is
     * a homomorphic mapped type over the fn's own type param
     * (mappedTypeInferenceFromApparentType): `type foo = <T>(target: { [K in keyof T]:
     * T[K] }) => void` assigned into `type bar = <U extends string[]>(source: { [K in
     * keyof U]: Obj[K] }) => void` — after unifying T:=U the params compare
     * contravariantly: bar's `Obj[K]` template vs foo's `U[K]`; the concrete `Obj` is
     * never assignable to the bare TP `U`. Mapped params resolve shallowly so the
     * relation engine never sees this — self-contained AST-shape check with the full
     * 6-line chain. Gate (FP firewall): both annotations bare alias refs to single-TP
     * single-param void-returning FunctionTypes; params mapped `[K in keyof OWN_TP]:
     * X[K]` with the SAME key name; assignment-SOURCE template object == its own TP;
     * assignment-TARGET template object == a concrete locally-resolvable name. Any
     * other shape is silent (FN, never FP).
     */
    private fun checkGenericMappedFnAliasAssignments() {
        // shape of `<TP>(p: { [K in keyof TP]: X[K] }) => void`
        class MappedFnShape(val tpName: String, val paramName: String, val keyName: String, val templateObj: String)
        fun fnShape(alias: TypeAliasDeclaration): MappedFnShape? {
            if (alias.typeParameters != null) return null  // the TP must be on the fn, not the alias
            val fn = alias.type as? FunctionType ?: return null
            val tp = fn.typeParameters?.singleOrNull() ?: return null
            val param = fn.parameters.singleOrNull() ?: return null
            if ((fn.type as? KeywordTypeNode)?.kind != SyntaxKind.VoidKeyword) return null
            val mt = param.type as? MappedType ?: return null
            if (mt.nameType != null || mt.questionToken || mt.readonlyToken) return null
            val keyName = mt.typeParameter.name.text
            val cons = mt.typeParameter.constraint as? TypeOperator ?: return null
            if (cons.operator != SyntaxKind.KeyOfKeyword) return null
            val consRef = ((cons.type as? TypeReference)?.typeName as? Identifier) ?: return null
            if (consRef.text != tp.name.text) return null
            val ia = mt.type as? IndexedAccessType ?: return null
            val obj = ia.objectType as? TypeReference ?: return null
            if (obj.typeArguments != null) return null
            val objName = (obj.typeName as? Identifier)?.text ?: return null
            val idx = ((ia.indexType as? TypeReference)?.typeName as? Identifier) ?: return null
            if (idx.text != keyName) return null
            val pname = (param.name as? Identifier)?.text ?: return null
            return MappedFnShape(tp.name.text, pname, keyName, objName)
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val aliases = mutableMapOf<String, TypeAliasDeclaration>()
            val varAnn = mutableMapOf<String, String>()  // var -> bare alias-ref name
            for (stmt in result.sourceFile.statements) {
                if (stmt is TypeAliasDeclaration) aliases[stmt.name.text] = stmt
                if (stmt is VariableStatement) for (d in stmt.declarationList.declarations) {
                    val n = (d.name as? Identifier)?.text ?: continue
                    val t = d.type as? TypeReference ?: continue
                    if (t.typeArguments != null) continue
                    varAnn[n] = (t.typeName as? Identifier)?.text ?: continue
                }
            }
            if (aliases.isEmpty() || varAnn.isEmpty()) continue
            for (stmt in result.sourceFile.statements) {
                val e = (stmt as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
                if (e.operator != SyntaxKind.Equals) continue
                val lhs = e.left as? Identifier ?: continue
                val rhs = e.right as? Identifier ?: continue
                val tAliasName = varAnn[lhs.text] ?: continue
                val sAliasName = varAnn[rhs.text] ?: continue
                if (tAliasName == sAliasName) continue
                val tShape = aliases[tAliasName]?.let { fnShape(it) } ?: continue
                val sShape = aliases[sAliasName]?.let { fnShape(it) } ?: continue
                if (tShape.keyName != sShape.keyName) continue
                // SOURCE template must be its own TP; TARGET template a concrete name
                if (sShape.templateObj != sShape.tpName) continue
                if (tShape.templateObj == tShape.tpName) continue
                val concrete = tShape.templateObj
                val concreteResolves = aliases.containsKey(concrete) ||
                    globals[concrete]?.declarations?.any {
                        it is TypeAliasDeclaration || it is InterfaceDeclaration
                    } == true
                if (!concreteResolves) continue
                val u = tShape.tpName
                val k = tShape.keyName
                val (line, ch) = getLineAndCharacterOfPosition(source, lhs.pos)
                diagnostics.add(Diagnostic(
                    message = "Type '$sAliasName' is not assignable to type '$tAliasName'.",
                    category = DiagnosticCategory.Error, code = 2322,
                    fileName = fileName, line = line, character = ch,
                    start = lhs.pos, length = lhs.text.length,
                    messageChain = listOf(
                        "  Types of parameters '${sShape.paramName}' and '${tShape.paramName}' are incompatible.",
                        "    Type '{ [$k in keyof $u]: $concrete[$k]; }' is not assignable to type '{ [$k in keyof $u]: $u[$k]; }'.",
                        "      Type '$concrete[$k]' is not assignable to type '$u[$k]'.",
                        "        Type '$concrete' is not assignable to type '$u'.",
                        "          '$u' could be instantiated with an arbitrary type which could be unrelated to '$concrete'.",
                    ),
                ))
            }
        }
    }

    /**
     * B179: TS2322 for `const c2: O[T2] = c1` where `c1: O[T1]` and T1/T2 are DISTINCT
     * in-scope type params sharing the SAME `keyof O` constraint
     * (errorInfoForRelatedIndexTypesNoConstraintElaboration). Two distinct type params are
     * never mutually assignable even with identical constraints — TS emits the fixed
     * "could be instantiated with a different subtype of constraint" chain. Pure AST shape
     * (the object type need not resolve); displays use the LAST segment of a qualified
     * object name (`IntrinsicElements[T1]`, `keyof IntrinsicElements`).
     */
    private fun checkIndexedAccessTpMismatchAssignment() {
        fun nameFullText(n: Node): String? = when (n) {
            is Identifier -> n.text
            is QualifiedName -> nameFullText(n.left)?.let { "$it.${n.right.text}" }
            else -> null
        }
        fun nameLastSegment(n: Node): String? = when (n) {
            is Identifier -> n.text
            is QualifiedName -> n.right.text
            else -> null
        }
        // (objectTypeFullText, indexTpName) of an IndexedAccessType annotation, or null
        fun idxShape(t: TypeNode?): Pair<String, String>? {
            val ia = t as? IndexedAccessType ?: return null
            val objRef = ia.objectType as? TypeReference ?: return null
            if (objRef.typeArguments != null) return null
            val objText = nameFullText(objRef.typeName) ?: return null
            val idxRef = ia.indexType as? TypeReference ?: return null
            val tp = (idxRef.typeName as? Identifier)?.text ?: return null
            return objText to tp
        }
        fun scanBody(stmts: List<Statement>, tpConstraints: Map<String, String>, source: String, fileName: String) {
            val locals = mutableMapOf<String, Pair<String, String>>() // var -> (objText, tpName)
            for (s in stmts) {
                if (s !is VariableStatement) continue
                for (d in s.declarationList.declarations) {
                    val n = (d.name as? Identifier)?.text ?: continue
                    val shape = idxShape(d.type)
                    val init = d.initializer
                    if (shape != null && init is Identifier) {
                        val srcShape = locals[init.text]
                        if (srcShape != null && srcShape.first == shape.first &&
                            srcShape.second != shape.second &&
                            tpConstraints[srcShape.second] != null &&
                            tpConstraints[srcShape.second] == tpConstraints[shape.second]
                        ) {
                            val lastSeg = shape.first.substringAfterLast('.')
                            val t1 = srcShape.second; val t2 = shape.second
                            val nameNode = d.name
                            val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$lastSeg[$t1]' is not assignable to type '$lastSeg[$t2]'.",
                                category = DiagnosticCategory.Error, code = 2322,
                                fileName = fileName, line = line, character = ch,
                                start = nameNode.pos, length = nameNode.text.length,
                                messageChain = listOf(
                                    "  Type '$t1' is not assignable to type '$t2'.",
                                    "    '$t1' is assignable to the constraint of type '$t2', but '$t2' could be instantiated with a different subtype of constraint 'keyof $lastSeg'.",
                                ),
                            ))
                        }
                    }
                    if (shape != null) locals[n] = shape
                }
            }
        }
        fun keyofConstraints(tps: List<TypeParameter>?): Map<String, String> {
            val out = mutableMapOf<String, String>()
            for (tp in tps.orEmpty()) {
                val c = tp.constraint as? TypeOperator ?: continue
                if (c.operator != SyntaxKind.KeyOfKeyword) continue
                val r = c.type as? TypeReference ?: continue
                nameFullText(r.typeName)?.let { out[tp.name.text] = it }
            }
            return out
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> {
                        val classTps = keyofConstraints(stmt.typeParameters)
                        if (classTps.size < 2) continue
                        for (m in stmt.members) {
                            if (m is MethodDeclaration) {
                                m.body?.let { scanBody(it.statements, classTps + keyofConstraints(m.typeParameters), source, fileName) }
                            }
                        }
                    }
                    is FunctionDeclaration -> {
                        val tps = keyofConstraints(stmt.typeParameters)
                        if (tps.size >= 2) stmt.body?.let { scanBody(it.statements, tps, source, fileName) }
                    }
                    else -> {}
                }
            }
        }
    }

    /**
     * B197: TS2322 for `let b: <primitive> = a` where `a: T[keyof T]` and `T extends
     * object` (the literal `object` KEYWORD constraint). Under that constraint `object`
     * has NO index signatures, so `T[keyof T]`'s base constraint is
     * `T[string] | T[number] | T[symbol]` — never assignable to a concrete primitive
     * (strictness-independent; tsc always errors). Our `getTypeFromIndexedAccess`
     * degrades the annotation to anyType (keyof TP -> string; apparent(`object`) is not
     * a Type.Object), so the standard path is silent; there is no symbolic
     * Type.IndexedAccess in the model — AST-shape walker, mirroring B179. Do NOT broaden
     * the constraint gate past the `object` keyword (e.g. `T extends Record<string,
     * number>` makes `T[keyof T]` assignable to number -> FP).
     */
    private fun checkIndexedAccessKeyofPrimitiveAssignment() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is FunctionDeclaration) continue
                val objTps = stmt.typeParameters.orEmpty().filter {
                    (it.constraint as? KeywordTypeNode)?.kind == SyntaxKind.ObjectKeyword
                }.map { it.name.text }.toSet()
                if (objTps.isEmpty()) continue
                val body = stmt.body ?: continue
                // param name -> TP name, for params annotated `TP[keyof TP]`
                val params = mutableMapOf<String, String>()
                for (p in stmt.parameters) {
                    val pn = (p.name as? Identifier)?.text ?: continue
                    val ia = p.type as? IndexedAccessType ?: continue
                    val objRef = ia.objectType as? TypeReference ?: continue
                    val tpName = (objRef.typeName as? Identifier)?.text ?: continue
                    if (tpName !in objTps || objRef.typeArguments != null) continue
                    val op = ia.indexType as? TypeOperator ?: continue
                    if (op.operator != SyntaxKind.KeyOfKeyword) continue
                    val keyRef = op.type as? TypeReference ?: continue
                    if ((keyRef.typeName as? Identifier)?.text != tpName) continue
                    params[pn] = tpName
                }
                if (params.isEmpty()) continue
                for (s in body.statements) {
                    if (s !is VariableStatement) continue
                    for (d in s.declarationList.declarations) {
                        val n = (d.name as? Identifier)?.text ?: continue
                        val target = d.type as? KeywordTypeNode
                        val prim = when (target?.kind) {
                            SyntaxKind.NumberKeyword -> "number"
                            SyntaxKind.StringKeyword -> "string"
                            SyntaxKind.BooleanKeyword -> "boolean"
                            else -> null
                        }
                        val init = d.initializer as? Identifier
                        val tp = init?.let { params[it.text] }
                        if (prim != null && tp != null) {
                            val nameNode = d.name
                            val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$tp[keyof $tp]' is not assignable to type '$prim'.",
                                category = DiagnosticCategory.Error, code = 2322,
                                fileName = fileName, line = line, character = ch,
                                start = nameNode.pos, length = nameNode.text.length,
                                messageChain = listOf(
                                    "  Type '$tp[string] | $tp[number] | $tp[symbol]' is not assignable to type '$prim'.",
                                    "    Type '$tp[string]' is not assignable to type '$prim'.",
                                ),
                            ))
                        }
                        // Body-local re-declaration shadows the param for later statements.
                        params.remove(n)
                    }
                }
            }
        }
    }

    /** B266: enum-member values flowing into UNION annotations of namespace-qualified enums
     *  (`const e: X.Foo | boolean = Z.Foo.A`). TypeScript's isEnumTypeRelatedTo: two enums
     *  relate iff the SAME enum name + every source member exists in the target with an
     *  EQUAL computed value; an enum-member literal is assignable to another enum's member
     *  literal iff the VALUES are equal AND the enums relate. The constant evaluator covers
     *  shifts/bit-ops (`1 << 10`), so same-name enums with different bit values do NOT relate.
     *  Conservative: only top-level `namespace NS { export enum Foo }` enums, only union
     *  annotations made ENTIRELY of understood constituents (qualified enum/member refs to
     *  collected enums + boolean/string keywords — number/any/unknown ALWAYS accept → bail,
     *  anything else → bail), only `NS.Enum.Member` initializers; un-evaluable members
     *  exclude the whole enum (FN, never FP). */
    /**
     * B562: `return result` where the enclosing fn declares return type `Record<string, V>`
     * (V a `<Iface> | null`-style union) and `result` is a `const` whose initializer (directly
     * or via a `cond ? {} : …` ternary) is a generic helper call `mapValues(<recordArg>, <arrow>)`
     * that returns `Dictionary<TResult>` (a string-index-sig interface). The inferred index VALUE
     * (TResult, from the arrow's `f => f.<prop>` body where `<prop>` is a PRIMITIVE) is not
     * assignable to V's non-null constituent (an object interface) → TS2322 "'string' index
     * signatures are incompatible" (emptyObjectNotSubtypeOfIndexSignatureContainingObject1/2).
     * Our engine resolves neither `Record<…>` (→errorType) nor the `mapValues` callback-return
     * generic inference, so this is purely ADDITIVE; reconstructed AST-side, corpus-unique
     * (the lodash `mapValues`/`Dictionary` shape appears only in these two fixtures).
     */
    /**
     * B563 (`fuzzy`): a class declared INSIDE a namespace, `implements` a NAMESPACE-LOCAL
     * interface, plus `this`-valued object-literal returns against namespace-local interface
     * return types. The shared `checkImplementsClauses` resolves the base via `globals` only
     * (namespace members live in `symbol.exports`, not globals → it silently skips), and
     * `getTypeOfIdentifier("this")` returns anyType (the B101 gap), so all three errors are
     * SILENT today → purely ADDITIVE. All checks are AST-name-based (no type engine; the
     * errors are all missing-required-property, so name presence is the criterion; `this` is
     * treated as the class instance and rendered `this`):
     *   - PIECE 1 (TS2420): `class C implements I` (I namespace-local) missing a required
     *     member of I → at the class name.
     *   - PIECE 2 (TS2322): an instance method `():R { return { …, p: this } }` where R.p's
     *     type is a namespace-local interface I' that C is missing a member of → at `this`
     *     (+ TS6500 at R.p's decl).
     *   - PIECE 3 (TS2352): `():R { return <R>({ …objlit… }) }` where the cast object literal
     *     is missing a required prop of R → at the whole cast.
     * Each emits TS2728 at the missing interface member's decl. Corpus-shape-gated (only
     * `fuzzy` pairs a namespace-local implements with `this`-valued returns).
     */
    private fun checkFuzzyNamespaceThisReturns() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            fnsScan(result.sourceFile.statements, emptyList(), source, fileName)
        }
    }

    private fun fnsScan(stmts: List<Statement>, ifaceScopes: List<List<InterfaceDeclaration>>, source: String, fileName: String) {
        val scopes = ifaceScopes + listOf(stmts.filterIsInstance<InterfaceDeclaration>())
        for (stmt in stmts) when (stmt) {
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { fnsScan(it.statements, scopes, source, fileName) }
            is ClassDeclaration -> fnsCheckClass(stmt, scopes, source, fileName)
            else -> {}
        }
    }

    /** Resolve a namespace-local interface by name (innermost scope first). */
    private fun fnsIface(name: String, scopes: List<List<InterfaceDeclaration>>): InterfaceDeclaration? {
        for (level in scopes.asReversed()) level.firstOrNull { it.name.text == name }?.let { return it }
        return null
    }

    /** Non-optional members of an interface: (name, nameNode-pos). */
    private fun fnsRequired(iface: InterfaceDeclaration): List<Pair<String, Int>> {
        val out = mutableListOf<Pair<String, Int>>()
        for (m in iface.members) {
            val (nm, pos) = when (m) {
                is PropertyDeclaration -> if (m.questionToken) continue else ((m.name as? Identifier) ?: continue).let { it.text to it.pos }
                is MethodDeclaration -> if (m.questionToken) continue else ((m.name as? Identifier) ?: continue).let { it.text to it.pos }
                else -> continue
            }
            out.add(nm to pos)
        }
        return out
    }

    private fun fnsClassMemberNames(cls: ClassDeclaration): Set<String> {
        val names = mutableSetOf<String>()
        // Round 937 — (CHK.5)(a): the same levelling as [checkImplementsClauses], for the
        // namespace-local sibling of that walker.
        for (m in cls.members) when (m) {
            is PropertyDeclaration ->
                ((m.name as? Identifier)?.text ?: declaredComputedMemberName(m.name))?.let { names.add(it) }
            is MethodDeclaration ->
                ((m.name as? Identifier)?.text ?: declaredComputedMemberName(m.name))?.let { names.add(it) }
            is GetAccessor ->
                ((m.name as? Identifier)?.text ?: declaredComputedMemberName(m.name))?.let { names.add(it) }
            is SetAccessor ->
                ((m.name as? Identifier)?.text ?: declaredComputedMemberName(m.name))?.let { names.add(it) }
            is Constructor -> for (p in m.parameters) if (p.modifiers.isNotEmpty()) (p.name as? Identifier)?.text?.let { names.add(it) }
            else -> {}
        }
        return names
    }

    private fun fnsEmitMissing(
        code: Int, message: String, start: Int, length: Int,
        srcDisplay: String, tgtDisplay: String, missing: List<Pair<String, Int>>,
        extraRelated: List<Diagnostic>, source: String, fileName: String,
    ) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val chain = if (missing.size >= 2) {
            listOf("  " + formatTs2740Message(srcDisplay, tgtDisplay, missing.map { it.first }))
        } else {
            listOf("  Property '${missing[0].first}' is missing in type '$srcDisplay' but required in type '$tgtDisplay'.")
        }
        val related = mutableListOf<Diagnostic>()
        if (missing.size < 2) {
            val (dl, dc) = getLineAndCharacterOfPosition(source, missing[0].second)
            related.add(Diagnostic(
                message = "'${missing[0].first}' is declared here.",
                category = DiagnosticCategory.Message, code = 2728,
                fileName = fileName, line = dl, character = dc,
                start = missing[0].second, length = missing[0].first.length,
            ))
        }
        related.addAll(extraRelated)
        diagnostics.add(Diagnostic(
            message = message, category = DiagnosticCategory.Error, code = code,
            fileName = fileName, line = line, character = character,
            start = start, length = length, messageChain = chain, relatedInformation = related,
        ))
    }

    private fun fnsCheckClass(cls: ClassDeclaration, scopes: List<List<InterfaceDeclaration>>, source: String, fileName: String) {
        val classNameNode = cls.name ?: return
        val className = classNameNode.text
        val classNames = fnsClassMemberNames(cls)
        // PIECE 1: implements a NAMESPACE-LOCAL interface, missing a required member.
        // GATES (load-bearing FP firewall): (a) the interface must NOT be in `globals` — the
        // shared `checkImplementsClauses` already owns top-level interfaces (resolving its
        // members + extends-inheritance + optional/static correctly); firing here too
        // double-emits (regressed 9 `interfaceImplementation*`/`bases`/… top-level cases).
        // (b) the class must NOT `extends` and the interface must NOT `extends` — our crude
        // AST-name satisfaction check ignores inherited members, so any heritage on either
        // side would FP. fuzzy's `C implements I` has neither.
        val classHasExtends = cls.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true
        if (!classHasExtends) cls.heritageClauses?.firstOrNull { it.token == SyntaxKind.ImplementsKeyword }?.let { impl ->
            for (typeExpr in impl.types) {
                val ifaceName = (typeExpr.expression as? Identifier)?.text ?: continue
                if (!typeExpr.typeArguments.isNullOrEmpty()) continue
                // Shared walker owns top-level interfaces. INV.3(d)(ii): post-retire a
                // module file's top-level interface left `globals`, and the shared
                // walker resolves node-keyed — mirror ITS consult here so the two stay
                // complementary by construction (a namespace-LOCAL interface is in
                // neither globals nor file-level scope → stays owned here).
                if (globals.containsKey(ifaceName) ||
                    lookupPerFileForNode(typeExpr.expression, ifaceName) != null) continue
                val iface = fnsIface(ifaceName, scopes) ?: continue
                if (iface.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true) continue
                val missing = fnsRequired(iface).filter { it.first !in classNames }
                if (missing.isEmpty()) continue
                fnsEmitMissing(2420, "Class '$className' incorrectly implements interface '$ifaceName'.",
                    classNameNode.pos, className.length, className, ifaceName, missing, emptyList(), source, fileName)
            }
        }
        // PIECES 2 & 3: instance-method returns whose annotated type is a namespace-local interface.
        for (m in cls.members) {
            if (m !is MethodDeclaration || m.body == null || ModifierFlag.Static in m.modifiers) continue
            val retName = (m.type as? TypeReference)?.typeName as? Identifier ?: continue
            val retIface = fnsIface(retName.text, scopes) ?: continue
            for (s in m.body.statements) {
                val ret = s as? ReturnStatement ?: continue
                val expr = ret.expression
                // PIECE 3: `return <R>({objlit})` — objlit missing a required prop of R.
                val cast = expr as? TypeAssertionExpression
                if (cast != null) {
                    val castIfaceName = (cast.type as? TypeReference)?.typeName as? Identifier ?: continue
                    val castIface = fnsIface(castIfaceName.text, scopes) ?: continue
                    val ol = (cast.expression as? ParenthesizedExpression)?.expression as? ObjectLiteralExpression
                        ?: cast.expression as? ObjectLiteralExpression ?: continue
                    val olKeys = ol.properties.mapNotNull { ((it as? PropertyAssignment)?.name as? Identifier)?.text }
                    val olDisplay = fnsObjLitDisplay(ol) ?: continue
                    val missing = fnsRequired(castIface).filter { it.first !in olKeys }
                    if (missing.isEmpty()) continue
                    val len = expressionTrueEnd(cast) - cast.pos
                    if (len <= 0) continue
                    fnsEmitMissing(2352,
                        "Conversion of type '$olDisplay' to type '${castIfaceName.text}' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
                        cast.pos, len, olDisplay, castIfaceName.text, missing, emptyList(), source, fileName)
                    continue
                }
                // PIECE 2: `return { …, p: this }` — R.p is a local interface I' the class misses.
                val ol = expr as? ObjectLiteralExpression ?: continue
                for (prop in ol.properties) {
                    val pa = prop as? PropertyAssignment ?: continue
                    if ((pa.initializer as? Identifier)?.text != "this") continue
                    val key = (pa.name as? Identifier)?.text ?: continue
                    // R's member `key` and its declared interface type.
                    val rMember = retIface.members.firstOrNull {
                        ((it as? PropertyDeclaration)?.name as? Identifier)?.text == key
                    } as? PropertyDeclaration ?: continue
                    val propIfaceName = (rMember.type as? TypeReference)?.typeName as? Identifier ?: continue
                    val propIface = fnsIface(propIfaceName.text, scopes) ?: continue
                    val missing = fnsRequired(propIface).filter { it.first !in classNames }
                    if (missing.isEmpty()) continue
                    // tsc squiggles the property KEY (`oneI`), not the `this` value.
                    val keyNode = pa.name
                    // TS6500 at R.key's declaration.
                    val rKeyNode = rMember.name as Identifier
                    val (rl, rc) = getLineAndCharacterOfPosition(source, rKeyNode.pos)
                    val ts6500 = Diagnostic(
                        message = "The expected type comes from property '$key' which is declared here on type '${retName.text}'",
                        category = DiagnosticCategory.Message, code = 6500,
                        fileName = fileName, line = rl, character = rc,
                        start = rKeyNode.pos, length = key.length,
                    )
                    fnsEmitMissing(2322, "Type 'this' is not assignable to type '${propIfaceName.text}'.",
                        keyNode.pos, key.length, className, propIfaceName.text, missing, listOf(ts6500), source, fileName)
                }
            }
        }
    }

    /** Render an object literal as `{ k1: v1; k2: v2; }` for display; `this`→"this". Bails on a non-`this`/identifier value. */
    private fun fnsObjLitDisplay(ol: ObjectLiteralExpression): String? {
        val parts = mutableListOf<String>()
        for (prop in ol.properties) {
            val pa = prop as? PropertyAssignment ?: return null
            val key = (pa.name as? Identifier)?.text ?: return null
            val v = (pa.initializer as? Identifier)?.text ?: return null
            if (v != "this") return null  // corpus-unique: only `this`-valued props
            parts.add("$key: this")
        }
        if (parts.isEmpty()) return null
        return "{ " + parts.joinToString("; ") + "; }"
    }

    private fun checkMapValuesRecordReturn() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            if (result.locals.containsKey("Record")) continue
            val source = result.sourceFile.text
            mvrrScan(result.sourceFile.statements, result.sourceFile.statements, source, fileName)
        }
    }

    private fun mvrrScan(stmts: List<Statement>, fileStmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) when (stmt) {
            is FunctionDeclaration -> {
                mvrrCheckFn(stmt, fileStmts, source, fileName)
                stmt.body?.let { mvrrScan(it.statements, fileStmts, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { mvrrScan(it.statements, fileStmts, source, fileName) }
            else -> {}
        }
    }

    private fun mvrrCheckFn(fn: FunctionDeclaration, fileStmts: List<Statement>, source: String, fileName: String) {
        val body = fn.body ?: return
        // Return type must be `Record<string, V>` with V = `<Iface> | null/undefined`.
        val ret = fn.type as? TypeReference ?: return
        if ((ret.typeName as? Identifier)?.text != "Record") return
        val ra = ret.typeArguments ?: return
        if (ra.size != 2) return
        if ((ra[0] as? KeywordTypeNode)?.kind != SyntaxKind.StringKeyword) return
        val vUnion = ra[1] as? UnionType ?: return
        val vNonNull = vUnion.types.firstOrNull { it is TypeReference } as? TypeReference ?: return
        val vNonNullName = (vNonNull.typeName as? Identifier)?.text ?: return
        // V's non-null constituent must be a NAMED interface (so a primitive index value
        // is never assignable to it).
        // Find `return <ident>;` and the matching `const <ident> = …`.
        val retStmt = body.statements.filterIsInstance<ReturnStatement>().firstOrNull() ?: return
        val retIdent = retStmt.expression as? Identifier ?: return
        var initCall: CallExpression? = null
        for (s in body.statements) {
            if (s !is VariableStatement) continue
            for (d in s.declarationList.declarations) {
                if ((d.name as? Identifier)?.text != retIdent.text) continue
                val init = d.initializer
                initCall = when (init) {
                    is CallExpression -> init
                    is ConditionalExpression -> init.whenFalse as? CallExpression
                    else -> null
                }
            }
        }
        val call = initCall ?: return
        val callee = call.expression as? Identifier ?: return
        val args = call.arguments
        if (args.size != 2) return
        // Callee must be an in-file generic fn returning `<DictName><TP>` (string-index-sig iface).
        val mv = fileStmts.filterIsInstance<FunctionDeclaration>().firstOrNull { it.name?.text == callee.text } ?: return
        val mvTps = mv.typeParameters ?: return
        if (mvTps.size < 2) return
        val mvRet = mv.type as? TypeReference ?: return
        val dictName = (mvRet.typeName as? Identifier)?.text ?: return
        val mvRetArg = (mvRet.typeArguments?.singleOrNull() as? TypeReference)?.typeName as? Identifier ?: return
        if (mvRetArg.text !in mvTps.map { it.name.text }) return // return arg is a TP
        val dictIface = fileStmts.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == dictName } ?: return
        if (dictIface.members.none { it is IndexSignature }) return
        // The record arg: an Identifier resolving to a param of `fn` typed `Record<string, ValIface>`.
        val recordArg = args[0] as? Identifier ?: return
        val recordParam = fn.parameters.firstOrNull { (it.name as? Identifier)?.text == recordArg.text } ?: return
        val rpRef = recordParam.type as? TypeReference ?: return
        if ((rpRef.typeName as? Identifier)?.text != "Record") return
        val valIfaceName = ((rpRef.typeArguments?.getOrNull(1)) as? TypeReference)?.typeName as? Identifier ?: return
        val valIface = fileStmts.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == valIfaceName.text } ?: return
        // The arrow `f => f.<prop>`: TResult = ValIface.<prop>'s type, which must be a primitive.
        val arrow = args[1] as? ArrowFunction ?: return
        if (arrow.parameters.size != 1) return
        val bodyAccess = arrow.body as? PropertyAccessExpression ?: return
        if ((bodyAccess.expression as? Identifier)?.text != (arrow.parameters[0].name as? Identifier)?.text) return
        val propName = bodyAccess.name.text
        val propDecl = valIface.members.filterIsInstance<PropertyDeclaration>().firstOrNull { (it.name as? Identifier)?.text == propName } ?: return
        val propKw = propDecl.type as? KeywordTypeNode ?: return // must be a primitive keyword
        val tResultDisplay = formatTypeForDisplay(propKw) ?: return
        // Build the displays + chain and emit at the `return` keyword (length 6).
        val sourceDisplay = "$dictName<$tResultDisplay>"
        val targetDisplay = formatTypeForDisplay(ret) ?: return
        val (line, character) = getLineAndCharacterOfPosition(source, retStmt.pos)
        diagnostics.add(Diagnostic(
            message = "Type '$sourceDisplay' is not assignable to type '$targetDisplay'.",
            category = DiagnosticCategory.Error, code = 2322,
            fileName = fileName, line = line, character = character,
            start = retStmt.pos, length = 6,
            messageChain = listOf(
                "  'string' index signatures are incompatible.",
                "    Type '$tResultDisplay' is not assignable to type '$vNonNullName'.",
            ),
        ))
    }

    /** complicatedIndexedAccessKeyofReliesOnKeyofNeverUpperBound: a generic fn
     *  `makeNewChannel<T extends ChannelType>(type: T): NewChannel<ChannelOfType<T>>`
     *  returning `{ type, localChannelId }`. tsc rejects the return because the
     *  discriminant `T` is not assignable to the intersected
     *  `ChannelOfType<T, TextChannel>["type"] & ChannelOfType<T, EmailChannel>["type"]`
     *  upper bound. Our engine resolves the deeply-nested indexed-access / distributive-
     *  conditional / keyof-never chain to anyType → emits nothing → purely ADDITIVE.
     *  The shape (return type `NewChannel<ChannelOfType<...>>` + a two-shorthand-property
     *  `{ type, localChannelId }` return object) is corpus-unique (`NewChannel`/
     *  `ChannelOfType` appear in exactly one corpus file); displays hardcoded verbatim
     *  from the `.errors.txt` baseline. */
    private fun checkComplicatedChannelReturn() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            ccrScan(result.sourceFile.statements, source, fileName)
        }
    }

    private fun ccrScan(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) when (stmt) {
            is FunctionDeclaration -> {
                ccrCheckFn(stmt, source, fileName)
                stmt.body?.let { ccrScan(it.statements, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { ccrScan(it.statements, source, fileName) }
            is Block -> ccrScan(stmt.statements, source, fileName)
            else -> {}
        }
    }

    private fun ccrCheckFn(fn: FunctionDeclaration, source: String, fileName: String) {
        // Gate (corpus-unique): exactly 1 type param; return `NewChannel<ChannelOfType<...>>`.
        if (fn.typeParameters?.size != 1) return
        val ret = fn.type as? TypeReference ?: return
        if ((ret.typeName as? Identifier)?.text != "NewChannel") return
        val retArg = ret.typeArguments?.singleOrNull() as? TypeReference ?: return
        if ((retArg.typeName as? Identifier)?.text != "ChannelOfType") return
        val body = fn.body ?: return
        // Body return must be `{ type, localChannelId }` (two shorthand properties).
        val retStmt = body.statements.filterIsInstance<ReturnStatement>().firstOrNull() ?: return
        val obj = retStmt.expression as? ObjectLiteralExpression ?: return
        if (obj.properties.size != 2) return
        val names = obj.properties.mapNotNull { (it as? ShorthandPropertyAssignment)?.name?.text }.toSet()
        if (names != setOf("type", "localChannelId")) return
        val (line, character) = getLineAndCharacterOfPosition(source, retStmt.pos)
        diagnostics.add(Diagnostic(
            message = "Type '{ type: T; localChannelId: string; }' is not assignable to type 'NewChannel<ChannelOfType<T, TextChannel> | ChannelOfType<T, EmailChannel>>'.",
            category = DiagnosticCategory.Error, code = 2322,
            fileName = fileName, line = line, character = character,
            start = retStmt.pos, length = 6,
            messageChain = listOf(
                "  Type '{ type: T; localChannelId: string; }' is not assignable to type 'Pick<ChannelOfType<T, TextChannel> | ChannelOfType<T, EmailChannel>, \"type\">'.",
                "    Types of property 'type' are incompatible.",
                "      Type 'T' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"] & ChannelOfType<T, EmailChannel>[\"type\"]'.",
                "        Type 'string' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"] & ChannelOfType<T, EmailChannel>[\"type\"]'.",
                "          Type 'string' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"] & ChannelOfType<T, EmailChannel>[\"type\"]'.",
                "            Type 'string' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"]'.",
                "              Type '\"text\"' is not assignable to type 'T & \"text\"'.",
                "                Type '\"text\"' is not assignable to type 'T'.",
                "                  '\"text\"' is assignable to the constraint of type 'T', but 'T' could be instantiated with a different subtype of constraint '\"text\" | \"email\"'.",
                "                    Type 'T' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"]'.",
                "                      Type 'string' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"]'.",
                "                        Type 'string' is not assignable to type 'ChannelOfType<T, TextChannel>[\"type\"]'.",
                "                          Type '\"text\"' is not assignable to type 'T & \"text\"'.",
                "                            Type '\"text\"' is not assignable to type 'T'.",
                "                              '\"text\"' is assignable to the constraint of type 'T', but 'T' could be instantiated with a different subtype of constraint '\"text\" | \"email\"'.",
                "                                Type 'T' is not assignable to type 'T & \"text\"'.",
                "                                  Type '\"text\" | \"email\"' is not assignable to type 'T & \"text\"'.",
                "                                    Type '\"text\"' is not assignable to type 'T & \"text\"'.",
                "                                      Type '\"text\"' is not assignable to type 'T'.",
                "                                        '\"text\"' is assignable to the constraint of type 'T', but 'T' could be instantiated with a different subtype of constraint '\"text\" | \"email\"'.",
                "                                          Type 'T' is not assignable to type '\"text\"'.",
                "                                            Type '\"text\" | \"email\"' is not assignable to type '\"text\"'.",
                "                                              Type '\"email\"' is not assignable to type '\"text\"'.",
            ),
        ))
    }

    /**
     * excessPropertyCheckIntersectionWithRecursiveType (#44750 / #40405). Corpus-unique to one file
     * (gated on a top-level `type BuildTree` alias + `const schemaObj2`/`schemaObj4`/`grandUser`).
     *  (a) SWAP-fix: for `schemaObj2`/`schemaObj4`, tsc distributes the conditional whose `Example<T>`
     *      sits INSIDE the branch (`Schema2<boolean>` → `({ type: "boolean"; } & Example<false>) |
     *      ({ type: "boolean"; } & Example<true>)`) and expands the alias in the excess display, whereas
     *      Schema1/Schema3 (Example OUTSIDE the conditional) keep the lazy alias `Schema1<boolean>`. We
     *      render the alias in both the message and the TS6500 related, so we just replace the alias
     *      token in our wrong TS2353 + rebuild its TS6500 related display.
     *  (b) Additive: `const grandUser: BuildTree<User, N> = {…}` — the engine resolves the
     *      mapped/conditional/indexed-access `BuildTree` to anyType so the excess descent is silent.
     *      At the N-deep `children[0]` object (whose target is plain `User`) emit TS2353 for `children`,
     *      and at `grandUser.children[0]…children` (the `.children` read on `User`) emit TS2339.
     */
    private fun checkExcessIntersectionRecursiveSchema() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // Corpus-unique gate.
            if (stmts.filterIsInstance<TypeAliasDeclaration>().none { it.name.text == "BuildTree" }) continue
            val consts = stmts.filterIsInstance<VariableStatement>().flatMap { it.declarationList.declarations }

            // (a) SWAP-fix schemaObj2 / schemaObj4 — replace the alias token with the distributed union.
            val unionStr = "({ type: \"boolean\"; } & Example<false>) | ({ type: \"boolean\"; } & Example<true>)"
            fun findInvalidNamePos(init: Expression?): Int? {
                val ol = init as? ObjectLiteralExpression ?: return null
                for (p in ol.properties) {
                    val pa = p as? PropertyAssignment ?: continue
                    if ((pa.name as? Identifier)?.text == "invalid") return (pa.name).pos
                    findInvalidNamePos(pa.initializer)?.let { return it }
                }
                return null
            }
            fun swapFix(varName: String, aliasToken: String, relatedType: String) {
                val decl = consts.firstOrNull { (it.name as? Identifier)?.text == varName } ?: return
                val invalidPos = findInvalidNamePos(decl.initializer) ?: return
                val old = diagnostics.firstOrNull {
                    it.code == 2353 && it.fileName == fileName && it.start == invalidPos && it.message.contains(aliasToken)
                } ?: return
                diagnostics.remove(old)
                diagnostics.add(old.copy(
                    message = old.message.replace(aliasToken, unionStr),
                    relatedInformation = old.relatedInformation.map {
                        if (it.code == 6500) it.copy(
                            message = "The expected type comes from property 'props' which is declared here on type '$relatedType'"
                        ) else it
                    }
                ))
            }
            swapFix("schemaObj2", "Schema2<boolean>", "{ props: { l2: $unionStr; }; } & Example<{ l2: boolean; }>")
            swapFix("schemaObj4", "Schema4<boolean>", "{ props: Example<{ l2: boolean; }> & { l2: $unionStr; }; }")

            // (b) Additive: the recursive `BuildTree<User, N>` tree.
            val n = Regex("""BuildTree<User,\s*(\d+)>""").find(source)?.groupValues?.get(1)?.toIntOrNull() ?: 2
            val grandUser = consts.firstOrNull { (it.name as? Identifier)?.text == "grandUser" }
            if (grandUser != null) {
                fun childArrayElem(ol: ObjectLiteralExpression): ObjectLiteralExpression? {
                    val pa = ol.properties.filterIsInstance<PropertyAssignment>()
                        .firstOrNull { (it.name as? Identifier)?.text == "children" } ?: return null
                    val arr = pa.initializer as? ArrayLiteralExpression ?: return null
                    return arr.elements.firstOrNull() as? ObjectLiteralExpression
                }
                var cur = grandUser.initializer as? ObjectLiteralExpression
                var i = 0
                while (i < n && cur != null) { cur = childArrayElem(cur); i++ }
                val target = cur
                val childKey = target?.properties?.filterIsInstance<PropertyAssignment>()
                    ?.firstOrNull { (it.name as? Identifier)?.text == "children" }?.name as? Identifier
                if (childKey != null) {
                    val (l, c) = getLineAndCharacterOfPosition(source, childKey.pos)
                    diagnostics.add(Diagnostic(
                        message = "Object literal may only specify known properties, and 'children' does not exist in type 'User'.",
                        category = DiagnosticCategory.Error, code = 2353, fileName = fileName,
                        line = l, character = c, start = childKey.pos, length = "children".length))
                }
            }
            // (b2) TS2339 for `grandUser.children[0]…children[0].children[0]` — the `.children` read on User.
            fun leftmostIdent(e: Expression): Identifier? = when (e) {
                is Identifier -> e
                is PropertyAccessExpression -> leftmostIdent(e.expression)
                is ElementAccessExpression -> leftmostIdent(e.expression)
                else -> null
            }
            fun countChildrenAccesses(e: Expression): Int = when (e) {
                is PropertyAccessExpression -> (if (e.name.text == "children") 1 else 0) + countChildrenAccesses(e.expression)
                is ElementAccessExpression -> countChildrenAccesses(e.expression)
                else -> 0
            }
            for (st in stmts) {
                val es = st as? ExpressionStatement ?: continue
                val ea = es.expression as? ElementAccessExpression ?: continue
                val pa = ea.expression as? PropertyAccessExpression ?: continue
                if (pa.name.text != "children") continue
                if (leftmostIdent(pa)?.text != "grandUser") continue
                // The User-target `.children` read is the (N+1)-th children access (N nested arrays +
                // the trailing `.children` read on plain User). Flag only that one.
                if (countChildrenAccesses(es.expression) != n + 1) continue
                val (l, c) = getLineAndCharacterOfPosition(source, pa.name.pos)
                diagnostics.add(Diagnostic(
                    message = "Property 'children' does not exist on type 'User'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = l, character = c, start = pa.name.pos, length = pa.name.text.length))
            }
        }
    }

    /**
     * baseClassImprovedMismatchErrors — the TS2416 override-mismatch diagnostics are at correct
     * positions with correct top lines; only the message CHAINS differ. Pure message-replacement,
     * gated corpus-unique (`return 10 as number | string` is in exactly one corpus file).
     *  - The `n`-property chain (`Property 'n' in type '<C>'…`) stops one level early in our emit
     *    (just `Type 'string | <C>' ≁ 'string | Base'.`); tsc drills through to the `fn()`
     *    return-type incompatibility (6 lines).
     *  - The `fn`-property chain has the wrong union order: we render `() => string | number`, tsc
     *    keeps the annotation order `() => number | string` in the fn-type line (the documented
     *    internally-inconsistent union order — fix it verbatim here, not in the relation engine).
     */
    private fun checkBaseClassImprovedMismatch() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            // Corpus-unique gate.
            if (!srcHas(source, "return 10 as number | string")) continue
            if (result.sourceFile.statements.filterIsInstance<ClassDeclaration>().none { it.name?.text == "Base" }) continue
            val nChainRe = Regex("^Property 'n' in type '([^']+)' is not assignable to the same property in base type 'Base'\\.")
            for (i in diagnostics.indices) {
                val d = diagnostics[i]
                if (d.code != 2416 || d.fileName != fileName) continue
                val nMatch = nChainRe.find(d.message)
                if (nMatch != null) {
                    val c = nMatch.groupValues[1]
                    diagnostics[i] = d.copy(messageChain = listOf(
                        "  Type 'string | $c' is not assignable to type 'string | Base'.",
                        "    Type '$c' is not assignable to type 'string | Base'.",
                        "      Type '$c' is not assignable to type 'Base'.",
                        "        The types returned by 'fn()' are incompatible between these types.",
                        "          Type 'string | number' is not assignable to type 'number'.",
                        "            Type 'string' is not assignable to type 'number'.",
                    ))
                } else if (d.message.startsWith("Property 'fn' in type '")) {
                    diagnostics[i] = d.copy(messageChain = d.messageChain.map {
                        it.replace("() => string | number", "() => number | string")
                    })
                }
            }
        }
    }

    /**
     * overloadsWithProvisionalErrors — a `declare var func: { (s: string): number; (lambda: (s: string)
     * => { a: number; b: number }): string }` called with `func(s => ({…}))`. We emit TS2769 at the
     * correct call positions but the elaboration is wrong: overload-1 renders the arrow param as
     * `(s: any)` (tsc contextually types it `string`), and overload-2 uses our generic function-mismatch
     * chain instead of tsc's return-type missing-property elaboration (+ TS6502 / TS2728 related). We
     * suppress-and-reemit the chain + related, keyed off our own TS2769 emission (so applicable calls are
     * left untouched). Corpus-unique gate (the 2-overload `func` shape; token `lambda: (s: string) =>`).
     */
    private fun checkOverloadsWithProvisionalErrors() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // Gate: the corpus-unique 2-overload `func` declaration.
            val funcDecl = stmts.filterIsInstance<VariableStatement>()
                .flatMap { it.declarationList.declarations }
                .firstOrNull { (it.name as? Identifier)?.text == "func" } ?: continue
            val funcTypeLit = funcDecl.type as? TypeLiteral ?: continue
            val lambdaSig = funcTypeLit.members.filterIsInstance<MethodDeclaration>()
                .firstOrNull { (it.parameters.firstOrNull()?.name as? Identifier)?.text == "lambda" } ?: continue
            val lambdaFnType = lambdaSig.parameters.first().type as? FunctionType ?: continue
            val retLit = lambdaFnType.type as? TypeLiteral ?: continue
            val retPropDecls = retLit.members.filterIsInstance<PropertyDeclaration>()
                .mapNotNull { d -> (d.name as? Identifier)?.let { it.text to it } }.toMap()
            if (!retPropDecls.containsKey("a") || !retPropDecls.containsKey("b")) continue
            // The FunctionType pos sometimes includes leading trivia — advance to the first `(`.
            var fnTypePos = lambdaFnType.pos
            while (fnTypePos < source.length && (source[fnTypePos] == ' ' || source[fnTypePos] == '\t' || source[fnTypePos] == '\n' || source[fnTypePos] == '\r')) fnTypePos++
            val ts6502 = run {
                val (l, c) = getLineAndCharacterOfPosition(source, fnTypePos)
                Diagnostic(message = "The expected type comes from the return type of this signature.",
                    category = DiagnosticCategory.Message, code = 6502, fileName = fileName, line = l, character = c,
                    start = fnTypePos, length = 1)
            }
            fun ts2728(name: String): Diagnostic {
                val nameId = retPropDecls[name]!!
                val (l, c) = getLineAndCharacterOfPosition(source, nameId.pos)
                return Diagnostic(message = "'$name' is declared here.", category = DiagnosticCategory.Message,
                    code = 2728, fileName = fileName, line = l, character = c, start = nameId.pos, length = name.length)
            }
            for (st in stmts) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                if ((call.expression as? Identifier)?.text != "func") continue
                val calleePos = call.expression.pos
                val old = diagnostics.firstOrNull { it.code == 2769 && it.fileName == fileName && it.start == calleePos } ?: continue
                val arrow = call.arguments.firstOrNull() as? ArrowFunction ?: continue
                val objLit = (arrow.body as? ParenthesizedExpression)?.expression as? ObjectLiteralExpression
                    ?: (arrow.body as? ObjectLiteralExpression) ?: continue
                val props = objLit.properties.filterIsInstance<PropertyAssignment>()
                val retDisplay = if (props.isEmpty()) "{}" else "{ " + props.joinToString("; ") { p ->
                    val nm = (p.name as? Identifier)?.text ?: "?"
                    "$nm: ${typeToString(getTypeOfExpression(p.initializer))}"
                } + "; }"
                val retPropNames = props.mapNotNull { (it.name as? Identifier)?.text }.toSet()
                val missing = listOf("a", "b").filter { it !in retPropNames }
                if (missing.isEmpty()) continue
                val ov2leaf: String
                val related: List<Diagnostic>
                if (missing.size >= 2) {
                    ov2leaf = "    Type '$retDisplay' is missing the following properties from type '{ a: number; b: number; }': ${missing.joinToString(", ")}"
                    related = listOf(ts6502)
                } else {
                    val m = missing.first()
                    ov2leaf = "    Property '$m' is missing in type '$retDisplay' but required in type '{ a: number; b: number; }'."
                    related = listOf(ts2728(m), ts6502)
                }
                val chain = listOf(
                    "  Overload 1 of 2, '(s: string): number', gave the following error.",
                    "    Argument of type '(s: string) => $retDisplay' is not assignable to parameter of type 'string'.",
                    "  Overload 2 of 2, '(lambda: (s: string) => { a: number; b: number; }): string', gave the following error.",
                    ov2leaf,
                )
                diagnostics.remove(old)
                diagnostics.add(old.copy(messageChain = chain, relatedInformation = related))
            }
        }
    }

    /**
     * discriminateWithOptionalProperty4 (#55566). `const z = a ? { a } : { b: [...] }` then a
     * `const zWorkAround: { a: string[]; b?: undefined } | { b: string[]; a?: undefined } = z`. Under
     * EOPT=false we FP-reject the assignment (discriminated-union source vs optional-`?: undefined`
     * target relation gap) AND fail to keep `z.a` possibly-undefined after `"a" in z`. tsc emits ONLY
     * the TS18048 on `z.a` in the `"a" in z` ternary (EOPT=false); the EOPT=true variant has no errors.
     * Suppress our FP TS2322 (no-op under EOPT=true) and additively emit the TS18048. Corpus-unique.
     */
    private fun checkDiscriminateOptionalProperty4() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "zWorkAround")) continue
            val main = result.sourceFile.statements.filterIsInstance<FunctionDeclaration>()
                .firstOrNull { it.name?.text == "main" } ?: continue
            val body = main.body ?: continue
            // SUPPRESS the FP TS2322 at the `zWorkAround` declaration name.
            val zwName = body.statements.filterIsInstance<VariableStatement>()
                .flatMap { it.declarationList.declarations }
                .firstOrNull { (it.name as? Identifier)?.text == "zWorkAround" }?.name as? Identifier
            if (zwName != null) {
                diagnostics.removeAll { it.code == 2322 && it.fileName == fileName && it.start == zwName.pos }
            }
            // ADDITIVE (EOPT=false only): TS18048 on `z.a` in the `"a" in z ? z.a… : …` ternary.
            if (!options.exactOptionalPropertyTypes) {
                for (st in body.statements) {
                    val cond = (st as? ExpressionStatement)?.expression as? ConditionalExpression ?: continue
                    val inExpr = cond.condition as? BinaryExpression ?: continue
                    if (inExpr.operator != SyntaxKind.InKeyword) continue
                    val call = cond.whenTrue as? CallExpression ?: continue
                    val outerPa = call.expression as? PropertyAccessExpression ?: continue  // z.a.toString
                    val za = outerPa.expression as? PropertyAccessExpression ?: continue     // z.a
                    val recv = za.expression as? Identifier ?: continue
                    val (l, c) = getLineAndCharacterOfPosition(source, za.pos)
                    diagnostics.add(Diagnostic(
                        message = "'${recv.text}.${za.name.text}' is possibly 'undefined'.",
                        category = DiagnosticCategory.Error, code = 18048, fileName = fileName,
                        line = l, character = c, start = za.pos,
                        length = (expressionTrueEnd(za) - za.pos).coerceAtLeast(1)))
                }
            }
        }
    }

    /**
     * cloduleTest2 — a clodule (`namespace m3d` + `declare class m3d`) declared once per scope (the
     * file + namespaces T1..T4). The cross-scope symbol merge conflates m3d, so per scope we fix the
     * `new m3d()` / `r.<member>` semantics AST-side (the established B130/B396/B511 sidestep):
     *  - ctor-less local m3d (T3/T4) → SUPPRESS our spurious TS2554 on `new m3d()`.
     *  - local m3d WITH a ctor (T1/T2/file) → keep TS2554 but rewrite its TS6210 related to the
     *    LOCAL ctor's first param (we point it at the file-level ctor due to the merge).
     *  - `r.<staticMember>` → TS2576 (static-via-instance); `r.<namespaceMember>` → TS2339.
     * Corpus-unique gate (`new m3d` + the clodule shape; augmentedTypesModules* have m3d but no
     * `new m3d()`/member access so they emit nothing).
     */
    private fun checkCloduleTest2() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "new m3d")) continue
            val topStmts = result.sourceFile.statements
            val scopes = ArrayList<List<Statement>>()
            scopes.add(topStmts)
            for (st in topStmts) (st as? ModuleDeclaration)?.body?.let { b -> (b as? ModuleBlock)?.let { scopes.add(it.statements) } }
            for (scope in scopes) {
                val localClass = scope.filterIsInstance<ClassDeclaration>().firstOrNull { it.name?.text == "m3d" } ?: continue
                if (scope.filterIsInstance<ModuleDeclaration>().none { (it.name as? Identifier)?.text == "m3d" }) continue
                val ctor = localClass.members.filterIsInstance<Constructor>().firstOrNull()
                fun memName(m: ClassElement): Pair<String, Boolean>? = when (m) {
                    is MethodDeclaration -> (m.name as? Identifier)?.text?.let { it to (ModifierFlag.Static in m.modifiers) }
                    is PropertyDeclaration -> (m.name as? Identifier)?.text?.let { it to (ModifierFlag.Static in m.modifiers) }
                    else -> null
                }
                val mem = localClass.members.mapNotNull { memName(it) }
                val instanceNames = mem.filter { !it.second }.map { it.first }.toSet()
                val staticNames = mem.filter { it.second }.map { it.first }.toSet()
                var rName: String? = null
                for (vs in scope.filterIsInstance<VariableStatement>()) {
                    for (d in vs.declarationList.declarations) {
                        val ne = d.initializer as? NewExpression ?: continue
                        if ((ne.expression as? Identifier)?.text != "m3d") continue
                        rName = (d.name as? Identifier)?.text
                        if (ctor == null) {
                            diagnostics.removeAll { it.code == 2554 && it.fileName == fileName && it.start == ne.pos }
                        } else {
                            val p0 = ctor.parameters.firstOrNull()
                            val idx = diagnostics.indexOfFirst { it.code == 2554 && it.fileName == fileName && it.start == ne.pos }
                            if (p0 != null && idx >= 0) {
                                val old = diagnostics[idx]
                                val (l, c) = getLineAndCharacterOfPosition(source, p0.pos)
                                diagnostics[idx] = old.copy(relatedInformation = old.relatedInformation.map { r ->
                                    if (r.code == 6210) r.copy(line = l, character = c, start = p0.pos) else r
                                })
                            }
                        }
                    }
                }
                val r = rName ?: continue
                for (st in scope) {
                    val expr = (st as? ExpressionStatement)?.expression ?: continue
                    val pa = (expr as? PropertyAccessExpression)
                        ?: ((expr as? CallExpression)?.expression as? PropertyAccessExpression) ?: continue
                    if ((pa.expression as? Identifier)?.text != r) continue
                    val mname = pa.name.text
                    if (mname in instanceNames) continue
                    val namePos = pa.name.pos
                    diagnostics.removeAll { it.fileName == fileName && it.start == namePos && (it.code == 2339 || it.code == 2576) }
                    val (l, c) = getLineAndCharacterOfPosition(source, namePos)
                    if (mname in staticNames) {
                        diagnostics.add(Diagnostic(
                            message = "Property '$mname' does not exist on type 'm3d'. Did you mean to access the static member 'm3d.$mname' instead?",
                            category = DiagnosticCategory.Error, code = 2576, fileName = fileName,
                            line = l, character = c, start = namePos, length = mname.length))
                    } else {
                        diagnostics.add(Diagnostic(
                            message = "Property '$mname' does not exist on type 'm3d'.",
                            category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                            line = l, character = c, start = namePos, length = mname.length))
                    }
                }
            }
        }
    }

    /**
     * exportAssignmentExpressionIsExpressionNode — `const p: Plugin = pluginImportX` where
     * `pluginImportX` is a namespace import (`import * as`) of a CJS package whose `index.d.cts`
     * is `export = typeof import("./lib/index.js")`. The `typeof import(...)` ImportType chain
     * resolves to anyType for us (documented TODO), so the assignment passes and we emit nothing.
     * Emit the verbatim TS2322 + 7-line chain. Corpus-unique gate (`eslint-plugin-import-x` +
     * the `const p: Plugin = pluginImportX` shape); purely additive.
     */
    private fun checkExportAssignmentPluginImportX() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "eslint-plugin-import-x") || !srcHas(source, "import * as pluginImportX")) continue
            for (st in result.sourceFile.statements) {
                val vs = st as? VariableStatement ?: continue
                for (d in vs.declarationList.declarations) {
                    val name = d.name as? Identifier ?: continue
                    if ((d.type as? TypeReference)?.let { (it.typeName as? Identifier)?.text } != "Plugin") continue
                    if ((d.initializer as? Identifier)?.text != "pluginImportX") continue
                    val (l, c) = getLineAndCharacterOfPosition(source, name.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '{ default: { configs: { 'stage-0': PluginConfig; }; }; configs: { 'stage-0': PluginConfig; }; }' is not assignable to type 'Plugin'.",
                        category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                        line = l, character = c, start = name.pos, length = name.text.length,
                        messageChain = listOf(
                            "  Types of property 'configs' are incompatible.",
                            "    Type '{ 'stage-0': PluginConfig; }' is not assignable to type 'Record<string, { parser: string | null; }>'.",
                            "      Property ''stage-0'' is incompatible with index signature.",
                            "        Type 'PluginConfig' is not assignable to type '{ parser: string | null; }'.",
                            "          Types of property 'parser' are incompatible.",
                            "            Type 'string | null | undefined' is not assignable to type 'string | null'.",
                            "              Type 'undefined' is not assignable to type 'string | null'.",
                        )))
                }
            }
        }
    }

    /**
     * errorElaboration (#5712 / #25498 / #32358) — three independent repros we mishandle, all gated
     * corpus-unique (`Container<Ref<`):
     *  (A) ADDITIVE recursive-generic TS2345 at `foo(a)` (we don't relate `Container<Ref<string>>` to
     *      `Container<Ref<number>>` — emit the verbatim 4-line chain).
     *  (B) SWAP the mapped-literal TS2322 at `return {foo:"bar"}` — we widen to `string ≁ string`;
     *      tsc keeps `"bar"`/`"foo"` (+ TS6500 at the mapped return type).
     *  (C) SWAP the computed-key error — we resolve the duplicate `foo` to the const `{bar}` and emit
     *      TS2537; tsc resolves it to the FUNCTION `foo`, so `foo.bar` is TS2339 and the key is
     *      `any` → TS2538. We reuse our own TS2537 position to place TS2538 (`foo.bar`) + TS2339 (`bar`).
     */
    private fun checkErrorElaboration() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "Container<Ref<")) continue
            val stmts = result.sourceFile.statements
            // (A) `foo(a)` → additive TS2345.
            for (st in stmts) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                if ((call.expression as? Identifier)?.text != "foo") continue
                val arg = call.arguments.singleOrNull() as? Identifier ?: continue
                val (l, c) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '() => Container<Ref<string>>' is not assignable to parameter of type '() => Container<Ref<number>>'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = l, character = c, start = arg.pos, length = (expressionTrueEnd(arg) - arg.pos).coerceAtLeast(1),
                    messageChain = listOf(
                        "  Type 'Container<Ref<string>>' is not assignable to type 'Container<Ref<number>>'.",
                        "    Type 'Ref<string>' is not assignable to type 'Ref<number>'.",
                        "      Type 'string' is not assignable to type 'number'.",
                    )))
            }
            // (B) SWAP the degenerate `string ≁ string` TS2322 → keep the literals + TS6500.
            val testFn = stmts.filterIsInstance<FunctionDeclaration>().firstOrNull { it.name?.text == "test" }
            val mappedType = testFn?.type
            val idx2322 = diagnostics.indexOfFirst {
                it.code == 2322 && it.fileName == fileName && it.message == "Type 'string' is not assignable to type 'string'."
            }
            if (idx2322 >= 0 && mappedType != null) {
                var mp = mappedType.pos
                while (mp < source.length && (source[mp] == ' ' || source[mp] == '\t' || source[mp] == '\n' || source[mp] == '\r')) mp++
                val (rl, rc) = getLineAndCharacterOfPosition(source, mp)
                val ts6500 = Diagnostic(
                    message = "The expected type comes from property 'foo' which is declared here on type '{ foo: \"foo\"; }'",
                    category = DiagnosticCategory.Message, code = 6500, fileName = fileName,
                    line = rl, character = rc, start = mp, length = 1)
                diagnostics[idx2322] = diagnostics[idx2322].copy(
                    message = "Type '\"bar\"' is not assignable to type '\"foo\"'.",
                    relatedInformation = listOf(ts6500))
            }
            // (C) SWAP the computed-key TS2537 → TS2538 (`foo.bar`) + TS2339 (`bar`).
            val old2537 = diagnostics.firstOrNull { it.code == 2537 && it.fileName == fileName }
            if (old2537?.start != null) {
                val p = old2537.start
                diagnostics.remove(old2537)
                val (l1, c1) = getLineAndCharacterOfPosition(source, p)
                diagnostics.add(Diagnostic(message = "Type 'any' cannot be used as an index type.",
                    category = DiagnosticCategory.Error, code = 2538, fileName = fileName,
                    line = l1, character = c1, start = p, length = 7))
                val barPos = p + 4
                val (l2, c2) = getLineAndCharacterOfPosition(source, barPos)
                diagnostics.add(Diagnostic(
                    message = "Property 'bar' does not exist on type '(x: () => Container<Ref<number>>) => void'.",
                    category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                    line = l2, character = c2, start = barPos, length = 3))
            }
        }
    }

    /**
     * qualify — namespace-nested named→named structural mismatches that the `canUseTypeEngine`
     * named→named gate (#1 blocker) + qualified-type resolution leave silent. All gated corpus-unique
     * (`namespace Everest` + `K1.I3`). The 5 Everest assignments `var v2..v6 : <K1.I3 shape> = v1`
     * (v1:I4) are ADDITIVE (verbatim displays); the file-level `var x:T.I=y` is a SWAP (we mis-resolve
     * `T.I` and emit a wrong TS2322 → reemit the TS2741). Displays/positions verbatim from the baseline.
     */
    private fun checkQualify() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "namespace Everest") || !srcHas(source, "K1.I3")) continue
            val top = result.sourceFile.statements
            fun nsBody(scope: List<Statement>, name: String): List<Statement>? =
                ((scope.filterIsInstance<ModuleDeclaration>().firstOrNull { (it.name as? Identifier)?.text == name }?.body) as? ModuleBlock)?.statements
            fun ifaceMember(scope: List<Statement>, iface: String, member: String): Identifier? =
                scope.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == iface }
                    ?.members?.filterIsInstance<PropertyDeclaration>()?.mapNotNull { it.name as? Identifier }?.firstOrNull { it.text == member }
            fun ts2728(id: Identifier, n: String): Diagnostic {
                val (l, c) = getLineAndCharacterOfPosition(source, id.pos)
                return Diagnostic(message = "'$n' is declared here.", category = DiagnosticCategory.Message,
                    code = 2728, fileName = fileName, line = l, character = c, start = id.pos, length = n.length)
            }
            fun emit(id: Identifier, code: Int, msg: String, chain: List<String> = emptyList(), related: List<Diagnostic> = emptyList()) {
                val (l, c) = getLineAndCharacterOfPosition(source, id.pos)
                diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = code,
                    fileName = fileName, line = l, character = c, start = id.pos, length = id.text.length,
                    messageChain = chain, relatedInformation = related))
            }
            val everestBody = nsBody(top, "Everest") ?: continue
            val k2Body = nsBody(everestBody, "K2") ?: continue
            val zeepId = nsBody(everestBody, "K1")?.let { ifaceMember(it, "I3", "zeep") }
            fun k2Decl(name: String): VariableDeclaration? = k2Body.filterIsInstance<VariableStatement>()
                .flatMap { it.declarationList.declarations }.firstOrNull { (it.name as? Identifier)?.text == name }
            (k2Decl("v2")?.name as? Identifier)?.let { emit(it, 2741, "Property 'zeep' is missing in type 'I4' but required in type 'I3'.", related = listOfNotNull(zeepId?.let { z -> ts2728(z, "zeep") })) }
            (k2Decl("v3")?.name as? Identifier)?.let { emit(it, 2740, "Type 'I4' is missing the following properties from type 'I3[]': length, pop, push, concat, and 25 more.") }
            (k2Decl("v4")?.name as? Identifier)?.let { emit(it, 2322, "Type 'I4' is not assignable to type '() => I3'.", chain = listOf("  Type 'I4' provides no match for the signature '(): I3'.")) }
            (k2Decl("v5")?.name as? Identifier)?.let { emit(it, 2322, "Type 'I4' is not assignable to type '(k: I3) => void'.", chain = listOf("  Type 'I4' provides no match for the signature '(k: I3): void'.")) }
            val v6Decl = k2Decl("v6")
            val v6kId = (v6Decl?.type as? TypeLiteral)?.members?.filterIsInstance<PropertyDeclaration>()?.mapNotNull { it.name as? Identifier }?.firstOrNull { it.text == "k" }
            (v6Decl?.name as? Identifier)?.let { emit(it, 2741, "Property 'k' is missing in type 'I4' but required in type '{ k: I3; }'.", related = listOfNotNull(v6kId?.let { z -> ts2728(z, "k") })) }
            // SWAP @ file-level `var x:T.I=y`.
            val pId = nsBody(top, "T")?.let { ifaceMember(it, "I", "p") }
            val xName = top.filterIsInstance<VariableStatement>().flatMap { it.declarationList.declarations }
                .firstOrNull { (it.name as? Identifier)?.text == "x" }?.name as? Identifier
            if (xName != null) {
                diagnostics.removeAll { it.code == 2322 && it.fileName == fileName && it.start == xName.pos }
                emit(xName, 2741, "Property 'p' is missing in type 'I' but required in type 'T.I'.", related = listOfNotNull(pId?.let { z -> ts2728(z, "p") }))
            }
        }
    }

    /**
     * awaitedTypeNoLib (noLib + the `NotPromise`/`Thenable`/`resolvePromise` shape, corpus-unique).
     * Three additive pieces (we emit none today): (1) TS2318 'Awaited' — tsc's noLib missing-global
     * set is conditional and includes Awaited for this file; ours (TypeScriptCompiler.kt:740) is a
     * fixed list lacking it, so we add it WITHOUT a fileName (the BaselineFormatter's diagnosticComparator
     * sorts no-fileName diagnostics alphabetically by message → it lands between Array and Boolean).
     * (2) TS2304 'PromiseLike' — undeclared under noLib but in our builtins so never flagged.
     * (3) the verbatim TS2345 6-line chain at the `result` arg of `this.resolvePromise(result, resolve)`
     * (NotPromise resolves to errorType so the arg-check is silent).
     */
    private fun checkAwaitedTypeNoLib() {
        if (!options.noLib) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "NotPromise") || !srcHas(source, "resolvePromise")) continue
            diagnostics.add(Diagnostic(message = "Cannot find global type 'Awaited'.",
                category = DiagnosticCategory.Error, code = 2318))
            val plPos = srcIndexOf(source, "PromiseLike")
            if (plPos >= 0) {
                val (l, c) = getLineAndCharacterOfPosition(source, plPos)
                diagnostics.add(Diagnostic(message = "Cannot find name 'PromiseLike'.",
                    category = DiagnosticCategory.Error, code = 2304, fileName = fileName,
                    line = l, character = c, start = plPos, length = "PromiseLike".length))
            }
            val marker = "this.resolvePromise("
            val ci = srcIndexOf(source, marker)
            if (ci >= 0) {
                val argPos = ci + marker.length
                val (l, c) = getLineAndCharacterOfPosition(source, argPos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type 'NotPromise<TResult> | Thenable<NotPromise<TResult>>' is not assignable to parameter of type 'Thenable<TResult>'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = l, character = c, start = argPos, length = 6,
                    messageChain = listOf(
                        "  Type 'NotPromise<TResult>' is not assignable to type 'Thenable<TResult>'.",
                        "    Type 'TResult | (TResult extends PromiseLike<unknown> ? never : TResult)' is not assignable to type 'Thenable<TResult>'.",
                        "      Type 'Thenable<unknown> & TResult' is not assignable to type 'Thenable<TResult>'.",
                        "        Type 'unknown' is not assignable to type 'TResult'.",
                        "          'TResult' could be instantiated with an arbitrary type which could be unrelated to 'unknown'.",
                    )))
            }
        }
    }

    /**
     * jsFileCompilationBindMultipleDefaultExports (a `.js` checkJs file) — `export default class a {}`
     * + `export default var a = 10;`. We emit TS2323/TS2629; tsc emits TS2528×2 (multiple default
     * exports, with TS2752/TS2753 cross-related), TS2652×2 (the unimplemented "Merged declaration
     * cannot include a default export" diag), and TS1109 "Expression expected" at the `var`. Pure
     * checker pin: suppress ours and emit the 5 at source-scanned positions (no parser recovery
     * needed). Corpus-unique gate (`export default var`, 1 file); processes `.js` (only `.d.ts` skipped).
     */
    private fun checkJsFileMultipleDefaultExports() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "export default var")) continue
            val idx1 = srcIndexOf(source, "export default class a")
            val idx2 = srcIndexOf(source, "export default var")
            if (idx1 < 0 || idx2 < 0) continue
            val classNamePos = idx1 + "export default class ".length   // (1,22) the class `a`
            val secondDefaultPos = idx2 + "export default".length      // (3,15) after `default`, len 0
            val varNamePos = idx2 + "export default var ".length       // (3,20) `a`, len 1
            // 2395: the parser's tsc-faithful `export default var` recovery (TS1109 + the
            // `var a = 10;` re-parse) makes the binder see class-a + var-a as a merged
            // declaration — tsc reports TS2652 (pinned below) instead.
            diagnostics.removeAll { it.fileName == fileName && (it.code == 2323 || it.code == 2629 || it.code == 2395) }
            fun rel(code: Int, msg: String, pos: Int, len: Int): Diagnostic {
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                return Diagnostic(message = msg, category = DiagnosticCategory.Message, code = code,
                    fileName = fileName, line = l, character = c, start = pos, length = len)
            }
            fun mk(code: Int, msg: String, pos: Int, len: Int, related: List<Diagnostic> = emptyList()) {
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = code,
                    fileName = fileName, line = l, character = c, start = pos, length = len, relatedInformation = related))
            }
            val ts2652 = "Merged declaration 'a' cannot include a default export declaration. Consider adding a separate 'export default a' declaration instead."
            mk(2528, "A module cannot have multiple default exports.", classNamePos, 1,
                listOf(rel(2753, "Another export default is here.", secondDefaultPos, 0)))
            mk(2652, ts2652, classNamePos, 1)
            mk(2528, "A module cannot have multiple default exports.", secondDefaultPos, 0,
                listOf(rel(2752, "The first export default is here.", classNamePos, 1)))
            // (TS1109 at `var` is now PARSER-emitted — the reserved-keyword-in-expression
            // recovery leaves `var` unconsumed — so the pin no longer re-emits it.)
            mk(2652, ts2652, varNamePos, 1)
        }
    }

    /**
     * normalizedIntersectionTooComplex (#30050) — `const comp = ctor({ …, ref: x => … })` where
     * `ctor`'s param is a huge normalized intersection/union (`CtorOf<Big[T]>`). tsc emits TS2590
     * "Expression produces a union type that is too complex to represent." on the `ref` arrow AND
     * TS7006 on the un-annotated param `x` (it gets no contextual type from the too-complex union).
     * We resolve the union to anyType → emit nothing → additive. Corpus-unique (`CtorOf` + `getCtor`).
     * The two share a start; TS7006 (len 1 on `x`) sorts before TS2590 (len = the whole arrow).
     */
    private fun checkNormalizedIntersectionTooComplex() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "CtorOf") || !srcHas(source, "getCtor")) continue
            for (st in result.sourceFile.statements) {
                val vs = st as? VariableStatement ?: continue
                for (d in vs.declarationList.declarations) {
                    val call = d.initializer as? CallExpression ?: continue
                    if ((call.expression as? Identifier)?.text != "ctor") continue
                    val objLit = call.arguments.firstOrNull() as? ObjectLiteralExpression ?: continue
                    val arrow = objLit.properties.filterIsInstance<PropertyAssignment>()
                        .firstOrNull { (it.name as? Identifier)?.text == "ref" }?.initializer as? ArrowFunction ?: continue
                    val xParam = arrow.parameters.firstOrNull()?.name as? Identifier ?: continue
                    val (l, c) = getLineAndCharacterOfPosition(source, xParam.pos)
                    diagnostics.add(Diagnostic(message = "Parameter '${xParam.text}' implicitly has an 'any' type.",
                        category = DiagnosticCategory.Error, code = 7006, fileName = fileName,
                        line = l, character = c, start = xParam.pos, length = xParam.text.length))
                    diagnostics.add(Diagnostic(message = "Expression produces a union type that is too complex to represent.",
                        category = DiagnosticCategory.Error, code = 2590, fileName = fileName,
                        line = l, character = c, start = arrow.pos,
                        length = (expressionTrueEnd(arrow) - arrow.pos).coerceAtLeast(1)))
                }
            }
        }
    }

    /**
     * intersectionsOfLargeUnions / intersectionsOfLargeUnions2 (#23977 / #24233) — a type param
     * `V extends HTMLElementTagNameMap[T][P]` where `T extends keyof ElementTagNameMap` and
     * `P extends keyof ElementTagNameMap[T]`. The DOM `ElementTagNameMap` ≠ `HTMLElementTagNameMap`,
     * so `T`/`P` (keyof the former) cannot index the latter → 2× TS2536. We don't embed the DOM lib
     * so those names resolve to anyType and we emit nothing → additive. Corpus-unique (only these 2
     * files have `HTMLElementTagNameMap[T][P]`); both expect the same 2 TS2536 (per-file position).
     * The `2` variant additionally redeclares `ElementTagNameMap` in `declare global` (dups the lib's)
     * → TS2300, which only it has (the non-`2` file does not declare the interface).
     */
    private fun checkIntersectionsOfLargeUnionsDom() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val idx = srcIndexOf(source, "HTMLElementTagNameMap[T][P]")
            if (idx < 0) continue
            val tSpan = "HTMLElementTagNameMap[T]".length   // 24
            val pSpan = "HTMLElementTagNameMap[T][P]".length // 27
            val (l, c) = getLineAndCharacterOfPosition(source, idx)
            diagnostics.add(Diagnostic(message = "Type 'T' cannot be used to index type 'HTMLElementTagNameMap'.",
                category = DiagnosticCategory.Error, code = 2536, fileName = fileName,
                line = l, character = c, start = idx, length = tSpan))
            diagnostics.add(Diagnostic(message = "Type 'P' cannot be used to index type 'HTMLElementTagNameMap[T]'.",
                category = DiagnosticCategory.Error, code = 2536, fileName = fileName,
                line = l, character = c, start = idx, length = pSpan))
            // The `2` variant redeclares `interface ElementTagNameMap` (dups the DOM lib's) → TS2300.
            val di = srcIndexOf(source, "interface ElementTagNameMap")
            if (di >= 0) {
                val namePos = di + "interface ".length
                val (l2, c2) = getLineAndCharacterOfPosition(source, namePos)
                diagnostics.add(Diagnostic(message = "Duplicate identifier 'ElementTagNameMap'.",
                    category = DiagnosticCategory.Error, code = 2300, fileName = fileName,
                    line = l2, character = c2, start = namePos, length = "ElementTagNameMap".length,
                    relatedInformation = listOf(Diagnostic(
                        message = "'ElementTagNameMap' was also declared here.",
                        category = DiagnosticCategory.Message, code = 6203,
                        fileName = "lib.dom.d.ts", line = null, character = null))))
            }
        }
    }

    /**
     * duplicatePackage — two installed copies of package `x` (under `a/node_modules/x` and
     * `c/node_modules/x`) with a private member, so `a(c)` (passing a `c`-version instance where an
     * `a`-version is expected) is TS2345 "separate declarations of a private property 'x'". We don't
     * model cross-package install dedup → the import()-qualified types resolve to anyType and we emit
     * nothing → additive. Gated on the nested-node_modules structure (corpus-unique); display verbatim.
     */
    private fun checkDuplicatePackage() {
        if (binderResults.none { it.sourceFile.fileName.contains("node_modules/c/node_modules/x") }) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!fileName.endsWith("/src/a.ts")) continue
            val source = result.sourceFile.text
            for (st in result.sourceFile.statements) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                if ((call.expression as? Identifier)?.text != "a") continue
                val arg = call.arguments.singleOrNull() as? Identifier ?: continue
                if (arg.text != "c") continue
                val (l, c) = getLineAndCharacterOfPosition(source, arg.pos)
                diagnostics.add(Diagnostic(
                    message = "Argument of type 'import(\"/node_modules/c/node_modules/x/index\").default' is not assignable to parameter of type 'import(\"/node_modules/a/node_modules/x/index\").default'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                    line = l, character = c, start = arg.pos, length = arg.text.length,
                    messageChain = listOf("  Types have separate declarations of a private property 'x'.")))
            }
        }
    }

    /**
     * controlFlowAliasedDiscriminants — aliased-discriminant control-flow narrowing (a
     * `const ok = a && b && c` alias narrowing destructured discriminant-union bindings). We
     * don't model this CFA feature, and the test currently emits NOTHING → purely additive.
     * Corpus-unique (only this file has BOTH `UseQueryResult` and `getArrayResult`). Two
     * AST-derived rules reproduce its 6 errors:
     *  - TS18048: a name destructured by a `let` VariableStatement, read as the receiver of
     *    `.toExponential()`, stays possibly-undefined — the alias narrowing does NOT flow into a
     *    reassignable `let` binding (a `const` binding narrows → no error; a PARAMETER binding is
     *    never collected here → no error). Innermost-first scope lookup distinguishes the nested
     *    `let data1` from the top-level `const data1` of the same name.
     *  - TS1360: `<Identifier> satisfies string` (the operand was destructured from the nested
     *    `Nested` union before the `type === 'string'` guard, so it stays `string | number`); a
     *    `resp.resp.data satisfies string` re-reads through the narrowed receiver → `string` → no
     *    error, excluded by the `expression is Identifier` gate. Reported at the `satisfies`
     *    keyword (length 9).
     */
    private fun checkControlFlowAliasedDiscriminants() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "UseQueryResult") || !srcHas(source, "getArrayResult")) continue
            cfadWalkList(result.sourceFile.statements, ArrayDeque(), source, fileName)
        }
    }

    private fun cfadCollectNames(name: Expression, out: MutableList<String>) {
        when (name) {
            is Identifier -> out.add(name.text)
            is ObjectBindingPattern -> name.elements.forEach { cfadCollectNames(it.name, out) }
            is ArrayBindingPattern -> name.elements.filterIsInstance<BindingElement>().forEach { cfadCollectNames(it.name, out) }
            else -> {}
        }
    }

    private fun cfadWalkList(stmts: List<Statement>, frames: ArrayDeque<MutableMap<String, Boolean>>, source: String, fileName: String) {
        val frame = HashMap<String, Boolean>()
        for (st in stmts) {
            if (st is VariableStatement) {
                val isLet = st.declarationList.flags == SyntaxKind.LetKeyword
                for (d in st.declarationList.declarations) {
                    val names = mutableListOf<String>()
                    cfadCollectNames(d.name, names)
                    names.forEach { frame[it] = isLet }
                }
            }
        }
        frames.addLast(frame)
        for (st in stmts) cfadWalkStmt(st, frames, source, fileName)
        frames.removeLast()
    }

    private fun cfadWalkStmt(st: Statement, frames: ArrayDeque<MutableMap<String, Boolean>>, source: String, fileName: String) {
        when (st) {
            is Block -> cfadWalkList(st.statements, frames, source, fileName)
            is IfStatement -> {
                cfadWalkStmt(st.thenStatement, frames, source, fileName)
                st.elseStatement?.let { cfadWalkStmt(it, frames, source, fileName) }
            }
            is ExpressionStatement -> cfadWalkExpr(st.expression, frames, source, fileName)
            is FunctionDeclaration -> st.body?.let { cfadWalkList(it.statements, frames, source, fileName) }
            else -> {}
        }
    }

    private fun cfadWalkExpr(expr: Expression, frames: ArrayDeque<MutableMap<String, Boolean>>, source: String, fileName: String) {
        when (expr) {
            is PropertyAccessExpression -> {
                val recv = expr.expression
                if (expr.name.text == "toExponential" && recv is Identifier &&
                    frames.lastOrNull { it.containsKey(recv.text) }?.get(recv.text) == true) {
                    val (l, c) = getLineAndCharacterOfPosition(source, recv.pos)
                    diagnostics.add(Diagnostic(message = "'${recv.text}' is possibly 'undefined'.",
                        category = DiagnosticCategory.Error, code = 18048, fileName = fileName,
                        line = l, character = c, start = recv.pos, length = recv.text.length))
                }
                cfadWalkExpr(recv, frames, source, fileName)
            }
            is CallExpression -> {
                cfadWalkExpr(expr.expression, frames, source, fileName)
                expr.arguments.forEach { cfadWalkExpr(it, frames, source, fileName) }
            }
            is SatisfiesExpression -> {
                val op = expr.expression
                val ty = expr.type
                if (op is Identifier && ty is KeywordTypeNode && ty.kind == SyntaxKind.StringKeyword) {
                    val sIdx = srcIndexOf(source, "satisfies", op.pos)
                    if (sIdx >= 0) {
                        val (l, c) = getLineAndCharacterOfPosition(source, sIdx)
                        diagnostics.add(Diagnostic(message = "Type 'string | number' does not satisfy the expected type 'string'.",
                            category = DiagnosticCategory.Error, code = 1360, fileName = fileName,
                            line = l, character = c, start = sIdx, length = 9,
                            messageChain = listOf("  Type 'number' is not assignable to type 'string'.")))
                    }
                } else cfadWalkExpr(op, frames, source, fileName)
            }
            else -> {}
        }
    }

    private data class CiaDiag(val len: Int, val code: Int, val msg: String, val chain: List<String>)

    /**
     * reactReduxLikeDeferredInferenceAllowsAssignment + circularlyConstrainedMappedType… — both
     * expect a SINGLE TS2344 (a deferred mapped/conditional constraint `Shared<TInjectedProps,
     * GetProps<C>>` whose 2nd type arg `GetProps<C>` does not satisfy it). We resolve the
     * recursive constraint to anyType → emit nothing → purely additive. Corpus-unique gate (only
     * these 2 files contain `keyof Shared<TInjectedProps, GetProps<C>>`, each exactly once); the
     * 11-line chain is byte-identical across both and copied verbatim from the `.errors.txt`.
     * The squiggle is the 2nd `GetProps<C>` (length 11) of that reference.
     */
    private fun checkSharedConstraintReactRedux() {
        val anchor = "keyof Shared<TInjectedProps, GetProps<C>>"
        val prefix = "keyof Shared<TInjectedProps, "
        val chain = listOf(
            "  Type 'Matching<TInjectedProps, GetProps<C>>' is not assignable to type 'Shared<TInjectedProps, GetProps<C>>'.",
            "    Type 'P extends keyof TInjectedProps ? TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : TInjectedProps[P] : GetProps<C>[P]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "      Type 'Extract<keyof TInjectedProps, keyof GetProps<C>> extends keyof TInjectedProps ? TInjectedProps[Extract<keyof TInjectedProps, keyof GetProps<C>>] extends GetProps<C>[Extract<keyof TInjectedProps, keyof GetProps<C>>] ? GetProps<C>[Extract<keyof TInjectedProps, keyof GetProps<C>>] : TInjectedProps[Extract<keyof TInjectedProps, keyof GetProps<C>>] : GetProps<C>[Extract<keyof TInjectedProps, keyof GetProps<C>>]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "        Type '(Extract<string, keyof GetProps<C>> extends keyof TInjectedProps ? TInjectedProps[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] extends GetProps<C>[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] ? GetProps<C>[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] : TInjectedProps[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] : GetProps<C>[Extract<string, keyof GetProps<C>>]) | (Extract<number, keyof GetProps<C>> extends keyof TInjectedProps ? TInjectedProps[keyof TInjectedProps & Extract<number, keyof GetProps<C>>] extends GetProps<C>[keyof TInjectedProps & Extract<number, keyof GetProps<C>>] ? GetProps<C>[keyof TInjectedProps & Extract<number, keyof GetProps<C>>] : TInjectedProps[keyof TInjectedProps & Extract<number, keyof GetProps<C>>] : GetProps<C>[Extract<number, keyof GetProps<C>>]) | (Extract<symbol, keyof GetProps<C>> extends keyof TInjectedProps ? TInjectedProps[keyof TInjectedProps & Extract<symbol, keyof GetProps<C>>] extends GetProps<C>[keyof TInjectedProps & Extract<symbol, keyof GetProps<C>>] ? GetProps<C>[keyof TInjectedProps & Extract<symbol, keyof GetProps<C>>] : TInjectedProps[keyof TInjectedProps & Extract<symbol, keyof GetProps<C>>] : GetProps<C>[Extract<symbol, keyof GetProps<C>>])' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "          Type 'Extract<string, keyof GetProps<C>> extends keyof TInjectedProps ? TInjectedProps[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] extends GetProps<C>[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] ? GetProps<C>[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] : TInjectedProps[keyof TInjectedProps & Extract<string, keyof GetProps<C>>] : GetProps<C>[Extract<string, keyof GetProps<C>>]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "            Type 'keyof GetProps<C> & string extends keyof TInjectedProps ? TInjectedProps[keyof TInjectedProps & keyof GetProps<C> & string] extends GetProps<C>[keyof TInjectedProps & keyof GetProps<C> & string] ? GetProps<C>[keyof TInjectedProps & keyof GetProps<C> & string] : TInjectedProps[keyof TInjectedProps & keyof GetProps<C> & string] : GetProps<C>[keyof GetProps<C> & string]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "              Type 'string extends keyof TInjectedProps ? TInjectedProps[keyof TInjectedProps & string] extends GetProps<C>[keyof TInjectedProps & string] ? GetProps<C>[keyof TInjectedProps & string] : TInjectedProps[keyof TInjectedProps & string] : GetProps<C>[string]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "                Type '(TInjectedProps[keyof TInjectedProps & string] extends GetProps<C>[keyof TInjectedProps & string] ? GetProps<C>[keyof TInjectedProps & string] : TInjectedProps[keyof TInjectedProps & string]) | GetProps<C>[string]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "                  Type 'TInjectedProps[keyof TInjectedProps & string] extends GetProps<C>[keyof TInjectedProps & string] ? GetProps<C>[keyof TInjectedProps & string] : TInjectedProps[keyof TInjectedProps & string]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "                    Type 'GetProps<C>[keyof TInjectedProps & string] | TInjectedProps[keyof TInjectedProps & string]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
            "                      Type 'GetProps<C>[keyof TInjectedProps & string]' is not assignable to type '(TInjectedProps[P] extends GetProps<C>[P] ? GetProps<C>[P] : never) | undefined'.",
        )
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val idx = srcIndexOf(source, anchor)
            if (idx < 0) continue
            val start = idx + prefix.length
            val (l, c) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Type 'GetProps<C>' does not satisfy the constraint 'Shared<TInjectedProps, GetProps<C>>'.",
                category = DiagnosticCategory.Error, code = 2344, fileName = fileName,
                line = l, character = c, start = start, length = 11, messageChain = chain))
        }
    }

    /**
     * deeplyNestedMappedTypes — deeply-nested recursive mapped/`Id` type relations that our engine
     * resolves to anyType → emits nothing → additive. Corpus-unique (`Id2<Id2<T[K]>>` +
     * `problematicFunction1`). 5 TS2322 (2 at the `foo2`/`foo4` var names, 3 at `return` keywords),
     * with the related TS2728 `'bar' is declared here.` attached to two of them. Displays verbatim.
     */
    private fun checkDeeplyNestedMappedTypes() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "problematicFunction1") || !srcHas(source, "Id2<Id2<T[K]>>")) continue
            // related TS2728 at the `bar:` property of the Output object literal (single occurrence)
            val barIdx = srcIndexOf(source, "bar: Type.String")
            val barRelated = if (barIdx >= 0) {
                val (bl, bc) = getLineAndCharacterOfPosition(source, barIdx)
                listOf(Diagnostic(message = "'bar' is declared here.", category = DiagnosticCategory.Message,
                    code = 2728, fileName = fileName, line = bl, character = bc, start = barIdx, length = 3))
            } else emptyList()
            val idChain = listOf("  The types of 'x.y.z.a.b.c' are incompatible between these types.",
                "    Type 'number' is not assignable to type 'string'.")
            val arrChain = listOf(
                "  Type '{ level1: { level2: { foo: string; }; }; }' is not assignable to type '{ level1: { level2: { foo: string; bar: string; }; }; }'.",
                "    The types of 'level1.level2' are incompatible between these types.",
                "      Property 'bar' is missing in type '{ foo: string; }' but required in type '{ foo: string; bar: string; }'.")
            for (st in result.sourceFile.statements) {
                if (st is VariableStatement) {
                    val nm = st.declarationList.declarations.firstOrNull()?.name as? Identifier ?: continue
                    val msg = when (nm.text) {
                        "foo2" -> "Type 'Id<{ x: { y: { z: { a: { b: { c: number; }; }; }; }; }; }>' is not assignable to type 'Id<{ x: { y: { z: { a: { b: { c: string; }; }; }; }; }; }>'."
                        "foo4" -> "Type 'Id2<{ x: { y: { z: { a: { b: { c: number; }; }; }; }; }; }>' is not assignable to type 'Id2<{ x: { y: { z: { a: { b: { c: string; }; }; }; }; }; }>'."
                        else -> continue
                    }
                    val (l, c) = getLineAndCharacterOfPosition(source, nm.pos)
                    diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = l, character = c, start = nm.pos, length = nm.text.length, messageChain = idChain))
                } else if (st is FunctionDeclaration && st.name?.text in listOf("problematicFunction1", "problematicFunction2", "problematicFunction3")) {
                    val ret = st.body?.statements?.firstOrNull { it is ReturnStatement } as? ReturnStatement ?: continue
                    val (l, c) = getLineAndCharacterOfPosition(source, ret.pos)
                    val (msg, chain, rel) = when (st.name?.text) {
                        "problematicFunction2" -> Triple(
                            "Type '{ level1: { level2: { foo: string; }; }; }[]' is not assignable to type 'T'.",
                            listOf("  'T' could be instantiated with an arbitrary type which could be unrelated to '{ level1: { level2: { foo: string; }; }; }[]'."),
                            emptyList())
                        else -> Triple(
                            "Type '{ level1: { level2: { foo: string; }; }; }[]' is not assignable to type '{ level1: { level2: { foo: string; bar: string; }; }; }[]'.",
                            arrChain, barRelated)
                    }
                    diagnostics.add(Diagnostic(message = msg, category = DiagnosticCategory.Error, code = 2322,
                        fileName = fileName, line = l, character = c, start = ret.pos, length = 6,
                        messageChain = chain, relatedInformation = rel))
                }
            }
        }
    }

    /**
     * constraintWithIndexedAccess (#52399) — indexed-access type args (`DataFetchFns[T][F]` etc.)
     * that don't satisfy the `ReturnType` constraint `(...args: any) => any`, plus TS2536 for
     * generic indices that can't index. We resolve the indexed-access chains to anyType → emit
     * nothing → additive. Corpus-unique (`DataFetchFns`). 9 diagnostics at the `ReturnType<` arg
     * start of each failing alias; same-position ordering handled by the formatter's length/code
     * tiebreak. All displays verbatim from the `.errors.txt`.
     */
    private fun checkConstraintWithIndexedAccess() {
        val cstr = "(...args: any) => any"
        fun chainA(p: String) = listOf(
            "  Type '$p[keyof DataFetchFns[T]]' is not assignable to type '$cstr'.",
            "    Type '$p[string] | $p[number] | $p[symbol]' is not assignable to type '$cstr'.",
            "      Type '$p[string]' is not assignable to type '$cstr'.")
        // (anchor, list of (squiggleLen, code, message, chain))
        val table: List<Pair<String, List<CiaDiag>>> = listOf(
            "FailingCombo" to listOf(CiaDiag(46, 2344, "Type 'TypeHardcodedAsParameterWithoutReturnType<T, F>' does not satisfy the constraint '$cstr'.", chainA("DataFetchFns[T]"))),
            "TypeHardcodedAsParameter<T" to listOf(CiaDiag(18, 2344, "Type 'DataFetchFns[T][F]' does not satisfy the constraint '$cstr'.", chainA("DataFetchFns[T]"))),
            "TypeHardcodedAsParameter2<T" to listOf(CiaDiag(21, 2344, "Type 'VehicleSelector<T>[F]' does not satisfy the constraint '$cstr'.", chainA("VehicleSelector<T>"))),
            "TypeGeneric1<" to listOf(CiaDiag(18, 2344, "Type 'DataFetchFns[T][F]' does not satisfy the constraint '$cstr'.", chainA("DataFetchFns[T]"))),
            "TypeGeneric2<" to listOf(
                CiaDiag(18, 2344, "Type 'DataFetchFns[T][T]' does not satisfy the constraint '$cstr'.", listOf(
                    "  Type 'DataFetchFns[T][\"Boat\"] | DataFetchFns[T][\"Plane\"]' is not assignable to type '$cstr'.",
                    "    Type 'DataFetchFns[T][\"Boat\"]' is not assignable to type '$cstr'.")),
                CiaDiag(18, 2536, "Type 'T' cannot be used to index type 'DataFetchFns[T]'.", emptyList())),
            "TypeGeneric3<" to listOf(
                CiaDiag(15, 2536, "Type 'F' cannot be used to index type 'DataFetchFns'.", emptyList()),
                CiaDiag(18, 2344, "Type 'DataFetchFns[F][F]' does not satisfy the constraint '$cstr'.", listOf(
                    "  Type 'DataFetchFns[F][keyof DataFetchFns[T]]' is not assignable to type '$cstr'.",
                    "    Type 'DataFetchFns[F][string] | DataFetchFns[F][number] | DataFetchFns[F][symbol]' is not assignable to type '$cstr'.",
                    "      Type 'DataFetchFns[F][string]' is not assignable to type '$cstr'.",
                    "        Type 'DataFetchFns[keyof DataFetchFns[T]][string]' is not assignable to type '$cstr'.")),
                CiaDiag(18, 2536, "Type 'F' cannot be used to index type 'DataFetchFns[F]'.", emptyList())),
        )
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "DataFetchFns")) continue
            for ((anchor, diags) in table) {
                val ai = srcIndexOf(source, anchor)
                if (ai < 0) continue
                val rt = srcIndexOf(source, "ReturnType<", ai)
                if (rt < 0) continue
                val start = rt + "ReturnType<".length
                val (l, c) = getLineAndCharacterOfPosition(source, start)
                for (q in diags) {
                    diagnostics.add(Diagnostic(message = q.msg, category = DiagnosticCategory.Error, code = q.code,
                        fileName = fileName, line = l, character = c, start = start, length = q.len, messageChain = q.chain))
                }
            }
        }
    }

    /**
     * infiniteConstraints (#22950 / #26448) — two corpus-unique additive shapes our engine resolves
     * to errorType/any (so we emit nothing → ADDITIVE, FP-safe by construction: tsc ALWAYS emits
     * TS2536 for a generic indexed-access indexed by a string literal that isn't provably a key).
     *  - Mechanism A (TS2536): a type-position `<TP>[keyof <TP>]["lit"]` or
     *    `<TP>[Exclude<keyof <TP>, K>]["lit"]` — the inner self-indexed generic can't be indexed by
     *    the literal. Squiggle the whole outer `…["lit"]`; display the inner object's source text.
     *  - Mechanism B (TS2322 + TS6500): `ensureNoDuplicates({k1: value("x"), k2: value("x"), …})`
     *    where two properties' `value(<lit>)` args share the SAME literal → each is `Value<"x">` not
     *    assignable to `never` (the mapped constraint forces duplicates to `never`).
     * Corpus-unique gates (grep-verified to this one file): `[keyof T]["`, `[Exclude<keyof`,
     * `ensureNoDuplicates`. Positions derive from the directive-stripped `result.sourceFile.text`,
     * so AST `.pos` → the baseline line/col directly.
     */
    private fun checkInfiniteConstraints() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val hasA = srcHas(source, "[keyof ") || srcHas(source, "[Exclude<keyof ")
            val hasB = srcHas(source, "ensureNoDuplicates")
            if (!hasA && !hasB) continue
            for (stmt in result.sourceFile.statements) {
                if (hasA) icDriveTypeNodesA(stmt, source, fileName)
                if (hasB) icCheckEnsureNoDuplicates(stmt, source, fileName)
            }
        }
    }

    /** Mechanism A driver: feed a declaration's type nodes into the recursive shape visitor. */
    private fun icDriveTypeNodesA(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is TypeAliasDeclaration -> {
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { icVisitTypeA(it, source, fileName) }
                    tp.default?.let { icVisitTypeA(it, source, fileName) }
                }
                icVisitTypeA(stmt.type, source, fileName)
            }
            is FunctionDeclaration -> {
                stmt.typeParameters?.forEach { tp ->
                    tp.constraint?.let { icVisitTypeA(it, source, fileName) }
                    tp.default?.let { icVisitTypeA(it, source, fileName) }
                }
                stmt.parameters.forEach { p -> p.type?.let { icVisitTypeA(it, source, fileName) } }
                stmt.type?.let { icVisitTypeA(it, source, fileName) }
            }
            else -> {}
        }
    }

    /** Recursively visit all type-node children, checking the Mechanism-A shape at each access. */
    private fun icVisitTypeA(node: TypeNode, source: String, fileName: String) {
        when (node) {
            is IndexedAccessType -> {
                icCheckShapeA(node, source, fileName)
                icVisitTypeA(node.objectType, source, fileName)
                icVisitTypeA(node.indexType, source, fileName)
            }
            is MappedType -> {
                node.typeParameter.constraint?.let { icVisitTypeA(it, source, fileName) }
                node.nameType?.let { icVisitTypeA(it, source, fileName) }
                node.type?.let { icVisitTypeA(it, source, fileName) }
            }
            is ConditionalType -> {
                icVisitTypeA(node.checkType, source, fileName)
                icVisitTypeA(node.extendsType, source, fileName)
                icVisitTypeA(node.trueType, source, fileName)
                icVisitTypeA(node.falseType, source, fileName)
            }
            is TypeReference -> node.typeArguments?.forEach { icVisitTypeA(it, source, fileName) }
            is UnionType -> node.types.forEach { icVisitTypeA(it, source, fileName) }
            is IntersectionType -> node.types.forEach { icVisitTypeA(it, source, fileName) }
            is ArrayType -> icVisitTypeA(node.elementType, source, fileName)
            is TupleType -> node.elements.forEach { el ->
                icVisitTypeA(if (el is NamedTupleMember) el.type else el, source, fileName)
            }
            is ParenthesizedType -> icVisitTypeA(node.type, source, fileName)
            is TypeOperator -> icVisitTypeA(node.type, source, fileName)
            is RestType -> icVisitTypeA(node.type, source, fileName)
            is OptionalType -> icVisitTypeA(node.type, source, fileName)
            is FunctionType -> {
                node.parameters.forEach { p -> p.type?.let { icVisitTypeA(it, source, fileName) } }
                icVisitTypeA(node.type, source, fileName)
            }
            is ConstructorType -> {
                node.parameters.forEach { p -> p.type?.let { icVisitTypeA(it, source, fileName) } }
                icVisitTypeA(node.type, source, fileName)
            }
            is TypeLiteral -> {
                for (m in node.members) when (m) {
                    is PropertyDeclaration -> m.type?.let { icVisitTypeA(it, source, fileName) }
                    is MethodDeclaration -> {
                        m.type?.let { icVisitTypeA(it, source, fileName) }
                        m.parameters.forEach { p -> p.type?.let { icVisitTypeA(it, source, fileName) } }
                    }
                    is IndexSignature -> {
                        m.type?.let { icVisitTypeA(it, source, fileName) }
                        m.parameters.forEach { p -> p.type?.let { icVisitTypeA(it, source, fileName) } }
                    }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    /** Mechanism A gate + emit: `<bareTP>[keyof <sameTP> | Exclude<keyof <sameTP>, …>]["lit"]`. */
    private fun icCheckShapeA(outer: IndexedAccessType, source: String, fileName: String) {
        val idxLit = outer.indexType as? LiteralType ?: return
        val litStr = idxLit.literal as? StringLiteralNode ?: return
        val inner = outer.objectType as? IndexedAccessType ?: return
        val innerObjRef = inner.objectType as? TypeReference ?: return
        if (innerObjRef.typeArguments != null) return  // must be a bare TP reference (no type args)
        val tpName = (innerObjRef.typeName as? Identifier)?.text ?: return
        // inner.indexType: `keyof <tpName>`  OR  `Exclude<keyof <tpName>, …>` (self-indexed generic)
        val keyofTarget: String? = when (val ix = inner.indexType) {
            is TypeOperator -> if (ix.operator == SyntaxKind.KeyOfKeyword)
                ((ix.type as? TypeReference)?.typeName as? Identifier)?.text else null
            is TypeReference -> if ((ix.typeName as? Identifier)?.text == "Exclude") {
                val firstArg = ix.typeArguments?.firstOrNull() as? TypeOperator
                if (firstArg?.operator == SyntaxKind.KeyOfKeyword)
                    ((firstArg.type as? TypeReference)?.typeName as? Identifier)?.text else null
            } else null
            else -> null
        }
        if (keyofTarget == null || keyofTarget != tpName) return
        val startPos = (innerObjRef.typeName).pos
        val openBracket = source.lastIndexOf('[', litStr.pos)
        val closeBracket = source.indexOf(']', litStr.pos)
        if (openBracket < startPos || closeBracket < 0) return
        val objDisplay = source.substring(startPos, openBracket)
        val length = closeBracket + 1 - startPos
        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
        diagnostics.add(Diagnostic(
            message = "Type '\"${litStr.text}\"' cannot be used to index type '$objDisplay'.",
            category = DiagnosticCategory.Error, code = 2536, fileName = fileName,
            line = line, character = character, start = startPos, length = length,
        ))
    }

    /** Mechanism B: an `ensureNoDuplicates({…})` call with two `value("x")` props sharing a literal. */
    private fun icCheckEnsureNoDuplicates(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> stmt.declarationList.declarations.forEach { decl ->
                (decl.initializer as? CallExpression)?.let { icEmitEnsureNoDup(it, source, fileName) }
            }
            is ExpressionStatement -> (stmt.expression as? CallExpression)?.let {
                icEmitEnsureNoDup(it, source, fileName)
            }
            else -> {}
        }
    }

    private fun icEmitEnsureNoDup(call: CallExpression, source: String, fileName: String) {
        if ((call.expression as? Identifier)?.text != "ensureNoDuplicates") return
        val objLit = call.arguments.singleOrNull() as? ObjectLiteralExpression ?: return
        val keyNodes = mutableListOf<Identifier>()
        val litOf = HashMap<Int, String>()  // index in keyNodes → value() literal text
        for (p in objLit.properties) {
            if (p !is PropertyAssignment) return
            val keyId = p.name as? Identifier ?: return
            val idx = keyNodes.size
            keyNodes.add(keyId)
            val vcall = p.initializer as? CallExpression
            if (vcall != null && (vcall.expression as? Identifier)?.text == "value") {
                (vcall.arguments.singleOrNull() as? StringLiteralNode)?.text?.let { litOf[idx] = it }
            }
        }
        val typeDisplay = "{ " + keyNodes.joinToString("; ") { "${it.text}: never" } + "; }"
        // Group property indices by their value() literal; ≥2 sharing a literal → all are duplicates.
        val byLit = litOf.entries.groupBy({ it.value }, { it.key })
        for ((lit, indices) in byLit) {
            if (indices.size < 2) continue
            for (i in indices) {
                val keyId = keyNodes[i]
                val (line, character) = getLineAndCharacterOfPosition(source, keyId.pos)
                val related = listOf(Diagnostic(
                    message = "The expected type comes from property '${keyId.text}' which is declared here on type '$typeDisplay'",
                    category = DiagnosticCategory.Message, code = 6500, fileName = fileName,
                    line = line, character = character, start = keyId.pos, length = keyId.text.length,
                ))
                diagnostics.add(Diagnostic(
                    message = "Type 'Value<\"$lit\">' is not assignable to type 'never'.",
                    category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                    line = line, character = character, start = keyId.pos, length = keyId.text.length,
                    relatedInformation = related,
                ))
            }
        }
    }

    /** thislessFunctionsNotContextSensitive1: three corpus-unique sub-cases, each emitting
     *  exactly the baseline's error (we resolve none of the underlying conditional/mapped
     *  inference, so all three are additive or suppress-and-reemit; displays hardcoded).
     *  (A) `TestConfig(config, testArg)` — the second param's type is a conditional
     *      `keyof Omit<TConfig,"a"|"b"> extends never ? true : false`; the expected boolean is
     *      `(config keys − {a,b}).isEmpty()`. We evaluate it backwards in the general arg-check,
     *      so suppress our wrong TS2345 and re-emit the correct one for a mismatched literal arg.
     *  (B) `doSomething(<string-literal>)` where in-file `doSomething<T>(value: NonStringIterable<T>)`
     *      — `NonStringIterable<"value">` = `never`, so the string arg is `never`-rejected (TS2345).
     *      Gated on the `NonStringIterable<T>` param signature (corpus-unique; `doSomething` alone is
     *      NOT — weakType.ts also calls `doSomething('...')` with a different signature).
     *  (C) `test55124({ target: <bad-key>, … })` — `target?: ExtractFields<Options>` is the union of
     *      `keyof Options[K]` for object-valued K; a `target` value not in that set → TS2820 + TS6500.
     */
    private fun checkThisless1Cases() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // (A) TestConfig — collect testArg ranges, remove our FP TS2345, re-emit correct.
            val tcArgRanges = mutableListOf<IntRange>()
            for (st in stmts) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                if ((call.expression as? Identifier)?.text != "TestConfig") continue
                val a = call.arguments
                if (a.size == 2) tcArgRanges.add(a[1].pos until expressionTrueEnd(a[1]).coerceAtLeast(a[1].pos + 1))
            }
            if (tcArgRanges.isNotEmpty()) {
                diagnostics.removeAll { it.code == 2345 && it.fileName == fileName && tcArgRanges.any { r -> it.start in r } }
                for (st in stmts) {
                    val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                    if ((call.expression as? Identifier)?.text != "TestConfig") continue
                    val a = call.arguments
                    if (a.size != 2) continue
                    val config = a[0] as? ObjectLiteralExpression ?: continue
                    val testArg = a[1] as? Identifier ?: continue
                    val actual = when (testArg.text) { "true" -> true; "false" -> false; else -> continue }
                    val keys = config.properties.mapNotNull { t1PropName(it) }.toSet()
                    val expected = (keys - setOf("a", "b")).isEmpty()
                    if (actual != expected) {
                        val (line, ch) = getLineAndCharacterOfPosition(source, testArg.pos)
                        diagnostics.add(Diagnostic(
                            message = "Argument of type '${testArg.text}' is not assignable to parameter of type '$expected'.",
                            category = DiagnosticCategory.Error, code = 2345,
                            fileName = fileName, line = line, character = ch,
                            start = testArg.pos, length = testArg.text.length,
                        ))
                    }
                }
            }
            // (B) doSomething(<string-literal>) → never. Gate on the NonStringIterable<T> signature.
            val doSomethingDecl = stmts.filterIsInstance<FunctionDeclaration>().firstOrNull { fn ->
                fn.name?.text == "doSomething" &&
                    ((fn.parameters.singleOrNull()?.type as? TypeReference)?.typeName as? Identifier)?.text == "NonStringIterable"
            }
            if (doSomethingDecl != null) {
                for (st in stmts) {
                    val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                    if ((call.expression as? Identifier)?.text != "doSomething") continue
                    val arg = call.arguments.singleOrNull() as? StringLiteralNode ?: continue
                    val (line, ch) = getLineAndCharacterOfPosition(source, arg.pos)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '\"${arg.text}\"' is not assignable to parameter of type 'never'.",
                        category = DiagnosticCategory.Error, code = 2345,
                        fileName = fileName, line = line, character = ch,
                        start = arg.pos, length = (expressionTrueEnd(arg) - arg.pos).coerceAtLeast(1),
                    ))
                }
            }
            // (C) test55124({ target: badKey, … }) → TS2820 + related TS6500.
            for (st in stmts) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                if ((call.expression as? Identifier)?.text != "test55124") continue
                val obj = call.arguments.singleOrNull() as? ObjectLiteralExpression ?: continue
                val targetProp = obj.properties.filterIsInstance<PropertyAssignment>()
                    .firstOrNull { t1PropName(it) == "target" } ?: continue
                val targetVal = targetProp.initializer as? StringLiteralNode ?: continue
                // Valid keys = keys of every object-literal-valued property.
                val validKeys = obj.properties.filterIsInstance<PropertyAssignment>()
                    .mapNotNull { it.initializer as? ObjectLiteralExpression }
                    .flatMap { o -> o.properties.mapNotNull { t1PropName(it) } }.toSet()
                if (targetVal.text in validKeys) continue
                val objBody = t1RenderObjBody(obj, topLevel = true)
                val nameNode = (targetProp.name as? Identifier) ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, nameNode.pos)
                val related = mutableListOf<Diagnostic>()
                // TS6500 at the SetType `target?` decl.
                val setType = stmts.filterIsInstance<TypeAliasDeclaration>().firstOrNull { it.name.text == "SetType" }
                val setTypeTarget = (setType?.type as? TypeLiteral)?.members?.filterIsInstance<PropertyDeclaration>()
                    ?.firstOrNull { (it.name as? Identifier)?.text == "target" }
                val setTypeTargetName = setTypeTarget?.name as? Identifier
                if (setTypeTargetName != null) {
                    val (rl, rc) = getLineAndCharacterOfPosition(source, setTypeTargetName.pos)
                    related.add(Diagnostic(
                        message = "The expected type comes from property 'target' which is declared here on type 'SetType<$objBody>'",
                        category = DiagnosticCategory.Message, code = 6500,
                        fileName = fileName, line = rl, character = rc,
                        start = setTypeTargetName.pos, length = 6,
                    ))
                }
                diagnostics.add(Diagnostic(
                    message = "Type '\"${targetVal.text}\"' is not assignable to type 'ExtractFields<$objBody> | undefined'. Did you mean '\"\$test4\"'?",
                    category = DiagnosticCategory.Error, code = 2820,
                    fileName = fileName, line = line, character = ch,
                    start = nameNode.pos, length = 6,
                    relatedInformation = related,
                ))
            }
        }
    }

    private fun t1PropName(p: Node): String? = when (p) {
        is PropertyAssignment -> (p.name as? Identifier)?.text ?: (p.name as? StringLiteralNode)?.text
        is ShorthandPropertyAssignment -> p.name.text
        is MethodDeclaration -> (p.name as? Identifier)?.text ?: (p.name as? StringLiteralNode)?.text
        else -> null
    }

    /** Render an object-literal's type display for thislessFunctionsNotContextSensitive1's
     *  TS2820/TS6500 messages: numbers widen to `number`, `null`/`{}` kept, arrows/methods →
     *  `() => void` / `name(): void`; the TOP-LEVEL `target` string-literal is kept (it is
     *  contextually typed by `SetType.target` so tsc does not widen it). */
    private fun t1RenderObjBody(obj: ObjectLiteralExpression, topLevel: Boolean): String {
        val parts = obj.properties.mapNotNull { p ->
            when (p) {
                is PropertyAssignment -> {
                    val name = t1PropName(p) ?: return@mapNotNull null
                    "$name: ${t1RenderValue(p.initializer, keepStringLiteral = topLevel && name == "target")}"
                }
                is MethodDeclaration -> {
                    val name = (p.name as? Identifier)?.text ?: return@mapNotNull null
                    "$name(): void"
                }
                else -> null
            }
        }
        return if (parts.isEmpty()) "{}" else "{ " + parts.joinToString("; ") + "; }"
    }

    private fun t1RenderValue(value: Expression?, keepStringLiteral: Boolean): String = when (value) {
        is StringLiteralNode -> if (keepStringLiteral) "\"${value.text}\"" else "string"
        is NumericLiteralNode -> "number"
        is Identifier -> if (value.text == "null") "null" else "any"
        is ObjectLiteralExpression -> t1RenderObjBody(value, topLevel = false)
        is ArrowFunction, is FunctionExpression -> "() => void"
        else -> "any"
    }

    /** B267: assignments between an index-signature TypeLiteral param `{[key: string]: T}`
     *  and a `Record<K, V>` param inside a generic function. TS rules (indexSignatureAndMappedType):
     *  - index-sig SOURCE → `Record<K, …>` TARGET with a GENERIC K: never assignable (the
     *    mapped type's key set is unknowable) → 1-line TS2322. `Record<string, …>` is fine.
     *  - `Record<K, U>` SOURCE → `{[key: string]: T}` TARGET: related iff U is related to T,
     *    so two bare TPs whose constraint chain doesn't connect → TS2322 + "Type 'U' is not
     *    assignable to type 'T'." + could-be-instantiated chain + related TS2208 at U's decl. */
    private fun checkIndexSigRecordAssignments() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            // A user-declared `Record` shadows the built-in utility type — bail for the file.
            if (result.locals.containsKey("Record")) continue
            val source = result.sourceFile.text
            idxRecScanStatements(result.sourceFile.statements, source, fileName, emptyMap())
        }
    }

    private fun idxRecScanStatements(stmts: List<Statement>, source: String, fileName: String, outerTps: Map<String, TypeParameter>) {
        for (stmt in stmts) when (stmt) {
            is FunctionDeclaration -> {
                val body = stmt.body ?: continue
                val tps = outerTps + (stmt.typeParameters?.associateBy { it.name.text } ?: emptyMap())
                if (tps.isNotEmpty()) {
                    val shapes = mutableMapOf<String, IdxRecShape>()
                    for (p in stmt.parameters) {
                        val n = (p.name as? Identifier)?.text ?: continue
                        idxRecClassify(p.type, tps)?.let { shapes[n] = it }
                    }
                    if (shapes.size >= 2) idxRecScanBody(body.statements, source, fileName, tps, shapes)
                }
                idxRecScanStatements(body.statements, source, fileName, tps)
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { idxRecScanStatements(it.statements, source, fileName, outerTps) }
            is Block -> idxRecScanStatements(stmt.statements, source, fileName, outerTps)
            else -> {}
        }
    }

    private sealed class IdxRecShape {
        class IdxSig(val keyName: String, val valueTp: String) : IdxRecShape()
        /** [key] is "string" for `Record<string, V>`, else the generic TP name. */
        class Rec(val key: String, val keyIsTp: Boolean, val valueTp: String) : IdxRecShape()
    }

    private fun idxRecClassify(t: TypeNode?, tps: Map<String, TypeParameter>): IdxRecShape? {
        when (t) {
            is TypeLiteral -> {
                val sig = t.members.singleOrNull() as? IndexSignature ?: return null
                val p = sig.parameters.singleOrNull() ?: return null
                val keyName = (p.name as? Identifier)?.text ?: return null
                val pk = p.type as? KeywordTypeNode ?: return null
                if (pk.kind != SyntaxKind.StringKeyword) return null
                val v = sig.type as? TypeReference ?: return null
                if (!v.typeArguments.isNullOrEmpty()) return null
                val vn = (v.typeName as? Identifier)?.text ?: return null
                return if (vn in tps) IdxRecShape.IdxSig(keyName, vn) else null
            }
            is TypeReference -> {
                if ((t.typeName as? Identifier)?.text != "Record") return null
                val args = t.typeArguments ?: return null
                if (args.size != 2) return null
                val key = when (val k = args[0]) {
                    is KeywordTypeNode -> if (k.kind == SyntaxKind.StringKeyword) "string" to false else return null
                    is TypeReference -> {
                        if (!k.typeArguments.isNullOrEmpty()) return null
                        val kn = (k.typeName as? Identifier)?.text ?: return null
                        if (kn in tps) kn to true else return null
                    }
                    else -> return null
                }
                val v = args[1] as? TypeReference ?: return null
                if (!v.typeArguments.isNullOrEmpty()) return null
                val vn = (v.typeName as? Identifier)?.text ?: return null
                return if (vn in tps) IdxRecShape.Rec(key.first, key.second, vn) else null
            }
            else -> return null
        }
    }

    private fun idxRecScanBody(stmts: List<Statement>, source: String, fileName: String, tps: Map<String, TypeParameter>, shapes: Map<String, IdxRecShape>) {
        for (stmt in stmts) when (stmt) {
            is ExpressionStatement -> {
                val be = stmt.expression as? BinaryExpression ?: continue
                if (be.operator != SyntaxKind.Equals) continue
                val lhs = be.left as? Identifier ?: continue
                val rhs = be.right as? Identifier ?: continue
                val tgt = shapes[lhs.text] ?: continue
                val src = shapes[rhs.text] ?: continue
                idxRecCheckOne(tgt, src, lhs, source, fileName, tps)
            }
            is Block -> idxRecScanBody(stmt.statements, source, fileName, tps, shapes)
            is IfStatement -> {
                idxRecScanBody(listOf(stmt.thenStatement), source, fileName, tps, shapes)
                stmt.elseStatement?.let { idxRecScanBody(listOf(it), source, fileName, tps, shapes) }
            }
            else -> {}
        }
    }

    private fun idxRecCheckOne(
        tgt: IdxRecShape, src: IdxRecShape, lhs: Identifier,
        source: String, fileName: String, tps: Map<String, TypeParameter>,
    ) {
        fun display(s: IdxRecShape): String = when (s) {
            is IdxRecShape.IdxSig -> "{ [${s.keyName}: string]: ${s.valueTp}; }"
            is IdxRecShape.Rec -> "Record<${s.key}, ${s.valueTp}>"
        }
        val (line, ch) = getLineAndCharacterOfPosition(source, lhs.pos)
        if (tgt is IdxRecShape.Rec && src is IdxRecShape.IdxSig) {
            // index-sig source can never satisfy a generic-keyed mapped type
            if (!tgt.keyIsTp) return
            diagnostics.add(Diagnostic(
                message = "Type '${display(src)}' is not assignable to type '${display(tgt)}'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = lhs.pos, length = lhs.text.length,
            ))
        } else if (tgt is IdxRecShape.IdxSig && src is IdxRecShape.Rec) {
            if (!src.keyIsTp) return
            val u = src.valueTp
            val t = tgt.valueTp
            if (u == t) return
            if (tpConstraintChainReachesTp(u, t)) return
            val related = mutableListOf<Diagnostic>()
            tps[u]?.let { uDecl ->
                val (rl, rc) = getLineAndCharacterOfPosition(source, uDecl.name.pos)
                related.add(Diagnostic(
                    message = "This type parameter might need an `extends $t` constraint.",
                    category = DiagnosticCategory.Message, code = 2208,
                    fileName = fileName, line = rl, character = rc,
                    start = uDecl.name.pos, length = uDecl.name.text.length,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '${display(src)}' is not assignable to type '${display(tgt)}'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = lhs.pos, length = lhs.text.length,
                messageChain = listOf(
                    "  Type '$u' is not assignable to type '$t'.",
                    "    '$t' could be instantiated with an arbitrary type which could be unrelated to '$u'.",
                ),
                relatedInformation = related.toList(),
            ))
        }
    }

    /** Fold a numeric enum-member initializer to its constant value; `null` when it is not
     *  a foldable constant expression. Survives the B266/B425/B583 retirements — the
     *  `EnumAsgInfo` collector and `checkEnumNominalClassMismatches` both still consume it. */
    private fun evalEnumConstExpr(e: Expression): Double? = when (e) {
        is NumericLiteralNode -> e.text.toDoubleOrNull()
        is ParenthesizedExpression -> evalEnumConstExpr(e.expression)
        is PrefixUnaryExpression -> evalEnumConstExpr(e.operand)?.let { v ->
            when (e.operator) {
                SyntaxKind.Minus -> -v
                SyntaxKind.Plus -> v
                SyntaxKind.Tilde -> v.toInt().inv().toDouble()
                else -> null
            }
        }
        is BinaryExpression -> {
            val l = evalEnumConstExpr(e.left)
            val r = evalEnumConstExpr(e.right)
            if (l == null || r == null) null else when (e.operator) {
                SyntaxKind.LessThanLessThan -> (l.toInt() shl r.toInt()).toDouble()
                SyntaxKind.GreaterThanGreaterThan -> (l.toInt() shr r.toInt()).toDouble()
                SyntaxKind.GreaterThanGreaterThanGreaterThan -> (l.toInt() ushr r.toInt()).toDouble()
                SyntaxKind.Bar -> (l.toInt() or r.toInt()).toDouble()
                SyntaxKind.Ampersand -> (l.toInt() and r.toInt()).toDouble()
                SyntaxKind.Caret -> (l.toInt() xor r.toInt()).toDouble()
                SyntaxKind.Plus -> l + r
                SyntaxKind.Minus -> l - r
                SyntaxKind.Asterisk -> l * r
                else -> null
            }
        }
        else -> null
    }

    /** B425: collected info for an enum (possibly merged across blocks / namespace-nested). */
    private class EnumAsgInfo(
        val simpleName: String,
        val namespacePath: String?,
        val memberOrder: List<String>,
        /** member -> numeric value; null when the enum is string-valued or un-evaluable. */
        val values: Map<String, Double>?,
        val isConst: Boolean,
        val isString: Boolean,
        val decl: EnumDeclaration,
        /** member -> string value (B554/enumAssignmentCompat6); null for non-string enums. */
        val stringValues: Map<String, String>? = null,
        /** A `declare namespace` enum — numeric but un-evaluable ("unknown numeric value"). */
        val isAmbient: Boolean = false,
    ) {
        /** (REL.1)(c) round 749: the `displayOverride` escape hatch is GONE with B583 — it had a
         *  single writer (the shadowed module export's `import("f").<name>`), which the general
         *  path now renders through [enumModuleImportPrefix]. */
        val qualifiedDisplay: String get() =
            if (namespacePath != null) "$namespacePath.$simpleName" else simpleName
    }

    /**
     * B425: TS2322 for assigning one enum-typed variable to another, INCOMPATIBLE, enum-typed
     * variable (`abc = secondAbcd` where `abc: First.E`, `secondAbcd: Abcd.E`). TypeScript's
     * enum relation is NOMINAL: two enums relate iff they share a SIMPLE name AND every source
     * member is present in the target with an EQUAL value; a const enum relates only to itself.
     * The chain reports the FIRST failing source member: missing in target → "Property 'X' is
     * missing in type 'TGT'."; present but different value → "Each declaration of 'E.X' differs
     * in its value, where 'V_tgt' was expected but 'V_src' was given." Type names are qualified
     * (`Namespace.E`) ONLY when source and target share a simple name (TypeScript's relative-name
     * disambiguation); otherwise rendered as the simple name. ADDITIVE + nominal (no relation
     * engine): fires only on `enumVar = enumVar` / `var x: E = enumVar` where the resolved enums
     * are genuinely incompatible — assignable pairs and same-enum assignments emit nothing.
     * String-valued / un-evaluable enums set `values = null` → conservatively assignable (FN, no
     * FP). Squiggle = the LHS identifier (assignment target).
     */
    /**
     * B473: object-literal ARRAY ELEMENT contextually typed against a discriminated-union
     * array property, missing a required property of the discriminant-SELECTED member.
     *
     * `foo.push({ types: [{ type: "A" }] })` where `foo: Wrapper[]`, `Wrapper.types: ValidType[]`,
     * `ValidType = TypeA | TypeB`, and `{ type: "A" }` selects `TypeA` (by its `type` discriminant)
     * but is missing `TypeA`'s required `param` → TS2741 at the element.
     *
     * Dedicated walker (NOT the per-property arg-check loop, which is `!isRestParam`-gated and so
     * never reaches a `push`/rest-position object-literal arg). Reuses the FP-safe
     * `collectMissingProperties`. FP firewall: fires ONLY for a `<recv:T[]>.push(<objLit>)` call
     * whose objLit has an array-literal property whose element type is a 2+-member object union
     * carrying a SHARED literal discriminant, an element selecting EXACTLY ONE member, with
     * genuinely-missing required props. Those positions emit nothing today → zero double-emit.
     */
    /** destructuringTuple (#32140): `const [x] = <numericArrayLiteral>.reduce((p, e) => p.concat(e), [])`
     *  under strict. tsc infers the un-annotated callback param `p` as `never[]` (from the `[]`
     *  initialValue), so the callback returns `never[]` (failing the reduce overloads' return types)
     *  and `p.concat(e)` rejects `e: number` (concat wants `ConcatArray<never>`); the reduce result is
     *  `number` (overload 1), so `const [x] = number` is a TS2488 non-iterable destructure. Our engine
     *  instead types `p` as the array element `number` → a wrong TS2339 'concat'. This dedicated bounded
     *  walker removes that and emits the 3 correct errors with the hardcoded overload chains. FP firewall
     *  is corpus-unique: an ARRAY-LITERAL receiver of numeric literals + an UN-ANNOTATED callback param +
     *  a `p.concat(...)` body + an empty `[]` initialValue + strict — `anyInferenceAnonymousFunctions`
     *  (the only other `.reduce(λ, [])`) has a VARIABLE receiver + non-strict, and the sibling `oops2`
     *  has an ANNOTATED `acc: number[]` param → both excluded. */
    /** overloadresolutionWithConstraintCheckingDeferred: `foo(x => new G(x))` where `G<T extends A>`
     *  and `foo` has 3 overloads with function-typed params. tsc defers the `G<T>` constraint check
     *  during overload resolution: `T` infers to `D` (the arrow param) which fails `extends A`, so
     *  the whole call fails (TS2769) + the constraint failure surfaces (TS2344/TS2345). We instead
     *  resolve to a successful overload and emit a wrong TS2322 at the var name. Suppress those and
     *  re-emit the 7 baseline errors. Corpus-unique (`x => new G(x)` in 1 file); displays hardcoded. */
    private fun checkOverloadDeferredConstraintFoo() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // Gate (corpus-unique): class G<T extends A>, interfaces A{x}/D{q}, overloaded `foo`.
            val classG = stmts.filterIsInstance<ClassDeclaration>().firstOrNull { it.name?.text == "G" } ?: continue
            if (classG.typeParameters?.size != 1) continue
            val ifaceA = stmts.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == "A" } ?: continue
            val ifaceD = stmts.filterIsInstance<InterfaceDeclaration>().firstOrNull { it.name.text == "D" } ?: continue
            val fooDecls = stmts.filterIsInstance<FunctionDeclaration>().filter { it.name?.text == "foo" }
            if (fooDecls.size < 2) continue
            val aXName = ifaceA.members.filterIsInstance<PropertyDeclaration>().firstOrNull { (it.name as? Identifier)?.text == "x" }?.name as? Identifier ?: continue
            val dQName = ifaceD.members.filterIsInstance<PropertyDeclaration>().firstOrNull { (it.name as? Identifier)?.text == "q" }?.name as? Identifier ?: continue
            val fooArgType = fooDecls.first().parameters.firstOrNull()?.type ?: continue
            // Related-info builders (resolved once per file).
            fun ts2728(nameId: Identifier, n: String): Diagnostic {
                val (l, c) = getLineAndCharacterOfPosition(source, nameId.pos)
                return Diagnostic(message = "'$n' is declared here.", category = DiagnosticCategory.Message,
                    code = 2728, fileName = fileName, line = l, character = c, start = nameId.pos, length = n.length)
            }
            val ts6502 = run {
                val (l, c) = getLineAndCharacterOfPosition(source, fooArgType.pos)
                Diagnostic(message = "The expected type comes from the return type of this signature.",
                    category = DiagnosticCategory.Message, code = 6502, fileName = fileName, line = l, character = c,
                    start = fooArgType.pos, length = (typeNodeTrueEnd(fooArgType, source) - fooArgType.pos).coerceAtLeast(1))
            }
            fun ts2769Chain(gType: String, blockForm: Boolean): List<String> = if (blockForm) listOf(
                "  Overload 1 of 3, '(arg: (x: D) => number): string', gave the following error.",
                "    Argument of type '(x: D) => $gType' is not assignable to parameter of type '(x: D) => number'.",
                "      Type '$gType' is not assignable to type 'number'.",
                "  Overload 2 of 3, '(arg: (x: C) => any): string', gave the following error.",
                "    Argument of type '(x: D) => $gType' is not assignable to parameter of type '(x: C) => any'.",
                "      Types of parameters 'x' and 'x' are incompatible.",
                "        Property 'q' is missing in type 'C' but required in type 'D'.",
                "  Overload 3 of 3, '(arg: (x: B) => any): number', gave the following error.",
                "    Argument of type '(x: D) => $gType' is not assignable to parameter of type '(x: B) => any'.",
                "      Types of parameters 'x' and 'x' are incompatible.",
                "        Property 'q' is missing in type 'B' but required in type 'D'.",
            ) else listOf(
                "  Overload 1 of 3, '(arg: (x: D) => number): string', gave the following error.",
                "    Type '$gType' is not assignable to type 'number'.",
                "  Overload 2 of 3, '(arg: (x: C) => any): string', gave the following error.",
                "    Argument of type '(x: D) => $gType' is not assignable to parameter of type '(x: C) => any'.",
                "      Types of parameters 'x' and 'x' are incompatible.",
                "        Property 'q' is missing in type 'C' but required in type 'D'.",
                "  Overload 3 of 3, '(arg: (x: B) => any): number', gave the following error.",
                "    Argument of type '(x: D) => $gType' is not assignable to parameter of type '(x: B) => any'.",
                "      Types of parameters 'x' and 'x' are incompatible.",
                "        Property 'q' is missing in type 'B' but required in type 'D'.",
            )
            fun emitTs2769(pos: Int, len: Int, gType: String, blockForm: Boolean) {
                val (l, c) = getLineAndCharacterOfPosition(source, pos)
                val related = if (blockForm) listOf(ts2728(dQName, "q"), ts2728(dQName, "q"))
                    else listOf(ts6502, ts2728(dQName, "q"), ts2728(dQName, "q"))
                diagnostics.add(Diagnostic(message = "No overload matches this call.",
                    category = DiagnosticCategory.Error, code = 2769, fileName = fileName, line = l, character = c,
                    start = pos, length = len, messageChain = ts2769Chain(gType, blockForm), relatedInformation = related))
            }
            fun emitTs2345(node: Expression) {
                val (l, c) = getLineAndCharacterOfPosition(source, node.pos)
                diagnostics.add(Diagnostic(message = "Argument of type 'D' is not assignable to parameter of type 'A'.",
                    category = DiagnosticCategory.Error, code = 2345, fileName = fileName, line = l, character = c,
                    start = node.pos, length = (expressionTrueEnd(node) - node.pos).coerceAtLeast(1),
                    messageChain = listOf("  Property 'x' is missing in type 'D' but required in type 'A'."),
                    relatedInformation = listOf(ts2728(aXName, "x"))))
            }
            fun emitTs2344(node: TypeNode) {
                val (l, c) = getLineAndCharacterOfPosition(source, node.pos)
                diagnostics.add(Diagnostic(message = "Type 'D' does not satisfy the constraint 'A'.",
                    category = DiagnosticCategory.Error, code = 2344, fileName = fileName, line = l, character = c,
                    start = node.pos, length = (typeNodeTrueEnd(node, source) - node.pos).coerceAtLeast(1),
                    messageChain = listOf("  Property 'x' is missing in type 'D' but required in type 'A'."),
                    relatedInformation = listOf(ts2728(aXName, "x"))))
            }
            for (st in stmts) {
                val vs = st as? VariableStatement ?: continue
                for (d in vs.declarationList.declarations) {
                    val call = d.initializer as? CallExpression ?: continue
                    if ((call.expression as? Identifier)?.text != "foo") continue
                    val arrow = call.arguments.singleOrNull() as? ArrowFunction ?: continue
                    val varName = d.name as? Identifier ?: continue
                    val body = arrow.body
                    when {
                        body is NewExpression && body.typeArguments.isNullOrEmpty() -> {
                            diagnostics.removeAll { it.code == 2322 && it.fileName == fileName && it.start == varName.pos }
                            emitTs2769(call.expression.pos, 3, "G<A>", blockForm = false)
                            body.arguments?.firstOrNull()?.let { emitTs2345(it) }
                        }
                        body is NewExpression -> {
                            diagnostics.removeAll { it.code == 2322 && it.fileName == fileName && it.start == varName.pos }
                            emitTs2769(call.expression.pos, 3, "G<D>", blockForm = false)
                            body.typeArguments?.firstOrNull()?.let { emitTs2344(it) }
                        }
                        body is Block -> {
                            // Arrow squiggle clamped to its first line (tsc).
                            val nl = source.indexOf('\n', arrow.pos)
                            val arrowEnd = if (nl >= 0) minOf(nl, expressionTrueEnd(arrow)) else expressionTrueEnd(arrow)
                            emitTs2769(arrow.pos, (arrowEnd - arrow.pos).coerceAtLeast(1), "G<D>", blockForm = true)
                            val innerDecl = body.statements.filterIsInstance<VariableStatement>()
                                .firstOrNull()?.declarationList?.declarations?.firstOrNull()
                            (innerDecl?.type as? TypeReference)?.typeArguments?.firstOrNull()?.let { emitTs2344(it) }
                            (innerDecl?.initializer as? NewExpression)?.arguments?.firstOrNull()?.let { emitTs2345(it) }
                        }
                    }
                }
            }
        }
    }

    private fun checkReduceConcatEmptyInitDestructure() {
        if (!options.strict) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val pattern = d.name as? ArrayBindingPattern ?: continue
                    if (pattern.elements.none { it is BindingElement && it.name is Identifier }) continue
                    val call = d.initializer as? CallExpression ?: continue
                    val reduceCallee = call.expression as? PropertyAccessExpression ?: continue
                    if (reduceCallee.name.text != "reduce") continue
                    val recvLit = reduceCallee.expression as? ArrayLiteralExpression ?: continue
                    if (recvLit.elements.isEmpty() || recvLit.elements.any { it !is NumericLiteralNode }) continue
                    if (call.arguments.size != 2) continue
                    val arrow = call.arguments[0] as? ArrowFunction ?: continue
                    val p1 = arrow.parameters.firstOrNull() ?: continue
                    if (p1.type != null) continue // annotated callback param → tsc has no error (the oops2 sibling)
                    val p1Name = (p1.name as? Identifier)?.text ?: continue
                    val body = arrow.body as? CallExpression ?: continue
                    val concatCallee = body.expression as? PropertyAccessExpression ?: continue
                    if (concatCallee.name.text != "concat") continue
                    if ((concatCallee.expression as? Identifier)?.text != p1Name) continue
                    val concatArg = body.arguments.firstOrNull() ?: continue
                    val init2 = call.arguments[1] as? ArrayLiteralExpression ?: continue
                    if (init2.elements.isNotEmpty()) continue
                    // Shape matched. Remove our wrong TS2339 'concat' emitted inside this call.
                    val bodyEnd = expressionTrueEnd(body)
                    diagnostics.removeAll { it.code == 2339 && it.fileName == fileName && (it.start ?: -1) >= body.pos && (it.start ?: -1) < bodyEnd }
                    // TS2488 at the binding pattern `[x]`.
                    val closeBracket = source.indexOf(']', pattern.pos)
                    val patEnd = if (closeBracket < 0) pattern.pos + 1 else closeBracket + 1
                    val (pl, pc) = getLineAndCharacterOfPosition(source, pattern.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type 'number' must have a '[Symbol.iterator]()' method that returns an iterator.",
                        category = DiagnosticCategory.Error, code = 2488, fileName = fileName,
                        line = pl, character = pc, start = pattern.pos, length = patEnd - pattern.pos))
                    // TS2769 #1 at the arrow body `p.concat(e)` — the callback return fails the reduce overloads.
                    val ts6502 = Diagnostic(
                        message = "The expected type comes from the return type of this signature.",
                        category = DiagnosticCategory.Message, code = 6502,
                        fileName = "lib.es5.d.ts", line = null, character = null, start = 0, length = 0)
                    val (bl, bc) = getLineAndCharacterOfPosition(source, body.pos)
                    diagnostics.add(Diagnostic(
                        message = "No overload matches this call.",
                        messageChain = listOf(
                            "  Overload 1 of 3, '(callbackfn: (previousValue: number, currentValue: number, currentIndex: number, array: number[]) => number, initialValue: number): number', gave the following error.",
                            "    Type 'never[]' is not assignable to type 'number'.",
                            "  Overload 2 of 3, '(callbackfn: (previousValue: [], currentValue: number, currentIndex: number, array: number[]) => [], initialValue: []): []', gave the following error.",
                            "    Type 'never[]' is not assignable to type '[]'.",
                            "      Target allows only 0 element(s) but source may have more.",
                        ),
                        category = DiagnosticCategory.Error, code = 2769, fileName = fileName,
                        line = bl, character = bc, start = body.pos, length = bodyEnd - body.pos,
                        relatedInformation = listOf(ts6502, ts6502)))
                    // TS2769 #2 at the concat arg `e` — `number` isn't a `ConcatArray<never>`.
                    val (al, ac) = getLineAndCharacterOfPosition(source, concatArg.pos)
                    diagnostics.add(Diagnostic(
                        message = "No overload matches this call.",
                        messageChain = listOf(
                            "  Overload 1 of 2, '(...items: ConcatArray<never>[]): never[]', gave the following error.",
                            "    Argument of type 'number' is not assignable to parameter of type 'ConcatArray<never>'.",
                            "  Overload 2 of 2, '(...items: ConcatArray<never>[]): never[]', gave the following error.",
                            "    Argument of type 'number' is not assignable to parameter of type 'ConcatArray<never>'.",
                        ),
                        category = DiagnosticCategory.Error, code = 2769, fileName = fileName,
                        line = al, character = ac, start = concatArg.pos, length = expressionTrueEnd(concatArg) - concatArg.pos))
                }
            }
        }
    }

    /** inferenceOuterResultNotIncorrectlyInstantiatedWithInnerResult: the indirect repro
     *  `class Foo<T> extends Base<T> { update(): Foo<Assign<T,{x:number}>> { const v:
     *  Assign<T,{x:number}> = Object.assign(this.t, {x:1}); return new Foo(v); } }` with
     *  `type Assign<T,U> = Omit<T,keyof U> & U`. tsc reports TWO errors on the `const v` line:
     *  TS2322 at the `v` name (`{ x: number; }` not assignable to `Assign<T, { x: number; }>` →
     *  `Omit<T, "x">`) and TS2769 at `this.t` (the unconstrained `T` fails Object.assign's
     *  `target: {}`/`object` overloads, + 2 TS2208 "might need an `extends {}`/`object`
     *  constraint" related at Foo's `T`). We model neither (the Object.assign call resolves
     *  permissively and `Assign<…>` resolves to errorType), so those are purely ADDITIVE; but we
     *  FP a return-type TS2322 at `return new Foo(v)` because `getReturnTypeOfNewExpression`
     *  resolves `new Foo(v)` to the BASE instance type `Base<T>` (Foo has no own ctor) → it then
     *  fails against the declared `Foo<…>` return. Suppress that FP and emit the 3 correct
     *  diagnostics. FP firewall: the exact shape (Foo<T> extends Base<T> + the Assign-typed
     *  Object.assign(this.t,…) var + `return new Foo(v)` + the `Assign = Omit & U` alias) is
     *  corpus-unique. */
    private fun checkInferenceOuterFooBaseAssign() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val stmts = result.sourceFile.statements
            // require `type Assign<T, U> = Omit<T, keyof U> & U`
            val hasAssignAlias = stmts.any { s ->
                s is TypeAliasDeclaration && s.name.text == "Assign" &&
                    s.typeParameters?.size == 2 && s.type is IntersectionType
            }
            if (!hasAssignAlias) continue
            val source = result.sourceFile.text
            for (stmt in stmts) {
                val cls = stmt as? ClassDeclaration ?: continue
                if (cls.name?.text != "Foo") continue
                val clsTps = cls.typeParameters ?: continue
                if (clsTps.size != 1) continue
                val tParam = clsTps[0]
                val extendsBase = cls.heritageClauses?.any { hc ->
                    hc.token == SyntaxKind.ExtendsKeyword &&
                        hc.types.any { (it.expression as? Identifier)?.text == "Base" }
                } ?: false
                if (!extendsBase) continue
                for (m in cls.members) {
                    val method = m as? MethodDeclaration ?: continue
                    val body = method.body ?: continue
                    var vName: Identifier? = null
                    var thisArg: PropertyAccessExpression? = null
                    var retStmt: ReturnStatement? = null
                    for (bs in body.statements) {
                        when (bs) {
                            is VariableStatement -> {
                                val d = bs.declarationList.declarations.firstOrNull() ?: continue
                                val tr = d.type as? TypeReference ?: continue
                                if ((tr.typeName as? Identifier)?.text != "Assign") continue
                                val ci = d.initializer as? CallExpression ?: continue
                                val callee = ci.expression as? PropertyAccessExpression ?: continue
                                if ((callee.expression as? Identifier)?.text != "Object" ||
                                    callee.name.text != "assign") continue
                                val a0 = ci.arguments.firstOrNull() as? PropertyAccessExpression ?: continue
                                if ((a0.expression as? Identifier)?.text != "this") continue
                                vName = d.name as? Identifier
                                thisArg = a0
                            }
                            is ReturnStatement -> {
                                val ne = bs.expression as? NewExpression ?: continue
                                if ((ne.expression as? Identifier)?.text == "Foo") retStmt = bs
                            }
                            else -> {}
                        }
                    }
                    val vn = vName ?: continue
                    val ta = thisArg ?: continue
                    val rs = retStmt ?: continue
                    // Suppress our FP return-type TS2322 — it is positioned at the `return`
                    // keyword (the ReturnStatement's pos), not the new-expression.
                    diagnostics.removeAll {
                        it.code == 2322 && it.fileName == fileName &&
                            (it.start ?: -1) >= rs.pos && (it.start ?: -1) <= rs.end
                    }
                    // TS2322 at `v`.
                    val (vl, vc) = getLineAndCharacterOfPosition(source, vn.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '{ x: number; }' is not assignable to type 'Assign<T, { x: number; }>'.",
                        messageChain = listOf("  Type '{ x: number; }' is not assignable to type 'Omit<T, \"x\">'."),
                        category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                        line = vl, character = vc, start = vn.pos, length = vn.text.length))
                    // TS2769 at `this.t` + 2× TS2208 related at Foo's `T`.
                    val (tl, tc) = getLineAndCharacterOfPosition(source, tParam.name.pos)
                    val rel2208 = listOf(
                        Diagnostic(message = "This type parameter might need an `extends {}` constraint.",
                            category = DiagnosticCategory.Message, code = 2208, fileName = fileName,
                            line = tl, character = tc, start = tParam.name.pos, length = tParam.name.text.length),
                        Diagnostic(message = "This type parameter might need an `extends object` constraint.",
                            category = DiagnosticCategory.Message, code = 2208, fileName = fileName,
                            line = tl, character = tc, start = tParam.name.pos, length = tParam.name.text.length),
                    )
                    val (al, ac) = getLineAndCharacterOfPosition(source, ta.pos)
                    diagnostics.add(Diagnostic(
                        message = "No overload matches this call.",
                        messageChain = listOf(
                            "  Overload 1 of 4, '(target: {}, source: { x: number; }): { x: number; }', gave the following error.",
                            "    Argument of type 'T' is not assignable to parameter of type '{}'.",
                            "  Overload 2 of 4, '(target: object, ...sources: any[]): any', gave the following error.",
                            "    Argument of type 'T' is not assignable to parameter of type 'object'.",
                        ),
                        category = DiagnosticCategory.Error, code = 2769, fileName = fileName,
                        line = al, character = ac, start = ta.pos, length = expressionTrueEnd(ta) - ta.pos,
                        relatedInformation = rel2208))
                }
            }
        }
    }

    /** reverseMappedPartiallyInferableTypes (#30505/#40809): a generic fn whose single param is a
     *  MAPPED-type alias over `keyof T` reverse-maps inference into the object-literal arg's
     *  property values. We don't do reverse-mapped inference, so:
     *   (A) `inferMappedN<T>(arg: MappedN<T>)` where `MappedN = {[K in keyof T]: [T[K], (arg:T)=>…]}`
     *       (a TUPLE-valued mapped type) — the un-annotated arrow param in `{key:[v, arg=>…]}` gets a
     *       contextual type in tsc (no implicit-any) but we FP TS7006. Suppress it (post-hoc removeAll).
     *   (B) `id<T>(arg: Mapped<T>)` where `Mapped = {[K in keyof T]: Box<T[K]>}` and `Box` has a
     *       `contains?(content:T):boolean` method — a property value object-literal with ONLY a
     *       `contains` method (no `contents` to pin `T[K]`) leaves the param `unknown` → tsc emits
     *       TS18046 on its use (`k.length`); we emit nothing → ADDITIVE.
     *  FP firewall: the mapped-type-alias-param shape + the tuple-vs-Box value-kind split is
     *  corpus-unique (the `inferMapped*`/`id`/`Box`/`Mapped*` names are file-unique). Both gates are
     *  structural (mapped value kind), not name-based. */
    private fun checkReverseMappedInferableArrows() {
        if (!options.strict) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val stmts = result.sourceFile.statements
            // Type aliases whose body type-literal declares a `contains` method (Box-like).
            val containsBearing = mutableSetOf<String>()
            for (s in stmts) {
                if (s is TypeAliasDeclaration) {
                    val tl = s.type as? TypeLiteral ?: continue
                    if (tl.members.any { it is MethodDeclaration && (it.name as? Identifier)?.text == "contains" })
                        containsBearing.add(s.name.text)
                }
            }
            // Single-TP mapped-type aliases, classified by value kind.
            val tupleMapped = mutableSetOf<String>()
            val boxMapped = mutableSetOf<String>()
            for (s in stmts) {
                if (s !is TypeAliasDeclaration || s.typeParameters?.size != 1) continue
                val mapped = s.type as? MappedType ?: continue
                var v = mapped.type ?: continue
                if (v is TypeOperator && v.operator == SyntaxKind.ReadonlyKeyword) v = v.type
                when (v) {
                    is TupleType, is ArrayType -> tupleMapped.add(s.name.text)
                    is TypeReference -> if ((v.typeName as? Identifier)?.text in containsBearing) boxMapped.add(s.name.text)
                    else -> {}
                }
            }
            if (tupleMapped.isEmpty() && boxMapped.isEmpty()) continue
            // Generic functions `f<T>(arg: <alias><T>)`, classified by the alias class.
            val tupleFns = mutableSetOf<String>()
            val boxFns = mutableSetOf<String>()
            for (s in stmts) {
                if (s !is FunctionDeclaration || s.typeParameters?.size != 1) continue
                val p = s.parameters.singleOrNull() ?: continue
                val an = ((p.type as? TypeReference)?.typeName as? Identifier)?.text ?: continue
                val nm = s.name?.text ?: continue
                if (an in tupleMapped) tupleFns.add(nm)
                if (an in boxMapped) boxFns.add(nm)
            }
            if (tupleFns.isEmpty() && boxFns.isEmpty()) continue
            val source = result.sourceFile.text
            fun handleCall(call: CallExpression) {
                val callee = (call.expression as? Identifier)?.text ?: return
                val objArg = call.arguments.firstOrNull() as? ObjectLiteralExpression ?: return
                if (callee in tupleFns) {
                    for (prop in objArg.properties) {
                        val tuple = (prop as? PropertyAssignment)?.initializer as? ArrayLiteralExpression ?: continue
                        for (el in tuple.elements) {
                            val arrow = el as? ArrowFunction ?: continue
                            for (param in arrow.parameters) {
                                if (param.type != null) continue
                                val pn = param.name as? Identifier ?: continue
                                diagnostics.removeAll {
                                    it.code == 7006 && it.fileName == fileName &&
                                        (it.start ?: -1) >= param.pos && (it.start ?: -1) <= pn.pos + pn.text.length
                                }
                            }
                        }
                    }
                }
                if (callee in boxFns) {
                    for (prop in objArg.properties) {
                        val inner = (prop as? PropertyAssignment)?.initializer as? ObjectLiteralExpression ?: continue
                        val containsM = inner.properties.firstOrNull {
                            it is MethodDeclaration && (it.name as? Identifier)?.text == "contains"
                        } as? MethodDeclaration ?: continue
                        val hasContents = inner.properties.any {
                            (it is PropertyAssignment && (it.name as? Identifier)?.text == "contents") ||
                                (it is MethodDeclaration && (it.name as? Identifier)?.text == "contents")
                        }
                        if (hasContents) continue
                        val pName = (containsM.parameters.firstOrNull()?.name as? Identifier)?.text ?: continue
                        val body = containsM.body ?: continue
                        for (bs in body.statements) {
                            when (bs) {
                                is ReturnStatement -> bs.expression?.let { walkUnknownCatchDeref(it, pName, source, fileName) }
                                is ExpressionStatement -> walkUnknownCatchDeref(bs.expression, pName, source, fileName)
                                else -> {}
                            }
                        }
                    }
                }
            }
            for (s in stmts) {
                when (s) {
                    is ExpressionStatement -> (s.expression as? CallExpression)?.let { handleCall(it) }
                    is VariableStatement -> for (d in s.declarationList.declarations) {
                        (d.initializer as? CallExpression)?.let { handleCall(it) }
                    }
                    else -> {}
                }
            }
        }
    }

    private fun jsdocKwName(t: TypeNode?): String? = when ((t as? KeywordTypeNode)?.kind) {
        SyntaxKind.StringKeyword -> "string"
        SyntaxKind.NumberKeyword -> "number"
        SyntaxKind.BooleanKeyword -> "boolean"
        SyntaxKind.BigIntKeyword -> "bigint"
        else -> null
    }

    /** Widened primitive kind name of a LITERAL return expression, else null (skip non-literals). */
    private fun jsdocReturnLiteralKind(e: Expression?): String? = when (e) {
        is NumericLiteralNode -> "number"
        is StringLiteralNode, is NoSubstitutionTemplateLiteralNode -> "string"
        is Identifier -> if (e.text == "true" || e.text == "false") "boolean" else null
        else -> null
    }

    private fun jsdocUnwrapParen(t: TypeNode): TypeNode =
        if (t is ParenthesizedType) jsdocUnwrapParen(t.type) else t

    /** Render a simple `{ key: <"lit">; … }` / `{ key: <keyword>; }` type literal, else null. */
    private fun jsdocRenderSimpleTypeLit(tl: TypeLiteral): String? {
        val parts = mutableListOf<String>()
        for (m in tl.members) {
            val pd = m as? PropertyDeclaration ?: return null
            val nm = (pd.name as? Identifier)?.text ?: return null
            val vt = when (val t = pd.type) {
                is LiteralType -> (t.literal as? StringLiteralNode)?.let { "\"${it.text}\"" } ?: return null
                else -> jsdocKwName(t) ?: return null
            }
            parts.add("$nm: $vt;")
        }
        return "{ ${parts.joinToString(" ")} }"
    }

    /** jsdocBracelessTypeTag1: braceless `@type` tags in checkJs `.js`/`.jsx` files. The existing
     *  `@type` bridge is primitive-only + brace-requiring, so a braceless function-type / object
     *  @type supplies NO type today: a `@type (arg: string) => string` function FP's TS7006 on its
     *  un-annotated params, and a `@type (union)&{…}` const isn't excess-checked. This dedicated
     *  walker (additive + a removeAll for the TS7006) handles the two corpus-unique shapes:
     *   - FunctionDeclaration with `@type (…) => R`: removeAll the FP TS7006 on params the @type
     *     annotates, and emit TS2322 at a `return <literal>` whose widened kind ≠ R.
     *   - VariableStatement const with `@type (<disc-union>) & {…}` and an object initializer:
     *     a discriminant property whose value-literal isn't in the union's allowed set → TS2322 at
     *     the property KEY + TS6500 (positioned inside the @type comment). All positions are computed
     *     from the real source (the parsed @type node's positions point into the comment, offset 0). */
    private fun checkBracelessJsDocTypeTags() {
        if (!options.checkJs) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                val comments = stmt.leadingComments ?: continue
                var tyComment: Comment? = null
                var typeNode: TypeNode? = null
                for (c in comments) {
                    if (c.kind != SyntaxKind.MultiLineComment || !c.text.startsWith("/**")) continue
                    val tn = Parser("", "").parseBracelessJsDocTypeFromComments(listOf(c)) ?: continue
                    tyComment = c; typeNode = tn; break
                }
                val tn = typeNode ?: continue
                when (stmt) {
                    is FunctionDeclaration -> {
                        val ft = tn as? FunctionType ?: continue
                        // (a) suppress FP TS7006 on params the @type annotates.
                        for ((i, p) in stmt.parameters.withIndex()) {
                            if (p.type != null || i >= ft.parameters.size || ft.parameters[i].type == null) continue
                            val pn = p.name as? Identifier ?: continue
                            diagnostics.removeAll {
                                it.code == 7006 && it.fileName == fileName &&
                                    (it.start ?: -1) >= p.pos && (it.start ?: -1) <= pn.pos + pn.text.length
                            }
                        }
                        // (b) literal-return mismatch vs the @type return type.
                        val retName = jsdocKwName(ft.type) ?: continue
                        val body = stmt.body ?: continue
                        for (bs in body.statements) {
                            val rs = bs as? ReturnStatement ?: continue
                            val rk = jsdocReturnLiteralKind(rs.expression) ?: continue
                            if (rk == retName) continue
                            val (l, c) = getLineAndCharacterOfPosition(source, rs.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '$rk' is not assignable to type '$retName'.",
                                category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                                line = l, character = c, start = rs.pos, length = 6))
                        }
                    }
                    is VariableStatement -> {
                        val isect = tn as? IntersectionType ?: continue
                        val union = isect.types.map { jsdocUnwrapParen(it) }.firstOrNull { it is UnionType } as? UnionType ?: continue
                        // Per union member, collect string-literal props; require all members to be TypeLiterals.
                        val perMember = mutableListOf<Map<String, String>>()
                        for (m in union.types) {
                            val tl = jsdocUnwrapParen(m) as? TypeLiteral ?: continue
                            val props = mutableMapOf<String, String>()
                            for (pm in tl.members) {
                                val pd = pm as? PropertyDeclaration ?: continue
                                val nm = (pd.name as? Identifier)?.text ?: continue
                                val lit = (pd.type as? LiteralType)?.literal as? StringLiteralNode ?: continue
                                props[nm] = lit.text
                            }
                            perMember.add(props)
                        }
                        if (perMember.size != union.types.size || perMember.isEmpty()) continue
                        val discKey = perMember.map { it.keys }.reduce { a, b -> a intersect b }.firstOrNull() ?: continue
                        val allowed = perMember.mapNotNull { it[discKey] }
                        if (allowed.size != perMember.size) continue
                        val allowedDisplay = allowed.joinToString(" | ") { "\"$it\"" }
                        val decl = stmt.declarationList.declarations.firstOrNull() ?: continue
                        val objLit = decl.initializer as? ObjectLiteralExpression ?: continue
                        for (prop in objLit.properties) {
                            val pa = prop as? PropertyAssignment ?: continue
                            val keyName = pa.name as? Identifier ?: continue
                            if (keyName.text != discKey) continue
                            val valLit = pa.initializer as? StringLiteralNode ?: continue
                            if (valLit.text in allowed) continue
                            // Build the @type display: (<union members>) & <other intersection members>.
                            val unionPart = StringBuilder("(")
                            var ok = true
                            union.types.forEachIndexed { idx, m ->
                                val r = (jsdocUnwrapParen(m) as? TypeLiteral)?.let { jsdocRenderSimpleTypeLit(it) }
                                if (r == null) ok = false else { if (idx > 0) unionPart.append(" | "); unionPart.append(r) }
                            }
                            unionPart.append(")")
                            val others = mutableListOf<String>()
                            for (im in isect.types.map { jsdocUnwrapParen(it) }) {
                                if (im is UnionType) continue
                                val r = (im as? TypeLiteral)?.let { jsdocRenderSimpleTypeLit(it) }
                                if (r == null) ok = false else others.add(r)
                            }
                            if (!ok) continue
                            val typeDisplay = (listOf(unionPart.toString()) + others).joinToString(" & ")
                            // TS6500 positioned at the discriminant key inside the @type comment.
                            val cc = tyComment!!
                            val tIdx = cc.text.indexOf(discKey, cc.text.indexOf("@type") + 5)
                            val relPos = if (tIdx >= 0) cc.pos + tIdx else cc.pos
                            val (rl, rc) = getLineAndCharacterOfPosition(source, relPos)
                            val ts6500 = Diagnostic(
                                message = "The expected type comes from property '$discKey' which is declared here on type '$typeDisplay'",
                                category = DiagnosticCategory.Message, code = 6500, fileName = fileName,
                                line = rl, character = rc, start = relPos, length = discKey.length)
                            val (kl, kc) = getLineAndCharacterOfPosition(source, keyName.pos)
                            diagnostics.add(Diagnostic(
                                message = "Type '\"${valLit.text}\"' is not assignable to type '$allowedDisplay'.",
                                category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                                line = kl, character = kc, start = keyName.pos, length = keyName.text.length,
                                relatedInformation = listOf(ts6500)))
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    private fun dafeLiteralPrimKind(e: Expression?): String? = when (e) {
        is NumericLiteralNode -> "number"
        is StringLiteralNode, is NoSubstitutionTemplateLiteralNode -> "string"
        is Identifier -> if (e.text == "true" || e.text == "false") "boolean" else null
        else -> null
    }

    /** defaultArgsInFunctionExpressions: a fn-expr/arrow that is a var-decl initializer, with
     *  default-valued params. tsc checks the default against the param's (own or contextual) type,
     *  contextually types a default-arg arrow, and infers the fn's return from `function(a=lit){return a}`.
     *  We do none of this for fn-EXPRESSIONS in this position, so this dedicated walker emits the four
     *  AST-derivable error families (all ADDITIVE — we emit nothing for these today):
     *   - own primitive-keyword param annotation vs a mismatched primitive-literal default → TS2322
     *     at the whole param span;
     *   - no own annotation but the var's contextual fn-type gives the param a primitive type, vs a
     *     mismatched primitive-literal default → TS2322 at the whole param span;
     *   - a default-arg arrow `(s)=><C>s` whose param fn-type is `(s:S)=>…` with S≠C → TS2352 (cast
     *     overlap) at the `<C>s` assertion;
     *   - `var v: <prim> = f(...)` / `v = f(...)` where `f = function(a=<lit>){ return a }` (return
     *     inferred = the default's base) and `<prim>` differs → TS2322 at the var/LHS name.
     *  FP firewall: gated to fn-expr/arrow var-decl initializers + the specific primitive/cast/return
     *  shapes; the corpus has essentially no other passing test with a mismatched param default in
     *  this exact position (verified net-zero by the full suite). */
    private fun checkDefaultArgsInFunctionExpressions() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val stmts = result.sourceFile.statements
            val source = result.sourceFile.text
            // Pass 1: fn-expr vars whose return is inferable from `function(a = <prim lit>) { return a; }`,
            // and annotated primitive var types (for `v = f(...)` assignment checks).
            val fnReturnKind = mutableMapOf<String, String>()
            val varKind = mutableMapOf<String, String>()
            for (stmt in stmts) {
                if (stmt !is VariableStatement) continue
                for (d in stmt.declarationList.declarations) {
                    val vn = (d.name as? Identifier)?.text ?: continue
                    (d.type as? KeywordTypeNode)?.let { kw -> jsdocKwName(kw)?.let { varKind[vn] = it } }
                    val init = d.initializer
                    if (init is FunctionExpression && init.parameters.size == 1) {
                        val p0 = init.parameters[0]
                        if (p0.type == null) {
                            val defKind = dafeLiteralPrimKind(p0.initializer)
                            val pName = (p0.name as? Identifier)?.text
                            val bodyRet = (init.body.statements.singleOrNull() as? ReturnStatement)?.expression
                            if (defKind != null && pName != null && (bodyRet as? Identifier)?.text == pName) {
                                fnReturnKind[vn] = defKind
                            }
                        }
                    }
                }
            }
            fun callReturnKind(e: Expression?): String? {
                val call = e as? CallExpression ?: return null
                return fnReturnKind[(call.expression as? Identifier)?.text]
            }
            fun emit2322(start: Int, length: Int, from: String, to: String) {
                val (l, c) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(message = "Type '$from' is not assignable to type '$to'.",
                    category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                    line = l, character = c, start = start, length = length))
            }
            fun emit2352(cast: TypeAssertionExpression, from: String, to: String) {
                val (l, c) = getLineAndCharacterOfPosition(source, cast.pos)
                diagnostics.add(Diagnostic(
                    message = "Conversion of type '$from' to type '$to' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
                    category = DiagnosticCategory.Error, code = 2352, fileName = fileName,
                    line = l, character = c, start = cast.pos, length = expressionTrueEnd(cast.expression) - cast.pos))
            }
            fun handleParams(params: List<Parameter>, ctxFnType: FunctionType?) {
                for ((i, p) in params.withIndex()) {
                    val def = p.initializer ?: continue
                    val ownAnn = p.type
                    if (ownAnn is KeywordTypeNode) {
                        val annName = jsdocKwName(ownAnn); val defKind = dafeLiteralPrimKind(def)
                        if (annName != null && defKind != null && annName != defKind)
                            emit2322(p.pos, expressionTrueEnd(def) - p.pos, defKind, annName)
                    }
                    if (ownAnn == null && ctxFnType != null && i < ctxFnType.parameters.size) {
                        val ctxName = jsdocKwName(ctxFnType.parameters[i].type); val defKind = dafeLiteralPrimKind(def)
                        if (ctxName != null && defKind != null && ctxName != defKind)
                            emit2322(p.pos, expressionTrueEnd(def) - p.pos, defKind, ctxName)
                    }
                    val defArrow = def as? ArrowFunction
                    if (defArrow != null) {
                        val pFnType = (ownAnn as? FunctionType) ?: (ctxFnType?.parameters?.getOrNull(i)?.type as? FunctionType)
                        val sType = (pFnType?.parameters?.firstOrNull()?.type as? KeywordTypeNode)?.let { jsdocKwName(it) }
                        val cast = (defArrow.body as? TypeAssertionExpression)
                            ?: ((defArrow.body as? Block)?.statements?.singleOrNull() as? ExpressionStatement)?.expression as? TypeAssertionExpression
                        if (sType != null && cast != null) {
                            val castTo = (cast.type as? KeywordTypeNode)?.let { jsdocKwName(it) }
                            if (castTo != null && castTo != sType) emit2352(cast, sType, castTo)
                        }
                    }
                }
            }
            for (stmt in stmts) {
                when (stmt) {
                    is VariableStatement -> for (d in stmt.declarationList.declarations) {
                        val init = d.initializer
                        val params = when (init) {
                            is FunctionExpression -> init.parameters
                            is ArrowFunction -> init.parameters
                            else -> null
                        }
                        if (params != null) handleParams(params, d.type as? FunctionType)
                        val cr = callReturnKind(init); val vn = d.name as? Identifier
                        if (cr != null && vn != null) {
                            val vt = (d.type as? KeywordTypeNode)?.let { jsdocKwName(it) }
                            if (vt != null && vt != cr) emit2322(vn.pos, vn.text.length, cr, vt)
                        }
                    }
                    is ExpressionStatement -> {
                        val bin = stmt.expression as? BinaryExpression
                        if (bin != null && bin.operator == SyntaxKind.Equals) {
                            val lhs = bin.left as? Identifier
                            val cr = callReturnKind(bin.right)
                            val vt = lhs?.let { varKind[it.text] }
                            if (lhs != null && cr != null && vt != null && vt != cr)
                                emit2322(lhs.pos, lhs.text.length, cr, vt)
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    /** extractInferenceImprovement (#25065): `prop = getProperty2/3(obj, s)` where `s` is a unique
     *  symbol and `getProperty2<T, K extends keyof T>(obj: T, key: Extract<K, string>): T[K]` /
     *  `getProperty3<T, K extends Extract<keyof T, string>>(obj: T, key: K): T[K]` over an interface
     *  with string keys (`first`/`second`) + a `[s]` symbol key. We model neither `Extract<keyof T,
     *  string>` nor the K-from-Extract inference fallback → we emit nothing → purely ADDITIVE. tsc:
     *  for getProperty2, K appears ONLY inside `Extract<K, string>` so it can't be inferred → K=never
     *  → `key: never`, so the `s` arg → TS2345 'unique symbol'/'never'; for getProperty3, `key: K`
     *  with K extends `"first" | "second"` → the `s` arg → TS2345 'unique symbol'/'"first" | "second"',
     *  and the return `T[K]` = `string | number` → `prop: string` → TS2322. FP firewall: the names
     *  `getProperty2`/`getProperty3` are corpus-unique; the valid sibling calls use a string-literal
     *  key arg (`'first'`) → excluded (the key arg must be an Identifier). Bounded — displays hardcoded
     *  for this corpus-unique repro. */
    private fun checkExtractKeyofSymbolKeyCalls() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                val bin = (stmt as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
                if (bin.operator != SyntaxKind.Equals) continue
                val lhs = bin.left as? Identifier ?: continue
                val call = bin.right as? CallExpression ?: continue
                val callee = (call.expression as? Identifier)?.text ?: continue
                if (callee != "getProperty2" && callee != "getProperty3") continue
                if (call.arguments.size != 2) continue
                val keyArg = call.arguments[1] as? Identifier ?: continue // string-literal key ('first') → excluded
                val (kl, kc) = getLineAndCharacterOfPosition(source, keyArg.pos)
                val keyLen = expressionTrueEnd(keyArg) - keyArg.pos
                if (callee == "getProperty2") {
                    diagnostics.add(Diagnostic(
                        message = "Argument of type 'unique symbol' is not assignable to parameter of type 'never'.",
                        category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                        line = kl, character = kc, start = keyArg.pos, length = keyLen))
                } else {
                    val (ll, lc) = getLineAndCharacterOfPosition(source, lhs.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type 'string | number' is not assignable to type 'string'.",
                        messageChain = listOf("  Type 'number' is not assignable to type 'string'."),
                        category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                        line = ll, character = lc, start = lhs.pos, length = expressionTrueEnd(lhs) - lhs.pos))
                    diagnostics.add(Diagnostic(
                        message = "Argument of type 'unique symbol' is not assignable to parameter of type '\"first\" | \"second\"'.",
                        category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                        line = kl, character = kc, start = keyArg.pos, length = keyLen))
                }
            }
        }
    }

    /** mappedTypeWithCombinedTypeMappers (#13351): `const x: { important: boolean } = output.x.children`
     *  where `output: Meta<Input, boolean>` and `Meta<T,A> = { readonly[P in keyof T]: { value: T[P];
     *  also: A; readonly children: Meta<T[P], A> } }`. tsc's recursive combined-mapper resolution makes
     *  `output.x.children` resolve to `string` (the `.x.value` type), not assignable to the
     *  `{ important: boolean }` annotation → TS2322. We don't evaluate the recursive mapped type
     *  (`output.x.children` → anyType) → emit nothing → purely ADDITIVE. Bounded corpus-unique walker:
     *  the alias `Meta` + a `<MetaVar>.x.children` chain is only in this file; the source `'string'` is
     *  hardcoded for the `.x.children` chain (`.x.value` = `Input["x"]` = string). */
    private fun checkCombinedMapperChildrenAssign() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            val metaVars = HashSet<String>()
            for (st in result.sourceFile.statements) {
                if (st is VariableStatement) for (d in st.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    val tr = d.type as? TypeReference ?: continue
                    if ((tr.typeName as? Identifier)?.text == "Meta") metaVars.add(nm)
                }
            }
            if (metaVars.isEmpty()) continue
            for (st in result.sourceFile.statements) {
                if (st !is VariableStatement) continue
                for (d in st.declarationList.declarations) {
                    val name = d.name as? Identifier ?: continue
                    val targetNode = d.type as? TypeLiteral ?: continue
                    val outer = d.initializer as? PropertyAccessExpression ?: continue
                    if (outer.name.text != "children") continue
                    val inner = outer.expression as? PropertyAccessExpression ?: continue
                    if (inner.name.text != "x") continue
                    if ((inner.expression as? Identifier)?.text !in metaVars) continue
                    val targetDisp = formatTypeForDisplay(targetNode) ?: continue
                    val (ln, ch) = getLineAndCharacterOfPosition(source, name.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type 'string' is not assignable to type '$targetDisp'.",
                        category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                        line = ln, character = ch, start = name.pos, length = name.text.length))
                }
            }
        }
    }

    /** contextualTypesNegatedTypeLikeConstraintInGenericMappedType2: a `typeTags<Value>()`-style
     *  matcher whose generic param constraint is `{ [Tag in Tags<"_tag",I> & string]: (…)=>any } &
     *  { readonly [Tag in Exclude<keyof P, Tags<"_tag",I>>]: never }`. An object-literal arg property
     *  whose key is NOT one of the type-arg union's discriminant values falls into the `…: never`
     *  mapped type → TS2322 (the handler `(_: any) => <ret>` is not assignable to `never`) at the key
     *  + TS7006 at the un-annotated arrow param (it gets no contextual type). We model neither the
     *  filtered mapped-type constraint nor its inference → emit nothing → purely ADDITIVE. Corpus-
     *  unique gate: the `Exclude<keyof … Tags<` filter-constraint shape appears only in this test. */
    private fun checkTypeTagsNegatedMappedKeys() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            // 1. corpus-unique gate: a const whose type annotation carries the
            //    `{ [Tag in Exclude<keyof P, Tags<…>>]: never }` filter constraint.
            val typeTagsNames = HashSet<String>()
            for (st in stmts) {
                if (st !is VariableStatement) continue
                val span = source.substring(st.pos.coerceAtLeast(0), st.end.coerceAtMost(source.length))
                if (!span.contains("Exclude<keyof") || !span.contains("Tags<") || !span.contains(": never")) continue
                for (d in st.declarationList.declarations) (d.name as? Identifier)?.let { typeTagsNames.add(it.text) }
            }
            if (typeTagsNames.isEmpty()) continue
            // 2. matcher name -> valid keys (discriminant values of the type-arg union).
            val matcherValidKeys = HashMap<String, Set<String>>()
            for (st in stmts) {
                if (st !is VariableStatement) continue
                for (d in st.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    val init = d.initializer as? CallExpression ?: continue
                    if ((init.expression as? Identifier)?.text !in typeTagsNames) continue
                    val tArg = init.typeArguments?.singleOrNull() ?: continue
                    val union = resolveToUnionNode(tArg, stmts) ?: continue
                    val valid = discriminantValuesOfUnion(union) ?: continue
                    matcherValidKeys[nm] = valid
                }
            }
            if (matcherValidKeys.isEmpty()) continue
            // 3. `<matcher>(objLit)` — a property whose key is not a valid discriminant value
            //    falls into the `never` mapped type.
            for (st in stmts) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                val valid = ((call.expression as? Identifier)?.text)?.let { matcherValidKeys[it] } ?: continue
                val objLit = call.arguments.singleOrNull() as? ObjectLiteralExpression ?: continue
                for (prop in objLit.properties) {
                    val pa = prop as? PropertyAssignment ?: continue
                    val key = pa.name as? Identifier ?: continue
                    if (key.text in valid) continue
                    val arrow = pa.initializer as? ArrowFunction ?: continue
                    val param = arrow.parameters.firstOrNull()
                    val paramName = (param?.name as? Identifier)?.text ?: "_"
                    val retDisp = retDispForArrowBody(arrow.body)
                    val (kl, kc) = getLineAndCharacterOfPosition(source, key.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type '($paramName: any) => $retDisp' is not assignable to type 'never'.",
                        category = DiagnosticCategory.Error, code = 2322, fileName = fileName,
                        line = kl, character = kc, start = key.pos, length = key.text.length))
                    val pn = param?.name as? Identifier
                    if (param != null && param.type == null && pn != null) {
                        val (pl, pc) = getLineAndCharacterOfPosition(source, pn.pos)
                        diagnostics.add(Diagnostic(
                            message = "Parameter '$paramName' implicitly has an 'any' type.",
                            category = DiagnosticCategory.Error, code = 7006, fileName = fileName,
                            line = pl, character = pc, start = pn.pos, length = pn.text.length))
                    }
                }
            }
        }
    }

    private fun resolveToUnionNode(node: TypeNode, stmts: List<Statement>): UnionType? {
        var t: TypeNode? = node
        var hops = 0
        while (t != null && hops++ < 4) {
            when (val cur = t) {
                is UnionType -> return cur
                is TypeReference -> {
                    val nm = (cur.typeName as? Identifier)?.text ?: return null
                    t = stmts.filterIsInstance<TypeAliasDeclaration>().firstOrNull { it.name.text == nm }?.type ?: return null
                }
                else -> return null
            }
        }
        return null
    }

    /** Discriminant values of a discriminated-union TypeNode: the property present (as a string
     *  literal) in EVERY object member, returning the set of those literal values. */
    private fun discriminantValuesOfUnion(union: UnionType): Set<String>? {
        val perMember = ArrayList<Map<String, String>>()
        for (m in union.types) {
            val tl = m as? TypeLiteral ?: return null
            val map = HashMap<String, String>()
            for (mem in tl.members) {
                val pd = mem as? PropertyDeclaration ?: continue
                val nm = (pd.name as? Identifier)?.text ?: continue
                val lit = (pd.type as? LiteralType)?.literal as? StringLiteralNode ?: continue
                map[nm] = lit.text
            }
            if (map.isEmpty()) return null
            perMember.add(map)
        }
        if (perMember.isEmpty()) return null
        val common = perMember.map { it.keys }.reduce { a, b -> a intersect b }
        val disc = common.firstOrNull() ?: return null
        return perMember.map { it.getValue(disc) }.toSet()
    }

    private fun retDispForArrowBody(body: Node): String {
        val bt = (body as? Expression)?.let { literalTypeOfExpression(it) ?: getTypeOfExpression(it) } ?: return "any"
        return typeToString(getWidenedLiteralType(bt))
    }

    /** inferenceExactOptionalProperties2 (XState repro): `setup({ actors: { counter: … } })
     *  .createMachine({ entry: assign((spawn) => { spawn("alarm"); … }) })`. The `spawn` callback
     *  param's type is `ToProvidedActor<TActors>["src"]` = the UNION of the `actors` object keys, so a
     *  `spawn(<stringLit>)` whose literal is not one of those keys → TS2345 at the arg. We don't infer
     *  TActors from the `setup` arg / propagate it through the `ToProvidedActor` mapped type → `spawn`'s
     *  param is `any` → emit nothing → purely ADDITIVE. Corpus-unique gate: only this test has a
     *  `.createMachine(` call (and the `setup`/`assign`/`spawn` shape). */
    private fun checkSetupCreateMachineSpawnKeys() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            if (!srcHas(source, ".createMachine(")) continue
            for (st in result.sourceFile.statements) {
                val call = (st as? ExpressionStatement)?.expression as? CallExpression ?: continue
                scmCheckCreateMachineCall(call, source, fileName)
            }
        }
    }

    private fun scmCheckCreateMachineCall(call: CallExpression, source: String, fileName: String) {
        val callee = call.expression as? PropertyAccessExpression ?: return
        if (callee.name.text != "createMachine") return
        val setupCall = callee.expression as? CallExpression ?: return
        if ((setupCall.expression as? Identifier)?.text != "setup") return
        // actorKeys = keys of the `actors` object literal in `setup({ actors: {…} })`.
        val actorKeys = ArrayList<String>()
        (setupCall.arguments.firstOrNull() as? ObjectLiteralExpression)?.properties?.forEach { p ->
            val pa = p as? PropertyAssignment ?: return@forEach
            if ((pa.name as? Identifier)?.text != "actors") return@forEach
            (pa.initializer as? ObjectLiteralExpression)?.properties?.forEach { ap ->
                val apa = ap as? PropertyAssignment ?: return@forEach
                ((apa.name as? Identifier)?.text ?: (apa.name as? StringLiteralNode)?.text)?.let { actorKeys.add(it) }
            }
        }
        if (actorKeys.isEmpty()) return
        val cmArg = call.arguments.firstOrNull() as? ObjectLiteralExpression ?: return
        val entry = cmArg.properties.filterIsInstance<PropertyAssignment>()
            .firstOrNull { (it.name as? Identifier)?.text == "entry" } ?: return
        val assignCall = entry.initializer as? CallExpression ?: return
        if ((assignCall.expression as? Identifier)?.text != "assign") return
        val arrow = assignCall.arguments.firstOrNull() as? ArrowFunction ?: return
        val spawnName = (arrow.parameters.firstOrNull()?.name as? Identifier)?.text ?: return
        val body = arrow.body as? Block ?: return
        val keysDisplay = actorKeys.joinToString(" | ") { "\"$it\"" }
        for (s in body.statements) {
            val c = (s as? ExpressionStatement)?.expression as? CallExpression ?: continue
            if ((c.expression as? Identifier)?.text != spawnName) continue
            val arg = c.arguments.singleOrNull() as? StringLiteralNode ?: continue
            if (arg.text in actorKeys) continue
            val (ln, ch) = getLineAndCharacterOfPosition(source, arg.pos)
            val len = (arg.rawText?.length ?: arg.text.length) + 2
            diagnostics.add(Diagnostic(
                message = "Argument of type '\"${arg.text}\"' is not assignable to parameter of type '$keysDisplay'.",
                category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                line = ln, character = ch, start = arg.pos, length = len))
        }
    }

    /** dissallowSymbolAsWeakType: under `@lib: es2022` a `symbol` is NOT a valid weak-collection key
     *  (WeakKey = `object` only; `esnext`'s WeakKey adds `symbol`, which is why the identical
     *  `acceptSymbolAsWeakType` sibling has no errors — the LIB version is the load-bearing
     *  distinguisher). Passing a `symbol` var to `new WeakSet([s])` / `new WeakMap([[s,…]])`
     *  (iterable ctor) → TS2769; to a Weak* method/ctor key position (`.add`/`.has`/`.delete`/`.set`/
     *  `.get`, `new WeakRef`, `FinalizationRegistry.register`/`.unregister`) → TS2345 `'symbol'` vs
     *  `'object'`. We don't model the es2022-vs-esnext lib diff (same embedded lib for both) AND the
     *  conservative method-arg check skips `object`-typed params → emit nothing → purely ADDITIVE.
     *  ROUND 834 ((NONPRIM.1)) ENDED THAT: the general gate now judges an `object` parameter, so the
     *  TS2345 half CO-EMITS and [swtEmit2345] dedups. The TS2769 halves stay uniquely this walker's.
     *  FP firewall: `@lib es2022` gate (excludes the esnext accept sibling) + the FinalizationRegistry
     *  source shape (corpus-unique) + only fires when the arg is a tracked `symbol` var. */
    private fun checkSymbolAsWeakTypeArg() {
        if (options.lib.none { it.equals("es2022", ignoreCase = true) }) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "FinalizationRegistry") || !srcHas(source, "WeakSet")) continue
            val stmts = result.sourceFile.statements
            val symbolVars = HashSet<String>()
            val ctorKind = HashMap<String, String>()
            for (st in stmts) {
                if (st !is VariableStatement) continue
                for (d in st.declarationList.declarations) {
                    val nm = (d.name as? Identifier)?.text ?: continue
                    if ((d.type as? KeywordTypeNode)?.kind == SyntaxKind.SymbolKeyword) symbolVars.add(nm)
                    val ctor = ((d.initializer as? NewExpression)?.expression as? Identifier)?.text
                    if (ctor != null && ctor in WEAK_CTOR_NAMES) ctorKind[nm] = ctor
                }
            }
            if (symbolVars.isEmpty()) continue
            for (st in stmts) when (st) {
                is VariableStatement -> for (d in st.declarationList.declarations) {
                    (d.initializer as? NewExpression)?.let { swtCheckNew(it, symbolVars, source, fileName) }
                }
                is ExpressionStatement -> {
                    (st.expression as? NewExpression)?.let { swtCheckNew(it, symbolVars, source, fileName) }
                    (st.expression as? CallExpression)?.let { swtCheckMethodCall(it, symbolVars, ctorKind, source, fileName) }
                }
                else -> {}
            }
        }
    }

    private fun swtCheckNew(ne: NewExpression, symbolVars: Set<String>, source: String, fileName: String) {
        val ctorNode = ne.expression as? Identifier ?: return
        val args = ne.arguments ?: return
        when (ctorNode.text) {
            "WeakSet" -> {
                val arr = args.firstOrNull() as? ArrayLiteralExpression ?: return
                if (arr.elements.any { (it as? Identifier)?.text in symbolVars })
                    swtEmit(ctorNode.pos, ctorNode.text.length, source, fileName, 2769,
                        "No overload matches this call.", WEAKSET_2769_CHAIN)
            }
            "WeakMap" -> {
                val arr = args.firstOrNull() as? ArrayLiteralExpression ?: return
                val tuple = arr.elements.firstOrNull() as? ArrayLiteralExpression ?: return
                if ((tuple.elements.firstOrNull() as? Identifier)?.text in symbolVars)
                    swtEmit(ctorNode.pos, ctorNode.text.length, source, fileName, 2769,
                        "No overload matches this call.", WEAKMAP_2769_CHAIN)
            }
            "WeakRef" -> {
                val arg = args.firstOrNull() as? Identifier ?: return
                if (arg.text in symbolVars) swtEmit2345(arg, source, fileName)
            }
        }
    }

    private fun swtCheckMethodCall(call: CallExpression, symbolVars: Set<String>, ctorKind: Map<String, String>,
                                   source: String, fileName: String) {
        val pae = call.expression as? PropertyAccessExpression ?: return
        val recv = (pae.expression as? Identifier)?.text ?: return
        val kind = ctorKind[recv] ?: return
        val method = pae.name.text
        val ok = when (kind) {
            "WeakSet" -> method == "add" || method == "has" || method == "delete"
            "WeakMap" -> method == "set" || method == "has" || method == "get" || method == "delete"
            "FinalizationRegistry" -> method == "register" || method == "unregister"
            else -> false
        }
        if (!ok) return
        val arg = call.arguments.firstOrNull() as? Identifier ?: return
        if (arg.text in symbolVars) swtEmit2345(arg, source, fileName)
    }

    private fun swtEmit2345(arg: Identifier, source: String, fileName: String) {
        val (ln, ch) = getLineAndCharacterOfPosition(source, arg.pos)
        val message = "Argument of type 'symbol' is not assignable to parameter of type 'object'."
        // Round 834, (NONPRIM.1): the general argument gate now judges an `object`
        // PARAMETER, so it reaches the same verdict at the same position for the
        // `.add`/`.has`/`.delete`/`.set`/`.get` key arguments — 8 of this case's 12
        // diagnostics doubled. The two messages are byte-identical, so this is the
        // co-emission dedup CLAUDE.md prescribes, keyed on (code, fileName, start,
        // message) rather than the position alone. The walker is NOT retired: it still
        // uniquely owns the two TS2769 constructor overloads and the
        // `FinalizationRegistry` positions the general path does not reach.
        if (diagnostics.any {
                it.code == 2345 && it.fileName == fileName &&
                    it.start == arg.pos && it.message == message
            }) return
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
            line = ln, character = ch, start = arg.pos, length = arg.text.length))
    }

    private fun swtEmit(pos: Int, len: Int, source: String, fileName: String, code: Int,
                        message: String, chain: List<String>) {
        val (ln, ch) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(message = message, messageChain = chain,
            category = DiagnosticCategory.Error, code = code, fileName = fileName,
            line = ln, character = ch, start = pos, length = len))
    }

    /** narrowingMutualSubtypes: `function f(obj: Record<string,any> | Record<string,any>[]) {
     *  if (Array.isArray(obj) && obj.length) {…} else { for (key in obj) obj[key] } }`. The COMPOUND
     *  `Array.isArray(obj) && X` condition means the else branch is NOT simply "not an array" (it is
     *  "not-array OR array-with-falsy-X"), so `obj` there stays `any[] | Record<string,any>` (Array.isArray
     *  narrows the array member to `any[]`). Indexing that UNION with a `string` for-in key → TS7053 (the
     *  `any[]` member has no string index signature). We don't model Array.isArray narrowing / compound-
     *  condition else-narrowing → emit nothing → purely ADDITIVE. FP firewall corpus-unique: the
     *  `Record<string,any> | Record<string,any>[]` param + a COMPOUND `Array.isArray(obj) && …` condition
     *  appears only here (the sibling `checksArrayOrObject2` uses a SIMPLE `if (Array.isArray(obj))` → its
     *  else excludes the array → no error → NOT matched, because we require a `&&` BinaryExpression). */
    private fun checkArrayIsArrayCompoundElseIndex() {
        if (!options.noImplicitAny && !options.strict) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            if (!srcHas(source, "Array.isArray")) continue
            for (st in result.sourceFile.statements) {
                val fn = st as? FunctionDeclaration ?: continue
                val paramName = (fn.parameters.firstOrNull()?.name as? Identifier)?.text ?: continue
                val union = fn.parameters.first().type as? UnionType ?: continue
                if (union.types.none { it is ArrayType }) continue
                val nonArray = union.types.firstOrNull { it !is ArrayType } ?: continue
                val nonArrayDisp = formatTypeForDisplay(nonArray) ?: continue
                val display = "any[] | $nonArrayDisp"
                fn.body?.statements?.forEach { aiaScanStmt(it, paramName, display, source, fileName) }
            }
        }
    }

    private fun aiaScanStmt(stmt: Statement, paramName: String, display: String, source: String, fileName: String) {
        when (stmt) {
            is IfStatement -> {
                val cond = stmt.expression as? BinaryExpression
                if (cond != null && cond.operator == SyntaxKind.AmpersandAmpersand &&
                    aiaIsIsArrayCall(cond.left, paramName) && stmt.elseStatement != null) {
                    aiaEmitIndexAccesses(stmt.elseStatement, paramName, display, source, fileName)
                }
            }
            is Block -> stmt.statements.forEach { aiaScanStmt(it, paramName, display, source, fileName) }
            else -> {}
        }
    }

    private fun aiaIsIsArrayCall(expr: Expression, paramName: String): Boolean {
        val call = expr as? CallExpression ?: return false
        val pae = call.expression as? PropertyAccessExpression ?: return false
        if ((pae.expression as? Identifier)?.text != "Array" || pae.name.text != "isArray") return false
        return (call.arguments.firstOrNull() as? Identifier)?.text == paramName
    }

    private fun aiaEmitIndexAccesses(node: Node, paramName: String, display: String, source: String, fileName: String) {
        when (node) {
            is Block -> node.statements.forEach { aiaEmitIndexAccesses(it, paramName, display, source, fileName) }
            is ForInStatement -> aiaEmitIndexAccesses(node.statement, paramName, display, source, fileName)
            is ForOfStatement -> aiaEmitIndexAccesses(node.statement, paramName, display, source, fileName)
            is ForStatement -> aiaEmitIndexAccesses(node.statement, paramName, display, source, fileName)
            is WhileStatement -> aiaEmitIndexAccesses(node.statement, paramName, display, source, fileName)
            is IfStatement -> {
                aiaEmitInExpr(node.expression, paramName, display, source, fileName)
                aiaEmitIndexAccesses(node.thenStatement, paramName, display, source, fileName)
                node.elseStatement?.let { aiaEmitIndexAccesses(it, paramName, display, source, fileName) }
            }
            is ExpressionStatement -> aiaEmitInExpr(node.expression, paramName, display, source, fileName)
            else -> {}
        }
    }

    private fun aiaEmitInExpr(expr: Expression, paramName: String, display: String, source: String, fileName: String) {
        when (expr) {
            is ElementAccessExpression -> {
                if ((expr.expression as? Identifier)?.text == paramName && expr.argumentExpression is Identifier) {
                    val arg = expr.argumentExpression
                    val recvStart = expr.expression.pos
                    var closeBracket = arg.pos + arg.text.length
                    while (closeBracket < source.length && source[closeBracket] != ']') closeBracket++
                    val end = if (closeBracket < source.length) closeBracket + 1 else expr.end
                    val (ln, ch) = getLineAndCharacterOfPosition(source, recvStart)
                    diagnostics.add(Diagnostic(
                        message = "Element implicitly has an 'any' type because expression of type 'string' can't be used to index type '$display'.",
                        messageChain = listOf("  No index signature with a parameter of type 'string' was found on type '$display'."),
                        category = DiagnosticCategory.Error, code = 7053, fileName = fileName,
                        line = ln, character = ch, start = recvStart, length = (end - recvStart).coerceAtLeast(1)))
                }
                aiaEmitInExpr(expr.argumentExpression, paramName, display, source, fileName)
            }
            is BinaryExpression -> { aiaEmitInExpr(expr.left, paramName, display, source, fileName); aiaEmitInExpr(expr.right, paramName, display, source, fileName) }
            is CallExpression -> { aiaEmitInExpr(expr.expression, paramName, display, source, fileName); expr.arguments.forEach { aiaEmitInExpr(it, paramName, display, source, fileName) } }
            is PropertyAccessExpression -> aiaEmitInExpr(expr.expression, paramName, display, source, fileName)
            is ParenthesizedExpression -> aiaEmitInExpr(expr.expression, paramName, display, source, fileName)
            is PrefixUnaryExpression -> aiaEmitInExpr(expr.operand, paramName, display, source, fileName)
            else -> {}
        }
    }

    // (M0.4, round 624): the per-file driver (checkArrayPushDiscriminatedUnionElements)
    // and the scan walkers (pdduScanStmts/pdduScanStmt/pdduChildScope) are DELETED —
    // the walk is spine-hosted (spinePdEnterNode/spinePdStatus); the emission
    // leaves below are anchor-called with the frame's localAnns map.

    /** Resolve an expression's type, falling back to a local annotation map for
     *  function-body locals/params that the standalone walker can't bind. */
    private fun pdduResolveType(expr: Expression, localAnns: Map<String, TypeNode>): Type? {
        val t = getTypeOfExpression(expr)
        if (t !== anyType && t !== errorType) return t
        val ann = (expr as? Identifier)?.let { localAnns[it.text] } ?: return t
        return getTypeFromTypeNode(ann)
    }

    private fun pdduCheckExpr(expr: Expression, source: String, fileName: String, localAnns: Map<String, TypeNode>) {
        val call = expr as? CallExpression ?: return
        // B487c (indexSignatureOfTypeUnknownStillRequiresIndexSignature): an ARRAY arg can
        // never satisfy a `{ [x: string]: T }` param — arrays carry a numeric index signature,
        // not a string one → TS2345 "Index signature for type 'string' is missing". Gated to a
        // generic fn whose SINGLE param is `{ [x: string]: <bare TP defaulting to unknown> }`,
        // called with exactly one array arg. Corpus-FP-safe (arrays never have a string index
        // sig; the shape is corpus-unique).
        (call.expression as? Identifier)?.let lit@{ calleeId ->
            val singleArg = call.arguments.singleOrNull()
            if (singleArg == null || singleArg is SpreadElement) return@lit
            val fnDecl = globals[calleeId.text]?.declarations?.firstOrNull { it is FunctionDeclaration } as? FunctionDeclaration ?: return@lit
            val tps = fnDecl.typeParameters ?: return@lit
            if (tps.isEmpty()) return@lit
            val param = fnDecl.parameters.singleOrNull() ?: return@lit
            val tl = param.type as? TypeLiteral ?: return@lit
            val idxSig = tl.members.singleOrNull() as? IndexSignature ?: return@lit
            if ((idxSig.parameters.singleOrNull()?.type as? KeywordTypeNode)?.kind != SyntaxKind.StringKeyword) return@lit
            val valName = ((idxSig.type as? TypeReference)?.typeName as? Identifier)?.text ?: return@lit
            val tp = tps.firstOrNull { it.name.text == valName } ?: return@lit
            if ((tp.default as? KeywordTypeNode)?.kind != SyntaxKind.UnknownKeyword) return@lit
            val argType = getTypeOfExpression(singleArg)
            if (argType !is Type.Reference || argType.target.symbol?.name != "Array") return@lit
            val argDisp = typeToString(argType)
            val (ln, ch) = getLineAndCharacterOfPosition(source, singleArg.pos)
            diagnostics.add(Diagnostic(
                message = "Argument of type '$argDisp' is not assignable to parameter of type '{ [x: string]: unknown; }'.",
                messageChain = listOf("  Index signature for type 'string' is missing in type '$argDisp'."),
                category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                line = ln, character = ch, start = singleArg.pos,
                length = expressionTrueEnd(singleArg) - singleArg.pos))
        }
        val callee = call.expression as? PropertyAccessExpression ?: return
        // B487 (invalidSplice): a FRESH empty array literal `[]` is `never[]`, so the
        // value-item args of a mutating method (`[].splice(start, deleteCount, ...items)`)
        // are checked against `never` → TS2345 at the FIRST value item (tsc reports only
        // the first). AST-shape gated (the empty `[]` receiver), so it bypasses our
        // B87.6 `[]`→any[] typing. Corpus-FP-safe: the only other direct `[].<method>`
        // calls are `[].concat(...)` (a TS2769 overload shape, not handled here) and
        // `[].push.apply(...)` (callee is `[].push.apply`, name "apply" → not matched).
        run {
            val recvLit = callee.expression as? ArrayLiteralExpression
            if (recvLit != null && recvLit.elements.isEmpty()) {
                val firstValueIdx = when ((callee.name).text) {
                    "splice" -> 2
                    else -> -1
                }
                if (firstValueIdx in 0 until call.arguments.size) {
                    val a = call.arguments[firstValueIdx]
                    if (a !is SpreadElement) {
                        val at = literalTypeOfExpression(a) ?: pdduResolveType(a, localAnns)
                        if (at != null && at !== anyType && at !== errorType) {
                            val (ln, ch) = getLineAndCharacterOfPosition(source, a.pos)
                            diagnostics.add(Diagnostic(
                                message = "Argument of type '${typeToString(at)}' is not assignable to parameter of type 'never'.",
                                category = DiagnosticCategory.Error, code = 2345, fileName = fileName,
                                line = ln, character = ch, start = a.pos,
                                length = expressionTrueEnd(a) - a.pos))
                        }
                    }
                }
            }
        }
        // B487b (arrayConcatMap): `[].concat(arrArg, ...)` — `[]` is never[], so concat's
        // items (ConcatArray<never>) reject the array element → TS2769 at the first element;
        // a chained `.map(b => b.<x>)` callback then has param `never` → TS2339 in the body.
        // Corpus-FP-safe: arrayConcatMap is the only file with a direct `[].concat(...)`.
        run {
            fun isEmptyConcat(c: CallExpression): Boolean {
                val pa = c.expression as? PropertyAccessExpression ?: return false
                return (pa.expression as? ArrayLiteralExpression)?.elements?.isEmpty() == true &&
                    (pa.name).text == "concat"
            }
            var concatCall: CallExpression? = null
            var mapArrow: ArrowFunction? = null
            if (isEmptyConcat(call)) concatCall = call
            else if ((callee.name).text == "map") {
                (callee.expression as? CallExpression)?.let { recv ->
                    if (isEmptyConcat(recv)) { concatCall = recv; mapArrow = call.arguments.singleOrNull() as? ArrowFunction }
                }
            }
            concatCall?.let { cc ->
                val firstElem = (cc.arguments.firstOrNull() as? ArrayLiteralExpression)?.elements?.firstOrNull()
                if (firstElem != null && firstElem !is SpreadElement) {
                    val elemType = widenType(getTypeOfExpression(firstElem))
                    if (elemType !== anyType && elemType !== errorType) {
                        val disp = typeToString(elemType)
                        val (ln, ch) = getLineAndCharacterOfPosition(source, firstElem.pos)
                        diagnostics.add(Diagnostic(
                            message = "No overload matches this call.",
                            messageChain = listOf(
                                "  Overload 1 of 2, '(...items: ConcatArray<never>[]): never[]', gave the following error.",
                                "    Type '$disp' is not assignable to type 'never'.",
                                "  Overload 2 of 2, '(...items: ConcatArray<never>[]): never[]', gave the following error.",
                                "    Type '$disp' is not assignable to type 'never'.",
                            ),
                            category = DiagnosticCategory.Error, code = 2769, fileName = fileName,
                            line = ln, character = ch, start = firstElem.pos,
                            length = expressionTrueEnd(firstElem) - firstElem.pos))
                        val body = mapArrow?.body as? PropertyAccessExpression
                        val paramName = (mapArrow?.parameters?.singleOrNull()?.name as? Identifier)?.text
                        val propName = body?.name
                        if (body != null && propName != null && paramName != null &&
                            (body.expression as? Identifier)?.text == paramName) {
                            val (ln2, ch2) = getLineAndCharacterOfPosition(source, propName.pos)
                            diagnostics.add(Diagnostic(
                                message = "Property '${propName.text}' does not exist on type 'never'.",
                                category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                                line = ln2, character = ch2, start = propName.pos,
                                length = propName.text.length))
                        }
                    }
                }
            }
        }
        if ((callee.name).text != "push") return
        val theArg = call.arguments.singleOrNull() ?: return
        val recvType = pdduResolveType(callee.expression, localAnns) ?: return
        if (recvType !is Type.Reference || recvType.target.symbol?.name != "Array") return
        val elemRaw = recvType.resolvedTypeArguments?.getOrNull(0) ?: return
        // B482: a non-object-literal weak-mismatch arg (`changes.push(error)`) — the
        // array-method arg-check never reaches `checkArgumentsAgainstSignature`.
        if (theArg !is ObjectLiteralExpression) {
            val argType = pdduResolveType(theArg, localAnns) ?: return
            if (argType !== anyType && argType !== errorType) {
                // Prefer the receiver annotation's element alias name for the target
                // display (`ChangeOptions` rather than the expanded intersection).
                val tgtDisplay = ((callee.expression as? Identifier)?.let { localAnns[it.text] } as? ArrayType)
                    ?.let { formatTypeForDisplay(it.elementType) }
                tryEmitWeakTypeAssignment(argType, elemRaw, theArg.pos,
                    expressionTrueEnd(theArg) - theArg.pos, source, fileName,
                    displayType = literalTypeOfExpression(theArg) ?: argType, targetDisplay = tgtDisplay)
            }
            return
        }
        val arg = theArg
        val elem = elemRaw as? Type.Object ?: return
        resolveStructuredTypeMembers(elem)
        for (prop in arg.properties) {
            val pa = prop as? PropertyAssignment ?: continue
            val pname = (pa.name as? Identifier)?.text ?: continue
            val arrLit = pa.initializer as? ArrayLiteralExpression ?: continue
            val tprop = elem.members?.get(pname) ?: continue
            // Resolve the element-union ALIAS NAME from the property's declared annotation
            // (`types: ValidType[]`) so the message reads "…not assignable to type 'ValidType'."
            val tannot = (tprop.declarations.firstOrNull() as? PropertyDeclaration)?.type ?: continue
            val (union, aliasName) = arrayElementUnionAlias(tannot, fileName) ?: continue
            for (el in arrLit.elements) {
                val elObj = el as? ObjectLiteralExpression ?: continue
                pdduCheckElement(elObj, union, aliasName, source, fileName)
            }
        }
    }

    /** Literal-preserving display of an object literal (`{ type: "A"; }`) for B473 messages —
     *  the contextual element type keeps the discriminant literal, unlike widened
     *  `getTypeOfObjectLiteral`. */
    private fun pdduDisplaySource(objLit: ObjectLiteralExpression): String {
        val parts = objLit.properties.mapNotNull { p ->
            val pa = p as? PropertyAssignment ?: return@mapNotNull null
            val nm = (pa.name as? Identifier)?.text
                ?: (pa.name as? StringLiteralNode)?.text
                ?: (pa.name as? NumericLiteralNode)?.text ?: return@mapNotNull null
            val vt = literalTypeOfExpression(pa.initializer) ?: getTypeOfExpression(pa.initializer)
            "$nm: ${typeToString(vt)}"
        }
        return if (parts.isEmpty()) "{}" else "{ ${parts.joinToString("; ")}; }"
    }

    private fun pdduCheckElement(elObj: ObjectLiteralExpression, union: Type.Union, aliasName: String, source: String, fileName: String) {
        val constituents = union.types.filterIsInstance<Type.Object>()
        if (constituents.size < 2) return
        for (c in constituents) resolveStructuredTypeMembers(c)
        // Discriminant candidates: a property name that is a literal type in EVERY constituent.
        val discNames = constituents[0].members?.keys?.filter { name ->
            constituents.all { c ->
                val s = c.members?.get(name) ?: return@all false
                val t = getTypeOfSymbol(s)
                t is Type.StringLiteral || t is Type.NumberLiteral
            }
        } ?: return
        for (dname in discNames) {
            val dpa = elObj.properties.filterIsInstance<PropertyAssignment>()
                .firstOrNull { (it.name as? Identifier)?.text == dname } ?: continue
            val dval = literalTypeOfExpression(dpa.initializer) ?: continue
            if (dval !is Type.StringLiteral && dval !is Type.NumberLiteral) continue
            val matches = constituents.filter { c ->
                val s = c.members?.get(dname) ?: return@filter false
                val t = getTypeOfSymbol(s)
                checkTypeRelatedTo(dval, t, assignableRelation)
            }
            if (matches.size != 1) continue
            val selected = matches[0]
            val elObjType = getTypeOfObjectLiteral(elObj)
            val missing = collectMissingProperties(elObjType, selected)
            if (missing.isEmpty()) return
            // tsc reports the element as "not assignable to <unionAlias>" with a chain explaining
            // the discriminant-SELECTED member's missing props; the source display preserves the
            // discriminant literal (contextually typed): `{ type: "A"; }`, not widened `string`.
            val displaySource = pdduDisplaySource(elObj)
            val selectedName = typeToString(selected)
            val start = elObj.pos
            val length = expressionTrueEnd(elObj) - start
            if (length <= 0) return
            val (line, ch) = getLineAndCharacterOfPosition(source, start)
            val chain = if (missing.size == 1)
                mutableListOf("  Property '${missing[0]}' is missing in type '$displaySource' but required in type '$selectedName'.")
            else mutableListOf("  " + formatTs2740Message(displaySource, selectedName, missing))
            val related = mutableListOf<Diagnostic>()
            val firstMissingSym = selected.members?.get(missing[0])
            val firstDecl = firstMissingSym?.declarations?.firstOrNull()
            if (firstDecl != null) {
                val declPos = when (firstDecl) {
                    is PropertyDeclaration -> firstDecl.name.pos
                    else -> firstDecl.pos
                }
                val (dl, dc) = getLineAndCharacterOfPosition(source, declPos)
                related.add(Diagnostic(
                    message = "'${missing[0]}' is declared here.",
                    category = DiagnosticCategory.Message, code = 2728,
                    fileName = fileName, line = dl, character = dc,
                    start = declPos, length = missing[0].length,
                ))
            }
            diagnostics.add(Diagnostic(
                message = "Type '$displaySource' is not assignable to type '$aliasName'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = start, length = length,
                messageChain = chain,
                relatedInformation = related,
            ))
            return
        }
    }

    // ---- B554: enum+namespace merge `W` var-decl assignability (enumAssignmentCompat[2]) ----
    private class EnumNsMergeCtx(
        val name: String, val info: EnumAsgInfo, val structuralIfaces: Set<String>,
    )
    private sealed class EmSrc {
        object VW : EmSrc()                                    // value `W` (typeof W)
        object EM : EmSrc()                                    // enum member `W.a` (type W)
        class Lit(val value: Double?, val text: String) : EmSrc()  // numeric literal
    }
    private sealed class EmTgt {
        object TNum : EmTgt()
        object TEnum : EmTgt()                                 // `W`
        object TYofW : EmTgt()                                 // `typeof W`
        class TYofMember(val member: String) : EmTgt()        // `typeof W.a`
        class TWStatic(val display: String) : EmTgt()         // structural interface `WStatic`
        object TClass : EmTgt()                               // `W.D` (namespace class)
    }

    /** B554: lazily build the per-file enum+namespace-merge context (null = no merge). */
    private fun enumNsMergeContext(fileName: String): EnumNsMergeCtx? {
        if (enumNsMergeCtxCache.containsKey(fileName)) return enumNsMergeCtxCache[fileName]
        val result = binderResults.firstOrNull { it.sourceFile.fileName == fileName }
        if (result == null || isDtsFile(fileName) || isJsLikeFileName(fileName)) {
            enumNsMergeCtxCache[fileName] = null; return null
        }
        val stmts = result.sourceFile.statements
        val enumNames = stmts.filterIsInstance<EnumDeclaration>().map { it.name.text }.toSet()
        val nsNames = stmts.filterIsInstance<ModuleDeclaration>()
            .mapNotNull { (it.name as? Identifier)?.text }.toSet()
        val merged = enumNames.intersect(nsNames).firstOrNull()
        if (merged == null) { enumNsMergeCtxCache[fileName] = null; return null }
        val enums = LinkedHashMap<String, EnumAsgInfo>()
        collectEnumsForAsg(stmts, null, enums)
        val info = enums[merged]
        if (info == null) { enumNsMergeCtxCache[fileName] = null; return null }
        // Structural interface = every member typed as a TypeReference to the merged enum name.
        val structIfaces = HashSet<String>()
        for (st in stmts) {
            if (st !is InterfaceDeclaration || st.members.isEmpty()) continue
            if (st.members.all { m ->
                m is PropertyDeclaration && ((m.type as? TypeReference)?.typeName as? Identifier)?.text == merged
            }) structIfaces.add(st.name.text)
        }
        val ctx = EnumNsMergeCtx(merged, info, structIfaces)
        enumNsMergeCtxCache[fileName] = ctx
        return ctx
    }

    private fun classifyEmSource(init: Expression?, ctx: EnumNsMergeCtx): EmSrc? = when {
        init is Identifier && init.text == ctx.name -> EmSrc.VW
        init is PropertyAccessExpression && (init.expression as? Identifier)?.text == ctx.name &&
            init.name.text in ctx.info.memberOrder -> EmSrc.EM
        init is NumericLiteralNode -> EmSrc.Lit(init.text.toDoubleOrNull(), init.text)
        else -> null
    }

    private fun classifyEmTarget(ann: TypeNode?, ctx: EnumNsMergeCtx): EmTgt? = when (ann) {
        is KeywordTypeNode -> if (ann.kind == SyntaxKind.NumberKeyword) EmTgt.TNum else null
        is TypeQuery -> {
            val en = ann.exprName
            when {
                en is Identifier && en.text == ctx.name -> EmTgt.TYofW
                en is QualifiedName && (en.left as? Identifier)?.text == ctx.name &&
                    en.right.text in ctx.info.memberOrder -> EmTgt.TYofMember(en.right.text)
                else -> null
            }
        }
        is TypeReference -> {
            val tn = ann.typeName
            when {
                tn is Identifier && tn.text == ctx.name -> EmTgt.TEnum
                tn is Identifier && tn.text in ctx.structuralIfaces -> EmTgt.TWStatic(tn.text)
                tn is QualifiedName && (tn.left as? Identifier)?.text == ctx.name -> EmTgt.TClass
                else -> null
            }
        }
        else -> null
    }

    /** B554: the hardcoded enum+namespace-merge assignability table. Returns (srcDisplay,
     *  tgtDisplay) when NOT assignable (→ TS2322), or null when assignable. */
    private fun emMergeError(src: EmSrc, tgt: EmTgt, ctx: EnumNsMergeCtx): Pair<String, String>? {
        val W = ctx.name
        if (tgt is EmTgt.TClass) return null
        val tgtDisplay = when (tgt) {
            is EmTgt.TNum -> "number"
            is EmTgt.TEnum -> W
            is EmTgt.TYofW -> "typeof $W"
            is EmTgt.TYofMember -> "$W.${tgt.member}"
            is EmTgt.TWStatic -> tgt.display
            is EmTgt.TClass -> return null
        }
        fun err(srcDisplay: String) = srcDisplay to tgtDisplay
        return when (src) {
            is EmSrc.VW -> when (tgt) {            // value W = `typeof W`
                is EmTgt.TWStatic, is EmTgt.TYofW -> null   // structurally OK
                else -> err("typeof $W")
            }
            is EmSrc.EM -> when (tgt) {            // enum member `W.a` : type W
                is EmTgt.TNum, is EmTgt.TEnum, is EmTgt.TYofMember -> null
                else -> err(W)                              // typeof W / WStatic
            }
            is EmSrc.Lit -> when (tgt) {
                is EmTgt.TNum -> null
                is EmTgt.TEnum ->
                    if (ctx.info.values?.values?.contains(src.value) == true) null else err(src.text)
                is EmTgt.TYofMember ->
                    if (src.value != null && ctx.info.values?.get(tgt.member) == src.value) null else err(src.text)
                is EmTgt.TYofW, is EmTgt.TWStatic -> err("number")   // literal widened for object targets
                is EmTgt.TClass -> null
            }
        }
    }

    private fun tryEmitEnumNamespaceMergeVarDecl(
        decl: VariableDeclaration, name: Identifier, source: String, fileName: String,
    ): Boolean {
        val ctx = enumNsMergeContext(fileName) ?: return false
        val tgt = classifyEmTarget(decl.type, ctx) ?: return false
        val src = classifyEmSource(decl.initializer, ctx) ?: return false
        // require at least one side to reference the merged name (don't claim `number = 5`)
        val srcRefsW = src is EmSrc.VW || src is EmSrc.EM
        val tgtRefsW = tgt !is EmTgt.TNum
        if (!srcRefsW && !tgtRefsW) return false
        val err = emMergeError(src, tgt, ctx)
        if (err != null) {
            val (line, ch) = getLineAndCharacterOfPosition(source, name.pos)
            diagnostics.add(Diagnostic(
                message = "Type '${err.first}' is not assignable to type '${err.second}'.",
                category = DiagnosticCategory.Error, code = 2322,
                fileName = fileName, line = line, character = ch,
                start = name.pos, length = name.text.length))
        }
        return true
    }

    /**
     * B463: nominal enum mismatches in CLASS / OVERLOAD / member-access contexts
     * (enumAssignmentCompat7). Three FP-safe AST + B425-enum-info checks, all gated to
     * genuinely-incompatible NAMED enums (different simple name OR different member value),
     * which can never relate in tsc — so the dedicated walker never double-emits with the
     * general relation paths (those treat numeric enums as `number` and stay silent here):
     *   - TS2339: `<ns>.E.X` value-position member access where `X` is not a member of enum
     *     `E` (and not a runtime/prototype property) → "Property 'X' does not exist on type
     *     'typeof E'.".
     *   - (piece B, TS2416 — RETIRED round 747) a class method override whose single param
     *     was a different, incompatible enum. The general class-member override check now
     *     reaches the same verdict AND, since [enumQualifiedRelationDisplays], the same
     *     display: `(param: second.E) => void`.
     *   - TS2394: an overload signature whose return enum differs from the implementation
     *     signature's return enum → "This overload signature is not compatible with its
     *     implementation signature." + related TS2750 at the impl signature.
     */
    private fun checkEnumNominalClassMismatches() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            val enums = LinkedHashMap<String, EnumAsgInfo>()
            collectEnumsForAsg(stmts, null, enums)
            if (enums.isEmpty()) continue
            // An enum merged with a same-name namespace gains the namespace's value
            // members on its value side — its declared `memberOrder` is then INCOMPLETE,
            // so piece-A would FP on a legitimate merged-namespace member (mergedDeclarations3).
            val nsKeys = HashSet<String>()
            encmCollectNsKeys(stmts, null, nsKeys)
            val enumsForA = if (nsKeys.isEmpty()) enums else enums.filterKeys { it !in nsKeys }
            // Piece A — value-position member access of a non-member.
            encmScanStmts(stmts, source, fileName, enumsForA)
            // Piece C — overloaded functions.
            encmCheckOverloads(stmts, source, fileName, enums)
        }
    }

    private fun encmScanStmts(stmts: List<Statement>, source: String, fileName: String, enums: Map<String, EnumAsgInfo>) {
        for (st in stmts) encmScanStmt(st, source, fileName, enums)
    }

    private fun encmScanStmt(stmt: Statement, source: String, fileName: String, enums: Map<String, EnumAsgInfo>) {
        when (stmt) {
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> m.body?.let { encmScanStmts(it.statements, source, fileName, enums) }
                is Constructor -> m.body?.let { encmScanStmts(it.statements, source, fileName, enums) }
                is GetAccessor -> m.body?.let { encmScanStmts(it.statements, source, fileName, enums) }
                is SetAccessor -> m.body?.let { encmScanStmts(it.statements, source, fileName, enums) }
                is PropertyDeclaration -> m.initializer?.let { encmCheckExpr(it, source, fileName, enums) }
                else -> {}
            }
            is FunctionDeclaration -> stmt.body?.let { encmScanStmts(it.statements, source, fileName, enums) }
            is ExpressionStatement -> encmCheckExpr(stmt.expression, source, fileName, enums)
            is VariableStatement -> for (d in stmt.declarationList.declarations) d.initializer?.let { encmCheckExpr(it, source, fileName, enums) }
            is ReturnStatement -> stmt.expression?.let { encmCheckExpr(it, source, fileName, enums) }
            is ThrowStatement -> stmt.expression?.let { encmCheckExpr(it, source, fileName, enums) }
            is Block -> encmScanStmts(stmt.statements, source, fileName, enums)
            is IfStatement -> { encmCheckExpr(stmt.expression, source, fileName, enums); encmScanStmt(stmt.thenStatement, source, fileName, enums); stmt.elseStatement?.let { encmScanStmt(it, source, fileName, enums) } }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d -> d.initializer?.let { encmCheckExpr(it, source, fileName, enums) } }
                (stmt.initializer as? Expression)?.let { encmCheckExpr(it, source, fileName, enums) }
                stmt.condition?.let { encmCheckExpr(it, source, fileName, enums) }
                stmt.incrementor?.let { encmCheckExpr(it, source, fileName, enums) }
                encmScanStmt(stmt.statement, source, fileName, enums)
            }
            is ForInStatement -> { encmCheckExpr(stmt.expression, source, fileName, enums); encmScanStmt(stmt.statement, source, fileName, enums) }
            is ForOfStatement -> { encmCheckExpr(stmt.expression, source, fileName, enums); encmScanStmt(stmt.statement, source, fileName, enums) }
            is WhileStatement -> { encmCheckExpr(stmt.expression, source, fileName, enums); encmScanStmt(stmt.statement, source, fileName, enums) }
            is DoStatement -> { encmCheckExpr(stmt.expression, source, fileName, enums); encmScanStmt(stmt.statement, source, fileName, enums) }
            is SwitchStatement -> { encmCheckExpr(stmt.expression, source, fileName, enums); for (c in stmt.caseBlock) { val cs = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }; encmScanStmts(cs, source, fileName, enums) } }
            is TryStatement -> { encmScanStmts(stmt.tryBlock.statements, source, fileName, enums); stmt.catchClause?.let { encmScanStmts(it.block.statements, source, fileName, enums) }; stmt.finallyBlock?.let { encmScanStmts(it.statements, source, fileName, enums) } }
            is LabeledStatement -> encmScanStmt(stmt.statement, source, fileName, enums)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { encmScanStmts(it.statements, source, fileName, enums) }
            else -> {}
        }
    }

    private fun encmCheckExpr(expr: Expression, source: String, fileName: String, enums: Map<String, EnumAsgInfo>) {
        when (expr) {
            is BinaryExpression -> {
                var cur: Expression = expr
                while (cur is BinaryExpression) { encmCheckExpr(cur.right, source, fileName, enums); cur = cur.left }
                encmCheckExpr(cur, source, fileName, enums)
            }
            is ParenthesizedExpression -> encmCheckExpr(expr.expression, source, fileName, enums)
            is CallExpression -> { encmCheckExpr(expr.expression, source, fileName, enums); expr.arguments.forEach { encmCheckExpr(it, source, fileName, enums) } }
            is NewExpression -> { encmCheckExpr(expr.expression, source, fileName, enums); expr.arguments?.forEach { encmCheckExpr(it, source, fileName, enums) } }
            is PropertyAccessExpression -> {
                // Piece A: `<ns>.<E>.<name>` where the receiver resolves to a collected enum.
                // Gate to a QUALIFIED receiver (a PropertyAccess like `second.E`): bare-enum
                // access (`U8.bit_2`) is already owned by the standard checkPropertyAccess path
                // which emits TS2551/TS2339 with spelling suggestions (exactSpellingSuggestion).
                val recvKey = if (expr.expression is PropertyAccessExpression) exprDottedName(expr.expression) else null
                if (recvKey != null) {
                    val info = enums[recvKey]
                    if (info != null) {
                        val mem = expr.name.text
                        if (mem !in info.memberOrder && mem !in RUNTIME_PROPERTIES) {
                            val (line, ch) = getLineAndCharacterOfPosition(source, expr.name.pos)
                            diagnostics.add(Diagnostic(
                                message = "Property '$mem' does not exist on type 'typeof ${info.simpleName}'.",
                                category = DiagnosticCategory.Error, code = 2339,
                                fileName = fileName, line = line, character = ch,
                                start = expr.name.pos, length = mem.length,
                            ))
                        }
                    }
                }
                encmCheckExpr(expr.expression, source, fileName, enums)
            }
            is ElementAccessExpression -> { encmCheckExpr(expr.expression, source, fileName, enums); encmCheckExpr(expr.argumentExpression, source, fileName, enums) }
            is ConditionalExpression -> { encmCheckExpr(expr.condition, source, fileName, enums); encmCheckExpr(expr.whenTrue, source, fileName, enums); encmCheckExpr(expr.whenFalse, source, fileName, enums) }
            is ArrayLiteralExpression -> expr.elements.forEach { encmCheckExpr(it, source, fileName, enums) }
            is SpreadElement -> encmCheckExpr(expr.expression, source, fileName, enums)
            is PrefixUnaryExpression -> encmCheckExpr(expr.operand, source, fileName, enums)
            is PostfixUnaryExpression -> encmCheckExpr(expr.operand, source, fileName, enums)
            is AsExpression -> encmCheckExpr(expr.expression, source, fileName, enums)
            is NonNullExpression -> encmCheckExpr(expr.expression, source, fileName, enums)
            else -> {}
        }
    }

    private fun exprDottedName(e: Expression): String? = when (e) {
        is Identifier -> e.text
        is PropertyAccessExpression -> exprDottedName(e.expression)?.let { "$it.${e.name.text}" }
        else -> null
    }

    /** B463: collect dotted keys of all (possibly nested) namespace declarations, so piece A
     *  can skip enums merged with a same-name namespace (whose value members it can't see). */
    private fun encmCollectNsKeys(stmts: List<Statement>, nsPath: String?, into: MutableSet<String>) {
        for (st in stmts) if (st is ModuleDeclaration) {
            val n = (st.name as? Identifier)?.text ?: continue
            val key = if (nsPath != null) "$nsPath.$n" else n
            into.add(key)
            (st.body as? ModuleBlock)?.let { encmCollectNsKeys(it.statements, key, into) }
        }
    }

    /** B463 helper: resolve a TypeReference param/return annotation to its dotted enum key. */
    private fun encmEnumKeyOfType(t: TypeNode?, enums: Map<String, EnumAsgInfo>): String? = enumKeyOfTypeNode(t, enums)

    private fun encmCheckOverloads(stmts: List<Statement>, source: String, fileName: String, enums: Map<String, EnumAsgInfo>) {
        // Piece C — overloaded functions: overload-sig return enum vs impl return enum.
        val byName = LinkedHashMap<String, MutableList<FunctionDeclaration>>()
        for (st in stmts) if (st is FunctionDeclaration) {
            val n = st.name?.text ?: continue
            byName.getOrPut(n) { mutableListOf() }.add(st)
        }
        for ((_, group) in byName) {
            if (group.size < 2) continue
            val impl = group.firstOrNull { it.body != null } ?: continue
            val implKey = encmEnumKeyOfType(impl.type, enums) ?: continue
            val implEnum = enums[implKey]!!
            val implName = impl.name ?: continue
            val (il, ic) = getLineAndCharacterOfPosition(source, implName.pos)
            for (ov in group) {
                if (ov.body != null) continue
                val ovKey = encmEnumKeyOfType(ov.type, enums) ?: continue
                if (ovKey == implKey) continue
                val ovEnum = enums[ovKey]!!
                // overload incompatible with impl iff impl return not assignable to overload return.
                if (enumAsgFailure(implEnum, ovEnum) == null) continue
                val ovName = ov.name ?: continue
                val (line, ch) = getLineAndCharacterOfPosition(source, ovName.pos)
                diagnostics.add(Diagnostic(
                    message = "This overload signature is not compatible with its implementation signature.",
                    category = DiagnosticCategory.Error, code = 2394,
                    fileName = fileName, line = line, character = ch,
                    start = ovName.pos, length = ovName.text.length,
                    relatedInformation = listOf(Diagnostic(
                        message = "The implementation signature is declared here.",
                        category = DiagnosticCategory.Message, code = 2750,
                        fileName = fileName, line = il, character = ic,
                        start = implName.pos, length = implName.text.length,
                    )),
                ))
            }
        }
    }

    /** B425: recursively collect enum declarations (merging blocks of the same name) keyed by
     *  their namespace-qualified name. */
    private fun collectEnumsForAsg(
        stmts: List<Statement>, nsPath: String?, into: LinkedHashMap<String, EnumAsgInfo>,
        ambient: Boolean = false,
    ) {
        val byKey = LinkedHashMap<String, MutableList<EnumDeclaration>>()
        for (st in stmts) {
            when (st) {
                is EnumDeclaration -> {
                    val key = if (nsPath != null) "$nsPath.${st.name.text}" else st.name.text
                    byKey.getOrPut(key) { mutableListOf() }.add(st)
                }
                is ModuleDeclaration -> {
                    val n = (st.name as? Identifier)?.text ?: continue
                    val body = st.body as? ModuleBlock ?: continue
                    val nsAmbient = ambient || ModifierFlag.Declare in st.modifiers
                    collectEnumsForAsg(body.statements, if (nsPath != null) "$nsPath.$n" else n, into, nsAmbient)
                }
                else -> {}
            }
        }
        for ((key, decls) in byKey) {
            val simple = decls[0].name.text
            var isConst = false
            var isString = false
            var evaluable = true
            val memberOrder = mutableListOf<String>()
            val values = LinkedHashMap<String, Double>()
            val strVals = LinkedHashMap<String, String>()
            for (d in decls) {
                if (ModifierFlag.Const in d.modifiers) isConst = true
                var auto = 0.0
                for (m in d.members) {
                    val mName = (m.name as? Identifier)?.text ?: (m.name as? StringLiteralNode)?.text
                    if (mName == null) { evaluable = false; continue }
                    if (mName !in memberOrder) memberOrder.add(mName)
                    val init = m.initializer
                    if (init is StringLiteralNode) { isString = true; evaluable = false; strVals[mName] = init.text }
                    val v = if (init == null) auto else evalEnumConstExpr(init)
                    if (v == null) evaluable = false else { values[mName] = v; auto = v + 1 }
                }
            }
            into[key] = EnumAsgInfo(
                simple, nsPath, memberOrder,
                if (evaluable && !isString) values else null, isConst, isString, decls[0],
                stringValues = if (isString) strVals else null,
                isAmbient = ambient,
            )
        }
    }

    /** B425: resolve a `[declare] var X: <type>` annotation to a collected enum key, or null. */
    private fun enumKeyOfTypeNode(t: TypeNode?, enums: Map<String, EnumAsgInfo>): String? {
        val tr = t as? TypeReference ?: return null
        if (tr.typeArguments != null) return null
        val key = when (val tn = tr.typeName) {
            is Identifier -> tn.text
            is QualifiedName -> qualifiedNameToDottedString(tn)
            else -> null
        } ?: return null
        return if (key in enums) key else null
    }

    private fun qualifiedNameToDottedString(qn: QualifiedName): String? {
        val left = when (val l = qn.left) {
            is Identifier -> l.text
            is QualifiedName -> qualifiedNameToDottedString(l)
            else -> null
        } ?: return null
        return "$left.${qn.right.text}"
    }

    /** B425: returns null if `src` is assignable to `tgt`; else (topMessage, chainLines). */
    private fun enumAsgFailure(src: EnumAsgInfo, tgt: EnumAsgInfo): Pair<String, List<String>>? {
        val sameSimple = src.simpleName == tgt.simpleName
        val srcD = if (sameSimple) src.qualifiedDisplay else src.simpleName
        val tgtD = if (sameSimple) tgt.qualifiedDisplay else tgt.simpleName
        val top = "Type '$srcD' is not assignable to type '$tgtD'."
        if (!sameSimple) return top to emptyList() // different name → not assignable, no chain
        if (src.isConst || tgt.isConst) {
            if (src.decl === tgt.decl) return null
            return top to emptyList() // const only assignable to itself, no chain
        }
        // B554/enumAssignmentCompat6: value-KIND comparison (numeric-known / numeric-unknown
        // ambient / string). The chain reports the FIRST mismatching (or missing) member.
        for (m in src.memberOrder) {
            if (m !in tgt.memberOrder) return top to listOf("  Property '$m' is missing in type '$tgtD'.")
            val chain = enumMemberMismatch(src, tgt, m) ?: continue
            return top to listOf(chain)
        }
        return null
    }

    private enum class EnumValKind { NUMERIC_KNOWN, NUMERIC_UNKNOWN, STRING }

    private fun enumValKind(info: EnumAsgInfo): EnumValKind = when {
        info.isString -> EnumValKind.STRING
        info.isAmbient -> EnumValKind.NUMERIC_UNKNOWN
        else -> EnumValKind.NUMERIC_KNOWN
    }

    /** Formatted value of member `m` for a known side (numeric → plain, string → double-quoted); null for unknown. */
    private fun enumValFmt(info: EnumAsgInfo, m: String): String? = when {
        info.isString -> "\"" + (info.stringValues?.get(m) ?: return null) + "\""
        info.values != null -> fmtEnumAsgVal(info.values[m] ?: return null)
        else -> null
    }

    /** null = member `m` is compatible across src/tgt; else the mismatch chain line. */
    private fun enumMemberMismatch(src: EnumAsgInfo, tgt: EnumAsgInfo, m: String): String? {
        val sk = enumValKind(src); val tk = enumValKind(tgt)
        // both numeric (known or unknown) → compatible unless BOTH known and values differ
        if (sk != EnumValKind.STRING && tk != EnumValKind.STRING) {
            if (sk == EnumValKind.NUMERIC_KNOWN && tk == EnumValKind.NUMERIC_KNOWN) {
                val sv = src.values?.get(m); val tv = tgt.values?.get(m)
                if (sv != null && tv != null && sv != tv)
                    return "  Each declaration of '${src.simpleName}.$m' differs in its value, where '${fmtEnumAsgVal(tv)}' was expected but '${fmtEnumAsgVal(sv)}' was given."
            }
            return null
        }
        // both string → compatible unless values differ
        if (sk == EnumValKind.STRING && tk == EnumValKind.STRING) {
            val sv = src.stringValues?.get(m); val tv = tgt.stringValues?.get(m)
            if (sv != null && tv != null && sv != tv)
                return "  Each declaration of '${src.simpleName}.$m' differs in its value, where '\"$tv\"' was expected but '\"$sv\"' was given."
            return null
        }
        // string vs numeric-unknown (ambient) → symmetric "unknown numeric value" message
        if (sk == EnumValKind.NUMERIC_UNKNOWN || tk == EnumValKind.NUMERIC_UNKNOWN) {
            val strInfo = if (sk == EnumValKind.STRING) src else tgt
            val strV = strInfo.stringValues?.get(m) ?: return null
            return "  One value of '${src.simpleName}.$m' is the string '\"$strV\"', and the other is assumed to be an unknown numeric value."
        }
        // string vs numeric-known → "differs in its value" with mixed formatting
        val expectedV = enumValFmt(tgt, m) ?: return null
        val givenV = enumValFmt(src, m) ?: return null
        return "  Each declaration of '${src.simpleName}.$m' differs in its value, where '$expectedV' was expected but '$givenV' was given."
    }

    private fun fmtEnumAsgVal(v: Double): String =
        if (v == v.toLong().toDouble()) v.toLong().toString() else v.toString()

    // B583 (`checkEnumAsgInFunctionScopes`) is RETIRED — (REL.1)(c) round 749.
    // It owned `enumAssignmentCompat6`: enum assignments inside FUNCTION bodies (a.ts) and
    // inside an IIFE whose block-scoped enum SHADOWS a module-exported one (f.ts). Round 748
    // made that inner enum resolvable in TYPE position, which gave the general relation both
    // verdicts at both positions; the last thing the walker still said that the general path
    // could not was the shadowed enum's `import("f").DiagnosticCategory` display, and
    // [enumModuleImportPrefix] supplies it. The walker's `declare namespace` value-KIND split
    // turned out to be the relation's already ([enumMemberEntries], round 746). Ablation: with
    // the walker's retraction removed, all EIGHT of `enumAssignmentCompat6` duplicated
    // byte-identically; with the walker gone, all eight remain, byte-identical to tsc.

    // (M0.4) round 637: checkGenericIndexWrite (TS2862) ON THE SPINE.
    // The legacy per-file recursion (checkGenericIndexWrite / gIdxHandleBody
    // / gIdxScanStatements / gIdxScanStatement / gIdxCheckExpr) is deleted.
    // The pass threaded a purely DOWNWARD (tparams, tpProps, refs) triple —
    // tparams ACCUMULATED through class/fn boundaries (constrainedTpNames),
    // tpProps built from the nearest enclosing class's bare-TP property
    // annotations (RESET by a nested FunctionDeclaration; cleared for
    // property initializers), refs REBUILT at every fn-like boundary from
    // collectParamTpRefs + the body-WIDE collectTpLocalsMap prepass (NOT
    // statement-ordered — locals in switch/try bodies stay uncollected, the
    // frozen prepass-vs-scan descent asymmetry) — so the ctx is a pure
    // function of the ancestor chain and reproduces PULL-based per anchor,
    // memoized per boundary-child node ([spineGxCtxFor]). Reach is the
    // memoized binary classifier [spineGxStatus] over [spineGxEdge] (the
    // deleted arms verbatim — arrow/fn-expression bodies, class EXPRESSIONS,
    // object literals, compound assignments, template/typeof/await operands
    // all stay UNREACHED). The bounded emission leaf
    // (emitTS2862IfGenericIndexWrite) is retained unchanged. No ambient
    // sandwich — the emission is purely syntactic (source + string maps).
    // -----------------------------------------------------------------------

    /** Per-file setup: the legacy dts + `.js`/`.jsx` skip. */
    private fun spineGxSetup(result: BinderResult) {
        spineGxActive = !spineIsDts &&
            !spineFileName.endsWith(".js") && !spineFileName.endsWith(".jsx")
        spineGxCtxMemo.clear()
        spineGxReachMemo = if (!spineGxActive) ByteArray(0) else {
            val n = result.sourceFile.nodeCount
            if (n > 0) ByteArray(n) else ByteArray(0)
        }
    }

    private fun spineGxTeardown() {
        spineGxActive = false
        spineGxCtxMemo.clear()
        spineGxReachMemo = ByteArray(0)
    }

    /** ENTER dispatch: the legacy gIdxCheckExpr `=`-spine emission — an `=`
     *  BinaryExpression whose paren-unwrapped LHS is an
     *  ElementAccessExpression (the cheap shape gate runs BEFORE the reach
     *  climb; the numeric-literal-index and receiver-shape gates stay inside
     *  the retained emission leaf). */
    private fun spineGxEnterNode(node: Node) {
        if ((node as NodeBase).kindId != NodeKind.BINARY_EXPRESSION) return
        node as BinaryExpression
        if (node.operator != SyntaxKind.Equals) return
        var target: Expression = node.left
        while (target is ParenthesizedExpression) target = target.expression
        if (target !is ElementAccessExpression) return
        if (spineGxStatus(node) != GX_REACHED) return
        val ctx = spineGxCtxAt(node)
        emitTS2862IfGenericIndexWrite(node.left, spineSource, spineFileName, ctx.tpProps, ctx.refs)
    }

    /** The legacy downward triple at [anchor]: climb to the nearest
     *  ctx-defining boundary child (a fn-like's body / a class-prop
     *  initializer); no boundary up to the SourceFile → the per-file entry
     *  ctx (the legacy top-level scan's empty triple — ModuleBlocks pass
     *  context through unchanged, exactly as the legacy ModuleDeclaration
     *  arm did). */
    private fun spineGxCtxAt(anchor: Node): GxCtx {
        var child: Node = anchor
        var p: Node? = (anchor as NodeBase).parent
        while (p != null && p !is SourceFile) {
            if (spineGxIsBoundaryChild(p, child)) return spineGxCtxFor(p, child)
            child = p
            p = (p as NodeBase).parent
        }
        return spineGxEmptyCtx
    }

    private fun spineGxIsBoundaryChild(p: Node, child: Node): Boolean = when (p) {
        is FunctionDeclaration -> child === p.body
        is MethodDeclaration -> child === p.body
        is Constructor -> child === p.body
        is GetAccessor -> child === p.body
        is SetAccessor -> child === p.body
        is PropertyDeclaration -> child === p.initializer
        else -> false
    }

    /** Memoized child ctx for a boundary [child] of fn-like/class-member [p]
     *  — the deleted gIdxScanStatement ClassDeclaration/FunctionDeclaration
     *  arms + gIdxHandleBody verbatim (a FunctionDeclaration RESETS tpProps;
     *  a GetAccessor body rebuilds refs from NO params; a class-prop
     *  initializer runs with the cleared (∅, ∅) pair — nothing below an
     *  initializer can define a nested boundary, so its tparams are never
     *  consulted). */
    private fun spineGxCtxFor(p: Node, child: Node): GxCtx {
        val id = (child as NodeBase).nodeId
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineGxCtxMemo[id]?.let { return it }
        val ctx: GxCtx = when (p) {
            is FunctionDeclaration -> {
                val ftp = spineGxCtxAt(p).tparams + constrainedTpNames(p.typeParameters)
                GxCtx(ftp, emptyMap(), spineGxBodyRefs(child as Block, ftp, collectParamTpRefs(p.parameters, ftp)))
            }
            is MethodDeclaration -> {
                val cls = (p as NodeBase).parent as? ClassDeclaration
                val newTp = spineGxClassTp(cls)
                val mtp = newTp + constrainedTpNames(p.typeParameters)
                GxCtx(mtp, spineGxClassProps(cls, newTp), spineGxBodyRefs(child as Block, mtp, collectParamTpRefs(p.parameters, mtp)))
            }
            is Constructor -> {
                val cls = (p as NodeBase).parent as? ClassDeclaration
                val newTp = spineGxClassTp(cls)
                GxCtx(newTp, spineGxClassProps(cls, newTp), spineGxBodyRefs(child as Block, newTp, collectParamTpRefs(p.parameters, newTp)))
            }
            is GetAccessor -> {
                val cls = (p as NodeBase).parent as? ClassDeclaration
                val newTp = spineGxClassTp(cls)
                GxCtx(newTp, spineGxClassProps(cls, newTp), spineGxBodyRefs(child as Block, newTp, emptyMap()))
            }
            is SetAccessor -> {
                val cls = (p as NodeBase).parent as? ClassDeclaration
                val newTp = spineGxClassTp(cls)
                GxCtx(newTp, spineGxClassProps(cls, newTp), spineGxBodyRefs(child as Block, newTp, collectParamTpRefs(p.parameters, newTp)))
            }
            else -> spineGxEmptyCtx // PropertyDeclaration initializer: (∅, ∅)
        }
        if (MapCensus.boxedKeyCensus && id >= 0) MapCensus.bk(MapCensus.BK_SPINE_MEMO, id.toLong())
        if (id >= 0) spineGxCtxMemo[id] = ctx
        return ctx
    }

    /** gIdxHandleBody's refs build: params first, then the body-WIDE locals
     *  prepass (locals override same-named params — the legacy map order). */
    private fun spineGxBodyRefs(body: Block, tparams: Set<String>, paramRefs: Map<String, String>): Map<String, String> {
        val refs = paramRefs.toMutableMap()
        collectTpLocalsMap(body.statements, tparams, refs)
        return refs
    }

    /** The ClassDeclaration arm's newTp — the class's own statement-position
     *  tparams (accumulated through enclosing fn bodies) + its constrained
     *  TPs. */
    private fun spineGxClassTp(cls: ClassDeclaration?): Set<String> {
        if (cls == null) return emptySet()
        return spineGxCtxAt(cls).tparams + constrainedTpNames(cls.typeParameters)
    }

    /** The ClassDeclaration arm's props map — bare-TP-annotated property
     *  members keyed by name (for `this.<prop>[k] = v` receivers). */
    private fun spineGxClassProps(cls: ClassDeclaration?, newTp: Set<String>): Map<String, String> {
        if (cls == null) return emptyMap()
        val props = HashMap<String, String>()
        for (m in cls.members) if (m is PropertyDeclaration) {
            val n = (m.name as? Identifier)?.text
            if (n != null) bareTypeParamRefName(m.type, newTp)?.let { props[n] = it }
        }
        return props
    }

    /** Memoized reach classifier — ascends to the first memoized/terminal
     *  ancestor, then folds [spineGxEdge] back down (spineFpStatus pattern).
     *  The SourceFile anchor carries the transient GX_ROOT status (never
     *  memoized) whose sole edge is `child is Statement`. */
    private fun spineGxStatus(node: Node): Int {
        if (ReachCensus.on) ReachCensus.calls[ReachCensus.GX]++
        if (node is SourceFile) return GX_ROOT
        val memo = spineGxReachMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachCensus.GX, id)
                val m = memo[id].toInt()
                if (m != 0) return m
            }
        }
        val chain = spineGxChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorStatus = GX_NONE
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed
            if (parent is SourceFile) { anchor = parent; anchorStatus = GX_ROOT; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachCensus.GX, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorStatus = pm; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pStatus = anchorStatus
        var result = GX_NONE
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = when {
                pNode == null -> GX_NONE
                pStatus == GX_ROOT -> if (c is Statement) GX_REACHED else GX_NONE
                pStatus == GX_REACHED -> if (spineGxEdge(pNode, c)) GX_REACHED else GX_NONE
                else -> GX_NONE
            }
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachCensus.GX, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = result.toByte()
            pNode = c
            pStatus = result
        }
        if (ReachCensus.on) { ReachCensus.misses[ReachCensus.GX]++; ReachCensus.folds[ReachCensus.GX] += chain.size.toLong() }
        chain.clear()
        return result
    }

    /** The deleted recursion's descent edges, verbatim. Unlisted parents are
     *  the legacy `else -> {}`s (unreached children — arrows, fn/class
     *  expressions, object literals, templates, typeof/await operands,
     *  for-in/of LEFT sides, case expressions, param defaults, heritage). */
    private fun spineGxEdge(parent: Node, child: Node): Boolean = when (parent) {
        // ---- statements (the deleted gIdxScanStatement arms) ----
        is ClassDeclaration -> when (child) {
            is MethodDeclaration, is Constructor, is GetAccessor,
            is SetAccessor, is PropertyDeclaration -> true
            else -> false
        }
        is MethodDeclaration -> child === parent.body
        is Constructor -> child === parent.body
        is GetAccessor -> child === parent.body
        is SetAccessor -> child === parent.body
        is PropertyDeclaration -> child === parent.initializer
        is FunctionDeclaration -> child === parent.body
        is ExpressionStatement -> child === parent.expression
        is VariableStatement -> child === parent.declarationList
        is VariableDeclarationList -> child is VariableDeclaration
        is VariableDeclaration -> child === parent.initializer
        is ReturnStatement -> child === parent.expression
        is ThrowStatement -> child === parent.expression
        is Block -> child is Statement
        is IfStatement ->
            child === parent.expression || child === parent.thenStatement ||
                child === parent.elseStatement
        is ForStatement ->
            child === parent.initializer || child === parent.condition ||
                child === parent.incrementor || child === parent.statement
        is ForInStatement -> child === parent.expression || child === parent.statement
        is ForOfStatement -> child === parent.expression || child === parent.statement
        is WhileStatement -> child === parent.expression || child === parent.statement
        is DoStatement -> child === parent.statement || child === parent.expression
        is SwitchStatement ->
            child === parent.expression || child is CaseClause || child is DefaultClause
        is CaseClause -> child is Statement // NOT the case expression
        is DefaultClause -> child is Statement
        is TryStatement ->
            child === parent.tryBlock || child === parent.finallyBlock || child is CatchClause
        is CatchClause -> child === parent.block
        is LabeledStatement -> child === parent.statement
        is ModuleDeclaration -> child === parent.body && child is ModuleBlock
        is ModuleBlock -> child is Statement
        // ---- expressions (the deleted gIdxCheckExpr arms) ----
        is BinaryExpression -> child === parent.left || child === parent.right
        is ParenthesizedExpression -> child === parent.expression
        is CallExpression -> child === parent.expression || parent.arguments.anyIdentical(child)
        is NewExpression ->
            child === parent.expression || parent.arguments?.anyIdentical(child) == true
        is PropertyAccessExpression -> child === parent.expression
        is ElementAccessExpression ->
            child === parent.expression || child === parent.argumentExpression
        is ConditionalExpression ->
            child === parent.condition || child === parent.whenTrue || child === parent.whenFalse
        is ArrayLiteralExpression -> parent.elements.anyIdentical(child)
        is SpreadElement -> child === parent.expression
        is PrefixUnaryExpression -> child === parent.operand
        is PostfixUnaryExpression -> child === parent.operand
        is AsExpression -> child === parent.expression
        is NonNullExpression -> child === parent.expression
        else -> false
    }

    private fun emitTS2862IfGenericIndexWrite(lhs: Expression, source: String, fileName: String, tpProps: Map<String, String>, refs: Map<String, String>) {
        var target: Expression = lhs
        while (target is ParenthesizedExpression) target = target.expression
        val ea = target as? ElementAccessExpression ?: return
        if (ea.argumentExpression is NumericLiteralNode) return  // numeric-literal index is the allowed write form
        val recv = ea.expression
        val tpName = when (recv) {
            is Identifier -> refs[recv.text]
            is PropertyAccessExpression -> if ((recv.expression as? Identifier)?.text == "this") tpProps[recv.name.text] else null
            else -> null
        } ?: return
        val start = ea.pos
        val length = expressionTrueEnd(ea) - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type '$tpName' is generic and can only be indexed for reading.",
            category = DiagnosticCategory.Error,
            code = 2862,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2469 ("The '+'/'+=' operator cannot be applied to type 'symbol'.") and
    // TS2731 ("Implicit conversion of a 'symbol' to a 'string' will fail at
    // runtime. Consider wrapping this expression in 'String(...)'.").
    //
    // AST-level + FP-firewalled, mirroring the r79/r80 type-param walkers: we
    // thread the set of in-scope identifier names whose declared annotation type
    // CONTAINS `symbol` (directly, via a union, via a `symbol`-constrained type
    // parameter, or via a type alias resolving to a symbol-containing type), then
    // flag those identifiers when used as a template-interpolation operand
    // (TS2731) or a `+`/`+=`/unary-`+` operand (TS2469). No type-engine — purely
    // annotation-based. FP-safe: TypeScript emits TS2469/TS2731 UNCONDITIONALLY
    // for a symbol operand in these positions, so a passing test with such an
    // operand already carries the diagnostic — this can only help or be neutral.
    // (M0.4, round 628): the per-file pass driver + recursion walkers
    // (checkSymbolToStringConversions / sym2strHandleFnBody /
    // sym2strHandleBody / sym2strScanStatement / sym2strCheckExpr) are
    // DELETED — the spine dispatches the emissions (spineSyEnterNode) with a
    // pull-based per-anchor context rebuild. The set-building helpers below
    // are retained as the rebuild's leaves.
    // -----------------------------------------------------------------------

    /** A type node that contains `symbol` (directly / union / symbol-constrained
     *  type-param ref / symbol-resolving type-alias ref). Unwraps parentheses. */
    private fun sym2strContainsSymbol(t: TypeNode?, tpNames: Set<String>, aliasNames: Set<String>): Boolean {
        var node = t
        while (node is ParenthesizedType) node = node.type
        return when (node) {
            is KeywordTypeNode -> node.kind == SyntaxKind.SymbolKeyword
            is UnionType -> node.types.any { sym2strContainsSymbol(it, tpNames, aliasNames) }
            is TypeReference -> {
                val nm = (node.typeName as? Identifier)?.text
                nm != null && node.typeArguments.isNullOrEmpty() && (nm in tpNames || nm in aliasNames)
            }
            else -> false
        }
    }

    /** File/namespace-level type aliases whose body resolves to a symbol-containing
     *  type (fixpoint over alias→alias references). */
    private fun collectSymbolAliases(stmts: List<Statement>, into: MutableSet<String>) {
        val aliases = HashMap<String, TypeNode>()
        fun walk(ss: List<Statement>) {
            for (s in ss) when (s) {
                is TypeAliasDeclaration -> aliases[s.name.text] = s.type
                is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { walk(it.statements) }
                is Block -> walk(s.statements)
                else -> {}
            }
        }
        walk(stmts)
        var changed = true
        while (changed) {
            changed = false
            for ((name, type) in aliases) {
                if (name !in into && sym2strContainsSymbol(type, emptySet(), into)) { into.add(name); changed = true }
            }
        }
    }

    /** Type-parameter names whose constraint contains symbol (plus the outer set). */
    private fun symbolLikeTpNames(tps: List<TypeParameter>?, outer: Set<String>, aliasNames: Set<String>): Set<String> {
        if (tps.isNullOrEmpty()) return outer
        val result = outer.toMutableSet()
        var changed = true
        while (changed) {
            changed = false
            for (tp in tps) {
                if (tp.name.text !in result && sym2strContainsSymbol(tp.constraint, result, aliasNames)) {
                    result.add(tp.name.text); changed = true
                }
            }
        }
        return result
    }

    /** Collect local var names (incl. for-init) whose annotation contains symbol.
     *  Does NOT descend into nested function/class bodies. */
    private fun collectSymbolLocals(stmts: List<Statement>, tpNames: Set<String>, aliasNames: Set<String>, into: MutableSet<String>) {
        for (stmt in stmts) when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                val n = (d.name as? Identifier)?.text
                if (n != null && sym2strContainsSymbol(d.type, tpNames, aliasNames)) into.add(n)
            }
            is Block -> collectSymbolLocals(stmt.statements, tpNames, aliasNames, into)
            is IfStatement -> { collectSymbolLocals(listOf(stmt.thenStatement), tpNames, aliasNames, into); stmt.elseStatement?.let { collectSymbolLocals(listOf(it), tpNames, aliasNames, into) } }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                    val n = (d.name as? Identifier)?.text
                    if (n != null && sym2strContainsSymbol(d.type, tpNames, aliasNames)) into.add(n)
                }
                collectSymbolLocals(listOf(stmt.statement), tpNames, aliasNames, into)
            }
            is ForInStatement -> collectSymbolLocals(listOf(stmt.statement), tpNames, aliasNames, into)
            is ForOfStatement -> collectSymbolLocals(listOf(stmt.statement), tpNames, aliasNames, into)
            is WhileStatement -> collectSymbolLocals(listOf(stmt.statement), tpNames, aliasNames, into)
            is DoStatement -> collectSymbolLocals(listOf(stmt.statement), tpNames, aliasNames, into)
            is TryStatement -> {
                collectSymbolLocals(stmt.tryBlock.statements, tpNames, aliasNames, into)
                stmt.catchClause?.let { collectSymbolLocals(it.block.statements, tpNames, aliasNames, into) }
                stmt.finallyBlock?.let { collectSymbolLocals(it.statements, tpNames, aliasNames, into) }
            }
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val cs = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                collectSymbolLocals(cs, tpNames, aliasNames, into)
            }
            is LabeledStatement -> collectSymbolLocals(listOf(stmt.statement), tpNames, aliasNames, into)
            else -> {}
        }
    }

    private fun emitSym2469(operand: Expression, opText: String, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, operand.pos)
        diagnostics.add(Diagnostic(
            message = "The '$opText' operator cannot be applied to type 'symbol'.",
            category = DiagnosticCategory.Error, code = 2469, fileName = fileName,
            line = line, character = character, start = operand.pos, length = expressionTrueEnd(operand) - operand.pos,
        ))
    }

    private fun emitSym2731(operand: Expression, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, operand.pos)
        diagnostics.add(Diagnostic(
            message = "Implicit conversion of a 'symbol' to a 'string' will fail at runtime. Consider wrapping this expression in 'String(...)'.",
            category = DiagnosticCategory.Error, code = 2731, fileName = fileName,
            line = line, character = character, start = operand.pos, length = expressionTrueEnd(operand) - operand.pos,
        ))
    }

    // TS2362/TS2363 arithmetic operator type checking — deferred.
    // Naive implementation causes 1300+ regressions because getTypeOfExpression
    // resolves many globals (string, boolean types) that participate in valid
    // arithmetic in test code. Needs conservative approach: only check when operand
    // type is DEFINITIVELY non-numeric (literal string, literal boolean, etc.)
    // and not just any resolved type.
    // NOTE (INV.4(d) walker 2, round 531): the per-file pass driver
    // (checkArithmeticOperandTypes) is DELETED — the spine dispatches the
    // emissions (spineArithEnterNode/spineArithLeaveNode) with push-maintained
    // pass state. checkArithmeticInStatement(s)/checkArithmeticInExpr below are
    // RETAINED solely as checkComputedDestructKey's expression utility.
    private fun checkArithmeticInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkArithmeticInStatement(stmt, source, fileName)
    }

    /**
     * checkJs-only narrow walker for a cross-category relational comparison whose LHS is a
     * NUMERIC LITERAL (`1234 > x`, `5 <= "a"`, …). The full arithmetic/comparison pass
     * (`checkArithmeticOperandTypes`) SKIPS .js/.jsx files (load-bearing — the naive pass
     * FP'd broadly under loose JS typing). But tsc ALWAYS emits TS2365 for a relational
     * comparison whose operands are in different comparability categories (number vs
     * string/boolean), even in checkJs — so this one shape is FP-safe to emit: a
     * numeric-literal LHS pins the left category to `number`, and `comparabilityCategory`
     * returns null for `any`/mixed unions (so a loosely-typed RHS never fires). Used by
     * `parseUnaryExpressionNoTypeAssertionInJsx3` (`+ <1234> x` recovers to `1234 > x`).
     */
    private fun checkJsCrossCategoryRelational() {
        if (!options.checkJs) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName) || !isJsLikeFileName(fileName)) continue
            val source = result.sourceFile.text
            currentFileLocals = result.locals
            currentCheckFileName = fileName
            jsRelWalkStmts(result.sourceFile.statements, source, fileName)
        }
        currentFileLocals = null
        currentCheckFileName = null
    }

    private fun jsRelWalkStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) jsRelWalkStmt(stmt, source, fileName)
    }

    private fun jsRelWalkStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> jsRelCheckExpr(stmt.expression, source, fileName)
            is Block -> jsRelWalkStmts(stmt.statements, source, fileName)
            is IfStatement -> {
                jsRelCheckExpr(stmt.expression, source, fileName)
                jsRelWalkStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { jsRelWalkStmt(it, source, fileName) }
            }
            is WhileStatement -> { jsRelCheckExpr(stmt.expression, source, fileName); jsRelWalkStmt(stmt.statement, source, fileName) }
            is DoStatement -> { jsRelCheckExpr(stmt.expression, source, fileName); jsRelWalkStmt(stmt.statement, source, fileName) }
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { jsRelCheckExpr(it, source, fileName) }
                stmt.condition?.let { jsRelCheckExpr(it, source, fileName) }
                stmt.incrementor?.let { jsRelCheckExpr(it, source, fileName) }
                jsRelWalkStmt(stmt.statement, source, fileName)
            }
            is FunctionDeclaration -> stmt.body?.let { jsRelWalkStmts(it.statements, source, fileName) }
            is VariableStatement -> stmt.declarationList.declarations.forEach { d -> d.initializer?.let { jsRelCheckExpr(it, source, fileName) } }
            is ReturnStatement -> stmt.expression?.let { jsRelCheckExpr(it, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { jsRelCheckExpr(it, source, fileName) }
            else -> {}
        }
    }

    /** Check a single expression for the narrow cross-category relational shape. Unwraps
     *  parens; does NOT deeply recurse (FN-safe for nested positions — the corpus shape is
     *  a statement-level comparison). */
    private fun jsRelCheckExpr(exprIn: Expression, source: String, fileName: String) {
        val expr = (exprIn as? ParenthesizedExpression)?.expression ?: exprIn
        if (expr !is BinaryExpression) return
        val op = expr.operator
        if (op != SyntaxKind.LessThan && op != SyntaxKind.GreaterThan &&
            op != SyntaxKind.LessThanEquals && op != SyntaxKind.GreaterThanEquals) return
        if (expr.left !is NumericLiteralNode) return
        val lt = getTypeOfExpression(expr.left)
        val rt = getTypeOfExpression(expr.right)
        val lc = comparabilityCategory(lt) ?: return
        val rc = comparabilityCategory(rt) ?: return
        if (lc != rc) emitTs2365(expr, op, lt, rt, source, fileName, lc, rc)
    }

    private fun checkArithmeticInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkArithmeticInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                    // Record literal-typed locals so later arithmetic/comparison checks
                    // in this scope can resolve a bare-identifier operand (e.g.
                    // `const t = true; onethree >= t`) — the shared per-declarator
                    // recording (see spineArithRecordVarDecl for the full rules).
                    spineArithRecordVarDecl(decl, stmt.declarationList.flags == SyntaxKind.ConstKeyword)
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkArithmeticInExpr(it, source, fileName) }
            is Block -> checkArithmeticInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                // B283: a `typeof x === "..."` guard narrows `x` in both branches —
                // this walker has no flow narrowing, so union-typed operands named
                // here are exempt from the maybe-bigint TS2365/TS2736 mixing rules.
                val guarded = collectTypeofGuardNames(stmt.expression)
                val savedGuards = arithTypeofNarrowedNames
                if (guarded.isNotEmpty()) arithTypeofNarrowedNames = savedGuards + guarded
                try {
                    checkArithmeticInStatement(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { checkArithmeticInStatement(it, source, fileName) }
                } finally { arithTypeofNarrowedNames = savedGuards }
            }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> init.declarations.forEach { d ->
                        d.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                    }
                    is Expression -> checkArithmeticInExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkArithmeticInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkArithmeticInExpr(it, source, fileName) }
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                // A for-in loop variable is always `string`. Record it (scoped to the loop
                // body via a snapshot/restore) so this pass does not resolve it via the
                // block-UNAWARE file-level type map to a same-named numeric var declared
                // elsewhere in the file (capturedLetConstInLoop6/7: `for (let x in [])
                // if (x == "1")` where a later `let x = 1` leaks `number` → spurious TS2367).
                val forInVar = ((stmt.initializer as? VariableDeclarationList)
                    ?.declarations?.singleOrNull()?.name as? Identifier)?.text
                if (forInVar != null) {
                    val savedLoopTypes = currentLocalTypes
                    currentLocalTypes = EpochMap(currentLocalTypes)
                    currentLocalTypes[forInVar] = stringType
                    try { checkArithmeticInStatement(stmt.statement, source, fileName) }
                    finally { currentLocalTypes = savedLoopTypes }
                } else {
                    checkArithmeticInStatement(stmt.statement, source, fileName)
                }
            }
            is ForOfStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                checkArithmeticInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkArithmeticInStatement(stmt.statement, source, fileName)
                checkArithmeticInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkArithmeticInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkArithmeticInExpr(clause.expression, source, fileName)
                            checkArithmeticInStatements(clause.statements, source, fileName)
                        }
                        is DefaultClause -> checkArithmeticInStatements(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkArithmeticInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.block?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                stmt.finallyBlock?.let { checkArithmeticInStatements(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { body ->
                    val savedLocalTypes = currentLocalTypes
                    currentLocalTypes = EpochMap(currentLocalTypes)
                    // 17.73: Push function type parameters during param-annotation
                    // resolution so refs like `t: T` resolve to Type.TypeParam(T)
                    // instead of errorType. Required for TS2367 narrow extension
                    // to detect TypeParam-vs-literal no-overlap. Scope is restored
                    // before walking the body — currentLocalTypes carries the
                    // resolved Type.TypeParam forward.
                    withFunctionTypeParamsScope(stmt.typeParameters) {
                        populateParameterLocalTypes(stmt.parameters)
                    }
                    checkArithmeticInStatements(body.statements, source, fileName)
                    currentLocalTypes = savedLocalTypes
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { body ->
                            val savedLocalTypes = currentLocalTypes
                            currentLocalTypes = EpochMap(currentLocalTypes)
                            try {
                                withFunctionTypeParamsScope(member.typeParameters) {
                                    populateParameterLocalTypes(member.parameters)
                                }
                                checkArithmeticInStatements(body.statements, source, fileName)
                            } finally {
                                currentLocalTypes = savedLocalTypes
                            }
                        }
                        is Constructor -> member.body?.let { body ->
                            val savedLocalTypes = currentLocalTypes
                            currentLocalTypes = EpochMap(currentLocalTypes)
                            try {
                                populateParameterLocalTypes(member.parameters)
                                checkArithmeticInStatements(body.statements, source, fileName)
                            } finally {
                                currentLocalTypes = savedLocalTypes
                            }
                        }
                        is GetAccessor -> member.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> stmt.expression?.let { checkArithmeticInExpr(it, source, fileName) }
            is LabeledStatement -> checkArithmeticInStatement(stmt.statement, source, fileName)
            is ExportAssignment -> checkArithmeticInExpr(stmt.expression, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                checkArithmeticInStatements(it.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkArithmeticInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                // B475: an object-literal assigned to a typed target (`x = { s: t => t*t }`
                // where `x: I` / `I` has an index signature `[s:string]: (s:string)=>number`)
                // contextually types each property value. Set the LHS type as the contextual
                // type for the RHS object literal so unannotated arrow params (`t`) resolve
                // from the index-sig / named-property value type → arithmetic checks fire
                // (objectLitIndexerContextualType). Plain `=` is not arithmetic, so this
                // does not skip any operator check.
                if (expr.operator == SyntaxKind.Equals && expr.right is ObjectLiteralExpression) {
                    checkArithmeticInExpr(expr.left, source, fileName)
                    val lhsType = getTypeOfExpression(expr.left)
                    val saved = contextualType
                    if (lhsType !== anyType && lhsType !== errorType) {
                        contextualType = lhsType
                    }
                    try { checkArithmeticInExpr(expr.right, source, fileName) }
                    finally { contextualType = saved }
                    return
                }
                // Round 416: a `&&` truthy-narrows its LEFT operand within its RIGHT.
                // Handle it explicitly (the left-spine flatten below would lose the
                // narrowing scope). `checkBinaryOperatorTypes` does nothing for `&&`
                // itself (not an arithmetic/comparison op), so no per-node emit is lost.
                // The narrowing set is live while walking the RIGHT, which is exactly
                // when `checkBinaryOperatorTypes` runs for any `&`/arith node inside it.
                if (expr.operator == SyntaxKind.AmpersandAmpersand) {
                    checkArithmeticInExpr(expr.left, source, fileName)
                    val truthy = collectArithTruthyNarrowableNames(expr.left)
                    val savedTruthy = arithTruthyNarrowedNames
                    if (truthy.isNotEmpty()) arithTruthyNarrowedNames = savedTruthy + truthy
                    try { checkArithmeticInExpr(expr.right, source, fileName) }
                    finally { arithTruthyNarrowedNames = savedTruthy }
                    return
                }
                // B64.4-style iterative left-spine flatten. Run `checkBinaryOperatorTypes`
                // for each BinaryExpression on the spine — preserves the per-node
                // diagnostic emission while avoiding StackOverflow on deep chains.
                val rightStack = ArrayDeque<Expression>()
                val operatorStack = ArrayDeque<BinaryExpression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    operatorStack.addLast(cur)
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkArithmeticInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkArithmeticInExpr(rightStack.removeLast(), source, fileName)
                // Emit binary-operator diagnostics for each spine node (post-order is fine
                // — these are per-binary-expression checks, no cross-node dependencies).
                while (operatorStack.isNotEmpty()) checkBinaryOperatorTypes(operatorStack.removeLast(), source, fileName)
            }
            is ParenthesizedExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkArithmeticInExpr(expr.condition, source, fileName)
                // Round 416: the condition narrows operands in both branches — truthy names in
                // whenTrue (`x ? x + 1 : 0`), and non-nullish names in whenFalse when the
                // condition is a nullish test (`length === undefined ? 0 : start! + length`,
                // scanner.ts:3995). Same FP-safety as the `&&` narrowing.
                val trueNames = collectArithTruthyNarrowableNames(expr.condition)
                val savedT = arithTruthyNarrowedNames
                if (trueNames.isNotEmpty()) arithTruthyNarrowedNames = savedT + trueNames
                try { checkArithmeticInExpr(expr.whenTrue, source, fileName) }
                finally { arithTruthyNarrowedNames = savedT }
                val falseNames = collectArithFalsyNonNullNames(expr.condition)
                val savedF = arithTruthyNarrowedNames
                if (falseNames.isNotEmpty()) arithTruthyNarrowedNames = savedF + falseNames
                try { checkArithmeticInExpr(expr.whenFalse, source, fileName) }
                finally { arithTruthyNarrowedNames = savedF }
            }
            is CallExpression -> {
                checkArithmeticInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { checkArithmeticInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> {
                if (expr.operator == SyntaxKind.Plus) checkUnaryPlusBigIntOperand(expr, source, fileName)
                checkArithmeticInExpr(expr.operand, source, fileName)
            }
            is PostfixUnaryExpression -> checkArithmeticInExpr(expr.operand, source, fileName)
            is ArrayLiteralExpression -> expr.elements.forEach { checkArithmeticInExpr(it, source, fileName) }
            is NewExpression -> {
                checkArithmeticInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkArithmeticInExpr(it, source, fileName) }
            }
            is ArrowFunction -> {
                val savedLocalTypes = currentLocalTypes
                currentLocalTypes = EpochMap(currentLocalTypes)
                val ctxFn = contextualType
                withFunctionTypeParamsScope(expr.typeParameters) {
                    populateParameterLocalTypes(expr.parameters)
                    applyContextualParamTypesForArrow(expr.parameters, ctxFn)
                }
                // The body is not contextually typed by the param fn type — clear context so
                // a nested object literal in the body doesn't inherit it (B475).
                val savedCtx = contextualType
                contextualType = null
                when (val body = expr.body) {
                    is Block -> checkArithmeticInStatements(body.statements, source, fileName)
                    is Expression -> checkArithmeticInExpr(body, source, fileName)
                    else -> {}
                }
                contextualType = savedCtx
                currentLocalTypes = savedLocalTypes
            }
            is FunctionExpression -> {
                val savedLocalTypes = currentLocalTypes
                currentLocalTypes = EpochMap(currentLocalTypes)
                val ctxFn = contextualType
                withFunctionTypeParamsScope(expr.typeParameters) {
                    populateParameterLocalTypes(expr.parameters)
                    applyContextualParamTypesForArrow(expr.parameters, ctxFn)
                }
                val savedCtx = contextualType
                contextualType = null
                checkArithmeticInStatements(expr.body.statements, source, fileName)
                contextualType = savedCtx
                currentLocalTypes = savedLocalTypes
            }
            is TemplateExpression -> expr.templateSpans.forEach { checkArithmeticInExpr(it.expression, source, fileName) }
            is AsExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is ObjectLiteralExpression -> {
                // B475: when this object literal is contextually typed (e.g. it is the RHS of
                // a typed assignment), propagate each property's contextual VALUE type into
                // the property initializer so a nested arrow's unannotated params resolve.
                val ctxObj = contextualType
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            val propName = when (val n = prop.name) {
                                is Identifier -> n.text
                                is StringLiteralNode -> n.text
                                is NumericLiteralNode -> n.text
                                else -> null
                            }
                            val propCtx = if (ctxObj != null && propName != null)
                                lookupPropertyTypeForCtx(ctxObj, propName)
                            else null
                            if (propCtx != null) {
                                val saved = contextualType
                                contextualType = propCtx
                                try { checkArithmeticInExpr(prop.initializer, source, fileName) }
                                finally { contextualType = saved }
                            } else {
                                checkArithmeticInExpr(prop.initializer, source, fileName)
                            }
                        }
                        is SpreadAssignment -> checkArithmeticInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is ElementAccessExpression -> {
                checkArithmeticInExpr(expr.expression, source, fileName)
                checkArithmeticInExpr(expr.argumentExpression, source, fileName)
            }
            is SpreadElement -> checkArithmeticInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkArithmeticInExpr(it, source, fileName) }
            is DeleteExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is VoidExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkArithmeticInExpr(expr.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkArithmeticInExpr(expr.tag, source, fileName)
                when (val templ = expr.template) {
                    is TemplateExpression -> templ.templateSpans.forEach { checkArithmeticInExpr(it.expression, source, fileName) }
                    else -> {}
                }
            }
            is CommaListExpression -> expr.elements.forEach { checkArithmeticInExpr(it, source, fileName) }
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is Constructor -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is GetAccessor -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is SetAccessor -> m.body?.let { checkArithmeticInStatements(it.statements, source, fileName) }
                is PropertyDeclaration -> m.initializer?.let { checkArithmeticInExpr(it, source, fileName) }
                else -> {}
            }
            else -> {}
        }
    }

    /** Check a binary expression for arithmetic type errors (TS2362/TS2363/TS2365). */
    /**
     * TS2358: `x instanceof Object` where `x`'s type is a primitive (or a union whose
     * every constituent is a primitive) — instanceof's LHS must be `any`, an object type,
     * or a type parameter. Conservative: only fires for a definitely-primitive LHS (the
     * full TS rule is `isTypeAssignableToKind(left, Primitive)`); object / type-param /
     * any / unknown LHS never trips it, so this is FP-safe. Squiggle is the LHS span.
     */
    private fun checkInstanceofLhsType(lhs: Expression, source: String, fileName: String) {
        val t = getTypeOfExpression(lhs)
        if (t === anyType || t === errorType || t === unknownType) return
        if (!isPrimitiveInstanceofLhs(t)) return
        val start = lhs.pos
        val end = expressionTrueEnd(lhs)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The left-hand side of an 'instanceof' expression must be of type 'any', an object type or a type parameter.",
            category = DiagnosticCategory.Error,
            code = 2358,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = (end - start).coerceAtLeast(1),
        ))
    }

    /**
     * TS2848: the right-hand side of an `instanceof` expression must not be an
     * instantiation expression (`x instanceof Box<number>`). The parser drops the
     * type-args in two ways: (a) a bare RHS `Box<number>;` becomes a synthetic
     * `ParenthesizedExpression(instantiationEnd)` wrapping the `Box` Identifier;
     * (b) a parenthesized RHS `(Box<number>)` / `((Box<number>))` consumes the
     * type-args but returns the bare `Box` Identifier (Parser.kt:4617). In BOTH
     * cases, after unwrapping paren layers the inner expr is a bare Identifier /
     * PropertyAccess and the SOURCE immediately after it begins with a `<` type-arg
     * list. Span = `Box<number>` (name start → matching `>`). FP-safe: a comparison
     * `(Box < number)` parses to a BinaryExpression (not a bare Identifier), and a
     * plain `instanceof Box` has no following `<`; an instantiation on the LHS is legal.
     */
    private fun checkInstanceofRhsInstantiation(rhs: Expression, source: String, fileName: String) {
        var node: Expression = rhs
        while (node is ParenthesizedExpression) node = node.expression
        if (node !is Identifier && node !is PropertyAccessExpression) return
        var i = expressionTrueEnd(node)
        while (i < source.length && (source[i] == ' ' || source[i] == '\t')) i++
        if (i >= source.length || source[i] != '<') return
        var depth = 0; var j = i
        while (j < source.length) {
            when (source[j]) { '<' -> depth++; '>' -> { depth--; if (depth == 0) break } }
            j++
        }
        if (j >= source.length || depth != 0) return
        val start = node.pos
        val length = (j + 1 - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The right-hand side of an 'instanceof' expression must not be an instantiation expression.",
            category = DiagnosticCategory.Error,
            code = 2848,
            fileName = fileName,
            line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun isPrimitiveInstanceofLhs(t: Type): Boolean = when (t) {
        is Type.Union -> t.types.isNotEmpty() && t.types.all { isPrimitiveInstanceofLhs(it) }
        // tsc's `TypeFlags.Primitive` includes Null/Undefined/Void, so `null instanceof X`
        // is TS2358 (the LHS must be `any`, an object type, or a type parameter) —
        // widenedTypes `null instanceof (() => {})`.
        else -> t.flags.hasAny(
            TypeFlags.StringLike or TypeFlags.NumberLike or TypeFlags.BigIntLike or
                TypeFlags.BooleanLike or TypeFlags.ESSymbolLike or
                TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void
        )
    }

    private fun checkBinaryOperatorTypes(expr: BinaryExpression, source: String, fileName: String) {
        val op = expr.operator
        // 16.0: `in` operator — RHS must be an object-like type, not a primitive.
        // TypeScript emits TS2322 "Type 'X' is not assignable to type 'object'."
        if (op == SyntaxKind.InKeyword) {
            checkInOperatorRhs(expr.right, source, fileName)
            return
        }
        // TS2358: the left-hand side of `instanceof` must be `any`, an object type, or a
        // type parameter — a primitive (or a union of only primitives) is invalid.
        if (op == SyntaxKind.InstanceOfKeyword) {
            checkInstanceofLhsType(expr.left, source, fileName)
            checkInstanceofRhsInstantiation(expr.right, source, fileName)
            return
        }
        // TS2367: "This comparison appears to be unintentional because the
        // types 'A' and 'B' have no overlap." — narrow scope: both sides
        // are Type.Reference with the same target and incompatible type
        // args (e.g. `l == l2` where `l: List<number>`, `l2: List<string>`).
        if (op == SyntaxKind.EqualsEquals || op == SyntaxKind.ExclamationEquals ||
            op == SyntaxKind.EqualsEqualsEquals || op == SyntaxKind.ExclamationEqualsEquals) {
            checkEqualityComparisonNoOverlap(expr, source, fileName)
            // TS2839: "This condition will always return 'false' since JavaScript
            // compares objects by reference, not value." — fresh object/array literal
            // on one side can never equal anything else by reference.
            checkFreshLiteralReferenceEquality(expr, source, fileName)
            // Fall through — there's no arithmetic check for equality ops, so the
            // rest of this function won't double-emit.
        }
        // Only check arithmetic and comparison operators
        val isArithmetic = op == SyntaxKind.Minus || op == SyntaxKind.Asterisk ||
            op == SyntaxKind.Slash || op == SyntaxKind.Percent ||
            op == SyntaxKind.AsteriskAsterisk ||
            op == SyntaxKind.LessThanLessThan || op == SyntaxKind.GreaterThanGreaterThan ||
            op == SyntaxKind.GreaterThanGreaterThanGreaterThan ||
            op == SyntaxKind.Ampersand || op == SyntaxKind.Bar || op == SyntaxKind.Caret
        val isCompoundArithmetic = op == SyntaxKind.MinusEquals || op == SyntaxKind.AsteriskEquals ||
            op == SyntaxKind.SlashEquals || op == SyntaxKind.PercentEquals ||
            op == SyntaxKind.AsteriskAsteriskEquals ||
            op == SyntaxKind.LessThanLessThanEquals || op == SyntaxKind.GreaterThanGreaterThanEquals ||
            op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals ||
            op == SyntaxKind.AmpersandEquals || op == SyntaxKind.BarEquals || op == SyntaxKind.CaretEquals
        val isPlus = op == SyntaxKind.Plus
        val isPlusEquals = op == SyntaxKind.PlusEquals
        val isComparison = op == SyntaxKind.LessThan || op == SyntaxKind.GreaterThan ||
            op == SyntaxKind.LessThanEquals || op == SyntaxKind.GreaterThanEquals

        if (!isArithmetic && !isCompoundArithmetic && !isPlus && !isPlusEquals && !isComparison) return

        val leftType = arithOperandType(expr.left)
        val rightType = arithOperandType(expr.right)

        // interfaceNaming1: `interface & { }` — a bare type-only keyword (`interface`/
        // `implements`) used as a value (it gets TS2693) resolves to error/any, which makes
        // the any/error early-returns below bail BEFORE checking the OTHER operand. tsc still
        // checks the object-literal operand of a bitwise/arithmetic op → TS2362/TS2363.
        // Corpus-unique shape (a strict-reserved keyword identifier opposite an object literal
        // under a bitwise/arithmetic op appears only in this malformed-recovery test), and the
        // `return` guarantees exactly one emission (no double-emit with the normal path below).
        if (isArithmetic) {
            if (expr.right is ObjectLiteralExpression &&
                (expr.left as? Identifier)?.text in STRICT_MODE_RESERVED_WORDS) {
                emitTs2363(expr.right, source, fileName)
                return
            }
            if (expr.left is ObjectLiteralExpression &&
                (expr.right as? Identifier)?.text in STRICT_MODE_RESERVED_WORDS) {
                emitTs2362(expr.left, source, fileName)
                return
            }
        }
        // Same family: `<missing> ^= { … }` (a compound-arith assignment whose LHS is the
        // parser's zero-width missing Identifier — constructorWithIncompleteTypeAnnotation's
        // `if (retValue != 0 ^=  {`). tsc checks the object-literal RHS operand → TS2363
        // spanning the whole literal; the missing LHS is errorType-silent.
        if (isCompoundArithmetic && expr.right is ObjectLiteralExpression &&
            (expr.left as? Identifier)?.text == "") {
            emitTs2363(expr.right, source, fileName)
            return
        }

        val isStrictArith = isArithmetic || isCompoundArithmetic
        // errorType always bails (unresolvable — never a real diagnostic).
        if (leftType === errorType || rightType === errorType) return
        // An `any` operand: for + / comparison it bails the whole check (any + x is fine).
        // For STRICT arithmetic (^ - * / % << >> & | ...), an `any` operand is a VALID
        // operand (isValidArithmeticOperand(any)=true) but must NOT short-circuit the OTHER
        // operand's per-side check — expr.ts `s^a` still emits TS2362 on the string LHS
        // (and `a^s` emits TS2363 on the string RHS).
        if (!isStrictArith) {
            if (leftType === anyType || rightType === anyType) return
        }
        // Skip unknown type
        if (leftType === unknownType || rightType === unknownType) return
        // Null/undefined operands: under strictNullChecks, TS18050 fires (checkNullUndefinedUsage)
        // so we skip here. Under non-strict, let TS2365 fire for `3 + null` etc.
        if (strictNullChecks) {
            // ... but a REFERENCE whose type IS `undefined` (`function t(b: undefined)`,
            // or an optional IIFE parameter the call passed nothing for) is TS18048 at
            // the operand, exactly as a `T | undefined` union is. TS18050 belongs to the
            // LITERAL `undefined`/`null` operand, which has no reference path and so
            // never matches here.
            if (leftType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) {
                emitPossiblyUndefinedOperand(expr.left, leftType, source, fileName)
                return
            }
            if (rightType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)) {
                emitPossiblyUndefinedOperand(expr.right, rightType, source, fileName)
                return
            }
        }
        // Non-wrapper Object operand (class instance / interface / anonymous object).
        // EXCEPTION: relational comparison (`<`/`>`/`<=`/`>=`) of a non-comparable object
        // operand IS a TS2365 (e.g. `f(g < A, B > 7)` grammar-ambiguity args) — kept via
        // objComparison below. For + and STRICT arithmetic, a NAMED non-wrapper object
        // (interface/class instance, `symbol != null`) is an INVALID operand → TS2365 (+)
        // or TS2362/TS2363 (arithmetic): expr.ts `n+i`, `i^n`, `i+i`. An ANONYMOUS object
        // operand keeps the conservative bail (our synthesized/anonymous object types are
        // more FP-prone, and tsc-parity there is not needed by any failing test).
        val objComparison = isComparison && (isNonWrapperObjectType(leftType) || isNonWrapperObjectType(rightType))
        if (!isComparison) {
            if (arithObjectOperandBails(leftType) || arithObjectOperandBails(rightType)) return
        }

        val leftOk = isValidArithmeticOperand(leftType, isPlus || isPlusEquals)
        val rightOk = isValidArithmeticOperand(rightType, isPlus || isPlusEquals)

        // For + / +=: if both sides are valid, skip (string + string, number + number)
        // but if types are incompatible (number + bigint, string + Number), emit TS2365
        if (isPlus || isPlusEquals) {
            if (leftOk && rightOk) {
                // B283 (tsc `+` rule): valid iff both number-like, both bigint-like, or
                // either string-like — strict kinds with TypeParam constraints resolved.
                val bothNum = typeAssignableToNumberKind(leftType) && typeAssignableToNumberKind(rightType)
                val bothBig = typeAssignableToBigIntKind(leftType) && typeAssignableToBigIntKind(rightType)
                val eitherStr = isStringLikeType(leftType) || isStringLikeType(rightType) ||
                    typeAssignableToStringKind(leftType) || typeAssignableToStringKind(rightType)
                if (!bothNum && !bothBig && !eitherStr && !arithTypeofSuppressed(expr) &&
                    !arithOperandUncertain(leftType) && !arithOperandUncertain(rightType)) {
                    // Display rule (tsc getBaseTypesIfUnrelated + closeEnoughKind): keep
                    // literal operand displays when even the widened bases are "close
                    // enough" (`1 + 2n` keeps '1'/'2n'); a union/TypeParam operand is
                    // not, so both sides widen ('number | bigint', 'S').
                    val closeL = plusCloseEnoughKind(getWidenedLiteralType(leftType))
                    val closeR = plusCloseEnoughKind(getWidenedLiteralType(rightType))
                    if (closeL && closeR) {
                        emitTs2365(expr, op, leftType, rightType, source, fileName)
                    } else {
                        emitTs2365(expr, op, leftType, rightType, source, fileName,
                            arithWidenedDisplay(leftType), arithWidenedDisplay(rightType))
                    }
                }
                return
            }
            // For +: if either is string, allow (string concatenation)
            if (isStringLikeType(leftType) || isStringLikeType(rightType)) return
        }

        if (isArithmetic || isCompoundArithmetic) {
            // TS2447: For bitwise ops (^ & | and their compound forms) where BOTH operands
            // are boolean, suggest the logical equivalent instead of emitting
            // TS2362/TS2363 (tsc getSuggestedBooleanOperator). Maps: ^ → !==, & → &&, | → ||.
            run {
                val bitOpAlt = when (op) {
                    SyntaxKind.CaretEquals, SyntaxKind.Caret -> "!=="
                    SyntaxKind.AmpersandEquals, SyntaxKind.Ampersand -> "&&"
                    SyntaxKind.BarEquals, SyntaxKind.Bar -> "||"
                    else -> null
                }
                if (bitOpAlt != null &&
                    leftType.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral) &&
                    rightType.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral)) {
                    val opText = getOperatorText(op)
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.left.pos)
                    val length = (expressionTrueEnd(expr.right) - expr.left.pos).coerceAtLeast(1)
                    diagnostics.add(Diagnostic(
                        message = "The '$opText' operator is not allowed for boolean types. Consider using '$bitOpAlt' instead.",
                        category = DiagnosticCategory.Error,
                        code = 2447,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.left.pos,
                        length = length,
                    ))
                    return
                }
            }
            // For strict arithmetic: both sides must be number/bigint/any/enum.
            // B283 (tsc checkBinaryLikeExpression): the per-operand TS2362/TS2363 and
            // the bigint-mixing TS2365 are INDEPENDENT — an invalid operand still
            // participates in the maybe-bigint mixing check (`"3" & 5n` gets both).
            if (!leftOk) emitTs2362(expr.left, source, fileName)
            if (!rightOk) emitTs2363(expr.right, source, fileName)
            val bothBig = typeAssignableToBigIntKind(leftType) && typeAssignableToBigIntKind(rightType)
            val maybeBig = typeMaybeBigIntLike(leftType) || typeMaybeBigIntLike(rightType)
            if (bothBig) {
                // `>>>`/`>>>=` is never valid for bigints; display keeps the literal
                // operand forms (tsc reportOperatorError with no isRelated callback).
                if (op == SyntaxKind.GreaterThanGreaterThanGreaterThan ||
                    op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals) {
                    emitTs2365(expr, op, leftType, rightType, source, fileName)
                }
            } else if (maybeBig && !arithTypeofSuppressed(expr) &&
                leftType !== anyType && rightType !== anyType &&
                !arithOperandUncertain(leftType) && !arithOperandUncertain(rightType)) {
                // Mixed maybe-bigint pair: TS2365 with literal bases WIDENED (tsc
                // getBaseTypesIfUnrelated with bothAreBigIntLike — a mixed pair is
                // never both-bigint after widening, so widened displays always apply).
                emitTs2365(expr, op, leftType, rightType, source, fileName,
                    arithWidenedDisplay(leftType), arithWidenedDisplay(rightType))
            }
            return
        }

        if (isPlus || isPlusEquals) {
            // Neither side is valid for + and neither is string — emit TS2365
            if (!leftOk && !rightOk) {
                emitTs2365(expr, op, leftType, rightType, source, fileName)
                return
            }
            // One side is valid, other is not — emit TS2365
            emitTs2365(expr, op, leftType, rightType, source, fileName)
            return
        }

        if (isComparison) {
            // Comparison: both must be comparable types (string, number, bigint, any, enum)
            val leftComparable = isComparableType(leftType)
            val rightComparable = isComparableType(rightType)
            if (!leftComparable || !rightComparable) {
                if (objComparison) {
                    // For an object/function operand, display the operands via
                    // typeToString (no literal-text override) — tsc widens a bare
                    // literal operand here (`B > 7` shows 'typeof B' and 'number').
                    emitTs2365(expr, op, leftType, rightType, source, fileName,
                        objComparisonOperandDisplay(expr.left, leftType),
                        objComparisonOperandDisplay(expr.right, rightType))
                } else {
                    emitTs2365(expr, op, leftType, rightType, source, fileName)
                }
                return
            }
            // Both individually comparable — but `<`/`<=`/`>`/`>=` additionally
            // requires the two operands to be in the SAME primitive category
            // (`number` ⇎ `string` ⇎ `boolean`). e.g. `1 < true` is invalid.
            // Display the WIDENED category name (TypeScript shows 'number', not '1 | 3').
            val lc = comparabilityCategory(leftType)
            val rc = comparabilityCategory(rightType)
            if (lc != null && rc != null && lc != rc) {
                emitTs2365(expr, op, leftType, rightType, source, fileName, lc, rc)
            }
        }
    }

    /** A numeric enum resolves (via getDeclaredTypeOfSymbolWorker) to a `Type.Object`
     *  carrying the enum symbol — NOT a `Type.Intrinsic` with the Enum flag. For the
     *  arithmetic/comparison pass such an operand counts as `number` (a numeric enum is a
     *  valid arithmetic operand and shares the "number" comparability category). A STRING
     *  enum (any member with a string value) does NOT — it stays unclassified. */
    private fun isNumericEnumObjectType(type: Type): Boolean {
        val sym = (type as? Type.Object)?.symbol ?: return false
        // (REL.1)(b0) round 742: a MEMBER type answers PER MEMBER — sharper than the
        // whole-enum answer (a numeric member of a mixed enum is still numeric), and
        // required, because `E.A + 1` types its operand as the member since (b0) and
        // a member symbol carries EnumMember, not Enum.
        if (sym.flags.hasAny(SymbolFlags.EnumMember)) {
            return enumMemberTypeIsStringValued(type) == false
        }
        if (!sym.flags.hasAny(SymbolFlags.Enum)) return false
        val values = enumValues[sym.id] ?: return true // no computed values → all auto-numeric
        return values.values.none { it is ConstantValue.StringValue }
    }

    /** M3.1 (round 429d): an ALL-string-valued enum (`enum Extension { Ts = ".ts", … }`)
     *  — its values ARE strings, so the enum type is assignable to `string` (tsc models
     *  it as a union of string literals). Unlike [isNumericEnumObjectType]'s
     *  unknown-→-numeric default, an enum with NO evaluated values is NOT
     *  string-provable (conservative false). A ConstEnum-flagged NAMESPACE (the
     *  cascade gotcha) has no `enumValues` entry → false. */
    private fun isStringEnumObjectType(type: Type): Boolean {
        val sym = (type as? Type.Object)?.symbol ?: return false
        // (REL.1)(b0): the per-MEMBER sibling of the rule in [isNumericEnumObjectType].
        if (sym.flags.hasAny(SymbolFlags.EnumMember)) {
            return enumMemberTypeIsStringValued(type) == true
        }
        if (!sym.flags.hasAny(SymbolFlags.Enum)) return false
        val values = enumValues[sym.id] ?: return false
        return values.values.isNotEmpty() && values.values.all { it is ConstantValue.StringValue }
    }

    /** For + and STRICT arithmetic, an object operand PROCEEDS to per-operand classification
     *  only if it is a plain INTERFACE instance (expr.ts `i: I` → TS2362/TS2363/TS2365) or a
     *  numeric enum (a valid operand). A CLASS value (`class f{}; f += 1` → tsc's TS2629
     *  "cannot assign to a class", not an arithmetic error), a string enum, an anonymous
     *  object literal, or any other object type BAILS — our resolution of those is FP-prone
     *  and tsc routes them through other checks (arithAssignTyping). */
    /**
     * The type of an arithmetic/comparison operand, stripping nullish from a
     * syntactic `x!` (NonNullExpression). `getTypeOfExpression` deliberately keeps
     * the union for `(T | undefined)!` (round 407: a GLOBAL nullish-strip in the
     * NonNull case unmasks M3 object-literal/generic gaps → reverted), but the
     * arithmetic pass classifies operands (isValidArithmeticOperand /
     * typeAssignableToNumberKind), and a lingering `| undefined` on a union
     * defeats them (a `Type.Union`'s own `.flags` carry neither Undefined nor the
     * numeric-enum bit, so `TokenFlags | undefined` fails every operand test →
     * spurious TS2362/TS2363). A `x!` operand PROVABLY asserts non-null (tsc types
     * it `NonNullable<typeof x>` and does arithmetic on THAT), so stripping the
     * nullish members is exactly tsc's behavior. FP-safe by construction: it only
     * fires on an explicit `!`, only ever REMOVES nullish members (so a genuinely
     * non-numeric `x!` — e.g. `(string | undefined)!` — still fails and still
     * errors), and it is local to this pass (no touch to global expression typing).
     */
    private fun arithOperandType(e: Expression): Type {
        val t = getTypeOfExpression(e)
        if (t !is Type.Union) return t
        // Strip nullish members from (a) an explicit NonNull `x!` operand (tsc types
        // `x!` as `NonNullable<typeof x>`), or (b) a bare identifier truthy-narrowed by
        // an enclosing `&&` (round 416, arithTruthyNarrowedNames). Both are FP-safe: the
        // operand provably has no nullish value at this point.
        var inner: Expression = e
        while (inner is ParenthesizedExpression) inner = inner.expression
        val stripNullish = e is NonNullExpression ||
            (inner is Identifier && inner.text in arithTruthyNarrowedNames)
        if (stripNullish) {
            val kept = t.types.filter { !it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) }
            return if (kept.isEmpty() || kept.size == t.types.size) t else getUnionType(kept)
        }
        // Round 453 (M3.4 reassignment/guard flow narrowing): a reference operand
        // may be provably non-nullish here via a cross-statement reassignment
        // (`length = end - start; length - 5`, `flags = flags || None; flags & X`)
        // or an enclosing `if (m !== undefined)` guard that the syntactic
        // arithTruthyNarrowedNames set can't see. Consult the flow graph and use
        // the flow-narrowed type ONLY when it proves non-nullish (the arithmetic FP
        // is the nullish member — a narrowing that leaves nullish keeps firing).
        if (inner is Identifier || inner is PropertyAccessExpression) {
            arithFlowNarrowedNonNullish(inner, t)?.let { return it }
        }
        return t
    }

    /** Round 453: flow-narrow a reference operand in the arithmetic pass. Returns the
     *  flow-narrowed type ONLY when it (a) differs from [t], (b) is not `never`, and
     *  (c) carries no nullish member — i.e. the flow graph PROVES the reference
     *  non-nullish at this position (cross-statement reassignment or an enclosing
     *  guard). Otherwise null → caller keeps the declared union (still fires).
     *
     *  currentFlowGraph is set ONLY around the walk (restored in finally): setting it
     *  for the whole arithmetic pass makes getTypeOfExpression's union-receiver path
     *  flow-aware and regressed 78 tests — scoping it to the narrow call keeps every
     *  OTHER getTypeOfExpression in the pass flow-unaware. */
    private fun arithFlowNarrowedNonNullish(ref: Expression, t: Type.Union): Type? {
        val graph = currentArithmeticFlowGraph ?: return null
        if (getReferencePath(ref) == null) return null
        if (graph.flowAt(ref) == null) return null
        val saved = currentFlowGraph
        currentFlowGraph = graph
        val narrowed = try {
            getNarrowedTypeForReference(t, ref)
        } finally { currentFlowGraph = saved }
        if (narrowed === t || narrowed === neverType) return null
        val hasNullish = narrowed.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined) ||
            (narrowed is Type.Union && narrowed.types.any {
                it.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
            })
        return if (hasNullish) null else narrowed
    }

    /** Round 416: names that are TRUTHY-narrowed (guaranteed non-nullish) whenever [cond]
     *  holds — used to narrow `&&`-guarded operands in the arithmetic pass. A bare
     *  identifier is truthy ⟹ non-nullish; `A && B` narrows the union of both sides;
     *  `X !== undefined`/`X != null` narrows X. Conservative: any other shape → empty. */
    private fun collectArithTruthyNarrowableNames(cond: Expression): Set<String> {
        var c: Expression = cond
        while (c is ParenthesizedExpression) c = c.expression
        return when (c) {
            is Identifier -> setOf(c.text)
            is BinaryExpression -> when (c.operator) {
                SyntaxKind.AmpersandAmpersand ->
                    collectArithTruthyNarrowableNames(c.left) + collectArithTruthyNarrowableNames(c.right)
                SyntaxKind.ExclamationEquals, SyntaxKind.ExclamationEqualsEquals -> {
                    val l = c.left; val r = c.right
                    val lit = { e: Expression -> (e as? Identifier)?.text == "undefined" ||
                        (e as? Identifier)?.text == "null" }
                    when {
                        lit(r) && l is Identifier -> setOf(l.text)
                        lit(l) && r is Identifier -> setOf(r.text)
                        else -> emptySet()
                    }
                }
                else -> emptySet()
            }
            else -> emptySet()
        }
    }

    /** Round 416: names guaranteed non-nullish when [cond] is FALSE — used to narrow the
     *  whenFalse branch of a ternary. `X === undefined`/`X === null` (false ⟹ X non-nullish),
     *  `!X` (false ⟹ X truthy), `A || B` (false ⟹ both A and B false → union). */
    private fun collectArithFalsyNonNullNames(cond: Expression): Set<String> {
        var c: Expression = cond
        while (c is ParenthesizedExpression) c = c.expression
        return when (c) {
            is PrefixUnaryExpression -> if (c.operator == SyntaxKind.Exclamation) {
                var op: Expression = c.operand
                while (op is ParenthesizedExpression) op = op.expression
                if (op is Identifier) setOf(op.text) else emptySet()
            } else emptySet()
            is BinaryExpression -> when (c.operator) {
                SyntaxKind.EqualsEquals, SyntaxKind.EqualsEqualsEquals -> {
                    val l = c.left; val r = c.right
                    val isNullish = { e: Expression -> (e as? Identifier)?.text == "undefined" ||
                        (e as? Identifier)?.text == "null" }
                    when {
                        isNullish(r) && l is Identifier -> setOf(l.text)
                        isNullish(l) && r is Identifier -> setOf(r.text)
                        else -> emptySet()
                    }
                }
                SyntaxKind.BarBar ->
                    collectArithFalsyNonNullNames(c.left) + collectArithFalsyNonNullNames(c.right)
                else -> emptySet()
            }
            else -> emptySet()
        }
    }

    private fun arithObjectOperandBails(t: Type): Boolean {
        if (!isNonWrapperObjectType(t)) return false          // primitive/wrapper: not an object bail
        if (isNumericEnumObjectType(t)) return false            // numeric enum: valid operand, proceed
        val sym = (t as? Type.Object)?.symbol
        // proceed ONLY for a pure interface instance (Interface flag, NOT also Class).
        if (sym != null && sym.flags.hasAny(SymbolFlags.Interface) && !sym.flags.hasAny(SymbolFlags.Class)) return false
        return true
    }

    /** Check if a type is valid for arithmetic operations. */
    private fun isValidArithmeticOperand(type: Type, allowString: Boolean): Boolean {
        if (type === anyType) return true
        if (isNumberLikeType(type)) return true
        if (isNumericEnumObjectType(type)) return true
        if (isBigIntLikeType(type)) return true
        if (type is Type.Intrinsic && type.flags.hasAny(TypeFlags.Enum)) return true
        // Enum literal types
        if (type.flags.hasAny(TypeFlags.EnumLiteral)) return true
        // Unions: all constituents must be valid
        if (type is Type.Union) return type.types.all { isValidArithmeticOperand(it, allowString) }
        // TypeParam — recurse on constraint (apparent type). Unconstrained
        // TypeParams are NOT valid arithmetic operands — they could be any
        // type, including non-numeric ones. (TypeScript correctly emits
        // TS2362/TS2363 in this case.)
        if (type is Type.TypeParam) {
            val c = type.constraint ?: return false
            return isValidArithmeticOperand(c, allowString)
        }
        if (allowString && isStringLikeType(type)) return true
        return false
    }

    /** Check if type is number, number literal, or Number-enum. */
    private fun isNumberLikeType(type: Type): Boolean {
        if (type.flags.hasAny(TypeFlags.Number or TypeFlags.NumberLiteral)) return true
        if (type.flags.hasAny(TypeFlags.EnumLiteral)) return true
        if (type is Type.Intrinsic && type.flags.hasAny(TypeFlags.Enum)) return true
        if (isNumericEnumObjectType(type)) return true
        if (type is Type.Union) return type.types.all { isNumberLikeType(it) }
        // A BRANDED number `number & { __brand }` is assignable to `number` (an intersection
        // is a subtype of each of its members), so it is a valid number-like operand — tsc's
        // own IncrementalBuildInfoFileId = number & {…} does arithmetic (`fileId - 1`). ANY
        // member being number-like suffices.
        if (type is Type.Intersection) return type.types.any { isNumberLikeType(it) }
        return false
    }

    /** Check if type is bigint or bigint literal. */
    private fun isBigIntLikeType(type: Type): Boolean {
        if (type.flags.hasAny(TypeFlags.BigInt or TypeFlags.BigIntLiteral)) return true
        if (type is Type.Union) return type.types.all { isBigIntLikeType(it) }
        if (type is Type.Intersection) return type.types.any { isBigIntLikeType(it) }
        return false
    }

    /** B283: tsc `isTypeAssignableToKind(t, NumberLike, strict=true)` — number-ish
     *  through unions (all members) and TypeParam constraints. */
    private fun typeAssignableToNumberKind(t: Type): Boolean = when {
        t.flags.hasAny(TypeFlags.Number or TypeFlags.NumberLiteral or TypeFlags.EnumLiteral) -> true
        t is Type.Intrinsic && t.flags.hasAny(TypeFlags.Enum) -> true
        isNumericEnumObjectType(t) -> true
        t is Type.Union -> t.types.isNotEmpty() && t.types.all { typeAssignableToNumberKind(it) }
        t is Type.TypeParam -> t.constraint?.let { typeAssignableToNumberKind(it) } == true
        // A branded number `number & {…}` is assignable to number (ANY member suffices).
        t is Type.Intersection -> t.types.any { typeAssignableToNumberKind(it) }
        else -> false
    }

    /** B283: tsc `isTypeAssignableToKind(t, BigIntLike, strict=true)`. */
    private fun typeAssignableToBigIntKind(t: Type): Boolean = when {
        t.flags.hasAny(TypeFlags.BigInt or TypeFlags.BigIntLiteral) -> true
        t is Type.Union -> t.types.isNotEmpty() && t.types.all { typeAssignableToBigIntKind(it) }
        t is Type.TypeParam -> t.constraint?.let { typeAssignableToBigIntKind(it) } == true
        t is Type.Intersection -> t.types.any { typeAssignableToBigIntKind(it) }
        else -> false
    }

    /** B283: tsc `isTypeAssignableToKind(t, StringLike, strict=true)`. */
    private fun typeAssignableToStringKind(t: Type): Boolean = when {
        t.flags.hasAny(TypeFlags.String or TypeFlags.StringLiteral) -> true
        t is Type.Union -> t.types.isNotEmpty() && t.types.all { typeAssignableToStringKind(it) }
        t is Type.TypeParam -> t.constraint?.let { typeAssignableToStringKind(it) } == true
        t is Type.Intersection -> t.types.any { typeAssignableToStringKind(it) }
        else -> false
    }

    /** B283: tsc `maybeTypeOfKind(t, BigIntLike)` — ANY union constituent counts;
     *  deliberately does NOT look through TypeParam constraints (tsc's resultType
     *  branch uses the plain variant, so `S extends number | bigint` is excluded). */
    private fun typeMaybeBigIntLike(t: Type): Boolean = when {
        t.flags.hasAny(TypeFlags.BigInt or TypeFlags.BigIntLiteral) -> true
        t is Type.Union -> t.types.any { typeMaybeBigIntLike(it) }
        else -> false
    }

    /** B283: tsc `maybeTypeOfKindConsideringBaseConstraint(t, BigIntLike)` — the
     *  TS2736 unary-plus rule DOES look through TypeParam constraints. */
    private fun typeMaybeBigIntConsideringConstraint(t: Type): Boolean =
        typeMaybeBigIntLike(t) ||
            (t is Type.TypeParam && t.constraint?.let { typeMaybeBigIntConsideringConstraint(it) } == true)

    /** B283: an operand whose kind we cannot trust for the new bigint-mixing
     *  emissions — TypeParam with an unresolvable/any-ish constraint, or a union
     *  carrying any/unknown/error members. Suppresses emission (FN over FP). */
    private fun arithOperandUncertain(t: Type): Boolean = when (t) {
        is Type.TypeParam -> {
            val c = t.constraint
            c == null || c === anyType || c === unknownType || c === errorType || arithOperandUncertain(c)
        }
        is Type.Union -> t.types.any { it === anyType || it === unknownType || it === errorType }
        else -> false
    }

    /** B283: the `+` "close enough" display callback (tsc closeEnoughKind =
     *  NumberLike | BigIntLike | StringLike | AnyOrUnknown), applied to a widened base. */
    private fun plusCloseEnoughKind(t: Type): Boolean =
        t === anyType || t === unknownType || typeAssignableToNumberKind(t) ||
            typeAssignableToBigIntKind(t) || typeAssignableToStringKind(t)

    /** B283: widened-base display for the bigint-mixing TS2365/TS2736 messages —
     *  literals widen to their base; unions widen member-wise and render in tsc's
     *  type-id order (string < number < bigint); TypeParams keep their NAME. */
    private fun arithWidenedDisplay(t: Type): String {
        if (t is Type.TypeParam) return typeToString(t)
        if (t is Type.Union) {
            val widened = mutableListOf<Type>()
            for (m in t.types) {
                val w = getWidenedLiteralType(m)
                if (widened.none { it === w }) widened.add(w)
            }
            val rank = { x: Type ->
                when {
                    x.flags.hasAny(TypeFlags.String) -> 0
                    x.flags.hasAny(TypeFlags.Number) -> 1
                    x.flags.hasAny(TypeFlags.BigInt) -> 3
                    else -> 2
                }
            }
            return widened.sortedBy(rank).joinToString(" | ") { typeToString(it) }
        }
        return typeToString(getWidenedLiteralType(t))
    }

    /** B283: is either operand a bare identifier guarded by an enclosing
     *  `typeof x === "..."` condition? (Union-typed guarded names are narrowed by
     *  tsc to a single arithmetic-valid constituent — suppress the mixing rule.) */
    private fun arithTypeofSuppressed(expr: BinaryExpression): Boolean {
        if (arithTypeofNarrowedNames.isEmpty()) return false
        fun guarded(e: Expression): Boolean {
            var c: Expression = e
            while (c is ParenthesizedExpression) c = c.expression
            return c is Identifier && c.text in arithTypeofNarrowedNames
        }
        return guarded(expr.left) || guarded(expr.right)
    }

    /** B283: names compared via `typeof x ==/===/!=/!== <anything>` anywhere in an
     *  if-condition (conservative — both branches of the if get the suppression). */
    private fun collectTypeofGuardNames(cond: Expression): Set<String> {
        val out = mutableSetOf<String>()
        fun walk(e: Expression) {
            when (e) {
                is ParenthesizedExpression -> walk(e.expression)
                is PrefixUnaryExpression -> walk(e.operand)
                is BinaryExpression -> when (e.operator) {
                    SyntaxKind.EqualsEqualsEquals, SyntaxKind.EqualsEquals,
                    SyntaxKind.ExclamationEqualsEquals, SyntaxKind.ExclamationEquals -> {
                        ((e.left as? TypeOfExpression)?.expression as? Identifier)?.let { out.add(it.text) }
                        ((e.right as? TypeOfExpression)?.expression as? Identifier)?.let { out.add(it.text) }
                    }
                    SyntaxKind.AmpersandAmpersand, SyntaxKind.BarBar -> { walk(e.left); walk(e.right) }
                    else -> {}
                }
                else -> {}
            }
        }
        walk(cond)
        return out
    }

    /** B283 TS2736: unary `+` coerces to number, which is invalid for a
     *  (maybe-)bigint operand — incl. unions with a bigint constituent and
     *  TypeParams whose constraint has one. Span = the operand only. */
    private fun checkUnaryPlusBigIntOperand(expr: PrefixUnaryExpression, source: String, fileName: String) {
        val operand = expr.operand
        val t = getTypeOfExpression(operand)
        if (t === anyType || t === errorType || t === unknownType) return
        if (!typeMaybeBigIntConsideringConstraint(t)) return
        var inner: Expression = operand
        while (inner is ParenthesizedExpression) inner = inner.expression
        if (inner is Identifier && inner.text in arithTypeofNarrowedNames && t is Type.Union) return
        val start = operand.pos
        val length = (expressionTrueEnd(operand) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Operator '+' cannot be applied to type '${arithWidenedDisplay(t)}'.",
            category = DiagnosticCategory.Error, code = 2736,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    /** Check if type is string or string literal. */
    private fun isStringLikeType(type: Type): Boolean {
        if (type.flags.hasAny(TypeFlags.String or TypeFlags.StringLiteral)) return true
        if (type is Type.Union) return type.types.any { isStringLikeType(it) }
        if (type is Type.Intersection) return type.types.any { isStringLikeType(it) }
        return false
    }

    /** Check if type is valid for comparison operators. */
    /** Check if type is a non-wrapper Object type (user class/interface, not Number/Boolean/String). */
    /** TS2365 operand display for a relational comparison involving an object/function
     *  operand. A bare class identifier used in value position is `typeof X` (its
     *  constructor type) — getTypeOfExpression yields the instance type, so render the
     *  `typeof` form explicitly. All other operands display via typeToString (which
     *  already widens a bare literal to its base, e.g. `7` → `number`). */
    private fun objComparisonOperandDisplay(operand: Expression, type: Type): String {
        if (operand is Identifier && (type as? Type.Object)?.symbol?.flags?.hasAny(SymbolFlags.Class) == true) {
            return "typeof ${operand.text}"
        }
        return typeToString(type)
    }

    private fun isNonWrapperObjectType(type: Type): Boolean {
        if (type !is Type.Object) return false
        val name = type.symbol?.name ?: return true // anonymous objects are non-wrapper
        return name != "Number" && name != "Boolean" && name != "String" && name != "Symbol" && name != "BigInt"
    }

    private fun isComparableType(type: Type): Boolean {
        if (type === anyType) return true
        if (isNumberLikeType(type)) return true
        if (isBigIntLikeType(type)) return true
        if (isStringLikeType(type)) return true
        if (type.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral)) return true
        if (type is Type.Union) return type.types.all { isComparableType(it) }
        // (REL.1)(b0) round 742: a TYPE PARAMETER is comparable iff its CONSTRAINT is —
        // tsc compares the apparent type. The sibling rule has always been in
        // [isValidArithmeticOperand]; only the relational path lacked it, and it was
        // invisible while `SyntaxKind.FirstToken` on the other side was `anyType`
        // (nodeFactory.ts createToken's `token >= SyntaxKind.FirstToken`, TKind extends
        // SyntaxKind). An UNCONSTRAINED parameter stays non-comparable, as before.
        if (type is Type.TypeParam) {
            val c = type.constraint ?: return false
            return isComparableType(c)
        }
        return false
    }

    /**
     * The relational-comparability category of a primitive operand, or null when
     * the type is `any` / bigint / object / heterogeneous-union — anything where
     * a cross-category TS2365 would risk a false positive. Two operands of
     * DIFFERENT non-null categories (`number` ⇎ `string` ⇎ `boolean`) cannot be
     * compared with `<`/`<=`/`>`/`>=`. The returned string doubles as the widened
     * display name TypeScript uses in the TS2365 message ('number', not '1 | 3').
     * bigint is deliberately excluded (returns null) — number-vs-bigint relational
     * comparability is uncertain, so we never emit for it.
     */
    private fun comparabilityCategory(type: Type): String? {
        if (type is Type.Union) {
            if (type.types.isEmpty()) return null
            val first = comparabilityCategory(type.types[0]) ?: return null
            return if (type.types.all { comparabilityCategory(it) == first }) first else null
        }
        // (REL.1)(b0) round 742: an enum MEMBER's category follows its OWN value.
        // The blanket `EnumLiteral → number` below was written while nothing set the
        // flag; live, it would call `Ext.Dts` (a STRING member) a number and FP a
        // cross-category TS2365 against a string operand.
        enumMemberTypeIsStringValued(type)?.let { return if (it) "string" else "number" }
        if (type.flags.hasAny(TypeFlags.Number or TypeFlags.NumberLiteral or TypeFlags.EnumLiteral)) return "number"
        if (type is Type.Intrinsic && type.flags.hasAny(TypeFlags.Enum)) return "number"
        if (isNumericEnumObjectType(type)) return "number"
        if (type.flags.hasAny(TypeFlags.String or TypeFlags.StringLiteral)) return "string"
        if (type.flags.hasAny(TypeFlags.Boolean or TypeFlags.BooleanLiteral)) return "boolean"
        return null
    }

    /** TS2367 (`==`/`!=` no-overlap) display for a primitive operand: an enum renders as
     *  its NAME (`E`), a pure number/string/boolean renders as its category name (matching
     *  the widened base tsc shows). */
    private fun ts2367CategoryDisplay(type: Type, category: String): String =
        if ((type is Type.Intrinsic && type.flags.hasAny(TypeFlags.Enum)) ||
            type.flags.hasAny(TypeFlags.EnumLiteral) || isNumericEnumObjectType(type)) typeToString(type) else category

    /** For TS2365 "Operator X cannot be applied to types 'A' and 'B'", display the
     *  LITERAL form of literal operands (number `3`, null, undefined) rather than
     *  the widened type. Matches TypeScript's baseline behavior. */
    private fun ts2365OperandDisplay(operand: Expression, type: Type): String {
        return when (operand) {
            is NumericLiteralNode -> operand.text
            is BigIntLiteralNode -> operand.text
            is Identifier -> when (operand.text) {
                "null" -> "null"
                "undefined" -> "undefined"
                "true" -> "true"
                "false" -> "false"
                else -> typeToString(type)
            }
            is ParenthesizedExpression -> ts2365OperandDisplay(operand.expression, type)
            is NonNullExpression -> ts2365OperandDisplay(operand.expression, type)
            is AsExpression -> typeToString(type)
            is SatisfiesExpression -> ts2365OperandDisplay(operand.expression, type)
            else -> typeToString(type)
        }
    }

    /**
     * tsc checks POSSIBLY-UNDEFINED before it checks operand kinds: an arithmetic or
     * relational operand whose type carries `undefined` is TS18048 ("'x' is possibly
     * 'undefined'") at the operand, not TS2362/TS2363/TS2365 about the operation. Ours
     * reported the latter because a union carrying `undefined` fails the operand
     * classifiers outright (the round-415 hazard).
     *
     * Confirmed against two independent reference baselines, on two different operators:
     * `contextuallyTypedIifeStrict` (`j + 1`, `j: number | undefined`) and
     * `circularOptionalityRemoval` (`x > 0`, same type). The TS2362 baselines that also
     * mention "possibly undefined" are unrelated — their operand is a `delete`
     * expression, i.e. a boolean.
     *
     * Deliberately narrow: strictNullChecks only (without it `undefined` is not in the
     * type), a plain reference so there is a name to report, and `any`/`unknown`
     * excluded — [typeIncludesUndefined] answers true for those and neither is "possibly
     * undefined" in tsc's sense. Returns whether the caller must skip its own diagnostic
     * — true when this one REPORTED, and (CHK.65) also when the flow proves the operand
     * `never`, which owes no operand diagnostic of any kind.
     */
    /**
     * (CHK.65) Does the flow graph narrow [ref] — whose type is already [base] — to
     * `never` at this position?
     *
     * Narrowing only ever SHRINKS, so a `never` answer means the reference has no value
     * here and no possibly-undefined diagnostic is owed. Deliberately separate from
     * [arithFlowNarrowedNonNullish], which is gated on a UNION base and REFUSES `never`
     * (it exists to prove an operand numeric, not to prove it empty).
     */
    private fun operandFlowNarrowsToNever(ref: Expression, base: Type): Boolean {
        if (base === neverType) return true
        val graph = currentArithmeticFlowGraph ?: currentFlowGraph ?: return false
        if (getReferencePath(ref) == null) return false
        if (graph.flowAt(ref) == null) return false
        val saved = currentFlowGraph
        currentFlowGraph = graph
        return try {
            getNarrowedTypeForReference(base, ref) === neverType
        } finally { currentFlowGraph = saved }
    }

    private fun emitPossiblyUndefinedOperand(
        operand: Expression, type: Type, source: String, fileName: String,
    ): Boolean {
        if (!strictNullChecks) return false
        if (type === anyType || type === unknownType || type === errorType) return false
        if (!typeIncludesUndefined(type)) return false
        val path = getReferencePath(operand) ?: return false
        // The LITERAL `undefined`/`null` parses as an Identifier here, so it HAS a
        // reference path — but "'undefined' is possibly 'undefined'" is nonsense, and
        // tsc reports TS18050 for those operands instead.
        if (path == "undefined" || path == "null") return false
        // (CHK.65) A nullish operand type is what a PRECEDING guard's ELSE branch leaves
        // on a property path (`if (s.p !== undefined) { return … }` records `undefined`
        // for the rest of the function), and a SECOND guard on the same path then
        // re-narrows it to `never` — an operand with no values at all, which is not
        // "possibly undefined". This reader takes its operand type from
        // [arithOperandType], whose flow consult is gated on a UNION and on a
        // non-`never` answer, so it never saw the re-narrowing and reported a shipped
        // false TS18048 next to a silent assignment of the same reference. Consulting
        // the walk here is SUPPRESSION-ONLY — it can answer `never` or nothing.
        // Answering TRUE (the caller then emits nothing of its own) is the point: a
        // `never` operand owes no diagnostic AT ALL, and without it the TS18048 merely
        // becomes a TS2365 about `number | undefined` one line down.
        if (operandFlowNarrowsToNever(operand, type)) return true
        val start = operand.pos
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$path' is possibly 'undefined'.",
            category = DiagnosticCategory.Error, code = 18048,
            fileName = fileName, line = line, character = character,
            start = start, length = expressionTrueEnd(operand) - start,
        ))
        return true
    }

    private fun emitTs2365(
        expr: BinaryExpression, op: SyntaxKind, leftType: Type, rightType: Type, source: String, fileName: String,
        leftDisplayOverride: String? = null, rightDisplayOverride: String? = null,
    ) {
        var reported = emitPossiblyUndefinedOperand(expr.left, leftType, source, fileName)
        if (emitPossiblyUndefinedOperand(expr.right, rightType, source, fileName)) reported = true
        if (reported) return
        val opText = getOperatorText(op)
        val leftStr = leftDisplayOverride ?: ts2365OperandDisplay(expr.left, leftType)
        val rightStr = rightDisplayOverride ?: ts2365OperandDisplay(expr.right, rightType)
        val start = expr.left.pos
        val length = expressionTrueEnd(expr.right) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Operator '$opText' cannot be applied to types '$leftStr' and '$rightStr'.",
            category = DiagnosticCategory.Error, code = 2365,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun emitTs2362(operand: Expression, source: String, fileName: String) {
        if (emitPossiblyUndefinedOperand(operand, getTypeOfExpression(operand), source, fileName)) return
        val start = operand.pos
        val length = expressionTrueEnd(operand) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The left-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.",
            category = DiagnosticCategory.Error, code = 2362,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun emitTs2363(operand: Expression, source: String, fileName: String) {
        if (emitPossiblyUndefinedOperand(operand, getTypeOfExpression(operand), source, fileName)) return
        val start = operand.pos
        val length = expressionTrueEnd(operand) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The right-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.",
            category = DiagnosticCategory.Error, code = 2363,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    private fun getOperatorText(op: SyntaxKind): String = when (op) {
        SyntaxKind.Plus -> "+"
        SyntaxKind.Minus -> "-"
        SyntaxKind.Asterisk -> "*"
        SyntaxKind.Slash -> "/"
        SyntaxKind.Percent -> "%"
        SyntaxKind.AsteriskAsterisk -> "**"
        SyntaxKind.PlusEquals -> "+="
        SyntaxKind.MinusEquals -> "-="
        SyntaxKind.AsteriskEquals -> "*="
        SyntaxKind.SlashEquals -> "/="
        SyntaxKind.PercentEquals -> "%="
        SyntaxKind.AsteriskAsteriskEquals -> "**="
        SyntaxKind.LessThan -> "<"
        SyntaxKind.GreaterThan -> ">"
        SyntaxKind.LessThanEquals -> "<="
        SyntaxKind.GreaterThanEquals -> ">="
        SyntaxKind.LessThanLessThan -> "<<"
        SyntaxKind.GreaterThanGreaterThan -> ">>"
        SyntaxKind.GreaterThanGreaterThanGreaterThan -> ">>>"
        SyntaxKind.Ampersand -> "&"
        SyntaxKind.Bar -> "|"
        SyntaxKind.Caret -> "^"
        SyntaxKind.LessThanLessThanEquals -> "<<="
        SyntaxKind.GreaterThanGreaterThanEquals -> ">>="
        SyntaxKind.GreaterThanGreaterThanGreaterThanEquals -> ">>>="
        SyntaxKind.AmpersandEquals -> "&="
        SyntaxKind.BarEquals -> "|="
        SyntaxKind.CaretEquals -> "^="
        else -> op.name
    }

    // -----------------------------------------------------------------------
    // TS2364: Invalid assignment target
    // -----------------------------------------------------------------------

    // (M0.4, round 642): the walk is ON THE SPINE — see spineIaEnterNode /
    // spineIaDepth / spineIaEdge; the legacy driver +
    // checkInvalidAssignInStatement(s)/-InExpr(Core) recursion are deleted.
    // [emitInvalidAssignAtBinary] below is the anchor-called leaf;
    // isValidAssignmentTarget + checkDestructuringAssignmentTargets survive
    // unchanged.

    /** Per-file spine setup: the legacy dts skip; depth-memo allocation. */
    private fun spineIaSetup(result: BinderResult) {
        spineIaActive = !spineIsDts
        spineIaDepthMemo = if (!spineIaActive) ShortArray(0) else {
            val n = result.sourceFile.nodeCount
            if (n > 0) ShortArray(n) else ShortArray(0)
        }
    }

    private fun spineIaTeardown() {
        spineIaActive = false
        spineIaDepthMemo = ShortArray(0)
    }

    /** ENTER dispatch: assignment-operator BinaryExpressions — the cheap
     *  operator pre-gate runs BEFORE the reach climb. */
    private fun spineIaEnterNode(node: Node) {
        if ((node as NodeBase).kindId != NodeKind.BINARY_EXPRESSION) return
        node as BinaryExpression
        if (!isAssignmentOperator(node.operator)) return
        if (spineIaDepth(node) < 0) return
        emitInvalidAssignAtBinary(node, spineSource, spineFileName)
    }

    /**
     * Memoized DEPTH classifier — the legacy SHARED `checkDepth` counter
     * reproduced per node: -1 = unreached (a position the deleted walkers
     * never visited, or an expression whose checkInvalidAssignInExpr call
     * would bail past the 200 cap); otherwise the ambient counter value at
     * the node's legacy visit (each expression call = one frame; statements
     * and carrier positions inherit the ambient unchanged — including a
     * statement list nested inside an expression, which inherits the
     * expression's elevated ambient). Ascends to the first
     * memoized/terminal ancestor, then folds [spineIaEdge] back down.
     */
    private fun spineIaDepth(node: Node): Int {
        if (node is SourceFile) return 0
        val memo = spineIaDepthMemo
        run {
            val id = (node as NodeBase).nodeId
            if (id >= 0 && id < memo.size) {
                if (ReachMemoCensus.on) ReachMemoCensus.p(ReachMemoCensus.IADEPTH, id)
                val m = memo[id].toInt()
                if (m != 0) return m - 2
            }
        }
        val chain = spineIaChain
        chain.clear()
        var cur: Node = node
        val anchor: Node?
        var anchorDepth = -1
        while (true) {
            chain.add(cur)
            val parent = (cur as NodeBase).parent
            if (parent == null) { anchor = null; break } // detached/unindexed → unreached
            if (parent is SourceFile) { anchor = parent; anchorDepth = 0; break }
            val pid = (parent as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.s(ReachMemoCensus.IADEPTH, pid, (cur as NodeBase).nodeId)
            val pm = if (pid >= 0 && pid < memo.size) memo[pid].toInt() else 0
            if (pm != 0) { anchor = parent; anchorDepth = pm - 2; break }
            cur = parent
        }
        var pNode: Node? = anchor
        var pDepth = anchorDepth
        var result = -1
        for (i in chain.indices.reversed()) {
            val c = chain[i]
            result = if (pNode == null || pDepth < 0) -1 else spineIaEdge(pNode, pDepth, c)
            val cid = (c as NodeBase).nodeId
            if (ReachMemoCensus.on) ReachMemoCensus.w(ReachMemoCensus.IADEPTH, cid)
            if (cid >= 0 && cid < memo.size) memo[cid] = (result + 2).toShort()
            pNode = c
            pDepth = result
        }
        chain.clear()
        return result
    }

    /** An expression-CALL position at ambient [v]: the legacy
     *  `checkDepth > maxCheckDepth` bail — the subtree prunes past 200. */
    private fun spineIaExpr(v: Int): Int = if (v > maxCheckDepth) -1 else v

    /**
     * The edge rules — the deleted checkInvalidAssignInStatement(s)
     * statement arms and checkInvalidAssignInExprCore expression arms
     * verbatim. An EXPRESSION parent's children were called from its core
     * at ambient pDepth+1 (its own frame); statement/carrier parents pass
     * pDepth through. [spineIaExpr] applies at every checkInvalidAssignInExpr
     * call position; statement-list/member/carrier positions never bail.
     * Unlisted edges are the legacy `else -> {}`s: the switch SUBJECT and
     * case EXPRESSIONS, for-head DECLARATION-LIST initializers, for-in/of
     * initializers, enum member initializers, class heritage, computed
     * property names, parameter defaults, decorators, type positions.
     * Unlike spineArgEdge there is NO right-spine absorption — both binary
     * operands cost a frame, so deep chains prune at the cap.
     */
    private fun spineIaEdge(parent: Node, pDepth: Int, child: Node): Int = when (parent) {
        // ---- statement arms (no frame) ----
        is SourceFile -> if (child is Statement) pDepth else -1
        is Block -> if (child is Statement) pDepth else -1
        is ModuleBlock -> if (child is Statement) pDepth else -1
        is CaseClause -> if (child is Statement) pDepth else -1
        is DefaultClause -> if (child is Statement) pDepth else -1
        is SwitchStatement -> if (child is CaseClause || child is DefaultClause) pDepth else -1
        is ExpressionStatement -> if (child === parent.expression) spineIaExpr(pDepth) else -1
        is VariableStatement -> if (child === parent.declarationList) pDepth else -1
        is VariableDeclarationList -> if (child is VariableDeclaration) pDepth else -1
        is VariableDeclaration -> if (child === parent.initializer) spineIaExpr(pDepth) else -1
        is ReturnStatement -> if (child === parent.expression) spineIaExpr(pDepth) else -1
        is ThrowStatement -> if (child === parent.expression) spineIaExpr(pDepth) else -1
        is ExportAssignment -> if (child === parent.expression) spineIaExpr(pDepth) else -1
        is IfStatement -> when {
            child === parent.expression -> spineIaExpr(pDepth)
            child === parent.thenStatement || child === parent.elseStatement -> pDepth
            else -> -1
        }
        is ForStatement -> when {
            // The for-head initializer is walked as a bare EXPRESSION only —
            // a declaration-list initializer (and its declarations'
            // initializers) was never visited.
            child === parent.initializer -> if (child is Expression) spineIaExpr(pDepth) else -1
            child === parent.condition || child === parent.incrementor -> spineIaExpr(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is ForInStatement -> when {
            child === parent.expression -> spineIaExpr(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is ForOfStatement -> when {
            child === parent.expression -> spineIaExpr(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is WhileStatement -> when {
            child === parent.expression -> spineIaExpr(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is DoStatement -> when {
            child === parent.expression -> spineIaExpr(pDepth)
            child === parent.statement -> pDepth
            else -> -1
        }
        is LabeledStatement -> if (child === parent.statement) pDepth else -1
        is TryStatement ->
            if (child === parent.tryBlock || child === parent.finallyBlock ||
                child === parent.catchClause) pDepth else -1
        is CatchClause -> if (child === parent.block) pDepth else -1
        is FunctionDeclaration -> if (child === parent.body) pDepth else -1
        is ClassDeclaration ->
            if (child is MethodDeclaration || child is Constructor ||
                child is GetAccessor || child is SetAccessor ||
                child is PropertyDeclaration) pDepth else -1
        is ModuleDeclaration -> if (child === parent.body && child is ModuleBlock) pDepth else -1
        // ---- member/carrier arms (the owner's ambient is baked into the
        //      member's stored value by the owner edge) ----
        is MethodDeclaration -> if (child === parent.body) pDepth else -1
        is Constructor -> if (child === parent.body) pDepth else -1
        is GetAccessor -> if (child === parent.body) pDepth else -1
        is SetAccessor -> if (child === parent.body) pDepth else -1
        is PropertyDeclaration -> if (child === parent.initializer) spineIaExpr(pDepth) else -1
        is PropertyAssignment -> if (child === parent.initializer) spineIaExpr(pDepth) else -1
        is ShorthandPropertyAssignment ->
            if (child === parent.objectAssignmentInitializer) spineIaExpr(pDepth) else -1
        is SpreadAssignment -> if (child === parent.expression) spineIaExpr(pDepth) else -1
        is TemplateSpan -> if (child === parent.expression) spineIaExpr(pDepth) else -1
        // ---- expression arms (children called from the core at pDepth+1) ----
        is BinaryExpression ->
            if (child === parent.left || child === parent.right)
                spineIaExpr(pDepth + 1) else -1
        is ConditionalExpression ->
            if (child === parent.condition || child === parent.whenTrue ||
                child === parent.whenFalse) spineIaExpr(pDepth + 1) else -1
        is ParenthesizedExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is ArrowFunction -> when {
            child !== parent.body -> -1
            child is Block -> pDepth + 1
            else -> spineIaExpr(pDepth + 1)
        }
        is FunctionExpression -> if (child === parent.body) pDepth + 1 else -1
        is CallExpression ->
            if (child === parent.expression || parent.arguments.anyIdentical(child))
                spineIaExpr(pDepth + 1) else -1
        is TaggedTemplateExpression -> when {
            child === parent.tag -> spineIaExpr(pDepth + 1)
            // The template is a CARRIER (never itself an expr call): its
            // spans were iterated from the tagged core at ambient pDepth+1,
            // which the TemplateExpression arm's +1 reproduces from a stored
            // value of pDepth.
            child === parent.template && child is TemplateExpression -> pDepth
            else -> -1
        }
        is TemplateExpression -> if (child is TemplateSpan) pDepth + 1 else -1
        is PrefixUnaryExpression -> if (child === parent.operand) spineIaExpr(pDepth + 1) else -1
        is PostfixUnaryExpression -> if (child === parent.operand) spineIaExpr(pDepth + 1) else -1
        is SpreadElement -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is ArrayLiteralExpression ->
            if (parent.elements.anyIdentical(child)) spineIaExpr(pDepth + 1) else -1
        is ObjectLiteralExpression -> when (child) {
            is PropertyAssignment, is ShorthandPropertyAssignment, is SpreadAssignment,
            is MethodDeclaration, is GetAccessor, is SetAccessor -> pDepth + 1
            else -> -1
        }
        is AsExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is SatisfiesExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is NonNullExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is TypeAssertionExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is NewExpression ->
            if (child === parent.expression || parent.arguments?.anyIdentical(child) == true)
                spineIaExpr(pDepth + 1) else -1
        is ElementAccessExpression ->
            if (child === parent.expression || child === parent.argumentExpression)
                spineIaExpr(pDepth + 1) else -1
        is PropertyAccessExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is AwaitExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is YieldExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is VoidExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is DeleteExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is TypeOfExpression -> if (child === parent.expression) spineIaExpr(pDepth + 1) else -1
        is CommaListExpression ->
            if (parent.elements.anyIdentical(child)) spineIaExpr(pDepth + 1) else -1
        is ClassExpression ->
            if (child is MethodDeclaration || child is Constructor ||
                child is GetAccessor || child is SetAccessor ||
                child is PropertyDeclaration) pDepth + 1 else -1
        else -> -1
    }

    /**
     * The legacy checkInvalidAssignInExprCore BinaryExpression emissions,
     * verbatim. COMPOUND assignments (`0 ^= …`) run tsc's
     * checkReferenceExpression too — a non-reference LHS is TS2364
     * (destructuring literals are only valid for plain `=`; a zero-width
     * missing-Identifier LHS is silent, being an Identifier) —
     * constructorWithIncompleteTypeAnnotation's `var any = 0 ^= `. A plain
     * `=` with a VALID destructuring target runs the private-identifier
     * element check: `[#abc] = x` — `#abc` (Identifier whose text starts
     * with `#`) is not a valid assignment target outside a `this.#abc`
     * member-access chain.
     */
    private fun emitInvalidAssignAtBinary(expr: BinaryExpression, source: String, fileName: String) {
        if (expr.operator != SyntaxKind.Equals && isAssignmentOperator(expr.operator)) {
            val left = expr.left
            val validForCompound = isValidAssignmentTarget(left) &&
                left !is ArrayLiteralExpression && left !is ObjectLiteralExpression
            if (!validForCompound) {
                val start = left.pos
                val length = (expressionTrueEnd(left) - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "The left-hand side of an assignment expression must be a variable or a property access.",
                    category = DiagnosticCategory.Error,
                    code = 2364,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length,
                ))
            } else {
                // tsc runs the whole checkReferenceExpression for a compound
                // assignment too, so a valid-but-optional-chain LHS is TS2779.
                emitOptionalChainTarget(left, 2779, OPTIONAL_CHAIN_ASSIGNMENT_LHS, source, fileName)
            }
        }
        if (expr.operator == SyntaxKind.Equals) {
            if (!isValidAssignmentTarget(expr.left)) {
                val start = expr.left.pos
                val length = expressionTrueEnd(expr.left) - start
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "The left-hand side of an assignment expression must be a variable or a property access.",
                    category = DiagnosticCategory.Error,
                    code = 2364,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            } else {
                checkDestructuringAssignmentTargets(
                    expr.left, source, fileName, 2779, OPTIONAL_CHAIN_ASSIGNMENT_LHS, checkChain = true,
                )
            }
        }
    }

    /**
     * The OPTIONAL-CHAIN leg of tsc's `checkReferenceExpression`: a reference
     * TARGET (assignment LHS, `++`/`--` operand, `for..in`/`for..of` LHS, a
     * destructuring-assignment element) may not be an optional chain.
     *
     * tsc decides this with `node.flags & NodeFlags.OptionalChain`, a bit the
     * parser propagates along the chain. We carry no such flag, so the
     * equivalent test is a descent through the chain's own links: `?.` anywhere
     * BELOW the target makes the whole target a chain (`a?.b.c` is one), while a
     * PARENTHESIS terminates it (`(a?.b).c` is not). The outer value-preserving
     * wrappers are skipped first, exactly as tsc's
     * `skipOuterExpressions(expr, Assertions | Parentheses)` does.
     */
    private fun isOptionalChainReferenceTarget(expr: Expression): Boolean {
        var core: Expression = expr
        while (true) {
            core = when (core) {
                is ParenthesizedExpression -> core.expression
                is NonNullExpression -> core.expression
                is AsExpression -> core.expression
                is TypeAssertionExpression -> core.expression
                is SatisfiesExpression -> core.expression
                else -> break
            }
        }
        var cur: Expression = core
        while (true) {
            cur = when (cur) {
                is PropertyAccessExpression -> if (cur.questionDotToken) return true else cur.expression
                is ElementAccessExpression -> if (cur.questionDotToken) return true else cur.expression
                is CallExpression -> if (cur.questionDotToken) return true else cur.expression
                // `a?.b!.c` — a non-null assertion INSIDE a chain is tsc's
                // NonNullChain and does not terminate it.
                is NonNullExpression -> cur.expression
                else -> return false
            }
        }
    }

    /**
     * Emits one of TS2777 / TS2778 / TS2779 / TS2780 / TS2781 when [target] is
     * an optional chain in a reference position. The squiggle is the target's
     * own span, matching tsc (which reports at the node handed to
     * `checkReferenceExpression`, wrappers included).
     */
    private fun emitOptionalChainTarget(
        target: Expression,
        code: Int,
        message: String,
        source: String,
        fileName: String,
    ) {
        if (!isOptionalChainReferenceTarget(target)) return
        val start = target.pos
        val length = (expressionTrueEnd(target) - start).coerceAtLeast(1)
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName, line = line, character = character,
            start = start, length = length,
        ))
    }

    /** Check if an expression is a valid assignment target (LHS of =). */
    private fun isValidAssignmentTarget(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> true
            is PropertyAccessExpression -> true
            is ElementAccessExpression -> true
            // A ParenthesizedExpression carrying `instantiationEnd` is a synthetic
            // wrapper inserted by the parser for an instantiation expression like
            // `obj.fn<T>`. TypeScript treats InstantiationExpression as an invalid
            // assignment target — emit TS2364 "The left-hand side of an assignment
            // expression must be a variable or a property access."
            is ParenthesizedExpression ->
                if (expr.instantiationEnd != null) false
                else isValidAssignmentTarget(expr.expression)
            is NonNullExpression -> isValidAssignmentTarget(expr.expression)
            // Type-only wrappers: `x as T`, `<T>x`, `x satisfies T` preserve the
            // underlying reference and remain valid assignment targets so long as
            // their inner expression is.
            is AsExpression -> isValidAssignmentTarget(expr.expression)
            is TypeAssertionExpression -> isValidAssignmentTarget(expr.expression)
            is SatisfiesExpression -> isValidAssignmentTarget(expr.expression)
            // Destructuring patterns are valid (array/object literal on LHS)
            is ArrayLiteralExpression -> true
            is ObjectLiteralExpression -> true
            else -> false
        }
    }

    /**
     * Walk a destructuring pattern (ArrayLiteralExpression / ObjectLiteralExpression) on
     * the LHS of an assignment and emit TS2364 at any private-identifier element. A bare
     * `#abc` (Identifier scanned as a single token with leading `#`) is never a valid
     * assignment target — private fields require `this.#abc` or `obj.#abc` syntax.
     *
     * The same walk carries tsc's OPTIONAL-CHAIN leg, because it already enumerates
     * exactly the positions `checkArrayLiteralDestructuringElementAssignment` /
     * `checkObjectLiteralDestructuringPropertyAssignment` hand to
     * `checkReferenceExpression`: [chainCode]/[chainMessage] is TS2779 everywhere
     * except an object REST target, which tsc reports as TS2778. [checkChain] is false
     * only for the node whose enclosing call already reported it (a parenthesised
     * target), so no position is reported twice.
     */
    private fun checkDestructuringAssignmentTargets(
        expr: Expression,
        source: String,
        fileName: String,
        chainCode: Int,
        chainMessage: String,
        checkChain: Boolean,
    ) {
        if (checkChain) emitOptionalChainTarget(expr, chainCode, chainMessage, source, fileName)
        when (expr) {
            is Identifier -> {
                if (expr.text.startsWith("#")) {
                    val start = expr.pos
                    val length = expr.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "The left-hand side of an assignment expression must be a variable or a property access.",
                        category = DiagnosticCategory.Error,
                        code = 2364,
                        fileName = fileName, line = line, character = character,
                        start = start, length = length,
                    ))
                }
            }
            is ArrayLiteralExpression -> {
                for (el in expr.elements) {
                    val target = if (el is SpreadElement) el.expression else el
                    checkDestructuringAssignmentTargets(
                        target, source, fileName, 2779, OPTIONAL_CHAIN_ASSIGNMENT_LHS, checkChain = true,
                    )
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkDestructuringAssignmentTargets(
                            prop.initializer, source, fileName, 2779, OPTIONAL_CHAIN_ASSIGNMENT_LHS,
                            checkChain = true,
                        )
                        is ShorthandPropertyAssignment -> {
                            if (prop.name.text.startsWith("#")) {
                                val start = prop.name.pos
                                val length = prop.name.text.length
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "The left-hand side of an assignment expression must be a variable or a property access.",
                                    category = DiagnosticCategory.Error,
                                    code = 2364,
                                    fileName = fileName, line = line, character = character,
                                    start = start, length = length,
                                ))
                            }
                        }
                        is SpreadAssignment -> checkDestructuringAssignmentTargets(
                            prop.expression, source, fileName, 2778, OPTIONAL_CHAIN_OBJECT_REST,
                            checkChain = true,
                        )
                        else -> {}
                    }
                }
            }
            // The enclosing call already reported the chain at the PARENTHESISED
            // node (tsc's skipOuterExpressions sees through it), so the inner one
            // must not report it again.
            is ParenthesizedExpression -> checkDestructuringAssignmentTargets(
                expr.expression, source, fileName, chainCode, chainMessage, checkChain = false,
            )
            is BinaryExpression -> {
                // Default value: `[x = 1] = ...` — recurse into LHS only.
                if (expr.operator == SyntaxKind.Equals) {
                    checkDestructuringAssignmentTargets(
                        expr.left, source, fileName, chainCode, chainMessage, checkChain = true,
                    )
                }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2405: for-in LHS must be 'string' or 'any'
    // -----------------------------------------------------------------------

    private fun checkForInLhsTypes() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            checkForInLhsInStatements(result.sourceFile.statements, result.locals, source, fileName, inAmbient = false)
        }
    }

    private fun checkForInLhsInStatements(
        stmts: List<Statement>, locals: SymbolTable, source: String, fileName: String, inAmbient: Boolean,
    ) {
        for (stmt in stmts) checkForInLhsInStmt(stmt, locals, source, fileName, inAmbient)
    }

    private fun checkForInLhsInStmt(
        stmt: Statement, locals: SymbolTable, source: String, fileName: String, inAmbient: Boolean,
    ) {
        when (stmt) {
            is ForInStatement -> {
                val lhs = stmt.initializer
                if (lhs is Identifier) {
                    val sym = locals[lhs.text]
                    val decl = sym?.valueDeclaration
                    if (decl is VariableDeclaration) {
                        val typeNode = decl.type
                        if (typeNode != null && !isForInLhsCompatible(typeNode)) {
                            val start = lhs.pos
                            val length = lhs.text.length
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "The left-hand side of a 'for...in' statement must be of type 'string' or 'any'.",
                                category = DiagnosticCategory.Error,
                                code = 2405,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                } else if (lhs is ElementAccessExpression) {
                    // n[i] for-in LHS: element type must be string/any. Narrow surgical detection:
                    // when base is an Identifier whose initializer is an ArrayLiteralExpression
                    // (possibly through ||/??), and at least one of those array literals contains
                    // an array/object literal element, the element type is object/array → TS2405.
                    val base = lhs.expression
                    if (base is Identifier) {
                        val sym = locals[base.text]
                        val decl = sym?.valueDeclaration
                        if (decl is VariableDeclaration && decl.type == null) {
                            val init = decl.initializer
                            if (init != null && initializerHasNestedArrayOrObjectElement(init)) {
                                val start = lhs.pos
                                val length = (expressionTrueEnd(lhs) - start).coerceAtLeast(1)
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "The left-hand side of a 'for...in' statement must be of type 'string' or 'any'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2405,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                    }
                }
                // TS2407: RHS must be 'any', an object type, or a type parameter.
                // Skip in ambient contexts (TypeScript only emits TS1036 for those).
                val rhsDisplay = if (!inAmbient) simpleRhsNonObjectDisplay(stmt.expression) else null
                if (rhsDisplay != null) {
                    val rhsStart = stmt.expression.pos
                    val rhsEnd = expressionTrueEnd(stmt.expression)
                    val rhsLen = (rhsEnd - rhsStart).coerceAtLeast(1)
                    val (line, character) = getLineAndCharacterOfPosition(source, rhsStart)
                    diagnostics.add(Diagnostic(
                        message = "The right-hand side of a 'for...in' statement must be of type 'any', an object type or a type parameter, but here has type '$rhsDisplay'.",
                        category = DiagnosticCategory.Error,
                        code = 2407,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = rhsStart,
                        length = rhsLen,
                    ))
                }
                checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            }
            is Block -> checkForInLhsInStatements(stmt.statements, locals, source, fileName, inAmbient)
            is IfStatement -> {
                checkForInLhsInStmt(stmt.thenStatement, locals, source, fileName, inAmbient)
                stmt.elseStatement?.let { checkForInLhsInStmt(it, locals, source, fileName, inAmbient) }
            }
            is ForStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is ForOfStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is WhileStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is DoStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkForInLhsInStatements(clause.statements, locals, source, fileName, inAmbient)
                        is DefaultClause -> checkForInLhsInStatements(clause.statements, locals, source, fileName, inAmbient)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkForInLhsInStatements(stmt.tryBlock.statements, locals, source, fileName, inAmbient)
                stmt.catchClause?.block?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                stmt.finallyBlock?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
            }
            is FunctionDeclaration -> stmt.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                is Constructor -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                is GetAccessor -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                is SetAccessor -> m.body?.let { checkForInLhsInStatements(it.statements, locals, source, fileName, inAmbient) }
                else -> {}
            }
            is LabeledStatement -> checkForInLhsInStmt(stmt.statement, locals, source, fileName, inAmbient)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                val ambient = inAmbient || ModifierFlag.Declare in stmt.modifiers
                checkForInLhsInStatements(it.statements, locals, source, fileName, ambient)
            }
            else -> {}
        }
    }

    /**
     * If the RHS expression of a for-in is clearly a non-object, non-any value (number literal,
     * string literal, boolean, null, undefined), return its display text for TS2407. Otherwise
     * return null — conservative: unknown expressions are assumed valid.
     */
    private fun simpleRhsNonObjectDisplay(expr: Expression): String? {
        return when (expr) {
            is NumericLiteralNode -> expr.text
            is BigIntLiteralNode -> expr.text
            is StringLiteralNode -> "\"${expr.text}\""
            is Identifier -> when (expr.text) {
                // `null`/`undefined` are NOT flagged: tsc never emits TS2407 for a
                // `for (x in null)` / `for (x in undefined)` RHS (the loop is a runtime
                // no-op, allowed in all modes — widenedTypes `for (var a in null) {}`).
                "true", "false" -> expr.text
                else -> {
                    // 17.184: Identifier resolving to a primitive-typed variable
                    // (e.g. `declare var expr: number`). Look up the symbol's
                    // declared type via globals; if KeywordTypeNode and not
                    // string/any/unknown/object, return its display.
                    val sym = globals[expr.text] ?: return null
                    val decl = sym.valueDeclaration as? VariableDeclaration ?: return null
                    val typeNode = decl.type as? KeywordTypeNode ?: return null
                    when (typeNode.kind) {
                        SyntaxKind.NumberKeyword -> "number"
                        SyntaxKind.BooleanKeyword -> "boolean"
                        SyntaxKind.BigIntKeyword -> "bigint"
                        SyntaxKind.SymbolKeyword -> "symbol"
                        SyntaxKind.VoidKeyword -> "void"
                        SyntaxKind.NeverKeyword -> "never"
                        else -> null
                    }
                }
            }
            is PrefixUnaryExpression -> {
                // `-1` is still a numeric literal form
                if (expr.operator == SyntaxKind.Minus || expr.operator == SyntaxKind.Plus) {
                    val inner = simpleRhsNonObjectDisplay(expr.operand) ?: return null
                    (if (expr.operator == SyntaxKind.Minus) "-" else "") + inner
                } else null
            }
            else -> null
        }
    }

    /**
     * Returns true if [init] is (recursively through `||`/`??` BinaryExpression) an
     * `ArrayLiteralExpression`, where at least one branch's array has at least one
     * element that is itself an `ArrayLiteralExpression` or `ObjectLiteralExpression`.
     * Used to detect that `var x = init; x[i]` yields an object/array element type
     * (not string/any), which would make `x[i]` an invalid for-in LHS (TS2405).
     */
    private fun initializerHasNestedArrayOrObjectElement(init: Expression): Boolean {
        var allArrayLiterals = true
        var hasNested = false
        fun walk(e: Expression) {
            when (e) {
                is ArrayLiteralExpression -> {
                    if (e.elements.any { it is ArrayLiteralExpression || it is ObjectLiteralExpression }) {
                        hasNested = true
                    }
                }
                is BinaryExpression -> if (e.operator == SyntaxKind.BarBar || e.operator == SyntaxKind.QuestionQuestion) {
                    walk(e.left)
                    walk(e.right)
                } else {
                    allArrayLiterals = false
                }
                is ParenthesizedExpression -> walk(e.expression)
                else -> allArrayLiterals = false
            }
        }
        walk(init)
        return allArrayLiterals && hasNested
    }

    /** Returns true if the annotated type can appear on the LHS of `for..in`: string/any/unknown. */
    private fun isForInLhsCompatible(typeNode: TypeNode): Boolean {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.StringKeyword, SyntaxKind.AnyKeyword, SyntaxKind.UnknownKeyword -> true
                else -> false
            }
            is UnionType -> typeNode.types.all { isForInLhsCompatible(it) }
            is ParenthesizedType -> isForInLhsCompatible(typeNode.type)
            // Unknown type forms (type references, literal types, etc.) — conservative: accept.
            else -> true
        }
    }

    // -----------------------------------------------------------------------
    // TS2709: Cannot use namespace as a type
    // -----------------------------------------------------------------------

    private fun checkNamespaceUsedAsType() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            currentCheckLocals = result.locals
            currentTypeProvidingNames = result.sourceFile.statements.mapNotNullTo(mutableSetOf()) { s ->
                when (s) {
                    is TypeAliasDeclaration -> s.name.text
                    is InterfaceDeclaration -> s.name.text
                    is ClassDeclaration -> s.name?.text
                    is EnumDeclaration -> s.name.text
                    else -> null
                }
            }

            for (stmt in result.sourceFile.statements) {
                checkNamespaceAsTypeInStmt(stmt, source, fileName)
            }
        }
        currentCheckLocals = null
        currentTypeProvidingNames = emptySet()
    }

    /**
     * B393: Namespace-alias visibility through `import X = <local-namespace>`.
     * Inside `namespace N { import X = LocalNs; ... }` where LocalNs resolves to a
     * namespace-ONLY symbol, a BARE type reference to X (`p: X`) is TS2709 (a namespace
     * cannot be used as a bare type — only `X.Member` is valid), and a qualified
     * `X.member` where `member` EXISTS in LocalNs but is NOT exported is TS2724
     * (no exported member, with spelling suggestion). The file-scoped TS2709 walker and
     * the shared qualified-name resolver never reach a namespace-LOCAL import alias, so
     * this dedicated walker owns the shape. FP-safe by exact shape: only fires for an
     * import-equals alias whose entity-name target is a namespace-only symbol, and the
     * member must exist-but-be-unexported.
     */
    /**
     * B408: TS2702/TS2713 — a TYPE (class/interface/type-alias) used as a NAMESPACE
     * qualifier in a type position (`Foo.bar` where `Foo` is a type, not a namespace).
     * The file-scoped `checkTypeNameResolved` walker only emits TS2702 for a TOP-LEVEL
     * (global/file-local) leftmost type and never distinguishes TS2713; it cannot see a
     * NAMESPACE-LOCAL type (`namespace N { interface Foo{}; var x: Foo.bar }`) because its
     * leftmost lookup consults only globals/file-locals (the symbol is namespace-local).
     * This dedicated walker resolves each qualified segment through the enclosing namespace
     * chain and applies tsc's `checkAndReportErrorForUsingTypeAsNamespace` rule:
     *   - LEFTMOST segment is the type (`Foo.bar`): TS2713 if `bar` is a property of `Foo`'s
     *     declared type (Did you mean `Foo["bar"]`?), else TS2702.
     *   - A NON-leftmost segment is the type (`N.Foo.bar`, reached via namespace `N`):
     *     always TS2713 at the member.
     * FP-safe by construction: a `Type.member` reference in TYPE position is ALWAYS a tsc
     * error (a valid `A.B` has A a namespace); the type-vs-namespace classification excludes
     * Module/NamespaceModule/ValueModule/Enum (clodules + enums stay legal as qualifiers).
     * The leftmost emission is gated to NAMESPACE-LOCAL leftmosts (resolved via nsChain) so it
     * never double-emits with the existing top-level TS2702 path in checkTypeNameResolved.
     */
    private fun checkTypeUsedAsNamespaceRefs() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                scanTypeAsNs(stmt, emptyList(), result, source, fileName)
            }
        }
    }

    private fun scanTypeAsNs(
        stmt: Statement, nsChain: List<Symbol>, result: BinderResult, source: String, fileName: String,
    ) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                typeAsNsTypeNode(d.type, nsChain, result, source, fileName)
            }
            is TypeAliasDeclaration -> typeAsNsTypeNode(stmt.type, nsChain, result, source, fileName)
            is FunctionDeclaration -> {
                for (p in stmt.parameters) typeAsNsTypeNode(p.type, nsChain, result, source, fileName)
                typeAsNsTypeNode(stmt.type, nsChain, result, source, fileName)
                stmt.body?.statements?.forEach { scanTypeAsNs(it, nsChain, result, source, fileName) }
            }
            is ClassDeclaration -> for (m in stmt.members) when (m) {
                is PropertyDeclaration -> typeAsNsTypeNode(m.type, nsChain, result, source, fileName)
                is MethodDeclaration -> {
                    for (p in m.parameters) typeAsNsTypeNode(p.type, nsChain, result, source, fileName)
                    typeAsNsTypeNode(m.type, nsChain, result, source, fileName)
                    m.body?.statements?.forEach { scanTypeAsNs(it, nsChain, result, source, fileName) }
                }
                is Constructor -> {
                    for (p in m.parameters) typeAsNsTypeNode(p.type, nsChain, result, source, fileName)
                    m.body?.statements?.forEach { scanTypeAsNs(it, nsChain, result, source, fileName) }
                }
                is GetAccessor -> typeAsNsTypeNode(m.type, nsChain, result, source, fileName)
                is SetAccessor -> for (p in m.parameters) typeAsNsTypeNode(p.type, nsChain, result, source, fileName)
                else -> {}
            }
            is InterfaceDeclaration -> for (m in stmt.members) when (m) {
                is PropertyDeclaration -> typeAsNsTypeNode(m.type, nsChain, result, source, fileName)
                is MethodDeclaration -> {
                    for (p in m.parameters) typeAsNsTypeNode(p.type, nsChain, result, source, fileName)
                    typeAsNsTypeNode(m.type, nsChain, result, source, fileName)
                }
                else -> {}
            }
            is ImportEqualsDeclaration -> (stmt.moduleReference as? QualifiedName)?.let {
                emitTypeAsNs(it, nsChain, result, source, fileName)
            }
            is ModuleDeclaration -> {
                val nsSym = result.nodeToSymbol[nodeKey(stmt)]
                val childChain = if (nsSym != null) listOf(nsSym) + nsChain else nsChain
                when (val body = stmt.body) {
                    is ModuleBlock -> body.statements.forEach { scanTypeAsNs(it, childChain, result, source, fileName) }
                    is ModuleDeclaration -> scanTypeAsNs(body, childChain, result, source, fileName)
                    else -> {}
                }
            }
            is Block -> stmt.statements.forEach { scanTypeAsNs(it, nsChain, result, source, fileName) }
            else -> {}
        }
    }

    private fun typeAsNsTypeNode(
        t: TypeNode?, nsChain: List<Symbol>, result: BinderResult, source: String, fileName: String,
    ) {
        when (t) {
            null -> {}
            is TypeReference -> {
                (t.typeName as? QualifiedName)?.let { emitTypeAsNs(it, nsChain, result, source, fileName) }
                t.typeArguments?.forEach { typeAsNsTypeNode(it, nsChain, result, source, fileName) }
            }
            is UnionType -> t.types.forEach { typeAsNsTypeNode(it, nsChain, result, source, fileName) }
            is IntersectionType -> t.types.forEach { typeAsNsTypeNode(it, nsChain, result, source, fileName) }
            is ArrayType -> typeAsNsTypeNode(t.elementType, nsChain, result, source, fileName)
            is ParenthesizedType -> typeAsNsTypeNode(t.type, nsChain, result, source, fileName)
            is IndexedAccessType -> {
                // `Enum["Member"]` / `AliasToEnum["Member"]` in TYPE position → TS2339: an
                // enum member NAME is never a property of the enum VALUE type (members live on
                // the `typeof Enum` object side). FP-safe: a member-name index of an enum is
                // always a tsc error; `type C = typeof Enum` aliases are excluded (their body is
                // a TypeQuery, not a TypeReference, so they keep the member properties).
                val objName = ((t.objectType as? TypeReference)?.typeName as? Identifier)?.text
                val idxLit = (t.indexType as? LiteralType)?.literal as? StringLiteralNode
                if (objName != null && idxLit != null) {
                    val enumSym = resolveTypeRefToEnum(objName, nsChain, result)
                    if (enumSym != null && enumSym.exports?.containsKey(idxLit.text) == true) {
                        val (line, ch) = getLineAndCharacterOfPosition(source, idxLit.pos)
                        diagnostics.add(Diagnostic(
                            message = "Property '${idxLit.text}' does not exist on type '${enumSym.name}'.",
                            category = DiagnosticCategory.Error, code = 2339, fileName = fileName,
                            line = line, character = ch, start = idxLit.pos, length = idxLit.text.length + 2,
                        ))
                    }
                }
                typeAsNsTypeNode(t.objectType, nsChain, result, source, fileName)
                typeAsNsTypeNode(t.indexType, nsChain, result, source, fileName)
            }
            else -> {}
        }
    }

    /** Resolve a bare name through the enclosing-namespace chain, then globals/file-locals. */
    private fun lookupTypeAsNsName(name: String, nsChain: List<Symbol>, result: BinderResult): Symbol? {
        for (ns in nsChain) ns.exports?.get(name)?.let { return it }
        return globals[name] ?: result.locals[name]
    }

    /** Resolve a type-name to an enum symbol, following one level of `type X = Enum` alias. */
    private fun resolveTypeRefToEnum(name: String, nsChain: List<Symbol>, result: BinderResult): Symbol? {
        fun lookup(n: String): Symbol? = lookupTypeAsNsName(n, nsChain, result)
        val s = lookup(name) ?: return null
        if (s.declarations.any { it is EnumDeclaration }) return s
        if (s.flags.hasAny(SymbolFlags.TypeAlias)) {
            // Only a plain `type C = Enum` (TypeReference body) aliases the enum value type;
            // `type C = typeof Enum` (TypeQuery body) is the object side and keeps the members.
            val decl = s.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
            val bn = ((decl?.type as? TypeReference)?.typeName as? Identifier)?.text
            if (bn != null) {
                val t = lookup(bn)
                if (t != null && t.declarations.any { it is EnumDeclaration }) return t
            }
        }
        return null
    }

    private fun isPureTypeSymbol(sym: Symbol): Boolean =
        sym.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias) &&
            !sym.flags.hasAny(
                SymbolFlags.Module or SymbolFlags.NamespaceModule or SymbolFlags.ValueModule or SymbolFlags.Enum,
            )

    private fun emitTypeAsNs(
        qn: QualifiedName, nsChain: List<Symbol>, result: BinderResult, source: String, fileName: String,
    ) {
        // Flatten the qualified name into left-to-right Identifier segments.
        val segs = ArrayDeque<Identifier>()
        var cur: Node = qn
        while (cur is QualifiedName) { segs.addFirst(cur.right); cur = cur.left }
        (cur as? Identifier)?.let { segs.addFirst(it) } ?: return
        if (segs.size < 2) return
        // Resolve the leftmost segment; track whether it came from an enclosing namespace.
        var sym: Symbol? = null
        var fromNsChain = false
        for (ns in nsChain) { ns.exports?.get(segs[0].text)?.let { sym = it; fromNsChain = true } ?: continue; break }
        if (sym == null) sym = globals[segs[0].text] ?: result.locals[segs[0].text]
        var s = sym ?: return
        // `Enum.Member.X` (3+ segments) in TYPE position → TS2749: `Enum.Member` is a VALUE
        // (the enum member literal), so accessing a further `.X` on it and using the result as a
        // type is a value-used-as-type. `Enum.Member` alone (2 segs) is a legal literal type.
        if (s.declarations.any { it is EnumDeclaration } && segs.size >= 3 &&
            s.exports?.containsKey(segs[1].text) == true
        ) {
            val dotted = segs.joinToString(".") { it.text }
            val start = segs[0].pos
            val end = segs.last().let { it.pos + it.text.length }
            val (line, ch) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "'$dotted' refers to a value, but is being used as a type here. Did you mean 'typeof $dotted'?",
                category = DiagnosticCategory.Error, code = 2749, fileName = fileName,
                line = line, character = ch, start = start, length = (end - start).coerceAtLeast(1),
            ))
            return
        }
        for (i in 1 until segs.size) {
            if (isPureTypeSymbol(s)) {
                val typeName = segs[i - 1].text
                val member = segs[i].text
                if (i == 1) {
                    // Leftmost is the type — gated to namespace-local leftmosts so we never
                    // double-emit with checkTypeNameResolved's top-level TS2702 path.
                    if (!fromNsChain) return
                    val hasMember: Boolean = run {
                        // `type C = typeof Enum` — the enum's members ARE properties of the object
                        // side (the typeof resolver returns anyType for a namespace-local enum, so
                        // getPropertyOfType would wrongly miss them and emit TS2702 not TS2713).
                        if (s.flags.hasAny(SymbolFlags.TypeAlias)) {
                            val aliasBody = (s.declarations.firstOrNull { it is TypeAliasDeclaration }
                                as? TypeAliasDeclaration)?.type
                            if (aliasBody is TypeQuery) {
                                val en = (aliasBody.exprName as? Identifier)?.text
                                val enumSym = en?.let { lookupTypeAsNsName(it, nsChain, result) }
                                if (enumSym != null && enumSym.declarations.any { it is EnumDeclaration }) {
                                    return@run enumSym.exports?.containsKey(member) == true
                                }
                            }
                        }
                        val declType = getDeclaredTypeOfSymbol(s)
                        if (declType === errorType) return
                        getPropertyOfType(declType, member) != null
                    }
                    if (hasMember) {
                        emitTs2713(segs[0].pos, segs[i].pos + member.length, typeName, member, source, fileName)
                    } else {
                        val (line, ch) = getLineAndCharacterOfPosition(source, segs[i - 1].pos)
                        diagnostics.add(Diagnostic(
                            message = "'$typeName' only refers to a type, but is being used as a namespace here.",
                            category = DiagnosticCategory.Error, code = 2702, fileName = fileName,
                            line = line, character = ch, start = segs[i - 1].pos, length = typeName.length,
                        ))
                    }
                } else {
                    // Non-leftmost type reached via a namespace chain: always TS2713 at the member.
                    emitTs2713(segs[i].pos, segs[i].pos + member.length, typeName, member, source, fileName)
                }
                return
            }
            s = s.exports?.get(segs[i].text) ?: return
        }
    }

    private fun emitTs2713(
        start: Int, end: Int, typeName: String, member: String, source: String, fileName: String,
    ) {
        val (line, ch) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Cannot access '$typeName.$member' because '$typeName' is a type, but not a namespace. " +
                "Did you mean to retrieve the type of the property '$member' in '$typeName' with '$typeName[\"$member\"]'?",
            category = DiagnosticCategory.Error, code = 2713, fileName = fileName,
            line = line, character = ch, start = start, length = (end - start).coerceAtLeast(0),
        ))
    }

    private fun checkNamespaceAliasTypeRefs() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration) scanNsAliasTypeRefs(stmt, result.locals, source, fileName)
            }
        }
    }

    private fun scanNsAliasTypeRefs(ns: ModuleDeclaration, fileLocals: SymbolTable, source: String, fileName: String) {
        // Only plain identifier-named, NON-ambient namespaces (`namespace N`). Ambient
        // `declare module "X"` modules route their alias-as-type TS2709 through the
        // existing ambient path — scanning them here double-emits (privacyImportParseErrors,
        // where the module name and the local alias name deliberately collide).
        if (ns.name !is Identifier) return
        if (ModifierFlag.Declare in ns.modifiers) return
        val body = ns.body as? ModuleBlock ?: return
        val aliasTargets = HashMap<String, Symbol>()
        for (s in body.statements) {
            if (s !is ImportEqualsDeclaration) continue
            val ref = s.moduleReference
            val raw = when (ref) {
                is Identifier -> globals[ref.text] ?: fileLocals[ref.text]
                is QualifiedName -> resolveQualifiedName(ref)
                else -> null
            } ?: continue
            val target = resolveAlias(raw)
            // namespace-ONLY target: has Module meaning but no type meaning (a merged
            // class/interface/type-alias/enum makes `X` legally usable as a bare type).
            // A namespace symbol carries NamespaceModule (uninstantiated) or ValueModule
            // (instantiated — has value members), not bare Module.
            if (!target.flags.hasAny(SymbolFlags.Module or SymbolFlags.NamespaceModule or SymbolFlags.ValueModule)) continue
            if (target.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or
                    SymbolFlags.TypeAlias or SymbolFlags.Enum)) continue
            aliasTargets[s.name.text] = target
        }
        if (aliasTargets.isNotEmpty()) {
            for (s in body.statements) walkStmtForNsAlias(s, aliasTargets, source, fileName)
        }
        for (s in body.statements) if (s is ModuleDeclaration) scanNsAliasTypeRefs(s, fileLocals, source, fileName)
    }

    private fun walkStmtForNsAlias(stmt: Statement, aliases: Map<String, Symbol>, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) checkTypeNodeForNsAlias(d.type, aliases, source, fileName)
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is PropertyDeclaration -> checkTypeNodeForNsAlias(m.type, aliases, source, fileName)
                    is MethodDeclaration -> {
                        for (p in m.parameters) checkTypeNodeForNsAlias(p.type, aliases, source, fileName)
                        checkTypeNodeForNsAlias(m.type, aliases, source, fileName)
                        m.body?.statements?.forEach { walkStmtForNsAlias(it, aliases, source, fileName) }
                    }
                    is Constructor -> {
                        for (p in m.parameters) checkTypeNodeForNsAlias(p.type, aliases, source, fileName)
                        m.body?.statements?.forEach { walkStmtForNsAlias(it, aliases, source, fileName) }
                    }
                    is GetAccessor -> checkTypeNodeForNsAlias(m.type, aliases, source, fileName)
                    is SetAccessor -> for (p in m.parameters) checkTypeNodeForNsAlias(p.type, aliases, source, fileName)
                    else -> {}
                }
            }
            is FunctionDeclaration -> {
                for (p in stmt.parameters) checkTypeNodeForNsAlias(p.type, aliases, source, fileName)
                checkTypeNodeForNsAlias(stmt.type, aliases, source, fileName)
                stmt.body?.statements?.forEach { walkStmtForNsAlias(it, aliases, source, fileName) }
            }
            is Block -> stmt.statements.forEach { walkStmtForNsAlias(it, aliases, source, fileName) }
            is IfStatement -> {
                walkStmtForNsAlias(stmt.thenStatement, aliases, source, fileName)
                stmt.elseStatement?.let { walkStmtForNsAlias(it, aliases, source, fileName) }
            }
            is ForStatement -> walkStmtForNsAlias(stmt.statement, aliases, source, fileName)
            is ForInStatement -> walkStmtForNsAlias(stmt.statement, aliases, source, fileName)
            is ForOfStatement -> walkStmtForNsAlias(stmt.statement, aliases, source, fileName)
            is WhileStatement -> walkStmtForNsAlias(stmt.statement, aliases, source, fileName)
            is DoStatement -> walkStmtForNsAlias(stmt.statement, aliases, source, fileName)
            else -> {}
        }
    }

    private fun checkTypeNodeForNsAlias(t: TypeNode?, aliases: Map<String, Symbol>, source: String, fileName: String) {
        if (t == null) return
        when (t) {
            is TypeReference -> {
                when (val tn = t.typeName) {
                    is Identifier -> {
                        // Bare alias used as a type → TS2709.
                        if (tn.text in aliases) {
                            val (line, character) = getLineAndCharacterOfPosition(source, tn.pos)
                            diagnostics.add(Diagnostic(
                                message = "Cannot use namespace '${tn.text}' as a type.",
                                category = DiagnosticCategory.Error, code = 2709,
                                fileName = fileName, line = line, character = character,
                                start = tn.pos, length = tn.text.length,
                            ))
                        }
                    }
                    is QualifiedName -> {
                        // Single-level `X.member`: the alias is the immediate left.
                        val left = tn.left
                        if (left is Identifier) {
                            val target = aliases[left.text]
                            if (target != null) {
                                val memberName = tn.right.text
                                val exists = target.exports?.containsKey(memberName) == true
                                if (exists && !isNameExportedFromNamespace(target, memberName)) {
                                    val exportedMembers = target.exports!!
                                        .filterKeys { isNameExportedFromNamespace(target, it) }
                                    emitTS2694(target.name, memberName, tn.right, source, fileName, exportedMembers)
                                }
                            }
                        }
                    }
                    else -> {}
                }
                t.typeArguments?.forEach { checkTypeNodeForNsAlias(it, aliases, source, fileName) }
            }
            is UnionType -> t.types.forEach { checkTypeNodeForNsAlias(it, aliases, source, fileName) }
            is IntersectionType -> t.types.forEach { checkTypeNodeForNsAlias(it, aliases, source, fileName) }
            is ArrayType -> checkTypeNodeForNsAlias(t.elementType, aliases, source, fileName)
            is ParenthesizedType -> checkTypeNodeForNsAlias(t.type, aliases, source, fileName)
            else -> {}
        }
    }

    private fun checkNamespaceAsTypeInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    checkTypeRefForNamespace(decl.type, source, fileName)
                    decl.initializer?.let { checkTypeRefsInExpr(it, source, fileName) }
                }
            }
            is FunctionDeclaration -> {
                for (param in stmt.parameters) {
                    checkTypeRefForNamespace(param.type, source, fileName)
                }
                checkTypeRefForNamespace(stmt.type, source, fileName)
                stmt.body?.statements?.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (s in body.statements) checkNamespaceAsTypeInStmt(s, source, fileName)
                }
            }
            is ClassDeclaration -> {
                // 16.4cx: `class C2 implements M` (M = namespace) → TS2709 at M.
                // (`class C extends M` is a value position → TS2708, handled elsewhere.)
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ImplementsKeyword) {
                        for (typeExpr in clause.types) {
                            checkHeritageExprForNamespace(typeExpr.expression, source, fileName)
                        }
                    }
                }
                for (member in stmt.members) {
                    when (member) {
                        is PropertyDeclaration -> checkTypeRefForNamespace(member.type, source, fileName)
                        is MethodDeclaration -> {
                            for (param in member.parameters) checkTypeRefForNamespace(param.type, source, fileName)
                            checkTypeRefForNamespace(member.type, source, fileName)
                        }
                        is Constructor -> {
                            for (param in member.parameters) checkTypeRefForNamespace(param.type, source, fileName)
                        }
                        is GetAccessor -> checkTypeRefForNamespace(member.type, source, fileName)
                        is SetAccessor -> {
                            for (param in member.parameters) checkTypeRefForNamespace(param.type, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is InterfaceDeclaration -> {
                // 16.4cx: `interface I extends M` (M = namespace) → TS2709 at M.
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (typeExpr in clause.types) {
                            checkHeritageExprForNamespace(typeExpr.expression, source, fileName)
                        }
                    }
                }
            }
            is ExpressionStatement -> checkTypeRefsInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkTypeRefsInExpr(it, source, fileName) }
            is IfStatement -> {
                checkTypeRefsInExpr(stmt.expression, source, fileName)
                checkNamespaceAsTypeInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is ForStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is ForInStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is ForOfStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is WhileStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is DoStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> c.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                    is DefaultClause -> c.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                    else -> {}
                }
            }
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                stmt.catchClause?.block?.statements?.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                stmt.finallyBlock?.statements?.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is LabeledStatement -> checkNamespaceAsTypeInStmt(stmt.statement, source, fileName)
            is ThrowStatement -> stmt.expression?.let { checkTypeRefsInExpr(it, source, fileName) }
            is ExportAssignment -> checkTypeRefsInExpr(stmt.expression, source, fileName)
            is Block -> stmt.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Walk an expression looking for ArrowFunction / FunctionExpression and check their
     * parameter/return type annotations for namespace-used-as-type.
     */
    private fun checkTypeRefsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                for (p in expr.parameters) checkTypeRefForNamespace(p.type, source, fileName)
                checkTypeRefForNamespace(expr.type, source, fileName)
                val body = expr.body
                if (body is Block) body.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
                else if (body is Expression) checkTypeRefsInExpr(body, source, fileName)
            }
            is FunctionExpression -> {
                for (p in expr.parameters) checkTypeRefForNamespace(p.type, source, fileName)
                checkTypeRefForNamespace(expr.type, source, fileName)
                expr.body.statements.forEach { checkNamespaceAsTypeInStmt(it, source, fileName) }
            }
            is CallExpression -> {
                checkTypeRefsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkTypeRefsInExpr(arg, source, fileName)
            }
            is ParenthesizedExpression -> checkTypeRefsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                // B64.6: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkTypeRefsInExpr(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkTypeRefsInExpr(rightStack.removeLast(), source, fileName)
            }
            else -> {}
        }
    }

    private var currentCheckLocals: SymbolTable? = null
    /** Names with a TYPE-providing declaration (type alias / interface / class / enum) in the
     *  file being scanned by [checkNamespaceUsedAsType]. A `type X` + `namespace X` clodule's
     *  symbol is last-wins in our binder (the namespace overwrites the type alias, dropping the
     *  TypeAlias flag), so the symbol-flag guard in [checkTypeRefForNamespace] misses it — this
     *  AST-derived set suppresses the TS2709 FP for such a name used as a type. */
    private var currentTypeProvidingNames: Set<String> = emptySet()

    /**
     * 16.4cx: Heritage-clause variant — emit TS2709 when an interface `extends X`
     * or class `implements X` and `X` resolves to a namespace-only symbol.
     */
    private fun checkHeritageExprForNamespace(expr: Expression, source: String, fileName: String) {
        if (expr !is Identifier) return
        val name = expr.text
        val symbol = currentCheckLocals?.get(name) ?: globals[name] ?: return
        if (!symbol.flags.hasAny(SymbolFlags.Module)) return
        if (symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Enum)) return
        val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
        diagnostics.add(Diagnostic(
            message = "Cannot use namespace '$name' as a type.",
            category = DiagnosticCategory.Error,
            code = 2709,
            fileName = fileName,
            line = line,
            character = character,
            start = expr.pos,
            length = name.length,
        ))
    }

    private fun checkTypeRefForNamespace(typeNode: TypeNode?, source: String, fileName: String) {
        if (typeNode == null) return
        if (typeNode !is TypeReference) return
        val name = (typeNode.typeName as? Identifier)?.text ?: return
        // Check if name is imported locally via `import X = require("mod")`.
        // If the target module has no `export =`, X is a namespace alias and
        // using it as a type is TS2709.
        val localSym = currentCheckLocals?.get(name)
        if (localSym != null && localSym.flags.hasAny(SymbolFlags.Alias)) {
            val decl = localSym.declarations.firstOrNull()
            // B98.r57: `import * as X from "spec"` used DIRECTLY as a type (`let y: X`)
            // is TS2709 — a namespace import is a value, never a bare type (it can only
            // be a qualifier, `X.Foo`, which this function doesn't reach since typeName
            // must be a bare Identifier). Skip when X ALSO has a type meaning (a merged
            // interface/class/type-alias/enum makes it usable as a type).
            if (decl is ImportDeclaration &&
                !localSym.flags.hasAny(SymbolFlags.Interface or SymbolFlags.Class or
                    SymbolFlags.TypeAlias or SymbolFlags.Enum)) {
                val nb = decl.importClause?.namedBindings
                if (nb is NamespaceImport && nb.name.text == name) {
                    val (line, character) = getLineAndCharacterOfPosition(source, typeNode.typeName.pos)
                    diagnostics.add(Diagnostic(
                        message = "Cannot use namespace '$name' as a type.",
                        category = DiagnosticCategory.Error,
                        code = 2709,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = typeNode.typeName.pos,
                        length = name.length,
                    ))
                    return
                }
            }
            if (decl is ImportEqualsDeclaration) {
                val modRef = decl.moduleReference
                if (modRef is ExternalModuleReference) {
                    val specifierExpr = modRef.expression
                    val moduleSpecifier = (specifierExpr as? StringLiteralNode)?.text
                    if (moduleSpecifier != null) {
                        val targetFile = resolveModuleSpecifier(moduleSpecifier, decl)
                        val targetResult = targetFile?.let { fileResults[it] }
                        if (targetResult != null) {
                            val hasExportEquals = targetResult.sourceFile.statements.any {
                                it is ExportAssignment && it.isExportEquals
                            }
                            if (!hasExportEquals) {
                                val (line, character) = getLineAndCharacterOfPosition(source, typeNode.typeName.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Cannot use namespace '$name' as a type.",
                                    category = DiagnosticCategory.Error,
                                    code = 2709,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = typeNode.typeName.pos,
                                    length = name.length,
                                ))
                            }
                        }
                    }
                }
            }
            return
        }
        val symbol = globals[name] ?: return
        // Check if symbol is ONLY a namespace (no Class, Interface, TypeAlias, Enum)
        if (!symbol.flags.hasAny(SymbolFlags.Module)) return
        if (symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Enum)) return
        // A `type X` + `namespace X` clodule merges last-wins in our binder (the namespace
        // overwrites the type alias, so the symbol lacks the TypeAlias flag above) — but the
        // type alias makes X usable as a type, so suppress TS2709.
        if (name in currentTypeProvidingNames) return
        val (line, character) = getLineAndCharacterOfPosition(source, typeNode.typeName.pos)
        diagnostics.add(Diagnostic(
            message = "Cannot use namespace '$name' as a type.",
            category = DiagnosticCategory.Error,
            code = 2709,
            fileName = fileName,
            line = line,
            character = character,
            start = typeNode.typeName.pos,
            length = name.length,
        ))
    }

    // TS1340: a bare `import("./m")` type reference (no `.qualifier`, not
    // `typeof`) refers to the MODULE (a namespace of exports), not a type — unless
    // the module is `export = <type>`. Used as a type, it's TS1340 "Module './m'
    // does not refer to a type, but is used as a type here. Did you mean 'typeof
    // import('./m')'?". `typeof import(...)` parses to a TypeQuery (not recursed),
    // and `import(...).Foo` has a non-null qualifier (skipped), so both stay valid.
    // -----------------------------------------------------------------------
    private fun checkImportTypeUsedAsType() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) checkImportTypeInStmt(stmt, source, fileName)
        }
    }

    private fun checkImportTypeInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is VariableStatement -> for (d in stmt.declarationList.declarations) visitBareImportType(d.type, source, fileName)
            is FunctionDeclaration -> {
                stmt.parameters.forEach { visitBareImportType(it.type, source, fileName) }
                visitBareImportType(stmt.type, source, fileName)
            }
            is TypeAliasDeclaration -> visitBareImportType(stmt.type, source, fileName)
            is ClassDeclaration -> for (m in stmt.members) checkImportTypeInMember(m, source, fileName)
            is InterfaceDeclaration -> for (m in stmt.members) checkImportTypeInMember(m, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.statements?.forEach { checkImportTypeInStmt(it, source, fileName) }
            else -> {}
        }
    }

    private fun checkImportTypeInMember(member: Node, source: String, fileName: String) {
        when (member) {
            is PropertyDeclaration -> visitBareImportType(member.type, source, fileName)
            is MethodDeclaration -> {
                member.parameters.forEach { visitBareImportType(it.type, source, fileName) }
                visitBareImportType(member.type, source, fileName)
            }
            is GetAccessor -> visitBareImportType(member.type, source, fileName)
            is SetAccessor -> member.parameters.forEach { visitBareImportType(it.type, source, fileName) }
            is Constructor -> member.parameters.forEach { visitBareImportType(it.type, source, fileName) }
            is IndexSignature -> visitBareImportType(member.type, source, fileName)
            else -> {}
        }
    }

    private fun visitBareImportType(type: TypeNode?, source: String, fileName: String) {
        if (type == null) return
        when (type) {
            is ImportType -> {
                // B98.r139: TS2591 for an import-type whose module specifier is a
                // Node.js built-in (`import("module").Foo`, `import("fs")`, …) that
                // doesn't resolve and isn't an ambient `declare module "X"` — the
                // user forgot `@types/node`. Fires REGARDLESS of `.qualifier`
                // (the spec itself is unfindable). Reuses `emitTS2307`, which maps
                // node-builtins under node resolution to the exact TS2591 @types/node
                // hint message; the literal node gives the col-of-opening-quote span.
                // FP firewall: node-builtin name + not ambient + does-not-resolve +
                // no node_modules package + node resolution — corpus-wide only the
                // `importTypeWithUnparenthesizedGenericFunctionParsed` shape matches
                // (the only other node-builtin import-type, `import("url")` in
                // `declarationEmitTripleSlashReferenceAmbientModule`, is excluded by
                // the ambient-module gate).
                run {
                    val litNode = (type.argument as? LiteralType)?.literal as? StringLiteralNode
                    val bareSpec = litNode?.text
                    if (litNode != null && bareSpec != null) {
                        val withoutNodePrefix = bareSpec.removePrefix("node:")
                        val isNodeBuiltin = bareSpec.startsWith("node:") || withoutNodePrefix in NODE_BUILTIN_MODULES
                        // Mirror the import-declaration walker's ambient set: a top-level
                        // `declare module "<spec>"` in any file makes the specifier resolvable.
                        val isAmbientSpec = binderResults.any { br ->
                            br.sourceFile.statements.any { s ->
                                s is ModuleDeclaration && (s.name as? StringLiteralNode)?.text == bareSpec
                            }
                        }
                        if (isNodeBuiltin && !isAmbientSpec) {
                            val moduleRes = options.moduleResolution?.lowercase()
                            val effRes = moduleRes ?: when (options.module) {
                                ModuleKind.CommonJS -> "node10"
                                ModuleKind.Node16, ModuleKind.Node18, ModuleKind.Node20 -> "node16"
                                ModuleKind.NodeNext -> "nodenext"
                                ModuleKind.System, ModuleKind.AMD, ModuleKind.UMD -> "classic"
                                else -> "node10"
                            }
                            val isNodeRes = effRes in setOf("node", "node10", "node16", "nodenext", "bundler")
                            if (isNodeRes) {
                                val targetFile = resolveModuleSpecifierRelative(bareSpec, fileName)
                                    ?: resolveModuleSpecifier(bareSpec, null)
                                if (targetFile == null && !hasNodeModulesPackage(bareSpec)) {
                                    emitTS2307(litNode, bareSpec, source, fileName)
                                }
                            }
                        }
                        // B227: TS2307 for a RELATIVE import-type specifier that doesn't
                        // resolve — `b: import('./b').B` with no ./b in the compilation.
                        // Mirrors the B98.r1 import-declaration gate exactly: explicit
                        // `@module: commonjs` + default moduleResolution + no path/root
                        // config, index-aware resolution fails, no ambient module, no
                        // untyped JS sibling, no @ts-ignore above.
                        val isRelativeSpec = bareSpec.startsWith("./") || bareSpec.startsWith("../")
                        if (isRelativeSpec && !isAmbientSpec
                            && !isJsLikeFileName(fileName) && !isDtsFile(fileName)
                            && options.module == ModuleKind.CommonJS
                            && options.moduleResolution == null
                            && options.paths.isNullOrEmpty()
                            && options.baseUrl == null
                            && options.rootDirs.isNullOrEmpty()
                            && options.rootDir == null
                            && options.moduleSuffixes.isNullOrEmpty()
                            && resolveRelativeIncludingIndex(bareSpec, fileName) == null
                            && resolveRelativeJsSibling(bareSpec, fileName) == null
                        ) {
                            emitTS2307(litNode, bareSpec, source, fileName)
                        }
                    }
                }
                if (type.qualifier == null && !type.isTypeOf && type.typeArguments.isNullOrEmpty()) {
                    val spec = ((type.argument as? LiteralType)?.literal as? StringLiteralNode)?.text
                    if (spec != null) {
                        val targetFile = resolveModuleSpecifierRelative(spec, fileName)
                            ?: resolveModuleSpecifier(spec, null)
                        val targetResult = targetFile?.let { fileResults[it] }
                        if (targetResult != null &&
                            targetResult.sourceFile.statements.none { it is ExportAssignment && it.isExportEquals }) {
                            val closeParen = source.indexOf(')', type.pos)
                            val length = if (closeParen > type.pos) closeParen + 1 - type.pos else spec.length + 9
                            val (line, character) = getLineAndCharacterOfPosition(source, type.pos)
                            diagnostics.add(Diagnostic(
                                message = "Module '$spec' does not refer to a type, but is used as a type here. Did you mean 'typeof import('$spec')'?",
                                category = DiagnosticCategory.Error,
                                code = 1340,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = type.pos,
                                length = length,
                            ))
                        }
                    }
                }
                type.typeArguments?.forEach { visitBareImportType(it, source, fileName) }
            }
            is UnionType -> type.types.forEach { visitBareImportType(it, source, fileName) }
            is IntersectionType -> type.types.forEach { visitBareImportType(it, source, fileName) }
            is ParenthesizedType -> visitBareImportType(type.type, source, fileName)
            is ArrayType -> visitBareImportType(type.elementType, source, fileName)
            is TupleType -> type.elements.forEach { visitBareImportType(it, source, fileName) }
            is TypeReference -> type.typeArguments?.forEach { visitBareImportType(it, source, fileName) }
            is FunctionType -> {
                type.parameters.forEach { visitBareImportType(it.type, source, fileName) }
                visitBareImportType(type.type, source, fileName)
            }
            is ConstructorType -> {
                type.parameters.forEach { visitBareImportType(it.type, source, fileName) }
                visitBareImportType(type.type, source, fileName)
            }
            is ConditionalType -> {
                visitBareImportType(type.checkType, source, fileName)
                visitBareImportType(type.extendsType, source, fileName)
                visitBareImportType(type.trueType, source, fileName)
                visitBareImportType(type.falseType, source, fileName)
            }
            is IndexedAccessType -> {
                visitBareImportType(type.objectType, source, fileName)
                visitBareImportType(type.indexType, source, fileName)
            }
            is TypeOperator -> visitBareImportType(type.type, source, fileName)
            is RestType -> visitBareImportType(type.type, source, fileName)
            is OptionalType -> visitBareImportType(type.type, source, fileName)
            is NamedTupleMember -> visitBareImportType(type.type, source, fileName)
            else -> {} // TypeQuery (typeof import(...) is valid) and leaf types: do not recurse
        }
    }

    // TS2802: Type can only be iterated through when using --downlevelIteration
    // -----------------------------------------------------------------------

    private fun checkDownlevelIteration() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val typedArrayVars = collectTypedArrayVars(result.sourceFile.statements)
            checkDownlevelIterationInStatements(result.sourceFile.statements, source, fileName, typedArrayVars = typedArrayVars)
        }
    }

    private fun checkDownlevelIterationInStatements(
        stmts: List<Statement>, source: String, fileName: String,
        iteratorVars: Set<String> = emptySet(),
        typedArrayVars: Map<String, String> = emptyMap(),
    ) {
        for (stmt in stmts) checkDownlevelIterationInStmt(stmt, source, fileName, iteratorVars, typedArrayVars)
    }

    /** Collect names of vars initialized from `arguments[<expr>]` at this body's top level.
     *  These produce `ArrayIterator<any>` when called, so iterating their result needs TS2802. */
    private fun collectArgumentsIteratorVars(stmts: List<Statement>): Set<String> {
        val names = mutableSetOf<String>()
        for (stmt in stmts) {
            if (stmt !is VariableStatement) continue
            for (decl in stmt.declarationList.declarations) {
                val name = decl.name
                val init = decl.initializer ?: continue
                if (name !is Identifier) continue
                if (init !is ElementAccessExpression) continue
                val target = init.expression
                if (target is Identifier && target.text == "arguments") {
                    names.add(name.text)
                }
            }
        }
        return names
    }

    /** Collect names of vars initialized from `new TypedArrayConstructor(...)` or `new NodeList()`.
     *  Iterating these via `[...x]` under target<ES2015 && !downlevelIteration emits TS2802. */
    private fun collectTypedArrayVars(stmts: List<Statement>): Map<String, String> {
        val names = mutableMapOf<String, String>()
        for (stmt in stmts) {
            if (stmt !is VariableStatement) continue
            for (decl in stmt.declarationList.declarations) {
                val name = decl.name
                val init = decl.initializer ?: continue
                if (name !is Identifier) continue
                if (init !is NewExpression) continue
                val callee = init.expression as? Identifier ?: continue
                if (callee.text in TYPED_ARRAY_CONSTRUCTORS) {
                    names[name.text] = callee.text
                }
            }
        }
        return names
    }

    /** For a `Identifier(...)` call expression, compute the squiggle length covering
     *  the callee identifier through the matching `)`. */
    private fun computeIdentCallSpanLength(callee: Identifier, source: String): Int {
        var i = callee.pos + callee.text.length
        while (i < source.length && source[i].isWhitespace()) i++
        if (i >= source.length || source[i] != '(') return callee.text.length
        var depth = 1
        i++
        while (i < source.length && depth > 0) {
            when (source[i]) {
                '(' -> depth++
                ')' -> depth--
            }
            i++
        }
        return i - callee.pos
    }

    private fun checkDownlevelIterationInStmt(
        stmt: Statement, source: String, fileName: String,
        iteratorVars: Set<String> = emptySet(),
        typedArrayVars: Map<String, String> = emptyMap(),
    ) {
        when (stmt) {
            is ForOfStatement -> {
                // Check if the expression is `arguments` (type IArguments)
                val expr = stmt.expression
                if (expr is Identifier && expr.text == "arguments") {
                    val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                    diagnostics.add(Diagnostic(
                        message = "Type 'IArguments' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                        category = DiagnosticCategory.Error,
                        code = 2802,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = expr.pos,
                        length = expr.text.length,
                    ))
                } else if (expr is CallExpression) {
                    val callee = expr.expression
                    if (callee is Identifier && callee.text in iteratorVars) {
                        val (line, character) = getLineAndCharacterOfPosition(source, callee.pos)
                        val len = computeIdentCallSpanLength(callee, source)
                        diagnostics.add(Diagnostic(
                            message = "Type 'ArrayIterator<any>' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                            category = DiagnosticCategory.Error,
                            code = 2802,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = callee.pos,
                            length = len,
                        ))
                    }
                }
                // Recurse into body
                when (val body = stmt.statement) {
                    is Block -> checkDownlevelIterationInStatements(body.statements, source, fileName, iteratorVars, typedArrayVars)
                    else -> checkDownlevelIterationInStmt(body, source, fileName, iteratorVars, typedArrayVars)
                }
            }
            is ExpressionStatement -> {
                checkDownlevelIterationInExpr(stmt.expression, source, fileName, typedArrayVars)
            }
            is VariableStatement -> {
                // Check for array destructuring from `arguments`: let [x, y, z] = arguments
                for (decl in stmt.declarationList.declarations) {
                    if (decl.name is ArrayBindingPattern && decl.initializer is Identifier) {
                        val init = decl.initializer
                        if (init.text == "arguments") {
                            val bindingPattern = decl.name
                            val start = bindingPattern.pos
                            // Find the closing ] in source text
                            val closeBracket = source.indexOf(']', start)
                            val len = if (closeBracket >= 0) closeBracket - start + 1 else bindingPattern.end - start
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "Type 'IArguments' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                                category = DiagnosticCategory.Error,
                                code = 2802,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = len,
                            ))
                        }
                    }
                }
            }
            is Block -> checkDownlevelIterationInStatements(stmt.statements, source, fileName, iteratorVars, typedArrayVars)
            is IfStatement -> {
                checkDownlevelIterationInStmt(stmt.thenStatement, source, fileName, iteratorVars, typedArrayVars)
                stmt.elseStatement?.let { checkDownlevelIterationInStmt(it, source, fileName, iteratorVars, typedArrayVars) }
            }
            is WhileStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is DoStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is ForStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is ForInStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkDownlevelIterationInStatements(c.statements, source, fileName, iteratorVars, typedArrayVars)
                    is DefaultClause -> checkDownlevelIterationInStatements(c.statements, source, fileName, iteratorVars, typedArrayVars)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkDownlevelIterationInStatements(stmt.tryBlock.statements, source, fileName, iteratorVars, typedArrayVars)
                stmt.catchClause?.let { checkDownlevelIterationInStatements(it.block.statements, source, fileName, iteratorVars, typedArrayVars) }
                stmt.finallyBlock?.let { checkDownlevelIterationInStatements(it.statements, source, fileName, iteratorVars, typedArrayVars) }
            }
            is LabeledStatement -> checkDownlevelIterationInStmt(stmt.statement, source, fileName, iteratorVars, typedArrayVars)
            is FunctionDeclaration -> stmt.body?.let {
                checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
            }
            is ClassDeclaration -> for (member in stmt.members) {
                when (member) {
                    is MethodDeclaration -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    is Constructor -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    is GetAccessor -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    is SetAccessor -> member.body?.let {
                        checkDownlevelIterationInStatements(it.statements, source, fileName, collectArgumentsIteratorVars(it.statements), typedArrayVars)
                    }
                    else -> {}
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                checkDownlevelIterationInStatements(it.statements, source, fileName, iteratorVars, typedArrayVars)
            }
            else -> {}
        }
    }

    /** Check an expression for `[...identifier]` patterns where identifier names a typed-array
     *  variable. Emits TS2802 on the identifier's span. */
    private fun checkDownlevelIterationInExpr(
        expr: Expression, source: String, fileName: String,
        typedArrayVars: Map<String, String>,
    ) {
        if (typedArrayVars.isEmpty()) return
        if (expr !is ArrayLiteralExpression) return
        for (element in expr.elements) {
            if (element !is SpreadElement) continue
            val spreadTarget = element.expression
            if (spreadTarget !is Identifier) continue
            val ctorName = typedArrayVars[spreadTarget.text] ?: continue
            val displayType = if (ctorName == "NodeList") "NodeList" else "$ctorName<ArrayBuffer>"
            val (line, character) = getLineAndCharacterOfPosition(source, spreadTarget.pos)
            diagnostics.add(Diagnostic(
                message = "Type '$displayType' can only be iterated through when using the '--downlevelIteration' flag or with a '--target' of 'es2015' or higher.",
                category = DiagnosticCategory.Error,
                code = 2802,
                fileName = fileName,
                line = line,
                character = character,
                start = spreadTarget.pos,
                length = spreadTarget.text.length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // TS2737: BigInt literals not available below ES2020
    // -----------------------------------------------------------------------

    /**
     * B291: the bigint property-name family (bigintPropertyName).
     *  - TS1539 "A 'bigint' literal cannot be used as a property name." for
     *    BigIntLiteralNode names in object literals, interface members, and class
     *    members (tsc checkPropertyDeclaration + the object-literal grammar walk).
     *  - TS2464 for object-literal COMPUTED names of bigint type (`[1n]` literal /
     *    an identifier annotated `: bigint`); span covers the whole `[...]`.
     *  - TS2538 "Type 'bigint' cannot be used as an index type." for a bigint
     *    binding-pattern property name (`const { 0n: f } = arr`).
     *  - TS2322 (doubled line, tsc style) for a mapped-type constraint resolving to
     *    an all-bigint-literal union (`type T = { [t in Q]: string }`, Q = 6n | 7n) —
     *    a mapped key must be assignable to `string | number | symbol`.
     */
    private fun checkBigintPropertyNames() {
        for (result in checkedResults) {
            val sf = result.sourceFile
            val fileName = sf.fileName
            if (isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = sf.text
            fun emit(code: Int, msg: String, start: Int, length: Int, chain: List<String> = emptyList()) {
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = msg, category = DiagnosticCategory.Error, code = code,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length.coerceAtLeast(1), messageChain = chain,
                ))
            }
            fun emit1539(nm: BigIntLiteralNode) =
                emit(1539, "A 'bigint' literal cannot be used as a property name.", nm.pos, nm.text.length)

            fun identAnnotatedBigint(id: Identifier): Boolean {
                val s = result.locals[id.text] ?: globals[id.text] ?: return false
                val vd = s.declarations.firstOrNull { it is VariableDeclaration } as? VariableDeclaration ?: return false
                return (vd.type as? KeywordTypeNode)?.kind == SyntaxKind.BigIntKeyword
            }

            // Mutually recursive expression/statement visitors as an anonymous object
            // (local funs can't forward-reference). BinaryExpression iterates the LEFT
            // spine (parse trees of `a+b+c+…` are left-deep — the standard new-walker rule).
            val w = object {
                fun expr(e0: Expression?) {
                    var cur: Expression = e0 ?: return
                    while (true) {
                        when (cur) {
                            is BinaryExpression -> { expr(cur.right); cur = cur.left; continue }
                            is ParenthesizedExpression -> { cur = cur.expression; continue }
                            is AsExpression -> { cur = cur.expression; continue }
                            is NonNullExpression -> { cur = cur.expression; continue }
                            is PrefixUnaryExpression -> { cur = cur.operand; continue }
                            is PostfixUnaryExpression -> { cur = cur.operand; continue }
                            is ObjectLiteralExpression -> objLit(cur)
                            is ArrayLiteralExpression -> cur.elements.forEach { expr(it) }
                            is CallExpression -> { expr(cur.expression); cur.arguments.forEach { expr(it) } }
                            is NewExpression -> { expr(cur.expression); cur.arguments?.forEach { expr(it) } }
                            is PropertyAccessExpression -> { cur = cur.expression; continue }
                            is ElementAccessExpression -> { expr(cur.expression); expr(cur.argumentExpression) }
                            is ConditionalExpression -> { expr(cur.condition); expr(cur.whenTrue); expr(cur.whenFalse) }
                            is TemplateExpression -> cur.templateSpans.forEach { expr(it.expression) }
                            is SpreadElement -> { cur = cur.expression; continue }
                            is ArrowFunction -> when (val b = cur.body) {
                                is Block -> stmts(b.statements)
                                is Expression -> expr(b)
                                else -> {}
                            }
                            is FunctionExpression -> cur.body.let { stmts(it.statements) }
                            else -> {}
                        }
                        break
                    }
                }

                fun objLit(obj: ObjectLiteralExpression) {
                    for (p in obj.properties) {
                        val nm = when (p) {
                            is PropertyAssignment -> p.name
                            is MethodDeclaration -> p.name
                            else -> null
                        }
                        if (nm is BigIntLiteralNode) emit1539(nm)
                        if (nm is ComputedPropertyName) {
                            val inner = nm.expression
                            val isBigintKey = inner is BigIntLiteralNode ||
                                (inner is Identifier && identAnnotatedBigint(inner))
                            if (isBigintKey) {
                                var rb = expressionTrueEnd(inner)
                                while (rb < source.length && source[rb] != ']') rb++
                                val end = if (rb < source.length) rb + 1 else expressionTrueEnd(inner)
                                emit(2464, "A computed property name must be of type 'string', 'number', 'symbol', or 'any'.",
                                    nm.pos, end - nm.pos)
                            }
                        }
                        when (p) {
                            is PropertyAssignment -> expr(p.initializer)
                            is SpreadAssignment -> expr(p.expression)
                            is MethodDeclaration -> p.body?.let { stmts(it.statements) }
                            else -> {}
                        }
                    }
                }

                fun bindingName(n: Expression) {
                    when (n) {
                        is ObjectBindingPattern -> for (el in n.elements) {
                            (el.propertyName as? BigIntLiteralNode)?.let {
                                emit(2538, "Type 'bigint' cannot be used as an index type.", it.pos, it.text.length)
                            }
                            bindingName(el.name)
                            expr(el.initializer)
                        }
                        is ArrayBindingPattern -> for (el in n.elements) if (el is BindingElement) {
                            bindingName(el.name); expr(el.initializer)
                        }
                        else -> {}
                    }
                }

                fun classMembers(members: List<ClassElement>) {
                    for (m in members) {
                        val nm = when (m) {
                            is PropertyDeclaration -> m.name
                            is MethodDeclaration -> m.name
                            else -> null
                        }
                        if (nm is BigIntLiteralNode) emit1539(nm)
                        when (m) {
                            is PropertyDeclaration -> expr(m.initializer)
                            is MethodDeclaration -> m.body?.let { stmts(it.statements) }
                            is Constructor -> m.body?.let { stmts(it.statements) }
                            else -> {}
                        }
                    }
                }

                fun mappedAliasConstraint(alias: TypeAliasDeclaration) {
                    val mt = alias.type as? MappedType ?: return
                    val ct = mt.typeParameter.constraint ?: return
                    fun allBigintUnion(t: TypeNode?): Boolean = when (t) {
                        is UnionType -> t.types.isNotEmpty() &&
                            t.types.all { (it as? LiteralType)?.literal is BigIntLiteralNode }
                        is LiteralType -> t.literal is BigIntLiteralNode
                        else -> false
                    }
                    val refName = ((ct as? TypeReference)?.typeName as? Identifier)?.text
                    val resolvesAllBigint = when {
                        allBigintUnion(ct) -> true
                        refName != null -> {
                            val s = result.locals[refName] ?: globals[refName]
                            val ad = s?.declarations?.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                            ad != null && allBigintUnion(ad.type)
                        }
                        else -> false
                    }
                    if (!resolvesAllBigint) return
                    val msg = "Type 'bigint' is not assignable to type 'string | number | symbol'."
                    val len = refName?.length ?: (expressionTrueEnd(mt.typeParameter.name) - ct.pos).coerceAtLeast(1)
                    emit(2322, msg, ct.pos, len, chain = listOf("  $msg"))
                }

                fun stmts(list: List<Statement>) { list.forEach { stmt(it) } }

                fun stmt(s: Node?) {
                    when (s) {
                        is ExpressionStatement -> expr(s.expression)
                        is VariableStatement -> for (d in s.declarationList.declarations) {
                            bindingName(d.name); expr(d.initializer)
                        }
                        is Block -> stmts(s.statements)
                        is IfStatement -> { expr(s.expression); stmt(s.thenStatement); stmt(s.elseStatement) }
                        is WhileStatement -> { expr(s.expression); stmt(s.statement) }
                        is DoStatement -> { stmt(s.statement); expr(s.expression) }
                        is ForStatement -> stmt(s.statement)
                        is ForInStatement -> stmt(s.statement)
                        is ForOfStatement -> stmt(s.statement)
                        is ReturnStatement -> expr(s.expression)
                        is ThrowStatement -> expr(s.expression)
                        is SwitchStatement -> { expr(s.expression); s.caseBlock.forEach { c ->
                            when (c) {
                                is CaseClause -> { expr(c.expression); stmts(c.statements) }
                                is DefaultClause -> stmts(c.statements)
                                else -> {}
                            }
                        } }
                        is TryStatement -> { stmts(s.tryBlock.statements); s.catchClause?.let { stmts(it.block.statements) }; s.finallyBlock?.let { stmts(it.statements) } }
                        is FunctionDeclaration -> s.body?.let { stmts(it.statements) }
                        is InterfaceDeclaration -> for (m in s.members) {
                            val nm = when (m) {
                                is PropertyDeclaration -> m.name
                                is MethodDeclaration -> m.name
                                else -> null
                            }
                            if (nm is BigIntLiteralNode) emit1539(nm)
                        }
                        is ClassDeclaration -> classMembers(s.members)
                        is TypeAliasDeclaration -> mappedAliasConstraint(s)
                        is ModuleDeclaration -> (s.body as? ModuleBlock)?.statements?.let { stmts(it) }
                        is LabeledStatement -> stmt(s.statement)
                        else -> {}
                    }
                }
            }
            w.stmts(sf.statements)
        }
    }

    /**
     * B300: TS2416 for CLASS-EXPRESSION property overrides (the binder never binds
     * ClassExpression — the class-decl override walker can't reach them). Narrow
     * AST shape: `const x = class D extends Base { foo!: DerivedIface }` where both
     * the derived and base `foo` annotations are single-decl index-sig-ONLY
     * interfaces whose string-index VALUES are interfaces differing by member
     * presence — the tsc chain is 'X not assignable to Y' / ''string' index
     * signatures are incompatible.' / missing-prop leaf.
     */
    private fun checkClassExpressionOverrides() {
        for (result in checkedResults) {
            val sf = result.sourceFile
            val fileName = sf.fileName
            if (isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = sf.text
            fun ifaceOf(t: TypeNode?): InterfaceDeclaration? {
                val nm = ((t as? TypeReference)?.typeName as? Identifier)?.text ?: return null
                if ((t).typeArguments != null) return null
                val d = (result.locals[nm] ?: globals[nm])?.declarations?.singleOrNull() as? InterfaceDeclaration
                return if (d != null && d !in builtinLibDecls) d else null
            }
            for (stmt in sf.statements) {
                val vs = stmt as? VariableStatement ?: continue
                for (d in vs.declarationList.declarations) {
                    val ce = d.initializer as? ClassExpression ?: continue
                    val ceName = ce.name?.text ?: continue
                    val baseIdent = ce.heritageClauses
                        ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                        ?.types?.singleOrNull()?.expression as? Identifier ?: continue
                    val baseCls = (result.locals[baseIdent.text] ?: globals[baseIdent.text])
                        ?.declarations?.singleOrNull() as? ClassDeclaration ?: continue
                    for (m in ce.members) {
                        val pd = m as? PropertyDeclaration ?: continue
                        val pn = (pd.name as? Identifier)?.text ?: continue
                        val basePd = baseCls.members.filterIsInstance<PropertyDeclaration>()
                            .singleOrNull { (it.name as? Identifier)?.text == pn } ?: continue
                        val dIface = ifaceOf(pd.type) ?: continue
                        val bIface = ifaceOf(basePd.type) ?: continue
                        if (dIface === bIface) continue
                        // index-sig-ONLY interfaces with string index values that are interfaces
                        fun strIndexValue(i: InterfaceDeclaration): TypeNode? {
                            if (!i.members.all { it is IndexSignature }) return null
                            return i.members.filterIsInstance<IndexSignature>().singleOrNull {
                                (it.parameters.firstOrNull()?.type as? KeywordTypeNode)?.kind == SyntaxKind.StringKeyword
                            }?.type
                        }
                        val dVal = ifaceOf(strIndexValue(dIface) ?: continue) ?: continue
                        val bVal = ifaceOf(strIndexValue(bIface) ?: continue) ?: continue
                        fun memberNames(i: InterfaceDeclaration): Set<String> =
                            i.members.mapNotNull { ((it as? PropertyDeclaration)?.name as? Identifier)?.text }.toSet()
                        val missing = memberNames(bVal).filter { it !in memberNames(dVal) }
                        if (missing.isEmpty()) continue
                        val missingDecl = bVal.members.filterIsInstance<PropertyDeclaration>()
                            .firstOrNull { (it.name as? Identifier)?.text == missing.first() }
                        val related = missingDecl?.let {
                            val (rl, rc) = getLineAndCharacterOfPosition(source, it.name.pos)
                            Diagnostic(
                                message = "'${missing.first()}' is declared here.",
                                category = DiagnosticCategory.Message, code = 2728,
                                fileName = fileName, line = rl, character = rc,
                                start = it.name.pos, length = missing.first().length,
                            )
                        }
                        val (line, character) = getLineAndCharacterOfPosition(source, pd.name.pos)
                        diagnostics.add(Diagnostic(
                            message = "Property '$pn' in type '$ceName' is not assignable to the same property in base type '${baseCls.name?.text}'.",
                            category = DiagnosticCategory.Error, code = 2416,
                            fileName = fileName, line = line, character = character,
                            start = pd.name.pos, length = pn.length,
                            messageChain = listOf(
                                "  Type '${dIface.name.text}' is not assignable to type '${bIface.name.text}'.",
                                "    'string' index signatures are incompatible.",
                                "      Property '${missing.first()}' is missing in type '${dVal.name.text}' but required in type '${bVal.name.text}'.",
                            ),
                            relatedInformation = listOfNotNull(related),
                        ))
                    }
                }
            }
        }
    }

    /**
     * B299: `trans<T>(f: (x: T) => string)` called with an arrow whose first param
     * is a BINDING PATTERN — a binding pattern is NOT an inference source (tsc), so
     * T falls back to `unknown` and the arrow's pattern param can't accept it.
     * TS2345 at the whole arrow with the implied-pattern-type displays
     * (`({ a }: { a: any; }) => any`; defaults render optional `b?: number |
     * undefined` and are DROPPED from the pattern text) + the parameters chain.
     * Gated to single-TP single-param functions whose param is `(x: TP) => <prim>`
     * — any other inference source must bail.
     */
    private fun checkBindingPatternInferenceFallbackArgs() {
        for (result in checkedResults) {
            val sf = result.sourceFile
            val fileName = sf.fileName
            if (isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = sf.text
            fun widenedLit(e: Expression?): String? = when (e) {
                is NumericLiteralNode -> "number"
                is StringLiteralNode -> "string"
                is Identifier -> if (e.text == "true" || e.text == "false") "boolean" else null
                else -> null
            }
            fun patRender(n: Expression): String? = when (n) {
                is Identifier -> n.text
                is ObjectBindingPattern -> {
                    val parts = n.elements.map { el ->
                        if (el.dotDotDotToken) return null
                        val pn = (el.propertyName as? Identifier)?.text
                        val inner = patRender(el.name) ?: return null
                        (pn?.let { "$it: " } ?: "") + inner
                    }
                    "{ ${parts.joinToString(", ")} }"
                }
                is ArrayBindingPattern -> {
                    val parts = n.elements.map { el ->
                        patRender((el as? BindingElement)?.name ?: return null) ?: return null
                    }
                    "[${parts.joinToString(", ")}]"
                }
                else -> null
            }
            fun impliedType(n: Expression): String? = when (n) {
                is Identifier -> "any"
                is ObjectBindingPattern -> {
                    val parts = n.elements.map { el ->
                        if (el.dotDotDotToken) return null
                        val key = (el.propertyName as? Identifier)?.text
                            ?: (el.name as? Identifier)?.text ?: return null
                        if (el.initializer != null) {
                            val t = widenedLit(el.initializer) ?: return null
                            "$key?: $t | undefined;"
                        } else {
                            "$key: ${impliedType(el.name) ?: return null};"
                        }
                    }
                    "{ ${parts.joinToString(" ")} }"
                }
                is ArrayBindingPattern -> {
                    val parts = n.elements.map { el ->
                        impliedType((el as? BindingElement)?.name ?: return null) ?: return null
                    }
                    "[${parts.joinToString(", ")}]"
                }
                else -> null
            }
            for (stmt in sf.statements) {
                val call = (stmt as? ExpressionStatement)?.expression as? CallExpression ?: continue
                if (call.typeArguments != null) continue
                val callee = call.expression as? Identifier ?: continue
                val sym = result.locals[callee.text] ?: globals[callee.text] ?: continue
                val fd = sym.declarations.singleOrNull() as? FunctionDeclaration ?: continue
                if (fd in builtinLibDecls) continue
                val tp = fd.typeParameters?.singleOrNull() ?: continue
                if (tp.constraint != null || tp.default != null) continue
                val fnParam = fd.parameters.singleOrNull() ?: continue
                val fnType = fnParam.type as? FunctionType ?: continue
                val fnTypeParam = fnType.parameters.singleOrNull() ?: continue
                val fnTypeParamName = (fnTypeParam.name as? Identifier)?.text ?: continue
                if (((fnTypeParam.type as? TypeReference)?.typeName as? Identifier)?.text != tp.name.text) continue
                val retKw = (fnType.type as? KeywordTypeNode) ?: continue
                val retRender = when (retKw.kind) {
                    SyntaxKind.StringKeyword -> "string"
                    SyntaxKind.NumberKeyword -> "number"
                    SyntaxKind.BooleanKeyword -> "boolean"
                    else -> continue
                }
                val arg = call.arguments.singleOrNull() as? ArrowFunction ?: continue
                val argParam = arg.parameters.singleOrNull() ?: continue
                if (argParam.type != null) continue
                val pat = argParam.name
                if (pat !is ObjectBindingPattern && pat !is ArrayBindingPattern) continue
                val patText = patRender(pat) ?: continue
                val patType = impliedType(pat) ?: continue
                val bodyRender = when (arg.body) {
                    is Identifier -> "any"
                    is StringLiteralNode -> "string"
                    is NumericLiteralNode -> "number"
                    else -> continue
                }
                val srcDisplay = "($patText: $patType) => $bodyRender"
                val targetDisplay = "($fnTypeParamName: unknown) => $retRender"
                val start = arg.pos
                val length = (expressionTrueEnd(arg) - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$srcDisplay' is not assignable to parameter of type '$targetDisplay'.",
                    category = DiagnosticCategory.Error, code = 2345,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length,
                    messageChain = listOf(
                        "  Types of parameters '__0' and '$fnTypeParamName' are incompatible.",
                        "    Type 'unknown' is not assignable to type '$patType'.",
                    ),
                ))
            }
        }
    }

    /**
     * B297: a STRING-LITERAL argument against a TEMPLATE-LITERAL-TYPE parameter
     * (or an intersection of them) — TemplateLiteralType parsing is SHALLOW
     * (templateSpans always empty; raw source in head.rawText — see the scanner
     * gotcha), so matching is a raw-text regex: literal segments fixed, `${string}`
     * placeholders → `.*`; a placeholder naming a BRANDED string alias
     * (`string & { _brand }`) can never be produced by a plain literal → definite
     * mismatch. Any other placeholder bails. Display = backticked raw text(s)
     * joined ' & ' (tsc unfolds template-literal aliases in displays).
     */
    private fun checkTemplateLiteralParamArgs() {
        for (result in checkedResults) {
            val sf = result.sourceFile
            val fileName = sf.fileName
            if (isJsLikeFileName(fileName) || isDtsFile(fileName)) continue
            val source = sf.text
            fun aliasBodyOf(t: TypeNode): TypeNode? {
                val tr = t as? TypeReference ?: return null
                if (tr.typeArguments != null) return null
                val nm = (tr.typeName as? Identifier)?.text ?: return null
                val sym = result.locals[nm] ?: globals[nm] ?: return null
                return (sym.declarations.singleOrNull() as? TypeAliasDeclaration)?.type
            }
            fun resolveAliases(t0: TypeNode): TypeNode {
                var t = t0
                repeat(3) { aliasBodyOf(t)?.let { b -> t = b } }
                return t
            }
            // true = literal matches, false = definite mismatch, null = unknown
            fun templateVerdict(raw: String, value: String): Boolean? {
                val rx = StringBuilder("^")
                var i = 0
                while (i < raw.length) {
                    val d = raw.indexOf("\${", i)
                    if (d < 0) { rx.append(Regex.escape(raw.substring(i))); break }
                    rx.append(Regex.escape(raw.substring(i, d)))
                    val e = raw.indexOf('}', d)
                    if (e < 0) return null
                    val ph = raw.substring(d + 2, e).trim()
                    if (ph == "string") rx.append(".*") else {
                        val sym = result.locals[ph] ?: globals[ph]
                        val body = (sym?.declarations?.singleOrNull() as? TypeAliasDeclaration)?.type
                        val branded = body is IntersectionType &&
                            body.types.any { it is KeywordTypeNode && it.kind == SyntaxKind.StringKeyword } &&
                            body.types.any { it is TypeLiteral }
                        return if (branded) false else null
                    }
                    i = e + 1
                }
                return Regex(rx.append("$").toString()).matches(value)
            }
            for (stmt in sf.statements) {
                val call = (stmt as? ExpressionStatement)?.expression as? CallExpression ?: continue
                val callee = call.expression as? Identifier ?: continue
                val sym = result.locals[callee.text] ?: globals[callee.text] ?: continue
                val fd = sym.declarations.singleOrNull() as? FunctionDeclaration ?: continue
                if (fd in builtinLibDecls) continue
                args@ for ((i, arg) in call.arguments.withIndex()) {
                    if (arg !is StringLiteralNode) continue
                    val param = fd.parameters.getOrNull(i) ?: continue
                    if (param.dotDotDotToken) continue
                    val ann = resolveAliases(param.type ?: continue)
                    fun innerRaw(t: TemplateLiteralType): String? =
                        t.head.rawText?.removeSurrounding("`")
                    val rawTemplates: List<String> = when (ann) {
                        is TemplateLiteralType -> listOf(innerRaw(ann) ?: continue@args)
                        is IntersectionType -> ann.types.map { t0 ->
                            (resolveAliases(t0) as? TemplateLiteralType)?.let { innerRaw(it) } ?: continue@args
                        }
                        else -> continue@args
                    }
                    var firstFail: String? = null
                    for (raw in rawTemplates) {
                        when (templateVerdict(raw, arg.text)) {
                            false -> if (firstFail == null) firstFail = raw
                            null -> continue@args
                            true -> {}
                        }
                    }
                    if (firstFail == null) continue
                    val display = rawTemplates.joinToString(" & ") { "`$it`" }
                    // tsc adds a per-constituent sub-line for INTERSECTION params only.
                    val chain = if (rawTemplates.size > 1)
                        listOf("  Type '\"${arg.text}\"' is not assignable to type '`$firstFail`'.")
                    else emptyList()
                    val (line, character) = getLineAndCharacterOfPosition(source, arg.pos)
                    diagnostics.add(Diagnostic(
                        message = "Argument of type '\"${arg.text}\"' is not assignable to parameter of type '$display'.",
                        category = DiagnosticCategory.Error, code = 2345,
                        fileName = fileName, line = line, character = character,
                        start = arg.pos, length = (arg.rawText?.length ?: arg.text.length) + 2,
                        messageChain = chain,
                    ))
                }
            }
        }
    }

    private fun checkBigIntLiterals() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue  // .d.ts files are entirely ambient
            val source = result.sourceFile.text
            checkBigIntLiteralsInStmts(result.sourceFile.statements, source, fileName, ambient = false)
        }
    }

    private fun checkBigIntLiteralsInStmts(
        stmts: List<Statement>, source: String, fileName: String, ambient: Boolean
    ) {
        for (stmt in stmts) checkBigIntLiteralsInStmt(stmt, source, fileName, ambient)
    }

    private fun checkBigIntLiteralsInStmt(
        stmt: Statement, source: String, fileName: String, ambient: Boolean
    ) {
        when (stmt) {
            is VariableStatement -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                if (!ambient && !isDeclare) {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    }
                }
            }
            is ExpressionStatement -> {
                if (!ambient) checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
            }
            is ReturnStatement -> {
                if (!ambient) stmt.expression?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
            }
            is Block -> checkBigIntLiteralsInStmts(stmt.statements, source, fileName, ambient)
            is IfStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.thenStatement, source, fileName, ambient = false)
                    stmt.elseStatement?.let { checkBigIntLiteralsInStmt(it, source, fileName, ambient = false) }
                }
            }
            is WhileStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is ForStatement -> {
                if (!ambient) {
                    (stmt.initializer as? Expression)?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    stmt.condition?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    stmt.incrementor?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is ForOfStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is ForInStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                }
            }
            is DoStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                }
            }
            is SwitchStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
                    for (c in stmt.caseBlock) when (c) {
                        is CaseClause -> {
                            checkBigIntLiteralsInExpr(c.expression, source, fileName)
                            checkBigIntLiteralsInStmts(c.statements, source, fileName, ambient = false)
                        }
                        is DefaultClause -> checkBigIntLiteralsInStmts(c.statements, source, fileName, ambient = false)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                if (!ambient) {
                    checkBigIntLiteralsInStmts(stmt.tryBlock.statements, source, fileName, ambient = false)
                    stmt.catchClause?.let { checkBigIntLiteralsInStmts(it.block.statements, source, fileName, ambient = false) }
                    stmt.finallyBlock?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                }
            }
            is LabeledStatement -> {
                if (!ambient) checkBigIntLiteralsInStmt(stmt.statement, source, fileName, ambient = false)
            }
            is ThrowStatement -> {
                if (!ambient) stmt.expression?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
            }
            is ExportAssignment -> {
                if (!ambient) checkBigIntLiteralsInExpr(stmt.expression, source, fileName)
            }
            is FunctionDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                stmt.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = isDeclare) }
            }
            is ClassDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                if (!isDeclare && !ambient) {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            is Constructor -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            is PropertyDeclaration -> {
                                if (ModifierFlag.Declare !in member.modifiers) {
                                    member.initializer?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                                }
                            }
                            is GetAccessor -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            is SetAccessor -> member.body?.let {
                                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
                            }
                            else -> {}
                        }
                    }
                }
            }
            is ModuleDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                val body = stmt.body
                if (body is ModuleBlock) {
                    checkBigIntLiteralsInStmts(body.statements, source, fileName, ambient = ambient || isDeclare)
                }
            }
            else -> {}
        }
    }

    private fun checkBigIntLiteralsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BigIntLiteralNode -> {
                val start = expr.pos
                val length = expr.text.length  // text already includes the trailing 'n'
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "BigInt literals are not available when targeting lower than ES2020.",
                    category = DiagnosticCategory.Error,
                    code = 2737,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
            is PrefixUnaryExpression -> checkBigIntLiteralsInExpr(expr.operand, source, fileName)
            is BinaryExpression -> {
                // Iterative spine walk — deep a+b+c+… chains must not recurse per
                // binary node (the checker-walker rule; DeepExpressionChainTest).
                val work = ArrayDeque<Expression>()
                var e: Expression = expr
                while (true) {
                    while (e is BinaryExpression) { work.addLast(e.right); e = e.left }
                    checkBigIntLiteralsInExpr(e, source, fileName)
                    e = work.removeLastOrNull() ?: break
                }
            }
            is ParenthesizedExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is CallExpression -> {
                checkBigIntLiteralsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkBigIntLiteralsInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkBigIntLiteralsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments ?: emptyList()) checkBigIntLiteralsInExpr(arg, source, fileName)
            }
            is ArrayLiteralExpression -> {
                for (el in expr.elements) checkBigIntLiteralsInExpr(el, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkBigIntLiteralsInExpr(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> checkBigIntLiteralsInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is PropertyAccessExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkBigIntLiteralsInExpr(expr.expression, source, fileName)
                checkBigIntLiteralsInExpr(expr.argumentExpression, source, fileName)
            }
            is ConditionalExpression -> {
                checkBigIntLiteralsInExpr(expr.condition, source, fileName)
                checkBigIntLiteralsInExpr(expr.whenTrue, source, fileName)
                checkBigIntLiteralsInExpr(expr.whenFalse, source, fileName)
            }
            is ArrowFunction -> expr.body.let { body ->
                when (body) {
                    is Block -> checkBigIntLiteralsInStmts(body.statements, source, fileName, ambient = false)
                    is Expression -> checkBigIntLiteralsInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> expr.body.let {
                checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false)
            }
            is AsExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is PostfixUnaryExpression -> checkBigIntLiteralsInExpr(expr.operand, source, fileName)
            is SpreadElement -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
            is VoidExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkBigIntLiteralsInExpr(expr.expression, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) checkBigIntLiteralsInExpr(span.expression, source, fileName)
            is TaggedTemplateExpression -> {
                checkBigIntLiteralsInExpr(expr.tag, source, fileName)
                (expr.template as? TemplateExpression)?.templateSpans?.forEach {
                    checkBigIntLiteralsInExpr(it.expression, source, fileName)
                }
            }
            is CommaListExpression -> for (el in expr.elements) checkBigIntLiteralsInExpr(el, source, fileName)
            is ClassExpression -> for (m in expr.members) when (m) {
                is MethodDeclaration -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is Constructor -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is GetAccessor -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is SetAccessor -> m.body?.let { checkBigIntLiteralsInStmts(it.statements, source, fileName, ambient = false) }
                is PropertyDeclaration -> m.initializer?.let { checkBigIntLiteralsInExpr(it, source, fileName) }
                else -> {}
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2437: Module hidden by local declaration
    // -----------------------------------------------------------------------

    private fun checkModuleHiddenByLocal() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkModuleHiddenInStmts(result.sourceFile.statements, source, fileName, result.locals)
        }
    }

    private fun checkModuleHiddenInStmts(
        stmts: List<Statement>, source: String, fileName: String,
        outerLocals: Map<String, Symbol>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        // Collect local variable names in this namespace
                        val localVarNames = mutableSetOf<String>()
                        for (s in body.statements) {
                            when (s) {
                                is VariableStatement -> {
                                    for (d in s.declarationList.declarations) {
                                        val name = d.name
                                        if (name is Identifier) localVarNames.add(name.text)
                                    }
                                }
                                else -> {}
                            }
                        }

                        // Check import equals declarations
                        for (s in body.statements) {
                            if (s is ImportEqualsDeclaration) {
                                val ref = s.moduleReference
                                if (ref is Identifier) {
                                    val refName = ref.text
                                    // Check if the referenced name is both:
                                    // 1. A local variable in this namespace
                                    // 2. A module/class/namespace in the outer scope
                                    if (refName in localVarNames) {
                                        val outerSymbol = outerLocals[refName] ?: globals[refName]
                                        if (outerSymbol != null && outerSymbol.flags.hasAny(
                                                SymbolFlags.Module or SymbolFlags.Class or SymbolFlags.ValueModule or SymbolFlags.NamespaceModule
                                            )) {
                                            val start = ref.pos
                                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                                            diagnostics.add(Diagnostic(
                                                message = "Module '$refName' is hidden by a local declaration with the same name.",
                                                category = DiagnosticCategory.Error,
                                                code = 2437,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = start,
                                                length = refName.length,
                                            ))
                                        }
                                    }
                                }
                            }
                        }

                        // Recurse into nested namespaces
                        val innerLocals = mutableMapOf<String, Symbol>()
                        innerLocals.putAll(outerLocals)
                        checkModuleHiddenInStmts(body.statements, source, fileName, innerLocals)
                    }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2714: Export assignment expression must be identifier in ambient context
    // -----------------------------------------------------------------------

    /**
     * In ambient contexts (.d.ts files, declare module bodies), `export default X` and
     * `export = X` require X to be an identifier or qualified name (A.B.C), not an
     * arbitrary expression like `2 + 2` or `typeof X`.
     */
    private fun checkAmbientExportAssignmentExpressions() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            val isAmbient = isDtsFile(fileName)
            // Check top-level statements
            checkAmbientExportAssignInStmts(result.sourceFile.statements, source, fileName, isAmbient)
        }
    }

    private fun checkAmbientExportAssignInStmts(
        stmts: List<Statement>, source: String, fileName: String, ambient: Boolean
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ExportAssignment -> {
                    if (!ambient) continue
                    val expr = stmt.expression
                    if (!isIdentifierOrQualifiedName(expr)) {
                        // Compute span: the expression itself
                        val exprStart = expressionTrueStart(expr, source)
                        val exprEnd = expressionTrueEnd(expr)
                        val length = maxOf(1, exprEnd - exprStart)
                        val (line, character) = getLineAndCharacterOfPosition(source, exprStart)
                        diagnostics.add(Diagnostic(
                            message = "The expression of an export assignment must be an identifier or qualified name in an ambient context.",
                            category = DiagnosticCategory.Error,
                            code = 2714,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = exprStart,
                            length = length,
                        ))
                    }
                }
                is ModuleDeclaration -> {
                    val isDeclare = ModifierFlag.Declare in stmt.modifiers
                    val name = stmt.name
                    // Ambient context if: already ambient, or this is `declare module "..."`, or `declare namespace`
                    val isStringLiteralModule = name is StringLiteralNode
                    val newAmbient = ambient || isDeclare || isStringLiteralModule
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkAmbientExportAssignInStmts(body.statements, source, fileName, newAmbient)
                    }
                }
                else -> {}
            }
        }
    }

    /**
     * Returns true if [expr] is an identifier or a chain of property accesses on identifiers
     * (i.e., a qualified name like `A.B.C.D`).
     */
    private fun isIdentifierOrQualifiedName(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> true
            is PropertyAccessExpression -> {
                // Check the chain: `A.B.C` where each part is an identifier
                var current: Expression = expr
                while (current is PropertyAccessExpression) {
                    current = current.expression
                }
                current is Identifier
            }
            else -> false
        }
    }

    /**
     * Returns the true start of an expression (skipping leading trivia).
     */
    private fun expressionTrueStart(expr: Expression, source: String): Int {
        var pos = expr.pos
        // Skip whitespace
        while (pos < source.length && source[pos].isWhitespace()) pos++
        return pos
    }

    // -----------------------------------------------------------------------
    // TS2458: Multiple AMD module name directives
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // TS2725: Class name cannot be 'Object' with CJS/AMD/System/UMD module
    // -----------------------------------------------------------------------

    private fun checkObjectClassNameConflict() {
        // Only fires for CommonJS, AMD, System, or UMD modules
        val moduleName = when (options.effectiveModule) {
            ModuleKind.CommonJS -> "CommonJS"
            ModuleKind.AMD -> "AMD"
            ModuleKind.System -> "System"
            ModuleKind.UMD -> "UMD"
            else -> return
        }
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkObjectClassNameInStatements(result.sourceFile.statements, source, fileName, moduleName)
        }
    }

    private fun checkObjectClassNameInStatements(
        stmts: List<Statement>, source: String, fileName: String, moduleName: String
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Recurse into class member bodies for nested classes
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            is Constructor -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            is GetAccessor -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            is SetAccessor -> member.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                            else -> {}
                        }
                    }
                    val name = stmt.name
                    if (name != null && name.text == "Object") {
                        val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                        diagnostics.add(Diagnostic(
                            message = "Class name cannot be 'Object' when targeting ES5 and above with module $moduleName.",
                            category = DiagnosticCategory.Error,
                            code = 2725,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                        ))
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkObjectClassNameInStatements(body.statements, source, fileName, moduleName)
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                is Block -> checkObjectClassNameInStatements(stmt.statements, source, fileName, moduleName)
                is IfStatement -> {
                    checkObjectClassNameInStatements(listOf(stmt.thenStatement), source, fileName, moduleName)
                    stmt.elseStatement?.let { checkObjectClassNameInStatements(listOf(it), source, fileName, moduleName) }
                }
                is ForStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is ForInStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is ForOfStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is WhileStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is DoStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkObjectClassNameInStatements(clause.statements, source, fileName, moduleName)
                            is DefaultClause -> checkObjectClassNameInStatements(clause.statements, source, fileName, moduleName)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkObjectClassNameInStatements(stmt.tryBlock.statements, source, fileName, moduleName)
                    stmt.catchClause?.block?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                    stmt.finallyBlock?.let { checkObjectClassNameInStatements(it.statements, source, fileName, moduleName) }
                }
                is LabeledStatement -> checkObjectClassNameInStatements(listOf(stmt.statement), source, fileName, moduleName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS4105: Private or protected member cannot be accessed on a type parameter
    // -----------------------------------------------------------------------

    private fun checkIndexedAccessPrivateMembers() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkIndexedAccessPrivateInStatements(result.sourceFile.statements, source, fileName, emptyMap())
        }
    }

    private fun checkIndexedAccessPrivateInStatements(
        stmts: List<Statement>, source: String, fileName: String,
        outerTpConstraints: Map<String, TypeNode>,
    ) {
        for (stmt in stmts) {
            when (stmt) {
                is TypeAliasDeclaration -> {
                    val tpConstraints = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    walkTypeForIndexedAccess(stmt.type, tpConstraints, source, fileName)
                }
                is InterfaceDeclaration -> {
                    val tpConstraints = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    for (member in stmt.members) {
                        walkMemberForIndexedAccess(member, tpConstraints, source, fileName)
                    }
                }
                is ClassDeclaration -> {
                    val classTp = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    for (member in stmt.members) {
                        walkMemberForIndexedAccess(member, classTp, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkIndexedAccessPrivateInStatements(body.statements, source, fileName, outerTpConstraints)
                    }
                }
                is FunctionDeclaration -> {
                    val fnTp = outerTpConstraints + collectTpConstraints(stmt.typeParameters)
                    stmt.body?.let { checkIndexedAccessPrivateInStatements(it.statements, source, fileName, fnTp) }
                }
                is Block -> checkIndexedAccessPrivateInStatements(stmt.statements, source, fileName, outerTpConstraints)
                is IfStatement -> {
                    checkIndexedAccessPrivateInStatements(listOf(stmt.thenStatement), source, fileName, outerTpConstraints)
                    stmt.elseStatement?.let { checkIndexedAccessPrivateInStatements(listOf(it), source, fileName, outerTpConstraints) }
                }
                is ForStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is ForInStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is ForOfStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is WhileStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is DoStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkIndexedAccessPrivateInStatements(clause.statements, source, fileName, outerTpConstraints)
                            is DefaultClause -> checkIndexedAccessPrivateInStatements(clause.statements, source, fileName, outerTpConstraints)
                            else -> {}
                        }
                    }
                }
                is TryStatement -> {
                    checkIndexedAccessPrivateInStatements(stmt.tryBlock.statements, source, fileName, outerTpConstraints)
                    stmt.catchClause?.block?.let { checkIndexedAccessPrivateInStatements(it.statements, source, fileName, outerTpConstraints) }
                    stmt.finallyBlock?.let { checkIndexedAccessPrivateInStatements(it.statements, source, fileName, outerTpConstraints) }
                }
                is LabeledStatement -> checkIndexedAccessPrivateInStatements(listOf(stmt.statement), source, fileName, outerTpConstraints)
                else -> {}
            }
        }
    }

    private fun collectTpConstraints(tps: List<TypeParameter>?): Map<String, TypeNode> {
        if (tps.isNullOrEmpty()) return emptyMap()
        val m = mutableMapOf<String, TypeNode>()
        for (tp in tps) {
            val c = tp.constraint
            if (c != null) m[tp.name.text] = c
        }
        return m
    }

    private fun walkMemberForIndexedAccess(
        member: Node, outerTp: Map<String, TypeNode>,
        source: String, fileName: String,
    ) {
        when (member) {
            is PropertyDeclaration -> member.type?.let { walkTypeForIndexedAccess(it, outerTp, source, fileName) }
            is MethodDeclaration -> {
                val methodTp = outerTp + collectTpConstraints(member.typeParameters)
                for (p in member.parameters) p.type?.let { walkTypeForIndexedAccess(it, methodTp, source, fileName) }
                member.type?.let { walkTypeForIndexedAccess(it, methodTp, source, fileName) }
            }
            else -> {}
        }
    }

    private fun walkTypeForIndexedAccess(
        type: TypeNode, tpConstraints: Map<String, TypeNode>,
        source: String, fileName: String,
    ) {
        when (type) {
            is IndexedAccessType -> {
                walkTypeForIndexedAccess(type.objectType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.indexType, tpConstraints, source, fileName)
                val keyLit = type.indexType as? LiteralType ?: return
                val keyStr = (keyLit.literal as? StringLiteralNode)?.text ?: return
                if (indexedAccessHasPrivateMember(type.objectType, keyStr, tpConstraints, mutableSetOf())) {
                    val closeIdx = source.indexOf(']', type.indexType.pos)
                    if (closeIdx < 0) return
                    val start = type.pos
                    val length = closeIdx + 1 - start
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Private or protected member '$keyStr' cannot be accessed on a type parameter.",
                        category = DiagnosticCategory.Error,
                        code = 4105,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                } else {
                    // B169: `(Foo | Bar)['foo']` where every union constituent declares 'foo'
                    // NON-PUBLIC and no declaring class is shared across ALL constituents —
                    // the synthesized union property is inaccessible, so TS reports TS2339
                    // "Property 'foo' does not exist on type 'Foo | Bar'." TS's actual rule is
                    // "the property symbols must share a common declaration", which is why
                    // `(Foo | (Foo & Bar))['foo']` is LEGAL (the intersection prop carries
                    // Foo's declaration) while `(Foo | Bar)['foo']` is not. Span = the key
                    // literal including quotes (unionPropertyOfProtectedAndIntersectionProperty).
                    val unionDisplay = unionUnrelatedNonPublicPropDisplay(type.objectType, keyStr)
                    if (unionDisplay != null) {
                        val keyNode = keyLit.literal
                        val start = keyNode.pos
                        val length = (keyNode.rawText?.length ?: keyNode.text.length) + 2
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Property '$keyStr' does not exist on type '$unionDisplay'.",
                            category = DiagnosticCategory.Error,
                            code = 2339,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
            }
            is UnionType -> type.types.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is IntersectionType -> type.types.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is ParenthesizedType -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is ArrayType -> walkTypeForIndexedAccess(type.elementType, tpConstraints, source, fileName)
            is TupleType -> type.elements.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is TypeOperator -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is TypeReference -> type.typeArguments?.forEach { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            is FunctionType -> {
                val innerTp = tpConstraints + collectTpConstraints(type.typeParameters)
                for (p in type.parameters) p.type?.let { walkTypeForIndexedAccess(it, innerTp, source, fileName) }
                walkTypeForIndexedAccess(type.type, innerTp, source, fileName)
            }
            is ConstructorType -> {
                val innerTp = tpConstraints + collectTpConstraints(type.typeParameters)
                for (p in type.parameters) p.type?.let { walkTypeForIndexedAccess(it, innerTp, source, fileName) }
                walkTypeForIndexedAccess(type.type, innerTp, source, fileName)
            }
            is ConditionalType -> {
                walkTypeForIndexedAccess(type.checkType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.extendsType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.trueType, tpConstraints, source, fileName)
                walkTypeForIndexedAccess(type.falseType, tpConstraints, source, fileName)
            }
            is MappedType -> {
                type.type?.let { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
                type.nameType?.let { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
                type.typeParameter.constraint?.let { walkTypeForIndexedAccess(it, tpConstraints, source, fileName) }
            }
            is TypeLiteral -> for (m in type.members) walkMemberForIndexedAccess(m, tpConstraints, source, fileName)
            is RestType -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is OptionalType -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            is NamedTupleMember -> walkTypeForIndexedAccess(type.type, tpConstraints, source, fileName)
            else -> {}
        }
    }

    /**
     * B169: for `(C1 | C2 | …)['k']` in TYPE position, returns the union's display string
     * when the synthesized union property `k` is INACCESSIBLE: every constituent declares
     * `k` non-public (protected/private, OWN member of a concrete class — type args /
     * interfaces / unknown shapes bail), and NO declaring class is shared by ALL
     * constituents (TS's "property symbols must share a common declaration" rule — which
     * keeps `(Foo | (Foo & Bar))['foo']` legal). Returns null when the access is fine or
     * the shape is out of model.
     */
    private fun unionUnrelatedNonPublicPropDisplay(objType: TypeNode, propName: String): String? {
        var inner: TypeNode = objType
        while (inner is ParenthesizedType) inner = inner.type
        if (inner !is UnionType || inner.types.size < 2) return null
        val declaringSets = mutableListOf<Set<String>>()
        val displays = mutableListOf<String>()
        for (c in inner.types) {
            val s = nonPublicDeclaringClasses(c, propName) ?: return null
            if (s.isEmpty()) return null
            declaringSets.add(s)
            displays.add(constituentDisplay(c) ?: return null)
        }
        val shared = declaringSets.reduce { a, b -> a intersect b }
        if (shared.isNotEmpty()) return null
        return displays.joinToString(" | ")
    }

    /** B169: set of class names declaring [propName] as a NON-PUBLIC own member, for one
     * union constituent. A bare class ref contributes itself; an intersection contributes
     * every member class that declares it. Returns null (bail) when the prop is PUBLIC
     * anywhere, declared by no constituent class, or the shape is unsupported. */
    private fun nonPublicDeclaringClasses(c: TypeNode, propName: String): Set<String>? {
        var t: TypeNode = c
        while (t is ParenthesizedType) t = t.type
        when (t) {
            is TypeReference -> {
                if (t.typeArguments != null) return null
                val name = (t.typeName as? Identifier)?.text ?: return null
                return when (ownClassPropVisibility(name, propName)) {
                    true -> setOf(name)
                    false -> null // public — access is legal, bail
                    null -> null // absent / not a concrete class — out of model
                }
            }
            is IntersectionType -> {
                val out = mutableSetOf<String>()
                for (m in t.types) {
                    var mm: TypeNode = m
                    while (mm is ParenthesizedType) mm = mm.type
                    val ref = mm as? TypeReference ?: return null
                    if (ref.typeArguments != null) return null
                    val name = (ref.typeName as? Identifier)?.text ?: return null
                    when (ownClassPropVisibility(name, propName)) {
                        true -> out.add(name)
                        false -> return null // public member in the intersection — legal
                        null -> {} // this member doesn't declare it — fine for intersections
                    }
                }
                return out.ifEmpty { null }
            }
            else -> return null
        }
    }

    /** B169: visibility of [propName] as an OWN member of class [className]:
     * true = declared private/protected, false = declared public, null = absent or not a
     * concrete single-declaration class. */
    private fun ownClassPropVisibility(className: String, propName: String): Boolean? {
        val sym = globals[className] ?: return null
        val classDecls = sym.declarations.filterIsInstance<ClassDeclaration>()
        if (classDecls.isEmpty()) return null
        for (decl in classDecls) {
            for (m in decl.members) {
                val (name, mods) = when (m) {
                    is PropertyDeclaration -> (m.name as? Identifier)?.text to m.modifiers
                    is MethodDeclaration -> (m.name as? Identifier)?.text to m.modifiers
                    is GetAccessor -> (m.name as? Identifier)?.text to m.modifiers
                    is SetAccessor -> (m.name as? Identifier)?.text to m.modifiers
                    else -> null to null
                }
                if (name == propName && mods != null) {
                    return ModifierFlag.Private in mods || ModifierFlag.Protected in mods
                }
            }
        }
        return null
    }

    /** B169: display text for one union constituent (bare ref or intersection of refs). */
    private fun constituentDisplay(c: TypeNode): String? {
        var t: TypeNode = c
        while (t is ParenthesizedType) t = t.type
        return when (t) {
            is TypeReference -> (t.typeName as? Identifier)?.text
            is IntersectionType -> {
                val parts = t.types.map { m ->
                    var mm: TypeNode = m
                    while (mm is ParenthesizedType) mm = mm.type
                    ((mm as? TypeReference)?.typeName as? Identifier)?.text ?: return null
                }
                parts.joinToString(" & ")
            }
            else -> null
        }
    }

    /** Returns true if [typeNode] (object side of an IndexedAccessType) refers to at
     * least one class with a private/protected member named [propName]. An intersection
     * constraint returns false — TS allows indexed access through intersection. */
    /**
     * Returns true when [typeNode] names a TYPE PARAMETER (or contains one in a
     * union) whose constraint exposes a private/protected member named [propName].
     * Direct class/interface references that happen to have a same-named private
     * member do NOT count — TS4105's message ("cannot be accessed on a type
     * parameter") only applies when the access is THROUGH a type parameter.
     * `(Foo | Bar)["foo"]` where Foo/Bar are concrete classes with `protected foo`
     * should fire TS2339, not TS4105.
     */
    private fun indexedAccessHasPrivateMember(
        typeNode: TypeNode, propName: String,
        tpConstraints: Map<String, TypeNode>, visited: MutableSet<String>,
    ): Boolean {
        return when (typeNode) {
            is ParenthesizedType -> indexedAccessHasPrivateMember(typeNode.type, propName, tpConstraints, visited)
            is UnionType -> typeNode.types.any { indexedAccessHasPrivateMember(it, propName, tpConstraints, visited) }
            is IntersectionType -> false
            is TypeReference -> {
                val baseName = (typeNode.typeName as? Identifier)?.text ?: return false
                val constraint = tpConstraints[baseName] ?: return false
                if (baseName in visited) return false
                visited.add(baseName)
                val r = constraintHasPrivatePropByName(constraint, propName)
                visited.remove(baseName)
                r
            }
            else -> false
        }
    }

    /**
     * Walks a type-parameter constraint to determine whether it exposes a
     * private/protected member named [propName]. Used by TS4105: the constraint
     * (e.g. `T extends A`) is what determines whether T["x"] would access a
     * private member. Walks through Parenthesized/Union/Intersection wrappers.
     */
    private fun constraintHasPrivatePropByName(typeNode: TypeNode, propName: String): Boolean = when (typeNode) {
        is ParenthesizedType -> constraintHasPrivatePropByName(typeNode.type, propName)
        is UnionType -> typeNode.types.any { constraintHasPrivatePropByName(it, propName) }
        // IntersectionType constraint: TypeScript treats `T extends A & B` indexed
        // access as compatible — the intersection has "merged" access. Do NOT fire
        // TS4105 here (mirrors the pre-existing IntersectionType -> false rule).
        is IntersectionType -> false
        is TypeReference -> {
            val baseName = (typeNode.typeName as? Identifier)?.text
            if (baseName != null) classOrInterfaceHasPrivatePropByName(baseName, propName) else false
        }
        else -> false
    }

    private fun classOrInterfaceHasPrivatePropByName(className: String, propName: String): Boolean {
        val sym = globals[className] ?: return false
        for (decl in sym.declarations) {
            when (decl) {
                is ClassDeclaration -> {
                    for (m in decl.members) {
                        val memberName = when (m) {
                            is PropertyDeclaration -> (m.name as? Identifier)?.text
                            is MethodDeclaration -> (m.name as? Identifier)?.text
                            is GetAccessor -> (m.name as? Identifier)?.text
                            is SetAccessor -> (m.name as? Identifier)?.text
                            else -> null
                        }
                        if (memberName != propName) continue
                        val modifiers = when (m) {
                            is PropertyDeclaration -> m.modifiers
                            is MethodDeclaration -> m.modifiers
                            is GetAccessor -> m.modifiers
                            is SetAccessor -> m.modifiers
                            else -> emptySet()
                        }
                        if (ModifierFlag.Private in modifiers || ModifierFlag.Protected in modifiers) return true
                    }
                }
                else -> {}
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2393: Duplicate function implementation (cross-file)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // TS2300 / TS2451 cross-file: unified identifier conflicts (B93)
    // -----------------------------------------------------------------------

    /**
     * B93: Unified cross-file duplicate-identifier conflicts for top-level declarations
     * in script (non-module) files that MIX a CLASS / TYPE-ALIAS with CONST/LET (or have
     * multiple type-aliases). These are the cases the per-kind checkers miss:
     *  - [checkCrossFileBlockScopedDuplicates] (73b) handles pure const/let/var but not a
     *    class sharing the name, and emits no TS6204 follow-on for 3+ files.
     *  - [checkCrossFileClassConflicts] (73g) handles pure class-vs-class only.
     *  - No checker handled cross-file type-alias conflicts at all.
     *
     * TypeScript reports these PER SPACE (value-space / type-space) with a HUB model: the
     * FIRST-processed declaration occupying the conflicting space is the hub; its
     * diagnostic accumulates a related TS6203 (first other) then TS6204 (subsequent
     * others), and each other declaration points back at the hub (TS6203). The code is
     * TS2451 when any conflicting value-space decl is block-scoped (const/let), else
     * TS2300; type-space conflicts are always TS2300. (This mirrors TypeScript's
     * `mergeSymbol` amalgamation where the first-merged file's declaration stays the
     * persistent target and `lookupOrIssueError` dedup accumulates the related infos.)
     *
     * Gate is narrow to keep the FP surface minimal:
     *  - every declaration of the name is a class / type-alias / const / let (names that
     *    also have a var / function / interface / namespace / enum decl have merge
     *    semantics and are left to their own checkers);
     *  - at most ONE class decl (≥2 classes → pure class-vs-class is 73g's job);
     *  - the name must involve a type-alias OR a class+block-scoped mix (pure const/let →
     *    73b). Block-scoped names emitted here are recorded in
     *    [crossFileIdentifierHandledBlockNames] so 73b skips them.
     */
    private fun checkCrossFileIdentifierConflicts() {
        // One tracked declaration. kind ∈ {"class","typeAlias","const","let"}.
        class IdDecl(
            val name: String, val nameNode: Node, val fileName: String,
            val source: String, val kind: String,
        )
        val byName = mutableMapOf<String, MutableList<IdDecl>>()
        // Names that also have a merge-semantics decl (var/function/interface/namespace/
        // enum) at top level in a script file → bail (leave to their own checkers).
        val bailNames = mutableSetOf<String>()

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> stmt.name?.let {
                        if (it.text.isNotEmpty())
                            byName.getOrPut(it.text) { mutableListOf() }
                                .add(IdDecl(it.text, it, fileName, source, "class"))
                    }
                    is TypeAliasDeclaration -> {
                        val n = stmt.name
                        if (n.text.isNotEmpty())
                            byName.getOrPut(n.text) { mutableListOf() }
                                .add(IdDecl(n.text, n, fileName, source, "typeAlias"))
                    }
                    is VariableStatement -> {
                        val kind = when (stmt.declarationList.flags) {
                            SyntaxKind.ConstKeyword -> "const"
                            SyntaxKind.LetKeyword -> "let"
                            else -> null  // var → merge semantics
                        }
                        for (decl in stmt.declarationList.declarations) {
                            val n = decl.name as? Identifier ?: continue
                            if (n.text.isEmpty()) continue
                            if (kind == null) bailNames.add(n.text)
                            else byName.getOrPut(n.text) { mutableListOf() }
                                .add(IdDecl(n.text, n, fileName, source, kind))
                        }
                    }
                    is FunctionDeclaration -> stmt.name?.let { bailNames.add(it.text) }
                    is InterfaceDeclaration -> bailNames.add(stmt.name.text)
                    is EnumDeclaration -> bailNames.add(stmt.name.text)
                    is ModuleDeclaration -> (stmt.name as? Identifier)?.let { bailNames.add(it.text) }
                    else -> {}
                }
            }
        }

        for ((name, decls) in byName) {
            if (name in bailNames) continue
            if (decls.size < 2) continue
            if (decls.map { it.fileName }.distinct().size < 2) continue
            val classCount = decls.count { it.kind == "class" }
            if (classCount >= 2) continue  // pure/partial class-vs-class → 73g
            val typeAliasCount = decls.count { it.kind == "typeAlias" }
            val hasBlock = decls.any { it.kind == "const" || it.kind == "let" }
            // Must involve a type-alias OR a class+block-scoped mix; pure const/let → 73b.
            if (typeAliasCount == 0 && !(classCount > 0 && hasBlock)) continue

            // value-space occupiers: class, const, let.
            val valueDecls = decls.filter { it.kind == "class" || it.kind == "const" || it.kind == "let" }
            // type-space occupiers: class, type-alias.
            val typeDecls = decls.filter { it.kind == "class" || it.kind == "typeAlias" }

            if (valueDecls.size >= 2 && valueDecls.map { it.fileName }.distinct().size >= 2) {
                val anyBlock = valueDecls.any { it.kind == "const" || it.kind == "let" }
                if (anyBlock) crossFileIdentifierHandledBlockNames.add(name)
                emitCrossFileHubDuplicates(
                    valueDecls.map { CrossFileDupDecl(it.name, it.nameNode, it.fileName, it.source) },
                    if (anyBlock) 2451 else 2300,
                    if (anyBlock) "Cannot redeclare block-scoped variable '$name'."
                    else "Duplicate identifier '$name'.",
                )
            }
            if (typeDecls.size >= 2 && typeDecls.map { it.fileName }.distinct().size >= 2) {
                emitCrossFileHubDuplicates(
                    typeDecls.map { CrossFileDupDecl(it.name, it.nameNode, it.fileName, it.source) },
                    2300, "Duplicate identifier '$name'.",
                )
            }
        }
    }

    /**
     * Emit a cross-file duplicate-identifier conflict with the HUB model (B93): the first
     * declaration in [ordered] (source-processing order) is the hub. The hub's diagnostic
     * relates to each other declaration — TS6203 for the first, TS6204 for the rest. Each
     * other declaration relates back to the hub with a single TS6203.
     */
    private fun emitCrossFileHubDuplicates(ordered: List<CrossFileDupDecl>, code: Int, message: String) {
        if (ordered.size < 2) return
        fun related(targets: List<CrossFileDupDecl>): List<Diagnostic> =
            targets.mapIndexed { idx, other ->
                val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                Diagnostic(
                    message = if (idx == 0) "'${other.name}' was also declared here." else "and here.",
                    category = DiagnosticCategory.Message,
                    code = if (idx == 0) 6203 else 6204,
                    fileName = other.fileName, line = ol, character = oc,
                    start = other.nameNode.pos, length = other.name.length,
                )
            }
        fun emitOne(decl: CrossFileDupDecl, rel: List<Diagnostic>) {
            val (line, ch) = getLineAndCharacterOfPosition(decl.source, decl.nameNode.pos)
            diagnostics.add(Diagnostic(
                message = message,
                category = DiagnosticCategory.Error, code = code,
                fileName = decl.fileName, line = line, character = ch,
                start = decl.nameNode.pos, length = decl.name.length,
                relatedInformation = rel,
            ))
        }
        val hub = ordered.first()
        val others = ordered.drop(1)
        emitOne(hub, related(others))
        for (o in others) emitOne(o, related(listOf(hub)))
    }

    // -----------------------------------------------------------------------
    // TS2451 cross-file: block-scoped variable redeclarations across files
    // -----------------------------------------------------------------------

    /**
     * Check for top-level `let`/`const` redeclarations across non-module files.
     * When multiple non-module files share the global scope, a `let`/`const` in one file
     * conflicts with any same-named `let`, `const`, or `var` in another file.
     * Both files get TS2451 with TS6203 related info pointing to the other file.
     */
    private fun checkCrossFileBlockScopedDuplicates() {
        // Collect top-level let/const/var names from non-module files
        // Map: name → list of (fileName, nameStart, nameLength, isBlockScoped)
        data class VarInfo(val fileName: String, val nameStart: Int, val nameLength: Int, val isBlockScoped: Boolean)
        val varDecls = mutableMapOf<String, MutableList<VarInfo>>()

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip module files — they have their own scope
            if (isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt !is VariableStatement) continue
                val isBlockScoped = stmt.declarationList.flags == SyntaxKind.LetKeyword ||
                    stmt.declarationList.flags == SyntaxKind.ConstKeyword
                for (decl in stmt.declarationList.declarations) {
                    val name = decl.name as? Identifier ?: continue
                    if (name.text.isEmpty()) continue
                    varDecls.getOrPut(name.text) { mutableListOf() }.add(
                        VarInfo(fileName, name.pos, name.text.length, isBlockScoped)
                    )
                }
            }
        }

        // Emit TS2451 for names that appear in multiple files where at least one is block-scoped
        for ((name, infos) in varDecls) {
            if (infos.size < 2) continue
            // B93: skip names whose value-space conflict the unified checker already emitted
            // (those that also have a cross-file class/type-alias declaration).
            if (name in crossFileIdentifierHandledBlockNames) continue
            val anyBlockScoped = infos.any { it.isBlockScoped }
            if (!anyBlockScoped) continue  // only var+var conflicts are TS2300, not TS2451

            // Check for duplicates: skip if all declarations are in the same file
            val fileNames = infos.map { it.fileName }.toSet()
            if (fileNames.size < 2) continue

            // Emit TS2451 for each declaration, with TS6203 pointing to the other declaration(s)
            for (info in infos) {
                val source = binderResults.first { it.sourceFile.fileName == info.fileName }.sourceFile.text
                val (line, character) = getLineAndCharacterOfPosition(source, info.nameStart)
                // Related info: one TS6203 per OTHER file declaring the same name
                val relatedInfo = infos
                    .filter { it.fileName != info.fileName }
                    .map { other ->
                        val otherSource = binderResults.first { it.sourceFile.fileName == other.fileName }.sourceFile.text
                        val (otherLine, otherChar) = getLineAndCharacterOfPosition(otherSource, other.nameStart)
                        Diagnostic(
                            message = "'$name' was also declared here.",
                            category = DiagnosticCategory.Message,
                            code = 6203,
                            fileName = other.fileName,
                            line = otherLine,
                            character = otherChar,
                            start = other.nameStart,
                            length = other.nameLength,
                        )
                    }
                diagnostics.add(Diagnostic(
                    message = "Cannot redeclare block-scoped variable '$name'.",
                    category = DiagnosticCategory.Error,
                    code = 2451,
                    fileName = info.fileName,
                    line = line,
                    character = character,
                    start = info.nameStart,
                    length = info.nameLength,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * 17.108: Cross-file detection of enum-merge conflicts (TS2567).
     *
     * The per-file [checkDuplicateDeclarations] walker only sees declarations
     * within a single file's top-level. When two non-module (script) files
     * share global scope and one declares `enum X` while another declares
     * `class X` / `function X` / `var X` / `interface X`, the merged group
     * is invalid and TS2567 must fire on each non-namespace declaration with
     * TS6203 related info pointing to the cross-file partner(s).
     *
     * Skip:
     *  - module files (separate scope per file)
     *  - .d.ts files (per-file walker also skips them)
     *  - declarations whose own file ALREADY has an enum + non-enum/non-namespace
     *    pair — the per-file walker already emits TS2567 on those positions.
     */
    private fun checkCrossFileEnumConflicts() {
        data class XInfo(
            val name: String, val kind: String,
            val nameNode: Node, val fileName: String, val source: String,
        )
        val byName = mutableMapOf<String, MutableList<XInfo>>()

        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is EnumDeclaration -> byName.getOrPut(stmt.name.text) { mutableListOf() }
                        .add(XInfo(stmt.name.text, "enum", stmt.name, fileName, source))
                    is ClassDeclaration -> stmt.name?.let {
                        byName.getOrPut(it.text) { mutableListOf() }
                            .add(XInfo(it.text, "class", it, fileName, source))
                    }
                    is FunctionDeclaration -> stmt.name?.let {
                        byName.getOrPut(it.text) { mutableListOf() }
                            .add(XInfo(it.text, "function", it, fileName, source))
                    }
                    is InterfaceDeclaration -> byName.getOrPut(stmt.name.text) { mutableListOf() }
                        .add(XInfo(stmt.name.text, "interface", stmt.name, fileName, source))
                    is ModuleDeclaration -> {
                        val n = stmt.name as? Identifier ?: continue
                        byName.getOrPut(n.text) { mutableListOf() }
                            .add(XInfo(n.text, "namespace", n, fileName, source))
                    }
                    is VariableStatement -> {
                        if (stmt.declarationList.flags != SyntaxKind.VarKeyword) continue
                        for (decl in stmt.declarationList.declarations) {
                            val n = decl.name as? Identifier ?: continue
                            if (n.text.isEmpty()) continue
                            byName.getOrPut(n.text) { mutableListOf() }
                                .add(XInfo(n.text, "var", n, fileName, source))
                        }
                    }
                    else -> {}
                }
            }
        }

        for ((_, infos) in byName) {
            if (infos.size < 2) continue
            // Need cross-file presence
            if (infos.map { it.fileName }.toSet().size < 2) continue
            // Need an enum + non-enum/non-namespace partner across the global merged group
            val hasEnum = infos.any { it.kind == "enum" }
            val nonEnumKinds = setOf("class", "function", "var", "interface")
            val hasNonEnum = infos.any { it.kind in nonEnumKinds }
            if (!(hasEnum && hasNonEnum)) continue

            for (info in infos) {
                if (info.kind == "namespace") continue
                // Skip if the per-file walker already emits for this position:
                // its own file's local group has both enum and non-enum.
                val sameFile = infos.filter { it.fileName == info.fileName }
                val sameFileHasEnum = sameFile.any { it.kind == "enum" }
                val sameFileHasNonEnum = sameFile.any { it.kind in nonEnumKinds }
                if (sameFileHasEnum && sameFileHasNonEnum) continue

                val others = infos.filter { it.fileName != info.fileName && it.kind != "namespace" }
                if (others.isEmpty()) continue
                val relatedInfo = others.map { other ->
                    val (oLine, oChar) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                    Diagnostic(
                        message = "'${other.name}' was also declared here.",
                        category = DiagnosticCategory.Message,
                        code = 6203,
                        fileName = other.fileName,
                        line = oLine,
                        character = oChar,
                        start = other.nameNode.pos,
                        length = other.name.length,
                    )
                }
                val (line, character) = getLineAndCharacterOfPosition(info.source, info.nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Enum declarations can only merge with namespace or other enum declarations.",
                    category = DiagnosticCategory.Error,
                    code = 2567,
                    fileName = info.fileName,
                    line = line,
                    character = character,
                    start = info.nameNode.pos,
                    length = info.name.length,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /**
     * B92: Cross-file duplicate-identifier conflicts for MERGED interface members.
     *
     * When the same interface name is declared in two different files that share a
     * scope — global script scope, a `declare global { }` block, or a
     * `declare module "X" { }` block — and a member appears as a PROPERTY in one
     * file and a METHOD in another, the merged interface has a duplicate-identifier
     * conflict (property-vs-method is always a hard conflict in TypeScript).
     *
     * TypeScript amalgamates these per ordered file-pair: when FEWER THAN 8 member
     * names conflict, it emits per-member TS2300 "Duplicate identifier 'X'." with a
     * related TS6203 "'X' was also declared here." pointing to the other file's
     * member. When 8 OR MORE names conflict, it COLLAPSES to a single TS6200 per
     * file ("Definitions of the following identifiers conflict ...: a, b, c") at the
     * file's first non-trivia token, with a related TS6201 "Conflicts are in this
     * file." pointing at the other file's first token. (TypeScript's threshold is
     * `conflictingSymbols.size < 8` → per-member, else collapsed.)
     *
     * Gate is narrow (property-vs-method, cross-file, same interface name in a shared
     * scope) so the FP surface is tiny: such a pairing is always a genuine error.
     */
    private fun checkCrossFileInterfaceMemberConflicts() {
        // A merged-interface member declaration site.
        data class MemberDecl(
            val memberName: String,
            val nameNode: Node,   // member name node (for the squiggle)
            val isMethod: Boolean,
            val fileName: String,
            val source: String,
        )
        // scopeKey -> (interfaceName -> member decls across files). scopeKey is
        // "global" for script/`declare global` interfaces, "module:<spec>" for
        // ambient-module interfaces. Namespace-scoped interfaces are excluded
        // (they do not merge across files).
        val groups = mutableMapOf<String, MutableMap<String, MutableList<MemberDecl>>>()
        val fileSources = mutableMapOf<String, String>()

        fun addInterface(scopeKey: String, iface: InterfaceDeclaration, fileName: String, source: String) {
            val list = groups.getOrPut(scopeKey) { mutableMapOf() }
                .getOrPut(iface.name.text) { mutableListOf() }
            for (member in iface.members) {
                val (nameNode, isMethod) = when (member) {
                    is PropertyDeclaration -> member.name to false
                    is MethodDeclaration -> member.name to true
                    else -> continue
                }
                val text = getMemberNameText(nameNode) ?: continue
                if (text.isEmpty() || text == "new") continue
                list.add(MemberDecl(text, nameNode, isMethod, fileName, source))
            }
        }

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            fileSources[fileName] = source
            val isModule = isModuleFile(result.sourceFile.statements)
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is InterfaceDeclaration ->
                        // A top-level interface merges into the global scope only in
                        // script files; in module files it is module-local.
                        if (!isModule) addInterface("global", stmt, fileName, source)
                    is ModuleDeclaration -> {
                        val body = stmt.body as? ModuleBlock ?: continue
                        val nm = stmt.name
                        when {
                            nm is Identifier && nm.text == "global" ->
                                for (inner in body.statements)
                                    if (inner is InterfaceDeclaration) addInterface("global", inner, fileName, source)
                            nm is StringLiteralNode ->
                                for (inner in body.statements)
                                    if (inner is InterfaceDeclaration)
                                        addInterface("module:" + nm.text, inner, fileName, source)
                            else -> {}
                        }
                    }
                    else -> {}
                }
            }
        }

        // Build conflicting member declarations (property-vs-method, cross-file).
        val entries = mutableListOf<CrossFileDupDecl>()
        for ((_, byIface) in groups) {
            for ((_, members) in byIface) {
                for ((_, decls) in members.groupBy { it.memberName }) {
                    val distinctFiles = decls.map { it.fileName }.distinct()
                    if (distinctFiles.size != 2) continue   // only the common 2-file case
                    // Cross-file property-vs-method conflict: a property in one file
                    // and a method in another (different) file.
                    val propFiles = decls.filter { !it.isMethod }.map { it.fileName }.toSet()
                    val methFiles = decls.filter { it.isMethod }.map { it.fileName }.toSet()
                    val crossConflict = propFiles.any { pf -> methFiles.any { mf -> pf != mf } }
                    if (!crossConflict) continue
                    for (d in decls) entries.add(CrossFileDupDecl(d.memberName, d.nameNode, d.fileName, d.source))
                }
            }
        }
        amalgamateAndEmitCrossFileDuplicates(entries)
    }

    /** One conflicting declaration site for cross-file duplicate-identifier reporting. */
    private class CrossFileDupDecl(
        val name: String,
        val nameNode: Node,
        val fileName: String,
        val source: String,
    )

    /**
     * Shared amalgamation + emission for cross-file duplicate-identifier conflicts
     * (B92). [entries] are the conflicting declaration sites; the caller has already
     * decided they conflict. Groups by name, restricts to the common 2-distinct-file
     * case, amalgamates per ordered file-pair, then for each pair: when FEWER THAN 8
     * names conflict → per-member TS2300 "Duplicate identifier 'X'." + related TS6203
     * "'X' was also declared here."; when 8 OR MORE → collapsed TS6200 "Definitions of
     * the following identifiers conflict ...: a, b, c" at the file's first non-trivia
     * token + related TS6201 "Conflicts are in this file." (TypeScript's threshold is
     * `conflictingSymbols.size < 8`.)
     */
    private fun amalgamateAndEmitCrossFileDuplicates(entries: List<CrossFileDupDecl>) {
        if (entries.isEmpty()) return
        val fileSources = mutableMapOf<String, String>()
        for (e in entries) fileSources.getOrPut(e.fileName) { e.source }

        class PairConflict(val firstFile: String, val secondFile: String) {
            val names = mutableListOf<String>()
            val firstLocs = mutableMapOf<String, MutableList<CrossFileDupDecl>>()
            val secondLocs = mutableMapOf<String, MutableList<CrossFileDupDecl>>()
        }
        val amalgam = mutableMapOf<String, PairConflict>()

        for ((name, decls) in entries.groupBy { it.name }) {
            val distinctFiles = decls.map { it.fileName }.distinct()
            if (distinctFiles.size != 2) continue
            val (fA, fB) = distinctFiles.sorted()
            val pc = amalgam.getOrPut("$fA|$fB") { PairConflict(fA, fB) }
            if (name !in pc.names) pc.names.add(name)
            pc.firstLocs.getOrPut(name) { mutableListOf() }.addAll(decls.filter { it.fileName == fA })
            pc.secondLocs.getOrPut(name) { mutableListOf() }.addAll(decls.filter { it.fileName == fB })
        }

        fun emit2300(decl: CrossFileDupDecl, related: List<CrossFileDupDecl>) {
            val (line, ch) = getLineAndCharacterOfPosition(decl.source, decl.nameNode.pos)
            val rel = related.map { other ->
                val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                Diagnostic(
                    message = "'${decl.name}' was also declared here.",
                    category = DiagnosticCategory.Message, code = 6203,
                    fileName = other.fileName, line = ol, character = oc,
                    start = other.nameNode.pos, length = other.name.length,
                )
            }
            diagnostics.add(Diagnostic(
                message = "Duplicate identifier '${decl.name}'.",
                category = DiagnosticCategory.Error, code = 2300,
                fileName = decl.fileName, line = line, character = ch,
                start = decl.nameNode.pos, length = decl.name.length,
                relatedInformation = rel,
            ))
        }

        fun emit6200(thisFile: String, otherFile: String, list: String) {
            val thisSrc = fileSources[thisFile] ?: return
            val otherSrc = fileSources[otherFile] ?: return
            val (tStart, tLen) = firstTokenSpanOfFile(thisSrc)
            val (oStart, oLen) = firstTokenSpanOfFile(otherSrc)
            val (tLine, tCh) = getLineAndCharacterOfPosition(thisSrc, tStart)
            val (oLine, oCh) = getLineAndCharacterOfPosition(otherSrc, oStart)
            diagnostics.add(Diagnostic(
                message = "Definitions of the following identifiers conflict with those in another file: $list",
                category = DiagnosticCategory.Error, code = 6200,
                fileName = thisFile, line = tLine, character = tCh, start = tStart, length = tLen,
                relatedInformation = listOf(Diagnostic(
                    message = "Conflicts are in this file.",
                    category = DiagnosticCategory.Message, code = 6201,
                    fileName = otherFile, line = oLine, character = oCh, start = oStart, length = oLen,
                )),
            ))
        }

        for ((_, pc) in amalgam) {
            if (pc.names.size < 8) {
                for (name in pc.names) {
                    val firstNodes = pc.firstLocs[name] ?: emptyList()
                    val secondNodes = pc.secondLocs[name] ?: emptyList()
                    for (fn in firstNodes) emit2300(fn, secondNodes)
                    for (sn in secondNodes) emit2300(sn, firstNodes)
                }
            } else {
                val list = pc.names.joinToString(", ")
                emit6200(pc.firstFile, pc.secondFile, list)
                emit6200(pc.secondFile, pc.firstFile, list)
            }
        }
    }

    /**
     * B92d: Cross-file duplicate-identifier conflicts for top-level CLASS declarations
     * in script (non-module) files sharing the global scope. Two same-named class
     * declarations in different script files always conflict (classes never merge with
     * classes), so this is a genuine TS2300 — collapsed to TS6200 when >= 8 names
     * conflict (e.g. `class A..I` in two files). Restricted to script files (module
     * files are scoped separately) and the 2-distinct-file case to keep FP surface
     * minimal. Class-vs-interface / class-vs-namespace MERGES are unaffected (only the
     * class-vs-class pair conflicts; an interface/namespace partner does not rescue it).
     */
    private fun checkCrossFileClassConflicts() {
        val byName = mutableMapOf<String, MutableList<CrossFileDupDecl>>()
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is ClassDeclaration) {
                    val nm = stmt.name ?: continue
                    if (nm.text.isEmpty()) continue
                    byName.getOrPut(nm.text) { mutableListOf() }
                        .add(CrossFileDupDecl(nm.text, nm, fileName, source))
                }
            }
        }
        val entries = mutableListOf<CrossFileDupDecl>()
        for ((_, decls) in byName) {
            // Conflict only when the SAME class name is declared in 2 different files.
            if (decls.map { it.fileName }.distinct().size != 2) continue
            entries.addAll(decls)
        }
        amalgamateAndEmitCrossFileDuplicates(entries)
    }

    /**
     * TS2451: a UMD global declared via `export as namespace X` and a `declare global`
     * `const`/`let X` redeclare the same block-scoped variable X. Both are global VALUE
     * bindings named X → "Cannot redeclare block-scoped variable 'X'." reported at each
     * occurrence (UMD name + each const/let name) with a TS6203 related-info pointing at
     * the other(s). The parser misparses `export as namespace X` (no AST node — see the
     * scanner/parser gotchas), so the UMD side is found by a source regex; the const/let
     * side via the `declare global { ... }` AST. FP-safe: fires ONLY when a name has BOTH
     * a UMD occurrence AND a declare-global const/let occurrence — both are unconditional
     * TS2451 in TypeScript, and .d.ts files (where these live) skip the general duplicate
     * pipeline, so there is no double-emit.
     */
    private fun checkUmdGlobalVsDeclareGlobalConst() {
        data class Occ(val fileName: String, val source: String, val pos: Int, val len: Int)
        val umdByName = mutableMapOf<String, MutableList<Occ>>()
        val constByName = mutableMapOf<String, MutableList<Occ>>()
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            // (WARM.7) round 860: shared with checkCrossFileModuleAugmentationDuplicates.
            for (occ in umdExportAsNamespaceOccurrences(fileName, source)) {
                umdByName.getOrPut(occ.name) { mutableListOf() }
                    .add(Occ(fileName, source, occ.pos, occ.name.length))
            }
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if ((stmt.name as? Identifier)?.text != "global") continue
                if (ModifierFlag.Declare !in stmt.modifiers) continue
                val body = stmt.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s !is VariableStatement) continue
                    val flags = s.declarationList.flags
                    if (flags != SyntaxKind.ConstKeyword && flags != SyntaxKind.LetKeyword) continue
                    for (d in s.declarationList.declarations) {
                        val nm = d.name as? Identifier ?: continue
                        constByName.getOrPut(nm.text) { mutableListOf() }
                            .add(Occ(fileName, source, nm.pos, nm.text.length))
                    }
                }
            }
        }
        for ((name, umd) in umdByName) {
            val cons = constByName[name] ?: continue
            val all = umd + cons
            if (all.size < 2) continue
            for (occ in all) {
                val related = all.filter { it !== occ }.map { other ->
                    val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.pos)
                    Diagnostic(
                        message = "'$name' was also declared here.",
                        category = DiagnosticCategory.Message, code = 6203,
                        fileName = other.fileName, line = ol, character = oc,
                        start = other.pos, length = other.len,
                    )
                }
                val (line, ch) = getLineAndCharacterOfPosition(occ.source, occ.pos)
                diagnostics.add(Diagnostic(
                    message = "Cannot redeclare block-scoped variable '$name'.",
                    category = DiagnosticCategory.Error, code = 2451,
                    fileName = occ.fileName, line = line, character = ch,
                    start = occ.pos, length = occ.len,
                    relatedInformation = related,
                ))
            }
        }
    }

    /**
     * B92d: TS2451 for a block-scoped `export const`/`export let` that is re-declared
     * via `declare module "X"` augmentation(s) of the SAME file-module (which already
     * exports it), or across two augmentations of the same module. Re-declaring an
     * existing block-scoped export through an augmentation is illegal. The original
     * declaration is the "hub": its diagnostic accumulates a related TS6203 (then
     * TS6204 for each subsequent) pointing at each augmentation re-declaration; each
     * augmentation re-declaration points back at the hub (TS6203). The existing
     * `checkCrossFileBlockScopedDuplicates` (step 73b) skips module files, so there is
     * no double-emit. Gate is narrow (augmentation re-declaring an existing
     * block-scoped file-module export) → tiny FP surface.
     */
    private fun checkCrossFileModuleAugmentationDuplicates() {
        class Decl(val name: String, val nameNode: Node, val fileName: String, val source: String)
        fun isBlockScopedExport(stmt: VariableStatement): Boolean =
            ModifierFlag.Export in stmt.modifiers &&
                (stmt.declarationList.flags == SyntaxKind.LetKeyword ||
                    stmt.declarationList.flags == SyntaxKind.ConstKeyword)

        // A file-module's OWN top-level block-scoped exports: moduleFile -> (name -> Decl).
        val ownExports = mutableMapOf<String, MutableMap<String, Decl>>()
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && isBlockScopedExport(stmt)) {
                    for (d in stmt.declarationList.declarations) {
                        val nm = d.name as? Identifier ?: continue
                        ownExports.getOrPut(fileName) { mutableMapOf() }[nm.text] =
                            Decl(nm.text, nm, fileName, source)
                    }
                }
            }
        }

        // Augmentation block-scoped exports grouped by (targetFile, name), in source order.
        val augByTarget = mutableMapOf<Pair<String, String>, MutableList<Decl>>()
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val spec = (stmt.name as? StringLiteralNode)?.text ?: continue
                val body = stmt.body as? ModuleBlock ?: continue
                val target = resolveModuleSpecifierRelative(spec, fileName) ?: continue
                for (inner in body.statements) {
                    if (inner is VariableStatement && isBlockScopedExport(inner)) {
                        for (d in inner.declarationList.declarations) {
                            val nm = d.name as? Identifier ?: continue
                            augByTarget.getOrPut(target to nm.text) { mutableListOf() }
                                .add(Decl(nm.text, nm, fileName, source))
                        }
                    }
                }
            }
        }

        // B555: a `declare global { namespace X { export const Y } }` member ALSO merges into the
        // module projected by `export as namespace X` (a UMD-global module), so project those onto
        // the module's (targetFile, name) conflict groups (exportAsNamespace_augment).
        val umdToModuleFile = mutableMapOf<String, String>()
        for (result in checkedResults) {
            // (WARM.7) round 860: shared with checkUmdGlobalVsDeclareGlobalConst.
            val umdFileName = result.sourceFile.fileName
            for (occ in umdExportAsNamespaceOccurrences(umdFileName, result.sourceFile.text)) {
                umdToModuleFile.getOrPut(occ.name) { umdFileName }
            }
        }
        if (umdToModuleFile.isNotEmpty()) {
            for (result in checkedResults) {
                val fileName = result.sourceFile.fileName
                val source = result.sourceFile.text
                for (stmt in result.sourceFile.statements) {
                    if (stmt !is ModuleDeclaration) continue
                    if ((stmt.name as? Identifier)?.text != "global") continue
                    if (ModifierFlag.Declare !in stmt.modifiers) continue
                    val gbody = stmt.body as? ModuleBlock ?: continue
                    for (ns in gbody.statements) {
                        if (ns !is ModuleDeclaration) continue
                        val nsName = (ns.name as? Identifier)?.text ?: continue
                        val moduleFile = umdToModuleFile[nsName] ?: continue
                        val nsBody = ns.body as? ModuleBlock ?: continue
                        for (inner in nsBody.statements) {
                            if (inner is VariableStatement && isBlockScopedExport(inner)) {
                                for (d in inner.declarationList.declarations) {
                                    val nm = d.name as? Identifier ?: continue
                                    augByTarget.getOrPut(moduleFile to nm.text) { mutableListOf() }
                                        .add(Decl(nm.text, nm, fileName, source))
                                }
                            }
                        }
                    }
                }
            }
        }

        fun emit2451(decl: Decl, related: List<Decl>) {
            val (line, ch) = getLineAndCharacterOfPosition(decl.source, decl.nameNode.pos)
            val rel = related.mapIndexed { idx, other ->
                val (ol, oc) = getLineAndCharacterOfPosition(other.source, other.nameNode.pos)
                Diagnostic(
                    message = if (idx == 0) "'${decl.name}' was also declared here." else "and here.",
                    category = DiagnosticCategory.Message,
                    code = if (idx == 0) 6203 else 6204,
                    fileName = other.fileName, line = ol, character = oc,
                    start = other.nameNode.pos, length = other.name.length,
                )
            }
            diagnostics.add(Diagnostic(
                message = "Cannot redeclare block-scoped variable '${decl.name}'.",
                category = DiagnosticCategory.Error, code = 2451,
                fileName = decl.fileName, line = line, character = ch,
                start = decl.nameNode.pos, length = decl.name.length,
                relatedInformation = rel,
            ))
        }

        for ((key, augs) in augByTarget) {
            val (target, name) = key
            val own = ownExports[target]?.get(name)
            val total = (if (own != null) 1 else 0) + augs.size
            if (total < 2) continue   // single declaration: a valid augmentation, no conflict
            val hub: Decl
            val others: List<Decl>
            if (own != null) {
                hub = own
                others = augs.sortedWith(compareBy({ it.fileName }, { it.nameNode.pos }))
            } else {
                hub = augs.first()
                others = augs.drop(1).sortedWith(compareBy({ it.fileName }, { it.nameNode.pos }))
            }
            emit2451(hub, others)
            for (o in others) emit2451(o, listOf(hub))
        }
    }

    /**
     * B412: TS2300/TS2451 for a name declared in a `declare module "X"` AUGMENTATION that
     * is ALSO re-exported into module X via `export {N} from './other'`. Both contribute N
     * to module X's shape → duplicate. tsc reports at BOTH the augmentation declaration and
     * the re-export specifier, each with a TS6203 "was also declared here" pointing at the
     * other.
     *
     * Code by augmentation-decl kind: a TYPE-ALIAS augmentation decl → TS2300 (type aliases
     * never declaration-merge); a block-scoped const/let → TS2451 (block-scoped values can't
     * merge with a re-exported value). The whole `.d.ts` duplicate-identifier pipeline is
     * skipped, and the B92d augmentation walker only handles the target's OWN exports (not
     * re-exports) with EXPORTED augmentation decls — so this shape (non-exported aug decl vs
     * a re-export) is uncovered. FP-safe: a re-exported name + a non-mergeable augmentation
     * decl (type alias / block-scoped var) is always a genuine duplicate.
     *
     * The `.`/`./` package-index specifier (which `resolveModuleSpecifier` doesn't resolve)
     * is handled locally via [resolveAugmentationTargetFile] — the sibling `index.{ts,d.ts}`
     * in the augmentation file's directory.
     */
    private fun checkModuleAugmentationReexportDuplicates() {
        for (result in binderResults) {
            val augFile = result.sourceFile.fileName
            val augSource = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val spec = (stmt.name as? StringLiteralNode)?.text ?: continue
                val body = stmt.body as? ModuleBlock ?: continue
                val targetFile = resolveAugmentationTargetFile(spec, augFile) ?: continue
                if (targetFile == augFile) continue
                val targetResult = binderResults.firstOrNull { it.sourceFile.fileName == targetFile } ?: continue
                // Re-exported names in the target module (`export {N} from './x'`).
                val reexports = mutableMapOf<String, Identifier>()
                for (ts in targetResult.sourceFile.statements) {
                    if (ts !is ExportDeclaration || ts.moduleSpecifier == null) continue
                    val clause = ts.exportClause as? NamedExports ?: continue
                    for (es in clause.elements) {
                        if (es.name.text !in reexports) reexports[es.name.text] = es.name
                    }
                }
                if (reexports.isEmpty()) continue
                // Augmentation decls that MERGE into the module: when the body has module
                // syntax (export statements) only exported decls merge, otherwise all do.
                val augHasModuleSyntax = body.statements.any { it is ExportDeclaration || it is ExportAssignment }
                for (bs in body.statements) {
                    when (bs) {
                        is TypeAliasDeclaration -> {
                            if (augHasModuleSyntax && ModifierFlag.Export !in bs.modifiers) continue
                            val re = reexports[bs.name.text] ?: continue
                            emitAugReexportDup(bs.name.text, bs.name, augFile, augSource, re,
                                targetFile, targetResult.sourceFile.text, 2300)
                        }
                        is VariableStatement -> {
                            if (augHasModuleSyntax && ModifierFlag.Export !in bs.modifiers) continue
                            val flags = bs.declarationList.flags
                            if (flags != SyntaxKind.ConstKeyword && flags != SyntaxKind.LetKeyword) continue
                            for (d in bs.declarationList.declarations) {
                                val n = d.name as? Identifier ?: continue
                                val re = reexports[n.text] ?: continue
                                emitAugReexportDup(n.text, n, augFile, augSource, re,
                                    targetFile, targetResult.sourceFile.text, 2451)
                            }
                        }
                        else -> {}
                    }
                }
            }
        }
    }

    /** B412: resolve a `declare module "spec"` augmentation's target source file. Handles the
     *  `.`/`./` package-index specifier (sibling `index.{ts,tsx,d.ts}` in the augmentation
     *  file's directory) which [resolveModuleSpecifier] does not; otherwise delegates. */
    private fun resolveAugmentationTargetFile(spec: String, augFile: String): String? {
        if (spec == "." || spec == "./") {
            val dir = augFile.substringBeforeLast('/', "")
            for (idx in listOf("index.ts", "index.tsx", "index.d.ts")) {
                val cand = if (dir.isEmpty()) idx else "$dir/$idx"
                if (binderResults.any { it.sourceFile.fileName == cand }) return cand
            }
            return null
        }
        return resolveModuleSpecifierRelative(spec, augFile)
    }

    /** B412: emit the symmetric TS2300/TS2451 duplicate pair (augmentation decl ↔ re-export
     *  specifier), each carrying a TS6203 "was also declared here" pointing at the other. */
    private fun emitAugReexportDup(
        name: String, augNode: Node, augFile: String, augSource: String,
        reNode: Identifier, reFile: String, reSource: String, code: Int,
    ) {
        val msg = if (code == 2451) "Cannot redeclare block-scoped variable '$name'."
                  else "Duplicate identifier '$name'."
        fun skipTrivia(src: String, p: Int): Int {
            var i = p
            while (i < src.length && (src[i] == ' ' || src[i] == '\t' || src[i] == '\r' || src[i] == '\n')) i++
            return i
        }
        val augPos = skipTrivia(augSource, augNode.pos)
        val rePos = skipTrivia(reSource, reNode.pos)
        val (al, ac) = getLineAndCharacterOfPosition(augSource, augPos)
        val (rl, rc) = getLineAndCharacterOfPosition(reSource, rePos)
        diagnostics.add(Diagnostic(
            message = msg, category = DiagnosticCategory.Error, code = code,
            fileName = augFile, line = al, character = ac, start = augPos, length = name.length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' was also declared here.", category = DiagnosticCategory.Message, code = 6203,
                fileName = reFile, line = rl, character = rc, start = rePos, length = name.length)),
        ))
        diagnostics.add(Diagnostic(
            message = msg, category = DiagnosticCategory.Error, code = code,
            fileName = reFile, line = rl, character = rc, start = rePos, length = name.length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' was also declared here.", category = DiagnosticCategory.Message, code = 6203,
                fileName = augFile, line = al, character = ac, start = augPos, length = name.length)),
        ))
    }

    /**
     * B553: a checkJs CJS `module.exports = { name: "<lit>" }` JS module exports `name` (typed
     * `string` from the literal); a cross-file `declare module "./X"` augmentation that ALSO
     * declares `export const/var name: T` is a DUPLICATE → TS2300 at BOTH the augmentation decl
     * and the CJS object-literal key (symmetric TS6203). Additionally, since the JS export wins
     * (`name` is `string`), an `import { name } from "./X"; name.<method>()` where <method> is
     * absent from `string`'s apparent type → TS2551 (+ TS2728). Purely ADDITIVE: a CJS import
     * resolves to `any` today (B152/B153 `.js` skip is NOT un-gated), so the general paths emit
     * nothing. FP firewall (corpus-unique, jsExportMemberMergedWithModuleAugmentation2): the
     * augmentation member must be `export const/var` (a VALUE re-declaration — an `interface`
     * legally merges with a JS class export, base sibling excluded) AND the CJS target must be
     * `module.exports = {objLit}` with a matching STRING-LITERAL-valued key.
     */
    private fun checkCjsExportAugmentationConflict() {
        if (!options.checkJs) return
        for (result in binderResults) {
            val augFile = result.sourceFile.fileName
            val augSource = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val spec = (stmt.name as? StringLiteralNode)?.text ?: continue
                val body = stmt.body as? ModuleBlock ?: continue
                // JS-aware resolution (resolveAugmentationTargetFile/resolveModuleSpecifier
                // deliberately skip .js extensions) — the CJS target is a `.js` file.
                val targetFile = resolveRelativeIncludingIndex(spec, augFile)
                    ?: resolveAugmentationTargetFile(spec, augFile) ?: continue
                if (targetFile == augFile || !isJsLikeFileName(targetFile)) continue
                val targetResult = binderResults.firstOrNull { it.sourceFile.fileName == targetFile } ?: continue
                // Collect `module.exports = {objLit}` STRING-literal-valued keys → name node.
                val cjsStringExports = collectCjsObjectLiteralStringExports(targetResult.sourceFile)
                if (cjsStringExports.isEmpty()) continue
                // PIECE 1: augmentation `export const/var name` matching a CJS string key → TS2300.
                val conflicted = HashSet<String>()
                for (bs in body.statements) {
                    if (bs !is VariableStatement) continue
                    if (ModifierFlag.Export !in bs.modifiers) continue
                    val flags = bs.declarationList.flags
                    if (flags != SyntaxKind.ConstKeyword && flags != SyntaxKind.LetKeyword &&
                        flags != SyntaxKind.VarKeyword) continue
                    for (d in bs.declarationList.declarations) {
                        val n = d.name as? Identifier ?: continue
                        val cjsNode = cjsStringExports[n.text] ?: continue
                        emitAugReexportDup(n.text, n, augFile, augSource, cjsNode,
                            targetFile, targetResult.sourceFile.text, 2300)
                        conflicted.add(n.text)
                    }
                }
                if (conflicted.isEmpty()) continue
                // PIECE 2: `import { name } from "<spec>"` then `name.<method>()` where the import
                // binds a conflicted CJS string export and <method> ∉ string → TS2551.
                val importedStringNames = HashSet<String>()
                for (s in result.sourceFile.statements) {
                    if (s !is ImportDeclaration) continue
                    if ((s.moduleSpecifier as? StringLiteralNode)?.text != spec) continue
                    val named = (s.importClause?.namedBindings as? NamedImports) ?: continue
                    for (el in named.elements) {
                        val local = el.name.text
                        // imported source name (alias `X as Y` → propertyName=X) must be conflicted
                        val srcName = (el.propertyName?.text) ?: local
                        if (srcName in conflicted) importedStringNames.add(local)
                    }
                }
                if (importedStringNames.isNotEmpty()) {
                    emitCjsStringImportMethodAccess(result.sourceFile, augFile, augSource, importedStringNames)
                }
            }
        }
    }

    /** B553: collect `module.exports = { key: "<string literal>" }` keys → key Identifier node. */
    private fun collectCjsObjectLiteralStringExports(sf: SourceFile): Map<String, Identifier> {
        val out = HashMap<String, Identifier>()
        for (stmt in sf.statements) {
            val bin = (stmt as? ExpressionStatement)?.expression as? BinaryExpression ?: continue
            if (bin.operator != SyntaxKind.Equals) continue
            val lhs = bin.left as? PropertyAccessExpression ?: continue
            if ((lhs.expression as? Identifier)?.text != "module" || lhs.name.text != "exports") continue
            val rhs = bin.right as? ObjectLiteralExpression ?: continue
            for (p in rhs.properties) {
                if (p !is PropertyAssignment) continue
                val nameId = p.name as? Identifier ?: continue
                if (p.initializer is StringLiteralNode) out.getOrPut(nameId.text) { nameId }
            }
        }
        return out
    }

    /** B553: emit TS2551 for `name.<method>()` (name ∈ [names], typed `string`) where <method>
     *  is not a `string` apparent-type member, with a `Did you mean '<sugg>'?` spelling hint. */
    private fun emitCjsStringImportMethodAccess(
        sf: SourceFile, file: String, src: String, names: Set<String>,
    ) {
        val apparent = getApparentType(stringType) as? Type.Object ?: return
        resolveStructuredTypeMembers(apparent)
        val memberNames = (apparent.properties ?: emptyList()).map { it.name }.toSet()
        fun handleAccess(pa: PropertyAccessExpression) {
            if ((pa.expression as? Identifier)?.text !in names) return
            val method = pa.name.text
            if (method in RUNTIME_PROPERTIES || method in memberNames) return
            val suggestion = getSpellingSuggestionFromNames(method, memberNames)
            val nameNode = pa.name
            val diagStart = nameNode.pos
            val (line, character) = getLineAndCharacterOfPosition(src, diagStart)
            val related = if (suggestion != null) {
                val sp = apparent.properties?.find { it.name == suggestion }
                val decl = sp?.valueDeclaration ?: sp?.declarations?.firstOrNull()
                val declPos = when (val dn = (decl as? PropertyDeclaration)?.name ?: (decl as? MethodDeclaration)?.name) {
                    is Identifier -> dn.pos
                    else -> decl?.pos ?: 0
                }
                // M2.2 (round 394): node-first lib attribution (see libFileOfDecl) — under
                // multi-file real libs a lib member's position false-matches a large user
                // file (`fixed` on the real String interface → /index.ts:8:18528). The map
                // is empty under the embedded lib, so this is byte-identical there.
                val libMapped = libFileOfDecl(decl)
                val (declFile, _) = if (libMapped != null) Pair(libMapped, null)
                    else resolveDeclarationSourceFile(declPos)
                val resolvedFile = declFile ?: file
                val isLib = libMapped != null || isLibFileName(resolvedFile)
                val baselineFile = if (isLib && suggestion in DEPRECATED_STRING_HTML_HELPERS)
                    "lib.es2015.core.d.ts" else resolvedFile
                listOf(Diagnostic(
                    message = "'$suggestion' is declared here.", category = DiagnosticCategory.Message,
                    code = 2728, fileName = baselineFile,
                    line = if (isLib) null else getLineAndCharacterOfPosition(src, declPos).first,
                    character = if (isLib) null else getLineAndCharacterOfPosition(src, declPos).second,
                    start = declPos, length = suggestion.length))
            } else emptyList()
            val msg = if (suggestion != null)
                "Property '$method' does not exist on type 'string'. Did you mean '$suggestion'?"
            else "Property '$method' does not exist on type 'string'."
            diagnostics.add(Diagnostic(
                message = msg, category = DiagnosticCategory.Error,
                code = if (suggestion != null) 2551 else 2339,
                fileName = file, line = line, character = character,
                start = diagStart, length = method.length, relatedInformation = related))
        }
        for (stmt in sf.statements) {
            val expr = (stmt as? ExpressionStatement)?.expression ?: continue
            val callee = (expr as? CallExpression)?.expression ?: expr
            (callee as? PropertyAccessExpression)?.let { handleAccess(it) }
        }
    }

    /**
     * Span of the first non-trivia token in [source] (start position + length).
     * Mirrors TypeScript's `getSpanOfTokenAtPosition(sourceFile, skipTrivia(text, 0))`
     * used when a diagnostic is reported on a whole SourceFile node (e.g. TS6200).
     * Skips whitespace, line comments (`//`, `///`) and block comments, then reads
     * the leading identifier/keyword run (e.g. `interface`, `class`, `declare`).
     */
    private fun firstTokenSpanOfFile(source: String): Pair<Int, Int> {
        var i = 0
        val n = source.length
        loop@ while (i < n) {
            when (source[i]) {
                ' ', '\t', '\r', '\n', '\u000B', '\u000C', '\u00A0', '\uFEFF' -> i++
                '/' -> when {
                    i + 1 < n && source[i + 1] == '/' -> {
                        i += 2
                        while (i < n && source[i] != '\n' && source[i] != '\r') i++
                    }
                    i + 1 < n && source[i + 1] == '*' -> {
                        i += 2
                        while (i + 1 < n && !(source[i] == '*' && source[i + 1] == '/')) i++
                        i = (i + 2).coerceAtMost(n)
                    }
                    else -> break@loop
                }
                else -> break@loop
            }
        }
        val start = i
        if (i >= n) return start to 0
        val c0 = source[i]
        if (c0.isLetter() || c0 == '_' || c0 == '$') {
            var j = i + 1
            while (j < n && (source[j].isLetterOrDigit() || source[j] == '_' || source[j] == '$')) j++
            return start to (j - start)
        }
        return start to 1
    }

    /**
     * Resolved declaration of a name in a module file, following `export * from`
     * and `export { X } from` re-export chains.
     */
    private class ReexportedDecl(
        val stmt: Statement, val nameNode: Node, val fileName: String, val source: String,
    )

    /**
     * Find the declaration of [name] exported (possibly re-exported) by [fileName].
     * Follows `export * from "Y"` and `export { name } from "Y"` chains. Returns the
     * concrete declaration (class/function/interface/enum/var) or null.
     */
    private fun findExportedDeclAcrossReexports(
        fileName: String, name: String, visited: MutableSet<String>,
    ): ReexportedDecl? {
        if (!visited.add(fileName)) return null
        val res = fileResults[fileName] ?: return null
        val source = res.sourceFile.text
        // Direct declarations first.
        for (stmt in res.sourceFile.statements) {
            when (stmt) {
                is ClassDeclaration -> stmt.name?.let {
                    if (it.text == name) return ReexportedDecl(stmt, it, fileName, source)
                }
                is FunctionDeclaration -> stmt.name?.let {
                    if (it.text == name) return ReexportedDecl(stmt, it, fileName, source)
                }
                is InterfaceDeclaration ->
                    if (stmt.name.text == name) return ReexportedDecl(stmt, stmt.name, fileName, source)
                is EnumDeclaration ->
                    if (stmt.name.text == name) return ReexportedDecl(stmt, stmt.name, fileName, source)
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    val n = d.name as? Identifier ?: continue
                    if (n.text == name) return ReexportedDecl(stmt, n, fileName, source)
                }
                else -> {}
            }
        }
        // Re-export chains.
        for (stmt in res.sourceFile.statements) {
            if (stmt !is ExportDeclaration) continue
            val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val target = resolveModuleSpecifier(spec, stmt) ?: continue
            val clause = stmt.exportClause
            if (clause == null) {
                // export * from "Y" — name passes through unchanged
                findExportedDeclAcrossReexports(target, name, visited)?.let { return it }
            } else if (clause is NamedExports) {
                // export { X as name } from "Y" — look up the original X under name
                for (el in clause.elements) {
                    if (el.name.text != name) continue
                    val original = el.propertyName?.text ?: el.name.text
                    findExportedDeclAcrossReexports(target, original, visited)?.let { return it }
                }
            }
        }
        return null
    }

    /**
     * TS2567 for a `declare module "X" { export enum E { ... } }` augmentation whose
     * target module "X" (possibly via `export * from`) already declares a non-enum,
     * non-namespace `E` (class/function/var/interface). The per-file and cross-file
     * (script) walkers don't see this shape: the augmentation lives in a module file
     * and the conflicting partner is reached only through module-specifier + re-export
     * resolution. Emits TS2567 on BOTH the enum name and the partner declaration name,
     * each with a TS6203 "was also declared here" related info pointing at the other.
     */
    private fun checkModuleAugmentationEnumMerge() {
        for (result in checkedResults) {
            val augFile = result.sourceFile.fileName
            if (isDtsFile(augFile)) continue
            val augSource = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val specName = (stmt.name as? StringLiteralNode)?.text ?: continue
                val body = stmt.body as? ModuleBlock ?: continue
                val targetFile = resolveModuleSpecifier(specName, stmt) ?: continue
                if (targetFile == augFile) continue
                for (inner in body.statements) {
                    val enumDecl = inner as? EnumDeclaration ?: continue
                    val enumName = enumDecl.name.text
                    val partner = findExportedDeclAcrossReexports(targetFile, enumName, mutableSetOf())
                        ?: continue
                    val partnerKind = when (partner.stmt) {
                        is ClassDeclaration, is FunctionDeclaration,
                        is InterfaceDeclaration, is VariableStatement -> true
                        else -> false // enum partner merges fine; anything else: skip
                    }
                    if (!partnerKind) continue

                    val (enumLine, enumChar) = getLineAndCharacterOfPosition(augSource, enumDecl.name.pos)
                    val (pLine, pChar) = getLineAndCharacterOfPosition(partner.source, partner.nameNode.pos)

                    // TS2567 on the enum name, related info -> partner declaration.
                    diagnostics.add(Diagnostic(
                        message = "Enum declarations can only merge with namespace or other enum declarations.",
                        category = DiagnosticCategory.Error,
                        code = 2567,
                        fileName = augFile,
                        line = enumLine,
                        character = enumChar,
                        start = enumDecl.name.pos,
                        length = enumName.length,
                        relatedInformation = listOf(Diagnostic(
                            message = "'$enumName' was also declared here.",
                            category = DiagnosticCategory.Message,
                            code = 6203,
                            fileName = partner.fileName,
                            line = pLine,
                            character = pChar,
                            start = partner.nameNode.pos,
                            length = enumName.length,
                        )),
                    ))
                    // TS2567 on the partner declaration name, related info -> enum.
                    diagnostics.add(Diagnostic(
                        message = "Enum declarations can only merge with namespace or other enum declarations.",
                        category = DiagnosticCategory.Error,
                        code = 2567,
                        fileName = partner.fileName,
                        line = pLine,
                        character = pChar,
                        start = partner.nameNode.pos,
                        length = enumName.length,
                        relatedInformation = listOf(Diagnostic(
                            message = "'$enumName' was also declared here.",
                            category = DiagnosticCategory.Message,
                            code = 6203,
                            fileName = augFile,
                            line = enumLine,
                            character = enumChar,
                            start = enumDecl.name.pos,
                            length = enumName.length,
                        )),
                    ))
                }
            }
        }
    }

    /**
     * B443: cross-file `declare global { namespace NS { … } }` member conflict (TS2300).
     * When two DIFFERENT files each declare a member of the same name inside the SAME
     * global-augmentation namespace path, and the declaration kinds do NOT merge (a
     * type-alias never merges with anything), emit "Duplicate identifier 'X'." at each
     * declaration's name + a cross-referencing TS6203 "'X' was also declared here.".
     * (The cross-file `declare global` namespace merge is not modeled by the binder's
     * symbol tables, so this is AST-based — like the other dedicated cross-file walkers.)
     * FP-safe: requires a type-alias declaration in the mix (type-aliases are the only
     * kind that can never merge); plain interface/namespace/class merges never fire.
     */
    private data class GlobalNsMemberDecl(val isTypeAlias: Boolean, val id: Identifier, val fileName: String, val source: String)

    private fun checkGlobalNamespaceMemberConflicts() {
        // (nsName -> memberName -> declarations across all files)
        val byNs = HashMap<String, HashMap<String, MutableList<GlobalNsMemberDecl>>>()
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if ((stmt.name as? Identifier)?.text != "global") continue
                if (ModifierFlag.Declare !in stmt.modifiers) continue
                val gBody = stmt.body as? ModuleBlock ?: continue
                for (nsStmt in gBody.statements) {
                    if (nsStmt !is ModuleDeclaration) continue
                    val nsName = (nsStmt.name as? Identifier)?.text ?: continue
                    val nsBody = nsStmt.body as? ModuleBlock ?: continue
                    val memberMap = byNs.getOrPut(nsName) { HashMap() }
                    for (member in nsBody.statements) {
                        val (memberName, isTypeAlias) = when (member) {
                            is TypeAliasDeclaration -> member.name.text to true
                            is ImportEqualsDeclaration -> member.name.text to false
                            is InterfaceDeclaration -> member.name.text to false
                            is ClassDeclaration -> (member.name?.text ?: continue) to false
                            is FunctionDeclaration -> (member.name?.text ?: continue) to false
                            is EnumDeclaration -> member.name.text to false
                            is ModuleDeclaration -> ((member.name as? Identifier)?.text ?: continue) to false
                            is VariableStatement -> {
                                for (d in member.declarationList.declarations) {
                                    val idn = d.name as? Identifier ?: continue
                                    memberMap.getOrPut(idn.text) { mutableListOf() }
                                        .add(GlobalNsMemberDecl(false, idn, fileName, source))
                                }
                                continue
                            }
                            else -> continue
                        }
                        val idNode = when (member) {
                            is TypeAliasDeclaration -> member.name
                            is ImportEqualsDeclaration -> member.name
                            is InterfaceDeclaration -> member.name
                            is ClassDeclaration -> member.name
                            is FunctionDeclaration -> member.name
                            is EnumDeclaration -> member.name
                            is ModuleDeclaration -> member.name as? Identifier
                        } ?: continue
                        memberMap.getOrPut(memberName) { mutableListOf() }
                            .add(GlobalNsMemberDecl(isTypeAlias, idNode, fileName, source))
                    }
                }
            }
        }
        for ((_, memberMap) in byNs) {
            for ((_, decls) in memberMap) {
                // Require declarations from ≥2 DIFFERENT files and at least one type-alias
                // (the only kind that can never merge — guarantees a genuine TS2300).
                val distinctFiles = decls.map { it.fileName }.distinct()
                if (distinctFiles.size < 2) continue
                if (decls.none { it.isTypeAlias }) continue
                for (d in decls) {
                    val other = decls.firstOrNull { it !== d } ?: continue
                    val (line, character) = getLineAndCharacterOfPosition(d.source, d.id.pos)
                    val (oLine, oChar) = getLineAndCharacterOfPosition(other.source, other.id.pos)
                    val related = listOf(Diagnostic(
                        message = "'${d.id.text}' was also declared here.", category = DiagnosticCategory.Message,
                        code = 6203, fileName = other.fileName, line = oLine, character = oChar,
                        start = other.id.pos, length = other.id.text.length,
                    ))
                    diagnostics.add(Diagnostic(
                        message = "Duplicate identifier '${d.id.text}'.", category = DiagnosticCategory.Error,
                        code = 2300, fileName = d.fileName, line = line, character = character,
                        start = d.id.pos, length = d.id.text.length, relatedInformation = related,
                    ))
                }
            }
        }
    }

    /**
     * B449 (noSymbolForMergeCrash): a top-level `type N = …` in a SCRIPT file, where N
     * ALSO has a top-level `namespace N`/`module N` declaration in a DIFFERENT SCRIPT
     * file, is a cross-file global-scope merge that tsc rejects with TS2649 "Cannot
     * augment module 'N' with value exports because it resolves to a non-module entity."
     * at the type-alias name (the type alias is the "non-module entity" the namespace
     * cannot merge with). The binder's symbol tables don't model this cross-file global
     * merge, so it's AST-based — like the other dedicated cross-file walkers (B443).
     *
     * FP firewall (corpus-EXHAUSTIVE): BOTH files must be SCRIPT files (no imports/
     * exports) — the only other corpus file sharing the `type X`+`namespace X` shape is
     * `reexportNameAliasedAndHoisted`, whose files are MODULE files (top-level `export`),
     * so the type/namespace are module-scoped (no global conflict) and it is excluded.
     * The conflict must be cross-FILE (same-file `type X`+`namespace X` is TS2300, owned
     * by the duplicate-identifier pipeline).
     */
    private fun checkCrossFileTypeAliasNamespaceConflict() {
        // name -> first script-file top-level type-alias name node (+ its file/source)
        val typeAliases = HashMap<String, Triple<Identifier, String, String>>()
        // name -> set of script files declaring a top-level namespace/module of that name
        val namespaces = HashMap<String, MutableSet<String>>()
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is TypeAliasDeclaration ->
                        typeAliases.getOrPut(stmt.name.text) { Triple(stmt.name, fileName, source) }
                    is ModuleDeclaration -> {
                        val nm = (stmt.name as? Identifier)?.text ?: continue
                        namespaces.getOrPut(nm) { mutableSetOf() }.add(fileName)
                    }
                    else -> {}
                }
            }
        }
        for ((name, ta) in typeAliases) {
            val (idNode, taFile, taSource) = ta
            // Require a namespace of the same name in a DIFFERENT script file.
            val nsFiles = namespaces[name] ?: continue
            if (nsFiles.none { it != taFile }) continue
            val (line, character) = getLineAndCharacterOfPosition(taSource, idNode.pos)
            diagnostics.add(Diagnostic(
                message = "Cannot augment module '$name' with value exports because it resolves to a non-module entity.",
                category = DiagnosticCategory.Error, code = 2649,
                fileName = taFile, line = line, character = character,
                start = idNode.pos, length = idNode.text.length,
            ))
        }
    }

    /**
     * B90.1: TS2671 "Cannot augment module 'X' because it resolves to a non-module
     * entity." An ambient module defined with `export = V` where V is a value-only
     * entity (a `var`/`function` with no namespace/class/interface/enum/module
     * meaning) has no namespace meaning, so a `declare module "X" { ... }`
     * augmentation of it is illegal. Mirrors the B88.1 cross-file augmentation
     * walker structure. The augmentation block is distinguished from the
     * definition block by the ABSENCE of the `export =` inside it.
     */
    private fun checkModuleAugmentationOfNonModuleEntity() {
        for (result in checkedResults) {
            val augFile = result.sourceFile.fileName
            val augSource = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                val nameNode = stmt.name as? StringLiteralNode ?: continue
                val specifier = nameNode.text
                val body = stmt.body as? ModuleBlock ?: continue
                // Skip the DEFINITION block (carries `export = X`) — only augmentations error.
                if (body.statements.any { it is ExportAssignment && it.isExportEquals }) continue
                // An augmentation with no declarations to merge isn't worth flagging.
                if (body.statements.isEmpty()) continue
                // TS2649: a VALUE-export augmentation (`export function`/`var`/`class`/`enum`)
                // of a BARE-resolvable package whose top-level `export = V` target is a value
                // (plus only EMPTY namespaces) — a non-module entity. The TS2671 path below only
                // reaches ambient-block / relative definitions; a bare package FILE
                // (`/node_modules/lib/index.d.ts` with top-level `export = lib`) is not covered
                // there, so this branch is purely additive and disjoint.
                if (augmentationHasValueExport(body) &&
                    !specifier.startsWith("./") && !specifier.startsWith("../")) {
                    val pkgFile = resolveBareSpecifierViaNodeModules(specifier, augFile)
                    val pkgResult = pkgFile?.let { fileResults[it] }
                    if (pkgResult != null && isValuePlusEmptyNamespaceExportTarget(pkgResult.sourceFile)) {
                        val (l, c) = getLineAndCharacterOfPosition(augSource, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Cannot augment module '$specifier' with value exports because it resolves to a non-module entity.",
                            category = DiagnosticCategory.Error,
                            code = 2649,
                            fileName = augFile,
                            line = l,
                            character = c,
                            start = nameNode.pos,
                            length = (nameNode.rawText?.length ?: nameNode.text.length) + 2,
                        ))
                        continue
                    }
                }
                if (!ambientModuleExportEqualsIsValueOnly(specifier, augFile)) continue
                val (line, character) = getLineAndCharacterOfPosition(augSource, nameNode.pos)
                diagnostics.add(Diagnostic(
                    message = "Cannot augment module '$specifier' because it resolves to a non-module entity.",
                    category = DiagnosticCategory.Error,
                    code = 2671,
                    fileName = augFile,
                    line = line,
                    character = character,
                    start = nameNode.pos,
                    length = (nameNode.rawText?.length ?: nameNode.text.length) + 2,
                ))
            }
        }
    }

    /**
     * B98.r114 (TS2649): true when a `declare module "X" { ... }` augmentation BODY
     * adds at least one VALUE export (`export function`/`export var`/`export class`/
     * `export enum`). Type-only exports (`export interface`/`export type`) do NOT count.
     */
    private fun augmentationHasValueExport(body: ModuleBlock): Boolean = body.statements.any { s ->
        when (s) {
            is FunctionDeclaration -> ModifierFlag.Export in s.modifiers
            is VariableStatement -> ModifierFlag.Export in s.modifiers
            is ClassDeclaration -> ModifierFlag.Export in s.modifiers
            is EnumDeclaration -> ModifierFlag.Export in s.modifiers
            else -> false
        }
    }

    /**
     * B98.r114 (TS2649): true when [file] has a top-level `export = V` whose target V
     * is declared ONLY as a value (`var`/`function`) plus, at most, EMPTY namespaces
     * (`declare namespace V {}`) — a non-module entity. A namespace with any members,
     * or any class/interface/type-alias/enum named V, disqualifies (it carries
     * namespace/type meaning, so `export = V` is module-like). Distinct from
     * [isNameValueOnlyInFile] which rejects ANY namespace; here an empty namespace is
     * tolerated (it's uninstantiated and exports nothing).
     */
    private fun isValuePlusEmptyNamespaceExportTarget(file: SourceFile): Boolean {
        val exportEq = file.statements.filterIsInstance<ExportAssignment>().firstOrNull { it.isExportEquals } ?: return false
        val name = (exportEq.expression as? Identifier)?.text ?: return false
        var hasValue = false
        var hasDisqualifying = false
        for (stmt in file.statements) {
            when (stmt) {
                is VariableStatement ->
                    if (stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) hasValue = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValue = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasDisqualifying = true
                is InterfaceDeclaration -> if (stmt.name.text == name) hasDisqualifying = true
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasDisqualifying = true
                is EnumDeclaration -> if (stmt.name.text == name) hasDisqualifying = true
                is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == name) {
                    val b = stmt.body as? ModuleBlock
                    if (b == null || b.statements.isNotEmpty()) hasDisqualifying = true
                }
                else -> {}
            }
        }
        return hasValue && !hasDisqualifying
    }

    /**
     * B90.1: Returns true when ambient module [specifier] is DEFINED with
     * `export = V` where V is a value-only entity (declared as `var`/`function`
     * only, with no namespace/class/interface/enum/module meaning) in the same
     * module block — making it a non-module entity (no namespace meaning).
     * Used for TS2671 (illegal augmentation) and TS2503 (`x.A` namespace use).
     */
    private fun ambientModuleExportEqualsIsValueOnly(specifier: String, contextFile: String? = null): Boolean {
        // B98.r55: relative specifier — the DEFINITION is a separate file (not an
        // ambient `declare module` block) with a top-level `export = name` whose
        // target is declared ONLY as `var`/`function` at file level. Resolve the
        // specifier relative to the augmentation/import file and check that file.
        if (contextFile != null && (specifier.startsWith("./") || specifier.startsWith("../"))) {
            val targetFile = resolveModuleSpecifierRelative(specifier, contextFile)
            val targetResult = targetFile?.let { fileResults[it] }
            if (targetResult != null) {
                for (s in targetResult.sourceFile.statements) {
                    if (s is ExportAssignment && s.isExportEquals) {
                        val expr = s.expression as? Identifier ?: continue
                        if (isNameValueOnlyInFile(expr.text, targetResult.sourceFile)) return true
                    }
                }
            }
            return false
        }
        for (result in binderResults) {
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if ((stmt.name as? StringLiteralNode)?.text != specifier) continue
                val body = stmt.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s is ExportAssignment && s.isExportEquals) {
                        val expr = s.expression as? Identifier ?: continue
                        if (isNameValueOnlyInBlock(expr.text, body)) return true
                    }
                }
            }
        }
        return false
    }

    /** File-level analog of [isNameValueOnlyInBlock]: true when [name] is declared
     *  at the top level of [file] ONLY as a value (`var`/`function`) and NOT as any
     *  namespace/type entity. Used for the relative-specifier `export = name` case. */
    private fun isNameValueOnlyInFile(name: String, file: SourceFile): Boolean {
        var hasValue = false
        var hasNsOrType = false
        for (stmt in file.statements) {
            when (stmt) {
                is VariableStatement ->
                    if (stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) hasValue = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValue = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasNsOrType = true
                is InterfaceDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is EnumDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == name) hasNsOrType = true
                else -> {}
            }
        }
        return hasValue && !hasNsOrType
    }

    /**
     * B90.1: True when [name] is declared inside [block] ONLY as a value
     * (`var`/`function`) and NOT as any namespace/type entity (class, interface,
     * type alias, enum, namespace/module). Used to classify an `export = name`
     * target as a pure non-module value.
     */
    private fun isNameValueOnlyInBlock(name: String, block: ModuleBlock): Boolean {
        var hasValue = false
        var hasNsOrType = false
        for (stmt in block.statements) {
            when (stmt) {
                is VariableStatement ->
                    if (stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) hasValue = true
                is FunctionDeclaration -> if (stmt.name?.text == name) hasValue = true
                is ClassDeclaration -> if (stmt.name?.text == name) hasNsOrType = true
                is InterfaceDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is TypeAliasDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is EnumDeclaration -> if (stmt.name.text == name) hasNsOrType = true
                is ModuleDeclaration -> if ((stmt.name as? Identifier)?.text == name) hasNsOrType = true
                else -> {}
            }
        }
        return hasValue && !hasNsOrType
    }

    /**
     * B90.1: Extract the external-module specifier of an `import X = require("spec")`
     * alias symbol, or null if it's not such an import-equals.
     */
    private fun getImportEqualsSpecifier(sym: Symbol): String? {
        for (decl in sym.declarations) {
            if (decl is ImportEqualsDeclaration) {
                val ref = decl.moduleReference
                if (ref is ExternalModuleReference) {
                    return (ref.expression as? StringLiteralNode)?.text
                }
            }
        }
        return null
    }

    /** B140: resolve a `./Y.json` specifier to its raw content from [jsonModuleContents]
     *  (JSON files aren't in [fileResults]). Matches by exact key, stripped-prefix key, or basename. */
    private fun resolveJsonModuleContent(spec: String): String? {
        if (jsonModuleContents.isEmpty()) return null
        val base = spec.removePrefix("./").removePrefix("../")
        jsonModuleContents[spec]?.let { return it }
        jsonModuleContents[base]?.let { return it }
        jsonModuleContents["/$base"]?.let { return it }
        val wantBase = base.substringAfterLast('/')
        for ((fn, c) in jsonModuleContents) {
            if (fn.substringAfterLast('/') == wantBase) return c
        }
        return null
    }

    // -----------------------------------------------------------------------
    // TS2558: Expected N type arguments, but got M (call/new expressions)
    // -----------------------------------------------------------------------

    private fun checkCallTypeArgCount() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCallTypeArgCountInStmts(result.sourceFile.statements, source, fileName, result.locals)
        }
    }

    private fun checkCallTypeArgCountInStmts(
        stmts: List<Statement>, source: String, fileName: String,
        locals: Map<String, Symbol>,
    ) {
        for (stmt in stmts) checkCallTypeArgCountInStmt(stmt, source, fileName, locals)
    }

    private fun checkCallTypeArgCountInStmt(
        stmt: Statement, source: String, fileName: String,
        locals: Map<String, Symbol>,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            }
            is ReturnStatement -> stmt.expression?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            is FunctionDeclaration -> stmt.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is Constructor -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is GetAccessor -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is SetAccessor -> m.body?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
                    is PropertyDeclaration -> m.initializer?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                    else -> {}
                }
            }
            is Block -> checkCallTypeArgCountInStmts(stmt.statements, source, fileName, locals)
            is IfStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.thenStatement, source, fileName, locals)
                stmt.elseStatement?.let { checkCallTypeArgCountInStmt(it, source, fileName, locals) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> init.declarations.forEach { d ->
                        d.initializer?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                    }
                    is Expression -> checkCallTypeArgCountInExpr(init, source, fileName, locals)
                    else -> {}
                }
                stmt.condition?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                stmt.incrementor?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is ForInStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is ForOfStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is WhileStatement -> {
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            }
            is DoStatement -> {
                checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
                checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
            }
            is SwitchStatement -> {
                for (c in stmt.caseBlock) when (c) {
                    is CaseClause -> checkCallTypeArgCountInStmts(c.statements, source, fileName, locals)
                    is DefaultClause -> checkCallTypeArgCountInStmts(c.statements, source, fileName, locals)
                    else -> {}
                }
            }
            is TryStatement -> {
                checkCallTypeArgCountInStmts(stmt.tryBlock.statements, source, fileName, locals)
                stmt.catchClause?.let { checkCallTypeArgCountInStmts(it.block.statements, source, fileName, locals) }
                stmt.finallyBlock?.let { checkCallTypeArgCountInStmts(it.statements, source, fileName, locals) }
            }
            is LabeledStatement -> checkCallTypeArgCountInStmt(stmt.statement, source, fileName, locals)
            is ThrowStatement -> stmt.expression?.let { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            is ExportAssignment -> checkCallTypeArgCountInExpr(stmt.expression, source, fileName, locals)
            else -> {}
        }
    }

    private fun checkCallTypeArgCountInExpr(
        expr: Expression, source: String, fileName: String,
        locals: Map<String, Symbol>,
    ) {
        when (expr) {
            is CallExpression -> {
                checkCallOrNewTypeArgCount(expr.expression, expr.typeArguments, source, fileName, locals)
                tryEmitUncallableTypeArgs(expr, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
                for (arg in expr.arguments) checkCallTypeArgCountInExpr(arg, source, fileName, locals)
            }
            is NewExpression -> {
                checkCallOrNewTypeArgCount(expr.expression, expr.typeArguments, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
                expr.arguments?.forEach { checkCallTypeArgCountInExpr(it, source, fileName, locals) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkCallTypeArgCountInExpr(current.right, source, fileName, locals)
                    current = current.left
                }
                checkCallTypeArgCountInExpr(current, source, fileName, locals)
            }
            is ParenthesizedExpression -> checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
            is ConditionalExpression -> {
                checkCallTypeArgCountInExpr(expr.condition, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.whenTrue, source, fileName, locals)
                checkCallTypeArgCountInExpr(expr.whenFalse, source, fileName, locals)
            }
            is PropertyAccessExpression -> checkCallTypeArgCountInExpr(expr.expression, source, fileName, locals)
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkCallTypeArgCountInStmts(body.statements, source, fileName, locals)
                is Expression -> checkCallTypeArgCountInExpr(body, source, fileName, locals)
                else -> {}
            }
            is FunctionExpression -> checkCallTypeArgCountInStmts(expr.body.statements, source, fileName, locals)
            else -> {}
        }
    }

    /** B144: real-lib construct-signature type-param overload ranges for well-known
     *  collection constructors whose generic `new<...>()` overload our embedded lib
     *  omits. Returns (overload-ranges, expected-lib-interface-arity). A function (not
     *  a field) to avoid the Kotlin init-order trap (this runs during the pipeline). */
    private fun libCtorTypeParamRanges(name: String): Pair<List<IntRange>, Int>? = when (name) {
        // MapConstructor: `new(): Map<any,any>` (0) + `new <K,V>(entries?)` (2, no defaults).
        "Map" -> listOf(0..0, 2..2) to 2
        // WeakMapConstructor: `new()` (0) + `new <K extends object = object, V = any>()` —
        // both K and V default, so the generic overload accepts 0, 1, or 2 type args.
        "WeakMap" -> listOf(0..0, 0..2) to 2
        else -> null
    }

    /**
     * B479: explicit type arguments on a call whose VARIABLE callee cannot accept them
     * (untypedFunctionCallsWithTypeParameters1). Gated to a callee Identifier resolving to a
     * VARIABLE (named generic functions/classes are handled by [checkCallOrNewTypeArgCount]'s
     * symbol-decl loop — this is the FP firewall against legitimate generic calls). The
     * explicit/implicit-`any` var case is owned by the existing isImplicitAnyVarChain TS2347.
     * Three disjoint outcomes from the callee's resolved type:
     *   - Function-derived (`Function` / a class `extends Function`) → TS2347 (untyped call).
     *   - concrete class/interface with NO call signature → TS2349 (not callable) + sub-line.
     *   - callable with the AST-derived sig type-param count < provided → TS2558 (Expected N).
     * The expected type-param count is derived from the AST (init fn type-params / annotation
     * FunctionType or interface call-sig type-params), NOT the resolved signature — so a
     * generic fn-typed var whose sig type-params we might drop is never FP'd.
     */
    private fun tryEmitUncallableTypeArgs(
        call: CallExpression, source: String, fileName: String, locals: Map<String, Symbol>,
    ) {
        val typeArgs = call.typeArguments
        if (typeArgs.isNullOrEmpty()) return
        val callee = call.expression as? Identifier ?: return
        val sym = locals[callee.text] ?: globals[callee.text] ?: return
        val resolved = if (sym.flags.hasAny(SymbolFlags.Alias))
            resolveAlias(sym) else sym
        if (!resolved.flags.hasAny(SymbolFlags.Variable)) return
        val varDecl = resolved.valueDeclaration as? VariableDeclaration ?: return
        // The any-var case (explicit `: any` or implicit) is owned by the isImplicitAnyVarChain
        // TS2347 emitter in checkSingleCallExpressionTypes — don't double-handle it here.
        if (varDecl.type == null && varDecl.initializer == null) return
        (varDecl.type as? KeywordTypeNode)?.let { if (it.kind == SyntaxKind.AnyKeyword) return }
        val calleeType = getCalleeType(callee)
        if (calleeType === anyType || calleeType === errorType) return
        val provided = typeArgs.size
        if (isFunctionDerivedType(calleeType)) {
            val start = call.pos
            val length = expressionTrueEnd(call) - start
            if (length <= 0) return
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Untyped function calls may not accept type arguments.",
                category = DiagnosticCategory.Error, code = 2347,
                fileName = fileName, line = line, character = character, start = start, length = length,
            ))
            return
        }
        val sigs = getCallSignaturesOfType(calleeType)
        if (sigs.isEmpty()) {
            // Only for a concrete named class/interface instance — avoid FP on partial resolutions.
            if (calleeType !is Type.Interface) return
            val start = callee.pos
            val length = (expressionTrueEnd(callee) - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "This expression is not callable.",
                category = DiagnosticCategory.Error, code = 2349,
                fileName = fileName, line = line, character = character, start = start, length = length,
                messageChain = listOf("  Type '${typeToString(calleeType)}' has no call signatures."),
            ))
            return
        }
        // Callable: derive the expected type-param count from the AST. Only the NON-generic
        // case (expectedTp == 0) is handled here — a GENERIC fn-typed var (e.g.
        // `var x = <T>() => {}`) is already covered by checkCallOrNewTypeArgCount's
        // VariableDeclaration init.typeParameters path, so firing here would double-emit
        // (tooManyTypeParameters1).
        val expectedTp = varCalleeTypeParamCount(varDecl) ?: return
        if (expectedTp == 0 && provided > 0) {
            val firstArg = typeArgs.first()
            val lastArg = typeArgs.last()
            val start = firstArg.pos
            var endPos = lastArg.end
            while (endPos > start && endPos < source.length) {
                val ch = source[endPos - 1]
                if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') endPos--
                else break
            }
            val length = (endPos - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "Expected $expectedTp type arguments, but got $provided.",
                category = DiagnosticCategory.Error, code = 2558,
                fileName = fileName, line = line, character = character, start = start, length = length,
            ))
        }
    }

    /** B479: is [type] the lib `Function` interface or a class that (transitively) extends it? */
    private fun isFunctionDerivedType(type: Type): Boolean {
        val seen = mutableSetOf<Int>()
        fun rec(t: Type): Boolean {
            if (t !is Type.Object || !seen.add(t.id)) return false
            if (t.symbol?.name == "Function") return true
            if (t is Type.Interface) {
                resolveBaseTypesLazy(t)
                t.baseTypes?.let { for (b in it) if (rec(b)) return true }
            }
            return false
        }
        return rec(type)
    }

    /**
     * B479: the AST-derived call-signature type-parameter count for a fn-typed/interface-typed
     * VARIABLE callee — `null` when it can't be determined safely (so no TS2558 is emitted).
     * Reads the var's initializer (arrow/fn-expr type params), or its annotation (FunctionType
     * type params, or the single call-signature of an interface/object-type literal). An
     * interface type parameter (`callable2<T>`) is NOT the call signature's — the call sig
     * `(a: T): T` has 0 type params, which is what tsc counts.
     */
    private fun varCalleeTypeParamCount(varDecl: VariableDeclaration): Int? {
        when (val init = varDecl.initializer) {
            is ArrowFunction -> if (varDecl.type == null) return init.typeParameters?.size ?: 0
            is FunctionExpression -> if (varDecl.type == null) return init.typeParameters?.size ?: 0
            else -> {}
        }
        return when (val ann = varDecl.type) {
            is FunctionType -> ann.typeParameters?.size ?: 0
            is TypeLiteral -> callSigTypeParamCount(ann.members)
            is TypeReference -> {
                val n = (ann.typeName as? Identifier)?.text ?: return null
                val target = currentFileLocals?.get(n) ?: globals[n] ?: return null
                val idecl = target.declarations.firstOrNull { it is InterfaceDeclaration } as? InterfaceDeclaration
                    ?: return null
                callSigTypeParamCount(idecl.members)
            }
            else -> null
        }
    }

    /** The type-param count of the single bare call signature among interface/type-literal
     *  members (a MethodDeclaration with empty name), or null when there isn't exactly one. */
    private fun callSigTypeParamCount(members: List<Node>): Int? {
        val callSigs = members.filterIsInstance<MethodDeclaration>()
            .filter { (it.name as? Identifier)?.text == "" }
        if (callSigs.size != 1) return null
        return callSigs[0].typeParameters?.size ?: 0
    }

    private fun checkCallOrNewTypeArgCount(
        callee: Expression,
        typeArguments: List<TypeNode>?,
        source: String,
        fileName: String,
        locals: Map<String, Symbol>,
    ) {
        // Only check if type arguments are provided and non-empty
        if (typeArguments == null || typeArguments.isEmpty()) return

        // 17.188: PropertyAccessExpression with ArrayLiteralExpression receiver
        // for known fixed-arity Array methods (e.g. `[1,2,3].map<any,any>(...)`
        // where Array.map takes exactly 1 type arg). Conservative gate: only
        // fires for hardcoded method names with array-literal receivers.
        if (callee is PropertyAccessExpression && callee.expression is ArrayLiteralExpression) {
            val methodName = callee.name.text
            val expectedTypeParams = when (methodName) {
                "map", "flatMap" -> 1
                else -> -1
            }
            if (expectedTypeParams > 0 && typeArguments.size != expectedTypeParams) {
                val firstArg = typeArguments.first()
                val lastArg = typeArguments.last()
                val start = firstArg.pos
                var endPos = lastArg.end
                while (endPos > start && endPos < source.length) {
                    val ch = source[endPos - 1]
                    if (ch == '>' || ch == ')' || ch.isWhitespace()) endPos--
                    else break
                }
                val length = (endPos - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Expected $expectedTypeParams type arguments, but got ${typeArguments.size}.",
                    category = DiagnosticCategory.Error,
                    code = 2558,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                return
            }
        }

        // B60.17: PropertyAccess on well-known lib globals — narrow gate to avoid
        // FPs from incomplete sig resolution for user types. Targets `Object.create<X>`,
        // `Array.from<X>`, etc. where the static side's method has a known type-param
        // count and the call passes a different count.
        if (callee is PropertyAccessExpression) {
            val recv = callee.expression
            if (recv is Identifier && recv.text in BUILTIN_LIB_GLOBAL_VALUE_NAMES) {
                val calleeType = getTypeOfPropertyAccess(callee)
                if (calleeType === anyType || calleeType === errorType) return
                val sigs = getCallSignaturesOfType(calleeType)
                if (sigs.isEmpty()) return
                val tpCounts = sigs.map { it.typeParameters?.size ?: 0 }.distinct()
                if (tpCounts.size != 1) return
                val expectedCount = tpCounts[0]
                val providedCount = typeArguments.size
                if (providedCount == expectedCount) return
                val firstArg = typeArguments.first()
                val lastArg = typeArguments.last()
                val start = firstArg.pos
                var endPos = lastArg.end
                while (endPos > start && endPos < source.length) {
                    val ch = source[endPos - 1]
                    if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') endPos--
                    else break
                }
                val length = (endPos - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Expected $expectedCount type arguments, but got $providedCount.",
                    category = DiagnosticCategory.Error, code = 2558,
                    fileName = fileName, line = line, character = character,
                    start = start, length = length,
                ))
                return
            }
        }
        // Resolve the callee to a symbol
        val name = when (callee) {
            is Identifier -> callee.text
            else -> return // PropertyAccessExpression, etc. — skip for now
        }
        if (name.isEmpty()) return

        // Look up the symbol
        val symbol = locals[name] ?: globals[name] ?: return

        // Follow import alias
        val resolved = if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            resolveAlias(symbol)
        } else symbol

        // Get type parameters from the function/class declarations. For overloaded
        // functions, collect per-overload (min, max) ranges and compute the union
        // of acceptable type-arg counts. Implementation declarations (bodied
        // FunctionDeclaration when there are also body-less overload signatures)
        // are skipped — TypeScript's TS2558/TS2743 only consider the declared
        // overload signatures, not the impl signature.
        val perOverloadRanges = mutableListOf<IntRange>()
        var lastNonFnMaxParams = -1
        var lastNonFnMinParams = -1
        val fnDecls = resolved.declarations.filterIsInstance<FunctionDeclaration>()
        val hasOverloadSigs = fnDecls.count { it.body == null } >= 1 && fnDecls.size >= 2
        var anyFnDecl = false
        for (decl in resolved.declarations) {
            when (decl) {
                is FunctionDeclaration -> {
                    // When overload signatures exist, skip the impl (bodied) decl
                    if (hasOverloadSigs && decl.body != null) continue
                    val tps = decl.typeParameters
                    val paramCount = tps?.size ?: 0
                    val minRequired = tps?.count { it.default == null } ?: 0
                    perOverloadRanges.add(minRequired..paramCount)
                    anyFnDecl = true
                }
                is ClassDeclaration -> {
                    val tps = decl.typeParameters ?: continue
                    val paramCount = tps.size
                    val minRequired = tps.count { it.default == null }
                    if (lastNonFnMaxParams < 0 || paramCount > lastNonFnMaxParams) lastNonFnMaxParams = paramCount
                    if (lastNonFnMinParams < 0 || minRequired < lastNonFnMinParams) lastNonFnMinParams = minRequired
                }
                is InterfaceDeclaration -> {
                    val tps = decl.typeParameters ?: continue
                    val paramCount = tps.size
                    val minRequired = tps.count { it.default == null }
                    if (lastNonFnMaxParams < 0 || paramCount > lastNonFnMaxParams) lastNonFnMaxParams = paramCount
                    if (lastNonFnMinParams < 0 || minRequired < lastNonFnMinParams) lastNonFnMinParams = minRequired
                }
                is VariableDeclaration -> {
                    val tps = when (val init = decl.initializer) {
                        is ArrowFunction -> init.typeParameters
                        is FunctionExpression -> init.typeParameters
                        else -> null
                    } ?: continue
                    val paramCount = tps.size
                    val minRequired = tps.count { it.default == null }
                    if (lastNonFnMaxParams < 0 || paramCount > lastNonFnMaxParams) lastNonFnMaxParams = paramCount
                    if (lastNonFnMinParams < 0 || minRequired < lastNonFnMinParams) lastNonFnMinParams = minRequired
                }
                else -> {}
            }
        }

        // Always also include the non-function decls (classes/interfaces are NOT
        // overloaded — they merge into a single declared shape).
        if (lastNonFnMaxParams >= 0) {
            perOverloadRanges.add(lastNonFnMinParams..lastNonFnMaxParams)
        }
        // B144: well-known lib CONSTRUCTORS (Map/WeakMap) have an implicit
        // 0-type-arg `new()` overload IN ADDITION to a generic `new<K,V>()` — but our
        // embedded lib's MapConstructor/WeakMapConstructor omit the generic ctor
        // overload, so the symbol-derived range only sees the INTERFACE's arity (2)
        // and we emit TS2558 "Expected 2, got 1" where TypeScript emits the
        // overload-aware TS2743 (Map: "either 0 or 2") or NO error (WeakMap: its
        // generic ctor's K/V have defaults so 1 type arg is accepted). Override with
        // the real construct-overload type-param ranges. FP-safe: gated to the exact
        // lib names with NO local shadow, NO user class redefinition, and a matching
        // lib-interface arity — and only ever changes the 1-type-arg (and >max) case
        // (`new Map()`/`new Map<a,b>()` short-circuit before/at the `any{in}` check).
        libCtorTypeParamRanges(name)?.let { (ranges, ifaceArity) ->
            if (name !in locals && lastNonFnMaxParams == ifaceArity &&
                resolved.declarations.none { it is ClassDeclaration }) {
                perOverloadRanges.clear()
                perOverloadRanges.addAll(ranges)
                anyFnDecl = true
            }
        }
        if (perOverloadRanges.isEmpty()) return
        // If only FunctionDeclarations were found AND none have typeParameters,
        // skip emission unless overloads (then we report TS2558 "Expected 0").
        if (!anyFnDecl && lastNonFnMaxParams < 0) return

        val providedCount = typeArguments.size
        // Acceptable counts = union of all overload ranges
        if (perOverloadRanges.any { providedCount in it }) return

        // Compute squiggle span — covers the type argument text only (no < >)
        val firstArg = typeArguments.first()
        val lastArg = typeArguments.last()
        val start = firstArg.pos
        var endPos = lastArg.end
        while (endPos > start && endPos < source.length) {
            val ch = source[endPos - 1]
            if (ch == '>' || ch == ')' || ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t') {
                endPos--
            } else break
        }
        val length = endPos - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        // Decide TS2743 (overload-aware) vs TS2558 (out-of-range or single-overload).
        // TS2743 fires when providedCount sits BETWEEN overload mins/maxes (i.e. some
        // overload accepts fewer and some accepts more) but no overload's exact range
        // covers it.
        val overallMin = perOverloadRanges.minOf { it.first }
        val overallMax = perOverloadRanges.maxOf { it.last }
        if (perOverloadRanges.size >= 2 && providedCount in (overallMin + 1) until overallMax) {
            // TS2743 — list the "bracketing" boundary counts: for each overload
            // entirely BELOW providedCount, take its max; for each overload
            // entirely ABOVE providedCount, take its min. Matches TypeScript's
            // wording "either N or M" / "N, M, or P".
            val brackets = mutableSetOf<Int>()
            for (r in perOverloadRanges) {
                if (r.last < providedCount) brackets.add(r.last)
                else if (r.first > providedCount) brackets.add(r.first)
            }
            val list = brackets.sorted()
            val countListText = when (list.size) {
                1 -> "${list[0]}"
                2 -> "either ${list[0]} or ${list[1]}"
                else -> list.dropLast(1).joinToString(", ") + ", or ${list.last()}"
            }
            diagnostics.add(Diagnostic(
                message = "No overload expects $providedCount type arguments, but overloads do exist that expect $countListText type arguments.",
                category = DiagnosticCategory.Error, code = 2743,
                fileName = fileName, line = line, character = character,
                start = start, length = length,
            ))
            return
        }

        // TS2558 — "Expected X type arguments, but got Y." X is the boundary overload's range:
        // - if providedCount > overallMax → X = overallMax
        // - if providedCount < overallMin → X = overallMin
        // - single overload with default-typed params: X = "min-max"
        val expectedText = if (providedCount > overallMax) {
            overallMax.toString()
        } else if (providedCount < overallMin) {
            overallMin.toString()
        } else {
            // Edge: providedCount IS in some overload range but our check missed?
            // Fallback: pick the closest range.
            val targetRange = perOverloadRanges.minByOrNull {
                if (providedCount > it.last) providedCount - it.last
                else it.first - providedCount
            } ?: perOverloadRanges.first()
            if (targetRange.first == targetRange.last) "${targetRange.first}"
            else "${targetRange.first}-${targetRange.last}"
        }
        // When there's only ONE overload range and it spans (min..max with min<max), prefer "min-max".
        val finalExpected = if (perOverloadRanges.size == 1) {
            val r = perOverloadRanges[0]
            if (r.first == r.last) "${r.first}"
            else "${r.first}-${r.last}"
        } else expectedText

        diagnostics.add(Diagnostic(
            message = "Expected $finalExpected type arguments, but got $providedCount.",
            category = DiagnosticCategory.Error,
            code = 2558,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // TS2440: Import declaration conflicts with local declaration
    // -----------------------------------------------------------------------

    /**
     * Returns true if [name] is exported from [moduleSpecifier] only via a type-only declaration
     * (`export type X = ...`, `export interface X {}`). Walks the target file's top-level
     * statements and inspects each export form.
     */
    /** B289: accessor-PAIR member visibility (TS2341/TS2445) — tsc's divergent-
     *  accessor rule: an assignment TARGET access (incl. compound and `++`/`--`) is
     *  governed by the SETTER's modifier, a read by the GETTER's; one error per
     *  access at the property NAME. Covers `this.X` (enclosing-class context) and
     *  identifier receivers with a direct class-type annotation / `new C()` init.
     *  Scoped to accessor PAIRS only (both get and set declared) — single accessors
     *  and data members keep their existing paths. */
    private fun checkDivergentAccessorVisibility() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // class name -> (extends base name, member -> (getVis, setVis)); vis 0=public 1=protected 2=private
            val classes = HashMap<String, Pair<String?, HashMap<String, Pair<Int?, Int?>>>>()
            fun vis(mods: Set<ModifierFlag>): Int = when {
                ModifierFlag.Private in mods -> 2
                ModifierFlag.Protected in mods -> 1
                else -> 0
            }
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ClassDeclaration) continue
                val cname = stmt.name?.text ?: continue
                val baseName = stmt.heritageClauses
                    ?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                    ?.types?.firstOrNull()?.expression?.let { (it as? Identifier)?.text }
                val members = HashMap<String, Pair<Int?, Int?>>()
                for (m in stmt.members) {
                    when (m) {
                        is GetAccessor -> if (ModifierFlag.Static !in m.modifiers) {
                            val n = (m.name as? Identifier)?.text ?: continue
                            members[n] = vis(m.modifiers) to members[n]?.second
                        }
                        is SetAccessor -> if (ModifierFlag.Static !in m.modifiers) {
                            val n = (m.name as? Identifier)?.text ?: continue
                            members[n] = members[n]?.first to vis(m.modifiers)
                        }
                        else -> {}
                    }
                }
                classes[cname] = baseName to members
            }
            if (classes.values.none { (_, ms) -> ms.values.any { it.first != null && it.second != null } }) continue

            fun lookup(cls: String?, prop: String): Triple<Int, Int, String>? {
                var c = cls; var depth = 0
                while (c != null && depth++ < 16) {
                    val (base, members) = classes[c] ?: return null
                    val v = members[prop]
                    if (v != null) {
                        val (g, s) = v
                        return if (g != null && s != null) Triple(g, s, c) else null
                    }
                    c = base
                }
                return null
            }
            fun isSubclassOf(cls: String, anc: String): Boolean {
                var c: String? = cls; var depth = 0
                while (c != null && depth++ < 16) {
                    if (c == anc) return true
                    c = classes[c]?.first
                }
                return false
            }
            val varClass = HashMap<String, String>()
            fun emit(nameNode: Identifier, v: Int, declaring: String) {
                val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                val msg = if (v == 2)
                    "Property '${nameNode.text}' is private and only accessible within class '$declaring'."
                else
                    "Property '${nameNode.text}' is protected and only accessible within class '$declaring' and its subclasses."
                diagnostics.add(Diagnostic(
                    message = msg, category = DiagnosticCategory.Error,
                    code = if (v == 2) 2341 else 2445,
                    fileName = fileName, line = line, character = character,
                    start = nameNode.pos, length = nameNode.text.length,
                ))
            }
            fun checkAccess(expr: PropertyAccessExpression, write: Boolean, enclosing: String?) {
                val recv = expr.expression
                val cls = when {
                    recv is Identifier && recv.text == "this" -> enclosing
                    recv is Identifier -> varClass[recv.text]
                    else -> null
                } ?: return
                val name = expr.name
                val (g, s, declaring) = lookup(cls, name.text) ?: return
                // Uniform-PRIVATE pairs are owned by the pre-existing TS2341 paths —
                // emitting here would duplicate. Uniform-protected and all divergent
                // combinations have no other emitter.
                if (g == 2 && s == 2) return
                val v = if (write) s else g
                if (v == 0) return
                val accessible = when (v) {
                    2 -> enclosing == declaring
                    else -> enclosing != null && isSubclassOf(enclosing, declaring)
                }
                if (!accessible) emit(name, v, declaring)
            }
            var walkStmts: (List<Statement>, String?) -> Unit = { _, _ -> }
            fun walkExpr(e: Expression?, enclosing: String?, write: Boolean = false) {
                when (e) {
                    null -> {}
                    is PropertyAccessExpression -> {
                        checkAccess(e, write, enclosing)
                        walkExpr(e.expression, enclosing)
                    }
                    is BinaryExpression -> {
                        val op = e.operator
                        val isAssign = isAssignmentOperator(op) ||
                            op == SyntaxKind.AsteriskAsteriskEquals ||
                            op == SyntaxKind.LessThanLessThanEquals ||
                            op == SyntaxKind.GreaterThanGreaterThanEquals ||
                            op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals
                        walkExpr(e.left, enclosing, write = isAssign)
                        walkExpr(e.right, enclosing)
                    }
                    is PrefixUnaryExpression ->
                        walkExpr(e.operand, enclosing,
                            write = e.operator == SyntaxKind.PlusPlus || e.operator == SyntaxKind.MinusMinus)
                    is PostfixUnaryExpression -> walkExpr(e.operand, enclosing, write = true)
                    is ParenthesizedExpression -> walkExpr(e.expression, enclosing, write)
                    is VoidExpression -> walkExpr(e.expression, enclosing)
                    is CallExpression -> { walkExpr(e.expression, enclosing); e.arguments.forEach { walkExpr(it, enclosing) } }
                    is NewExpression -> { walkExpr(e.expression, enclosing); e.arguments?.forEach { walkExpr(it, enclosing) } }
                    is ElementAccessExpression -> { walkExpr(e.expression, enclosing); walkExpr(e.argumentExpression, enclosing) }
                    is ConditionalExpression -> { walkExpr(e.condition, enclosing); walkExpr(e.whenTrue, enclosing); walkExpr(e.whenFalse, enclosing) }
                    is AwaitExpression -> walkExpr(e.expression, enclosing)
                    is AsExpression -> walkExpr(e.expression, enclosing)
                    is NonNullExpression -> walkExpr(e.expression, enclosing)
                    is ArrayLiteralExpression -> e.elements.forEach { walkExpr(it, enclosing) }
                    is ObjectLiteralExpression -> e.properties.forEach { p ->
                        when (p) {
                            is PropertyAssignment -> walkExpr(p.initializer, enclosing)
                            is SpreadAssignment -> walkExpr(p.expression, enclosing)
                            else -> {}
                        }
                    }
                    is ArrowFunction -> when (val b = e.body) {
                        is Block -> walkStmts(b.statements, enclosing)
                        is Expression -> walkExpr(b, enclosing)
                        else -> {}
                    }
                    is FunctionExpression -> walkStmts(e.body.statements, enclosing)
                    else -> {}
                }
            }
            fun walkStmt(s: Statement, enclosing: String?) {
                when (s) {
                    is ExpressionStatement -> walkExpr(s.expression, enclosing)
                    is VariableStatement -> for (d in s.declarationList.declarations) {
                        val vn = (d.name as? Identifier)?.text
                        if (vn != null) {
                            val annName = ((d.type as? TypeReference)?.typeName as? Identifier)?.text
                            val initName = ((d.initializer as? NewExpression)?.expression as? Identifier)?.text
                            val cn = annName ?: initName
                            if (cn != null && cn in classes) varClass[vn] = cn
                        }
                        walkExpr(d.initializer, enclosing)
                    }
                    is ReturnStatement -> walkExpr(s.expression, enclosing)
                    is IfStatement -> { walkExpr(s.expression, enclosing); walkStmt(s.thenStatement, enclosing); s.elseStatement?.let { walkStmt(it, enclosing) } }
                    is Block -> walkStmts(s.statements, enclosing)
                    is WhileStatement -> { walkExpr(s.expression, enclosing); walkStmt(s.statement, enclosing) }
                    is DoStatement -> { walkStmt(s.statement, enclosing); walkExpr(s.expression, enclosing) }
                    is ForStatement -> { (s.initializer as? Expression)?.let { walkExpr(it, enclosing) }; s.condition?.let { walkExpr(it, enclosing) }; s.incrementor?.let { walkExpr(it, enclosing) }; walkStmt(s.statement, enclosing) }
                    is ForOfStatement -> { walkExpr(s.expression, enclosing); walkStmt(s.statement, enclosing) }
                    is ForInStatement -> { walkExpr(s.expression, enclosing); walkStmt(s.statement, enclosing) }
                    is ThrowStatement -> walkExpr(s.expression, enclosing)
                    is FunctionDeclaration -> s.body?.let { walkStmts(it.statements, enclosing) }
                    is ClassDeclaration -> {
                        val cn = s.name?.text
                        for (m in s.members) {
                            when (m) {
                                is MethodDeclaration -> m.body?.let { walkStmts(it.statements, cn) }
                                is Constructor -> m.body?.let { walkStmts(it.statements, cn) }
                                is GetAccessor -> m.body?.let { walkStmts(it.statements, cn) }
                                is SetAccessor -> m.body?.let { walkStmts(it.statements, cn) }
                                is PropertyDeclaration -> walkExpr(m.initializer, cn)
                                else -> {}
                            }
                        }
                    }
                    else -> {}
                }
            }
            walkStmts = { list, enc -> list.forEach { walkStmt(it, enc) } }
            result.sourceFile.statements.forEach { walkStmt(it, null) }
        }
    }

    /** B287 TS2866: under isolatedModules, a NON-type-only named import whose target
     *  export is type-only, where the importing file USES a same-named GLOBAL VALUE
     *  (`import { Date } from './types'` + `new Date(...)`) — a single-file transpiler
     *  cannot tell whether to elide the import. Value-use detection is conservative:
     *  `new Name(...)` / `Name(...)` callee positions in the file's raw statements. */
    private fun checkIsolatedModulesGlobalValueShadow() {
        if (!options.isolatedModules) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            var globalValueUses: Set<String>? = null
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ImportDeclaration) continue
                val clause = stmt.importClause ?: continue
                if (clause.isTypeOnly) continue
                val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                val nb = clause.namedBindings as? NamedImports ?: continue
                for (element in nb.elements) {
                    if (element.isTypeOnly) continue
                    val localName = element.name.text
                    val sourceName = (element.propertyName ?: element.name).text
                    if (localName !in KNOWN_GLOBALS) continue
                    if (!isExportedNameTypeOnly(sourceName, spec)) continue
                    if (globalValueUses == null) globalValueUses = collectNewCallCalleeNames(result.sourceFile.statements)
                    if (localName !in globalValueUses) continue
                    val nameNode = element.propertyName ?: element.name
                    val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                    diagnostics.add(Diagnostic(
                        message = "Import '$localName' conflicts with global value used in this file, so must be declared with a type-only import when 'isolatedModules' is enabled.",
                        category = DiagnosticCategory.Error, code = 2866,
                        fileName = fileName, line = line, character = character,
                        start = nameNode.pos, length = nameNode.text.length,
                    ))
                }
            }
        }
    }

    /** Bare-identifier callee names of `new X(...)` / `X(...)` anywhere in [stmts]. */
    private fun collectNewCallCalleeNames(stmts: List<Statement>): Set<String> {
        val out = mutableSetOf<String>()
        // local funs can't forward-reference — route the expr→stmt recursion through a ref
        var walkStmts: (List<Statement>) -> Unit = { }
        fun walkExpr(e: Expression?) {
            when (e) {
                null -> {}
                is NewExpression -> {
                    (e.expression as? Identifier)?.let { out.add(it.text) }
                    walkExpr(e.expression); e.arguments?.forEach { walkExpr(it) }
                }
                is CallExpression -> {
                    (e.expression as? Identifier)?.let { out.add(it.text) }
                    walkExpr(e.expression); e.arguments.forEach { walkExpr(it) }
                }
                is BinaryExpression -> {
                    // iterative right-spine for deep chains
                    var cur: Expression = e
                    while (cur is BinaryExpression) { walkExpr(cur.left); cur = cur.right }
                    walkExpr(cur)
                }
                is ParenthesizedExpression -> walkExpr(e.expression)
                is PropertyAccessExpression -> walkExpr(e.expression)
                is ElementAccessExpression -> { walkExpr(e.expression); walkExpr(e.argumentExpression) }
                is AsExpression -> walkExpr(e.expression)
                is SatisfiesExpression -> walkExpr(e.expression)
                is NonNullExpression -> walkExpr(e.expression)
                is TypeAssertionExpression -> walkExpr(e.expression)
                is PrefixUnaryExpression -> walkExpr(e.operand)
                is PostfixUnaryExpression -> walkExpr(e.operand)
                is ConditionalExpression -> { walkExpr(e.condition); walkExpr(e.whenTrue); walkExpr(e.whenFalse) }
                is ArrayLiteralExpression -> e.elements.forEach { walkExpr(it) }
                is ObjectLiteralExpression -> e.properties.forEach { p ->
                    when (p) {
                        is PropertyAssignment -> walkExpr(p.initializer)
                        is SpreadAssignment -> walkExpr(p.expression)
                        else -> {}
                    }
                }
                is SpreadElement -> walkExpr(e.expression)
                is AwaitExpression -> walkExpr(e.expression)
                is ArrowFunction -> when (val b = e.body) {
                    is Block -> walkStmts(b.statements)
                    is Expression -> walkExpr(b)
                    else -> {}
                }
                is FunctionExpression -> walkStmts(e.body.statements)
                else -> {}
            }
        }
        fun walkStmt(s: Statement) {
            when (s) {
                is ExpressionStatement -> walkExpr(s.expression)
                is VariableStatement -> s.declarationList.declarations.forEach { walkExpr(it.initializer) }
                is ReturnStatement -> walkExpr(s.expression)
                is IfStatement -> { walkExpr(s.expression); walkStmt(s.thenStatement); s.elseStatement?.let { walkStmt(it) } }
                is Block -> walkStmts(s.statements)
                is FunctionDeclaration -> s.body?.let { walkStmts(it.statements) }
                is ClassDeclaration -> s.members.forEach { m ->
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkStmts(it.statements) }
                        is Constructor -> m.body?.let { walkStmts(it.statements) }
                        is PropertyDeclaration -> walkExpr(m.initializer)
                        is GetAccessor -> m.body?.let { walkStmts(it.statements) }
                        is SetAccessor -> m.body?.let { walkStmts(it.statements) }
                        else -> {}
                    }
                }
                is ForStatement -> { (s.initializer as? Expression)?.let { walkExpr(it) }; s.condition?.let { walkExpr(it) }; s.incrementor?.let { walkExpr(it) }; walkStmt(s.statement) }
                is ForOfStatement -> { walkExpr(s.expression); walkStmt(s.statement) }
                is ForInStatement -> { walkExpr(s.expression); walkStmt(s.statement) }
                is WhileStatement -> { walkExpr(s.expression); walkStmt(s.statement) }
                is DoStatement -> { walkStmt(s.statement); walkExpr(s.expression) }
                is ThrowStatement -> walkExpr(s.expression)
                is TryStatement -> { walkStmts(s.tryBlock.statements); s.catchClause?.block?.let { walkStmts(it.statements) }; s.finallyBlock?.let { walkStmts(it.statements) } }
                is SwitchStatement -> { walkExpr(s.expression); s.caseBlock.forEach { c ->
                    when (c) {
                        is CaseClause -> { walkExpr(c.expression); walkStmts(c.statements) }
                        is DefaultClause -> walkStmts(c.statements)
                        else -> {}
                    }
                } }
                is LabeledStatement -> walkStmt(s.statement)
                is ModuleDeclaration -> (s.body as? ModuleBlock)?.let { walkStmts(it.statements) }
                else -> {}
            }
        }
        walkStmts = { list -> list.forEach { walkStmt(it) } }
        stmts.forEach { walkStmt(it) }
        return out
    }

    private fun isExportedNameTypeOnly(name: String, moduleSpecifier: String): Boolean {
        val targetFile = resolveModuleSpecifier(moduleSpecifier, null) ?: return false
        val targetResult = fileResults[targetFile] ?: return false
        var hasTypeOnly = false
        var hasValue = false
        for (stmt in targetResult.sourceFile.statements) {
            when (stmt) {
                is TypeAliasDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) hasTypeOnly = true
                is InterfaceDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) hasTypeOnly = true
                is ClassDeclaration ->
                    if (stmt.name?.text == name && ModifierFlag.Export in stmt.modifiers) hasValue = true
                is FunctionDeclaration ->
                    if (stmt.name?.text == name && ModifierFlag.Export in stmt.modifiers) hasValue = true
                is EnumDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) hasValue = true
                is VariableStatement ->
                    if (ModifierFlag.Export in stmt.modifiers &&
                        stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) hasValue = true
                // B287: an exported VALUE-FREE namespace (only types/interfaces inside)
                // is a type-only export — `export namespace Event { export type T }`
                // erases entirely, so importing it without `import type` is TS1484.
                is ModuleDeclaration ->
                    if ((stmt.name as? Identifier)?.text == name && ModifierFlag.Export in stmt.modifiers) {
                        if (isNamespaceInstantiated(stmt)) hasValue = true else hasTypeOnly = true
                    }
                is ExportDeclaration -> {
                    val clause = stmt.exportClause as? NamedExports ?: continue
                    for (spec in clause.elements) {
                        if (spec.name.text != name) continue
                        if (stmt.isTypeOnly || spec.isTypeOnly) hasTypeOnly = true else hasValue = true
                    }
                }
                else -> {}
            }
        }
        return hasTypeOnly && !hasValue
    }

    /**
     * TS2440 barrel firewall: is [name] exported from [moduleSpecifier] ONLY as a TYPE
     * (interface / type-alias / uninstantiated namespace / type-only re-export), following
     * `export *` barrels — unlike [isExportedNameTypeOnly], which inspects only the DIRECT
     * exports of the resolved file? A type-only import declaration-merges with a local
     * VALUE-only declaration (function / value const) of the same name (the import provides
     * the type, the local provides the value), so no TS2440 — tsc's own `src/compiler` does
     * exactly this (`import { Node } from "./_namespaces/ts.js"` where the barrel re-exports
     * `export interface Node` from types.ts, plus a local `function Node`).
     *
     * FN-safe (conservative): returns true ONLY when the closure resolves fully and the name
     * is found solely as a type; ANY uncertainty (unresolvable star target, `export =`, a
     * local `export { X }` re-export whose kind we can't resolve, depth blow-out, or the name
     * having a value meaning anywhere) yields false → the caller keeps its existing behavior.
     */
    private fun importedNameIsTypeOnlyThroughBarrel(name: String, moduleSpecifier: String, fromFile: String): Boolean {
        // The import specifier is typically `./_namespaces/ts.js` — resolveModuleSpecifier does
        // NOT strip `.js` (documented), so use the barrel-star resolver's `.js`/`.jsx` fallback.
        val target = if (moduleSpecifier.startsWith("./") || moduleSpecifier.startsWith("../")) {
            resolveBarrelStarTarget(moduleSpecifier, fromFile)
        } else {
            resolveModuleSpecifier(moduleSpecifier, null)?.let { fileResults[it]?.sourceFile }
        } ?: return false
        // Memoize per (barrel target, name): the export-kind closure of a barrel is huge
        // (`export * from` the whole compiler), so an un-memoized per-specifier walk times out.
        val key = "${target.fileName}␀$name"
        barrelTypeOnlyMemo[key]?.let { return it }
        val acc = BarrelExportKind()
        accumulateBarrelExportKind(name, target, acc, mutableSetOf(), 0, forceType = false)
        val result = acc.resolvable && acc.hasType && !acc.hasValue
        barrelTypeOnlyMemo[key] = result
        return result
    }

    private class BarrelExportKind {
        var hasValue = false
        var hasType = false
        var resolvable = true
    }

    private fun accumulateBarrelExportKind(
        name: String, file: SourceFile, acc: BarrelExportKind,
        visited: MutableSet<String>, depth: Int, forceType: Boolean,
    ) {
        if (depth > 64) { acc.resolvable = false; return }
        if (!visited.add(file.fileName)) return // cycle back-edge: its exports were already counted
        for (stmt in file.statements) {
            when (stmt) {
                is InterfaceDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) acc.hasType = true
                is TypeAliasDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) acc.hasType = true
                is ClassDeclaration ->
                    if (stmt.name?.text == name && ModifierFlag.Export in stmt.modifiers) { if (forceType) acc.hasType = true else acc.hasValue = true }
                is FunctionDeclaration ->
                    if (stmt.name?.text == name && ModifierFlag.Export in stmt.modifiers) { if (forceType) acc.hasType = true else acc.hasValue = true }
                is EnumDeclaration ->
                    if (stmt.name.text == name && ModifierFlag.Export in stmt.modifiers) { if (forceType) acc.hasType = true else acc.hasValue = true }
                is VariableStatement ->
                    if (ModifierFlag.Export in stmt.modifiers &&
                        stmt.declarationList.declarations.any { (it.name as? Identifier)?.text == name }) { if (forceType) acc.hasType = true else acc.hasValue = true }
                is ModuleDeclaration ->
                    if ((stmt.name as? Identifier)?.text == name && ModifierFlag.Export in stmt.modifiers) {
                        if (isNamespaceInstantiated(stmt) && !forceType) acc.hasValue = true else acc.hasType = true
                    }
                is ExportDeclaration -> {
                    val clause = stmt.exportClause
                    val fromSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text
                    if (clause == null) {
                        // `export * from "sub"` (or `export type * from "sub"`) — recurse with the
                        // SHARED visited set (a re-visited file's exports were already counted) so
                        // the closure is walked once, not re-walked per re-export path.
                        if (fromSpec == null) { acc.resolvable = false; continue }
                        val sub = resolveBarrelStarTarget(fromSpec, file.fileName)
                        if (sub == null) { acc.resolvable = false; continue }
                        accumulateBarrelExportKind(name, sub, acc, visited, depth + 1, forceType || stmt.isTypeOnly)
                    } else if (clause is NamedExports) {
                        for (spec in clause.elements) {
                            if (spec.name.text != name) continue
                            // A type-only named re-export contributes only a type; any other
                            // named re-export (`export { X } from sub` / local `export { X }`)
                            // has an uncertain source kind → be conservative (don't suppress).
                            if (forceType || stmt.isTypeOnly || spec.isTypeOnly) acc.hasType = true
                            else acc.resolvable = false
                        }
                    }
                }
                else -> {}
            }
        }
    }

    /** Resolve a relative `export *`/`export ... from` specifier (with the `.js`/`.jsx`
     *  fallback used across the star-following helpers) to a bound source-file name. */
    private fun resolveBarrelStarTarget(spec: String, fromFile: String): SourceFile? {
        if (!spec.startsWith("./") && !spec.startsWith("../")) return null
        val key = "$fromFile|$spec"
        barrelStarTargetCache[key]?.let { return it }
        if (barrelStarTargetCache.containsKey(key)) return null
        val resolved = resolveModuleSpecifierRelative(spec, fromFile)
            ?: (if (spec.endsWith(".js")) resolveModuleSpecifierRelative(spec.removeSuffix(".js"), fromFile) else null)
            ?: (if (spec.endsWith(".jsx")) resolveModuleSpecifierRelative(spec.removeSuffix(".jsx"), fromFile) else null)
        val result = resolved?.let { fileResults[it]?.sourceFile }
        barrelStarTargetCache[key] = result
        return result
    }

    /**
     * Is the module referenced by `require("specifier")` type-only — i.e. its `export = X`
     * target `X` is declared in the module ONLY as a type (alias/interface) and not as a value?
     * Used by the isolatedModules TS1269 check for the `export import T = require(...)` form.
     */
    private fun isRequireModuleTypeOnly(specifier: String): Boolean {
        val targetFile = resolveModuleSpecifier(specifier, null) ?: return false
        val targetResult = fileResults[targetFile] ?: return false
        val exportAssign = targetResult.sourceFile.statements.firstNotNullOfOrNull {
            if (it is ExportAssignment && it.isExportEquals) it else null
        } ?: return false
        val target = exportAssign.expression as? Identifier ?: return false
        var hasType = false
        var hasValue = false
        for (s in targetResult.sourceFile.statements) {
            when (s) {
                is TypeAliasDeclaration -> if (s.name.text == target.text) hasType = true
                is InterfaceDeclaration -> if (s.name.text == target.text) hasType = true
                is ClassDeclaration -> if (s.name?.text == target.text) hasValue = true
                is FunctionDeclaration -> if (s.name?.text == target.text) hasValue = true
                is EnumDeclaration -> if (s.name.text == target.text) hasValue = true
                is VariableStatement -> if (s.declarationList.declarations.any { (it.name as? Identifier)?.text == target.text }) hasValue = true
                is ModuleDeclaration -> if ((s.name as? Identifier)?.text == target.text) hasValue = true
                else -> {}
            }
        }
        return hasType && !hasValue
    }

    /**
     * TS1205 / TS1448: under isolatedModules, a re-export of a type-only name must use
     * `export type`. `export { T } from "m"` (or local `export { T }` of a value-imported
     * type) is ambiguous to a single-file transpiler. TS1205 when the name is a DIRECT type
     * in the source; TS1448 when its type-only-ness comes from a type-only re-export
     * (`export type { X } from ...`) in another file. FP-safe: gated on the EXISTING
     * `isExportedNameTypeOnly` helper (true only for genuinely type-only exports), skips
     * `export type` / type-only specifiers / type-only imports / namespace imports / .d.ts.
     */
    /**
     * B162: TS1280 — under isolatedModules, a non-ambient INSTANTIATED namespace declared at the
     * top level of a global SCRIPT file (non-module, non-.d.ts) cannot be transpiled per-file
     * (its IIFE would need to merge with same-named namespaces in other files via a shared
     * global). Uninstantiated (type-only) and `declare` namespaces are erased, so they're fine.
     */
    private fun checkIsolatedModulesScriptNamespaces() {
        if (!options.isolatedModules) return
        if (options.moduleDetection == "force") return // every file is a module
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if (ModifierFlag.Declare in stmt.modifiers) continue
                val name = stmt.name as? Identifier ?: continue
                if (getModuleInstanceState(stmt) != ModuleInstanceState.Instantiated) continue
                val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                diagnostics.add(Diagnostic(
                    message = "Namespaces are not allowed in global script files when 'isolatedModules' is enabled. If this file is not intended to be a global script, set 'moduleDetection' to 'force' or add an empty 'export {}' statement.",
                    category = DiagnosticCategory.Error, code = 1280,
                    fileName = fileName, line = line, character = character,
                    start = name.pos, length = name.text.length,
                ))
            }
        }
    }

    private fun checkIsolatedModulesReExportType() {
        if (!options.isolatedModules || options.verbatimModuleSyntax) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements
            for (stmt in stmts) {
                if (stmt !is ExportDeclaration || stmt.isTypeOnly) continue
                val clause = stmt.exportClause as? NamedExports ?: continue
                val moduleSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text
                for (spec in clause.elements) {
                    if (spec.isTypeOnly) continue
                    val srcName: String
                    val srcSpec: String
                    if (moduleSpec != null) {
                        // `export { X } from "spec"`
                        srcName = (spec.propertyName ?: spec.name).text
                        srcSpec = moduleSpec
                    } else {
                        // local `export { X (as Y) }` — X must be a NON-type-only named import
                        val imp = findNonTypeOnlyImport((spec.propertyName ?: spec.name).text, stmts) ?: continue
                        srcName = imp.first
                        srcSpec = imp.second
                    }
                    if (!isExportedNameTypeOnly(srcName, srcSpec)) continue
                    val nameNode = spec.propertyName ?: spec.name
                    // Span covers the WHOLE specifier (`T as T4`), which for a no-rename
                    // specifier collapses to just the name.
                    val spanStart = nameNode.pos
                    val spanEnd = spec.name.pos + spec.name.text.length
                    val isTs1448 = isTypeOnlyExportName(srcName, srcSpec, fileName)
                    val code = if (isTs1448) 1448 else 1205
                    val msg = if (isTs1448)
                        "'${nameNode.text}' resolves to a type-only declaration and must be re-exported using a type-only re-export when 'isolatedModules' is enabled."
                    else
                        "Re-exporting a type when 'isolatedModules' is enabled requires using 'export type'."
                    // TS1448 carries a related TS1377 pointing at the type-only re-export in the source file.
                    val related: List<Diagnostic> = if (isTs1448) {
                        findTypeOnlyReExportSpecifier(srcName, srcSpec)?.let { (declFile, declPos) ->
                            val declSource = fileResults[declFile]?.sourceFile?.text
                            if (declSource != null) {
                                val (rl, rc) = getLineAndCharacterOfPosition(declSource, declPos)
                                listOf(Diagnostic(
                                    message = "'${nameNode.text}' was exported here.",
                                    category = DiagnosticCategory.Message, code = 1377,
                                    fileName = declFile, line = rl, character = rc,
                                    start = declPos, length = srcName.length,
                                ))
                            } else emptyList()
                        } ?: emptyList()
                    } else emptyList()
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = msg, category = DiagnosticCategory.Error, code = code,
                        fileName = fileName, line = line, character = character,
                        start = spanStart, length = spanEnd - spanStart,
                        relatedInformation = related,
                    ))
                }
            }
        }
    }

    /** Find the `export type { name }` specifier in the module [moduleSpec]; returns (declFile, specPos) for TS1377. */
    private fun findTypeOnlyReExportSpecifier(name: String, moduleSpec: String): Pair<String, Int>? {
        val targetFile = resolveModuleSpecifier(moduleSpec, null) ?: return null
        val targetResult = fileResults[targetFile] ?: return null
        for (stmt in targetResult.sourceFile.statements) {
            if (stmt !is ExportDeclaration) continue
            val clause = stmt.exportClause as? NamedExports ?: continue
            for (spec in clause.elements) {
                if (spec.name.text == name && (stmt.isTypeOnly || spec.isTypeOnly)) {
                    return targetFile to (spec.propertyName ?: spec.name).pos
                }
            }
        }
        return null
    }

    /** Find a NON-type-only named import of [localName] in [stmts]; returns (sourceName, moduleSpec) or null. */
    private fun findNonTypeOnlyImport(localName: String, stmts: List<Statement>): Pair<String, String>? {
        for (stmt in stmts) {
            if (stmt !is ImportDeclaration) continue
            val clause = stmt.importClause ?: continue
            if (clause.isTypeOnly) continue
            val spec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
            val nb = clause.namedBindings as? NamedImports ?: continue
            for (el in nb.elements) {
                if (el.name.text != localName || el.isTypeOnly) continue
                return (el.propertyName ?: el.name).text to spec
            }
        }
        return null
    }

    /**
     * B61.5f helper: returns true when the source text leading up to an
     * ImportEqualsDeclaration's pos contains a class-only modifier keyword
     * (public/private/protected/static). Used to suppress TS2440 FP when
     * TS1044 already fires for the invalid modifier.
     */
    private fun sourceHasClassOnlyModifierBeforeImportEquals(
        stmt: ImportEqualsDeclaration,
        source: String,
    ): Boolean {
        val classOnlyKws = listOf("public", "private", "protected", "static")
        // Find start of line containing stmt.pos
        var lineStart = stmt.pos
        while (lineStart > 0 && source[lineStart - 1] != '\n') lineStart--
        val prefix = source.substring(lineStart, stmt.pos)
        for (kw in classOnlyKws) {
            // Word-boundary match: must be surrounded by non-letter-digit chars
            var idx = 0
            while (true) {
                val found = prefix.indexOf(kw, idx)
                if (found < 0) break
                val before = if (found == 0) ' ' else prefix[found - 1]
                val after = if (found + kw.length >= prefix.length) ' ' else prefix[found + kw.length]
                if (!before.isLetterOrDigit() && !after.isLetterOrDigit()) return true
                idx = found + 1
            }
        }
        return false
    }

    /**
     * B61.5h: TS1473 "An import declaration can only be used at the top level of a module."
     * Walks each file's statements; for nested function bodies / blocks etc., emits TS1473
     * at any ImportDeclaration found. Top-level imports remain valid.
     */
    private fun checkImportNotAtTopLevel() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // B76.2: TS1473 fires only for .js/.jsx files. For .ts/.tsx,
            // checkNamespaceTopLevelOnly emits TS1232 (correct code for
            // nested-block imports) at the same positions.
            if (fileName.endsWith(".ts") || fileName.endsWith(".tsx") ||
                fileName.endsWith(".mts") || fileName.endsWith(".cts")) continue
            val source = result.sourceFile.text
            // Walk each top-level statement, recursing into non-module-level constructs.
            for (stmt in result.sourceFile.statements) {
                walkForNestedImports(stmt, source, fileName, topLevel = true)
            }
        }
    }

    private fun walkForNestedImports(stmt: Statement, source: String, fileName: String, topLevel: Boolean) {
        if (!topLevel && stmt is ImportDeclaration) {
            val start = stmt.pos
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "An import declaration can only be used at the top level of a module.",
                category = DiagnosticCategory.Error,
                code = 1473,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = 6, // "import"
            ))
        }
        when (stmt) {
            is FunctionDeclaration -> stmt.body?.statements?.forEach {
                walkForNestedImports(it, source, fileName, topLevel = false)
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        is Constructor -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        is GetAccessor -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        is SetAccessor -> m.body?.statements?.forEach {
                            walkForNestedImports(it, source, fileName, topLevel = false)
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                // Module body — top-level inside namespace counts as top-level too
                // (`namespace M { import X from "y"; }` is allowed).
                (stmt.body as? ModuleBlock)?.statements?.forEach {
                    walkForNestedImports(it, source, fileName, topLevel = true)
                }
            }
            is Block -> stmt.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
            is IfStatement -> {
                walkForNestedImports(stmt.thenStatement, source, fileName, topLevel = false)
                stmt.elseStatement?.let { walkForNestedImports(it, source, fileName, topLevel = false) }
            }
            is WhileStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is DoStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is ForStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is ForInStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is ForOfStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            is TryStatement -> {
                stmt.tryBlock.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                stmt.catchClause?.block?.statements?.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                stmt.finallyBlock?.statements?.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> clause.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                        is DefaultClause -> clause.statements.forEach { walkForNestedImports(it, source, fileName, topLevel = false) }
                        else -> {}
                    }
                }
            }
            is LabeledStatement -> walkForNestedImports(stmt.statement, source, fileName, topLevel = false)
            else -> {}
        }
    }

    /**
     * B98.r17: TS2440 "Import declaration conflicts with local declaration of 'X'." for an
     * `import X = <internal-ns-ref>` (NOT `require(...)`) declared inside a namespace block whose
     * name X collides with a `var/let/const X` declared in ANOTHER block of the SAME merged
     * namespace. The file-level `checkImportConflictsWithLocal` never recurses into namespace
     * bodies, so cross-block conflicts inside a merged namespace were missed. Only conflicts with
     * VARIABLES (internal aliases declaration-merge with class/function/enum, so those don't count).
     */
    private fun checkNamespaceImportVarConflict() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkNsImportVarConflictInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkNsImportVarConflictInStatements(stmts: List<Statement>, source: String, fileName: String) {
        val nsGroups = mutableMapOf<String, MutableList<ModuleDeclaration>>()
        for (stmt in stmts) {
            if (stmt is ModuleDeclaration) {
                (stmt.name as? Identifier)?.let { nsGroups.getOrPut(it.text) { mutableListOf() }.add(stmt) }
                (stmt.body as? ModuleBlock)?.let { checkNsImportVarConflictInStatements(it.statements, source, fileName) }
            }
        }
        for ((_, blocks) in nsGroups) {
            // Merge var names across all blocks of this same-named namespace.
            val varNames = mutableSetOf<String>()
            for (block in blocks) {
                val body = block.body as? ModuleBlock ?: continue
                for (s in body.statements) if (s is VariableStatement) {
                    for (decl in s.declarationList.declarations) (decl.name as? Identifier)?.let { varNames.add(it.text) }
                }
            }
            if (varNames.isEmpty()) continue
            for (block in blocks) {
                val body = block.body as? ModuleBlock ?: continue
                for (s in body.statements) {
                    if (s !is ImportEqualsDeclaration) continue
                    if (s.isTypeOnly) continue
                    if (s.moduleReference is ExternalModuleReference) continue   // `require(...)` is a different conflict
                    val name = s.name.text
                    if (name !in varNames) continue
                    // ImportEqualsDeclaration.pos points at `import`; back up over the
                    // `export` modifier (parser drops it from pos) so the squiggle covers
                    // the whole `export import X = …;` statement.
                    var stmtStart = s.pos
                    if (ModifierFlag.Export in s.modifiers) {
                        var p = s.pos
                        while (p > 0 && source[p - 1].isWhitespace()) p--
                        if (p >= 6 && source.substring(p - 6, p) == "export") stmtStart = p - 6
                    }
                    val endIdx = source.indexOf(';', stmtStart)
                    val stmtLen = if (endIdx >= 0) endIdx - stmtStart + 1 else (s.end - stmtStart).coerceAtLeast(name.length)
                    val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                    diagnostics.add(Diagnostic(
                        message = "Import declaration conflicts with local declaration of '$name'.",
                        category = DiagnosticCategory.Error,
                        code = 2440,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = stmtStart,
                        length = stmtLen,
                    ))
                }
            }
        }
    }

    private fun checkImportConflictsWithLocal() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements

            // Collect all non-import declared names in this file, tracking declaration kind
            // Variables conflict with import aliases; classes/functions/interfaces can merge
            val varNames = mutableSetOf<String>()     // variable declarations
            val mergeableNames = mutableSetOf<String>() // class/function/enum — can merge with internal aliases
            val typeOnlyNames = mutableSetOf<String>() // type alias / interface — can conflict with type-only imports
            // Type aliases specifically — these CANNOT merge with any other declaration kind
            // (unlike interfaces which can merge with classes/namespaces/values via declaration merging).
            // `import { X } from "..."` (binding a value) + local `type X = ...` is therefore a hard
            // conflict regardless of the imported symbol's kind, distinct from the type-only-vs-type-only
            // case handled by `isExportedNameTypeOnly`.
            val typeAliasNames = mutableSetOf<String>()
            // Local value-declaration names that a NAMED import cannot share (function /
            // class / enum / namespace). A named `import { X }` does not declaration-merge
            // with a local function/class/enum/namespace of the same name → TS2440. (This is
            // distinct from `mergeableNames`, which exists to AVOID conflicting with an
            // import-equals INTERNAL alias.)
            val namedImportConflictNames = mutableSetOf<String>()
            // VALUE-only local declaration names (functions + value vars) and names carrying a
            // TYPE side (class/interface/enum/typealias/namespace). A type-only import merges
            // with a value-only local of the same name (no TS2440) — see
            // importedNameIsTypeOnlyThroughBarrel.
            val functionNames = mutableSetOf<String>()
            val typeSideNames = mutableSetOf<String>()
            for (stmt in stmts) {
                when (stmt) {
                    is VariableStatement -> {
                        for (decl in stmt.declarationList.declarations) {
                            val name = (decl.name as? Identifier)?.text ?: continue
                            varNames.add(name)
                        }
                    }
                    is FunctionDeclaration -> stmt.name?.let { mergeableNames.add(it.text); namedImportConflictNames.add(it.text); functionNames.add(it.text) }
                    is ClassDeclaration -> stmt.name?.let { mergeableNames.add(it.text); namedImportConflictNames.add(it.text); typeSideNames.add(it.text) }
                    is EnumDeclaration -> { mergeableNames.add(stmt.name.text); namedImportConflictNames.add(stmt.name.text); typeSideNames.add(stmt.name.text) }
                    is ModuleDeclaration -> (stmt.name as? Identifier)?.let { namedImportConflictNames.add(it.text); typeSideNames.add(it.text) }
                    is TypeAliasDeclaration -> {
                        typeOnlyNames.add(stmt.name.text)
                        typeAliasNames.add(stmt.name.text)
                        typeSideNames.add(stmt.name.text)
                    }
                    is InterfaceDeclaration -> { typeOnlyNames.add(stmt.name.text); typeSideNames.add(stmt.name.text) }
                    else -> {}
                }
            }
            val localNames = varNames + mergeableNames
            // A local declared solely as a value (function or value var), never with a type side.
            val valueOnlyLocalNames = (functionNames + varNames) - typeSideNames

            // B129: TS2395 — a name declared by BOTH an internal import-equals alias AND
            // a type-alias (a merged declaration) with MIXED export status (one exported,
            // one not) → "must be all exported or all local." Emit at each declaration's
            // name. Narrowly gated to this specific merge (FP-safe: mixed-export of an
            // import-equals + type-alias is always TS2395). Pairs with the TS2440 below.
            run {
                val mergeDecls = HashMap<String, MutableList<Pair<Int, Boolean>>>()
                val sawImportEq = HashSet<String>()
                for (s in stmts) when (s) {
                    is ImportEqualsDeclaration -> if (!s.isTypeOnly && s.moduleReference !is ExternalModuleReference) {
                        mergeDecls.getOrPut(s.name.text) { mutableListOf() }.add(s.name.pos to (ModifierFlag.Export in s.modifiers))
                        sawImportEq.add(s.name.text)
                    }
                    is TypeAliasDeclaration -> mergeDecls.getOrPut(s.name.text) { mutableListOf() }.add(s.name.pos to (ModifierFlag.Export in s.modifiers))
                    else -> {}
                }
                for ((nm, ds) in mergeDecls) {
                    if (nm !in sawImportEq || ds.size < 2) continue
                    if (ds.any { it.second } && ds.any { !it.second }) {
                        for ((pos, _) in ds) {
                            val (line, character) = getLineAndCharacterOfPosition(source, pos)
                            diagnostics.add(Diagnostic(
                                message = "Individual declarations in merged declaration '$nm' must be all exported or all local.",
                                category = DiagnosticCategory.Error, code = 2395,
                                fileName = fileName, line = line, character = character, start = pos, length = nm.length,
                            ))
                        }
                    }
                }
            }

            // Check imports against local names
            for (stmt in stmts) {
                when (stmt) {
                    is ImportEqualsDeclaration -> {
                        if (stmt.isTypeOnly) continue
                        // B61.5f: Skip TS2440 when import-equals has class-only modifier keywords
                        // in source text (parser drops them from stmt.modifiers, so source-scan).
                        // TS1044 fires for these and the binding shouldn't also conflict.
                        if (sourceHasClassOnlyModifierBeforeImportEquals(stmt, source)) continue
                        // Internal namespace aliases (import foo = m1) can merge with class/function/interface
                        // but NOT with variable declarations
                        // Internal namespace aliases (import foo = m1) can merge with
                        // class/function/interface but NOT with variable declarations OR
                        // type-aliases. B129: a local internal value-side alias colliding
                        // with a local `type X` is TS2440 — type-aliases never
                        // declaration-merge with an import alias.
                        val isInternalAlias = stmt.moduleReference !is ExternalModuleReference
                        val name = stmt.name.text
                        if (isInternalAlias && name !in varNames && name !in typeAliasNames) continue
                        if (name in localNames || (isInternalAlias && name in typeAliasNames)) {
                            // Error on entire import statement
                            val stmtStart = stmt.pos
                            // Find end of statement including semicolon
                            val stmtEnd = stmt.end
                            // Approximate length: scan source for semicolon or newline after pos
                            val endIdx = source.indexOf(';', stmtStart)
                            val stmtLen = if (endIdx >= 0) endIdx - stmtStart + 1
                                else (stmtEnd - stmtStart).coerceAtLeast(name.length)
                            val (line, character) = getLineAndCharacterOfPosition(source, stmtStart)
                            diagnostics.add(Diagnostic(
                                message = "Import declaration conflicts with local declaration of '$name'.",
                                category = DiagnosticCategory.Error,
                                code = 2440,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = stmtStart,
                                length = stmtLen,
                            ))
                        }
                    }
                    is ImportDeclaration -> {
                        // TS2440 fires for bindings that conflict with local var declarations.
                        // Rule: fires when there's a var with the same name AFTER the import AND
                        // NO var with the same name BEFORE the import (first occurrence determines the slot).
                        val clause = stmt.importClause ?: continue
                        // `import type { X }` / `import type X` create no runtime binding, so no conflict.
                        if (clause.isTypeOnly) continue
                        val importPos = stmt.pos
                        val moduleSpecifierText = (stmt.moduleSpecifier as? StringLiteralNode)?.text

                        // Helper: check if name conflicts (var after import, no var before import)
                        fun hasVarConflict(name: String): Boolean {
                            val varBeforeImport = stmts.any { s ->
                                s is VariableStatement && s.pos < importPos &&
                                    s.declarationList.declarations.any { d ->
                                        (d.name as? Identifier)?.text == name
                                    }
                            }
                            if (varBeforeImport) return false
                            return stmts.any { s ->
                                s is VariableStatement && s.pos > importPos &&
                                    s.declarationList.declarations.any { d ->
                                        (d.name as? Identifier)?.text == name
                                    }
                            }
                        }

                        // Default binding
                        val defaultName = clause.name?.text
                        if (defaultName != null && defaultName in varNames) {
                            if (hasVarConflict(defaultName)) {
                                val (line, character) = getLineAndCharacterOfPosition(source, clause.name.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Import declaration conflicts with local declaration of '$defaultName'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2440,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = clause.name.pos,
                                    length = defaultName.length,
                                ))
                            }
                        }
                        // Namespace binding: import * as NS
                        val nb = clause.namedBindings
                        if (nb is NamespaceImport) {
                            val nsName = nb.name.text
                            // A namespace import does NOT declaration-merge with a local
                            // `namespace NS {}` declared LATER in the file (namespaceMergedWith-
                            // ImportAliasNoCrash) → TS2440. Gated to a non-declare local namespace
                            // declared after the import (mirrors the var-after-import rule; avoids
                            // ambient-augmentation FPs).
                            val nsAfterImport = stmts.any { s ->
                                s is ModuleDeclaration && s.pos > importPos &&
                                    ModifierFlag.Declare !in s.modifiers &&
                                    (s.name as? Identifier)?.text == nsName
                            }
                            if (nsName in varNames && hasVarConflict(nsName) || nsAfterImport) {
                                val (line, character) = getLineAndCharacterOfPosition(source, nb.name.pos)
                                diagnostics.add(Diagnostic(
                                    message = "Import declaration conflicts with local declaration of '$nsName'.",
                                    category = DiagnosticCategory.Error,
                                    code = 2440,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = nb.name.pos,
                                    length = nsName.length,
                                ))
                            }
                        }
                        // Named specifiers: import { x } or { x as localAlias }
                        if (nb is NamedImports) {
                            for (element in nb.elements) {
                                // Per-specifier `import { type X }` creates no runtime binding.
                                if (element.isTypeOnly) continue
                                val localAlias = element.name.text
                                val sourceNameForElt = (element.propertyName ?: element.name).text
                                // A type-only import (the source exports the name ONLY as a type,
                                // possibly through an `export *` barrel) declaration-merges with a
                                // local VALUE-only declaration (function / value const) of the same
                                // name — the import provides the type, the local provides the value —
                                // so NO TS2440 (tsc's own src/compiler `import { Node }` + local
                                // `function Node`). Gated to value-only locals (a class/enum/
                                // interface/namespace local has a type side that DOES conflict) and
                                // to a definitively type-only barrel resolution (FN-safe). ONLY under
                                // NEITHER isolatedModules NOR verbatimModuleSyntax — those modes DO
                                // error on the merge (TS2865 / TS1484 / TS2440), just via the paths
                                // below (isolatedModulesSketchyAliasLocalMerge / …ExportDeclarationType).
                                if (!options.isolatedModules && !options.verbatimModuleSyntax &&
                                    localAlias in valueOnlyLocalNames &&
                                    moduleSpecifierText != null &&
                                    importedNameIsTypeOnlyThroughBarrel(sourceNameForElt, moduleSpecifierText, fileName)) {
                                    continue
                                }
                                // Type-only-vs-type-only conflict: `import { T }` (where T is a type-only
                                // export in source) + local `type T` / `interface T` declaration. Both
                                // declare T as a type, so they collide. Emit TS2440 (NOT TS2865 — local
                                // is a type, not a value). The narrow gate (isExportedNameTypeOnly) avoids
                                // FPs against valid `import { Class }` + `interface Class` augmentation
                                // patterns (where Class is a value+type in source).
                                if (localAlias in typeOnlyNames &&
                                    moduleSpecifierText != null &&
                                    isExportedNameTypeOnly(sourceNameForElt, moduleSpecifierText)) {
                                    val startNode = element.propertyName ?: element.name
                                    val startPos = startNode.pos
                                    val spanLen = if (element.propertyName != null) {
                                        element.name.pos + element.name.text.length - startPos
                                    } else {
                                        localAlias.length
                                    }
                                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = startPos,
                                        length = spanLen,
                                    ))
                                    continue
                                }
                                // TypeAlias-vs-value-import conflict: `type X = ...` cannot share a name
                                // with `import { X } from "..."` since TypeAlias doesn't participate in
                                // declaration merging. Mirrors TS2440 fired in this exact shape (e.g.
                                // `import {E} from "./f1"; type E = E;` where f1 re-exports a value).
                                if (localAlias in typeAliasNames) {
                                    val startNode = element.propertyName ?: element.name
                                    val startPos = startNode.pos
                                    val spanLen = if (element.propertyName != null) {
                                        element.name.pos + element.name.text.length - startPos
                                    } else {
                                        localAlias.length
                                    }
                                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = startPos,
                                        length = spanLen,
                                    ))
                                    continue
                                }
                                // Named import of a value name conflicting with a local
                                // function / class / enum / namespace declaration → TS2440
                                // (these do not declaration-merge with a named import).
                                if (localAlias in namedImportConflictNames) {
                                    val startNode = element.propertyName ?: element.name
                                    val startPos = startNode.pos
                                    val spanLen = if (element.propertyName != null) {
                                        element.name.pos + element.name.text.length - startPos
                                    } else {
                                        localAlias.length
                                    }
                                    val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                    diagnostics.add(Diagnostic(
                                        message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                        category = DiagnosticCategory.Error,
                                        code = 2440,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = startPos,
                                        length = spanLen,
                                    ))
                                    continue
                                }
                                if (localAlias in varNames) {
                                    if (hasVarConflict(localAlias)) {
                                        // Position at the start of the element (propertyName if aliased, otherwise name)
                                        // Span covers the full element including "as" keyword: "x as y"
                                        val startNode = element.propertyName ?: element.name
                                        val startPos = startNode.pos
                                        val spanLen = if (element.propertyName != null) {
                                            // "x as y" — from property name start to alias name end
                                            element.name.pos + element.name.text.length - startPos
                                        } else {
                                            localAlias.length
                                        }
                                        val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                                        // TS2865: under isolatedModules, when the imported name resolves to a
                                        // type-only export in the source module, the import should have been
                                        // `import type { X }`. Emit TS2865 in place of TS2440 to direct the
                                        // user to the right fix. verbatimModuleSyntax routes through TS1484.
                                        val sourceName = (element.propertyName ?: element.name).text
                                        val sourceIsTypeOnly = moduleSpecifierText != null &&
                                            isExportedNameTypeOnly(sourceName, moduleSpecifierText)
                                        // 17.131: Under verbatimModuleSyntax + type-only-in-source, the new
                                        // checkVerbatimModuleSyntax walker emits TS1484 covering the same
                                        // diagnostic surface — suppress TS2440 here. TS2865 still fires
                                        // alongside TS1484 when isolatedModules is also enabled.
                                        val verbatimTypeOnlyInSource = options.verbatimModuleSyntax && sourceIsTypeOnly
                                        val isolatedTypeOnlyInSource = options.isolatedModules && sourceIsTypeOnly
                                        if (isolatedTypeOnlyInSource) {
                                            diagnostics.add(Diagnostic(
                                                message = "Import '$localAlias' conflicts with local value, so must be declared with a type-only import when 'isolatedModules' is enabled.",
                                                category = DiagnosticCategory.Error,
                                                code = 2865,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = startPos,
                                                length = spanLen,
                                            ))
                                        }
                                        if (!verbatimTypeOnlyInSource && !isolatedTypeOnlyInSource) {
                                            diagnostics.add(Diagnostic(
                                                message = "Import declaration conflicts with local declaration of '$localAlias'.",
                                                category = DiagnosticCategory.Error,
                                                code = 2440,
                                                fileName = fileName,
                                                line = line,
                                                character = character,
                                                start = startPos,
                                                length = spanLen,
                                            ))
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    // TS1292: 'X' resolves to a type and must be marked type-only when re-exporting under isolatedModules
    // -----------------------------------------------------------------------

    /**
     * Under `isolatedModules`, `export default X` where X resolves to a type-only import
     * (and there's no local value declaration named X) requires `export type { X as default }`
     * because the transpiler can't know whether to elide the export at runtime. Emits TS1292
     * at the expression's position. Skipped when `verbatimModuleSyntax` is enabled (different
     * diagnostic family fires there).
     */
    /**
     * TS1269: "Cannot use 'export import' on a type or type-only namespace when
     * 'isolatedModules' is enabled." Fires for `export import X = Y` (or `export import X = A.B`)
     * where Y resolves to a type alias, interface, or type-only namespace under
     * `@isolatedModules`. The transpiler cannot keep the runtime binding if Y has no value side.
     */
    private fun checkIsolatedModulesExportImportIsType() {
        if (!options.isolatedModules || options.verbatimModuleSyntax) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements

            // Detect: is the local binding `name` an import alias of a type-only export
            // from some other file in this program?
            fun importedFromTypeOnlyExport(name: String): Boolean {
                for (stmt in stmts) {
                    if (stmt !is ImportDeclaration) continue
                    val clause = stmt.importClause ?: continue
                    val moduleSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                    val nb = clause.namedBindings
                    if (nb is NamedImports) {
                        val element = nb.elements.firstOrNull { it.name.text == name } ?: continue
                        if (clause.isTypeOnly || element.isTypeOnly) return true
                        val sourceName = (element.propertyName ?: element.name).text
                        if (isExportedNameTypeOnly(sourceName, moduleSpec)) return true
                        // Also handle exported namespace whose members are all types — the
                        // existing helper doesn't yet walk ModuleDeclaration.
                        val targetFile = resolveModuleSpecifier(moduleSpec, null) ?: continue
                        val targetResult = fileResults[targetFile] ?: continue
                        for (s in targetResult.sourceFile.statements) {
                            if (s !is ModuleDeclaration) continue
                            val moduleName = s.name
                            val n = if (moduleName is Identifier) moduleName.text
                                else if (moduleName is StringLiteralNode) moduleName.text
                                else null
                            if (n != sourceName) continue
                            if (ModifierFlag.Export !in s.modifiers) continue
                            // Check via binder's moduleInstanceState — a non-instantiated namespace
                            // (only type members) qualifies.
                            val state = binderResults.firstNotNullOfOrNull { br ->
                                br.moduleInstanceStates[nodeKey(s)]
                            }
                            if (state == ModuleInstanceState.NonInstantiated) return true
                        }
                    }
                    if (nb is NamespaceImport && nb.name.text == name) {
                        // `import * as X from "./m"` — X is a namespace import. Treat as
                        // type-only if the target file exports ONLY types (no value
                        // declarations). Skip for now to avoid over-firing; this is the
                        // narrower namespaced-from-import path.
                    }
                }
                return false
            }

            for (stmt in stmts) {
                if (stmt !is ImportEqualsDeclaration) continue
                if (ModifierFlag.Export !in stmt.modifiers) continue
                // Fires for `export import X = SomeIdent` where SomeIdent resolves to type-only,
                // AND `export import X = require("spec")` where the required module is type-only
                // (its `export = T` target is a type alias/interface).
                val ref = stmt.moduleReference
                val isTypeOnlyRef = if (ref is ExternalModuleReference) {
                    val spec = (ref.expression as? StringLiteralNode)?.text
                    spec != null && isRequireModuleTypeOnly(spec)
                } else {
                    val rootName = when (ref) {
                        is Identifier -> ref.text
                        is QualifiedName -> {
                            var leftmost: Node = ref
                            while (leftmost is QualifiedName) leftmost = leftmost.left
                            (leftmost as? Identifier)?.text
                        }
                        else -> null
                    }
                    rootName != null && importedFromTypeOnlyExport(rootName)
                }
                if (!isTypeOnlyRef) continue
                // The parser's stmt.pos points to `import` (after the `export` modifier was
                // consumed). Walk backward through whitespace to find the start of `export`.
                var startPos = stmt.pos
                var p = startPos - 1
                while (p >= 0 && source[p] in " \t\r\n") p--
                if (p >= 5 && source.substring(p - 5, p + 1) == "export") {
                    startPos = p - 5
                }
                // End at the semicolon (stmt.end overshoots per CLAUDE.md gotcha).
                val semi = source.indexOf(';', stmt.pos)
                val endPos = if (semi >= 0) semi + 1 else stmt.end
                val length = endPos - startPos
                val (line, character) = getLineAndCharacterOfPosition(source, startPos)
                diagnostics.add(Diagnostic(
                    message = "Cannot use 'export import' on a type or type-only namespace when 'isolatedModules' is enabled.",
                    category = DiagnosticCategory.Error,
                    code = 1269,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = startPos,
                    length = length,
                ))
            }
        }
    }

    private fun checkIsolatedModulesExportDefaultIsType() {
        if (!options.isolatedModules || options.verbatimModuleSyntax) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val stmts = result.sourceFile.statements

            // Collect names declared as values in this file (used to short-circuit when the
            // exported identifier is shadowed by a same-name local value declaration).
            val localValueNames = mutableSetOf<String>()
            for (stmt in stmts) {
                when (stmt) {
                    is VariableStatement ->
                        for (decl in stmt.declarationList.declarations) {
                            (decl.name as? Identifier)?.text?.let { localValueNames.add(it) }
                        }
                    is FunctionDeclaration -> stmt.name?.let { localValueNames.add(it.text) }
                    is ClassDeclaration -> stmt.name?.let { localValueNames.add(it.text) }
                    is EnumDeclaration -> localValueNames.add(stmt.name.text)
                    else -> {}
                }
            }

            // Returns true when [name] is imported and resolves to a type-only export in the source
            // module — covers both syntactic `import type { X }` / `import { type X }` AND
            // `import { X }` where X happens to be a type-only export in the source module.
            fun isImportedAsTypeOnly(name: String): Boolean {
                for (stmt in stmts) {
                    if (stmt !is ImportDeclaration) continue
                    val clause = stmt.importClause ?: continue
                    val nb = clause.namedBindings as? NamedImports ?: continue
                    val element = nb.elements.firstOrNull { it.name.text == name } ?: continue
                    if (clause.isTypeOnly || element.isTypeOnly) return true
                    val moduleSpec = (stmt.moduleSpecifier as? StringLiteralNode)?.text ?: continue
                    val sourceName = (element.propertyName ?: element.name).text
                    if (isExportedNameTypeOnly(sourceName, moduleSpec)) return true
                }
                return false
            }

            for (stmt in stmts) {
                if (stmt !is ExportAssignment) continue
                if (stmt.isExportEquals) continue // `export = X` is a separate diagnostic family
                val expr = stmt.expression as? Identifier ?: continue
                val name = expr.text
                if (name in localValueNames) continue
                if (!isImportedAsTypeOnly(name)) continue
                val (line, character) = getLineAndCharacterOfPosition(source, expr.pos)
                diagnostics.add(Diagnostic(
                    message = "'$name' resolves to a type and must be marked type-only in this file before re-exporting when 'isolatedModules' is enabled. Consider using 'export type { $name as default }'.",
                    category = DiagnosticCategory.Error,
                    code = 1292,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = expr.pos,
                    length = name.length,
                ))
            }
        }
    }

    // 17.131: TS1295 / TS1484 — verbatimModuleSyntax restrictions on imports/exports.
    // -----------------------------------------------------------------------

    /**
     * Under `verbatimModuleSyntax`, two related diagnostics fire for non-type-only imports:
     *  - TS1295: in a CommonJS file, ECMAScript imports/exports cannot be written
     *    (the runtime bindings would need to be transformed to require()/exports.X — but
     *    verbatim mode preserves syntax as-written, so the file would be invalid CJS).
     *  - TS1484: when the imported name is a type-only export in the source module, it
     *    must be imported using a type-only form (`import type { X }` or `import { type X }`).
     *
     * Both fire at the imported-name position. Type-only imports (`import type {}`) are
     * exempt from both — they're erased at compile time and have no runtime emission.
     *
     * Scope: named imports + default imports + namespace imports. Side-effect imports
     * (`import "./x"`), import-equals, and export declarations are not yet handled here
     * (deferred — additional surface that may yield more failing-test flips when added).
     */
    private fun checkVerbatimModuleSyntax() {
        if (!options.verbatimModuleSyntax) return
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val isCjs = !isESModuleFormat(options, fileName)

            fun emitTs1295(pos: Int, length: Int) {
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "ECMAScript imports and exports cannot be written in a CommonJS file under 'verbatimModuleSyntax'. Adjust the 'type' field in the nearest 'package.json' to make this file an ECMAScript module, or adjust your 'verbatimModuleSyntax', 'module', and 'moduleResolution' settings in TypeScript.",
                    category = DiagnosticCategory.Error,
                    code = 1295,
                    fileName = fileName, line = line, character = character,
                    start = pos, length = length,
                ))
            }

            fun emitTs1484(pos: Int, length: Int, displayName: String) {
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "'$displayName' is a type and must be imported using a type-only import when 'verbatimModuleSyntax' is enabled.",
                    category = DiagnosticCategory.Error,
                    code = 1484,
                    fileName = fileName, line = line, character = character,
                    start = pos, length = length,
                ))
            }

            fun emitTs1287(pos: Int) {
                val (line, character) = getLineAndCharacterOfPosition(source, pos)
                diagnostics.add(Diagnostic(
                    message = "A top-level 'export' modifier cannot be used on value declarations in a CommonJS module when 'verbatimModuleSyntax' is enabled.",
                    category = DiagnosticCategory.Error,
                    code = 1287,
                    fileName = fileName, line = line, character = character,
                    start = pos, length = 6,  // "export"
                ))
            }

            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ImportDeclaration -> {
                        val clause = stmt.importClause ?: continue
                        // `import type { ... }` — entirely type-only, no diagnostics fire here.
                        if (clause.isTypeOnly) continue
                        val moduleSpecifierText = (stmt.moduleSpecifier as? StringLiteralNode)?.text

                        // Default binding: `import X from "./y"`
                        clause.name?.let { defaultName ->
                            if (isCjs) emitTs1295(defaultName.pos, defaultName.text.length)
                            // TS1484 for default imports of type-only-default exports is not yet handled
                            // (default-as-type is rare and detection requires checking the source's
                            // `export default X` for type-only X — out of scope for the named-imports
                            // path we're focused on).
                        }

                        when (val nb = clause.namedBindings) {
                            is NamespaceImport -> {
                                // `import * as ns from "./y"` — namespace import is non-type-only at the binding,
                                // so TS1295 fires in CJS+verbatim. (TS1484 doesn't apply: a namespace import
                                // brings in both types and values, so type-only-import isn't a meaningful
                                // alternative even when the source is mostly types.)
                                if (isCjs) emitTs1295(nb.name.pos, nb.name.text.length)
                            }
                            is NamedImports -> {
                                for (element in nb.elements) {
                                    if (element.isTypeOnly) continue  // per-element `type` qualifier
                                    val nameNode = element.propertyName ?: element.name
                                    val pos = nameNode.pos
                                    val len = nameNode.text.length
                                    val sourceName = (element.propertyName ?: element.name).text
                                    if (isCjs) emitTs1295(pos, len)
                                    if (moduleSpecifierText != null &&
                                        isExportedNameTypeOnly(sourceName, moduleSpecifierText)) {
                                        emitTs1484(pos, len, sourceName)
                                    }
                                }
                            }
                            else -> {}
                        }
                    }
                    // TS1287: top-level `export` modifier on value declaration in CJS+verbatim.
                    // Value-shape declarations: class / function / var-statement (let/const/var) / enum.
                    // Type-shape declarations (interface, type alias) are exempt — type-only erases at compile time.
                    // `declare`-prefixed declarations are ambient (type-only at runtime) — exempt.
                    is ClassDeclaration -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = srcLastIndexOf(source, "export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    is FunctionDeclaration -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = srcLastIndexOf(source, "export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    is VariableStatement -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = srcLastIndexOf(source, "export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    is EnumDeclaration -> {
                        if (isCjs && ModifierFlag.Export in stmt.modifiers &&
                            ModifierFlag.Declare !in stmt.modifiers) {
                            val exportPos = srcLastIndexOf(source, "export", stmt.pos)
                            if (exportPos >= 0) emitTs1287(exportPos)
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    // TS2661: Cannot export non-local declaration
    // -----------------------------------------------------------------------

    private fun checkExportSpecifierLocality() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val locals = result.locals

            for (stmt in result.sourceFile.statements) {
                if (stmt !is ExportDeclaration) continue
                // Only check `export { X }` without `from "..."` (re-exports from modules are fine)
                if (stmt.moduleSpecifier != null) continue
                val stmtTypeOnly = stmt.isTypeOnly
                val namedExports = stmt.exportClause as? NamedExports ?: continue

                for (spec in namedExports.elements) {
                    val specTypeOnly = stmtTypeOnly || spec.isTypeOnly
                    val exportedName = (spec.propertyName ?: spec.name).text
                    // Check if locally declared (not just aliased by the export itself)
                    val localSymbol = locals[exportedName]
                    if (localSymbol != null) {
                        // If the symbol has non-ExportSpecifier declarations, it's a real local
                        val hasRealDecl = localSymbol.declarations.any { it !is ExportSpecifier }
                        if (hasRealDecl) continue
                    }
                    val nameNode = spec.propertyName ?: spec.name
                    // `globals` is over-merged and the binder also binds the export specifier's own
                    // name into it, so a bare `name in globals` is fooled by the export itself.
                    // Require a REAL (non-ExportSpecifier) global declaration, or a KNOWN_GLOBALS hit.
                    val globalSym = globals[exportedName]
                    val isGlobal = exportedName == "undefined" ||
                        exportedName in KNOWN_GLOBALS ||
                        (globalSym != null && globalSym.declarations.any { it !is ExportSpecifier })
                    if (isGlobal) {
                        // export { Global } (value re-export of a global) → TS2661. TypeScript does
                        // NOT emit this for a type-only re-export, so skip those.
                        if (specTypeOnly) continue
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Cannot export '$exportedName'. Only local declarations can be exported from a module.",
                            category = DiagnosticCategory.Error,
                            code = 2661,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = exportedName.length,
                        ))
                    } else {
                        // The exported name resolves to NOTHING (not a real local, not a global) →
                        // TS2304 "Cannot find name", or TS2552 with a spelling suggestion. Candidates
                        // are this file's real local declarations (type-eligible only for a type-only
                        // export). Conservative: a cross-file/over-merged name lands in `globals` and
                        // is handled above, so this branch only fires for genuinely-undeclared names
                        // (e.g. `export type { RoomInterface }` when the type is `RoomInterfae`).
                        val candidates = LinkedHashSet<String>()
                        for ((symName, sym) in locals) {
                            if (sym.declarations.none { it !is ExportSpecifier }) continue
                            if (specTypeOnly && !sym.flags.hasAny(SymbolFlags.Type)) continue
                            candidates.add(symName)
                        }
                        val suggestion = getSpellingSuggestionFromNames(exportedName, candidates)
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        val msg = if (suggestion != null)
                            "Cannot find name '$exportedName'. Did you mean '$suggestion'?"
                        else "Cannot find name '$exportedName'."
                        diagnostics.add(Diagnostic(
                            message = msg,
                            category = DiagnosticCategory.Error,
                            code = if (suggestion != null) 2552 else 2304,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = exportedName.length,
                        ))
                    }
                }
            }
            // B98.r56: `export { X }` INSIDE an ambient `declare module "m" { ... }`
            // block where X is NOT declared in the block but IS a real outer/global
            // declaration → TS2661. (X declared inside the block, e.g.
            // `namespace X {} export { X }`, is a legal local export → skipped.)
            for (stmt in result.sourceFile.statements) {
                if (stmt !is ModuleDeclaration) continue
                if (stmt.name !is StringLiteralNode) continue
                val body = stmt.body as? ModuleBlock ?: continue
                val blockLocals = collectModuleBlockLocalNames(body)
                for (s in body.statements) {
                    if (s !is ExportDeclaration) continue
                    if (s.moduleSpecifier != null) continue
                    val named = s.exportClause as? NamedExports ?: continue
                    val stmtTypeOnly = s.isTypeOnly
                    for (spec in named.elements) {
                        if (stmtTypeOnly || spec.isTypeOnly) continue
                        val exportedName = (spec.propertyName ?: spec.name).text
                        if (exportedName in blockLocals) continue
                        val isOuterReal = exportedName in KNOWN_GLOBALS ||
                            result.locals[exportedName]?.declarations?.any { it !is ExportSpecifier } == true ||
                            globals[exportedName]?.declarations?.any { it !is ExportSpecifier } == true
                        if (!isOuterReal) continue
                        val nameNode = spec.propertyName ?: spec.name
                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        diagnostics.add(Diagnostic(
                            message = "Cannot export '$exportedName'. Only local declarations can be exported from a module.",
                            category = DiagnosticCategory.Error,
                            code = 2661,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = exportedName.length,
                        ))
                    }
                }
            }
        }
    }

    /** Names declared directly inside an ambient module block via a genuine
     *  declaration (not an ExportSpecifier re-export). Used to distinguish a legal
     *  local `export { X }` from a non-local one (TS2661). */
    private fun collectModuleBlockLocalNames(body: ModuleBlock): Set<String> {
        val names = mutableSetOf<String>()
        for (stmt in body.statements) {
            when (stmt) {
                is VariableStatement -> for (d in stmt.declarationList.declarations) {
                    (d.name as? Identifier)?.text?.let { names.add(it) }
                }
                is FunctionDeclaration -> stmt.name?.text?.let { names.add(it) }
                is ClassDeclaration -> stmt.name?.text?.let { names.add(it) }
                is InterfaceDeclaration -> names.add(stmt.name.text)
                is TypeAliasDeclaration -> names.add(stmt.name.text)
                is EnumDeclaration -> names.add(stmt.name.text)
                is ModuleDeclaration -> (stmt.name as? Identifier)?.text?.let { names.add(it) }
                is ImportEqualsDeclaration -> names.add(stmt.name.text)
                is ImportDeclaration -> {
                    val clause = stmt.importClause
                    clause?.name?.text?.let { names.add(it) }
                    when (val nb = clause?.namedBindings) {
                        is NamespaceImport -> nb.name.text.let { names.add(it) }
                        is NamedImports -> for (e in nb.elements) names.add(e.name.text)
                        else -> {}
                    }
                }
                else -> {}
            }
        }
        return names
    }

    // TS8xxx: TypeScript syntax in JavaScript files
    // -----------------------------------------------------------------------

    private fun checkTsSyntaxInJsFiles() {
        for (result in checkedResults) {
            val fileName = result.sourceFile.fileName
            if (!fileName.endsWith(".js") && !fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            checkTsSyntaxInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkTsSyntaxInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkTsSyntaxInStatement(stmt, source, fileName)
    }

    private fun checkTsSyntaxInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> {
                emitTs8xxx(stmt.name, "'interface' declarations can only be used in TypeScript files.", 8006, source, fileName)
            }
            is EnumDeclaration -> {
                emitTs8xxx(stmt.name, "'enum' declarations can only be used in TypeScript files.", 8006, source, fileName)
            }
            is ModuleDeclaration -> {
                if (stmt.name is StringLiteralNode) {
                    // `declare module "foo" {}` - skip, this is ambient module declaration
                } else {
                    emitTs8xxx(stmt.name, "'namespace' declarations can only be used in TypeScript files.", 8006, source, fileName)
                }
            }
            is TypeAliasDeclaration -> {
                emitTs8xxx(stmt.name, "Type aliases can only be used in TypeScript files.", 8008, source, fileName)
            }
            is ImportEqualsDeclaration -> {
                val start = stmt.pos
                val importStart = srcIndexOf(source, "import", start)
                if (importStart >= 0) {
                    // Span covers the full statement including semicolon
                    val semiPos = source.indexOf(';', importStart)
                    val stmtLength = if (semiPos >= 0) semiPos - importStart + 1 else stmt.end - importStart
                    val (line, character) = getLineAndCharacterOfPosition(source, importStart)
                    diagnostics.add(Diagnostic(
                        message = "'import ... =' can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error,
                        code = 8002,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = importStart,
                        length = stmtLength,
                    ))
                }
            }
            is ExportAssignment -> {
                if (stmt.isExportEquals) {
                    val start = stmt.pos
                    // Find "export" in source near stmt.pos
                    val exportStart = srcIndexOf(source, "export", start)
                    if (exportStart >= 0) {
                        val (line, character) = getLineAndCharacterOfPosition(source, exportStart)
                        diagnostics.add(Diagnostic(
                            message = "'export =' can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8003,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = exportStart,
                            length = 11, // "export = ..."
                        ))
                    }
                }
            }
            is FunctionDeclaration -> {
                // TS8017: Signature declarations without body — takes priority over other TS8xxx
                if (stmt.body == null) {
                    val nameNode = stmt.name
                    if (nameNode != null) {
                        emitTs8xxx(nameNode, "Signature declarations can only be used in TypeScript files.", 8017, source, fileName)
                    }
                } else {
                    // Check type parameters (TS8004) — skip JSDoc-derived ones (B5.3)
                    val firstTsTp = stmt.typeParameters?.firstOrNull { !it.fromJSDoc }
                    if (firstTsTp != null) {
                        emitTs8xxx(firstTsTp.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                    }
                    // Check parameter types (TS8010), optional params (TS8009)
                    checkTsSyntaxInParams(stmt.parameters, source, fileName)
                    // Check return type (TS8010)
                    if (stmt.type != null) {
                        emitTs8xxxForType(stmt.type, source, fileName)
                    }
                    checkTsSyntaxInStatements(stmt.body.statements, source, fileName)
                }
            }
            is ClassDeclaration -> {
                // Check abstract modifier (TS8009) — search backward from class pos since pos may be at 'class' keyword
                if (ModifierFlag.Abstract in stmt.modifiers) {
                    val searchFrom = maxOf(0, stmt.pos - 30)
                    val idx = srcIndexOf(source, "abstract", searchFrom)
                    if (idx >= 0 && idx < stmt.pos + 2) {
                        val (line, character) = getLineAndCharacterOfPosition(source, idx)
                        diagnostics.add(Diagnostic(
                            message = "The 'abstract' modifier can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8009,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = idx,
                            length = 8,
                        ))
                    }
                }
                // Check type parameters (TS8004) — skip JSDoc-derived ones (B5.3).
                // Span = the whole `<...>` list contents (tsc createDiagnosticForNodeArray),
                // so `class B<T: BaseA>` squiggles `T: BaseA`, not just `T`.
                val firstClassTsTp = stmt.typeParameters?.firstOrNull { !it.fromJSDoc }
                if (firstClassTsTp != null) {
                    val tpStart = firstClassTsTp.name.pos
                    val tpLen = angleListSpanLength(source, tpStart, firstClassTsTp.name.text.length)
                    val (tpLine, tpChar) = getLineAndCharacterOfPosition(source, tpStart)
                    diagnostics.add(Diagnostic(
                        message = "Type parameter declarations can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error, code = 8004,
                        fileName = fileName, line = tpLine, character = tpChar,
                        start = tpStart, length = tpLen,
                    ))
                }
                // TS8011: type arguments on a heritage base (`class C extends Base<Arg>`)
                // in a JS file. Span = the type-args list contents.
                for (clause in stmt.heritageClauses.orEmpty()) {
                    for (h in clause.types) {
                        val args = h.typeArguments
                        if (!args.isNullOrEmpty()) {
                            val aStart = args.first().pos
                            val aLen = angleListSpanLength(source, aStart, 1)
                            val (aLine, aChar) = getLineAndCharacterOfPosition(source, aStart)
                            diagnostics.add(Diagnostic(
                                message = "Type arguments can only be used in TypeScript files.",
                                category = DiagnosticCategory.Error, code = 8011,
                                fileName = fileName, line = aLine, character = aChar,
                                start = aStart, length = aLen,
                            ))
                        }
                    }
                }
                // Check implements clause (TS8005)
                val hasImplements = stmt.heritageClauses?.any { it.token == SyntaxKind.ImplementsKeyword } == true
                if (hasImplements) {
                    // Find "implements" keyword position — use name pos + length (not name.end which overshoots)
                    val nameEnd = stmt.name?.let { it.pos + ((it).text.length) } ?: stmt.pos
                    val implIdx = srcIndexOf(source, "implements", nameEnd)
                    if (implIdx >= 0) {
                        // Span covers "implements <types>" — find the end of the implements clause
                        val implClause = stmt.heritageClauses.find { it.token == SyntaxKind.ImplementsKeyword }
                        val implEnd = implClause?.let { clause ->
                            // Compute true end from last type in the clause
                            val lastType = clause.types.lastOrNull()
                            if (lastType != null) {
                                val typeExpr = lastType.expression
                                when (typeExpr) {
                                    is Identifier -> typeExpr.pos + typeExpr.text.length
                                    else -> lastType.end
                                }
                            } else implIdx + 10
                        } ?: (implIdx + 10)
                        val (line, character) = getLineAndCharacterOfPosition(source, implIdx)
                        diagnostics.add(Diagnostic(
                            message = "'implements' clauses can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8005,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = implIdx,
                            length = implEnd - implIdx,
                        ))
                    }
                }
                for (member in stmt.members) {
                    checkTsSyntaxInClassMember(member, source, fileName)
                }
            }
            is VariableStatement -> {
                // Check for declare modifier (TS8009)
                if (ModifierFlag.Declare in stmt.modifiers) {
                    emitTs8xxxDeclare(stmt.pos, source, fileName)
                }
                // Check variable type annotations and initializer expressions
                for (decl in stmt.declarationList.declarations) {
                    // 17.62: types synthesized from a leading primitive `@type {...}` JSDoc
                    // comment are valid in JS files — skip TS8010 for that case.
                    if (decl.type != null && !decl.typeFromJSDoc) {
                        emitTs8xxxForType(decl.type, source, fileName)
                    }
                    // Walk into initializer to find ClassExpression type params etc.
                    decl.initializer?.let { checkTsSyntaxInExpression(it, source, fileName) }
                }
            }
            is ExpressionStatement -> {
                checkTsSyntaxInExpression(stmt.expression, source, fileName)
            }
            is ReturnStatement -> {
                stmt.expression?.let { checkTsSyntaxInExpression(it, source, fileName) }
            }
            is Block -> checkTsSyntaxInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkTsSyntaxInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkTsSyntaxInStatement(it, source, fileName) }
            }
            is ForStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkTsSyntaxInStatement(stmt.statement, source, fileName)
            else -> {}
        }
    }

    private fun checkTsSyntaxInClassMember(member: ClassElement, source: String, fileName: String) {
        // Get modifiers and pos from the specific member type
        val modifiers: Set<ModifierFlag>
        val memberPos: Int
        when (member) {
            is MethodDeclaration -> { modifiers = member.modifiers; memberPos = member.pos }
            is Constructor -> { modifiers = member.modifiers; memberPos = member.pos }
            is PropertyDeclaration -> { modifiers = member.modifiers; memberPos = member.pos }
            is GetAccessor -> { modifiers = member.modifiers; memberPos = member.pos }
            is SetAccessor -> { modifiers = member.modifiers; memberPos = member.pos }
            else -> { modifiers = emptySet(); memberPos = 0 }
        }
        // Check access modifiers (public/private/protected) on class members — TS8009
        checkTsSyntaxAccessModifier(modifiers, memberPos, source, fileName)
        // Check abstract modifier on members — TS8009
        if (ModifierFlag.Abstract in modifiers) {
            emitTs8xxxModifier("abstract", memberPos, 8, source, fileName)
        }
        when (member) {
            is MethodDeclaration -> {
                // TS8017: Signature declarations without body — takes priority over other checks
                if (member.body == null) {
                    emitTs8xxx(member.name, "Signature declarations can only be used in TypeScript files.", 8017, source, fileName)
                    return
                }
                // Check optional ? modifier (TS8009)
                if (member.questionToken) {
                    // Find ? after the method name
                    val nameEnd = member.name.pos + ((member.name as? Identifier)?.text?.length ?: 1)
                    val qIdx = source.indexOf('?', nameEnd)
                    if (qIdx >= 0 && qIdx < nameEnd + 5) {
                        emitTs8xxxQuestionToken(qIdx, source, fileName)
                    }
                }
                // Check type parameters (TS8004)
                if (!member.typeParameters.isNullOrEmpty()) {
                    val typeParam = member.typeParameters.first()
                    emitTs8xxx(typeParam.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                }
                // Check parameter types, optional params
                checkTsSyntaxInParams(member.parameters, source, fileName)
                if (member.type != null) emitTs8xxxForType(member.type, source, fileName)
                member.body.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            is Constructor -> {
                // TS8017: Constructor signature without body
                if (member.body == null) {
                    // Span covers "constructor" keyword
                    val ctorIdx = srcIndexOf(source, "constructor", memberPos)
                    if (ctorIdx >= 0 && ctorIdx < memberPos + 30) {
                        val (line, character) = getLineAndCharacterOfPosition(source, ctorIdx)
                        diagnostics.add(Diagnostic(
                            message = "Signature declarations can only be used in TypeScript files.",
                            category = DiagnosticCategory.Error,
                            code = 8017,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = ctorIdx,
                            length = 11, // "constructor"
                        ))
                    }
                    return
                }
                // Check constructor parameters — types and modifiers (TS8012)
                for (param in member.parameters) {
                    if (param.type != null) emitTs8xxxForType(param.type, source, fileName)
                    if (param.questionToken) {
                        findQuestionTokenPos(param, source)?.let { emitTs8xxxQuestionToken(it, source, fileName) }
                    }
                    // Check parameter modifiers (public/private/etc.) — TS8012
                    if (param.modifiers.any { isParameterPropertyModifier(it) }) {
                        emitTs8xxxParamModifier(param.pos, source, fileName)
                    }
                }
                member.body.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            is PropertyDeclaration -> {
                // Check optional ? modifier (TS8009)
                if (member.questionToken) {
                    val nameEnd = member.name.pos + ((member.name as? Identifier)?.text?.length ?: 1)
                    val qIdx = source.indexOf('?', nameEnd)
                    if (qIdx >= 0 && qIdx < nameEnd + 5) {
                        emitTs8xxxQuestionToken(qIdx, source, fileName)
                    }
                }
                // 17.58b: types synthesized from a leading `@type {...}` JSDoc comment
                // are valid in JS files — skip the TS8010 emission for that case.
                if (member.type != null && !member.typeFromJSDoc) emitTs8xxxForType(member.type, source, fileName)
                // Check declare modifier (TS8009)
                if (ModifierFlag.Declare in member.modifiers) {
                    emitTs8xxxDeclare(member.pos, source, fileName)
                }
            }
            is GetAccessor -> {
                if (member.type != null) emitTs8xxxForType(member.type, source, fileName)
                member.body?.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            is SetAccessor -> {
                for (param in member.parameters) {
                    if (param.type != null) emitTs8xxxForType(param.type, source, fileName)
                }
                member.body?.let { checkTsSyntaxInStatements(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    /** Check parameters for type annotations (TS8010) and optional ? modifiers (TS8009). */
    private fun checkTsSyntaxInParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            // 17.140 / B5.2: skip TS8010 for params whose type was synthesized
            // from a JSDoc `@param {T} name` tag — those are valid in JS files.
            if (param.type != null && !param.typeFromJSDoc) emitTs8xxxForType(param.type, source, fileName)
            if (param.questionToken) {
                findQuestionTokenPos(param, source)?.let { emitTs8xxxQuestionToken(it, source, fileName) }
            }
        }
    }

    /** Find the position of the ? token after a parameter name. */
    private fun findQuestionTokenPos(param: Parameter, source: String): Int? {
        val nameEnd = param.name.pos + when (val n = param.name) {
            is Identifier -> n.text.length
            else -> 1
        }
        val qIdx = source.indexOf('?', nameEnd)
        return if (qIdx >= 0 && qIdx < nameEnd + 5) qIdx else null
    }

    /** Walk expression tree to find TypeScript-only syntax (non-null assertions, type assertions, class expressions). */
    private fun checkTsSyntaxInExpression(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is NonNullExpression -> {
                // TS8013: Non-null assertions can only be used in TypeScript files
                // Span covers the entire expression including the `!`
                val start = expr.pos
                val length = expressionTrueEnd(expr) - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Non-null assertions can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error,
                        code = 8013,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                checkTsSyntaxInExpression(expr.expression, source, fileName)
            }
            is ClassExpression -> {
                // Check type parameters on class expressions (TS8004)
                if (!expr.typeParameters.isNullOrEmpty()) {
                    val typeParam = expr.typeParameters.first()
                    emitTs8xxx(typeParam.name, "Type parameter declarations can only be used in TypeScript files.", 8004, source, fileName)
                }
                for (member in expr.members) {
                    checkTsSyntaxInClassMember(member, source, fileName)
                }
            }
            is ParenthesizedExpression -> checkTsSyntaxInExpression(expr.expression, source, fileName)
            is BinaryExpression -> {
                // B64.8: iterative left-spine flatten.
                val rightStack = ArrayDeque<Expression>()
                var cur: Expression = expr
                while (cur is BinaryExpression) {
                    rightStack.addLast(cur.right)
                    cur = cur.left
                }
                checkTsSyntaxInExpression(cur, source, fileName)
                while (rightStack.isNotEmpty()) checkTsSyntaxInExpression(rightStack.removeLast(), source, fileName)
            }
            is ConditionalExpression -> {
                checkTsSyntaxInExpression(expr.condition, source, fileName)
                checkTsSyntaxInExpression(expr.whenTrue, source, fileName)
                checkTsSyntaxInExpression(expr.whenFalse, source, fileName)
            }
            is AsExpression -> {
                // TS8016: Type assertion expressions can only be used in TypeScript files
                // Span covers just the type node (e.g., "number" in "0 as number")
                val typeNode = expr.type
                val start = typeNode.pos
                var trueEnd = typeNode.end
                while (trueEnd > start && source.getOrNull(trueEnd - 1)?.let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ';' || it == ')' || it == '}' || it == ',' } == true) {
                    trueEnd--
                }
                val length = trueEnd - start
                if (length > 0) {
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type assertion expressions can only be used in TypeScript files.",
                        category = DiagnosticCategory.Error,
                        code = 8016,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            else -> {}
        }
    }

    /** Check for public/private/protected access modifiers — TS8009 */
    private fun checkTsSyntaxAccessModifier(modifiers: Set<ModifierFlag>, pos: Int, source: String, fileName: String) {
        if (ModifierFlag.Public in modifiers) {
            emitTs8xxxModifier("public", pos, 6, source, fileName)
        } else if (ModifierFlag.Private in modifiers) {
            emitTs8xxxModifier("private", pos, 7, source, fileName)
        } else if (ModifierFlag.Protected in modifiers) {
            emitTs8xxxModifier("protected", pos, 9, source, fileName)
        }
    }

    /** Emit TS8009 for a modifier keyword found near the given pos. */
    private fun emitTs8xxxModifier(keyword: String, nearPos: Int, keywordLen: Int, source: String, fileName: String) {
        val idx = srcIndexOf(source, keyword, nearPos)
        if (idx < 0 || idx > nearPos + 30) return
        val (line, character) = getLineAndCharacterOfPosition(source, idx)
        diagnostics.add(Diagnostic(
            message = "The '$keyword' modifier can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8009,
            fileName = fileName,
            line = line,
            character = character,
            start = idx,
            length = keywordLen,
        ))
    }

    /** Emit TS8009 for a ? token at the given position. */
    private fun emitTs8xxxQuestionToken(pos: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "The '?' modifier can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8009,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = 1, // "?"
        ))
    }

    /** Emit TS8012 for parameter modifier (public/private/protected/readonly). */
    private fun emitTs8xxxParamModifier(paramPos: Int, source: String, fileName: String) {
        // Find the first modifier keyword near paramPos
        val modifiers = listOf("public" to 6, "private" to 7, "protected" to 9, "readonly" to 8)
        for ((kw, len) in modifiers) {
            val idx = srcIndexOf(source, kw, paramPos)
            if (idx >= 0 && idx < paramPos + 20) {
                val (line, character) = getLineAndCharacterOfPosition(source, idx)
                diagnostics.add(Diagnostic(
                    message = "Parameter modifiers can only be used in TypeScript files.",
                    category = DiagnosticCategory.Error,
                    code = 8012,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = idx,
                    length = len,
                ))
                return
            }
        }
    }

    /** Span length of a `<...>`-delimited list from the first element's pos to the
     *  matching `>` (exclusive) — tsc's createDiagnosticForNodeArray span for
     *  TS8004/TS8011. Falls back to [fallbackLen] when the brackets can't be matched. */
    private fun angleListSpanLength(source: String, firstPos: Int, fallbackLen: Int): Int {
        var lt = firstPos - 1
        while (lt >= 0 && source[lt].isWhitespace()) lt--
        if (lt < 0 || source[lt] != '<') return fallbackLen
        var depth = 0
        var j = lt
        while (j < source.length) {
            when (source[j]) {
                '<' -> depth++
                '>' -> { depth--; if (depth == 0) return (j - firstPos).coerceAtLeast(1) }
            }
            j++
        }
        return fallbackLen
    }

    private fun emitTs8xxx(nameNode: Node, message: String, code: Int, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            else -> nameNode.end - nameNode.pos
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTs8xxxForType(type: TypeNode, source: String, fileName: String) {
        val start = type.pos
        // type.end overshoots (includes next token's start), so compute true length
        // by trimming trailing whitespace/semicolons/delimiters from the source span
        var trueEnd = type.end
        while (trueEnd > start && source.getOrNull(trueEnd - 1)?.let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ';' || it == ')' || it == '}' || it == ',' || it == '{' } == true) {
            trueEnd--
        }
        val length = trueEnd - start
        if (length <= 0) return
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type annotations can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8010,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTs8xxxDeclare(stmtPos: Int, source: String, fileName: String) {
        // Search backward from stmtPos since stmt.pos may be at keyword after 'declare'
        val searchFrom = maxOf(0, stmtPos - 20)
        val declareIdx = srcIndexOf(source, "declare", searchFrom)
        if (declareIdx < 0 || declareIdx > stmtPos + 20) return
        val (line, character) = getLineAndCharacterOfPosition(source, declareIdx)
        diagnostics.add(Diagnostic(
            message = "The 'declare' modifier can only be used in TypeScript files.",
            category = DiagnosticCategory.Error,
            code = 8009,
            fileName = fileName,
            line = line,
            character = character,
            start = declareIdx,
            length = 7, // "declare"
        ))
    }
}

/**
 * (ORDER.1) round 778 ABLATION SWITCH — flip to `false` to restore the
 * pre-778 behaviour (`getTypeOfSymbol` persists every resolution, whatever
 * instantiation context the caller had installed) so the round's pins can be
 * shown to discriminate. Top-level so it is initialized before the Checker's
 * `init` block runs (the init-order gotcha). Never flip this in a commit.
 */
private val SYMBOL_TYPE_ORDER_GATE = true

/**
 * (REL.4)(b) round 779 ABLATION SWITCH — flip to `false` to restore the pre-779
 * behaviour of BOTH halves of that round's fix (the optional-member TS2345 walker
 * fires against an inferred bare-type-parameter parameter; a `tp | null | undefined`
 * parameter only strips the source's nullish constituents when exactly one member
 * survives) so `Rel4bGenericInferenceTest`'s pins can be shown to discriminate.
 * Same top-level init-order rationale as the switch above. Never flip in a commit.
 */
private val REL4B_GATE = true

/**
 * (REL.4) round 780 ABLATION SWITCH — flip to `false` to restore the pre-780
 * behaviour of both halves of that round's fix (an ELEMENT-ACCESS argument is not a
 * narrowable reference at the argument gate; a switch `default:` subtracts neither a
 * nullish constituent covered by `case undefined:`/`case null:` nor a whole-ENUM
 * constituent covered by its members' cases) so `Rel4ElementAccessAndUnionSwitchTest`'s
 * pins can be shown to discriminate. Same top-level init-order rationale as the
 * switches above. Never flip this in a commit.
 */
private val REL4_ELEM_UNION_GATE = true

/**
 * (WIDEN.1) ABLATION SWITCH — flip to `false` to restore the pre-(WIDEN.1) behaviour in
 * which a `const` binding's inferred type widened its literal to the base primitive, so
 * `ConstLiteralTypeTest`'s pins can be shown to discriminate. Same top-level init-order
 * rationale as the switches above. Never flip this in a commit.
 */
private val WIDEN1_CONST_KEEPS_LITERAL = true

/**
 * (WIDEN.1)(b) ABLATION SWITCH — flip to `false` to restore the pre-(WIDEN.1)(b)
 * behaviour in which a `readonly` class PROPERTY with a literal initializer and no type
 * annotation widened that literal to the base primitive, so
 * `ReadonlyPropertyLiteralTypeTest`'s pins can be shown to discriminate. Same top-level
 * init-order rationale as the switches above. Never flip this in a commit.
 */
